window.LIB = {"generated": "2026-10-02", "about": "A citation-linked map of 274 peer-reviewed papers on running AI models on analog / in-memory hardware (PCM, ReRAM, charge-domain CIM) and mapping them onto crossbar arrays. It started from the papers of the \"Analog Silicon for Language Models\" review, expanded through their references and the papers citing them (and the citers of the most important hop-1 papers), then was filtered to reputable venues (IEEE, ACM, Nature/Science family, NeurIPS, DAC/DATE/ICCAD/ISCA/MICRO/HPCA/ASPLOS, ISSCC/IEDM/VLSI) and curated by relevance. Citation links come from OpenAlex reference lists; the quoted citation sentences were extracted from the full text of the citing paper where an open copy existed.", "categories": [{"id": "01", "name": "Surveys & Foundations", "short": "Surveys", "dir": "01_Surveys_and_Foundations", "color": "#4e79a7", "desc": "Reviews and perspectives that define in-memory computing with resistive / phase-change devices, the memory-wall motivation, device requirements, and the state of analog AI hardware."}, {"id": "02", "name": "Fabricated Chips & Macros", "short": "Chips", "dir": "02_Fabricated_Chips_and_Macros", "color": "#59a14f", "desc": "Measured silicon: PCM and RRAM chips, CIM macros (ISSCC/JSSC/Nature) and full-system demonstrations that report on-chip accuracy, TOPS/W and density."}, {"id": "03", "name": "Crossbar Accelerator Architectures", "short": "Architectures", "dir": "03_Crossbar_Accelerator_Architectures", "color": "#9c755f", "desc": "Architecture-level designs that build DNN accelerators out of crossbar tiles (ISAAC, PRIME, PipeLayer, PUMA and successors): tiles, pipelines, ISAs, heterogeneous analog+digital systems."}, {"id": "04", "name": "Transformer & Attention Accelerators (CIM / PIM)", "short": "Transformers", "dir": "04_Transformers_and_LLMs", "color": "#e15759", "desc": "Architectures that accelerate transformers and self-attention on crossbars and CIM/PIM: dynamic-operand attention, write-endurance, hybrid analog/digital and 3D designs. Papers whose focus is deploying language models themselves are in folder 11."}, {"id": "05", "name": "Mapping, Compilation & Dataflow", "short": "Mapping", "dir": "05_Mapping_Compilation_and_Dataflow", "color": "#f28e2b", "desc": "How a network is placed onto crossbars: weight/layer mapping, tiling and partitioning, crossbar allocation, compilers and software stacks, scheduling and dataflow, NN/architecture co-exploration."}, {"id": "06", "name": "Non-idealities, Reliability & Fault Tolerance", "short": "Non-idealities", "dir": "06_Nonidealities_and_Reliability", "color": "#b07aa1", "desc": "Device and circuit non-idealities and their mitigation: conductance variation, drift, read/write noise, IR drop and parasitics, stuck-at faults, thermal effects, read disturb, programming / write-verify."}, {"id": "07", "name": "Hardware-aware Training & Noise Robustness", "short": "HW-aware training", "dir": "07_Hardware_Aware_Training_and_Robustness", "color": "#3fa7a0", "desc": "Algorithmic mitigation: noise-injection / hardware-aware training, non-ideality-aware fine-tuning, drift-aware regularisation, NAS for analog hardware, post-training calibration, robustness analyses."}, {"id": "08", "name": "Simulation, Modeling & Benchmarking", "short": "Simulators", "dir": "08_Simulation_and_Benchmarking_Frameworks", "color": "#c9a227", "desc": "Simulators and evaluation frameworks (NeuroSim, MNSIM, AIHWKit, RxNN, GENIEx, CiMLoop …) and quantitative analog-vs-digital IMC benchmarking."}, {"id": "09", "name": "ADCs, Peripherals, Quantization & Sparsity", "short": "ADC / quant.", "dir": "09_ADCs_Peripherals_Quantization_Sparsity", "color": "#ff8fa3", "desc": "Peripheral cost (ADC/DAC), ADC-less and low-resolution designs, partial-sum and mixed-precision quantization, pruning and bit-level sparsity tailored to crossbars."}, {"id": "10", "name": "On-chip & Analog Training", "short": "Training", "dir": "10_On_Chip_and_Analog_Training", "color": "#8a8f98", "desc": "Training (not only inference) in analog memory: in-situ learning, mixed-precision training, PCM+capacitor and ECRAM/FeFET synapses, training accelerators."}, {"id": "11", "name": "Small Language Models on Analog / NVM In-Memory Hardware", "short": "SLMs on AIMC", "dir": "11_Small_Language_Models_on_AIMC", "color": "#8b5cf6", "desc": "Running and evaluating (small) language models (BERT-family, GPT-2, Llama-1B–8B, Phi, ternary/1-bit LLMs, KV caches) on analog or non-volatile in-memory hardware (PCM, ReRAM, FeFET/FeRAM, MRAM, gain cells), on silicon or under its non-idealities: hardware-aware training, adapters, noise robustness, mapping and accelerator design."}], "papers": [{"id": "W7160842405", "short": "High-Accuracy Memristor CIM Strategies", "title": "Strategies of high-accuracy memristor-based analogue computing in memory for artificial intelligence", "authors": ["Zhixing Jiang", "H Zhao", "Jianshi Tang", "Yuyao Lu", "Qi Qin", "Ze Wang", "Ruofei Hu", "Ruihua Yu", "Yuan He", "Junyang Zhang", "Mingcheng Shi", "Ning Deng", "Bin Gao", "He Qian", "Huaqiang Wu"], "year": 2026, "venue": "Nature Materials", "venue_short": "NatMater", "venue_full": "Nature Materials", "venue_ok": true, "doi": "https://doi.org/10.1038/s41563-026-02600-y", "cites_global": 5, "cat": "01", "seed": true, "devices": ["Memristor(generic)", "ReRAM"], "models": [], "evidence": "survey", "tldr": "Nature Materials review that dissects computing-error sources in memristor analogue CIM across device, array, architecture and algorithm levels, and evaluates mitigation strategies against their hardware/energy cost.", "summary": "Memristor-based analogue CIM promises large energy-efficiency gains for AI but struggles to reach high accuracy at the same time. The causes are the noise sensitivity of analogue computing and device/circuit non-idealities. The review dissects error sources up the hierarchy: memristor device, array, system architecture and algorithm. It evaluates material/device innovations, array-level techniques and algorithm-architecture co-design frameworks. A central theme is that many mitigations add hardware or energy overhead that erodes analogue CIM's benefit. The review draws a roadmap from proof-of-concept prototypes to large-scale deployment based on this accuracy-vs-cost trade-off.", "contributions": ["Hierarchical taxonomy of computing-error sources (device → array → architecture → algorithm)", "Evaluation of mitigation strategies at each level", "Explicit framing of the accuracy-vs-implementation-cost trade-off", "Roadmap to large-scale deployment"], "claims": [{"claim": "Errors in memristor analogue CIM originate at device, array, system-architecture and algorithm levels, so mitigation must be co-designed across levels.", "support": "\"This Review dissects the computing error sources across the CIM hierarchy from the memristor device and array to the system architecture and algorithm\"", "loc": "Abstract"}, {"claim": "Many accuracy fixes inadvertently add hardware or energy overhead that undermines analogue CIM's core benefit.", "support": "Abstract", "loc": "Abstract"}], "results": [], "limitations": ["Only the abstract was available here.", "The original review's stronger reading of this paper (accuracy is the binding constraint; efficiency and accuracy cannot be had together) was refuted 0-3 (R1). Do not cite it for that."], "remarks": "A good map of where mapping-related errors come from (IR drop and sneak paths at array level, ADC quantization at architecture level). It frames accuracy as a cost trade-off, not an impossibility. The review used it for F9 (error hierarchy); its stronger R1 claim was refuted.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [{"fid": "F9", "text": "Device non-idealities are the physical limit and span a hierarchy, not just the material: memory window, read noise, program noise and conductance drift act on different time scales while constraining manufacturability; errors originate at device, array, architecture and algorithm levels. NVM writes cost 1–2 orders of magnitude more latency and energy per bit than SRAM, with ~106–109 write endurance.", "grade": "High confidence", "vote": "3–0 unanimous", "note": "Wiley Adv. Intelligent Systems 2026 · Nature Materials 2026 · X-Former"}, {"fid": "R1", "text": "“Accuracy, not energy efficiency, is the binding constraint on memristor-based analogue CIM — high efficiency and high accuracy cannot be achieved simultaneously.”", "grade": "Refuted 0–3", "vote": "Nature Materials 2026", "note": "Consequence: do not present analog accuracy as fundamentally unachievable. The review this came from catalogues mitigation strategies; the claim overstated its own source."}], "pdf_expected": "01_Surveys_and_Foundations/2026_Jiang_HighAccuracyMemristorCIM_NatMater.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2026_Jiang_HighAccuracyMemristorCIM_NatMater.pdf", "priority": 7.04}, {"id": "W4417492578", "short": "AIMC Tile Design", "title": "The design of analogue in-memory computing tiles", "authors": ["Abhairaj Singh", "Manuel Le Gallo", "Athanasios Vasilopoulos", "Jose Luquin", "Pritish Narayanan", "Geoffrey W. Burr", "Abu Sebastian"], "year": 2025, "venue": "Nature Electronics", "venue_short": "NatElectron", "venue_full": "Nature Electronics", "venue_ok": true, "doi": "https://doi.org/10.1038/s41928-025-01537-5", "cites_global": 13, "cat": "01", "seed": true, "devices": ["PCM", "ReRAM", "Generic-NVM"], "models": [], "evidence": "survey", "tldr": "IBM perspective on how to design a memristive AIMC tile: its components, how signed multi-bit weights and inputs are encoded, the efficiency/accuracy of ADC-based output encodings, and how memory technologies compare and scale.", "summary": "The AIMC tile is the building block of analog in-memory DNN accelerators. It can be built from volatile charge-based or non-volatile memristive memory. This Perspective from IBM Research Zurich/Almaden focuses on non-volatile memristive tiles. It walks through each tile component, the range of mapping techniques that encode signed multi-bit weights and inputs onto conductances and pulses, and the efficiency/accuracy trade-offs of output encoding schemes including several ADC approaches. It closes with a comparison of the candidate memory technologies and projections of how technology scaling affects key tile components.", "contributions": ["Component-by-component breakdown of a memristive AIMC tile", "Survey of signed multi-bit weight and input encoding/mapping techniques", "Efficiency vs accuracy analysis of output encoding schemes and ADC approaches", "Comparison of memory technologies and technology-scaling projections for tile components"], "claims": [{"claim": "The AIMC tile is the key element of AIMC-based DNN accelerators and can be implemented with volatile charge-based or non-volatile memristive technologies.", "support": "Abstract", "loc": "Abstract"}, {"claim": "Output encoding (ADC choice) is a first-class design axis with a quantifiable efficiency/accuracy trade-off.", "support": "\"We provide an analysis of the efficiency and accuracy of output encoding schemes, including various analogue-to-digital converter approaches.\"", "loc": "Abstract"}], "results": [], "limitations": ["Only the abstract was available here; numbers in the paper were not checked.", "Perspective/analysis, not a new chip.", "Single (IBM) group view."], "remarks": "A design reference for anyone mapping models to crossbars: weight-encoding choices (differential pairs, multi-device bit-slicing) and ADC choices set the accuracy/efficiency of every mapping. The original review used it to say no memory technology has won yet, which is an unverified lead (N1), not an adjudicated claim.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [{"fid": "N1", "text": "The December 2025 IBM Research perspective (Nature Electronics) frames the AIMC tile as the building block, buildable from volatile charge-based or non-volatile memristive memory; no single memory technology has been settled on, and signed multi-bit weight encoding and output conversion remain open design axes.", "grade": "Not adjudicated", "vote": "", "note": "Reported in §10 of the review as a lead; never sampled into verification."}], "pdf_expected": "01_Surveys_and_Foundations/2025_Singh_AIMCTileDesign_NatElectron.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2025_Singh_AIMCTileDesign_NatElectron.pdf", "priority": 8.2}, {"id": "W4411926812", "short": "AIMC Software Stacks", "title": "Deep learning software stacks for analogue in-memory computing-based accelerators", "authors": ["Corey Lammie", "Hadjer Benmeziane", "William Simon", "Elena Ferro", "Athanasios Vasilopoulos", "Julian Büchel", "Manuel Le Gallo", "Irem Boybat", "Abu Sebastian"], "year": 2025, "venue": "Nature Reviews Electrical Engineering", "venue_short": "NatRevElectrEng", "venue_full": "Nature Reviews Electrical Engineering", "venue_ok": true, "doi": "https://doi.org/10.1038/s44287-025-00187-1", "cites_global": 7, "cat": "01", "seed": true, "devices": ["Generic-NVM", "PCM"], "models": [], "evidence": "survey", "tldr": "Perspective arguing that heterogeneous AIMC + digital accelerators need purpose-built DL software stacks. Fixed weight stationarity, cross-layer pipelining and stochastic analog noise make existing compiler tools not directly applicable.", "summary": "Heterogeneous architectures that combine AIMC tiles with digital processing units (DPUs) can execute whole DNNs end-to-end with low latency and high efficiency. Building their software stack is hard for three reasons. Peak performance needs extensive or complete weight stationarity and pipelined execution across layers. AIMC tiles inject both stochastic and deterministic noise that hurts accuracy. Hardware design work routinely underestimates software-stack effort. The authors review the attributes of DL software stacks and of AIMC accelerators, list the challenges of combining them (mapping, scheduling, accuracy-aware compilation), and outline research opportunities.", "contributions": ["Overview of DL software-stack layers and AIMC accelerator attributes", "Identification of AIMC-specific challenges: fixed weight stationarity, cross-layer pipelining, analog noise", "Research agenda for compilers, mappers and co-design tools for AIMC"], "claims": [{"claim": "End-to-end DNN execution on AIMC requires heterogeneous AIMC tiles + digital processing units.", "support": "Key points: \"AIMC-based accelerators, comprising AIMC tiles and digital processing units (DPUs), can be used to perform end-to-end execution\"", "loc": "Key points"}, {"claim": "Existing software-stack tools are not directly applicable because of weight stationarity, pipelining and analog noise.", "support": "\"As a result, existing tools for software stack development are not directly applicable.\"", "loc": "Abstract"}, {"claim": "Most device/accelerator work underestimates the time and complexity of software-stack development.", "support": "Key points, 4th bullet", "loc": "Key points"}], "results": [], "limitations": ["Abstract and key points only.", "Perspective, not quantitative.", "The original review's stronger claim (TVM/Glow/nGraph cannot be reused, so software is a first-order bottleneck) was refuted 0-3 (R2)."], "remarks": "The most direct statement of why mapping/compilation is its own research problem for analog hardware. Weight stationarity turns mapping into a placement problem under fixed capacity, which ties to category 05 (PIMCOMP, LionHeart, CIM-MLC). The review cites it for F11 (heterogeneous design point); R2 was refuted.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [{"fid": "F11", "text": "Heterogeneous architecture is the consensus design point: AIMC tiles combined with digital processing units, because analog tiles alone cannot execute an end-to-end deep neural network.", "grade": "Medium confidence", "vote": "3–0 unanimous", "note": "Graded medium because “dominant” is a review-level characterization resting largely on one review plus the same lab's own chips — and a companion claim from that same review was refuted 0–3 (see §09)."}, {"fid": "R2", "text": "“Conventional deep-learning compiler stacks (TVM, Glow, nGraph) cannot be reused for AIMC, making software a first-order bottleneck.”", "grade": "Refuted 0–3", "vote": "Nature Rev. Electrical Engineering 2025", "note": "Consequence: the software-stack story in this review is thin and should not be asserted. This is a genuine coverage gap, not a settled negative."}], "pdf_expected": "01_Surveys_and_Foundations/2025_Lammie_AIMCSoftwareStacks_NatRevElectrEng.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2025_Lammie_AIMCSoftwareStacks_NatRevElectrEng.pdf", "priority": 8.03}, {"id": "W4392367648", "short": "Memristor ANN HW Review", "title": "Hardware implementation of memristor-based artificial neural networks", "authors": ["Fernando Leonel Aguirre", "Abu Sebastian", "Manuel Le Gallo", "Wenhao Song", "Tong Wang", "J. Joshua Yang", "Wei Dong Lu", "Meng‐Fan Chang", "Daniele Ielmini", "Yuchao Yang", "Adnan Mehonić", "Anthony Joseph Kenyon", "Marco Antonio Villena", "J.B. Roldán", "Yuting Wu", "Hung-Hsi Hsu", "Nagarajan Raghavan", "Jordi Suñé", "Enrique A. Miranda", "Ahmed M. Eltawil", "Gianluca Setti", "Kamilya Smagulova", "Khaled N. Salama", "Olga Krestinskaya", "Xiaobing Yan", "Kah‐Wee Ang", "Samarth Jain", "Sifan Li", "Osamah Alharbi", "Sebastian Matias Pazos", "Mario Lanza"], "year": 2024, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-024-45670-9", "cites_global": 497, "cat": "01", "seed": false, "devices": ["Memristor(generic)", "ReRAM", "PCM"], "models": ["MLP", "CNN", "LSTM/RNN"], "evidence": "survey", "tldr": "A comprehensive review of hardware implementation of memristor-based artificial neural networks, covering device-level programming (write-verify), crossbar/peripheral circuit design (ADC/DAC trade-offs), published prototype chips (performance/throughput/density comparisons), the landscape of memristive-ANN simulation frameworks, and accuracy/learning-algorithm comparisons, intended as a protocol/reference for newcomers and experts alike.", "summary": "The paper is a large, multi-author review addressing the gap between the theoretical promise of memristor-based in-memory ANN hardware and the practical engineering challenges of building it, by systematically covering the working principles and design alternatives at every block of a memristive ANN system. It details device programming schemes (e.g., write-verify loops for accurate conductance programming, partitioned crossbar programming architectures), the circuit-level analogue/digital trade-offs in ADC/DAC design (precision vs. energy/area, multiplexed DACs, time-encoding schemes), and tabulates published full hardware prototypes along with throughput/density/efficiency metrics (Table 3) comparing hybrid CMOS/memristor chips to fully-CMOS alternatives. It also surveys the ecosystem of simulation frameworks spanning device-level SPICE/Verilog models to system-level tools (e.g., NeuroSim, MNSIM, PUMAsim, DL-RSIM, CrossSim, MemTorch, AIHWKit), tabulating their language, year, and capabilities (Table 4), and compares accuracies achieved by different memristor-based neural network types and learning algorithms (Table 5). The review's central message is that peripheral CMOS circuitry (ADC/DAC) and device nonidealities (sneak paths, line resistance, variability, limited conductance states) remain the dominant bottlenecks limiting the energy/area/accuracy benefits of memristive crossbars, and that device-hardware co-design plus a judicious combination of simulation tools (at different abstraction levels) is essential for further progress.", "contributions": ["Systematic, block-by-block description of memristive ANN hardware design: device programming (write-verify), crossbar partitioning, peripheral ADC/DAC circuit trade-offs, and analogue/digital boundary choices across published designs", "Comparative Table 3 of published hybrid CMOS/memristor hardware prototypes against fully-CMOS accelerators on throughput (TOPS), density, and efficiency", "Comparative Table 4 cataloguing memristive-ANN simulation frameworks (device to system level) by language, year, and supported features (training/inference, network types)", "Comparative Table 5 of accuracies achieved across different memristor-based neural network types and learning algorithms", "Identifies ADC/DAC peripheral circuitry and device nonidealities (sneak-path effects, line resistance, conductance-state limitations) as the dominant practical bottlenecks to realizing memristive ANN hardware's theoretical efficiency gains"], "claims": [{"claim": "ADC circuitry can consume up to 70-90% of on-chip area and up to 80-88% of energy in crossbar-based computation units.", "support": "cited statistic aggregated from prior work", "loc": "Sec. on peripheral circuit design, citing refs 55,154,155"}, {"claim": "Hybrid RRAM/CMOS ANN architectures achieve throughput similar to fully-CMOS commercial accelerators, but are sometimes still limited by the large area consumption of ADC circuits.", "support": "Table 3 comparison of hybrid vs fully-CMOS chips", "loc": "Table 3 / surrounding text"}, {"claim": "True full-on-chip hybrid CMOS/memristor systems have only started appearing in the last two years (relative to publication), so performance metrics from systems relying heavily on off-chip electronics should be interpreted cautiously.", "support": "qualitative review observation", "loc": "Sec. on crossbar architecture discussion"}, {"claim": "Mixed-precision training (accumulating weight updates in software, only writing to the memristor when the accumulated update surpasses programming granularity) can relax conductance-update-resolution and endurance requirements while achieving software-comparable accuracy.", "support": "cited prior work on mixed-precision in-memory computing", "loc": "Sec. on training approaches, citing refs 192,193"}], "results": ["Table 3 compares throughput (TOPS), density, and efficiency of hybrid CMOS/memristor prototype chips vs. fully-CMOS accelerators (e.g., DaDianNao-class, NVIDIA/Habana inference platforms), showing broadly similar throughput but persistent ADC-area bottlenecks for hybrid chips", "Table 4 catalogs ~20+ memristive-ANN simulation frameworks (e.g., NeuroSim, MNSIM, PUMAsim, DL-RSIM, CrossSim, MemTorch, NVM-SPICE, AIHWKit) by implementation language, release year, and supported training/inference/network-type features", "Table 5 compares classification accuracies across memristor-based network types (MLP, CNN, SNN) and learning algorithms"], "limitations": ["As a review, it reports and tabulates results from many underlying primary studies rather than generating new experimental results itself, so figures reflect heterogeneous experimental conditions across sources", "Performance comparisons (e.g., Table 3) mix hardware-measured and simulation-based entries from different source papers, which the authors themselves caution should be read carefully given differing reliance on off-chip electronics", "Given its breadth (device, circuit, simulation, and algorithm levels), individual topics are covered at a tutorial depth rather than exhaustive critical depth"], "remarks": "This is a central, up-to-date (2024) reference work for a thesis in this area: it is one of the few single sources tying together device programming circuits, ADC/DAC peripheral design trade-offs, published prototype performance comparisons, and the full landscape of memristive-ANN simulation tools (including most of the frameworks referenced by other papers in this collection, e.g., NeuroSim, MNSIM, PUMA, DL-RSIM, CrossSim, AIHWKit). Its main value is as a map of the field and its bottlenecks (ADC/DAC overhead, device nonidealities, simulation tool landscape) rather than new empirical results; a thesis can use its Tables 3-5 as a structured starting point before going to the primary sources for exact numbers.", "basis": "full-text", "pdf_source_url": "", "abstract": "Artificial Intelligence (AI) is currently experiencing a bloom driven by deep learning (DL) techniques, which rely on networks of connected simple computing units operating in parallel. The low communication bandwidth between memory and processing units in conventional von Neumann machines does not support the requirements of emerging applications that rely extensively on large sets of data. More recent computing paradigms, such as high parallelization and near-memory computing, help alleviate the data communication bottleneck to some extent, but paradigm- shifting concepts are required. Memristors, a novel beyond-complementary metal-oxide-semiconductor (CMOS) technology, are a promising choice for memory devices due to their unique intrinsic device-level properties, enabling both storing and computing with a small, massively-parallel footprint at low power. Theoretically, this directly translates to a major boost in energy efficiency and computational throughput, but various practical challenges remain. In this work we review the latest efforts for achieving hardware-based memristive artificial neural networks (ANNs), describing with detail the working principia of each block and the different design alternatives with their own advantages and disadvantages, as well as the tools required for accurate estimation of performance metrics. Ultimately, we aim to provide a comprehensive protocol of the materials and methods involved in memristive neural networks to those aiming to start working in this field and the experts looking for a holistic approach.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2024_Aguirre_MemristorANNHWReview_NatCommun.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2024_Aguirre_MemristorANNHWReview_NatCommun.pdf", "priority": 8.42}, {"id": "W3197197128", "short": "Resistive Neural Hardware Accelerators", "title": "Resistive Neural Hardware Accelerators", "authors": ["Kamilya Smagulova", "Mohammed E. Fouda", "Fadi Kurdahi", "Khaled N. Salama", "Ahmed M. Eltawil"], "year": 2023, "venue": "Proceedings of the IEEE", "venue_short": "ProcIEEE", "venue_full": "Proceedings of the IEEE, vol. 111, 2023 (arXiv:2109.03934 preprint, 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/jproc.2023.3268092", "cites_global": 31, "cat": "01", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "MLP", "LSTM/RNN", "ResNet"], "evidence": "survey", "tldr": "Survey of many-core ReRAM crossbar DNN accelerators (ISAAC, PRIME, AEPE, PipeLayer, AtomLayer, Newton, CASCADE, PUMA/PANTHER) and fabricated ReRAM CIM macros, concluding that peripherals/interconnect dominate cost and that fair metrics, benchmarks and integrated simulators are missing.", "summary": "The paper reviews state-of-the-art ReRAM-based many-core/multi-node DNN accelerators, describing each architecture's tile/core hierarchy, pipeline and dataflow. It compares them on hierarchy, power and area breakdown, ReRAM technology assumptions, precision/data encoding (bit-serial inputs, weight composing/bit slicing), weight-mapping schemes (ISAAC unrolled kernels, AtomLayer row-disjoint mapping, PRIME positive/negative split and replication), interconnect (bus vs c-mesh NoC) and the modeling tools used (CACTI, NVSim, Orion, PUMAsim). It then summarises fabricated ReRAM CIM macros from ISSCC 2018-2020. The final section lays out open directions: new normalized performance metrics (Eyexam-style), device precision, endurance/retention, thermal density, stuck-at faults, IR drop/sneak paths, asymmetric programming nonlinearity, ADC/DAC overhead, NoC pipelining, CAD tools and benchmarking against AIBench/MLPerf workloads.", "contributions": ["Unified description and notation table for eight ReRAM many-core accelerator architectures", "Side-by-side comparison of power/area breakdown, precision/encoding, weight mapping, interconnect and modeling tools", "Summary table of fabricated ReRAM CIM macros (ISSCC'18-'20) with precision, TOPS/W and accuracy", "Catalogue of ReRAM non-idealities (SAF, IR drop, sneak paths, thermal effects, endurance) and mitigation approaches", "Argument for new bit-normalized performance metrics, AIBench-style benchmark coverage and integrated CAD tools"], "claims": [{"claim": "Area and power in state-of-the-art ReRAM accelerators are dominated by digital peripherals and communication, not by the crossbars.", "support": "\"Overall, it can be concluded that the majority of area and power in SotA ReRAM accelerators are consumed by digital peripheral circuits and communication links.\"", "loc": "Sec. 3.2, Figs. 10-11"}, {"claim": "Most ReRAM accelerators after ISAAC are incremental improvements on its design.", "support": "\"The majority of the subsequent works on accelerator architecture aimed to improve limitations of the design of ISAAC\"; AEPE gets 2.71x power efficiency and 2.41x area efficiency over ISAAC.", "loc": "Sec. 3"}, {"claim": "Peak-throughput metrics (GOPS, GOPS/W, GOPS/mm2) are insufficient for fair comparison of CIM accelerators.", "support": "Proposes normalizing ops/s to 1 bit and per-layer inferences/s and energy/inference, extending Eyexam.", "loc": "Sec. 5.1"}, {"claim": "ReRAM accelerators are evaluated on a narrow workload set, mostly image classification with MLP/CNN.", "support": "AIBench coverage tables show image classification dominates; only PUMA covers translation/speech/detection; normalization and dropout are not supported.", "loc": "Sec. 5.7, Tables 5-6"}, {"claim": "Existing simulators are fragmented and do not jointly model non-idealities of all components.", "support": "\"the diversity and disunity of design tools ... showed the need for an integrated universal simulation tool\"", "loc": "Sec. 5.6"}], "results": ["ISAAC vs DaDianNao (as reported by the survey): 14.8x throughput, 5.5x energy, 7.5x computational density", "CASCADE TIA interface: 77.5x lower energy than an ADC interface and 325.4x lower than a sense-amplifier interface; peak 101 GOPS/mm2", "Newton: 51% power-efficiency gain and 2.2x computation-efficiency over ISAAC", "PipeLayer power efficiency 142.9 GOPS/W, penalized by write energy for training", "Fabricated macros: 65 nm 1 Mb ISSCC'18 binary macro 25.42 TOPS/W @1V; 55 nm ISSCC'19 21.9 TOPS/W with CIFAR-10 88.52%; 22 nm 2 Mb ISSCC'20 45.52 TOPS/W @0.8V"], "limitations": ["Purely a literature review; numbers are copied from the original papers, which mostly rely on 32 nm simulation with differing assumptions", "Focus restricted to ReRAM many-core designs; PCM, Flash and SRAM-CIM are only mentioned in passing", "Text analysed is the 2021 arXiv v1; the 2023 Proc. IEEE version was extended (e.g. FORMS and thermal-aware work cited there are absent from v1)", "No new quantitative normalization of the compared accelerators despite advocating new metrics (\"due to the lack of data\")", "Transformers/attention workloads are not covered"], "remarks": "A useful, architecture-centric tour of the ISAAC lineage of ReRAM accelerators, with a good explanation of how kernels are unrolled/replicated onto crossbars (ISAAC, PRIME, AtomLayer) and of bit-serial/bit-sliced encoding. Its critical value lies in pointing out that peripherals dominate cost, that reported metrics are not comparable, and that workloads are narrow - points later formalised by benchmarking frameworks and tile-design perspectives. It predates the large measured PCM/ReRAM chips (IBM HERMES, NeuRRAM) and transformer-on-analog work, so it should be paired with newer reviews.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2109.03934", "abstract": "Deep neural networks (DNNs), as a subset of machine learning (ML) techniques, entail that real-world data can be learned, and decisions can be made in real time. However, their wide adoption is hindered by a number of software and hardware limitations. The existing general-purpose hardware platforms used to accelerate DNNs are facing new challenges associated with the growing amount of data and are exponentially increasing the complexity of computations. Emerging nonvolatile memory (NVM) devices and the compute-in-memory (CIM) paradigm are creating a new hardware architecture generation with increased computing and storage capabilities. In particular, the shift toward resistive random access memory (ReRAM)-based in-memory computing has great potential in the implementation of area- and power-efficient inference and in training large-scale neural network architectures. These can accelerate the process of IoT-enabled AI technologies entering our daily lives. In this survey, we review the state-of-the-art ReRAM-based DNN many-core accelerators, and their superiority compared to CMOS counterparts was shown. The review covers different aspects of hardware and software realization of DNN accelerators, their present limitations, and prospects. In particular, a comparison of the accelerators shows the need for the introduction of new performance metrics and benchmarking standards. In addition, the major concerns regarding the efficient design of accelerators include a lack of accuracy in simulation tools for software and hardware codesign.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2023_Smagulova_ResistiveNeuralHardwareAccelerators_ProcIEEE.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2023_Smagulova_ResistiveNeuralHardwareAccelerators_ProcIEEE.pdf", "priority": 5.45}, {"id": "W4313254474", "short": "CIM-NVM-Codesign-Review", "title": "Compute in‐Memory with Non‐Volatile Elements for Neural Networks: A Review from a Co‐Design Perspective", "authors": ["Wilfried E. Haensch", "Anand Raghunathan", "Kaushik Roy", "Bhaswar Chakrabarti", "Charudatta Phatak", "Cheng Wang", "Supratik Guha"], "year": 2022, "venue": "Advanced Materials", "venue_short": "AdvMater", "venue_full": "Advanced Materials (2022)", "venue_ok": true, "doi": "https://doi.org/10.1002/adma.202204944", "cites_global": 134, "cat": "01", "seed": false, "devices": ["PCM", "ReRAM", "MRAM", "ECRAM", "FeFET", "SRAM-analog"], "models": ["CNN", "MLP"], "evidence": "survey", "tldr": "A materials-to-architecture co-design review of crossbar compute-in-memory, deriving sub-system-level requirements (resistance range, ON/OFF ratio, endurance, cell size, ADC overhead) that PCM, RRAM, MRAM, ECRAM and FeFET/FTJ devices must meet for digital- and all-analog neural-network inference and training.", "summary": "The paper addresses the von Neumann memory-wall bottleneck for deep learning and argues that cross-bar compute-in-memory (CIM), where non-volatile memory (NVM) elements perform an analog multiply-accumulate via Ohm's/Kirchhoff's laws, is a key candidate architecture. Rather than reviewing devices in isolation, the authors take a co-design view: starting from cross-bar array architecture, bit-slicing for digital-precision storage, partitioning of large matrices, ADC/DAC and peripheral-circuit energy budgets, and the distinct requirements of all-analog (continuously tunable, in-array weight-update) versus digital-storage/analog-MAC designs, they derive concrete device-level targets (resistance range ~10 MOhm for all-analog, multi-bit capability, endurance, variation, drift). They then survey the device physics, maturity and reported cross-bar MVM demonstrations for PCM, RRAM (filamentary and interfacial), ECRAM, FeFET/FTJ and MRAM (STT/SOT), tabulating cell area, write energy/latency, endurance and multi-level capability (Table II) against SRAM/eDRAM. The discussion concludes that MRAM is the most mature but limited by low resistance (IR drop, power) and single-bit storage; RRAM/PCM offer compact multi-bit cells but suffer variability, drift and limited endurance; and RRAM/ECRAM are the most promising route to fully analog on-chip training once their low intrinsic resistance range and noise are addressed. No single candidate currently meets every requirement, and the energy-efficiency case is argued to be stronger for training than for inference.", "contributions": ["A co-design framework connecting CMOS/cross-bar architectural constraints (bit-slicing, partitioning, ADC/DAC energy, analog vs. digital storage) to the physical requirements placed on NVM materials", "A systematic comparison of PCM, RRAM, ECRAM, FeFET/FTJ and MRAM against derived sub-system metrics (resistance range, multi-bit capability, endurance, cell area, write energy/latency) rather than single-device figures of merit", "A review and critical reading of representative RRAM/PCM/MRAM cross-bar MVM hardware demonstrations, highlighting weight-transfer and variability issues", "A quantitative summary table (Table II, Sec. 6) comparing NVM, SRAM and eDRAM on storage density, Ron/Roff, write energy/latency, endurance and multi-level capability", "Explicit, differentiated requirements for inference-only (digital storage) versus all-analog training-capable crossbars (e.g., ~10 MOhm target resistance, symmetric/near-symmetric conductance update for RRAM/ECRAM)"], "claims": [{"claim": "ADC/peripheral circuitry, not the NVM array itself, dominates cross-bar tile area and energy in current CIM implementations", "support": "ADC consumes about 60% of total energy and over 80% of chip area in CIM hardware", "loc": "Sec. 2 (citing ref [27]); Sec. 4"}, {"claim": "MRAM is the most mature NVM candidate for digital on-chip CIM but is limited by its low resistance", "support": "STT-MRAM offers >10^15 cycle endurance, ~10-20ns access, 2-4x higher density than SRAM, but low resistance causes IR drop and higher power, and is restricted to 1-bit storage", "loc": "Sec. 4, Table II"}, {"claim": "RRAM and PCM provide compact, multi-bit cells but suffer reliability problems that limit analog weight storage", "support": "16F^2 cell area and large ON/OFF ratio for RRAM/PCM vs 30-80F^2 for MRAM and 160F^2 for SRAM (Table II), but both exhibit conductance drift, device-to-device and cycle-to-cycle variation, and limited endurance (10^5-10^7 cycles)", "loc": "Sec. 4, Table II"}, {"claim": "RRAM and ECRAM are the most promising devices for fully analog on-chip training, but their resistance range is currently too low for large arrays", "support": "a target resistance of ~10 MOhm is needed to support large array sizes, while current RRAM/ECRAM operate in the 10s of kOhm to 100 kOhm range", "loc": "Sec. 4"}, {"claim": "No current NVM candidate satisfies all cross-bar CIM requirements simultaneously", "support": "stated conclusion after comparing PCM/RRAM/MRAM/ECRAM/FeFET against derived sub-system targets", "loc": "Sec. 5 Conclusion"}], "results": ["ADC overhead: ~60% of energy and >80% of chip area in representative CIM macros (per cited ref [27])", "Device comparison table: PCM write energy ~6nJ/150ns, RRAM ~2nJ/100ns, MRAM <1nJ/10ns vs SRAM <0.1nJ/<1ns and eDRAM <0.2nJ/1-2ns (Table II)", "Endurance comparison: PCM ~10^7 cycles, RRAM ~10^5 cycles, MRAM ~10^15 cycles, SRAM/eDRAM >10^16 cycles (Table II)", "Cell area: PCM and RRAM ~16F^2, MRAM 30-80F^2, SRAM ~160F^2, eDRAM ~30F^2 (Table II)", "Example RRAM MVM demonstration (ref [169]) on a 96x40 one-layer MNIST network: 89.9% classification accuracy, about 2.5 percentage points below theoretical expectation for that configuration, attributed to weight-transfer and multi-bit noise"], "limitations": ["A literature/co-design review, not new experimental or simulation data; conclusions depend on the accuracy and comparability of the many cited sources' reported numbers", "Device comparison table (Table II) is explicitly noted as 'broadly indicative,' not a rigorous apples-to-apples benchmark across process nodes", "Authors note that reported speed/energy numbers from hardware demonstrations are often not directly comparable across papers because full end-to-end system costs are frequently omitted", "Focuses on PCM/RRAM/MRAM/ECRAM/FeFET; charge-domain/capacitor-based and SRAM-analog CIM approaches get comparatively less device-physics depth"], "remarks": "A materials-science-oriented counterpart to architecture-focused CIM surveys: its value for mapping work is the explicit translation of architectural choices (bit-slicing vs. all-analog, array size, ADC budget) into quantitative device targets (resistance range, multi-bit capability, endurance), which is a clearer causal chain than most device review papers provide. The claim that ADC/peripherals dominate area and energy is widely corroborated elsewhere in the field and is a recurring justification for ADC-free and peripheral-aware architectures and mapping schemes. Because it is a 2022 review co-authored by device/CMOS specialists rather than ML systems researchers, its treatment of training-time non-idealities and large-scale (CNN/Transformer) mapping is comparatively shallow next to papers in categories 05-07.", "basis": "full-text", "pdf_source_url": "", "abstract": "Deep learning has become ubiquitous, touching daily lives across the globe. Today, traditional computer architectures are stressed to their limits in efficiently executing the growing complexity of data and models. Compute-in-memory (CIM) can potentially play an important role in developing efficient hardware solutions that reduce data movement from compute-unit to memory, known as the von Neumann bottleneck. At its heart is a cross-bar architecture with nodal non-volatile-memory elements that performs an analog multiply-and-accumulate operation, enabling the matrix-vector-multiplications repeatedly used in all neural network workloads. The memory materials can significantly influence final system-level characteristics and chip performance, including speed, power, and classification accuracy. With an over-arching co-design viewpoint, this review assesses the use of cross-bar based CIM for neural networks, connecting the material properties and the associated design constraints and demands to application, architecture, and performance. Both digital and analog memory are considered, assessing the status for training and inference, and providing metrics for the collective set of properties non-volatile memory materials will need to demonstrate for a successful CIM technology.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2022_Haensch_CIMNVMCodesignReview_AdvMater.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2022_Haensch_CIMNVMCodesignReview_AdvMater.pdf", "priority": 4.99}, {"id": "W4225739994", "short": "PIM Circuits Overview", "title": "An Overview of Processing-in-Memory Circuits for Artificial Intelligence and Machine Learning", "authors": ["Donghyuk Kim", "Chengshuo Yu", "Shanshan Xie", "Yuzong Chen", "Joo-Young Kim", "Bongjin Kim", "Jaydeep P. Kulkarni", "Tony Tae-Hyoung Kim"], "year": 2022, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems, vol. 12, no. 2, pp. 338-353, June 2022", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2022.3160455", "cites_global": 85, "cat": "01", "seed": false, "devices": ["SRAM-analog", "DRAM", "ReRAM", "Charge/Capacitor"], "models": ["CNN", "MLP"], "evidence": "survey", "tldr": "Circuit-level survey of SRAM-, DRAM- and ReRAM-based processing-in-memory for AI, covering bitcells, MAC sensing modes, multi-bit schemes, PIM software stacks and open problems (data-converter overhead, accuracy, intra-memory data movement).", "summary": "The paper organises PIM work by memory type. For SRAM it reviews 6T/8T/capacitor-augmented bitcells and current-, voltage-, charge-sharing and capacitive-coupling accumulation modes plus digital SRAM PIM; for DRAM it covers cell-level bulk bitwise PIM, bank-level PIM (Newton, Samsung HBM-PIM) and 3D HMC-based PIM (Neurocube, Tetris, iPIM). For ReRAM it explains current-mode vs voltage-mode MAC sensing, why most macros use binary (HRS/LRS) cells with parallel-input or serial-input multi-bit composition, ADC/DAC overhead and bit-line current distribution problems, and trends from ISSCC macros. It then describes a PIM software stack (framework, library, runtime, driver), offloading, data mapping, scheduling and cache coherence, and closes with research directions on data converters, test accuracy and im2col-induced intra-memory data movement.", "contributions": ["Taxonomy of PIM circuits by memory technology (SRAM analog/digital, DRAM cell/bank/3D, ReRAM)", "Explanation of ReRAM MAC sensing modes and multi-bit (PIPW vs SIPW) composition with binary cells", "Identification of ReRAM PIM design challenges: ADC/DAC overhead and BL current distribution from HRS leakage", "Overview of a PIM software stack and system-integration issues (offloading, data mapping, scheduling, coherence)", "Comparison tables of SRAM/DRAM/ReRAM PIM prototypes, data converters and reported test accuracy"], "claims": [{"claim": "Data converters dominate ReRAM PIM macro power and area.", "support": "For a 1152x128 ReRAM macro with 2-bit DACs and 8-bit ADCs, DACs and ADCs consume 24% and 61% of total power; ADCs occupy 91% of area at 8-bit output precision.", "loc": "Sec. IV-D1"}, {"claim": "Most ReRAM PIM macros use binary (digital) cells rather than analog multi-level cells.", "support": "Due to large device variation, HRS offset current, and costly write-verify for multi-level states; \"Digital ReRAM is more preferred compared with analog ReRAM due to large ReRAM device variations.\"", "loc": "Sec. IV-C, IV-E"}, {"claim": "Current-mode sensing dominates ReRAM PIM despite worse energy efficiency than voltage-mode.", "support": "Current mode gives larger sensing margin; \"most ReRAM PIM works are based on current-mode sensing\" while static current hurts energy.", "loc": "Sec. IV-B"}, {"claim": "Recent CIM demonstrations reach near-software accuracy on small benchmarks.", "support": "MNIST 97%-99.63%; CIFAR-10 80.1%-92.52% with 0.55%-1.39% drop from software.", "loc": "Sec. VI-B, Table VI"}, {"claim": "HRS leakage current makes BL current for a given MAC value input-dependent, degrading sensing margin.", "support": "For a macro with max MAC 9, MAC='+1' ranges from '1L0H' to '1L8H' BL current configurations.", "loc": "Sec. IV-D2"}], "results": ["ReRAM macro power breakdown: DAC 24%, ADC 61%; ADC area 91% at 8-bit output (as reported for a 1152x128 macro)", "Reported CIM test accuracy range: MNIST 97%-99.63%, CIFAR-10 80.1%-92.52% (0.55%-1.39% below software)", "Cited retraining example: CIFAR-10 accuracy recovered from 90.3% (81.6% uncalibrated) to 91.6% (86.2%) after 3 epochs vs 91.9% float", "BNN-based CIM avoids data conversion but costs ~3% accuracy on CIFAR-10"], "limitations": ["Breadth over depth: ReRAM is one section among SRAM and DRAM; PCM, Flash and FeFET are not covered", "Focused on macro-level circuits and small benchmarks (MNIST/CIFAR-10); no discussion of large models or transformers on analog arrays", "No quantitative re-normalization of the compared prototypes; tables mix technologies and precisions", "Hardware-aware training and device non-ideality modeling are only touched on briefly"], "remarks": "A compact, circuit-designer-oriented primer that is useful for understanding why fabricated ReRAM macros have favoured binary cells, current-mode sensing and input bit-serial schemes, and how badly ADCs dominate macro cost. Its software-stack section is DRAM/HBM-PIM centric and does not address weight-stationary crossbar mapping or noise, which later analog-specific perspectives (e.g. IBM's software-stack review) treat in depth. The ADC breakdown it cites (from the 78.4 TOPS/W ReRAM chip) is a frequently reused motivation for ADC-reduction research.", "basis": "full-text", "pdf_source_url": "https://sites.utexas.edu/CRL/files/2022/06/PIM_overview_JETCAS2022.pdf", "abstract": "Artificial intelligence (AI) and machine learning (ML) are revolutionizing many fields of study, such as visual recognition, natural language processing, autonomous vehicles, and prediction. Traditional von-Neumann computing architecture with separated processing elements and memory devices have been improving their computing performances rapidly with the scaling of process technology. However, in the era of AI and ML, data transfer between memory devices and processing elements becomes the bottleneck of the system. To address this data movement issue, memory-centric computing takes an approach of merging the memory devices with processing elements so that computations can be done in the same location without moving any data. Processing-In-Memory (PIM) has attracted research community’s attention because it can improve the energy efficiency of memory-centric computing systems substantially by minimizing the data movement. Even though the benefits of PIM are well accepted, its limitations and challenges have not been investigated thoroughly. This paper presents a comprehensive investigation of state-of-the-art PIM research works based on various memory device types, such as static-random-access-memory (SRAM), dynamic-random-access-memory (DRAM), and resistive memory (ReRAM). We will present the overview of PIM designs in each memory type, covering from bit cells, circuits, and architecture. Then, a new software stack standard and its challenges for incorporating PIM with the conventional computing architecture will be discussed. Finally, we will discuss various future research directions in PIM for further reducing the data conversion overhead, improving test accuracy, and minimizing intra-memory data movement.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2022_Kim_PIMCircuitsOverview_JETCAS.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2022_Kim_PIMCircuitsOverview_JETCAS.pdf", "priority": 5.76}, {"id": "W3194056411", "short": "CIM Chips for Deep Learning", "title": "Compute-in-Memory Chips for Deep Learning: Recent Trends and Prospects", "authors": ["Shimeng Yu", "Hongwu Jiang", "Shanshi Huang", "Xiaochen Peng", "Anni Lu"], "year": 2021, "venue": "IEEE Circuits and Systems Magazine", "venue_short": "CASMag", "venue_full": "IEEE Circuits and Systems Magazine, vol. 21, no. 3, pp. 31-56 (2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/mcas.2021.3092533", "cites_global": 393, "cat": "01", "seed": false, "devices": ["SRAM-analog", "ReRAM"], "models": ["CNN"], "evidence": "survey", "tldr": "Review of silicon-demonstrated SRAM- and RRAM-based CIM macros for DNNs, their common design challenges (ADC bottleneck, analog variation, device non-idealities), and the DNN+NeuroSim framework for device-to-system co-design of CIM inference and training.", "summary": "CIM performs DNN multiply-and-accumulate in the analog domain within memory sub-arrays to address the memory wall. The review first surveys recent SRAM and RRAM CIM macros demonstrated in silicon (e.g., ISSCC/VLSI macros). It then discusses general CIM chip challenges: the analog-to-digital conversion bottleneck, variations in analog computation, and device non-idealities. Finally, it introduces the DNN+NeuroSim benchmark framework for evaluating device technologies in CIM inference and training from a software/hardware co-design perspective. Abstract-only basis; specific macro metrics not reproduced.", "contributions": ["Survey of measured SRAM and RRAM CIM macros in silicon.", "Discussion of ADC bottleneck, analog variation and device non-idealities as cross-cutting CIM challenges.", "Tutorial-style introduction to DNN+NeuroSim for device-to-system CIM benchmarking."], "claims": [{"claim": "Performing MACs in the analog domain inside memory sub-arrays yields significant throughput and energy-efficiency improvements.", "support": "Abstract states this as the motivating premise of CIM.", "loc": "Abstract"}, {"claim": "ADC conversion is a key bottleneck of CIM chips, together with analog-compute variation and device non-idealities.", "support": "Abstract: 'general design challenges of the CIM chips including analog-to-digital conversion (ADC) bottleneck, variations in analog compute, and device non-idealities'.", "loc": "Abstract"}, {"claim": "DNN+NeuroSim can evaluate versatile device technologies for CIM inference and training.", "support": "Abstract: 'DNN+NeuroSim benchmark framework that is capable of evaluating versatile device technologies for CIM inference and training'.", "loc": "Abstract"}], "results": ["Quantitative macro comparisons not extracted (abstract-only basis)."], "limitations": ["Full text not accessed; macro metrics (TOPS/W, precision) not verified.", "Benchmarking relies on the authors' own NeuroSim framework.", "CNN-centric; no Transformer workloads."], "remarks": "A good 2021 snapshot of measured SRAM/RRAM CIM macros and the peripheral (ADC) problem, useful for situating analog crossbar accelerators against silicon reality. Pair with Sebastian et al. 2020 for device breadth and with NeuroSim papers (Peng et al.) for methodology.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Compute-in-memory (CIM) is a new computing paradigm that addresses the memory-wall problem in hardware accelerator design for deep learning. The input vector and weight matrix multiplication, i.e., the multiply-and-accumulate (MAC) operation, could be performed in the analog domain within memory sub-array, leading to significant improvements in throughput and energy efficiency. Static random access memory (SRAM) and emerging non-volatile memories such as resistive random access memory (RRAM) are promising candidates to store the weights of deep neural network (DNN) models. In this review, firstly we survey the recent progresses in SRAM and RRAM based CIM macros that have been demonstrated in silicon. Then we discuss general design challenges of the CIM chips including analog-to-digital conversion (ADC) bottleneck, variations in analog compute, and device non-idealities. Next we introduce the DNN+NeuroSim benchmark framework that is capable of evaluating versatile device technologies for CIM inference and training performance from software/hardware co-design's perspective.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2021_Yu_CIMChipsDeepLearning_CASMag.pdf", "analysed": true, "pdf": null, "priority": 8.65}, {"id": "W3155456425", "short": "RRAM for CIM: Inference to Training", "title": "RRAM for Compute-in-Memory: From Inference to Training", "authors": ["Shimeng Yu", "Wonbo Shim", "Xiaochen Peng", "Yandong Luo"], "year": 2021, "venue": "IEEE Transactions on Circuits and Systems I Regular Papers", "venue_short": "TCAS-I", "venue_full": "IEEE Transactions on Circuits and Systems I: Regular Papers, vol. 68, no. 7, pp. 2753-2765 (2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcsi.2021.3072200", "cites_global": 141, "cat": "01", "seed": false, "devices": ["ReRAM", "Charge/Capacitor"], "models": ["CNN"], "evidence": "device-experiment", "tldr": "Review of RRAM-based CIM that adds measured multilevel RRAM data from a test vehicle, a scalability/monolithic-3D benchmark of RRAM CIM inference, and a hybrid-precision RRAM+capacitor synapse for in-situ training evaluated at system level.", "summary": "Targeting edge ML, the paper reviews RRAM-based compute-in-memory accelerators and their instant-on, non-volatile benefits. First, multilevel RRAM characteristics are measured on a test vehicle to assess key device properties for inference. Second, a benchmark (NeuroSim-based) studies the scalability of RRAM CIM inference engines and the feasibility of monolithic 3D integration of RRAM arrays above advanced logic nodes. Third, it presents the grand challenges for in-situ training on RRAM and proposes a hybrid-precision synapse combining RRAM with a volatile capacitor-based memory to enable fast, accurate in-situ training followed by inference, evaluated at system level. Abstract-only basis; numbers not reproduced.", "contributions": ["Measurement of multilevel RRAM states from a test vehicle for inference-relevant properties.", "System-level benchmark of RRAM CIM scalability and monolithic 3D (RRAM-on-logic) integration.", "Analysis of grand challenges for in-situ training on RRAM.", "Hybrid-precision RRAM + capacitor synapse design and system-level evaluation for training then inference."], "claims": [{"claim": "RRAM enables instant-on CIM inference at the edge with improved throughput and energy efficiency.", "support": "Abstract: 'Instant-on inference is further enabled by emerging non-volatile memory technologies such as RRAM'.", "loc": "Abstract"}, {"claim": "Monolithic 3D stacking of RRAM arrays on advanced logic is feasible for CIM inference engines.", "support": "Abstract: benchmark studies 'feasibility towards monolithic 3D integration that stacks RRAM arrays on top of advanced logic process node'.", "loc": "Abstract"}, {"claim": "A hybrid precision synapse (RRAM + capacitor) supports accurate and fast in-situ training and subsequent inference on one platform.", "support": "Abstract describes design and system-level evaluation of this synapse.", "loc": "Abstract"}], "results": ["Quantitative results not extracted (abstract-only basis)."], "limitations": ["Full text not accessed; measured and benchmarked numbers not verified.", "Benchmarks rely on NeuroSim models rather than full silicon.", "Capacitor-based volatile weights need refresh/transfer overhead (typical of hybrid-precision schemes)."], "remarks": "Represents the Georgia Tech/NeuroSim view that RRAM is ready for inference but training needs hybrid volatile/non-volatile synapses, echoing IBM's PCM+capacitor 3T1C work (Ambrogio 2018). Useful for M3D and scaling arguments, but its numbers come from the authors' simulator.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "To efficiently deploy machine learning applications to the edge, compute-in-memory (CIM) based hardware accelerator is a promising solution with improved throughput and energy efficiency. Instant-on inference is further enabled by emerging non-volatile memory technologies such as resistive random access memory (RRAM). This paper reviews the recent progresses of the RRAM based CIM accelerator design. First, the multilevel states RRAM characteristics are measured from a test vehicle to examine the key device properties for inference. Second, a benchmark is performed to study the scalability of the RRAM CIM inference engine and the feasibility towards monolithic 3D integration that stacks RRAM arrays on top of advanced logic process node. Third, grand challenges associated with in-situ training are presented. To support accurate and fast in-situ training and enable subsequent inference in an integrated platform, a hybrid precision synapse that combines RRAM with volatile memory (e.g. capacitor) is designed and evaluated at system-level. Prospects and future research needs are discussed.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2021_Yu_RRAMforCIMInferenceToTraining_TCAS-I.pdf", "analysed": true, "pdf": null, "priority": 7.34}, {"id": "W3013080934", "short": "Memory Devices for IMC", "title": "Memory devices and applications for in-memory computing", "authors": ["Abu Sebastian", "Manuel Le Gallo", "Riduan Khaddam-Aljameh", "Evangelos S. Eleftheriou"], "year": 2020, "venue": "Nature Nanotechnology", "venue_short": "NatNanotechnol", "venue_full": "Nature Nanotechnology, vol. 15, pp. 529-544 (2020)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41565-020-0655-z", "cites_global": 2277, "cat": "01", "seed": true, "devices": ["SRAM-analog", "DRAM", "Flash", "ReRAM", "PCM", "MRAM", "FeFET"], "models": ["MLP", "CNN", "LSTM/RNN", "SNN"], "evidence": "survey", "tldr": "Highly cited Nature Nanotechnology review of charge-based (SRAM, DRAM, Flash) and resistance-based (RRAM, PCM, MRAM) memory devices for in-memory computing, their computational primitives (logic, MVM) and applications from scientific computing to deep learning.", "summary": "The review motivates in-memory computing by the energy/time cost of data movement in von Neumann systems, worsened by data-centric AI workloads. It surveys both charge-based memories (SRAM, DRAM, Flash) and resistance-based memories (RRAM, PCM, MRAM, and related devices) and the key computational primitives they enable, notably in-place logical operations and analog matrix-vector multiplication. Applications span scientific computing (including mixed-precision linear solvers), signal processing, optimization, machine learning, deep-learning inference and training, and stochastic computing. It also discusses non-idealities (noise, drift, variability), precision and peripheral challenges, and outlook. Abstract-only basis here; numbers not reproduced.", "contributions": ["Unified review across charge-based and resistance-based memories for in-memory computing.", "Organization by computational primitive (logic, MVM) and by application domain.", "Discussion of DL inference/training on IMC including device non-idealities and mixed-precision approaches.", "Outlook on challenges toward commercial IMC."], "claims": [{"claim": "In-memory computing exploits physical attributes of memory devices to perform computation in place, avoiding costly data movement.", "support": "Publisher summary: 'In-memory computing performs certain computational tasks in place in the memory itself by exploiting the physical attributes of the memory devices'.", "loc": "Abstract"}, {"claim": "Both charge-based and resistance-based memory devices are viable for in-memory computing.", "support": "Publisher summary: 'Both charge-based and resistance-based memory devices are being explored for in-memory computing'.", "loc": "Abstract"}, {"claim": "IMC primitives apply across scientific computing, signal processing, optimization, ML/DL and stochastic computing.", "support": "Semantic Scholar TLDR / summary listing these applications.", "loc": "Abstract"}], "results": ["Qualitative review; no quantitative results extracted (abstract-only basis)."], "limitations": ["Full text not accessed; specific comparisons not verified.", "Broad scope means limited architectural detail on tiling, ADC sharing and compilation.", "Pre-Transformer era: does not cover attention/LLM workloads."], "remarks": "Arguably the most cited general IMC review (41 in-set citations); it is the standard reference for the charge- vs resistance-based taxonomy and for IBM's PCM view (drift, mixed precision, hardware-aware training). For a thesis on mapping models onto analog crossbars it is the best single overview to cite, complemented by Xiao et al. 2020 for circuits/architecture and Yu et al. 2021 for silicon macros.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [{"fid": "F15", "text": "The shared motivation across this literature is the memory wall: data movement between separate processing and memory units is the dominant time and energy cost in von Neumann systems, aggravated by data-centric AI workloads. In-memory computing computes in place inside the array by exploiting device physics; two-terminal resistive switching devices are the favoured substrate.", "grade": "High confidence", "vote": "4 claims merged · 3–0 unanimous", "note": "Nature Electronics 2018 · Nature Nanotechnology 2020"}], "pdf_expected": "01_Surveys_and_Foundations/2020_Sebastian_MemoryDevicesInMemoryComputing_NatNanotechnol.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2020_Sebastian_MemoryDevicesInMemoryComputing_NatNanotechnol.pdf", "priority": 12.83}, {"id": "W3041897167", "short": "Analog NN Architectures on NVM", "title": "Analog architectures for neural network acceleration based on non-volatile memory", "authors": ["T. Patrick Xiao", "Christopher H. Bennett", "Ben Feinberg", "Sapan Agarwal", "Matthew J. Marinella"], "year": 2020, "venue": "Applied Physics Reviews", "venue_short": "ApplPhysRev", "venue_full": "Applied Physics Reviews, vol. 7, 031301 (2020)", "venue_ok": true, "doi": "https://doi.org/10.1063/1.5143815", "cites_global": 195, "cat": "01", "seed": false, "devices": ["ReRAM", "PCM", "ECRAM", "Flash", "Generic-NVM"], "models": ["MLP", "CNN"], "evidence": "survey", "tldr": "Sandia review of analog NVM crossbar accelerators for deep supervised learning, organized by the accelerator design hierarchy with emphasis on circuits and architecture, consolidating techniques that address peripheral overhead and device non-idealities for inference and training.", "summary": "Analog accelerators that compute inside dense memory arrays promise to remove data-movement bottlenecks, but peripheral circuitry overhead (ADCs/DACs, etc.) and device non-idealities have made the gains hard to realize. The review organizes existing implementations around the levels of the design hierarchy (device, array/circuit, architecture, algorithm) with an emphasis on circuits and architecture. It consolidates proposed solutions for both inference and training and highlights the key design trade-offs behind them, such as weight/input encoding, bit slicing, ADC precision and sharing, and handling of non-ideal device behavior. Abstract-only basis; numbers not reproduced.", "contributions": ["Hierarchy-based organization (device-circuit-architecture) of analog NVM accelerator literature.", "Consolidation of techniques for mitigating peripheral overhead and device non-idealities.", "Coverage of both inference and in-situ training accelerators.", "Explicit statement of design trade-offs underlying the techniques."], "claims": [{"claim": "Peripheral circuitry overhead and non-ideal device properties are the principal obstacles to realizing analog accelerator advantages.", "support": "Abstract: 'challenging principally due to the overhead imposed by the peripheral circuitry and due to the non-ideal properties of memory devices'.", "loc": "Abstract"}, {"claim": "Analog accelerators can overcome major bottlenecks of digital hardware for data-heavy workloads like deep learning.", "support": "Abstract: 'have the potential to overcome the major bottlenecks faced by digital hardware for data-heavy workloads such as deep learning'.", "loc": "Abstract"}], "results": ["Qualitative review; quantitative comparisons not extracted (abstract-only basis)."], "limitations": ["Full text not accessed despite being CC-BY open access (publisher/OSTI downloads blocked from this machine).", "Focus on supervised DNNs; no Transformer/LLM workloads.", "Comparisons across papers use heterogeneous assumptions."], "remarks": "Among the most useful reviews for an architecture/mapping thesis because it is circuit- and architecture-centric (Sandia's CrossSim team), complementing the device-centric Nature reviews. It should be read for its treatment of ADC overhead, bit slicing and weight-encoding trade-offs; it is open access (CC-BY) at the publisher.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Analog hardware accelerators, which perform computation within a dense memory array, have the potential to overcome the major bottlenecks faced by digital hardware for data-heavy workloads such as deep learning. Exploiting the intrinsic computational advantages of memory arrays, however, has proven to be challenging principally due to the overhead imposed by the peripheral circuitry and due to the non-ideal properties of memory devices that play the role of the synapse. We review the existing implementations of these accelerators for deep supervised learning, organizing our discussion around the different levels of the accelerator design hierarchy, with an emphasis on circuits and architecture. We explore and consolidate the various approaches that have been proposed to address the critical challenges faced by analog accelerators, for both neural network inference and training, and highlight the key design trade-offs underlying these techniques.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2020_Xiao_AnalogArchitecturesNVM_ApplPhysRev.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2020_Xiao_AnalogArchitecturesNVM_ApplPhysRev.pdf", "priority": 7.13}, {"id": "W3042468132", "short": "Resistive Crossbars as Approximate Hardware", "title": "Resistive Crossbars as Approximate Hardware Building Blocks for Machine Learning: Opportunities and Challenges", "authors": ["Indranil Chakraborty", "Mustafa Ali", "Aayush Ankit", "Shubham Jain", "Sourjya Roy", "Shrihari Sridharan", "Amogh Agrawal", "Anand Raghunathan", "Kaushik Roy"], "year": 2020, "venue": "Proceedings of the IEEE", "venue_short": "ProcIEEE", "venue_full": "Proceedings of the IEEE, vol. 108, no. 12, pp. 2276-2310 (2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/jproc.2020.3003007", "cites_global": 140, "cat": "01", "seed": false, "devices": ["ReRAM", "PCM", "MRAM", "Generic-NVM"], "models": ["CNN", "MLP", "LSTM/RNN"], "evidence": "survey", "tldr": "Purdue review treating NVM resistive crossbars as inherently approximate MVM engines for ML: device/circuit design principles, functional impact of non-idealities, spatial architectures, and device-to-architecture evaluation frameworks.", "summary": "The paper argues that resistive NVM crossbars are attractive building blocks for ML because of high density and massively parallel in-situ MVM, but that analog crossbar computing is inherently approximate due to device and circuit non-idealities, and that ADC/DAC peripheral costs can greatly erode intrinsic efficiency. It describes the design principles of crossbars (devices and circuits), analyses intrinsic approximations and their functional impact on MVM, and reviews spatial architectures exploiting NVM storage density (e.g., the authors' PUMA line). It also covers software frameworks that capture device-circuit-architecture characteristics to evaluate large DNNs on crossbar hardware (e.g., RxNN/GENIEx-style models) and closes with open challenges. Abstract-only basis; numbers not reproduced.", "contributions": ["Framing of resistive crossbars as approximate computing primitives with a taxonomy of non-idealities.", "Analysis of the functional impact of device/circuit non-idealities on MVM.", "Overview of spatial crossbar-based architectures for ML.", "Review of device-circuit-architecture evaluation frameworks for large DNNs.", "Open challenges and research directions."], "claims": [{"claim": "Resistive crossbar-based analog computing is inherently approximate due to device- and circuit-level non-idealities.", "support": "Abstract states this directly.", "loc": "Abstract"}, {"claim": "Area and energy of analog-digital conversion peripherals can greatly diminish crossbar MVM efficiency.", "support": "Abstract: 'the area and energy costs of peripheral circuits for conversions between the analog and digital domains can greatly diminish the intrinsic efficiency'.", "loc": "Abstract"}, {"claim": "Cross-layer simulation frameworks are needed to evaluate large DNNs on resistive crossbar hardware.", "support": "Abstract: elaborates on 'software frameworks that effectively capture device-circuit-architecture characteristics to evaluate the performance of large-scale DNNs'.", "loc": "Abstract"}], "results": ["Qualitative review; no quantitative results extracted (abstract-only basis)."], "limitations": ["Full text not accessed; specific error/accuracy figures not verified.", "Largely reflects the authors' own frameworks and architectures (PUMA, RxNN, GENIEx).", "Pre-Transformer focus."], "remarks": "A strong review for the mapping/non-ideality angle: it ties crossbar non-idealities (IR drop, sneak paths, peripheral nonlinearity) to DNN accuracy via simulation frameworks and connects to spatial architectures and compilers. Useful bridge between device reviews and architecture papers such as ISAAC/PUMA.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Traditional computing systems based on the von Neumann architecture are fundamentally bottlenecked by data transfers between processors and memory. The emergence of data-intensive workloads, such as machine learning (ML), creates an urgent need to address this bottleneck by designing computing platforms that utilize the principle of colocated memory and processing units. Such an approach, known as “in-memory computing,” can potentially eliminate data movement costs by computing inside the memory array itself. Crossbars based on resistive nonvolatile memory (NVM) devices have shown immense promise in serving as the building blocks of in-memory computing systems for ML workloads. This is because their high density can lead to higher on-chip storage capacity, while they can also perform massively parallel, in situ matrix-vector multiplication (MVM) operations, thereby accelerating the main computational kernel of ML workloads. However, resistive crossbar-based analog computing is inherently approximate due to the device- and circuit-level nonidealities. Furthermore, the area and energy costs of peripheral circuits for conversions between the analog and digital domains can greatly diminish the intrinsic efficiency of crossbar-based MVM computation. We present a comprehensive overview of the emerging paradigm of computing using NVM crossbars for accelerating ML workloads. We describe the design principles of resistive crossbars, including the devices and associated circuits that constitute them. We discuss intrinsic approximations arising from the device and circuit characteristics and study their functional impact on the MVM operation. Next, we present an overview of spatial architectures that exploit the high storage density of NVM crossbars. Furthermore, we elaborate on software frameworks that effectively capture device-circuit-architecture characteristics to evaluate the performance of large-scale deep neural networks (DNNs) using resistive crossbar-based hardware. Finally, we discuss open challenges and future research directions that need to be explored in order to realize the vision of resistive crossbars as the building blocks of future computing platforms.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2020_Chakraborty_ResistiveCrossbarsApproximateHW_ProcIEEE.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2020_Chakraborty_ResistiveCrossbarsApproximateHW_ProcIEEE.pdf", "priority": 7.03}, {"id": "W2923010225", "short": "Memristive Crossbar Arrays", "title": "Memristive crossbar arrays for brain-inspired computing", "authors": ["Qiangfei Xia", "J. Joshua Yang"], "year": 2019, "venue": "Nature Materials", "venue_short": "NatMater", "venue_full": "Nature Materials, vol. 18, pp. 309-323 (2019)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41563-019-0291-x", "cites_global": 1792, "cat": "01", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["MLP", "CNN", "SNN"], "evidence": "survey", "tldr": "Nature Materials review of memristive crossbar arrays for brain-inspired computing, discussing device/materials and integration challenges of large-scale memristive networks as DL accelerators and as building blocks of spiking neural networks.", "summary": "The review covers in-memory computing with memristor crossbars, where conductances store weights and Ohm's law plus Kirchhoff's current law implement multiply-accumulate in one step. It discusses the materials and device engineering of memristors and the challenges of integrating them into large-scale arrays, including selector/transistor integration and array-level non-idealities. Applications are split into accelerators for deep learning (analog vector-matrix multiplication) and building blocks for spiking neural networks (using device dynamics). The authors close with the outstanding challenges for large-scale memristive neural networks. Specific numbers are not reproduced (abstract-only basis; publisher abstract unavailable).", "contributions": ["Review of memristor materials/devices and crossbar integration for computing.", "Coverage of both DL-accelerator use (analog MVM) and SNN use of memristors.", "Identification of integration and computation challenges for large-scale memristive networks."], "claims": [{"claim": "Memristive crossbars perform multiplication via Ohm's law and summation via Kirchhoff's current law, storing weights locally as conductance.", "support": "Standard in-memory computing principle described in the review (per publisher summary).", "loc": "Introduction"}, {"claim": "Integration of large-scale memristive neural networks faces significant challenges both as DL accelerators and as SNN building blocks.", "support": "Semantic Scholar TLDR: 'The challenges in the integration and use in computation of large-scale memristive neural networks are discussed'.", "loc": "Abstract/Summary"}], "results": ["Qualitative review; no quantitative results extracted (abstract-only basis)."], "limitations": ["Full text and abstract not accessed; content summarized from publisher summary and established knowledge of the review.", "Device/materials-oriented; architecture, ADC overhead and compilation aspects are covered only briefly.", "2019 snapshot."], "remarks": "A standard materials-side reference from the UMass group (authors of several 1T1R ReRAM crossbar demonstrations, e.g., Li et al. 2018, Wang et al.). Good for device-level vocabulary and integration issues; for architecture-level mapping and peripherals see Xiao et al. 2020 or Chakraborty et al. 2020.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2019_Xia_MemristiveCrossbarArrays_NatMater.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2019_Xia_MemristiveCrossbarArrays_NatMater.pdf", "priority": 8.51}, {"id": "W2805362231", "short": "IMC with Resistive Switching Devices", "title": "In-memory computing with resistive switching devices", "authors": ["Daniele Ielmini", "H.‐S. Philip Wong"], "year": 2018, "venue": "Nature Electronics", "venue_short": "NatElectron", "venue_full": "Nature Electronics, vol. 1, pp. 333-343 (2018)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41928-018-0092-2", "cites_global": 2281, "cat": "01", "seed": true, "devices": ["ReRAM", "PCM", "MRAM"], "models": ["MLP", "SNN"], "evidence": "survey", "tldr": "Nature Electronics review of in-memory computing with resistive switching devices, covering digital (stateful logic), analogue (crossbar MVM) and stochastic computing schemes, the underlying switching physics, and scaling challenges.", "summary": "The review frames the memory wall of von Neumann machines and in-memory computing as a remedy. It surveys resistive switching devices whose two-terminal structure and resistive switching enable dense, energy-efficient in-memory computation. Computing schemes are organized into digital (logic within memory), analogue (e.g., Ohm's/Kirchhoff's-law matrix-vector multiplication for neural networks and other linear algebra) and stochastic approaches, and the microscopic physical mechanisms behind each are discussed. It closes with challenges for in-memory computing including required scaling characteristics. Being abstract-only here, specific numbers are not reproduced.", "contributions": ["Unified taxonomy of digital, analogue and stochastic in-memory computing with resistive switching devices.", "Links computing schemes to microscopic device physics (switching mechanisms).", "Discussion of challenges and scaling requirements for next-generation in-memory computing."], "claims": [{"claim": "Two-terminal resistive switching devices enable area- and energy-efficient computation directly in memory.", "support": "Abstract: 'the two-terminal structure of the devices, their resistive switching properties, and direct data processing in the memory can enable area- and energy-efficient computation'.", "loc": "Abstract"}, {"claim": "Digital, analogue and stochastic computing schemes have all been proposed with resistive switching devices.", "support": "Abstract: 'We examine the different digital, analogue, and stochastic computing schemes that have been proposed'.", "loc": "Abstract"}, {"claim": "Scaling characteristics remain a key challenge for in-memory computing to deliver next-generation computing.", "support": "Abstract: 'we discuss the challenges in-memory computing faces, including the required scaling characteristics'.", "loc": "Abstract"}], "results": ["Qualitative review; no new quantitative results extracted (abstract-only basis)."], "limitations": ["Full text not accessed; figures/numbers not verified.", "Device- and physics-centric; little detail on architecture-level mapping, ADC cost or compilers.", "2018 snapshot, before large DNN CIM chips."], "remarks": "A canonical citation for the in-memory computing paradigm with RRAM/PCM, often cited together with Sebastian et al. 2020 and Xia & Yang 2019. Its value for a mapping thesis is the broad taxonomy (logic vs analog MVM vs stochastic) and device-physics grounding rather than any architecture guidance.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [{"fid": "F15", "text": "The shared motivation across this literature is the memory wall: data movement between separate processing and memory units is the dominant time and energy cost in von Neumann systems, aggravated by data-centric AI workloads. In-memory computing computes in place inside the array by exploiting device physics; two-terminal resistive switching devices are the favoured substrate.", "grade": "High confidence", "vote": "4 claims merged · 3–0 unanimous", "note": "Nature Electronics 2018 · Nature Nanotechnology 2020"}], "pdf_expected": "01_Surveys_and_Foundations/2018_Ielmini_IMCResistiveSwitchingDevices_NatElectron.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2018_Ielmini_IMCResistiveSwitchingDevices_NatElectron.pdf", "priority": 12.14}, {"id": "W2785141883", "short": "Neuro-Inspired Computing with eNVM", "title": "Neuro-Inspired Computing With Emerging Nonvolatile Memorys", "authors": ["Shimeng Yu"], "year": 2018, "venue": "Proceedings of the IEEE", "venue_short": "ProcIEEE", "venue_full": "Proceedings of the IEEE, vol. 106, no. 2, pp. 260-285 (2018)", "venue_ok": true, "doi": "https://doi.org/10.1109/jproc.2018.2790840", "cites_global": 1168, "cat": "01", "seed": false, "devices": ["PCM", "ReRAM", "FeFET", "Flash"], "models": ["MLP", "CNN", "SNN"], "evidence": "survey", "tldr": "Comprehensive review of emerging-NVM synaptic devices and crossbar arrays for neuro-inspired computing, covering design choices (digital/analog, spiking/non-spiking, online/offline training), required device properties, array architectures and NeuroSim-style device-to-system evaluation.", "summary": "The review motivates moving beyond von Neumann architectures for neural networks and categorizes neuromorphic hardware approaches: digital vs analog, spiking vs non-spiking, and online vs offline training. It argues emerging NVMs are attractive as synapses and lays out the desired synaptic-device characteristics: multilevel states, weight-update nonlinearity and asymmetry, and variation/noise. Representative material systems with analog conductance tuning (PCM, resistive memory, ferroelectric memory, floating-gate transistors) are surveyed. It then introduces crossbar arrays for accelerating weighted-sum and weight-update operations and reviews array-level demonstrations and design/benchmarking considerations; the abstract-only basis means specific numbers are not reproduced here.", "contributions": ["Taxonomy of neuro-inspired hardware design choices (digital vs analog, spiking vs non-spiking, online vs offline training).", "Specification of desired synaptic device properties (multilevel states, update nonlinearity/asymmetry, variation/noise).", "Survey of analog-tunable eNVM synapse candidates: PCM, RRAM, ferroelectric devices, floating-gate transistors.", "Crossbar-array architecture for parallel weighted sum and weight update, with review of array-level progress."], "claims": [{"claim": "Emerging NVMs are attractive for implementing synapses in neural-network hardware.", "support": "Abstract: discusses 'why emerging nonvolatile memory is attractive for implementing the synapses in the neural network'.", "loc": "Abstract"}, {"claim": "Weight-update nonlinearity/asymmetry and variation/noise are key device metrics for synaptic devices, alongside multilevel states.", "support": "Abstract lists these as the desired device characteristics discussed.", "loc": "Abstract"}, {"claim": "Crossbar arrays can accelerate both weighted-sum and weight-update operations used in neuro-inspired learning algorithms.", "support": "Abstract: 'we introduce the crossbar array architecture to accelerate the weighted sum and weight update operations'.", "loc": "Abstract"}], "results": ["Qualitative review; no new quantitative results extracted (abstract-only basis)."], "limitations": ["Full text not accessed; specific benchmarks and numbers not verified.", "2018 snapshot: predates large-scale CIM macros and Transformer workloads.", "Training-centric emphasis (update nonlinearity/asymmetry) is less relevant for inference-only deployment."], "remarks": "One of the most cited early device-to-system reviews from the Yu group, widely used as the reference for synaptic-device requirements (nonlinearity, asymmetry, number of states) that later NeuroSim benchmarks quantify. It is a good entry point for training-on-crossbar device specs, but for inference mapping onto crossbars the later Yu reviews (TCSI 2021, CASMag 2021) and Sebastian et al. 2020 are more current.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "This comprehensive review summarizes state of the art, challenges, and prospects of the neuro-inspired computing with emerging nonvolatile memory devices. First, we discuss the demand for developing neuro-inspired architecture beyond today's von-Neumann architecture. Second, we summarize the various approaches to designing the neuromorphic hardware (digital versus analog, spiking versus nonspiking, online training versus offline training) and discuss why emerging nonvolatile memory is attractive for implementing the synapses in the neural network. Then, we discuss the desired device characteristics of the synaptic devices (e.g., multilevel states, weight update nonlinearity/asymmetry, variation/noise), and survey a few representative material systems and device prototypes reported in the literature that show the analog conductance tuning. These candidates include phase change memory, resistive memory, ferroelectric memory, floating-gate transistors, etc. Next, we introduce the crossbar array architecture to accelerate the weighted sum and weight update operations that are commonly used in the neuro-inspired machine learning algorithms, and review the recent progresses of array-level experimental demonstrations for pattern recognition tasks. In addition, we discuss the peripheral neuron circuit design issues and present a device-circuit-algorithm codesign methodology to evaluate the impact of nonideal device effects on the system-level performance (e.g., learning accuracy). Finally, we give an outlook on the customization of the learning algorithms for efficient hardware implementation.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2018_Yu_NeuroInspiredComputingENVM_ProcIEEE.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2018_Yu_NeuroInspiredComputingENVM_ProcIEEE.pdf", "priority": 9.61}, {"id": "W2765081478", "short": "Mixed-Precision In-Memory Computing", "title": "Mixed-precision in-memory computing", "authors": ["Manuel Le Gallo", "Abu Sebastian", "Roland Mathis", "Matteo Manica", "Heiner Giefers", "Tomáš Tůma", "Costas Bekas", "Alessandro Curioni", "Evangelos S. Eleftheriou"], "year": 2018, "venue": "Nature Electronics", "venue_short": "NatElectron", "venue_full": "Nature Electronics, vol. 1, pp. 246-253 (2018)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41928-018-0054-8", "cites_global": 481, "cat": "01", "seed": false, "devices": ["PCM"], "models": ["Linear solver (CG/GMRES)"], "evidence": "device-experiment", "tldr": "Introduces mixed-precision in-memory computing, where an imprecise PCM crossbar does the bulk MVMs inside a Krylov inner solver and a digital CPU does high-precision iterative refinement, solving a 5,000-equation dense system with 998,752 PCM devices to arbitrary (machine-limited) accuracy.", "summary": "Analog memristive MVM is too imprecise for scientific computing because of device variability, read noise and drift. The paper pairs a low-precision computational memory unit with a high-precision von Neumann unit: the outer iterative-refinement loop computes residuals r=b-Ax in double precision, while the inner Krylov solver (CG or GMRES) performs its matrix-vector products w=Av in the PCM array where A is stored as conductances. Experiments use an IBM 90-nm prototype chip (512 WL x 2048 BL sub-array of 1M doped-GST PCM devices) programmed with iterative program-and-verify; because the chip only allows serial cell access, element-wise products are done on chip and summation off chip, with K devices averaged per matrix element and a global drift-calibration step. Model covariance matrices up to N=5,000 (banded) and a 40x40 gene-expression covariance matrix (TCGA autophagy genes) are solved to the target tolerance, and the system-level analysis (CPU/GPU as the high-precision unit, crossbar cost assumed negligible) projects 6.8x-24x energy gains over high-precision-only solvers.", "contributions": ["Concept of mixed-precision in-memory computing: low-precision analog MVM inside an inexact inner solver, wrapped by high-precision iterative refinement.", "Experimental demonstration on a ~1M-device PCM prototype chip, including scalar-multiplication error characterization (error s.d. scaling as K^-0.5 when averaging K devices).", "Use of inexact input data (banded matrix in the array, full matrix for residuals) to scale to N=5,000 with 998,752 PCM devices.", "A real-world application (inverse covariance / gene interactome from TCGA RNA data) solved with GMRES as inner solver.", "System-level energy/time analysis vs POWER8 CPU and P100 GPU, and a comparison with a 4-bit FPGA MVM unit."], "claims": [{"claim": "Achievable accuracy is limited only by the high-precision unit, not by the analog memory precision.", "support": "Minimum error for N=500 with tol=1e-15 is ~1.3e-15, limited by machine precision of the high-precision unit.", "loc": "Sec. III"}, {"claim": "Analog PCM multiplication errors are dominated by random (iid-like) perturbations that average out.", "support": "Error distribution standard deviation scales as K^-0.5 with the number of averaged devices K.", "loc": "Sec. II, Fig. 2d"}, {"claim": "The approach converges for large dense systems even with an inexact (banded) matrix in the array.", "support": "N=5,000 with K=8, banded matrix (12 entries each side of diagonal), 998,752 PCM devices; N=500 full matrix converged after 23 iterative refinements.", "loc": "Sec. III, Fig. 3"}, {"claim": "Mixed-precision reduces high-precision work compared with a pure high-precision Krylov solver.", "support": "23 high-precision MVMs needed vs 50 for a single high-precision CG run to the same accuracy (N=5,000).", "loc": "Sec. III"}, {"claim": "Mixed-precision in-memory computing beats CPU- and GPU-only high-precision solvers in energy to solution (upper bound).", "support": "Maximum measured dynamic energy gains of 6.8x (current PCM precision) up to 24x (two orders of magnitude less noise), assuming negligible crossbar cost.", "loc": "Sec. IV, Suppl. Note VII.A"}], "results": ["Solved N=5,000 dense model-covariance linear system using 998,752 PCM devices (K=8, banded) to tol=1e-5.", "N=500 full matrix (K=4, all 1M devices) converged after 23 iterative refinements; convergence shown up to N=10,000 with acceleration methods (Suppl. Note VI).", "Final error ~1.3e-15 (machine precision) for N=500 with tol=1e-15.", "Projected dynamic energy gain 6.8x-24x vs high-precision-only CPU/GPU solvers (upper bound).", "PCM crossbar MVM projected up to 80x lower energy than a 4-bit FPGA MVM of comparable accuracy (Suppl. Note VIII).", "Speed spec: ~10 crossbars of 1000x1000 at <=1 us cycle time needed to reach the upper-bound speed."], "limitations": ["No true in-array summation: hardware allowed only serial cell access, so products were done on chip and accumulated off chip; no crossbar IR-drop/ADC effects captured.", "Energy gains assume the computational memory consumes negligible time/energy (explicitly an upper bound).", "Only well-conditioned, diagonally dominant covariance-type matrices of modest size; ill-conditioned problems need higher analog precision.", "Needs K-device averaging per element (4-8 devices), multiplying array cost.", "Not a neural-network workload; relevance to DNN inference is indirect."], "remarks": "A key conceptual paper for IBM's PCM line: it frames analog arrays as approximate engines that are acceptable whenever an outer digital loop can correct errors, the same logic later used for mixed-precision training (Nandakumar et al.) and in hybrid digital/analog accelerator designs. The experimental evidence is real PCM device data but not a true crossbar MVM (accumulation was off chip), and the energy numbers are optimistic bounds. For DNN mapping, its main lessons are drift calibration via global conductance scaling and averaging/multi-device encoding to raise effective precision; Sebastian et al. 2020 (NatNano) and Joshi et al. 2020 build directly on it.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/1701.04279", "abstract": "", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2018_LeGallo_MixedPrecisionInMemoryComputing_NatElectron.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2018_LeGallo_MixedPrecisionInMemoryComputing_NatElectron.pdf", "priority": 8.0}, {"id": "W2896122000", "short": "Analog Computing for Deep Learning", "title": "The Next Generation of Deep Learning Hardware: Analog Computing", "authors": ["Wilfried E. Haensch", "Tayfun Gokmen", "Ruchir Puri"], "year": 2018, "venue": "Proceedings of the IEEE", "venue_short": "ProcIEEE", "venue_full": "Proceedings of the IEEE, vol. 107, no. 1, pp. 108-122 (2019; online 2018)", "venue_ok": true, "doi": "https://doi.org/10.1109/jproc.2018.2871057", "cites_global": 236, "cat": "01", "seed": false, "devices": ["Generic-NVM", "ReRAM", "PCM", "ECRAM"], "models": ["MLP", "CNN"], "evidence": "analytical", "tldr": "IBM perspective arguing that analog crossbar arrays of NVMs can execute DL matrix operations in constant time, and that NVM materials must be re-engineered (away from memory-oriented specs) to meet the requirements of DL training.", "summary": "Starting from the GPU's role in DL training, the paper argues that further compute efficiency comes from exploiting the approximate nature of DL: reduced precision in digital and, beyond that, intrinsically noisy analog computing that executes matrix operations in constant time on NVM arrays. It contends that existing NVM materials, optimized for storage, are of limited use for in-memory DL compute. It provides an analysis and design guidelines for how these materials must be re-engineered for optimal DL performance, concluding that the required properties deviate strongly from those of memory applications. The work sits in IBM's resistive processing unit (RPU) line on analog training.", "contributions": ["Positions analog in-memory compute as the next step after reduced-precision digital DL hardware.", "Analysis of how NVM device properties map onto DL (especially training) requirements.", "Design guidelines for re-engineering NVM materials for DL rather than for storage."], "claims": [{"claim": "Analog arrays of NVMs can execute DL matrix operations in constant time.", "support": "Abstract: 'revisit analog computing ... to execute the matrix operations for deep learning in constant time on arrays of nonvolatile memories'.", "loc": "Abstract"}, {"claim": "Current NVM materials are of limited use for in-memory DL compute.", "support": "Abstract: 'current nonvolatile memory materials are of limited use'.", "loc": "Abstract"}, {"claim": "Optimal DL devices deviate strongly from materials used in memory applications.", "support": "Abstract: 'design guidelines ... shows a strong deviation from the materials used in memory applications'.", "loc": "Abstract"}], "results": ["Qualitative/analytical design guidelines; specific device specs not extracted (abstract-only basis)."], "limitations": ["Full text not accessed; quantitative device specs not verified.", "Training-focused requirements (symmetric, many-state updates) are stricter than inference needs.", "Perspective/analysis rather than experimental demonstration."], "remarks": "Useful as IBM's framing of analog AI and device co-design (RPU concept, symmetric update requirement), which motivated later ECRAM and Tiki-Taka work. For inference mapping, its requirements are overly stringent; later IBM papers (e.g., Joshi 2020, Rasch's AIHWKit) show inference is feasible with today's PCM via hardware-aware training.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Initially developed for gaming and 3-D rendering, graphics processing units (GPUs) were recognized to be a good fit to accelerate deep learning training. Its simple mathematical structure can easily be parallelized and can therefore take advantage of GPUs in a natural way. Further progress in compute efficiency for deep learning training can be made by exploiting the more random and approximate nature of deep learning work flows. In the digital space that means to trade off numerical precision for accuracy at the benefit of compute efficiency. It also opens the possibility to revisit analog computing, which is intrinsically noisy, to execute the matrix operations for deep learning in constant time on arrays of nonvolatile memories. To take full advantage of this in-memory compute paradigm, current nonvolatile memory materials are of limited use. A detailed analysis and design guidelines how these materials need to be reengineered for optimal performance in the deep learning space shows a strong deviation from the materials used in memory applications.", "review": [], "pdf_expected": "01_Surveys_and_Foundations/2018_Haensch_AnalogComputingDeepLearning_ProcIEEE.pdf", "analysed": true, "pdf": "01_Surveys_and_Foundations/2018_Haensch_AnalogComputingDeepLearning_ProcIEEE.pdf", "priority": 7.19}, {"id": "W4408245641", "short": "Mixed-Precision Memristor-SRAM CIM Processor", "title": "A mixed-precision memristor and SRAM compute-in-memory AI processor", "authors": ["Win-San Khwa", "Tai-Hao Wen", "Hung-Hsi Hsu", "Wei-Hsing Huang", "Yu‐Chen Chang", "Ting-Chien Chiu", "Zhao-En Ke", "Yu-Hsiang Chin", "Hua-Jin Wen", "Wei‐Ting Hsu", "Chung‐Chuan Lo", "Ren-Shuo Liu", "Chih-Cheng Hsieh", "Kea‐Tiong Tang", "Mon‐Shu Ho", "Ashwin Sanjay Lele", "Shih-Hsin Teng", "Chung-Cheng Chou", "Yu-Der Chih", "Tsung-Yung Jonathan Chang", "Meng‐Fan Chang"], "year": 2025, "venue": "Nature", "venue_short": "Nature", "venue_full": "Nature", "venue_ok": true, "doi": "https://doi.org/10.1038/s41586-025-08639-2", "cites_global": 68, "cat": "02", "seed": false, "devices": ["Memristor(generic)", "SRAM-analog"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "A fabricated AI processor combines memristor-based analog compute-in-memory with SRAM-based compute-in-memory in a mixed-precision architecture, aiming to pair the high density/non-volatility of memristor CIM with the higher precision and endurance of SRAM CIM on a single measured chip.", "summary": "This paper, from a TSMC/NTHU-affiliated author group with a track record of ReRAM and SRAM compute-in-memory macro publications (e.g., prior ISSCC macros and the related in-set reference 'Fusion of memristor and digital compute-in-memory processing for energy-efficient edge computing'), reports a fabricated AI processor chip that integrates both memristor-based and SRAM-based compute-in-memory (CIM) in a mixed-precision scheme. The general approach in this line of work is to assign lower-precision, high-density, non-volatile weight storage and MAC operations to memristor CIM arrays, while using SRAM CIM for operations or layers that need higher precision, endurance, or reconfigurability, with the combination aimed at improving overall energy efficiency and accuracy trade-offs for edge AI inference relative to single-technology CIM designs. As no abstract or full text was retrievable for this entry, specific quantitative results (TOPS/W, energy efficiency, measured accuracy on benchmarks) cannot be confirmed here and are omitted rather than estimated.", "contributions": ["Presents a fabricated (measured-silicon) AI processor chip combining memristor and SRAM compute-in-memory on one die", "Proposes a mixed-precision CIM architecture that likely splits workloads/precision needs between the two memory technologies", "Builds on the authors' prior memristor/SRAM CIM fusion work (cited in-set as 'Fusion of memristor and digital compute-in-memory processing for energy-efficient edge computing')", "Targets improved energy efficiency and/or accuracy for edge AI inference relative to single-technology CIM accelerators"], "claims": [], "results": [], "limitations": ["No abstract or full text was retrievable for this paper (empty abstract field in metadata; not found via arXiv or other legitimate open-access sources), so this entry is based only on the title, authorship, venue, and the paper's in-set reference list — specific claims, numbers, and methodology could not be verified and are deliberately omitted", "Category/device/model tags are inferred from the title and author group's known prior work, not confirmed from the paper itself"], "remarks": "This entry is unusually thin because neither an abstract nor the full text could be obtained; the title and authorship (overlapping with TSMC/National Tsing Hua University researchers behind prior ReRAM/SRAM CIM macro papers, including the in-set-cited 2024 'Fusion of memristor and digital compute-in-memory' work) strongly suggest a fabricated mixed-precision memristor+SRAM CIM chip for edge AI, but no quantitative results can be responsibly reported without access to the paper. This should be revisited and filled in if the full text or abstract becomes available.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2025_Khwa_MixedPrecisionMemristorSRAMCIM_Nature.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2025_Khwa_MixedPrecisionMemristorSRAMCIM_Nature.pdf", "priority": 7.82}, {"id": "W4394909859", "short": "Memristor-SRAM CIM Fusion", "title": "Fusion of memristor and digital compute-in-memory processing for energy-efficient edge computing", "authors": ["Tai-Hao Wen", "Je-Min Hung", "Wei-Hsing Huang", "Chuan-Jia Jhang", "Yun-Chen Lo", "Hung-Hsi Hsu", "Zhao-En Ke", "Yu-Chiao Chen", "Yu-Hsiang Chin", "Chin-I Su", "Win-San Khwa", "Chung‐Chuan Lo", "Ren-Shuo Liu", "Chih-Cheng Hsieh", "Kea‐Tiong Tang", "Mon‐Shu Ho", "Chung-Cheng Chou", "Yu-Der Chih", "Tsung-Yung Jonathan Chang", "Meng‐Fan Chang"], "year": 2024, "venue": "Science", "venue_short": "Science", "venue_full": "Science", "venue_ok": true, "doi": "https://doi.org/10.1126/science.adf5538", "cites_global": 122, "cat": "02", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "A fabricated AI edge processor fuses memristor (ReRAM) and digital SRAM compute-in-memory on one chip to combine SRAM's accuracy with memristor's energy efficiency and storage density, achieving 392 microsecond wakeup-to-response latency, 77.64 TOPS/W peak energy efficiency, and under 0.5% accuracy loss, plus support for adaptive local (on-chip) training.", "summary": "The paper addresses a core trade-off in AI edge CIM hardware: memristor-based (nonvolatile, resistive) CIM offers high energy efficiency and storage density but suffers accuracy loss from device nonidealities and cannot support on-chip training well due to limited write endurance, whereas digital SRAM-based CIM is accurate and supports training but is volatile and area-hungry. The authors design and fabricate a memristor-SRAM CIM-fusion processor that combines both CIM types on one chip, using the SRAM CIM for high-accuracy, trainable computation and the memristor CIM for high-density, energy-efficient nonvolatile storage/compute, letting the system dynamically exploit each technology's strength. This fusion also enables adaptive local (on-chip) training so the device can personalize to user-specific characteristics and environment after deployment, rather than only running a fixed pretrained model. The fabricated chip is characterized for CIM capacity, wakeup-to-response latency, peak energy efficiency, and accuracy loss relative to a non-fused baseline, demonstrating that memristor CIM technology is mature enough for manufacturable AI edge processors rather than being confined to lab-scale demonstrations.", "contributions": ["Proposes and fabricates a memristor-SRAM CIM-fusion architecture combining nonvolatile ReRAM CIM and digital SRAM CIM on a single AI edge processor chip", "Enables adaptive local (on-chip) training on the fused chip to personalize to user/environment characteristics despite memristor endurance limits, by offloading training-sensitive operations to the SRAM CIM", "Demonstrates high CIM storage capacity alongside short wakeup-to-response latency and high peak energy efficiency on real silicon", "Provides an experimental case for memristor CIM technology having reached manufacturability for real AI edge processors, beyond lab-scale prototypes"], "claims": [{"claim": "The fusion processor achieves a wakeup-to-response latency of 392 microseconds.", "support": "measured chip latency", "loc": "Results (measured chip characterization)"}, {"claim": "The fusion processor achieves a peak energy efficiency of 77.64 TOPS/W.", "support": "measured chip peak energy efficiency", "loc": "Results (measured chip characterization)"}, {"claim": "The fusion scheme keeps accuracy loss below 0.5% relative to a non-fused/ideal baseline.", "support": "measured accuracy-loss figure", "loc": "Results (measured chip characterization)"}, {"claim": "Combining memristor and digital SRAM CIM on one chip can simultaneously deliver the accuracy of SRAM CIM and the energy-efficiency/storage-density of memristor CIM, including supporting adaptive local training that pure memristor CIM cannot due to endurance limits.", "support": "architectural claim validated by the above measured results", "loc": "Abstract / architecture discussion"}], "results": ["392 microsecond wakeup-to-response latency (measured silicon)", "77.64 TOPS/W peak energy efficiency (measured silicon)", "<0.5% accuracy loss relative to baseline (measured silicon)", "High CIM capacity achieved via the fusion scheme (qualitative claim; exact capacity figure not in abstract)"], "limitations": ["Full text not available for this analysis; results above are taken from the abstract only and not independently verified against figures/tables (e.g., exact CIM capacity, benchmark models/datasets used, comparison baselines)", "The abstract does not specify which DNN models/datasets were used to measure accuracy loss, or the workload scale (model size) tested", "Fusing two CIM technologies on one die likely adds design/fabrication complexity and area overhead relative to a single-technology CIM chip; this trade-off is not quantified in the abstract"], "remarks": "A high-profile (Science) measured-silicon demonstration explicitly designed to resolve the memristor-vs-SRAM CIM trade-off by fusing both on one chip rather than picking one, with on-chip adaptive training as a distinguishing capability enabled by routing training-sensitive operations to SRAM CIM. This is strong hardware evidence for heterogeneous (mixed-device) CIM architectures as a practical path to deployable, trainable, energy-efficient edge AI, complementing the pure-ReRAM or pure-digital-CIM accelerators elsewhere in this collection. Because the review here is abstract-only, the specific workloads/benchmarks and the quantitative CIM-capacity numbers should be confirmed from the full Science 2024 paper before citing details beyond the headline latency/efficiency/accuracy figures.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Artificial intelligence (AI) edge devices prefer employing high-capacity nonvolatile compute-in-memory (CIM) to achieve high energy efficiency and rapid wakeup-to-response with sufficient accuracy. Most previous works are based on either memristor-based CIMs, which suffer from accuracy loss and do not support training as a result of limited endurance, or digital static random-access memory (SRAM)-based CIMs, which suffer from large area requirements and volatile storage. We report an AI edge processor that uses a memristor-SRAM CIM-fusion scheme to simultaneously exploit the high accuracy of the digital SRAM CIM and the high energy-efficiency and storage density of the resistive random-access memory memristor CIM. This also enables adaptive local training to accommodate personalized characterization and user environment. The fusion processor achieved high CIM capacity, short wakeup-to-response latency (392 microseconds), high peak energy efficiency (77.64 teraoperations per second per watt), and robust accuracy (<0.5% accuracy loss). This work demonstrates that memristor technology has moved beyond in-lab development stages and now has manufacturability for AI edge processors.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2024_Wen_MemristorSRAMCIMFusion_Science.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2024_Wen_MemristorSRAMCIMFusion_Science.pdf", "priority": 9.27}, {"id": "W4402811198", "short": "CR-CIM", "title": "A 818–4094 TOPS/W Capacitor-Reconfigured Analog CIM for Unified Acceleration of CNNs and Transformers", "authors": ["Kentaro Yoshioka"], "year": 2024, "venue": "IEEE Journal of Solid-State Circuits", "venue_short": "JSSC", "venue_full": "IEEE Journal of Solid-State Circuits (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/jssc.2024.3457898", "cites_global": 27, "cat": "02", "seed": false, "devices": ["Charge/Capacitor", "SRAM-analog"], "models": ["ViT", "CNN"], "evidence": "measured-silicon", "tldr": "A capacitor-reconfiguring charge-domain CIM macro reuses its compute capacitor array as a 10-bit successive-approximation C-DAC, eliminating charge-redistribution signal attenuation and reaching 45-dB SQNR / 31-dB CSNR with 95.8% CIFAR-10 ViT accuracy, and (per the journal extension) a dual CNN/Transformer mode spanning 818-4094 TOPS/W.", "summary": "Analog charge-domain compute-in-memory (CIM) macros have mostly targeted CNNs, where lower compute SNR (CSNR) is tolerable, but Transformers need much higher precision (10-bit-class ADCs) that conventional charge-based CIM cannot reach without large area/power overhead from charge redistribution loss. The author proposes Capacitor-Reconfigured CIM (CR-CIM): the same capacitor array used for charge-domain multiply-accumulate is reconfigured, after computation, into a 10-bit binary-weighted C-DAC that performs successive-approximation ADC conversion in place, so no charge is transferred off-array and no separate large ADC capacitor bank is needed. This roughly halves ADC-related area and doubles the useful signal swing (equivalent to a 2x comparator noise/energy improvement). A software-analog co-design (SAC) technique adaptively applies 6x majority voting to the last SAR comparisons (CSNR boost, CB) only for the Transformer's MLP block, which the authors find needs ~10 dB higher CSNR than the Attention block, trading power/latency for precision only where needed. Fabricated in 65nm CMOS as a 1088x78 array, the chip measures INL < 2 LSB, 45-dB SQNR and 31-dB CSNR (23/14 dB better than prior charge-based CIMs), runs a 12-layer ViT-small on CIFAR-10 at 95.8% top-1 accuracy (vs. 96.8% ideal) with the SAC+bit-precision scheme giving a 2.1x Transformer inference-efficiency improvement, and reports 818 TOPS/W peak power efficiency in this configuration; the extended journal version adds a dual-mode bit-parallel/8-bit-ADC CNN path reaching up to 4094 TOPS/W (normalized to 1b x 1b MAC).", "contributions": ["CR-CIM: reconfigures the same capacitor array between charge-domain MAC compute and a 10-bit SAR C-DAC for ADC conversion, saving ~2x area vs. separate compute/ADC capacitor arrays", "Eliminates charge-redistribution signal attenuation by keeping charge stationary within the array, giving a 2x larger signal swing / effective 2x ADC noise improvement", "10T CR-CIM cell with a shared DAC/Reset signal path to minimize per-cell overhead (2.3 um^2 in 65nm, ~2x a 6T SRAM cell)", "Software-analog co-design (SAC): adaptive 6x majority-voting CSNR-boost applied only to the higher-precision-sensitive MLP block of a Transformer, exploiting the ~10dB lower CSNR requirement of the Attention block", "First reported analog-CIM acceleration of a Transformer (ViT) to the authors' knowledge, measured in silicon", "(Journal extension) dual-mode operation switching between bit-parallel/8-bit-ADC (CNN, high efficiency) and bit-serial/10-bit-ADC (Transformer, high precision) in the same macro"], "claims": [{"claim": "CR-CIM achieves substantially higher compute accuracy than prior charge-based CIMs", "support": "measured SQNR 45 dB and CSNR 31 dB, 23 dB and 14 dB better than previously reported charge-based CIMs [refs 4,5]", "loc": "Measurement results section, Fig. 5"}, {"claim": "CR-CIM enables accurate Vision Transformer inference with high power efficiency", "support": "95.8% CIFAR-10 top-1 accuracy with ViT-small (12 layers) vs. 96.8% ideal FP inference; 818 TOPS/W power efficiency", "loc": "Measurement results, Fig. 6"}, {"claim": "Software-analog co-design (adaptive majority voting) improves Transformer inference efficiency without full-precision cost everywhere", "support": "adaptively activating CSNR-boost (6x majority voting, +5.5dB CSNR, 1.9x power / 2.5x latency overhead when active) based on running block improves inference efficiency by up to 2.1x", "loc": "Fig. 4 discussion"}, {"claim": "CR-CIM's accuracy-normalized figures of merit beat prior analog CIM works", "support": "SQNR-FoM and CSNR-FoM (TOPS/W x 2^(SQNR or CSNR bits)) are 2.3x and 1.5x higher than previous works, respectively", "loc": "Fig. 6 performance summary"}], "results": ["Measured INL error <2 LSB for 10-bit readout; SQNR 45 dB, CSNR 31 dB (23 dB / 14 dB better than prior charge-based CIMs)", "CIFAR-10 accuracy with ViT-small: 95.8% (CR-CIM, SAC-optimized) vs. 96.8% ideal; 92.4%/91.1% for alternative configurations without full SAC", "818 TOPS/W power efficiency (single-mode, Transformer-capable configuration); journal-level dual-mode design reaches up to 4094 TOPS/W peak (CNN mode, normalized to 1b x 1b MAC) per the published abstract", "1088x78 array fabricated in 65nm CMOS; CR-CIM cell area 2.3 um^2 (~2x a 6T SRAM cell); SAC gives 2.1x Transformer inference-efficiency improvement; FoM improvements of 2.3x (SQNR) and 1.5x (CSNR) over prior analog CIMs"], "limitations": ["Full text available for this analysis is the IEEE VLSI Symposium 2024 conference precursor paper (818 TOPS/W, single ViT demonstration); the cited JSSC journal article is an extended version adding the dual CNN/Transformer mode (up to 4094 TOPS/W), which is summarized here from the abstract rather than verified against full journal text", "Demonstrated only on a single, relatively small ViT-small model on CIFAR-10 (32x32 images, 10 classes), not larger-scale vision/language transformers", "Attention layer uses lower 4-bit input/weight precision without CSNR boost, which may limit generality to tasks more sensitive to attention precision", "Area/power savings depend on the specific 65nm process and custom 1.5fF fringe capacitor; scaling to advanced nodes or larger arrays not demonstrated", "Majority-voting CSNR boost adds 1.9x power and 2.5x latency overhead when active, a real trade-off rather than a free improvement"], "remarks": "A strong measured-silicon result bridging charge-domain CIM circuit design and the precision demands of Transformers, directly relevant to crossbar/CIM mapping for attention and MLP blocks: the key insight that Attention needs materially lower CSNR than the MLP block is a concrete, reusable precision-allocation heuristic for software-hardware co-design. Because the analyzed full text is the shorter VLSI Symposium conference version, the CNN-mode dual-precision extension and the headline 4094 TOPS/W figure (from the JSSC abstract) could not be independently verified against primary journal text, so those numbers should be treated as reported rather than confirmed here. It has already been cited by SRAM-based CIM accuracy-modeling (ASiM) and LLM-mapping (SAGE) 2025 papers as a recent analog-CIM benchmark for Transformer-capable precision.", "basis": "full-text", "pdf_source_url": "", "abstract": "The rapid evolution of machine learning has led to the emergence of diverse neural network architectures, such as CNNs, Transformers, and their hybrid models, each with unique computational precision requirements. Transformers, in particular, demand higher precision compared to CNNs. Existing analog compute-in-memory (ACIM) solutions primarily cater to CNNs and struggle to achieve the high precision necessary for Transformers, despite their promise in addressing the memory bottleneck. To bridge this gap, we propose a capacitor-reconfigured CIM (CR-CIM) macro that introduces dual-mode operation, dynamically switching between high-precision and high-efficiency modes based on the active DNN layer. In the CNN mode, the CR-CIM employs bit-parallel computation and an 8-bit ADC to maximize power efficiency, exploiting the inherent error tolerance of CNNs. In contrast, for the Transformer mode, the CR-CIM switches to bit-serial computation and a 10-bit ADC to boost the compute signal-to-noise ratio (CSNR), ensuring the higher precision required by Transformers. This dual-mode functionality of the proposed CR-CIM is enabled by three key technologies: 1) a novel CR-CIM architecture and cell structure; 2) a resource-efficient multi-bit driver for bit-parallel computation; and 3) a software-analog co-design (SAC) strategy for enhanced Transformer computation. Our CR-CIM prototype is the first ACIM design to enable optimized operation for both Transformers and CNNs. CR-CIM achieves 45-dB signal-to-quantization-noise ratio (SQNR) and 31-dB CSNR (8-bit input and 8-bit weight bit-serial MAC) in the Transformer mode and a peak-power efficiency of 4094 TOPS/W (normalized to 1-bit${\\times } 1$-bit MAC) in the CNN mode.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2024_Yoshioka_CRCIM_JSSC.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2024_Yoshioka_CRCIM_JSSC.pdf", "priority": 7.54}, {"id": "W4390576773", "short": "eFlash IMC SoC Toolchain", "title": "An End-to-End In-Memory Computing System Based on a 40-nm eFlash-Based IMC SoC: Circuits, Toolchains, and Systems Co-Design Framework", "authors": ["Tianshuo Bai", "Wanru Mao", "Guangyao Wang", "Hanjie Liu", "Aifei Zhang", "Shihang Fu", "Shuaikai Liu", "Jianchao Hu", "Xitong Yang", "Biao Pan", "Wei W. Xing", "Wang Kang"], "year": 2024, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2024.3349502", "cites_global": 12, "cat": "02", "seed": false, "devices": ["Flash"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "Presents an end-to-end circuit-toolchain-system co-design framework (QAT quantization, operator optimization, and ILP-based mapping) for a 40nm eFlash-based in-memory-computing SoC, validated on real voice-recognition, speech-noise-reduction, and person-detection tasks on fabricated silicon.", "summary": "The paper addresses the practical gap between IMC (in-memory computing) chip technology and usable deployment toolchains for real applications: without efficient toolchains, canonical DNNs cannot be reliably mapped onto IMC chips at production quality. The authors propose a co-designed framework spanning circuit, toolchain, and system layers: (a) an 8-bit hardware-friendly Quantization-Aware Training (QAT) method converting floating-point networks to fixed-point for the eFlash IMC array, (b) an operator optimization technique to raise computing precision when executing models on the IMC chip (addressing array/device nonidealities), and (c) an Integer-Linear-Programming (ILP)-based mapping strategy to improve utilization of the IMC array's computation resources. The framework is evaluated end-to-end on the authors' own fabricated 40nm eFlash-based IMC SoC across three real edge-AI tasks: voice recognition, speech noise reduction, and person detection, demonstrating that the co-design stack delivers competitive accuracy directly on silicon.", "contributions": ["Proposes an integrated circuit + toolchain + system co-design framework targeting a specific fabricated eFlash IMC SoC, rather than a software-only or simulation-only mapping tool", "8-bit hardware-friendly Quantization-Aware Training (QAT) scheme tailored to IMC array fixed-point constraints", "An operator optimization technique to recover computing precision lost to IMC array nonidealities", "An ILP-based mapping strategy to improve utilization of IMC array compute resources", "End-to-end validation across three distinct real applications (voice recognition, speech noise reduction, person detection) on real 40nm eFlash IMC silicon"], "claims": [{"claim": "The proposed QAT + operator-optimization + ILP-mapping toolchain achieves over 94.60% voice recognition accuracy in a quiet environment on the fabricated 40nm eFlash IMC SoC.", "support": "measured accuracy figure", "loc": "Experimental results section"}, {"claim": "Voice recognition accuracy remains at 87.27% under white-noise conditions on the chip.", "support": "measured accuracy figure", "loc": "Experimental results section"}, {"claim": "False recognition rate for voice recognition is below 1 per 24 hours on the fabricated chip.", "support": "measured false-recognition-rate figure", "loc": "Experimental results section"}, {"claim": "The framework improves Perceptual Evaluation of Speech Quality (PESQ) for noise reduction by 21.53%.", "support": "measured PESQ improvement", "loc": "Experimental results section"}, {"claim": "Person detection achieves 97.80% accuracy on the fabricated IMC SoC.", "support": "measured accuracy figure", "loc": "Experimental results section"}], "results": ["Voice recognition: >94.60% accuracy (quiet), 87.27% accuracy (white noise), <1 false recognition per 24 hours, on 40nm eFlash IMC SoC silicon", "Speech noise reduction: 21.53% PESQ improvement", "Person detection: 97.80% accuracy"], "limitations": ["Full text not available for this analysis; results summarized here are taken verbatim from the abstract and not independently verified against tables/figures or compared quantitatively with a floating-point/digital baseline", "Evaluated tasks (voice recognition, speech noise reduction, person detection) are relatively small edge-AI workloads; scalability to larger CNNs/transformers on this eFlash platform is not addressed in the abstract", "Device technology (eFlash) nonidealities (retention, endurance, programming granularity) and their quantitative impact are not detailed in the abstract"], "remarks": "This paper is notable for being an industrial-style, full-stack (circuit+toolchain+system) demonstration on a genuinely fabricated eFlash IMC SoC rather than a pure simulation study, which strengthens its evidentiary value for the thesis's mapping/compilation chapter as a real deployment case study. However, because only the abstract was reviewed, the specific contributions of the ILP-mapping and operator-optimization techniques relative to simpler baselines, and the degree of accuracy loss relative to floating-point models, could not be assessed and should be checked in the full TCAD 2024 text before being cited in detail.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Despite its promising potential for Artificial Intelligence (AI) applications, current In-Memory Computing (IMC) technology faces a variety of challenges before mass production. One of the major challenges we face is the absence of efficient toolchains for deploying canonical networks on IMC chips. To address this issue, we propose a co-designed framework that integrates circuit, toolchain, and system elements specifically for IMC. More specifically, our framework consists of several key techniques to improve the key performance including (a) an 8-bit hardware-friendly Quantization-Aware Training (QAT) approach to quantify the deep learning network from floating-point data to fixed-point data, (b) a novel operator optimization technique to increase the computing precision when running the algorithm models on the IMC chips, and (c) an efficient mapping strategy based on the Integer Linear Programming (ILP) approach to improve the computation resource utilization of the IMC array. We assess our method on our 40nm eFlash-based IMC SoC chip with voice recognition, speech noise reduction, and person detection tasks. Our experimental results show an accuracy over 94.60% in a quiet environment and 87.27% in a white noise environment and a false recognition rate below 1 time per 24 hours for voice recognition, a 21.53% improvement for the Perceptual Evaluation of Speech Quality (PESQ) for noise reduction, and a 97.80% accuracy in person detection.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2024_Bai_eFlashIMCSoC_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.88}, {"id": "W4385896568", "short": "IBM HERMES Chip", "title": "A 64-core mixed-signal in-memory compute chip based on phase-change memory for deep neural network inference", "authors": ["Manuel Le Gallo", "Riduan Khaddam-Aljameh", "Miloš Stanisavljević", "Athanasios Vasilopoulos", "Benedikt Kersting", "Martino Dazzi", "Geethan Karunaratne", "Matthias Brändli", "Abhairaj Singh", "Silvia M. Müller", "Julian Büchel", "Xavier Timoneda", "Vinay Joshi", "Malte J. Rasch", "Urs Egger", "Angelo Garofalo", "Anastasios Petropoulos", "Theodore A. Antonakopoulos", "Kevin W. Brew", "Samuel Choi", "Injo Ok", "Timothy M. Philip", "V. Chan", "Claire Silvestre", "Ishtiaq Ahsan", "Nicole Saulnier", "Vijay Narayanan", "Pier Andrea Francese", "Evangelos C. Eleftheriou", "Abu Sebastian"], "year": 2023, "venue": "Nature Electronics", "venue_short": "NatElectron", "venue_full": "Nature Electronics", "venue_ok": true, "doi": "https://doi.org/10.1038/s41928-023-01010-1", "cites_global": 300, "cat": "02", "seed": true, "devices": ["PCM"], "models": ["CNN", "ResNet", "LSTM/RNN"], "evidence": "measured-silicon", "tldr": "The IBM HERMES Project Chip, a 64-core 14nm CMOS PCM-based AIMC chip with fully on-chip digital activation/LSTM units, runs complete end-to-end ResNet-9 (CIFAR-10), LSTM (PTB) and image-captioning inference entirely on-chip at near-software accuracy, reaching 63.1 TOPS / 9.76 TOPS/W (1-phase) and the highest CIFAR-10 accuracy (92.81%) among comparable multi-core resistive-memory AIMC chips.", "summary": "Prior multi-core AIMC chips either used digital (bit-per-device) weight storage, which limits throughput because few rows can be read at once, or analog (one-device-per-weight) storage, which is denser and allows more parallel rows but suffers accuracy loss from noisy weights and requires per-network recalibration/chip-in-the-loop fine-tuning; none supported all the on-chip digital operations (activation functions, LSTM cell-state math) needed for complete end-to-end inference. The HERMES chip integrates 64 256x256 PCM crossbar cores (4 PCM devices per unit-cell, differential encoding) on a 12mm x 12mm 14nm CMOS die, each core with per-row current-controlled-oscillator (CCO) time-based ADCs calibrated on-chip (gain/offset trim) so that no per-application retuning is needed, plus dedicated digital units (LDPU per core, GDPU slices) implementing ReLU, batch norm, LSTM sigmoid/tanh/cell-state computation, and inter-core data aggregation over an on-chip link network (5-Parallel-Prism topology), so an entire inference workload runs without off-chip intervention. Networks are trained off-chip with hardware-aware noise injection (IBM Analog Hardware Acceleration Kit) before weight mapping. Three full networks are demonstrated on-chip: ResNet-9 on CIFAR-10 (1.87M weights, 40 cores), an LSTM for PTB character prediction (1.3M weights, 26 cores), and an LSTM+dense image-captioning model exercising all 64 cores (4.08M weights). Measured hardware accuracy closely tracks software baselines (92.81% vs. 93.67% CIFAR-10 with temporal drift compensation (TDP); BPC within 0.1 of the 1.336 software baseline on PTB; near-identical BLEU scores for captioning), and the chip achieves a peak MVM throughput of 63.1 TOPS at 9.76 TOPS/W and 1.55 TOPS/mm2 (1-phase mode) or 16.1 TOPS at 2.48 TOPS/W (4-phase, higher-precision mode), with MVM throughput density >15x higher than prior multi-core resistive-memory AIMC chips while achieving the best CIFAR-10 accuracy among them.", "contributions": ["First (at publication) multi-core AIMC chip to perform complete, fully-on-chip end-to-end inference (all weight-layer MVMs plus all activation/LSTM digital post-processing) for non-trivial CNN and LSTM networks, not just the MVM portion", "Analog (4-device-per-weight) PCM storage achieving high weight capacity (>4M weights on-chip) combined with per-row CCO-based time-domain ADCs for fully parallel, low-latency MVM readout", "On-chip ADC calibration circuits that remove nonlinear response without application-specific re-tuning, enabling near-software accuracy across three very different workloads without per-network chip adjustment", "Dedicated per-core (LDPU) and shared (GDPU) digital units implementing batch norm, ReLU, and full LSTM cell-state/gating computation on-chip, plus an on-chip communication fabric (5-Parallel-Prism, 418 links) for multi-core data aggregation", "Demonstrated on three realistic workloads (ResNet-9/CIFAR-10, PTB-char LSTM, Flickr8k image captioning) with measured near-software accuracy and throughput/efficiency benchmarking against prior AIMC chips"], "claims": [{"claim": "The chip achieves near-software-equivalent accuracy on CIFAR-10 with all computation on-chip", "support": "92.81% hardware accuracy with TDP vs. 93.67% software baseline (<1% drop); ODP achieves 92.23%", "loc": "Sec. IV / Fig. 3c"}, {"claim": "The chip achieves near-software-equivalent accuracy on PTB character-level language modeling", "support": "hardware BPC <0.1 higher than software baseline of 1.336; ODP BPC only ~0.02 higher than TDP", "loc": "Sec. IV / Fig. 4c"}, {"claim": "Image-caption generation on-chip matches software BLEU scores when averaged over the test set", "support": "BLEU-n scores essentially identical to software, Fig. 5c", "loc": "Sec. IV / Fig. 5c-d"}, {"claim": "The chip delivers high peak throughput and energy efficiency for 8-bit MVMs", "support": "63.1 TOPS at 9.76 TOPS/W and 1.55 TOPS/mm2 (1-phase); 16.1 TOPS at 2.48 TOPS/W (4-phase)", "loc": "Sec. VI / Table I"}, {"claim": "The chip's MVM throughput density exceeds prior multi-core resistive-memory AIMC chips while achieving the best CIFAR-10 accuracy among them", "support": "measured MVM throughput per area of 400 GOPS/mm2 (4-phase) is >15x higher than previous multi-core resistive-memory AIMC chips, highest CIFAR-10 accuracy of 92.81% among them (Extended Data Table II)", "loc": "Conclusions"}, {"claim": "The accuracy gap from the software baseline is explained almost entirely by weight (conductance) error and digital quantization, not by peripheral circuit nonlinearity", "support": "simulation including only per-core weight error + 8-bit quantization nearly matches experimental accuracy on both ResNet-9 and LSTM-PTB", "loc": "Sec. IV"}], "results": ["63.1 TOPS peak MVM throughput, 9.76 TOPS/W, 1.55 TOPS/mm2 (1-phase read mode, all 64 cores)", "16.1 TOPS, 2.48 TOPS/W (4-phase, higher-precision mode) -- roughly 4x lower due to ~4x higher latency", "CIFAR-10 (ResNet-9, 1.87M weights/40 cores): 92.81% hardware accuracy (TDP) vs. 93.67% software baseline; 92.23% with ODP", "PTB character prediction (LSTM, 1.3M weights/26 cores): hardware BPC <0.1 above 1.336 software baseline", "Image captioning (LSTM+dense, 4.08M weights, all 64 cores): BLEU scores essentially matching software baseline", "Measured MVM throughput density 400 GOPS/mm2 (4-phase), >15x higher than prior multi-core resistive-memory AIMC chips", "Single ResNet-9 layer input processed in 1.52 microseconds / 1.51 microjoules; single LSTM timestep in 1.43 microseconds / 5.24 microjoules"], "limitations": ["Off-chip CNN feature extraction is still used for the image-captioning task (only the LSTM+dense portion runs on-chip)", "Networks are trained off-chip with hardware-aware noise injection before mapping; the chip itself does not perform on-chip training", "PCM conductance drift over time still requires a global drift-compensation/rescaling procedure, and since each device drifts at a slightly different rate, the per-core rescaling is an approximation", "Energy efficiency and throughput density are lower than the SRAM-based accelerator of Jia et al. (ref. 24), though that design needs an off-chip weight buffer whereas HERMES stores the whole model on-chip", "Benchmarks (CIFAR-10 ResNet-9, PTB-char, Flickr8k captioning) are moderate-scale; no large-scale transformer/LLM workload is demonstrated"], "remarks": "This is a landmark measured-silicon result (widely cited, >20 in-set forward citations in this collection including AnalogNAS, the IBM Analog Hardware Acceleration Kit paper, and multiple later transformer/LLM-on-analog works) because it is one of the first PCM-based multi-core chips to demonstrate complete end-to-end inference, including all digital glue logic and LSTM cell-state computation, entirely on-chip at near-software accuracy across three qualitatively different workloads. Its careful decomposition of the accuracy gap (dominated by weight/conductance error and digital quantization, not peripheral nonlinearity) is a methodologically useful result for anyone validating analog-mapping-induced accuracy loss. As a direct successor to the single-core HERMES-Core (ref. 18) and built on PCM programming/compensation techniques from the same IBM group (bit-slicing, diagonal decoding, drift compensation), it anchors much of the subsequent IBM analog-AI software/hardware stack (AnalogNAS, AIHWKit, follow-on heterogeneous mesh and 3D analog-CIM accelerators) referenced by later papers in this collection.", "basis": "full-text", "pdf_source_url": "", "abstract": "", "review": [{"fid": "F2", "text": "Analog CIM has moved past simulation to fabricated, measured multi-core silicon in both PCM and RRAM: IBM's 14 nm chip, IBM's 64-core HERMES chip, and NeuRRAM. HERMES's 400 GOPS/mm² in 4-phase mode is more than 15× higher than previous multi-core resistive-memory AIMC chips.", "grade": "High confidence", "vote": "3–0 on HERMES and NeuRRAM · 2–1 on the 14 nm chip", "note": "The single dissent concerned the scope of “software-equivalent”, not the hardware specifications."}, {"fid": "F3", "text": "Measured on-chip accuracy is close to software but not free, and the penalty grows with model scale — from full software-equivalence on keyword spotting, to <1 pp on ResNet-9, to 1.8 pp on ALBERT/GLUE, to a missed equivalence threshold on a 45M-weight RNN-T.", "grade": "High confidence", "vote": "3–0 on NeuRRAM · 2–1 on HERMES and RNN-T", "note": "Dissents addressed interpretive framing, not the numbers. Caveat: NeuRRAM's “comparable to software” baseline is itself 4-bit quantized."}, {"fid": "F4", "text": "Hardware-aware training — injecting realistic device noise during training or fine-tuning — is the field's dominant and empirically validated mitigation, and it now scales to pre-trained LLMs. On under 1% of pre-training tokens, Phi-3-mini-4k-instruct and Llama-3.2-1B-Instruct retained accuracy comparable to 4-bit-weight / 8-bit-activation quantized baselines under hardware-realistic analog noise — a gap off-the-shelf LLMs cannot close on their own.", "grade": "High confidence", "vote": "3–0 on the LLM result and the 4.4% ALBERT figure", "note": "Analog Foundation Models, NeurIPS 2025 (IBM Zurich / ETH) · ALBERT paper quantifies HWA's own contribution at 4.4% average recovery"}], "pdf_expected": "02_Fabricated_Chips_and_Macros/2023_LeGallo_IBMHERMESChip_NatElectron.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2023_LeGallo_IBMHERMESChip_NatElectron.pdf", "priority": 13.12}, {"id": "W4386100686", "short": "IBM Analog-AI Speech Chip (RNNT)", "title": "An analog-AI chip for energy-efficient speech recognition and transcription", "authors": ["Stefano Ambrogio", "Pritish Narayanan", "Atsuya Okazaki", "Andrea Fasoli", "Charles Mackin", "Kohji Hosokawa", "Akiyo Nomura", "T. Yasuda", "A. Chen", "Alexander M. Friz", "Masatoshi Ishii", "Jose Luquin", "Yasuteru Kohda", "Nicole Saulnier", "Kevin W. Brew", "S. Choi", "Kang Min Ok", "Timothy M. Philip", "V. Chan", "C. Silvestre", "Ishtiaq Ahsan", "Vijay Narayanan", "Hsinyu Tsai", "Geoffrey W. Burr"], "year": 2023, "venue": "Nature", "venue_short": "Nature", "venue_full": "Nature", "venue_ok": true, "doi": "https://doi.org/10.1038/s41586-023-06337-5", "cites_global": 239, "cat": "02", "seed": true, "devices": ["PCM"], "models": ["LSTM/RNN", "MLP"], "evidence": "measured-silicon", "tldr": "A 14nm analog-AI chip with 34 PCM crossbar tiles and a massively parallel 2D-mesh inter-tile routing fabric demonstrates software-equivalent accuracy on a small keyword-spotting network and near-software-equivalent accuracy (9.258% WER, 0.88% from SWeq) on the full-scale MLPerf RNNT speech-transcription model (45M weights, 140M+ PCM devices across 5 chips), reaching up to 12.4 TOPS/W sustained.", "summary": "Analog in-memory computing promises large energy-efficiency gains for matrix-vector multiplication, but prior work had not shown software-equivalent (SWeq) accuracy on models large enough to require many communicating tiles. This paper presents a 14nm inference chip with 34 tiles of 512x2048 PCM crossbars, analog low-power peripheral circuitry (duration/ramp-based ADC via on/off-chip latch pairs, ILP/OLP), and a massively parallel, multi-cast-capable 2D-mesh inter-tile communication network -- the first hardware demonstration of a previously simulation-only heterogeneous mesh architecture. Two workloads are demonstrated end-to-end: a small keyword-spotting (KWS) network achieving fully analog SWeq accuracy (86.14% vs. an 85.88% SWeq threshold) using a novel 'AB' (weight +W/-W split, two-tile) MAC-accuracy-improvement technique, and the much larger MLPerf Datacenter RNNT speech-transcription model (45.3M weights, >140M PCM devices mapped across 142 tiles / 5 chip modules), using per-layer sensitivity analysis to decide which layers need higher-precision treatment (AB method, weight-expansion) versus direct quantized mapping, with the small, WER-sensitive joint-FC layer computed digitally off-chip. A new weight-expansion technique (inserting a random matrix M and its pseudoinverse to add redundant rows with sub-linearly growing aggregate noise) is introduced to rescue the most sensitive layer (Enc-LSTM0). The full RNNT system achieves 9.258% WER (1.81% from the SW FP32 baseline, 0.88% from the SWeq threshold), with measured drift of only +0.4% WER after one week. Chip-level sustained energy efficiency reaches up to 12.4 TOPS/W (chip 4, most densely weight-populated), with an estimated full-system (including projected digital logic) efficiency of 6.94-6.7 TOPS/W, and the weight-expansion-based system is estimated at 546.6 samples/s/W (6.704 TOPS/W), a reported 14x improvement over the best MLPerf-submitted energy efficiency for this task.", "contributions": ["First hardware demonstration of a massively parallel, multi-cast 2D-mesh analog-AI tile-interconnect architecture that had previously only been evaluated in simulation", "Demonstrated fully end-to-end software-equivalent (SWeq) accuracy on a complete analog KWS network using a new 'AB' (differential two-tile) MAC-accuracy technique", "Scaled analog-AI inference to an industry/datacenter-relevant model (MLPerf RNNT, 45M weights) spanning 142 tiles across 5 chips, with per-layer noise-sensitivity analysis guiding where extra accuracy techniques are needed", "Introduced a weight-expansion technique (redundant rows via random matrix + pseudoinverse) that improves SNR sub-linearly in noise while linearly in signal, rescuing the most PCM-noise-sensitive LSTM layer", "Measured full system power/performance breakdown (per-chip TOPS/W, analog-vs-digital operation ratio, drift-induced WER degradation after 1 week) and system-level comparison against MLPerf-submitted energy efficiencies"], "claims": [{"claim": "The chip achieves SWeq accuracy end-to-end on a small keyword-spotting network", "support": "measured KWS accuracy of 86.14%, within the MLPerf SWeq 'iso-accuracy' limit of 85.88% (99% of 86.75% SW baseline)", "loc": "Fig. 3g"}, {"claim": "The full MLPerf RNNT model achieves near-SWeq WER when mapped across 142 analog tiles / 5 chips", "support": "9.258% WER with weight expansion, 1.81% from the 7.452% SW FP32 baseline, 0.88% from the 8.378% SWeq threshold (99% of baseline)", "loc": "Fig. 5b,f / Conclusions"}, {"claim": "PCM conductance drift has only a modest effect on WER over one week", "support": "cumulative WER rises from 9.475% (day 0, original MLPerf weights) to 9.894% after one week of drift, a 0.4% absolute increase", "loc": "Fig. 5c"}, {"claim": "The chip achieves high sustained energy efficiency, up to 12.4 TOPS/W, correlated with on-chip weight density", "support": "chip 4 (densest, 2 PCM/weight) reaches 12.40 TOPS/W sustained; analog tile peak is 20.0 TOPS/W; full system estimated at 6.94 TOPS/W", "loc": "Fig. 6a,c"}, {"claim": "A weight-expansion-based analog-AI system would substantially outperform the best MLPerf-submitted energy efficiency for RNNT", "support": "estimated 546.6 samples/s/W (6.704 TOPS/W) at 9.258% WER, a 14-fold improvement over the best energy efficiency submitted to MLPerf", "loc": "Fig. 6f / Power and system performance"}], "results": ["KWS: 86.14% measured accuracy, within SWeq limit of 85.88% (baseline 86.75%)", "RNNT (5 chips, 142 tiles, 45.3M weights, 140M+ PCM devices): 9.258% WER with weight expansion vs. 7.452% SW FP32 baseline and 8.378% SWeq threshold", "Drift-induced WER degradation: +0.4% absolute after one week (9.475% -> 9.894%, before weight-expansion fix)", "Up to 12.4 TOPS/W chip-sustained performance (chip 4); 20.0 TOPS/W peak at the analog-tile level; ~6.94-6.7 TOPS/W estimated full-system efficiency", "Estimated 546.6 samples/s/W (6.704 TOPS/W) with weight expansion, 14x better than best MLPerf-submitted energy efficiency for this task", "Real-time factor of 8x10^-5 for RNNT audio processing (500 microsecond average query processing time), well below the MLPerf real-time constraint of 1"], "limitations": ["The chip itself contains no on-chip digital compute cores or SRAM; all activation functions, vector-vector operations, and the WER-sensitive joint-FC layer are computed off-chip on a host, so true single-chip end-to-end energy efficiency is only estimated/projected, not directly measured", "MLPerf weights are mapped with no additional hardware-aware retraining for RNNT (direct quantized mapping plus AB/weight-expansion for sensitive layers only), relying on per-layer sensitivity analysis rather than full HWA training", "The RNNT model is simplified relative to state-of-the-art (unidirectional rather than bidirectional LSTMs, greedy rather than beam-search decoding), which the authors note increases WER somewhat", "Drift compensation/robustness is only characterized out to one week, not longer-term retention", "Weight-expansion improves one specific sensitive layer; scaling this approach to many more sensitive layers would increase area/tile overhead proportionally"], "remarks": "This is a landmark large-scale measured-silicon validation (highly cited, 12 in-set forward citations including the AIHWKit paper, ALBERT-on-analog chip demo, and several LLM/transformer analog-CIM mapping papers) because it is the first hardware proof that a simulation-only heterogeneous 2D-mesh analog-AI architecture (Jain et al., W4313251083, cited directly as ref. 20) can scale to a commercially relevant, 45M-parameter speech model while staying within 1% of software-equivalent accuracy. The weight-expansion technique is a clean, quantitatively validated mapping-level trick (trading tile/row count for noise robustness with sub-linear noise growth) directly relevant to anyone doing analog crossbar noise mitigation, and the per-layer WER-sensitivity sweep (Fig. 5a) is a reusable methodology for deciding which layers of a large network need special accuracy treatment when mapped to analog hardware. The honest caveat is that all non-MVM digital computation is off-chip, so the system-level TOPS/W figures are projections rather than fully measured end-to-end numbers.", "basis": "full-text", "pdf_source_url": "", "abstract": "Abstract Models of artificial intelligence (AI) that have billions of parameters can achieve high accuracy across a range of tasks 1,2 , but they exacerbate the poor energy efficiency of conventional general-purpose processors, such as graphics processing units or central processing units. Analog in-memory computing (analog-AI) 3–7 can provide better energy efficiency by performing matrix–vector multiplications in parallel on ‘memory tiles’. However, analog-AI has yet to demonstrate software-equivalent (SW eq ) accuracy on models that require many such tiles and efficient communication of neural-network activations between the tiles. Here we present an analog-AI chip that combines 35 million phase-change memory devices across 34 tiles, massively parallel inter-tile communication and analog, low-power peripheral circuitry that can achieve up to 12.4 tera-operations per second per watt (TOPS/W) chip-sustained performance. We demonstrate fully end-to-end SW eq accuracy for a small keyword-spotting network and near-SW eq accuracy on the much larger MLPerf 8 recurrent neural-network transducer (RNNT), with more than 45 million weights mapped onto more than 140 million phase-change memory devices across five chips.", "review": [{"fid": "F2", "text": "Analog CIM has moved past simulation to fabricated, measured multi-core silicon in both PCM and RRAM: IBM's 14 nm chip, IBM's 64-core HERMES chip, and NeuRRAM. HERMES's 400 GOPS/mm² in 4-phase mode is more than 15× higher than previous multi-core resistive-memory AIMC chips.", "grade": "High confidence", "vote": "3–0 on HERMES and NeuRRAM · 2–1 on the 14 nm chip", "note": "The single dissent concerned the scope of “software-equivalent”, not the hardware specifications."}, {"fid": "F3", "text": "Measured on-chip accuracy is close to software but not free, and the penalty grows with model scale — from full software-equivalence on keyword spotting, to <1 pp on ResNet-9, to 1.8 pp on ALBERT/GLUE, to a missed equivalence threshold on a 45M-weight RNN-T.", "grade": "High confidence", "vote": "3–0 on NeuRRAM · 2–1 on HERMES and RNN-T", "note": "Dissents addressed interpretive framing, not the numbers. Caveat: NeuRRAM's “comparable to software” baseline is itself 4-bit quantized."}], "pdf_expected": "02_Fabricated_Chips_and_Macros/2023_Ambrogio_IBMAnalogAISpeechChip_Nature.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2023_Ambrogio_IBMAnalogAISpeechChip_Nature.pdf", "priority": 12.29}, {"id": "W4379527483", "short": "WH-2T1R RRAM CIM Macro", "title": "A 28-nm RRAM Computing-in-Memory Macro Using Weighted Hybrid 2T1R Cell Array and Reference Subtracting Sense Amplifier for AI Edge Inference", "authors": ["Wang Ye", "Linfang Wang", "Zhidao Zhou", "Junjie An", "Weizeng Li", "Hanghang Gao", "Zhi Li", "Jinshan Yue", "Hongyang Hu", "Xiaoxin Xu", "Jianguo Yang", "Jing Liu", "Dashan Shang", "Feng Zhang", "Jinghui Tian", "Chunmeng Dou", "Qi Liu", "Ming Liu"], "year": 2023, "venue": "IEEE Journal of Solid-State Circuits", "venue_short": "JSSC", "venue_full": "IEEE Journal of Solid-State Circuits", "venue_ok": true, "doi": "https://doi.org/10.1109/jssc.2023.3280357", "cites_global": 61, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "measured-silicon", "tldr": "A 28nm 2T1R RRAM compute-in-memory macro with a weighted hybrid cell array, redundant-sub-array MSB mapping, and a reference-subtracting current sense amplifier achieves 30.34-154.04 TOPS/W silicon-measured MAC efficiency and improves ResNet-18 CIFAR accuracy via its MSB scheme.", "summary": "The paper targets limitations of non-volatile compute-in-memory (nvCIM) macros: restricted input parallelism from parasitics, signal-margin loss from device non-idealities, and costly analog readout circuitry. It proposes a 2T1R RRAM macro with four elements: a macro architecture that decouples the memory and computing data paths; a weighted hybrid 2T1R (WH-2T1R) cell array; a redundant sub-array mapping scheme for the most-significant bit (RSM-MSB) to protect the MSB against variation; and a reference-subtracting current sense amplifier (RS-CSA) to improve readout margin. A test chip was fabricated in a 28nm HKMG logic process with foundry RRAM and silicon-verified, performing linear analog MAC over 32 accumulation channels with 1-bit input, 3-bit weight, 4-bit output. The chip achieves 30.34-154.04 TOPS/W. Using the chip's measured behavior/mapping scheme in evaluation with a ResNet-18 model, the RSM-MSB scheme improves CIFAR-10 and CIFAR-100 inference accuracy by 0.96% and 2.83%, respectively, versus a baseline without the MSB-protection scheme.", "contributions": ["A macro architecture with decoupled memory and computing datapaths to reduce parasitic/IR-drop related degradation of input parallelism", "A weighted hybrid 2T1R (WH-2T1R) cell array design for in-memory MAC", "A redundant sub-array MSB mapping scheme (RSM-MSB) that protects the most significant weight bit from device variation, improving downstream inference accuracy", "A reference-subtracting current sense amplifier (RS-CSA) to improve analog readout margin at lower hardware cost", "Silicon-verified 28nm test chip reporting 30.34-154.04 TOPS/W and quantified ResNet-18 CIFAR-10/100 accuracy gains from the MSB scheme"], "claims": [{"claim": "The 28nm 2T1R RRAM CIM macro achieves 30.34-154.04 TOPS/W energy efficiency", "support": "30.34-154.04 TOPS/W reported for 1-bit input, 3-bit weight, 4-bit output over 32 accumulation channels", "loc": "Abstract"}, {"claim": "The RSM-MSB scheme improves ResNet-18 inference accuracy on CIFAR-10 and CIFAR-100", "support": "0.96% accuracy improvement on CIFAR-10 and 2.83% on CIFAR-100", "loc": "Abstract / Evaluation"}], "results": ["30.34-154.04 TOPS/W measured energy efficiency (1-bit IN, 3-bit W, 4-bit O, 32 accumulation channels)", "0.96% ResNet-18/CIFAR-10 accuracy improvement from RSM-MSB scheme", "2.83% ResNet-18/CIFAR-100 accuracy improvement from RSM-MSB scheme"], "limitations": ["Analysis based on abstract only (no full text available to this reviewer); architectural/circuit details (array size, ADC precision chain, area, throughput, comparison baselines) could not be independently verified", "ResNet-18 accuracy results appear to be evaluated via simulation/emulation of the mapping scheme using measured device characteristics rather than full end-to-end silicon inference of the whole network (unconfirmed without full text)"], "remarks": "This is a measured-silicon compute-in-memory macro paper reporting strong energy efficiency (up to 154 TOPS/W) for low-precision (1b/3b/4b) MAC, with its main mapping-relevant contribution being the RSM-MSB redundancy scheme that specifically protects the most-significant weight bit from RRAM variability — a concrete, quantified instance of bit-significance-aware mapping for crossbar accuracy. Because only the abstract was available, the claimed efficiency numbers and accuracy deltas should be treated as reported headline figures pending verification against the full paper; no numbers beyond the abstract are given here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Non-volatile computing-in-memory (nvCIM) can potentially meet the ever-increasing demands on improving the energy efficiency (EF) for intelligent edge devices. However, it still suffers from limited input parallelism due to the parasitic effects, signal margin degradation due to device non-idealities, and large hardware cost for analog readout. In this work, we present a two-transistor-one-resistor (2T1R) resistive memory (RRAM) nvCIM macro featuring: 1) a macro structure with decoupled memory and computing data paths; 2) the weighted hybrid 2T1R (WH-2T1R) cell array; 3) the redundant sub-array mapping scheme of the most-significant-bit (RSM-MSB); and 4) reference-subtracting current sense amplifier (RS-CSA). A test-chip is silicon-verified using the 28-nm high-k/metal-gate (HKMG) logic process with foundry-developed RRAM. The test-chip performs linear analog multiply-and-accumulate (MAC) operations over 32 accumulation channels and achieves 30.34–154.04 TOPS/W with 1-bit input (IN), 3-bit weight (W), and 4-bit output (O). Evaluations with the ResNet-18 model show that the MSB-RSM scheme results in 0.96% and 2.83% improvement on CIFAR-10 and CIFAR-100 inference accuracy, respectively.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2023_Ye_WH2T1RRRAMCIM_JSSC.pdf", "analysed": true, "pdf": null, "priority": 6.76}, {"id": "W4292121737", "short": "NeuRRAM", "title": "A compute-in-memory chip based on resistive random-access memory", "authors": ["Weier Wan", "Rajkumar Chinnakonda Kubendran", "Clemens Schaefer", "Sukru Burc Eryilmaz", "Wenqiang Zhang", "Dabin Wu", "Stephen R. Deiss", "Priyanka Raina", "He Qian", "Bin Gao", "Siddharth Joshi", "Huaqiang Wu", "H.‐S. Philip Wong", "Gert Cauwenberghs"], "year": 2022, "venue": "Nature", "venue_short": "Nature", "venue_full": "Nature, vol. 608 (2022)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41586-022-04992-8", "cites_global": 922, "cat": "02", "seed": true, "devices": ["ReRAM"], "models": ["CNN", "ResNet", "LSTM/RNN", "MLP"], "evidence": "measured-silicon", "tldr": "NeuRRAM is a 48-core, 3-million-RRAM-cell compute-in-memory chip with a reconfigurable transposable neurosynaptic array and voltage-mode neuron that simultaneously achieves 1.6-2.3x lower energy-delay product and 7-13x higher computational density than prior RRAM-CIM chips, with measured accuracy within a few percent of 4-bit software models across CNN, ResNet, LSTM and RBM benchmarks.", "summary": "The paper targets the long-standing trade-off in RRAM compute-in-memory chips between energy efficiency, model versatility, and software-comparable accuracy, which prior fully-integrated RRAM-CIM chips had not jointly solved. NeuRRAM co-optimizes across algorithm, architecture, circuit and device levels: a transposable neurosynaptic array (TNSA) lets each core be reconfigured for forward, backward or recurrent dataflow and differential (signed) weight encoding across two RRAM cells per weight; a voltage-mode neuron senses settled bitline/sourceline capacitor voltage (rather than current) to avoid area-hungry current sinks and give single-cycle MVMs with automatic dynamic-range normalization; algorithm-hardware co-design uses Gaussian noise injection during training (matched to measured RRAM conductance-relaxation statistics) plus chip-in-the-loop progressive layer-wise fine-tuning to recover accuracy. Measured on the 130 nm, 48-core, 3M-RRAM-cell chip across MNIST (7-layer CNN), CIFAR-10 (ResNet-20), Google speech commands (4-cell LSTM) and an MNIST image-recovery RBM task, it attains accuracy within 4-bit-software-model range while achieving 1.6-2.3x lower EDP and 7-13x higher computational density (throughput per million RRAM cells) than previously reported state-of-the-art RRAM-CIM chips, despite an older process node.", "contributions": ["Transposable neurosynaptic array (TNSA) architecture enabling reconfigurable forward/backward/recurrent dataflow directions on the same RRAM cores", "Voltage-mode (charge-sensing) neuron circuit that avoids current-mode ADC/current-sink bottlenecks, giving variable-precision, single-cycle MVM with automatic output dynamic-range normalization", "Noise-injection training matched to measured RRAM conductance-relaxation statistics plus write-verify programming, enabling 4-bit-equivalent accuracy with only 2 RRAM cells per weight (2x denser than 1-cell-per-bit schemes)", "Chip-in-the-loop progressive layer-wise fine-tuning that corrects nonlinear non-idealities (e.g., IR drop) without requiring RRAM reprogramming", "Measured demonstration across 4 diverse edge-AI tasks (CNN/ResNet image classification, LSTM speech recognition, RBM image recovery) on one 48-core chip, matching MLPerf-Tiny-class task complexity"], "claims": [{"claim": "NeuRRAM achieves 1.6x-2.3x lower energy-delay product than previous state-of-the-art RRAM-based CIM chips across various bit-precisions despite an older technology node.", "support": "'the NeuRRAM chip achieves 1.6-times to 2.3-times lower EDP ... at various MVM input and output bit-precisions than previous state-of-the-art RRAM-based CIM chips, despite being fabricated at an older technology node'", "loc": "Main text, 'Efficient voltage-mode neuron circuit' section; Fig. 1d / Extended Data Table 1"}, {"claim": "NeuRRAM achieves 7x-13x higher computational density (throughput per million RRAM cells) than prior RRAM-CIM chips.", "support": "'7-times to 13-times higher computational density (measured by throughput per million of RRAMs)'", "loc": "Main text; Fig. 1d / Extended Data Table 1"}, {"claim": "Gaussian noise injection during training (matched to RRAM conductance spread) dramatically improves noise immunity vs. unmodified training.", "support": "'from a CIFAR-10 classification accuracy of 25.34% without noise injection to 85.99% with noise injection'", "loc": "Fig. 5a"}, {"claim": "Chip-in-the-loop progressive fine-tuning improves CIFAR-10 accuracy beyond standard fine-tuning without extra RRAM reprogramming.", "support": "'The cumulative CIFAR-10 test-set inference accuracy is improved by 1.99% using this technique.'", "loc": "Fig. 5b"}, {"claim": "Across all 4 measured benchmarks, chip accuracy is comparable to software models quantized to 4-bit weights.", "support": "MNIST CNN: 0.98% error; CIFAR-10 ResNet-20: 14.34% error (83.67% measured accuracy vs 87.03% software 4-bit baseline, 3.36 pp gap); Google speech LSTM: 15.34% error; MNIST RBM image recovery: 70% L2-error reduction", "loc": "Fig. 1e, main text"}, {"claim": "NeuRRAM's weight-encoding scheme (full-precision RRAM conductance + noise-aware training) is 2x denser than schemes requiring one RRAM cell per bit.", "support": "'encoding each weight using only two RRAM cells, which is two-times denser than previous studies that require one RRAM cell per bit'", "loc": "Main text, non-idealities section"}], "results": ["48 cores, 3 million RRAM cells on chip, fabricated in 130 nm CMOS + RRAM back-end-of-line process", "1.6x-2.3x lower EDP and 7x-13x higher computational density (throughput/million RRAM) vs prior state-of-the-art RRAM-CIM chips (Fig. 1d)", "MNIST classification (7-layer CNN): 0.98% error rate (99.0% accuracy)", "CIFAR-10 classification (ResNet-20): 83.67% measured accuracy vs 87.03% for 4-bit software baseline (14.34% error rate, 3.36 pp gap before mitigation)", "Google speech command recognition (4-cell LSTM): 84.7% accuracy (15.34% error rate)", "MNIST image recovery (RBM): 70% reduction in L2 image-reconstruction error vs noisy input", "Projected 2-3 orders of magnitude further EDP improvement when scaling from 130 nm to 7 nm CMOS/RRAM (projection, not measured)"], "limitations": ["Intermediate data buffers and partial-sum accumulators are off-chip (FPGA), not yet integrated on the NeuRRAM chip itself", "Reported peak energy efficiency/EDP numbers assume 100% array utilization and exclude inter-core/NoC data-transfer energy, so end-to-end application-level efficiency will be lower", "CIFAR-10 ResNet-20 accuracy (83.67%) remains 3.36 percentage points below the 4-bit software baseline even after noise-aware training and chip-in-the-loop fine-tuning", "Accuracy gap attributed largely to low-bit (<=4-bit) input/activation quantization; deeper networks show accumulating nonlinear non-idealities (e.g., IR drop) that are harder to fully correct", "7 nm technology-node efficiency projections are analytical extrapolations, not measured silicon", "Benchmarks are relatively small/edge-scale (MNIST, CIFAR-10, speech commands, MNIST RBM); no transformer/LLM-scale workloads"], "remarks": "This is a landmark measured-silicon result (Nature, 2022) combining architecture (TNSA reconfigurable dataflow), circuit (voltage-mode neuron) and algorithm (noise-aware training + chip-in-the-loop fine-tuning) innovations on a single fabricated RRAM-CIM chip, which is rare — most crossbar mapping/accuracy papers rely on simulation. Its chip-in-the-loop fine-tuning and Gaussian noise-injection training are widely cited techniques for hardware-aware training of analog accelerators, and it is heavily cited by later mapping, quantization, and LLM-on-CIM papers (per in_set_cited_by) as the reference point for what a versatile, high-efficiency RRAM chip can achieve. Caveats: reported EDP/throughput numbers are per-MVM peak figures excluding system-level data-movement overhead, and the remaining accuracy gap on deeper CNNs (ResNet-20) shows that mapping larger/deeper models onto real crossbars still faces non-trivial non-ideality challenges even with state-of-the-art mitigation.", "basis": "full-text", "pdf_source_url": "", "abstract": "Abstract Realizing increasingly complex artificial intelligence (AI) functionalities directly on edge devices calls for unprecedented energy efficiency of edge hardware. Compute-in-memory (CIM) based on resistive random-access memory (RRAM) 1 promises to meet such demand by storing AI model weights in dense, analogue and non-volatile RRAM devices, and by performing AI computation directly within RRAM, thus eliminating power-hungry data movement between separate compute and memory 2–5 . Although recent studies have demonstrated in-memory matrix-vector multiplication on fully integrated RRAM-CIM hardware 6–17 , it remains a goal for a RRAM-CIM chip to simultaneously deliver high energy efficiency, versatility to support diverse models and software-comparable accuracy. Although efficiency, versatility and accuracy are all indispensable for broad adoption of the technology, the inter-related trade-offs among them cannot be addressed by isolated improvements on any single abstraction level of the design. Here, by co-optimizing across all hierarchies of the design from algorithms and architecture to circuits and devices, we present NeuRRAM—a RRAM-based CIM chip that simultaneously delivers versatility in reconfiguring CIM cores for diverse model architectures, energy efficiency that is two-times better than previous state-of-the-art RRAM-CIM chips across various computational bit-precisions, and inference accuracy comparable to software models quantized to four-bit weights across various AI tasks, including accuracy of 99.0 percent on MNIST 18 and 85.7 percent on CIFAR-10 19 image classification, 84.7-percent accuracy on Google speech command recognition 20 , and a 70-percent reduction in image-reconstruction error on a Bayesian image-recovery task.", "review": [{"fid": "F2", "text": "Analog CIM has moved past simulation to fabricated, measured multi-core silicon in both PCM and RRAM: IBM's 14 nm chip, IBM's 64-core HERMES chip, and NeuRRAM. HERMES's 400 GOPS/mm² in 4-phase mode is more than 15× higher than previous multi-core resistive-memory AIMC chips.", "grade": "High confidence", "vote": "3–0 on HERMES and NeuRRAM · 2–1 on the 14 nm chip", "note": "The single dissent concerned the scope of “software-equivalent”, not the hardware specifications."}, {"fid": "F3", "text": "Measured on-chip accuracy is close to software but not free, and the penalty grows with model scale — from full software-equivalence on keyword spotting, to <1 pp on ResNet-9, to 1.8 pp on ALBERT/GLUE, to a missed equivalence threshold on a 45M-weight RNN-T.", "grade": "High confidence", "vote": "3–0 on NeuRRAM · 2–1 on HERMES and RNN-T", "note": "Dissents addressed interpretive framing, not the numbers. Caveat: NeuRRAM's “comparable to software” baseline is itself 4-bit quantized."}], "pdf_expected": "02_Fabricated_Chips_and_Macros/2022_Wan_NeuRRAM_Nature.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2022_Wan_NeuRRAM_Nature.pdf", "priority": 13.83}, {"id": "W4210530509", "short": "HERMES-Core", "title": "HERMES-Core—A 1.59-TOPS/mm 2 PCM on 14-nm CMOS In-Memory Compute Core Using 300-ps/LSB Linearized CCO-Based ADCs", "authors": ["Riduan Khaddam-Aljameh", "Miloš Stanisavljević", "Jordi Fornt", "Geethan Karunaratne", "Matthias Brändli", "Feng Liu", "Abhairaj Singh", "Silvia M. Müller", "Urs Egger", "Anastasios Petropoulos", "Theodore A. Antonakopoulos", "Kevin W. Brew", "Samuel Choi", "Injo Ok", "Fee Li Lie", "Nicole Saulnier", "V. Chan", "Ishtiaq Ahsan", "Vijay Narayanan", "S. R. Nandakumar", "Manuel Le Gallo", "Pier Andrea Francese", "Abu Sebastian", "Evangelos S. Eleftheriou"], "year": 2022, "venue": "IEEE Journal of Solid-State Circuits", "venue_short": "JSSC", "venue_full": "IEEE Journal of Solid-State Circuits, vol. 57, no. 4, pp. 1027-1038 (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/jssc.2022.3140414", "cites_global": 140, "cat": "02", "seed": false, "devices": ["PCM"], "models": ["MLP", "ResNet"], "evidence": "measured-silicon", "tldr": "IBM's HERMES core: a 256x256 PCM-on-14nm-CMOS in-memory compute core with 256 pitch-matched linearized CCO-based ADCs and a local digital processing unit. It achieves 1.59 TOPS/mm2 and 10.5 TOPS/W at 1 GHz, with 98.3% MNIST and 85.6% CIFAR-10 (ResNet-9) on two cores.", "summary": "HERMES is a fully parallel analog MVM core: 256x256 8T4R unit cells, where each signed weight uses two PCM devices for G+ and two for G-, with stacked nMOS selectors. Diagonal select routing enables parallel programming, and input signs are handled by bitline polarity so a signed MVM finishes in one step. Each of the 256 columns has its own current-controlled-oscillator ADC at 4-um pitch. A feed-forward compensation that lowers the latch trip point linearizes the CCO beyond 3 GHz (300 ps/LSB). The ripple counter performs shift-and-add, which allows bit-serial inputs. A three-parameter per-ADC calibration (read-voltage offset, gain, nonlinearity) is followed by digital gain/offset equalization in the LDPU (FP16 multiply-add, ReLU, cross-core partial-sum combination, residual add). MVM accuracy against FP32 is 1.94% error std for 8-b PWM inputs, about twice that for bit-serial inputs. With hardware-aware training (weight noise injection), a 2-layer MLP and ResNet-9 are mapped onto two cores. MNIST reaches 98.3% (-0.3%) fully on chip, and CIFAR-10 reaches 85.6% (<3% loss) with pooling in software.", "contributions": ["256x256 8T4R PCM unit-cell array in 14-nm CMOS supporting signed weights/inputs in one MVM step and O(N) parallel programming", "Pitch-matched (4 um) CCO-based current ADC with feed-forward linearization (fCCO >3 GHz, 300 ps/LSB) and in-counter shift-and-add", "Per-ADC calibration procedure (offset, gain, nonlinearity) plus LDPU digital equalization, affine scaling and ReLU", "Statistical MVM-accuracy methodology comparing PWM and bit-serial input modulation", "Two-core DNN demonstrations (MLP/MNIST, ResNet-9/CIFAR-10) using hardware-aware training"], "claims": [{"claim": "Pitch-matched time-based current ADCs make fully parallel O(1) MVM practical by avoiding large integration capacitors and ADC sharing.", "support": "256 CCO-ADCs at 4-um pitch, one per column", "loc": "Sec. III, Conclusion"}, {"claim": "Feed-forward compensation linearizes the CCO at high frequency.", "support": "Max CCO frequency >3 GHz, weight/input INL within +/-1 LSB, 300 ps/LSB", "loc": "Sec. III-A, Fig. 4"}, {"claim": "Analog MVM error is small with multi-bit PWM inputs and worse with bit-serial inputs in this design.", "support": "Error std 1.94% (PWM). Bit-serial error histogram has about 2x the std because only the upper 4 bits remain usable", "loc": "Sec. IV-A, Fig. 7"}, {"claim": "End-to-end DNN inference on PCM cores is near software accuracy.", "support": "MNIST MLP 98.3% vs 98.6% software. ResNet-9 CIFAR-10 85.6% vs 88.4% software", "loc": "Sec. V"}, {"claim": "PCM IMC density is competitive with SRAM IMC despite PCM sitting high in the BEOL.", "support": "1.59 TOPS/mm2, above ReRAM designs [24],[45] and slightly above SRAM+capacitor [44] at 8-b inputs", "loc": "Sec. V-D, Table I"}], "results": ["Peak 1.008 TOPS at 10.5 TOPS/W, 1.59 TOPS/mm2 (1 GHz, 0.8 V)", "MVM error std 1.94% vs FP32 with 8-b PWM inputs (128-ns integration). Bit-serial about 2x worse", "MNIST 2-layer MLP fully on chip: 98.3% (software 98.6%)", "CIFAR-10 ResNet-9 (100,726 params): 85.6% (software 88.4%). Pooling in software, FPGA moves data between layers", "Weight-programming error std 4.8% (MLP) and 5.3% (ResNet-9). Programming convergence 100% and 99.9%", "After calibration, residual ADC gain spread sigma = 7.09% (within +/-21%), equalized digitally in the LDPU"], "limitations": ["Small networks only (2-layer MLP, ResNet-9 with about 100k params) on two cores, with FPGA control and software pooling", "PCM drift is not characterised over time in the inference experiments. Weight-programming error is limited by on-chip ADC read accuracy", "Needs per-ADC calibration and hardware-aware (noise-injection) retraining", "PCM inserted high in the BEOL, so cell density is not representative. Efficiency (10.5 TOPS/W) is modest compared with SRAM CIM"], "remarks": "This is a strong measured-silicon paper that serves as the core building block of IBM's later 64-core PCM chip (Le Gallo et al., Nature Electronics 2023). Its main lessons for mapping models onto crossbars are that the peripheral ADC design, per-column calibration and digital affine post-processing largely determine achievable accuracy, and that layers larger than one tile need digital partial-sum combination across cores. The CIFAR-10 accuracy gap (2.8%) shows that small models are sensitive to programming error, which motivated later work on hardware-aware training (AIHWKit) and larger models.", "basis": "full-text", "pdf_source_url": "https://repository.tudelft.nl/file/File_5db3a1ef-d43a-4262-bd14-05f2242232a4", "abstract": "We present a 256$\\times$256 in-memory compute (IMC) core designed and fabricated in 14-nm CMOS technology with backend-integrated multi-level phase change memory (PCM). It comprises 256 linearized current-controlled oscillator (CCO)-based A/D converters (ADCs) at a compact 4-$\\mu \\text{m}$pitch and a local digital processing unit (LDPU) performing affine scaling and ReLU operations. A frequency-linearization technique for CCO is introduced, which increases the maximum CCO frequency beyond 3 GHz, while ensuring accurate on-chip matrix–vector multiplications (MVMs). Moreover, the design and functionality of the digital ADC calibration procedure is described in detail and the MVM accuracy is quantified. Finally, the measured classification accuracies of deep learning (DL) inference applications on the MNIST and CIFAR-10 datasets, when two IMC cores are employed, are presented. For a performance density of 1.59 TOPS/mm2, a measured energy efficiency of 10.5 TOPS/W, at a main clock frequency of 1 GHz, is achieved.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2022_Khaddam-Aljameh_HERMES-Core_JSSC.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2022_Khaddam-Aljameh_HERMES-Core_JSSC.pdf", "priority": 9.62}, {"id": "W4223592331", "short": "FeTFT Synaptic CIM", "title": "CMOS-compatible compute-in-memory accelerators based on integrated ferroelectric synaptic arrays for convolution neural networks", "authors": ["Min‐Kyu Kim", "Ik‐Jyae Kim", "Jang‐Sik Lee"], "year": 2022, "venue": "Science Advances", "venue_short": "SciAdv", "venue_full": "Science Advances", "venue_ok": true, "doi": "https://doi.org/10.1126/sciadv.abm8537", "cites_global": 109, "cat": "02", "seed": false, "devices": ["FeFET"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "Fabricated CMOS-compatible ferroelectric thin-film-transistor (FeTFT) synaptic crossbar arrays with parallel row/column programming and used the measured device statistics to simulate a VGG-8 CNN, reaching 90.3% CIFAR-10 accuracy versus 91.0% for ideal devices.", "summary": "The paper targets the cross-talk, sneak-path and imprecise programming problems of two-terminal (ReRAM/PCM) synapses in compute-in-memory (CIM) crossbars by building three-terminal ferroelectric synaptic transistors (IZO channel + HfZrOx ferroelectric gate dielectric) that are CMOS-compatible below 400 degC. They fabricate small arrays (4x4 for programming demos, 9x2/9x4 for convolution demos) and demonstrate selective column-wise and row-wise parallel weight updates using program-inhibit pulses to suppress disturb, achieving 64 conductance levels, Gmax/Gmin = 33.1, high update linearity, ~1.3% cycle-to-cycle and ~3.7% device-to-device variation. Using a differential two-column (positive/negative weight) scheme with an op-amp subtractor for signed MAC readout, they perform convolution-based edge/mean/sharpen feature extraction on a 64x64 grayscale image. Finally, they feed the measured device statistics (linearity, state count, Gmax/Gmin, variations) into a NeuroSim-style simulator to evaluate a VGG-8 network on CIFAR-10, obtaining 90.3% accuracy versus a 91.0% ideal-device ceiling.", "contributions": ["CMOS-compatible, sub-400 degC fabrication flow for ferroelectric (HfZrOx/IZO) three-terminal synaptic transistor arrays", "Column-wise and row-wise parallel program/program-inhibit scheme that avoids program disturb across unselected devices sharing a gate line", "Measured synapse-level metrics: 64-level conductance, Gmax/Gmin=33.1, Apot/Adep linearity, ~1.3% cycle-to-cycle and ~3.7% device-to-device variation, ~0.95 I-V linearity, ~4.1% retention drift over 10,000 s", "Differential (signed-weight) convolution demonstration on a 9x2 array performing 4-kernel feature extraction on a 64x64 Lena image via an op-amp subtractor readout", "NeuroSim-based VGG-8/CIFAR-10 simulation using the measured device nonidealities, reaching near-ideal accuracy"], "claims": [{"claim": "Parallel column- and row-wise programming with program-inhibit pulses prevents program disturbance in FeTFT synaptic arrays.", "support": "Device-to-device variation ~3.7% (36 devices), cycle-to-cycle variation ~1.3% (30 cycles), no disturbance observed on unselected devices in repeated program-inhibit tests", "loc": "Results, Fig. 2"}, {"claim": "The measured FeTFT array characteristics support near-ideal CNN inference accuracy.", "support": "VGG-8 on CIFAR-10: 90.3% accuracy using measured device statistics vs 91.0% for ideal synaptic devices (100 epochs)", "loc": "Fig. 4C"}, {"claim": "Convolution can be performed with low energy due to low-conductance FeTFT synapses.", "support": "Estimated ~2 fJ per 3x3 convolution operation (E=V^2*G*t*n, V=0.1V, G~1uS, t=10ns, n=18)", "loc": "Results, convolution section"}, {"claim": "FeTFTs exhibit sufficiently linear I-V behavior across conductance states for accurate VMM.", "support": "I-V linearity ~0.95 (defined as IDL at 0.1V / 2*IDL at 0.05V)", "loc": "Results, fig. S7"}], "results": ["90.3% CIFAR-10 accuracy for VGG-8 CNN simulated with measured FeTFT array statistics vs 91.0% for an ideal-device baseline (100 training epochs)", "64 conductance states, Gmax/Gmin = 33.1, Apot = 0.8139, Adep = 1.1464", "Cycle-to-cycle variation ~1.3% over 30 potentiation/depression cycles; device-to-device variation ~3.7% across 36 FeTFTs", "I-V linearity ~0.95; ~4.1% average conductance drift over 10,000 s retention test with no overlap between states", "Estimated ~2 fJ energy per single 3x3-kernel convolution MAC operation"], "limitations": ["Only small arrays demonstrated (4x4 for parallel-programming demo, 9x2/9x4 for convolution/kernel demos) -- not a full chip or macro with integrated periphery/ADCs", "CNN accuracy is from a device-statistics-driven simulation (NeuroSim-style), not an on-chip, fully integrated large-scale CIM execution of the network", "Incremental pulse programming scheme requires iterative read-verify-like amplitude stepping, which the authors note increases training/programming time and circuit complexity", "No evaluation of line resistance/IR drop, sneak paths at larger array scale, or ADC quantization effects"], "remarks": "A solid device/array-level demonstration that three-terminal FeFETs can sidestep the sneak-path and imprecise-programming issues of two-terminal ReRAM/PCM synapses while giving CMOS-compatible, parallel-programmable, reasonably linear weights. The evidence is credible at small array scale (fabricated and measured, not merely modeled), but the CNN accuracy numbers come from feeding measured single/array-level statistics into a NeuroSim-type simulator rather than from a fully integrated chip, so scaling claims (large arrays, peripheral ADC/driver overhead, IR drop) remain untested. Useful data point for the FeFET device/array column of a broader CIM mapping survey, complementary to ReRAM/PCM-crossbar accelerator work that relies on two-terminal devices.", "basis": "full-text", "pdf_source_url": "", "abstract": "Convolutional neural networks (CNNs) have gained much attention because they can provide superior complex image recognition through convolution operations. Convolution processes require repeated multiplication and accumulation operations, which are difficult tasks for conventional computing systems. Compute-in-memory (CIM) that uses parallel data processing is an ideal device structure for convolution operations. CIM based on two-terminal synaptic devices with a crossbar structure has been developed, but unwanted leakage current paths and the high-power consumption remain as the challenges. Here, we demonstrate integrated ferroelectric thin-film transistor (FeTFT) synaptic arrays that can provide efficient parallel programming and data processing for CNNs by the selective and accurate control of polarization in the ferroelectric layer. In addition, three-terminal FeTFTs can act as both nonvolatile memory and access device, which tackle issues from two-terminal devices. An integrated FeTFT synaptic array with parallel programming capabilities can perform convolution operations to extract image features with a high-recognition accuracy.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2022_Kim_FeTFTSynapticCIM_SciAdv.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2022_Kim_FeTFTSynapticCIM_SciAdv.pdf", "priority": 6.03}, {"id": "W4226111665", "short": "40nm MLC-RRAM CIM Macro", "title": "A 40-nm MLC-RRAM Compute-in-Memory Macro With Sparsity Control, On-Chip Write-Verify, and Temperature-Independent ADC References", "authors": ["Wantong Li", "Xiaoyu Sun", "Shanshi Huang", "Hongwu Jiang", "Shimeng Yu"], "year": 2022, "venue": "IEEE Journal of Solid-State Circuits", "venue_short": "JSSC", "venue_full": "IEEE Journal of Solid-State Circuits (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/jssc.2022.3163197", "cites_global": 77, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "A fabricated 40-nm RRAM compute-in-memory macro combines multi-level-cell (MLC) RRAM, sparsity-aware input control, on-chip write-verify with periodic drift refresh, and temperature-independent on-chip ADC reference generation, reaching 97.8 GOPS/mm2 and 44.5 TOPS/W on a ternary-weight VGG-8 while sustaining 85.8% CIFAR-10 accuracy at 120 degC.", "summary": "Off-chip write-verify and off-chip ADC reference tuning, common in prior RRAM compute-in-memory (CIM) research chips, are impractical for real deployment, and single-level RRAM cells limit density/throughput. This chip integrates: (1) multi-level-cell (MLC) RRAM for higher density and compute throughput; (2) sparsity-aware input control that exploits high DNN activation sparsity; (3) on-chip write-verify circuitry that both speeds up initial weight programming and periodically refreshes cells to counter resistance drift; and (4) on-chip ADC reference generation with column-wise tunability that remains stable across temperature. Fabricated in TSMC 40-nm embedded-RRAM technology, the macro is evaluated on a VGG-8 network with ternary weights, achieving 97.8 GOPS/mm2 and 44.5 TOPS/W peak MAC performance while maintaining 85.8% CIFAR-10 classification accuracy even at 120 degC.", "contributions": ["Multi-level-cell (MLC) RRAM integration into a compute-in-memory macro for improved density and throughput over single-level-cell designs", "Sparsity-aware input control that leverages high DNN activation sparsity for efficiency gains", "On-chip write-verify circuitry that both accelerates initial weight programming and periodically refreshes cells to compensate resistance drift under stress, removing the need for off-chip write-verify", "On-chip, column-wise tunable ADC reference generation that is stable across a wide temperature range, removing the need for off-chip ADC reference tuning", "Full chip fabrication and measurement in TSMC 40-nm embedded-RRAM technology"], "claims": [{"claim": "The macro sustains high classification accuracy even at elevated temperature thanks to on-chip, temperature-independent ADC reference generation and periodic write-verify refresh.", "support": "85.8% CIFAR-10 accuracy maintained at 120 degC", "loc": "Abstract (full text not available)"}, {"claim": "The macro achieves high area- and energy-efficiency for MAC operations.", "support": "97.8 GOPS/mm2 and 44.5 TOPS/W peak performance on VGG-8 with ternary weights", "loc": "Abstract (full text not available)"}], "results": ["97.8 GOPS/mm2 peak macro-level performance for MAC operations", "44.5 TOPS/W peak energy efficiency for MAC operations", "85.8% CIFAR-10 accuracy on a ternary-weight VGG-8 network, maintained at 120 degC", "Fabricated in TSMC 40-nm process with embedded RRAM technology"], "limitations": ["Analysis is abstract-only here (full text not accessible from this machine) -- die area/macro size, array dimensions, exact write-verify/refresh timing overhead, and comparison against other fabricated RRAM-CIM macros are not verifiable without the full text", "Reported accuracy/efficiency figures are for a single network (VGG-8, ternary weights) and dataset (CIFAR-10); generality to deeper networks or other precisions is not established from the abstract"], "remarks": "A solid, fully fabricated measured-silicon RRAM-CIM macro (category 02) from the Shimeng Yu group addressing two practically important gaps in prior work -- the reliance on off-chip write-verify and off-chip ADC reference tuning -- which matters for any real deployment of RRAM CIM chips rather than lab-bench testing. The 120 degC accuracy-retention result is a notable reliability data point for thermal robustness, directly relevant to non-ideality/reliability questions in this collection; it is cited by several later fabricated-macro and transformer-attention CIM papers (e.g., H3DAtten, ROSETTA) as a representative on-chip-calibrated RRAM CIM baseline.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive random access memory (RRAM)-based compute-in-memory (CIM) has shown great potential for accelerating deep neural network (DNN) inference. However, device characteristics, such as low-resistance values, susceptibility to drift, and single-level cells, may limit the capabilities of RRAM-based CIM. In addition, prior works generally used the off-chip write-verify scheme to tighten RRAM resistance distributions and used off-chip analog-to-digital converter (ADC) references for fine-tuning partial sum quantization. Although off-chip techniques are viable for testing purposes, they may be unsuitable for practical applications. In this work, we present an RRAM-CIM macro to accelerate DNN inference. The chip features: 1) multi-level cell (MLC) RRAM for improving compute performance and density; 2) sparsity-aware input control to leverage the high activation sparsity in DNN models; 3) on-chip write-verify to speed up initial weight programming and periodically refresh cells to compensate for resistance drift under stress; and 4) on-chip ADC reference generation that provides column-wise tunability and stability with varying temperatures to guarantee the CIFAR-10 accuracy of 85.8% at 120 °C. The design is fabricated in TSMC 40-nm process with embedded RRAM technology and achieves a macro-level peak performance of 97.8 GOPS/mm2and 44.5 TOPS/W for multiply-and-accumulate (MAC) operations on VGG-8 network with ternary weights.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2022_Li_40nmMLCRRAMCIMMacro_JSSC.pdf", "analysed": true, "pdf": null, "priority": 8.45}, {"id": "W4312799098", "short": "PCM14nm", "title": "Analog-memory-based 14nm Hardware Accelerator for Dense Deep Neural Networks including Transformers", "authors": ["Atsuya Okazaki", "Pritish Narayanan", "Stefano Ambrogio", "Kohji Hosokawa", "Hsinyu Tsai", "Akiyo Nomura", "Takeo Yasuda", "Charles Mackin", "Alexander M. Friz", "Masatoshi Ishii", "Yasuteru Kohda", "Katie Spoon", "An Chen", "Andrea Fasoli", "Malte J. Rasch", "Geoffrey W. Burr"], "year": 2022, "venue": "IEEE International Symposium on Circuits and Systems proceedings", "venue_short": "ISCAS", "venue_full": "IEEE International Symposium on Circuits and Systems (ISCAS), 2022", "venue_ok": true, "doi": "https://doi.org/10.1109/iscas48785.2022.9937292", "cites_global": 6, "cat": "02", "seed": false, "devices": ["PCM"], "models": ["LSTM", "BERT/Transformer"], "evidence": "measured-silicon", "tldr": "14nm chip with multiple 512x512 PCM arrays gives software-equivalent accuracy on MNIST and LSTM using drift/noise compensation, and the paper projects BERT NLP accuracy on an extended version.", "summary": "Describes an IBM 14nm inference chip built from multiple 512x512 PCM arrays performing analog MAC via Ohm/Kirchhoff laws. Compensation techniques counter conductance drift and noise so that MNIST and recurrent LSTM benchmarks reach software-equivalent accuracy. The authors then project accuracy for NLP tasks with BERT mapped onto an extended version of the same architecture. Only the abstract was available, so details of mapping and numbers are not recorded here.", "contributions": ["14nm multi-array PCM analog inference chip", "Drift and noise compensation yielding software-equivalent accuracy on MNIST and LSTM", "Projection of BERT accuracy on an extended architecture"], "claims": [], "results": [], "limitations": ["BERT results are projections, not silicon measurements", "Abstract-only analysis"], "remarks": "Important early step in the IBM analog-AI line toward Transformers, but LM evidence is a projection. Silicon validates only small DNN/LSTM workloads.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Analog non-volatile memory (NVM)-based accelerators for deep neural networks perform high-throughput and energy-efficient multiply-accumulate (MAC) operations (e.g., high TeraOPS/W) by taking advantage of massively parallelized analog MAC operations, implemented with Ohm’s law and Kirchhoff’s current law on array-matrices of resistive devices. While the wide-integer and floating-point operations offered by conventional digital CMOS computing are much more suitable than analog computing for conventional applications that require high accuracy and true reproducibility, deep neural networks can still provide competitive end-to-end results even with modest (e.g., 4-bit) precision in synaptic operations. In this paper, we describe a 14-nm inference chip, comprising multiple 512$\\times$ 512 arrays of Phase Change Memory (PCM) devices, which can deliver software-equivalent inference accuracy for MNIST handwritten-digit recognition and recurrent LSTM benchmarks, by using compensation techniques to finesse analog-memory challenges such as conductance drift and noise. We also project accuracy for Natural Language Processing (NLP) tasks performed with a state-of-art large Transformer-based model, BERT, when mapped onto an extended version of this same fundamental chip architecture.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2022_Okazaki_PCM14nmAnalogAccelerator_ISCAS.pdf", "analysed": true, "slm": true, "lm_models": ["BERT (projected)", "LSTM"], "param_scale": "~110M-340M (BERT, projected)", "slm_note": "14nm PCM chip with 512x512 arrays (true analog MVM) demonstrated on MNIST and LSTM; BERT (~110M-340M scale) accuracy only projected for an extended architecture. LM content is a projection, not measured.", "added": "2026-10 SLM search", "pdf": null, "priority": 8.09}, {"id": "W3164913974", "short": "CAP-RAM", "title": "CAP-RAM: A Charge-Domain In-Memory Computing 6T-SRAM for Accurate and Precision-Programmable CNN Inference", "authors": ["Zhiyu Chen", "Zhanghao Yu", "Qing Jin", "Yan He", "Jingyu Wang", "Sheng Lin", "Dai Li", "Yanzhi Wang", "Kaiyuan Yang"], "year": 2021, "venue": "IEEE Journal of Solid-State Circuits", "venue_short": "JSSC", "venue_full": "IEEE Journal of Solid-State Circuits, vol. 56 (2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/jssc.2021.3056447", "cites_global": 136, "cat": "02", "seed": false, "devices": ["SRAM-analog", "Charge/Capacitor"], "models": ["CNN", "ResNet"], "evidence": "measured-silicon", "tldr": "CAP-RAM: a 65-nm charge-domain 6T-SRAM IMC macro using 8-cell clusters, 4-b bitline-DAC inputs and compact charge-injection SAR ADCs, reaching 98.8% MNIST (pruned LeNet-5) and 89.0% CIFAR-10 (ResNet-20) at 573.4 GOPS and 49.4 TOPS/W.", "summary": "Current-domain SRAM IMC suffers from access-transistor nonlinearity and variation, and charge-domain designs usually need large custom bit cells. CAP-RAM groups eight standard 6T cells with one switch-and-MOM-capacitor MAC unit (semi-parallel clustering). Only one cell per cluster computes at a time, which trades compute parallelism for weight-storage density, so a whole pruned CNN fits in the macro. Multi-bit 4-b inputs are applied as bitline voltages from current-steering DACs (multi-bit analog input instead of bit-serial). Weights use 2's-complement or ternary encodings across +/- slice pairs with differential ADC inputs. A 7-b charge-injection SAR ADC removes the S&H and reference buffers. The 512x128 macro (0.179 mm2) shows near-ideal linearity with two-step digital calibration. Pruned LeNet-5 (95.6% pruned, ADMM-NN) and quantized ResNet-20 are mapped with explicit layer-per-row rules.", "contributions": ["6T-SRAM charge-domain MAC cluster (8 cells share one capacitor MAC circuit) with coupling/charge-injection error cancellation", "Precision-programmable semi-parallel architecture: 8 input bit-widths and 6 weight bit-widths, 2's-complement or ternary encoding", "Charge-injection SAR ADC (429 um2, 6.85 ENOB simulated) without S&H or reference buffers", "Two-step post-silicon calibration (linear fit plus master curve) and a measured error characterisation methodology", "Explicit mapping rules for pruned/quantized CNNs storing whole models on-macro"], "claims": [{"claim": "Current-domain SRAM IMC is inherently nonlinear and variation-prone. Charge-domain IMC is far more linear.", "support": "Simulated 128x128 8T current-domain macro shows about 2-LSB error std (6-b ideal ADC). CAP-RAM measures near-perfect MAC linearity", "loc": "Sec. II-B, Figs. 4-5, 15"}, {"claim": "After calibration, end-to-end analog computing error is bounded.", "support": "Largest linearity error expected <2 LSB across 64 slices on two chips. ADC thermal noise averages 0.35 LSB rms", "loc": "Sec. IV-A/B, Figs. 16, 19"}, {"claim": "Whole compressed CNN models can be stored and run on a single macro at software-level accuracy.", "support": "Pruned LeNet-5 (19,149 params) gives 98.8% MNIST, identical to software (500 test images)", "loc": "Sec. IV-C, Table I"}, {"claim": "CIFAR-10 ResNet-20 runs with small accuracy loss despite a 6-b ADC.", "support": "89.0% accuracy, 1.6% below software baseline, using quantization-aware training", "loc": "Sec. IV-C, Table II"}, {"claim": "CAP-RAM has the best bitwise compute density among compared SRAM IMC designs.", "support": "3.4 TOPS/mm2 (4b-in, 1-2b weights). 27.2 TOPS/mm2 bitwise", "loc": "Sec. IV-D, Table III"}], "results": ["Peak throughput 573.4 GOPS and energy efficiency 49.4 TOPS/W (4-b inputs, binary/ternary weights, 1.2 V, 70 MHz)", "Compute density 3.4 TOPS/mm2 (27.2 TOPS/mm2 bitwise-normalized)", "MNIST 98.8% (pruned LeNet-5, matches software). CIFAR-10 89.0% (ResNet-20, -1.6% vs software)", "Macro area 0.179 mm2. Amortized bit cell about 38% larger than a 6T cell. ADCs 8.2% and DACs 3.6% of area", "Total power 11.62 mW, of which ADCs and shared control take 7.56 mW"], "limitations": ["Only 500 test images used for accuracy measurements", "SRAM (volatile) and charge-domain, not an NVM crossbar", "Clustering lowers parallelism: only one of 8 rows computes per cycle", "Calibration coefficients are fitted per chip from measured data. Accuracy depends on QAT and heavy pruning"], "remarks": "This is a careful, well-measured charge-domain SRAM macro. Its value for crossbar mapping lies in the explicit storage-density versus parallelism knob (cluster size) and in its concrete mapping rules for placing bits and filters across slices and rows. Like PCM/ReRAM chips, it relies on calibration and quantization-aware training to close the accuracy gap. Its ADC analysis (charge sharing into a SAR capacitive DAC loses about 61% of range) is relevant to the ADC-cost discussion in analog CIM generally.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2107.02388", "abstract": "A compact, accurate, and bitwidth-programmable in-memory computing (IMC) static random-access memory (SRAM) macro, named CAP-RAM, is presented for energy-efficient convolutional neural network (CNN) inference. It leverages a novel charge-domain multiply-and-accumulate (MAC) mechanism and circuitry to achieve superior linearity under process variations compared to conventional IMC designs. The adopted semi-parallel architecture efficiently stores filters from multiple CNN layers by sharing eight standard 6T SRAM cells with one charge-domain MAC circuit. Moreover, up to six levels of bit-width of weights with two encoding schemes and eight levels of input activations are supported. A 7-bit charge-injection SAR (ciSAR) analog-to-digital converter (ADC) getting rid of sample and hold (S&H) and input/reference buffers further improves the overall energy efficiency and throughput. A 65-nm prototype validates the excellent linearity and computing accuracy of CAP-RAM. A single 512×128 macro stores a complete pruned and quantized CNN model to achieve 98.8% inference accuracy on the MNIST data set and 89.0% on the CIFAR-10 data set, with a 573.4-giga operations per second (GOPS) peak throughput and a 49.4-tera operations per second (TOPS)/W energy efficiency.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2021_Chen_CAP-RAM_JSSC.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2021_Chen_CAP-RAM_JSSC.pdf", "priority": 7.52}, {"id": "W3195245399", "short": "Fully On-Chip MAC at 14nm", "title": "Fully On-Chip MAC at 14 nm Enabled by Accurate Row-Wise Programming of PCM-Based Weights and Parallel Vector-Transport in Duration-Format", "authors": ["Pritish Narayanan", "Stefano Ambrogio", "Atsuya Okazaki", "Kohji Hosokawa", "Hsinyu Tsai", "Akiyo Nomura", "T. Yasuda", "Charles Mackin", "Scott C. Lewis", "Alexander M. Friz", "Masatoshi Ishii", "Yasuteru Kohda", "H. Mori", "Katherine Spoon", "Riduan Khaddam-Aljameh", "Nicole Saulnier", "M. Bergendahl", "James J. Demarest", "Kevin W. Brew", "V. Chan", "S. Choi", "Kang Min Ok", "Ishtiaq Ahsan", "F. L. Lie", "Wilfried E. Haensch", "Vijay Narayanan", "Geoffrey W. Burr"], "year": 2021, "venue": "IEEE Transactions on Electron Devices", "venue_short": "TED", "venue_full": "IEEE Transactions on Electron Devices, vol. 68, no. 12 (2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/ted.2021.3115993", "cites_global": 85, "cat": "02", "seed": false, "devices": ["PCM"], "models": ["MLP", "LSTM/RNN"], "evidence": "measured-silicon", "tldr": "IBM's 14-nm analog-AI PCM test chip with multiple 512x512 tiles linked by a duration-format 2-D mesh, row-wise closed-loop weight tuning (<3% weight error), a fully on-chip two-layer MNIST network (about 0.6% degradation) and LSTM inference stable over 10,000 characters.", "summary": "Analog NVM inference needs large high-yield arrays, accurate MAC and a way to route activations between arrays for arbitrary DNN topologies. This IBM Almaden test chip in 14-nm CMOS integrates several PCM arrays, each storing 512x512 weights, with four PCM devices per weight. DNN excitations move between tiles as pulse durations on a parallel, reconfigurable 2-D mesh. A closed-loop tuning (CLT) algorithm programs the four conductances of each weight to <3% average error, and row-wise programming circuitry runs CLT on up to 512 weights at once. The chip demonstrates tile-to-tile transport with a fully on-chip two-layer MNIST network (about 0.6% accuracy loss). It also runs an LSTM where activations and vector-vector operations are off-chip, showing no runaway error accumulation over sequences up to 10,000 characters.", "contributions": ["14-nm multi-tile PCM analog-AI chip (512x512 weights per tile, 4 PCM per weight)", "Duration-format activation transport on a reconfigurable 2-D mesh between tiles", "Row-wise parallel closed-loop tuning of PCM weights (<3% weight error, up to 512 weights concurrently)", "Fully on-chip two-layer MNIST and a long-sequence LSTM demonstration"], "claims": [{"claim": "CLT programming of four PCMs per weight gives accurate weight transfer.", "support": "<3% average weight error", "loc": "Abstract"}, {"claim": "Row-wise programming parallelises weight tuning.", "support": "CLT on up to 512 weights concurrently", "loc": "Abstract"}, {"claim": "Multi-tile on-chip inference with duration-format transport keeps accuracy near software.", "support": "Two-layer MNIST fully on chip, accuracy degradation about 0.6%", "loc": "Abstract"}, {"claim": "Analog MAC errors do not accumulate catastrophically in recurrent networks.", "support": "LSTM resilient across sequences up to 10,000 characters (activations off-chip)", "loc": "Abstract"}], "results": ["512x512 weights per PCM array, 14-nm CMOS", "Average weight-programming error <3%", "MNIST two-layer network fully on-chip: about 0.6% accuracy degradation", "LSTM: stable across 10,000-character sequences"], "limitations": ["Abstract-only analysis. Energy/throughput figures were not verified", "The LSTM demo uses off-chip activations and vector-vector ops, so it is not fully on-chip", "Small networks. Duration-format transport latency and energy are not given in the abstract"], "remarks": "This is the device/array-level companion to IBM's 14-nm 34-tile chip line, which led to the Ambrogio et al. Nature 2023 speech chip and the 2025 ALBERT demonstration. Its main contributions for mapping DNNs onto crossbars are the parallel row-wise programming, which makes weight loading of large arrays practical, and the duration-encoded inter-tile communication, which avoids ADC/DAC conversion between layers. HERMES (W4210530509) cites it as one of the first complete PCM IMC systems.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Hardware acceleration of deep learning using analog non-volatile memory (NVM) requires large arrays with high device yield, high accuracy Multiply-ACcumulate (MAC) operations, and routing frameworks for implementing arbitrary deep neural network (DNN) topologies. In this article, we present a 14-nm test-chip for Analog AI inference—it contains multiple arrays of phase change memory (PCM)-devices, each array capable of storing 512$\\times $512 unique DNN weights and executing massively parallel MAC operations at the location of the data. DNN excitations are transported across the chip using a duration representation on a parallel and reconfigurable 2-D mesh. To accurately transfer inference models to the chip, we describe a closed-loop tuning (CLT) algorithm that programs the four PCM conductances in each weight, achieving <3% average weight-error. A row-wise programming scheme and associated circuitry allow us to execute CLT on up to 512 weights concurrently. We show that the test chip can achieve near-software-equivalent accuracy on two different DNNs. We demonstrate tile-to-tile transport with a fully-on-chip two-layer network for MNIST (accuracy degradation ~0.6%) and show resilience to error propagation across long sequences (up to 10 000 characters) with a recurrent long short-term memory (LSTM) network, implementing off-chip activation and vector-vector operations to generate recurrent inputs used in the next on- chip MAC.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2021_Narayanan_FullyOnChipMAC14nmPCM_TED.pdf", "analysed": true, "pdf": null, "priority": 10.03}, {"id": "W3015982917", "short": "Fully Integrated Analog ReRAM CIM Chip", "title": "33.2 A Fully Integrated Analog ReRAM Based 78.4TOPS/W Compute-In-Memory Chip with Fully Parallel MAC Computing", "authors": ["Qi Liu", "Bin Gao", "Peng Yao", "Dong Min Wu", "Junren Chen", "Yachuan Pang", "Wenqiang Zhang", "Yan Biao Liao", "Cheng-Xin Xue", "Wei-Hao Chen", "Jianshi Tang", "Yu Wang", "Meng‐Fan Chang", "He Qian", "Huaqiang Wu"], "year": 2020, "venue": "", "venue_short": "ISSCC", "venue_full": "2020 IEEE International Solid-State Circuits Conference (ISSCC), paper 33.2", "venue_ok": true, "doi": "https://doi.org/10.1109/isscc19947.2020.9062953", "cites_global": 305, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "measured-silicon", "tldr": "A fully integrated 130-nm analog ReRAM CIM chip (158.8 kb) that runs a complete 784-100-10 MLP with fully parallel MAC, reaching 94.4% on MNIST at 77 us/image and 78.4 TOPS/W peak.", "summary": "Earlier NVM CIM demonstrations were single macros with limited parallelism, and no chip integrated a complete network. This Tsinghua work integrates analog ReRAM arrays and their interfaces to run a whole 784-100-10 MLP on one chip. A sign-weighted 2T2R (SW-2T2R) array lowers the accumulated source-line current, which reduces IR drop and allows more rows to compute in parallel. A low-power, resolution-adjustable ADC (LPAR-ADC) trades accuracy against interface power between arrays. The chip achieves 94.4% MNIST accuracy, 77 us/image, and 78.4 TOPS/W peak efficiency.", "contributions": ["First fully integrated analog ReRAM CIM chip running a complete NN model on chip", "Sign-weighted 2T2R array to reduce IR drop and increase computing parallelism", "Resolution-adjustable low-power ADC interface for an accuracy/power trade-off"], "claims": [{"claim": "Reducing accumulated SL current with SW-2T2R mitigates IR drop and enables higher parallelism.", "support": "Design rationale stated in abstract", "loc": "Abstract"}, {"claim": "A complete MLP runs on chip with good accuracy.", "support": "784-100-10 MLP, 94.4% on MNIST", "loc": "Abstract"}, {"claim": "The chip achieves high speed and efficiency.", "support": "77 us/image and 78.4 TOPS/W peak", "loc": "Abstract"}], "results": ["158.8 kb analog ReRAM, 130-nm CMOS", "MNIST 94.4% with a 784-100-10 MLP", "77 us/image inference, 78.4 TOPS/W peak"], "limitations": ["Abstract-only analysis", "Small MLP on MNIST, and 94.4% is well below software accuracy for MNIST MLPs", "Old 130-nm node. Peak efficiency is not system-average"], "remarks": "This is a key step from Yao et al.'s PCB-level multi-array system (Nature 2020) toward the fully integrated ReRAM chips that followed (NeuRRAM; Zhang et al. Science 2023). It shows that IR drop and the ADC/DAC interface, not the device, set the limit on parallelism and efficiency, which is a recurring theme for crossbar mapping. The accuracy gap on MNIST shows how immature analog precision was at this stage.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Non-volatile memory (NVM) based computing-in-memory (CIM) shows significant advantages in handling deep learning tasks for artificial intelligence (AI) applications. To overcome the decreasing cost effectiveness of transistor scaling and the intrinsic inefficiency of data-shuttling in the von-Neumann architecture, CIM is proposed to realize high-speed and low-power system with parallel multiplication accumulation (MAC) computing [1] [2]. However, current demonstrations are mainly based on single macro and present limited computing parallelism. Realizing a fully-integrated CIM chip with a complete neural network model is still missing. The major challenges lie in: (1) The IR drop and transient errors when carrying out MAC operations in non-volatile memory arrays decrease the computing accuracy and further limit the parallelism; (2) The inefficiency of the interface blocks between different arrays due to the power overhead of the A/D and D/A converters (shown in Fig. 33.2.1). To address these challenges, this work proposes: (1) A sign-weighted 2T2R (SW-2T2R) array to reduce IR drop by decreasing the accumulative SL current (ISL), and eventually boost the computing parallelism; (2) a low-power interface design with resolution-adjustable LPAR-ADC to realize flexible tradeoff between system accuracy and power consumption. In this manner, this work implements a fully-integrated 784-100-10 MLP model on an integrated CIM chip with158.8kb analog ReRAMs. This chip realizes high recognition accuracy (94.4%) on MNIST database, high inference speed (77 µs/lmage), and 78.4 TOPS/W peak energy efficiency. The CMOS circuits are fabricated in a 130nm process.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2020_Liu_FullyIntegratedAnalogReRAMCIM_ISSCC.pdf", "analysed": true, "pdf": null, "priority": 9.73}, {"id": "W3015980402", "short": "22nm 2Mb ReRAM CIM Macro", "title": "15.4 A 22nm 2Mb ReRAM Compute-in-Memory Macro with 121-28TOPS/W for Multibit MAC Computing for Tiny AI Edge Devices", "authors": ["Cheng-Xin Xue", "Tsung-Yuan Huang", "Je-Syu Liu", "Ting-Wei Chang", "Hui-Yao Kao", "Jinghong Wang", "Ta-Wei Liu", "Shih-Ying Wei", "Sheng-Po Huang", "Wei-Chen Wei", "Yiren Chen", "Tzu-Hsiang Hsu", "Yen-Kai Chen", "Yun-Chen Lo", "Tai-Hsing Wen", "Chung‐Chuan Lo", "Ren-Shuo Liu", "Chih-Cheng Hsieh", "Kea‐Tiong Tang", "Meng‐Fan Chang"], "year": 2020, "venue": "", "venue_short": "ISSCC", "venue_full": "2020 IEEE International Solid-State Circuits Conference (ISSCC), paper 15.4", "venue_ok": true, "doi": "https://doi.org/10.1109/isscc19947.2020.9063078", "cites_global": 233, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "A 22-nm 2-Mb ReRAM CIM macro, the first 4b-input nvCIM, reaching 9.8-18.3 ns access time and 121.3-28.9 TOPS/W from binary to 4b-in/4b-W/11b-out precision.", "summary": "Multi-bit CNNs need about 4b/4b input/weight precision, but earlier ReRAM nvCIM macros were limited by wide BL-current ranges, few parallel inputs, multi-cycle binary WL inputs, and costly positive/negative split weight mapping. This ISSCC macro proposes BL-IN-OUT multibit computing (BLIOMC), which uses a single WL-on with input-aware multibit BL clamping to keep BL current and its range small. It also uses scrambled 2's-complement weight mapping with input-aware SL biasing and a value combiner to cut array area and current, and a dual-bit small-offset current-mode sense amplifier to reduce reference currents and access time. The fabricated 22-nm 2-Mb macro is presented as the first 4b-input nvCIM.", "contributions": ["BLIOMC scheme with input-aware multibit BL clamping (inputs on BL, single WL on)", "Scrambled 2's-complement weight mapping (S2CWM) with IA-SLVB and S2C value combiner to reduce area overhead and BL current", "Dual-bit small-offset current-mode SA (DbSO-CSA) to reduce reference count and latency", "First 4b-input nonvolatile CIM macro in 22 nm"], "claims": [{"claim": "This is the first nvCIM macro supporting 4b inputs.", "support": "'first 4b-input nvCIM macro'", "loc": "Abstract"}, {"claim": "The macro reaches high efficiency across precisions.", "support": "EF_MAC 121.3-28.9 TOPS/W from binary to 4bIN-4bW-11bOUT", "loc": "Abstract"}, {"claim": "The macro has short access time.", "support": "tAC 9.8-18.3 ns", "loc": "Abstract"}, {"claim": "Positive/negative split weight mapping is area-costly. S2C mapping reduces area overhead and BL current.", "support": "Prior split mapping needs 2x(m-1) cells per signed m-bit weight", "loc": "Abstract"}], "results": ["22-nm 2-Mb ReRAM-CIM macro", "tAC = 9.8-18.3 ns", "121.3 TOPS/W (binary) to 28.9 TOPS/W (4b-in/4b-W/11b-out)"], "limitations": ["Abstract-only analysis. Accuracy on CNN benchmarks was not verified", "Macro-level only. Number of rows activated in parallel is limited, so it is not a fully parallel crossbar MVM", "Efficiency numbers exclude system-level data movement and weight-update cost"], "remarks": "This is the second step in the Chang-group ReRAM-CIM macro line (after Xue ISSCC 2019 at 55 nm), moving to 22 nm and 4b inputs. It is a common comparison point for NVM CIM efficiency (HERMES compares against it, for example), but its bit-serial/partial-row operation differs from the fully parallel analog MVM of PCM/ReRAM crossbar chips, so TOPS/W comparisons need care. The 8b-precision successor appeared at ISSCC 2021 and in Nature Electronics.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Nonvolatile computing-in-memory (nvCIM) can improve the latency (tAC) and energy-efficiency (EFMAC) of tiny AI edge devices performing multiply-and-accumulate (MAC) computing after system wake-up. Prior nvCIMs have proven effective for binary input (IN) and weight (W), and 3b output (OUT) [1], 1-8-1b IN-W-OUT [2], and 2-3-4b IN-W-OUT [3] neural networks; however, the higher precision (4-4b IN-W) for MAC operations is needed for multi-bit CNNs to achieved high-inference accuracy [4]. As Fig.15.4.1 shows, improving the precision of nvCIM macros involves various challenges. (1) A large number of activated WLs provides a wide range of BL current (IBL) resulting in an inaccurate BL-clamping voltage (VBLC); as well as a large (IBL) requiring a large array area due to the need for wide metal lines to support high-current density. (2) Previous “WL = input” approaches suffer from: (a) few parallel inputs (IN#) due to (1), and (b) long (tAC) in multiple cycles of binary WL inputs on 1T1R cells for multibit inputs. (3) Previous positive-negative-split weight-mapping consumes high total (lBL) and area overhead (needing 2x(m-1) cells for a signed m-bit weight) for cell arrays with high-weight precision. (4) Long (tAC) and a large number of reference currents (IREF#) for high-precision outputs. To overcome these challenges, this work proposes: (1) a BL-IN-OUT multibit computing (BLIOMC) scheme using a single WL-on and input-aware multibit BL clamping (IA-MBC) to shorten (lBL) for multibit inputs, increase IN#, and reduce the (lBL) range/size for accurate (VBLC) and a compact array area. (2) Scrambled 2's complement (S2C) weight mapping (S2CWM), input-aware source-line (SL) voltage biasing (IA-SLVB), and an S2C value combiner (S2CVC) to reduce area overhead and lBLin the cell array. (3) A dual-bit small-offset current-mode sense amplifier (DbSO-CSA) to reduce IREF# and tAC. A fabricated 22nm 2Mb ReRAM-CIM macro presents the first 4b-input nvCIM macro, featuring a 9.8-18.3ns tACand an EFMACof 121.3-28.9TOPS/W from binary to 4bIN-4bW-11bOUT compute precisions.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2020_Xue_22nm2MbReRAMCIM_ISSCC.pdf", "analysed": true, "pdf": null, "priority": 9.72}, {"id": "W2899641901", "short": "Programmable IMC Microprocessor", "title": "A Programmable Heterogeneous Microprocessor Based on Bit-Scalable In-Memory Computing", "authors": ["Hongyang Jia", "Hossein Valavi", "Yinqi Tang", "Jintao Zhang", "Naveen Kumar Verma"], "year": 2020, "venue": "IEEE Journal of Solid-State Circuits", "venue_short": "JSSC", "venue_full": "IEEE Journal of Solid-State Circuits, vol. 55, no. 9 (2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/jssc.2020.2987714", "cites_global": 227, "cat": "02", "seed": false, "devices": ["SRAM-analog", "Charge/Capacitor"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "A 65-nm RISC-V microprocessor with a 590-kb charge-domain SRAM in-memory-computing accelerator, bit-parallel/bit-serial multi-bit compute and a software mapping stack, running a 10-layer CNN on CIFAR-10 at software-level accuracy.", "summary": "The paper asks whether high-SNR charge-domain SRAM IMC can be made programmable enough to sit inside a general processor instead of being a fixed-function macro. The chip combines a 590-kb Compute-In-Memory Unit (16 banks, MVM dimension up to 2304x256) with a RISC-V CPU, DMA, 128 kB program/data memory and a configurable near-memory digital datapath. Each bit cell (6T SRAM + 2 PMOS + 1.2 fF MOM capacitor) does a 1-b XNOR/AND multiply. Charge sharing along the column does the accumulation. Multi-bit operands use a bit-parallel/bit-serial scheme: matrix bits go to parallel columns, input bits are applied serially, and each column result is digitized by an 8-b SAR ADC and shift-added near memory, so energy and throughput scale linearly with BA x BX. Interfaces (a word-to-bit reshaping buffer and a sparsity/AND-logic controller) place the accelerator in the CPU memory space, and software libraries map CNN layers onto it. Measured results show column transfer functions close to ideal and CIFAR-10 accuracy at software level for 1-b and 4-b networks.", "contributions": ["Charge-domain SRAM IMC integrated in a RISC-V microprocessor memory space (tight CPU coupling, DMA, reshaping buffer)", "Bit-parallel/bit-serial scheme giving 1-8 b scalable precision with linear (not exponential) cost scaling", "Per-column 8-b SAR ADC plus 8-way multiplexed near-memory datapath for shift-add, scaling, batch-norm and activation", "Input-sparsity-proportional energy via mask bits, and SQNR analysis of the trade-off between ADC range and N", "Software libraries for mapping CNNs, with CIFAR-10 demonstrations at 1-b and 4-b precision"], "claims": [{"claim": "Charge-domain accumulation avoids the variation/nonlinearity of current-domain IMC because capacitance is set by lithographic geometry.", "support": "'capacitance can be precisely controlled in modern VLSI technologies (as it is primarily set by geometric parameters...)'", "loc": "Sec. 1"}, {"claim": "With BP/BS, energy and area-normalized throughput scale linearly with BA x BX rather than exponentially as in purely analog multi-bit schemes.", "support": "Stated design property of the BP/BS scheme (Fig. 4)", "loc": "Sec. 2, Fig. 4"}, {"claim": "An 8-b ADC is sufficient for near-integer SQNR at the 2-6 b operand precisions typical of NNs, even though a column can have up to 2305 output levels.", "support": "Simulated SQNR vs BA, BX and N (N up to 2304); exact integer emulation if N<=255", "loc": "Sec. 3, Fig. 7"}, {"claim": "The 8-b ADC adds only modest overhead per column.", "support": "18%/15% area/energy increase per CIMA column", "loc": "Sec. 2"}, {"claim": "CNN inference reaches software-level accuracy on chip.", "support": "CIFAR-10: 89.3% (1-b) and 92.4% (4-b) at 5.3 / 105.2 uJ/image and 176 / 23 fps (preprint numbers)", "loc": "Abstract, Fig. 11"}], "results": ["IMC macro: 152/297 1b-TOPS/W and 4.7/1.9 1b-TOPS at VDD 1.2/0.85 V (arXiv preprint). The JSSC version reports 192/400 1b-TOPS/W and 0.60/0.24 1b-TOPS/mm2", "CIFAR-10 10-layer CNN: 89.3% (1-b weights/activations) and 92.4% (4-b), matching software simulation", "Energy/throughput per image: 5.31 uJ at 176 fps (1-b) and 105.2 uJ at 23 fps (4-b)", "8-b SAR ADC costs 18%/15% area/energy per column; sparsity masking saves XNOR/broadcast energy (about 50% of CIMA energy)"], "limitations": ["SRAM-based: volatile, so weights must be reloaded (up to about 18k cycles to load A), and it is not an NVM crossbar", "Full text analysed is the 2018 arXiv preprint. Its headline efficiency numbers differ from the final JSSC article", "Only small CNNs on CIFAR-10. Throughput may become I/O-bound as CIMU speed rises (the authors note this)", "Bit-serial input costs Bx cycles, and the 8-b ADC truncates dynamic range when N>255"], "remarks": "This is a standard reference showing that charge-domain analog IMC can be exposed as a programmable accelerator with a software stack, not only a fixed macro. Its architectural template (BP/BS bit-slicing, per-column ADC, near-memory digital post-processing, sparsity masking) reappears in later NVM work. HERMES's in-ADC shift-and-add is positioned against it, and CAP-RAM compares against it on compute density. The evidence is measured silicon, though at 65 nm and on modest CNNs. For NVM crossbar mapping, the main lessons are the digital-periphery and tiling abstractions; the bit cell itself does not transfer.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/1811.04047", "abstract": "In-memory computing (IMC) addresses the cost of accessing data from memory in a manner that introduces a tradeoff between energy/throughput and computation signal-to-noise ratio (SNR). However, low SNR posed a primary restriction to integrating IMC in larger, heterogeneous architectures required for practical workloads due to the challenges with creating robust abstractions necessary for the hardware and software stack. This work exploits recent progress in high-SNR IMC to achieve a programmable heterogeneous microprocessor architecture implemented in 65-nm CMOS and corresponding interfaces to the software that enables mapping of application workloads. The architecture consists of a 590-Kb IMC accelerator, configurable digital near-memory-computing (NMC) accelerator, RISC-V CPU, and other peripherals. To enable programmability, microarchitectural design of the IMC accelerator provides the integration in the standard processor memory space, areaand energy-efficient analog-to-digital conversion for interfacing to NMC, bit-scalable computation (1-8 b), and input-vector sparsity-proportional energy consumption. The IMC accelerator demonstrates excellent matching between computed outputs and idealized software-modeled outputs, at 1b TOPS/W of 192|400 and 1b-TOPS/mm2 of 0.60|0.24 for MAC hardware, at VDDof 1.2|0.85 V, both of which scale directly with the bit precision of the input vector and matrix elements. Software libraries developed for application mapping are used to demonstrate CIFAR-10 image classification with a ten-layer CNN, achieving accuracy, throughput, and energy of 89.3%|92.4%, 176|23 images/s, and 5.31|105.2 μJ/image, for 1|4 b quantization levels.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2020_Jia_ProgrammableIMCMicroprocessor_JSSC.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2020_Jia_ProgrammableIMCMicroprocessor_JSSC.pdf", "priority": 9.18}, {"id": "W3016048022", "short": "Transposable RRAM Neurosynaptic Core", "title": "33.1 A 74 TMACS/W CMOS-RRAM Neurosynaptic Core with Dynamically Reconfigurable Dataflow and In-situ Transposable Weights for Probabilistic Graphical Models", "authors": ["Weier Wan", "Rajkumar Chinnakonda Kubendran", "Sukru Burc Eryilmaz", "Wenqiang Zhang", "Yan Biao Liao", "Dabin Wu", "Stephen R. Deiss", "Bin Gao", "Priyanka Raina", "Siddharth Joshi", "Huaqiang Wu", "Gert Cauwenberghs", "H.‐S. Philip Wong"], "year": 2020, "venue": "", "venue_short": "ISSCC", "venue_full": "2020 IEEE International Solid-State Circuits Conference (ISSCC), paper 33.1", "venue_ok": true, "doi": "https://doi.org/10.1109/isscc19947.2020.9062979", "cites_global": 141, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["PGM", "LSTM/RNN"], "evidence": "measured-silicon", "tldr": "A 130-nm CMOS/RRAM CIM core with runtime-reconfigurable dataflow and in-situ transposable weight access, reaching 74 TMACS/W, the highest reported for RRAM CIM at the time, aimed at probabilistic graphical models.", "summary": "Models such as probabilistic graphical models (e.g., RBMs) and RNNs need both forward and transposed weight access and flexible dataflow. Typical CIM designs either lack this or duplicate ADCs/neurons on both rows and columns. This Stanford/UCSD/Tsinghua core in 130-nm CMOS/RRAM lets the same RRAM array be read in either direction through a reconfigurable dataflow. It uses a voltage-sensing stochastic integrate-and-fire analog neuron that is reused for correlated double sampling, stochastic voltage integration and threshold comparison, which avoids replicated periphery. The design reports 74 TMACS/W computational efficiency. It is a precursor of the NeuRRAM chip.", "contributions": ["Runtime-reconfigurable dataflow with in-situ access to the RRAM array and its transpose", "Voltage-sensing stochastic integrate-and-fire neuron reused for CDS, integration and comparison", "Highest reported RRAM-CIM computational efficiency at the time (74 TMACS/W)"], "claims": [{"claim": "Transposable access can be supported without duplicating ADC/neuron periphery on rows and columns.", "support": "Reconfigurable dataflow plus shared analog neuron", "loc": "Abstract"}, {"claim": "The core has the highest computational energy efficiency reported for RRAM CIM.", "support": "74 TMACS/W", "loc": "Abstract"}], "results": ["130-nm CMOS/RRAM core", "74 TMACS/W computational energy efficiency"], "limitations": ["Abstract-only analysis. Benchmark accuracy and workload details were not verified", "Old 130-nm node and small array scale", "Efficiency counts computation only and excludes system I/O"], "remarks": "This is the direct predecessor of the NeuRRAM chip (Wan et al., Nature 2022). Its transposable neurosynaptic array (TNSA) and voltage-mode neuron ideas went into that chip. For mapping, it shows that bidirectional crossbar reads support backprop-like and PGM sampling dataflows at low periphery cost, which matters for RNNs and on-chip learning.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Many powerful neural network (NN) models such as probabilistic graphical models (PGMs) and recurrent neural networks (RNNs) require flexibility in dataflow and weight access patterns as shown in Fig. 33.1.1 Typically, Compute-In-Memory (CIM) designs do not implement such dataflows or do so by replicating circuits at the memory periphery such as ADCs/neurons along both the rows and columns of the memory array, leading to an overhead in operation. This paper describes a CIM architecture implemented in a 130nm CMOS/RRAM process, that delivers the highest reported computational energy-efficiency of 74 tera-multiply-accumulates per second per watt (TMACS/W) for RRAM-based CIM architectures while simultaneously offering dataflow reconfigurability to address the limitations of previous designs. This is made possible through two key features: 1) a runtime reconfigurable dataflow with in-situ access to RRAM array and its transpose for efficient access to NN weights and 2) a voltage sensing stochastic integrate-and-fire analog neuron (I&F) that is reused for correlated double sampling (CDS), stochastic voltage integration, and threshold comparison.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2020_Wan_TransposableRRAMNeurosynapticCore_ISSCC.pdf", "analysed": true, "pdf": null, "priority": 8.72}, {"id": "W3003821665", "short": "Fully Hardware Memristor CNN", "title": "Fully hardware-implemented memristor convolutional neural network", "authors": ["Peng Yao", "Huaqiang Wu", "Bin Gao", "Jianshi Tang", "Qingtian Zhang", "Wenqiang Zhang", "J. Joshua Yang", "He Qian"], "year": 2020, "venue": "Nature", "venue_short": "Nature", "venue_full": "Nature, vol. 577, pp. 641-646 (2020)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41586-020-1942-4", "cites_global": 2205, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "measured-silicon", "tldr": "A five-layer CNN implemented entirely on multiple memristor (1T1R ReRAM) crossbar arrays, using hybrid training and kernel replication, reaching >96% MNIST accuracy with energy efficiency claimed >100x that of GPUs.", "summary": "The paper (Tsinghua) builds a multi-array memristor system that runs the whole CNN, including the convolutional layers, on crossbars rather than only the fully connected layers. High-yield, uniform 1T1R memristor arrays are integrated into a system of multiple processing elements. A hybrid training scheme transfers ex-situ trained weights and then trains part of the network (the last layer) in situ to compensate for device imperfections and programming errors. To fix the speed mismatch between convolution and FC layers, the same convolution kernels are replicated across several memristor arrays and run in parallel. The system reaches >96% accuracy on MNIST with a five-layer CNN, and the authors estimate energy efficiency more than two orders of magnitude above state-of-the-art GPUs. Simulations suggest the approach scales to ResNet-sized networks.", "contributions": ["Multi-array memristor hardware system running a complete five-layer CNN (conv + FC) on crossbars", "Hybrid training: ex-situ weight transfer plus in-situ training of part of the network to absorb device non-idealities", "Kernel replication across parallel arrays to speed up convolution and balance the pipeline", "System-level energy-efficiency estimate and simulated scalability to residual networks"], "claims": [{"claim": "A complete CNN can run on memristor crossbars with accuracy close to software.", "support": ">96% MNIST accuracy for a five-layer memristor CNN", "loc": "Abstract"}, {"claim": "Hybrid training compensates for device imperfections in the transferred weights.", "support": "In-situ training of part of the network after ex-situ transfer recovers accuracy (as summarised in the abstract)", "loc": "Abstract / main text"}, {"claim": "Replicating kernels across arrays increases convolution throughput.", "support": "Same kernels replicated in different memristor arrays for parallel computing", "loc": "Abstract / main text"}, {"claim": "The memristor CNN is much more energy-efficient than GPUs.", "support": "More than two orders of magnitude higher energy efficiency than state-of-the-art GPUs (estimate)", "loc": "Abstract"}], "results": [">96% accuracy on MNIST with a five-layer CNN run in memristor hardware", "Energy efficiency estimated >100x that of a state-of-the-art GPU", "Simulated scalability to larger networks such as ResNet"], "limitations": ["Abstract-only analysis (no open full text found). Detailed numbers were not verified", "MNIST-scale demonstration. Larger networks (ResNet) are simulation only", "System uses off-array/off-chip peripherals and control. The energy-efficiency comparison is an estimate, not a fully integrated measured chip", "Hybrid in-situ training adds programming cost and needs on-system weight updates"], "remarks": "This is a landmark demonstration and one of the most cited in the field. It showed end-to-end CNN inference on multiple ReRAM arrays and introduced two ideas that recur in mapping work: weight replication for conv/FC pipeline balance, and hybrid (ex-situ plus in-situ) training to absorb non-idealities. The evidence is real hardware, but on MNIST with a PCB-level system. Later work from the same group (Liu ISSCC 2020, then Wan et al. NeuRRAM Nature 2022 and Zhang et al. Science 2023) moved toward fully integrated chips and larger tasks.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2020_Yao_FullyHardwareMemristorCNN_Nature.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2020_Yao_FullyHardwareMemristorCNN_Nature.pdf", "priority": 11.47}, {"id": "W2921329602", "short": "1Mb Multibit ReRAM CIM Macro", "title": "24.1 A 1Mb Multibit ReRAM Computing-In-Memory Macro with 14.6ns Parallel MAC Computing Time for CNN Based AI Edge Processors", "authors": ["Cheng-Xin Xue", "Wei-Hao Chen", "Je-Syu Liu", "Jia-Fang Li", "Wei‐Yu Lin", "Wei-En Lin", "Jinghong Wang", "Wei-Chen Wei", "Ting-Wei Chang", "Tung-Cheng Chang", "Tsung-Yuan Huang", "Hui-Yao Kao", "Shih-Ying Wei", "Yen-Cheng Chiu", "Chun‐Ying Lee", "Chung‐Chuan Lo", "Ya‐Chin King", "Chorng-Jung Lin", "Ren-Shuo Liu", "Chih-Cheng Hsieh", "Kea‐Tiong Tang", "Meng‐Fan Chang"], "year": 2019, "venue": "", "venue_short": "ISSCC", "venue_full": "2019 IEEE International Solid-State Circuits Conference (ISSCC), paper 24.1", "venue_ok": true, "doi": "https://doi.org/10.1109/isscc.2019.8662395", "cites_global": 293, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "A 55-nm 1-Mb ReRAM CIM macro, the first to support multibit input/weight/output MAC for CNNs, with 14.6 ns MAC time (2b-in, 3b-weight, 4b-out) and 53.17 TOPS/W peak in binary mode.", "summary": "Earlier ReRAM CIM macros supported only binary inputs with ternary or binary weights, or 1-b outputs, which limited CNN accuracy. This ISSCC paper targets multibit inputs, weights and MAC outputs in a 55-nm 1-Mb ReRAM macro. Three circuit techniques address the problems of multibit sensing. A serial-input non-weighted product (SINWP) structure trades area, latency and energy. A down-scaling weighted current translator (DSWCT) and positive-negative current subtractor (PN-ISUB) shorten delay and reduce offset and read-path area. A triple-margin small-offset current-mode sense amplifier (TMCSA) tolerates small sensing margins. The macro reports the shortest MAC access time among ReRAM CIMs at the time and the best peak binary-mode efficiency.", "contributions": ["First ReRAM CIM macro supporting CNN operation with multibit input, weight and MAC output", "SINWP serial-input structure for the area/latency/energy trade-off", "DSWCT and PN-ISUB read path for signed multibit current accumulation with small offset", "TMCSA current-mode sense amplifier tolerating small read margins"], "claims": [{"claim": "The macro achieves the shortest CIM MAC access time among existing ReRAM CIMs.", "support": "tMAC = 14.6 ns with 2b-input, 3b-weight, 4b-MAC-OUT", "loc": "Abstract"}, {"claim": "The macro achieves the best peak energy efficiency among ReRAM CIMs in binary mode.", "support": "53.17 TOPS/W (binary mode)", "loc": "Abstract"}, {"claim": "Multibit ReRAM CIM is limited by large BL currents, sense-amplifier offset and small sensing margins, which the proposed read path mitigates.", "support": "Challenges (1)-(3) listed in Fig. 24.1.1 and addressed by SINWP/DSWCT/PN-ISUB/TMCSA", "loc": "Abstract / Fig. 24.1.1"}], "results": ["55-nm 1-Mb ReRAM CIM macro (fabricated)", "tMAC = 14.6 ns at 2b-in/3b-W/4b-out", "Peak 53.17 TOPS/W in binary mode"], "limitations": ["Abstract-only analysis. Network-level accuracy and the full configuration table were not checked", "Low precision (2b inputs, 3b weights, 4b outputs) compared with what high-accuracy CNNs need", "Macro-level result only (no full system, weight loading or inter-layer data movement), and peak efficiency is quoted in binary mode"], "remarks": "This is the first of a series of TSMC/NTHU (M.-F. Chang group) ReRAM-CIM ISSCC macros. Later work raised precision to 4b/4b and moved to 22 nm (Xue ISSCC 2020), then to 8b precision. It is useful as a baseline for macro-level latency and efficiency, but like most ISSCC macros it limits how many rows are activated and reports peak binary-mode numbers, so it is not directly comparable to fully parallel analog crossbars.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Embedded nonvolatile memory (NVM) and computing-in-memory (CIM) are significantly reducing the latency (tMAC) and energy consumption (EMAC) of multiply- and-accumulate (MAC) operations in artificial intelligence (AI) edge devices [1, 2]. Previous ReRAM CIM macros demonstrated MAC operations for lb-input, ternary- weighted, 3b-output CNNs [1] or lb-input, 8b-weighted, 1b-output fully-connected networks with limited accuracy [2]. To support higher-accuracy convolution neural network heavy applications NVM-CIM should support multibit inputs/weights and multi-bit output (MAC-OUT) for CNN operations. One way to achieve multibit weights is to use a multi-level ReRAM cell to store the weight. However, as shown in Fig. 24.1.1, multibit ReRAM CIM faces several challenges. (1) a tradeoff between area and speed for multibit input/weight/MAC-OUT MAC operations; (2) sense amplifier’s high input offset, large area, and high parasitic load on the read-path due to large BL currents (IBL) from multibit MAC; (3) limited accuracy due to a small read/sensing margin (ISM) across MAC-OUT or variation in cell resistance (particularly MLC cells). To overcome these challenges, this work proposes, (1) a serial-input non-weighted product (SINWP) structure to optimize the tradeoff between area, tMACand EMAC, (2) a down-scaling weighted current translator (DSWCT) and positive-negative current- subtractor (PN-ISUB) for short delay, a small offset and a compact read-path area; and (3) a triple-margin small-offset current-mode sense amplifier (TMCSA) to tolerate a small ISM. A fabricated 55nm 1Mb ReRAM-CIM macro is the first ReRAM CIM macro to support CNN operations using multibit input/weight MAC-OUT. This device achieves the shortest CIM-MAC-access time (tAC) among existing ReRAM-CIMs (tMAC=14.6ns with 2b-input, 3b-weight with 4b-MAC-OUT) and the best peak EMACof 53.17 TOPS/W (in binary mode).", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2019_Xue_1MbMultibitReRAMCIM_ISSCC.pdf", "analysed": true, "pdf": null, "priority": 9.9}, {"id": "W2782791387", "short": "Dot Product Engine", "title": "Memristor‐Based Analog Computation and Neural Network Classification with a Dot Product Engine", "authors": ["Miao Hu", "Catherine E. Graves", "Can Li", "Yunning Li", "Ning Ge", "Eric Montgomery", "Noraica Dávila", "Hao Jiang", "Richard Stanley Williams", "J. Joshua Yang", "Qiangfei Xia", "John Paul Strachan"], "year": 2018, "venue": "Advanced Materials", "venue_short": "AdvMater", "venue_full": "Advanced Materials, vol. 30, 2018", "venue_ok": true, "doi": "https://doi.org/10.1002/adma.201705914", "cites_global": 755, "cat": "02", "seed": false, "devices": ["Memristor(generic)"], "models": ["MLP"], "evidence": "device-experiment", "tldr": "HP Labs demonstrates high-precision analog programming of a 128x64 memristor crossbar (\"Dot Product Engine\") achieving ~6-bit effective vector-matrix-multiplication accuracy and 89.9% MNIST classification accuracy in a single-layer neural network, with projected efficiency above 100 TOPS/W for scaled, integrated devices.", "summary": "The paper targets a key bottleneck in memristor-crossbar neural-network acceleration: most prior demonstrations were simulated or limited to small arrays because reliably programming memristor cells to stable, precise analog conductance values at scale is hard. The authors demonstrate high-precision analog tuning and control across a 128x64 memristor crossbar array (a 'Dot Product Engine') and evaluate the resulting vector-matrix-multiplication (VMM) computing precision. They perform single-layer neural-network inference in hardware on this array and compare its classification performance to a digital approach, finding the memristor computing system reaches a VMM accuracy equivalent to about 6 bits and achieves 89.9% recognition accuracy on the full 10k-image MNIST test set. The authors also project that with integrated, on-chip and further-scaled memristor devices, computational efficiency greater than 100 trillion operations per second per Watt (100 TOPS/W) is achievable.", "contributions": ["Demonstration of high-precision analog programming/control of memristor conductance values across a relatively large (128x64) crossbar array", "Quantification of the achievable vector-matrix-multiplication computing precision of a physically programmed memristor crossbar (~6-bit equivalent)", "Hardware demonstration of single-layer neural-network inference (MNIST digit classification) running on the physical memristor crossbar, with comparison to a digital baseline", "Projection of achievable energy efficiency (>100 TOPS/W) for future integrated, scaled memristor crossbar systems"], "claims": [{"claim": "The memristor crossbar computing system achieves a VMM accuracy equivalent to approximately 6 bits of precision", "support": "'Memristor computing system used here reaches a VMM accuracy equivalent of 6 bits'", "loc": "Abstract"}, {"claim": "A single-layer neural network implemented on the physical 128x64 memristor crossbar achieves 89.9% classification accuracy on the full MNIST test set", "support": "'89.9% recognition accuracy is achieved for the 10k MNIST handwritten digit test set'", "loc": "Abstract"}, {"claim": "Scaled, on-chip-integrated memristor crossbars could in principle exceed 100 TOPS/W computational efficiency", "support": "'Forecasts show that with integrated (on chip) and scaled memristors, a computational efficiency greater than 100 trillion operations per second per Watt is possible'", "loc": "Abstract"}], "results": ["~6-bit equivalent VMM computing precision on a physically programmed 128x64 memristor crossbar", "89.9% MNIST test-set classification accuracy for a single-layer neural network run on the hardware crossbar", "Projected >100 TOPS/W computational efficiency for future scaled, integrated memristor systems (forecast, not measured)"], "limitations": ["Full text not available to this review (abstract-only basis); experimental setup details (programming scheme, read/write circuitry, number of trials) could not be independently verified", "Demonstration is limited to a single-layer neural network and a 128x64 array, well below the scale needed for practical deep networks", "The headline 89.9% MNIST accuracy is notably below typical software baselines (~98-99%) for MNIST classifiers, reflecting the real precision/noise limits of the physical crossbar", "The >100 TOPS/W efficiency figure is an extrapolated forecast for future integrated/scaled devices, not a measured result of the demonstrated system"], "remarks": "This HP Labs (now HPE Labs) paper is an important measured-hardware milestone showing that reasonably large memristor crossbar arrays can be programmed with enough analog precision (~6 bits) to perform real inference with non-trivial accuracy, going beyond earlier small-scale or purely simulated demonstrations (e.g., Prezioso's 2015 integrated network, Burr's PCM synapse work). It is widely cited as evidence that crossbar-based analog VMM is experimentally viable at a useful scale, though the 89.9% MNIST accuracy (well below software baselines) and reliance on a single-layer network also illustrate the gap between fabricated-device precision and the near-lossless accuracy needed for competitive deep-learning accelerators -- a gap that motivated much of the non-ideality-aware training and mapping literature that followed. The quantitative claims above come directly from the paper's own abstract since the full text could not be retrieved for this review.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Using memristor crossbar arrays to accelerate computations is a promising approach to efficiently implement algorithms in deep neural networks. Early demonstrations, however, are limited to simulations or small-scale problems primarily due to materials and device challenges that limit the size of the memristor crossbar arrays that can be reliably programmed to stable and analog values, which is the focus of the current work. High-precision analog tuning and control of memristor cells across a 128 × 64 array is demonstrated, and the resulting vector matrix multiplication (VMM) computing precision is evaluated. Single-layer neural network inference is performed in these arrays, and the performance compared to a digital approach is assessed. Memristor computing system used here reaches a VMM accuracy equivalent of 6 bits, and an 89.9% recognition accuracy is achieved for the 10k MNIST handwritten digit test set. Forecasts show that with integrated (on chip) and scaled memristors, a computational efficiency greater than 100 trillion operations per second per Watt is possible.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2018_Hu_DotProductEngine_AdvMater.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2018_Hu_DotProductEngine_AdvMater.pdf", "priority": 9.65}, {"id": "W2794288888", "short": "65nm 1Mb ReRAM CIM Macro", "title": "A 65nm 1Mb nonvolatile computing-in-memory ReRAM macro with sub-16ns multiply-and-accumulate for binary DNN AI edge processors", "authors": ["Wei-Hao Chen", "Kaixiang Li", "Wei‐Yu Lin", "Kuo-Hsiang Hsu", "Pinyi Li", "Cheng‐Han Yang", "Cheng-Xin Xue", "En-Yu Yang", "Yen-Kai Chen", "Yun-Sheng Chang", "Tzu-Hsiang Hsu", "Ya‐Chin King", "Chorng-Jung Lin", "Ren-Shuo Liu", "Chih-Cheng Hsieh", "Kea‐Tiong Tang", "Meng‐Fan Chang"], "year": 2018, "venue": "", "venue_short": "ISSCC", "venue_full": "2018 IEEE International Solid-State Circuits Conference (ISSCC)", "venue_ok": true, "doi": "https://doi.org/10.1109/isscc.2018.8310400", "cites_global": 334, "cat": "02", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "A fabricated 65nm, 1Mb nonvolatile ReRAM computing-in-memory macro performs multiply-and-accumulate for binary DNN inference with sub-16ns MAC time, targeting the memory-I/O bottleneck of conventional von-Neumann AI edge processors running CNN/FCN layers.", "summary": "AI edge devices that store neural-network weights in nonvolatile memory and run inference using conventional von-Neumann memory hierarchies suffer from high access latency, I/O energy consumption, and hardware cost, especially as CNN and fully-connected (FCN) layers generate large working sets and large volumes of intermediate multiply-and-accumulate (MAC) data, a bottleneck that persists even with binary-weight DNNs. The authors address this by fabricating a 65nm, 1Mb nonvolatile ReRAM computing-in-memory (CIM) macro that performs MAC operations for binary DNN inference directly within the memory array, achieving a reported sub-16ns MAC computation time, aiming to remove the memory-I/O bottleneck for AI edge processors.", "contributions": ["A fabricated 65nm, 1Mb ReRAM computing-in-memory macro that performs multiply-and-accumulate (MAC) operations in-array rather than moving weights to a separate compute unit", "A circuit design achieving sub-16ns MAC computation time for binary-weight DNN (CNN/FCN) inference", "Demonstration that in-memory ReRAM MAC can reduce the memory-hierarchy I/O bottleneck that limits conventional von-Neumann AI edge processors"], "claims": [{"claim": "The fabricated 65nm 1Mb ReRAM macro performs multiply-and-accumulate computation for binary DNNs in under 16ns", "support": "stated in the paper's title: 'sub-16ns multiply-and-accumulate for binary DNN AI edge processors'", "loc": "Title/Abstract"}, {"claim": "Conventional von-Neumann memory architectures for AI edge processors are bottlenecked by access latency, I/O energy, and hardware cost from large CNN/FCN working sets and intermediate MAC data, motivating an in-memory-computing approach", "support": "qualitative motivation given in the abstract", "loc": "Abstract"}], "results": ["Sub-16ns multiply-and-accumulate (MAC) computation time, fabricated in 65nm CMOS with a 1Mb ReRAM array"], "limitations": ["Full text not available to this review (abstract-only basis, as is typical for ISSCC papers that are not openly archived); detailed measured metrics such as energy efficiency (TOPS/W), area efficiency, ADC/peripheral overhead, and achieved classification accuracy could not be independently verified", "Targets binary-weight DNNs specifically, which trade off accuracy for computing simplicity relative to higher-precision networks", "As an ISSCC macro paper, results are from a single fabricated test chip/macro rather than a full end-to-end system evaluation"], "remarks": "This is a representative measured-silicon ReRAM computing-in-memory macro from the Meng-Fan Chang group (National Tsing Hua University), part of a well-known series of ISSCC ReRAM CIM macro papers (including later multibit and higher-TOPS/W follow-ups) that are frequently used as measured-hardware reference points in survey and benchmarking papers for crossbar/PIM accelerators. Because the full text could not be retrieved, only the title-stated sub-16ns MAC latency could be confirmed here; quantitative claims about energy efficiency or classification accuracy are not included since they were not present in the available abstract.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Many artificial intelligence (AI) edge devices use nonvolatile memory (NVM) to store the weights for the neural network (trained off-line on an AI server), and require low-energy and fast I/O accesses. The deep neural networks (DNN) used by AI processors [1,2] commonly require p-layers of a convolutional neural network (CNN) and q-layers of a fully-connected network (FCN). Current DNN processors that use a conventional (von-Neumann) memory structure are limited by high access latencies, I/O energy consumption, and hardware costs. Large working data sets result in heavy accesses across the memory hierarchy, moreover large amounts of intermediate data are also generated due to the large number of multiply-and-accumulate (MAC) operations for both CNN and FCN. Even when binary-based DNN [3] are used, the required CNN and FCN operations result in a major memory I/O bottleneck for AI edge devices.", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2018_Chen_65nm1MbReRAMMacro_ISSCC.pdf", "analysed": true, "pdf": null, "priority": 10.33}, {"id": "W1542981317", "short": "Memristor Perceptron", "title": "Training and operation of an integrated neuromorphic network based on metal-oxide memristors", "authors": ["M. Prezioso", "Farshad Merrikh‐Bayat", "Brian D. Hoskins", "Gina C. Adam", "Konstantin K. Likharev", "Dmitri B. Strukov"], "year": 2015, "venue": "Nature", "venue_short": "Nature", "venue_full": "Nature, vol. 521 (2015)", "venue_ok": true, "doi": "https://doi.org/10.1038/nature14441", "cites_global": 3032, "cat": "02", "seed": false, "devices": ["Memristor(generic)"], "models": ["MLP"], "evidence": "measured-silicon", "tldr": "First experimental demonstration of a transistor-free, integrated metal-oxide memristor crossbar (12x12, Al2O3/TiO2-x) trained in situ to perform perfect single-layer-perceptron classification of 3x3-pixel patterns.", "summary": "Prior memristive neuromorphic demonstrations relied on discrete devices or an extra transistor per crosspoint for individual forming, which is incompatible with dense, transistor-free CrossNet-style crossbars. This paper reports a fabricated 12x12 Al2O3/TiO2-x metal-oxide memristor crossbar with device-to-device variability low enough to allow individual electrical forming of each device directly through the crossbar wiring. The crossbar implements a single-layer perceptron (10 inputs including bias, 3 outputs, 30 differential synapses realized with 60 memristors) that computes the vector-matrix product via Ohm's law/Kirchhoff's current summation. The network is trained in situ with a coarse-grained, batch-mode 'Manhattan Update rule' variant of the delta rule, applying fixed-amplitude set/reset pulses to each column. On a toy 30-pattern task (3 stylized letters z/v/n plus 9 single-pixel-flip noisy versions each), the physical network reaches perfect classification after an average of 15 training epochs.", "contributions": ["First working transistor-free (1T0S-free) metal-oxide memristor crossbar integrated with CMOS-compatible, low-temperature fabrication", "Demonstrated individual electroforming of every crosspoint device through the crossbar's own row/column wires (no per-device switch transistor, no external disconnection)", "Implemented analog vector-matrix multiplication directly via Ohm's law/KCL summation on the fabricated array", "Demonstrated in-situ (on-chip) training using a coarse-grain Manhattan Update / delta-rule variant with fixed-amplitude set/reset pulses", "Achieved perfect classification of a toy pattern-recognition task on real hardware, establishing feasibility of dense transistor-free memristive neural networks"], "claims": [{"claim": "Optimized Al2O3/TiO2-x memristor stacks give sufficiently low device-to-device variability to allow individual forming of every device in an integrated crossbar without extra transistors", "support": "ON/OFF ratio >10^4 at 0.1V, >10-fold I-V nonlinearity ratio, forming voltage <2V, switching voltage ~1.5V, endurance >=5000 cycles, retention >=10 years (est.)", "loc": "Memristor Fabrication, Forming and Characterization section"}, {"claim": "The fabricated 12x12 crossbar can implement a trainable single-layer perceptron entirely via physical Ohm's-law summation for the matrix-vector product", "support": "30 synapses realized with 60 memristors (2 per synapse, differential), effective conductances 10-100 microS, output currents ~few microA matching Eq. (2)-(3)", "loc": "Pattern Classification Experiment section"}, {"claim": "In-situ training with a coarse-grain Manhattan Update rule converges to perfect classification on the benchmark task", "support": "Perfect classification reached on average after 15 training epochs (Fig. 4) when memristors initialized near mid-range conductance (~35 microS, per Fig. S7b)", "loc": "Pattern Classification Experiment / Fig. 4"}], "results": ["Perfect classification of 30 patterns (3 classes, 3x3-pixel images with noisy variants) achieved after ~15 training epochs on average", "Device ON/OFF current ratio > 10^4 at 0.1 V; I-V nonlinearity >10x between switching voltage and half that voltage", "Switching endurance >=5000 cycles; low forming voltage <2V and switching voltage ~1.5V; estimated retention >=10 years at room temperature", "Crossbar wire resistance reduced to ~800 ohm (top lines) and ~600 ohm (bottom lines) via thicker metal electrodes"], "limitations": ["Extremely small-scale demonstration: only a 12x12 crossbar (60 memristors) and a 10-input/3-output single-layer perceptron on a 3x3-pixel toy task", "Non-crossbar operations (activation function, error computation, weight-update decision) performed by external electronics, not on-chip", "Training set (30 patterns) also used for testing, so no generalization claim is made", "Manhattan Update rule followed only approximately because actual conductance change depends on initial device state (fixed-amplitude pulses, not device-calibrated)", "No discussion of scaling to deep/multilayer networks beyond stating it as future work"], "remarks": "This is a foundational device/circuit-level proof of concept rather than a system or architecture paper: it shows, for the first time, that a transistor-free metal-oxide memristor crossbar can be formed, operated, and trained in situ with enough uniformity to realize a working (if tiny) neural network. Its significance for the thesis topic is mainly historical/foundational -- it is heavily cited by essentially all later ReRAM crossbar accelerator, in-situ training, and non-ideality/fault-tolerance papers as the earliest hardware evidence that memristor crossbars can perform analog vector-matrix multiplication and learning. The result should be read with caution: the task is trivial by modern standards, and much of the training loop and signal generation was done off-chip, so it demonstrates feasibility of the core analog MVM + local update primitive, not a scalable system.", "basis": "full-text", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "02_Fabricated_Chips_and_Macros/2015_Prezioso_MemristorPerceptron_Nature.pdf", "analysed": true, "pdf": "02_Fabricated_Chips_and_Macros/2015_Prezioso_MemristorPerceptron_Nature.pdf", "priority": 11.16}, {"id": "W4407720907", "short": "Heterogeneous PCM-AIMC NPU", "title": "Heterogeneous Embedded Neural Processing Units Utilizing PCM-Based Analog In-Memory Computing", "authors": ["Irem Boybat", "Thomas Boesch", "Mario Allegra", "M. Baldo", "J.J. Bertolini-Agnoletto", "Geoffrey W. Burr", "Alessandro Buschini", "Alessandro Cabrini", "Emanuela Calvetti", "Carmine Cappetta", "Francesco Conti", "Elena Ferro", "Eleonora Franchi Scarselli", "A. Garofalo", "Francesca Girardi", "Gamze İslamoğlu", "Vara Prasad Jonnalagadda", "Geethan Karunaratne", "Corey Lammie", "Manuel Le Gallo", "C. Li", "R. Massa", "Andrea Carlo Ornstein", "H. Pang", "Marco Pasotti", "Bipin Rajendran", "Andrea Redaelli", "İrem Şanlı", "William Simon", "Abhairaj Singh", "Surinder-Pal Singh", "Giulio Urlini", "A. Vasilopoulos", "Riccardo Zurla", "Giuseppe Desoli", "Abu Sebastian"], "year": 2024, "venue": "", "venue_short": "IEDM", "venue_full": "2024 IEEE International Electron Devices Meeting (IEDM)", "venue_ok": true, "doi": "https://doi.org/10.1109/iedm50854.2024.10873479", "cites_global": 15, "cat": "03", "seed": false, "devices": ["PCM"], "models": ["Transformer"], "evidence": "analytical", "tldr": "IBM and STMicroelectronics propose a heterogeneous embedded NPU architecture for edge AI that pairs PCM-based AIMC tiles (for matrix-vector multiplication) with digital accelerator nodes and a programmable software cluster, projecting transformer inference throughput competitive with high-end mobile SoCs built on more advanced nodes.", "summary": "The paper targets edge AI inference, where energy, area, and cost budgets are much tighter than in datacenter accelerators. It proposes a heterogeneous embedded Neural Processing Unit (NPU) that combines multiple digital and analog accelerator nodes to cover diverse operation types and precision requirements within one SoC. The key analog component is a set of Analog In-Memory Computing (AIMC) tiles based on Phase-Change Memory (PCM), used to execute matrix-vector multiplications with high energy efficiency and substantial non-volatile on-chip weight storage, avoiding the need to stream weights from off-chip DRAM. A digital data path and a programmable software cluster coordinate end-to-end inference across layers/operations that require different numeric precision (e.g., attention/softmax, normalization) that are not well suited to the analog tiles. The authors project that this heterogeneous PCM-AIMC/digital NPU can deliver throughput for transformer-based neural networks that is competitive with high-end mobile SoCs fabricated at more advanced technology nodes, despite relying on an older/cheaper process enabled by PCM's density and efficiency advantage.", "contributions": ["Proposes a heterogeneous embedded NPU architecture mixing digital accelerator nodes and PCM-based AIMC tiles within a single edge-AI SoC", "Uses PCM AIMC tiles specifically for matrix-vector multiplication to combine high energy efficiency with large non-volatile on-chip weight capacity", "Adds a digital data path and programmable software cluster to support end-to-end inference across multiple precision levels and non-MVM operations", "Targets transformer neural network workloads at the edge, projecting throughput competitive with higher-end mobile SoCs on more advanced technology nodes"], "claims": [{"claim": "A heterogeneous PCM-AIMC + digital NPU can match the transformer inference throughput of high-end mobile SoCs built on more advanced process nodes", "support": "The NPU is projected to deliver competitive throughput for transformer neural networks rivaling high-end mobile/edge SoCs fabricated at more advanced technology nodes (stated in the abstract; no full-text numeric figures available from this access)", "loc": "Abstract"}], "results": [], "limitations": ["Analysis based on abstract only; no full text was accessible (not found via arXiv or other legitimate open-access sources), so specific throughput/energy numbers, benchmark details, and comparison baselines could not be verified", "Claims described as 'projected'/architectural rather than confirmed as measured silicon results in the available abstract"], "remarks": "This IEDM 2024 paper (IBM/STMicroelectronics-affiliated authorship consistent with the IBM PCM-AIMC line of work, e.g. HERMES chip) is a device-to-system architecture proposal pairing non-volatile PCM crossbars with digital compute for edge transformer inference; without full text, the specific throughput/efficiency numbers and the degree of silicon validation versus projection cannot be confirmed, so this entry should be revisited if the full paper becomes accessible.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "We propose an embedded Neural Processing Unit (NPU) architecture for deep learning inference to address the stringent energy, area, and cost requirements of edge AI. This heterogeneous architecture integrates a variety of digital and analog accelerator nodes to cater to diverse operation types and precision requirements. To achieve high energy efficiency while maintaining substantial non-volatile on-chip weight capacity, we utilize Analog In-Memory Computing (AIMC) tiles based on Phase-Change Memory (PCM) for Matrix-Vector Multiplications (MVMs). Additionally, a digital data path and a programmable software cluster facilitate end-to-end inference across multiple precision levels. The NPU is projected to deliver competitive throughput for transformer Neural Networks (NNs), rivaling high-end System-on-Chips (SoCs) for mobile devices and edge accelerators fabricated at more advanced technology nodes.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2024_Boybat_HeterogeneousPCMAimcNPU_IEDM.pdf", "analysed": true, "pdf": null, "priority": 7.17}, {"id": "W4379116135", "short": "AIMC-ResNet18-Manycore", "title": "End-to-End DNN Inference on a Massively Parallel Analog In Memory Computing Architecture", "authors": ["Nazareno Bruschi", "Giuseppe Tagliavini", "Angelo Garofalo", "Francesco Conti", "Irem Boybat", "Luca Benini", "Davide Rossi"], "year": 2023, "venue": "", "venue_short": "DATE", "venue_full": "Design, Automation & Test in Europe Conference (DATE 2023)", "venue_ok": true, "doi": "https://doi.org/10.23919/date56975.2023.10137208", "cites_global": 5, "cat": "03", "seed": false, "devices": ["PCM"], "models": ["CNN", "ResNet"], "evidence": "simulation", "tldr": "A 512-cluster RISC-V + PCM in-memory-compute many-core SoC maps a full end-to-end ResNet-18 across on-chip analog crossbars, reaching 20.2 TOPS and 6.5 TOPS/W in cycle-accurate-calibrated simulation.", "summary": "Prior multi-AIMC systems demonstrated only tiny/custom CNNs or offloaded some layers off-chip; this paper targets full end-to-end inference of a real, residual-connection-bearing network (ResNet-18) on a large heterogeneous many-core fabric. Each of 512 clusters pairs 16 RISC-V cores with one PCM-based in-memory-compute accelerator (IMA, 256x256 crossbar, 130 ns MVM latency) sharing a local scratchpad, connected via a hierarchical AXI network-on-chip to off-chip HBM. Layers are statically mapped to clusters by parameter count, with multi-cluster splitting/broadcast for layers too large or too wide for a single 256x256 IMA, data-replication to balance pipeline stage latency, a log-depth reduction tree for accumulating partial sums across clusters, and reuse of idle clusters' local memory (rather than HBM) to buffer residual/skip-connection data. Evaluation uses an extended version of the GVSOC event-based simulator (>90% accuracy vs. cycle-accurate RTL/FPGA) together with 22nm place-and-route data scaled to 5nm. The optimized mapping (data-replication + parallelization + improved residual storage) improves throughput by 1.6x and a further 1.9x over a naive multi-cluster mapping, reaching 20.2 TOPS / 3303 images/s and 6.5 TOPS/W for batch-16 256x256 ResNet-18 inference, while only using 322 of 512 clusters (42 GOPS/mm2 overall, up to 600 GOPS/mm2 in the best-utilized layer group).", "contributions": ["First reported full end-to-end inference of a real residual CNN (ResNet-18) entirely on-chip across many non-volatile AIMC (PCM) cores, rather than tiny/custom networks or partial off-chip execution", "A static layer-to-cluster mapping scheme handling multi-IMA splitting (input-channel overflow) and broadcast (output-channel overflow) simultaneously, needed for ResNet-18's channel depths", "Data-replication and parallelization techniques to balance a many-stage analog/digital pipeline, plus a hierarchical reduction-tree scheme for cross-cluster partial-sum accumulation", "A residual/skip-connection buffering strategy that reuses idle clusters' local L1 memory instead of off-chip HBM, improving performance by 1.9x", "Quantified breakdown of the 'ideal vs achieved' performance gap into global mapping, local mapping, intra-layer unbalance and communication overheads"], "claims": [{"claim": "The architecture achieves 20.2 TOPS and 6.5 TOPS/W for end-to-end ResNet-18 inference on batches of 16 256x256 images", "support": "20.2 TOPS (3303 images/s), 9.2 ms and 15 mJ per batch, 6.5 TOPS/W, 42 GOPS/mm2, 480 mm2 architecture", "loc": "Sec. VI / Conclusion"}, {"claim": "Optimized data-replication/parallelization mapping improves throughput by 1.6x over a naive multi-cluster mapping", "support": "Fig. 5A/5C: 1.6x gain at the cost of 61 additional clusters", "loc": "Sec. VI, Fig. 5"}, {"claim": "Moving residual (skip-connection) storage from off-chip HBM to idle clusters' on-chip L1 memory improves performance by 1.9x", "support": "1.9x improvement, using 2 MB of on-chip memory across 2 extra clusters", "loc": "Sec. V-4 / Sec. VI"}, {"claim": "Only a fraction of clusters are actually used for parameter mapping, limiting area efficiency", "support": "322 of 512 clusters exploited; global mapping accounts for a large share of the ideal-to-achieved performance gap in Fig. 6", "loc": "Sec. VI, Fig. 6"}, {"claim": "The extended GVSOC simulator used for all performance numbers is accurate relative to cycle-accurate RTL/FPGA", "support": ">90% accuracy vs. cycle-accurate equivalent, 25 MIPS simulation speed, full ResNet-18 on 512 clusters simulated in <20 minutes", "loc": "Sec. III"}], "results": ["20.2 TOPS, 6.5 TOPS/W, 42 GOPS/mm2 for end-to-end ResNet-18 inference (batch 16, 256x256 images, 9.2 ms, 15 mJ)", "1.6x throughput improvement from data-replication/parallelization (at cost of 61 extra clusters)", "1.9x further throughput improvement from on-chip (vs. off-chip HBM) residual storage", "322 of 512 clusters utilized for parameter mapping; area efficiency ranges from 50 GOPS/mm2 (deep, low-reuse layers) to 600 GOPS/mm2 (high-reuse layer group)", "Simulator calibrated to >90% accuracy vs. cycle-accurate RTL/FPGA equivalent"], "limitations": ["Purely simulation-based (GVSOC extension); no silicon measurement of the full system, only physical synthesis/P&R of a single cluster scaled across a projected 5nm node", "PCM device non-idealities (drift, noise, write latency/endurance) are not modeled in the computational/accuracy sense — the work is about architectural/mapping throughput, not inference accuracy under analog non-idealities", "Only ResNet-18 at a fixed 256x256 input resolution and 256x256 IMA size is evaluated; generality to larger/irregular models or other crossbar sizes is not demonstrated", "Only ~63% of clusters are actually used for mapping (322/512), and static mapping cannot adapt at runtime to rebalance the pipeline"], "remarks": "This is a mapping/architecture simulation study, not a silicon or device-accuracy paper: its contribution is scheduling/dataflow (multi-cluster splitting, data-replication, residual buffering) to get a full non-trivial CNN with skip connections pipelined across hundreds of PCM crossbar cores, something earlier systolic-style accelerators (ISAAC, PUMA) avoided by targeting VGG-style networks without residuals. The quantified decomposition of inefficiency (global/local mapping, intra-layer unbalance, communication) is a useful diagnostic for anyone mapping deep CNNs onto crossbar arrays and shows that cluster underutilization (only 322/512 used) is a first-order cost, not non-idealities. Because it builds on the same group's GVSOC/PULP cluster line (Garofalo et al.), it should be read alongside that work for the underlying IMA/cluster microarchitecture.", "basis": "full-text", "pdf_source_url": "", "abstract": "The demand for computation resources and energy efficiency of Convolutional Neural Networks (CNN) applications requires a new paradigm to overcome the “Memory Wall”. Analog In-Memory Computing (AIMC) is a promising paradigm since it performs matrix-vector multiplications, the critical kernel of many ML applications, in-place in the analog domain within memory arrays structured as crossbars of memory cells. However, several factors limit the full exploitation of this technology, including the physical fabrication of the crossbar devices, which constrain the memory capacity of a single array. Multi-AIMC architectures have been proposed to overcome this limitation, but they have been demonstrated only for tiny and custom CNNs or performing some layers off-chip. In this work, we present the full inference of an end-to-end ResNet-18 DNN on a 512-cluster heterogeneous architecture coupling a mix of AIMC cores and digital RISC-V cores, achieving up to 20.2 TOPS. Moreover, we analyze the mapping of the network on the available non-volatile cells, compare it with state-of-the-art models, and derive guidelines for next-generation many-core architectures based on AIMC devices.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2023_Bruschi_AIMCResNet18Manycore_DATE.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2023_Bruschi_AIMCResNet18Manycore_DATE.pdf", "priority": 4.04}, {"id": "W4313251083", "short": "Analog-AI-2DMesh", "title": "A Heterogeneous and Programmable Compute-In-Memory Accelerator Architecture for Analog-AI Using Dense 2-D Mesh", "authors": ["Shubham Jain", "Hsinyu Tsai", "Ching-Tzu Chen", "R. Muralidhar", "Irem Boybat", "Martin M. Frank", "Stanisław Woźniak", "Miloš Stanisavljević", "Praneet Adusumilli", "Pritish Narayanan", "Kohji Hosokawa", "Masatoshi Ishii", "Arvind Kumar", "Vijay Narayanan", "Geoffrey W. Burr"], "year": 2022, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2022.3221390", "cites_global": 74, "cat": "03", "seed": false, "devices": ["PCM"], "models": ["CNN", "LSTM/RNN", "Transformer", "BERT"], "evidence": "simulation", "tldr": "IBM's heterogeneous, programmable compute-in-memory accelerator architecture combines spatially distributed analog CIM tiles for weight-stationary MAC with heterogeneous digital compute cores, connected by a dense circuit-switched 2-D mesh, and shows projected system-level performance 40x-140x more energy-efficient than an NVIDIA A100 across CNNs, LSTMs and transformers (including BERT).", "summary": "The paper presents a highly heterogeneous and programmable compute-in-memory (CIM) accelerator architecture for DNN inference that combines spatially distributed CIM memory array 'tiles' performing weight-stationary, energy-efficient MAC operations with heterogeneous special-function digital compute cores for auxiliary operations. Massively parallel activation vectors move between tiles and cores over short distances via a dense, efficient circuit-switched 2-D mesh (the 'analog fabric'), which is designed to support a wide range of DNN workloads including CNNs, LSTMs, and transformers end-to-end. The authors address both the mapping of DNNs onto this hardware and the pipelining of workloads across a range of batch sizes, and present system-level performance estimates using projected component parameters for a realistic 'analog AI' system built from dense crossbar arrays of low-power nonvolatile analog memory elements (PCM), including scaling the single analog-fabric design to larger networks by introducing inter-chip data transport across multiple analog AI chips. Performance estimates for several networks, including large LSTM and BERT, show highly competitive throughput while offering substantially higher energy efficiency than an NVIDIA A100 GPU.", "contributions": ["A heterogeneous, programmable CIM accelerator architecture combining analog CIM tiles (weight-stationary MAC) with heterogeneous digital special-function compute cores", "A dense, efficient circuit-switched 2-D mesh ('analog fabric') interconnecting tiles and cores for massively parallel activation data movement", "End-to-end support for a wide range of DNN workloads (CNNs, LSTM, transformers/BERT) on a single common hardware fabric design", "Mapping and pipelining strategies for DNN workloads across a range of batch sizes on the proposed architecture", "System-level performance projections using realistic component parameters for an analog-AI system based on dense nonvolatile-memory crossbars, including scale-out across multiple analog AI chips", "First system-level assessment (per the authors) showing analog-AI accelerators are competitive in throughput while offering large energy-efficiency gains over a modern GPU"], "claims": [{"claim": "The proposed analog-AI accelerator architecture offers highly competitive throughput for large and diverse DNN workloads, including transformers", "support": "performance estimates reported for several networks including large LSTM and BERT, shown to be highly competitive in throughput", "loc": "Abstract"}, {"claim": "The analog-AI architecture offers dramatically higher energy efficiency than a state-of-the-art GPU", "support": "40x-140x higher energy efficiency than NVIDIA A100, depending on workload", "loc": "Abstract"}, {"claim": "A single common analog fabric design can scale to large networks via inter-chip data transport across multiple analog AI chips", "support": "stated architectural capability demonstrated via system-level performance estimates", "loc": "Abstract"}], "results": ["40x-140x higher energy efficiency than NVIDIA A100 across evaluated networks (projected system-level estimates)", "Highly competitive throughput reported for CNNs, large LSTM networks, and BERT (transformer) workloads"], "limitations": ["This entry is based on the abstract only (no full text or PDF was located); the exact simulation/estimation methodology, specific per-network throughput numbers, and batch-size sensitivity results are not confirmed here", "Performance figures are system-level projections using projected component parameters for a realistic analog-AI system, not measurements from a fabricated multi-tile chip", "Energy-efficiency comparison is against an NVIDIA A100 GPU baseline; comparisons to other PIM/CIM accelerator architectures are not stated in the abstract"], "remarks": "This is IBM's influential heterogeneous analog-AI accelerator architecture paper (74 citations, with numerous later papers in this collection -- AnalogNAS, NORA, SAGE, CIMFlow, the ALBERT demonstration chip, and others -- explicitly building on or citing it), making it a key reference point for mapping transformer/LLM workloads onto PCM-based analog crossbar fabrics at system scale. Its central contribution for mapping research is the explicit co-design of a 2-D circuit-switched interconnect ('analog fabric') to support heterogeneous digital+analog cores and diverse workloads (CNN/LSTM/transformer) on one architecture, rather than a single-workload-specific crossbar design. Because only the abstract was available here, the specific mapping/pipelining algorithms and the precise throughput-vs-batch-size tradeoffs could not be verified and should be checked in the full text, which is recommended given the paper's centrality to this literature.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "We introduce a highly heterogeneous and programmable compute-in-memory (CIM) accelerator architecture for deep neural network (DNN) inference. This architecture combines spatially distributed CIM memory array “tiles” for weight-stationary, energy-efficient multiply–accumulate (MAC) operations, together with heterogeneous special-function compute cores for auxiliary digital computation. Massively parallel vectors of neuron activation data are exchanged over short distances using a dense and efficient circuit-switched 2-D mesh, offering full end-to-end support for a wide range of DNN workloads, including CNNs, long-short-term-memory (LSTM), and transformers. We discuss the design of the “analog fabric”—the 2-D grid of tiles and compute cores interconnected by the 2-D mesh—and address the efficiency in both mapping of DNNs onto the hardware and in pipelining of various DNN workloads across a range of batch sizes. We show, for the first time, system-level assessments using projected component parameters for a realistic “analog AI” system, based on dense crossbar arrays of low-power nonvolatile analog memory elements, while incorporating a single common analog fabric design that can scale to large networks by introducing data transport between multiple analog AI chips. Our performance estimates for several networks, including large LSTM and bidirectional encoder representations from transformers (BERT), show highly competitive throughput while offering$40\\times $–$140\\times $higher energy efficiency than NVIDIA A100—thus illustrating the strong promise of analog AI and the proposed architecture for DNN inference applications.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2022_Jain_AnalogAI2DMesh_TVLSI.pdf", "analysed": true, "pdf": null, "priority": 8.83}, {"id": "W4287736153", "short": "Heterogeneous IMC Cluster", "title": "A Heterogeneous In-Memory Computing Cluster for Flexible End-to-End Inference of Real-World Deep Neural Networks", "authors": ["Angelo Garofalo", "Gianmarco Ottavi", "Francesco Conti", "Geethan Karunaratne", "Irem Boybat", "Luca Benini", "Davide Rossi"], "year": 2022, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems, vol. 12, no. 2, 2022", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2022.3170152", "cites_global": 41, "cat": "03", "seed": false, "devices": ["PCM"], "models": ["CNN", "MobileNetV2"], "evidence": "simulation", "tldr": "A PULP cluster tightly couples 8 RISC-V cores, a 256x256 PCM analog in-memory accelerator and a digital depth-wise engine (post-place-and-route, GF 22nm FDX). It runs a MobileNetV2 bottleneck 11.5x faster and 9.5x more energy-efficiently than the 8 cores alone, and full MobileNetV2 in about 10 ms / 482 uJ using 34 crossbars.", "summary": "The paper studies system-level integration of analog IMC for edge/TinyML inference, where Amdahl's law and interface bandwidth limit the benefit of a fast MVM array. The authors build a shared-L1 (512 kB TCDM) PULP cluster with 8 RISC-V cores, a PCM IMA modelled on IBM's HERMES 14 nm core (256x256, 4-bit signed weights, 8-bit DAC/ADC, 130 ns MVM), scaled to 22 nm, and a small digital depth-wise convolution accelerator. The IMA streams data directly to and from the TCDM through a widened, pipelined interface. Point-wise and standard convolutions are mapped to the crossbar via im2col, while depth-wise layers are either expanded into sparse block-diagonal crossbar mappings (C_job splitting) or run on the digital accelerator; residuals run on the cores. For end-to-end MobileNetV2, a Tile&Pack bin-packing algorithm splits and packs layer weights onto 34 crossbars (most at 100% cell utilisation), executed sequentially. Results come from post-P&R gate-level power simulation of the digital logic combined with silicon-extrapolated IMA models.", "contributions": ["Post-P&R, silicon-ready heterogeneous cluster (8 RISC-V cores + PCM IMA + depth-wise digital accelerator) in GF 22nm FDX, 2.5 mm2", "Optimised IMA-to-L1 interface reaching 958 GOPS on MVMs (>90% of the 1.008 TOPS peak)", "Analysis of mapping depth-wise convolutions onto crossbars (block-diagonal padding cost, C_job splitting) vs a digital accelerator", "Tile&Pack bin-packing mapping of all MobileNetV2 weights onto multiple 256x256 crossbars and end-to-end latency/energy estimation"], "claims": [{"claim": "Heterogeneous analog/digital execution of a MobileNetV2 bottleneck greatly beats software execution on the cores", "support": "11.5x performance and 9.5x energy efficiency improvements compared to highly optimized parallel execution on the cores", "loc": "Abstract, Sec. V-C, Fig. 9"}, {"claim": "Adding the digital depth-wise accelerator removes the Amdahl bottleneck left by the IMA", "support": "2.6x better performance and 2.8x better energy efficiency compared to executing the layers on our previous work that integrates only 8 programmable cores and the IMC analog array", "loc": "Sec. I contributions, Sec. V-C"}, {"claim": "Depth-wise convolutions map very inefficiently onto crossbars", "support": "mapping the whole bottleneck on the 256x256 array would require 23x more cross-bar locations than the real number of weights; C_job=8/16 increase devices by 25%/54%", "loc": "Sec. V-C"}, {"claim": "End-to-end MobileNetV2 runs an order of magnitude faster than digital MCUs", "support": "inference in 10.1 ms consuming 482 uJ; 10x latency and 2.5x energy improvement vs fully digital SoA, two orders of magnitude faster than SoA analog/digital heterogeneous systems", "loc": "Sec. VI, Sec. VII"}, {"claim": "The tight interface lets the IMA be used near its peak", "support": "958 GOPS on MVMs, more than 90% of its peak theoretical throughput (1.008 TOPS)", "loc": "Sec. V-B, Fig. 7"}], "results": ["Bottleneck layer: 11.5x speedup and 9.5x energy efficiency vs 8-core software; 2.6x/2.8x vs IMA+cores without depth-wise accelerator", "IMA MVM throughput 958 GOPS (>90% of 1.008 TOPS peak) at 500 MHz cluster clock", "MobileNetV2 end-to-end: 10.1 ms, 482 uJ, 34 IMA crossbars, about 30 mm2 of IMA area (0.83 mm2 per IMA)", "Last (best-utilised) layers exceed 5 TOPS/W; early point-wise layers with large activations are dominated by digital data movement", "Cluster area 2.5 mm2 (about 1/3 IMA, 1/3 TCDM); depth-wise accelerator only 2.1% of area"], "limitations": ["IMA area, power and timing are extrapolated from a 14 nm PCM prototype to 22 nm with classical scaling; latency assumed constant", "No accuracy evaluation under PCM noise or drift; quantisation is assumed (4-bit weights, 8-bit activations)", "Scaled-up MobileNetV2 study uses per-layer results from the single-IMA cluster, executes crossbars one at a time (no inter-layer pipelining), and ignores activation movement in the memory hierarchy", "Requires about 30 mm2 of PCM crossbars for a compact mobile network, since weights cannot be reprogrammed at runtime", "Comparisons with SoA are across different technologies and precisions"], "remarks": "This is a careful systems paper that moves the analog-IMC question from peak TOPS/W to end-to-end utilisation. It shows that depth-wise convolutions, residuals and data marshalling dominate once MVMs are accelerated, and that crossbar capacity (34 arrays for MobileNetV2) is the real cost. The evidence is stronger than pure architecture simulation for the digital part (post-P&R, gate-level power) but extrapolated for the analog part. It leads directly to ALPINE-style CPU-coupled designs, the Bruschi et al. massively parallel AIMC DATE'23 study and the IBM/ST heterogeneous embedded NPU (IEDM'24) from overlapping authors.", "basis": "full-text", "pdf_source_url": "", "abstract": "Deployment of modern TinyML tasks on small battery-constrained IoT devices requires high computational energy efficiency. Analog In-Memory Computing (IMC) using non-volatile memory (NVM) promises major efficiency improvements in deep neural network (DNN) inference and serves as on-chip memory storage for DNN weights. However, IMC’s functional flexibility limitations and their impact on performance, energy, and area efficiency are not yet fully understood at the system level. To target practical end-to-end IoT applications, IMC arrays must be enclosed in heterogeneous programmable systems, introducing new system-level challenges which we aim at addressing in this work. We present a heterogeneous tightly-coupled clustered architecture integrating 8 RISC-V cores, an in-memory computing accelerator (IMA), and digital accelerators. We benchmark the system on a highly heterogeneous workload such as the Bottleneck layer from a MobileNetV2, showing$11.5\\times $performance and$9.5\\times $energy efficiency improvements, compared to highly optimized parallel execution on the cores. Furthermore, we explore the requirements for end-to-end inference of a full mobile-grade DNN (MobileNetV2) in terms of IMC array resources, by scaling up our heterogeneous architecture to a multi-array accelerator. Our results show that our solution, on the end-to-end inference of the MobileNetV2, is one order of magnitude better in terms of execution latency than existing programmable architectures and two orders of magnitude better than state-of-the-art heterogeneous solutions integrating in-memory computing analog cores.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2022_Garofalo_HeterogeneousIMCCluster_JETCAS.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2022_Garofalo_HeterogeneousIMCCluster_JETCAS.pdf", "priority": 5.54}, {"id": "W4311978413", "short": "ALPINE", "title": "ALPINE: Analog In-Memory Acceleration with Tight Processor Integration for Deep Learning", "authors": ["Joshua Alexander Harrison Klein", "Irem Boybat", "Yasir Mahmood Qureshi", "Martino Dazzi", "Alexandre Levisse", "Giovanni Ansaloni", "Marina Zapater", "Abu Sebastian", "David Atienza"], "year": 2022, "venue": "IEEE Transactions on Computers", "venue_short": "TC", "venue_full": "IEEE Transactions on Computers", "venue_ok": true, "doi": "https://doi.org/10.1109/tc.2022.3230285", "cites_global": 17, "cat": "03", "seed": false, "devices": ["PCM"], "models": ["MLP", "LSTM/RNN", "CNN"], "evidence": "simulation", "tldr": "ALPINE tightly integrates PCM-based AIMC tiles into an ARMv8 CPU core via a custom ISA extension, modeled in a gem5-X full-system simulator, achieving up to 20.5x/20.8x performance/energy gains over a SIMD CPU for MLP, LSTM and CNN inference.", "summary": "The paper addresses the inflexibility of stand-alone AIMC crossbar accelerators (hard-coded dataflow, limited operation sets) by instead coupling a PCM-based AIMC tile directly into each core of a general-purpose ARM CPU, governed by custom ISA instructions (CM_INITIALIZE, CM_QUEUE, CM_PROCESS, CM_DEQUEUE) rather than memory-mapped I/O. They build ALPINE, an extension of the gem5-X full-system simulator, that models the AIMC tile's timing/energy (calibrated from 14 nm PCM chip measurements) alongside the ARMv8 pipeline, caches, DRAM and Linux OS, and provide a software library (AIMCLib) so neural-network layers can be mapped onto AIMC tiles from C/C++ code. Three exploration studies map single/multi-core MLPs, LSTMs and CNNs onto one or several tightly-coupled AIMC tiles in low-power and high-power system configurations. Results show the tightly-coupled design beats a loosely-coupled (I/O-bus-attached) AIMC accelerator by up to 3.1x, and that adding more CPU cores does not straightforwardly improve performance because inter-core communication of activations becomes the new bottleneck once compute is accelerated. The largest CNN configuration achieves a 20.5x speedup, 3.7x memory-intensity (LLCMPI) reduction and 20.8x energy improvement over a CPU-only SIMD baseline.", "contributions": ["A tightly-coupled system architecture that places a private PCM-based AIMC tile inside each CPU core instead of on the I/O bus", "ARMv8 ISA extension (CM_INITIALIZE/QUEUE/PROCESS/DEQUEUE) to drive the AIMC tile directly from core execution", "ALPINE: a gem5-X-based full-system simulation framework that models AIMC tiles together with the complete CPU/cache/DRAM/OS stack", "AIMCLib software library for mapping MLP, LSTM and CNN layers onto AIMC tiles", "Three multi-core exploration studies (MLP, LSTM, CNN) across low-power and high-power system configurations identifying inter-core communication as the dominant bottleneck once AIMC removes the compute bottleneck"], "claims": [{"claim": "Tightly-coupled AIMC integration outperforms a loosely-coupled (I/O-bus) AIMC accelerator", "support": "loosely-coupled config attains 4.1x speedup vs CPU baseline but is up to 3.1x slower than the tightly-coupled system", "loc": "Sec. VII.B"}, {"claim": "AIMC tiles give large speedup/energy gains for CNN inference", "support": "up to 20.5x speedup, 3.7x memory-intensity improvement, 20.8x energy improvement for CNN-S on the high-power system", "loc": "Sec. IX.B"}, {"claim": "Adding more CPU cores does not translate into proportional performance gains once AIMC tiles remove the MVM bottleneck", "support": "single-core Case 1 has ~20% and ~30% better run-time than dual-core Case 3 and quad-core Case 4 respectively", "loc": "Sec. VII.C"}, {"claim": "AIMC tile MVM operations become a negligible fraction of total run-time, shifting the bottleneck to data queuing/dequeuing", "support": "even a 10x increase in CM_PROCESS latency has minimal impact on performance results; queue/dequeue dominates run-time (Fig. 8)", "loc": "Sec. VII.B, Fig. 8"}, {"claim": "AIMC integration reduces MLP memory-access complexity from O(n^2) to O(n) per inference", "support": "analytical complexity derivation: CPU-only O(Ninf*n^2) vs AIMC-enabled O(Ninf*n)", "loc": "Sec. VII.D"}], "results": ["Up to 20.5x speedup and 20.8x energy improvement vs SIMD ARM CPU for the largest CNN variant (CNN-S), high-power system", "3.7x memory-intensity (LLCMPI) improvement for CNN-S vs CPU-only baseline", "Loosely-coupled AIMC accelerator: 4.1x speedup vs CPU baseline, but up to 3.1x slower than tightly-coupled design", "Single-core MLP (Case 1) ~20% and ~30% faster than dual-core (Case 3) and quad-core (Case 4) MLP mappings respectively, due to inter-core communication overhead", "AIMC tile DAC/ADC resolution: signed 8-bit; MVM latency on the order of 10s-100s of nanoseconds (per 14 nm PCM chip data)"], "limitations": ["Purely simulation-based (gem5-X full-system simulation); no silicon prototype of the tightly-coupled core", "AIMC tile power/performance figures are scaled analytically (5.3x / 2x factors) from a 14 nm chip measurement to match a 28 nm core/cache power model, introducing cross-technology-node approximation error", "Does not model device non-idealities (drift, noise, conductance variation) in the accuracy dimension — focuses on system-level timing/energy, not inference accuracy", "Workloads are relatively small/benchmark-style MLP, LSTM and CNN models rather than large-scale modern networks (no transformer workload)", "ISA extension and co-processor coupling is specific to ARMv8/gem5-X; portability to other ISAs or real silicon integration is not demonstrated"], "remarks": "This is a systems/architecture contribution rather than a device or algorithm paper: its main value for crossbar-mapping research is the full-system simulation methodology (gem5-X + ISA extension) that exposes communication/queueing overhead, not compute, as the bottleneck once AIMC removes the MVM cost — a finding relevant to anyone designing software stacks or compilers for AIMC-augmented CPUs. Evidence quality is moderate: the AIMC tile energy/latency numbers are grounded in real 14 nm PCM chip data (IBM) but the overall power model is a scaled composite across process nodes, so absolute numbers should be read as directional. Later work (cited by it is sparse; only one in-set citing paper, a 2025 software-stack survey) suggests it had modest direct follow-on in this corpus but situates well alongside PUMA/ISAAC-style loosely-coupled tile architectures as a tightly-coupled alternative.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog in-memory computing (AIMC) cores offers significant performance and energy benefits for neural network inference with respect to digital logic (e.g., CPUs). AIMCs accelerate matrix-vector multiplications, which dominate these applications' run-time. However, AIMC-centric platforms lack the flexibility of general-purpose systems, as they often have hard-coded data flows and can only support a limited set of processing functions. With the goal of bridging this gap in flexibility, we present a novel system architecture that tightly integrates analog in-memory computing accelerators into multi-core CPUs in general-purpose systems. We developed a powerful gem5-based full system-level simulation framework into the gem5-X simulator, ALPINE, which enables an in-depth characterization of the proposed architecture. ALPINE allows the simulation of the entire computer architecture stack from major hardware components to their interactions with the Linux OS. Within ALPINE, we have defined a custom ISA extension and a software library to facilitate the deployment of inference models. We showcase and analyze a variety of mappings of different neural network types, and demonstrate up to 20.5x/20.8x performance/energy gains with respect to a SIMD-enabled ARM CPU implementation for convolutional neural networks, multi-layer perceptrons, and recurrent neural networks.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2022_Klein_ALPINE_TC.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2022_Klein_ALPINE_TC.pdf", "priority": 5.28}, {"id": "W3191560475", "short": "FORMS", "title": "FORMS: Fine-grained Polarized ReRAM-based In-situ Computation for Mixed-signal DNN Accelerator", "authors": ["Geng Yuan", "Payman Behnam", "Zhengang Li", "Ali Reza Shafiee", "Sheng Lin", "Xiaolong Ma", "Hang Liu", "Xuehai Qian", "Mahdi Nazm Bojnordi", "Yanzhi Wang", "Caiwen Ding"], "year": 2021, "venue": "", "venue_short": "ISCA", "venue_full": "ACM/IEEE 48th International Symposium on Computer Architecture (ISCA 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/isca52012.2021.00029", "cites_global": 73, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "FORMS enforces same-sign weights within fine-grained crossbar sub-array fragments via ADMM-regularized training, avoiding the extra crossbar (PRIME) or offset circuitry (ISAAC) needed for signed weights, and combines this with structured pruning, quantization and zero-skipping to beat ISAAC by up to 377.9x in frame rate.", "summary": "ReRAM crossbars perform in-situ matrix-vector multiplication but can only hold same-sign weights per column, forcing prior designs to either duplicate crossbars for positive/negative weights (PRIME) or add offset-correction circuitry (ISAAC). FORMS instead partitions each crossbar column into small logical sub-array 'fragments' and uses ADMM-regularized training to force all weights within a fragment to share a single sign (or be pruned to zero), eliminating the need for extra crossbars or offset circuits. This fragment polarization is combined with crossbar-aware structured pruning and quantization in one ADMM optimization, and the small fragments additionally enable input zero-skipping to cut cycles further. Evaluated on LeNet5/VGG16/ResNet18/50 across MNIST, CIFAR-10/100 and ImageNet with a custom CACTI/NVSIM-based simulator, FORMS achieves large crossbar-reduction ratios (e.g., 185x on LeNet5, up to ~406x with aggressive settings) with no or minor accuracy loss, and at iso power/area with ISAAC delivers 1.50x/1.93x peak throughput per mm^2/W and 1.12x-2.4x (full optimization: 10.7x-377.9x) frames-per-second speedup over ISAAC.", "contributions": ["Fragment polarization: a fine-grained scheme that forces all weights in a crossbar sub-array column (fragment) to share one sign, removing the need for a second crossbar or offset-correction circuits", "A unified ADMM-regularized training procedure that jointly performs crossbar-aware structured pruning, fragment polarization, and quantization", "Exploits the small fragment granularity to enable input zero-skipping in the analog domain, reducing ADC/cycle overhead", "A custom architecture (sign-indicator arrays, modified MCU pipeline) built to be iso-power/area with ISAAC for fair comparison", "Extensive evaluation across 5 datasets/6 networks plus a device-variation robustness study"], "claims": [{"claim": "FORMS achieves large crossbar reduction with no/minor accuracy loss relative to ISAAC-style mapping", "support": "185.44x crossbar reduction on LeNet5/MNIST with only 0.14% accuracy drop; 406.8x on VGG16/CIFAR-10", "loc": "Sec. V-A, Table I"}, {"claim": "FORMS improves peak throughput per area and per power over ISAAC and DaDianNao at iso power/area", "support": "1.50x and 1.93x improvement in GOPs/(s*mm^2) and GOPs/W vs ISAAC (fragment 16, full optimization: 36.02x-39.48x and 27.73x-51.26x normalized to ISAAC baseline)", "loc": "Sec. V-C, Table V"}, {"claim": "Combining pruning/quantization/polarization/zero-skipping gives large end-to-end frame-rate speedups", "support": "10.7x up to 377.9x fps speedup over non-pruned ISAAC-32 depending on network/dataset/fragment size", "loc": "Sec. V-D, Fig. 13-14"}, {"claim": "FORMS can be built with nearly the same area/power footprint as ISAAC", "support": "0.08% more power and 4.5% more area than ISAAC chip-wide (Table IV)", "loc": "Sec. V-B, Table III-IV"}, {"claim": "Fragment polarization/quantization/zero-skipping do not worsen robustness to ReRAM device variation, but pruning does", "support": "Under lognormal variation (0 mean, 0.1 std), ResNet18/ImageNet accuracy degradation goes from 2.87% (original) to 2.86% (polarization only) but 4.24% with pruning", "loc": "Sec. V-E, Table VI"}], "results": ["185.44x crossbar reduction on LeNet5/MNIST (vs 4.2x for GroupScissor) with 0.14% accuracy drop (8-bit, fragment 16)", "Up to 406.8x crossbar reduction on VGG16/CIFAR-10 with <1% accuracy drop", "1.50x throughput/mm^2 and 1.93x throughput/W vs ISAAC at iso power/area (polarization+pruning+quantization, fragment 16)", "10.7x to 377.9x frame-per-second speedup over non-pruned ISAAC-32 across networks/datasets (fragment size 8, full optimization)", "FORMS chip-wide power/area within 0.08%/4.5% of ISAAC (Table IV)", "Accuracy degradation under 0.1-std lognormal device variation stays close to baseline for polarization/quantization/zero-skipping (e.g. 2.86% vs 2.87% original on ResNet18/ImageNet) but worsens with pruning (4.24%)"], "limitations": ["Evaluation is simulation-based (in-house CACTI/NVSim-derived simulator), not silicon-measured", "Uses 2-bit ReRAM cells and 8-bit weights/16-bit activations; higher-precision or analog-domain-only workloads not explored", "No transformer/LLM workloads evaluated — only CNNs (LeNet5, VGG16, ResNet18/50)", "Pruning measurably reduces robustness to device variation, a tradeoff the paper acknowledges but does not fully resolve", "Comparisons rely on reimplementing/estimating ISAAC/PUMA/DaDianNao parameters rather than independent third-party verification"], "remarks": "FORMS is a solid algorithm/hardware co-design paper that directly targets a real ISAAC/PRIME weakness (signed-weight representation) with a simple, elegant idea — enforce same-sign fragments via ADMM — rather than adding more peripheral circuitry. The claimed gains are large and stack multiple orthogonal techniques (pruning, quantization, polarization, zero-skipping), so care is needed attributing credit to polarization alone (its standalone contribution is more modest, ~1.5-1.9x). As with most crossbar accelerator papers of this era, results rest on simulation with assumed variation models rather than fabricated silicon. It is a frequently-cited reference point for later ADC/sparsity-aware accelerator work (e.g., RAELLA, ReHarvest) and is itself a direct descendant of ISAAC/PRIME/TinyADC in this collection.", "basis": "full-text", "pdf_source_url": "", "abstract": "Recent work demonstrated the promise of using resistive random access memory (ReRAM) as an emerging technology to perform inherently parallel analog domain in-situ matrix-vector multiplication—the intensive and key computation in deep neural networks (DNNs). One key problem is the weights that are signed values. However, in a ReRAM crossbar, weights are stored as conductance of the crossbar cells, and the in-situ computation assumes all cells on each crossbar column are of the same sign. The current architectures either use two ReRAM crossbars for positive and negative weights (PRIME), or add an offset to weights so that all values become positive (ISAAC). Neither solution is ideal: they either double the cost of crossbars, or incur extra offset circuity. To better address this problem, we propose FORMS, a fine-grained ReRAM-based DNN accelerator with algorithm/hardware co-design. Instead of trying to represent the positive/negative weights, our key design principle is to enforce exactly what is assumed in the in-situ computation— ensuring that all weights in the same column of a crossbar have the same sign. It naturally avoids the cost of an additional crossbar. Such polarized weights can be nicely generated using alternating direction method of multipliers (ADMM) regularized optimization during the DNN training, which can exactly enforce certain patterns in DNN weights. To achieve high accuracy, we divide the crossbar into logical sub-arrays and only enforce this property within the fine-grained sub-array columns. Crucially, the small sub-arrays provides a unique opportunity for input zero-skipping, which can significantly avoid unnecessary computations and reduce computation time. At the same time, it also makes the hardware much easier to implement and is less susceptible to non-idealities and noise than coarse-grained architectures. Putting all together, with the same optimized DNN models, FORMS achieves 1.50× and 1.93× throughput improvement in terms of $\\frac{{GOPs}}{{s \\times m{m^2}}}$ and $\\frac{{GOPs}}{W}$ compared to ISAAC, and 1.12× ~2.4 × speed up in terms of frame per second over optimized ISAAC with almost the same power/area cost. Interestingly, FORMS optimization framework can even speed up the original ISAAC from 10.7 × up to 377.9×, reflecting the importance of software/hardware co-design optimizations.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2021_Yuan_FORMS_ISCA.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2021_Yuan_FORMS_ISCA.pdf", "priority": 8.24}, {"id": "W3212662098", "short": "BRAHMS", "title": "BRAHMS: Beyond Conventional RRAM-based Neural Network Accelerators Using Hybrid Analog Memory System", "authors": ["Tao Song", "Xiaoming Chen", "Xiaoyu Zhang", "Yinhe Han"], "year": 2021, "venue": "", "venue_short": "DAC", "venue_full": "ACM/IEEE 58th Design Automation Conference (DAC 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/dac18074.2021.9586247", "cites_global": 15, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "BRAHMS eliminates redundant analog-to-digital conversions in RRAM-based CNN accelerators by fusing post-MAC operations (shift-add, pooling, activation, etc.) into analog resistive content-addressable memory (ARCAM) arrays, reporting several-fold throughput and >10x energy-efficiency gains over an ISAAC-like baseline.", "summary": "The paper targets the ADC/DAC overhead in conventional RRAM-based CNN accelerators, observing that many AD conversions performed after a crossbar MAC are redundant because the result is immediately fed into further arithmetic (e.g., shift-and-add across bit-sliced partial sums, or pooling/activation). It proposes BRAHMS, which reorders operations following a convolutional or fully-connected layer and groups them into 'fused operators' (FOPs) that are executed as a whole inside analog resistive content-addressable memory (ARCAM) arrays rather than through digital logic and ADCs. The resulting architecture is a mixed-signal pipeline that keeps signals in the analog domain within an FOP and only converts to digital between FOPs, reducing conversion counts while reusing RRAM crossbars for both matrix-vector multiplication and the fused post-processing operators. Compared with an ISAAC-like baseline architecture, simulation results show BRAHMS improves performance by several times and average energy efficiency by over 10x.", "contributions": ["Identifies redundant analog-to-digital conversions as a major inefficiency in conventional RRAM-based CNN accelerators", "Proposes 'fused operators' (FOPs) that reorder and merge post-MAC operations (e.g., shift-add, pooling) to avoid unnecessary AD/DA conversions", "Introduces analog resistive content-addressable memory (ARCAM) arrays as the hardware substrate implementing FOPs without digital logic or ADCs", "Designs a mixed-signal pipeline (BRAHMS) that keeps data analog within an FOP and digital only between FOPs", "Reports simulation-based performance and energy comparisons against an ISAAC-like RRAM CNN accelerator baseline"], "claims": [{"claim": "Conventional RRAM-based CNN accelerators perform redundant analog-to-digital conversions that waste energy", "support": "Abstract: conventional mixed-signal accelerators use DACs/ADCs that cause performance and energy efficiency degradation; BRAHMS eliminates 'redundant AD conversions'", "loc": "Abstract"}, {"claim": "Fusing post-MAC operations into ARCAM arrays removes the need for digital logic and ADCs within a fused operator", "support": "Abstract: FOPs 'are implemented as a whole by ARCAM arrays so that digital logic and ADCs are eliminated'", "loc": "Abstract"}, {"claim": "BRAHMS substantially outperforms an ISAAC-like RRAM CNN accelerator", "support": "Abstract: 'compared with an ISAAC-like architecture, BRAHMS improves the performance by several times and the energy efficiency by 10+ times on average'", "loc": "Abstract"}], "results": ["Several-times performance (throughput) improvement over an ISAAC-like RRAM-based CNN accelerator baseline (abstract-level figure, no further breakdown available)", "Average energy efficiency improvement of >10x over the ISAAC-like baseline (abstract-level figure)"], "limitations": ["Only the abstract was available for this analysis (paper is paywalled, no open-access copy found); quantitative claims beyond the abstract (architectural details, benchmarks used, array sizes) could not be verified", "Evaluation is simulation-based; no silicon measurements are reported in the abstract", "Scope is limited to CNNs (convolutional/fully-connected layers); applicability to other workloads (RNN/Transformer) is not indicated"], "remarks": "Abstract-only analysis: BRAHMS belongs to the line of work (alongside CASCADE, Neural-PIM, TinyADC) attacking ADC/DAC overhead in RRAM crossbar accelerators, here via a content-addressable-memory-based analog fusion of post-MAC operators rather than ADC-resolution reduction or peripheral-circuit-aware pruning. Because no full text was accessible, the strength of evidence and the precise mechanism of ARCAM fused operators cannot be independently verified beyond what the abstract states; the reported '10+x' energy efficiency gain should be treated as a headline claim pending verification against the full paper.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Accelerating convolutional neural networks (CNNs) with resistive random-access memory (RRAM) based processing-in-memory systems has been recognized as a promising approach. However, conventional accelerators are usually mixed-signal circuits with digital-to-analog converters (DACs) and analog-to-digital converters (ADCs), which cause performance and energy efficiency degradation. In this work, we first analyze the problems in existing RRAM-based CNN accelerators and point out that there are redundant analog-to-digital (AD) conversions. To eliminate redundant AD conversions and also reduce AD conversion overhead, we propose the BRAHMS architecture, which is an RRAM-based CNN accelerator composed of reconfigurable RRAM crossbars and analog resistive content-addressable memory (ARCAM) arrays. We reorder the operations after a convolutional or fully-connected layer and form fused operators (FOPs), which are implemented as a whole by ARCAM arrays so that digital logic and ADCs are eliminated. BRAHMS realizes a mixed-signal pipeline which transmits data signals in the analog domain within an FOP and in the digital domain between FOPs to obtain high performance and energy efficiency. Detailed simulation results show that compared with an ISAAC-like architecture, BRAHMS improves the performance by several times and the energy efficiency by 10 + times on average.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2021_Song_BRAHMS_DAC.pdf", "analysed": true, "pdf": null, "priority": 6.87}, {"id": "W3042493405", "short": "TIMELY", "title": "Timely: Pushing Data Movements And Interfaces In Pim Accelerators Towards Local And In Time Domain", "authors": ["Weitao Li", "Pengfei Xu", "Yang Katie Zhao", "Haitong Li", "Yuan Xie", "Yingyan Lin"], "year": 2020, "venue": "", "venue_short": "ISCA", "venue_full": "ACM/IEEE 47th Annual International Symposium on Computer Architecture (ISCA 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/isca45697.2020.00073", "cites_global": 86, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet", "MLP"], "evidence": "simulation", "tldr": "TIMELY attacks the input/partial-sum movement and DAC/ADC bottlenecks of ReRAM PIM with analog local buffers between crossbars, time-domain (DTC/TDC) interfaces and an only-once-input-read mapping, reaching 21 TOPs/W (8-bit) peak and on average 10x/14.8x higher energy efficiency than PRIME/ISAAC in simulation.", "summary": "The paper observes that even with stationary weights, ReRAM PIM accelerators spend most energy on input and partial-sum (Psum) movement (up to 83% in PRIME) and on DAC/ADC interfaces (>61% in ISAAC). TIMELY organizes crossbars into sub-Chips where inputs are converted once by 8-bit DTCs into time-domain pulses and passed between horizontally adjacent crossbars through analog X-subBufs, while Psum currents from vertically stacked crossbars are buffered in P-subBufs, summed in an I-adder, integrated on a capacitor with a 2-phase charging scheme and converted once by a TDC; 8-bit weights are split into MSB/LSB 4-bit columns (sub-ranging). The O2IR mapping places filters sharing inputs in parallel columns, duplicates filters with a vertical Z x S offset, and shifts inputs horizontally between X-subBufs so every input is read from L1 only once; layers are mapped layer-by-layer onto sub-Chips with inter- and intra-sub-Chip pipelining. Evaluated with an in-house simulator (validated to 8% energy error vs PRIME's simulator; 65nm, 40 MHz) on 1 MLP and 13 CNNs, TIMELY improves energy efficiency, computational density and throughput substantially over PRIME, ISAAC, PipeLayer and AtomLayer, with <=0.1% accuracy loss when Monte-Carlo circuit noise is injected during training.", "contributions": ["Analog local buffers (X-subBufs for inputs, P-subBufs for Psums) inside the crossbar fabric to keep data movement local and analog.", "Time-domain interfaces (DTC/TDC) replacing DAC/ADC, with one conversion per sub-Chip row/column instead of per crossbar.", "Only-once input read (O2IR) weight-mapping method exploiting the three CNN input-reuse patterns via parallel filter mapping, shifted filter duplication and inter-buffer input shifting.", "Full architecture with inter/intra-sub-Chip pipelining, evaluated on >10 CNN/DNN models with energy/area ablations and a demonstration that ALB+O2IR also helps PRIME (-68% intra-bank data-movement energy)."], "claims": [{"claim": "Data movement and interfaces, not MACs, dominate ReRAM-PIM energy.", "support": "Input/Psum movement up to 83% of energy in PRIME; DAC/ADC >61% in ISAAC.", "loc": "Sec. I, Fig. 4"}, {"claim": "TIMELY improves peak energy efficiency and computational density over prior ReRAM PIM accelerators.", "support": "21.00 TOPs/W and 38.33 TOPs/(s mm2) at 8-bit; 6.90 TOPs/W and 9.58 TOPs/(s mm2) at 16-bit: +10.0x/+31.2x vs PRIME, +18.2x/+20.0x vs ISAAC, +49.3x/+6.4x vs PipeLayer, +10.1x/+20.0x vs AtomLayer.", "loc": "Table IV"}, {"claim": "Gains generalize across CNN/DNN models.", "support": "On average 10x and 14.8x more energy efficient than PRIME and ISAAC (geomean over 1 MLP + 13 CNNs); gains shrink for compact models like SqueezeNet/CNN-1.", "loc": "Sec. VI-B, Fig. 8(a)"}, {"claim": "ALB and O2IR provide almost all the savings; TDI contributes little energy but saves area.", "support": "ALB+O2IR contribute up to 99% of energy savings on VGG-D, TDI ~1%; memory-access energy reduced 93% vs PRIME; Psum/input/output movement energy reduced 99.9%/95.8%/87.1%.", "loc": "Sec. VI-C, Fig. 9"}, {"claim": "Analog buffering and time-domain signaling do not hurt accuracy.", "support": "<=0.1% inference accuracy loss in system-level simulation with Cadence Monte-Carlo noise/PVT errors injected during training; cascaded X-subBufs limited to 12.", "loc": "Sec. VI-B 'Accuracy', Sec. V"}], "results": ["Peak 21.00 TOPs/W (8-bit MAC) vs PRIME 2.10 TOPs/W; 6.90 TOPs/W (16-bit) vs ISAAC 0.38 and PipeLayer 0.14 TOPs/W", "Computational density 38.33 TOPs/(s mm2) (8-bit), up to 31.2x over PRIME and 6.4x over PipeLayer", "Throughput up to 736.6x over PRIME (VGG-D) and on average 2.1x/2.4x/2.7x over ISAAC for 16/32/64-chip configurations", "15.6x energy efficiency vs PRIME on VGG-D; ReRAM array area fraction 2.2% vs 0.4% in ISAAC", "Applying ALB+O2IR to PRIME reduces intra-bank data-movement energy by 68%"], "limitations": ["Simulation only (in-house simulator validated against PRIME's simulator with 8% energy error); baseline peak numbers taken from the original papers.", "Accuracy analysis relies on Gaussian circuit-noise injection and noise-aware training; ReRAM device variation, IR drop and drift are not modeled in depth.", "Time-domain signaling limits speed (40 MHz clock, 25 ns DTC/TDC conversions) and requires careful bounding of cascaded buffer error.", "O2IR's shifted filter duplication increases ReRAM usage; analysis focuses on CNN convolutions, not Transformers or RNNs.", "Inference only, 4-bit cells assumed with MSB/LSB sub-ranging for 8-bit weights."], "remarks": "TIMELY is an influential example of shifting the optimization target from the MAC array to the data-movement and conversion periphery, and its O2IR scheme is a concrete crossbar mapping strategy that couples dataflow with weight duplication. Its headline numbers are relative to PRIME/ISAAC-era baselines with expensive SRAM/eDRAM hierarchies and are entirely simulated; the robustness of long analog/time-domain chains to real device and PVT variation remains the main open question. It extends the analog-buffer idea of CASCADE (which it explicitly contrasts with) and was later compared against by FORMS and other mixed-signal designs.", "basis": "full-text", "pdf_source_url": "", "abstract": "Resistive-random-access-memory (ReRAM) based processing-in-memory (R2PIM) accelerators show promise in bridging the gap between Internet of Thing devices' constrained resources and Convolutional/Deep Neural Networks' (CNNs/DNNs') prohibitive energy cost. Specifically, R2PIM accelerators enhance energy efficiency by eliminating the cost of weight movements and improving the computational density through ReRAM's high density. However, the energy efficiency is still limited by the dominant energy cost of input and partial sum (Psum) movements and the cost of digital-to-analog (D/A) and analog-to-digital (A/D) interfaces. In this work, we identify three energy-saving opportunities in R2PIM accelerators: analog data locality, time-domain interfacing, and input access reduction, and propose an innovative R2PIM accelerator called TIMELY, with three key contributions: (1) TIMELY adopts analog local buffers (ALBs) within ReRAM crossbars to greatly enhance the data locality, minimizing the energy overheads of both input and Psum movements; (2) TIMELY largely reduces the energy of each single D/A (and A/D) conversion and the total number of conversions by using time-domain interfaces (TDIs) and the employed ALBs, respectively; (3) we develop an only-once input read (O2IR) mapping method to further decrease the energy of input accesses and the number of D/A conversions. The evaluation with more than 10 CNN/DNN models and various chip configurations shows that, TIMELY outperforms the baseline R2PIM accelerator, PRIME, by one order of magnitude in energy efficiency while maintaining better computational density (up to 31.2×) and throughput (up to 736.6×). Furthermore, comprehensive studies are performed to evaluate the effectiveness of the proposed ALB, TDI, and O2IR in terms of energy savings and area reduction.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2020_Li_TIMELY_ISCA.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2020_Li_TIMELY_ISCA.pdf", "priority": 7.79}, {"id": "W2913104037", "short": "PUMA", "title": "PUMA", "authors": ["Aayush Ankit", "Izzat El Hajj", "Sai Rahul Chalamalasetti", "Geoffrey Ndu", "Martin Foltín", "Richard Stanley Williams", "Paolo Faraboschi", "Wen‐mei Hwu", "John Paul Strachan", "Kaushik Roy", "Dejan S. Milojicic"], "year": 2019, "venue": "", "venue_short": "ASPLOS", "venue_full": "24th International Conference on Architectural Support for Programming Languages and Operating Systems (ASPLOS '19), ACM", "venue_ok": true, "doi": "https://doi.org/10.1145/3297858.3304049", "cites_global": 422, "cat": "03", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["CNN", "MLP", "LSTM/RNN"], "evidence": "simulation", "tldr": "PUMA is the first ISA-programmable memristor-crossbar inference accelerator (spatial cores with crossbar MVM units, vector FUs, ROM-embedded RAM, and a compiler), reaching 837 GOPS/s/W and up to 2,446x energy / 66x latency improvement vs GPUs at only ~20-30% efficiency loss vs ISAAC.", "summary": "Prior memristor accelerators (ISAAC, PRIME, PipeLayer) are state-machine-configured for one or two network types and lack the vector/transcendental ops and flexible data movement needed by e.g. LSTMs. PUMA is a spatial node-tile-core hierarchy in which each core has an in-order instruction pipeline, several 128x128 memristive MVM units (16-bit MVMs built from eight 2-bit-per-cell crossbars via ISAAC-style bit slicing, with shared ADCs), a temporal-SIMD vector functional unit, and ROM-embedded RAM for transcendental lookups; tiles communicate via shared memory with attribute-tagged synchronization and receive FIFOs. A C++/ONNX runtime compiler tiles weight tensors into MVMU-sized blocks, hierarchically partitions the graph to MVMUs/cores/tiles, schedules instructions (MVM coalescing, deadlock avoidance) and allocates registers. Using the PUMAsim simulator (32nm, 1 GHz, ISAAC-derived crossbar/ADC models) on MLPs, deep/wide LSTMs (up to BigLSTM ~800M synapses) and VGG CNNs, PUMA shows large energy and latency gains over CPUs/GPUs/TPU, with the largest gains on weight-heavy, low-reuse LSTMs.", "contributions": ["Programmable hybrid CMOS-memristor spatial architecture with a specialized 7-byte-wide ISA (MVM, vector ALU, transcendental, load/store, send/receive, control).", "Core microarchitecture balancing crossbar MVMUs against digital VFUs and ROM-embedded RAM so programmability does not erase crossbar efficiency.", "Compiler that partitions large computational graphs across thousands of spatial cores, with instruction scheduling and register allocation; ONNX bindings.", "Open-sourced cycle-level simulator (PUMAsim) with functionality, timing and power models.", "Evaluation vs CPUs, GPUs, TPU and ISAAC, plus design-space exploration and a write-noise/bit-precision accuracy study."], "claims": [{"claim": "PUMA delivers order-of-magnitude energy and latency gains over GPUs for memory-bound workloads.", "support": "Energy reduction over Pascal: CNNs 11.7-13.0x, MLPs 30.2-80.1x, Deep LSTMs 2,302-2,446x, Wide LSTMs 758-1336x; latency improvement for Deep LSTMs 41.6-66.0x.", "loc": "Sec. 7.1-7.2, Fig. 11"}, {"claim": "Programmability costs only modest efficiency relative to an application-specific memristor accelerator.", "support": "PUMA has 20.7% lower power efficiency and 29.2% lower area efficiency than ISAAC (0.84 vs 1.06 TOPS/s/W; 0.58 vs 0.82 TOPS/s/mm2).", "loc": "Sec. 7.4.2, Table 6"}, {"claim": "Analog MVMUs are essential to the efficiency.", "support": "A digital MVMU would need 8.97x area and 4.17x energy for the same latency; whole chip 4.93x area and 6.76x energy.", "loc": "Sec. 7.4.3"}, {"claim": "PUMA beats the TPU in efficiency, especially for low-reuse workloads.", "support": "8.3x higher peak area efficiency and 1.65x higher peak power efficiency than TPU; 64.4x, 193x, 9.7x higher area efficiency for MLP, LSTM, CNN.", "loc": "Sec. 7.4.1, Table 6"}, {"claim": "Conservative 2-bit cells keep inference accurate under write noise.", "support": "PUMA with 2-bit memristors performs well even at high write-noise levels (sigma_N up to 0.3); higher bits per cell lose more accuracy.", "loc": "Sec. 7.6, Fig. 13"}], "results": ["Peak 577 GOPS/s/mm2 and 837 GOPS/s/W at 1 GHz (32nm); 90.6 mm2, 62.5 W node storing up to 69 MB of weights", "Up to 2,446x energy and 66x latency improvement vs state-of-the-art GPUs", "CNNs: only 11.7-13.0x energy and 2.73-2.99x latency improvement over Pascal; MLPs show 0.24-0.40x (slowdown) latency vs Pascal", "vs ISAAC: 20.7% lower power efficiency, 29.2% lower area efficiency", "vs TPU: 8.3x peak area efficiency, 1.65x peak power efficiency"], "limitations": ["Simulation only (PUMAsim); crossbar and ADC energy/area models largely adapted from ISAAC.", "Accuracy study uses a simple write-noise model; IR drop, drift, ADC non-linearity and device variation largely ignored; 16-bit fixed point assumed to preserve accuracy.", "Requires the whole model to fit on-chip (spatial, weight-stationary); no evaluation of models exceeding capacity or crossbar rewriting.", "No attention/Transformer workloads; MLP latency worse than GPUs."], "remarks": "PUMA is the reference point for programmable, compiler-driven crossbar accelerators: its node/tile/core/MVMU hierarchy, graph partitioning into crossbar-sized blocks and ISA were reused by later compilers and by IBM/HPE-style heterogeneous designs. The evidence is entirely simulated and inherits ISAAC's optimistic peripheral assumptions, so its absolute numbers should be treated as upper bounds. For model-to-crossbar mapping, its main lesson is that partitioning must co-optimize MVMU placement with intra-layer (partial-sum) and inter-layer data movement, as seen in the deep-vs-wide LSTM gap.", "basis": "full-text", "pdf_source_url": "", "abstract": "Memristor crossbars are circuits capable of performing analog matrix-vector multiplications, overcoming the fundamental energy efficiency limitations of digital logic. They have been shown to be effective in special-purpose accelerators for a limited set of neural network applications. We present the Programmable Ultra-efficient Memristor-based Accelerator (PUMA) which enhances memristor crossbars with general purpose execution units to enable the acceleration of a wide variety of Machine Learning (ML) inference workloads. PUMA's microarchitecture techniques exposed through a specialized Instruction Set Architecture (ISA) retain the efficiency of in-memory computing and analog circuitry, without compromising programmability. We also present the PUMA compiler which translates high-level code to PUMA ISA. The compiler partitions the computational graph and optimizes instruction scheduling and register allocation to generate code for large and complex workloads to run on thousands of spatial cores. We have developed a detailed architecture simulator that incorporates the functionality, timing, and power models of PUMA's components to evaluate performance and energy consumption. A PUMA accelerator running at 1 GHz can reach area and power efficiency of 577 GOPS/s/mm 2 and 837~GOPS/s/W, respectively. Our evaluation of diverse ML applications from image recognition, machine translation, and language modelling (5M-800M synapses) shows that PUMA achieves up to 2,446× energy and 66× latency improvement for inference compared to state-of-the-art GPUs. Compared to an application-specific memristor-based accelerator, PUMA incurs small energy overheads at similar inference latency and added programmability.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2019_Ankit_PUMA_ASPLOS.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2019_Ankit_PUMA_ASPLOS.pdf", "priority": 10.05}, {"id": "W2949989598", "short": "FloatPIM", "title": "FloatPIM", "authors": ["Mohsen Imani", "Saransh Gupta", "Yeseong Kim", "Tajana Rosing"], "year": 2019, "venue": "", "venue_short": "DAC", "venue_full": "ACM/IEEE Design Automation Conference (DAC 2019)", "venue_ok": true, "doi": "https://doi.org/10.1145/3307650.3322237", "cites_global": 190, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "FloatPIM is a fully-digital ReRAM-based processing-in-memory architecture that performs bitwise NOR-logic floating-point arithmetic directly in memristor crossbars, avoiding ADC/DAC and the fixed-point precision limits of analog PIM accelerators.", "summary": "The paper argues that analog PIM accelerators (ISAAC, PRIME) are limited to low fixed-point precision and burn most of their area/power on ADC/DAC blocks, which also prevents accurate floating-point CNN training in memory. FloatPIM instead stores operands in a ReRAM crossbar and implements addition/multiplication as sequences of in-memory NOR operations, natively supporting floating-point representation entirely in the digital domain. A fast inter-block data transfer/switch mechanism moves data between neighboring memory blocks to reduce the internal data-movement bottleneck common to PIM designs. The design is evaluated on large-scale CNNs on ImageNet, comparing training throughput/energy against a GTX 1080 GPU and PipeLayer, and inference against GPU and ISAAC.", "contributions": ["A fully-digital, bit-serial PIM architecture (FloatPIM) that performs floating-point CNN training and inference using in-memristor NOR logic, with no ADC/DAC", "Native floating-point support in memory, avoiding the fixed-point-induced accuracy loss of prior analog crossbar PIM accelerators", "A row-parallel floating-point arithmetic scheme and an inter-block switch mechanism to reduce internal data movement", "System-level evaluation on ImageNet-scale CNNs comparing training/testing speed and energy against GPU, PipeLayer, and ISAAC"], "claims": [{"claim": "Floating-point precision in PIM improves accuracy over fixed-point PIM designs", "support": "up to 5.1% higher classification accuracy vs. existing fixed-point PIM architectures", "loc": "Abstract"}, {"claim": "FloatPIM training is substantially faster and more energy-efficient than GPU and analog PIM accelerators", "support": "303.2x and 48.6x faster/more energy efficient than GTX 1080 GPU, 4.3x and 15.8x vs. PipeLayer, for training", "loc": "Abstract"}, {"claim": "FloatPIM inference/testing also outperforms GPU and ISAAC", "support": "324.8x and 297.9x speedup/energy efficiency vs. GPU, 6.3x and 21.6x vs. ISAAC", "loc": "Abstract, Sec. 4 (Conclusion/Results)"}, {"claim": "Even without the inter-block parallel data-transfer switches, FloatPIM still beats the analog ISAAC baseline", "support": "1.7x speedup and 3.9x energy efficiency vs. ISAAC with no in-parallel data transfer", "loc": "Sec. 4 (results discussion)"}], "results": ["Up to 5.1% higher classification accuracy using floating-point vs. fixed-point PIM representation", "Training: 303.2x speedup / 48.6x energy efficiency vs. GTX 1080 GPU; 4.3x / 15.8x vs. PipeLayer", "Testing: 324.8x speedup / 297.9x energy efficiency vs. GPU; 6.3x / 21.6x vs. ISAAC"], "limitations": ["Purely simulation-based evaluation; no silicon or device-level validation of the ReRAM NOR-logic PIM", "Digital bitwise in-memory operations are inherently slower per-operation than CMOS logic, relying on massive row-level parallelism to win overall", "Comparisons are made against specific baselines (GPU, PipeLayer, ISAAC) using the authors' own simulators, which can favor the proposed design", "Scalability of the inter-block switch network and its overhead at very large array counts is not deeply analyzed"], "remarks": "FloatPIM is a useful counterpoint in the crossbar-mapping literature: rather than exploiting ReRAM's analog conductance for MAC (as ISAAC/PRIME do), it uses ReRAM purely as digital bit-cells for NOR-based bulk logic, trading analog efficiency for full floating-point precision and removing ADC/DAC overhead entirely. This makes it architecturally closer to bit-wise PIM/DRAM-logic accelerators than to analog crossbar accelerators, despite sharing the 'ReRAM PIM' label. Later ADC-aware and mixed digital/analog designs implicitly respond to the precision-vs-efficiency tradeoff FloatPIM highlights.", "basis": "full-text", "pdf_source_url": "", "abstract": "Processing In-Memory (PIM) has shown a great potential to accelerate inference tasks of Convolutional Neural Network (CNN). However, existing PIM architectures do not support high precision computation, e.g., in floating point precision, which is essential for training accurate CNN models. In addition, most of the existing PIM approaches require analog/mixed-signal circuits, which do not scale, exploiting insufficiently reliable multi-bit Non-Volatile Memory (NVM). In this paper, we propose FloatPIM, a fully-digital scalable PIM architecture that accelerates CNN in both training and testing phases. FloatPIM natively supports floating-point representation, thus enabling accurate CNN training. FloatPIM also enables fast communication between neighboring memory blocks to reduce internal data movement of the PIM architecture. We evaluate the efficiency of FloatPIM on ImageNet dataset using popular large-scale neural networks. Our evaluation shows that FloatPIM supporting floating point precision can achieve up to 5.1% higher classification accuracy as compared to existing PIM architectures with limited fixed-point precision. FloatPIM training is on average 303.2× and 48.6× (4.3× and 15.8×) faster and more energy efficient as compared to GTX 1080 GPU (PipeLayer [1] PIM accelerator). For testing, FloatPIM also provides 324.8× and 297.9× (6.3× and 21.6×) speedup and energy efficiency as compared to GPU (ISAAC [2] PIM accelerator) respectively.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2019_Imani_FloatPIM_DAC.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2019_Imani_FloatPIM_DAC.pdf", "priority": 7.59}, {"id": "W2979663695", "short": "CASCADE", "title": "CASCADE", "authors": ["Teyuh Chou", "Wei Tang", "Jacob Botimer", "Zhengya Zhang"], "year": 2019, "venue": "", "venue_short": "MICRO", "venue_full": "ACM/IEEE 52nd Annual International Symposium on Microarchitecture (MICRO 2019)", "venue_ok": true, "doi": "https://doi.org/10.1145/3352460.3358328", "cites_global": 89, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "LSTM/RNN"], "evidence": "simulation", "tldr": "CASCADE connects RRAM MAC-crossbar arrays with dedicated RRAM buffer arrays so that partial-sum buffering and accumulation for a full DNN/RNN layer happen in the analog domain, cutting the number of costly A/D conversions and improving energy efficiency by 3.5x over prior in-RRAM accelerators.", "summary": "The paper targets the cost of multibit analog-to-digital (A/D) conversion in resistive-RAM (RRAM) processing-in-memory accelerators, which can erode the efficiency gains of in-memory dot products. CASCADE extends the analog dataflow beyond the dot-product step by cascading MAC RRAM crossbar arrays with separate RRAM buffer arrays, so that partial sums produced by one array are accumulated in the analog domain in the buffer arrays before conversion, rather than being digitized after every array. A new memory-mapping scheme, R-Mapping, is devised to enable in-RRAM accumulation of partial sums, together with an analog summation scheme that reduces the number of required A/D conversions. The interface between MAC and buffer arrays is designed to keep the extended analog dataflow variation-tolerant. CASCADE is evaluated against recent in-RRAM computation architectures on state-of-the-art DNN and RNN benchmarks.", "contributions": ["A cascaded RRAM architecture connecting MAC crossbar arrays to dedicated RRAM buffer arrays to extend processing in the analog domain beyond the dot product", "R-Mapping: a memory-mapping scheme enabling in-RRAM accumulation of partial sums across arrays", "An analog summation scheme that reduces the number of A/D conversions needed to obtain a layer's final output", "A variation-tolerant interface/dataflow design between MAC and buffer arrays, evaluated on DNN and RNN workloads against prior in-RRAM accelerators"], "claims": [{"claim": "Extending analog processing from dot-products to partial-sum accumulation improves energy efficiency over prior in-RRAM accelerators", "support": "CASCADE improves energy efficiency by 3.5x while maintaining competitive throughput compared with recent in-RRAM computation architectures", "loc": "Abstract"}], "results": ["3.5x energy-efficiency improvement over recent in-RRAM computation architectures while maintaining competitive throughput (per abstract; full paper not retrieved)"], "limitations": ["Analysis based on the abstract only; full methodology, non-ideality assumptions, and benchmark details could not be verified from the paper text", "As with most crossbar accelerator papers of this era, the evaluation is presumed architecture-level simulation rather than silicon measurement (unconfirmed from abstract alone)"], "remarks": "CASCADE's core idea -- keeping partial-sum accumulation analog via cascaded buffer arrays (R-Mapping) rather than converting to digital after every crossbar -- directly targets the well-known ADC-dominated energy/area bottleneck shared by ISAAC/PRIME-style accelerators, and is cited by later ADC-reduction and mixed analog/digital dataflow papers (e.g., Light-CIM, ReHarvest, CiMLoop) as a reference point for in-memory partial-sum accumulation. Because only the abstract could be verified here, the quantitative comparison basis (which baselines, which benchmarks) and non-ideality handling should be checked against the full MICRO 2019 paper before citing specifics beyond the headline 3.5x energy-efficiency figure.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Processing in memory (PIM) is a concept to enable massively parallel dot products while keeping one set of operands in memory. PIM is ideal for computationally demanding deep neural networks (DNNs) and recurrent neural networks (RNNs). Processing in resistive RAM (RRAM) is particularly appealing due to RRAM's high density and low energy. A key limitation of PIM is the cost of multibit analog-to-digital (A/D) conversions that can defeat the efficiency and performance benefits of PIM. In this work, we demonstrate the CASCADE architecture that connects multiply-accumulate (MAC) RRAM arrays with buffer RRAM arrays to extend the processing in analog and in memory: dot products are followed by partial-sum buffering and accumulation to implement a complete DNN or RNN layer. Design choices are made and the interface is designed to enable a variation-tolerant, robust analog dataflow. A new memory mapping scheme named R-Mapping is devised to enable the in-RRAM accumulation of partial sums; and an analog summation scheme is used to reduce the number of A/D conversions required to obtain the final sum. CASCADE is compared with recent in-RRAM computation architectures using state-of-the-art DNN and RNN benchmarks. The results demonstrate that CASCADE improves the energy efficiency by 3.5× while maintaining a competitive throughput.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2019_Chou_CASCADE_MICRO.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2019_Chou_CASCADE_MICRO.pdf", "priority": 7.97}, {"id": "W2996781237", "short": "ERA-LSTM", "title": "ERA-LSTM: An Efficient ReRAM-Based Architecture for Long Short-Term Memory", "authors": ["Jianhui Han", "He Liu", "Mingyu Wang", "Zhaolin Li", "Youhui Zhang"], "year": 2019, "venue": "IEEE Transactions on Parallel and Distributed Systems", "venue_short": "TPDS", "venue_full": "IEEE Transactions on Parallel and Distributed Systems (2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/tpds.2019.2962806", "cites_global": 36, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["LSTM/RNN"], "evidence": "simulation", "tldr": "ERA-LSTM uses ReRAM-based analog approximate computing for LSTM's element-wise operations alongside crossbar dot products, plus a multi-tile mapping scheme and crossbar-friendly pruning, to cut ADC demand and outperform FPGA- and ReRAM-based LSTM accelerators by up to 103.6x and 6.1x respectively.", "summary": "The paper targets the ADC overhead of ReRAM processing-in-memory LSTM accelerators, which dominates power consumption in prior designs that compute LSTM's element-wise (gate) operations digitally. Based on a dataflow analysis of the LSTM computation, ERA-LSTM proposes performing the element-wise computations using ReRAM-based analog approximate computing instead of digital logic, combined with the standard crossbar dot-product computation, in a unified LSTM processing tile that significantly reduces the number of ADCs required. The paper also presents a mapping scheme to deploy large-scale LSTM models across multiple processing tiles, and an architecture enhancement supporting crossbar-friendly LSTM pruning for further efficiency gains. A fine-tuning scheme and approximator design optimization are used to control the accuracy impact of the analog approximate element-wise computation and hardware constraints.", "contributions": ["Use of ReRAM-based analog approximate computing for LSTM's element-wise (gate) operations, integrated with crossbar dot-product computation in a single processing tile", "A significant reduction in required ADCs compared to prior ReRAM LSTM accelerators with digital element-wise computation", "A mapping scheme to deploy large-scale LSTM models efficiently across multiple processing tiles", "An architecture enhancement supporting crossbar-friendly LSTM pruning, with a fine-tuning scheme to recover accuracy lost to approximation and hardware constraints"], "claims": [{"claim": "ERA-LSTM substantially outperforms FPGA-based LSTM accelerators", "support": "outperforms two state-of-the-art FPGA-based LSTM accelerators by 103.6x and 35.9x, respectively", "loc": "Abstract"}, {"claim": "ERA-LSTM is more efficient than a prior ReRAM-based LSTM accelerator using digital element-wise computation", "support": "6.1x more efficient compared with a state-of-the-art ReRAM-based LSTM accelerator with digital element-wise computation", "loc": "Abstract"}, {"claim": "Fine-tuning and approximator design optimization mitigate the accuracy impact of hardware constraints and approximation errors", "support": "experiments demonstrate that the impact of hardware constraints and approximation errors on inference accuracy can be effectively reduced by the proposed fine-tuning scheme and by optimizing the design of the approximator", "loc": "Abstract"}], "results": ["103.6x and 35.9x efficiency improvement over two FPGA-based LSTM accelerators", "6.1x improvement in efficiency over a state-of-the-art ReRAM-based LSTM accelerator with digital element-wise computation"], "limitations": ["Analysis based on the abstract only; details of the approximate computing error model, ADC reduction factor, and benchmark LSTM sizes could not be verified from the full text", "Analog approximate computing for element-wise operations inherently trades some numerical accuracy for efficiency, requiring fine-tuning to recover accuracy (extent not independently verifiable here)"], "remarks": "ERA-LSTM is a relevant data point for RNN/LSTM-specific crossbar mapping: unlike CNN-focused accelerators (ISAAC, PRIME), it explicitly tackles the element-wise (sigmoid/tanh-gated) operations that dominate LSTM's non-MAC compute, using ReRAM analog approximation to avoid a second round of digital logic and ADC conversions. Because only the abstract was available, the specific approximate-computing technique, fine-tuning procedure, and quantitative accuracy loss figures should be checked against the full TPDS paper before being cited beyond the headline speedup numbers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Processing-in-memory (PIM) architecture based on resistive random access memory (ReRAM) crossbars is a promising solution to the memory bottleneck that long short-term memory (LSTM) faces. Based on the dataflow analysis of the LSTM computing paradigm, this article proposes to adopt the ReRAM-based analog approximate computing to conduct the LSTM-specific element-wise computation. Combined with the dot-product computation implemented with ReRAM crossbars, a new LSTM processing tile is designed to significantly reduce the demand for analog-to-digital converters (ADCs), which is the major part of power consumption of existing designs. Next, we elaborate on a mapping scheme to efficiently deploy large-scale LSTM onto multiple processing tiles. Finally, an architecture enhancement is proposed to support crossbar-friendly LSTM pruning to further improve efficiency. This overall design, named ERA-LSTM, is presented. Our evaluation shows that it can outperform two state-of-the-art FPGA-based LSTM accelerators by 103.6 and 35.9 times, respectively; compared with a state-of-the-art ReRAM-based LSTM accelerator with digital element-wise computation, it is 6.1 times more efficient. Moreover, our experiments demonstrate that the impact of hardware constraints and approximation errors on the inference accuracy can be effectively reduced by the proposed fine-tuning scheme and by optimizing the design of the approximator.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2019_Han_ERALSTM_TPDS.pdf", "analysed": true, "pdf": null, "priority": 5.53}, {"id": "W2811080765", "short": "ReRAM RNN PIM", "title": "ReRAM-Based Processing-in-Memory Architecture for Recurrent Neural Network Acceleration", "authors": ["Yun Long", "Taesik Na", "Saibal Mukhopadhyay"], "year": 2018, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2018.2819190", "cites_global": 123, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["LSTM/RNN"], "evidence": "simulation", "tldr": "A ReRAM-based processing-in-memory architecture redesigned specifically for recurrent neural networks (rather than reused CNN-oriented designs) reports roughly 79x computing-efficiency improvement over a GPU baseline, with device-level guidance on required read-noise, resistance, and write-latency margins.", "summary": "The paper presents an RNN accelerator built on ReRAM-based processing-in-memory (PIM), distinguishing itself from prior ReRAM accelerators that targeted convolutional neural networks by redesigning the architecture and dataflow to suit RNN structure. It evaluates system throughput and energy efficiency using detailed circuit and device characterization, supports reprogrammability, and introduces an RNN-friendly pipeline to raise throughput. Reported results (abstract-level) show an average 79x improvement in computing efficiency over a GPU baseline. The authors also derive device-level design constraints from their simulation: read-noise standard deviation should stay below 0.2, device resistance should be at least 1 MOhm, and device write latency should be minimized to preserve both accuracy and efficiency.", "contributions": ["A ReRAM-based processing-in-memory architecture redesigned specifically for RNN acceleration, rather than adapting a CNN-oriented crossbar design", "An RNN-friendly pipeline intended to increase system throughput over naive crossbar mapping of RNN computation", "Reprogrammable crossbar design to support different RNN workloads", "Device/circuit-level characterization translated into concrete device design constraints (noise, resistance, write latency) needed for accurate and efficient RNN inference"], "claims": [{"claim": "The proposed ReRAM PIM RNN accelerator achieves large average throughput/efficiency gains over a GPU baseline", "support": "79x improvement of computing efficiency compared with a GPU baseline (reported in abstract)", "loc": "Abstract"}, {"claim": "Device noise and resistance must be bounded for the RNN accelerator to maintain accuracy and efficiency", "support": "simulation indicates read noise standard deviation should be < 0.2, device resistance should be at least 1 MOhm, and write latency should be minimized", "loc": "Abstract"}], "results": ["~79x average computing-efficiency improvement vs. GPU baseline (abstract-level figure; full-text methodology not available to verify benchmark details)"], "limitations": ["Full text was not accessible (IEEE Xplore paywalled, no legitimate open-access copy found); this entry is based on title/abstract only, so method details, exact benchmarks, and all numeric results beyond the headline figure could not be verified", "Evidence basis appears to be simulation with device-characterization parameters rather than a fabricated chip"], "remarks": "Abstract-only analysis: could not locate a legitimate open copy (not on arXiv/OpenReview/author pages indexed by OpenAlex/Semantic Scholar; IEEE Xplore is not accessible from this environment), so claims beyond the abstract are not verified. The paper is notable in the mapping/architecture literature as an early (2018) example of specializing a ReRAM PIM accelerator for RNN/LSTM workloads rather than reusing CNN-oriented crossbar designs (e.g., ISAAC, PRIME), and is cited by later ReRAM-based RNN/LSTM and Transformer accelerator work (ERA-LSTM, ReTransformer) as prior art for recurrent-workload mapping on ReRAM. Given the abstract-only basis, the 79x efficiency figure and the device-constraint thresholds (noise std < 0.2, R >= 1 MOhm) should be treated as reported but unverified pending access to the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "We present a recurrent neural network (RNN) accelerator design with resistive random-access memory (ReRAM)-based processing-in-memory (PIM) architecture. Distinguished from prior ReRAM-based convolutional neural network accelerators, we redesign the system to make it suitable for RNN acceleration. We measure the system throughput and energy efficiency with the detailed circuit and device characterization. Reprogrammability is enabled with our design, and an RNN friendly pipeline is employed to increase the system throughput. We observe that on average the proposed system achieves 79× improvement of computing efficiency compared with graphics processing unit baseline. Our simulation also indicates that to maintain high accuracy and computing efficiency, the read noise standard deviation should be less than 0.2, the device resistance should be at least 1 MQ, and the device writes latency should be minimized.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2018_Long_ReRAMRnnPim_TVLSI.pdf", "analysed": true, "pdf": null, "priority": 7.32}, {"id": "W2613989746", "short": "PipeLayer", "title": "PipeLayer: A Pipelined ReRAM-Based Accelerator for Deep Learning", "authors": ["Linghao Song", "Xuehai Qian", "Hai Helen Li", "Yiran Chen"], "year": 2017, "venue": "", "venue_short": "HPCA", "venue_full": "2017 IEEE International Symposium on High Performance Computer Architecture (HPCA)", "venue_ok": true, "doi": "https://doi.org/10.1109/hpca.2017.55", "cites_global": 841, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "PipeLayer is a ReRAM-based processing-in-memory accelerator that, unlike prior inference-only designs (PRIME, ISAAC), supports on-device CNN training by exploiting inter-layer pipeline parallelism and intra-layer weight replication, reporting 42.45x speedup and 7.17x energy savings over GPU on average.", "summary": "Prior ReRAM crossbar accelerators (PRIME, ISAAC) target CNN inference and are poorly suited to training because they ignore weight updates and the data dependencies of backpropagation, and because ISAAC's deep pipeline only helps with large, consecutive batches and is vulnerable to pipeline stalls. PipeLayer addresses this by analyzing the data dependencies and weight-update patterns of training algorithms and designing a pipeline that exploits inter-layer parallelism across forward, backward and weight-update passes without stalls. It also introduces a notion of parallelism granularity and weight replication (duplicating crossbars holding a layer's weights) to exploit intra-layer parallelism, enabling highly pipelined execution of both training and inference on ReRAM crossbars. Simulation-based evaluation (comparable in style to the ISAAC/PRIME line of work) shows average speedups of 42.45x and energy savings of 7.17x versus a GPU baseline.", "contributions": ["First ReRAM-based processing-in-memory (PIM) accelerator explicitly designed to support CNN training (forward, backward, and weight update), not just inference", "Analysis of data dependency and weight-update structure of backpropagation to design a stall-free, deeply pipelined execution schedule across layers", "A parallelism-granularity and weight-replication scheme to extract intra-layer parallelism within crossbar tiles", "Demonstration that the proposed pipeline avoids the batch-size-limited and stall-prone behavior of prior deep-pipeline inference accelerators (e.g., ISAAC) when applied to training"], "claims": [{"claim": "PipeLayer achieves substantially higher throughput than a GPU baseline on CNN training/inference workloads", "support": "average speedup of 42.45x compared with a GPU platform", "loc": "Abstract"}, {"claim": "PipeLayer is also substantially more energy-efficient than a GPU baseline", "support": "average energy saving of 7.17x compared with GPU implementation", "loc": "Abstract"}, {"claim": "Prior ReRAM inference accelerators such as ISAAC are not well suited to training because their deep pipelines are batch-size-limited and stall-prone under the weight-update data dependencies of backpropagation", "support": "qualitative architectural argument in the paper's motivation (abstract)", "loc": "Introduction/motivation"}], "results": ["42.45x average speedup vs. GPU platform", "7.17x average energy saving vs. GPU platform"], "limitations": ["Full text not available to this review (abstract-only basis); detailed benchmark set, baseline configuration, and precision/accuracy assumptions could not be independently verified", "As with most ReRAM crossbar accelerator papers of this era, results are simulation-based rather than measured on fabricated silicon", "Training on ReRAM crossbars assumes the devices can reliably support the write/update operations the pipeline schedules, which is a strong assumption given known analog device write non-idealities (variation, limited endurance) not discussed in the abstract"], "remarks": "PipeLayer is one of the most frequently cited early architecture papers on enabling on-chip/in-crossbar training for ReRAM-based accelerators (alongside PRIME and ISAAC for inference), and is a standard baseline/comparison point for virtually all later ReRAM accelerator, mapping, and training-architecture papers in this literature set. Because only the abstract was available for this analysis, the key numbers above (42.45x speedup, 7.17x energy saving) are taken directly from the paper's own abstract; finer architectural and evaluation details (crossbar size, exact workloads, baseline assumptions) could not be verified against the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Convolution neural networks (CNNs) are the heart of deep learning applications. Recent works PRIME [1] and ISAAC [2] demonstrated the promise of using resistive random access memory (ReRAM) to perform neural computations in memory. We found that training cannot be efficiently supported with the current schemes. First, they do not consider weight update and complex data dependency in training procedure. Second, ISAAC attempts to increase system throughput with a very deep pipeline. It is only beneficial when a large number of consecutive images can be fed into the architecture. In training, the notion of batch (e.g. 64) limits the number of images can be processed consecutively, because the images in the next batch need to be processed based on the updated weights. Third, the deep pipeline in ISAAC is vulnerable to pipeline bubbles and execution stall. In this paper, we present PipeLayer, a ReRAM-based PIM accelerator for CNNs that support both training and testing. We analyze data dependency and weight update in training algorithms and propose efficient pipeline to exploit inter-layer parallelism. To exploit intra-layer parallelism, we propose highly parallel design based on the notion of parallelism granularity and weight replication. With these design choices, PipeLayer enables the highly pipelined execution of both training and testing, without introducing the potential stalls in previous work. The experiment results show that, PipeLayer achieves the speedups of 42.45x compared with GPU platform on average. The average energy saving of PipeLayer compared with GPU implementation is 7.17x.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2017_Song_PipeLayer_HPCA.pdf", "analysed": true, "pdf": null, "priority": 10.88}, {"id": "W4243519499", "short": "ISAAC", "title": "ISAAC: A Convolutional Neural Network Accelerator with In-Situ Analog Arithmetic in Crossbars", "authors": ["Ali Reza Shafiee", "Anirban Nag", "Naveen Muralimanohar", "Rajeev Balasubramonian", "John Paul Strachan", "Miao Hu", "Richard Stanley Williams", "Vivek Srikumar"], "year": 2016, "venue": "", "venue_short": "ISCA", "venue_full": "ACM/IEEE 43rd Annual International Symposium on Computer Architecture (ISCA 2016)", "venue_ok": true, "doi": "https://doi.org/10.1109/isca.2016.12", "cites_global": 741, "cat": "03", "seed": false, "devices": ["ReRAM", "Memristor(generic)"], "models": ["CNN", "MLP"], "evidence": "simulation", "tldr": "First full-fledged memristor-crossbar CNN accelerator with an inter-layer pipeline, bit-serial inputs, 2-bit cells and a weight-flipping encoding that saves one ADC bit; reports 14.8x throughput, 5.5x lower energy and 7.5x computational density vs DaDianNao.", "summary": "ISAAC asks what a complete CNN/DNN accelerator built around analog memristor dot-product engines would look like, rather than the crossbar alone. Weights are written once and kept stationary: each layer gets its own crossbars (spread across in-situ multiply-accumulate units (IMAs), tiles and chips), and layers form a pipeline with small eDRAM buffers between them. Weights from early layers are replicated to balance throughput. Inputs are fed bit-serially through 1-bit DACs over 16 cycles, a 16-bit weight is spread across 8 two-bit cells in 128x128 arrays, and a 'flipped' column encoding cuts the needed ADC resolution to 8 bits, read by a shared 1.28 GS/s SAR ADC per column group. Signed weights use a biased representation, and digital shift-and-add, sigmoid and max-pool units finish the computation. The authors map the networks by hand and estimate performance analytically (CACTI 6.5 at 32 nm, an ADC survey, and memristor models from Hu et al.). Across VGG/MSRA CNNs and DNNs, the CE-optimised design improves throughput 14.8x and energy 5.5x over DaDianNao at the same area.", "contributions": ["Tiled crossbar architecture (chip -> tiles -> IMAs -> 128x128 crossbars) with a layer-wise, weight-stationary inter-layer pipeline and weight replication to balance it", "Bit-serial 1-bit DAC inputs and 2-bit/cell weight slicing with shift-and-add, keeping the ADC at 8 bits", "'Flipped' weight encoding that guarantees the column sum's MSB is 0, saving one ADC bit, plus a biased representation for signed arithmetic", "Design-space exploration over crossbar size, ADCs per IMA, IMAs per tile and eDRAM size, yielding ISAAC-CE/PE/SE design points", "Quantified that ADCs dominate tile power (58%), which set the agenda for later ADC-reduction work"], "claims": [{"claim": "ISAAC-CE beats DaDianNao in throughput and energy on CNN/DNN benchmarks for 16-chip configurations", "support": "on average ISAAC-CE achieves 14.8x higher throughput, consumes 95% more power, and achieves 5.5x lower energy than DaDianNao", "loc": "Sec. VIII-B, Fig. 6"}, {"claim": "ADCs are the dominant cost in a crossbar tile", "support": "ADCs account for 58% of tile power and 31% of tile area", "loc": "Sec. VIII-A, Table I"}, {"claim": "The flipped-weight encoding gives large efficiency gains by avoiding a 9-bit ADC", "support": "encoding scheme enables a 50% and 80% improvement in CE and PE, respectively", "loc": "Sec. VIII-A (Impact of Data Layout)"}, {"claim": "1-bit DACs and 2-bit cells are the optimal operating point", "support": "2-bit DAC increases chip area and power by 63% and 7% without throughput gain; 4-bit cells reduce CE and PE by 21% and 41%", "loc": "Sec. VIII-A"}, {"claim": "Inter-layer pipelining drastically reduces buffering needs", "support": "largest layer buffer drops from 1,176 KB (no pipeline) to 74 KB; 64 KB eDRAM per tile suffices", "loc": "Sec. VIII-A, Table III"}], "results": ["14.8x throughput, 5.5x lower energy, 7.5x computational density vs DaDianNao (iso-area, 16-chip boards)", "Peak CE 478.95 GOPS/(s*mm2) and PE 627.5 GOPS/W for ISAAC-CE vs 63.46 and 286.4 for DaDianNao (Table IV)", "ISAAC chip power 65.8 W vs 20.1 W for DaDianNao; ISAAC tile 0.37 mm2 at 1.2 GHz, 14x12 tiles per chip", "ISAAC-SE stores 20.25 MB/mm2 (Table IV), so the large DNN benchmark fits on 1 chip vs 32 ISAAC-CE / 64 DaDianNao chips", "Pipelining gives about 16x throughput over an unpipelined ISAAC for 16-layer VGG-1"], "limitations": ["Analytical performance model with manual mapping; no cycle-accurate simulation, no fabricated hardware", "Device non-idealities (noise, IR drop, variation, drift, stuck-at faults) are not modelled; accuracy is assumed preserved based on Hu et al.'s MNIST result", "Assumes ideal 16-bit fixed-point equivalence and inference-only use with weights programmed once; reprogramming cost ignored", "Extreme weight replication in early layers (sometimes >50K times) is not achievable, which lowers utilisation in later layers; the evaluation predates residual/attention models", "The published ISCA numbers were later corrected for ISAAC-PE and ISAAC-SE (Oct 2016 version)"], "remarks": "ISAAC is the reference template for ReRAM crossbar accelerators: weight-stationary tiles, bit-serial inputs, bit-sliced weights, shared SAR ADCs and a layer pipeline. Nearly every later architecture (PipeLayer, PUMA, Newton, the IBM 2-D-mesh fabric) reuses or compares against it. Its evidence is purely analytical, and its idealised device assumptions and 16-bit exact-arithmetic framing hide the accuracy question that later non-ideality and hardware-aware-training work showed to be central. Its finding that ADCs dominate power drove a long line of ADC-reduction and sparsity papers, and its fully spatial, replicate-to-balance pipeline maps poorly to networks whose weights exceed on-chip capacity.", "basis": "full-text", "pdf_source_url": "https://www.cs.utah.edu/~rajeev/pubs/isca16.pdf", "abstract": "A number of recent efforts have attempted to design accelerators for popular machine learning algorithms, such as those involving convolutional and deep neural networks (CNNs and DNNs). These algorithms typically involve a large number of multiply-accumulate (dot-product) operations. A recent project, DaDianNao, adopts a near data processing approach, where a specialized neural functional unit performs all the digital arithmetic operations and receives input weights from adjacent eDRAM banks. This work explores an in-situ processing approach, where memristor crossbar arrays not only store input weights, but are also used to perform dot-product operations in an analog manner. While the use of crossbar memory as an analog dot-product engine is well known, no prior work has designed or characterized a full-fledged accelerator based on crossbars. In particular, our work makes the following contributions: (i) We design a pipelined architecture, with some crossbars dedicated for each neural network layer, and eDRAM buffers that aggregate data between pipeline stages. (ii) We define new data encoding techniques that are amenable to analog computations and that can reduce the high overheads of analog-to-digital conversion (ADC). (iii) We define the many supporting digital components required in an analog CNN accelerator and carry out a design space exploration to identify the best balance of memristor storage/compute, ADCs, and eDRAM storage on a chip. On a suite of CNN and DNN workloads, the proposed ISAAC architecture yields improvements of 14.8×, 5.5×, and 7.5× in throughput, energy, and computational density (respectively), relative to the state-of-the-art DaDianNao architecture.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2016_Shafiee_ISAAC_ISCA.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2016_Shafiee_ISAAC_ISCA.pdf", "priority": 11.55}, {"id": "W4254672563", "short": "PRIME", "title": "PRIME: A Novel Processing-in-Memory Architecture for Neural Network Computation in ReRAM-Based Main Memory", "authors": ["Ping Chi", "Shuangchen Li", "Cong Xu", "Tao Zhang", "Jishen Zhao", "Yongpan Liu", "Yu Wang", "Yuan Xie"], "year": 2016, "venue": "", "venue_short": "ISCA", "venue_full": "ACM/IEEE 43rd Annual International Symposium on Computer Architecture (ISCA 2016)", "venue_ok": true, "doi": "https://doi.org/10.1109/isca.2016.13", "cites_global": 570, "cat": "03", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "MLP"], "evidence": "simulation", "tldr": "Processing-in-memory architecture in which some ReRAM main-memory subarrays can switch between storage and analog NN computation; reports about 2360x speedup and 895x energy saving over a CPU+NPU co-processor baseline with only 5.76% area overhead.", "summary": "PRIME targets the memory wall in NN inference by computing inside ReRAM main memory instead of adding a separate accelerator. Each bank is split into ordinary memory subarrays, 'full-function' (FF) subarrays that can act as memory or as analog matrix-vector engines, and buffer subarrays wired to the FF subarrays through private ports. Reusing peripherals keeps area low. The FF subarrays get multi-level wordline drivers, positive and negative weight crossbars with analog subtraction, sigmoid circuits, reconfigurable sense amplifiers that double as ADCs, and ReLU/4-1 max-pool units. To work within modest device precision (3-bit inputs, 4-bit cells, 6-bit sense amplifiers), an input-and-synapse composing scheme combines two 3-bit inputs into a 6-bit input and two 4-bit cells into an 8-bit weight, keeping only the high-order output bits. A software/hardware interface and compile-time mapping (splitting large layers, replicating small ones, bank-level parallelism) map MLPs and CNNs up to VGG-D. Trace-based simulation with modified NVSim shows large speedup and energy gains over CPU, NPU co-processor and 3D-stacked NPU-PIM baselines.", "contributions": ["Morphable ReRAM main-memory organisation: Mem, full-function (compute/memory) and buffer subarrays per bank", "Circuit and microarchitecture changes reusing memory peripherals: multi-level drivers, reconfigurable sense amplifiers as ADCs, analog subtraction, sigmoid, ReLU and max-pool", "Input and synapse composing scheme that builds 6-bit inputs and 8-bit weights from 3-bit voltage levels and 4-bit MLC cells", "Software/hardware interface and compile-time NN mapping (layer splitting and replication, bank-level parallelism)"], "claims": [{"claim": "PRIME vastly outperforms CPU and NPU baselines on MLP/CNN benchmarks", "support": "compared with a state-of-the-art neural processing unit design, PRIME improves the performance by ~2360x and the energy consumption by ~895x", "loc": "Abstract, Sec. V-B/C, Figs. 8 and 10"}, {"claim": "Computing with ReRAM in place beats even a 3D-stacked NPU PIM", "support": "PRIME achieves the highest speedup over the CPU-only solution, about 4.1x of pNPU-pim-x64's", "loc": "Sec. V-B, Fig. 8"}, {"claim": "The morphable design adds little area", "support": "Given two FF subarrays and one Buffer subarray per bank, PRIME only incurs 5.76% area overhead", "loc": "Sec. V-D, Fig. 12"}, {"claim": "Low input/weight precision suffices for NN accuracy", "support": "3-bit dynamic fixed point input and 3-bit weight precision are adequate to achieve 99% accuracy on LeNet-5/MNIST", "loc": "Sec. III-D, Fig. 6"}, {"claim": "Buffer subarrays hide memory access time", "support": "pNPU-pim reduces the memory access time a lot, and PRIME further reduces it to zero (hidden by Buffer subarrays)", "loc": "Sec. V-B, Fig. 9"}], "results": ["~2360x performance and ~895x energy improvement vs pNPU co-processor (MlBench average)", "About 4.1x speedup over a 64-NPU 3D-stacked PIM (pNPU-pim-x64); PIM alone gives 9.1x over co-processor", "5.76% chip area overhead; 60% area increase within an FF-subarray mat (driver 23%, subtraction+sigmoid 29%)", "FF subarray utilisation 39.8% -> 75.9% with replication (MlBench excluding VGG-D); 53.9% -> 73.6% for VGG-D", "Configuration: 256x256 mats, 4-bit MLC cells, 6-bit inputs/outputs and 8-bit weights after composing; Pt/TiO2-x/Pt devices with Ron/Roff = 1k/20k ohm"], "limitations": ["Trace-based simulation with modified NVSim and a 65 nm NPU baseline; no silicon", "Baseline is a CPU-hosted NPU co-processor, not an optimised accelerator like DaDianNao or GPUs, which inflates the headline speedups", "ReRAM programming time and energy for configuring weights are excluded (assumes many inferences per configuration)", "Output truncation makes dot products lossy (high-order bits only); accuracy is shown only for LeNet-5/MNIST, and device noise/variation is not modelled", "Inputs must be unsigned; the benchmarks are mostly small MNIST networks plus VGG-D, and VGG-D's speedup drops because it is spread across 8 chips"], "remarks": "PRIME and ISAAC (same ISCA 2016) together started the ReRAM-crossbar accelerator field. PRIME's distinctive idea is morphable memory/compute subarrays inside main memory, while ISAAC focused on a dedicated pipelined accelerator. Its headline numbers rest on a weak baseline and ignore programming cost and analog non-idealities, so they are best read as an upper bound. The composing scheme, which builds higher precision from multiple low-precision cells and input slices, became the standard bit-slicing approach. Later work (PipeLayer, ISAAC-style comparisons, the IBM 2-D mesh) usually cites PRIME as foundational ReRAM PIM, and ISAAC criticises its lossy ADC precision and unsigned inputs.", "basis": "full-text", "pdf_source_url": "https://cseweb.ucsd.edu/~jzhao/files/PRIME_isca2016.pdf", "abstract": "Processing-in-memory (PIM) is a promising solution to address the \"memory wall\" challenges for future computer systems. Prior proposed PIM architectures put additional computation logic in or near memory. The emerging metal-oxide resistive random access memory (ReRAM) has showed its potential to be used for main memory. Moreover, with its crossbar array structure, ReRAM can perform matrix-vector multiplication efficiently, and has been widely studied to accelerate neural network (NN) applications. In this work, we propose a novel PIM architecture, called PRIME, to accelerate NN applications in ReRAM based main memory. In PRIME, a portion of ReRAM crossbar arrays can be configured as accelerators for NN applications or as normal memory for a larger memory space. We provide microarchitecture and circuit designs to enable the morphable functions with an insignificant area overhead. We also design a software/hardware interface for software developers to implement various NNs on PRIME. Benefiting from both the PIM architecture and the efficiency of using ReRAM for NN computation, PRIME distinguishes itself from prior work on NN acceleration, with significant performance improvement and energy saving. Our experimental results show that, compared with a state-of-the-art neural processing unit design, PRIME improves the performance by ~2360x and the energy consumption by ~895x, across the evaluated machine learning benchmarks.", "review": [], "pdf_expected": "03_Crossbar_Accelerator_Architectures/2016_Chi_PRIME_ISCA.pdf", "analysed": true, "pdf": "03_Crossbar_Accelerator_Architectures/2016_Chi_PRIME_ISCA.pdf", "priority": 11.08}, {"id": "W7129625181", "short": "ROSETTA", "title": "ROSETTA: ROM-Overlaid STT-MRAM for Efficient MVM and Softmax Operations Toward Accelerating Transformer Inference", "authors": ["Amod Holla", "Mainakh Mukherjee", "Anish Mukherjee", "Kaushik Roy"], "year": 2026, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2026.3665635", "cites_global": 0, "cat": "04", "seed": false, "devices": ["MRAM"], "models": ["Transformer", "GPT/LLM"], "evidence": "simulation", "tldr": "ROSETTA is a 3T-2R STT-MRAM compute-in-memory array using series-resistance sensing with time-to-digital conversion and palindromic input/weight encoding, adding a ROM word line for in-array softmax lookup tables; it reports ~47% less area and 3.1x less MVM energy than an equivalent 8T-SRAM ROM-overlaid macro and 11.7-14.5x energy efficiency over 1T-1R MRAM CiM at the system level.", "summary": "The paper addresses two bottlenecks for transformer inference on compute-in-memory (CiM) hardware: matrix-vector multiplication (MVM) energy efficiency and the non-linear softmax operations that MVM-centric CiM arrays don't natively support. Conventional 1T-1R STT-MRAM CiM has lower MVM energy efficiency than 8T-SRAM CiM due to the low resistance of MRAM devices, with line parasitics and low ON/OFF ratios further limiting row-level parallelism. ROSETTA proposes a CiM array built from 3T-2R STT-MRAM bit-cells using series-resistance sensing and time-to-digital conversion (TDC) for low-power MVM, plus an added word line that stores a ROM bit to enable in-array lookup tables for fast softmax without extra bit-cell area. A novel palindromic encoding of inputs and weights is introduced to counteract the data-dependent nonlinearity inherent to TDC-based STT-MRAM sensing, enabling 8x higher row-level parallelism than standard 1T-1R MRAM CiM and better scalability to larger arrays. The macro-level design is compared against an equivalent ROM-overlaid 8T-SRAM macro and system-level spatial architectures using 1T-1R MRAM and 8T-SRAM ROM-overlaid CiM macros.", "contributions": ["3T-2R STT-MRAM bit-cell CiM array using series-resistance sensing with time-to-digital conversion (TDC) for low-power MVM", "In-array ROM word line enabling fast softmax lookup tables without added bit-cell area", "Palindromic input/weight encoding scheme that mitigates data-dependent nonlinearity of TDC-based STT-MRAM sensing, enabling 8x higher row-level parallelism than standard 1T-1R MRAM CiM", "System-level spatial architecture evaluation comparing ROSETTA macros against 1T-1R MRAM and 8T-SRAM ROM-overlaid CiM macros"], "claims": [{"claim": "ROSETTA's palindromic encoding enables substantially higher row-level parallelism than standard 1T-1R MRAM CiM", "support": "8x higher row-level parallelism than standard 1T-1R MRAM CiM", "loc": "Abstract"}, {"claim": "ROSETTA macro is more area- and energy-efficient than an equivalent ROM-overlaid 8T-SRAM macro at similar latency/accuracy", "support": "~47% less area and 3.1x less MVM energy than an equivalent ROM-overlaid 8T-SRAM macro, at similar latency and accuracy", "loc": "Abstract"}, {"claim": "At the system level, ROSETTA-based architectures are substantially more energy efficient than equivalent MRAM/SRAM CiM architectures", "support": "11.7-14.5x higher energy efficiency vs. 1T-1R MRAM CiM architectures, and 1.44-1.5x vs. 8T-SRAM ROM-overlaid CiM architectures", "loc": "Abstract"}], "results": ["~47% less area than an equivalent ROM-overlaid 8T-SRAM macro", "3.1x less MVM energy than an equivalent ROM-overlaid 8T-SRAM macro (similar latency/accuracy)", "8x higher row-level parallelism than standard 1T-1R MRAM CiM", "11.7-14.5x higher system-level energy efficiency vs. equivalent 1T-1R MRAM CiM architectures", "1.44-1.5x higher system-level energy efficiency vs. equivalent 8T-SRAM ROM-overlaid CiM architectures"], "limitations": ["Full text not accessible to this reviewer (no open preprint found); device-level noise/variation modeling, benchmarked transformer models, and accuracy validation details could not be verified beyond the abstract", "Evidence basis is simulation/macro-design analysis rather than measured silicon"], "remarks": "Abstract-only assessment: JETCAS is not downloadable here and no arXiv preprint was found. This is a device/circuit-level contribution (MRAM is comparatively underexplored for CiM relative to ReRAM/PCM/SRAM) that tackles both the MVM-energy weakness of 1T-1R STT-MRAM and the softmax bottleneck for transformers via an in-array ROM table — a nice complement to papers that only address MVM efficiency. The reliance on a time-to-digital conversion scheme introduces data-dependent nonlinearity that the palindromic encoding is designed to counteract; how robust this is in practice (process variation, temperature) cannot be judged without the full paper.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Deep learning architectures are increasingly limited by the memory wall — the “von Neumann bottleneck” that forces frequent data transfers between memory and processing units, throttling throughput and energy efficiency. To alleviate this bottleneck, researchers have explored Compute-in-Memory (CiM) architectures to accelerate the core computing primitives such as the matrix–vector multiplications (MVMs), within memory arrays. Yet, large language models based on transformers also require many non-linear softmax operations, creating a new bottleneck. From a technology perspective, non-volatile STT-MRAMs are promising for CiM thanks to their endurance, nonvolatility, and area footprint. However, conventional 1T–1R STT-MRAM CiM arrays place bit-cells in parallel, yielding lower MVM energy efficiency than 8T-SRAM CiM due to low device resistance; line parasitics and low OFF/ON ratios of STT-MRAM devices further limit row parallelism and scalability. In this context, we propose ROSETTA, a CiM array based on 3T–2R STT-MRAM bit-cells that uses series-resistance sensing and time-to-digital conversion (TDC) for low-power MVMs. An added word line also stores a ROM bit, enabling in-array tables for fast softmax, without increasing bit-cell area. We introduce a novel palindromic encoding of inputs and weights to mitigate the data-dependent nonlinearity in STT-MRAM CiM arrays based on TDC sensing. This enables 8× higher row-level parallelism than standard 1T–1R MRAM CiM and facilitates scaling to larger CiM arrays. Our macro occupies ∼ 47% less area and consumes 3.1× less MVM energy than an equivalent ROM-overlaid 8T-SRAM macro, at similar latency and accuracy. At the system level, a spatial architecture comprising our macros exhibits 11.7−14.5× and 1.44 − 1.5× higher energy efficiency than equivalent architectures comprising 1T-1R MRAM and 8T-SRAM ROM-overlaid CiM macros, respectively.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2026_Holla_ROSETTA_JETCAS.pdf", "analysed": true, "pdf": null, "priority": 5.0}, {"id": "W7162657777", "short": "Harmony", "title": "Harmony: A Hardware-Mapping Co-Exploration Framework for Hybrid CIM-based Vision Transformer Accelerator", "authors": ["Yihang Zuo", "Fu Zexin", "Cong Wang", "Yuchao Wu", "Jiayi Huang", "Yuzhe Ma"], "year": 2026, "venue": "", "venue_short": "ISQED", "venue_full": "International Symposium on Quality Electronic Design (ISQED 2026)", "venue_ok": true, "doi": "https://doi.org/10.1109/isqed69900.2026.11534775", "cites_global": 0, "cat": "04", "seed": false, "devices": ["SRAM-analog", "Memristor(generic)"], "models": ["ViT", "Transformer"], "evidence": "simulation", "tldr": "Harmony is a hardware-mapping co-exploration framework for hybrid CIM-based vision transformer accelerators that uses a knowledge-guided grid search and an improved genetic algorithm to jointly search CIM macro hardware configuration and spatial mapping, reporting 48% area reduction, 13% latency reduction, 32% energy reduction and 1.27x average energy efficiency versus a baseline, while trading off accuracy against all-SRAM designs.", "summary": "The paper targets the difficulty of automating high-performance CIM-based transformer accelerator design: unlike CNNs, where CIM-based acceleration is mature, the design space for hybrid/heterogeneous CIM-based vision transformer (ViT) accelerators is extremely large due to complex model structure and dataflow, covering both hardware configuration (CIM macro parameters) and spatial mapping. Harmony defines a universal design-space representation for implementing ViTs on hybrid, heterogeneous CIM accelerators and proposes two search algorithms to navigate it efficiently: a knowledge-guided grid search (KGGS) that uses orthogonal-experiment and dominance analysis to find stable exploration probabilities for different parameters, and an improved genetic algorithm (IGA) with a unique order-crossover and swapping-mutation scheme that preserves relative order to avoid costly legalization steps during iteration. Performance experiments show Harmony's co-explored designs achieve notable area, latency, and energy improvements over a baseline, while accuracy experiments show the hybrid (non-all-SRAM) architecture trades some accuracy for these efficiency gains relative to all-SRAM CIM-based accelerators.", "contributions": ["A universal design-space representation for hybrid/heterogeneous CIM-based vision transformer accelerators (hardware configuration + spatial mapping)", "Knowledge-guided grid search (KGGS) using orthogonal experiment design and dominance analysis to efficiently explore parameter space", "Improved genetic algorithm (IGA) with order-crossover and swapping-mutation that preserves relative order to skip legalization steps", "Quantitative evaluation of area/latency/energy gains and an accuracy tradeoff analysis vs. all-SRAM CIM baselines"], "claims": [{"claim": "Harmony's co-exploration achieves substantial area, latency and energy improvements over the baseline design", "support": "48% area reduction, 13% latency reduction, 32% energy reduction, and 1.27x energy efficiency on average compared with the baseline", "loc": "Abstract"}, {"claim": "The hybrid CIM-based architecture trades off some accuracy relative to all-SRAM CIM-based accelerators", "support": "Abstract: 'hybrid architecture achieves a trade-off between accuracy and performance compared with all-SRAM CIM-based accelerators'", "loc": "Abstract"}], "results": ["48% area reduction vs. baseline", "13% latency reduction vs. baseline", "32% energy reduction vs. baseline", "1.27x average energy efficiency vs. baseline"], "limitations": ["Full text not accessible to this reviewer (ISQED is not downloadable here and no arXiv preprint was found); baseline definition, benchmarked ViT models, and the exact accuracy tradeoff numbers could not be verified", "Accuracy is explicitly described as trading off against all-SRAM designs, implying the efficiency gains come partly from using lower-accuracy (presumably analog/ReRAM) macros alongside SRAM"], "remarks": "Abstract-only assessment: ISQED proceedings are not downloadable here and no preprint was found. This is a mapping/design-space-exploration contribution much like other DSE frameworks in this collection (e.g., JADE, Gibbon/MNSIM-style co-exploration tools it cites), specifically targeting the harder, more heterogeneous design space created by hybrid CIM for ViTs; the explicit accuracy-vs-efficiency tradeoff disclosure is a useful honesty signal, but without the full text the real-world significance of the 13-48% gains relative to a possibly weak baseline cannot be judged.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Computing-in-memory (CIM) architectures have successfully enhanced convolutional neural network (CNN) performance, but the automation of high-performance CIM-based transformer accelerators is still challenging. Specifically, the design space of hardware design and mapping is extremely large due to the complex model structure and data flow. To address this problem, we propose Harmony, a hardware and mapping co-exploration framework to optimize the hybrid CIM-based vision transformer accelerator. We define a universal design space representation for implementing vision transformers in CIM-based accelerators that support hybrid and heterogeneous features. The corresponding design space comprises the hardware configuration of CIM macros and their spatial mapping scheme. Furthermore, we propose the knowledge-guided grid search (KGGS) algorithm and improved genetic algorithm (IGA) to boost exploration efficiency. The orthogonal experiment and dominance analysis of KGGS could obtain the exploration probabilities of different parameters and ensure its stability, while the unique order crossover and swapping mutation of IGA could retain relative order to avoid legalization processes during the iteration. Performance experimental results show that Harmony achieves $48 \\%$ area reduction, $13 \\%$ latency reduction, $32 \\%$ energy reduction, and $1.27 \\times$ energy efficiency on average compared with the baseline. The accuracy experiment demonstrates that our hybrid architecture achieves a trade-off between accuracy and performance compared with all-SRAM CIM-based accelerators.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2026_Zuo_Harmony_ISQED.pdf", "analysed": true, "pdf": null, "priority": 5.0}, {"id": "W4406521098", "short": "Atleus", "title": "Atleus: Accelerating Transformers on the Edge Enabled by 3D Heterogeneous Manycore Architectures", "authors": ["Pratyush Dhingra", "Janardhan Rao Doppa", "Partha Pratim Pande"], "year": 2025, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2025.3531255", "cites_global": 9, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["BERT", "GPT/LLM", "Transformer"], "evidence": "simulation", "tldr": "Atleus is a 3D-stacked heterogeneous manycore (3 ReRAM PIM tiers + 1 systolic-array tier, TSV NoC) that keeps frozen pre-trained transformer weights in ReRAM crossbars and runs dynamic attention, nonlinearities and LoRA fine-tuning on systolic arrays, claiming up to 56x speedup and 64.5x energy efficiency vs a V100 GPU.", "summary": "The paper targets edge fine-tuning (LoRA/QLoRA) as well as inference of transformers, arguing that standalone NVM PIM is unsuitable because dynamic-operand attention MatMuls and parameter updates would require frequent NVM writes (e.g. ~5x10^4 rewrites for one BERT-Large sequence of length 1024). Atleus maps weight-stationary MatMuls (W_Q, W_K, W_V, W_O, FF1, FF2) to ISAAC-style ReRAM tiles (128x128, 2-bit cells, 8-bit ADCs, 32 nm) and maps QK^T, softmax (fused), LayerNorm and LoRA A/B to output-stationary 128x32 systolic arrays (10 nm), with an intra-layer pipeline across tiers. A space-filling-curve NoC on ReRAM tiers plus TSV skip links to the systolic tier minimise communication, and 'crossbar-wise quantization' (per-crossbar scale, dequantised after the MVM using extra shift-and-add units) supports QLoRA-style compressed models. Evaluation (NeuroSim + SCALE-Sim + BookSim2) on RoBERTa-Base, BERT-Large, GPT-2 Medium and BLOOM-560m compares against HAIMA, a TPUv4-like 3D systolic array and a V100 GPU; noise-aware LoRA fine-tuning restores accuracy to within 0.5% under Gaussian weight variation.", "contributions": ["Heterogeneous 3D architecture that puts static pre-trained weights in ReRAM PIM and all dynamic/trainable computation (attention scores, softmax, LayerNorm, LoRA) in systolic arrays, avoiding NVM rewrites during fine-tuning.", "Intra-layer pipelined mapping across heterogeneous tiers with an SFC-based ReRAM NoC and TSV skip links.", "Crossbar-wise quantization with post-MVM dequantization in a modified ReRAM tile (2.15% area, 1.5% power overhead).", "Noise-aware LoRA fine-tuning in which the LoRA adapters learn to compensate Gaussian noise in ReRAM-stored frozen weights."], "claims": [{"claim": "ReRAM handles the vast majority of transformer MatMuls even when dynamic attention is offloaded.", "support": "ReRAM performs 90.08-94.7% of MM operations (≈12x the systolic array for GPT-2 Medium, n=1024).", "loc": "Sec. V-C, Fig. 7"}, {"claim": "Standalone NVM PIM is impractical for transformers due to write endurance.", "support": "~5x10^4 rewrite operations to ReRAM cells for one BERT-Large sequence of length 1024; endurance 10^6-10^12 writes.", "loc": "Sec. II, Sec. V-A"}, {"claim": "Atleus outperforms GPU, 3D-TPU and HAIMA for fine-tuning and inference.", "support": "Up to 56x speedup and 64.5x energy efficiency vs GPU; 3D-TPU ~2x faster than GPU; GPU core utilization <50%.", "loc": "Sec. V-G, Fig. 11, Conclusion"}, {"claim": "Noise-aware LoRA fine-tuning recovers accuracy under ReRAM weight noise.", "support": "Accuracy loss <0.5% vs ideal device for RoBERTa-Base and BERT-Large.", "loc": "Sec. V-F, Fig. 9"}, {"claim": "Crossbar-wise quantization reduces Atleus energy while GPU/HAIMA/3D-TPU energy rises with quantization.", "support": "M8F8 maintains perplexity, M8F4 costs ~2-3% model performance for more energy savings, M4F4 fails (~8,000 values share one scale).", "loc": "Sec. V-H, Figs. 12-14"}], "results": ["Up to 56x speedup and 64.5x energy-efficiency improvement vs NVIDIA V100 GPU (LoRA fine-tuning/inference).", "ReRAM performs 90.08-94.7% of MM operations across RoBERTa-Base, BERT-Large, GPT-2 Medium, BLOOM-560m.", "Crossbar-level dequantization overhead: 2.15% area and 1.5% power.", "Noise-aware fine-tuning: <0.5% accuracy loss vs ideal ReRAM."], "limitations": ["Simulation only (NeuroSim/SCALE-Sim/BookSim2); ReRAM tier at 32 nm and systolic tier at 10 nm, with 3D hybrid-bonded integration of ReRAM and logic assumed feasible.", "Analog non-idealities modelled as simple Gaussian weight noise; ADC/IR-drop effects and drift not studied.", "Headline 56x/64.5x factors are versus a GPU; comparisons with HAIMA are re-implementations; homogeneous ReRAM transformer accelerators (ReTransformer, AccelTran) are excluded from comparison.", "Models are small (110M-560M parameters); assumes all pre-trained weights fit on-chip in ReRAM."], "remarks": "A clean statement of the now-common heterogeneous principle: analog NVM crossbars for frozen weights, digital engines for dynamic operands and trainable adapters; LoRA makes this especially natural because the frozen base never needs rewriting. The architecture-level evidence is purely simulated and the crossbar is treated mostly as an ISAAC tile, so the work says little about analog accuracy at scale, but the mapping/partitioning argument (over 90% of MACs remain weight-stationary) is useful for thesis-level design-space reasoning.", "basis": "full-text", "pdf_source_url": "", "abstract": "Transformer architectures have become the standard neural network model for various machine learning (ML) applications, including natural language processing and computer vision. However, the compute and memory requirements introduced by transformer models make them challenging to adopt for edge applications. Furthermore, fine-tuning pretrained transformers (e.g., foundation models) is a common task to enhance the model’s predictive performance on specific tasks/applications. Existing transformer accelerators are oblivious to complexities introduced by fine-tuning. In this article, we propose the design of a three-dimensional (3D) heterogeneous architecture referred to as Atleus that incorporates heterogeneous computing resources specifically optimized to accelerate transformer models for the dual purposes of fine-tuning and inference. Specifically, Atleus utilizes nonvolatile memory and systolic array for accelerating transformer computational kernels using an integrated 3D platform. Moreover, we design a suitable NoC to achieve high performance and energy efficiency. Finally, Atleus adopts an effective quantization scheme to support model compression. Experimental results demonstrate that Atleus outperforms existing state-of-the-art by up to$56\\times $and$64.5\\times $in terms of performance and energy efficiency, respectively.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Dhingra_Atleus_TCAD.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2025_Dhingra_Atleus_TCAD.pdf", "priority": 7.13}, {"id": "W4408563999", "short": "Topkima-Former", "title": "Topkima-Former: Low-Energy, Low-Latency Inference for Transformers Using Top- k In-Memory ADC", "authors": ["Shuai Dong", "Junyi Yang", "Xiaoqi Peng", "Hongyang Shang", "Ye Ke", "Xiaofeng Yang", "H. Liu", "Arindam Basu"], "year": 2025, "venue": "IEEE Transactions on Circuits and Systems I Regular Papers", "venue_short": "TCAS-I", "venue_full": "IEEE Transactions on Circuits and Systems I: Regular Papers", "venue_ok": true, "doi": "https://doi.org/10.1109/tcsi.2025.3549060", "cites_global": 7, "cat": "04", "seed": false, "devices": ["SRAM-analog", "ReRAM"], "models": ["Transformer", "ViT", "BERT"], "evidence": "algorithm+simulation", "tldr": "Topkima-Former combines a top-k activation selection circuit fused with in-memory ADCs (topkima) to compute softmax without sorting overhead, plus a sub-top-k crossbar-aggregation scheme and a scale-free attention technique, giving 1.8x-84x speedup and 1.3x-35x energy efficiency over prior IMC transformer accelerators with only 0.4%-1.6% accuracy loss.", "summary": "Softmax and other nonlinear operations can consume up to 40% of transformer inference latency, yet most in-memory-computing (IMC) transformer accelerators focus only on accelerating the linear matrix multiplications. The paper proposes 'topkima,' a circuit-level technique that fuses top-k winner-take-all activation selection with in-memory ADCs (IMA) so only the k largest pre-softmax activations are converted and passed to the softmax block, eliminating sorting latency and reducing the cost of softmax. At the algorithm level, a modified training scheme applies top-k only in the forward pass and introduces a sub-top-k method that aggregates per-crossbar top-k values into a global top-k to handle crossbar size limits. At the architecture level, a fine-grained pipeline and an improved scale-free attention technique remove the cost of score scaling. The combined SRAM/RRAM IMC system, Topkima-Former, is evaluated via NeuroSim-based system simulation on ViT, DistilBERT and BERT-base over CIFAR-10, CIFAR-100 and SQuAD, showing large speedup/energy gains over prior IMC transformer accelerators (ELSA, ReTransformer, X-Former, HARDSEA) at k=5, with minimal accuracy loss.", "contributions": ["Proposes topkima: a circuit combining top-k activation selection with in-memory ADC (IMA) to compute softmax inputs without separate sorting hardware or ramp-ADC-style full conversion of all activations", "Introduces a sub-top-k algorithm/training scheme that aggregates per-crossbar top-k candidates into a correct global top-k, addressing crossbar size limitations, using top-k only during the forward pass", "Introduces an improved scale-free attention technique at the architecture level to remove the computational cost of query/key scaling", "Designs a fine-grained pipeline for scheduling the combined system's dataflow", "Benchmarks the full Topkima-Former system via NeuroSim against prior IMC transformer accelerators (ELSA, ReTransformer, X-Former, HARDSEA) on ViT/DistilBERT/BERT-base"], "claims": [{"claim": "Topkima-Former achieves large speedup and energy-efficiency gains over prior IMC transformer accelerators", "support": "1.8x-84x speedup and 1.3x-35x energy-efficiency (EE) improvement over ELSA, ReTransformer, X-Former and HARDSEA; the paper's design reaches 6.70 TOPS throughput-related figure and 16.84 TOPS/W EE at 200 MHz (256x256 SRAM/RRAM IMC array)", "loc": "Abstract; Sec. IV, comparison table"}, {"claim": "The topkima softmax macro is much faster than conventional and digital top-k softmax implementations", "support": "~15x faster than a conventional softmax macro and ~8x faster than a digital top-k (Dtopk) softmax macro", "loc": "Abstract; Sec. IV"}, {"claim": "Top-k=5 activation selection for softmax causes only minimal accuracy loss across vision and NLP models", "support": "0.4%-1.2% (abstract) / 0.42%-1.60% (per-model results) accuracy drop across ViT, DistilBERT and BERT-base on CIFAR-10, CIFAR-100 and SQuAD at k=5", "loc": "Abstract; Sec. V Conclusion"}, {"claim": "Softmax is a major latency bottleneck in transformer inference that prior IMC accelerators under-address", "support": "Softmax operation consumes up to 40% of inference time, motivating the circuit-level topkima design", "loc": "Sec. I Introduction"}], "results": ["1.8x-84x speedup and 1.3x-35x energy-efficiency gain vs. ELSA, ReTransformer, X-Former and HARDSEA IMC transformer accelerators", "~15x faster softmax macro vs. a conventional softmax macro; ~8x faster vs. a digital top-k (Dtopk) softmax macro", "0.42%-1.60% accuracy drop across ViT, DistilBERT, BERT-base on CIFAR-10/CIFAR-100/SQuAD at k=5", "256x256 SRAM/RRAM IMC array design point: 6.70 (throughput-related metric) and 16.84 TOPS/W energy efficiency at 200 MHz, per the system comparison table"], "limitations": ["Evaluation is via NeuroSim-based system simulation, not a fabricated/measured chip", "Accuracy results depend on the choice of top-k parameter (k=5); larger sequence lengths or more aggressive k reduction could affect the accuracy/efficiency trade-off differently", "Comparisons to prior accelerators (ELSA, ReTransformer, X-Former, HARDSEA) are based on reported/simulated figures from differing technology/array configurations rather than a fully controlled common testbed", "No dedicated pipelining was added for some comparisons per the authors' own note, meaning reported speedups could be a conservative or inconsistent baseline depending on configuration", "Self-attention's dynamic weight-dependent operations and crossbar partitioning (sub-top-k) add algorithmic complexity whose overhead is not fully isolated from the headline speedup numbers"], "remarks": "This paper targets a specific, often-overlooked bottleneck in analog/IMC transformer accelerators — the nonlinear softmax path — rather than just the linear MVM layers that dominate most crossbar-mapping work, and the in-memory-ADC/top-k fusion is a neat circuit-algorithm co-design. Its claims rest on NeuroSim-level simulation and comparisons against other simulated accelerators' published numbers, so absolute gains should be read as architecture-level projections rather than silicon-validated results; still, it is a useful complement to transformer-mapping frameworks (e.g., LionHeart, COMPASS) that mostly ignore softmax/attention-internal costs.", "basis": "full-text", "pdf_source_url": "", "abstract": "Transformer has emerged as a leading architecture in neural language processing (NLP) and computer vision (CV). However, the extensive use of nonlinear operations, like softmax, poses a performance bottleneck during transformer inference and comprises up to 40% of the total latency. Hence, we propose innovations at the circuit, algorithm and architecture levels to accelerate the transformer. At the circuit level, we propose Topkima—combining top-kactivation selection with in-memory ADC (IMA) to implement efficient softmax without any sorting overhead. Only theklargest activations are sent to softmax calculation block, reducing the huge computational cost of softmax. At the algorithmic level, a modified training scheme utilizes top-kactivations only during the forward pass, combined with a sub-top-kmethod to address the crossbar size limitation by aggregating each sub-top-kvalues as global top-k. At the architecture level, we introduce a fine pipeline for efficiently scheduling data flows and an improved scale-free technique for removing scaling cost. The combined system, dubbed Topkima-Former, enhances$1.8\\times -84\\times $speedup and$1.2\\times -36\\times $energy efficiency (EE) over prior In-memory computing (IMC) accelerators. Compared to a conventional softmax macro and a digital top-k(Dtopk) softmax macro, our proposed Topkima softmax macro achieves about$15\\times $and$8\\times $faster speed respectively. Experimental evaluations demonstrate minimal (0.42% to 1.60%) accuracy loss for different models in both vision and NLP tasks.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Dong_TopkimaFormer_TCAS-I.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2025_Dong_TopkimaFormer_TCAS-I.pdf", "priority": 5.63}, {"id": "W4413394346", "short": "COMET-3D", "title": "COMET-3D: Compute-in-Memory-Based Transformer Accelerator With Optimized Pipeline and 3D Heterogeneous Integration", "authors": ["Ashish Reddy Bommana", "Farshad Firouzi", "Krishnendu Chakrabarty"], "year": 2025, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2025.3601526", "cites_global": 7, "cat": "04", "seed": false, "devices": ["SRAM-analog", "ReRAM"], "models": ["Transformer", "BERT", "GPT/LLM"], "evidence": "simulation", "tldr": "COMET-3D is a 3D heterogeneous compute-in-memory accelerator that pairs SRAM- and ReRAM-based CIM arrays with a logic die (digital MAC + softmax units) and a latency-optimized, operational-unit-aware pipeline for multi-head self-attention, achieving up to 34x EDP improvement on LLAMA versus similarly-resourced baselines.", "summary": "The paper argues that existing CIM-based Transformer accelerators rest on unrealistic assumptions (single-cycle activation of an entire crossbar), use pipelines not optimized for operational-unit (OU)-based execution, and incur high ADC cost. To address these, the authors propose a latency-optimized pipeline tailored to OU-based CIM execution, and COMET-3D, a 3D heterogeneous architecture stacking SRAM- and ReRAM-based CIM arrays with a logic die containing digital MAC units and softmax modules. The architecture and dataflow are designed to maximize hardware utilization for the multi-head self-attention (MHSA) layer specifically. Evaluated across BERT, GPT2, and LLaMA, COMET-3D outperforms baseline architectures with comparable compute resources, with the largest gains on the largest model (LLaMA).", "contributions": ["Identifies three limitations of prior CIM Transformer accelerators: unrealistic single-cycle whole-crossbar activation, OU-execution-unaware pipelines, and high ADC cost", "Proposes a latency-optimized pipeline specifically tailored for operational-unit (OU)-based CIM execution", "Introduces COMET-3D, a 3D heterogeneous architecture integrating SRAM- and ReRAM-based CIM arrays with a digital logic die (MAC units + softmax modules) via 3D integration", "Designs the dataflow to maximize hardware utilization specifically for multi-head self-attention (MHSA) acceleration", "Evaluates across BERT, GPT2 and LLaMA, demonstrating large energy-delay-product (EDP) gains over similarly-resourced baselines"], "claims": [{"claim": "COMET-3D achieves large EDP improvements over baseline CIM architectures with similar compute resources, with gains scaling with model size", "support": "Up to 34x EDP improvement for LLAMA, 7.4x for GPT2, and 4.3x for BERT-Large", "loc": "Abstract"}], "results": ["Up to 34x energy-delay-product (EDP) improvement for LLaMA vs. baseline architectures with similar compute resources", "7.4x EDP improvement for GPT2", "4.3x EDP improvement for BERT-Large"], "limitations": ["Evaluation is simulation-based (architecture/CAD-level, consistent with the TCAD venue); no fabricated 3D chip is reported in the abstract", "3D heterogeneous integration (SRAM + ReRAM CIM arrays + digital logic die) introduces assembly/thermal/yield considerations not addressed in the abstract", "Gains are reported relative to baselines with 'similar compute resources' as defined by the authors; the specific baseline architectures and their representativeness of the broader CIM-Transformer literature are not stated in the abstract"], "remarks": "The explicit critique of the 'single-cycle whole-crossbar activation' assumption used in earlier CIM Transformer accelerator papers is a useful methodological point for mapping research -- it suggests that OU (operational-unit)-level timing realism materially changes design conclusions for self-attention acceleration. The EDP gains scaling with model size (34x for LLaMA vs. 4.3x for BERT-Large) is consistent with larger models amortizing the fixed overhead of 3D-integrated digital logic (softmax/MAC) more effectively, but this should be checked against the full text's baseline definitions before citing the headline multipliers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformers have become the backbone of large language decoder and encoder models, but their compute- and memory-intensive nature makes them inefficient on traditional von Neumann architectures. Compute-in-memory (CIM) architectures offer a promising path forward by enablingin situmatrix operations and reducing memory access overhead. However, existing CIM-based accelerators suffer from: (1) unrealistic assumption of single-cycle activation of entire crossbar; (2) inefficient pipelines that are not optimized for operational unit (OU)-based execution; and (3) high analog-to-digital converter (ADC) cost. To address these limitations, we propose a latency-optimized pipeline tailored specifically for OU-based CIM execution and introduce COMET-3D—a 3D heterogeneous architecture that integrates SRAM and ReRAM-based CIM arrays with a logic die containing digital MAC units and softmax modules. The proposed architecture and dataflow maximize hardware utilization and enable efficient acceleration of the multi-head self-attention (MHSA) layer. Experimental results across BERT, GPT2, and LLAMA demonstrate that COMET-3D outperforms baseline architectures with similar compute resources by up to 34× in energy-delay product (EDP) for LLAMA, with gains of 7.4× for GPT2 and 4.3× for BERT-Large.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Bommana_COMET3D_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.63}, {"id": "W4414197154", "short": "VQT-CiM", "title": "VQT-CiM: Accelerating Vector Quantization Enhanced Transformer with Ferroelectric Compute-in-Memory", "authors": ["Xuchu Huang", "Haonan Du", "Min Zhou", "Zheyu Yan", "Cheng Zhuo", "Xunzhao Yin"], "year": 2025, "venue": "", "venue_short": "DAC", "venue_full": "ACM/IEEE Design Automation Conference (DAC 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/dac63849.2025.11133264", "cites_global": 3, "cat": "04", "seed": false, "devices": ["FeFET"], "models": ["Transformer"], "evidence": "simulation", "tldr": "VQT-CiM is a FeFET-based CiM design that eliminates the runtime write operations dynamic attention VMMs otherwise require, by vector-quantizing keys/values (residual + product VQ) into static codebook VMMs, achieving 3.54x energy efficiency and 4.53x throughput over state-of-the-art NVM CiM transformer designs.", "summary": "The paper targets a specific obstacle to deploying non-volatile-memory (NVM) based compute-in-memory for Transformer self-attention: unlike the static weight matrices of feed-forward/projection layers, the attention mechanism's query-key and attention-weighted-value multiplications are dynamic (data-dependent), requiring runtime writes into the NVM crossbar, which is costly due to high write energy/latency, complex compute-write-compute dependencies, and limited device endurance. VQT-CiM, built on ferroelectric FET (FeFET) CiM crossbars, sidesteps this by applying vector quantization (VQ) to keys and values so that the inner-product and weighted-sum operations inside self-attention become static VMMs against fixed codebooks rather than dynamic per-token VMMs. Because plain VQ would limit representational capacity and hurt accuracy, the authors combine residual VQ (RVQ) and product VQ (PVQ) to expand representation capacity while retaining the static-VMM benefit. They present a hardware implementation with an optimized RVQ dataflow using FeFET CiM crossbars plus digital peripheral circuits, reporting large efficiency gains over prior NVM-based CiM Transformer accelerators.", "contributions": ["Identifies that dynamic (data-dependent) VMMs in Transformer self-attention are a poor fit for NVM-based CiM due to runtime write overhead, compute-write-compute dependencies, and limited endurance", "Proposes converting dynamic attention VMMs into static VMMs by vector-quantizing keys and values, enabling computation against fixed codebooks stored in CiM crossbars", "Introduces a combined residual-VQ + product-VQ (RVQ+PVQ) scheme to recover representational capacity lost to plain vector quantization", "Designs a FeFET-based CiM hardware implementation with an optimized dataflow for the RVQ computation plus digital peripheral circuits", "Reports 3.54x energy efficiency and 4.53x throughput improvement over state-of-the-art NVM-based CiM Transformer designs"], "claims": [{"claim": "VQT-CiM substantially improves energy efficiency and throughput over prior NVM-based CiM Transformer accelerators by eliminating runtime write operations", "support": "3.54x energy efficiency improvement and 4.53x throughput improvement vs. state-of-the-art NVM-based CiM transformer designs", "loc": "Abstract"}, {"claim": "Directly applying vector quantization to keys/values would hurt transformer accuracy due to limited representation capacity, motivating the combined RVQ+PVQ scheme", "support": "Stated rationale in the abstract for introducing the residual+product VQ combination", "loc": "Abstract"}], "results": ["3.54x energy efficiency improvement vs. state-of-the-art NVM-based CiM transformer designs", "4.53x throughput improvement vs. state-of-the-art NVM-based CiM transformer designs"], "limitations": ["Vector quantization of keys/values is inherently an approximation; while RVQ+PVQ is intended to mitigate accuracy loss, the abstract gives no explicit accuracy-retention numbers", "Evaluation basis (simulation vs. measured FeFET devices) and which Transformer models/datasets were tested are not specified in the abstract", "Comparisons are against other NVM-based CiM transformer designs rather than GPU or SRAM-CiM baselines, which may understate or overstate relative gains depending on what is being targeted"], "remarks": "This is a device/algorithm co-design approach to a well-known problem in CiM Transformer acceleration (dynamic attention VMMs vs. static-weight-friendly crossbars), using vector quantization as the bridge rather than analog-domain tricks or hybrid digital-SRAM designs (as in HARDSEA) or sparsity (as in CPSAA). The RVQ+PVQ combination is a sensible way to recover capacity, but the practical accuracy impact on real transformer benchmarks is the key open question that the abstract does not answer; the full paper should be checked for accuracy-vs-baseline numbers before citing this as an accuracy-neutral solution.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformer models have achieved state-of-the-art performance in various natural language processing (NLP) and computer vision (CV) tasks. To meet their substantial computational demands, the compute-in-memory (CiM) architectures, which alleviate the memory wall problem and enable efficient vector-matrix multiplication (VMM), have been adopted for transformer accelerators. However, the dynamic VMM involved in the attention mechanism, which necessitates runtime write operations, presents significant challenges for non-volatile memory (NVM)-based CiM designs. High write overhead, complex compute-write-compute (CWC) dependencies, and limited endurance reduce their effectiveness. In this paper, we propose VQT-CiM, a ferroelectric FET (FeFET)-based CiM design that accelerates vector quantization (VQ) enhanced transformers by eliminating the runtime write operations. VQT-CiM quantizes keys and values in self-attention to convert dynamic VMMs in inner-product and weighted-sum into static VMMs with the codebooks, enabling efficient calculations with CiM crossbars. However, directly applying VQ hinders the accuracy of transformer model due to its limited representation capability. To address this, we introduce a vector quantization scheme that integrates residual VQ (RVQ) and product VQ (PVQ) for enhanced representation space. We present an efficient hardware implementation for the proposed VQT-CiM with optimized dataflow in RVQ, which incorporates the FeFET-based CiM crossbars and peripheral digital circuits. Evaluation results suggest that VQT-CiM achieves the $3.54 \\times$ and $4.53 \\times$ improvements in energy efficiency and throughput, respectively, compared to state-of-the-art NVM-based CiM transformer designs.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Huang_VQTCiM_DAC.pdf", "analysed": true, "pdf": null, "priority": 5.42}, {"id": "W4413553738", "short": "HASTILY", "title": "HASTILY: Hardware-Software Co-Design for Accelerating Transformer Inference Leveraging Compute-in-Memory", "authors": ["Dong Eun Kim", "Tanvi Sharma", "Kaushik Roy"], "year": 2025, "venue": "IEEE transactions on circuits and systems for artificial intelligence.", "venue_short": "TCASAI", "venue_full": "IEEE Transactions on Circuits and Systems for Artificial Intelligence (2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcasai.2025.3601975", "cites_global": 3, "cat": "04", "seed": false, "devices": ["SRAM-analog"], "models": ["Transformer", "BERT"], "evidence": "simulation", "tldr": "HASTILY is an analog 8T-SRAM CIM accelerator for BERT whose arrays double as exponential lookup tables (UCLMs), combined with multi-core tree reduction for softmax and row-wise fine-grained pipelining; in PUMA-based simulation it reaches 158/263 TOPS and 8 TOPS/W on BERT-Base/Large, 4.4-9.8x faster than an A40 GPU.", "summary": "Softmax and the quadratically growing QK^T intermediate matrix limit CIM accelerators for Transformers, because CIM speeds up the MatMuls and leaves softmax on a narrow vector unit. HASTILY adds a lookup line to the source lines of 8T-SRAM analog CIM arrays, so the same 64x64 array can perform MVMs or act as a 128-entry 2^(i/K) table for the exponential (e^x = 2^n * 2^(d/K) * e^r), with no array area overhead in TSMC 65 nm. Softmax max/sum reductions are parallelised across cores and gathered in a binary tree, which reduces their complexity from N to log N. A fine-grained pipelining scheme streams one row vector at a time through Q/K/V projection, QK^T (K^T written into the next core's UCLMs as weights), softmax, xV and the FFN, so on-chip memory scales linearly with sequence length. A compiler with an extended ISA and a PUMAsim-based cycle-level simulator at 32 nm evaluate BERT-Base/Large at INT8 against an Nvidia A40 GPU and an SRAM-ized PUMA baseline.", "contributions": ["Unified compute-and-lookup module (UCLM): 8T-SRAM CIM array that also serves as an exponential lookup table, with no area overhead (TSMC 65 nm layout)", "Software-hardware softmax co-design: LUT-based exp, plus max/sum reductions spread across cores and combined in a tree (O(log N))", "Fine-grained, vector-level pipelining of attention and FFN within and across encoder layers, which makes intermediate memory linear rather than quadratic in sequence length", "Compiler/ISA extensions (transpose, multi-core max, tree reduce, SIMD exp) on top of the PUMA toolchain"], "claims": [{"claim": "The dual-function SRAM array adds lookup capability with no array area overhead.", "support": "\"the extra source line (LKL) does not add any extra area to the array\"; lookup latency 4 cycles", "loc": "Sec. III-A / Fig. 3(d)"}, {"claim": "UCLM-based softmax with multi-core reduction greatly cuts softmax latency at long sequences.", "support": "At l=8192 with ALU width 16, softmax latency drops from 22.13 us (PUMA) to 6 us (UCLM) and 1.36 us (UCLM + multi-core)", "loc": "Sec. VI-A / Fig. 7"}, {"claim": "Fine-grained pipelining and softmax acceleration together give large speedups over a baseline CIM accelerator.", "support": "4.47x speedup over PUMA at embedding 768, l=1024; 3.31x over pipelined PUMA at l=8192", "loc": "Sec. VI-B / Fig. 9"}, {"claim": "HASTILY outperforms an A40 GPU in throughput and energy efficiency on BERT.", "support": "158 TOPS (BERT-Base) and 263 TOPS (BERT-Large), up to 9.8x the GPU; ~8 TOPS/W vs 0.3-0.9 TOPS/W for the GPU", "loc": "Sec. VI-C / Figs. 12-13"}, {"claim": "The exponential LUT approximation is accurate.", "support": "K=128 gives error below 0.54% (e^r~1) and 0.0015% (e^r~1+r)", "loc": "Sec. III-B"}], "results": ["End-to-end throughput 4.4-9.8x vs Nvidia A40 GPU and 1.7-5.9x vs baseline CIM (PUMA with SRAM crossbars), BERT INT8", "Energy efficiency 16-36x vs A40 GPU; similar to the baseline CIM (ADC energy dominates both)", "Encoder-layer dynamic energy 10-68x lower than the GPU", "Softmax share of runtime at l=1024 reduced from 38% (PUMA) to 13%", "Accelerator area ~330 mm^2 at 32 nm (same as PUMA) vs 628.4 mm^2 for the A40"], "limitations": ["Simulation only (PUMAsim-based, scaled from 65 nm to 32 nm); no fabricated chip", "Analog non-idealities and accuracy are not evaluated; the paper assumes they can be handled by hardware-aware training", "Only encoder models (BERT-Base/Large); memory-bound decoder (GPT) generation is discussed as having limited benefit", "Assumes all weights and intermediates fit on-chip (DRAM only for initial inputs and outputs); batch scaling is limited to 2 by the pipelining memory needs", "GPU energy comparison uses nvidia-smi dynamic power and an under-utilised batch-1 GPU, which inflates the gains", "No energy advantage over the baseline CIM, because ADCs dominate energy"], "remarks": "A clean architectural idea: reuse CIM arrays as LUTs for nonlinear functions, plus vector-level pipelining that removes the O(l^2) intermediate-storage problem when mapping attention onto spatial CIM tiles. Writing K^T and V into SRAM CIM arrays as 'weights' at runtime is practical with SRAM but would be costly with NVM crossbars, so the work fits the SRAM-analog camp, unlike ReRAM attention designs such as ReTransformer and X-Former. The evidence is purely architectural simulation with no noise or accuracy analysis, so it says little about analog fidelity for Transformers. Because energy is ADC-bound, the gains come from latency/pipelining rather than better analog efficiency.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2502.12344", "abstract": "Transformers have become the backbone of neural network architecture for most machine learning applications. Their widespread use has resulted in multiple efforts on accelerating attention, the basic building block of transformers. This paper tackles the challenges associated with accelerating attention through a hardware-software co-design approach while leveraging compute-in-memory (CIM) architecture. In particular, our energy- and area-efficient CIM based accelerator, named HASTILY, aims to accelerate softmax computation, an integral operation in attention, and minimize their high on-chip memory requirements that grows quadratically with input sequence length. Our architecture consists of novel CIM units called unified compute and lookup modules (UCLMs) that integrate both lookup and multiply-accumulate functionality within the same SRAM array, incurring minimal area overhead over standard CIM arrays. Designed in TSMC 65nm, UCLMs can be used to concurrently perform exponential and matrix-vector multiplication operations. Complementing the proposed architecture, HASTILY features a fine-grained pipelining strategy for scheduling both attention and feed-forward layers, to reduce the quadratic dependence on sequence length to linear dependence.Further, for fast softmax computation which involves computing the maxima and sum of exponential values, such operations are parallelized across multiple cores using reduce and gather strategy. We evaluate our proposed architecture using a compiler tailored towards attention computation and a standard cycle-level CIM simulator. Our evaluation shows end-to-end throughput (TOPS) improvement of 4.4× −9.8×and 1.7× −5.9× over Nvidia A40 GPU and baseline CIM hardware, respectively, for BERT models with INT-8 precision. Additionally, it shows gains of 16× −36× in energy-efficiency (TOPS/W) over A40 GPU and similar energy-efficiency as baseline CIM hardware. Code base of our evaluation setup will be open-sourced at github.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Kim_HASTILY_TCASAI.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2025_Kim_HASTILY_TCASAI.pdf", "priority": 6.32}, {"id": "W4416963215", "short": "Cross-Type Mapped Dataflow", "title": "Optimizing Heterogeneous Compute-in-Memory with Hybrid Dataflow and In-Network Reduction for Vision Transformer", "authors": ["Zexin Fu", "Yihang Zuo", "Yuzhe Ma", "Jiayi Huang"], "year": 2025, "venue": "", "venue_short": "ISLPED", "venue_full": "2025 IEEE/ACM International Symposium on Low Power Electronics and Design (ISLPED 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/islped65674.2025.11261801", "cites_global": 1, "cat": "04", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["ViT"], "evidence": "simulation", "tldr": "A flat-NoC heterogeneous RRAM analog-CIM + SRAM digital-CIM architecture for ViTs that reuses idle DCIMs for static VMMs (Hybrid Dataflow) and reduces partial sums inside NoC routers (In-Network Reduction), reaching 4.63x speedup and 2.47-2.59x energy efficiency over an X-Former-like design in simulation.", "summary": "Heterogeneous CIM Transformer accelerators usually place static weight VMMs (QKV projection, FFN) on dense RRAM analog CIM and dynamic VMMs (QK^T, SV) on rewritable SRAM digital CIM, but this isolated mapping leaves one PE type idle and global reduction units add extra NoC hops. The authors propose a flat mesh NoC that connects individual PEs (ACIM:DCIM 3:1, plus SIMD and SRAM memory units) rather than tiles. A Hybrid Dataflow copies static weights row by row from ACIM to idle DCIMs so they can share the static VMM, and an In-Network Reduction scheme puts vector adders, operand buffers and flow behaviour tables into pipelined routers, with compile-time 'Intra-Block Zigzag' routing and deadlock analysis. A compiler handles partitioning, weight duplication, zigzag mapping and INR routing. They evaluate DeiT-Tiny/Small layers on a cycle-level simulator (NeuroSim v1.3, AutoDCIM data, BookSim/DSENT, CACTI) at 22 nm with 128x128 2-bit RRAM crossbars and 8-bit ADCs, and check accuracy with NeuroSim v2.1 non-ideality models.", "contributions": ["Flat (crossbar-PE level) mesh NoC heterogeneous ACIM/DCIM/SIMD/MU architecture for ViT instead of a 3-level tile hierarchy", "Hybrid Dataflow: idle SRAM DCIMs receive copies of RRAM-resident static weights via a pipelined read-transfer-write scheme to raise parallelism for static VMMs", "In-Network Reduction with active routers (operand buffers, shared vector adders, flow behaviour tables) and a deadlock-aware Intra-Block Zigzag routing algorithm", "End-to-end compiler with a Hybrid Dataflow predictor and an INR orchestrator, plus a cycle-level NoC-CIM simulator"], "claims": [{"claim": "Heterogeneous RRAM-ACIM + SRAM-DCIM with isolated mapping beats an area-matched homogeneous DCIM", "support": "average 3.57x speedup (max 16.67x) and 2.78x energy efficiency, because HomoDCIM has 3.64x/2.66x less weight capacity and must fetch weights from DRAM", "loc": "Sec. VI-B, Fig. 6"}, {"claim": "Hybrid Dataflow improves on isolated mapping and on X-Former's Sequence Blocking dataflow", "support": "1.93x speedup / 1.56x energy efficiency over IsolatedMap; 1.82x / 1.46x over XFormerLike", "loc": "Sec. VI-B"}, {"claim": "INR outperforms the prior INA in-network accumulation scheme on heterogeneous layouts", "support": "3.37x speedup / 2.63x EE over IsolatedMap and 1.63x / 1.47x over INA; INA routing failures 2/21 (DeiT-Small) and 12/51 (DeiT-Base) while INR always routes", "loc": "Sec. VI-B"}, {"claim": "Homogeneous RRAM ACIM is impractical for Transformers because dynamic weights must be rewritten", "support": "HomoACIM accuracy drops to 0.12% (DeiT-Tiny) and 1.38% (DeiT-Small), while HeteCIM keeps 71.88% / 79.74% at drift coefficient 0.001 over 10 s", "loc": "Sec. VI-C, Fig. 7"}, {"claim": "ADC resolution of 8 bits is needed for negligible accuracy loss", "support": "accuracy drops sharply at <=6-bit ADC; <1% loss at >=8 bits", "loc": "Sec. VI-C, Fig. 7"}], "results": ["3.57x average speedup and 2.78x energy efficiency for heterogeneous CIM (IsolatedMap) vs homogeneous DCIM at equal area", "HD+INR: 4.91x speedup and 2.64x energy efficiency over IsolatedMap; 4.63x speedup and 2.47x energy efficiency over XFormer-like design (abstract reports 2.59x)", "INR on DeiT-Small at 1x1 granularity: 4.28x speedup and 3.17x energy efficiency over INA", "DCIM PEs are 2.95-5.42x larger than RRAM ACIM PEs at 22 nm", "Accuracy with RRAM non-idealities: 71.88% DeiT-Tiny, 79.74% DeiT-Small (drift coefficient 0.001, 10 s); periodic recalibration needed at drift coefficient >= 0.003"], "limitations": ["Simulation only (NeuroSim-derived ACIM numbers, scaled AutoDCIM data, BookSim/DSENT); no silicon", "Evaluated only on small ViTs (DeiT-Tiny/Small single layers, with DeiT-Base only for routing-failure counts) and short token counts (SL 16-64)", "200 MHz clock, W8A8 I-ViT quantization; finite on/off ratio not modelled (assumed fixed by dummy columns)", "Energy-efficiency number over X-Former-like differs between abstract (2.59x) and results text (2.47x)", "Hybrid Dataflow copies weights into SRAM, which costs extra NoC traffic and write energy and only helps when DCIMs are idle long enough"], "remarks": "This is a careful architecture/NoC paper rather than a device paper: most of the gain comes from the scheduling and network side (PE utilization, removing reduction hops), not from analog compute. Its main lesson for crossbar mapping is that partial-sum reduction across tiles, caused by limited crossbar rows, can dominate NoC traffic and can be absorbed into routers. Its accuracy study (homogeneous RRAM collapsing to near 0% for ViTs) gives a simple simulated argument for the now-standard split: static weights on NVM, dynamic attention on SRAM. The evaluation is small (DeiT layers, SL<=64), and Harmony (2026) later builds a hardware-mapping co-exploration framework on top of this style of hybrid CIM ViT design.", "basis": "full-text", "pdf_source_url": "https://zyh0911.github.io/assets/pdf/ISLPED25_CIM.pdf", "abstract": "Transformer models have shown remarkable performance in AI tasks. However, their large model sizes and large-scale matrix computations heavily press the memory bandwidth. Compute-in-memory (CIM) solutions have emerged to address these issues by integrating computation into memory. Nevertheless, existing scalable and heterogeneous CIM designs further suffer from inefficiencies caused by isolated mapping strategies and communication redundancy. To address these issues, we propose Cross-Type Mapped Dataflow, an architecture-dataflow co-design that enables efficient and collaborative analog-digital CIM execution.Our approach features a heterogeneous analog-digital CIM architecture with flat network-on-chip (NoC) interconnects, enabling seamless cross-type communication. The core innovations include: a Hybrid Dataflow that schedules idle CIMs for cross-type collaboration on vector-matrix multiplication, and an In-Network Reduction (INR) mechanism that eliminates redundant data transfers by embedding Reduction operations within NoC communication. Experimental results show an average 3.57× speedup and 2.78× energy efficiency improvement over Homogeneous DCIM architecture. Optimized by the proposed Hybrid Dataflow and INR, our heterogeneous CIMs further achieve an average 4.63× speedup and 2.59× energy efficiency improvement over state-of-the-art X-Former-like design across various ViT workloads.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Fu_CrossTypeMappedDataflow_ISLPED.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2025_Fu_CrossTypeMappedDataflow_ISLPED.pdf", "priority": 6.11}, {"id": "W7117584415", "short": "RACE-IT", "title": "RACE-IT: A Reconfigurable Analog Computing Engine for In-Memory Transformer Acceleration", "authors": ["Lei Zhao", "Aishwarya Natarajan", "Luca Buonanno", "Archit Gajjar", "Ron M. Roth", "Sergey Serebryakov", "John Moon", "Omar Eldash", "Jim Ignowski", "Giacomo Pedretti"], "year": 2025, "venue": "", "venue_short": "ICCD", "venue_full": "2025 IEEE 43rd International Conference on Computer Design (ICCD 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccd65941.2025.00021", "cites_global": 1, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["BERT", "GPT/LLM", "CNN"], "evidence": "simulation", "tldr": "RACE-IT extends RRAM analog CAMs into a reconfigurable engine that computes any 1- or 2-variable function (activations, Softmax exponent and inverse, 4-bit products for dynamic matmuls) by bitwise range matching, so all Transformer operators stay in the analog/in-memory domain; it reports 453x speedup and 354x energy savings vs an H100 at batch size 1, and 15x / 122x vs prior Transformer IMC designs.", "summary": "Crossbar IMC accelerators handle static VMMs well but must send activations, Softmax and data-dependent matmuls (DMMuls) to fixed CMOS units (ISAAC), digital VFUs (PUMA) or input-written RRAM crossbars (ReTransformer, which suffers from slow writes and limited endurance). RACE-IT proposes a RACE cell built from three lower-bound and three upper-bound ACAM components (two TaOx RRAMs each) that implements either an 8-bit range check on one variable (by slicing into 4-bit MSB/LSB) or a 4-bit range check on two variables. Any quantized function is computed bit by bit, with one array row per output bit and one column per disjoint input range (a Karnaugh-map-like cover). Gray-code output encoding, applied up to three times, shrinks the arrays to 8x50 and is decoded with XOR gates. The 22 nm tile design follows ISAAC with one RACE unit per tile. RRAM noise in the RACE is handled by noise-aware fine-tuning that uses differentiable relaxations of the comparisons. Timeloop+Accelergy simulations compare against an H100, Eyeriss+Flex-SFU, PUMA and ReTransformer on BERT-base/GLUE, EfficientNet/CIFAR-10 and LLaMA-3.2 1B/3B (multi-chip).", "contributions": ["RACE cell: an ACAM extension supporting one-variable 8-bit and two-variable 4-bit range comparisons, configured only by programmed RRAM bounds", "A method to compute arbitrary quantized 1- and 2-variable functions (Tanh/GELU, exp, reciprocal, multiplication) as per-output-bit range covers mapped to RACE arrays; Softmax and DMMul done entirely in RACE", "Gray-code (multi-depth) output encoding that reduces the number of ranges and array size, with cheap XOR decoding", "SPICE-level cell validation in GF22FDX and noise-aware fine-tuning with differentiable two-variable comparison", "RACE-IT tiled architecture (ISAAC-like) and evaluation vs GPU, Eyeriss, PUMA, ReTransformer"], "claims": [{"claim": "RACE-IT is much faster and more energy-efficient than a GPU for single-batch Transformer/CNN inference", "support": "453x speedup and 354x energy savings on average vs NVIDIA H100 (BS=1)", "loc": "Sec. VIII-C, Fig. 11(b,c)"}, {"claim": "Doing non-VMM operators in analog CAMs beats Transformer-specific IMC accelerators", "support": "15x performance and 122x energy reduction over existing Transformer-specific IMC accelerators (ReTransformer)", "loc": "Abstract, Fig. 11"}, {"claim": "Gray-code depth 3 minimises RACE array size and EDP", "support": "array size and EDP minimum at depth 3; arrays set to 8x50", "loc": "Sec. VIII-B, Fig. 11(a)"}, {"claim": "RACE noise causes noticeable accuracy loss that noise-aware fine-tuning recovers", "support": "EfficientNet/CIFAR-10: 89.47 (RACE) -> 70.25 (RACE noise) -> 89.37 (NAF); BERT-base CoLA MCC 0.578 -> 0.515 -> 0.577", "loc": "Table III"}, {"claim": "The approach scales to billion-parameter LLMs via multi-chip deployment", "support": "LLaMA-3.2-1B and 3B need 3 and 8 chips; still hundreds of times speedup/energy savings vs GPU with 10 Gbps, 30 pJ/bit C2C links", "loc": "Sec. VIII-C, Fig. 11(d)"}], "results": ["453x speedup and 354x energy savings vs H100 on average at batch size 1", "15x speedup and 122x energy reduction vs Transformer-specific IMC accelerators (abstract)", "BERT-base GLUE accuracy after NAF within ~0.1-1 point of the ideal-RACE results (e.g., MRPC 84.21 vs 84.31; SST-2 91.69 vs 91.85)", "EfficientNet CIFAR-10: FP32 91.15, after NAF 89.37 (RACE noise without NAF 70.25)", "RACE array size 8x50 with Gray-code depth 3; RACE-IT fits BERT-base in one chip; LLaMA-3.2 1B/3B need 3/8 chips"], "limitations": ["Architecture-level simulation (Timeloop+Accelergy) plus single-cell SPICE; no fabricated RACE-IT chip", "Headline 453x is at batch size 1, where GPU utilization is poor; large-batch gains are smaller", "DMMuls are computed as 4-bit products composed into 8-bit, with RACE arrays per multiplication. The paper gives little analysis of throughput and area for long sequences or large attention matrices", "RRAM conductance range 0.1-150 uS and noise models from one TaOx device paper; ACAM precision limited to ~4 bits per device", "Requires noise-aware fine-tuning of stored bounds per model; LLaMA accuracy under noise not reported"], "remarks": "RACE-IT is an unusual answer to the 'non-VMM operators' problem of analog Transformer accelerators: instead of digital SFUs or rewriting crossbars, it treats every nonlinear or dynamic operator as a lookup implemented with analog CAM range matching, which avoids RRAM write endurance issues for attention. The large speedups mostly reflect a batch-1 GPU baseline and an idealised architecture model, so the 15x / 122x vs ReTransformer is the more meaningful comparison. Computing DMMuls through bitwise CAM lookups needs many arrays and is limited to low precision, and its scalability to long-context attention is still unproven. It builds on HPE's ACAM line (Li et al. 2020, X-TIME) and is relevant to anyone mapping Softmax/GELU onto memristive hardware.", "basis": "full-text", "pdf_source_url": "", "abstract": "Transformer models represent the cutting edge of Deep Neural Networks (DNNs) and excel in a wide range of machine learning tasks. However, processing these models demands significant computational resources and results in a substantial memory footprint. While In-memory Computing (IMC) offers promise for accelerating Vector-Matrix Multiplications (VMMs) with high computational parallelism and minimal data movement, employing it for other crucial DNN operators remains a formidable task. This challenge is exacerbated by the extensive use of complex activation functions, Softmax, and data-dependent matrix multiplications (DMMuls) within Transformer models. To address this challenge, we introduce a Reconfigurable Analog Computing Engine (RACE) by enhancing Analog Content Addressable Memories (ACAMs) to support broader operations. Based on the RACE, we propose the RACE-IT accelerator (meaning RACE for In-memory Transformers) to enable efficient analog-domain execution of all core operations of Transformer models. Given the flexibility of our proposed RACE in supporting arbitrary computations, RACE-IT is well-suited for adapting to emerging and non-traditional DNN architectures without requiring hardware modifications. We compare RACE-IT with various accelerators. Results show that RACE-IT increases performance by 453× and 15×, and reduces energy by 354× and 122× over the state-of-the-art GPUs and existing Transformer-specific IMC accelerators, respectively.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Zhao_RACE-IT_ICCD.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2025_Zhao_RACE-IT_ICCD.pdf", "priority": 5.21}, {"id": "W7130560115", "short": "ETA", "title": "ETA: Efficient Transformer Attention Mapping for ReRAM-Based Compute-In-Memory Architectures", "authors": ["Johnny Rhe", "Juhong Park", "Kang Eun Jeon", "Jong Hwan Ko"], "year": 2025, "venue": "", "venue_short": "APCCAS", "venue_full": "IEEE Asia Pacific Conference on Circuits and Systems (APCCAS 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/apccas67402.2025.11377506", "cites_global": 0, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["Transformer", "ViT", "GPT/LLM"], "evidence": "simulation", "tldr": "ETA is a mapping strategy for transformer attention on ReRAM-based CIM that overlaps computation with the frequent memory writes attention requires and reduces array count via array-aware mapping, cutting waiting-for-write time by up to 66%, latency by up to 20%, and array count by up to 29% versus prior methods on DeiT-small and GPT2-small (64x64 arrays).", "summary": "The paper targets the mismatch between transformer attention mechanisms and compute-in-memory (CIM) architectures: unlike static weight matrices, attention involves dynamically generated Q/K/V and attention-score matrices that must be frequently written into ReRAM arrays, and compute-write dependencies force the accelerator to wait for writes to finish before computing, inflating latency and wasting resources. ETA (Efficient Transformer Attention mapping) addresses the compute-write bottleneck by enabling parallel execution of computation and memory writes, so that a new write can proceed while a different computation is still utilizing the array, and reduces the number of required ReRAM arrays via an array-aware mapping strategy. The combination of overlap-friendly scheduling and reduced array footprint is evaluated on DeiT-small (a vision transformer) and GPT2-small using 64x64 ReRAM arrays, where ETA reduces waiting-for-write (W4W) time, overall latency, and array count versus prior state-of-the-art mapping methods.", "contributions": ["Identifies compute-write dependency as a key bottleneck for mapping transformer attention onto ReRAM CIM", "Proposes parallel execution of computation and memory writes to hide write latency behind other arrays' computation", "Array-aware mapping strategy that reduces the number of ReRAM arrays required for attention computation", "Evaluation on DeiT-small and GPT2-small with 64x64 arrays against prior state-of-the-art attention-mapping methods"], "claims": [{"claim": "ETA substantially reduces time spent waiting for crossbar writes during attention computation", "support": "Reduces waiting-for-write (W4W) by up to 66% vs. previous state-of-the-art methods", "loc": "Abstract"}, {"claim": "ETA's optimizations translate into end-to-end latency reduction", "support": "Latency reduced by up to 20%", "loc": "Abstract"}, {"claim": "ETA's array-aware mapping reduces hardware resource (array) requirements", "support": "Fewer arrays by up to 29%", "loc": "Abstract"}], "results": ["Up to 66% reduction in waiting-for-write (W4W) time vs. previous state-of-the-art", "Up to 20% latency reduction vs. previous state-of-the-art", "Up to 29% fewer arrays required vs. previous state-of-the-art", "Evaluated on DeiT-small and GPT2-small using 64x64 ReRAM arrays"], "limitations": ["Full text not accessible to this reviewer (APCCAS is not downloadable here and no arXiv preprint was found); the identity/configuration of the 'previous state-of-the-art' baselines could not be verified", "Evidence basis is simulation; only two model families evaluated (DeiT-small, GPT2-small), both at a single array size (64x64)"], "remarks": "Abstract-only assessment: APCCAS proceedings are not downloadable here and no preprint was found. The compute-write dependency problem for dynamic attention tensors on ReRAM CIM is a well-recognized challenge for mapping transformers to crossbars (since ReRAM writes are far slower/costlier than reads), and this paper's focus on overlapping writes with computation plus array-aware mapping is directly relevant to the mapping/compilation theme of this literature map; the magnitude of gains should be read against whatever specific baseline mapping schemes (e.g., ReTransformer/X-Former-style approaches) the full paper compares to.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformer models have set new performance benchmarks in vision and language applications. However, their attention mechanisms remain poorly suited for Compute-In-Memory (CIM) architectures due to frequent memory write and compute-write dependencies. These limitations often lead to increased latency and inefficient resource use. In this work, we propose Efficient Transformer Attention mapping (ETA), a novel approach optimized for ReRAM-based CIM systems. ETA alleviates the compute-write bottleneck by enabling parallel execution of computation and memory writes, and reduces the number of required arrays through an array-aware mapping strategy. This dual optimization leads to significant improvements in both energy efficiency and latency. Experimental results on DeiT-small and GPT2-small using$64 \\times 64$array demonstrate that ETA outperforms previous state-of-the-art methods, reducing waiting-for-write (W4W) by up to 66%, latency by up to 20%, and fewer arrays by up to 29%.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2025_Rhe_ETA_APCCAS.pdf", "analysed": true, "pdf": null, "priority": 5.0}, {"id": "W4403546214", "short": "ReCAT", "title": "A Cascaded ReRAM-based Crossbar Architecture for Transformer Neural Network Acceleration", "authors": ["Jiahong Xu", "Haikun Liu", "Xiaoyang Peng", "Zhuohui Duan", "Xiaofei Liao", "Hai Jin"], "year": 2024, "venue": "ACM Transactions on Design Automation of Electronic Systems", "venue_short": "TODAES", "venue_full": "ACM Transactions on Design Automation of Electronic Systems (2024)", "venue_ok": true, "doi": "https://doi.org/10.1145/3701034", "cites_global": 6, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["Transformer"], "evidence": "algorithm+simulation", "tldr": "ReCAT is a ReRAM PIM accelerator for Transformers that cascades pairs of crossbar arrays via transimpedance amplifiers so attention matrix-matrix-multiply intermediates are passed directly between crossbars without ADC/DAC conversion, plus ADC virtualization for sharing scarce ADCs, giving 207.3x/2.11x/3.06x speedup over GPU/ReBERT/ReTransformer.", "summary": "ReRAM-based PIM accelerators excel at in-situ matrix-vector multiplication but struggle with Transformers, which require a chain of matrix-matrix multiplications (MatMuls) with data dependencies (e.g. in self-attention), forcing intermediate results to be written back to crossbar arrays for the next MatMul; this incurs high ReRAM write latency and causes intra-layer pipeline stalls in conventional designs. ReCAT addresses this by cascading pairs of crossbar arrays through transimpedance amplifiers (TIAs), so that the analog output current of one crossbar (representing an intermediate MatMul result) can be fed directly as the input of a second crossbar, skipping the analog-to-digital conversion and explicit ReRAM-write step that conventional designs need between dependent MatMuls. This lets MVM computation overlap with data mapping, hiding ReRAM write latency. A second contribution, ADC virtualization, dynamically shares a limited pool of ADCs across a group of crossbar arrays to raise ADC utilization and remove it as the throughput bottleneck. Evaluated against GPUs, ReBERT, and ReTransformer (both in-set references representing prior ReRAM Transformer accelerators), ReCAT achieves average speedups of 207.3x, 2.11x, and 3.06x respectively.", "contributions": ["Cascaded crossbar-array design using transimpedance amplifiers (TIAs) to chain dependent matrix-matrix multiplications (notably self-attention) without intermediate ADC/DAC conversion or explicit ReRAM writes", "Overlap of MVM computation with data mapping, hiding the high latency of ReRAM writes that plague prior Transformer-on-ReRAM designs", "An ADC virtualization scheme that dynamically shares scarce ADCs among groups of crossbar arrays to improve utilization and remove the ADC bottleneck", "System-level evaluation against GPU, ReBERT, and ReTransformer baselines showing large average speedups"], "claims": [{"claim": "Cascading crossbar arrays via TIAs eliminates the need for costly ADC conversion between dependent MatMuls in attention", "support": "'the intermediate result of a MatMul generated by one crossbar array can be directly mapped to another crossbar array, avoiding costly analog-to-digital conversions'", "loc": "Abstract"}, {"claim": "ReCAT substantially outperforms GPUs and prior ReRAM-based Transformer accelerators", "support": "207.3x, 2.11x, and 3.06x average performance improvement vs GPUs, ReBert, and ReTransformer respectively", "loc": "Abstract"}, {"claim": "ADC virtualization improves ADC utilization and removes it as the MVM performance bottleneck", "support": "stated mechanism and motivation in abstract", "loc": "Abstract"}], "results": ["207.3x average performance improvement over GPUs", "2.11x average performance improvement over ReBert", "3.06x average performance improvement over ReTransformer"], "limitations": ["Abstract-only analysis in this record: full text unavailable, so circuit-level feasibility of TIA cascading (noise accumulation across cascaded analog stages, linearity, calibration) and benchmark details could not be verified", "As with most ReRAM Transformer accelerator papers, evidence is presumably simulation-based rather than measured silicon (not confirmed without full text)", "GPU baseline comparison (207.3x) likely reflects a different power/area class of hardware, making that specific multiplier less informative than the more comparable ReBert/ReTransformer numbers"], "remarks": "ReCAT extends the cascaded-crossbar idea (seen in CASCADE for CNNs) specifically to Transformer self-attention, directly addressing the write-latency and pipeline-stall problems that ReTransformer and other ReRAM Transformer accelerators (both in-set references here) are known to suffer from. The analog current-domain cascading via TIAs is an elegant way to avoid ADC/DAC overhead between dependent MatMuls, but analog signal integrity across multiple cascaded crossbar stages is a known risk area (noise/offset accumulation) that would need full-text circuit analysis to assess; this could not be done from the abstract alone.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Emerging resistive random-access memory (ReRAM) based processing-in-memory (PIM) accelerators have been increasingly explored in recent years because they can efficiently perform in-situ matrix-vector multiplication (MVM) operations involved in a wide spectrum of artificial neural networks. However, there remain significant challenges to apply existing ReRAM-based PIM accelerators to the most popular Transformer neural networks. Since Transformers involve a series of matrix-matrix multiplication (MatMul) operations with data dependencies, they should write intermediate results of MatMuls to ReRAM crossbar arrays for further processing. Conventional ReRAM-based PIM accelerators often suffer from high latency of ReRAM writes and intra-layer pipeline stalls. In this paper, we propose ReCAT, a ReRAM-based PIM accelerator designed particularly for Transformers. ReCAT exploits transimpedance amplifiers (TIAs) to cascade a pair of crossbar arrays for MatMul operations involved in the self-attention mechanism. The intermediate result of a MatMul generated by one crossbar array can be directly mapped to another crossbar array, avoiding costly analog-to-digital conversions. In this way, ReCAT allows MVM operations to overlap with the corresponding data mapping, hiding the high latency of ReRAM writes. Furthermore, we propose an analog-to-digital converter (ADC) virtualization scheme to dynamically share scarce ADCs among a group of crossbar arrays, and thus significantly improve the utilization of ADCs to eliminate the performance bottleneck of MVM operations. Experimental results show that ReCAT achieves 207.3×, 2.11×, and 3.06× performance improvement on average compared with other Transformer acceleration solutions—GPUs, ReBert, and ReTransformer, respectively.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2024_Xu_ReCAT_TODAES.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2024_Xu_ReCAT_TODAES.pdf", "priority": 5.59}, {"id": "W4409285593", "short": "AESHA", "title": "AESHA: Accelerating Eigen-decomposition-based Sparse Transformer with Hybrid RRAM-SRAM Architecture", "authors": ["Xuliang Yu", "Tianwei Ni", "Xinsong Sheng", "Yun Pan", "Lei He", "Liang Zhao"], "year": 2024, "venue": "", "venue_short": "ICCAD", "venue_full": "Proceedings of the 43rd IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2024)", "venue_ok": true, "doi": "https://doi.org/10.1145/3676536.3676660", "cites_global": 5, "cat": "04", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["Transformer", "BERT", "ViT"], "evidence": "simulation", "tldr": "AESHA is a hybrid RRAM-SRAM compute-in-memory Transformer accelerator that uses eigen-decomposition of WQW_K^T plus systolic in-memory attention reconstruction to avoid ever writing intermediate attention results into RRAM (sidestepping its endurance limit), reporting up to 7.84x RRAM memory footprint reduction and up to 3170x speedup / 336,000x energy reduction over various baselines.", "summary": "Prior CIM-based Transformer accelerators built on emerging non-volatile memories (eNVM, e.g. RRAM) mostly accelerate the vector-matrix multiplications needed to produce Q, K, V, but many designs store large volumes of dynamically changing intermediate attention results directly in eNVM arrays, which is unrealistic given RRAM's limited write endurance. AESHA proposes a hybrid RRAM-SRAM CIM architecture that exploits an eigen-decomposition of the product W_Q W_K^T: because this product can be expressed via symmetric/skew-symmetric real matrix structure, attention computation is split into an RRAM-based sparse feature transformation (using RRAM's static, written-once weight storage) and an SRAM-based systolic in-memory attention reconstruction (for the dynamic, per-input intermediate values), so that RRAM arrays are never written to at runtime, eliminating the endurance problem entirely. The architecture is evaluated on BERT-Base, BERT-Large, BigBird, Sanger, ViT-Base, and ViT-Large, measuring RRAM memory footprint, speed, and energy versus CPU, GPU, and other CIM Transformer accelerators (ReBERT, ReTransformer, CPSAA).", "contributions": ["Identifies and addresses the RRAM write-endurance problem in prior CIM Transformer accelerators that store dynamic intermediate attention results in eNVM", "Proposes an eigen-decomposition-based reformulation of W_Q W_K^T that separates static (RRAM-mappable) and dynamic (SRAM-mappable) attention computation", "Introduces 'systolic in-memory attention reconstruction' to perform the dynamic part of attention computation in SRAM without needing RRAM runtime writes", "Eliminates all runtime write access to RRAM arrays, directly removing the endurance bottleneck for CIM Transformer acceleration", "Evaluates across six Transformer/ViT benchmarks against CPU, GPU, and three prior CIM Transformer accelerators (ReBERT, ReTransformer, CPSAA)"], "claims": [{"claim": "AESHA substantially reduces RRAM memory footprint by avoiding storage of large intermediate attention matrices", "support": "2.59x, 2.69x, 2.62x, 2.58x, 3.08x and 7.84x maximum static RRAM memory footprint reduction on BERT-Base, BERT-Large, BigBird, Sanger, ViT-Base and ViT-Large respectively, versus vanilla computation stack", "loc": "Abstract"}, {"claim": "AESHA eliminates the RRAM endurance bottleneck entirely", "support": "The design eliminates all runtime write access to the RRAM arrays", "loc": "Abstract"}, {"claim": "AESHA achieves large speedups and energy reductions over CPU/GPU and prior CIM Transformer accelerators", "support": "3170.0x, 95.6x, 4.1x, 19.0x, and 19.2x speedup, and 336.0K x, 12.6K x, 7.3x, 23.1x, and 25.8x energy reduction over CPU, GPU, ReBERT, ReTransformer, and CPSAA respectively", "loc": "Abstract"}], "results": ["RRAM static memory footprint reduction: 2.59x (BERT-Base), 2.69x (BERT-Large), 2.62x (BigBird), 2.58x (Sanger), 3.08x (ViT-Base), 7.84x (ViT-Large) vs. vanilla computation stack", "Speedup: 3170.0x vs CPU, 95.6x vs GPU, 4.1x vs ReBERT, 19.0x vs ReTransformer, 19.2x vs CPSAA", "Energy reduction: 336.0K x vs CPU, 12.6K x vs GPU, 7.3x vs ReBERT, 23.1x vs ReTransformer, 25.8x vs CPSAA", "Zero runtime write accesses to RRAM arrays (endurance limit circumvented by design)"], "limitations": ["Analysis based on the abstract only; full text was not accessible (not found via arXiv or other legitimate open-access sources), so the architectural/circuit details, exact experimental setup, and whether results are simulation-based could not be independently verified beyond the abstract's self-description", "The eigen-decomposition approach relies on mathematical structure (symmetric/skew-symmetric decomposition of W_Q W_K^T) that may not generalize to all attention variants or multi-head configurations without further adaptation", "Headline speedup/energy numbers span a very wide range (e.g., 4x-3170x) depending on baseline, making it hard to assess typical real-world gain without more context from the full paper"], "remarks": "AESHA targets a genuine and often glossed-over hardware constraint for RRAM-based Transformer accelerators: non-volatile memory write endurance makes storing per-input dynamic intermediate values in RRAM impractical, a point many other CIM-Transformer designs in this collection (e.g., HARDSEA, X-Former) do not fully resolve. The eigen-decomposition reformulation that confines RRAM to static, write-once weight storage while handling dynamic computation in SRAM is an elegant systems-level fix, though the extremely large reported speedup/energy ratios (especially vs. CPU) should be interpreted cautiously without the full paper's experimental methodology.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Compute-in-memory (CIM) architectures based on emerging nonvolatile memories (eNVM) are recognized as promising candidates for the efficient computation of self-attention-based Transformer models, which are bounded by memory-intensive dynamic computations involving large matrices. However, existing CIM-based approaches mostly focused on the acceleration of vector-matrix multiplications (VMM) to obtain Q, K and V matrices for direct or sparse calculations of the vanilla Transformer. By storing large amounts of intermediate results in eNVM, the endurance limit is ignored which contradicts the reality of these technologies. In this work, a hybrid RRAM-SRAM CIM architecture to accelerate Transformers, namely AESHA, is proposed based on the eigen-decomposition of WQWTK and the systolic in-memory attention reconstruction. By utilizing the features of symmetric/skew-symmetric real matrices, AESHA translates dynamic attention computation to RRAM-based sparse feature transformation and SRAM-based systolic attention reconstruction to fully exploit the advantages of both on the architectural level. Experiments on a broad spectrum of benchmarks demonstrate that AESHA delivers superior performance in terms of pipeline optimization and energy efficiency. Specifically, AESHA achieves 2.59×, 2.69×, 2.62×, 2.58×, 3.08× and 7.84× maximum static RRAM memory footprint reduction in BERT-Base, BERT-Large, BigBird, Sanger, ViT-Base and ViT-Large over vanilla computation stack, respectively. It eliminates all runtime write access to the RRAM arrays to circumvent the endurance limit. Additionally, AESHA demonstrates 3170.0×, 95.6×, 4.1×, 19.0×, and 19.2× speedup, and 336.0K×, 12.6K×, 7.3×, 23.1×, and 25.8× energy reduction over CPU, GPU, ReBERT, ReTransformer, and CPSAA, respectively.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2024_Yu_AESHA_ICCAD.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2024_Yu_AESHA_ICCAD.pdf", "priority": 6.45}, {"id": "W4401070622", "short": "ClipFormer", "title": "ClipFormer : Key–Value Clipping of Transformers on Memristive Crossbars for Write Noise Mitigation", "authors": ["Abhiroop Bhattacharjee", "Abhishek Moitra", "Priyadarshini Panda"], "year": 2024, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2024.3435762", "cites_global": 5, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["ViT", "Transformer"], "evidence": "algorithm+simulation", "tldr": "Shows that the dynamically written K and V matrices make ViTs highly vulnerable to NVM write noise on crossbars, and proposes ClipFormer, a training-free conductance shift-and-clip of K/V that recovers up to ~40% ImageNet accuracy at high write noise.", "summary": "When attention is computed on memristive crossbars, the input-dependent K and V matrices must be re-programmed for every input, so they suffer stochastic write noise (in addition to read noise), unlike weight-stationary layers. Using a Python crossbar emulator (ViT-X; 64x64 RRAM arrays, 2 bits/cell with bit-slicing, 8-bit inputs, 6-bit ADC, conductance-proportional write-noise model with factor gamma), the authors show pre-trained DeiT-S loses up to ~57% accuracy. ClipFormer exploits the fact that write noise grows with conductance: it shifts K/V conductances down by alpha*G_MIN (floored at G_MIN) and clips at beta*G_MAX, increasing the share of low-conductance cells. This raises per-block SNR by ~1.5-1.9 dB and improves non-ideal accuracy of DeiT-S, token-pruned DeiT-S and LV-ViT-S, both for standard and variation-aware-trained (VAT) models. With beta=0.25 the K/V need only 6-bit conductances, saving one of four bit-sliced crossbars and giving ~7-8% attention area/energy reduction.", "contributions": ["First analysis of pre-trained ViT vulnerability to NVM write noise on the dynamically programmed K and V operands of attention.", "ClipFormer: an inference-only, hardware-agnostic two-stage shift/clip transformation of K/V conductances (parameters alpha, beta).", "ViT-X: a Python crossbar emulation framework for ViTs with read/write noise and an energy/area estimator.", "Shows ClipFormer composes with variation-aware training and gives a by-product 7-8% attention area/energy saving."], "claims": [{"claim": "Standard pre-trained ViTs suffer large accuracy losses on non-ideal RRAM crossbars due to write noise on K/V.", "support": "Standard pre-trained models lose ~6.5-57.2% vs software baseline across gamma=3-5 (e.g. DeiT-S 79.76% -> 22.59% at gamma=5).", "loc": "Sec. VI-A, Table II"}, {"claim": "ClipFormer substantially recovers accuracy without retraining.", "support": "+~3-5% at low gamma and ~23-44% at high gamma for standard models; DeiT-S at gamma=5 goes 22.59% -> 64.05%.", "loc": "Sec. VI-A, Table II"}, {"claim": "ClipFormer is complementary to variation-aware training.", "support": "VAT DeiT-S at gamma=5: 57.50% -> 69.21%; VAT Sparse DeiT-S and LV-ViT-S +1.6-12.4%.", "loc": "Table II"}, {"claim": "Write-noise impact on weights is independent of device ON/OFF ratio, so higher ON/OFF devices do not solve it.", "support": "Sparse DeiT-S accuracy unchanged when ON/OFF ratio varied 25-100.", "loc": "Sec. VI-C, Fig. 9, Appendix"}, {"claim": "VAT is costly and unstable for high write noise.", "support": "VAT training per epoch is 5x more expensive than standard training; VAT with gamma>2 on K/V does not converge.", "loc": "Sec. V, Fig. 7, Table III"}], "results": ["DeiT-S (standard) on ImageNet-1k at gamma=5: 22.59% untransformed vs 64.05% with ClipFormer (alpha=2, beta=0.25); software baseline 79.76%.", "LV-ViT-S (standard) at gamma=5: 41.52% -> 64.63%; VAT LV-ViT-S at gamma=5: 67.8% -> 72.14%.", "Average per-block SNR improvement ~1.5-1.9 dB at gamma=4.", "~7-8% reduction in total attention area and energy with beta=0.25 (6-bit K/V conductances, 3 instead of 4 bit-sliced crossbars).", "RRAM crossbars vs digital SRAM IMC for DeiT-S attention: ~5.1x lower area and ~2.3x lower energy (motivating radar chart)."], "limitations": ["Simulation only with a simple Gaussian, conductance-proportional write-noise model; gamma values 3-5 are assumed rather than device-characterized.", "Ignores interconnect parasitics (justified by 100 kOhm R_MIN) and models ADC only implicitly; softmax/LayerNorm/GELU assumed digital and ideal.", "Best (alpha, beta) chosen heuristically per model and noise level, i.e. effectively tuned on the evaluation setting.", "Assumes K/V are written into NVM crossbars per input, a design choice many accelerators avoid (they compute QK^T/SV digitally); relevance depends on that architecture.", "Only small ViTs (DeiT-S, LV-ViT-S) on ImageNet; no NLP/LLM models. Text analysed is the arXiv version; the TCAD version may contain extended results."], "remarks": "A useful, clearly reasoned observation: writing activations (K/V) into NVM makes write noise, not read noise, the dominant error source, which argues for keeping the dynamic attention MatMuls in digital/SRAM CIM or in low-write-noise devices. The fix is essentially conductance-range compression and is cheap, but the evidence rests entirely on an idealised noise model with tuned hyperparameters. It complements the same group's hardware-aware ViT work (e.g. X-Former) and is relevant to any design that, like ReTransformer-style accelerators, programs K/V into crossbars.", "basis": "full-text", "pdf_source_url": "", "abstract": "Transformers have revolutionized various real-world applications from natural language processing to computer vision. However, traditional von-Neumann computing paradigm faces memory and bandwidth limitations in accelerating transformers owing to their massive model sizes. To this end, in-memory computing (IMC) crossbars based on nonvolatile memories (NVMs), due to their ability to perform highly parallelized matrix-vector multiplications (MVMs) with high energy efficiencies, have emerged as a promising solution for accelerating transformers. However, analog MVM operations in crossbars introduce nonidealities, such as stochastic read and write noise, which affect the inference accuracy of the deployed transformers. Specifically, we find pretrained vision transformers (ViTs) to be vulnerable on crossbars due to the impact of write noise on the dynamically generated key$(K)$and value$(V)$matrices in the attention layers, an effect not accounted for in prior studies. We, thus, propose ClipFormer, a transformation on the K and V matrices during inference, to boost the nonideal accuracies of pretrained ViT models. ClipFormer requires no additional hardware and training overhead and is amenable to transformers deployed on any memristive crossbar platform impacted by write nonidealities. Our experiments on Imagenet-1k dataset using pretrained DeiT-S transformers, subjected to standard training and variation-aware training, show >10%–40% higher nonideal accuracies at the high write noise regime by applying ClipFormer.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2024_Bhattacharjee_ClipFormer_TCAD.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2024_Bhattacharjee_ClipFormer_TCAD.pdf", "priority": 6.45}, {"id": "W4393168980", "short": "PRIMATE", "title": "PRIMATE: Processing in Memory Acceleration for Dynamic Token-pruning Transformers", "authors": ["Yue Pan", "Minxuan Zhou", "Chonghan Lee", "Zheyu Li", "Rishika Kushwah", "Vijaykrishnan Narayanan", "Tajana Rosing"], "year": 2024, "venue": "", "venue_short": "ASP-DAC", "venue_full": "29th Asia and South Pacific Design Automation Conference (ASP-DAC 2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/asp-dac58780.2024.10473968", "cites_global": 3, "cat": "04", "seed": false, "devices": ["DRAM"], "models": ["ViT", "BERT", "RoBERTa", "Transformer"], "evidence": "simulation", "tldr": "HBM2E-based bit-serial PIM framework for dynamic token-pruning Transformers that adds near-channel Top-k Engines and a pipelined, per-layer memory-partitioning optimizer (PrimateOpt), reaching up to 30.6x throughput, 29.5x space efficiency and 4.3x energy efficiency over TransPIM.", "summary": "Dynamic token pruning shrinks Transformer compute, but on existing PIM (TransPIM) it needs host-CPU top-k selection (up to 25% latency penalty) and leaves pruned tokens' memory scattered and under-utilised, so a workload with 3.2x theoretical speedup yields only 1.5x. PRIMATE keeps TransPIM's token-based dataflow and bit-serial processing-using-memory with near-bank reduction, and adds per-channel Top-k Engines (8-bit accumulators, segmented top-k buffer in reserved DRAM, bitonic sorter/merger) to compute token importance and select tokens in memory. On the software side it pipelines layers across inputs on dedicated memory partitions, sized by PrimateOpt via layer-wise exploration of token density vs quantity, stack-aligned global adjustment, and layer merging. Evaluated with a Ramulator-like simulator on 8 HBM2E stacks with ViT, BERT and RoBERTa token-pruned workloads (8-bit).", "contributions": ["Identifies two blockers for token pruning on PIM: lack of in-memory top-k and memory under-utilisation after pruning", "Near-channel Top-k Engines with accumulators, segmented sorted buffer and bitonic sorter/merger (2.53 mm2, 2.3% of an HBM2E stack, 1.3 W)", "Inter-layer pipelined mapping on pre-allocated memory partitions to recover utilisation under non-uniform pruned layer sizes", "PrimateOpt: layer-wise exploration, global stack-alignment adjustment and layer merging for throughput and space efficiency"], "claims": [{"claim": "Existing PIM Transformer accelerators cannot exploit dynamic token pruning", "support": "TransPIM can only provide 1.5x speedup when the workload allows 3.2x theoretical speedup (69% computation pruned); CPU top-k incurs up to 25% latency penalty", "loc": "Sec. III-A"}, {"claim": "PRIMATE greatly outperforms TransPIM on token-pruned workloads", "support": "up to 30.6x (avg 21x) throughput, up to 29.5x (avg 18.9x) space efficiency, up to 4.3x (avg 3.8x) energy efficiency on W1-W4", "loc": "Sec. VI-B, Fig. 8-9"}, {"claim": "In-memory top-k removes sorting overhead", "support": "sorting overhead reduced from 9.2%, 25.2%, 2.8%, 5.4% to an average of 0.14%; up to 90x better standalone sorting cost", "loc": "Sec. VI-C"}, {"claim": "Layer-wise exploration beats naive partitioning", "support": "average 1.67x and up to 2.11x reduction in critical pipeline runtime, saving up to 46.7% memory banks", "loc": "Sec. VI-D, Fig. 7"}], "results": ["Up to 30.6x throughput, 29.5x throughput/GB and 4.3x throughput/J vs TransPIM (HPCA'22)", "Global adjustment: +23.7%, 7.0%, 16.7%, 0% throughput on W1-W4; layer merging: +11.7%, 18%, 0%, 26.2% throughput per GB", "Top-k engine overhead: 2.53 mm2 (2.3% of one HBM2E stack), 1.3 W", "Pruned models reach 91.1%, 89.6%, 92.7%, 87.1% accuracy on W1-W4, comparable to unpruned baselines"], "limitations": ["Digital DRAM bit-serial PIM; no analog crossbars, so relevance to analog CIM is limited to dataflow/pipelining ideas", "Simulation only (in-house Ramulator-like simulator, 32nm synthesis scaled to 10nm); TransPIM baseline re-modelled by the authors", "Gains are largely throughput from pipelining many inputs: per-inference latency and batch-1 behaviour not emphasised", "Small/medium encoder models only (ViT, BERT, RoBERTa); no autoregressive LLM decoding", "Weights duplicated in every bank for token-based dataflow, which costs capacity"], "remarks": "PRIMATE is a solid incremental follow-up to TransPIM from the same group, showing that algorithmic dynamic sparsity (token pruning) needs explicit hardware support (top-k, re-partitioning) to pay off on PIM. For analog-crossbar research its main transferable lesson is that dynamic sparsity breaks static layout/mapping and that pipelined per-layer partitioning is needed to keep arrays utilised. The paper explicitly avoids ReRAM, citing numerical instability of NVM, and positions X-Former and TransPIM only as related PIM work.", "basis": "full-text", "pdf_source_url": "https://par.nsf.gov/servlets/purl/10534271", "abstract": "Attention-based models such as Transformers represent the state of the art for various machine learning (ML) tasks. Their superior performance is often overshadowed by the substantial memory requirements and low data reuse opportunities. Processing in Memory (PIM) is a promising solution to accelerate Transformer models due to its massive parallelism, low data movement costs, and high memory bandwidth utilization. Existing PIM accelerators lack the support for algorithmic optimizations like dynamic token pruning that can significantly improve the efficiency of Transformers. We identify two challenges to enabling dynamic token pruning on PIM-based architectures: the lack of an in-memory top-k token selection mechanism and the memory underutilization problem from pruning. To address these challenges, we propose PRIMATE, a software-hardware co-design PIM framework based on High Bandwidth Memory (HBM). We initiate minor hardware modifications to conventional HBM to enable Transformer model computation and top-k selection. For software, we introduce a pipelined mapping scheme and an optimization framework for maximum throughput and efficiency. PRIMATE achieves $30.6\\times$ improvement in throughput, $29.5\\times$ improvement in space efficiency, and $4.3\\times$ better energy efficiency compared to the current state-of-the-art PIM accelerator for Transformers.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2024_Pan_PRIMATE_ASP-DAC.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2024_Pan_PRIMATE_ASP-DAC.pdf", "priority": 5.42}, {"id": "W4403600569", "short": "TReX", "title": "TReX- Reusing Vision Transformer’s Attention for Efficient Xbar-Based Computing", "authors": ["Abhishek Moitra", "Abhiroop Bhattacharjee", "Youngeun Kim", "Priyadarshini Panda"], "year": 2024, "venue": "IEEE Transactions on Emerging Topics in Computing", "venue_short": "TETC", "venue_full": "IEEE Transactions on Emerging Topics in Computing (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tetc.2024.3480524", "cites_global": 3, "cat": "04", "seed": false, "devices": ["FeFET", "SRAM-analog"], "models": ["ViT", "BERT", "Transformer"], "evidence": "algorithm+simulation", "tldr": "TReX removes the attention block from selected ViT encoders and reuses the previous encoder's attention output via a small transform block, chosen to meet a delay target on IMC hardware, giving 2.3x (DeiT-S) / 2.19x (LV-ViT-S) EDAP reduction at ~1% accuracy loss on FeFET crossbars.", "summary": "On IMC crossbars, ViT attention blocks dominate energy, delay (~80% of delay due to crossbar writes of K^T and V) and area. TReX is an algorithm-hardware co-optimization that lets some encoders reuse the concatenated attention output of a preceding encoder through a lightweight transformation block (LayerNorm + d x d FC + GELU), deleting their QKV, QK^T, softmax and SV computation. A simulator (TReX-Sim; NeuroSim-style tiled architecture with 64x64 2-bit FeFET or 1-bit SRAM crossbars, flash ADCs, LUT-based digital softmax, explicit crossbar write cost for K^T/V) determines the number of reuse encoders that meets a user delay target; uniform reuse patterns (strided/continuous/pyramid) are partially trained on 20% of ImageNet and the best is fine-tuned with IMC variation-aware training. TReX beats token pruning (DynamicViT), weight sharing (MiniViT) and ReTransformer on EDAP-accuracy trade-off when all are mapped on TReX-Sim, and a hybrid mapping (attention MatMuls on SRAM, weights on FeFET) further improves EDAP and non-ideal accuracy. It also extends to BERT-Base on CoLA.", "contributions": ["Attention-reuse ViT optimization (TReX) with transformation blocks and delay-constrained selection of the number/location of reusing encoders.", "TReX-Sim: IMC benchmarking platform for ViTs on FeFET and SRAM crossbars that explicitly accounts for K^T/V crossbar write energy/delay and a digital LUT softmax.", "Uniform reuse-pattern search that cuts search GPU-hours by 23.1x vs random patterns (100x cheaper than training DeiT-S from scratch).", "Hybrid FeFET-SRAM mapping in which write-heavy attention MatMuls go to SRAM IMC to improve both EDAP and non-ideal accuracy."], "claims": [{"claim": "Attention dominates IMC ViT cost, with crossbar writes of K^T and V a major delay contributor.", "support": "Write operations inside the attention block contribute ~80% of overall delay (64x64 FeFET implementation).", "loc": "Sec. I, Fig. 1b"}, {"claim": "Attention reuse gives large EDAP reduction at near-iso accuracy.", "support": "2.3x (2.19x) EDAP reduction and 1.86x (1.79x) TOPS/mm^2 improvement with ~1% accuracy drop for DeiT-S (LV-ViT-S); TReX-D-4 reaches 6.3x EDAP reduction.", "loc": "Abstract, Tables IV-V"}, {"claim": "Prior IMC transformer dataflows give little benefit once write cost is modelled realistically.", "support": "ReTransformer reduces EDAP by only 1.03x on TReX-Sim because FeFET write delay is ~10^3x read delay.", "loc": "Sec. VII-B, Fig. 13a"}, {"claim": "TReX beats token pruning and weight sharing on EDAP-accuracy.", "support": "Token pruning: 1.3x EDAP at 79.3% acc (2.2x at 7.4% drop); weight sharing WS=2: 2x EDAP at 78.3%, WS=3 drops to 60%; TReX-D-9: 1.6x EDAP at 79.3%, 2.3x at ~1.2% drop.", "loc": "Sec. VII-B, Fig. 13"}, {"claim": "Attention reuse also works for NLP.", "support": "BERT-Base on CoLA: 2% higher non-ideal accuracy at 1.6x lower EDAP (TReX-B-7/B-6); 3.5x EDAP at 8% drop.", "loc": "Sec. VII-F, Fig. 18"}], "results": ["DeiT-S on 64x64 2-bit FeFET IMC: EDAP 1115.23 -> 484.15 mJ·ms·mm^2 (2.3x) for TReX-D-7, up to 177.6 (6.3x) for TReX-D-4.", "LV-ViT-S: up to 2.57x EDAP reduction at ~1.5% NI-accuracy drop; up to 5.57x at 3-5% drop.", "TReX-Sim (FeFET) DeiT-S throughput exceeds Raspberry-Pi 4 CPU, FPGA systolic array and Jetson Orin Nano GPU by 68x, 12x and 2x at ~10^3x lower power; TReX-D-9 adds 1.3x throughput.", "TOPS/W improves only modestly (1.03-1.11x); gains are mainly in delay and area (TOPS/mm^2 up to 4.21x)."], "limitations": ["Simulation-only, with NeuroSim-derived FeFET/SRAM component numbers; non-idealities limited to read/write variation and ADC quantization (no IR drop).", "Requires retraining/fine-tuning (partial training per pattern plus full variation-aware fine-tuning), unlike post-training approaches.", "Evaluated on small isotropic models (DeiT-S, LV-ViT-S, BERT-Base on CoLA only); applicability to LLMs/hierarchical ViTs untested.", "Assumes K^T and V are written into NVM crossbars, which inflates attention cost relative to designs that compute attention digitally — this framing drives the size of the gains.", "Energy-efficiency (TOPS/W) gains are small; benefit is mostly fewer operations rather than better analog compute."], "remarks": "TReX is a model-side co-design that shrinks the part of the transformer that maps badly onto weight-stationary crossbars, rather than improving the crossbar itself; the strongest takeaway is the quantification that, once NVM write latency is modelled, writing K/V into crossbars dominates delay and dataflow tricks like ReTransformer barely help. The hybrid FeFET-SRAM mapping (dynamic MatMuls in SRAM CIM, static weights in NVM) foreshadows the heterogeneous mappings common in later work. Evidence is moderate (simulator plus trained-model accuracy), from the same Yale group as ClipFormer.", "basis": "full-text", "pdf_source_url": "", "abstract": "Due to the high computation overhead of Vision Transformers (ViTs), In-memory Computing architectures are being researched towards energy-efficient deployment in edge-computing scenarios. Prior works have proposed efficient algorithm-hardware co-design and IMC-architectural improvements to improve the energy-efficiency of IMC-implemented ViTs. However, all prior works have neglected the overhead and co-depencence of attention blocks on the accuracy-energy-delay-area of IMC-implemented ViTs. To this end, we propose TReX- an attention-reuse-driven ViT optimization framework that effectively performs attention reuse in ViT models to achieve optimal accuracy-energy-delay-area tradeoffs. TReX optimally chooses the transformer encoders for attention reuse to achieve near-iso-accuracy performance while meeting the user-specified delay requirement. Based on our analysis on the Imagenet-1k dataset, we find that TReX achieves 2.3× (2.19×) EDAP reduction and 1.86× (1.79×) TOPS/mm$^{2}$improvement with$\\sim$1% accuracy drop in case of DeiT-S (LV-ViT-S) ViT models. Additionally, TReX achieves high accuracy at high EDAP reduction compared to state-of-the-art token pruning and weight sharing approaches. On NLP tasks such as CoLA, TReX leads to 2% higher non-ideal accuracy compared to baseline at 1.6× lower EDAP.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2024_Moitra_TReX_TETC.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2024_Moitra_TReX_TETC.pdf", "priority": 5.42}, {"id": "W4400230160", "short": "Memristor LSH Attention", "title": "In-Memory Transformer Self-Attention Mechanism Using Passive Memristor Crossbar", "authors": ["Jack Cai", "Muhammad Ahsan Kaleem", "Roman Genov", "Mostafa Rahimi Azghadi", "Amirali Amirsoleimani"], "year": 2024, "venue": "", "venue_short": "ISCAS", "venue_full": "IEEE International Symposium on Circuits and Systems (ISCAS 2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/iscas58744.2024.10558182", "cites_global": 2, "cat": "04", "seed": false, "devices": ["Memristor(generic)"], "models": ["Transformer", "GPT/LLM"], "evidence": "simulation", "tldr": "Proposes performing locality-sensitive-hashing (LSH) self-attention using stochastic vector-matrix multiplication on low-resolution, semi-passive 0T1R memristor crossbars, showing via circuit-level simulation that it can approximate LLM self-attention with no evaluation-metric degradation.", "summary": "Transformer self-attention has quadratic time/memory complexity in sequence length, which is especially costly for both conventional and in-memory computing hardware. Prior algorithmic work (LSH attention) reduces this to O(L log L), and this paper proposes implementing LSH attention's underlying computation on semi-passive memristor crossbar arrays using low-resolution, energy-efficient 0T1R stochastic vector-matrix multiplication (VMM), rather than purely in conventional digital or full in-memory arithmetic. Using circuit-level simulation, the authors claim the hardware-level LSH approximation can be substituted as a drop-in replacement for exact attention in large language models (LLMs) without degrading evaluation metrics. The work positions itself as an early building block toward eventually computing the entire transformer architecture in-memory.", "contributions": ["Proposes mapping the hashing step of LSH self-attention onto low-resolution, semi-passive 0T1R memristor crossbar arrays", "Uses stochastic VMM on memristor arrays to perform the approximate nearest-neighbor hashing needed for LSH attention", "Demonstrates via circuit-level simulation that the hardware-approximated LSH attention is a feasible drop-in replacement in LLMs with no reported degradation in evaluation metrics", "Frames the approach as a stepping stone toward fully in-memory transformer computation"], "claims": [{"claim": "Low-resolution, energy-efficient 0T1R memristor arrays can perform the stochastic VMM needed for LSH attention", "support": "circuit-level simulation results (abstract); full quantitative details not available without full text", "loc": "abstract"}, {"claim": "The proposed in-memory LSH approximation can replace exact self-attention in LLMs without degrading evaluation metrics", "support": "stated in abstract as a simulation-based finding; specific benchmark numbers not available without full text", "loc": "abstract"}], "results": ["No full-text access; abstract reports qualitative claims of feasibility and 'no degradation in evaluation metrics' for LLMs under the proposed memristor-based LSH attention scheme, without specific quantitative figures"], "limitations": ["Full text unavailable; this analysis is based on the abstract only, so quantitative results, exact benchmark models, and simulation parameters (array size, bit precision, noise models) could not be verified", "Evidence is circuit-level simulation only, not device/silicon measurement", "Addresses only the attention/hashing sub-block of transformers, not the full transformer pipeline (as the paper itself notes as future work)"], "remarks": "A short (ISCAS) paper exploring a specific, narrow idea: using low-precision stochastic memristor VMM to accelerate the approximate hashing step of LSH attention. Without full text, the strength of evidence and generality of the 'no degradation' claim cannot be independently assessed; this should be treated as a preliminary feasibility study rather than a complete system demonstration. It is one of relatively few works targeting the attention mechanism specifically for passive/semi-passive memristor crossbars rather than only dense matrix multiplication.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformers have emerged as the state-of-the-art architecture for natural language processing (NLP) and computer vision. However, they are inefficient in both conventional and in-memory computing architectures as doubling their sequence length quadruples their time and memory complexity due to their self-attention mechanism. Traditional methods optimize self-attention using memory-efficient algorithms or approximate methods, such as locality-sensitive hashing (LSH) attention that reduces time and memory complexity from O(L2) to O(L log L). In this work, we propose a hardware-level solution that further improves the computational efficiency of LSH attention by utilizing in-memory computing with semi-passive memristor arrays. We demonstrate that LSH can be performed with low-resolution, energy-efficient 0T1R arrays performing stochastic memristive vector-matrix multiplication (VMM). Using circuit-level simulation, we show our proposed method is feasible as a drop-in approximation in Large Language Models (LLMs) with no degradation in evaluation metrics. Our results set the foundation for future works on computing the entire transformer architecture in-memory.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2024_Cai_MemristorLSHAttention_ISCAS.pdf", "analysed": true, "pdf": null, "priority": 6.24}, {"id": "W4381233128", "short": "X-Former", "title": "X-Former: In-Memory Acceleration of Transformers", "authors": ["Shrihari Sridharan", "Jacob R. Stevens", "Kaushik Roy", "Anand Raghunathan"], "year": 2023, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems, 2023", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2023.3282046", "cites_global": 66, "cat": "04", "seed": true, "devices": ["ReRAM", "SRAM-analog"], "models": ["BERT", "Transformer"], "evidence": "simulation", "tldr": "Hybrid in-memory Transformer accelerator that keeps all static weights in ReRAM crossbars (Projection Engine) and runs dynamic Q-K-V attention MVMs in 8T-SRAM CIM tiles (Attention Engine), with a sequence-blocking dataflow; reports up to 85x latency and 7.5x energy gains over a GTX 1060 GPU and up to 10.7x/4.6x over a PUMA-like NVM accelerator.", "summary": "Transformers contain MVM_Dynamic operations (QK^T, attention x V) in which both operands change per input; mapping these to NVM crossbars requires reprogramming, which is slow, energy-hungry and wears out devices with 1e6-1e9 endurance. X-Former splits the work: a Projection Engine of ReRAM crossbar tiles (bit-sliced weights, bit-streamed inputs, shared low-resolution DAC/ADCs) stores all layer weights spatially and is programmed once, while an Attention Engine of 8T-SRAM analog CIM attention head compute tiles writes Q and V once per sequence and streams K vectors (Query/Value-stationary dataflow). A sequence-blocking dataflow pipelines blocks of SB tokens between the two engines, raising utilization and making intermediate attention storage depend on SB rather than SL^2. Evaluated with a PUMAsim-based simulator (SPICE for SRAM macro, 32nm synthesis, CACTI) on BERT-Base/Large for GLUE and SQuAD, with a NeuroSim-based accuracy study of device variation.", "contributions": ["Classification of Transformer kernels into MVM_Static, MVM_Dynamic and NonMVM, showing MVM_Dynamic is 35% of FLOPs at SL=512 and 80% of runtime on a conventional crossbar accelerator at SL=256", "Hybrid architecture: ReRAM crossbar Projection Engine for weights + 8T-SRAM CIM Attention Engine for dynamic MVMs, avoiding NVM writes", "Intra-layer sequence-blocking dataflow that overlaps the two engines and bounds intermediate storage to SB x SB", "Simulation framework built on PUMAsim with NeuroSim-based accuracy analysis under device variation"], "claims": [{"claim": "Dynamic MVMs are a bottleneck for conventional crossbar accelerators running Transformers", "support": "for a sequence length of 256, 80% of the total runtime is spent in processing MVM_Dynamic operations; MVM_Dynamic is 35% of FLOPs at SL=512", "loc": "Sec. II, Fig. 1(b), Fig. 2"}, {"claim": "X-Former strongly outperforms a GPU", "support": "up to 85x (GLUE) and 81x (SQuAD) speedup with sequence blocking; 4.85x-7.5x (GLUE) and 3.52x-5.31x (SQuAD) energy benefit vs GTX 1060", "loc": "Sec. VII, Fig. 8, Fig. 11"}, {"claim": "Hybrid NVM+SRAM beats an all-NVM crossbar even with an ideal high-endurance device", "support": "8.1x speedup over a same-area crossbar architecture with NVM_Ideal device", "loc": "Sec. VII, Fig. 9"}, {"claim": "Hybrid beats an iso-area all-SRAM in-memory design because ReRAM holds all weights on chip", "support": "1.82x (BERT-Base) and 2.03x (BERT-Large) speedup and 52.1x / 36.8x energy efficiency vs in-SRAM baseline at SL=512", "loc": "Sec. VII, Fig. 10"}, {"claim": "Analog non-idealities cause modest loss at low variation but significant loss at high variation", "support": "<1% accuracy loss for variation 0-0.2; ~4.2% (BERT-Base) and 9.87% (BERT-Large) at larger variations on WNLI", "loc": "Sec. VI, Fig. 7"}], "results": ["Up to 85x latency and 7.5x energy improvement vs NVIDIA GTX 1060 GPU", "Up to 10.7x latency and 4.6x energy improvement vs PUMA-style in-memory NVM accelerator (dynamic MVMs on SIMD lanes)", "8.1x speedup vs crossbar-only architecture with idealized NVM", "Energy breakdown (SL=512, one encoder, 15.2 uJ): 58% attention-score computation in SRAM engine, 28% Q/K/V generation; ADC is 36.8% of NVM-engine MVM energy vs 12.1% in attention engine"], "limitations": ["Simulation only; ReRAM models from PUMA, SRAM macro from SPICE; no fabricated chip", "Accuracy study only on WNLI (baseline 56.34%, near chance) with generic process variation; no drift, IR-drop co-simulation with performance", "Weak GPU baseline (GTX 1060) inflates headline speedups", "Encoder-only BERT models; no autoregressive decoding/KV-cache or very large models; spatial weight mapping requires ReRAM area to scale with model size", "Attention Engine sized only for the largest layer, serialising encoder layers"], "remarks": "X-Former crystallised the now-standard 'static weights in NVM, dynamic attention in SRAM/CMOS' partition that most later hybrid analog Transformer accelerators (HARDSEA, H3DAtten, PRIMATE comparisons, ClipFormer) adopt or argue against. The evidence is purely architectural simulation and the accuracy analysis is thin (a single near-chance GLUE task), so the noise-robustness side of mapping BERT onto crossbars is under-explored here. For a thesis, it is a clean reference for the MVM_Static/MVM_Dynamic taxonomy and the write-endurance argument against mapping QK^T onto ReRAM.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2303.07470", "abstract": "Transformers have achieved great success in a wide variety of natural language processing (NLP) tasks due to the self-attention mechanism, which assigns an importance score for every word relative to other words in a sequence. However, these models are very large, often reaching hundreds of billions of parameters, and therefore require a large number of dynamic random access memory (DRAM) accesses. Hence, traditional deep neural network (DNN) accelerators such as graphical processing units (GPUs) and tensor processing units (TPUs) face limitations in processing Transformers efficiently. In-memory accelerators based on nonvolatile memory (NVM) promise to be an effective solution to this challenge, since they provide high storage density while performing massively parallel matrix–vector multiplications (MVMs) within memory arrays. However, attention score computations, which are frequently used in Transformers unlike convolutional neural networks (CNNs) and recurrent neural network (RNNs), require MVMs where both the operands change dynamically for each input. As a result, conventional NVM-based accelerators incur high write latency and write energy when used for Transformers and further suffer from the low endurance of most NVM technologies. To address these challenges, we present X-Former, a hybrid in-memory hardware accelerator that consists of both NVM and CMOS processing elements to execute transformer workloads efficiently. To improve the hardware utilization of X-Former, we also propose a sequence blocking dataflow, which overlaps the computations of the two processing elements and reduces execution time. Across several benchmarks, we show that X-Former achieves up to$69.8\\times $and$13\\times $improvements in latency and energy over a NVIDIA GeForce GTX 1060 GPU and up to$24.1\\times $and$7.95\\times $improvements in latency and energy over a state-of-the-art in-memory NVM accelerator.", "review": [{"fid": "F6", "text": "The central architectural gap between CNN-era analog IMC accelerators and transformer workloads is self-attention's dynamic matrix-matrix multiplication: both operands are input-dependent, so crossbars must be reprogrammed per self-attention layer. At sequence length 256 these dynamic MVMs consume 80% of total runtime, and the compute-write-compute dependency stalls MatMul until KT is written column by column.", "grade": "High confidence", "vote": "4 claims merged · 3–0 unanimous", "note": "X-Former (IEEE TVLSI) · ReTransformer (ICCAD 2020) · arXiv 2601.14260 — three independent groups; repeated by ClipFormer, CPSAA, RED-PIM, RAELLA, TransPIM"}, {"fid": "F9", "text": "Device non-idealities are the physical limit and span a hierarchy, not just the material: memory window, read noise, program noise and conductance drift act on different time scales while constraining manufacturability; errors originate at device, array, architecture and algorithm levels. NVM writes cost 1–2 orders of magnitude more latency and energy per bit than SRAM, with ~106–109 write endurance.", "grade": "High confidence", "vote": "3–0 unanimous", "note": "Wiley Adv. Intelligent Systems 2026 · Nature Materials 2026 · X-Former"}], "pdf_expected": "04_Transformers_and_LLMs/2023_Sridharan_X-Former_TVLSI.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2023_Sridharan_X-Former_TVLSI.pdf", "priority": 11.88}, {"id": "W4390017976", "short": "HARDSEA", "title": "HARDSEA: Hybrid Analog-ReRAM Clustering and Digital-SRAM In-Memory Computing Accelerator for Dynamic Sparse Self-Attention in Transformer", "authors": ["Shiwei Liu", "Chen Mu", "Hao Jiang", "Yunzhengmao Wang", "Jinshan Zhang", "Feng Lin", "Keji Zhou", "Qi Liu", "Chixiao Chen"], "year": 2023, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2023.3337777", "cites_global": 38, "cat": "04", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["Transformer", "BERT", "GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "HARDSEA is a hybrid analog-ReRAM/digital-SRAM compute-in-memory accelerator for dynamic sparse self-attention in transformers, using product-quantization-based token-relevance prediction on noise-tolerant ReRAM and exact sparse computation on reorganized SRAM-CIM, reporting 13.5x-28.5x speedup and 291.6x-1894.3x energy efficiency over GPU.", "summary": "The paper targets the quadratic cost of self-attention in transformers (BERT, GPT-2) by exploiting dynamic sparsity while coping with the fact that analog ReRAM-CIM is noisy/imprecise but digital SRAM-CIM is precise but less energy-efficient. HARDSEA performs algorithm-architecture-circuit co-design: a product-quantization-based scheme predicts lightweight token relevance to dynamically determine which attention entries are important, exploiting the fact that only the relative ordering (monotonicity), not exact values, of relevance scores is needed -- a task well suited to noise-tolerant analog ReRAM-CIM. The exact (precision-sensitive) sparse attention computation is then performed on a digital SRAM-CIM array reorganized with an 'on-memory-boundary computing' scheme to flexibly handle the resulting irregular sparsity patterns. To avoid the area/energy cost of ADCs for the relevance-prediction ReRAM macro, the authors propose a time-domain winner-take-all (WTA) circuit that directly produces the needed ranking without full analog-to-digital conversion. Evaluated on BERT and GPT-2, HARDSEA prunes attention to 12%-33% sparsity without accuracy loss and achieves large speedup/energy-efficiency gains over GPU and over prior transformer accelerators.", "contributions": ["Algorithm-architecture-circuit co-design combining a product-quantization-based dynamic token-relevance predictor with a hybrid analog/digital CIM architecture", "Uses noise-tolerant analog ReRAM-CIM specifically for the relevance-prediction sub-task, which only needs correct ranking (monotonicity) rather than exact values, sidestepping ReRAM's precision limitations", "Reorganizes digital SRAM-CIM with an 'on-memory-boundary computing' scheme to handle irregular sparse attention access patterns efficiently", "Proposes a time-domain winner-take-all (WTA) circuit that replaces conventional ADCs in the ReRAM-CIM relevance-prediction macro, reducing peripheral circuit cost", "Demonstrates pruning BERT and GPT-2 self-attention to 12%-33% sparsity with no accuracy loss"], "claims": [{"claim": "HARDSEA prunes BERT and GPT-2 attention to 12%-33% sparsity without accuracy loss.", "support": "sparsity range reported in abstract/experiments", "loc": "Experimental results section"}, {"claim": "HARDSEA achieves 13.5x-28.5x speedup over GPU.", "support": "reported speedup range vs GPU baseline", "loc": "Experimental results section"}, {"claim": "HARDSEA achieves 291.6x-1894.3x energy efficiency over GPU.", "support": "reported energy-efficiency range vs GPU baseline", "loc": "Experimental results section"}, {"claim": "HARDSEA achieves 1.2x-14.9x better energy efficiency than state-of-the-art transformer accelerators at the same throughput level.", "support": "comparison against prior transformer accelerators (e.g., ReRAM-based attention accelerators)", "loc": "Experimental results / comparison section"}, {"claim": "Replacing ADCs with a time-domain winner-take-all circuit in the ReRAM-CIM relevance-prediction macro is sufficient because only ranking information, not exact magnitude, is required downstream.", "support": "circuit design rationale tied to the algorithm's use of relevance ranking only", "loc": "Architecture/circuit design section"}], "results": ["12%-33% self-attention sparsity on BERT/GPT-2 with no accuracy loss", "13.5x-28.5x speedup vs GPU", "291.6x-1894.3x energy efficiency vs GPU", "1.2x-14.9x better energy efficiency than state-of-the-art transformer accelerators at equal throughput"], "limitations": ["Full text not available for this analysis; all quantitative results above are taken from the abstract only and not independently checked against tables/figures", "ReRAM is used only for the noise-tolerant ranking/prediction sub-task, implying the authors judged ReRAM-CIM unsuitable for exact sparse-attention computation, which still has to run on digital SRAM-CIM -- i.e., analog compute coverage of the workload is partial", "Based on the abstract alone, it is unclear whether the reported numbers are from post-layout simulation, pure architectural simulation, or measured silicon"], "remarks": "HARDSEA is a notable hybrid-analog/digital design pattern for transformer attention acceleration in the analog-CIM literature: rather than trying to make ReRAM compute attention scores exactly, it restricts analog compute to tasks that are inherently robust to noise (ranking/relevance prediction) while keeping exact computation digital. This hybrid strategy (and the ADC-avoiding time-domain WTA circuit) is a useful mapping/architecture pattern to compare against pure-ReRAM transformer accelerators (e.g., CPSAA, X-Former) in a mapping-focused thesis chapter. Because only the abstract was available, the specific experimental setup (baseline GPU model, precision assumptions, device variation modeling) could not be verified and should be checked against the full TVLSI 2023 paper before citing specific numbers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Self-attention-based transformers have outperformed recurrent and convolutional neural networks (RNN/ CNNs) in many applications. Despite the effectiveness, calculating self-attention is prohibitively costly due to quadratic computation and memory requirements. To solve this challenge, this article proposes a hybrid analog-ReRAM and digital-SRAM in-memory computing accelerator (HARDSEA), a computing-in-memory (CIM) accelerator supporting self-attention in transformer applications. To trade off between energy efficiency and algorithm accuracy, HARDSEA features an algorithm-architecture-circuit codesign. A product-quantization-based scheme dynamically facilitates self-attention sparsity by predicting lightweight token relevance. A hybrid in-memory computing architecture employs both high-efficiency analog ReRAM-CIM and high-precision digital SRAM-CIM to implement the proposed new scheme. The ReRAM-CIM, whose precision is sensitive to circuit nonidealities, takes charge of token relevance prediction where only computing monotonicity is demanded. The SRAM-CIM, utilized for exact sparse attention computing, is reorganized as an on-memory-boundary computing scheme, thus adapting to irregular sparsity patterns. In addition, we propose a time-domain winner-take-all (WTA) circuit to replace the expensive ADCs in ReRAM-CIM macros. Experimental results show that HARDSEA prunes BERT and GPT-2 models to 12%–33% sparsity without accuracy loss, achieving$13.5\\times $–$28.5\\times $speedup and$291.6\\times $–$1894.3\\times $energy efficiency over GPU. Compared to state-of-the-art transformer accelerators, HARDSEA has$1.2\\times $–$14.9\\times $better energy efficiency at the same level of throughput.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2023_Liu_HARDSEA_TVLSI.pdf", "analysed": true, "pdf": null, "priority": 9.04}, {"id": "W4385656513", "short": "H3DAtten", "title": "H3DAtten: Heterogeneous 3-D Integrated Hybrid Analog and Digital Compute-in-Memory Accelerator for Vision Transformer Self-Attention", "authors": ["Wantong Li", "Madison Manley", "James Read", "Ankit Kaul", "Muhannad S. Bakir", "Shimeng Yu"], "year": 2023, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2023.3299509", "cites_global": 30, "cat": "04", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["ViT", "Transformer"], "evidence": "simulation", "tldr": "H3DAtten is a heterogeneous 3D-integrated accelerator for vision-transformer multi-head self-attention that stacks a 40nm RRAM analog-CIM tier with a 16nm SRAM digital-CIM tier, reporting 8.4x compute density over iso-capacity 2D baselines with no accuracy loss on ImageNet-1k.", "summary": "Vision transformers' multi-head self-attention (MHSA) is costly to run on conventional hardware due to the memory wall, and 2D compute-in-memory (CIM) designs must grow their footprint to hold increasingly large models. H3DAtten proposes heterogeneous 3D (H3D) integration that combines RRAM-based analog CIM (ACIM, 40nm) and SRAM-based digital CIM (DCIM, 16nm) tiers to target MHSA workloads specifically, exploiting the different strengths of analog (density/efficiency) and digital (precision) compute-in-memory within a single stacked package. The authors perform signaling and thermal analyses to characterize the effects of 3D stacking (e.g., inter-tier interconnect and heat) on the accelerator's behavior. A proposed 5-tier H3DAtten accelerator is compared against iso-capacity 2D CIM baselines, achieving 8.4x compute density without accuracy loss on ImageNet-1k.", "contributions": ["A heterogeneous 3D-integrated (H3D) CIM architecture combining RRAM analog-CIM (40nm) and SRAM digital-CIM (16nm) tiers in one package", "Targets vision transformer multi-head self-attention (MHSA) specifically, rather than only the linear/MVM-dominated feed-forward layers", "Comprehensive signaling and thermal analysis of the effects of 3D stacking on the accelerator", "A 5-tier H3DAtten design demonstrating 8.4x compute density over iso-capacity 2D baselines with no ImageNet-1k accuracy loss"], "claims": [{"claim": "3D heterogeneous integration of analog and digital CIM tiers substantially increases compute density for ViT self-attention without hurting accuracy", "support": "8.4x compute density vs. iso-capacity 2D baseline designs, no accuracy loss on ImageNet-1k", "loc": "Abstract"}], "results": ["8.4x compute density vs. iso-capacity 2D CIM baseline designs (5-tier H3DAtten)", "No accuracy loss on ImageNet-1k"], "limitations": ["Analysis based on abstract only (full text not accessible); the mix/partitioning of ACIM vs. DCIM tiers, exact self-attention mapping scheme, and thermal/signaling analysis details could not be verified", "3D-stacking results (thermal, interconnect) are based on simulation/analysis rather than fabricated 3D silicon"], "remarks": "H3DAtten is an architecture-level contribution notable for combining heterogeneous device classes (RRAM analog-CIM and SRAM digital-CIM) across 3D-stacked tiers specifically for the self-attention bottleneck in vision transformers, rather than treating CIM as homogeneous. It has a substantial in-set forward citation footprint (AESHA, COMET-3D, SAGE, Harmony, HyPIM, etc.), indicating it is an influential reference point for later hybrid CIM/ViT accelerator work; full-text access would be valuable to confirm the exact attention-mapping and 3D thermal/signaling methodology.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "After the success of the transformer networks on natural language processing (NLP), the application of transformers to computer vision (CV) has followed suit to deliver unprecedented performance gains on vision tasks, including image recognition and object detection. The multihead self-attention (MHSA) is the key component in transformers, allowing the models to learn the amount of attention paid to each input position. Despite its strong modeling capability, MHSA involves complex operations that make transformers prohibitively costly for hardware deployment. Existing acceleration efforts with conventional hardware platforms are challenged by the memory wall. To alleviate the memory wall problem, compute-in-memory (CIM) is a promising solution by storing all model parameters on-chip in compute-capable memory arrays. The footprint of 2-D CIM designs must, however, expand to accommodate the increasingly larger model sizes. In this work, we present a heterogeneous 3-D integrated (H3D) accelerator to target the MHSA workloads in vision transformers. H3D allows the proposed H3DAtten architecture to combine the merits of resistive random access memory (RRAM)-based analog CIM (ACIM) in 40 nm and static random access memory (SRAM)-based digital CIM (DCIM) in 16 nm. We perform comprehensive signaling and thermal analyses to examine the effects of 3-D stacking on the accelerator. Compared to iso-capacity 2-D baseline designs, the proposed 5-tier H3DAtten accelerator achieves$8.4\\times $compute density without experiencing accuracy loss on the ImageNet-1k dataset.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2023_Li_H3DAtten_TVLSI.pdf", "analysed": true, "pdf": null, "priority": 8.4}, {"id": "W4390241252", "short": "CPSAA", "title": "CPSAA: Accelerating Sparse Attention Using Crossbar-Based Processing-In-Memory Architecture", "authors": ["Huize Li", "Hai Jin", "Long Zheng", "Xiaofei Liao", "Yu Huang", "Cong Liu", "Jiahong Xu", "Zhuohui Duan", "Dan Chen", "Chuangyi Gui"], "year": 2023, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2023.3344524", "cites_global": 17, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["Transformer", "BERT"], "evidence": "simulation", "tldr": "CPSAA is a crossbar-based ReRAM PIM accelerator for sparse attention that couples two crossbar-array types for in-PIM pruning and for unstructured SDDMM/SpMM, reporting up to 89.6x speedup and 755.6x energy savings over GPU and gains over FPGA/SANGER/ReBERT/ReTransformer baselines.", "summary": "The paper targets the off-chip data-transfer bottleneck that limits existing sparse-attention accelerators: sparsity pruning and the resulting unstructured sparse attention matrix force repeated off-chip memory access in GPU/FPGA/ASIC solutions, and prior ReRAM-based attention accelerators (e.g., ReBERT, ReTransformer) cannot efficiently extend dense-attention PIM designs to sparse attention because of ReRAM write overhead and lack of in-PIM pruning support. CPSAA proposes (1) a new attention calculation mode that overlaps/hides crossbar write latency with VMM processing, (2) a PIM-based sparsity-pruning architecture that generates the pruning mask in-memory rather than off-chip, and (3) novel ReRAM-crossbar-based SDDMM and SpMM methods that couple two types of crossbar arrays to process unstructured sparse attention matrices without converting them back to dense form. The design builds on the ISAAC-style in-situ dot-product crossbar scheme for VMM-heavy operations. Evaluated in simulation against GPU, FPGA, and prior sparse-attention/PIM accelerators (SANGER, ReBERT, ReTransformer), CPSAA achieves large performance and energy improvements, with the gains attributed to eliminating off-chip transfers in both the pruning and attention-computation phases.", "contributions": ["Proposes a crossbar write/VMM-overlapped attention calculation mode to hide ReRAM programming latency, which is a major overhead for the input-dependent (non-reusable) attention matrices", "Designs a PIM-based sparsity-pruning architecture that produces the sparsity mask directly in the crossbar array, removing the off-chip data transfer that limits prior software-based pruning + PIM pipelines", "Introduces crossbar-based SDDMM (sampled dense-dense matrix multiply) and SpMM (sparse matrix multiply) methods using coupled pairs of crossbar array types to handle unstructured sparsity patterns in-memory", "Benchmarks against GPU, FPGA, and PIM/ASIC sparse-attention accelerators (SANGER, ReBERT, ReTransformer) for both performance and energy"], "claims": [{"claim": "CPSAA achieves an average of 89.6x, 32.2x, 17.8x, 3.39x, and 3.84x performance improvement over GPU, FPGA, SANGER, ReBERT, and ReTransformer respectively.", "support": "reported average speedup figures", "loc": "Abstract / Sec. VI experimental results"}, {"claim": "CPSAA achieves 755.6x, 55.3x, 21.3x, 5.7x, and 4.9x energy savings over the same five baselines (GPU, FPGA, SANGER, ReBERT, ReTransformer) respectively.", "support": "reported average energy-saving figures", "loc": "Abstract / Sec. VI experimental results"}, {"claim": "Prior ReRAM-based attention accelerators (ReBERT, ReTransformer) perform the crossbar write operation serially with the VMM operation, substantially increasing latency.", "support": "Discussion of ReBERT's calculation mode in Fig. 4(a)", "loc": "Sec. II/III, Fig. 4(a)"}, {"claim": "SANGER achieves 5.03x and 1.81x performance improvement compared with GPU- and FPGA-based sparse attention accelerators, which CPSAA further improves upon.", "support": "comparison figures cited for SANGER baseline", "loc": "Sec. VI, p.~2443"}], "results": ["Average 89.6x / 32.2x / 17.8x / 3.39x / 3.84x performance improvement vs. GPU / FPGA / SANGER / ReBERT / ReTransformer", "Average 755.6x / 55.3x / 21.3x / 5.7x / 4.9x energy saving vs. GPU / FPGA / SANGER / ReBERT / ReTransformer", "CPSAA maintains stable throughput (GOPS) as sequence length / number of encoder layers scales, unlike baselines whose performance degrades (Sec. VI scaling study)"], "limitations": ["Evaluation is simulation-based; no reported fabricated silicon or measured chip results", "ADC/peripheral circuit cost assumptions follow ISAAC-style configuration (e.g., 25ns per 32-column ADC cycle), carrying over ISAAC's idealizations for ADC precision/noise rather than independently characterizing device nonidealities", "Gains are reported as averages across benchmarks; per-model/per-task variance and the specific attention-sparsity levels used are not given in the parts reviewed here", "Coupling two crossbar array types in the SDDMM/SpMM design adds hardware/area complexity whose overhead relative to a single-array design is not clearly quantified in the summary results"], "remarks": "CPSAA is a well-cited example (noted by HARDSEA and other works in this collection) of extending ReRAM-crossbar PIM beyond dense CNN/MVM workloads to dynamic, unstructured sparse attention, specifically addressing the write-overhead problem that makes naive ReRAM-based attention acceleration impractical. Its reliance on ISAAC's ADC/cycle-time assumptions means its absolute numbers inherit optimism about analog peripheral overheads; a thesis chapter on mapping sparse attention to crossbars should treat the architectural techniques (write/VMM overlap, in-PIM pruning, coupled-array SDDMM/SpMM) as the main contribution, with the specific speedup/energy numbers read as simulation-based upper bounds rather than measured results.", "basis": "full-text", "pdf_source_url": "", "abstract": "The attention-based neural network attracts great interest due to its excellent accuracy enhancement. However, the attention mechanism requires huge computational efforts to process unnecessary calculations, significantly limiting the system’s performance. To reduce the unnecessary calculations, researchers propose sparse attention to convert some dense-dense matrices multiplication (DDMM) operations to sampled dense-dense matrix multiplication (SDDMM) and sparse matrix multiplication (SpMM) operations. However, current sparse attention solutions introduce massive off-chip random memory access since the sparse attention matrix is generally unstructured. We propose CPSAA, a novel crossbar-based processing-in-memory (PIM)-featured sparse attention accelerator to eliminate off-chip data transmissions. First, we present a novel attention calculation mode to balance the crossbar writing and crossbar processing latency. Second, we design a novel PIM-based sparsity pruning architecture to eliminate the pruning phase’s off-chip data transfers. Finally, we present novel crossbar-based SDDMM and SpMM methods to process unstructured sparse attention matrices by coupling two types of crossbar arrays. Experimental results show that CPSAA has an average of 89.6×, 32.2×, 17.8×, 3.39×, and 3.84× performance improvement and 755.6×, 55.3×, 21.3×, 5.7×, and 4.9× energy-saving when compare with GPU, FPGA, SANGER, ReBERT, and ReTransformer.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2023_Li_CPSAA_TCAD.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2023_Li_CPSAA_TCAD.pdf", "priority": 7.91}, {"id": "W4386764227", "short": "Reconfigurable Sparse-Attention NVPIM", "title": "Accelerating Sparse Attention with a Reconfigurable Non-volatile Processing-In-Memory Architecture", "authors": ["Qilin Zheng", "Shiyu Li", "Yitu Wang", "Ziru Li", "Yiran Chen", "Hai Helen Li"], "year": 2023, "venue": "", "venue_short": "DAC", "venue_full": "60th ACM/IEEE Design Automation Conference (DAC 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/dac56929.2023.10247908", "cites_global": 14, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["ViT", "DeiT", "PVT", "PiT", "BERT"], "evidence": "simulation", "tldr": "A ReRAM PIM bank that can switch between analog VMM mode (dense layers) and two digital vector modes, inner-product and scalar-vector multiply, so that dynamically sparse attention (SDDMM/SpMM) maps efficiently; with a pipelined hybrid-stationary dataflow it reports 2.95-12.36x speedup and 1.2-3.4x energy efficiency over ReTransformer.", "summary": "Sparse attention turns QK^T into SDDMM and attention x V into SpMM with irregular, input-dependent masks, but an NVPIM bank's VMM primitive only reaches full utilisation when N consecutive mask entries are valid, so directly mapping sparse attention to ReTransformer gives only 1.59x speedup at 95% sparsity (1.84x with SRE). The authors redesign the ReRAM bank so its multi-bit sense amplifiers (MBSAs) can be reconfigured into many 1-bit SAs, reading out a stored vector and ANDing it with bit-serial inputs to implement an inner-product (IP) primitive for SDDMM and a scalar-vector multiplication (SVM) primitive for SpMM, while dense QKV/FFN layers still use analog VMM with stride-8 bit-interleaved weights. A tile-level hybrid stationary dataflow (Q-stationary for attention map, V-stationary for output) with chunk-level pipelining overlaps the two stages. Evaluation uses a cycle-accurate simulator with ISAAC-derived array models, 28nm synthesised PE, transistor-level MBSA, on DeiT/PVT/PiT (ImageNet) and BERT (GLUE, SQuAD, CLOTH) with Sanger-style precision-gating masks.", "contributions": ["Analysis showing the rigid VMM primitive of NVPIM banks wastes input/output parallelism under unstructured dynamic attention sparsity", "Reconfigurable ReRAM bank reusing MBSAs/Col.MUX to support analog VMM plus digital inner-product and scalar-vector primitives with no throughput loss", "Hybrid stationary (Q-stationary / V-stationary) dataflow with chunk-level pipelining of SDDMM and SpMM that also shrinks attention-map buffering", "Comparison against NVPIM (ReTransformer+SRE) and non-PIM (Sanger, DOTA) sparse-attention accelerators under matched throughput"], "claims": [{"claim": "Conventional NVPIM cannot exploit unstructured attention sparsity", "support": "mapping to ReTransformer only induces about 1.59x (1.0x) speedup under 95% (67%) sparsity; ~1.84x (1.11x) with SRE", "loc": "Sec. I, Fig. 1"}, {"claim": "Reconfigurable vector primitives greatly improve sparse-attention performance on NVPIM", "support": "speedup ranging from 2.95x to 12.36x and 1.2x to 3.4x energy efficiency over the baseline NVPIM accelerator", "loc": "Sec. V-B, Fig. 9"}, {"claim": "Vector-mode primitives do not lower bank throughput", "support": "row activation parallelism is reduced 8x but 8x more columns are sensed in parallel as the MBSA is configured into multiple SAs", "loc": "Sec. III"}, {"claim": "Better energy-latency trade-off than non-PIM sparse-attention accelerators", "support": "up to 3.8x and 8.6x energy reduction vs Sanger and DOTA at similar latency, while ReTransformer saves energy at 4.8x/3.3x latency cost", "loc": "Sec. V-C, Fig. 10(b)"}, {"claim": "Sparse attention keeps accuracy", "support": "negligible accuracy loss (<1%) at >85% attention sparsity for most models (vision models retrained 60 epochs)", "loc": "Sec. V-B, Fig. 9"}], "results": ["2.95x-12.36x speedup and 1.2x-3.4x energy efficiency vs ReTransformer(+SRE) on ViT and BERT tasks", "Up to 3.8x / 8.6x lower energy than Sanger / DOTA at the same latency level", "Each bank: ~9.14 GOPS with 128 kB; 72 banks/tile give 658 GOPS and 9 MB", "Latency drops ~50% when banks increase from 8 to 24, vs 30% for the baseline"], "limitations": ["Simulation only; array model taken from ISAAC, MBSA from schematics, no ReRAM non-idealities or accuracy-under-noise analysis", "Q, K, V are written into ReRAM arrays at runtime for the sparse modes; write latency/energy and endurance impact are not discussed", "Higher memory-access energy than ReTransformer due to reduced data reuse in vector mode", "Sparse masks rely on Sanger-style precision gating and retraining/fine-tuning; mask-generation cost partly offloaded to a functional unit taken from DOTA", "Short 4-page DAC paper: limited sensitivity and area-overhead detail"], "remarks": "The key insight for crossbar mapping is that the VMM granularity of an analog array is a poor fit for dynamic, fine-grained sparsity, and that the read-out periphery can be repurposed to operate as a digital vector unit, so the same ReRAM array serves both static-weight VMM and data-dependent sparse ops. However, it implicitly assumes cheap and endurable runtime writes of Q/K/V into ReRAM, which X-Former and HARDSEA explicitly avoid by moving dynamic operands into SRAM. Evidence is architectural simulation without device noise, so accuracy claims refer only to the sparsity algorithm.", "basis": "full-text", "pdf_source_url": "https://par.nsf.gov/servlets/purl/10565765", "abstract": "Attention-based neural networks have shown superior performance in a wide range of tasks. Non-volatile processing-in-memory (NVPIM) architecture shows its great potential to accelerate the dense attention model. However, the unique unstructured and dynamic sparsity pattern in the sparse attention model challenges the mapping efficiency of the NVPIM architecture, as the conventional NVPIM architecture uses a vector-matrix-multiplication primitives. In this paper, we propose a NVPIM architecture to accelerate a dynamic and unstructured sparse computation in the sparse attention. We aim to improve the mapping efficiency for both SDDMM and SpMM by introducing two vector-based primitives with a reconfigurable NVPIM bank. Further, based on our reconfigurable NVPIM bank, we further propose a hybrid stationary data flow to hide the latency. Our evaluation result shows that, over previous NVPIM accelerators, our design could deliver up to 12.36× performance improvement and 3.4× energy efficiency improvement on a range of vision and language tasks.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2023_Zheng_ReconfigurableSparseAttentionNVPIM_DAC.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2023_Zheng_ReconfigurableSparseAttentionNVPIM_DAC.pdf", "priority": 6.75}, {"id": "W4390285480", "short": "RIME", "title": "An RRAM-Based Computing-in-Memory Architecture and Its Application in Accelerating Transformer Inference", "authors": ["Zhaojun Lu", "Xueyan Wang", "Md Tanvir Arafin", "Haoxiang Yang", "Zhenglin Liu", "Jiliang Zhang", "Gang Qu"], "year": 2023, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems, 2023", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2023.3345651", "cites_global": 34, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["Transformer"], "evidence": "simulation", "tldr": "RIME is an RRAM in-memory floating-point architecture (single-cycle NOR/NAND/minority logic) with pipelined MatMul and softmax, giving a transformer accelerator 2.3x faster and 1.7x more energy-efficient than a GPU without accuracy loss.", "summary": "Existing CIM designs lack floating-point support needed by NLP transformers and need costly peripherals. The paper proposes RIME, using RRAM cells as logic gates (NOR, NAND, minority) to perform floating-point operations in memory with a centralized control module and simplified peripherals. Pipelined MatMul and softmax implementations are built on RIME to form a transformer accelerator. Reported results are 2.3x timing and 1.7x energy-efficiency gains over a GPU implementation with no inference accuracy loss. (Abstract only; details not verified.)", "contributions": ["RIME: scalable RRAM in-memory floating-point architecture", "Single-cycle NOR/NAND/minority-based FP operations", "Pipelined in-memory MatMul and softmax", "Transformer accelerator built on RIME"], "claims": [{"claim": "2.3x time and 1.7x energy efficiency vs GPU, no accuracy loss", "support": "abstract", "loc": "Abstract"}], "results": ["2.3x timing efficiency and 1.7x energy efficiency vs GPU"], "limitations": ["Abstract only; models, datasets and baselines unknown", "Digital stateful logic is slow per-op and endurance-heavy; device non-idealities not discussed in abstract"], "remarks": "Relevant to in-memory transformer inference but computes digitally in ReRAM, so it sidesteps analog noise and is not an analog SLM deployment. Gains over a GPU are modest. Treat as generic transformer accelerator (04).", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Deep neural network (DNN)-based transformer models have demonstrated remarkable performance in natural language processing (NLP) applications. Unfortunately, the unique scaled dot-product attention mechanism and intensive memory access pose a significant challenge during inference on power-constrained edge devices. One emerging solution to this challenge is computing-in-memory (CIM), which uses memory cells for logic computation to reduce data movement and overcome the memory wall. However, existing CIM designs do not support high-precision computations, such as floating-point operations, which are essential for NLP applications. Furthermore, CIM architectures require complex control modules and costly peripheral circuits to harness the full potential of in-memory computation. Hence, this article proposes a scalable RRAM-based in-memory floating-point computation architecture (RIME) that uses single-cycle NOR, NAND, and minority logic to implement in-memory floating-point operations. RIME features efficient parallel and pipeline capabilities with a centralized control module and a simplified peripheral circuit to eliminate data movement during computation. Furthermore, the article proposes pipelined implementations of matrix–matrix multiplication (MatMul) and softmax functions, enabling the construction of a transformer accelerator based on RIME. Extensive experimental results show that compared with GPU-based implementation, the RIME-based transformer accelerator improves timing efficiency by$2.3\\times $and energy efficiency by$1.7\\times $without compromising inference accuracy.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2023_Lu_RIME_TVLSI.pdf", "analysed": true, "slm": false, "lm_models": [], "param_scale": "", "slm_note": "Transformer (NLP) inference on RRAM using in-memory NOR/NAND/minority logic floating-point; digital stateful logic, not analog crossbar MVM. Specific LMs and scale not stated in abstract.", "added": "2026-10 SLM search", "pdf": null, "priority": 7.01}, {"id": "W4280496502", "short": "TransPIM", "title": "TransPIM: A Memory-based Acceleration via Software-Hardware Co-Design for Transformer", "authors": ["Minxuan Zhou", "Weihong Xu", "Jaeyoung Kang", "Tajana Rosing"], "year": 2022, "venue": "", "venue_short": "HPCA", "venue_full": "2022 IEEE International Symposium on High-Performance Computer Architecture (HPCA 2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/hpca53966.2022.00082", "cites_global": 142, "cat": "04", "seed": false, "devices": ["DRAM"], "models": ["Transformer", "RoBERTa", "Pegasus", "GPT-2", "BERT"], "evidence": "simulation", "tldr": "End-to-end Transformer acceleration in HBM using a token-based data-sharding dataflow plus lightweight in-bank auxiliary compute units and ring-broadcast links, reporting 22.1-114.9x speedup over an RTX 2080Ti GPU and 3.7x/9.1x over PIM-only/NMC-only HBM.", "summary": "The paper observes that existing memory-based DNN accelerators use layer-based dataflows that, for Transformers, spend ~60% of time on data loading/reorganisation, and that bit-serial row-parallel DRAM PIM is slow at long-vector reductions (23-32% of time). TransPIM shards input tokens across HBM banks so each bank computes FC, attention and FFN for its own tokens across all layers, exchanging K and V sub-matrices via a ring broadcast to compute cross-shard attention. In hardware it adds per-subarray Auxiliary Computing Units (256-wide bit-serial adder trees and a divider) for reduction and softmax normalisation, plus per-bank data buffers and direct ring-broadcast links between neighbouring banks to bypass the shared bus. Point-wise multiplication is done in DRAM cells with majority-based bulk bitwise PIM, and exp() is approximated with a 5th-order Taylor series. Evaluated with a Ramulator-based in-house simulator on 8 HBM2 stacks (64 GB) with RoBERTa, Pegasus and GPT-2-medium workloads, it outperforms GPU, TPUv3, PIM-only, NMC (Newton-like) and ASIC (A3, SpAtten) baselines.", "contributions": ["Token-based data sharding dataflow that keeps per-token intermediate data bank-local across layers, with ring broadcast for cross-shard attention (4.6x faster than layer-based dataflow)", "Hybrid PIM-NMC HBM: bit-serial in-DRAM point-wise ops plus in-bank ACUs (bit-serial adder trees, divider) for reductions and softmax", "Data communication architecture (per-bank 8x256b buffers, ring-broadcast links) that cuts ring broadcast from 8T to 3T for two bank groups", "Decoder dataflow supporting encoder-decoder and decoder-only models", "Area/power analysis: 512 ACUs add ~2.15 mm2 (4.0% DRAM area), under 60 W DRAM power budget"], "claims": [{"claim": "Layer-based dataflows waste most of PIM execution time on data movement for Transformers", "support": "data movement takes around 60% of execution time for RoBERTa text classification on an 8-stack PIM-only HBM system; reduction takes 23%-32%", "loc": "Sec. II-C, Fig. 3"}, {"claim": "TransPIM is much faster than GPU/TPU for Transformers, especially long sequences", "support": "22.1x (8.7x) to 114.9x (57.4x) faster than GPU (TPU); 138.1x to 666.6x more energy efficient than GPU", "loc": "Sec. V-B, Fig. 10"}, {"claim": "Hardware support beats prior memory-based accelerators", "support": "9.6x faster than layer-based PIM-only; 3.7x faster than token-sharded PIM-only; 9.1x faster than token-sharded NBP", "loc": "Sec. V-B"}, {"claim": "TransPIM is not more energy-efficient than near-bank processing with the same dataflow", "support": "around 0.2% less energy efficient than NBP due to energy of parallel row activations for bit-serial in-situ ops", "loc": "Sec. V-B"}, {"claim": "Lightweight hardware preserves DRAM density", "support": "512 ACUs consume about 2.15 mm2, 4.0% area overhead, below the 25% threshold", "loc": "Sec. V-A, Table II"}], "results": ["22.1x-114.9x speedup and 138.1x-666.6x energy efficiency vs NVIDIA RTX 2080Ti GPU", "3.7x faster than PIM-only and 9.1x faster than NMC-only HBM (both with token sharding)", "Average throughput 734 GOP/s, about 2.0-3.3x the peak throughput of A3 (221 GOP/s) and SpAtten (360 GOP/s)", "Decoder-only GPT-2 LM: only 1.4x faster and 2.1x more energy-efficient than Layer-TransPIM", "Token sharding reduces data-movement latency by 4.5-4.8x; custom data path gives a further 4.1x reduction"], "limitations": ["Digital DRAM PIM, not analog: no crossbar MVM, no ADCs; relevance to analog CIM is as a dataflow and baseline reference", "Simulation only (modified Ramulator, CACTI-3DD, 65nm synthesis scaled to 22nm); no silicon", "Benefits shrink for short sequences (IMDB) and decoder-only generation (1.4x vs layer-based TransPIM)", "Bit-serial PIM is energy-hungry: no energy gain over near-bank processing with the same dataflow", "8-bit FC/FFN and 16-bit softmax with Taylor-series exp; accuracy impact not deeply evaluated"], "remarks": "TransPIM is a well-executed architecture study, but it is DRAM bit-serial PIM, so its findings transfer to analog crossbars mainly at the dataflow level: token-sharded execution and the cost of moving K/V between memory partitions is a recurring theme in later NVM work. It became the standard 'PIM for Transformer' baseline (e.g. PRIMATE from the same group reports 30.6x throughput over it, HARDSEA cites it). The headline GPU speedups compare 8 HBM stacks against a single consumer GPU, so they should be read with care.", "basis": "full-text", "pdf_source_url": "https://par.nsf.gov/servlets/purl/10345536", "abstract": "Transformer-based models are state-of-the-art for many machine learning (ML) tasks. Executing Transformer usually requires a long execution time due to the large memory footprint and the low data reuse rate, stressing the memory system while under-utilizing the computing resources. Memory-based processing technologies, including processing in-memory (PIM) and near-memory computing (NMC), are promising to accelerate Transformer since they provide high memory bandwidth utilization and extensive computation parallelism. However, the previous memory-based ML accelerators mainly target at optimizing dataflow and hardware for compute-intensive ML models (e.g., CNNs), which do not fit the memory-intensive characteristics of Transformer. In this work, we propose TransPIM, a memory-based acceleration for Transformer using software and hardware co-design. In the software-level, TransPIM adopts a token-based dataflow to avoid the expensive inter-layer data movements introduced by previous layer-based dataflow. In the hardware-level, TransPIM introduces lightweight modifications in the conventional high bandwidth memory (HBM) architecture to support PIM-NMC hybrid processing and efficient data communication for accelerating Transformer-based models. Our experiments show that TransPIM is 3.7× to 9.1× faster than existing memory-based acceleration. As compared to conventional accelerators, TransPIM is 22.1× to 114.9× faster than GPUs and provides 2.0× more throughput than existing ASIC-based accelerators.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2022_Zhou_TransPIM_HPCA.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2022_Zhou_TransPIM_HPCA.pdf", "priority": 9.34}, {"id": "W4205363571", "short": "Full-Circuit Memristor Transformer", "title": "Full-Circuit Implementation of Transformer Network Based on Memristor", "authors": ["Chao Yang", "Xiaoping Wang", "Zhigang Zeng"], "year": 2022, "venue": "IEEE Transactions on Circuits and Systems I Regular Papers", "venue_short": "TCAS-I", "venue_full": "IEEE Transactions on Circuits and Systems I: Regular Papers, vol. 69, no. 4, pp. 1395-1407 (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcsi.2021.3136355", "cites_global": 66, "cat": "04", "seed": false, "devices": ["Memristor(generic)"], "models": ["Transformer"], "evidence": "simulation", "tldr": "An all-analog, full-circuit memristor implementation of the Transformer network -- crossbar VMM plus dedicated analog circuit modules for softmax, layer normalization, ReLU, multiply-add and residual connections -- that computes end-to-end without any ADC, DAC or digital memory, verified in PSPICE on a character image-recognition task.", "summary": "The paper proposes what it presents as the first full-circuit (entirely analog) implementation of a Transformer network using memristors, rather than offloading only the matrix multiplications to crossbars while handling nonlinear Transformer operations (softmax, layer norm, residual, activations) digitally. The design comprises: (1) a memristor crossbar module storing weights and performing vector-matrix multiplication; (2) an analog signal memory module that stores intermediate analog signals in near-memory fashion (avoiding repeated analog-to-digital round trips); (3) dedicated analog function-circuit modules realizing softmax, layer normalization, ReLU, multiply-add and residual-connection transformations; and (4) a timing-signal generation module to sequence circuit operation. Because all signal paths stay analog, the design needs no ADC, DAC, or digital memory anywhere in the pipeline. The authors verify functional correctness in PSPICE using a character image-recognition task and analyze signal retention of the analog memory, overall circuit performance, and the impact of memristor non-idealities, reporting advantages in area overhead, energy efficiency, and noise tolerance relative to (unspecified in the abstract) comparison points.", "contributions": ["A memristor-crossbar module for Transformer weight storage and vector-matrix multiplication", "An analog signal memory module that retains intermediate activations in near-memory analog form, avoiding repeated ADC/DAC conversion between Transformer sub-layers", "Dedicated analog function-circuit modules implementing softmax, layer normalization, ReLU, multiply-add, and residual connections directly in the analog domain", "A timing-signal generation module to schedule the full set of circuit operations", "An end-to-end, ADC/DAC/digital-memory-free analog Transformer circuit verified functionally in PSPICE"], "claims": [{"claim": "A Transformer network can be implemented end-to-end in the analog domain using memristors without any ADC, DAC, or digital memory.", "support": "Full circuit design (crossbar + analog memory + analog function circuits + timing control) verified functionally in PSPICE on a character image-recognition task", "loc": "Abstract (full text not available)"}, {"claim": "The proposed all-analog Transformer circuit has advantages in area overhead, energy efficiency, and noise tolerance.", "support": "Stated as a conclusion from PSPICE-based circuit performance and memristor-non-ideality analysis", "loc": "Abstract (full text not available)"}], "results": ["Functional correctness of the full analog Transformer circuit verified via PSPICE simulation on a character image-recognition task (per abstract; no specific accuracy/throughput/energy numbers given in the abstract)"], "limitations": ["Analysis is abstract-only here (full text not accessible from this machine; only IEEE Xplore hosts it and no legitimate open copy was found) -- quantitative results, baseline comparisons, and the scale of the demonstrated Transformer are not independently verifiable", "As described, evaluation is circuit-level SPICE simulation on a small character-recognition task, not a fabricated chip or a large-scale NLP/vision Transformer benchmark"], "remarks": "Notable for pushing analog Transformer implementation beyond just the matmul/attention-score crossbar step to also realize softmax, layer-norm and residual connections in the analog domain, eliminating per-sublayer ADC/DAC conversions that dominate many other analog-Transformer proposals. Being a circuit-simulation (PSPICE) study rather than silicon, and evaluated on what the abstract describes as a small character-image task, its claims about area/energy/noise advantages should be read as circuit-level, simulation-based estimates; later citing works (e.g., TReX, cascaded ReRAM Transformer accelerators) suggest it is referenced primarily for its all-analog nonlinear-function circuit modules rather than as a scaled system.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "As an emerging in-memory element, memristor has been widely used in various neural network circuits to represent the weights and accelerate the calculation. However, the Transformer Network (TN), one of the most important models for machine vision and natural language processing in recent years, has not yet been full-circuit implemented using memristors due to the complex calculation process and data storage. In order to carry out the computation of the TN more efficiently, this work proposes a memristor-based full-circuit implementation of the TN capable of: 1) a memristor crossbar module to preserve the weights of the TN and perform the vector-matrix multiplications; 2) an analog signal memory module to store the analog signal directly in near-memory mode; 3) function circuit modules to achieve five transformations, namely Softmax, Layer Normalization, ReLU, Multiply-add and Residual; 4) a timing signal generation module to schedule operations of the circuit. The proposed TN circuit can complete all calculations directly based on the analog signal without using any analog-digital converter (ADC), digital-analog converter (DAC) and digital memory. In addition, character image recognition experiments are carried out in PSPICE to verify the functional correctness of the designed circuit. The corresponding signal retention rates of the analog memory, the performance of the whole circuit, and the non-idealities of the memristors are also analyzed. The results indicate that the circuit has advantages in terms of area overhead, energy efficiency and anti-noise.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2022_Yang_FullCircuitMemristorTransformer_TCASI.pdf", "analysed": true, "pdf": null, "priority": 7.87}, {"id": "W3209892756", "short": "Window Self-Attention ReRAM", "title": "A Framework for Accelerating Transformer-Based Language Model on ReRAM-Based Architecture", "authors": ["Myeonggu Kang", "Hyein Shin", "Lee‐Sup Kim"], "year": 2021, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2021.3121264", "cites_global": 28, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["Transformer"], "evidence": "algorithm+simulation", "tldr": "Proposes window self-attention plus a window-size search algorithm to resolve the pipeline-hazard bottleneck of running transformer-based language models on ReRAM in-situ accelerators, reporting up to 39.2x speedup and 643.2x energy efficiency over GPU.", "summary": "Transformer-based language models are increasingly the de-facto NLP workload, but running them on ReRAM-based in-situ compute accelerators (which help avoid the memory wall) creates a pipeline hazard: the self-attention mechanism's data dependencies stall the ReRAM accelerator's processing pipeline, inflating execution time. The authors analyze the properties of self-attention and propose 'window self-attention,' which restricts the computation scope of attention to a window around each token to reduce the dependency chain that causes the hazard. They then design a window-size search algorithm that selects window sizes per layer/head to balance the target application's accuracy/performance against hazard reduction. A hardware design is proposed to exploit this algorithmic optimization on a general ReRAM-based accelerator template. The approach is reported to deliver a 5.8x speedup over a provisioned (un-optimized) ReRAM baseline, and up to 39.2x speedup / 643.2x energy efficiency over GPU execution of the same transformer language models.", "contributions": ["Identification and analysis of a pipeline-hazard problem specific to running self-attention on ReRAM-based in-situ accelerators", "Window self-attention: an algorithmic restriction of attention computation scope designed to reduce the hazard-causing data-dependency chain", "A window-size search algorithm that selects per-layer/head window sizes to trade off algorithmic (accuracy) performance against hardware hazard mitigation", "A ReRAM accelerator hardware design that exploits the window self-attention optimization", "Reported large speedups (5.8x over baseline ReRAM accelerator; up to 39.2x/643.2x over GPU in speed/energy efficiency)"], "claims": [{"claim": "Window self-attention combined with the proposed hardware design resolves the pipeline hazard while maintaining algorithmic performance, giving a 5.8x speedup over the provisioned (non-optimized) ReRAM baseline.", "support": "5.8x speedup over provisioned baseline (abstract)", "loc": "Abstract"}, {"claim": "The proposed framework delivers up to 39.2x speedup and 643.2x higher energy efficiency versus GPU.", "support": "up to 39.2x / 643.2x speedup/energy-efficiency over GPU (abstract)", "loc": "Abstract"}], "results": ["5.8x speedup over the provisioned (hazard-unmitigated) ReRAM baseline accelerator (abstract)", "Up to 39.2x speedup and up to 643.2x higher energy efficiency vs. GPU (abstract; exact GPU model and benchmark set not verifiable from abstract alone)"], "limitations": ["Full text was not accessible (IEEE TCAD paywalled; no legitimate open preprint found); this entry is based on abstract and metadata only, so details of the window-size search algorithm, hardware microarchitecture, and benchmark/accuracy trade-offs could not be verified", "Windowed/local attention is a lossy approximation of full self-attention; the accuracy impact across different transformer model sizes and tasks is not quantifiable from the abstract"], "remarks": "This is one of the earlier works specifically targeting the transformer self-attention bottleneck on ReRAM crossbar accelerators (alongside ReTransformer), framing the problem as a pipeline-hazard issue rather than purely an ADC/crossbar-capacity issue, and addressing it with an algorithm-hardware co-design (sparsity-like windowing) rather than new device technology. Later in-set citing works (e.g., CPSAA, HARDSEA, ETA) continue this line of attention-sparsification/scheduling for ReRAM transformer acceleration, suggesting the hazard problem identified here remained an active research target. Because the full text was unavailable, the magnitude and robustness of the reported speedups (particularly the 643.2x energy-efficiency figure) should be treated as a headline claim pending verification against baseline and benchmark details.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformer-based language models have become thede-factostandard model for various natural language processing (NLP) applications given the superior algorithmic performances. Processing a transformer-based language model on a conventional accelerator induces the memory wall problem, and the ReRAM-based accelerator is a promising solution to this problem. However, due to the characteristics of the self-attention mechanism and the ReRAM-based accelerator, the pipeline hazard arises when processing the transformer-based language model on the ReRAM-based accelerator. This hazard issue greatly increases the overall execution time. In this article, we propose a framework to resolve the hazard issue. First, we propose the concept of window self-attention to reduce the attention computation scope by analyzing the properties of the self-attention mechanism. After that, we present a window-size search algorithm, which finds an optimal window size set according to the target application/algorithmic performance. We also suggest a hardware design that exploits the advantages of the proposed algorithm optimization on the general ReRAM-based accelerator. The proposed work successfully alleviates the hazard issue while maintaining the algorithmic performance, leading to a$5.8\\times $speedup over the provisioned baseline. It also delivers up to$39.2\\times /643.2\\times $speedup/higher energy efficiency over GPU, respectively.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2021_Kang_WindowSelfAttentionReRAM_TCAD.pdf", "analysed": true, "pdf": null, "priority": 8.95}, {"id": "W3111375540", "short": "ReTransformer", "title": "ReTransformer", "authors": ["Xiaoxuan Yang", "Bonan Yan", "Hai Li", "Yiran Chen"], "year": 2020, "venue": "", "venue_short": "ICCAD", "venue_full": "39th IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2020)", "venue_ok": true, "doi": "https://doi.org/10.1145/3400302.3415640", "cites_global": 80, "cat": "04", "seed": true, "devices": ["ReRAM"], "models": ["Transformer"], "evidence": "algorithm+simulation", "tldr": "ReTransformer is a ReRAM-based PIM architecture for Transformer acceleration that uses a matrix-decomposition technique to avoid writing intermediate scaled dot-product attention results back to the crossbar and a sub-matrix pipeline for multi-head self-attention, improving computing efficiency 23.21x over GPU and 3.25x over PipeLayer.", "summary": "The paper targets the inference bottleneck of the scaled dot-product attention mechanism in Transformer decoders and the general compute/memory intensity of Transformers. While ReRAM-based processing-in-memory (PIM) had already been applied to CNNs and RNNs, the authors note that Transformer's attention computation, which involves matrix-matrix multiplication of intermediate activations (Q, K, V) rather than static weights, is not directly compatible with existing ReRAM PIM designs because intermediate results would otherwise need to be written back to crossbars, incurring heavy write overhead. ReTransformer addresses this via a matrix decomposition technique that eliminates the need to write intermediate MatMul results, and a new sub-matrix pipeline design for multi-head self-attention to improve hardware utilization and fine-grained pipelining. Compared to GPU and the PipeLayer ReRAM accelerator, the proposed design reports large gains in computing efficiency and especially power.", "contributions": ["Identification and analysis of the specific data-dependency and write-overhead challenges of mapping Transformer's scaled dot-product self-attention onto ReRAM-based PIM", "A matrix decomposition technique that avoids writing intermediate Matrix-matrix Multiplication (MatMul) results back to ReRAM crossbars", "A new sub-matrix pipeline design for multi-head self-attention to enable finer-grained pipelining of Transformer computation on ReRAM PIM", "Experimental comparison against GPU and the PipeLayer ReRAM accelerator showing large efficiency and power improvements"], "claims": [{"claim": "ReTransformer improves computing efficiency by 23.21x over GPU and 3.25x over PipeLayer", "support": "stated experimental comparison in the abstract", "loc": "Abstract"}, {"claim": "ReTransformer reduces overall power by 1086x versus GPU and 2.82x versus PipeLayer", "support": "stated experimental comparison in the abstract", "loc": "Abstract"}], "results": ["23.21x computing-efficiency improvement over GPU", "3.25x computing-efficiency improvement over PipeLayer (ReRAM accelerator baseline)", "1086x power reduction versus GPU", "2.82x power reduction versus PipeLayer"], "limitations": ["Full text not available to this review; limitations, benchmark details, and precise experimental methodology beyond the abstract could not be independently verified", "Analysis based only on the abstract; specific network sizes/datasets evaluated and non-ideality assumptions are unknown from the abstract alone"], "remarks": "ReTransformer is one of the earliest (2020) ReRAM-PIM designs specifically targeting the Transformer attention mechanism and is frequently cited as a baseline/precursor by later Transformer-on-analog-hardware papers (e.g., X-Former, RACE-IT, H3DAtten, and others in this collection's citation graph), indicating strong influence on category 04 (Transformers & LLMs on analog/PIM hardware). Because the full text was not accessible (ACM DL, not downloadable from this environment), this entry is abstract-only and the claimed headline numbers should be treated as reported by the authors without independent verification of methodology.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformer has emerged as a popular deep neural network (DNN) model for Neural Language Processing (NLP) applications and demonstrated excellent performance in neural machine translation, entity recognition, etc. However, its scaled dot-product attention mechanism in auto-regressive decoder brings a performance bottleneck during inference. Transformer is also computationally and memory intensive and demands for a hardware acceleration solution. Although researchers have successfully applied ReRAM-based Processing-in-Memory (PIM) to accelerate convolutional neural networks (CNNs) and recurrent neural networks (RNNs), the unique computation process of the scaled dot-product attention in Transformer makes it difficult to directly apply these designs. Besides, how to handle intermediate results in Matrix-matrix Multiplication (MatMul) and how to design a pipeline at a finer granularity of Transformer remain unsolved. In this work, we propose ReTransformer - a ReRAM-based PIM architecture for Transformer acceleration. ReTransformer can not only accelerate the scaled dot-product attention of Transformer using ReRAM-based PIM but also eliminate some data dependency by avoiding writing the intermediate results using the proposed matrix decomposition technique. Moreover, we propose a new sub-matrix pipeline design for multi-head self-attention. Experimental results show that compared to GPU and Pipelayer, ReTransformer improves computing efficiency by 23.21× and 3.25×, respectively. The corresponding overall power is reduced by 1086× and 2.82×, respectively.", "review": [{"fid": "F6", "text": "The central architectural gap between CNN-era analog IMC accelerators and transformer workloads is self-attention's dynamic matrix-matrix multiplication: both operands are input-dependent, so crossbars must be reprogrammed per self-attention layer. At sequence length 256 these dynamic MVMs consume 80% of total runtime, and the compute-write-compute dependency stalls MatMul until KT is written column by column.", "grade": "High confidence", "vote": "4 claims merged · 3–0 unanimous", "note": "X-Former (IEEE TVLSI) · ReTransformer (ICCAD 2020) · arXiv 2601.14260 — three independent groups; repeated by ClipFormer, CPSAA, RED-PIM, RAELLA, TransPIM"}, {"fid": "F7", "text": "The write bottleneck is being attacked algorithmically rather than only with better devices, via reformulations that keep the static weight matrix in the crossbar; dedicated ReRAM PIM transformer accelerators report large gains (ReTransformer: 23.21× efficiency and 1086× power versus GPU).", "grade": "Medium confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Graded medium: self-reported simulator and architecture-level speedups against differing baselines, not measured silicon. The 1086× power figure compares an accelerator model against a general-purpose GPU."}], "pdf_expected": "04_Transformers_and_LLMs/2020_Yang_ReTransformer_ICCAD.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2020_Yang_ReTransformer_ICCAD.pdf", "priority": 11.44}, {"id": "W3116577775", "short": "ATT", "title": "ATT: A Fault-Tolerant ReRAM Accelerator for Attention-based Neural Networks", "authors": ["Haoqiang Guo", "Lu Peng", "Jian Zhang", "Qing Chen", "Travis LeCompte"], "year": 2020, "venue": "", "venue_short": "ICCD", "venue_full": "2020 IEEE 38th International Conference on Computer Design (ICCD 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccd50377.2020.00047", "cites_global": 12, "cat": "04", "seed": false, "devices": ["ReRAM"], "models": ["Transformer", "BERT"], "evidence": "simulation", "tldr": "ATT is a pipelined ReRAM-crossbar accelerator for attention-based networks (Transformer/BERT/XLNet/XLM) that adds a non-uniform crossbar-grouping redundancy algorithm (NuXG), exploiting layer-wise weight sparsity to tolerate stuck-at-faults with less overhead than uniform redundancy, reaching ~2.5x the throughput and ~2x the power efficiency of a prior redundancy scheme (RX).", "summary": "The paper targets ReRAM-based PIM acceleration of attention-based neural networks (AttNNs), which existing CNN/RNN-oriented ReRAM accelerators cannot efficiently support due to attention, layer normalization, GELU and intermediate matrix-matrix multiplications. It proposes ATT, an intra-layer-pipelined accelerator with dedicated engines (Q-K-V, Head-Merge, Fully-Connected, LayerNorm) mapped onto ReRAM crossbars in weight-stationary dataflow. To address stuck-at-faults (SA0/SA1) in crossbars, the authors observe that weight sparsity varies strongly across layers and propose NuXG (Non-uniform Xbar Grouping), a heuristic redundancy algorithm based on maximum-weight bipartite matching (Hungarian algorithm) that assigns different redundancy ratios to layer groups (High/Medium/Low sparsity) instead of a uniform ratio. Evaluated in an in-house NVSim-based simulator against GPU (NVIDIA GTX 1080 Ti) and a prior redundancy scheme (RX) across Transformer, BERT-base, XLNet and XLM, ATT achieves about 2.5x the throughput and roughly 60% of the ideal (fault-free) power efficiency, versus 20-25% for RX, with ~125x average speedup over GPU versus ~51x for RX and ~203x for the fault-free ideal case.", "contributions": ["First (at time of writing) ReRAM PIM accelerator that handles the full AttNN data flow (attention, layer norm, GELU, matrix-matrix multiplications), not just the attention module", "Intra-layer pipeline design with dedicated Q-K-V, Head-Merge, Fully-Connected and LayerNorm engines to address hardware hazards in AttNN data flow", "NuXG: a non-uniform, layer-sparsity-aware crossbar redundancy algorithm based on maximum-weight bipartite matching (Hungarian algorithm) for stuck-at-fault tolerance", "Evaluation across four AttNN benchmarks (Transformer, BERT-base, XLNet, XLM) comparing against GPU, an ideal fault-free crossbar baseline, and a prior uniform-redundancy scheme (RX)"], "claims": [{"claim": "Fully-connected layers dominate AttNN compute time (74-84% across benchmarks), making them the primary target for acceleration/redundancy, while attention consumes at most ~20%", "support": "FC accounts for 81.5%, 75.79%, 74.2%, 83.69% of compute time for Transformer, BERT, XLNet, XLM respectively", "loc": "Sec. VI.A"}, {"claim": "Layer-wise sparsity varies strongly within a network (near 0% in early layers, near 100% in some late layers for BERT/XLNet), enabling non-uniform redundancy allocation with <2% accuracy loss", "support": "Fig. 5 sparsity profile; largest accuracy loss 1.9% (Transformer)", "loc": "Sec. VI.A, Fig. 5"}, {"claim": "NuXG achieves about 2.5x the throughput of the uniform-redundancy RX scheme at equal crossbar count", "support": "Fig. 6 throughput comparison; RX throughput is ~1/4 of Ideal while ATT stores ~2.5x the weight matrices of RX", "loc": "Sec. VI.B, Fig. 6"}, {"claim": "ATT reaches ~60% of theoretical (fault-free) power efficiency versus 20-25% for RX, while consuming only ~1.5x the energy of the ideal case", "support": "Fig. 7 energy breakdown and power-efficiency comparison", "loc": "Sec. VI.C, Fig. 7"}, {"claim": "ATT delivers an average 125.28x speedup over GPU across the four benchmarks, versus 50.69x for RX and 202.78x for the fault-free Ideal case", "support": "Fig. 8 overall speedup numbers", "loc": "Sec. VI.C, Fig. 8"}], "results": ["~2.5x throughput improvement over RX redundancy scheme at equal crossbar budget (Fig. 6)", "~60% of ideal (fault-free) power efficiency achieved by ATT vs 20-25% for RX (Sec. VI.B)", "Average 125.28x speedup over NVIDIA GTX 1080 Ti GPU (vs 50.69x for RX, 202.78x for Ideal) (Fig. 8)", "Energy overhead of only ~1.5x versus the fault-free ideal case across all four benchmarks (Sec. VI.C)", "Accuracy loss kept below 2% (max 1.9%, on Transformer) under the chosen sparsity-based redundancy configuration (Sec. VI.A)"], "limitations": ["Evaluation uses an in-house, NVSim-derived performance simulator rather than measured silicon or a cycle-accurate public simulator", "Sparsity thresholds for layer grouping (0.35/0.5 splits) are manually configured, not learned or automatically optimized", "Fault model is limited to stuck-at-faults (SA0/SA1); does not address other non-idealities such as conductance drift, IR-drop, or write variation", "Power/area models for crossbars are adapted from ISAAC and scaled from other literature (CACTI, NVSim) rather than directly measured", "Only 4 Transformer-family benchmarks evaluated (Transformer, BERT-base, XLNet, XLM), all moderate scale by current LLM standards"], "remarks": "ATT is one of the earliest ReRAM crossbar accelerators to explicitly design for the full Transformer/attention data flow (including GELU and LayerNorm) rather than just the attention kernel, and it is also one of the first to combine AttNN mapping with stuck-at-fault-aware redundancy. Its main contribution (NuXG) is algorithmic — exploiting naturally occurring layer-wise sparsity to cut redundancy overhead — but the evaluation relies on an in-house simulator and only moderate-scale Transformer models, so the generality to larger/sparser LLM workloads remains untested. It is a useful reference point alongside the contemporaneous ReTransformer for how ReRAM-PIM designs began targeting Transformers circa 2020.", "basis": "full-text", "pdf_source_url": "", "abstract": "Crossbar-based resistive RAM has been widely used in deep learning accelerator designs because it largely eliminates weight movement between memory and processing units. The high-density storage and low leakage power make it a good fit for edge/IoT devices. However, existing ReRAM designs for traditional neural networks cannot support Attention-based Neural Networks, which are stacked with encoders and decoders instead of convolutional layers or fully connected layers. In addition to matrix-matrix multiplications in traditional neural networks, an encoder or a decoder also includes the attention mechanism, the layer normalization and the gaussian error linear unit. These new characteristics make the data flow far more complicated than that of a convolutional layer. Faulty ReRAM devices are additional obstacles when mapping weights that severely degrade computation accuracy. Existing hardware redundancy strategies that are unaware of application characteristics usually result in inefficient designs. In this work, we analyze the data flow of these attention-based neural networks and propose a ReRAM-based accelerator with a dedicated pipeline design for Attention-based Neural Networks. When considering cells with hard faults in crossbars, we further propose NuXG, a non-uniform redundancy strategy, to meet accuracy requirements and save energy consumption by decreasing the redundancy ratio. Finally, we evaluate results and demonstrate that the proposed can achieve more than two times improved performance over existing redundancy schemes in both power efficiency and throughput for Attention-based Neural Networks. Moreover, it also significantly outperforms an NVIDIA GPU.", "review": [], "pdf_expected": "04_Transformers_and_LLMs/2020_Guo_ATT_ICCD.pdf", "analysed": true, "pdf": "04_Transformers_and_LLMs/2020_Guo_ATT_ICCD.pdf", "priority": 6.21}, {"id": "W7160523127", "short": "TriCIM", "title": "TriCIM: A General CIM-Capacity-Aware Framework for Optimizing Model, Layer, and Tile-Stationary Dataflows in CIM Accelerators", "authors": ["Yi-Xiang Wang", "Yufu Zhang", "Longyang Lin"], "year": 2026, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems (2026)", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2026.3688907", "cites_global": 0, "cat": "05", "seed": false, "devices": ["Generic-NVM", "SRAM-analog"], "models": ["DNN (unspecified)"], "evidence": "simulation", "tldr": "TriCIM splits the CIM dataflow space into model-, layer- and tile-stationary regions based on CIM capacity vs. model size and applies region-specific optimisations (load balancing, layer grouping, weight-update scheduling, tiling, inter-tile ordering), achieving 1.1x-13.2x runtime speedup over state-of-the-art frameworks.", "summary": "CIM dataflow frameworks tend to target a narrow range of architectures or dataflow types and often ignore CIM-specific features such as weight-update scheduling when weights do not fit. TriCIM introduces a CIM-capacity-aware formulation: depending on how the available CIM capacity compares with model size, a mapping falls into model-stationary (whole model resident), layer-stationary, or tile-stationary (weights must be reloaded per tile) regions. For each region it identifies the dominant bottleneck and applies tailored optimisations: load balancing, layer grouping, weight-update scheduling, tiling and inter-tile ordering. Evaluation across various CIM accelerators and representative NN models reports that TriCIM consistently finds optimal dataflows with 1.1x to 13.2x runtime speedup over state-of-the-art frameworks.", "contributions": ["CIM-capacity-aware taxonomy of the dataflow space into model-, layer- and tile-stationary regions", "Region-specific bottleneck analysis", "Optimisations: load balancing, layer grouping, weight-update scheduling, tiling, inter-tile ordering", "Evaluation across multiple CIM accelerator configurations and NN models"], "claims": [{"claim": "The CIM dataflow space can be partitioned by CIM capacity vs. model size into three regions with distinct bottlenecks.", "support": "Core formulation in abstract", "loc": "Abstract"}, {"claim": "TriCIM outperforms state-of-the-art CIM dataflow frameworks in runtime.", "support": "'1.1x to 13.2x runtime speedup compared to state-of-the-art frameworks'", "loc": "Abstract"}, {"claim": "TriCIM consistently finds optimal dataflows across diverse CIM accelerators.", "support": "Stated in abstract", "loc": "Abstract"}], "results": ["1.1x-13.2x runtime speedup vs. state-of-the-art CIM dataflow frameworks (abstract)"], "limitations": ["Abstract-only analysis; architectures, models and baselines not verified", "Device list is an inference (framework is device-agnostic; weight-update scheduling suggests capacity-limited, e.g. SRAM, CIM)", "'Optimal' presumably relative to its own cost model", "Performance-only; no accuracy/non-ideality modelling indicated"], "remarks": "The capacity-region framing is a clean way to reason about when the 'weights stay in the crossbar' assumption of ISAAC/PUMA-style mapping breaks, which is exactly the regime of large transformers on limited CIM capacity. Weight-update scheduling is especially relevant to NVM CIM where writes are slow/costly, though the abstract does not quantify write costs.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Compute-in-memory (CIM) has emerged as a promising paradigm for accelerating neural networks (NNs), offering high parallelism and superior energy efficiency. To fully leverage the potential of CIM accelerators for deploying NNs, it is essential to carefully optimize their mapping dataflows, which determine how computations and data are scheduled across CIM resources over space and time. However, the diversity of CIM architectures, with their varying hardware parameters and mapping constraints, makes it challenging to develop a unified framework that efficiently optimizes dataflows across different CIM systems. Most existing CIM dataflow frameworks are tailored to a limited range of architectures or dataflow types, and often neglect CIM-specific features such as weight-update scheduling, which limits their effectiveness and generality. In this work, we propose TriCIM, a general dataflow optimization framework designed to adapt to diverse CIM architectures. We begin by introducing a CIM-capacity-aware formulation that classifies the CIM dataflow space into three distinct regions, model-stationary, layer-stationary, and tile-stationary, based on the available CIM capacity and the model size. For each dataflow region, we identify specific bottlenecks and propose tailored optimization strategies, including load balancing, layer grouping, weight-update scheduling, tiling, and inter-tile ordering, to address region-specific bottlenecks and enhance dataflow efficiency. Our evaluation across various CIM accelerators and representative NN models demonstrates that TriCIM consistently finds optimal dataflows, achieving$1.1\\times $to$13.2\\times $runtime speedup compared to state-of-the-art frameworks.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2026_Wang_TriCIM_TVLSI.pdf", "analysed": true, "pdf": null, "priority": 4.5}, {"id": "W4408893285", "short": "CMSwitch", "title": "Be CIM or Be Memory: A Dual-mode-aware DNN Compiler for CIM Accelerators", "authors": ["Shixin Zhao", "Yuming Li", "Bing Li", "Yintao He", "Mengdi Wang", "Yinhe Han", "Ying Wang"], "year": 2025, "venue": "", "venue_short": "ASPLOS", "venue_full": "Proceedings of the 30th ACM International Conference on Architectural Support for Programming Languages and Operating Systems (ASPLOS 2025)", "venue_ok": true, "doi": "https://doi.org/10.1145/3676641.3716248", "cites_global": 2, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN", "ResNet", "BERT", "GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "CMSwitch is a DNN compiler that exposes CIM arrays' dynamic compute/memory mode switching as a first-class optimization dimension, using dynamic programming for network segmentation plus mixed-integer programming for resource allocation to get an average 1.31x speedup (up to 2.03x) over state-of-the-art CIM compilers on CNNs, BERT, and LLMs like LLaMA2-7B/OPT-13B.", "summary": "Dual-mode CIM arrays can be reconfigured on the fly to act as either compute units (matrix-vector multiply) or plain memory, but prior CIM compilers (e.g., CIM-MLC, PIMCOMP, OCC) treat all CIM arrays as fixed compute resources and ignore this switching capability, which is especially valuable for LLM workloads whose compute/memory balance shifts across layers and inference stages (prefill vs. decode, varying batch size/sequence length). CMSwitch adds a hardware abstraction attribute for the compute-memory mode switch into the compilation optimization space, then uses dynamic programming to segment the network graph (accounting for mode-switch overhead) and mixed-integer programming to allocate the optimal compute/memory resource split within each segment. The optimized schedule is expressed via tailored 'meta-operators' that generalize across CIM architectures and are lowered to machine code/ISA for a CIM-MLC-based functional simulator. Evaluated on CNNs (VGG16, ResNet18, MobileNet), BERT, and LLMs (LLaMA2-7B, OPT-6.7B, OPT-13B) at varying batch sizes and sequence lengths, CMSwitch achieves an average 1.31x speedup (up to 2.03x) over state-of-the-art CIM compilation baselines (CIM-MLC, OCC, PUMA), with mode-switch overhead contributing only ~3-5% of execution time.", "contributions": ["Identifies that existing CIM compilers ignore dual-mode (compute/memory) array reconfigurability, leaving performance on the table especially for LLM workloads with varying compute/memory demands", "Introduces a hardware abstraction attribute that integrates compute-memory mode switching into the CIM compilation optimization space", "Proposes a dynamic-programming-based network segmentation pass that accounts for mode-switch overhead when partitioning the network graph", "Uses mixed-integer programming to determine the optimal compute/memory resource allocation within each network segment", "Introduces tailored meta-operators to express dual-mode compilation results in an architecture-generalized form, lowered via a CIM-MLC-based functional simulator", "Demonstrates consistent speedups across CNNs, BERT, and multi-billion-parameter LLMs (LLaMA2-7B, OPT-6.7B/13B) at varying batch sizes and sequence lengths"], "claims": [{"claim": "CMSwitch improves average inference speed across a range of DNN/LLM workloads compared to state-of-the-art CIM compilation", "support": "Average speedup of 1.31x compared to prior state-of-the-art compilation work (CIM-MLC), with a maximum improvement reported in the evaluation", "loc": "Abstract; Sec. 6 Evaluation"}, {"claim": "Gains are especially large for decode-heavy / memory-bound LLM inference configurations", "support": "For OPT-13B, CMSwitch outperformed the baseline by 1.20x-2.03x (average 1.73x); for LLaMA2-7B, gains of 1.13x-1.30x (average 1.24x)", "loc": "Sec. 6, 'LLaMA2-7B' and 'OPT-13B' results"}, {"claim": "Speedup over CIM-MLC decreases as sequence length grows because fewer arrays benefit from mode switching at longer context lengths", "support": "Speedups compared to CIM-MLC drop from ~1.50x-1.76x range at short sequence lengths to 1.41x/1.58x/1.32x at sequence length 2048 for LLaMA2-7B/OPT-6.7B/OPT-13B respectively", "loc": "Sec. 6, sequence-length sensitivity study"}, {"claim": "The dual-mode switching mechanism itself adds negligible runtime overhead", "support": "The dual-mode switch process contributes around 3%-5% to total execution time", "loc": "Sec. 6, 'Dual-mode switch overhead'"}], "results": ["Average speedup of 1.31x over CIM-MLC across evaluated DNN/LLM workloads, up to 2.03x in the best case (OPT-13B)", "LLaMA2-7B (decode-only): 1.13x-1.30x speedup (average 1.24x) vs. baseline", "OPT-13B: 1.20x-2.03x speedup (average 1.73x) vs. baseline", "At sequence length 2048, speedups compared to CIM-MLC settle at 1.41x (LLaMA2-7B), 1.58x (OPT-6.7B), 1.32x (OPT-13B)", "Mode-switch overhead: ~3%-5% of total execution time", "Also evaluated on CNNs (VGG16, ResNet18, MobileNet) and BERT against CIM-MLC, OCC, and PUMA baselines with speedups generally in the 1.0x-2x range depending on model/batch size"], "limitations": ["Evaluated purely via a CIM-MLC-based functional/architectural simulator, not on physical dual-mode CIM silicon", "Benefits depend on workloads having heterogeneous compute/memory demand across layers or inference stages; gains shrink for long sequence lengths as the paper itself shows", "Mixed-integer programming for resource allocation may face scalability challenges for very large networks/segment counts, though not explicitly quantified for compile time", "Relies on an idealized dual-mode CIM array abstraction; practical overheads of real dual-mode circuits (beyond the measured 3-5% switch cost) may vary by device technology", "Comparisons are against other compiler frameworks' reported configurations (CIM-MLC, OCC, PUMA) rather than a from-scratch, fully matched hardware baseline"], "remarks": "This is a compiler/scheduling contribution rather than a device or architecture paper, and it makes a solid point that prior CIM compilation work (including CIM-MLC, which it builds directly on) leaves performance on the table by treating CIM arrays as compute-only resources. The DP-plus-MILP formulation is a reasonable way to jointly optimize segmentation and mode allocation, and testing across CNNs, BERT, and multi-billion-parameter LLMs under varying batch/sequence-length regimes gives the results some generality; the main open question for a mapping-focused thesis is how well the idealized dual-mode switch overhead model (3-5%) would hold on real fabricated CIM hardware rather than in the CIM-MLC simulator.", "basis": "full-text", "pdf_source_url": "", "abstract": "Computing-in-memory (CIM) architectures demonstrate superior performance over traditional architectures. To unleash the potential of CIM accelerators, many compilation methods have been proposed, focusing on application scheduling optimization specific to CIM. However, existing compilation methods often overlook CIM's capability to switch dynamically between compute and memory modes, which is crucial for accommodating the diverse memory and computational needs of real-world deep neural network architectures, especially the emerging large language models. To fill this gap, we introduce CMSwitch, a novel compiler to optimize resource allocation for CIM accelerators with adaptive mode-switching capabilities, thereby enhancing the performance of DNN applications. Specifically, our approach integrates the compute-memory mode switch into the CIM compilation optimization space by introducing a new hardware abstraction attribute. Then, we propose a novel compilation optimization pass that identifies the optimal network segment and the corresponding mode resource allocations using dynamic programming and mixed-integer programming. CMSwitch uses the tailored meta-operator to express the compilation result in a generalized manner. Evaluation results demonstrate that CMSwitch achieves an average speedup of 1.31x compared to existing SOTA CIM compilation works, highlighting CMSwitch's effectiveness in fully exploiting the potential of CIM processors for a wide range of real-world DNN applications.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2025_Zhao_CMSwitch_ASPLOS.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2025_Zhao_CMSwitch_ASPLOS.pdf", "priority": 4.83}, {"id": "W4408145534", "short": "LionHeart", "title": "LionHeart: A Layer-Based Mapping Framework for Heterogeneous Systems With Analog In-Memory Computing Tiles", "authors": ["Corey Lammie", "Yuxuan Wang", "Flavio Ponzina", "Joshua Alexander Harrison Klein", "Hadjer Benmeziane", "Marina Zapater", "Irem Boybat", "Abu Sebastian", "Giovanni Ansaloni", "David Atienza"], "year": 2025, "venue": "IEEE Transactions on Emerging Topics in Computing", "venue_short": "TETC", "venue_full": "IEEE Transactions on Emerging Topics in Computing", "venue_ok": true, "doi": "https://doi.org/10.1109/tetc.2025.3546128", "cites_global": 10, "cat": "05", "seed": false, "devices": ["PCM", "Generic-NVM"], "models": ["CNN", "ResNet", "Transformer", "BERT"], "evidence": "algorithm+simulation", "tldr": "LionHeart is a layer-wise, accuracy-constrained search framework that greedily decides which DNN/transformer layers to map to AIMC tiles versus digital compute in a heterogeneous SoC, achieving over 6x system-level speedup and energy-efficiency gains for a user-defined accuracy threshold relative to a fully digital floating-point baseline.", "summary": "Analog in-memory computing (AIMC) crossbars accelerate matrix-vector multiplications but introduce precision loss, stochastic noise, and temporal conductance drift that degrade accuracy over time. LionHeart addresses the resulting accuracy/performance trade-off by producing hybrid analog-digital layer-to-hardware mappings for DNN and transformer inference on heterogeneous systems containing both AIMC tiles and conventional processing units. Using the IBM AIHWKIT to model realistic PCM device behavior (including hardware-aware training and temporal drift at a chosen evaluation time), LionHeart iteratively converts the most AIMC-sensitive layers/channels to digital execution until a user-specified accuracy-degradation threshold (relative to an all-digital floating-point baseline) is satisfied, then estimates system-level performance via a full-system simulation that accounts for tiling, data movement, and non-AIMC compute/memory. Evaluated on ResNet8/20, AlexNet, VGG16, MobileNetV2 (CIFAR-10/100) and MobileBERT (SQuAD), LionHeart finds configurations that AIMC-accelerate a large fraction of MACs (e.g., ~60% for ResNet8 at a 5% accuracy threshold) while bounding accuracy loss, yielding system run-time and energy efficiency gains exceeding 6x versus all-digital execution, and is compared against prior mapping strategies DIANA (Ueyoshi et al.) and Harmonica.", "contributions": ["Proposes LionHeart, a layer/channel-granularity heuristic search for hybrid analog-digital mapping of DNNs and transformers onto heterogeneous AIMC+digital systems under a user-defined accuracy-degradation constraint", "Integrates realistic AIMC device modeling (via IBM AIHWKIT), including hardware-aware training and temporal conductance drift at a chosen evaluation time, directly into the mapping decision", "Builds a full-system performance/energy simulator to translate layer-level analog/digital assignment into run-time and energy-efficiency estimates, accounting for tiling and inter-tile data movement", "Evaluates across multiple CNNs (ResNet8/20, AlexNet, VGG16, MobileNetV2) and a transformer-based network (MobileBERT on SQuAD), exploring the accuracy-vs-performance Pareto front", "Compares against prior application-mapping approaches (PUMA, AERO, DIANA/Ueyoshi et al., Harmonica, ODiMO) and open-sources the framework"], "claims": [{"claim": "LionHeart achieves large system-level speedup and energy-efficiency gains at a bounded accuracy loss relative to all-digital execution", "support": "Run-time reductions and energy efficiency gains exceeding 6x were measured across benchmarks for a user-defined accuracy threshold", "loc": "Abstract"}, {"claim": "A large share of computation can be AIMC-accelerated on ResNet8 while keeping accuracy loss small", "support": "Almost 60% of ResNet8's computation can be AIMC-accelerated for a 5% accuracy threshold, while the all-analog configuration incurs a ~20% accuracy drop", "loc": "Sec. IV.D, Accuracy Evaluation"}, {"claim": "Networks without depthwise-separable convolutions (AlexNet, VGG16) have more headroom for AIMC acceleration than MobileNetV2", "support": "Full-analog speedup of 660% (VGG16) and 550% (AlexNet) vs. only 24% for MobileNetV2 in the all-analog case; at 5% accuracy drop, speedups of 425% (AlexNet) and 285% (VGG16) were measured", "loc": "Sec. IV, Fig. 6 results discussion"}, {"claim": "AIMC tiles are not the dominant contributor to system power, so energy gains track speedup closely", "support": "System-level energy gains closely follow speedup trends because processors and memory, not AIMC tiles, dominate overall power", "loc": "Sec. IV, Fig. 6 discussion"}, {"claim": "Accuracy-threshold-constrained search does not always monotonically trade accuracy for performance due to stochastic heuristic behavior and global threshold enforcement", "support": "For some networks/datasets, the All-Analog configuration outperforms some LionHeart configurations with larger (e.g., 10%) drop thresholds, attributed to heuristic stochasticity and the way the global drop budget is allocated across layers", "loc": "Sec. IV.D"}], "results": ["System-level speedup and energy efficiency gains exceed 6x vs. all-digital floating-point baseline at a user-defined accuracy threshold", "ResNet8: ~60% of MACs AIMC-accelerated at a 5% accuracy-degradation threshold (vs. ~20% accuracy drop for the all-analog configuration)", "VGG16: up to 660% speedup (all-analog) / 285% speedup at 5% accuracy threshold", "AlexNet: up to 550% speedup (all-analog) / 425% speedup at 5% accuracy threshold", "MobileNetV2: only 24% speedup achievable even in the all-analog configuration, due to depthwise-separable convolutions limiting AIMC benefit", "Accuracy evaluated by averaging over 20 stochastic hardware instances per configuration to account for AIMC non-determinism"], "limitations": ["Evaluation is simulation-based using IBM AIHWKIT device models, not measured on physical AIMC silicon", "Heuristic, layer/channel-greedy search can produce non-monotonic accuracy-vs-threshold behavior and is sensitive to where early accuracy drops occur in the network", "Self-attention's internal FC layers (scaled dot-product attention) are excluded from AIMC mapping because their dynamic weights would require constant reprogramming, limiting applicability to full transformer blocks", "Benefits are workload-dependent: networks with depthwise-separable convolutions (e.g., MobileNetV2) see much smaller speedups than standard-convolution networks", "Comparisons to prior work (DIANA, Harmonica) are limited to specific benchmark/network configurations, not a fully general sweep"], "remarks": "LionHeart is a solid, practically-oriented mapping/compilation contribution that treats the analog-vs-digital layer assignment as a first-class, accuracy-budgeted search problem rather than a fixed heuristic (e.g., always keep first/last layers digital), and it is one of the few mapping frameworks in this space to jointly model temporal drift and hardware-aware training in the loop. Its main weakness for a thesis on crossbar mapping is that it operates at coarse layer/channel granularity using a greedy, stochastic search rather than a provably optimal formulation, and transformer support is limited to the FC projections (self-attention's dynamic weights are left on digital hardware) — a gap that later analog-transformer mapping papers in this collection explicitly try to close.", "basis": "full-text", "pdf_source_url": "", "abstract": "When arranged in a crossbar configuration, resistive memory devices can be used to execute Matrix-Vector Multiplications (MVMs), the most dominant operation of many Machine Learning (ML) algorithms, in constant time complexity. Nonetheless, when performing computations in the analog domain, novel challenges are introduced in terms of arithmetic precision and stochasticity, due to non-ideal circuit and device behaviour. Moreover, these non-idealities have a temporal dimension, resulting in a degrading application accuracy over time. Facing these challenges, we propose a novel framework, namedLionHeart, to obtain hybrid analog-digital mappings to execute Deep Learning (DL) inference workloads using heterogeneous accelerators. The accuracy-constrained mappings derived byLionHeartshowcase, across different Convolutional Neural Networks (CNNs) and one transformer-based network, high accuracy and potential for speedup. The results of the full system simulations highlight run-time reductions and energy efficiency gains that exceed 6×, with a user-defined accuracy threshold for a fully digital floating point implementation.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2025_Lammie_LionHeart_TETC.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2025_Lammie_LionHeart_TETC.pdf", "priority": 6.66}, {"id": "W4410583474", "short": "COMPASS", "title": "COMPASS: A Compiler Framework for Resource-Constrained Crossbar-Array Based In-Memory Deep Learning Accelerators", "authors": ["Jihoon Park", "Jeongin Choe", "Dohyun Kim", "Jae‐Joon Kim"], "year": 2025, "venue": "", "venue_short": "DATE", "venue_full": "Design, Automation & Test in Europe Conference & Exhibition (DATE 2025)", "venue_ok": true, "doi": "https://doi.org/10.23919/date64628.2025.10993229", "cites_global": 3, "cat": "05", "seed": false, "devices": ["SRAM-analog", "Generic-NVM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "COMPASS is a compiler framework that partitions DNNs too large to fit on-chip into sequentially-executed, weight-reloaded partitions for crossbar PIM accelerators, using a genetic algorithm to jointly optimize partitioning, weight replication and batching, giving 1.78x throughput and 1.28x EDP over greedy/layerwise baselines.", "summary": "Existing PIM compilers (PUMA, PIMCOMP) assume an entire DNN's weights fit on-chip, which fails as models grow relative to the few-hundred-KB-to-few-MB footprints of real crossbar prototypes. COMPASS targets this resource-constrained regime by partitioning a model into groups of layers ('partitions') that each fit on-chip, executing them sequentially with a weight-replace phase (loading new weights from external/global memory, e.g. DRAM) between partitions, while within a partition layers run pipelined with optional weight replication to balance throughput across layers of different sizes. A genetic algorithm (COMPASS algorithm) explores the partition-group search space (merge/split/move mutations over partition units) using a fitness function that accounts for data dependencies, core utilization, batch size and the number of weight-write instructions, jointly optimizing partitioning and replication rather than treating them as separate problems as prior work did. Evaluated by extending the open-source PIMCOMP framework with a 256x256 SRAM-CIM crossbar model (16nm, power/energy from Jia et al.'s IMC-SRAM prototype, DRAM energy via DRAMsim3) across three resource-constrained chip sizes (S/M/L) and VGG16, ResNet18 and SqueezeNet at 4-bit precision, against greedy and layerwise baseline partitioning schemes.", "contributions": ["First compiler framework (to the authors' knowledge) that handles DNNs exceeding the on-chip memory footprint of crossbar-based PIM accelerators via external-memory weight replacement", "A partition-generation scheme supporting weight reloading and multi-endpoint dependency checks between partitions, unlike prior compilers that assume full on-chip residency", "A joint optimization (via a genetic algorithm) of partitioning and weight replication together, rather than treating replication as a secondary fit-the-remaining-space step", "A batching strategy for partitioned execution that amortizes the weight-reload overhead against throughput/latency trade-offs", "System-level evaluation (extending PIMCOMP) across three chip-size configurations and three CNNs showing consistent throughput and EDP gains"], "claims": [{"claim": "COMPASS can map models (e.g. full VGG16/ResNet18) onto resource-constrained chips that existing compilers (PIMCOMP, PUMA style, assuming full on-chip mapping) cannot map at all", "support": "'existing compiler methods can only map SqueezeNet in resource-constrained chips, while COMPASS allows all three models'", "loc": "Sec. IV.A.2"}, {"claim": "COMPASS improves throughput over naive partitioning baselines", "support": "1.78x average throughput over baselines; 1.80x/1.71x/2.24x over greedy and 1.56x/1.31x/1.98x over layerwise for VGG16/ResNet18/SqueezeNet respectively", "loc": "Sec. IV.B.1, Fig. 6"}, {"claim": "COMPASS improves energy-delay product over baselines despite higher per-inference energy from more replication", "support": "1.28x average EDP improvement over greedy and layerwise combined (2.08x over layerwise specifically)", "loc": "Sec. IV.B.2, Fig. 8"}, {"claim": "COMPASS reduces per-partition latency versus greedy/layerwise schemes", "support": "2.26x and 1.67x speedup vs greedy and layerwise respectively on ResNet18-M-16", "loc": "Sec. IV.B.1, Fig. 7"}, {"claim": "Weight-replacement overhead is effectively amortized by batching", "support": "at batch size 1, weight-load energy dominates over compute energy; at batch size 16, replacement overhead is sufficiently amortized", "loc": "Sec. IV.B.3, Fig. 9"}], "results": ["1.78x average throughput improvement over baseline partitioning methods", "1.28x average energy-delay-product (EDP) savings over baselines", "2.26x / 1.67x latency speedup vs greedy / layerwise on ResNet18-M-16", "Enables mapping of VGG16 and ResNet18 on resource-constrained chips (a few hundred KB-few MB) where baseline compilers can only fit SqueezeNet"], "limitations": ["Evaluated only on an SRAM-based CIM architecture (chosen for maturity of modeling), not ReRAM/PCM/MRAM silicon, though the authors argue the method generalizes", "Only CNNs (VGG16, ResNet18, SqueezeNet) evaluated; no Transformer/LLM workloads", "Latency/power model is simulation-based (extended PIMCOMP estimator + DRAMsim3), not measured hardware", "Genetic-algorithm partition search (population 100, 30 generations) adds compile-time cost not characterized in the paper", "Baselines (greedy, layerwise) are simple heuristics rather than other state-of-the-art partitioning-aware compilers, so gains may partly reflect weak baselines"], "remarks": "This directly targets a practical mapping gap: nearly all crossbar-accelerator compiler work (PUMA, PIMCOMP) assumes the whole model fits on-chip, which does not hold once PIM capacity is measured in few-hundred-KB-to-few-MB prototype terms. The genetic-algorithm co-optimization of partitioning, replication and batch size is a reasonable general technique that should transfer to ReRAM/PCM crossbars with different (and often worse) write costs, though the paper only validates the write-cost sensitivity qualitatively rather than quantitatively for those technologies. As a DATE paper it is simulation-only and compares against weak heuristic baselines rather than other learned/optimized partitioners, so the claimed multipliers should be read as a proof that joint optimization helps, not as a tight bound on achievable gains.", "basis": "full-text", "pdf_source_url": "", "abstract": "Recently, crossbar array based in-memory accelerators have been gaining interest due to their high throughput and energy efficiency. While software and compiler support for the in-memory accelerators has also been introduced, they are currently limited to the case where all weights are assumed to be on-chip. This limitation becomes apparent with the significantly increasing network sizes compared to the in-memory footprint. Weight replacement schemes are essential to address this issue. We propose COMPASS, a compiler framework for resource-constrained crossbar-based processing-in-memory (PIM) deep neural network (DNN) accelerators. COMPASS is specially targeted for networks that exceed the capacity of PIM crossbar arrays, necessitating access to external memories. We propose an algorithm to determine the optimal partitioning that divides the layers so that each partition can be accelerated on chip. Our scheme takes into account the data dependence between layers, core utilization, and the number of write instructions to minimize latency, memory accesses, and improve energy efficiency. Simulation results demonstrate that COMPASS can accommodate much more networks using a minimal memory footprint, while improving throughput by 1.78X and providing 1.28X savings in energy-delay product (EDP) over baseline partitioning methods.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2025_Park_COMPASS_DATE.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2025_Park_COMPASS_DATE.pdf", "priority": 4.92}, {"id": "W4416429527", "short": "CIMWise", "title": "CIMWise: An IREE-based End-To-End AI Compiler with Auto-Tuning for CIM Processors", "authors": ["Bo Mai", "Jin Wang", "Zhen Zhai", "Liang Zhang", "Yufu Zhang", "Longyang Lin"], "year": 2025, "venue": "", "venue_short": "ICCAD", "venue_full": "2025 IEEE/ACM International Conference on Computer Aided Design (ICCAD 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad66269.2025.11240989", "cites_global": 1, "cat": "05", "seed": false, "devices": ["None"], "models": ["DNN (unspecified)"], "evidence": "measured-silicon", "tldr": "CIMWise is an IREE/MLIR-based end-to-end compiler for CIM processors whose auto-tuner searches hardware parameters and dataflow characteristics with a two-stage simulated annealing over an analytical cost model, reporting up to 58% lower energy and 19% lower latency than prior CIM compilers, validated with hardware measurements.", "summary": "Existing CIM compilers mostly parametrise hardware (array size, number of CIM units, buffer capacity) but ignore that different CIM architectures have different dataflow patterns (CIM parallelism, scheduling, buffer allocation). CIMWise builds on IREE: IREE's frontend performs graph-level optimisation and a custom backend performs operator-level optimisation. At its core is an auto-tuning framework with a search space covering both hardware parameters and dataflow characteristics, an analytical cost model with an adaptable on-chip memory model, and a two-stage simulated annealing search to find scheduling strategies per workload. The approach is validated through actual hardware measurements and achieves up to 58% energy reduction and 19% latency reduction over prior CIM compilers.", "contributions": ["IREE-based end-to-end compilation flow for CIM processors (graph-level via IREE frontend, operator-level via custom backend)", "Search space that includes dataflow characteristics in addition to hardware parameters", "Analytical cost model with adaptable on-chip memory model", "Two-stage simulated annealing auto-tuner; validation via hardware measurements"], "claims": [{"claim": "Prior CIM compilers neglect dataflow-pattern diversity across CIM architectures.", "support": "Motivation stated in abstract", "loc": "Abstract"}, {"claim": "CIMWise reduces energy and latency relative to prior CIM compilers.", "support": "'up to a 58% reduction in energy consumption and a 19% decrease in latency compared to prior CIM compilers'", "loc": "Abstract"}, {"claim": "The compiler's results are validated on real hardware.", "support": "'validated through actual hardware measurements'", "loc": "Abstract"}], "results": ["Up to 58% energy reduction vs. prior CIM compilers (abstract)", "Up to 19% latency reduction vs. prior CIM compilers (abstract)"], "limitations": ["Abstract-only analysis; target CIM processor, its memory technology (analog vs. digital, SRAM vs. NVM), workloads and baseline compilers not verified", "'Up to' figures are best cases", "Analytical cost model accuracy relative to hardware not quantified in abstract", "Device type left as 'None' (device-agnostic compiler) because the abstract does not specify it"], "remarks": "Notable mainly for integrating CIM compilation into a mainstream MLIR stack (IREE) rather than a bespoke toolchain, and for claiming hardware-measured validation, which most CIM compilers (PIMCOMP, CIM-MLC, polyhedral flows) lack. The energy gains come from scheduling/buffer decisions rather than analog circuit changes, so they are likely orthogonal to non-ideality and ADC work.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Computing-In-memory (CIM) processors have emerged as a promising approach for accelerating deep neural networks (DNNs). To unleash the potential of diverse CIM architectures, it is essential to develop a tailored compiler that is aware of both the architectural parameters of CIM processors (e.g., CIM array size, number of CIM units, on-chip buffer capacity) and their dataflow characteristics (e.g., CIM parallelism, dataflow scheduling, buffer allocation). However, existing CIM compilers primarily focus on hardware parameters, while neglecting the diversity of dataflow patterns across different architectures. In this paper, we propose CIMWise, a general, IREE-based, end-to-end AI compiler for CIM processors. At its core, an auto-tuning framework has been developed, comprising a comprehensive search space (including both hardware parameters and dataflow characteristics), an analytical cost model (integrating an adaptable on-chip memory model), and a two-stage simulated annealing search algorithm, to explore optimal scheduling strategies for the target workload on CIM processors. Additionally, CIMWise leverages IREE’s frontend for graph-level optimization and implements a customized backend to perform operator-level optimization using the proposed auto-tuning framework, enabling seamless end-to-end deployment of neural networks on CIM processors. The proposed CIMWise is validated through actual hardware measurements. Experimental results show that CIMWise achieves up to a 58% reduction in energy consumption and a 19% decrease in latency compared to prior CIM compilers.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2025_Mai_CIMWise_ICCAD.pdf", "analysed": true, "pdf": null, "priority": 5.31}, {"id": "W4413633179", "short": "CIMFlow", "title": "CIMFlow: Modelling Dataflow in Cross-Layer Compute-in-Memory Deep Learning Accelerators", "authors": ["José Cubero-Cascante", "Lenka Schneider", "Rebecca Pelke", "Arunkumar M. Vaidyanathan", "Rainer Leupers", "Jan Moritz Joseph"], "year": 2025, "venue": "ACM Transactions on Embedded Computing Systems", "venue_short": "TECS", "venue_full": "ACM Transactions on Embedded Computing Systems, Vol. 24, Issue 5s (2025)", "venue_ok": true, "doi": "https://doi.org/10.1145/3760780", "cites_global": 0, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "simulation", "tldr": "CIMFlow models fully-weight-stationary, cross-layer (pipelined multi-core) CNN inference on CIM accelerators as a timed cyclo-static dataflow graph, showing cross-layer execution cuts latency by up to 52x and that ignoring memory-access delays overestimates throughput by up to 308%.", "summary": "Multi-core CIM accelerators with dense NVM arrays can hold all weights on-chip (fully weight-stationary, FWS) and run layers as a pipeline with intermediate tensors kept on-chip, but no existing tool modelled the resulting dataflow, memory access patterns and timing. CIMFlow combines a Hardware Architecture Model (CIM and digital cores, with the buffets storage idiom for distributed token-based flow control) and an Array-OL-based Workload Model that captures CNNs' multidimensional dependencies and applies hardware-aware transformations. Both are lowered to a timed cyclo-static dataflow (CSDF) graph that is simulated to produce latency, energy and core/buffer utilisation traces. Mapping is layer-to-core with weights pinned in CIM arrays; the tool focuses on the data movement between cores and buffers. Case studies on state-of-the-art CNNs report up to 52x latency reduction from cross-layer inference and up to 308% throughput overestimation when memory access delays are neglected.", "contributions": ["Hardware Architecture Model for multi-core CIM with CIM and digital cores and buffet-based token flow control", "Array-OL-based workload model capturing multidimensional CNN dependencies with hardware-aware transformations", "Lowering to a timed cyclo-static dataflow graph to simulate FWS cross-layer execution, reporting latency, energy and utilisation traces", "Case studies quantifying the benefit of cross-layer inference and the error of ignoring memory access costs"], "claims": [{"claim": "Cross-layer (pipelined) inference on multi-core CIM substantially reduces latency versus layer-by-layer execution.", "support": "Abstract: 'cross-layer inference reduces latency by up to 52x'", "loc": "Abstract"}, {"claim": "Neglecting memory-access delays leads to large throughput overestimation for CIM accelerators.", "support": "Abstract: 'throughput overestimations of up to 308%'", "loc": "Abstract"}, {"claim": "CIMFlow is the first tool focused on FWS cross-layer execution in CIM that explicitly models data movement costs.", "support": "Stated novelty claim in abstract", "loc": "Abstract"}], "results": ["Up to 52x latency reduction with cross-layer inference on state-of-the-art CNNs (abstract)", "Ignoring memory access delays overestimates throughput by up to 308% (abstract)"], "limitations": ["Abstract-only analysis: models, architectures and baselines behind the 52x/308% figures not verified", "Workload model targets CNNs; transformers/attention not mentioned", "Performance/energy modelling only; no analog non-idealities or accuracy modelling", "FWS assumption requires all weights to fit on-chip, which does not hold for large models"], "remarks": "A useful cost model for the system-level (inter-core, buffer) side of mapping CNNs to multi-core CIM, complementing intra-macro models such as CiMLoop and NeuroSim. The 308% figure is a pointed warning against throughput numbers from analytical models that assume ideal data movement (common in ISAAC/PUMA-style evaluations). Its FWS framing is tied to chips like IBM's 64-core PCM chip and NeuRRAM, where all weights are resident; its relevance for LLM-scale models that exceed on-chip capacity is limited.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Traditional Deep Learning Accelerators (DLAs) rely on off-chip memory to store large weight tensors, leading to high bandwidth demands and energy consumption. Compute-in-Memory (CIM) accelerators mitigate this by integrating high-density, non-volatile memory arrays, enabling a fully weight-stationary (FWS) dataflow. Multi-core CIM systems further enhance efficiency with cross-layer inference, where intermediate tensors stay on-chip, and cores operate in a pipeline. Despite diverse architecture proposals, no existing tool models the dataflow, memory access patterns and timing behaviour of multi-core CIM accelerators. We introduce CIMFlow, a modelling framework for cross-layer CIM architectures. Our flexible Hardware Architecture Model includes CIM and digital cores and leverages the buffets storage idiom for distributed token-based flow control. An Array-OL-based Workload Model captures CNNs’ multidimensional dependencies and applies hardware-aware transformations. These models are transformed into a timed cyclo-static dataflow graph for simulation. CIMFlow delivers latency, energy and traces for core and buffer utilisation. Our case studies on state-of-the-art CNNs show that cross-layer inference reduces latency by up to 52×. We also reveal that neglecting memory access delays results in throughput overestimations of up to 308%. To our knowledge, CIMFlow is the first tool focused on FWS cross-layer execution in CIM architectures that explicitly models data movement costs. It serves as a powerful cost model for design space exploration in next-generation CIM accelerators.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2025_CuberoCascante_CIMFlow_TECS.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2025_CuberoCascante_CIMFlow_TECS.pdf", "priority": 4.5}, {"id": "W4415179271", "short": "PIMapping", "title": "PIMapping: A Tile-Level Dataflow Optimization Framework for PIM Architecture", "authors": ["Ziqian Zhu", "Yifei Zhou", "Jinsen Zhu", "Yuxuan Wang", "Hongbing Pan"], "year": 2025, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2025, early access)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2025.3621513", "cites_global": 0, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "analytical", "tldr": "PIMapping is an analytical framework for tile-based PIM accelerators that uses a tile-level dataflow IR, a data-proximity mapping method and congestion-aware scheduling to cut inter-tile communication latency and bandwidth versus prior mapping frameworks.", "summary": "Hierarchical tile-based PIM accelerators exploit multi-layer parallelism, but existing dataflow analysis uses computational models and metrics that do not fit tile-level dataflows. PIMapping defines a general tile-level dataflow representation as an IR for multi-layer DNN mapping and scheduling. On top of it, a data-proximity-based mapping places layers/weight blocks on tiles to minimise inter-tile communication, and a congestion-aware scheduler reduces inter-tile communication conflicts. Case studies map common DNNs onto several PIM architectures and report improvements over the state-of-the-art mapping framework in communication latency, required inter-tile bandwidth and pipeline efficiency.", "contributions": ["General tile-level dataflow representation used as an IR for multi-layer mapping and scheduling", "Data-proximity-based tile mapping to minimise inter-tile communication", "Congestion-aware scheduling to reduce inter-tile communication conflicts", "Case studies across several tile-based PIM architectures"], "claims": [{"claim": "Existing dataflow analysis models/metrics are unsuitable for tile-level dataflows in tile-based PIM.", "support": "Motivation stated in abstract", "loc": "Abstract"}, {"claim": "PIMapping improves communication latency, inter-tile bandwidth requirement and pipeline efficiency over the state-of-the-art mapping framework.", "support": "Abstract states 'significant improvements'; magnitudes not given in abstract", "loc": "Abstract"}], "results": ["Reported improvements in communication latency, inter-tile bandwidth and pipeline efficiency vs. state-of-the-art mapping framework (magnitudes not available from abstract)"], "limitations": ["Abstract-only analysis; no numbers available", "Analytical model; no cycle-accurate or silicon validation indicated", "Focus on inter-tile communication; intra-crossbar effects (ADC cost, non-idealities, accuracy) out of scope", "Workloads described only as 'common DNN algorithms'"], "remarks": "Addresses the NoC/inter-tile side of mapping, which ISAAC/PUMA-style designs largely abstract away and which becomes dominant once layers are pipelined across many tiles. It sits alongside PIMCOMP, CIM-MLC and AERO-style mappers; the lack of quantitative claims in the abstract makes it hard to judge its margin over them without the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Process-in-memory (PIM) accelerators demonstrate outstanding performance in accelerating matrix-vector multiplication (MVM) tasks in neural networks. To achieve better acceleration performance, extensive research has focused on the design of hierarchical tile-based PIM architectures, presenting challenges for the hardware deployment of algorithms. Multilayer parallelism in tile-based architectures requires the support of dataflow optimization techniques. However, existing research primarily performs dataflow analysis using computational models and performance metrics that are not suitable for tile-level dataflows. In this paper, we propose an analytical framework, PIMapping, for tile-based PIM architectures that supports multi-layer parallelism mapping and tile-level dataflow optimization. In this work, we first establish a general dataflow representation for tile-level dataflow, which serves as an intermediate representation (IR) for multi-layer DNN mapping and scheduling tasks at tile level. Next, based on the proposed representation, we introduce a data proximity-based mapping method aimed at minimizing the inter-tile communication overhead. Furthermore, we propose a congestion-aware scheduling algorithm to minimize inter-tile communication conflicts. Experimental case-studies are conducted to map common DNN algorithms onto different PIM architectures. The results demonstrate significant improvements over the state-of-the-art mapping framework in terms of communication latency, required inter-tile bandwidth, and pipeline efficiency.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2025_Zhu_PIMapping_TCAD.pdf", "analysed": true, "pdf": null, "priority": 4.5}, {"id": "W4417052206", "short": "HARMONY", "title": "HARMONY: A Hardware-Aware Mapping and Optimizing Framework for Computing-in-Memory Accelerators", "authors": ["Xinmo Li", "Weidong Yang", "Naifeng Jing", "Qin Wang", "Zhigang Mao", "Weiguang Sheng"], "year": 2025, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2025, early access)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2025.3641044", "cites_global": 0, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["DNN (unspecified)"], "evidence": "simulation", "tldr": "HARMONY is a CIM compiler built on a hardware IR unifying compute and memory abstractions; it automatically identifies CIM-offloadable operators, builds a hybrid SW/HW IR and uses reinforcement learning to search a joint space of general-purpose and CIM-specific scheduling primitives.", "summary": "Model and hardware diversity make CIM accelerators hard to exploit, and existing approaches rely on manual mapping or limited automation that does not combine general-purpose compiler optimisations with CIM-specific features. HARMONY introduces a hardware intermediate representation that unifies computational and memory abstractions. An automatic mapping algorithm identifies operators that can be offloaded to CIM and constructs a hybrid software-hardware IR, which lets general-purpose and CIM-specific scheduling primitives coexist in one search space. The space is explored with reinforcement learning. Evaluations report support for a broader set of operators than existing CIM compilers and consistent performance and energy improvements across diverse DNN workloads.", "contributions": ["Hardware IR unifying computational and memory abstractions of CIM accelerators", "Automatic offloadable-operator identification and hybrid SW-HW IR construction", "Unified search space combining general-purpose and CIM-specific scheduling primitives", "RL-based exploration of the scheduling space"], "claims": [{"claim": "HARMONY supports a broader set of operators than existing CIM compilers.", "support": "Stated in abstract; no operator counts given", "loc": "Abstract"}, {"claim": "HARMONY consistently improves performance and energy across diverse DNN workloads.", "support": "Stated qualitatively in abstract", "loc": "Abstract"}], "results": ["Performance and energy improvements over existing CIM compilers across diverse DNN workloads (magnitudes not available from abstract)"], "limitations": ["Abstract-only analysis; no quantitative results, target architectures or baselines verified", "RL search cost/compile time not characterised in abstract", "Likely evaluated with simulators/cost models rather than silicon", "Accuracy effects of analog non-idealities presumably out of scope"], "remarks": "Positions itself against PIMCOMP, OCC and polyhedral CIM compilers by merging TVM-like general scheduling with CIM-specific primitives; the hybrid IR idea (deciding what runs on CIM vs. digital units) is important for transformer-style models with many non-MVM ops. Without the full text, the size of the gains and the realism of the hardware model cannot be assessed.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The increasing adoption of artificial intelligence has spurred the development of specialized deep neural network (DNN) accelerators. Among them, computing-in-memory (CIM) architectures are promising for their in-situ computation capability, which alleviates the computation and data movement bottlenecks of modern DNNs. However, the diversity of models and hardware designs makes it challenging to fully exploit CIM accelerators. Existing approaches often rely on manual mapping or provide limited automation, struggling to integrate general-purpose optimizations with CIM-specific features. In this work, we present HARMONY, a hardware-aware compilation framework for CIM accelerators. At its core is a hardware intermediate representation (IR) that unifies computational and memory abstractions. Based on this IR, HARMONY introduces an automatic mapping algorithm that identifies offloadable operators and constructs a hybrid software–hardware IR. This enables systematic integration of general-purpose and CIM-specific scheduling primitives within a unified search space, which is efficiently explored using reinforcement learning (RL). Extensive evaluations show that HARMONY supports a broader set of operators than existing CIM compilers and consistently delivers substantial performance and energy improvements across diverse DNN workloads. These results demonstrate that HARMONY provides both generality and efficiency, making it a practical compilation solution for CIM accelerators.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2025_Li_HARMONY_TCAD.pdf", "analysed": true, "pdf": null, "priority": 4.5}, {"id": "W4394998365", "short": "CIM-MLC", "title": "CIM-MLC: A Multi-level Compilation Stack for Computing-In-Memory Accelerators", "authors": ["Songyun Qu", "Shixin Zhao", "Bing Li", "Yintao He", "Xuyi Cai", "Lei Zhang", "Ying Wang"], "year": 2024, "venue": "", "venue_short": "ASPLOS", "venue_full": "ACM International Conference on Architectural Support for Programming Languages and Operating Systems (ASPLOS 2024)", "venue_ok": true, "doi": "https://doi.org/10.1145/3620665.3640359", "cites_global": 11, "cat": "05", "seed": false, "devices": ["ReRAM", "SRAM-analog", "Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "CIM-MLC is a universal, multi-level compilation stack for computing-in-memory accelerators that introduces a general hardware abstraction (chip/core/crossbar tiers, Virtual Crossbar) and jointly schedules across computing-graph, MVM, and VVM granularities, achieving up to 3.2x inference speedup over prior CIM-oriented compilers.", "summary": "The paper addresses the fragmentation of DNN-to-CIM compilation tools: existing compilers target specific device types, architecture hierarchies, or programming interfaces and are not portable across the diverse CIM accelerator landscape (ReRAM, SRAM, PCM/Flash-based; single- vs multi-tier hierarchies; MVM vs VVM programming interfaces such as PUMA, ISAAC, PRIME, FORMS). CIM-MLC introduces a general hardware abstraction with architecture parameters (Abs-arch) and computing-mode (Abs-com) descriptions spanning chip, core, and crossbar tiers, and defines a Virtual Crossbar (VXB) concept as the compiler's computational unit (decoupled from physical crossbar specifics) to represent diverse CIM designs uniformly. On top of this abstraction, the compiler explores a multi-level scheduling/mapping space -- computing-graph-grained (CG-grained: pipelining and duplication), MVM-grained, and VVM-grained optimization -- which the authors argue is more tractable than single-level fine-grained scheduling while covering a broader space than prior graph- or MVM-level-only compilers (e.g., the polyhedral-based approach of Han et al.). The framework is validated on existing CIM accelerators including PUMA, demonstrating consistent inference speedups over prior CIM compilation work.", "contributions": ["General hardware abstraction (Abs-arch/Abs-com) for CIM architectures spanning chip, core, and crossbar tiers, supporting diverse devices (ReRAM, SRAM, PCM/Flash) and programming interfaces (MVM, VVM)", "Introduces the Virtual Crossbar (VXB) concept to decouple compiler scheduling from physical crossbar specifics", "A multi-level (CG-grained, MVM-grained, VVM-grained) mapping/scheduling optimization flow that is more tractable than single-level fine-grained scheduling while covering more of the design space than prior graph-only or MVM-only compilers", "Demonstrates up to 3.2x inference speedup over prior CIM-oriented compilation work (e.g., Han et al.'s polyhedral-based compiler)", "Validates the compilation stack on existing CIM accelerator designs, including PUMA", "Open-sources the framework"], "claims": [{"claim": "CIM-MLC achieves up to 3.2x inference speedup compared to prior CIM-oriented compilation work (Han et al.'s polyhedral-based compiler for ISAAC).", "support": "comparison experiment reported for computation-cycle reduction up to 95%, ~3.2x speedup", "loc": "Sec. 4 (experiments), p.~1987-1988"}, {"claim": "CG-grained optimization combining dynamic-programming-based duplication and pipelining (CG-P&D) achieves about 3.7x speedup over a prior scheduling method (Jia et al.).", "support": "Figure 20(a) comparison", "loc": "Sec. 4, Fig. 20(a), p.~1942-1944"}, {"claim": "Multi-level (CG+MVM-grained) optimization achieves about 2.3x speedup over Jain et al.'s work.", "support": "reported speedup figure", "loc": "Sec. 4, p.~1966-1967"}, {"claim": "VVM-grained optimization on ResNet50 achieves about 10% higher speedup than MVM-grained optimization alone, because data remapping improves pipeline throughput.", "support": "Figure 21(c) comparison", "loc": "Sec. 4, Fig. 21(c)"}, {"claim": "Pipeline-based CG-grained optimization speedup increases from 2.3x to 4.7x as ResNet depth increases (ResNet50 to ResNet101).", "support": "scaling experiment with ResNet depth", "loc": "Sec. 4, Fig. 21(a), p.~2175-2183"}], "results": ["Up to 3.2x inference speedup vs. prior CIM-oriented compilation work (Han et al., polyhedral-based, on ISAAC)", "~3.7x speedup from combined CG-grained duplication+pipelining vs. Jia et al.'s scheduling", "~2.3x speedup from combined multi-granularity optimization vs. Jain et al.'s work", "CG-Pipeline speedup scales from 2.3x to 4.7x as ResNet depth grows from ResNet50 to ResNet101", "VVM-grained optimization gives ~10% additional speedup over MVM-grained alone on ResNet50"], "limitations": ["Evaluation is simulation/compilation-based; no fabricated silicon results, relies on modeled CIM architecture parameters rather than measured device behavior", "Comparisons are against specific prior compilation works (Han et al., Jia et al., Jain et al.) rather than a broad, standardized compiler benchmark suite", "Evaluated primarily on CNN workloads (e.g., ResNet); no evidence from the reviewed sections of transformer/LLM support", "Device-level nonidealities (ADC noise, conductance drift, etc.) are abstracted away at the compilation level; the framework targets scheduling/mapping efficiency, not analog accuracy modeling"], "remarks": "CIM-MLC is a solid compiler-stack contribution to the mapping/compilation thread of analog/PIM research, directly analogous to general-purpose DNN accelerator compilers (e.g., Timeloop/Maestro-style approaches) but tailored to CIM-specific constraints (crossbar tiers, VMM/VVM granularity). Its core insight -- that scheduling across multiple architectural granularities (graph/MVM/VVM) is more tractable and effective than single-level scheduling -- is a useful design principle for a thesis chapter on mapping DNNs to crossbar hardware. Because validation is against specific named prior compilers rather than an industry-standard benchmark, the reported speedups (2.3x-4.7x depending on setting) should be read as relative to those particular baselines.", "basis": "full-text", "pdf_source_url": "", "abstract": "In recent years, various computing-in-memory (CIM) processors have been presented, showing superior performance over traditional architectures. To unleash the potential of various CIM architectures, such as device precision, crossbar size, and crossbar number, it is necessary to develop compilation tools that are fully aware of the CIM architectural details and implementation diversity. However, due to the lack of architectural support in current popular open-source compiling stacks such as TVM, existing CIM designs either manually deploy networks or build their own compilers, which is time-consuming and labor-intensive. Although some works expose the specific CIM device programming interfaces to compilers, they are often bound to a fixed CIM architecture, lacking the flexibility to support the CIM architectures with different computing granularity. On the other hand, existing compilation works usually consider the scheduling of limited operation types (such as crossbar-bound matrix-vector multiplication). Unlike conventional processors, CIM accelerators are featured by their diverse architecture, circuit, and device, which cannot be simply abstracted by a single level if we seek to fully explore the advantages brought by CIM.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2024_Qu_CIMMLC_ASPLOS.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2024_Qu_CIMMLC_ASPLOS.pdf", "priority": 7.58}, {"id": "W4404294109", "short": "PIMCOMP", "title": "PIMCOMP: An End-to-End DNN Compiler for Processing-In-Memory Accelerators", "authors": ["Xiaotian Sun", "Xinyu Wang", "Wanqian Li", "Yinhe Han", "Xiaoming Chen"], "year": 2024, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2024.3496847", "cites_global": 6, "cat": "05", "seed": false, "devices": ["ReRAM", "Generic-NVM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "PIMCOMP is an end-to-end DNN compiler for crossbar-based PIM accelerators that abstracts hardware into a configurable pseudo-instruction template and jointly optimizes weight-layout-guided computation-storage mapping and dataflow scheduling, achieving up to ~274x throughput and ~25x energy-efficiency gains over prior compilation methods across three architectures.", "summary": "Deploying DNNs onto diverse crossbar-based PIM accelerators (which differ in micro-architecture, interfaces, and scale) is too complex for manual design, so the authors propose PIMCOMP, an end-to-end compiler built on an abstract configurable PIM accelerator template with pseudo-instructions that can be lowered to specific hardware intrinsics. PIMCOMP targets two system-level problems: resource utilization (via a flexible unfolding format for convolution layers plus a weight-layout-guided computation-storage-mapping, as opposed to prior 'naive computation-storage-binding' compilers) and dataflow scheduling (two inter-layer pipeline algorithms -- High-Throughput (HT) for batched inference and Low-Latency (LL) for single-sample pixel-level pipelining -- to support different application scenarios). The compiler is evaluated by implementing itself and three baselines (SongC, PUMA, Polyhedral) within the same framework and simulating them (crossbar/VFU power from prior PIM work, memory/router power from CACTI and Orion 3.0, 32nm-scaled) across three PIM architecture configurations and four CNN benchmarks (VGG8, ResNet18 on MNIST; ResNet34, GoogLeNet on ImageNet) with 16-bit fixed-point weights. In the high-throughput (batch=128) scenario PIMCOMP achieves up to roughly 274x throughput improvement and much higher resource utilization than baselines; in the low-latency scenario it achieves up to ~25x energy savings and comparable large latency/throughput gains, demonstrating that better resource allocation, data layout, and scheduling -- independent of the underlying device -- substantially improve PIM deployment efficiency.", "contributions": ["An abstract, configurable PIM accelerator template with pseudo-instructions that generalizes across different crossbar-based PIM micro-architectures", "A generic multi-level optimization framework converting a high-level DNN description end-to-end into pseudo-instructions / hardware intrinsics", "A flexible unfolding format plus weight-layout-guided computation-storage mapping that improves resource utilization over prior 'naive computation-storage-binding' compilers", "Two dataflow scheduling algorithms (High-Throughput and Low-Latency) targeting different inter-layer pipeline granularities and application scenarios", "A faithful re-implementation of three baseline compilation methods (SongC, PUMA, Polyhedral) within the same framework for controlled comparison across three hardware architectures", "Open-source release (github.com/sunxt99/PIMCOMP-NN); extends an earlier conference version (PIMCOMP, ref. 12) with hardware compatibility, software support and holistic performance improvements"], "claims": [{"claim": "PIMCOMP's weight-layout-guided computation-storage-mapping and scheduling substantially outperform prior compilation strategies in high-throughput (batched) inference", "support": "Fig. 10: throughput improvements up to ~274.4x and large resource-utilization gains vs. SongC/PUMA/Polyhedral baselines across VGG8/ResNet18/ResNet34/GoogLeNet on three architectures", "loc": "Sec. VIII-B1, Fig. 10"}, {"claim": "PIMCOMP's low-latency dataflow scheduling gives large energy savings in single-sample (batch=1) inference", "support": "Fig. 11 (normalized energy savings): up to ~14.5x-25.3x energy-efficiency gains over baselines depending on architecture/network", "loc": "Sec. VIII-B, Figs. 11-12"}, {"claim": "Prior PIM compilers do not jointly consider weight replication and weight layout, limiting their resource utilization", "support": "comparison table: TC-CIM, TDO-CIM, CINM, OCC, Polyhedral, Co-Design, PUMA, and SongC all use 'naive computation-storage-binding' design philosophy versus PIMCOMP's 'weight-layout guided computation-storage-mapping'", "loc": "Sec. II, comparison table"}], "results": ["High-throughput scenario: throughput improvements over baselines ranging roughly 2x-274x depending on architecture/network/baseline (Fig. 10)", "Low-latency scenario: normalized energy savings ranging roughly 2x-25x over baselines (Fig. 11); resource utilization improved from as low as single-digit percent to much higher values under PIMCOMP", "Evaluated on 4 CNNs (VGG8, ResNet18 on MNIST; ResNet34, GoogLeNet on ImageNet, 16-bit fixed-point weights) across 3 PIM hardware architecture configurations"], "limitations": ["Evaluation is simulation-based (crossbar/VFU power from literature values, memory/router power via CACTI/Orion 3.0 scaled to 32nm) rather than on fabricated hardware", "Benchmarks are limited to CNN classification models (VGG8, ResNet18/34, GoogLeNet); no Transformer/LLM workloads evaluated", "Baselines (SongC, PUMA, Polyhedral) are re-implemented by the authors within PIMCOMP's own framework rather than run via their original codebases, which could introduce implementation bias", "Architecture abstraction (pseudo-instruction template) is derived from existing crossbar PIM accelerator designs and may not capture every possible PIM micro-architecture variant", "16-bit fixed-point weight quantization is used uniformly; no exploration of lower-bit or mixed-precision quantization effects on accuracy"], "remarks": "A solid systems/compiler contribution to the mapping and dataflow-scheduling side of crossbar PIM research, notable for implementing and fairly comparing three prior compilation approaches (SongC, PUMA, Polyhedral) within one common framework rather than relying on reported numbers, which strengthens the throughput/energy comparisons. As a journal extension of an earlier PIMCOMP conference paper, it is squarely a mapping/compilation contribution (orthogonal to device or circuit innovations) and is already cited by other 2025 CiM mapping/dataflow frameworks (HARMONY, TriCIM), suggesting it is becoming a reference baseline for PIM compiler research. Its evaluation remains simulation-only and CNN-focused, so its claims about generality to Transformer workloads and real hardware are untested here.", "basis": "full-text", "pdf_source_url": "", "abstract": "In the past decade, various processing-in-memory (PIM) accelerators based on various devices, micro-architectures, and interfaces have been proposed to accelerate deep neural networks (DNNs). How to deploy DNNs onto PIM-based accelerators is the key to explore PIM’s high performance and energy efficiency. The scale of DNN models, the diversity of PIM accelerators, and the complexity of deployment are far beyond the human deployment capability. Hence, an automatic deployment methodology is indispensable. In this work, we propose PIMCOMP, an end-to-end DNN compiler tailored for PIM accelerators, achieving efficient deployment of DNN models on PIM hardware. PIMCOMP can adapt to various PIM architectures by using an abstract configurable PIM accelerator template with a set of pseudo instructions, which is a high-level abstraction of the hardware’s fundamental functionalities. Through a generic multilevel optimization framework, PIMCOMP realizes an end-to-end conversion from a high-level DNN description to pseudo instructions, which can be further converted to specific hardware intrinsics/primitives. The compilation addresses two critical issues in PIM-accelerated inference from a system perspective: 1) resource utilization and 2) dataflow scheduling. PIMCOMP adopts a flexible unfolding format to reshape and partition convolutional layers, adopts a weight-layout guided computation-storage-mapping approach to enhance resource utilization, and balances the system’s computation, memory access, and communication characteristics. For dataflow scheduling, we design two scheduling algorithms with different interlayer pipeline granularities to support varying application scenarios while ensuring high-computational parallelism. Experiments demonstrate that PIMCOMP improves throughput, latency, and energy efficiency across various architectures. PIMCOMP is open-sourced athttps://github.com/sunxt99/PIMCOMP-NN.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2024_Sun_PIMCOMP_TCAD.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2024_Sun_PIMCOMP_TCAD.pdf", "priority": 6.89}, {"id": "W4360831836", "short": "INCA", "title": "INCA: Input-stationary Dataflow at Outside-the-box Thinking about Deep Learning Accelerators", "authors": ["Bokyung Kim", "Shiyu Li", "Hai Helen Li"], "year": 2023, "venue": "", "venue_short": "HPCA", "venue_full": "IEEE International Symposium on High-Performance Computer Architecture (HPCA 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/hpca56546.2023.10070992", "cites_global": 28, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "simulation", "tldr": "INCA proposes an input-stationary (rather than weight-stationary) RRAM crossbar dataflow using a novel 2T1R cell and 3D stacked architecture, achieving up to 20.6x/260x energy efficiency and 4.8x/18.6x speedup over a weight-stationary baseline for inference/training while also being more robust to RRAM noise on weights.", "summary": "The paper argues that all prior RRAM-based PIM accelerators implicitly use weight-stationary (WS) dataflow, which forces heavy DRAM/buffer traffic for activations, extra RRAM arrays for transposed weights during training, coarse-grained arrays requiring high-resolution ADCs, and accuracy sensitivity to RRAM weight nonidealities. INCA instead stores activations (inputs) in the RRAM array and streams weights through it, using a new two-transistor-one-RRAM (2T1R) cell that enables direct convolution with kernel sliding while retaining one-shot current accumulation via Kirchhoff's law. To get high batch parallelism despite the finer-grained arrays this dataflow requires, INCA stacks 2T1R vertical planes into a 3D RRAM structure where each plane processes one image of a batch in parallel, sharing input pillars. The design is mapped to intra-layer (feature-map partitioning across small arrays with adder-tree accumulation) and inter-layer (sequential layer-to-macro assignment) schemes, and supports a full forward/backward training flow by reusing activation RRAM cells for backpropagated errors. Evaluated via a custom simulator built on a circuit-simulated (TSMC 65nm) 2T1R cell integrated into NeuroSim+, against an ISAAC/PipeLayer-like WS baseline and a GPU, across VGG16/19, ResNet18/50, MobileNetV2 and MNasNet on ImageNet: INCA cuts buffer accesses, uses much lower-resolution (4-bit vs 8-bit) ADCs due to small arrays, and under RRAM noise injected on weights vs. activations, shows far less training-accuracy degradation (86% vs. 15% at sigma=0.05) because noise lands on frequently-rewritten activations rather than persistent weights.", "contributions": ["Identification that all prior RRAM PIM accelerators are implicitly weight-stationary, and a systematic argument for why input-stationary (IS) dataflow addresses WS's buffer/DRAM dependency, transpose-weight overhead, ADC resolution, and noise-sensitivity limitations", "A novel 2T1R RRAM cell design that supports direct convolution with kernel sliding (not achievable in standard 1T1R crossbars) while retaining one-shot Kirchhoff's-law current accumulation", "A 3D stacked RRAM architecture (vertically erected 2T1R planes sharing input pillars) that recovers batch-level parallelism for the smaller, finer-grained arrays IS dataflow requires", "Intra-/inter-layer mapping schemes and a full training dataflow (forward, backward error propagation, weight update) that reuses activation cells for gradients", "End-to-end evaluation on 6 ImageNet CNNs via a custom circuit-calibrated NeuroSim+-based simulator, including an RRAM noise-robustness study on weights vs. activations"], "claims": [{"claim": "INCA's IS dataflow substantially improves energy efficiency over a WS RRAM PIM baseline for both inference and training", "support": "Up to 20.6x (VGG16), 15.9x (VGG19), 8.7x (ResNet18), 8.0x (ResNet50) energy-efficiency improvement for inference; 260x, 202x, 103x, 152x for training on the same models", "loc": "Sec. V.B.1, Fig. 11"}, {"claim": "INCA achieves speedup over the WS baseline for both inference and training", "support": "4.6x/3.7x (VGG16/19) and 1.9x/4.8x (ResNet18/50) speedup in inference; 18.6x, 14.2x, 7.2x, 6.8x speedup in training for the four models", "loc": "Sec. V.B.2, Fig. 14"}, {"claim": "Fine-grained arrays in INCA allow much lower-resolution ADCs, cutting ADC energy substantially", "support": "ADCs of INCA spend 5x less energy in total than ADCs of the baseline (4-bit vs 8-bit ADC, with one 8-bit ADC costing as much as four 4-bit ADCs)", "loc": "Sec. V.B.1, Fig. 13a"}, {"claim": "INCA's 3D design offers an area advantage despite the larger 2T1R cell", "support": "16 stacked INCA cells occupy 0.048 micron^2 vs. 0.030 micron^2 for one baseline 1T1R cell; total chip area 47.914 mm^2 (INCA) vs. 84.088 mm^2 (baseline) at iso-capacity", "loc": "Sec. V.B.6, Table V"}, {"claim": "Because INCA stores activations (frequently rewritten) rather than weights in RRAM, it is far more robust to RRAM nonideality noise applied to weights than the WS baseline", "support": "Training accuracy with weight noise sigma=0.05 drops to 15.17% in the noisy-weight case vs. only 85.59% drop for noisy-activation case (used as proxy for INCA's exposure)", "loc": "Sec. V.B.7, Table VI"}], "results": ["20.6x/260x peak energy-efficiency improvement over WS RRAM baseline for inference/training (VGG16)", "4.8x/18.6x peak speedup over baseline for inference (ResNet50)/training (VGG16)", "5x reduction in ADC energy consumption vs. baseline due to 4-bit vs 8-bit ADC resolution", "43% area reduction at iso-RRAM-capacity (47.914 mm^2 vs 84.088 mm^2, Table V)", "Under sigma=0.05 Gaussian noise on weights, accuracy drops to 15.17% for the WS-like noisy-weight case vs. 85.59% retained accuracy for the noisy-activation (INCA-representative) case"], "limitations": ["Pure simulation (circuit simulation of the 2T1R cell in TSMC 65nm scaled to accelerator-level technology node, plus a customized NeuroSim+-based system simulator); no fabricated macro or chip", "RRAM endurance under frequent activation rewriting is explicitly left as a known open problem ('Future Work for Endurance' section) rather than solved", "Accuracy/noise study uses a generic zero-centered Gaussian noise model rather than a device-calibrated nonideality model, and only evaluates ResNet18", "3D architecture assumes feasibility of 16x16 pillar interconnect fan-out and vertical plane stacking that has not been experimentally demonstrated at the scales simulated", "Comparison baseline (ISAAC-like WS 2D crossbar with PipeLayer training) is itself a simulated baseline, not independently re-verified hardware"], "remarks": "INCA's central insight -- that forcing all prior RRAM PIM designs into a default weight-stationary dataflow has architectural costs that an input-stationary alternative can avoid -- is a genuine mapping/dataflow contribution rather than just another crossbar variant, and the noise-robustness argument (activations get rewritten and refreshed, so persistent-weight-style degradation does not accumulate) is a useful reframing of reliability for mapping research. However, the claims rest entirely on simulation stacked on simulation (physical 2T1R layout scaled into a modified NeuroSim+ model), the RRAM endurance cost of constantly rewriting activation cells is acknowledged as unresolved, and the noise study is a coarse proxy rather than a rigorous device model, so the magnitude of the robustness and efficiency gains should be treated as an upper-bound estimate pending hardware validation.", "basis": "full-text", "pdf_source_url": "", "abstract": "This paper first presents an input-stationary (IS) implemented crossbar accelerator (INCA), supporting inference and training for deep neural networks (DNNs). Processing-in-memory (PIM) accelerators for DNNs have been actively researched, specifically, with resistive random-access memory (RRAM), due to RRAM’s computing and memorizing capabilities and device merits. To the best of our knowledge, all previous PIM accelerators have saved weights into RRAMs and inputs (activations) into conventional memories—it naturally forms weight-stationary (WS) dataflow. WS has generally been considered the most optimized choice for high parallelism and data reuse. How-ever, WS-based PIM accelerators show fundamental limitations: first, remaining high dependency on DRAM and buffers for fetching and saving inputs (activations); second, a remarkable number of extra RRAMs for transposed weights and additional computational intermediates in training; third, coarse-grained arrays demanding high-bit analog-to-digital converters (ADCs) and introducing poor utilization in depthwise and pointwise convolution; last, degraded accuracy due to its sensitivity to weights which are affected by RRAM’s nonideality. On the other hand, we observe that IS dataflow, where RRAMs retain inputs (activations), can effectively address the limitations of WS, because of low dependency by only loading weights, no need for extra RRAMs, feasibility of fine-grained accelerator design, and less impact of input (activation) variance on accuracy. But IS dataflow is hardly achievable by the existing crossbar structure because it is difficult to implement kernel sliding and preserve the high parallelism. To support kernel movement, we constitute a cell structure with two-transistor-one-RRAM (2T1R). Based on the 2T1R cell, we design a novel three-dimensional (3D) architecture for high parallelism in batch training. Our experiment results prove the potential of INCA. Compared to the WS accelerator, INCA achieves up to 20.6× and 260× energy efficiency improvement in inference and training, respectively; 4.8× (inference) and 18.6× (training) speedup as well. While accuracy in WS drops to 15% in our high-noise simulation, INCA presents an even more robust result as 86% accuracy.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Kim_INCA_HPCA.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2023_Kim_INCA_HPCA.pdf", "priority": 5.02}, {"id": "W4386763580", "short": "PIMCOMP", "title": "PIMCOMP: A Universal Compilation Framework for Crossbar-based PIM DNN Accelerators", "authors": ["Xiaotian Sun", "Xinyu Wang", "Wanqian Li", "Lei Wang", "Yinhe Han", "Xiaoming Chen"], "year": 2023, "venue": "", "venue_short": "DAC", "venue_full": "60th ACM/IEEE Design Automation Conference (DAC 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/dac56929.2023.10247928", "cites_global": 19, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "VGG", "ResNet", "GoogLeNet", "Inception-v3", "SqueezeNet"], "evidence": "simulation", "tldr": "PIMCOMP is a four-stage compiler (node partitioning, weight replicating, core mapping, dataflow scheduling) for NVM-crossbar PIM accelerators that uses a genetic algorithm for replication+mapping and achieves 1.6x throughput and 2.4x latency gains over a PUMA-like compiler.", "summary": "The paper argues that existing crossbar PIM accelerators rely on manual weight mapping and heuristic weight replication, and that PUMA's compiler only pipelines at inference granularity. PIMCOMP defines an abstract accelerator (cores with a PIM Matrix Unit of crossbars, a vector functional unit and local scratchpad, connected to global memory), compatible with ISAAC's Crossbar/IMA/Tile/Chip hierarchy. Conv/FC weights are unrolled into a (kh*kw*Cin) x Cout matrix and cut into Array Groups (AGs) of crossbar-height rows spanning all output columns; a genetic algorithm (mutation only, fitness = estimated per-core time) jointly selects per-layer replication counts and AG-to-core assignment. Two scheduling modes are supported: High-Throughput (layer-by-layer, inter-inference pipelining) and Low-Latency (fine-grained inter-layer pipelining when enough input rows are available), plus AG-level on-chip memory reuse. Evaluated with a cycle-accurate simulator on a PUMA-parameterised ReRAM chip (2-bit cells, 16-bit data) across VGG16, ResNet18, GoogLeNet, Inception-v3 and SqueezeNet, it gives 1.6x throughput and 2.4x latency improvement over a faithfully re-implemented PUMA-like dataflow.", "contributions": ["Generic abstract NVM-crossbar PIM accelerator template (core = PIMMU + VFU + local memory) and an execution model capturing structural conflicts and data dependencies of MVMs.", "Four-stage compilation flow: node partitioning into Array Groups, weight replicating, core mapping, dataflow scheduling.", "Genetic algorithm jointly optimising weight replication and core mapping with separate fitness functions for HT and LL modes.", "Scheduling algorithms for complex topologies (concat, eltwise) with ADD-reuse / AG-reuse on-chip memory optimisation."], "claims": [{"claim": "PIMCOMP outperforms a PUMA-like compiler in both throughput and latency.", "support": "1.6x throughput and 2.4x latency improvement relative to PUMA on average.", "loc": "Sec. V-B1, Fig. 8"}, {"claim": "Gains are largest for compute-heavy networks and shrink as on-chip parallelism grows.", "support": "VGG16 up to 3.9x (HT) and 4.9x (LL); GoogLeNet/SqueezeNet gains limited in HT because global-memory and vector ops dominate.", "loc": "Sec. V-B1, Fig. 8"}, {"claim": "In LL mode, balanced replication reduces static energy substantially.", "support": "PIMCOMP reduces static energy by 58.3% by reducing overall runtime in LL mode; dynamic energy is close to PUMA.", "loc": "Sec. V-B2, Fig. 9"}, {"claim": "AG-reuse memory optimisation cuts global memory traffic.", "support": "Global memory access reduced by an average 47.8% vs naive in HT mode; LL local memory usage kept within 64 kB.", "loc": "Sec. V-B3, Fig. 10"}, {"claim": "Compilation time is practical.", "support": "Total compile time 8.5-40.2 s across benchmarks (GA population 100, 200 iterations).", "loc": "Table II"}], "results": ["1.6x throughput (HT) and 2.4x latency (LL) improvement vs PUMA-like dataflow on average.", "VGG16: up to 3.9x normalized throughput (HT) and 4.9x speed (LL) vs PUMA-like at low parallelism.", "58.3% static-energy reduction in LL mode; HT mode total energy ~equal to PUMA (0.97-1.06x).", "47.8% average reduction in global memory accesses with AG-reuse (HT mode).", "Compile time 8.48-40.21 s per network."], "limitations": ["Evaluation only by the authors' own cycle-accurate simulator with PUMA parameters; no silicon or third-party simulator validation.", "Analog non-idealities, ADC precision and accuracy effects are ignored; the PIM matrix unit is treated as an ideal MVM with fixed latency.", "Only CNNs evaluated; no transformers/LLMs and all weights assumed to fit on chip (no weight reloading).", "Baseline is a re-implementation of PUMA's heuristic, including an LL mode that PUMA itself does not support."], "remarks": "A compact and influential DAC paper that framed crossbar compilation as replication + mapping + scheduling and introduced the Array Group abstraction now reused in several follow-ups (PIMCOMP TCAD 2024, COMPASS, CMSwitch, PIMapping). The evidence is simulation-only and treats crossbars as ideal digital-like MVM engines, so it says nothing about accuracy under analog noise. Its key insight for mapping is that weight replication should be optimised jointly with core placement and pipeline granularity rather than set to balance layer latencies heuristically. COMPASS later challenged its assumption that all weights fit on-chip.", "basis": "full-text", "pdf_source_url": "", "abstract": "Crossbar-based PIM DNN accelerators can provide massively parallel in-situ operations. A specifically designed compiler is important to achieve high performance for a wide variety of DNN workloads. However, some key compilation issues such as parallelism considerations, weight replication selection, and array mapping methods have not been solved. In this work, we propose PIMCOMP - a universal compilation framework for NVM crossbar-based PIM DNN accelerators. PIMCOMP is built on an abstract PIM accelerator architecture, which is compatible with the widely used Crossbar/IMA/Tile/Chip hierarchy. On this basis, we propose four general compilation stages for crossbar-based PIM accelerators: node partitioning, weight replicating, core mapping, and dataflow scheduling. We design two compilation modes with different inter-layer pipeline granularities to support high-throughput and low-latency application scenarios, respectively. Our experimental results show that PIMCMOP yields improvements of 1.6× and 2.4× in throughput and latency, respectively, relative to PUMA.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Sun_PIMCOMP_DAC.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2023_Sun_PIMCOMP_DAC.pdf", "priority": 7.44}, {"id": "W4361857408", "short": "Gibbon", "title": "Gibbon: An Efficient Co-Exploration Framework of NN Model and Processing-In-Memory Architecture", "authors": ["Hanbo Sun", "Zhenhua Zhu", "Chenyu Wang", "Xuefei Ning", "Guohao Dai", "Huazhong Yang", "Yu Wang"], "year": 2023, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2023.3262201", "cites_global": 12, "cat": "05", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "Gibbon is a neural-architecture-and-PIM-hardware co-exploration framework that uses an evolutionary search with adaptive parameter priority (ESAPP) plus an RNN performance predictor to jointly search NN topology/quantization and crossbar/ADC/DAC hardware configs, finding better accuracy-EDP-area tradeoffs than prior co-exploration methods in only ~6 GPU-hours.", "summary": "Memristor-based PIM accelerators intersect NN hyperparameters (depth, kernel size, quantization) with PIM hardware hyperparameters (crossbar size, ADC/DAC resolution, device precision), so optimizing either alone is suboptimal, but the combined search space is astronomically large (up to ~4.3x10^84 configurations) and each candidate's evaluation requires a slow cycle-accurate PIM simulator. Gibbon addresses this with three components: (1) a PIM-oriented search space that is the Cartesian product of an NN structure search space (DAG topology plus per-operation quantization) and a PIM hardware search space built on the MultiPrecision crossbar architecture (crossbar size, ADC/DAC resolution, memristor precision, activated word/bit lines); (2) an evolutionary search algorithm with adaptive parameter priority (ESAPP) that mutates candidates according to learned priorities over hyperparameters and uses an RNN-based performance predictor to filter ~95% of sampled candidates before invoking the expensive simulator; and (3) a multi-level joint simulator (built on MNSIM 2.0) used to generate ground-truth accuracy/EDP/area labels that fine-tune the predictor. Evaluated on CIFAR-10/100 against NACIM, UAE, NAS4RRAM and vanilla CARS, Gibbon improves PIM-based NN accuracy by 4.6-15.3% with 9.8-48.2x faster search (about six GPU-hours total), and against manually designed networks (AlexNet, VGG16/VGGM, ResNet18) it reduces EDP by 1.46-234.1x or area by 5.47-36.5x depending on optimization target, at comparable or better accuracy.", "contributions": ["A PIM-oriented joint search space combining NN DAG topology + per-operation weight/activation quantization with PIM hardware hyperparameters (crossbar size, ADC/DAC resolution, memristor precision, word/bit-line activation)", "ESAPP: an evolutionary search algorithm that adaptively prioritizes which hyperparameters to mutate based on their observed impact on performance", "An RNN-based performance predictor that filters out ~95% of sampled candidates before expensive simulation, built on top of MNSIM 2.0 as the accurate (but slow) PIM simulator", "A multi-level joint simulator design that keeps the predictor fine-tuned using sparse ground-truth simulator evaluations", "Demonstrated 9.8-48.2x faster co-exploration and better accuracy/EDP/area Pareto points than NACIM, UAE, NAS4RRAM and vanilla CARS on CIFAR-10/100"], "claims": [{"claim": "The joint NN+PIM co-exploration search space is far too large for manual or naive search", "support": "search space size reaches 4.3 x 10^84 after including PIM architecture design hyperparameters (vs. 3.3 x 10^54 for NN topology alone)", "loc": "Sec. IV, quoted text"}, {"claim": "Gibbon finds higher-accuracy PIM-based designs than prior NN/PIM co-exploration methods, much faster", "support": "4.6-15.3% PIM-based NN accuracy improvement over NACIM/UAE/NAS4RRAM with 9.8-48.2x search speedup, in about six GPU-hours", "loc": "Sec. VII.B"}, {"claim": "ESAPP and the RNN predictor substantially speed up search versus a vanilla evolutionary co-exploration baseline (CARS) without sacrificing quality", "support": "12x co-exploration speedup vs. vanilla CARS with better co-exploration performance", "loc": "Sec. VII.B"}, {"claim": "Gibbon's EDP-optimized configuration achieves large energy-delay-product reduction with simultaneous accuracy improvement over an existing co-design baseline", "support": "5.96x EDP reduction with 9.5% accuracy improvement compared with existing work", "loc": "Sec. VII.B, Abstract"}, {"claim": "Compared to manually designed networks (AlexNet, VGG16, VGGM, ResNet18), Gibbon finds much more hardware-efficient PIM-mapped networks at comparable accuracy", "support": "EDP reduced 1.46-234.1x (EDP-opt) and area reduced 5.47-36.5x (area-opt) across CIFAR-10/100; accuracy-opt configuration achieves 14.1x EDP and 5.12x area reduction on average at comparable accuracy", "loc": "Sec. VII.B, Tables IV-V"}], "results": ["4.6-15.3% PIM-based NN accuracy improvement over NACIM/UAE/NAS4RRAM baselines", "9.8-48.2x faster co-exploration search than prior PIM-oriented NAS methods; converges in ~6 GPU-hours", "12x speedup over vanilla CARS co-exploration with the proposed ESAPP + predictor", "5.96x EDP reduction with 9.5% accuracy improvement vs. existing co-design work", "Up to 234.1x EDP reduction and 36.5x area reduction vs. manually designed networks (AlexNet/VGG/ResNet18) on CIFAR-10/100"], "limitations": ["Evaluated only on CIFAR-10/CIFAR-100 (small, low-resolution image classification), not ImageNet-scale or non-vision workloads", "Relies on MNSIM 2.0 as the ground-truth PIM simulator, so absolute accuracy/EDP/area numbers inherit that simulator's modeling assumptions and non-ideality handling", "Uses only 1-bit and 2-bit memristor precision ('most mature'), limiting exploration of higher-precision analog storage", "Hardware search space is restricted to the MultiPrecision crossbar architecture template rather than a fully open architecture space", "No silicon validation; all accuracy/EDP/area results are simulator-predicted"], "remarks": "Gibbon sits squarely in the mapping/co-design literature that treats NN architecture and PIM hardware configuration as a joint search problem rather than optimizing either independently, and its predictor-filtered evolutionary search is a reasonable answer to the combinatorial explosion (4.3x10^84) that this joint space creates. The gains are reported entirely relative to other PIM-oriented NAS baselines and MNSIM-simulated hardware, so the work's contribution is primarily in search efficiency and the quality of the discovered configurations within that simulated space, not in new device or circuit evidence. The abstract's accuracy/EDP numbers are not independently reproduced here against hardware, and the framework is a natural companion to the MNSIM 2.0 simulator it builds on (also in this collection).", "basis": "full-text", "pdf_source_url": "", "abstract": "The memristor-based Processing-In-Memory (PIM) architectures have been proven to be a potential architecture to store enormous parameters and execute the complicated computations of Deep Neural Networks (DNNs) efficiently. Existing PIM studies focus on designing high energy-efficient hardware architecture and algorithm-hardware co-optimization for better performance. However, the impacts of the algorithms and hardware architectures on the performance intersect with each other. Only optimizing the algorithms or the hardware architectures can not realize the optimal design. Therefore, the co-exploration of NN models and PIM architecture is necessary. However, for one thing, the co-exploration space size of NN models and PIM architectures is extremely huge, and is challenging to search. For another, during the co-exploration process, time-consuming PIM simulators are needed to evaluate various design candidates and pose a heavy time burden. To tackle these problems, we propose an efficient co-exploration framework of NN models and PIM architectures, named . In, the co-exploration space is carefully designed to adapt both NN models and PIM architectures. Besides, in order to improve search efficiency, we propose an evolutionary search algorithm with adaptive parameter priority (ESAPP). In addition, introduces a multi-level joint simulator to alleviate the problem of time-consuming evaluation. The experimental results show that the proposed co-exploration framework can find better NN models and PIM architectures than existing studies in only six GPU hours (9.8 48.2× speedup). At the same time, can improve the accuracy of co-design results by 15.3% and reduce the energy-delay-product (EDP) by 5.96× compared with existing work.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Sun_Gibbon_TCAD.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2023_Sun_Gibbon_TCAD.pdf", "priority": 6.21}, {"id": "W4388052862", "short": "IMC PE-Level Mapping Benchmark", "title": "Benchmarking DNN Mapping Methods for the in-Memory Computing Accelerators", "authors": ["Yi‐Min Wang", "Xuanyao Fong"], "year": 2023, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2023.3328864", "cites_global": 11, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "A systematic loop-unrolling-based taxonomy of processing-element-level DNN-to-crossbar mapping methods, paired with a mapping-oriented architecture and benchmarking framework, shows large design-space tradeoffs and finds a hybrid mapping scheme improves minimum execution time by up to 30% across public DNN benchmarks.", "summary": "While many works study which-layer-to-which-core (tile-level) mapping for in-memory computing accelerators, PE-level mapping (how a convolution's loops are unrolled onto a crossbar's rows/columns) had not been systematically studied for IMC. This paper categorizes PE-level mapping methods from a loop-unrolling perspective, analyzing their implications for input data reuse and output (partial-sum) data reduction. It then proposes a mapping-oriented PE architecture whose input/output datapaths are designed to support the various mapping methods, evaluated at 45nm technology for area efficiency and scalability. An accompanying evaluation framework captures architecture-level behavior to benchmark mapping methods across different DNN workloads, main-memory bandwidth, and digital-compute throughput assumptions. The benchmarking reveals significant design-space tradeoffs between mapping choices and that no single mapping method is best across all conditions, motivating a hybrid-mapping scheme that switches mapping strategy to minimize execution time, improving it by up to 30% over the best single static mapping method across public DNN benchmarks.", "contributions": ["A loop-unrolling-based taxonomy of PE-level (within-crossbar) DNN mapping methods for in-memory computing, analyzed for input reuse and output reduction implications", "A mapping-oriented PE architecture with input/output datapaths designed to flexibly support multiple mapping methods, evaluated at 45nm for area efficiency/scalability", "An evaluation/benchmarking framework spanning DNN workloads, memory bandwidth, and digital-compute throughput to quantify mapping-method tradeoffs", "A hybrid-mapping scheme combining multiple PE-level mapping strategies, improving minimum execution time by up to 30% over public DNN benchmarks"], "claims": [{"claim": "No single static PE-level mapping method is best across all workloads/conditions; a hybrid-mapping scheme improves execution time", "support": "hybrid-mapping scheme enhances minimum execution time by up to 30% for the publicly available DNN benchmarks", "loc": "Abstract"}], "results": ["Up to 30% improvement in minimum execution time from hybrid mapping vs. single-mapping-method baselines across public DNN benchmarks", "Mapping-oriented PE architecture evaluated at 45nm technology shows good area efficiency and scalability"], "limitations": ["Analysis based on abstract only (full text not accessible); the specific loop-unrolling taxonomy, benchmark networks, and quantitative tradeoff curves could not be verified", "45nm technology node evaluation is relatively old relative to modern IMC chip demonstrations (e.g., 14nm PCM chips), which may limit direct comparability to state-of-the-art accelerators"], "remarks": "This is a mapping/dataflow-focused systematization paper that fills a specific gap (PE-level, i.e., intra-crossbar loop-unrolling mapping) distinct from tile-/layer-level mapping studied elsewhere (e.g., AERO, Xbar-Partitioning in the same in-set reference list). It has already attracted forward citations from DNN-to-PIM compiler frameworks (PIMCOMP, PIMapping, JADE), indicating it is being used as a reference taxonomy for mapping-space exploration; full-text access would help confirm how its loop-unrolling categories map onto commonly used crossbar dataflow terms (weight-stationary, output-stationary, etc.).", "basis": "abstract-only", "pdf_source_url": "", "abstract": "This paper presents a study of methods for mapping the convolutional workloads in deep neural networks (DNNs) onto the computing hardware in the in-memory computing (IMC) architecture. Specifically, we focus on categorizing and benchmarking the processing element (PE)-level mapping methods, which have not been investigated in detail for IMC-based architectures. First, we categorize the PE-level mapping methods from the loop unrolling perspective and discuss the corresponding implications on input data reuse and output data reduction. Then, a mapping-oriented architecture is proposed by considering the input and output datapaths under various mapping methods. The architecture is evaluated on the 45 nm technology showing good area-efficiency and scalability, providing a hardware substrate for further performance improvements via PE-level mappings. Furthermore, we present an evaluation framework that captures the architecture behaviors and enables extensive benchmarking of mapping methods under various neural network workloads, main memory bandwidth, and digital computing throughput. The benchmarking results demonstrate significant tradeoffs in the design space and unlock new design possibilities. We present case studies to showcase preferred mapping methods for best energy consumption and/or execution time and demonstrate that a hybrid-mapping scheme enhances minimum execution time by up to 30% for the publicly-available DNN benchmarks.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Wang_IMCPELevelMappingBenchmark_JETCAS.pdf", "analysed": true, "pdf": null, "priority": 6.56}, {"id": "W4388893898", "short": "Multi-core CNN Mapping", "title": "Mapping of CNNs on multi-core RRAM-based CIM architectures", "authors": ["Rebecca Pelke", "Nils Bosbach", "Jose Cubero", "Felix Staudigl", "Rainer Leupers", "Jan Moritz Joseph"], "year": 2023, "venue": "", "venue_short": "VLSI-SoC", "venue_full": "31st IFIP/IEEE International Conference on Very Large Scale Integration (VLSI-SoC 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/vlsi-soc57769.2023.10321873", "cites_global": 9, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "MobileNet", "ResNet"], "evidence": "simulation", "tldr": "Proposes decentralized, register-based (sequence-number CALL/WAIT) synchronization so that a conv layer split across many RRAM CIM cores can accumulate partial sums in parallel, reaching >99% of the theoretical speedup with <4% extra bus traffic.", "summary": "When a conv2D layer's im2col weight matrix is split across multiple RRAM crossbar cores, cores that produce partial sums for the same output vectors (same horizontal group) create race conditions on the shared OFM buffer; prior work either serialises them or uses PUMA's memory-heavy attribute buffer. The authors give each CIM core a single sequence-number register that other cores can increment (CALL) and that the owner can block on (WAIT), and compile conv layers with linear or cyclic ownership-passing schedules over output vectors. A Python compiler generates per-core code from TensorFlow models for a SystemC/TLM-2.0 multi-core architecture with an AXI4 bus and shared memory. On MobileNet and ResNet-18 conv layers with 32x32-128x128 crossbars and 4-64 B buses, the schemes reach the upper-bound speedup PV (up to 16x vs sequential) when the bus is wide enough, and quantify how many cores a given bus width can feed.", "contributions": ["Decentralized, event-based inter-core synchronization using one sequence-number register per CIM core (CALL/WAIT instructions).", "Linear and cyclic synchronization schemes for partial-sum accumulation of im2col-split conv layers, with analytic CALL/WAIT counts.", "Python compiler for TensorFlow conv2D/dense layers targeting a configurable multi-core RRAM CIM architecture.", "SystemC/TLM-2.0 approximately-timed simulator with AXI4 interconnect for design-space exploration of bus width, crossbar size and core count."], "claims": [{"claim": "Parallel synchronization nearly attains the theoretical speedup limit.", "support": "More than 99% of the theoretical acceleration limit for conv2D layers; highest speedup 16x for MobileNet layer 5.", "loc": "Abstract, Sec. V-B, Fig. 5"}, {"claim": "Synchronization traffic overhead is marginal.", "support": "CALL-traffic overhead <4% with 32x32, <2% with 64x64, <1% with 128x128 crossbars.", "loc": "Sec. V-E, Fig. 7"}, {"claim": "The approach needs far less synchronization memory than PUMA's attribute buffer.", "support": "Saves at least 87.5% of synchronization memory (4 kB for 1024 cores vs 32K attributes per 64 kB in PUMA).", "loc": "Sec. V-D"}, {"claim": "Bus width bounds how many cores are worth using.", "support": "4 B bus: max ~16 cores for >90% of speedup limit; 64 B bus: up to 512 cores; halving crossbar dimension needs at least doubled bus width.", "loc": "Sec. V-C, Fig. 6"}], "results": [">99% of theoretical speedup limit (PV) for MobileNet/ResNet-18 conv2D layers with sufficient bus width.", "Up to 16x speedup vs sequential synchronization (MobileNet layer 5).", "Shrinking crossbars 64x64 -> 32x32 gives at most 2x extra speedup but needs up to 4x more cores.", "Bus-traffic overhead of CALLs <4% (32x32), <2% (64x64), <1% (128x128).", ">=87.5% synchronization-memory saving vs PUMA's central scheme."], "limitations": ["Only single conv2D/dense layers are evaluated; inter-layer dependencies and full-network pipelining are left to future work.", "Accuracy, analog non-idealities and ADC effects are not modelled (crossbars treated as ideal MVM units).", "No energy or area evaluation beyond synchronization-register memory; results are latency/traffic from a TLM simulator.", "Uses only the dense im2col mapping; weight replication is not considered."], "remarks": "A narrow but clean systems contribution: it isolates the intra-layer partial-sum synchronization problem that most crossbar compilers (e.g., PUMA, PIMCOMP) handle implicitly, and shows that cheap per-core registers suffice when the bus is not the bottleneck. Evidence is a SystemC simulator only, and the per-layer scope means it complements rather than competes with full-network compilers. Useful for a thesis as a reference for bus-width vs core-count sizing when splitting large layers over small crossbars.", "basis": "full-text", "pdf_source_url": "", "abstract": "Resistive random access memory (RRAM)-based multi-core systems improve the energy efficiency and performance of convolutional neural networks (CNNs). Thereby, the distributed parallel execution of convolutional layers causes critical data dependencies that limit the potential speedup. This paper presents synchronization techniques for parallel inference of convolutional layers on RRAM-based computing-in-memory (CIM) architectures. We propose an architecture optimization that enables efficient data exchange and discuss the impact of different architecture setups on the performance. The corresponding compiler algorithms are optimized for high speedup and low memory consumption during CNN inference. We achieve more than 99 % of the theoretical acceleration limit with a marginal data transmission overhead of less than 4 % for state-of-the-art CNN benchmarks.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Pelke_MultiCoreCNNMapping_VLSI-SoC.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2023_Pelke_MultiCoreCNNMapping_VLSI-SoC.pdf", "priority": 4.7}, {"id": "W4389166698", "short": "ARES", "title": "ARES: A Mapping Framework of DNNs Towards Diverse PIMs with General Abstractions", "authors": ["Xiuping Cui", "Size Zheng", "Tianyu Jia", "Le Ye", "Yun Liang"], "year": 2023, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad57390.2023.10323777", "cites_global": 3, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "ARES is a general mapping framework for deploying DNNs on diverse processing-in-memory (PIM) architectures using a hardware-abstraction and mapping-space-search approach, reported to give up to 70% speedup on single operators and 50% on whole networks versus prior mapping methods.", "summary": "The paper targets the fragmentation problem in PIM mapping tools: existing DNN-to-PIM mapping approaches are hand-tailored to a specific accelerator architecture and do not generalize across the diversity of PIM memory types, compute functions, and memory-mapping constraints seen across recent designs (e.g., ReRAM crossbar accelerators like PipeLayer, PUMA, ISAAC, PRIME). ARES introduces a hardware abstraction that represents DNN computation on PIM as a tensorized compute function together with data-layout constraints imposed by the memory array, and uses this abstraction to build a unified mapping space spanning both compute and memory constraints. The framework then explores this mapping space to automatically derive efficient, architecture-specific mapping strategies without requiring per-architecture hand engineering. The authors evaluate ARES across four distinct PIM hardware configurations and compare against state-of-the-art mapping methods, reporting speed improvements for both individual operator mapping and full-network mapping.", "contributions": ["Proposes a general hardware abstraction for PIM architectures expressing DNN computation as a tensorized compute function plus array data-layout constraints", "Builds a unified mapping space covering both compute scheduling and memory/array placement constraints from this abstraction", "Provides a mapping-space exploration/search procedure that derives efficient, hardware-specific mapping strategies automatically rather than via per-architecture hand design", "Evaluates the framework across four distinct PIM hardware architectures to demonstrate generality", "Reports speedups over state-of-the-art, architecture-specific mapping methods for both single-operator and whole-network mapping"], "claims": [{"claim": "ARES achieves up to 70% speed improvement for single operator mapping versus state-of-the-art mapping methods.", "support": "reported speedup figure in abstract", "loc": "Abstract"}, {"claim": "ARES achieves up to 50% speedup for overall network mapping versus state-of-the-art mapping methods.", "support": "reported speedup figure in abstract", "loc": "Abstract"}, {"claim": "A single general hardware-abstraction-based mapping framework can be applied across architecturally diverse PIM hardware without per-architecture redesign.", "support": "evaluation across four distinct hardware architectures", "loc": "Abstract / evaluation section (not verified in full text)"}], "results": ["Up to 70% speedup for single-operator mapping vs. state-of-the-art mapping methods (abstract)", "Up to 50% speedup for overall network mapping vs. state-of-the-art mapping methods (abstract)", "Evaluated across four distinct PIM hardware architectures (abstract; specific architectures not confirmed from full text)"], "limitations": ["Full text was not available for this analysis; numbers above are taken verbatim from the abstract only, not independently verified against tables/figures", "Abstract does not specify which four hardware architectures were used, exact baselines compared against, or whether results are simulation-only", "No device-level or non-ideality modeling is evident from the abstract; this appears to be a compiler/dataflow-mapping contribution orthogonal to analog device accuracy concerns"], "remarks": "Positioned similarly to other general PIM mapping/compilation frameworks (e.g., CIM-MLC) in this collection, addressing the practical software-stack gap between diverse crossbar/PIM hardware and DNN deployment. Because only the abstract was available, the critical assessment here is necessarily shallow; the claimed 50-70% speedups should be read as reported by the authors and not independently checked. This is useful background for the mapping/compilation thread of the thesis but should be followed up with the full text (ICCAD 2023 proceedings) before relying on specific numbers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Numerous architectures based on processing-in-memory (PIM) have recently emerged, exhibiting diversity in memory types, compute functions, memory mapping constraints, etc. To effectively utilize PIM hardware for deploying deep neural networks (DNNs), programmers face the challenge of mapping computations and data across multiple memory arrays, scheduling computation and data transfers, while adhering to various hardware constraints. Existing mapping approaches, however, are tailored to specific architectures and lack a general formulation for mapping optimization, limiting their applicability and performance. In this paper, we present ARES, a comprehensive mapping framework designed for diverse PIM architectures. The core of the framework is hardware abstractions for PIMs, which is inspired by the fact that DNNs on PIM hardware can be represented by a tensorized compute function and data layout constraints in the memory array. This abstraction forms the basis for constructing a mapping space that encompasses both compute and memory constraints. Through exploration of this mapping space, we derive efficient mapping strategies tailored to different PIM hardware configurations. Experimental evaluation conducted on four distinct hardware architectures demonstrates that compared to state-of-the-art mapping methods, ARES yields up to a 70% speed improvement for single operator mapping and a 50% speedup for overall network mapping.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Cui_ARES_ICCAD.pdf", "analysed": true, "pdf": null, "priority": 5.32}, {"id": "W4385768723", "short": "Static Weight-Programming Scheduling", "title": "Static Scheduling of Weight Programming for DNN Acceleration with Resource Constrained PIM", "authors": ["Xin Qin Gao", "Hongyue Wang", "Yiyan Chen", "Yuhao Zhang", "Zhaoyan Shen", "Lei Ju"], "year": 2023, "venue": "ACM Transactions on Embedded Computing Systems", "venue_short": "TECS", "venue_full": "ACM Transactions on Embedded Computing Systems", "venue_ok": true, "doi": "https://doi.org/10.1145/3615657", "cites_global": 3, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "A static scheduling framework builds a ReRAM crossbar weight-programming latency model and searches for a weight-to-OU mapping plus operating-unit (OU) activation schedule that minimizes online weight-reprogramming overhead when a DNN's weights do not all fit in the crossbar simultaneously.", "summary": "Most ReRAM PIM accelerator studies assume a DNN's full weight set can be mapped into the crossbar at once, but limited crossbar resources mean that in practice, weights must be programmed into the array in multiple rounds during inference, incurring non-trivial runtime programming latency. This paper targets that gap: it builds a ReRAM crossbar programming-latency model that accounts jointly for DNN weight patterns, ReRAM programming (write) operation characteristics, and PIM architecture features. The model drives a search procedure that produces an optimized weight-to-operating-unit (OU) mapping table designed to minimize online (runtime) programming latency, i.e., a static schedule decided ahead of inference. An OU scheduler then coordinates the activation order of OUs within the crossbars at runtime to execute inference correctly given that mapping. Evaluated across multiple DNN models and datasets, the framework is reported to significantly reduce both weight-programming overhead and overall inference latency compared to baseline (presumably naive/ad hoc) scheduling.", "contributions": ["Identifies and targets the under-idealized assumption in prior ReRAM PIM work that all DNN weights can be mapped to the crossbar simultaneously", "A ReRAM crossbar programming-latency model jointly accounting for weight patterns, programming (RESET/SET) operation cost, and PIM architecture constraints", "A static scheduling/search framework producing a weight-to-operating-unit (OU) mapping table that minimizes online weight-programming latency", "An OU scheduler coordinating runtime activation order of operating units for correct inference execution under the resource-constrained mapping", "Demonstrated reduction in both programming overhead and overall inference latency across multiple DNNs and datasets"], "claims": [{"claim": "The proposed static scheduling framework significantly reduces weight-programming overhead and overall inference latency versus baseline approaches for resource-constrained ReRAM PIM", "support": "evaluation across various DNN models and datasets shows significant reduction in programming overhead and inference latency", "loc": "Abstract"}], "results": ["Significant reduction in weight-programming overhead across various DNN models/datasets (quantitative figures not given in abstract)", "Significant reduction in overall inference latency across various DNN models/datasets (quantitative figures not given in abstract)"], "limitations": ["Analysis based on abstract only (full text not accessible); exact speedup numbers, baseline definitions, and crossbar/OU sizing assumptions could not be verified", "The programming-latency model's fidelity to real ReRAM write characteristics (RESET/SET asymmetry, endurance, write-verify) is unclear without the full text"], "remarks": "This is a mapping/compilation-layer contribution addressing a frequently idealized assumption in crossbar accelerator literature (full-model-fits-at-once mapping), which matters directly for larger models that exceed available crossbar capacity and must be time-multiplexed with weight reprogramming. Because ReRAM writes are slow and wear-limited, minimizing runtime reprogramming via a static, pattern-aware schedule is a practically important idea for scaling crossbar accelerators beyond toy model sizes; full-text access would help assess how the latency model compares to measured ReRAM write timing in the literature (e.g., HERMES-Core, PCM write-latency studies).", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Most existing architectural studies on ReRAM-based processing-in-memory (PIM) DNN accelerators assume that all weights of the DNN can be mapped to the crossbar at once. However, these studies are over-idealized. ReRAM crossbar resources for calculation are limited because of technological limitations, so multiple weight mapping procedures are required during the inference process. In this article, we propose a static scheduling framework which generates the mapping between DNN weights and ReRAM cells with minimum runtime weight programming cost. We first build a ReRAM crossbar programming latency model by simultaneously considering the DNN weight patterns, ReRAM programming operations, and PIM architecture characteristics. Then, the model is used in the searching process to obtain an optimized weight-to-OU mapping table with minimum online programming latency. Finally, an OU scheduler is used to coordinate the activation sequences of OUs in the crossbars to perform the inference computation correctly. Evaluation results show the proposed framework significantly reduces the weight programming overhead and the overall inference latency for various DNN models with different input datasets.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Gao_StaticWeightProgScheduling_TECS.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2023_Gao_StaticWeightProgScheduling_TECS.pdf", "priority": 4.42}, {"id": "W4388210331", "short": "Crossbar Allocation Optimization", "title": "Mathematical Framework for Optimizing Crossbar Allocation for ReRAM-based CNN Accelerators", "authors": ["Wanqian Li", "Yinhe Han", "Xiaoming Chen"], "year": 2023, "venue": "ACM Transactions on Design Automation of Electronic Systems", "venue_short": "TODAES", "venue_full": "ACM Transactions on Design Automation of Electronic Systems (2023)", "venue_ok": true, "doi": "https://doi.org/10.1145/3631523", "cites_global": 2, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "analytical", "tldr": "The paper formulates ReRAM crossbar allocation across a CNN's layers as a constrained optimization problem and solves it with a dynamic-programming solver to find near-optimal numbers of duplicated crossbars per layer under crossbar-count and bandwidth constraints.", "summary": "ReRAM-based CNN accelerators duplicate crossbars per layer to exploit intra-layer parallelism, but under fixed resource budgets (total crossbars, memory bandwidth) finding the optimal number of crossbars to allocate to each layer so as to minimize end-to-end CNN inference time is an unsolved combinatorial problem. This paper models crossbar allocation mathematically as a constrained optimization problem and proposes a dynamic-programming-based solver to find a near-optimal allocation. The authors emphasize that communication (data access/movement between crossbars and buffers) must be modeled alongside compute throughput, since bandwidth constraints can dominate the achievable inference time in a way that is often neglected by designs that only optimize for raw crossbar throughput. Experiments reportedly show the model for CNN inference time is 'almost precise' (closely matches actual simulated/measured inference time) and that the DP-based framework obtains solutions close to optimal.", "contributions": ["A mathematical (constrained optimization) formulation of the crossbar-allocation problem for ReRAM-based CNN accelerators, covering per-layer crossbar counts under global crossbar-count and bandwidth budgets", "A dynamic-programming-based solver that finds near-optimal crossbar allocations", "An accurate CNN inference-time model validated to be 'almost precise' against ground truth", "Explicit incorporation of communication/bandwidth cost (not just compute parallelism) as a first-class factor in the allocation decision"], "claims": [{"claim": "The inference-time model used to drive the optimization is highly accurate", "support": "stated as 'almost precise' in experiments (abstract)", "loc": "Abstract"}, {"claim": "The DP-based solver obtains near-optimal crossbar allocation solutions", "support": "framework obtains solutions with near-optimal inference time (abstract)", "loc": "Abstract"}, {"claim": "Communication/data-access cost is an important factor that must be considered alongside crossbar count when allocating crossbars", "support": "authors explicitly emphasize this as a key finding distinguishing their approach", "loc": "Abstract"}], "results": ["Near-optimal CNN inference time achieved by the DP-based crossbar allocation solver relative to the formulated optimization problem (exact speedup/ratio numbers not available from abstract alone)"], "limitations": ["Abstract-only analysis in this record: full text not available, so the exact optimization formulation, DP state space, and quantitative comparison baselines could not be verified", "Being a mathematical/analytical optimization paper, the degree of validation against real hardware or cycle-accurate simulation is unclear from the abstract alone", "Only 2 citations recorded in this collection, suggesting limited uptake so far (paper is recent, 2023)"], "remarks": "This targets a genuinely under-addressed problem in crossbar accelerator design: most architecture papers (ISAAC, PRIME, PUMA, etc.) treat per-layer crossbar duplication/allocation heuristically, whereas this paper gives it a principled optimization formulation with a tractable DP solver and explicitly folds in bandwidth/communication cost, which is often the bottleneck in practice once compute is parallelized. Because only the abstract was available, the rigor of the optimality guarantees and the realism of the cost model versus actual accelerator simulators (e.g. PUMA, CASCADE, FORMS, all of which are in-set references) could not be independently assessed here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The resistive random-access memory (ReRAM) has widely been used to accelerate convolutional neural networks (CNNs) thanks to its analog in-memory computing capability. ReRAM crossbars not only store layers’ weights, but also perform in-situ matrix-vector multiplications which are core operations of CNNs. To boost the performance of ReRAM-based CNN accelerators, crossbars can be duplicated to explore more intra-layer parallelism. The crossbar allocation scheme can significantly influence both the computing throughput and bandwidth requirements of ReRAM-based CNN accelerators. Under the resource constraints (i.e., crossbars and memory bandwidths), how to find the optimal number of crossbars for each layer to maximize the inference performance for an entire CNN is an unsolved problem. In this work, we find the optimal crossbar allocation scheme by mathematically modeling the problem as a constrained optimization problem and solving it with a dynamic programming based solver. Experiments demonstrate that our model for CNN inference time is almost precise, and the proposed framework can obtain solutions with near-optimal inference time. We also emphasize that communication (i.e., data access) is an important factor and must also be considered when determining the optimal crossbar allocation scheme.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2023_Li_CrossbarAllocationOpt_TODAES.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2023_Li_CrossbarAllocationOpt_TODAES.pdf", "priority": 5.24}, {"id": "W4307927141", "short": "HW-aware Quant/Mapping for CIM", "title": "Hardware-aware Quantization/Mapping Strategies for Compute-in-Memory Accelerators", "authors": ["Shanshi Huang", "Hongwu Jiang", "Shimeng Yu"], "year": 2022, "venue": "ACM Transactions on Design Automation of Electronic Systems", "venue_short": "TODAES", "venue_full": "ACM Transactions on Design Automation of Electronic Systems", "venue_ok": true, "doi": "https://doi.org/10.1145/3569940", "cites_global": 12, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "A joint algorithm-hardware design-space exploration of quantization algorithms, data representations and ADC configurations for eNVM-based CIM accelerators finds that dynamic fixed-point quantization with 2's-complement/shifted-unsigned-INT representation and optimized-precision ADCs gives ~2x energy efficiency and 1.2-1.6x throughput with 5-25% less area than naive strategies.", "summary": "The paper addresses the lack of systematic, hardware-aware quantization/mapping guidance for mixed-signal compute-in-memory (CIM) accelerators built on emerging non-volatile memories (eNVM). Because quantization, data-representation and ADC-configuration choices interact strongly with circuit-level design (and improper choices can needlessly shrink the usable design space), the authors perform a joint algorithm-hardware design-space exploration comparing quantization algorithms, weight/activation data-representation methods, and ADC configurations at the system level. Using CIFAR-10/100 and ImageNet classification as evaluation workloads, they derive guidelines for chip architects on which combinations are most hardware-friendly. The recommended combination — dynamic fixed-point quantization with 2's-complement (or shifted unsigned INT) representation and optimized-precision ADCs — achieves roughly 2x energy efficiency and 1.2-1.6x throughput improvement with 5-25% reduced area overhead relative to a naive baseline (fixed-point quantization + differential-pair representation + full-precision ADC).", "contributions": ["Joint algorithm-hardware analysis comparing quantization algorithms, data representation methods and ADC configurations for CIM accelerators", "System-level hardware performance comparison across design options evaluated on CIFAR-10/100 and ImageNet", "Concrete design guidelines for chip architects on hardware-friendly quantization/mapping strategy combinations", "Quantified comparison of a recommended strategy against a naive baseline strategy showing energy, throughput and area tradeoffs"], "claims": [{"claim": "Dynamic fixed-point quantization + 2's complement/shifted-unsigned-INT representation + optimized-precision ADC outperforms a naive strategy", "support": "~2x energy efficiency and 1.2-1.6x throughput improvement with 5-25% reduced area overhead vs naive (fixed-point quant + differential-pair representation + full-precision ADC)", "loc": "Abstract"}], "results": ["~2x energy efficiency improvement for the recommended quantization/mapping strategy vs naive baseline (CIFAR-10/100, ImageNet)", "1.2x-1.6x throughput improvement for the recommended strategy vs naive baseline", "5%-25% reduced area overhead for the recommended strategy vs naive baseline"], "limitations": ["Analysis based on abstract only — full text not retrievable (ACM-paywalled; no arXiv preprint or other legitimate open copy found within the session's search budget), so the exact experimental setup, hardware model, and per-dataset breakdown of results could not be verified", "Design-space exploration is evaluated with image classification CNN benchmarks only (per abstract); applicability to other model types (transformers, RNNs) is not stated", "The study reports comparative energy/throughput/area ratios but the abstract does not specify ADC/device technology assumptions in enough detail to judge generality"], "remarks": "Full text could not be retrieved (ACM Digital Library is not downloadable from this environment; no open-access copy was found via arXiv or web search within the session's search budget), so this entry is abstract-only. The work is a natural companion to NeuroSim-style benchmarking frameworks (it cites DNN+NeuroSim and RaQu) and targets exactly the mapping/quantization co-design question central to this literature map; the reported ~2x energy-efficiency and throughput gains are plausible in magnitude for this class of study but could not be cross-checked against the authors' own tables/figures.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The emerging non-volatile memory (eNVM) based mixed-signal Compute-in-Memory (CIM) accelerators are of great interest in today's AI accelerators design due to their high energy efficiency. Various CIM architectures and circuit-level designs have been proposed, showing superior hardware performance for deep neural network (DNN) acceleration. However, hardware-aware quantization strategies for CIM-based accelerators are not systematically explored. Since there are a variety of design options for neural network mapping on CIM systems while improper strategies may narrow the circuit-level design space and further limit the hardware performance, it is important to make a comprehensive early-stage design space exploration and find appropriate quantization/mapping strategies to achieve better hardware performance. In this paper, we provide a joint algorithm-hardware analysis and compare the system-level hardware performance for various design options, including quantization algorithms, data representation methods and analog-to-digital converter (ADC) configurations. This work aims to propose guidelines for choosing more hardware-friendly design options for chip architects. According to our evaluation results for CIFAR-10/100 and ImageNet classification, the properly chosen quantization approach and optimal mapping strategy (dynamic fixed-point quantization + 2’s complement representation/shifted unsigned INT representation + optimized precision ADC) could achieve ∼2 × energy efficiency and 1.2 ∼ 1.6 × throughput with 5%∼25% reduced area overhead, compared to naïve strategy (fixed-point quantization + differential pair number representation + full precision ADC).", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2022_Huang_HWAwareQuantMappingCIM_TODAES.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2022_Huang_HWAwareQuantMappingCIM_TODAES.pdf", "priority": 6.21}, {"id": "W4285263226", "short": "AERO", "title": "AERO: Design Space Exploration Framework for Resource-Constrained CNN Mapping on Tile-Based Accelerators", "authors": ["Simei Yang", "Debjyoti Bhattacharjee", "Vinay Kumar", "S. Chatterjee", "Sayandip De", "Peter Debacker", "Diederik Verkest", "Arindam Mallik", "Francky Catthoor"], "year": 2022, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems (JETCAS), 2022", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2022.3171826", "cites_global": 11, "cat": "05", "seed": false, "devices": ["SRAM-analog", "Generic-NVM"], "models": ["MLP", "CNN", "ResNet"], "evidence": "simulation", "tldr": "AERO is a design-space-exploration framework that models hierarchical tile/PE/AIMC-level mapping of CNNs onto hybrid digital-analog multi-layer-parallel accelerators, finding weight-stationary mapping gives up to ~100x better power efficiency/throughput than weight-loading for MLPs and 1.6-3.4x for ResNets.", "summary": "The paper addresses the lack of fast, accurate DSE tools for multi-layer-parallel hybrid digital-analog accelerators (e.g. ISAAC/PUMA-style), where existing single-layer DSE tools (Timeloop, Interstellar, ZigZag) don't apply. AERO provides a hierarchical virtual-mapping (layer fusion/splitting) and physical-mapping (accelerator/cluster/tile/PE/AIMC level) flow plus a detailed PPA (performance-power-area) model covering digital and analog (AIMC) units, instruction memory and weight-loading overhead, under both sufficient-resource (SR) and limited-resource (LR) constraints. It is evaluated on a TANIA-style template architecture for MLP-3, LeNet-5 and ResNet-18/34/50/101 workloads with ternary weights, sweeping weight-loading vs weight-stationary mapping, weight memory bandwidth, SR vs LR constraints, AIMC array dimensions, and AIMC cell technology (SRAM vs IGZO vs SOT-MRAM). Results show weight-stationary mapping is far more energy/throughput efficient than weight-loading, that even moderate weight reuse (e.g. 16) gets within ~90% of weight-stationary efficiency, and that bandwidth gains saturate inference latency around 120 Bytes/cycle.", "contributions": ["Hierarchical Tile/PE-level mapping exploration supporting inter-layer interaction and layer fusion/splitting for multi-layer-parallel hybrid digital-analog accelerators", "DSE under both sufficient-resource and limited-resource (tile/PE-constrained) scenarios, unlike prior multi-layer-parallel mapping work which assumes unlimited resources", "Detailed PPA model spanning a broad range of hybrid digital + analog (AIMC) units, including instruction memory and weight-loading overhead often ignored by generic DSE tools", "Case studies quantifying the impact of weight loading vs weight-stationary mapping, external memory bandwidth, resource constraints, AIMC array dimensions, and AIMC cell technology (SRAM/IGZO/SOT-MRAM) on PPA"], "claims": [{"claim": "Weight-stationary (WS) mapping gives roughly 100x better power efficiency and performance than weight-loading (WL, #reuse=1) for MLP-3.", "support": "'Compared to WL mode (#reuse=1), WS mode (#reuse=inf) is ~100x better in power efficiency and performance.'", "loc": "Sec. V-C, Fig. 10"}, {"claim": "For CNN workloads (ResNet-18/34/50/101, LeNet-5), WS mode is 1.57x-3.21x better power efficiency and 1.19x-3.36x better throughput than WL mode.", "support": "Table VI: ratio WS/WL power efficiency 1.570-3.207x; pipeline throughput ratio 1.186-3.362x", "loc": "Sec. V-C, Table VI"}, {"claim": "Even low weight-reuse values (e.g. 16) achieve close to weight-stationary efficiency for ResNet-18 and ResNet-50.", "support": "'their power efficiency and pipeline throughput approaches up to 90% of WS mode (#reuse=inf) when #reuse=16'", "loc": "Sec. V-C"}, {"claim": "Inference latency gains from increasing weight bandwidth saturate around 120 Bytes/cycle for deep ResNets.", "support": "'latency saturates to a critical path, which happens around bandwidth of 120 Bytes/cycle'", "loc": "Sec. V-D, Fig. 11"}, {"claim": "Limited-resource weight-loading (LR-WL) offers an energy-area-performance trade-off: 18% higher latency, 15% higher power efficiency and 73% lower area than SR-WL.", "support": "'It has 18% higher latency than SR-WL, with 15% higher power efficiency and 73% lower area.'", "loc": "Sec. VI"}, {"claim": "Among SRAM, IGZO and SOT-MRAM AIMC cell technologies, SRAM has the lowest energy/latency in WL mode while IGZO has the best power/area efficiency in WS mode.", "support": "Sec VI bullet; Fig. 15 normalized energy/latency/power-efficiency/area-efficiency comparison", "loc": "Sec. VI, Fig. 15"}], "results": ["ResNet-18: WS mode gives 2.702x power efficiency and 1.585x throughput vs WL mode (Table VI)", "ResNet-101: WS mode gives 2.745x power efficiency and 3.362x throughput vs WL mode (Table VI)", "AIMC arrays dominate baseline architecture area at 46.6% of a 103.60 mm^2 4-cluster chip (Fig. 9)", "LR-WL vs SR-WS: close or up to 54% higher area efficiency for LR-WL (Sec. VI)", "Layer-splitting (Split 2_2) on first two layers reduces inference latency by up to 70% with <13.5% energy increase for LeNet-5/ResNets"], "limitations": ["Pure simulation / analytical PPA modeling study, no fabricated hardware or silicon measurements", "NoC-level latency estimation does not model communication contention", "Loop transformation exploration over the memory hierarchy is not supported", "Case studies use ternary weights only; other precision levels not explored", "Workloads limited to MLP-3, LeNet-5, and ResNet-18/34/50/101 (no transformer/LLM workloads)"], "remarks": "AERO is a mapping/DSE paper rather than a new accelerator or device result; its evidence is purely simulated PPA modeling built on an internal TANIA-style template, so absolute numbers (areas, TOPS/W) are architecture-specific and not independently verified against silicon. Its main value for analog crossbar mapping is methodological: it's one of few DSE frameworks that explicitly handles resource-constrained (not just resource-unlimited) multi-layer-parallel mapping and quantifies the weight-loading/weight-stationary trade-off space, which later benchmarking papers (e.g. 'Benchmarking DNN Mapping Methods for IMC Accelerators') build on and compare against.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog In-Memory Compute (AIMC) arrays can store weights and perform matrix-vector multiplication operations for Deep Convolutional Neural Networks (CNNs). A number of recent efforts have integrated AIMC arrays into hybrid digital-analog accelerators in a multi-layer parallel manner to achieve energy efficiency and high throughput. Multi-layer parallelism on large-scale tile-based architectures need efficient mapping support at the processing element (PE)-level (e.g., digital or analog processing elements) and tile-level. To find the most efficient architectures, fast and accurate design space exploration (DSE) support is required. In this paper, a novel DSE framework, AERO, is presented to characterize a CNN inference workload executing on hybrid tile-based architectures that supports multi-layer parallelism. Three characteristics can be seen in our DSE framework: (1) It presents a hierarchical Tile/PE-level mapping exploration strategy including inter-layer interaction, and allowing layer fusion/splitting configurations for PE-level mapping optimization. (2) It unlocks different Performance, Power and Area (PPA) exploration points under both sufficient and limited resource constraints, while limited resource case is not considered in prior works of multi-layer parallel architectures. The impact of weight loading and weight stationary mapping are analyzed for better insights into hybrid tile-based architectures. (3) It incorporates a detailed PPA model that supports a broad range of hybrid digital and analog units in a tile. Experimental case-studies are performed for realistic and relevant benchmarks such as MLP, CNNs (Lenet-5, Resnet-18,-34,-50 and −101).", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2022_Yang_AERO_JETCAS.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2022_Yang_AERO_JETCAS.pdf", "priority": 6.85}, {"id": "W4312542636", "short": "Coordinated Pruning-Mapping", "title": "A Coordinated Model Pruning and Mapping Framework for RRAM-Based DNN Accelerators", "authors": ["Songyun Qu", "Bing Li", "Shixin Zhao", "Lei Zhang", "Ying Wang"], "year": 2022, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2022.3221906", "cites_global": 9, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Jointly co-designs bit-wise pruning and crossbar mapping for RRAM DNN accelerators, using two's-complement bit-matrix decoupling and an RL-driven crossbar-granularity bit-pruning policy to free whole crossbars rather than leaving sparsity unexploited; reports up to 89.64% energy and 84.12% area reduction versus a PRIME-like baseline and 1.5x better energy reduction than SOTA bit-sparsity designs.", "summary": "RRAM-based DNN accelerators normally apply weight pruning and crossbar mapping as separate, independently-optimized steps, which leaves the random zeros produced by pruning irregularly scattered across crossbars so that computation parallelism is lost without any reduction in the number of crossbars actually needed. The paper proposes a coordinated framework that unifies pruning and mapping: weight matrices are decoupled bit-wise and mapped to separate crossbars, using two's-complement representation of signed weights to roughly halve the crossbars needed; pruning is then performed at crossbar granularity (pruning whole bit-slices rather than scattered individual weights) so that entire crossbars holding pruned bits can be physically freed rather than merely zeroed. A reinforcement-learning (RL) agent automatically searches for the optimal crossbar-aware bit-pruning policy per network, removing the need for hand-tuned pruning schedules. On a set of representative CNNs, the coordinated framework is compared against a PRIME-like architecture and against state-of-the-art bit-sparsity designs.", "contributions": ["Bit-wise decoupling of weight matrices with two's-complement signed representation to roughly halve the number of crossbars needed for weight storage", "Crossbar-granularity bit-pruning that prunes whole bit-slices so pruned crossbars can be physically freed (not just zeroed), recovering parallelism lost to irregular sparsity", "RL-based automatic search for the crossbar-aware bit-pruning strategy per network, avoiding manual tuning", "Joint pruning+mapping co-optimization framework evaluated against a PRIME-like baseline and SOTA bit-sparsity designs"], "claims": [{"claim": "Coordinating pruning and mapping (vs. optimizing them independently) substantially reduces energy and area on RRAM accelerators", "support": "up to 89.64% energy reduction and 84.12% area overhead reduction compared to existing PRIME-like architecture", "loc": "Abstract"}, {"claim": "The framework outperforms state-of-the-art bit-sparsity accelerator designs", "support": "1.5x better energy reduction than the SOTA bit-sparsity design on the RRAM-based accelerator", "loc": "Abstract"}], "results": ["Up to 89.64% energy reduction and 84.12% area overhead reduction vs. a PRIME-like RRAM accelerator baseline", "1.5x energy reduction improvement over the state-of-the-art bit-sparsity design"], "limitations": ["Abstract-only analysis: full text unavailable, so exact benchmark networks, accuracy impact of pruning, and RL search cost could not be verified", "Comparisons framed primarily against PRIME-like and bit-sparsity baselines; broader comparison against other mapping/compiler frameworks not stated in the abstract"], "remarks": "This addresses a real and under-appreciated mismatch in RRAM accelerator design flows: pruning algorithms and crossbar mapping are usually developed independently, so irregular sparsity patterns fail to reduce the actual crossbar count. The bit-slice/two's-complement decoupling plus RL-driven crossbar-granularity pruning is a sensible hardware-aware co-design approach consistent with other works by the same group (RaQu). Reported gains are large (near 90% energy/area reduction) but are abstract-only claims relative to a PRIME-like baseline, so the margin over more modern mapping frameworks is unclear without the full text; it was later cited by CIM-MLC as part of the broader compilation-stack literature for CIM accelerators.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Network sparsity or pruning is a pivotal technology for edge intelligence. Resistive random access memory (RRAM)-based accelerators, featuring dense storage and processing in memory capability, have demonstrated the superior computing performance and energy efficiency over the traditional CMOS-based accelerators for neural network applications. Unfortunately, RRAM-based accelerators suffer the performance or energy degradation when deploying pruned models, impairing their competition in the edge intelligence scenarios. We observed the essential reason is the pruning technology and the mapping strategy in prior RRAM-based accelerator and are optimized individually. As a result, the random zeros in the pruned deep neural network are irregularly distributed in the crossbars, rendering the degradation of computation parallelism of the crossbar without crossbar demand reduction. In this work, we propose a coordinated model pruning and mapping framework to jointly optimize of model accuracy and efficiency of RRAM-based accelerators. As for the mapping, we first decouple weight matrices in the bit-wise way and map the bit matrices to different crossbars, where the signed weights are represented with the two’s complement so as that save half desired crossbars. As for the pruning, we prune weight bits at the crossbar granularity so that free the crossbars holding the pruned bits. Furthermore, we employ an reinforcement learning (RL) approach to automatically select the optimal crossbar-aware bit-pruning strategy for any given neural network without laborious human efforts. We conducted the experiments on a set of representative neural networks and compared our framework with the state-of-the-art (SOTA) bit-sparsity works. The results show that automatic structured bit-pruning saves up to 89.64% energy reduction and 84.12% area overhead compared to existing PRIME-like architecture. Besides, our framework outperforms the SOTA bit-sparsity design by$1.5\\times $in terms of the energy reduction on the RRAM-based accelerator.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2022_Qu_CoordinatedPruningMapping_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.6}, {"id": "W3188508394", "short": "OCC", "title": "OCC: An Automated End-to-End Machine Learning Optimizing Compiler for Computing-In-Memory", "authors": ["Adam Siemieniuk", "Lorenzo Chelini", "Asif Ali Khan", "Jerónimo Castrillón", "Andi Drebes", "Henk Corporaal", "Tobias Grosser", "Martin Kong"], "year": 2021, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems, vol. 41, no. 6, pp. 1674-1686 (published online Aug. 2021, issue June 2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2021.3101464", "cites_global": 31, "cat": "05", "seed": false, "devices": ["PCM"], "models": ["MLP", "LSTM/RNN", "CNN", "WaveNet", "GEMM/tensor-contraction kernels"], "evidence": "simulation", "tldr": "OCC is an MLIR-based, multilevel-rewriting compiler that automatically detects GEMM-like motifs (contractions via TTGT, convolutions via Im2Col) in Tensor Comprehension code and lowers them to a PCM-crossbar co-processor runtime, giving up to 17x average speedup and 5.0x energy reduction over an ARM core in gem5.", "summary": "The paper targets the programmability gap of memristive CIM accelerators, where most prior work requires manual kernel mapping or rewriting against a hardware API. OCC enters MLIR at the Linalg dialect via the Teckyl Tensor-Comprehensions frontend, applies hardware-agnostic rewrites (TTGT for arbitrary tensor contractions, Im2Col for convolutions) so every motif becomes a GEMM, then lowers to a custom CIM dialect where hardware-specific passes tile GEMMs to the crossbar size, interchange loops to minimise crossbar writes, and unroll across tiles for parallelism, finally emitting calls to a CIM runtime library. Non-offloadable parts follow the normal CPU LLVM path. The target is a gem5 full-system SoC with an in-order ARM core and a memory-mapped 4-tile, 64x64, 8-bit (bit-sliced) PCM accelerator accessed by DMA. Across ML kernels (mm, mv, conv1/2/3d, MLP3, LSTM, WaveNet) and chemistry-style contractions, OCC offloads every expected kernel (matching an oracle where prior TDO-CIM/TC-CIM miss contractions), improves performance up to 17x and energy up to 5.0x on average vs the ARM baseline, while low-reuse or low-utilisation kernels (mv, lstm, conv2d, WaveNet) can be slower or costlier.", "contributions": ["First end-to-end CIM compilation flow built on MLIR multilevel IR rewriting, with a dedicated CIM dialect and runtime library (open-sourced as Open-CIM-Compiler)", "Hardware-agnostic Linalg passes that detect contractions (TTGT) and convolutions (Im2Col) and rewrite them as GEMMs", "Hardware-specific passes: crossbar-size tiling, loop interchange to cut crossbar writes (endurance), and loop unrolling across CIM tiles", "gem5 full-system evaluation of a PCM crossbar co-processor, including endurance/lifetime analysis and comparison against TDO-CIM and TC-CIM detection"], "claims": [{"claim": "Loop interchange substantially reduces crossbar writes and so improves both speed and endurance.", "support": "Interchange reduces the number of write operations to the crossbar by 7.4x; lifetime increased by almost two years assuming 3.2e7 endurance", "loc": "Sec. V-C, Sec. V-E, Fig. 11"}, {"claim": "Tiling plus parallelisation over CIM tiles yields the largest performance gains over the host CPU.", "support": "tile: 6.6x; tile+parallel: 15.5x; tile+parallel+interchange: 17x speedup vs ARM", "loc": "Sec. V-C, Fig. 8"}, {"claim": "CIM offload reduces energy on average but not for all kernels.", "support": "Average 1.9x-5.0x energy reduction; waveNet, conv2d, lstm and mv consume 60%, 30%, 10% and 40% more energy than ARM in the full-optimisation config", "loc": "Sec. V-D, Fig. 8"}, {"claim": "Progressive lowering makes motif detection more robust than loop-tactics-based compilers.", "support": "OCC matches the oracle callsite count on all benchmarks, while TDO-CIM and TC-CIM miss contractions and one matrix-vector op in mlp3 and waveNet", "loc": "Sec. V-F, Fig. 12"}, {"claim": "For small problem sizes crossbar programming cost dominates, but large GEMMs benefit massively.", "support": "Baseline 32% faster for small sizes; CIM up to 512x faster for large mm", "loc": "Sec. V-B, Fig. 7"}], "results": ["Up to 512x speedup vs in-order ARM core for large matrix multiplication (matrices fit in crossbar); 32% slower for small sizes", "Average speedups vs ARM: 6.6x (tile), 15.5x (tile+parallel), 17x (tile+parallel+interchange)", "7.4x fewer crossbar writes with loop interchange; almost two years longer expected PCM lifetime", "Average energy reduction 1.9x-5.0x vs ARM; up to 60% higher energy for WaveNet in the best config", "Crossbar utilisation ~100% for GEMM kernels, ~2% for conv2d (3x3 kernels), ~6.5% for WaveNet; only 50% of WaveNet computation offloadable vs 99.5% for mlp3"], "limitations": ["Baseline is a single in-order ARM core, not a GPU/TPU or a competing CIM accelerator; speedups say little about CIM vs state-of-the-art digital hardware", "ADC quantization loss, device noise and drift are explicitly not modelled; accuracy is never evaluated", "Tiny accelerator (4 tiles of 64x64) and weights are re-programmed per GEMM, so results are dominated by write cost rather than a weight-stationary deployment", "Accumulation of partial sums and Im2Col happen on the host; batch matmul, grouped convolution and some contractions are unsupported", "Evaluation uses kernels and a few small networks, not full modern DNNs"], "remarks": "OCC is important mainly as a compiler-infrastructure contribution: it showed that MLIR dialects and progressive lowering give robust pattern detection for crossbar offload, an idea later picked up by CINM/Cinnamon, CIM-MLC and other MLIR-based CIM stacks that cite it. Its hardware model is simplistic (a write-heavy co-processor with re-programmed weights, ideal analog compute), so the performance and energy numbers should not be taken as representative of weight-stationary analog inference. For a thesis on mapping models to crossbars, it is a good reference for the compiler front/middle end (motif detection, tiling, write-minimising loop orders) rather than for mapping quality or accuracy under non-idealities.", "basis": "full-text", "pdf_source_url": "https://pure.tue.nl/ws/files/328202256/OCC_An_Automated_End-to-End_Machine_Learning_Optimizing_Compiler_for_Computing-In-Memory.pdf", "abstract": "Memristive devices promise an alternative approach toward non-Von Neumann architectures, where specific computational tasks are performed within the memory devices. In the machine learning (ML) domain, crossbar arrays of resistive devices have shown great promise for ML inference, as they allow for hardware acceleration of matrix multiplications. But, to enable widespread adoption of these novel architectures, it is critical to have an automatic compilation flow as opposed to relying on a manual mapping of specific kernels on the crossbar arrays. We demonstrate the programmability of memristor-based accelerators using the new compiler design principle of multilevel rewriting, where a hierarchy of abstractions lowers programs level-by-level and perform code transformations at the most suitable abstraction. In particular, we develop a prototype compiler, which progressively lowers a mathematical notation for tensor operations arising in ML workloads, to fixed-function memristor-based hardware blocks.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2021_Siemieniuk_OCC_TCAD.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2021_Siemieniuk_OCC_TCAD.pdf", "priority": 7.38}, {"id": "W3204737618", "short": "Polyhedral PIM Compiler", "title": "Polyhedral-Based Compilation Framework for In-Memory Neural Network Accelerators", "authors": ["Jianhui Han", "Xiang Fei", "Zhaolin Li", "Youhui Zhang"], "year": 2021, "venue": "ACM Journal on Emerging Technologies in Computing Systems", "venue_short": "JETC", "venue_full": "ACM Journal on Emerging Technologies in Computing Systems", "venue_ok": true, "doi": "https://doi.org/10.1145/3469847", "cites_global": 10, "cat": "05", "seed": false, "devices": ["Memristor(generic)"], "models": ["CNN", "LSTM/RNN"], "evidence": "algorithm+simulation", "tldr": "A source-to-source compilation framework uses the polyhedral model to automatically detect and map NN operators onto memristor-based PIM hardware and generate pipelined execution schedules, improving throughput by an order of magnitude over non-pipelined polyhedral compilers.", "summary": "Memristor-based processing-in-memory (PIM) accelerators promise to address the memory bottleneck in neural network execution, but programming them requires compiling high-level NN workloads (with heterogeneous operators) down to hardware with varying programming granularities. The authors propose a source-to-source compilation framework built on the polyhedral model, which they argue gives richer representational power than prior ad hoc mapping schemes, enabling automatic detection and mapping of multiple NN operator types to memristor crossbar hardware. Unlike prior polyhedral-based compilation work, the framework adds pipeline generation to exploit loop-level parallelism in NN workloads so that hardware resources (crossbars, buffers) are kept busier across pipeline stages. The framework is evaluated on synthetic kernels and NN benchmarks, and case studies on representative memristor-based accelerator architectures are used to show generality across different hardware designs. Reported results show the pipelined version improves performance by about an order of magnitude over otherwise-equivalent polyhedral compilation frameworks without pipelining support.", "contributions": ["A source-to-source compilation framework for memristor-based PIM accelerators built on the polyhedral model", "Automatic detection and mapping of multiple NN operator types to crossbar hardware with varying programming granularities", "Pipeline generation support to exploit NN-workload parallelism, extending prior (non-pipelined) polyhedral compilation approaches for PIM", "Evaluation across multiple representative memristor-based accelerator architectures (case studies) to demonstrate generality", "Order-of-magnitude throughput improvement from pipelined execution vs. non-pipelined polyhedral baselines (per abstract)"], "claims": [{"claim": "The framework can reliably detect and map target NN operators onto memristor-based accelerators using the polyhedral model.", "support": "Abstract: 'demonstrates that the proposed framework can reliably detect and map the target operators'", "loc": "Abstract"}, {"claim": "Supporting pipelined execution improves performance by about an order of magnitude over existing polyhedral-based compilation frameworks that lack pipelining.", "support": "Abstract: 'the performance can upgrade by an order of magnitude with the pipelined execution'", "loc": "Abstract"}], "results": ["Order-of-magnitude performance improvement from pipelined execution vs. non-pipelined polyhedral-based compilation baselines (abstract; exact benchmark-level numbers not available from abstract alone)"], "limitations": ["Full text was not accessible (IEEE/ACM paywalled; no legitimate open copy found); this entry is based on the abstract and metadata only, so detailed quantitative results, benchmark specifics, and comparison baselines beyond the abstract's headline claim could not be verified", "Evaluated on synthetic kernels plus NN benchmarks and case-study architectures rather than a single standardized large-scale accelerator or end-to-end chip"], "remarks": "This paper addresses the compiler/mapping layer for memristor-based PIM rather than proposing new hardware or device-level accuracy techniques, positioning it in the mapping-and-dataflow literature alongside PUMA, PANTHER, and FloatPIM. Because only the abstract was available, the critical assessment is necessarily limited: the claimed order-of-magnitude gain from pipelining is plausible given known PIM pipeline-stall bottlenecks (e.g., ADC/DAC and crossbar-array contention) but could not be cross-checked against baseline configuration details or hardware assumptions.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Memristor-based processing-in-memory architecture is a promising solution to the memory bottleneck in the neural network ( NN ) processing. A major challenge for the programmability of such architectures is the automatic compilation of high-level NN workloads, from various operators to the memristor-based hardware that may provide programming interfaces with different granularities. This article proposes a source-to-source compilation framework for such memristor-based NN accelerators, which can conduct automatic detection and mapping of multiple NN operators based on the flexible and rich representation capability of the polyhedral model. In contrast to previous studies, it implements support for pipeline generation to exploit the parallelism in the NN loads to leverage hardware resources for higher efficiency. The evaluation based on synthetic kernels and NN benchmarks demonstrates that the proposed framework can reliably detect and map the target operators. Case studies on typical memristor-based architectures also show its generality over various architectural designs. The evaluation further demonstrates that compared with existing polyhedral-based compilation frameworks that do not support the pipelined execution, the performance can upgrade by an order of magnitude with the pipelined execution, which emphasizes the necessity of our improvement.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2021_Han_PolyhedralPIMCompiler_JETC.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2021_Han_PolyhedralPIMCompiler_JETC.pdf", "priority": 7.06}, {"id": "W3091895175", "short": "RaQu", "title": "RaQu: An automatic high-utilization CNN quantization and mapping framework for general-purpose RRAM Accelerator", "authors": ["Songyun Qu", "Bing Li", "Ying Wang", "Dawen Xu", "Xiandong Zhao", "Lei Zhang"], "year": 2020, "venue": "", "venue_short": "DAC", "venue_full": "57th ACM/IEEE Design Automation Conference (DAC 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/dac18072.2020.9218724", "cites_global": 40, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "RaQu is an AutoML-based, array-aware mixed-precision quantization and mapping framework that uses a two-stage learning and array-aware grouping strategy to search fine-grained per-parameter bit-widths, improving RRAM crossbar resource utilization by 18.2%-36.1% and accuracy by 0.9%-3.3% over prior coarse-grained quantization methods.", "summary": "Mapping an arbitrary CNN architecture onto a general-purpose RRAM crossbar accelerator for edge inference often leads to severe underutilization of crossbar resources, because fixed/coarse-grained bit-widths do not match the network's actual parameter distribution. Manually tuning per-parameter bit-widths at scale is impractical. RaQu proposes an AutoML-based array-aware quantization and mapping framework that automatically generates fine-grained mixed-precision CNNs, using a two-stage learning process together with an array-aware grouping strategy to make the otherwise huge bit-width search space tractable. The framework targets both resource (crossbar) utilization and model accuracy jointly, reporting improvements over prior coarse-grained quantization/mapping methods.", "contributions": ["An AutoML-based array-aware quantization and mapping framework (RaQu) that generates fine-grained, mixed-precision CNNs tailored to RRAM crossbar resource utilization", "A two-stage learning strategy to make bit-width search tractable across a huge per-parameter search space", "An array-aware grouping strategy that aligns quantization granularity with the RRAM crossbar's physical array structure", "Demonstrated improvements in both resource utilization and model accuracy over prior coarse-grained quantization/mapping baselines"], "claims": [{"claim": "RaQu substantially improves RRAM crossbar resource utilization over prior coarse-grained quantization methods", "support": "18.2%-36.1% improvement in resource utilization (abstract)", "loc": "Abstract"}, {"claim": "RaQu simultaneously improves model accuracy over prior coarse-grained quantization methods", "support": "0.9%-3.3% increase in model accuracy (abstract)", "loc": "Abstract"}, {"claim": "Automated (AutoML-based) bit-width search is necessary because manual per-parameter bit-width selection is impractical at scale", "support": "Abstract: 'Selecting the bit-width for the vast parameters is impractically completed by human labor'", "loc": "Abstract"}], "results": ["18.2%-36.1% improvement in resource utilization versus prior coarse-grained quantization methods", "0.9%-3.3% increase in model accuracy versus prior coarse-grained quantization methods"], "limitations": ["Only the abstract was available for this analysis (full text not accessible from this machine; IEEE Xplore/ACM DL are not downloadable here); specific networks, datasets, crossbar sizes, and search cost/runtime of the AutoML search could not be verified", "As a DAC conference paper, experimental breadth may be more limited than a journal-length treatment"], "remarks": "Based on the abstract, RaQu sits in the mapping/compilation space alongside other quantization-and-mapping frameworks in this collection (e.g., the energy-efficient quantized training framework, the configurable multi-precision RRAM framework it cites), specifically targeting the mismatch between a trained CNN's natural per-layer/per-parameter precision needs and a general-purpose RRAM accelerator's crossbar granularity. The reported gains (resource utilization and accuracy) are both abstract-stated ranges rather than single numbers, so the actual operating point and cost of the AutoML search (a known concern for such frameworks) could not be assessed without the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Convolutional neural networks (CNNs) have become the state-of-the-art technique in many classification tasks in IoT system. However, the low-power and area-constraint edge devices are unable to afford the expensive cost of CNNs. Resistive random access memory (RRAM) is attractive for establishing the CNN accelerator at the edge end due to the features of scalability, low-power and in-situ dot-product. However, mapping a random network architecture onto a general-purpose RRAM accelerator suffers a severe issue of resource underutilization. The neural network quantization offers an opportunity to rescue the degraded resource utilization. Selecting the bit-width for the vast parameters is impractically completed by human labor. This paper proposes an AutoML-based array-aware quantization and mapping framework that generates the fine-grained mixed-precision neural networks to optimize resource utilization in RRAM. In this framework, we design a two-stage learning and array-aware grouping strategy to quickly explore the huge searching space. The experimental results show that the proposed framework achieves 18.2%~36.1% improvement in resource utilization and 0.9%~3.3% increase in model accuracy over prior coarse-grained quantization methods.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2020_Qu_RaQu_DAC.pdf", "analysed": true, "pdf": null, "priority": 6.96}, {"id": "W3020710655", "short": "FPSA Reduced Architecture", "title": "A Reduced Architecture for ReRAM-Based Neural Network Accelerator and Its Software Stack", "authors": ["Yu Ji", "Zixin Liu", "Youhui Zhang"], "year": 2020, "venue": "IEEE Transactions on Computers", "venue_short": "TC", "venue_full": "IEEE Transactions on Computers (TC), 2020", "venue_ok": true, "doi": "https://doi.org/10.1109/tc.2020.2988248", "cites_global": 5, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "MLP"], "evidence": "algorithm+simulation", "tldr": "Inspired by RISC design, the Field Programmable Synapse Array (FPSA) keeps ReRAM-crossbar hardware compact (reconfigurable logic, wires and compute resources) and pushes complexity into a software stack that converts arbitrary/dynamic NNs into hardware-compatible equivalents and optimizes their scheduling/mapping, reporting up to 1000x speedup over PRIME.", "summary": "The paper addresses two limitations of prior ReRAM-based NN accelerators: performance bounded by peripheral circuits/interconnect, and accuracy/flexibility problems from device variation and the fixed in-situ computation mode. Rather than fixing these purely in hardware (which would add overhead), the authors apply a RISC-like design philosophy: keep the hardware, Field Programmable Synapse Array (FPSA), simple, dense and efficient (reconfigurable logic, wires and compute resources built from ReRAM crossbars), and move complexity into a software stack. The software converts various neural network types, including dynamic NNs, into equivalent networks that satisfy hardware constraints with negligible accuracy loss, and performs scheduling and mapping of the converted network onto the FPSA fabric. Per the abstract, evaluation against the PRIME ReRAM-based accelerator shows up to 1000x speedup.", "contributions": ["Field Programmable Synapse Array (FPSA): a reduced/compact ReRAM-crossbar-based reconfigurable hardware architecture providing dense logic, wiring, and compute resources, following a RISC-inspired hardware/software split", "A software stack that converts arbitrary and dynamic neural networks into equivalent networks meeting FPSA's hardware constraints with negligible accuracy loss", "Scheduling and mapping optimization of the converted network onto the FPSA hardware", "A full software/hardware system co-design intended to fully exploit ReRAM's potential while minimizing hardware complexity"], "claims": [{"claim": "The proposed FPSA software/hardware system substantially outperforms a state-of-the-art ReRAM-based NN accelerator (PRIME)", "support": "Reported up to 1000x speedup versus PRIME (abstract)", "loc": "Abstract"}, {"claim": "The software conversion of networks (including dynamic NNs) to FPSA-compatible equivalents incurs negligible accuracy loss", "support": "Stated directly in abstract: 'negligible accuracy loss'", "loc": "Abstract"}, {"claim": "Moving complexity to software (RISC-like design) allows the ReRAM hardware to be more compact and efficient than approaches that solve accuracy/flexibility issues purely in hardware", "support": "Abstract argument: 'Solving these issues with hardware will further offset the performance'", "loc": "Abstract"}], "results": ["Up to 1000x speedup compared to PRIME (per abstract)"], "limitations": ["Only the abstract was available for this analysis (full text not accessible from this machine; IEEE Xplore is not downloadable here), so the specific benchmarks, network sizes, and conditions under which the 1000x speedup was measured could not be verified", "As an extension/journal version of conference-level FPSA work, some architectural or experimental details may be inherited from prior publications not captured here"], "remarks": "Based on the abstract, this is a mapping/compilation and architecture co-design paper in the spirit of a RISC-like split between simple reconfigurable ReRAM hardware and a sophisticated software compiler/scheduler, directly targeting the flexibility limitations of fixed in-situ crossbar designs like PRIME and ISAAC. The claimed 1000x speedup over PRIME is a striking figure that, without full-text access, cannot be contextualized against workload selection or baseline configuration; this should be treated as a headline abstract claim pending verification against the full paper or its earlier (likely ISCA) conference version.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Neural network (NN) accelerators based on resistive random access memory (ReRAM) have been widely investigated as a promising solution to address the memory wall challenge, due to its capability of processing-in-memory with extremely high density. However, the performance of these accelerators is bounded by the peripheral circuits and the interconnection. And they also suffer from accuracy issue and flexibility issue caused by the device-variation and the in-situ computation mode respectively. Solving these issues with hardware will further offset the performance. Enlightened by the design principle of conventional reduced instruction set computer (RISC), this article proposes a new software/hardware system for ReRAM-based NN acceleration, which achieves complex functions with sophisticated software tools while making the hardware much more compact and efficient, in order to fully utilize ReRAM potential. The hardware architecture, Field Programmable Synapse Array (FPSA), provides high-density reconfigurable logic, wires, and computational resources based on ReRAM-crossbar. Accordingly, the software can convert various types of NNs, including dynamic NNs, into equivalent networks that meet hardware constraints with negligible accuracy loss and optimize the scheduling and mapping of the latter onto FPSA. Further evaluations show that compared to one state-of-the-art ReRAM-based NN accelerator, PRIME, our approach achieves up to 1000× speedup.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2020_Ji_FPSAReducedArchitecture_TC.pdf", "analysed": true, "pdf": null, "priority": 4.04}, {"id": "W3013896150", "short": "Representable Matrices", "title": "Representable Matrices: Enabling High Accuracy Analog Computation for Inference of DNNs using Memristors", "authors": ["Baogang Zhang", "Necati Uysal", "Deliang Fan", "Rickard Ewetz"], "year": 2020, "venue": "", "venue_short": "ASP-DAC", "venue_full": "25th Asia and South Pacific Design Automation Conference (ASP-DAC 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/asp-dac47756.2020.9045101", "cites_global": 3, "cat": "05", "seed": false, "devices": ["Memristor(generic)"], "models": ["CNN", "MLP"], "evidence": "algorithm+simulation", "tldr": "A new matrix-to-crossbar mapping technique jointly optimizes a scaling factor and memristor conductance/state values to balance IR-drop value-range errors against programming-precision errors, cutting MVM error 4x-9x over the prior dot-product-engine heuristic and raising a 7-layer CNN's CIFAR-10 accuracy from 20.5% to 71.8%.", "summary": "The paper targets the fundamental problem of mapping an arbitrary weight matrix onto a memristor crossbar array (MCA) so that the realized matrix (after IR-drop and finite conductance precision) reproduces the target matrix as accurately as possible. It observes that the state-of-the-art heuristic (Hu et al.'s dot-product engine mapping) only guarantees correctness for two input vectors (zero and a calibration vector) because it fixes the scaling factor arbitrarily. The key insight is that the realizable conductance matrix only needs to be proportional (via a scaling factor alpha) to the target matrix, and that alpha trades off a 'value range error' (from IR-drop, worse for large alpha) against a 'precision error' (from limited conductance resolution, worse for small alpha) -- together defining a 'space of representable matrices' that varies by location in the crossbar. The proposed 5-step flow converts non-ideal devices to an ideal-conductance model, optimizes alpha to balance the two error sources, solves for conductance values g (extending a Frobenius-norm minimization from prior work) while forcing the output error on a calibration vector toward zero, converts g to memristor state variables via Newton's method, and finally applies closed-loop programming. Evaluated via SPICE-level circuit simulation with non-ideal device models on MNIST (4-layer MLP) and CIFAR-10 (7-layer CNN), the method reduces maximum MVM output error 4x-9x versus the baseline across different wire resistances, crossbar sizes, and devices-per-weight, and raises CIFAR-10 CNN inference accuracy from 20.5% (baseline mapping) to 71.8% (software accuracy is 75.2%), at the cost of substantially longer mapping run-time (e.g., 6.17h vs 0.28h for MNIST).", "contributions": ["Formalizes the concept of a 'space of representable matrices' for an MCA, characterizing how value range and precision errors trade off with the scaling factor alpha and with position in the crossbar", "Proposes an iterative algorithm to jointly optimize the scaling factor alpha together with memristor conductance values g, rather than fixing alpha a priori as in prior work", "Extends conductance-value specification to guarantee near-zero error on a calibration vector drawn from the actual input distribution, by redistributing residual error across matrix-row elements not already saturated", "Provides a technique to convert between ideal conductance values and non-ideal memristor state variables via Newton's method for circuit-accurate programming", "End-to-end SPICE-level evaluation of MVM accuracy and DNN inference accuracy (MNIST MLP, CIFAR-10 CNN) against the prior dot-product-engine mapping"], "claims": [{"claim": "The proposed mapping reduces maximum MVM output error by 4x-9x compared to the state-of-the-art heuristic mapping", "support": "Fig. 7 comparison across wire resistance, crossbar size, memristors-per-weight, and device model", "loc": "Sec. VI.A, Fig. 7"}, {"claim": "The improved mapping substantially recovers DNN inference accuracy lost to crossbar non-idealities", "support": "7-layer CNN CIFAR-10 accuracy improves from 20.5% (prior mapping) to 71.8% (proposed), vs. 75.2% software baseline; MNIST MLP: 98.3% (proposed) vs. 96.3% (prior) vs. 98.4% software, with no DAC/ADC quantization", "loc": "Sec. VI.B, Fig. 9"}, {"claim": "The proposed mapping is more robust to coarse DAC/ADC bit-accuracy than the prior method", "support": "Fig. 9(a)-(b): proposed mapping tracks the upper-bound (no-quantization) accuracy curve closely across DAC/ADC bit-accuracies on both MNIST and CIFAR-10", "loc": "Sec. VI.B, Fig. 9"}, {"claim": "The accuracy gains come without area/power overhead since they stem purely from parameter (alpha, g) optimization", "support": "Stated benefits obtained 'with no overhead' because power/area depend on crossbar structure, not mapping algorithm", "loc": "Sec. VI.A"}, {"claim": "The improved accuracy comes at a mapping run-time cost", "support": "Fig. 10(b): mapping run-time of 6.17h (proposed) vs 0.28h (prior work) for MNIST; 0.93h vs 0.61h for CIFAR-10", "loc": "Sec. VI.B, Fig. 10"}], "results": ["4x-9x reduction in maximum MVM output error vs. prior dot-product-engine mapping (Fig. 7)", "CIFAR-10 7-layer CNN accuracy: 71.8% (proposed) vs. 20.5% (prior mapping) vs. 75.2% software baseline", "MNIST 4-layer MLP accuracy: 98.3% (proposed) vs. 96.3% (prior mapping) vs. 98.4% software baseline (no DAC/ADC quantization)", "Classification accuracy degrades gracefully under up to 20% random telegraph noise on CIFAR-10/MNIST (Fig. 10a)", "Programmable conductance range utilization of 64%/60%/48% for 32x32/64x64/128x128 MCAs; mapping run-time 0.5/1.5/5 min per 32/64/128-sized matrix"], "limitations": ["Evaluated via circuit simulation (SPICE-accurate) rather than measured silicon; relies on device models from prior work", "Mapping run-time is substantially higher than the baseline (up to ~20x for MNIST), which could limit scalability to larger networks/crossbar grids", "Only small-scale networks tested (4-layer MLP on MNIST, 7-layer CNN on CIFAR-10); no evaluation on larger modern architectures", "No direct comparison against the IR-drop compensation technique of Liu et al. (treated as solving only a subproblem), limiting completeness of the comparison", "Assumes a single device/crossbar technology (128x128 default MCA, 2kOhm-3MOhm range) calibrated from one prior dataset of device models"], "remarks": "This is a mapping/compilation-layer contribution that directly targets the accuracy loss caused by IR-drop and conductance quantization during crossbar programming, rather than proposing new hardware or training algorithms. The large accuracy jump on CIFAR-10 (20.5% to 71.8%) illustrates how much headroom exists in just the matrix-to-conductance mapping step, independent of device or architecture innovations, and it directly builds on and critiques the widely used Hu et al. dot-product-engine heuristic cited by much of this literature (PRIME, ISAAC, PipeLayer lineage). The main caveat for thesis work is the mapping run-time overhead, which the authors flag as future work and which would need addressing before this approach scales to full-size modern networks mapped across many crossbars.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog computing based on memristor technology is a promising solution to accelerating the inference phase of deep neural networks (DNNs). A fundamental problem is to map an arbitrary matrix to a memristor crossbar array (MCA) while maximizing the resulting computational accuracy. The state-of-the-art mapping technique is based on a heuristic that only guarantees to produce the correct output for two input vectors. In this paper, a technique that aims to produce the correct output for every input vector is proposed, which involves specifying the memristor conductance values and a scaling factor realized by the peripheral circuitry. The key insight of the paper is that the conductance matrix realized by an MCA is only required to be proportional to the target matrix. The selection of the scaling factor between the two regulates the utilization of the programmable memristor conductance range and the representability of the target matrix. Consequently, the scaling factor is set to balance precision and value range errors. Moreover, a technique of converting conductance values into state variables and vice versa is proposed to handle memristors with non-ideal device characteristics. Compared with the state-of-the-art technique, the proposed mapping results in 4X-9X smaller errors. The improvements translate into that the classification accuracy of a seven-layer convolutional neural network (CNN) on CIFAR-10 is improved from 20.5% to 71.8%.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2020_Zhang_RepresentableMatrices_ASPDAC.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2020_Zhang_RepresentableMatrices_ASPDAC.pdf", "priority": 3.92}, {"id": "W2946659370", "short": "Multi-Precision RRAM CNN", "title": "A Configurable Multi-Precision CNN Computing Framework Based on Single Bit RRAM", "authors": ["Zhenhua Zhu", "Hanbo Sun", "Yujun Lin", "Guohao Dai", "Lixue Xia", "Song Han", "Yu Wang", "Huazhong Yang"], "year": 2019, "venue": "", "venue_short": "DAC", "venue_full": "56th ACM/IEEE Design Automation Conference (DAC 2019)", "venue_ok": true, "doi": "https://doi.org/10.1145/3316781.3317739", "cites_global": 86, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "simulation", "tldr": "A configurable multi-precision CNN computing framework built entirely from single-bit RRAM cells, combining an RRAM-overhead-aware layer-wise quantization algorithm with a reconfigurable multi-crossbar architecture, reaching near full-precision accuracy with 70% less area and 75% less energy than a multi-bit baseline.", "summary": "Multi-bit RRAM devices are hard to fabricate reliably and suffer resistance non-linearity/variation, while existing single-bit-RRAM accelerators are limited to binary/ternary CNNs with 10-20% accuracy loss. The paper proposes (1) an RRAM-computing-overhead-aware quantization algorithm that picks per-layer weight/activation bit-widths by jointly modeling accuracy loss, crossbar storage (number of crossbars) and latency (ADC/DAC-limited cycles), and (2) a configurable multi-precision architecture that represents a W-bit weight using W separate single-bit crossbars (Process Elements) combined via barrel shifters and an H-tree Joint Module, rather than multiple bits per cell or per row. PE Slices (8 PEs) are tiled into RRAM Banks and an allocation strategy spreads PE-Slice summation along the H-tree diagonal to balance delay. Evaluated on LeNet/VGG-16/ResNet-18 on CIFAR-10 with RTL synthesis at 45nm plus RRAM/ADC/DAC models from prior silicon papers. The chosen configuration (256x256 crossbars, 6-bit ADC, 2-bit DAC) achieves near-baseline accuracy (e.g., VGG-16 92.20% vs 92.02% baseline) while cutting area 70% and energy 75% versus a multi-bit RRAM realization of the same network, with crossbar-bank energy efficiency of 3.44 TOPS/W (1.6-8.6x ISAAC/PRIME).", "contributions": ["RRAM-computing-overhead-aware layer-wise quantization/compression algorithm that jointly optimizes weight/activation bit-width against a crossbar-count and latency cost model under an accuracy-loss constraint", "A configurable multi-precision CNN architecture built purely from single-bit RRAM cells, storing each weight bit in a separate crossbar (Process Element) instead of multi-bit cells or multiple bits per row", "PE Slice / RRAM Bank / H-tree Joint-Module hierarchy with a diagonal PE-Slice allocation strategy to reduce summation latency and energy", "Design-space analysis of DAC/ADC precision and crossbar size trade-offs between accuracy and area/energy/latency", "End-to-end evaluation on LeNet, VGG-16 and ResNet-18 on CIFAR-10 with RTL-synthesized peripheral circuits"], "claims": [{"claim": "Naively mapping a GPU-trained multi-precision (quantized) model onto RRAM without hardware-aware retraining causes large accuracy loss.", "support": "VGG on CIFAR-10: baseline 92.02%, GPU-quantized 88.80%, same model mapped to RRAM 83.80% (Table 1).", "loc": "Sec. 3.1, Table 1"}, {"claim": "The proposed quantization + architecture recovers most of that RRAM-mapping accuracy loss.", "support": "Their method reaches 88.48% vs. 83.80% for naive GPU-quantization-on-RRAM, close to the 92.02% full-precision baseline.", "loc": "Table 1"}, {"claim": "The framework reduces hardware cost with little accuracy loss relative to a multi-bit RRAM implementation.", "support": "70% computing-area reduction and 75% computing-energy reduction on average, nearly no accuracy loss.", "loc": "Sec. 1 (abstract/contributions), Sec. 6.3"}, {"claim": "The design achieves higher energy efficiency than prior RRAM CNN accelerators.", "support": "3.44 TOPS/W, 8.6x vs ISAAC and 1.6x vs PRIME.", "loc": "Sec. 6.3"}, {"claim": "The extra digital circuitry needed for multi-crossbar bit-splicing (PE Slice + Joint Module) adds only small overhead.", "support": "Extra energy and area overhead are only 6% and 1.07% relative to the RRAM banks (Fig. 5).", "loc": "Sec. 6.3, Fig. 5"}], "results": ["70% average computing-area reduction and 75% average computing-energy reduction vs. multi-bit RRAM baseline, with nearly no accuracy loss", "Energy efficiency 3.44 TOPS/W, 8.6x vs ISAAC and 1.6x vs PRIME", "VGG-16 on CIFAR-10: 92.20% accuracy at {256x256 crossbar, 6-bit ADC, 2-bit DAC} vs. 92.02% full-precision baseline", "ResNet-18 on CIFAR-10: up to 95.06% accuracy at 256x256/Q=10 configuration", "Extra peripheral (PE Slice + Joint Module) overhead only 6% energy / 1.07% area vs. RRAM banks"], "limitations": ["Pure simulation study: RRAM device, ADC and DAC models are taken from prior published macros/ISSCC papers rather than measured in the authors' own silicon", "Only evaluated on CIFAR-10 with relatively small/older networks (LeNet, VGG-16, ResNet-18); no ImageNet-scale or Transformer workloads", "Does not address device-level non-idealities beyond quantization error of ADC/DAC interfaces (explicitly assumes resistance variation effects on single-bit RRAM are negligible)", "Multi-crossbar-per-bit storage trades area efficiency (more crossbars needed) for reliability/manufacturability; the area numbers reported are per-PE/bank, not full chip including all peripheral and global control overhead"], "remarks": "This is a solid architecture+quantization co-design paper from the Tsinghua ISAAC/PRIME lineage, directly building on and citing ISAAC, PRIME and the same group's own Mixed-Size-Crossbar mapping work (W2899868573). Its core insight -- use only single-bit RRAM cells (which are far more manufacturable and reliable) but recover multi-bit weight precision by spreading bits across separate crossbars combined digitally -- is a practical bridge between accuracy and fabrication maturity, and the cost model linking per-layer bit-width choice to crossbar count and ADC/DAC-limited latency is a reusable mapping/quantization idea. Evidence is simulation-only with RTL-synthesized peripherals and literature-sourced device models, so real silicon variation and yield effects are not captured; the claimed 8.6x/1.6x efficiency gains over ISAAC/PRIME should be read with that caveat.", "basis": "full-text", "pdf_source_url": "", "abstract": "Convolutional Neural Networks (CNNs) play a vital role in machine learning. Emerging resistive random-access memories (RRAMs) and RRAM-based Processing-In-Memory architectures have demonstrated great potentials in boosting both the performance and energy efficiency of CNNs. However, restricted by the immature process technology, it is hard to implement and fabricate a CNN accelerator chip based on multi-bit RRAM devices. In addition, existing single bit RRAM based CNN accelerators only focus on binary or ternary CNNs which have more than 10% accuracy loss compared with full precision CNNs. This paper proposes a configurable multi-precision CNN computing framework based on single bit RRAM, which consists of an RRAM computing overhead aware network quantization algorithm and a configurable multi-precision CNN computing architecture based on single bit RRAM. The proposed method can achieve equivalent accuracy as full precision CNN but also with lower storage consumption and latency via multiple precision quantization. The designed architecture supports for accelerating the multi-precision CNNs even with various precision among different layers. Experiment results show that the proposed framework can reduce 70% computing area and 75% computing energy on average, with nearly no accuracy loss. And the equivalent energy efficiency is 1.6 ~ 8.6× compared with existing RRAM based architectures with only 1.07% area overhead.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2019_Zhu_MultiPrecisionRRAMCNN_DAC.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2019_Zhu_MultiPrecisionRRAMCNN_DAC.pdf", "priority": 8.19}, {"id": "W2997869757", "short": "Weight Mapping Dataflow PIM", "title": "Optimizing Weight Mapping and Data Flow for Convolutional Neural Networks on Processing-in-Memory Architectures", "authors": ["Xiaochen Peng", "Rui Liu", "Shimeng Yu"], "year": 2019, "venue": "IEEE Transactions on Circuits and Systems I Regular Papers", "venue_short": "TCAS-I", "venue_full": "IEEE Transactions on Circuits and Systems I: Regular Papers (2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcsi.2019.2958568", "cites_global": 100, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "simulation", "tldr": "A kernel-splitting weight-mapping and dataflow scheme that assigns input data to processing elements by spatial location (instead of unrolling whole 3D kernels into crossbar columns) improves ResNet-34 throughput/energy efficiency by ~1.4x, and by 1.96x with an optimal pipeline architecture reaching 132,476 FPS and 20.1 TOPS/W on a 32nm RRAM PIM design.", "summary": "The paper addresses inefficient input-data reuse in prior PIM accelerators, which typically unroll each 3D convolutional kernel into a vertical column of a large weight matrix mapped onto a crossbar, forcing the same input data to be accessed multiple times. The authors propose a new weight-mapping method and corresponding dataflow that divides kernels and assigns input data to different processing elements (PEs) according to their spatial location, maximizing both weight and input data reuse for PIM architectures. As a case study, they benchmark an 8-bit RRAM-based PIM design at 32 nm technology. They further propose an optimal pipeline architecture (with added area overhead) to improve throughput and energy efficiency beyond what the new mapping/dataflow alone achieves.", "contributions": ["A novel weight-mapping method that splits convolutional kernels and assigns input data to PEs by spatial location, rather than unrolling whole 3D kernels into crossbar columns", "A corresponding dataflow that maximizes both weight reuse and input-data reuse for PIM-based CNN inference", "A case-study benchmark of an 8-bit RRAM-based PIM design at 32 nm incorporating the new mapping and dataflow", "An optimal pipeline architecture (with ~50% area overhead) that further improves throughput and energy efficiency over the mapping/dataflow optimization alone"], "claims": [{"claim": "The new mapping/dataflow improves speed and efficiency over conventional kernel-unrolling mapping", "support": "~2.03x speedup and ~1.4x improvement in throughput and energy efficiency for ResNet-34, compared with the prior design based on conventional mapping", "loc": "Abstract"}, {"claim": "Adding an optimal pipeline architecture yields large further throughput/energy gains at a bounded area cost", "support": "with ~50% area overhead, achieves overall 913x and 1.96x improvement in throughput and energy efficiency, reaching 132,476 FPS and 20.1 TOPS/W", "loc": "Abstract"}], "results": ["~2.03x speedup and ~1.4x throughput/energy-efficiency improvement for ResNet-34 vs. conventional kernel-unrolling mapping", "With optimal pipelining (~50% area overhead): 913x throughput improvement and 1.96x energy-efficiency improvement overall", "Final design reaches 132,476 FPS and 20.1 TOPS/W (8-bit RRAM-based PIM, 32 nm)"], "limitations": ["Analysis based on the abstract only; details of the non-ideality assumptions, crossbar size, and ADC configuration used in the 32nm case study could not be verified from the full text", "The 913x throughput figure appears to combine the mapping/dataflow gain with the pipeline architecture's gain, so the marginal contribution of each technique individually needs the full paper to disentangle"], "remarks": "This paper (from the Georgia Tech group behind DNN+NeuroSim) is a useful, mapping-and-dataflow-centric companion to that benchmarking framework: its core insight -- that naive kernel-to-column unrolling forces redundant input reads, and that spatially-aware kernel splitting plus PE-level dataflow can reclaim significant reuse -- is a recurring theme in later PIM dataflow/compiler papers (it is cited by DNN+NeuroSim V2.0, several mapping-method and tile-level dataflow optimization works). Because only the abstract was available here, the specific crossbar/ADC configuration and the breakdown between mapping-only and mapping+pipeline gains should be confirmed against the full TCAS-I text before being used as precise baselines.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Recent state-of-the-art deep convolutional neural networks (CNNs) have shown remarkable success in current intelligent systems for various tasks, such as image/speech recognition and classification. A number of recent efforts have attempted to design custom inference engines based on processing-in-memory (PIM) architecture, where the memory array is used for weighted sum computation, thereby avoiding the frequent data transfer between buffers and computation units. Prior PIM designs typically unroll each 3D kernel of the convolutional layers into a vertical column of a large weight matrix, where the input data needs to be accessed multiple times. In this paper, in order to maximize both weight and input data reuse for PIM architecture, we propose a novel weight mapping method and the corresponding data flow which divides the kernels and assign the input data into different processing-elements (PEs) according to their spatial locations. As a case study, resistive random access memory (RRAM) based 8-bit PIM design at 32 nm is benchmarked. The proposed mapping method and data flow yields ~2.03× speed up and ~1.4× improvement in throughput and energy efficiency for ResNet-34, compared with the prior design based on the conventional mapping method. To further optimize the hardware performance and throughput, we propose an optimal pipeline architecture, with ~50% area overhead, it achieves overall 913× and 1.96× improvement in throughput and energy efficiency, which are 132476 FPS and 20.1 TOPS/W, respectively.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2019_Peng_WeightMappingDataflowPIM_TCAS-I.pdf", "analysed": true, "pdf": null, "priority": 8.59}, {"id": "W2925767305", "short": "XB-Sim", "title": "A Unified Framework for Training, Mapping and Simulation of ReRAM-Based Convolutional Neural Network Acceleration", "authors": ["He Liu", "Jianhui Han", "Youhui Zhang"], "year": 2019, "venue": "IEEE Computer Architecture Letters", "venue_short": "CAL", "venue_full": "IEEE Computer Architecture Letters (2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/lca.2019.2908374", "cites_global": 8, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Presents XB-Sim, a unified open-source framework combining ReRAM-aware NN training, a CNN-oriented mapper, and a micro-architecture simulator for end-to-end evaluation of ReRAM-based neural network accelerators (RNAs), with core components verified against circuit simulation of a real chip design.", "summary": "The paper notes that despite growing interest in ReRAM-based neural network accelerators (RNAs), there was no open, end-to-end software tool spanning training, mapping, and architectural simulation for broad design-space exploration. It presents a unified simulation framework (released as XB-Sim) consisting of three coupled components: a ReRAM-aware training algorithm that accounts for crossbar/device characteristics during NN training, a CNN-oriented mapper that places trained weights onto crossbar arrays, and a configurable micro-architecture simulator that models ReRAM and peripheral circuit behavior. The framework's core components are validated against circuit simulation of a real chip design, giving it a degree of fidelity beyond purely architectural models. The tool targets comprehensive architectural exploration and end-to-end (training-to-hardware) evaluation of CNN inference on ReRAM accelerators, and a preliminary version was released publicly on GitHub.", "contributions": ["A unified, open-source (preliminary) simulation framework spanning ReRAM-aware training, CNN mapping, and micro-architecture simulation in one pipeline", "A customized ReRAM-aware training algorithm that incorporates device/circuit characteristics", "A CNN-oriented mapper for placing trained weights onto ReRAM crossbar arrays", "Validation of the simulator's core components against circuit-level simulation of a real chip design"], "claims": [{"claim": "The simulator's core components accurately reflect real hardware behavior", "support": "function of core components verified by corresponding circuit simulation of a real chip design", "loc": "abstract"}, {"claim": "The framework enables comprehensive, end-to-end architectural exploration of ReRAM-based NN accelerators", "support": "combines ReRAM-aware training tool, CNN-oriented mapper, and micro-architecture simulator in one framework", "loc": "abstract"}], "results": ["Preliminary framework released publicly (github.com/CRAFT-THU/XB-Sim)", "Core simulator components cross-checked against circuit simulation of a real chip design (no further quantitative figures available from abstract)"], "limitations": ["Only abstract was accessible; specific benchmark networks, accuracy/throughput/energy numbers, and crossbar configurations evaluated are not verifiable here", "Described as a 'preliminary version', suggesting the released tool and evaluation may be limited in scope at time of publication", "As a short Computer Architecture Letters paper, depth of validation and breadth of benchmarks is likely limited relative to a full conference paper"], "remarks": "This is a tool/infrastructure paper rather than a novel accelerator or algorithm, aiming to fill a gap for an open, end-to-end (training-mapping-architecture) ReRAM accelerator simulator, which is valuable for reproducibility in this subfield. It is itself cited by later mapping/compilation and simulator papers in this collection (e.g. ERA-LSTM, a polyhedral-based compilation framework, and IBM's analog hardware acceleration kit paper), suggesting some adoption. Since only the abstract could be reviewed here, the claim of chip-level validation (an important differentiator from purely behavioral simulators like MNSIM) could not be independently assessed for rigor.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "ReRAM-based neural network accelerators (RNAs) could outshine their digital counterparts in terms of computational efficiency and performance remarkably. However, some open software tool for broad architectural exploration and end-to-end evaluation are still missing. We present a simulation framework of RNA for CNN inference that encompasses a ReRAM-aware NN training tool, a CNN-oriented mapper and a micro-architecture simulator. Main characteristics of ReRAM and circuits are reflected by the configurable simulator, as well as by the customized training algorithm. The function of the simulator's core components is verified by the corresponding circuit simulation of a real chip design. This framework enables comprehensive architectural exploration and end-to-end evaluation, and it's preliminary version is available at https://github.com/CRAFT-THU/XB-Sim.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2019_Liu_XB-Sim_CAL.pdf", "analysed": true, "pdf": null, "priority": 5.97}, {"id": "W2899868573", "short": "MISCA", "title": "Mixed size crossbar based RRAM CNN accelerator with overlapped mapping method", "authors": ["Zhenhua Zhu", "Jilan Lin", "Ming Cheng", "Lixue Xia", "Hanbo Sun", "Xiaoming Chen", "Yu Wang", "Huazhong Yang"], "year": 2018, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2018)", "venue_ok": true, "doi": "https://doi.org/10.1145/3240765.3240825", "cites_global": 55, "cat": "05", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "MISCA combines mixed-size RRAM crossbars with an Overlapped Mapping Method (OMM) that reuses otherwise-idle crossbar cells, reporting 2.7x speedup, 30% utilization improvement and 1.2x energy efficiency over fixed-size-crossbar baselines, and 26.4x speedup / 1.65x energy efficiency over PRIME.", "summary": "Large RRAM crossbars are more energy-efficient per cell than small crossbars because of reduced peripheral-interface overhead, but conventional per-small-crossbar workload mapping cannot fully exploit a large crossbar's capacity, leaving many cells idle. The paper proposes an Overlapped Mapping Method (OMM) together with a Mixed-Size-Crossbar RRAM CNN Accelerator (MISCA) that assigns CNN workloads to large crossbars so idle cells are reused, improving parallelism and reducing per-conversion interface-circuit energy. Using a mix of large and small crossbars sized to the workload, MISCA+OMM is evaluated in simulation against both a fixed-size-crossbar RRAM accelerator baseline and a GPU platform, and separately against PRIME, an existing RRAM-based accelerator design.", "contributions": ["Overlapped Mapping Method (OMM) that reuses idle RRAM cells within large crossbars to raise utilization and parallelism for CNN workloads", "Mixed-size crossbar accelerator architecture (MISCA) combining large and small crossbars rather than one fixed crossbar size", "Simulation-based evaluation of speedup, utilization, and energy efficiency versus fixed-size-crossbar RRAM accelerators and GPU", "Direct comparison against the PRIME accelerator architecture"], "claims": [{"claim": "MISCA with OMM improves speedup, utilization, and energy efficiency over a fixed-size-crossbar RRAM accelerator using conventional mapping", "support": "2.7x speedup, 30% utilization-rate improvement, 1.2x energy-efficiency improvement on average (simulation)", "loc": "Abstract"}, {"claim": "MISCA with OMM greatly outperforms a GPU platform", "support": "490.4x average energy efficiency and 20x average speedup over GPU", "loc": "Abstract"}, {"claim": "MISCA with OMM outperforms the PRIME RRAM accelerator", "support": "26.4x speedup and 1.65x energy-efficiency improvement vs PRIME", "loc": "Abstract"}], "results": ["2.7x speedup, 30% utilization-rate improvement, 1.2x energy-efficiency improvement vs fixed-size-crossbar RRAM accelerator (average, simulation)", "490.4x average energy efficiency and 20x average speedup vs GPU platform", "26.4x speedup and 1.65x energy-efficiency improvement vs PRIME"], "limitations": ["Analysis here is abstract-only -- benchmark CNN set, crossbar size choices, and device non-ideality assumptions underlying these numbers could not be verified against the full text", "All reported numbers are simulation-based; no silicon measurement is claimed"], "remarks": "MISCA/OMM targets the same core inefficiency as SemiMap and Crossbar-Aware Pruning -- wasted crossbar cells from naive workload-to-crossbar mapping -- but attacks it from the crossbar-sizing/mapping side rather than sparsification or fold/unfold scheduling, and is cited by several later mapping/compilation frameworks (PIMCOMP, Gibbon, Mathematical Framework for Crossbar Allocation) as a reference mixed-size mapping scheme. Reported gains (especially the 490x GPU energy-efficiency number) are the kind of large simulation-only speedups common in this literature and should be read against the specific (likely favorable) baseline configuration rather than as a general property of RRAM accelerators; full-text verification is recommended before citing specific figures.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Convolutional Neural Networks (CNNs) play a vital role in machine learning. CNNs are typically both computing and memory intensive. Emerging resistive random-access memories (RRAMs) and RRAM crossbars have demonstrated great potentials in boosting the performance and energy efficiency of CNNs. Compared with small crossbars, large crossbars show better energy efficiency with less interface overhead. However, conventional workload mapping methods for small crossbars cannot make full use of the computation ability of large crossbars. In this paper, we propose an Overlapped Mapping Method (OMM) and MIxed Size Crossbar based RRAM CNN Accelerator (MISCA) to solve this problem. MISCA with OMM can reduce the energy consumption caused by the interface circuits, and improve the parallelism of computation by leveraging the idle RRAM cells in crossbars. The simulation results show that MISCA with OMM can achieve 2.7× speedup, 30% utilization rate improvement, and 1.2× energy efficiency improvement on average compared with fixed size crossbars based accelerator using the conventional mapping method. In comparison with GPU platform, MISCA with OMM can perform 490.4× higher on average in energy efficiency and 20× higher on average in speedup. Compared with PRIME, an existing RRAM based accelerator, MISCA has 26.4× speedup and 1.65× energy efficiency improvement.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2018_Zhu_MISCA_ICCAD.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2018_Zhu_MISCA_ICCAD.pdf", "priority": 7.95}, {"id": "W2883149906", "short": "Crossbar-Aware Pruning", "title": "Crossbar-Aware Neural Network Pruning", "authors": ["Ling Liang", "Lei Deng", "Yueling Jenny Zeng", "Xing Hu", "Yu Ji", "Xin Ma", "Guoqi Li", "Yuan Xie"], "year": 2018, "venue": "IEEE Access", "venue_short": "IEEEAccess", "venue_full": "IEEE Access", "venue_ok": true, "doi": "https://doi.org/10.1109/access.2018.2874823", "cites_global": 53, "cat": "05", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "An L0-norm constrained gradient-descent pruning algorithm (LGD with relaxant probabilistic projection) produces crossbar-grain and column-grain sparsity that directly reduces the number of physical crossbars needed to map CNNs, cutting crossbar overhead by 44%-72% on VGG8/VGG16/ResNet18 with little accuracy loss.", "summary": "The paper addresses the problem that standard neural-network pruning is not crossbar-aware: unstructured sparsity doesn't reduce the number of physical crossbars needed because a single remaining nonzero weight still occupies a whole row/column/crossbar. It formulates pruning as an L0-norm-constrained optimization problem and solves it with a new L0-constrained gradient descent (LGD) algorithm using relaxant probabilistic projection (RPP) to toggle between full and sparse weight spaces during training. Two pruning grains are produced: crossbar-grain sparsity (whole crossbars eliminated) and finer column-grain sparsity with output recombination (packing surviving columns from multiple crossbars together), plus an input-feature-map reordering scheme that clusters FMs of similar importance to reduce the accuracy loss from recombination. Evaluated on VGG8/CIFAR-10 and VGG16/ResNet18/ImageNet, the method reduces the number of crossbars needed by 59.8% (VGG16), 44.2% (ResNet18) and 72.1% (VGG8) with only minor accuracy degradation, and the paper reports ResNet's compact structure makes it more sensitive to pruning than VGG. This is a pure algorithm/software framework evaluated via simulated crossbar mapping, not a fabricated chip.", "contributions": ["Formulates CNN pruning as an L0-norm constrained optimization problem targeted specifically at crossbar hardware cost, rather than generic FLOP/parameter count", "Proposes an L0-constrained gradient descent (LGD) algorithm with relaxant probabilistic projection (RPP) that switches between dense and sparse weight spaces during training to get precise, controllable sparsity", "Introduces two pruning granularities: crossbar-grain sparsity (removes whole crossbars) and column-grain sparsity with output recombination (finer-grained, better accuracy at same sparsity)", "Proposes an input feature-map reordering method that clusters feature maps of similar importance to reduce the accuracy loss introduced by column recombination", "Demonstrates 44%-72% reduction in required crossbars across VGG8 (CIFAR-10), VGG16 and ResNet18 (ImageNet) with small accuracy degradation"], "claims": [{"claim": "Crossbar-aware pruning substantially reduces the number of physical crossbars needed to map CNNs vs. unstructured pruning, which gives no hardware savings", "support": "59.8%, 44.2%, and 72.1% of compute crossbars saved in VGG16, ResNet18, and VGG8 respectively", "loc": "Sec. IV / Conclusion"}, {"claim": "Column-grain sparsity with output recombination gives better accuracy than naive crossbar-grain sparsity at the same sparsity level", "support": "qualitative comparison in Sec. III/IV showing column-grain + recombination outperforms crossbar-grain at equal pruning ratio", "loc": "Sec. III-IV"}, {"claim": "Input feature-map reordering reduces the accuracy drop caused by column recombination", "support": "accuracy-vs-reorder comparison for multiple VGG16 layers (Conv1_2 etc.)", "loc": "Fig. 8, around line 1333"}, {"claim": "ResNet18 is more sensitive to crossbar-aware pruning than VGG-style networks", "support": "ResNet18 only yields 44.2% crossbar savings vs. 59.8%/72.1% for VGG16/VGG8, attributed to ResNet's more compact structure", "loc": "Sec. IV, final results discussion"}], "results": ["59.8% crossbar/compute-resource reduction on VGG16 (ImageNet) with insignificant accuracy degradation", "44.2% crossbar reduction on ResNet18 (ImageNet)", "72.1% crossbar reduction on VGG8 (CIFAR-10)", "Overall range reported across all three benchmarks: 44%-72% crossbar overhead reduction with acceptable accuracy loss"], "limitations": ["Evaluation is purely algorithmic/simulated crossbar-count reduction; no device non-idealities (noise, IR drop, conductance variation) are modeled", "No fabricated or measured hardware; benefits are estimated from the pruning mask mapped onto an idealized crossbar model", "Reported accuracy degradation is described qualitatively as 'insignificant' in places without a single consolidated accuracy-drop number per network in the text excerpted", "ResNet18's lower savings (44.2%) show the approach's benefit is architecture-dependent and shrinks for already-compact networks", "Requires fine-tuning with extra training epochs (e.g., 30 extra epochs on ImageNet) to recover accuracy after pruning, adding training cost"], "remarks": "This is a software/algorithm contribution rather than a hardware or device paper: its contribution is making pruning crossbar-aware so that sparsity translates into actual crossbar-count savings, which plain unstructured pruning does not provide. It builds directly on the semi-folded mapping baseline (SemiMap, W2902501132, by an overlapping author group) and targets the same inefficiency (large resource overhead of many-crossbar CNN mapping, citing ISAAC/PRIME-style fully-unfolded mappings as the baseline this improves on). Evidence strength is moderate: results are simulation/algorithm-level crossbar-count reductions without device non-idealities, so real hardware gains (energy, latency under noise) would need separate validation; the lack of fabricated-chip or noise-aware evaluation is the main gap for a thesis reader interested in actual analog deployment.", "basis": "full-text", "pdf_source_url": "", "abstract": "Crossbar architecture has been widely adopted in neural network accelerators due to the efficient implementations on vector-matrix multiplication operations. However, in the case of convolutional neural networks (CNNs), the efficiency is compromised dramatically because of the large amounts of data reuse. Although some mapping methods have been designed to achieve a balance between the execution throughput and resource overhead, the resource consumption cost is still huge while maintaining the throughput. Network pruning is a promising and widely studied method to shrink the model size, whereas prior work for CNNs compression rarely considered the crossbar architecture and the corresponding mapping method and cannot be directly utilized by crossbar-based neural network accelerators. This paper proposes a crossbar-aware pruning framework based on a formulated$L_{0}$-norm constrained optimization problem. Specifically, we design an$L_{0}$-norm constrained gradient descent with relaxant probabilistic projection to solve this problem. Two types of sparsity are successfully achieved: 1) intuitive crossbar-grain sparsity and 2) column-grain sparsity with output recombination, based on which we further propose an input feature maps reorder method to improve the model accuracy. We evaluate our crossbar-aware pruning framework on the median-scale CIFAR10 data set and the large-scale ImageNet data set with VGG and ResNet models. Our method is able to reduce the crossbar overhead by 44%–72% with insignificant accuracy degradation. This paper significantly reduce the resource overhead and the related energy cost and provides a new co-design solution for mapping CNNs onto various crossbar devices with much better efficiency.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2018_Liang_CrossbarAwarePruning_IEEEAccess.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2018_Liang_CrossbarAwarePruning_IEEEAccess.pdf", "priority": 6.8}, {"id": "W2902501132", "short": "SemiMap", "title": "SemiMap: A Semi-Folded Convolution Mapping for Speed-Overhead Balance on Crossbars", "authors": ["Lei Deng", "Ling Liang", "Guanrui Wang", "Liang Juan Chang", "Xing Hu", "Xin Ma", "Liu Liu", "Jing Pei", "Guoqi Li", "Yuan Xie"], "year": 2018, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2018.2883959", "cites_global": 25, "cat": "05", "seed": false, "devices": ["None"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "SemiMap folds a convolution's row dimension while unfolding its column dimension across a many-crossbar array, cutting resource use by >35x and cycle count by hundreds of times relative to the fully-unfolded and fully-folded extremes, validated with a fabricated 28nm virtual-crossbar test chip.", "summary": "Crossbar-style accelerators map fully-connected layers efficiently but convolution layers force a choice between a fully-unfolded mapping (huge resource overhead, e.g. >30,000 crossbars for a CIFAR-scale CNN) and a fully-folded mapping (minimal resources but very high cycle counts). The paper proposes SemiMap, a semi-folded mapping that folds the physical compute/routing resources along the feature-map row dimension while unfolding along the column dimension, plus a feature-map slicing scheme for large images, giving a tunable speed/overhead point with streaming row-by-row and periodical inter-image pipelines. They build a many-crossbar architecture (FunC compute units wired by a routing infrastructure), fabricate a 28nm UMC test chip with 156 FunCs implemented as an off-the-shelf SRAM array plus digital multiply-accumulate units (a 'virtual crossbar', not an analog NVM device crossbar), and build a Matlab mapping compiler and a C++ cycle-accurate simulator calibrated against the chip's measured per-FunC power (1.95-6.29 mW). On a single VGG16 conv layer SemiMap needs 1176 FunCs over 115 phases versus 75,264 FunCs/1 phase (fully-unfolded) or 6 FunCs/12,544 phases (fully-folded) -- 64x and 109x reductions respectively. Across LeNet/VGG8/AlexNet/VGG16/ResNet18 it reports >35x average resource saving and shows 1.1x-2.8x speedup over a Titan Xp GPU, 14.7x over Eyeriss, 2x over DNA, and 1.3x over DRISA.", "contributions": ["Semi-folded (row-fold, column-unfold) convolution mapping for many-crossbar architectures that trades off between fully-unfolded and fully-folded extremes", "Feature-map slicing scheme to handle convolution layers whose feature maps exceed a single crossbar/FunC's capacity", "Row-by-row streaming (intra-image) and periodical (inter-image) pipeline schedules enabled by the mapping", "Fabricated 28nm (UMC HLP CMOS) 156-FunC test chip (virtual SRAM-based crossbar) used to calibrate power/timing for a Matlab mapping compiler and C++ cycle-accurate simulator", "System-level evaluation across 5 CNNs (LeNet, VGG8, AlexNet, VGG16, ResNet18) against GPU and published accelerators"], "claims": [{"claim": "SemiMap reduces resource overhead by more than 35x on average versus fully-unfolded mapping across the evaluated CNNs", "support": ">35x resource saving (abstract); per-layer case: 1176 vs 75,264 FunCs (64x) on VGG16 conv2-2", "loc": "Abstract; Sec. IV-B, Table III"}, {"claim": "SemiMap reduces cycle/latency cost by hundreds of times versus fully-folded mapping", "support": "109x time reduction on VGG16 conv2-2 (115 vs 12,544 phases); 'several hundred times cycle reduction' claimed overall", "loc": "Abstract; Sec. IV-B, Table III"}, {"claim": "SemiMap achieves higher throughput than GPU and prior digital/PIM CNN accelerators", "support": "1.5x-2.8x speedup over Titan Xp GPU on small-image datasets, 1.1x-1.4x on ImageNet (except AlexNet); 14.7x avg over Eyeriss, 2x avg over DNA, 1.3x avg over DRISA", "loc": "Sec. IV-C, Fig. 18, Table IV"}, {"claim": "The mapping methodology generalizes beyond the SRAM-based test chip to physical NVM crossbars (RRAM/PCRAM/MRAM)", "support": "Stated generalization claim; not experimentally verified on an actual analog device crossbar", "loc": "Sec. IV-A"}], "results": [">35x average resource saving vs fully-unfolded mapping across evaluated CNNs", "64x resource reduction and 109x cycle reduction on a single VGG16 conv2-2 layer vs fully-unfolded/fully-folded baselines respectively", "1.5x-2.8x speedup over NVIDIA Titan Xp GPU on small-image datasets (MNIST/CIFAR10), 1.1x-1.4x on ImageNet (except AlexNet)", "14.7x average speedup over Eyeriss, 2x over DNA, 1.3x over DRISA across AlexNet/VGG16", "Measured per-FunC power of 1.95-6.29 mW on a fabricated 28nm UMC chip with 156 FunCs at 300 MHz"], "limitations": ["The fabricated chip is a digital 'virtual crossbar' (SRAM array plus discrete multiplier/accumulator logic), not a physical analog NVM crossbar, so no RRAM/PCM device non-idealities (conductance variation, IR drop, ADC quantization) are modeled or measured", "Only 156 FunCs were integrated on-chip due to fabrication cost; large-network results come from a simulator calibrated on this small chip, not from silicon at scale", "Inter-chip communication cost is explicitly excluded from the simulation", "Comparisons against Eyeriss/DNA/DRISA are cross-platform/cross-paper throughput numbers rather than head-to-head measurements under identical conditions"], "remarks": "This is a mapping/dataflow paper whose hardware validation is digital (an SRAM-emulated 'virtual crossbar'), so it says little about analog device-level behavior; its real contribution is the row-fold/column-unfold scheduling idea and the chip-calibrated simulator methodology, which is mapping-technique-agnostic and could in principle be ported to true PCM/RRAM crossbars. Evidence is reasonably strong for the claimed resource/cycle trade-off curve (measured FunC power, cycle-accurate sim validated against real timing), but the throughput comparisons to Eyeriss/DNA/DRISA are indirect. It is a useful reference point for students studying convolution-to-crossbar mapping strategies distinct from the fully-unfolded (ISAAC-style) and fully-folded (PRIME-style) extremes, and is cited as a baseline/related mapping scheme by later works such as Crossbar-Aware Pruning and RAELLA.", "basis": "full-text", "pdf_source_url": "", "abstract": "Crossbar architecture has been widely used in neural network (NN) accelerators, involving conventional and emerging devices. It performs well on the fully connected layer through efficient vector-matrix multiplication. Whereas, the advantages degrade on the convolutional layer with huge data reuse, since the execution speed and resource overhead are imbalanced when using existing fully unfolded or fully folded mapping strategy. To address this issue, we propose a novel semi-folded mapping (SemiMap) framework for implementing the convolution on crossbars. It simultaneously folds the physical resources along the row dimension of feature maps (FMs) and unfolds them along the column dimension. The former reduces the resource overhead, and the latter maintains the parallelism. An FM slicing scheme is further proposed to enable the processing of large-size image. Via our mapping framework, a row-by-row streaming pipeline for intraimage dataflow and periodical pipeline for interimage dataflow are easy to be obtained. To validate the idea, we build a many-crossbar architecture with several designs to guarantee the overall functionality and performance. Based on the measurement data of a fabricated chip, a mapping compiler and a cycle-accurate simulator are developed for the hardware simulation of large-scale networks. We evaluate the proposed SemiMap on various convolutional NNs across different network scale. ${>} 35 {\\times }$ resource saving and several hundred times cycle reduction are demonstrated compared to the existing fully unfolded and fully folded strategies, respectively. This paper jumps out of the current extreme mapping schemes, and provides a balanced solution on how to efficiently deploy the computational graphs with data reuse on many-crossbar architecture.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2018_Deng_SemiMap_TCAD.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2018_Deng_SemiMap_TCAD.pdf", "priority": 7.18}, {"id": "W4236788275", "short": "TraNNsformer", "title": "TraNNsformer: Neural network transformation for memristive crossbar based neuromorphic system design", "authors": ["Aayush Ankit", "Abhronil Sengupta", "Kaushik Roy"], "year": 2017, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2017)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad.2017.8203823", "cites_global": 32, "cat": "05", "seed": false, "devices": ["Memristor(generic)", "PCM"], "models": ["MLP", "SNN"], "evidence": "algorithm+simulation", "tldr": "TraNNsformer interleaves pruning with size-constrained spectral clustering during training so that the surviving fully-connected weights form dense crossbar-sized blocks, cutting memristive-crossbar area by 28-55% and energy by 49-67% vs the original MLP-SNNs at iso-accuracy.", "summary": "Unstructured pruning leaves zeros scattered across crossbars, so a pruned FC layer still occupies nearly as many crossbars (and peripherals) as the dense one. TraNNsformer addresses this for fully-connected layers by running a Size-Constrained Iterative Clustering (SCIC) algorithm, an adaptation of spectral clustering that recursively splits the layer's connectivity graph into clusters no larger than the technology-permitted crossbar size with high utilisation. Training alternates backprop, magnitude pruning (accuracy don't-cares) and SCIC on unclustered synapses (clustering don't-cares), pruning synapses in both sets; once few synapses remain unclustered, whole low-value clusters are pruned. Each cluster maps to one crossbar, outputs spread over several crossbars are time-multiplexed into the neuron. Evaluated on MLP-based SNNs (MNIST, SVHN, CIFAR-10; 2.4M-5.6M synapses) using the RESPARC architecture model with 4-bit (16-level) 20k-200k ohm devices, it reduces area by 28-55% and energy by 49-67% vs the unpruned network, and by 28-49% / 15-29% vs plain pruning.", "contributions": ["Size-Constrained Iterative Clustering (SCIC): spectral-clustering-based partitioning of FC connectivity into crossbar-sized, high-utilisation clusters for any permissible crossbar size", "Integrated training loop combining pruning, clustering and cluster pruning so sparsity becomes crossbar-level (structured) sparsity", "Demonstration that offline (post-training) clustering leaves many unclustered synapses and can be worse than plain pruning", "Area/energy evaluation on a memristive crossbar architecture and on a CMOS general-purpose architecture"], "claims": [{"claim": "Unstructured pruning barely improves crossbar utilisation, so sparsity does not translate to area savings on crossbars.", "support": "A pruned DNN with ~70% sparsity maps to MCAs with ~0.3 utilization factor, almost uniform across all MCAs", "loc": "Sec. V-A, Fig. 5"}, {"claim": "TraNNsformer reduces crossbar-architecture area vs both original and pruned networks at iso-accuracy.", "support": "28%-55% (avg 39%) area savings vs original; 28%-49% (avg 37%) vs pruned", "loc": "Sec. V-B, Fig. 7"}, {"claim": "TraNNsformer reduces energy per classification, because it shrinks both crossbar and peripheral energy.", "support": "49%-67% (avg 56%) energy reduction vs original; 15%-29% (avg 20%) vs pruned", "loc": "Sec. V-B, Fig. 8"}, {"claim": "Clustering must be done during training; offline clustering leaves too many unclustered synapses.", "support": "Fraction of unclustered synapses after offline clustering is significantly higher in all layers; offline clustering energy is higher than pruning for MNIST and SVHN", "loc": "Sec. V-A/B, Fig. 6, Fig. 8"}, {"claim": "The clustered structure also benefits CMOS general-purpose architectures via smaller weight memory.", "support": "TraNNsformer is 20%-57% (avg 37%) more energy efficient than the pruned DNN on CMOS", "loc": "Sec. V-C, Fig. 9"}], "results": ["Area: -28% to -55% (avg -39%) vs original, -28% to -49% (avg -37%) vs pruned, iso-accuracy, MNIST/SVHN/CIFAR-10 MLP-SNNs", "Energy on crossbar architecture: -49% to -67% (avg -56%) vs original, -15% to -29% (avg -20%) vs pruned", "Energy on CMOS general-purpose architecture: 20%-57% (avg 37%) lower than pruned DNN", "Pruned (70% sparse) network gives ~0.3 crossbar utilisation; TraNNsformer shifts the cluster-quality distribution toward high utilisation (SVHN)"], "limitations": ["Only fully-connected layers / MLP-based SNNs are transformed; convolution layers are argued to be inherently structured and are not handled", "Results are normalised area/energy from an analytical architecture model (RESPARC-based); no absolute numbers, no circuit/device non-idealities, ideal 4-bit weights", "Accuracy only reported as 'iso-accuracy'; exact accuracy figures and datasets are small (MNIST/SVHN/CIFAR-10 with MLPs)", "Spectral clustering on large layers is expensive and training effort is higher than plain pruning (acknowledged)", "Time-multiplexed integration of partial outputs across crossbars adds latency that is not quantified"], "remarks": "TraNNsformer is one of the earliest papers to state clearly that sparsity only pays off on crossbars if it is structured at crossbar granularity, an idea that underlies later crossbar-aware pruning (e.g., Crossbar-Aware Neural Network Pruning, ADMM-based structured pruning, Tiny-but-Accurate and bit/crossbar-level pruning works that cite it). The evidence is simulation-only, with normalised numbers and MLP-only workloads, so the magnitudes should not be extrapolated to CNNs/Transformers where conv/attention mapping dominates. Its key mapping insight (cluster rows/columns into dense crossbar tiles and count crossbars plus peripherals, not nonzeros) remains directly relevant to mapping sparse models onto analog arrays.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/1708.07949", "abstract": "Implementation of Neuromorphic Systems using post Complementary Metal-Oxide-Semiconductor (CMOS) technology based Memristive Crossbar Array (MCA) has emerged as a promising solution to enable low-power acceleration of neural networks. However, the recent trend to design Deep Neural Networks (DNNs) for achieving human-like cognitive abilities poses significant challenges towards the scalable design of neuromorphic systems (due to the increase in computation/storage demands). Network pruning [7] is a powerful technique to remove redundant connections for designing optimally connected (maximally sparse) DNNs. However, such pruning techniques induce irregular connections that are incoherent to the crossbar structure. Eventually they produce DNNs with highly inefficient hardware realizations (in terms of area and energy). In this work, we propose TraNNsformer - an integrated training framework that transforms DNNs to enable their efficient realization on MCA-based systems. TraNNsformer first prunes the connectivity matrix while forming clusters with the remaining connections. Subsequently, it retrains the network to fine tune the connections and reinforce the clusters. This is done iteratively to transform the original connectivity into an optimally pruned and maximally clustered mapping. We evaluated the proposed framework by transforming different Multi-Layer Perceptron (MLP) based Spiking Neural Networks (SNNs) on a wide range of datasets (MNIST, SVHN and CIFAR10) and executing them on MCA-based systems to analyze the area and energy benefits. Without accuracy loss, TraNNsformer reduces the area (energy) consumption by 28%-55% (49%-67%) with respect to the original network. Compared to network pruning, TraNNsformer achieves 28%-49% (15%-29%) area (energy) savings. Furthermore, TraNNsformer is a technology-aware framework that allows mapping a given DNN to any MCA size permissible by the memristive technology for reliable operations.", "review": [], "pdf_expected": "05_Mapping_Compilation_and_Dataflow/2017_Ankit_TraNNsformer_ICCAD.pdf", "analysed": true, "pdf": "05_Mapping_Compilation_and_Dataflow/2017_Ankit_TraNNsformer_ICCAD.pdf", "priority": 6.89}, {"id": "W4407065774", "short": "Layer Ensemble Averaging", "title": "Layer ensemble averaging for fault tolerance in memristive neural networks", "authors": ["Osama Yousuf", "Brian D. Hoskins", "K Ramu", "Mitchell Fream", "William A. Borders", "Advait Madhavan", "Matthew W. Daniels", "Andrew Dienstfrey", "Jabez J. McClelland", "Martin Lueker-Boden", "Gina C. Adam"], "year": 2025, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-025-56319-6", "cites_global": 19, "cat": "06", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["MLP"], "evidence": "device-experiment", "tldr": "Layer ensemble averaging maps the same pre-trained, quantized weight matrix redundantly onto a memristive crossbar and averages the resulting currents to correct stuck-at faults without retraining, restoring near-software accuracy on both simulated MNIST and a 20,000-device ReRAM hardware prototype running a continual-learning task.", "summary": "In-memory memristive accelerators suffer from device non-idealities, especially stuck-at faults, that degrade inference accuracy of pre-trained solutions mapped directly to hardware without retraining. The authors propose layer ensemble averaging (LEA), a training-free, hardware-correction fault-tolerance scheme that writes the same quantized weight matrix to a crossbar multiple times (redundancy parameter alpha), identifies the least-defective rows using a summed-conductance-variation metric, and averages the currents from a subset (beta) of the best copies to recover the ideal vector-matrix multiplication output. LEA is evaluated via hardware-informed simulation on MNIST classification against two prior hardware-oriented schemes (MAO and Committee Machines), and validated end-to-end on a continual-learning Yin-Yang task using a custom 20,000-device ReRAM prototyping platform called Daffodil. The scheme requires only 1-bit device tunability and works independent of the underlying non-volatile memory technology, since it makes no assumption about achievable conductance precision. Results show LEA achieves higher accuracy than MAO and CM at matched redundancy/overhead levels, bringing networks with up to 20% stuck-at faults to within a few percent of software baseline accuracy.", "contributions": ["Proposes layer ensemble averaging (LEA), a device-agnostic, training-free fault-tolerance scheme based on redundant block-wise crossbar mapping and current averaging", "Introduces a summed-conductance-variation (SCV) metric to identify and discard the most defective redundant rows before averaging", "Validates the scheme end-to-end on real hardware: a custom 20,000-device ReRAM prototyping platform (Daffodil) running a continual-learning (Yin-Yang) task", "Benchmarks against two prior hardware-oriented fault-tolerance schemes (MAO, Committee Machines) at matched redundancy and overhead on MNIST", "Shows the scheme only requires 1-bit device tunability, generalizing beyond memristors to other two-state NVM technologies (e.g., MTJs)"], "claims": [{"claim": "LEA restores near-software accuracy on a network with severe stuck-at faults without retraining", "support": "For MNIST with 20% stuck-at faults, accuracy improves from 40% (no correction) to 89.6 ± 1.0% at redundancy alpha=6, within 5% of the software baseline", "loc": "Abstract; Results, 'test accuracy ... alpha = 6'"}, {"claim": "LEA generalizes to real hardware on a continual-learning task", "support": "On the Yin-Yang dataset using the 20,000-device Daffodil ReRAM platform, accuracy improves from 55% to 71% (median), within 1% of the 72% software baseline, at the highest tested redundancy", "loc": "Abstract; Results, Yin-Yang hardware demonstration"}, {"claim": "LEA outperforms prior hardware-oriented schemes (MAO, Committee Machines) at matched redundancy/overhead", "support": "LEA achieves higher accuracy than MAO and CM for a given stuck-device percentage and redundancy level alpha; MAO is described as erratic at low redundancy (e.g., accuracy drop at 10% defects)", "loc": "Results, Fig. 4 comparison"}, {"claim": "The scheme only needs 1-bit device tunability, unlike many prior schemes assuming >=6-bit precision", "support": "Devices are artificially limited to 1-bit target conductance states throughout the experiments", "loc": "Introduction / Methods"}, {"claim": "Hardware overhead of LEA is comparable to prior schemes at matched redundancy", "support": "At similar redundancy levels all schemes require the same number of extra crossbar writes/devices; LEA's extra cost is a constant-time averaging step", "loc": "Results, 'overheads' discussion"}], "results": ["MNIST, 20% stuck-at faults: accuracy 40% (uncorrected) -> 89.6 ± 1.0% with LEA at alpha=6 (software baseline ~94%, within 5%)", "Yin-Yang continual learning task on 20,000-device ReRAM hardware: accuracy 55% -> 71% median with LEA (software baseline 72%, within 1%)", "Without redundancy (alpha=1), Yin-Yang accuracy is worse than a linear solver baseline of 63.8%", "LEA outperforms MAO and Committee Machines algorithms at matched redundancy alpha and overhead on MNIST"], "limitations": ["MNIST results are hardware-informed simulations, not run on the physical 20,000-device chip (only the simpler Yin-Yang task was demonstrated on real hardware)", "Devices are artificially restricted to 1-bit precision, which may understate what higher-precision devices could achieve with other schemes", "No comparison against retraining-based or software-level (e.g., error-correcting code) fault-tolerance methods, which the authors treat as orthogonal", "Scheme adds device/area overhead proportional to redundancy level alpha, trading capacity for fault tolerance", "Demonstrated only on small networks (shallow MLP/perceptron-scale) for MNIST and Yin-Yang, not on larger modern DNN workloads"], "remarks": "This is a solid device-experiment-backed contribution to the fault-tolerance/non-idealities literature: unlike most prior redundancy schemes it is validated end-to-end on a real multi-thousand-device ReRAM prototype rather than purely in simulation, and its training-free, precision-agnostic design makes it attractive for deploying pre-trained models onto early-stage or defect-prone crossbar hardware. The core idea (redundant mapping + outlier-aware current averaging) is a natural complement to algorithmic/training-based robustness methods elsewhere in this collection, though the area/energy overhead of redundancy-based correction remains a real cost that is not deeply quantified against alternative circuit-level or training-based fixes.", "basis": "full-text", "pdf_source_url": "", "abstract": "Artificial neural networks have advanced due to scaling dimensions, but conventional computing struggles with inefficiencies due to memory bottlenecks. In-memory computing architectures using memristor devices offer promise but face challenges due to hardware non-idealities. This work proposes layer ensemble averaging—a hardware-oriented fault tolerance scheme for improving inference performance of non-ideal memristive neural networks programmed with pre-trained solutions. Simulations on an image classification task and hardware experiments on a continual learning problem with a custom 20,000-device prototyping platform show significant performance gains, outperforming prior methods at similar redundancy levels and overheads. For the image classification task with 20% stuck-at faults, accuracy improves from 40% to 89.6% (within 5% of baseline), and for the continual learning problem, accuracy improves from 55% to 71% (within 1% of baseline). The proposed scheme is broadly applicable to accelerators based on a variety of different non-volatile device technologies. Fault tolerance is essential for reliable AI acceleration using novel memristive hardware. Yousuf et al. developed a training-free fault tolerance scheme and demonstrated on a 20,000-memristor prototyping platform that it outperforms other solutions.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2025_Yousuf_LayerEnsembleAveraging_NatCommun.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2025_Yousuf_LayerEnsembleAveraging_NatCommun.pdf", "priority": 4.41}, {"id": "W4405521014", "short": "MemristorCiMLLM", "title": "Memristor State Transition Dynamics for Energy-Efficient CiM-Driven LLMs in Industrial IoT", "authors": ["Tao Li", "Tetsuo Endoh"], "year": 2024, "venue": "IEEE Internet of Things Journal", "venue_short": "IoTJ", "venue_full": "IEEE Internet of Things Journal, 2024", "venue_ok": true, "doi": "https://doi.org/10.1109/jiot.2024.3519511", "cites_global": 1, "cat": "06", "seed": false, "devices": ["memristor (multistate and dual-state)"], "models": ["GPT/LLM"], "evidence": "device-experiment", "tldr": "Analyses memristor mobility and drive-frequency effects on state transitions and discusses implications for analog vs digital CiM in LLMs for IIoT.", "summary": "The paper explores connections between memristor-based CiM and LLMs for industrial IoT. It reports that memristor mobility and applied-voltage frequency are key parameters of state transitions and examines instant saturation and transition dynamics. It compares multistate (analog CiM) and dual-state (digital CiM) memristors in terms of accuracy and power. Based on abstract only.", "contributions": ["State-transition dynamics analysis of memristors", "Comparison of multistate vs dual-state memristors for analog/digital CiM", "Positioning toward LLMs in IIoT"], "claims": [{"claim": "Mobility and voltage frequency are key parameters of memristor state transitions", "support": "experimental results (abstract)", "loc": "Abstract"}], "results": ["No quantitative numbers in abstract"], "limitations": ["No LLM-level benchmark visible", "Abstract-only"], "remarks": "Link between device physics and LLM performance appears qualitative. Low evidence for SLM deployment; treat as device background.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The rapid development of the Industrial Internet of Things (IIoT) marks a major paradigm shift in the application of advanced computing technologies across industries. At the forefront of this revolution is the advanced technology of Computing in Memory (CiM), which mainly focuses on combining digital and analog approaches to improve the computational efficiency of neuromorphic processors. The goal of this study is to explore the connection between memristor-based CiM techniques and large-scale language models (LLMs) in IIoT systems, with a particular focus on memristor state-transition models and their impact on developing energy-efficient, high-performance neuromorphic processors. Experimental results show that the mobility of the memristor and the frequency of the applied voltage are important parameters of state transitions. We focus on exploring memristor’s instant saturation properties and state transition dynamics, and we investigate their potential applications in CiM-based LLMs. We analyze both multistate and dual-state memristors for analog and digital CiM, focusing on their advantages in terms of computational accuracy and power consumption for intelligent IIoT.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2024_Li_MemristorCiMLLM_IoTJ.pdf", "analysed": true, "slm": false, "lm_models": [], "param_scale": "unspecified", "slm_note": "Memristor state-transition modelling with a discussion of CiM-based LLMs for IIoT; abstract names no specific LM, parameter scale or end-to-end LLM evaluation. Device-level analysis, not a demonstrated LM deployment.", "added": "2026-10 SLM search", "pdf": null, "priority": 3.71}, {"id": "W4319990485", "short": "PCM-Drift-HWSW-Mitigation", "title": "Combined HW/SW Drift and Variability Mitigation for PCM-Based Analog In-Memory Computing for Neural Network Applications", "authors": ["Alessio Antolini", "Carmine Paolino", "Francesco Zavalloni", "Andrea Lico", "Eleonora Franchi Scarselli", "Mauro Mangia", "Fabio Pareschi", "Gianluca Setti", "Riccardo Rovatti", "Mattia Luigi Torres", "Marcella Carissimi", "Marco Pasotti"], "year": 2023, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems (2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2023.3241750", "cites_global": 35, "cat": "06", "seed": false, "devices": ["PCM"], "models": ["MLP", "CNN"], "evidence": "device-experiment", "tldr": "A combined hardware/software approach mitigates PCM conductance drift in an analog in-memory-computing MAC prototype (90nm STMicroelectronics) by using a conductance-ratio circuit technique plus device-aware DNN training, achieving ~95% MAC accuracy under drift and up to a 36% classification-accuracy gain over conventional training on a LeNet-5/CIFAR-10 task.", "summary": "Matrix-vector multiplications dominate DNN training and inference cost, and phase-change-memory (PCM) based analog in-memory computing (AIMC) is a candidate for improving DNN accelerator energy efficiency, but PCM conductance drift over time can significantly degrade MVM precision and thus DNN accuracy. This paper proposes a combined hardware and software mitigation: at the circuit level, a conductance-ratio technique compensates for PCM cell conductance drift within the core MAC computation; at the software/training level, a model of PCM cell behavior is used to perform device-aware training of DNNs, with accuracy estimated on a CIFAR-10 classification task. The approach is validated with a PCM-based AIMC prototype designed in a 90nm STMicroelectronics process that performs multiply-and-accumulate (MAC) operations, the computational kernel of MVMs. The combined hardware drift compensation and device-aware training substantially improve robustness to PCM non-idealities relative to conventional training.", "contributions": ["A circuit-level conductance-ratio technique embedded in the MAC computation core to compensate for PCM conductance drift", "A device-aware DNN training methodology using a model of PCM cell behavior, evaluated on a CIFAR-10 classification task", "A PCM-based AIMC hardware prototype in 90nm STMicroelectronics technology performing MAC (the MVM kernel operation), used to validate the approach", "Quantification of MAC computation accuracy under drift, and of the classification-accuracy benefit from device-aware training with and without drift compensation"], "claims": [{"claim": "The combined circuit-level drift compensation keeps MAC computation accuracy high even under PCM conductance drift", "support": "MAC computation accuracy around 95% even under the effect of cell drift", "loc": "Abstract"}, {"claim": "Device-aware DNN training makes networks substantially less sensitive to PCM weight variability than conventional training", "support": "15% increase in classification accuracy over a conventionally-trained LeNet-5 DNN from device-aware training alone", "loc": "Abstract"}, {"claim": "Combining device-aware training with drift compensation yields a larger accuracy improvement than either alone", "support": "36% classification-accuracy gain when drift compensation is applied on top of device-aware training", "loc": "Abstract"}], "results": ["~95% MAC computation accuracy under PCM cell conductance drift, measured on the 90nm PCM-based AIMC prototype", "15% increase in CIFAR-10 classification accuracy from device-aware DNN training vs. conventionally-trained LeNet-5", "36% classification-accuracy gain when drift compensation is additionally applied"], "limitations": ["This entry is based on the abstract only (no full text or PDF was located); the exact conductance-ratio circuit mechanism, device model details, and full experimental protocol are not confirmed here", "Accuracy evaluation uses LeNet-5 on CIFAR-10, a relatively small network/dataset, so results may not generalize directly to larger modern DNNs", "Classification-accuracy estimates rely on a device behavior model for training rather than being directly measured end-to-end on the fabricated prototype (per the abstract's description)"], "remarks": "This paper sits alongside the broader PCM drift-mitigation literature (e.g., Ambrogio's conductance-drift papers, HERMES-Core, Mackin's weight-programming work) by combining a circuit-level compensation technique with device-aware training, and backing the MAC-level claim with an actual 90nm fabricated prototype rather than simulation alone. Because only the abstract was available, the precise drift model, the time horizon over which the ~95% MAC accuracy and 36% gain were measured, and comparison to alternative drift-mitigation schemes could not be verified here and should be checked in the full paper.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Matrix-Vector Multiplications (MVMs) represent a heavy workload for both training and inference in Deep Neural Networks (DNNs) applications. Analog In-memory Computing (AIMC) systems based on Phase Change Memory (PCM) has been shown to be a valid competitor to enhance the energy efficiency of DNN accelerators. Although DNNs are quite resilient to computation inaccuracies, PCM non-idealities could strongly affect MVM operations precision, and thus the accuracy of DNNs. In this paper, a combined hardware and software solution to mitigate the impact of PCM non-idealities is presented. The drift of PCM cells conductance is compensated at the circuit level through the introduction of a conductance ratio at the core of the MVM computation. A model of the behaviour of PCM cells is employed to develop a device-aware training for DNNs and the accuracy is estimated in a CIFAR-10 classification task. This work is supported by a PCM-based AIMC prototype, designed in a 90-nm STMicroelectronics technology, and conceived to perform Multiply-and-Accumulate (MAC) computations, which are the kernel of MVMs. Results show that the MAC computation accuracy is around 95% even under the effect of cells drift. The use of a device-aware DNN training makes the networks less sensitive to weight variability, with a 15% increase in classification accuracy over a conventionally-trained Lenet-5 DNN, and a 36% gain when drift compensation is applied.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2023_Antolini_PCMDriftHWSWMitigation_JETCAS.pdf", "analysed": true, "pdf": null, "priority": 5.52}, {"id": "W4321488325", "short": "Multilevel-RRAM-VMM-Assessment", "title": "Experimental Assessment of Multilevel RRAM-Based Vector-Matrix Multiplication Operations for In-Memory Computing", "authors": ["Emilio Pérez-Bosch Quesada", "Mamathamba Kalishettyhalli Mahadevaiah", "Tommaso Rizzi", "Jianan Wen", "Markus Ulbricht", "Milos D. Krstic", "Christian Wenger", "Eduardo Pérez"], "year": 2023, "venue": "IEEE Transactions on Electron Devices", "venue_short": "TED", "venue_full": "IEEE Transactions on Electron Devices (2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/ted.2023.3244509", "cites_global": 21, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": [], "evidence": "device-experiment", "tldr": "Programs two 8x8 1T1R RRAM subarrays with different conductance-level distributions and subjects them to 1000 consecutive identical vector-matrix-multiplication operations, quantifying the accuracy loss and robustness-vs-linearity trade-off of multilevel RRAM conductance states for in-memory computing.", "summary": "RRAM-based hardware accelerators rely on vector-matrix multiplication (VMM) operations whose accuracy is challenged by the stochastic, nonideal nature of RRAM devices. The authors programmed two 8x8 one-transistor-one-resistor (1T1R) RRAM subarrays using two different distributions of conductance levels and then repeated the same VMM operation 1000 times consecutively on each subarray, monitoring the devices' inherent nonidealities throughout the test. They quantify the resulting accuracy loss of the VMM operations once digitized, and examine the trade-off between using a linearly spaced distribution of resistive states (for programming simplicity/predictability) versus robustness against the devices' nonideal behavior, aiming to inform future RRAM-based in-memory-computing hardware design.", "contributions": ["Direct experimental characterization of two different conductance-level distribution strategies in real 1T1R RRAM subarrays for multilevel VMM operations", "Repeated (1000x) consecutive identical VMM operation testing to quantify accuracy degradation and device nonideality drift over repeated use", "Quantitative comparison of the trade-off between linearly distributed resistive states and robustness to RRAM nonidealities for future IMC hardware design"], "claims": [{"claim": "Consecutive repeated VMM operations on programmed multilevel RRAM subarrays accumulate measurable accuracy loss due to device nonidealities", "support": "1000 identical consecutive VMM operations performed on two 8x8 1T1R subarrays, with accuracy loss quantified in the digital domain after monitoring nonidealities throughout", "loc": "Abstract"}, {"claim": "There is a trade-off between linearly distributing RRAM conductance levels and robustness against nonidealities", "support": "comparison of two different conductance-level distributions across the 1000-operation robustness test", "loc": "Abstract"}], "results": ["1000 consecutive identical VMM operations characterized on two 8x8 1T1R RRAM subarrays with different conductance-level distributions", "Accuracy loss of VMM operations quantified in the digital domain after repeated operation (specific accuracy percentages not given in the abstract)"], "limitations": ["This entry is based on the abstract only (no full text or PDF was located); specific accuracy-loss numbers, the exact conductance-level distributions tested, and the digitization/readout methodology are not confirmed here", "Experiments are limited to small 8x8 subarrays, which may not capture nonideality effects (e.g., IR drop, sneak paths) that scale with larger array sizes", "No neural-network-level (end-to-end DNN accuracy) evaluation is indicated in the abstract; this is a device/circuit-level VMM characterization study"], "remarks": "This is a device-experiment paper providing direct, repeated-operation hardware characterization of multilevel RRAM VMM accuracy and the linearity-vs-robustness trade-off, which is useful ground-truth evidence for the many simulation-based mapping and non-ideality papers in this collection that assume particular RRAM conductance distributions. Being limited to small 8x8 subarrays and (per the abstract) to VMM-level rather than full DNN-level accuracy, its main contribution is characterizing device behavior rather than demonstrating a complete accelerator or mapping method; a later paper in this collection ('The Lynchpin of In-Memory Computing: A Benchmarking Framework for Vector-Matrix Multiplication in RRAMs') is listed as building on it.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive random access memory (RRAM)-based hardware accelerators are playing an important role in the implementation of in-memory computing (IMC) systems for artificial intelligence applications. The latter heavily rely on vector-matrix multiplication (VMM) operations that can be efficiently boosted by RRAM devices. However, the stochastic nature of the RRAM technology is still challenging real hardware implementations. To study the accuracy degradation of consecutive VMM operations, in this work we programed two RRAM subarrays composed of$8\\times $8 one-transistor-one-resistor (1T1R) cells following two different distributions of conductive levels. We analyze their robustness against 1000 identical consecutive VMM operations and monitor the inherent devices’ nonidealities along the test. We finally quantize the accuracy loss of the operations in the digital domain and consider the trade-offs between linearly distributing the resistive states of the RRAM cells and their robustness against nonidealities for future implementation of IMC hardware systems.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2023_PerezBoschQuesada_MultilevelRRAMVMMAssessment_TED.pdf", "analysed": true, "pdf": null, "priority": 4.84}, {"id": "W4376606760", "short": "PCM Drift Energy-Accuracy Impact", "title": "Impact of Phase-Change Memory Drift on Energy Efficiency and Accuracy of Analog Compute-in-Memory Deep Learning Inference (Invited)", "authors": ["Martin M. Frank", "Ning Li", "Malte J. Rasch", "Shubham Jain", "Ching-Tzu Chen", "R. Muralidhar", "Jin‐Ping Han", "Vijay Narayanan", "Timothy M. Philip", "Kevin W. Brew", "Andrew H. Simon", "Iqbal Saraf", "Nicole Saulnier", "Irem Boybat", "Stanisław Woźniak", "Abu Sebastian", "Pritish Narayanan", "Charles Mackin", "An Chen", "Hsinyu Tsai", "Geoffrey W. Burr"], "year": 2023, "venue": "", "venue_short": "IRPS", "venue_full": "2023 IEEE International Reliability Physics Symposium (IRPS 2023), invited paper", "venue_ok": true, "doi": "https://doi.org/10.1109/irps48203.2023.10117874", "cites_global": 7, "cat": "06", "seed": false, "devices": ["PCM"], "models": ["BERT", "Transformer", "CNN", "LSTM/RNN"], "evidence": "simulation", "tldr": "IBM invited IRPS paper showing that projection-liner PCM with a two-pairs-of-varying-significance weight mapping keeps BERT accuracy loss minimal after long drift, and that drift actually raises peak VMM energy efficiency of a 14 nm heterogeneous CIM accelerator by 3-15% over one day to ten years (sustained gains <10% for CNN/LSTM/Transformer).", "summary": "Resistance drift in analog phase-change memory lowers conductances over time and threatens inference accuracy of compute-in-memory (CIM) accelerators. The paper first discusses mitigating drift and noise by integrating projection liners into mushroom-type PCM cells, including the tradeoff with reduced dynamic range. It then evaluates the resulting inference accuracy on the Transformer-based language model BERT, mapping each weight onto two pairs of liner PCM devices of differing significance, and reports minimal accuracy loss after extended drift with an optimized mapping. Finally, combining drift, circuit and architecture simulations of a previously proposed heterogeneous 14 nm CIM accelerator, it quantifies how drift-induced conductance decay reduces column currents and hence VMM energy, finding that peak VMM energy efficiency increases by 3-15% over one day to ten years for typical drift coefficients, and sustained efficiency for CNN, LSTM and Transformer benchmarks rises by less than 10%, most for analog-dominated models. Longer VMM integration times amplify the energy impact of drift.", "contributions": ["Discussion of drift/noise mitigation via projection-liner mushroom PCM and its dynamic-range tradeoff", "BERT inference-accuracy study under drift using a 2-pair (varying significance) liner-PCM weight mapping", "Joint drift + circuit + architecture simulation quantifying how drift changes VMM and end-to-end energy efficiency of a 14 nm heterogeneous CIM accelerator", "Benchmark-level energy analysis for CNN, LSTM and Transformer workloads"], "claims": [{"claim": "With an optimized mapping onto two pairs of liner PCM devices of varying significance, BERT accuracy loss after extended drift can be minimal", "support": "stated in abstract (no numbers available without full text)", "loc": "Abstract"}, {"claim": "Drift increases peak VMM energy efficiency of a heterogeneous 14 nm CIM accelerator", "support": "3% to 15% increase from one day to ten years for a range of typical drift coefficients", "loc": "Abstract"}, {"claim": "Sustained end-to-end energy-efficiency gain from drift is small and workload-dependent", "support": "below 10% for CNN, LSTM and Transformer benchmarks; greatest for models dominated by analog computation", "loc": "Abstract"}, {"claim": "Longer VMM integration times increase the energy impact of drift", "support": "stated in abstract", "loc": "Abstract"}], "results": ["Peak VMM energy efficiency rises 3-15% over 1 day to 10 years of drift (14 nm heterogeneous CIM accelerator, typical drift coefficients)", "Sustained energy-efficiency increase < 10% for CNN, LSTM and Transformer benchmarks"], "limitations": ["Abstract-only analysis here: specific BERT accuracy numbers, drift coefficients and device data could not be verified", "Energy results are from simulation of a proposed (not fabricated) 14 nm heterogeneous accelerator", "Energy 'benefit' of drift comes from shrinking currents, which simultaneously reduces signal/SNR; it is not a design lever by itself", "Invited 4-page-style reliability-symposium paper; largely synthesizes prior IBM device and architecture work"], "remarks": "Useful as a systems-level perspective linking a device non-ideality (PCM drift) to both accuracy and energy, with the counter-intuitive point that drift slightly improves energy efficiency rather than only hurting accuracy. The accuracy side builds on IBM's projection-liner PCM and multi-device significance mapping, and on hardware-aware training (Joshi et al. 2020; Rasch et al. 2023 AIHWKit) and the 14 nm heterogeneous accelerator architecture (Jain et al. 2022). Without full text the strength of the BERT accuracy evidence cannot be judged; treat numbers as simulation-based.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Among the emerging approaches for deep learning acceleration, compute-in-memory (CIM) in crossbar arrays, in conjunction with optimized digital computation and communication, is attractive for achieving high execution speeds and energy efficiency. Analog phase-change memory (PCM) is particularly promising for this purpose. However, resistance typically drifts, which can degrade deep learning accuracy over time. Herein, we first discuss drift and noise mitigation by integrating projection liners into analog mushroom-type PCM devices, as well as tradeoffs with dynamic range. We then study their impact on inference accuracy for the Transformer-based language model BERT. We find that accuracy loss after extended drift can be minimal with an optimized mapping of weights to cells comprising two pairs of liner PCM devices of varying significance. Finally, we address the impact of drift on energy consumption during inference through a combination of drift, circuit, and architecture simulations. For a range of typical drift coefficients, we show that the peak vector-matrix multiplication (VMM) energy efficiency of a recently proposed heterogeneous CIM accelerator in 14 nm technology can increase by 3% to 15% over the course of one day to ten years. For convolutional neural network (CNN), long short-term memory (LSTM) and Transformer benchmarks, the increase in sustained energy efficiency remains below 10%, being greatest for models dominated by analog computation. Longer VMM integration times increase the energy impact of drift.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2023_Frank_PCMDriftEnergyAccuracyImpact_IRPS.pdf", "analysed": true, "pdf": null, "priority": 5.06}, {"id": "W4389166806", "short": "VECOM", "title": "VECOM: Variation-Resilient Encoding and Offset Compensation Schemes for Reliable ReRAM-Based DNN Accelerator", "authors": ["Je-Woo Jang", "Thai-Hoang Nguyen", "Joon-Sung Yang"], "year": 2023, "venue": "", "venue_short": "ICCAD", "venue_full": "2023 IEEE/ACM International Conference on Computer Aided Design (ICCAD 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad57390.2023.10323803", "cites_global": 5, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet", "VGG", "Inception-V3", "LeNet"], "evidence": "simulation", "tldr": "VECOM re-biases 8-bit weights (bias 64 instead of 128) and redundantly maps the [5:4] bits so MSB MLC cells sit in low-conductance, low-variation levels, and adds a G00 conductance offset to make HRS offset-current subtraction exact for MLC, enabling far more activated wordlines: up to 9.1x throughput and ~50% energy savings with no retraining, and tolerating R-ratio down to 7.", "summary": "ReRAM PIM accelerators limit the number of simultaneously activated wordlines (MAW/NAW) because lognormal conductance variation and HRS offset current cause overlap of bitline-current distributions, which cuts throughput. VECOM observes that in 8-bit quantized CNNs (ResNet-18, VGG-16, Inception-V3) the MSB 2-bit MLC pattern is almost always 01 or 10 (weights within +/-64), so it lowers the ISAAC-style bias from 128 to 64 (clipping only ~0.002% of weights) to move MSBs to the 00/01 levels, and redundantly maps the [5:4] bit position into an original array (00/01, result multiplied by 3) plus a redundant array. A second technique, conductance offset mapping, programs every level as G + G00 via write-and-verify so a single extra HRS column subtracts the offset exactly even for multi-level cells. Monte-Carlo PyTorch simulations of an ISAAC-like 128x128, 2-bit/cell, 1-bit-DAC design show large accuracy gains at high NAW, translating to fewer ADC cycles, 3.9-7.2x average speedup and >50% energy reduction.", "contributions": ["Analysis of MLC bit-pattern distributions of 8-bit quantized CNN weights, showing MSB patterns concentrate in 01/10", "VECOM encoding: bias control (bias 64) plus redundant mapping of [5:4] bits, moving significant bits to low-conductance, low-variation MLC levels without retraining", "Conductance offset mapping (G' = G + G00) enabling exact offset-current compensation with one extra column for MLC and higher bits-per-cell", "Evaluation of accuracy vs NAW, R-ratio and bits-per-cell, plus area, speedup and energy estimates vs IAC and Go Unary"], "claims": [{"claim": "Lowering the bias to 64 clips a negligible fraction of weights", "support": "clipped weight ratio 0.00059% (ResNet-18), 0.00018% (VGG-16), 0.002% (Inception-V3)", "loc": "Table I"}, {"claim": "VECOM greatly improves accuracy at high wordline parallelism under variation sigma=0.08", "support": "accuracy gap vs conventional up to 58.4% (NAW=8) and 64.9% (NAW=128) on CIFAR-10; 77.6% (NAW=8) on CIFAR-100; 62% at NAW=8 on ImageNet", "loc": "Sec. IV-B2, Fig. 9"}, {"claim": "Offset compensation keeps accuracy at very low R-ratio", "support": "almost no degradation down to R-ratio 7 (sigma=0.04, 128 wordlines), while IAC degrades and is worse than conventional for MLC VGG-16", "loc": "Sec. IV-B3, Fig. 10"}, {"claim": "VECOM scales to multi-bit cells where IAC fails", "support": "<1% accuracy difference from baseline up to 4 bits/cell (QLC) at NAW=128, sigma=0.04, R-ratio 300; IAC declines from 2 bits/cell", "loc": "Fig. 11"}, {"claim": "Higher allowable NAW yields throughput and energy gains", "support": "speedup up to 9.1x (avg 7.2x) on CIFAR-10 and up to 5.3x (avg 3.9x) on CIFAR-100; >50% average energy reduction", "loc": "Figs. 12-13"}], "results": ["Area overhead ~25% over baseline (8-bit) due to redundant mapping, vs ~1% for IAC and ~25% (4-bit) to ~20x (8-bit) for Go Unary (Fig. 7)", "Up to 9.1x (avg 7.2x) speedup on CIFAR-10 and up to 5.3x (avg 3.9x) on CIFAR-100 vs conventional mapping (Fig. 12)", ">50% average reduction in operational energy vs baseline despite higher ADC resolution (Fig. 13)", "Accuracy improvement of up to 64.9% at NAW=128 (CIFAR-10) and 62% at NAW=8 (ImageNet) at sigma=0.08 (Fig. 9)", "Near-zero accuracy loss down to R-ratio 7 and <1% loss up to 4 bits/cell (Figs. 10-11)"], "limitations": ["Simulation-only (PyTorch Monte-Carlo) with a simple lognormal variation model applied uniformly to all levels; no IR drop, read noise, drift or device data", "Speedup derived by extrapolating conventional-mapping NAW to a 1% accuracy-drop point and assuming SAR ADC with log2(NAW)+2 bits; energy from a scaling equation, not circuit simulation", "Exploits an empirical weight distribution of 8-bit CNNs; benefit for models with heavier-tailed weights (e.g., LLM outliers) is untested", "25% crossbar area overhead and per-bit-slice array reorganization", "Only CNNs evaluated; no Transformers"], "remarks": "A clean, retraining-free data-encoding idea: map the bits that matter most onto the lowest-variation conductance levels, and fix offset subtraction for MLC by shifting all programmed targets by G00. It is a good example of exploiting weight statistics to raise wordline parallelism and lower ADC cost, complementary to hardware-aware training approaches (Chen 2017, Joshi 2020). Evidence is behavioral simulation with assumed models, so the headline speedups should be read as upper-bound estimates; the bias-control trick depends on bit-sliced, offset-binary (ISAAC-style) weight encoding.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2312.11042", "abstract": "Resistive Random-Access Memory (ReRAM)-based Processing In-Memory (PIM) Accelerator has emerged as a promising computing architecture for memory-intensive applications, such as Deep Neural Networks (DNNs). However, due to its immaturity, ReRAM devices often suffer from various reliability issues, which hinder the practicality of the PIM architecture and lead to a severe degradation in DNN accuracy. Among various reliability issues, device variation and offset current from High Resistance State (HRS) cell have been considered as major problems in a ReRAM-based PIM architecture. Due to these problems, the throughput of the ReRAM-based PIM is reduced as fewer wordlines are activated. In this paper, we propose VECOM, a novel approach that includes a variation-resilient encoding technique and an offset compensation scheme for a robust ReRAM-based PIM architecture. The first technique (i.e., VECOM encoding) is built based on the analysis of the weight pattern distribution of DNN models, along with the insight into the ReRAM's variation property. The second technique, VECOM offset compensation, tolerates offset current in PIM by mapping the conductance of each Multi-level Cell (MLC) level added with a specific offset conductance. Experimental results in various DNN models and datasets show that the proposed techniques can increase the throughput of the PIM architecture by up to 9.1 times while saving 50% of energy consumption without any software overhead. Additionally, VECOM is also found to endure low R-ratio ReRAM cell (up to 7) with a negligible accuracy drop.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2023_Jang_VECOM_ICCAD.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2023_Jang_VECOM_ICCAD.pdf", "priority": 3.54}, {"id": "W4322007931", "short": "SAF/Variation-Tolerant Mapping", "title": "A Mapping Method Tolerating SAF and Variation for Memristor Crossbar Array Based Neural Network Inference on Edge Devices", "authors": ["Yu Ma", "Linfeng Zheng", "Pingqiang Zhou"], "year": 2023, "venue": "ACM Journal on Emerging Technologies in Computing Systems", "venue_short": "JETC", "venue_full": "ACM Journal on Emerging Technologies in Computing Systems, Vol. 19, No. 2, Article 15 (2023)", "venue_ok": true, "doi": "https://doi.org/10.1145/3585518", "cites_global": 5, "cat": "06", "seed": false, "devices": ["Memristor(generic)"], "models": ["MLP", "NeRF"], "evidence": "simulation", "tldr": "A retraining-free, sort-based weight-to-crossbar remapping that groups similar-valued weights into the same crossbar (so each crossbar uses a narrow local weight range), keeping a 3-layer MNIST MLP at ~92% accuracy even at 28% stuck-at-fault rate and ~90% at lognormal variation sigma=0.4.", "summary": "The paper targets stuck-at faults (SAF) and lognormal programming variation in edge memristor crossbar accelerators where each weight uses a single memristor and no per-chip fault map or retraining is affordable. It shows that the sum weight variation (SWV) caused by a conductance deviation scales with the weight range (Wmax-Wmin) mapped to each crossbar, and formulates the assignment of weight-matrix entries to crossbars as a 0-1 program minimizing sum(max-min). Relaxing to column-by-column (vector-vector) computation and approximating that all columns have the same weight distribution, it proposes an optimal-for-the-simplified-problem algorithm: sort each column, then assign consecutive sorted chunks to crossbars, with per-crossbar local min/max used for the linear weight-to-conductance mapping and routers re-arranging inputs per stored index. Evaluated on 2- and 3-layer MNIST MLPs and an 11-layer NeRF (FERN scene) via effective-weight Monte-Carlo simulation, the remapping cuts sum(max-min) ~3-5x and maintains near-ideal accuracy under heavy SAF.", "contributions": ["Analysis showing per-crossbar weight range (Wmax-Wmin) drives SWV under SAF and variation, and a 0-1 programming formulation of weight-to-crossbar assignment", "Column-by-column (vector-vector) computing pipeline that relaxes row constraints, enabling arbitrary within-column reassignment of weights to crossbars", "Sort-based remapping algorithm, proven optimal for the simplified 'all columns share the same weight distribution' problem, requiring no fault map or retraining", "Evaluation on MNIST MLPs and a NeRF rendering network, plus speed/energy/storage overhead discussion"], "claims": [{"claim": "Minimizing the sum of per-crossbar weight ranges minimizes SWV under SAF and variation", "support": "Eq. (8)-(9): SWV = sum_k (Wmax^k - Wmin^k)/(Gmax-Gmin) * sum_i |dG_k,i|", "loc": "Sec. 3.1"}, {"claim": "Weight distributions across columns of a trained layer are very similar, justifying the simplification", "support": "For a 784x1000 layer, normalized average difference < 10% for the most different column pair and < 0.5% for the most similar", "loc": "Sec. 4.1, Fig. 6"}, {"claim": "The remapping maintains accuracy under high SAF rates without retraining", "support": "~95% accuracy at 5% defect rate and 92% at 28% defect rate vs. <80% at 5% for conventional mapping (3-layer MLP, ideal 95.73%)", "loc": "Sec. 5.1.1, Fig. 10(b)"}, {"claim": "Recovered accuracy at 20% SAF matches retraining-based methods with one memristor per weight", "support": "95.9% recovered accuracy vs 30.1% for matrix-transformation [27] and 95% for retraining-based [15]", "loc": "Table 4"}, {"claim": "The method tolerates larger variation than quantization-based training", "support": "accuracy raised from 32% to 90% at sigma=0.4, whereas [29] only raises 50% to 80%", "loc": "Sec. 5.1.2, Fig. 11(b)"}], "results": ["sum(max-min) reduced from 17.49 to 2.01 (layer 1) and 4.77 to 1.31 (layer 2) vs conventional mapping; local mapping only reaches 10.13 / 4.17 (Table 3)", "3-layer MNIST MLP: ~95% accuracy at 5% SAF and 92% at 28% SAF; 95.9% recovered accuracy at 20% SAF (Table 4)", "Variation: 95% accuracy at sigma=0.2 and 90% at sigma=0.4, vs <85% at sigma=0.2 for conventional mapping (Fig. 11)", "Scalability: ~90% reduction of normalized objective at R/S ratio = 32; 81.88% accuracy at ratio 2 with 20% SAF + sigma=0.4 (Figs. 12-13)", "NeRF: remapping reduces the objective by ~77% beyond local mapping and visibly preserves rendering quality at small defect rates (p=0.001-0.01) and sigma=0.05-0.1 (Table 5, Figs. 15-16)", "Storage overhead for the mapping index: < 2 MB for a 1024x1024 matrix; estimated ~10^3 FPS with 100 ns cycles (Sec. 5.4)"], "limitations": ["Evaluated only on tiny MLPs (MNIST) and one NeRF MLP; no CNNs, Transformers, or ImageNet-scale models", "Simulation via 'effective weights' rather than circuit-level crossbar simulation; no IR drop, ADC quantization, or read noise", "Requires column-by-column computing, which sacrifices crossbar parallelism (latency rises from ~10^3 ns to ~10^6 ns per layer); energy overhead only argued qualitatively", "Optimality holds only for the idealized assumption that all columns share the same weight distribution; effectiveness drops at small R/S ratios", "Assumes signed weights mapped linearly to a single memristor with per-crossbar ranges, requiring per-crossbar scale/offset handling in the periphery"], "remarks": "A neat, cheap observation: shrinking the dynamic range each crossbar must represent reduces the absolute weight error from any fixed conductance deviation, and sorting achieves that without fault maps. However, the evidence is weak for modern workloads (small MLPs, effective-weight simulation), and the column-serial pipeline gives up the core throughput advantage of analog crossbars, so it is mostly relevant to low-throughput edge settings. Conceptually it relates to range/scale-aware mapping and per-tile scaling used in later AIMC compilers; it would need validation with realistic peripheral (ADC, per-crossbar scaling) costs.", "basis": "full-text", "pdf_source_url": "https://faculty.sist.shanghaitech.edu.cn/faculty/zhoupq/publications/A%20Mapping%20Method%20Tolerating%20SAF%20and%20Variation%20for%20Memristor%20Crossbar%20Array%20Based%20Neural%20Network%20Inference%20on%20Edge%20Devices-MY.pdf", "abstract": "There is an increasing demand for running neural network inference on edge devices. Memristor crossbar array (MCA) based accelerators can be used to accelerate neural networks on edge devices. However, reliability issues in memristors, such as stuck-at faults (SAF) and variations, lead to weight deviation of neural networks and therefore have a severe influence on inference accuracy. In this work, we focus on the reliability issues in memristors for edge devices. We formulate the reliability problem as a 0–1 programming problem, based on the analysis of sum weight variation (SWV) . In order to solve the problem, we simplify the problem with an approximation - different columns have the same weights, based on our observation of the weight distribution. Then we propose an effective mapping method to solve the simplified problem. We evaluate our proposed method with two neural network applications on two datasets. The experimental results on the classification application show that our proposed method can recover 95% accuracy considering SAF defects and can increase by up to 60% accuracy with variation σ =0.4. The results of the neural rendering application show that our proposed method can prevent render quality reduction.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2023_Ma_SAFVariationTolerantMapping_JETC.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2023_Ma_SAFVariationTolerantMapping_JETC.pdf", "priority": 3.54}, {"id": "W3198899759", "short": "Analog Accuracy Study", "title": "On the Accuracy of Analog Neural Network Inference Accelerators", "authors": ["T. Patrick Xiao", "Ben Feinberg", "Christopher H. Bennett", "Venkatraman Prabhakar", "Prashant Saxena", "Vineet Suresh Agrawal", "Sapan Agarwal", "Matthew J. Marinella"], "year": 2022, "venue": "IEEE Circuits and Systems Magazine", "venue_short": "CASMag", "venue_full": "IEEE Circuits and Systems Magazine", "venue_ok": true, "doi": "https://doi.org/10.1109/mcas.2022.3214409", "cites_global": 72, "cat": "06", "seed": false, "devices": ["Flash", "ReRAM", "PCM", "Generic-NVM"], "models": ["CNN", "ResNet", "MLP"], "evidence": "simulation", "tldr": "A systematic accuracy study of analog in-situ MVM accelerators shows that making analog hardware quantities proportional to the algorithmic values (proportional mapping) is the key design principle for accuracy and energy efficiency, and that bit slicing gives only a small accuracy benefit that rarely justifies its overhead.", "summary": "The paper studies how mapping choices in analog in-memory MVM accelerators (bit-sliced vs. unsliced weights, offset-subtraction vs. differential signed-weight representation, ADC resolution vs. the 'full-precision guarantee') affect end-to-end inference accuracy, using a detailed per-MAC error model built on CrossSim and evaluated on ResNet50/ImageNet plus other CNNs. The central finding is that when conductances and dot-product outputs are made proportional to the underlying weight/activation values (rather than offset to be all-positive), analog errors scale with the stored value itself and inference becomes far more robust to cell programming errors, low ADC resolution, and parasitic IR drop. Under this proportional mapping, full-precision bit slicing provides only marginal accuracy gains over storing the full weight magnitude in a single device, so its ~8x area/energy overhead is rarely worth paying. A SONOS (flash) case study with 40nm circuit-level energy/area models shows a differential, unsliced, proportional design (Design A) achieves 2.17% ImageNet top-1 accuracy loss (0.86% with 4-bit QAT) at a fraction of the energy/area of a bit-sliced offset-subtraction design resembling ISAAC. The authors argue that accuracy-aware architecture design, not just intermediate-precision guarantees, is required to realize the promised energy benefits of analog compute.", "contributions": ["A detailed, per-MAC analog error model (extending CrossSim) that captures cell programming/process variation, ADC quantization/clipping, and array parasitic resistance together", "A systematic evaluation showing proportional (value-matched) mapping of weights/dot-products to analog quantities is the key enabler of accuracy, error tolerance, and reduced ADC/energy overhead", "A re-examination of bit slicing showing it gives only a small accuracy benefit under proportional mapping, insufficient to justify its energy/area cost", "A critique of the 'full-precision guarantee' (FPG) convention for setting ADC resolution, showing it is overly conservative for DNN inference", "A SONOS (flash) case study with circuit-level 40nm energy/area modeling comparing five design points (differential vs. offset-subtraction, sliced vs. unsliced) on ResNet50-v1.5/ImageNet"], "claims": [{"claim": "Proportional (differential, unsliced) mapping tolerates much larger analog errors than offset-subtraction/bit-sliced mapping", "support": "With differential cells and On/Off ratio ≥100, accuracy loss is near-zero for state-proportional cell errors up to αprop=5% even for arrays up to 4608 rows", "loc": "Sec. 5.3-5.4, Fig. 9-11"}, {"claim": "Bit slicing gives only a small accuracy benefit relative to its cost", "support": "Design B (1-bit slices) is only slightly more SONOS-error-tolerant than Design A (unsliced) but needs ~8x larger energy (63.1 fJ/op vs 8.4 fJ/op) and area (2.02 mm2 vs 0.24 mm2)", "loc": "Sec. 9.3, Table 3-4"}, {"claim": "Offset-subtraction designs without proportionality suffer severe accuracy loss and energy/area overhead", "support": "Design E (offset subtraction, ISAAC-like) loses >20% ImageNet accuracy (76.3%->50.2%) from SONOS errors and has 107x higher energy and 46x larger area than Design A", "loc": "Sec. 9.3-9.4, Table 3-4"}, {"claim": "A differential, unsliced, proportional SONOS design achieves near-digital accuracy at low overhead", "support": "Design A: 2.17% top-1 accuracy loss vs. floating point on full 50,000-image ImageNet test set (76.466%->74.296%), reduced to 0.86% with 4-bit quantization-aware training", "loc": "Sec. 9.4, Table 5"}, {"claim": "Analog input-bit accumulation substantially improves energy efficiency over digital shift-and-add", "support": "Analog S&A yields 2-4x energy improvement by cutting ADC conversions 8x", "loc": "Sec. 9.3"}], "results": ["Design A (differential, unsliced, 8b ADC, 1152 rows): 74.0% ResNet50 ImageNet accuracy with SONOS errors vs 76.3% ideal (1000-image subset); 8.4 fJ/op, 0.24 mm2 core", "Design E (offset-subtraction, bit-sliced, ISAAC-like, 72 rows): 50.2% accuracy with SONOS errors vs 74.9% ideal; 902.0 fJ/op, 11.14 mm2 core (107x energy, 46x area vs Design A)", "Full ImageNet test set (50,000 images): Design A SONOS accuracy 74.296% (±0.348%) vs 76.466% floating point baseline (2.17 pp loss); with 4-bit QAT, loss shrinks to 0.86 pp (75.294% vs 76.154%)", "At On/Off ratio >=100, differential proportional cells retain near-ideal accuracy for state-proportional error up to 5%, across arrays as large as 4608 rows", "Calibrated 8-bit ADC suffices for differential/proportional designs regardless of array size or bits/cell, whereas offset-subtraction needs small arrays (<=144 rows) and fine bit slicing (<=2 bits/cell) to reach comparable accuracy"], "limitations": ["All results are from a detailed but still-simplified simulation/error model (CrossSim-based), not measured silicon", "The SONOS energy/area numbers are derived from circuit-level estimates in a 40nm process, not a fabricated chip", "Parasitic resistance effects were excluded from the main SONOS accuracy comparison for tractability; the paper itself notes Design E's reported accuracy is likely an optimistic best case once parasitics are included", "Evaluation focuses on CNN image classification (ResNet50 and a few other ImageNet CNNs); no RNN/Transformer workloads", "Error model parameters (state-independent vs state-proportional error, On/Off ratio) are device-technology-specific generalizations that may not transfer directly to every ReRAM/PCM device"], "remarks": "This is a widely-cited, rigorous simulation study that reframes a key architectural assumption in the analog-accelerator literature: that bit slicing and the full-precision guarantee (as used in ISAAC, PRIME, PUMA, etc.) are necessary for accuracy. By showing that value-proportional, differential, unsliced mapping both improves error tolerance and cuts energy/area overhead, it directly critiques and reinterprets prior crossbar accelerator designs cited in this collection (ISAAC, PRIME, CASCADE, PUMA). Later mapping/compilation and non-ideality papers frequently cite it as the reference for why bit-slicing/ADC-resolution tradeoffs must be evaluated end-to-end rather than via intermediate-precision proxies; it is primarily an architectural/algorithmic insight validated by simulation rather than by hardware demonstration.", "basis": "full-text", "pdf_source_url": "", "abstract": "Specialized accelerators have recently garnered attention as a method to reduce the power consumption of neural network inference. A promising category of accelerators utilizes nonvolatile memory arrays to both store weights and perform in situ analog computation inside the array. While prior work has explored the design space of analog accelerators to optimize performance and energy efficiency, there is seldom a rigorous evaluation of the accuracy of these accelerators. This work shows how architectural design decisions, particularly in mapping neural network parameters to analog memory cells, influence inference accuracy. When evaluated using ResNet50 on ImageNet, the resilience of the system to analog non-idealities—cell programming errors, analog-to-digital converter resolution, and array parasitic resistances—all improve when analog quantities in the hardware are made proportional to the numerical values in the network. Moreover, contrary to the assumptions of prior work, nearly equivalent resilience to cell imprecision can be achieved by fully storing weights as analog quantities, rather than spreading weight bits across multiple devices, often referred to as bit slicing. By exploiting proportionality, analog system designers have the freedom to match the precision of the hardware to the needs of the algorithm, rather than attempting to guarantee the same level of precision in the intermediate results as an equivalent digital accelerator. This ultimately results in an analog accelerator that is more accurate, more robust to analog errors, and more energy-efficient.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Xiao_AnalogAccuracyStudy_CASMag.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2022_Xiao_AnalogAccuracyStudy_CASMag.pdf", "priority": 6.63}, {"id": "W4283733417", "short": "Weight Programming Optimisation", "title": "Optimised weight programming for analogue memory-based deep neural networks", "authors": ["Charles Mackin", "Malte J. Rasch", "An Chen", "Jonathan Timcheck", "Robert L. Bruce", "Ning Li", "Pritish Narayanan", "Stefano Ambrogio", "Manuel Le Gallo", "S. R. Nandakumar", "Andrea Fasoli", "Jose Luquin", "Alexander M. Friz", "Abu Sebastian", "Hsinyu Tsai", "Geoffrey W. Burr"], "year": 2022, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications, vol. 13, 3765 (2022)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-022-31405-1", "cites_global": 54, "cat": "06", "seed": false, "devices": ["PCM"], "models": ["LSTM/RNN", "CNN", "ResNet", "Transformer", "BERT"], "evidence": "algorithm+simulation", "tldr": "IBM proposes a network-agnostic weight-programming optimiser -- Differential Weight Evolution (DWE) over a dimension-reduced, discretised conductance-pair search space guided by a time-averaged proxy error metric -- that converts software weights into multi-conductance analogue (PCM) hardware weights so as to keep inference accuracy close to the software baseline over time, validated on LSTM, ResNet-32 and BERT-base.", "summary": "The paper addresses an under-studied step in analogue-memory DNN deployment: given a software-trained DNN, how to translate each weight into target conductances (here using 4 conductances G+, G-, g+, g- with a significance factor F per weight) so as to minimise accuracy loss from programming error, conductance drift, and read noise, especially as drift evolves over time. Because the resulting optimisation problem has ~4N+2 parameters (N = number of weights, potentially larger than the DNN itself), the authors reduce dimensionality by exploiting weight-distribution symmetry and by optimising only a handful of discretised weight levels (D=6) and linearly interpolating -- shrinking the BERT-base search space from ~212 million to 26 parameters. To avoid costly repeated inference simulation inside the optimisation loop, they define a time-averaged, normalised mean-squared-error proxy metric (weighted by weight-density importance kappa_j) and search the resulting hypercube with a Differential Weight Evolution (DWE) genetic-style optimiser. Using experimentally derived mushroom-type PCM device models (conductance-dependent programming error, drift coefficient, and read noise), they simulate weight programming and inference over time for a two-layer LSTM (Penn Treebank), ResNet-32 (CIFAR-10), and BERT-base (MNLI), showing that DWE-optimised programming, combined with hardware-aware (HWA) training, drives inference accuracy close to the floating-point/software iso-accuracy baseline and well above naive MSP-only or 50/50 MSP/LSP programming strategies, generalising across RNN, CNN and Transformer architectures without any network-specific tuning.", "contributions": ["A generalised, network-structure-agnostic computational framework for optimising analogue weight-programming strategies (choice of conductances per weight) under arbitrary device non-idealities", "Dimensionality reduction from ~4N+2 to ~4D+2 parameters by exploiting weight-distribution symmetry and discretising the weight range into D representative levels, then interpolating", "A time-averaged, density-weighted normalised MSE proxy metric that avoids running costly full inference simulations inside the optimisation loop", "Differential Weight Evolution (DWE), a genetic/evolutionary search over the resulting discretised conductance hypercube", "Demonstrated generalisation across RNN (LSTM), CNN (ResNet-32) and Transformer (BERT-base) architectures using experimentally grounded PCM device models, including accuracy over time under conductance drift"], "claims": [{"claim": "Weight programming optimisation (DWE) materially improves and helps maintain inference accuracy over time for analogue memory-based DNNs, beyond what hardware-aware (HWA) training alone achieves.", "support": "Combination of HWA training + DWE optimisation (green curves) tracks iso-accuracy more closely than HWA training with naive MSP-only or 50/50 MSP/LSP programming across LSTM, ResNet-32 and BERT-base (Fig. 4d-f)", "loc": "Results, Fig. 4"}, {"claim": "The approach is agnostic to network type, size, structure and activation function -- it only depends on the weight distribution.", "support": "Same DWE/error-metric framework applied unmodified to LSTM (Penn Treebank), ResNet-32 (CIFAR-10) and BERT-base (MNLI) with consistent accuracy benefits (Fig. 4d-f)", "loc": "Results, 'Generalisation across different DNN types'"}, {"claim": "The optimisation problem's dimensionality can be drastically reduced without losing solution quality by discretising the weight range and exploiting symmetry.", "support": "BERT-base's ~86M weights / 53M unique weights reduce from ~212 million programming parameters to 26 (D=6 discretised levels) in the proposed scheme", "loc": "Results, dimensionality-reduction section"}, {"claim": "A proxy weight-fidelity error metric (time-averaged normalised MSE) can substitute for costly repeated inference simulation during optimisation while still improving real inference accuracy.", "support": "Minimising the proxy metric (Eq. 3) over the DWE search consistently translated into the accuracy improvements observed in Fig. 4-5 inference simulations", "loc": "Results, error-metric section / Discussion"}, {"claim": "The method generalises to different PCM device characteristics, not just one specific device model.", "support": "A second, alternative PCM device characteristic set (Fig. 5) with different noise/drift statistics shows the same qualitative accuracy improvement across LSTM, ResNet-32 and BERT-base", "loc": "Results, Fig. 5"}], "results": ["DWE-optimised programming + HWA training drives inference accuracy of LSTM, ResNet-32 and BERT-base close to their floating-point/software iso-accuracy baselines over time, versus clear degradation under naive (MSP-only or 50/50 MSP/LSP) programming (Fig. 4d-f, Fig. 5d-f)", "Dimensionality reduction: BERT-base weight-programming search space reduced from ~212 million parameters to 26 (4D+2 with D=6 discretised positive-weight levels)", "Results compiled from 25 independent weight-programming/inference simulations over time per network to report mean +/- one standard deviation", "Device models are experimentally derived from measured mushroom-type PCM devices (conductance-dependent programming error, drift coefficient, and read noise)"], "limitations": ["All reported inference results use simulated hardware ('All reported inference results are produced using simulated hardware as opposed to physical hardware'), not physical PCM chips", "Optimisation still relies on a proxy error metric rather than ground-truth inference accuracy; while shown to correlate well with accuracy gains, it is an approximation", "Discretisation to D=6 weight levels plus linear interpolation is a design choice/compromise between fidelity and compute cost; sensitivity to D is only explored in Supplementary Information", "Framework assumes/exploits roughly symmetric weight distributions about zero; strongly asymmetric distributions double the parameter count", "DWE optimisation and multi-time-step inference simulation (25 runs per network, per device model) represent non-trivial offline compute cost"], "remarks": "A methodologically strong, IBM Research-authored contribution that treats the often-overlooked 'weight-to-conductance translation' step as a first-class optimisation problem, complementing (not replacing) hardware-aware training. The explicit admission that results are simulation-only tempers the generalisation claims, but the use of experimentally measured PCM device statistics, validation across three very different architectures (RNN/CNN/Transformer including BERT-base), and the clever dimensionality-reduction/proxy-metric design make this a frequently cited reference point for later IBM analog-AI toolkit work (aihwkit, NORA, hardware-aware training surveys) and for the broader 'how do you actually program a crossbar weight' question in this collection.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analogue memory-based deep neural networks provide energy-efficiency and per-area throughput gains relative to state-of-the-art digital counterparts such as graphics processing units. Recent advances focus largely on hardware-aware algorithmic training and improvements to circuits, architectures, and memory devices. Optimal translation of software-trained weights into analogue hardware weights-given the plethora of complex memory non-idealities-represents an equally important task. We report a generalised computational framework that automates the crafting of complex weight programming strategies to minimise accuracy degradations during inference, particularly over time. The framework is agnostic to network structure and generalises well across recurrent, convolutional, and transformer neural networks. As a highly flexible numerical heuristic, the approach accommodates arbitrary device-level complexity, making it potentially relevant for a variety of analogue memories. By quantifying the limit of achievable inference accuracy, it also enables analogue memory-based deep neural network accelerators to reach their full inference potential.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Mackin_WeightProgrammingOptimisation_NatCommun.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2022_Mackin_WeightProgrammingOptimisation_NatCommun.pdf", "priority": 7.34}, {"id": "W4293243554", "short": "Hybrid RRAM/SRAM IMC", "title": "Hybrid RRAM/SRAM in-Memory Computing for Robust DNN Acceleration", "authors": ["Gokul Krishnan V", "Zhenyu Wang", "Injune Yeo", "Li Yang", "Jian Meng", "Maximilian Liehr", "Rajiv Joshi", "Nathaniel C. Cady", "Deliang Fan", "Jae-sun Seo", "Yu Kevin Cao"], "year": 2022, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2022); also presented at CASES 2022 as part of the ESWEEK-TCAD special issue", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2022.3197516", "cites_global": 31, "cat": "06", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["CNN", "ResNet", "MLP"], "evidence": "measured-silicon", "tldr": "A hybrid RRAM/SRAM in-memory-computing architecture adds a parallel digital SRAM+MAC macro, combined via a programmable shifter, to compensate RRAM non-idealities, recovering up to 21.9%/12.65%/6.52% post-mapping accuracy over prior SOTA on ResNet-20/CIFAR-10, VGG-16/CIFAR-10, and ResNet-18/ImageNet, validated on a 65nm test chip with at most ~20% area and ~2.6% power overhead.", "summary": "RRAM-based in-memory computing (IMC) accelerators suffer large post-mapping accuracy loss from device variations and low-bit precision. The paper proposes a hybrid IMC architecture that runs a conventional RRAM IMC crossbar macro (1T1R multi-level cells, bit-serial ADC readout) in parallel with a small digital SRAM macro containing an array of MAC processing elements; the SRAM macro's precise output is combined with the RRAM macro's noisy output through a programmable right-shifter and adder, letting the SRAM compensate different bit-significances of the RRAM result. A training framework performs weight/activation quantization, structured pruning of the SRAM macro weights, RRAM-IMC-aware training using real device variation statistics extracted from a fabricated 65nm 1T1R RRAM device, and ensemble learning across different shifter compensation scales. The design was fabricated as a test chip in a 65nm SUNY process (both RRAM and SRAM macros) and evaluated on ResNet-20/CIFAR-10, VGG-16/CIFAR-10, ResNet-18/ImageNet, and MobileNet-v2/ImageNet using post-layout area/power at 100MHz. The hybrid architecture improves post-mapping accuracy over prior SOTA techniques by up to 21.9%, 12.65%, and 6.52% on ResNet-20/CIFAR-10, VGG-16/CIFAR-10, and ResNet-18/ImageNet respectively, at modest area (up to ~20%, dominated by MobileNet-v2) and power (up to ~2.6%) overhead relative to the RRAM macro alone.", "contributions": ["Hybrid RRAM/SRAM IMC architecture where a digital SRAM+MAC macro runs in parallel with the RRAM crossbar macro and compensates its output via a programmable shifter/adder", "End-to-end training framework combining weight/activation quantization, structured SRAM-weight pruning, RRAM-IMC-aware training with measured device variation, and ensemble learning over shift scales", "65nm 1T1R RRAM device characterization (cycle-to-cycle HRS/LRS switching variation, up to 8 resistance levels) used directly in training, giving one-to-one correspondence with real hardware", "Fabricated 65nm test chip of both RRAM and SRAM macros with post-layout area/power/timing used for all overhead numbers", "Comprehensive sweep of RRAM/SRAM precision, shift scale, and pruning ratio across 4 DNNs/2 datasets, plus comparison against 6 prior post-mapping accuracy recovery methods"], "claims": [{"claim": "The hybrid RRAM/SRAM architecture recovers substantial post-mapping accuracy lost to RRAM non-idealities versus prior SOTA methods", "support": "improvements of 21.9% (vs. Model Stability, ResNet-20/CIFAR-10), 12.65% (vs. DFP+DVA, VGG-16/CIFAR-10), and 6.52% (vs. Unary Opt, ResNet-18/ImageNet Top-1)", "loc": "Table V / Abstract"}, {"claim": "SRAM compensation achieves near-baseline accuracy at low hardware cost", "support": "Ours-A reaches 90.73% (ResNet-20), 92.75-92.97% (VGG-16), 69.21% (ResNet-18 Top-1) vs. FP-32 baselines; area overhead up to 20% and power overhead up to 2.6% of the RRAM macro", "loc": "Table V, Fig. 12"}, {"claim": "Training-time overhead of the hybrid scheme is modest compared to iterative read-verify-write (R-V-W) calibration", "support": "12-25% training-time overhead vs. R-V-W needing on the order of days to verify/write 100% of RRAM cells; hybrid training takes on the order of a couple of hours", "loc": "Sec. V, Fig. 11(a)"}, {"claim": "Memory overhead from the SRAM macro is small relative to the RRAM macro it compensates", "support": "6.5% (ResNet-20, 0.004MB SRAM vs 0.067MB RRAM) up to 24% (MobileNet-v2, 0.31MB vs 1.3MB) memory overhead", "loc": "Sec. V-F"}], "results": ["Post-mapping accuracy improvement over SOTA: +21.9% (ResNet-20/CIFAR-10 vs. Model Stability, 8-bit), +12.65% (VGG-16/CIFAR-10 vs. DFP+DVA, 8-bit), +6.52% (ResNet-18/ImageNet Top-1 vs. Unary Opt, 8-bit)", "Absolute post-mapping accuracy: 90.73% (ResNet-20, 2-bit RRAM+1-bit SRAM, 3-bit activation) vs. 91.34% FP-32 baseline; 92.75-92.97% (VGG-16, 3-bit RRAM+SRAM, 6-bit activation); 69.21% (ResNet-18 ImageNet Top-1, 3-bit RRAM+2-bit SRAM)", "Area overhead of SRAM macro vs. RRAM macro: 3.7% (ResNet-20), 2.3% (VGG-16), up to 20% (MobileNet-v2, worst case)", "Power overhead of SRAM macro vs. RRAM macro: 0.5% (ResNet-20), 0.3% (VGG-16), up to 2.6% (MobileNet-v2, worst case)", "Training time overhead: 12-25% across the four DNNs, versus on the order of days for full read-verify-write calibration"], "limitations": ["Overhead and accuracy results rely on post-layout simulation of the 65nm test chip (100MHz), not full chip-level measured inference across all four DNN benchmarks", "RRAM crossbar size fixed at 64x64 for consistency with the test chip, limiting generality to other crossbar sizes", "Comparisons against prior work use reported precision/accuracy numbers from those papers (some precisions not reported, marked '**' in Table V), making exact apples-to-apples comparison imperfect", "MobileNet-v2 shows the largest overhead (20% area, 2.6% power, 24% memory), indicating the approach is less efficient for already-compact models needing higher compensation"], "remarks": "This is a solid hardware-validated (65nm fabricated macros) contribution to RRAM non-ideality mitigation that goes beyond pure algorithmic variation-aware training by adding a small digital compensation path, with real device-variation statistics closing the sim-to-hardware gap. Its device-centric, additive-compensation approach (rather than redundancy or retraining alone) is a useful mapping technique for crossbar accelerators and has already been built upon for hybrid CIM dataflow/mapping co-exploration (e.g., Harmony, hardware-aware LoRA for LLMs). The main caveat is that although both macros are fabricated, the DNN-level accuracy/overhead results are derived from post-layout modeling of the chip rather than full end-to-end silicon-measured inference runs.", "basis": "full-text", "pdf_source_url": "", "abstract": "RRAM-based in-memory computing (IMC) effectively accelerates deep neural networks (DNNs) and other machine learning algorithms. On the other hand, in the presence of RRAM device variations and lower precision, the mapping of DNNs to RRAM-based IMC suffers from severe accuracy loss. In this work, we propose a novel hybrid IMC architecture that integrates an RRAM-based IMC macro with a digital SRAM macro using a programmable shifter to compensate for the RRAM variations and recover the accuracy. The digital SRAM macro consists of a small SRAM memory array and an array of multiply-and-accumulate (MAC) units. The nonideal output from the RRAM macro, due to device and circuit nonidealities, is compensated by adding the precise output from the SRAM macro. In addition, the programmable shifter allows for different scales of compensation by shifting the SRAM macro output relative to the RRAM macro output. On the algorithm side, we develop a framework for the training of DNNs to support the hybrid IMC architecture through ensemble learning. The proposed framework performs quantization (weights and activations), pruning, RRAM IMC-aware training, and employs ensemble learning through different compensation scales by utilizing the programmable shifter. Finally, we design a silicon prototype of the proposed hybrid IMC architecture in the 65-nm SUNY process to demonstrate its efficacy. Experimental evaluation of the hybrid IMC architecture shows that the SRAM compensation allows for a realistic IMC architecture with multilevel RRAM cells (MLCs) even though they suffer from high variations. The hybrid IMC architecture achieves up to 21.9%, 12.65%, and 6.52% improvement in post-mapping accuracy over state-of-the-art techniques, at minimal overhead, for ResNet-20 on CIFAR-10, VGG-16 on CIFAR-10, and ResNet-18 on ImageNet, respectively.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Krishnan_HybridRRAMSRAM_TCAD.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2022_Krishnan_HybridRRAMSRAM_TCAD.pdf", "priority": 6.46}, {"id": "W4312141825", "short": "Xbar-Partitioning", "title": "Xbar-Partitioning: A Practical Way for Parasitics and Noise Tolerance in Analog IMC Circuits", "authors": ["Md Hasibul Amin", "Mohammed Elbtity", "Ramtin Zand"], "year": 2022, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2022.3222966", "cites_global": 16, "cat": "06", "seed": false, "devices": ["Memristor(generic)", "PCM", "ReRAM", "MRAM"], "models": ["MLP"], "evidence": "simulation", "tldr": "Proposes horizontal/vertical partitioning of fully-analog in-memory-computing crossbars to limit interconnect-parasitic and noise degradation, finding PCM with 1T-1R cells and fine partitioning gives the best accuracy/noise tradeoff.", "summary": "Fully-analog IMC circuits perform both matrix-vector multiplication and nonlinear vector operations in the analog domain to avoid energy-hungry ADC/DAC signal converters, but this makes them far more sensitive to interconnect parasitics and noise than conventional mixed-signal IMC. The paper proposes 'Xbar-partitioning', which splits large crossbar arrays into smaller horizontal and vertical partitions with dedicated routing/accumulation circuitry (demultiplexers and switches) so that partial products from sub-arrays are recombined, shortening interconnects and reducing parasitic resistance/capacitance per partition. Using SPICE simulation of a 400x120x84x10 DNN (apparently an MNIST-scale MLP) mapped onto crossbars built from several 2-terminal and 3-terminal resistive device technologies, six bitcell layouts, and four partitioning schemes, they report that PCM devices with a 1T-1R bitcell and a specific per-layer partition configuration (13/4/3 horizontal and 4/3/1 vertical partitions for the three layers) achieve the best accuracy (98.08%). They further provide an SNR-based analysis showing that smaller bitcells, finer partitioning, and devices with higher Roff/Ron ratio improve noise tolerance.", "contributions": ["Xbar-partitioning: a circuit-level method (horizontal + vertical) to split large fully-analog IMC crossbars into smaller sub-arrays with DEMUX/switch routing to recombine partial MAC products", "SPICE-level evaluation across five device technologies (2- and 3-terminal) and six bitcell layouts on a small DNN workload", "Identification of a best configuration (PCM, 1T-1R, fine-grained per-layer partitioning) reaching 98.08% accuracy", "SNR-based noise-tolerance analysis linking partition count, bitcell size, and Roff/Ron ratio to robustness"], "claims": [{"claim": "Fine-grained partitioning recovers accuracy lost to interconnect parasitics in fully-analog IMC crossbars", "support": "best configuration (PCM, 1T-1R, 13/4/3 horizontal and 4/3/1 vertical partitions) reaches 98.08% accuracy", "loc": "Abstract"}, {"claim": "Noise tolerance improves with smaller bitcells, more partitions, and higher Roff/Ron device ratio", "support": "SNR analysis across partitioning schemes and device technologies", "loc": "Abstract / SNR analysis section"}], "results": ["Best configuration (PCM devices, 1T-1R bitcell, 13/4/3 horizontal and 4/3/1 vertical partitions across the three layers of a 400x120x84x10 DNN) achieves 98.08% accuracy"], "limitations": ["Abstract-only analysis: full text not available, so method details (routing overhead, area/energy cost of partitioning circuitry, exact SNR numbers) could not be verified from the paper itself", "Evaluated on a single small MLP-scale model (400x120x84x10), not larger CNNs or modern DNNs", "Partitioning necessarily adds peripheral circuitry (DEMUX, switches) whose area/energy overhead is not quantified in the abstract"], "remarks": "This is a companion/extension of the authors' own fully-analog IMAC line of work (IMAC co-processor, interconnect-parasitics ISCAS paper); a related 2-page preprint by the same authors (arXiv:2211.00590, 'Reliability-Aware Deployment of DNNs on In-Memory Analog Computing Architectures') covers the same partitioning idea with different device numbers, so it was not used here as a stand-in for this paper to avoid misattributing figures. The core idea — trade partitioning granularity against routing/accumulation overhead to balance parasitic/noise tolerance versus area/power — is a useful practical knob for mapping models onto fully-analog crossbars, but the evidence is simulation-only on a toy-scale model.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Conventional in-memory computing (IMC) architectures consist of analog memristive crossbars to accelerate matrix-vector multiplication (MVM), and digital functional units to realize nonlinear vector (NLV) operations in deep neural networks (DNNs). These designs, however, require energy-hungry signal conversion units which can dissipate more than 95% of the total power of the system. Fully-analog IMC circuits remove the need for signal converters by realizing both MVM and NLV operations in the analog domain leading to significant energy savings. However, they are more susceptible to errors caused by interconnect parasitic and noise. Here, we propose Xbar-partitioning, a practical approach to divide large IMC arrays into multiple partitions to alleviate the impacts of noise and parasitics while keeping the computation in the analog domain. The SPICE circuit simulation results for the deployment of a$400\\times 120\\times 84\\times 10$DNN model on various fully-analog IMC architectures with five different 2-terminal and 3-terminal resistive devices, six different bitcell layouts, and four different partitioning schemes show that the highest accuracy of 98.08% can be obtained for a design using phase-change memory (PCM) devices and 1T-1R bitcell with 13, 4, and 3 horizontal partitions, and 4, 3, and 1 vertical partition for the first, second, and third layers of the DNN, respectively. Finally, we provide a signal-to-noise ratio (SNR) analysis which shows that the IMC architectures can be made more noise-tolerant by using smaller-sized bitcells, higher partitions in the crossbar, and device technologies with higher$R_{off}/R_{on}$ratio.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Amin_XbarPartitioning_JETCAS.pdf", "analysed": true, "pdf": null, "priority": 4.76}, {"id": "W4312457094", "short": "Fault-Free", "title": "Fault-Free: A Framework for Analysis and Mitigation of Stuck-At-Fault on Realistic ReRAM-Based DNN Accelerators", "authors": ["Hyein Shin", "Myeonggu Kang", "Lee‐Sup Kim"], "year": 2022, "venue": "IEEE Transactions on Computers", "venue_short": "TC", "venue_full": "IEEE Transactions on Computers (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tc.2022.3227871", "cites_global": 16, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Proposes an offline-compilation plus lightweight online-compensation framework (Fault-Free) that mitigates stuck-at-fault errors in low-resolution ReRAM crossbars, recovering accuracy at only ~5% area and ~0.8% energy overhead versus an ideal (fault-free) accelerator.", "summary": "Low-resolution ReRAM cells used in energy-efficient DNN accelerators suffer severe stuck-at-fault (SAF) issues that corrupt a significant fraction of mapped weights and degrade inference accuracy. The paper analyzes how SAF impacts low-bit-resolution cells specifically, then proposes 'Fault-Free', a two-stage framework: an offline compilation stage that identifies indices of weights distorted by SAF and applies fault-aware weight decomposition plus closest-value mapping to minimize the resulting weight error, and an online stage that executes the DNN on the ReRAM accelerator with lightweight hardware compensation units applied selectively only to a small subset of affected weights (rather than globally), limiting hardware overhead. Evaluated across multiple DNN models on realistic ReRAM accelerator configurations, the framework restores near-ideal inference accuracy while adding only modest area (~5%) and energy (~0.8%) overhead relative to a hypothetical fault-free ReRAM accelerator.", "contributions": ["Analysis of how stuck-at-fault (SAF) severity scales with ReRAM cell bit-resolution, motivating the need for low-resolution-specific mitigation", "Offline compilation step: SAF-affected weight index extraction, fault-aware weight decomposition, and closest-value mapping to minimize mapping error before deployment", "Online lightweight compensation units applied selectively to only a small fraction of weights, reducing hardware cost versus full per-cell correction", "System-level evaluation showing accuracy recovery close to an ideal ReRAM accelerator with low area/energy overhead"], "claims": [{"claim": "Fault-Free recovers near-ideal inference accuracy on ReRAM accelerators affected by stuck-at-faults", "support": "average area overhead of 5% and energy overhead of 0.8% from an ideal ReRAM-based accelerator while preserving accuracy, across various DNN models", "loc": "Abstract"}, {"claim": "Selective online compensation (applied to only a small portion of weights) is sufficient to control hardware overhead", "support": "stated design choice reducing hardware overhead vs. full compensation", "loc": "Abstract"}], "results": ["Average area overhead ~5% and energy overhead ~0.8% versus an ideal (fault-free) ReRAM-based DNN accelerator, across multiple DNN models"], "limitations": ["Abstract-only analysis: full text unavailable, so exact SAF rates assumed, DNN models/datasets tested, and comparison baselines could not be independently verified", "Builds on the same group's prior thermal-aware ReRAM optimization work, suggesting the evaluation methodology/accelerator model may be shared/simulation-based rather than measured silicon"], "remarks": "This targets a well-known, practically important non-ideality (stuck-at-faults in low-bit-resolution ReRAM cells) with a software/compilation-centric fix rather than pure redundancy, which is attractive because it avoids blanket hardware duplication. Without the full text the precise fault models and benchmark suite can't be checked, so the reported ~5%/~0.8% overhead figures should be treated as the authors' claim pending verification; it builds directly on Shin et al.'s earlier thermal-aware ReRAM optimization line and was followed up by at least one 2025 paper (Atleus) in the same space.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive RAM(ReRAM) is gaining attention as a suitable memory platform for accelerating deep neural networks(DNNs) in an energy-efficient way. However, energy-efficient ReRAM-based DNN accelerators suffer from serious Stuck-At-Fault(SAF) issues that significantly degrade the inference accuracy. SAF is a device-level non-ideality, and the problems of SAF worsen in the realistic ReRAM with low cell resolution. To address the problem in the realistic ReRAM, we present a framework for mitigating SAF on ReRAM-based accelerators(Fault-free). We first analyze the impact of SAF on low-resolution cells. Based on the analysis, we present offline compilation, which drastically reduces the impact of SAF on inference accuracy. At the first stage, we extract indices of distorted weights due to SAF. For extracted weights, fault-aware weight decomposition and closest value mapping are applied to minimize the error of weights. In the online phase, the target DNN model is executed on the ReRAM-based accelerator along with lightweight compensation units. The online compensation is selectively performed for a small portion of weights to reduce the hardware overhead. With the proposed framework, the ReRAM-based accelerator successfully ensures the inference accuracy of various DNN models with an average area of 5% and an energy overhead of 0.8% from an ideal ReRAM-based accelerator.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Shin_FaultFree_TC.pdf", "analysed": true, "pdf": null, "priority": 5.29}, {"id": "W4280592620", "short": "WRAP", "title": "WRAP: Weight RemApping and Processing in RRAM-based Neural Network Accelerators Considering Thermal Effect", "authors": ["Po-Yuan Chen", "Fang-Yi Gu", "Yühong Huang", "Ing-Chao Lin"], "year": 2022, "venue": "", "venue_short": "DATE", "venue_full": "Design, Automation and Test in Europe Conference (DATE 2022)", "venue_ok": true, "doi": "https://doi.org/10.23919/date54114.2022.9774678", "cites_global": 15, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "WRAP is a subarray-based, thermal-aware weight remapping and processing framework that maps DNN weights onto RRAM subarrays (rather than individual cells) to reduce computational complexity while compensating for temperature-dependent resistance variation, keeping accuracy loss under 2% (1% with compensation) at ambient temperatures up to ~360K.", "summary": "RRAM-based compute-in-memory accelerators lose accuracy both from intrinsic cell-to-cell resistance variation and from temperature-dependent resistance drift, which worsens at high operating temperatures. WRAP proposes a subarray-based weight remapping and processing framework: instead of analyzing and compensating weights/cells individually, it operates on RRAM subarrays, applying subarray-level algorithms to reduce the computational complexity of thermal-aware mapping while preserving accuracy. Evaluated across four DNN models, WRAP keeps inference accuracy loss below 2% relative to the ideal (noiseless) result, and below 1% when its thermal compensation is applied, even when the surrounding temperature is around 360 K.", "contributions": ["A subarray-based (rather than per-cell) framework for mapping and remapping DNN weights onto RRAM crossbars, reducing the computational cost of thermal-aware weight placement", "Subarray-level algorithms that account for thermal effects on RRAM resistance during weight mapping", "A compensation mechanism that further reduces temperature-induced accuracy loss", "Evaluation across four DNN models demonstrating accuracy robustness up to ~360 K ambient temperature"], "claims": [{"claim": "WRAP keeps inference accuracy loss under 2% relative to the ideal result across four DNN models despite high ambient temperature.", "support": "Accuracy loss <2% at ~360K surrounding temperature without compensation", "loc": "Abstract (full text not available)"}, {"claim": "Applying WRAP's thermal compensation further reduces accuracy loss to under 1%.", "support": "Accuracy loss <1% at ~360K with compensation applied", "loc": "Abstract (full text not available)"}], "results": ["Inference accuracy loss <2% (without compensation) across four DNN models at ~360K ambient temperature", "Inference accuracy loss <1% (with thermal compensation applied) at ~360K ambient temperature"], "limitations": ["Analysis is abstract-only here (full text not accessible from this machine) -- the specific DNN models/datasets evaluated, the subarray size/granularity used, and the overhead of the remapping algorithm are not verifiable without the full text", "As a DATE architecture paper, results are expected to be simulation-based rather than measured silicon, though this could not be confirmed from the abstract alone"], "remarks": "Addresses a practically important and under-examined non-ideality -- temperature-dependent RRAM resistance variation -- with a subarray-granularity remapping approach that trades fine per-cell precision for tractable computational complexity, which is a sensible engineering compromise for thermal-aware mapping at scale. It builds directly on the same group's prior thermal-aware optimization framework (Shin et al., cited in-set) and is itself cited by later Transformer-on-CIM pipeline work (COMET-3D), suggesting the subarray-thermal-mapping idea carries forward into more complex accelerator designs; without the full text, the precise accuracy/overhead trade-off curve and generalization beyond the four tested models could not be assessed here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive random-access memory (RRAM) has shown great potential for computing in memory (CIM) to support the requirements of high memory bandwidth and low power in neuromorphic computing systems. However, the accuracy of RRAM-based neural network (NN) accelerators can degrade significantly due to the intrinsic statistical variations of the resistance of RRAM cells, as well as the negative effects of high temperatures. In this paper, we propose a subarray-based thermal-aware weight remapping and processing framework (WRAP) to map the weights of a neural network model into RRAM subarrays. Instead of dealing with each weight individually, this framework maps weights into subarrays and performs subarray-based algorithms to reduce computational complexity while maintaining accuracy under thermal impact. Experimental results demonstrate that using our framework, inference accuracy losses of four DNN models are less than 2% compared to the ideal results and 1% with compensation applied even when the surrounding temperature is around 360K.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Chen_WRAP_DATE.pdf", "analysed": true, "pdf": null, "priority": 4.74}, {"id": "W4310449176", "short": "RRAM Read Disturb", "title": "Evaluating Read Disturb Effect on RRAM based AI Accelerator with Multilevel States and Input Voltages", "authors": ["Jianan Wen", "Andrea Baroni", "Eduardo Pérez", "Markus Ulbricht", "Christian Wenger", "Milos D. Krstic"], "year": 2022, "venue": "", "venue_short": "DFT", "venue_full": "IEEE International Symposium on Defect and Fault Tolerance in VLSI and Nanotechnology Systems (DFT 2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/dft56152.2022.9962345", "cites_global": 12, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "device-experiment", "tldr": "Measures RRAM read-disturb-induced conductance drift at the device level and simulates its impact on LeNet-5/VGG-7 inference accuracy, finding that differential-pair weight mapping is more robust than single-device mapping.", "summary": "RRAM crossbars used for analog in-memory MAC computation suffer read disturb: repeated read operations with multilevel input voltages gradually drift device conductance and introduce errors over time. The authors measure this effect on fabricated RRAM devices with multilevel conductance states under different input (read) voltages, then feed the measured drift and device-to-device variability statistics into accuracy simulations of two CNN inference workloads, LeNet-5 on MNIST and VGG-7 on CIFAR-10. They compare single-device weight mapping against a differential-pair mapping scheme for robustness to the combined read-disturb and variability effects. The paper is a device-characterization-plus-system-simulation study rather than a full chip demonstration, aimed at quantifying how an underappreciated non-ideality (disturb from repeated analog reads, not just programming noise) degrades deployed DNN accuracy over operational lifetime.", "contributions": ["Experimental measurement of RRAM read disturb (conductance drift) as a function of input/read voltage and conductance level on real devices", "Incorporation of measured disturb statistics plus device-to-device variability into an accuracy simulation pipeline for CNN inference", "Benchmarking of LeNet-5/MNIST and VGG-7/CIFAR-10 under the combined non-ideality model", "Comparison of single-ended vs. differential-pair weight mapping schemes for disturb robustness"], "claims": [{"claim": "Read disturb causes measurable conductance drift in RRAM devices that depends on applied input voltage and conductance state", "support": "device measurements described in abstract/methodology", "loc": "Sec. on device measurement (abstract-only, page unknown)"}, {"claim": "Differential-pair weight mapping is more robust to read disturb and device variability than direct/single mapping", "support": "stated as main result in abstract", "loc": "Results (abstract-only, page unknown)"}], "results": ["Qualitative result only available from abstract: differential-pair mapping yields better robustness to read disturb and variability than single-device mapping for LeNet-5/MNIST and VGG-7/CIFAR-10 (no specific accuracy numbers available without full text)"], "limitations": ["Abstract-only basis: no numeric accuracy/drift figures available for this entry", "Short conference paper (DFT) — likely limited to a small number of device samples and two CNN benchmarks", "Read disturb is characterized for a specific RRAM technology; generalization to other oxide/device stacks is unclear"], "remarks": "This is a device-level reliability study that complements the broader non-ideality/noise-robustness literature (ISAAC, PRIME-era architectures) by isolating read disturb specifically, which is distinct from programming/retention noise usually modeled in mapping-robustness papers. Without full text the quantitative strength of the claims (how much accuracy drop, over how many reads) cannot be verified here; the abstract indicates it is a measured-device-plus-simulation study, which gives it more credibility than a purely analytical treatment, but the finding (differential mapping helps) is consistent with and reinforces general practice in the field (e.g., differential encoding used in PCM/RRAM chips like IBM's analog AI core and Tsinghua's RRAM macro) rather than being a novel mapping technique itself.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "RRAM technology is a promising candidate for implementing efficient AI accelerators with extensive multiply-accumulate operations. By scaling RRAM devices to the synaptic crossbar array, the computations can be realized in situ, avoiding frequent weights transfer between the processing units and memory. Besides, as the computations are conducted in the analog domain with high flexibility, applying multilevel input voltages to the RRAM devices with multilevel conductance states enhances the computational efficiency further. However, several non-idealities existing in emerging RRAM technology may degrade the reliability of the system. In this paper, we measured and investigated the impact of read disturb on RRAM devices with different input voltages, which incurs conductance drifts and introduces errors. The measured data are deployed to simulate the RRAM based AI inference engines with multilevel conductance states and input voltages. Device-to-device variability is also taken into consideration to assess the accuracy drop. Two convolutional neural networks, LeNet-5 and VGG-7, are benchmarked with MNIST and CIFAR-10 datasets, respectively. Our results show that mapping weights with differential pairs yields better robustness to read disturb and variability effects.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Wen_RRAMReadDisturb_DFT.pdf", "analysed": true, "pdf": null, "priority": 3.78}, {"id": "W4313170690", "short": "Parasitics-Partitioning", "title": "Interconnect Parasitics and Partitioning in Fully-Analog In-Memory Computing Architectures", "authors": ["Md Hasibul Amin", "Mohammed Elbtity", "Ramtin Zand"], "year": 2022, "venue": "", "venue_short": "ISCAS", "venue_full": "IEEE International Symposium on Circuits and Systems (ISCAS 2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/iscas48785.2022.9937884", "cites_global": 13, "cat": "06", "seed": false, "devices": ["Memristor(generic)", "MRAM"], "models": ["MLP"], "evidence": "simulation", "tldr": "SPICE-level study showing interconnect RC parasitics in fully-analog (MVM+activation-in-array) IMC crossbars collapse MNIST accuracy to ~15%, and an analog horizontal/vertical array-partitioning scheme recovers it to 94.84%.", "summary": "Fully-analog IMC architectures perform both matrix-vector multiplication and nonlinear activation inside the same memristive array to avoid ADC/DAC conversion, but this leaves the whole pipeline exposed to interconnect wire resistance and capacitance, which grow with array size. The paper models wire parasitics (Fuchs-Sondheimer/Mayadas-Shatzkes scattering-corrected resistivity, Sakurai-Tamaru capacitance) and simulates a 400x120x84x10 MNIST MLP in SPICE using a 14nm FinFET PTM and SOT-MRAM synapse/sigmoid-neuron bitcells. Without mitigation, large unpartitioned crossbars (512x512) degrade accuracy to ~10%; the authors propose analog horizontal and vertical partitioning (splitting arrays and accumulating partial products via DEMUX/switch circuitry, still entirely in the analog domain) to shorten wire lengths. With heavy partitioning (32x32 effective subarrays, HP=[16,8,8], VP=[8,8,1]) accuracy recovers to 94.84%, close to the ~97% digital CPU baseline, at the cost of higher power (3.375W vs <1W for coarser partitioning) and lower array utilization. A second experiment with a non-ideal (larger) bitcell layout shows the same partitioning mechanism can compensate for layout-induced parasitics, cutting a ~55% accuracy drop to <1%.", "contributions": ["Analytical model of interconnect wire resistance/capacitance in fully-analog (compute+activation-in-array) IMC crossbars, including size-dependent resistivity scattering effects", "SPICE-level case study quantifying how parasitics alone can reduce a 3-layer MNIST MLP's accuracy from ~97% to ~15% or lower as array size grows", "An all-analog horizontal and vertical partitioning scheme (DEMUX + switch control) that reduces effective wire length without converting to digital", "Demonstration that partitioning recovers accuracy to 94.84% at a quantified power cost, and that it also compensates for non-ideal (larger) synapse bitcell layouts"], "claims": [{"claim": "Without partitioning, growing fully-analog IMC array size severely degrades accuracy due to interconnect parasitics", "support": "512x512 unpartitioned array achieves only 10.42% accuracy vs 94.84% for a heavily partitioned 32x32-equivalent layout", "loc": "Table I, Sec. V"}, {"claim": "Analog partitioning recovers near-digital accuracy on MNIST for the fully-analog architecture", "support": "94.84% accuracy with HP=[16,8,8], VP=[8,8,1] vs ~97% digital CPU baseline", "loc": "Sec. V, Table I"}, {"claim": "Accuracy recovery via partitioning comes at a power cost", "support": "Power rises to 3.375W for the most partitioned, highest-accuracy configuration vs as low as 0.826-0.927W for lightly partitioned, lower-accuracy ones", "loc": "Table I"}, {"claim": "Partitioning also compensates for non-ideal (larger) bitcell layout parasitics", "support": "Accuracy drop of ~55% (28.44% vs near-ideal) for HP=[7,2,2]/VP=[2,2,1] non-ideal layout reduces to <1% drop (94.04%) for HP=[16,8,8]/VP=[8,8,1]", "loc": "Table II, Sec. V"}], "results": ["94.84% MNIST accuracy with 32x32 effective subarrays, HP=[16,8,8], VP=[8,8,1] vs ~97% digital CPU baseline", "Accuracy collapses to 10.42%-15.43% for 512x512 to 128x128 arrays without adequate partitioning", "Power consumption of 3.375W for the best-accuracy highly-partitioned configuration vs 0.826-2.640W for less-partitioned configurations", "Non-ideal bitcell layout: accuracy drop reduced from ~55% to <1% via heavy partitioning (94.04% vs 11.35-73.64% for other configs)"], "limitations": ["Evaluated only on a small 3-layer MLP (400-120-84-10) for MNIST, not CNNs or larger models", "SPICE-level circuit simulation only; no fabricated silicon", "Device model is SOT-MRAM-specific; parasitic trends may differ for ReRAM/PCM with different bitcell geometries", "Partitioning trades power and area utilization for accuracy, and this tradeoff is only characterized for a few discrete configurations, not optimized"], "remarks": "Short conference paper (ISCAS) that makes a narrow but important point for mapping: fully-analog (compute+nonlinearity in-array) IMC designs trade ADC/DAC removal for extreme sensitivity to interconnect RC parasitics, and this sensitivity must be addressed at the mapping/partitioning level rather than purely at the device level. Evidence is limited to SPICE simulation of a tiny MLP, so the magnitude of the effect for larger, deeper networks is unverified, but it is a useful, concrete illustration of why 'analog-all-the-way' architectures need array-partitioning-aware mapping strategies. A direct extension, 'Xbar-Partitioning,' is already listed as citing this work.", "basis": "full-text", "pdf_source_url": "", "abstract": "Fully-analog in-memory computing (IMC) architectures that implement both matrix-vector multiplication and nonlinear vector operations within the same memory array have shown promising performance benefits over conventional IMC systems due to the removal of energy-hungry signal conversion units. However, maintaining the computation in the analog domain for the entire deep neural network (DNN) comes with potential sensitivity to interconnect parasitics. Thus, in this paper, we investigate the effect of wire parasitic resistance and capacitance on the accuracy of DNN models deployed on fully-analog IMC architectures. Moreover, we propose a partitioning mechanism to alleviate the impact of the parasitic while keeping the computation in the analog domain through dividing large results for a $400 \\times 120 \\times 84 \\times 10$ DNN model deployed on a results for a $400 \\times 120 \\times 84 \\times 10$ DNN model deployed on a fully-analog IMC circuit show that a 94.84 % accuracy could be achieved for MNIST classification application with 16,8, and 8 horizontal partitions, as well as 8,8, and 1 vertical partitions for first, second, and third layers of the DNN, respectively, which is comparable to the $\\sim 97$ % accuracy realized by digital implementation on CPU. It is shown that accuracy benefits are extra circuitry required for handling partitioning.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Amin_ParasiticsPartitioning_ISCAS.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2022_Amin_ParasiticsPartitioning_ISCAS.pdf", "priority": 4.7}, {"id": "W4285122104", "short": "Offline Training IR-Drop Mitigation", "title": "Offline Training-Based Mitigation of IR Drop for ReRAM-Based Deep Neural Network Accelerators", "authors": ["Sugil Lee", "Mohammed E. Fouda", "Jongeun Lee", "Ahmed M. Eltawil", "Fadi Kurdahi"], "year": 2022, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2022.3177002", "cites_global": 17, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Two neural-network IR-drop predictor models, trained to match SPICE-level 'golden' validation, are incorporated into DNN training (with incremental retraining) to recover accuracy lost to interconnect IR drop in ReRAM crossbars, avoiding expensive per-design SPICE simulation.", "summary": "Technology scaling increases ReRAM crossbar interconnect resistance, causing IR drops that degrade signal integrity and limit accelerator performance; predicting this effect normally requires expensive hardware emulation or SPICE simulation. The authors propose two neural-network models that predict IR-drop impact on DNN computation, validated to track SPICE-based ('golden') DNN accuracy closely across binary and quantized neural networks. These predictor models are then embedded into the DNN training framework so the network can be retrained (including via proposed incremental training methods) to compensate for IR-drop-induced errors ahead of deployment. SPICE-validated results on datasets including CIFAR-10 and SVHN show large performance recovery relative to baseline (non-IR-drop-aware) training, closing the gap to the SPICE golden-validation accuracy.", "contributions": ["Two neural-network models that predict the accuracy/computation impact of IR drop in ReRAM crossbars without requiring per-case SPICE simulation", "Validation of these predictor models against SPICE-based ('golden') DNN accuracy across binary and quantized DNNs", "Incorporation of the IR-drop predictor models directly into the DNN training loop to retrain networks for IR-drop robustness", "Incremental training methods proposed to further improve validation accuracy of the IR-drop-aware retraining", "SPICE-based validation on CIFAR-10 and SVHN confirming large accuracy recovery close to baseline performance"], "claims": [{"claim": "The proposed IR-drop prediction models can substitute for expensive SPICE simulation while tracking SPICE-validated DNN accuracy closely.", "support": "Prediction models show similar performance (recognition accuracy) to golden SPICE-based DNN validation across binary and quantized DNN models", "loc": "Abstract (full text not available)"}, {"claim": "Retraining DNNs using the IR-drop prediction models (with incremental training) substantially recovers accuracy lost to IR drop, even on challenging datasets.", "support": "SPICE-simulation-validated results show very high performance improvement close to baseline performance on datasets including CIFAR-10 and SVHN", "loc": "Abstract (full text not available)"}], "results": ["IR-drop predictor models match SPICE-based 'golden' DNN validation accuracy across binary and quantized DNNs (per abstract; no specific numeric accuracy given)", "Incremental IR-drop-aware retraining yields large accuracy recovery, validated via SPICE simulation, on CIFAR-10 and SVHN (per abstract; specific percentage figures not given)"], "limitations": ["Analysis is abstract-only here (full text not accessible from this machine) -- the exact predictor-model architecture, crossbar/wire-resistance assumptions, and quantitative accuracy-recovery numbers are not verifiable without the full text", "Approach is evaluated via SPICE simulation as the 'golden' reference rather than measured silicon; real-chip IR-drop behavior could differ from the SPICE model used"], "remarks": "Tackles IR drop -- a non-ideality that worsens specifically with technology scaling and larger crossbars -- via a learned, SPICE-free predictor embedded in training, which is an efficient alternative to the expensive per-design circuit simulation used by other IR-drop-aware training works in this collection (e.g., IR-QNN Framework, cited in-set by this same group). The approach is methodologically consistent with the broader 'hardware-aware/non-ideality-aware training' trend seen elsewhere in this collection (D-NAT, NEAT, nonideality-aware training), applied specifically to the IR-drop non-ideality; without the full text, how well the learned predictors generalize across crossbar sizes/process corners beyond the tested binary/quantized networks could not be assessed here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Recently, resistive RAM (ReRAM)-based hardware accelerators showed unprecedented performance compared the digital accelerators. Technology scaling causes an inevitable increase in interconnect wire resistance, which leads to IR drops that could limit the performance of ReRAM-based accelerators. These IR drops deteriorate the signal integrity and quality, especially in the crossbar structures which are used to build high-density ReRAMs. Hence, finding a software solution, which can predict the effect of IR drop without involving expensive hardware or SPICE simulations, is very desirable. In this article, we propose two neural networks models to predict the impact of the IR drop problem. These models are used to evaluate the performance of the different deep neural network (DNN) models including binary and quantized neural networks showing similar performance (i.e., recognition accuracy) to the golden validation (i.e., SPICE-based DNN validation). In addition, these predication models are incorporated into the DNN training framework to efficiently retrain the DNN models and bridge the accuracy drop. To further enhance the validation accuracy, we propose incremental training methods. The DNN validation results, done through SPICE simulations, show very high improvement in performance close to the baseline performance, which demonstrates the efficacy of the proposed method even with challenging datasets, such as CIFAR10 and SVHN.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2022_Lee_OfflineTrainingIRDropMitigation_TCAD.pdf", "analysed": true, "pdf": null, "priority": 3.88}, {"id": "W3180792321", "short": "RRAM Program/Verify Schemes", "title": "Accurate Program/Verify Schemes of Resistive Switching Memory (RRAM) for In-Memory Neural Network Circuits", "authors": ["Valerio Milo", "Artem Glukhov", "Eduardo Pérez", "Cristian Zambelli", "Nicola Lepri", "Mamathamba Kalishettyhalli Mahadevaiah", "Emilio Pérez-Bosch Quesada", "Piero Olivo", "Christian Wenger", "Daniele Ielmini"], "year": 2021, "venue": "IEEE Transactions on Electron Devices", "venue_short": "TED", "venue_full": "IEEE Transactions on Electron Devices", "venue_ok": true, "doi": "https://doi.org/10.1109/ted.2021.3089995", "cites_global": 107, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "device-experiment", "tldr": "Compares three multilevel-cell (MLC) program/verify algorithms on a fabricated 4-kbit 1T1R HfO2 RRAM array (ISPVA, IGVVA-100, IGVVA-10) and shows gate-voltage-controlled incremental programming with a fine voltage step (IGVVA-10) gives the lowest device-to-device variability, enabling a 2-layer FC-NN on MNIST to reach 96.58% inference accuracy (vs. 96.77% FP-64 software) with 19 differential weight levels, while quantifying the accuracy/current/IR-drop trade-offs of the weight-mapping choice.", "summary": "The paper addresses the limited conductance precision of RRAM used as synaptic weights in in-memory-computing (IMC) neural network accelerators. Using a fabricated 64x64 (4-kbit) 1T1R HfO2-based RRAM array, the authors experimentally compare three multilevel-cell program/verify schemes: top-electrode-voltage-controlled incremental step pulse (ISPVA) versus gate-voltage-controlled incremental schemes with coarse (IGVVA-100) and fine (IGVVA-10) voltage steps. They show IGVVA-10 achieves the shallowest conductance-vs-pulse slope and lowest device-to-device (D2D) variability of the three. Using measured conductance CDFs from IGVVA-10 (up to 9 levels, 19 differential weights via a G+/G- differential encoding scheme), they map the weights of an offline-trained 2-layer fully-connected neural network (197-20-10, MNIST-14x14) onto the array and compute inference accuracy in simulation as a function of weight-mapping combination, number of conductance levels, mapping step size, hidden-layer size, and parasitic IR drop in 32x32-tiled crossbars. The best configuration reaches 96.58% accuracy, close to the 96.77% FP-64 software baseline, while current consumption and IR-drop sensitivity grow with the chosen conductance levels, illustrating a fundamental accuracy-vs-energy/area trade-off that the authors argue requires device-circuit-algorithm co-design.", "contributions": ["Experimental comparison of three MLC program/verify algorithms (ISPVA, IGVVA-100, IGVVA-10) on a fabricated 4-kbit 1T1R HfO2 RRAM array, identifying gate-voltage control with fine step as most accurate", "Extension of conductance levels to 9 LRS states (19 differential synaptic weights) with measured after-switching (AS) and end-of-algorithm (EA) conductance CDFs capturing post-programming relaxation", "A differential weight-mapping study (G+/G- combinations) quantifying the trade-off between weight precision (lowest sigma_W), current consumption, and IR-drop sensitivity", "Simulation of inference accuracy for a 2-layer FC-NN (MNIST, 14x14 downsampled) as a function of number of weight levels, mapping step, hidden-layer size, and parasitic wire resistance across 32x32-tiled crossbars"], "claims": [{"claim": "Gate-voltage-controlled incremental programming (IGVVA) with the smallest voltage step gives the lowest device-to-device conductance variability compared to top-electrode-voltage-controlled ISPVA", "support": "IGVVA-10 shows lowest D2D variability in both AS and EA CDFs; reducing delta-VG from 100 mV to 10 mV significantly decreases LRS conductance standard deviation", "loc": "Sec. III, Fig. 4"}, {"claim": "Best achievable weight-mapping combination (C10, lowest sigma_W) raises FC-NN inference accuracy close to the floating-point software baseline", "support": "C10 achieves 96.58% MNIST test accuracy vs. 96.77% FP-64 software accuracy (0.19 percentage-point gap); improvement from C1 to C10 is 0.15 percentage points", "loc": "Sec. V, Fig. 8(a)"}, {"claim": "Higher-accuracy weight mappings require larger conductances, incurring roughly 5x more current consumption than the lowest-current mapping", "support": "current consumption at C10 is about five times that at C1", "loc": "Sec. V, Fig. 8(b)"}, {"claim": "IR drop from parasitic wire resistance degrades inference accuracy more severely for larger crossbar arrays and higher conductance (current) mappings", "support": "simulated accuracy drop increases with parasitic resistance r (0 to 3 Ohm) and with increasing crossbar size Nrow for r = 1, 3, 5 Ohm", "loc": "Sec. V, Fig. 8(c)-(d)"}, {"claim": "Increasing the number of discrete conductance levels from 9 to 19 improves inference accuracy more than increasing conductance values alone, and more so under IGVVA-10 than the other two algorithms", "support": "Fig. 9(a): accuracy improves from 9 to 19 levels for ISPVA, IGVVA-100, IGVVA-10, with IGVVA-10 giving highest improvement", "loc": "Sec. V, Fig. 9"}], "results": ["Best weight-mapping combination (C10) achieves 96.58% MNIST test accuracy vs. 96.77% FP-64 software baseline with NH=100 hidden neurons and 19 differential weight levels (Fig. 8a)", "Current consumption at the highest-accuracy mapping (C10) is ~5x that of the lowest-current mapping (C1) (Fig. 8b)", "Increasing hidden-layer size from NH=20 to NH=100 (with 19 weight levels) raises accuracy from 92% to 96.2% (Sec. V)", "IGVVA-10 requires 121 programming pulses (vs 16 for ISPVA) due to its smaller voltage step, trading programming time for precision (Sec. III)"], "limitations": ["Demonstrated only on a small 2-layer fully-connected network (197-20-10) on a downsampled 14x14 MNIST, not on CNNs or larger/modern workloads", "Inference accuracy results for arrays larger than the measured 4-kbit/32x32 tiles (IR drop study) are obtained by simulation, not direct measurement", "Weight programming and mapping are evaluated for a single fabricated technology (TiN/Ti/HfO2/TiN 1T1R, 0.25 micron CMOS); generality to other RRAM stacks not addressed", "Does not include retention/endurance degradation over long time scales beyond the immediate AS-to-EA relaxation window", "Trade-off analysis (accuracy vs current vs IR drop vs area) is empirical/case-specific rather than a general optimization framework"], "remarks": "This is a device-level experimental study from the Ielmini/Wenger groups (Politecnico di Milano / IHP) that cleanly quantifies how MLC program/verify algorithm choice translates into neural-network inference accuracy on real fabricated RRAM, directly complementing the companion IRPS 2021 paper by Pedretti, Ambrosi and Ielmini (also in this collection) on conductance variation effects. Its main value for mapping AI models onto analog crossbars is the explicit, measured trade-off between device programming precision, weight-mapping choice (differential encoding), current/IR-drop cost, and achieved accuracy — a quantitative example of the device-circuit-algorithm co-design argument repeated across many non-ideality papers in this set, though demonstrated only on a small MLP rather than a modern CNN/Transformer workload.", "basis": "full-text", "pdf_source_url": "", "abstract": "Resistive switching memory (RRAM) is a promising technology for embedded memory and its application in computing. In particular, RRAM arrays can provide a convenient primitive for matrix-vector multiplication (MVM) with strong impact on the acceleration of neural networks for artificial intelligence (AI). At the same time, RRAM is affected by intrinsic conductance variations, which might cause degradation of accuracy in AI inference hardware. This work provides a detailed study of the multilevel-cell (MLC) programming of RRAM for neural network applications. We compare three MLC programming schemes and discuss their variations in terms of the different slopes in the programming characteristics. We test the accuracy of a two-layer fully connected neural network (FC-NN) as a function of the MLC scheme, the number of weight levels, and the weight mapping configuration. We find a tradeoff between the FC-NN accuracy, size, and current consumption. This work highlights the importance of a holistic approach to AI accelerators encompassing the device properties, the overall circuit performance, and the AI application specifications.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2021_Milo_RRAMProgramVerify_TED.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2021_Milo_RRAMProgramVerify_TED.pdf", "priority": 5.85}, {"id": "W3174812964", "short": "IR-Drop Fault Mitigation RRAM", "title": "Efficient and Optimized Methods for Alleviating the Impacts of IR-Drop and Fault in RRAM Based Neural Computing Systems", "authors": ["Chenglong Huang", "Nuo Xu", "Keni Qiu", "Yujie Zhu", "Desheng Ma", "Liang Fang"], "year": 2021, "venue": "IEEE Journal of the Electron Devices Society", "venue_short": "JEDS", "venue_full": "IEEE Journal of the Electron Devices Society", "venue_ok": true, "doi": "https://doi.org/10.1109/jeds.2021.3093478", "cites_global": 44, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Proposes two circuit-level mitigation methods -- an additional tunable RRAM row and a trans-impedance-amplifier (TIA) based RRAM scheme -- to recover computation accuracy lost to IR-drop and stuck-at-faults in RRAM crossbar-array DNN accelerators, evaluated via simulation on LeNet-5/MNIST and VGG16/CIFAR-10 across different crossbar sizes and resistance levels.", "summary": "The paper addresses two coupled non-idealities in RRAM crossbar array (RRAM CBA) based DNN accelerators: IR-drop (voltage/current variation along crossbar rows/columns due to wire and device resistance) and stuck-at-faults (SAF), both of which are often ignored during direct weight-to-crossbar mapping but which significantly degrade computation accuracy via multiplication-and-accumulation errors that violate the ideal Kirchhoff's-law-based MAC assumption. The authors propose two optimized methods: (1) adding an extra tunable RRAM row to compensate for output column current variation, and (2) a trans-impedance-amplifier (TIA) based RRAM scheme to reduce variation in output voltage per column. Both methods are evaluated across different RRAM crossbar array sizes and RRAM resistance levels, using LeNet-5 on MNIST and VGG16 on CIFAR-10 as benchmark networks, showing suppressed accuracy degradation from IR-drop and SAF effects.", "contributions": ["Joint consideration of IR-drop and stuck-at-fault (SAF) non-idealities together in RRAM crossbar array DNN accelerator design, rather than treating them in isolation", "An additional-tunable-RRAM-row method to reduce output column current variation caused by IR-drop/SAF", "A trans-impedance-amplifier (TIA) based RRAM scheme to reduce output voltage variation per column", "Evaluation of both methods across varying crossbar array sizes and RRAM resistance levels on two benchmark networks (LeNet-5/MNIST, VGG16/CIFAR-10)"], "claims": [{"claim": "Direct mapping of DNN weights onto RRAM crossbar arrays without accounting for IR-drop and SAF is unrealistic due to resulting computation-accuracy degradation", "support": "motivating analysis in the abstract", "loc": "Abstract"}, {"claim": "The two proposed optimized methods (tunable RRAM row; TIA-based RRAM) further suppress computing-accuracy degradation induced by IR-drop and SAF", "support": "simulation results across different crossbar sizes and resistance levels for LeNet-5/MNIST and VGG16/CIFAR-10", "loc": "Abstract / simulation results"}], "results": ["Simulation-based demonstration that both proposed methods reduce accuracy degradation from IR-drop and SAF for LeNet-5 on MNIST and VGG16 on CIFAR-10 across varying crossbar sizes and resistance levels (specific accuracy/overhead percentages not given in the abstract)"], "limitations": ["Full text not available to this review (open-access PDF exists only via IEEE Xplore, which is outside this environment's accessible sources); specific quantitative accuracy and hardware-overhead numbers could not be captured beyond the abstract", "Analysis based only on the abstract; the exact circuit overhead (area/energy) of the additional tunable row and TIA-based scheme relative to baseline is unknown from the abstract alone", "Evaluated only on two relatively small/older benchmark networks (LeNet-5, VGG16), not on modern Transformer or large-CNN workloads"], "remarks": "This paper addresses IR-drop and stuck-at-fault jointly, which is a useful complement to papers in this set that treat these non-idealities separately (e.g., the unary-coding/variation-aware mapping paper, the Milo et al. program/verify paper). It is cited by at least one later IR-drop-mitigation training paper (Offline Training-Based Mitigation of IR Drop for ReRAM-Based DNN Accelerators) in this collection's forward citations. The paper is gold open access (CC-BY) but hosted only on IEEE Xplore, which per this review's sourcing rules could not be downloaded, so this entry remains abstract-only despite being technically open access.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive switching random access memory (RRAM) shows its potential to be a promising candidate as the basic in-memory computing unit for deep neural networks (DNN) accelerator design due to its non-volatile, low power, and small footprint properties. The RRAM based crossbar array (RRAM CBA) is usually employed to accelerate DNN because of its intrinsic characteristic of executing multiplication-and-accumulation (MAC) operation according to Kirchhoffs' law. However, some major non-ideal effects including IR-drop and Stuck-at-Faults (SAF) in real RRAM CBA are typically ignored in the DNN accelerator design because of the considerations of training speed and design closure. Such non-ideal effects will conduct the variations of output column current and voltage and further cause serious degradation in computing accuracy. Thus, direct mapping from the weights of DNN model without considering the IR-drop and SAF to RRAM CBA is unrealistic. In this work, two efficient and optimized methods including adding additional tunable RRAM row and Trans-impedance amplifier (TIA) based RRAM are proposed to recover the computation accuracy with a view to reducing variation of the output column current of the RRAM CBA and output voltage of the TIA in each column respectively. The two optimized methods are evaluated in different sizes of RRAM CBA and different resistance levels of RRAM cell. The simulation results show that the two optimized methods can further suppress the degradation of computing accuracy induced by IR-drop and SAF for LeNet-5 with the MNIST dataset and VGG16 with the CIFAR-10 dataset.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2021_Huang_IRDropFaultMitigation_JEDS.pdf", "analysed": true, "pdf": null, "priority": 5.06}, {"id": "W3157191380", "short": "Conductance Variations IMC", "title": "Conductance variations and their impact on the precision of in-memory computing with resistive switching memory (RRAM)", "authors": ["Giacomo Pedretti", "Elia Ambrosi", "Daniele Ielmini"], "year": 2021, "venue": "", "venue_short": "IRPS", "venue_full": "2021 IEEE International Reliability Physics Symposium (IRPS 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/irps46558.2021.9405130", "cites_global": 36, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": [], "evidence": "analytical", "tldr": "A reliability-physics perspective on RRAM conductance variation in in-memory computing: characterizes conductance variation/stability and its impact on matrix-vector-multiplication accuracy, then compares mapping strategies (multilevel, binary, unary, redundancy, slicing) for robustness, concluding there is a fundamental accuracy-vs-area tradeoff requiring co-design of precise/stable devices with error-tolerant mapping schemes.", "summary": "The paper examines RRAM reliability from the specific angle of conductance variation and its impact on in-memory computing (IMC) accuracy, given that matrix-vector multiplication (MVM) executed in the analog domain is inherently sensitive to imprecision in the stored conductance weights. Focusing on RRAM as the representative IMC device, the authors describe conductance variation and time-stability behavior and relate it to computation error. They then survey and compare several coefficient-mapping strategies used to represent synaptic weights in RRAM arrays -- multilevel, binary, unary, redundancy, and slicing schemes -- evaluating their robustness to conductance error. The paper's central conclusion is that a tradeoff exists between IMC accuracy and memory array area, implying that accurate IMC circuits require co-design of highly-precise/stable devices together with error-tolerant mapping and computing schemes.", "contributions": ["A characterization of RRAM conductance variation and stability over time and its direct link to MVM computation error in IMC", "A comparative discussion of weight-mapping/coding strategies (multilevel, binary, unary, redundancy, slicing) in terms of their robustness to conductance variation", "Articulation of a general accuracy-vs-area tradeoff principle for IMC circuit design, arguing for co-design across device, mapping, and application levels"], "claims": [{"claim": "A tradeoff exists between IMC accuracy and memory area occupation, depending on the chosen weight-mapping/coding scheme", "support": "comparative analysis of multilevel, binary, unary, redundancy and slicing mapping schemes", "loc": "Abstract"}, {"claim": "Accurate IMC circuits require co-design of highly precise, highly stable devices together with error-tolerant mapping/computing schemes", "support": "overall conclusion of the comparative mapping analysis", "loc": "Abstract / Conclusion"}], "results": [], "limitations": ["Full text not available to this review; the quantitative basis for the accuracy-vs-area tradeoff claims and the detail of each mapping scheme's evaluation could not be verified beyond the abstract", "Analysis based only on the abstract; it is unclear whether new experimental/simulation data or only a synthesis of prior results is presented for each mapping scheme", "No specific neural network benchmark or quantitative error/accuracy numbers appear in the abstract"], "remarks": "This paper functions as a reliability-physics-oriented overview connecting RRAM conductance variation/stability to the full landscape of weight-mapping strategies used across the crossbar-accelerator literature (multilevel vs. unary vs. redundancy vs. slicing), and is cited by the companion Milo et al. program/verify paper (also in this collection) and later variation-tolerant mapping work. Its value is primarily as a conceptual/comparative framework for the accuracy-area-robustness tradeoff space rather than a single new result; full-text verification was not possible from this environment, so this entry is abstract-only.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "This work addresses the reliability of RRAM, with a focus on conductance variation and its impact on in-memory computing (IMC). The core advantage of IMC is the ability to execute matrix-vector multiplication (MVM) in one step in crosspoint memory arrays, which can significantly accelerate data-intensive computing tasks, such as the inference and training of deep neural networks (DNNs). Since MVM is executed in the analogue domain, the imprecision of weight parameters stored in the memory array can result in errors which can affect the accuracy of the computation. By referring to a typical IMC device, that is the resistive switching memory (RRAM), we describe the conductance variations and stability with time, highlighting their impact on IMC accuracy. Then we discuss various options for mapping coefficients in the memory device, including multilevel, binary, unary, redundancy and slicing schemes, and their robustness with respect to conductance errors. It turns out that a tradeoff exists between accuracy and memory area occupation in the IMC circuit. Accurate IMC circuits thus must rely on the co-design of highly-precise, highly-stable devices and error tolerant mapping/computing schemes.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2021_Pedretti_ConductanceVariationsIMC_IRPS.pdf", "analysed": true, "pdf": null, "priority": 5.9}, {"id": "W3162727751", "short": "Pruning + Differential Mapping", "title": "Improving DNN Fault Tolerance using Weight Pruning and Differential Crossbar Mapping for ReRAM-based Edge AI", "authors": ["Geng Yuan", "Zhiheng Liao", "Xiaolong Ma", "Yuxuan Cai", "Zhenglun Kong", "Xuan Shen", "Jingyan Fu", "Zhengang Li", "Chengming Zhang", "Hongwu Peng", "Ning Liu", "Ao Ren", "Jinhui Wang", "Yanzhi Wang"], "year": 2021, "venue": "", "venue_short": "ISQED", "venue_full": "22nd International Symposium on Quality Electronic Design (ISQED 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/isqed51717.2021.9424332", "cites_global": 36, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["ResNet", "CNN", "YOLOv4"], "evidence": "algorithm+simulation", "tldr": "Uses unstructured (ADMM) weight pruning plus a 'differential' two-cell mapping that encodes zero weights as both cells at high conductance, so that stuck-off and (5.2x more frequent) stuck-on faults more often coincide with the intended cell value, tolerating roughly 10x higher stuck-at-fault rates than standard two-column mapping without per-chip retraining.", "summary": "Stuck-at-faults (SAF) in ReRAM crossbars cause mismatch between trained and mapped weights; existing fixes (defect-aware retraining, row/column permutation, redundant columns) need per-chip optimization, impractical for mass-produced IoT devices. The authors observe that pruned (zero) weights mapped to low conductance are immune to stuck-off faults, and propose a hierarchical progressive pruning algorithm that increases pruning ratio block-by-block while monitoring fault-injected accuracy, finding a sweet spot (e.g. ~0.6 for ResNet18/CIFAR-10). Because stuck-on faults are reported to be 5.2x more frequent, they introduce a differential mapping where w = wa - wb with one cell always at 1 (max conductance) and zero weights mapped to (1,1), converting pruning-induced sparsity into stuck-on tolerance at no extra hardware compared to two-column mapping with a subtractor. Fault injection is done in PyTorch at weight level (100 runs averaged) on ResNet18 (CIFAR-10, ImageNet) and YOLOv4 (MS COCO), showing roughly an order of magnitude higher tolerable failure rate than unpruned two-column mapping.", "contributions": ["Reframes unstructured pruning as a chip-agnostic fault-tolerance technique for ReRAM DNN inference (no per-device optimization)", "Hierarchical progressive pruning that searches block-wise pruning ratios under fault injection; shows non-monotonic relation between sparsity and SAF robustness", "Differential crossbar mapping (zero -> both cells high) that turns sparsity into stuck-on fault tolerance with the same two-column + subtractor hardware", "Evaluation on classification (ResNet18 CIFAR-10/ImageNet) and detection (YOLOv4 on COCO)"], "claims": [{"claim": "Offset-based (single-column) mapping is far less SAF-tolerant than two-column mapping", "support": "Fig. 2: 'both mapping methods suffer severe accuracy loss compared to the ideal case, where the offset method shows much worse tolerance to the defect'", "loc": "Sec. III, Fig. 2"}, {"claim": "SAF-induced accuracy drop vs pruning ratio is non-monotonic, minimum near 0.6 for ResNet18/CIFAR-10", "support": "'the accuracy drop caused by the stuck-off fault decreases and reaches its minimum value at the pruning ratio of 0.6, then the accuracy drop goes up again'", "loc": "Sec. IV-B, Fig. 3"}, {"claim": "Pruning reduces stuck-off-induced ImageNet error", "support": "'mitigated by up to 2% (Top-1 error) ... under a 0.3 pruning ratio with a 0.024 fault rate'", "loc": "Sec. IV-B, Fig. 4"}, {"claim": "Combined method keeps CIFAR-10 accuracy at fault rates where two-column mapping collapses", "support": "At 0.001 failure rate: 0.2% drop vs 1.2% for traditional mapping; traditional collapses at 0.005 while proposed preserves high accuracy at 0.01", "loc": "Sec. V-B, Fig. 6"}, {"claim": "Roughly 10x higher failure-rate tolerance at no extra hardware cost", "support": "'our method can tolerate almost an order of magnitude higher failure rate than the traditional two-column method'", "loc": "Sec. V-B, Figs. 6-7"}], "results": ["ResNet18/CIFAR-10 baseline 94.1%; at SAF rate 0.001 accuracy drop 0.2% (proposed) vs 1.2% (two-column)", "Two-column mapping collapses around SAF rate 0.005; proposed retains high accuracy up to 0.01 (CIFAR-10)", "ResNet18/ImageNet: pruning (ratio 0.3) cuts stuck-off-induced Top-1 drop by up to 2% at 0.024 fault rate", "YOLOv4/COCO: improved mAP retention over fault rates 1e-4 to 2e-3 (Fig. 7, values only graphical)"], "limitations": ["Pure weight-level fault injection in PyTorch; no circuit model (no IR drop, ADC, conductance variation, or device nonlinearity)", "Assumes binary/ideal cells and a specific SAF ratio (stuck-off:stuck-on = 1:5.2 from one march-test study); benefit hinges on stuck-on dominance", "Differential mapping stores zero (and many weights) with one or both cells at maximum conductance, which raises array current, power and IR drop — not analysed", "Unstructured sparsity yields no hardware savings on crossbars; pruning ratio search itself is a model-level (not device-level) optimisation requiring fault-injected evaluation", "4-page workshop-style paper; ImageNet/COCO results shown only graphically, no comparison against retraining/remapping SAF methods"], "remarks": "An interesting cheap, chip-agnostic idea: choose the weight-to-conductance encoding so that the most likely fault state coincides with the most common weight value (zero after pruning). This is a mapping-level insight relevant to anyone designing differential-pair encodings, but the trade-off is significant: mapping zeros to (Gmax, Gmax) maximises read current and IR drop, the opposite of what parasitic-aware works (e.g. Zhang & Hu, IR-QNN) recommend. Evidence is weight-level simulation only; FORMS (same group) later built on polarized/fine-grained mapping ideas.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2106.09166", "abstract": "Recent research demonstrated the promise of using resistive random access memory (ReRAM) as an emerging technology to perform inherently parallel analog domain in-situ matrix-vector multiplication-the intensive and key computation in deep neural networks (DNNs). However, hardware failure, such as stuck-at-fault defects, is one of the main concerns that impedes the ReRAM devices to be a feasible solution for real implementations. The existing solutions to address this issue usually require an optimization to be conducted for each individual device, which is impractical for mass-produced products (e.g., IoT devices). In this paper, we rethink the value of weight pruning in ReRAM-based DNN design from the perspective of model fault tolerance. And a differential mapping scheme is proposed to improve the fault tolerance under a high stuck-on fault rate. Our method can tolerate almost an order of magnitude higher failure rate than the traditional two-column method in representative DNN tasks. More importantly, our method does not require extra hardware cost compared to the traditional two-column mapping scheme. The improvement is universal and does not require the optimization process for each individual device.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2021_Yuan_PruningDifferentialMapping_ISQED.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2021_Yuan_PruningDifferentialMapping_ISQED.pdf", "priority": 5.0}, {"id": "W3119537022", "short": "Unary Optimal Mapping", "title": "Unary Coding and Variation-Aware Optimal Mapping Scheme for Reliable ReRAM-Based Neuromorphic Computing", "authors": ["Yanan Sun", "Chang Ma", "Zhi Li", "Yilong Zhao", "Jiachen Jiang", "Weikang Qian", "Rui Xia Yang", "Zhezhi He", "Li Jiang"], "year": 2021, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2021.3051856", "cites_global": 32, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "Proposes unary-coded synaptic weights plus a variation-aware optimal mapping (bipartite-style assignment exploiting unary coding's multiple representations of the same value) for MLC ReRAM, cutting accuracy loss to <0.89% (CIFAR10) and <4.45% top-5 (ImageNet) under severe resistance variation (sigma=1.0), versus 20-62% loss for binary coding and >60% loss for a prior priority-mapping baseline.", "summary": "The paper addresses accuracy degradation in ReRAM-based neural network accelerators caused by resistance variations in multi-level cells (MLCs), which disproportionately corrupt the most-significant bits under conventional binary weight coding. It proposes representing synaptic weights in unary coding (all bits equal significance) using multiple 2-bit MLCs, which is inherently more tolerant to bit-level error than binary coding, and extends the authors' earlier 'priority mapping' with a new 'optimal mapping' scheme that exploits unary coding's redundancy (multiple device-level assignments can represent the same numeric value) to choose, for each weight, the assignment of physical ReRAM devices (with known/characterized variation) that minimizes expected representation error, modeled as a Root-Mean-Squared-Error minimization. Evaluated with a Python accuracy simulator and a C++ cycle-accurate hardware simulator on ResNet18 and VGG16 over CIFAR10 and ImageNet, with resistance variation sigma up to 1.0 and N=4 ReRAMs / L=4 MLC levels per weight. The optimal mapping cuts top-1 accuracy loss to under 0.89% on CIFAR10 and under 4.45% top-5 loss on ImageNet at sigma=1.0, dramatically outperforming binary coding (10-62% absolute accuracy loss) and the prior priority-mapping scheme (>60% loss on ResNet18/ImageNet), at equal hardware (N, L) cost; the paper also provides an energy/area/accuracy trade-off study across different N, L configurations.", "contributions": ["First reported use of unary-coded synaptic weights (via multi-level ReRAM cells) for ReRAM-based NN accelerators to improve tolerance to resistance variation", "A novel variation-aware 'optimal mapping' algorithm that selects, per weight, the device-to-level assignment minimizing representation error, exploiting unary coding's multiple valid representations of a value", "A quantitative design-space study of the trade-off between NN accuracy and hardware cost (ReRAM count N and MLC level L per weight)", "Evaluation on two networks (ResNet18, VGG16) and two datasets (CIFAR10, ImageNet) with both an accuracy simulator (Python/PyTorch) and a cycle-accurate hardware simulator (C++) for energy/area"], "claims": [{"claim": "Binary coding suffers severe accuracy loss under ReRAM resistance variation, even at moderate variation levels", "support": "nearly 20% accuracy loss at sigma=0.2 for binary coding", "loc": "Sec. IV.B, Fig. 11"}, {"claim": "The proposed optimal mapping with unary coding achieves far smaller accuracy loss than the prior priority-mapping method under large variation", "support": "4.4% loss vs >60% loss for priority mapping at sigma=1.0 relative to ideal accuracy of 89.066%", "loc": "Sec. IV.B, Fig. 11"}, {"claim": "Under extreme resistance variation (sigma=1.0), the optimal-mapping method keeps accuracy loss small across four NN/dataset combinations", "support": "<0.89% top-1 loss on CIFAR10 (ResNet18, VGG16), <4.45% top-5 loss on ImageNet (ResNet18, VGG16); at least 62.58% higher accuracy than binary coding", "loc": "Sec. IV.B, Table III"}, {"claim": "A high MLC level (L) combined with a small ReRAM count (N) per weight is preferable for minimizing energy/area while keeping accuracy loss acceptable", "support": "Table IV trade-off: e.g., N2L8 configuration for ResNet&CIFAR gives 1.10% loss at 0.96 mJ/42.86 mm2 vs N4L4's 0.08% loss at 1.7 mJ/52.81 mm2", "loc": "Sec. IV.C, Table IV"}], "results": ["Optimal mapping: <0.89% top-1 accuracy loss on CIFAR10 (ResNet18: 0.08%, VGG16: 0.89%) at N=4, L=4, sigma=1.0 (Table III)", "Optimal mapping: <4.45% top-5 accuracy loss on ImageNet (ResNet18: 4.45%, VGG16: 3.43%) at N=4, L=4, sigma=1.0 (Table III)", "Optimal mapping improves accuracy over binary coding by at least 62.58% (absolute) under the same hardware cost (Table III)", "At sigma=1.0, optimal mapping has only 4.4% accuracy loss vs ideal (89.066%) compared to >60% loss for prior priority mapping (Fig. 11)", "Hardware-oriented configuration N2L8 for ResNet/CIFAR achieves 1.10% accuracy loss at 0.96 mJ and 42.86 mm2, roughly half the area of the accuracy-oriented N4L4 configuration (Table IV)"], "limitations": ["Evaluated only on image classification (ResNet18, VGG16 on CIFAR10/ImageNet); no evaluation on Transformers, RNNs or other modalities", "Unary coding with the tested configuration can only represent a bounded weight range (e.g., [0,12] for N=4,L=4), trading off representational range for error tolerance", "Accuracy loss attributable partly to lower representation precision of unary coding itself (2.052% loss even at sigma=0), separate from the variation-tolerance benefit", "Simulation-only (Python accuracy simulator + C++ cycle-accurate hardware simulator); no fabricated chip or measured ReRAM array", "Only a simple quantization-aware training method used; authors note a more effective method could further close the baseline accuracy gap"], "remarks": "This is a solid algorithmic/mapping-level contribution to the non-idealities and reliability literature, building directly on the authors' own prior priority-mapping work and clearly out-performing it and binary coding under severe resistance variation. Because the approach only changes how weights are encoded/mapped onto MLC ReRAM (not the device or peripheral circuits), it is readily combinable with other mapping or training-based robustness techniques; however, all results are simulation-based and the practical overhead of per-weight assignment search (bipartite-matching-like optimization) is not deeply analyzed for inference-time or compilation-time cost.", "basis": "full-text", "pdf_source_url": "", "abstract": "Neural network (NN) computing contains a large number of multiply-and-accumulate (MAC) operations. The performance of NN accelerator is limited with the traditional von Neumann architecture due to the tremendous off-chip memory accesses. Resistive random-access memory (ReRAM)-based crossbars can naturally perform matrix–vector multiplication (MVM) operations and are well suitable for NN accelerators. In the existing ReRAM-based NN accelerators, the synaptic weights represented by the conductances of ReRAMs are mainly based on the binary coding. However, the imperfect fabrication process combined with stochastic filament-based switching leads to resistance variations of ReRAMs, which can significantly alter the weights in binary synapses and degrade the NN accuracy. Moreover, the NN accuracy further deteriorates with multilevel cells (MLCs) used for reducing hardware overhead. In this article, a novel unary coding of synaptic weights is proposed to overcome the resistance variations of MLCs and achieve reliable ReRAM-based neuromorphic computing. A variation-aware optimal mapping scheme is also proposed in compliance with the unary coding to guarantee high accuracy by leveraging a unique feature of unary coding—the existence of multiple ways to represent the same value. The optimal mapping obtains very small errors for weights with resistance variations of MLCs. Our simulation results show that under resistance variations, the proposed method achieves less than 0.08% and 3.43% accuracy loss on CIFAR10 and ImageNet, respectively, compared to the ideal accuracy. With each synaptic weight represented by four 2-b MLCs, the proposed method improves the accuracy over the traditional binary coding scheme by 83.39% and 87.6% for CIFAR10 and ImageNet, respectively.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2021_Sun_UnaryOptimalMapping_TCAD.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2021_Sun_UnaryOptimalMapping_TCAD.pdf", "priority": 5.49}, {"id": "W2972862238", "short": "Committee Machines", "title": "Committee machines—a universal method to deal with non-idealities in memristor-based neural networks", "authors": ["D. Joksas", "P. Freitas", "Z. Chai", "W. H. Ng", "M. Buckwell", "C. Li", "W. D. Zhang", "Q. Xia", "A. J. Kenyon", "A. Mehonic"], "year": 2020, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications 11, 4273 (2020)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-020-18098-0", "cites_global": 76, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "Ensemble-averaging committees of memristor-based networks, simulated with measured data from three RRAM technologies, recover accuracy lost to stuck devices, device-to-device variability, RTN and line resistance (e.g. Ta/HfO2: 91.0% -> 95.7% median with 5 networks), even at a fixed total memristor count.", "summary": "Device and system non-idealities (stuck/unformed devices, D2D variability, RTN, line resistance) prevent memristive neural networks from reaching software accuracy. The authors propose committee machines with ensemble averaging: several independently trained networks are each mapped onto crossbars (proportional mapping onto conductance pairs, layers split across multiple 128x64 crossbars) and their outputs averaged. Non-idealities are injected from experimental data: a 128x64 Ta/HfO2 1T1R array (faulty devices, D2D variability, interconnect resistance), and single-device RTN data for Ta2O5 and aVMCO RRAM. On one-hidden-layer MNIST MLPs, committees of five networks raise median accuracy substantially for all three technologies, and committees of smaller networks beat single larger networks with the same total number of memristors.", "contributions": ["Applies ensemble-averaging committee machines to memristive neural networks as a technology-agnostic non-ideality mitigation", "Experimental non-ideality data from three RRAM technologies (Ta/HfO2 array, Ta2O5 and aVMCO RTN)", "Shows committees improve accuracy under combined faults, D2D variability, RTN and line resistance", "Iso-memristor-count comparison showing committees of smaller networks beat single larger networks"], "claims": [{"claim": "Committees recover most of the accuracy lost to Ta/HfO2 non-idealities.", "support": "Median accuracy: digital ~95.9%, non-ideal single ~91.0%, committee of 5 ~95.7%", "loc": "Fig. 4"}, {"claim": "With low-impact non-idealities, committees can exceed the software baseline of individual networks.", "support": "Ta2O5: non-ideal median ~94.1% rising to ~96.5% with 5 networks, above single-network software baseline", "loc": "Fig. 6"}, {"claim": "For a fixed total memristor count, committees of smaller networks outperform single larger networks.", "support": "Two 25-hidden-neuron networks are ~0.9% better than one 50-neuron net; two 100-neuron nets ~1.1% better than one 200-neuron net; four 50-neuron nets ~1.5% better", "loc": "Fig. 9"}, {"claim": "Line resistance substantially perturbs crossbar outputs even with 128x64 tiles.", "support": "Output current decreases from ~12% to ~16% across bit lines in Ta/HfO2 crossbars", "loc": "Fig. 3b"}, {"claim": "Accuracy of committees is largely determined by the accuracy of their individual non-ideal networks.", "support": "Trend observed across all three device types", "loc": "Discussion"}], "results": ["Ta/HfO2 (faults + D2D + line resistance): median 91.0% -> 95.7% with 5-network committee (digital ~95.9%)", "Ta2O5 (RTN + line resistance): median ~94.1% -> ~96.5% with 5 networks", "aVMCO (RTN + line resistance): median ~94.6% -> ~96.7% with 5 networks", "Iso-memristor comparisons: +0.9% to +1.5% median accuracy for committees vs. single larger nets (Fig. 9)"], "limitations": ["Only small one-hidden-layer MLPs on MNIST; no CNNs or larger datasets", "Simulation driven by measured data, not an end-to-end hardware demonstration", "RTN data from single devices; line resistance borrowed from Ta/HfO2 array for other technologies", "Ensemble averaging done digitally; peripheral (ADC/neuron) overhead of multiple networks only argued, not quantified", "Committees of N networks multiply crossbar and periphery count unless network size is reduced"], "remarks": "A simple, technology-agnostic system-level idea with careful use of experimental device data, but the evidence is limited to MNIST MLPs where ensembling is known to help a lot. The iso-memristor result is the key mapping-relevant insight: spreading capacity across several smaller independently-mapped networks can beat one large mapping. Follow-ups include the same group's nonideality-aware training and 'layer ensemble averaging' on real memristive hardware.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/1909.06658", "abstract": "Artificial neural networks are notoriously power- and time-consuming when implemented on conventional von Neumann computing systems. Consequently, recent years have seen an emergence of research in machine learning hardware that strives to bring memory and computing closer together. A popular approach is to realise artificial neural networks in hardware by implementing their synaptic weights using memristive devices. However, various device- and system-level non-idealities usually prevent these physical implementations from achieving high inference accuracy. We suggest applying a well-known concept in computer science-committee machines-in the context of memristor-based neural networks. Using simulations and experimental data from three different types of memristive devices, we show that committee machines employing ensemble averaging can successfully increase inference accuracy in physically implemented neural networks that suffer from faulty devices, device-to-device variability, random telegraph noise and line resistance. Importantly, we demonstrate that the accuracy can be improved even without increasing the total number of memristors.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2020_Joksas_CommitteeMachines_NatCommun.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2020_Joksas_CommitteeMachines_NatCommun.pdf", "priority": 5.25}, {"id": "W3111367661", "short": "IR-QNN Framework", "title": "IR-QNN Framework: An IR Drop-Aware Offline Training of Quantized Crossbar Arrays", "authors": ["Mohammed E. Fouda", "Sugil Lee", "Jongeun Lee", "Gun Hwan Kim", "Fadi Kurdahi", "Ahmed M. Eltawil"], "year": 2020, "venue": "IEEE Access", "venue_short": "IEEEAccess", "venue_full": "IEEE Access, vol. 8, 2020", "venue_ok": true, "doi": "https://doi.org/10.1109/access.2020.3044652", "cites_global": 41, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["MLP", "CNN"], "evidence": "algorithm+simulation", "tldr": "IR-QNN is a fast offline training/validation framework that incorporates interconnect IR-drop into quantized DNN training using a fabricated 4-bit Au/Al2O3/HfO2/TiN device model and efficient system-level IR-drop estimation (avoiding full SPICE during training), achieving near-baseline accuracy (2% drop on MNIST MLP, 4% drop on CIFAR-10 VGG/AlexNet) while also studying stuck-at-faults, variability and aging.", "summary": "Resistive crossbar arrays (RCAs) accelerate the matrix-vector multiplication at the core of DNNs in O(1) time, but interconnect wire resistance causes an IR-drop problem that degrades computational accuracy and is costly to simulate accurately via SPICE during training. IR-QNN proposes a fast and efficient training and validation framework that incorporates wire resistance into quantized DNN training without requiring full SPICE simulation in the training loop, instead using efficient system-level IR-drop estimation methods. The framework uses a device model derived from a fabricated four-bit Au/Al2O3/HfO2/TiN memristive device and two mapping schemes to realize quantized weights on the crossbar. SPICE is used only for final validation, confirming the system-level estimation captures the IR-drop effect well. The paper also studies other non-idealities (stuck-at-fault defects, variability, aging) and discusses neuronal/driver circuit design considerations.", "contributions": ["A fast offline training/validation framework (IR-QNN) that incorporates crossbar interconnect IR-drop into quantized DNN training without requiring computationally expensive SPICE simulation during training", "Use of a fabricated four-bit Au/Al2O3/HfO2/TiN memristive device model with two weight-mapping schemes to realize quantized weights on the crossbar", "Efficient system-level IR-drop estimation methods validated against SPICE simulation for accuracy", "Extension of the robustness study to other non-idealities: stuck-at-fault defects, device variability, and aging", "Discussion of neuronal and driver circuit design considerations for IR-drop-aware crossbar accelerators"], "claims": [{"claim": "The proposed system-level IR-drop estimation during training achieves accuracy close to the baseline (no IR-drop) when validated with SPICE", "support": "2% accuracy drop (worst case) for MNIST on an MLP network; 4% accuracy drop (worst case) for CIFAR-10 on modified VGG and AlexNet networks, relative to baseline", "loc": "Abstract"}, {"claim": "The device model used is grounded in a real fabricated device rather than a purely theoretical model", "support": "'A fabricated four-bit Au/Al2O3/HfO2/TiN device is modelled and used within the framework' (abstract)", "loc": "Abstract"}, {"claim": "The framework is efficient enough to avoid computationally extensive SPICE simulations during the training process itself", "support": "Abstract: 'without the need for computationally extensive SPICE simulations during the training process'; SPICE used only for validation", "loc": "Abstract"}], "results": ["2% worst-case accuracy drop on MNIST (MLP network) versus baseline accuracy", "4% worst-case accuracy drop on CIFAR-10 (modified VGG and AlexNet networks) versus baseline accuracy", "SPICE validation confirms the system-level IR-drop estimation effectively captures the IR-drop problem"], "limitations": ["Only the abstract was available for this analysis (full text not accessible from this machine; IEEE Access article appears gold open access but the PDF is hosted on IEEE Xplore's delivery system, which is not reachable from this environment); exact mapping schemes, IR-drop estimation method, and quantitative variability/aging/SAF results could not be verified", "Device model is based on a single fabricated device type (Au/Al2O3/HfO2/TiN), so generalization to other RRAM material stacks is unclear from the abstract alone"], "remarks": "Based on the abstract, this paper directly targets a core non-ideality (interconnect IR-drop) that many architecture and mapping papers in this collection acknowledge but do not always model rigorously, using a real fabricated-device model for credibility, and explicitly trades off training-time cost (via fast system-level estimation) against the gold-standard but expensive SPICE accuracy. It is a useful companion to mapping/representability papers (e.g., Representable Matrices, W3013896150) that also address IR-drop, but from an offline-training-robustness angle rather than a mapping-optimization angle. Despite the IEEE Access venue being nominally open access, the PDF could not be retrieved from this machine (IEEE Xplore delivery is blocked here), so this entry remains abstract-only.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive Crossbar Arrays present an elegant implementation solution for Deep Neural Networks acceleration. The Matrix-Vector Multiplication, which is the corner-stone of DNNs, is carried out in O(1) compared to O(N2) steps for digital realizations of O(log2(N)) steps for in-memory associative processors. However, the IR drop problem, caused by the inevitable interconnect wire resistance in RCAs remains a daunting challenge. In this article, we propose a fast and efficient training and validation framework to incorporate the wire resistance in Quantized DNNs, without the need for computationally extensive SPICE simulations during the training process. A fabricated four-bit Au/Al2O3/HfO2/TiN device is modelled and used within the framework with two-mapping schemes to realize the quantized weights. Efficient system-level IR-drop estimation methods are used to accelerate training. SPICE validation results show the effectiveness of the proposed method to capture the IR drop problem achieving the baseline accuracy with a 2% and 4% drop in the worst-case scenario for MNIST dataset on multilayer perceptron network and CIFAR 10 dataset on modified VGG and AlexNet networks, respectively. Other nonidealities, such as stuck-at fault defects, variability, and aging, are studied. Finally, the design considerations of the neuronal and the driver circuits are discussed.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2020_Fouda_IRQNNFramework_IEEEAccess.pdf", "analysed": true, "pdf": null, "priority": 5.44}, {"id": "W3030670306", "short": "Parasitic Resistance Mitigation CNN", "title": "Mitigate Parasitic Resistance in Resistive Crossbar-based Convolutional Neural Networks", "authors": ["Fan Zhang", "Miao Hu"], "year": 2020, "venue": "ACM Journal on Emerging Technologies in Computing Systems", "venue_short": "JETC", "venue_full": "ACM Journal on Emerging Technologies in Computing Systems (JETC), Special Issue on Nanoelectronic Device, Circuit, Architecture Design, 2020", "venue_ok": true, "doi": "https://doi.org/10.1145/3371277", "cites_global": 27, "cat": "06", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["CNN", "ResNet"], "evidence": "simulation", "tldr": "SPICE-level, experiment-calibrated end-to-end simulation of CNNs (4-layer CNN/MNIST, ResNet-20/32/56/CIFAR-10) on 1T1M crossbars with wire/IO parasitics, plus a dense kernel-to-crossbar mapping and a conversion+calibration mitigation algorithm that keeps near-software accuracy with 8-bit (and partly 6-bit) ADC/DAC.", "summary": "The paper studies how parasitic (wire, input/output) resistances distort analog VMMs when deep CNNs are mapped to resistive crossbars. It proposes 'dense mapping', where each 3-D kernel is unrolled into a single crossbar column and inputs are streamed through a sliding-window shift register, with negative weights handled by a constant shift that is removed digitally using sum(X), avoiding differential columns. Parasitics are compensated by an extension of the HPE Dot-Product-Engine 'conversion' method (solving for a tweaked conductance matrix G' via KCL nodal equations) whose conversion-signal amplitude is tuned per crossbar size, followed by a per-crossbar first-order polynomial calibration fitted on 10 sampled inputs. Using an experimentally verified (128x64 array) SPICE-level simulator, the authors propagate errors layer by layer through a 4-layer MNIST CNN and ResNet-20/32/56 on CIFAR-10. They report ~50% lower error than the original conversion algorithm, 0.25% mean relative error on a 576x64 crossbar, and software-level accuracy with 8-bit ADC/DAC quantization, which also suppresses error accumulation across layers.", "contributions": ["Dense mapping of 4-D conv kernels onto small dense crossbars (one unrolled 3-D kernel per column) with a weight-shift trick instead of differential pairs; >100x fewer ADC/DACs than Toeplitz (sparse) mapping", "Experiment-calibrated SPICE-level 1T1M crossbar model including wire, input/output and transistor parasitics", "Improved parasitic-mitigation flow: data-sparsity-aware choice of conversion-signal amplitude plus per-crossbar linear calibration, no retraining", "End-to-end circuit simulation of error propagation through deep CNNs (up to ResNet-56) versus ADC/DAC resolution and programming error"], "claims": [{"claim": "Dense mapping drastically reduces peripheral cost versus Toeplitz/sparse mapping", "support": "Sparse mapping 'still needs 100x numbers of DACs&ADCs than dense mapping'; e.g. 3x3x16x16 kernel: 144x16 crossbar, 146.34 mW vs 16384x14400, 51170 mW", "loc": "Sec. 3.1, Table 2"}, {"claim": "The proposed mitigation algorithm outperforms the original DPE conversion algorithm and is insensitive to input sparsity and kernel type", "support": "'our method provides ~50% better overall accuracy than the original conversion algorithm'", "loc": "Sec. 4.2, Figs. 14-18"}, {"claim": "Mitigated crossbars reach ~8.6-bit mean computing precision at 576x64", "support": "'0.25% mean relative error (~8.6 bits) or 1.2% worst relative error (~6.4 bits) for crossbar size 576 x 64'", "loc": "Sec. 5"}, {"claim": "ADC/DAC quantization at 8 bits preserves software-level accuracy and stops inter-layer error accumulation; 4 bits fails", "support": "ResNet-20: software 89.3%, 8-bit 90.7%, 6-bit 82.7%, 4-bit 11.3% (150-image CIFAR-10 subset)", "loc": "Table 6, Sec. 4.3"}, {"claim": "Conversion-signal amplitude is critical: a bad choice causes ~100x more error", "support": "'±20% in all 1 signal versus ±0.2% in all 0.1 signal' for 144x16 crossbar", "loc": "Sec. 3.3.2, Fig. 11"}], "results": ["576x64 crossbar after mitigation: 0.25% mean / 1.2% worst relative error (~8.6 / ~6.4 bits)", "ResNet-20/32/56 on CIFAR-10 (150-image subset), 8-bit ADC/DAC: 90.7% / 90% / 89.3% vs software 89.3% / 89.3% / 90%", "6-bit ADC/DAC: ResNet-20 82.7%, ResNet-32 82%, ResNet-56 88%; 4-bit: ResNet-20 collapses to 11.3%", "4-layer CNN on MNIST (4000 images): 98.8% with 8-bit vs 99.1% software (text)", "ResNet-20 stays >80% accuracy for programming-error sigma < 0.4 uS (conductance range 3.3-66.7 uS)", "Dense mapping: ResNet-20 inference needs 9089 sequential crossbar iterations, ~0.09 ms at 100 MHz"], "limitations": ["Simulation only; ResNet results use a 150-image CIFAR-10 subset because each image takes ~5 min of circuit simulation, so accuracy differences of ~1% are not statistically meaningful", "Abstract claims 6-bit ADC/DAC preserves software accuracy, but Table 6 shows 6-bit costs ~7 points on ResNet-20/32; the 8-bit result is the robust one. Table 6 MNIST 8-bit entry (88.8%) contradicts text (98.8%)", "Conversion (solving G') requires per-crossbar nonlinear solving and exact knowledge of parasitics; programming the tweaked G' assumes precise 1T1M write-verify", "Device variation/noise only crudely modelled (Gaussian programming error); no drift, read noise, stuck-at faults or I-V nonlinearity beyond the model", "Dense mapping trades parallelism for area (sequential sliding-window iterations); throughput/energy at system level not evaluated beyond rough estimates"], "remarks": "A useful, circuit-faithful reference for how IR drop interacts with CNN mapping and ADC precision, building directly on the HPE DPE conversion method (Hu et al.). The 'dense mapping' is essentially the im2col-style column mapping that ISAAC/PUMA-type designs already use, so the novelty lies more in the parasitic compensation and end-to-end error-propagation study than in mapping. Evidence is weak statistically (150 test images) and the compensation is a per-array, data-aware pre-distortion rather than a training-time fix; later works (e.g. Xiao et al.'s accuracy study, IR-drop-aware training such as IR-QNN) instead fold parasitics into training or exploit proportional mapping.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/1912.08716", "abstract": "Traditional computing hardware often encounters on-chip memory bottleneck on large-scale Convolution Neural Networks (CNN) applications. With its unique in-memory computing feature, resistive crossbar-based computing attracts researchers’ attention as a promising solution to the memory bottleneck issue in von Neumann architectures. However, the parasitic resistances in crossbar deviate its behavior from the ideal weighted summation operation. In large-scale implementations, the impact of parasitic resistances must be carefully considered and mitigated to ensure circuits’ functionality. In this work, we implemented and simulated CNNs on resistive crossbar circuits with consideration of parasitic resistances. Moreover, we carried out a new mapping scheme for high utilization of crossbar arrays on convolution, and a mitigation algorithm to mitigate parasitic resistances in CNN applications. The mitigation algorithm considers parasitic resistances as well as data/kernel patterns of each layer to minimize the computing error in crossbar-based convolutions of CNNs. We demonstrated the proposed methods with implementations of a 4-layer CNN on MNIST, and residual neural network (ResNet) (20, 32, and 56) on CIFAR-10. Simulation results show the proposed methods well mitigate the parasitic resistances in crossbars. With our methods, modern CNNs on crossbars can preserve ideal (software) level classification accuracy with 6-bit ADCs and DACs implementation.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2020_Zhang_ParasiticResistanceMitigationCNN_JETC.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2020_Zhang_ParasiticResistanceMitigationCNN_JETC.pdf", "priority": 4.94}, {"id": "W3111989171", "short": "TOPAR", "title": "A thermal-aware optimization framework for ReRAM-based deep neural network acceleration", "authors": ["Hyein Shin", "Myeonggu Kang", "Lee‐Sup Kim"], "year": 2020, "venue": "", "venue_short": "ICCAD", "venue_full": "39th IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2020)", "venue_ok": true, "doi": "https://doi.org/10.1145/3400302.3415665", "cites_global": 23, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "TOPAR is a thermal-aware optimization framework for ReRAM-based DNN accelerators combining offline thermal-aware weight decomposition/column reordering/fine-grained weight adjustment with online thermal-aware error compensation, improving endurance degradation due to temperature rise by up to 2.39x while preserving inference accuracy.", "summary": "The paper addresses the thermal problems of ReRAM-based DNN accelerators: elevated and non-uniform temperature across crossbar arrays degrades both device endurance/lifetime and inference accuracy. TOPAR (Thermal-aware OPtimization for Accelerating DNN on ReRAM) tackles this with a 3-stage offline thermal optimization (thermal-aware weight decomposition, thermal-aware column reordering, and fine-grained weight adjustment) intended to reduce the temperature profile of the chip, combined with an online thermal-aware error-compensation mechanism that adjusts for conductance changes caused by temperature variation during operation. The approach is evaluated for its effect on both accelerator lifetime (endurance) and inference accuracy preservation.", "contributions": ["A 3-stage offline thermal optimization pipeline for ReRAM accelerators: thermal-aware weight decomposition, thermal-aware column reordering, and fine-grained weight adjustment", "An online thermal-aware error-compensation scheme that adjusts for conductance changes due to temperature variation during inference", "Demonstrated improvement in endurance degradation from thermal stress without sacrificing inference accuracy"], "claims": [{"claim": "TOPAR improves endurance degradation due to temperature rise by up to 2.39x", "support": "stated result in the abstract", "loc": "Abstract"}, {"claim": "TOPAR preserves inference accuracy without harming the performance of the ReRAM-based DNN accelerator", "support": "stated result in the abstract", "loc": "Abstract"}], "results": ["Up to 2.39x improvement in endurance degradation caused by temperature rise", "Inference accuracy preserved relative to baseline (no reported accuracy loss) while addressing thermal effects"], "limitations": ["Full text not available to this review; detailed thermal model, benchmarked networks, and the magnitude of baseline thermal degradation could not be independently verified beyond the abstract", "Analysis based only on the abstract; it is unclear from the abstract alone how the 3-stage pipeline trades off against latency/area overhead"], "remarks": "TOPAR is a relatively early (2020) and still fairly lightly-cited (23 citations as of this writing) contribution addressing a non-ideality that receives comparatively little attention in most crossbar accelerator papers: self-heating and thermal gradients and their coupled effect on both endurance and accuracy. It is cited by later thermal-effect-aware work (e.g., WRAP) and general reliability frameworks (Fault-Free), suggesting it helped establish thermal-awareness as a distinct axis in the non-idealities/reliability literature alongside the more commonly studied IR-drop, stuck-at-fault, and conductance-variation effects. Full-text verification was not possible (ACM DL, not downloadable from this environment), so this entry is abstract-only.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive RAM (ReRAM) is widely regarded as a promising platform for deep neural network (DNN) acceleration. However, the ReRAM device suffers from severe thermal problems that degrade the lifetime and inference accuracy of the ReRAM-based DNN accelerator. To address the issues, we propose a thermal-aware optimization framework for accelerating DNN on ReRAM (TOPAR). TOPAR includes 3-stage offline thermal optimization and online thermal-aware error compensation. Offline thermal optimization consists of thermal-aware weight decomposition, thermal-aware column reordering, and fine-grained weight adjustment to reduce the temperature of the ReRAM-based DNN accelerator. For online thermal-aware error compensation, we compensate conductance change according to the temperature variation. With TOPAR, the endurance degradation due to temperature rise improves up to 2.39×, and inference accuracy is preserved without harming the performance of the ReRAM-based DNN accelerator.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2020_Shin_TOPAR_ICCAD.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2020_Shin_TOPAR_ICCAD.pdf", "priority": 5.27}, {"id": "W3138725418", "short": "PCM Weight Precision", "title": "Precision of synaptic weights programmed in phase-change memory devices for deep learning inference", "authors": ["S. R. Nandakumar", "Irem Boybat", "Jin‐Ping Han", "Stefano Ambrogio", "Praneet Adusumilli", "Robert L. Bruce", "Matthew J. BrightSky", "Malte J. Rasch", "Manuel Le Gallo", "Abu Sebastian"], "year": 2020, "venue": "", "venue_short": "IEDM", "venue_full": "2020 IEEE International Electron Devices Meeting (IEDM 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/iedm13553.2020.9371990", "cites_global": 35, "cat": "06", "seed": false, "devices": ["PCM"], "models": ["CNN", "LSTM/RNN"], "evidence": "device-experiment", "tldr": "Derives analytically that the precision achievable when iteratively programming PCM conductance states with closed-loop feedback is fundamentally limited by read noise, validates this against measurements on >1k doped-GST PCM device arrays, and shows that tuning the feedback timing improves deep-learning inference accuracy retention on CIFAR-10, CIFAR-100 and PTB.", "summary": "The paper (from IBM Research, including Sebastian/Le Gallo/Ambrogio and collaborators) studies the precision with which synaptic weights can be programmed into phase-change memory (PCM) conductance states using iterative program-verify with closed-loop feedback, the standard approach for achieving target conductance values in analog in-memory computing. The authors analytically derive the programming-noise precision limit, showing it is fundamentally set by the PCM cell's read noise, and quantitatively match this prediction against measurements on more than 1,000 PCM devices across two doped-GST phase-change material variants. They further show that conductance drift causes the programmed state to diverge over time in a way that depends on when (how late) feedback was applied during programming, and that tuning this feedback-timing parameter yields significant improvements in deep-learning inference accuracy retention over time on CIFAR-10, CIFAR-100 and Penn Treebank (PTB) benchmarks run on PCM-based DNN inference hardware simulations.", "contributions": ["An analytical derivation of the programming precision limit for iterative closed-loop program-verify schemes on PCM, showing it is fundamentally bounded by read noise", "Experimental validation of this precision model on >1000 PCM devices spanning two doped-GST phase-change materials", "Demonstration that conductance-drift-driven divergence of programmed states depends on the timing of the last feedback step during iterative programming", "Practical demonstration that tuning feedback timing significantly improves long-term inference accuracy retention for CNNs (CIFAR-10/100) and sequence models (PTB) run on PCM-based inference hardware"], "claims": [{"claim": "The precision of iteratively programmed PCM conductance states is fundamentally limited by the device's read noise", "support": "analytical derivation matched quantitatively to measurements on >1k PCM device arrays", "loc": "Abstract / analytical section"}, {"claim": "Conductance-drift-driven divergence of the programmed state depends on the time of the last feedback step in the iterative programming process", "support": "stated analysis in the abstract", "loc": "Abstract"}, {"claim": "Tuning the feedback timing yields significant accuracy-retention improvements for deep learning inference on PCM-based hardware", "support": "demonstrated on CIFAR-10, CIFAR-100, and PTB benchmarks", "loc": "Abstract"}], "results": ["Analytically derived programming-noise precision model quantitatively matches measurements across >1,000 PCM devices (two doped-GST variants)", "Significant accuracy-retention improvements reported on CIFAR-10, CIFAR-100, and PTB when feedback timing is tuned (specific percentage figures not given in the abstract)"], "limitations": ["Full text not available to this review; the quantitative magnitude of the accuracy-retention improvements and the exact feedback-timing parameter values were not disclosed in the abstract", "Analysis based only on the abstract; details of the inference hardware simulation setup and dataset-specific network architectures are unknown from the abstract alone"], "remarks": "This is a well-cited (35+ citations) IBM Research paper that gives a rigorous, device-physics-grounded explanation (read-noise-limited programming precision) for a key practical knob -- feedback timing in iterative program-verify -- that is widely used across PCM-based in-memory computing work, and it is cited by several later PCM accelerator and drift-mitigation papers in this collection (HERMES-Core, Optimised weight programming, drift-aware regularization work). Because full text was not accessible (IEDM proceedings not downloadable from this environment), this entry is abstract-only and specific numeric accuracy-retention results could not be captured.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The precision at which the conductance states can be programmed and maintained over time is central to the operation of analog resistance-based memory devices such as phase-change memory (PCM) in in-memory computing applications such as deep learning and scientific computing. Iterative programming with closed loop feedback is the most common approach towards programming an array of devices to achieve the desired conductance values as stipulated by the application. In this work, we analytically derive the precision associated with the iterative programming scheme and show that it is fundamentally limited by the read noise. The estimated programming noise quantitatively matches that measured experimentally on >1k PCM device arrays incorporating two types of doped GST phase-change materials. We further demonstrate that the conductance drift driven divergence of the programmed conductance states depends on the time of feedback in the iterative programming. Moreover, we studied the impact of the inaccuracy associated with synaptic weight storage on deep learning inference. We demonstrate significant accuracy retention improvements on CIFAR-10, CIFAR-100, and PTB benchmarks by tuning the time of feedback when programming weights on PCM-based DNN inference hardware.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2020_Nandakumar_PCMWeightPrecision_IEDM.pdf", "analysed": true, "pdf": null, "priority": 6.58}, {"id": "W3005874416", "short": "PCM Drift Inference", "title": "Reducing the Impact of Phase-Change Memory Conductance Drift on the Inference of large-scale Hardware Neural Networks", "authors": ["Stefano Ambrogio", "M. Gallot", "Katherine Spoon", "Hsinyu Tsai", "Charles Mackin", "M. Wesson", "Sanjay Kariyappa", "Pritish Narayanan", "ChenKang Liu", "Arvind Kumar", "A. Chen", "Geoffrey W. Burr"], "year": 2019, "venue": "", "venue_short": "IEDM", "venue_full": "2019 IEEE International Electron Devices Meeting (IEDM 2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/iedm19573.2019.8993482", "cites_global": 76, "cat": "06", "seed": false, "devices": ["PCM"], "models": ["MLP", "ResNet", "LSTM/RNN"], "evidence": "device-experiment", "tldr": "IBM builds a statistical PCM conductance-drift model (including cycle-to-cycle variability of the drift coefficient nu) from large-array measurements, quantifies long-term accuracy loss for MLP, ResNet-10/18/34 and LSTM inference, and proposes slope correction plus DNN-architecture choices to suppress it.", "summary": "Phase-change memory conductance drifts over time (G ~ t^-nu), which degrades the accuracy of pre-trained DNNs whose weights are stored as PCM conductances. Starting from large-array characterisation of drift in partial-SET states, the authors build a statistical drift model that captures the empirically observed cycle-to-cycle variability of the drift coefficient nu. They simulate MLPs on MNIST, ResNet-10/18/34 on CIFAR-10 and a 2-layer LSTM on 'Alice in Wonderland' to show how drift plus nu-variability causes long-term accuracy degradation. Mitigations include 'slope correction' (compensating the average drift-induced scaling of outputs) and DNN architecture choices (squashing function, number of hidden units, hidden layers or convolution filters). They also show that 1/f noise, random telegraph noise and device-to-device heater-diameter variability complicate accurate drift measurement.", "contributions": ["Statistical PCM drift model from large-array partial-SET measurements including cycle-to-cycle nu variability", "Assessment of drift impact on MLP, ResNet-10/18/34 and LSTM inference", "Slope correction technique to compensate average drift", "DNN design guidelines (activation choice, width/depth, filter count) for drift tolerance", "Analysis of how 1/f noise, RTN and heater-diameter variability affect drift measurement"], "claims": [{"claim": "The combination of drift and nu-variability causes long-term DNN accuracy degradation.", "support": "Characterised across MLP/MNIST, ResNet/CIFAR-10 and LSTM workloads", "loc": "Abstract"}, {"claim": "Slope correction and architectural choices can suppress drift-induced degradation.", "support": "Stated in abstract; magnitudes not available", "loc": "Abstract"}, {"claim": "Noise sources (1/f, RTN) and heater-diameter variability complicate accurate drift measurement.", "support": "Stated in abstract", "loc": "Abstract"}], "results": ["Drift + nu-variability degrades accuracy over time for MLP (MNIST), ResNet-10/18/34 (CIFAR-10) and 2-layer LSTM (abstract; numbers not available)", "Slope correction and network design choices mitigate the degradation (abstract)"], "limitations": ["Abstract-only analysis; no quantitative accuracy-vs-time numbers verified", "Network-level results are simulations using a device-calibrated model, not on-chip inference", "Small-to-mid-size workloads (CIFAR-10 ResNets, small LSTM)", "Slope correction compensates mean drift but not the nu-variability-induced spread"], "remarks": "A foundational IBM paper for drift-aware PCM inference: its statistical drift model and slope (global drift) correction underlie later IBM work, including the AIHWKit inference noise model, hardware-aware training studies and the 14nm analog chip demonstrations, many of which cite it in this collection. Its key lesson for mapping is that drift is mostly a correctable global scaling, while nu-variability sets the residual accuracy floor, motivating periodic recalibration and drift-robust training.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "We extensively analyze the impact of conductance \"drift\" - inherent to Phase Change Memory (PCM) devices - on the inference of pre-trained Deep Neural Networks (DNNs). Starting from large-array experimental characterization of PCM drift in partial-SET states, we build a statistical model of conductance drift capturing the cycle-to-cycle variability in drift-coefficient ν observed empirically. Using a variety of small and large DNNs (few-layer perceptrons using MNIST dataset, ResNet-(10,18,34) using CIFAR-10, and a 2-layer LSTM using \"Alice in Wonderland\"), we characterize how the combination of drift and ν-variability can induce long-term degradations in DNN accuracy. We then introduce several techniques to suppress these effects, including \"slope correction\" and modifications to the DNN architecture (choice of squashing function, the number of hidden units, hidden layers, or convolution filters). Finally, we show how noise sources such as 1/f and Random Telegraph Noise (RTN), and device-to-device variability in heater diameter, can complicate the accurate measurement of PCM drift.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2019_Ambrogio_PCMDriftInference_IEDM.pdf", "analysed": true, "pdf": null, "priority": 7.5}, {"id": "W2978384356", "short": "MT Framework", "title": "Handling Stuck-at-Fault Defects Using Matrix Transformation for Robust Inference of DNNs", "authors": ["Baogang Zhang", "Necati Uysal", "Deliang Fan", "Rickard Ewetz"], "year": 2019, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems, vol. 39, no. 10, pp. 2448-2460 (2020; online 2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2019.2944582", "cites_global": 52, "cat": "06", "seed": false, "devices": ["Memristor(generic)"], "models": ["MLP", "CNN"], "evidence": "algorithm+simulation", "tldr": "The MT framework tolerates stuck-at faults in memristor crossbars by transforming weight matrices (row flipping, permutation, value-range reduction) to minimise a fault-impact cost, recovering 99% of the accuracy loss on MNIST and CIFAR-10 without hardware-aware training, at 8.19x power and 9.23x area overhead.", "summary": "Stuck-at faults in memristor crossbar arrays severely degrade DNN inference accuracy, and earlier fixes rely on extra hardware or hardware-aware (fault-aware) retraining. This TCAD extension of the authors' ASP-DAC'19 paper defines a cost metric capturing the negative impact of stuck-at faults and minimises it by applying matrix transformations T, so that W is mapped as T(W). Row flipping converts stuck-off faults into stuck-on faults (and vice versa), permutation maps small weights onto stuck-off cells and large weights onto stuck-on cells, and value-range transformation shrinks the extreme weight magnitudes so each fault introduces a smaller error. Experiments on MNIST and CIFAR-10 recover 99% of the accuracy loss without hardware-aware training, at the cost of 8.19x power and 9.23x area overhead, which can be reduced by up to 50% when combined with hardware-aware training.", "contributions": ["Cost metric quantifying the impact of stuck-at faults on a mapped weight matrix", "Row-flipping transformation swapping stuck-on/stuck-off semantics", "Permutation transformation matching weight magnitudes to fault types", "Value-range transformation reducing per-fault error magnitude", "Combination with hardware-aware training to reduce overhead"], "claims": [{"claim": "Matrix transformations alone, without retraining, recover nearly all SAF-induced accuracy loss.", "support": "'capable of recovering 99% of the accuracy loss on both the MNIST and CIFAR-10 datasets without utilizing hardware aware training'", "loc": "Abstract"}, {"claim": "The recovery comes at significant hardware cost.", "support": "'8.19x and 9.23x overhead in power and area, respectively'", "loc": "Abstract"}, {"claim": "Hardware-aware training can reduce the overhead.", "support": "'the overhead can be reduced with up to 50% by leveraging hardware aware training'", "loc": "Abstract"}], "results": ["99% of SAF-induced accuracy loss recovered on MNIST and CIFAR-10 without hardware-aware training (abstract)", "8.19x power and 9.23x area overhead; up to 50% overhead reduction with hardware-aware training (abstract)"], "limitations": ["Abstract-only analysis; fault rates, network architectures and baselines not verified", "Large power/area overhead (8-9x) relative to the unprotected design", "Requires per-chip fault map", "Stuck-at faults only; does not address variation, drift or IR drop", "Small datasets (MNIST, CIFAR-10)"], "remarks": "Represents the retraining-free, mapping-centric school of SAF tolerance (contrast with Liu et al. DAC'17 retraining/remapping, which it cites), and is cited by later fault-tolerant mapping work for ReRAM and attention models. The 8-9x overhead reported in the abstract is a serious practical caveat and suggests the transformations require substantial redundant hardware, so its value is more conceptual (fault-aware weight-to-cell assignment) than as a deployable scheme.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Matrix-vector multiplication is the dominating computational workload in the inference phase of deep neural networks (DNNs). Memristor crossbar arrays (MCAs) can efficiently perform matrix-vector multiplication in the analog domain. A key challenge is that memristor devices may suffer stuck-at-fault defects, which can severely degrade the classification accuracy. Earlier studies have shown that the accuracy loss can be recovered by utilizing additional hardware or hardware aware training. In this article, we propose a framework that handles stuck-at-faults using matrix transformations, which is called the MT framework. The framework is based on introducing a cost metric that captures the negative impact of the stuck-atfault defects. Next, the cost metric is minimized by applying matrix transformations T. A transformation T changes a weight matrix W into a new weight matrix W̃ = T(W). In particular, a row flipping transformation, a permutation transformation, and a value range transformation are proposed. The row flipping transformation results in that stuck-off (stuck-on) faults are translated into stuck-on (stuck-off) faults. The permutation transformation maps small (large) weights to memristors stuck-off (stuck-on). The value range transformation is based on reducing the magnitude of the smallest and largest elements in the weight matrices, which results in that the stuck-at-faults introduce smaller errors. The experimental results demonstrate that the MT framework is capable of recovering 99% of the accuracy loss on both the MNIST and CIFAR-10 datasets without utilizing hardware aware training. The accuracy improvements come at the expense of an 8.19× and 9.23× overhead in power and area, respectively. Nevertheless, the overhead can be reduced with up to 50% by leveraging hardware aware training.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2019_Zhang_MTFramework_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.51}, {"id": "W2795127895", "short": "Data-aware ABN codes", "title": "Making Memristive Neural Network Accelerators Reliable", "authors": ["Ben Feinberg", "Shibo Wang", "Engin İpek"], "year": 2018, "venue": "", "venue_short": "HPCA", "venue_full": "2018 IEEE International Symposium on High Performance Computer Architecture (HPCA 2018)", "venue_ok": true, "doi": "https://doi.org/10.1109/hpca.2018.00015", "cites_global": 134, "cat": "06", "seed": false, "devices": ["ReRAM"], "models": ["MLP", "CNN"], "evidence": "simulation", "tldr": "First error-correction scheme for in-situ analog MVM in memristive DNN accelerators: data-aware AN/ABN arithmetic codes that survive the crossbar's additions, reducing MNIST and ImageNet (AlexNet) misclassification by 1.5x and 1.1x for under 4.5% area and 4.7% energy overhead.", "summary": "Analog crossbar accelerators (ISAAC, PRIME, PipeLayer, Memristive Boltzmann Machine) compute dot products in-situ, so conventional ECC cannot be applied: SECDED codes do not preserve addition, and a small additive error in a bit-sliced column sum can flip many bits. The paper encodes weights with AN arithmetic codes (multiply each operand by an integer A before bit slicing), so the shift-and-add output remains a multiple of A; the residue mod A indexes a correction table, and an extra factor B=3 provides post-correction detection (ABN codes). Since random telegraph noise is strongly state-dependent (rows with fewer 1s or lower-resistance cells err less) and higher-order bit slices matter more, the correction table is built per array from predicted row error probabilities weighted by bit significance, and multiple operands are concatenated into a 128-bit coded word to amortise check bits. Evaluated with a Monte-Carlo simulator of an ISAAC-like accelerator (128x128 arrays, 16-bit weights, 1-5 bits/cell, NiO RTN model, stuck-at faults) on two MLPs and one CNN for MNIST plus AlexNet, the ECU is placed per IMA and fully pipelined.", "contributions": ["Shows SECDED ECC cannot protect in-situ crossbar sums and motivates arithmetic (AN) codes", "Data-aware ABN codes: per-array syndrome tables built from state-dependent RTN error probabilities and bit significance, with multi-operand coding and B=3 detection", "Pipelined error correction unit integrated into ISAAC IMAs (5 candidate A values, shared tables)", "Evaluation on MLPs/CNN (MNIST) and AlexNet (ImageNet) with RTN and stuck-at faults, plus area/power overheads"], "claims": [{"claim": "Analog crossbar errors materially hurt DNN accuracy even though individual cells read correctly.", "support": "Misclassification rises from 1% to 3% (MNIST) and 43% to 48% (ILSVRC-2012)", "loc": "Sec. I"}, {"claim": "Conventional SECDED ECC cannot protect in-situ additions in crossbars.", "support": "Adding two (8,4) Hamming-encoded values gives a result at Hamming distance 2 from the encoded sum even without errors", "loc": "Sec. III, Fig. 5"}, {"claim": "Data-aware ABN codes restore much of the noise-induced accuracy loss.", "support": "Eliminate misclassifications due to array noise for 1-bit cells and generally up to half for multi-bit cells; AlexNet top-1 48.3% -> 43.9% (software 42.96%)", "loc": "Sec. VIII-A, Fig. 10, Table III"}, {"claim": "The scheme can trade ECC for more bits per cell.", "support": "In MLP1, a 9-bit data-aware code with 4-bit cells matches an uncorrected array with 2-bit cells", "loc": "Sec. VIII-A"}, {"claim": "Overheads are modest and throughput is unaffected.", "support": "6.3% tile area (5.3% chip area), 5.8% chip power; ECU fully pipelined", "loc": "Sec. VIII-B, Table IV"}], "results": ["AlexNet (ImageNet) top-1 misclassification: software 42.96%, uncorrected 48.3%, ABN-9 43.9%; top-5: 19.74% / 21.3% / 20.1% (Table III)", "MNIST misclassification increased from 1-2% (software) to 3-4% (MLPs) and 2-3% (CNN) by array noise; ABN codes remove up to about half of that increase (Fig. 10)", "SPICE model of a 128-cell row with 2 bits/cell shows a 14.5% raw row error rate (13.9% high, 0.51% low) (Sec. IV)", "Overhead: ECU 3.4% of an ISAAC tile; total 6.3% tile area, 5.3% chip area, 5.8% chip power (Sec. VIII-B)"], "limitations": ["Simulation only (Monte-Carlo with SPICE-derived error model); no silicon", "Error model is dominated by an RTN model for NiO with chosen parameters; real-array effects such as IR drop are compensated by assumption", "Assumes per-array characterisation/prediction of row error rates and searching A values at programming time", "AlexNet evaluated at a single design point (2-bit cells, 9 check bits) because of simulation cost", "Corrects quantised-output errors at ADC granularity; does not address drift or analog conductance variations beyond 1% programming error"], "remarks": "A rare architecture-level treatment of error correction for analog MVM, and the paper that made the point that crossbar errors are additive syndromes on sums, not bit flips. The evidence is simulation with a specific RTN model, and the gains on ImageNet (1.1x) are modest; later work (PUMA, VECOM, LLM-on-memristor papers) cites it mainly as the ECC baseline. For mapping it matters because coding interacts with bit slicing and cells per weight, i.e. it changes how many crossbar columns a weight occupies.", "basis": "full-text", "pdf_source_url": "https://www.bfeinberg.com/hpca18.pdf", "abstract": "Deep neural networks (DNNs) have attracted substantial interest in recent years due to their superior performance on many classification and regression tasks as compared to other supervised learning models. DNNs often require a large amount of data movement, resulting in performance and energy overheads. One promising way to address this problem is to design an accelerator based on in-situ analog computing that leverages the fundamental electrical properties of memristive circuits to perform matrix-vector multiplication. Recent work on analog neural network accelerators has shown great potential in improving both the system performance and the energy efficiency. However, detecting and correcting the errors that occur during in-memory analog computation remains largely unexplored. The same electrical properties that provide the performance and energy improvements make these systems especially susceptible to errors, which can severely hurt the accuracy of the neural network accelerators. This paper examines a new error correction scheme for analog neural network accelerators based on arithmetic codes. The proposed scheme encodes the data through multiplication by an integer, which preserves addition operations through the distributive property. Error detection and correction are performed through a modulus operation and a correction table lookup. This basic scheme is further improved by data-aware encoding to exploit the state dependence of the errors, and by knowledge of how critical each portion of the computation is to overall system accuracy. By leveraging the observation that a physical row that contains fewer 1s is less susceptible to an error, the proposed scheme increases the effective error correction capability with less than 4.5% area and less than 4.7% energy overheads. When applied to a memristive DNN accelerator performing inference on the MNIST and ILSVRC-2012 datasets, the proposed technique reduces the respective misclassification rates by 1.5x and 1.1x.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2018_Feinberg_DataAwareABNCodes_HPCA.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2018_Feinberg_DataAwareABNCodes_HPCA.pdf", "priority": 7.33}, {"id": "W2625840880", "short": "Defect Rescuing", "title": "Rescuing Memristor-based Neuromorphic Design with High Defects", "authors": ["Chenchen Liu", "Miao Hu", "John Paul Strachan", "Hai Helen Li"], "year": 2017, "venue": "", "venue_short": "DAC", "venue_full": "Proceedings of the 54th Annual Design Automation Conference (DAC 2017)", "venue_ok": true, "doi": "https://doi.org/10.1145/3061639.3062310", "cites_global": 260, "cat": "06", "seed": false, "devices": ["Memristor(generic)"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "Identifies significant weights and uses defect-aware retraining plus remapping to make a memristor-crossbar neural network tolerate stuck-at defects, recovering almost full MNIST accuracy (92.64% baseline, two-layer network) with 20% random defects, evaluated with real device test data.", "summary": "As memristor crossbars scale in density, bit failures (stuck cells) become a critical issue that significantly degrades computation accuracy. The paper proposes a defect rescuing design: significant weights of a trained network are first identified, then retraining and remapping algorithms are applied so that the network tolerates the known defect locations in the crossbar. Remapping changes how the logical weight matrix is placed onto the physical crossbar so that important weights avoid defective cells, while retraining adapts the remaining weights to the defects. Evaluated on a two-layer network for MNIST (92.64% accuracy) using real device testing data from HP Labs memristors, the design recovers almost all of the accuracy when 20% random defects are present.", "contributions": ["Significance-based identification of weights critical to accuracy", "Defect-aware retraining algorithm for memristor crossbar networks", "Remapping algorithm placing significant weights away from defective cells", "Evaluation with real device test data showing recovery at 20% defect rate"], "claims": [{"claim": "Crossbar bit failures significantly degrade neural network computation accuracy as density grows.", "support": "Motivation in abstract", "loc": "Abstract"}, {"claim": "Retraining plus remapping recovers almost full accuracy with 20% random defects.", "support": "Two-layer MNIST network with 92.64% baseline 'can recover almost its full performance when 20% random defects are present'", "loc": "Abstract"}], "results": ["Two-layer MNIST network (92.64% baseline accuracy) recovers almost full accuracy under 20% random defects (abstract)"], "limitations": ["Abstract-only analysis; exact recovered accuracy and overheads not verified", "Very small workload (two-layer network, MNIST)", "Requires per-chip defect map and per-chip retraining/remapping", "Stuck-at defects only; analog noise, drift and IR drop not addressed per abstract"], "remarks": "An early and heavily cited (260+) DAC paper establishing the 'know the fault map, then retrain and remap' recipe for memristor crossbars; later in-set works (MT framework, RxNN, PANTHER, SAF/variation-tolerant mapping) cite it as the reference retraining-based approach. Its per-chip retraining requirement is the main criticism later papers address with retraining-free remapping or matrix transformations.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Memristor-based synaptic network has been widely investigated and applied to neuromorphic computing systems for the fast computation and low design cost. As memristors continue to mature and achieve higher density, bit failures within crossbar arrays can become a critical issue. These can degrade the computation accuracy significantly. In this work, we propose a defect rescuing design to restore the computation accuracy. In our proposed design, significant weights in a specified network are first identified and retraining and remapping algorithms are described. For a two layer neural network with 92.64% classification accuracy on MNIST digit recognition, our evaluation based on real device testing shows that our design can recover almost its full performance when 20% random defects are present.", "review": [], "pdf_expected": "06_Nonidealities_and_Reliability/2017_Liu_DefectRescuing_DAC.pdf", "analysed": true, "pdf": "06_Nonidealities_and_Reliability/2017_Liu_DefectRescuing_DAC.pdf", "priority": 7.71}, {"id": "W7134259416", "short": "Device Spec Methodology", "title": "Methods for Setting Device Specifications for Analog In‐Memory Computing Inference", "authors": ["Zhenyu Wu", "Xin Su", "Malte J. Rasch", "Ning Li"], "year": 2026, "venue": "Advanced Intelligent Systems", "venue_short": "AdvIntellSyst", "venue_full": "Advanced Intelligent Systems", "venue_ok": true, "doi": "https://doi.org/10.1002/aisy.202501355", "cites_global": 0, "cat": "07", "seed": true, "devices": ["PCM"], "models": ["CNN", "LSTM/RNN", "Transformer"], "evidence": "algorithm+simulation", "tldr": "Proposes a systematic methodology for mapping the multidimensional device-specification space (memory window, read/program noise, conductance drift) needed for PCM-based analog in-memory computing to reach floating-point-equivalent inference accuracy, showing that multiple co-optimized specification families achieve comparable accuracy.", "summary": "The paper addresses how to set target device specifications for analog in-memory computing (AIMC) inference hardware based on non-volatile memory, using phase-change memory (PCM) as the representative device. It argues that key device parameters (memory window, read noise, program noise, conductance drift) are strongly interdependent, so specifying them independently is suboptimal; tightening one parameter can relax requirements on another. The authors propose a methodology for systematically exploring this coupled, multidimensional specification space to identify sets of device parameters that still achieve floating-point-equivalent accuracy after hardware-aware training. They evaluate the approach across CNN, RNN, and Transformer architectures, finding that several different combinations of device specifications (not just the tightest/most ideal ones) can deliver comparable inference accuracy, which gives hardware designers flexibility to trade off which parameters to prioritize for manufacturability and cost. The work is positioned as a practical bridge between algorithm-level hardware-aware training research and device/fabrication-level specification targets.", "contributions": ["Proposes a systematic framework for exploring the joint (not independent) specification space of key PCM device parameters for AIMC inference", "Identifies the strong interdependence between memory window, read/program noise, and conductance drift and shows how trade-offs among them affect inference fidelity", "Cross-model evaluation spanning CNN, RNN, and Transformer architectures to assess generality of the specification methodology", "Identifies multiple distinct 'specification families' that achieve comparable, near-floating-point accuracy, enabling cost-flexible hardware design choices"], "claims": [{"claim": "Device specifications for AIMC must be co-optimized jointly rather than set independently because of strong parameter interdependence", "support": "Cross-model analysis shows tuning one parameter (e.g., noise) relaxes or tightens constraints on others (e.g., memory window, drift)", "loc": "Abstract"}, {"claim": "Multiple different specification sets can achieve comparable, floating-point-equivalent accuracy", "support": "Resulting analysis identifies families of specification sets delivering comparable accuracy across CNN/RNN/Transformer models", "loc": "Abstract"}], "results": ["No specific quantitative accuracy/noise numbers available from abstract alone"], "limitations": ["Full text not available to this reviewer; assessment based on abstract only, so methodology details, exact benchmarks, and numeric results could not be verified", "Representative device studied is PCM only; generality to ReRAM or other NVMs with different noise/drift statistics is not confirmed in the abstract"], "remarks": "Abstract-only assessment (no accessible full text; not found on arXiv, and the publisher — Wiley Advanced Intelligent Systems — is not an open-access source reachable from this environment). The paper appears to be a device/algorithm co-design study from authors associated with PCM-based AIMC work (including the IBM AIHWKIT lead author), likely using hardware-aware training simulation to derive specification targets; its core contribution — treating device specs as a coupled multidimensional space rather than independent knobs — is a useful conceptual framing for thesis work on mapping models to analog hardware, but the lack of full text means specific numbers and claims cannot be independently verified here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Analog in‐memory computing (AIMC) based on non‐volatile memories (NVMs) offers a transformative pathway toward ultra‐energy‐efficient deep learning, enabling high‐speed, low‐power inference with scalable performance. Recent progress has demonstrated floating‐point‐level accuracy through hardware‐aware training, highlighting AIMC's potential to rival conventional digital architectures. As NVM technologies for AIMC continue to advance, a systematic framework for defining device specification targets is critical for balancing inference accuracy and fabrication cost. Key device parameters, such as memory window, read and program noise, and conductance drift, directly influence inference fidelity across different time scales while simultaneously affecting manufacturability. Their strong interdependence complicates optimization, as tuning one parameter can relax or tighten constraints on others. To address this challenge, we propose a comprehensive methodology for mapping the multidimensional device specification space required to achieve floating‐point‐equivalent accuracy, using phase‐change memory (PCM) as a representative platform. Cross‐model evaluations on convolutional neural networks, recurrent neural networks, and transformer architectures reveal that device characteristics must be co‐optimized within this coupled landscape. The resulting analysis identifies families of specification sets that deliver comparable accuracy, enabling flexible, cost‐effective hardware design and paving the way for scalable, commercially viable AIMC deployment.", "review": [{"fid": "F9", "text": "Device non-idealities are the physical limit and span a hierarchy, not just the material: memory window, read noise, program noise and conductance drift act on different time scales while constraining manufacturability; errors originate at device, array, architecture and algorithm levels. NVM writes cost 1–2 orders of magnitude more latency and energy per bit than SRAM, with ~106–109 write endurance.", "grade": "High confidence", "vote": "3–0 unanimous", "note": "Wiley Adv. Intelligent Systems 2026 · Nature Materials 2026 · X-Former"}, {"fid": "F14", "text": "The field's framing of its own open problem has shifted: since floating-point-level inference accuracy has been demonstrated via hardware-aware training, the question is no longer whether analog can match digital accuracy but what device specifications are required at what fabrication cost — motivating systematic methodologies for mapping the multidimensional device-specification space, with PCM as the representative platform.", "grade": "Medium confidence", "vote": "3–0 unanimous", "note": "Graded medium: a research-agenda framing statement from a single recent paper, and it understates the residual gap seen at larger model scale (see F3, F10)."}], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2026_Wu_DeviceSpecMethodology_AdvIntellSyst.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2026_Wu_DeviceSpecMethodology_AdvIntellSyst.pdf", "priority": 6.5}, {"id": "W4411725113", "short": "CS-PCM Vision System", "title": "Attention-driven PCM-based In-Memory Computing for Smart Vision Systems", "authors": ["Adnan Haidar", "Amir Khan", "Vasileios G. Ntinas", "Jorge Fernández‐Berni", "Ricardo Carmona‐Galán", "Ronald Tetzlaff"], "year": 2025, "venue": "", "venue_short": "ISCAS", "venue_full": "IEEE International Symposium on Circuits and Systems (ISCAS 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/iscas56072.2025.11044041", "cites_global": 2, "cat": "07", "seed": false, "devices": ["PCM"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "An energy-efficient edge vision system combining compressed sensing for on-sensor dimensionality reduction with a single-layer ANN on PCM crossbars, using attention-regularized hardware-aware training to keep face-recognition accuracy stable under PCM conductance drift.", "summary": "The paper targets low-power edge vision, proposing a system that pairs compressed sensing (CS) for dimensionality reduction at the sensor with a single-layer artificial neural network implemented on Phase-Change-Memory (PCM) crossbars for inference. CS produces a low-dimensional feature vector fed directly into the PCM-based ANN, avoiding the cost of processing full-resolution images. To counter PCM hardware non-idealities, the authors apply hardware-aware (HWA) training augmented with an attention-based regularization mechanism intended to prioritize critical features, improving both inference stability and resilience to long-term conductance drift. On a face-recognition task, the attention-enhanced HWA training reduces overfitting and sustains accuracy under simulated PCM drift conditions.", "contributions": ["Integrates compressed sensing (on-sensor dimensionality reduction) with a PCM-crossbar-based single-layer ANN for an end-to-end low-power edge inference pipeline", "Introduces an attention-based regularization mechanism added to standard hardware-aware (HWA) training to prioritize critical features and improve drift resilience", "Evaluates the approach on a face-recognition task, showing improved inference stability and reduced overfitting under PCM drift versus standard HWA training"], "claims": [{"claim": "Attention-enhanced hardware-aware training mitigates overfitting and maintains face-recognition accuracy under PCM conductance drift better than standard HWA training", "support": "Qualitative claim stated in the abstract; no specific numeric accuracy values given", "loc": "Abstract"}], "results": [], "limitations": ["Abstract gives no specific quantitative accuracy/drift numbers, so the magnitude of improvement over standard HWA training cannot be verified from the abstract alone", "Evaluated on a single-layer ANN and a single task (face recognition); generalization to deeper networks or other tasks is untested per the abstract", "Likely simulation-based (PCM device/drift models) rather than measured on fabricated PCM hardware; full text not available to confirm"], "remarks": "This is one of two related papers in this batch (with the Haidar/Ntinas/Tetzlaff Drift-Aware Regularization AICAS paper) from the same group exploring attention-based regularization for PCM drift resilience; together they suggest a developing research thread on using feature-importance-style regularization during hardware-aware training as a lightweight alternative/complement to global drift-compensation techniques. Without the full text, the practical significance (effect size, comparison baselines) cannot be assessed here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "As demand grows for efficient edge computing systems, innovative architectures are crucial for achieving low-power, high-density data processing in resource-constrained environments. Compressed sensing (CS) and Analog In-Memory Computing (AIMC) offer promising pathways to meet these needs by enabling localized, efficient feature extraction and inference. This paper introduces an energy-efficient on-chip system that integrates CS with AIMC based on Phase-Change Memory (PCM) devices to enable robust feature extraction and inference. The proposed architecture employs CS for dimensionality reduction at the sensor level, generating low-dimensional feature vectors directly fed into a single-layer artificial neural network (ANN) implemented on PCM crossbars. To address inherent hardware non-idealities, we utilize hardware-aware (HWA) training combined with an attention-based regularization mechanism, improving both inference stability and drift resilience over extended periods. Performance evaluation on a face recognition task demonstrates that attention-enhanced HWA training effectively mitigates overfitting and maintains model accuracy under PCM drift conditions, highlighting the system's suitability for edge computing applications requiring low power consumption and long-term reliability.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2025_Haidar_CSPCMVisionSystem_ISCAS.pdf", "analysed": true, "pdf": null, "priority": 4.33}, {"id": "W4407751056", "short": "Inherent Adversarial Robustness of AIMC", "title": "The inherent adversarial robustness of analog in-memory computing", "authors": ["Corey Lammie", "Julian Büchel", "Athanasios Vasilopoulos", "Manuel Le Gallo", "Abu Sebastian"], "year": 2025, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-025-56595-2", "cites_global": 12, "cat": "07", "seed": false, "devices": ["PCM"], "models": ["CNN", "Transformer"], "evidence": "device-experiment", "tldr": "Experiments on IBM's HERMES PCM-based AIMC chip show that intrinsic stochastic device noise (both recurrent and non-recurrent) measurably increases robustness to evasion adversarial attacks compared to digital and floating-point baselines, and simulations show the effect persists for a much larger RoBERTa transformer on an NLP task.", "summary": "The paper experimentally tests the long-speculated conjecture that non-deterministic analog in-memory computing (AIMC) substrates are inherently more robust to adversarial attacks than deterministic digital hardware. Using IBM's 64-core HERMES PCM-based AIMC chip running a CIFAR-10 CNN, the authors compare adversarial success rate (ASR) and accuracy under PGD, Square and OnePixel attacks across floating-point, hardware-aware-trained, fixed-point digital, and AIMC chip/chip-model targets, including hardware-in-the-loop attacks where the attacker has full chip access. They then isolate which noise sources (recurrent vs non-recurrent, weight vs output) drive the effect by selectively injecting/disabling noise types in the chip model at matched accuracy-drop levels. Finally, they use simulation to test whether the effect generalizes to a much larger pretrained RoBERTa transformer fine-tuned for a sentence-pair NLP task under the GBDA attack. The central finding is that AIMC's inherent stochasticity provides adversarial robustness 'for free' (without extra training or accuracy cost beyond the baseline hardware-aware accuracy loss), with output noise contributing more than weight noise, and this benefit persists even for a transformer and a different input modality.", "contributions": ["First experimental validation (rather than simulation-only) of adversarial robustness of AIMC on a real PCM-based chip (IBM HERMES Project Chip)", "Evaluation against multiple evasion attack types (PGD, Square, OnePixel) and both standard and hardware-in-the-loop (full chip access) attack settings", "Ablation isolating which stochastic noise properties (recurrence, location, type) are responsible for the robustness, via controlled noise injection in a calibrated chip model", "Simulation study extending the finding to a much larger pretrained RoBERTa transformer on an NLP task under the GBDA attack", "Shows the robustness benefit comes at no extra training/accuracy cost beyond standard hardware-aware training"], "claims": [{"claim": "The AIMC chip is more adversarially robust than deterministic digital hardware at comparable accuracy", "support": "AIMC chip/chip-model test accuracies of 84.31%/84.85% (drops of 4.11%/3.57% from floating-point) show lower ASR envelopes than the floating-point and digital fixed-point (8-bit act/4-bit weight) baselines across PGD, Square, and OnePixel attacks", "loc": "Results, Fig. 2"}, {"claim": "Robustness holds even under hardware-in-the-loop attacks where the attacker has full chip access", "support": "Additional robustness is observed when attacks are generated and evaluated directly on the AIMC chip/chip model compared to the digital hardware accelerator", "loc": "Results, Fig. 4 / hardware-in-the-loop section"}, {"claim": "Both recurrent and non-recurrent stochastic noise sources contribute to robustness, with output noise having a larger effect than weight noise", "support": "At matched 5% test-accuracy drop, a model with only output noise shows the highest robustness while a model with only weight noise is least robust; the AIMC chip/chip-model falls between the two", "loc": "Results, Fig. 3c-e"}, {"claim": "The recurrence property of noise does not change average test accuracy but does affect ASR distribution/variance", "support": "At matched accuracy drop (5% or 10%), recurrent vs non-recurrent noise of similar magnitude gives similar mean accuracy but different ASR envelopes across n=10 repetitions", "loc": "Results, Fig. 3a-b"}, {"claim": "The robustness effect generalizes beyond CNN/vision to a much larger transformer model on NLP", "support": "Simulations of a pretrained RoBERTa model fine-tuned for a sentence-pair task, attacked with GBDA, show additional adversarial robustness for the AIMC chip model versus baseline digital platforms", "loc": "Results, Fig. 5 / 'Applicability to transformer-based models'"}], "results": ["CIFAR-10 CNN on IBM HERMES PCM chip: test accuracy 84.31% (chip) / 84.85% (chip model), i.e., 4.11%/3.57% drop vs floating-point, with lower adversarial success rate across PGD, Square, OnePixel attacks than floating-point and digital fixed-point (8-bit activation/4-bit weight) baselines", "ASR is largely independent of test-set accuracy except in extreme cases (test accuracy < 25%)", "At matched 5%/10% accuracy drop, output-noise-only model is most robust, weight-noise-only model is least robust, with the real AIMC chip/chip-model falling in between", "RoBERTa transformer (NLP, sentence-pair task) under GBDA attack: additional adversarial robustness observed on the simulated AIMC chip model compared to digital baselines"], "limitations": ["Core experimental result is on a single CNN/CIFAR-10 workload and one PCM chip (HERMES); the transformer result is simulation-only, not measured on silicon", "Robustness is tied to a specific accuracy-drop operating point; the paper notes accuracy loss itself (not just noise type) partly explains attack sensitivity in extreme regimes (<25% accuracy)", "Evaluated attack set is evasion-based (PGD, Square, OnePixel, GBDA); other attack families (e.g., poisoning, transfer attacks from surrogate models) are not studied", "Benefit is a byproduct of uncontrolled device noise rather than a designed defense, so the achievable robustness level is not tunable independently of accuracy/noise trade-offs without further study", "Relies on IBM's proprietary HERMES chip and AIHWKIT-based noise modeling, limiting independent reproducibility on other PCM/ReRAM platforms"], "remarks": "This is a well-controlled, first-of-its-kind hardware validation of a long-standing conjecture in the AIMC literature, strengthening the case that analog non-idealities are not purely a liability but can double as a free adversarial defense. For mapping models onto crossbars, it suggests hardware-aware training pipelines could be tuned to preserve or even enhance this noise-derived robustness rather than treating all noise as something to be calibrated away; however, since the benefit is an emergent side effect of stochasticity rather than a controllable design knob, more work (cited by later papers on HWA training and PEFT on AIMC) is needed to turn it into a reliable, quantifiable security property.", "basis": "full-text", "pdf_source_url": "", "abstract": "A key challenge for deep neural network algorithms is their vulnerability to adversarial attacks. Inherently non-deterministic compute substrates, such as those based on analog in-memory computing, have been speculated to provide significant adversarial robustness when performing deep neural network inference. In this paper, we experimentally validate this conjecture for the first time on an analog in-memory computing chip based on phase change memory devices. We demonstrate higher adversarial robustness against different types of adversarial attacks when implementing an image classification network. Additional robustness is also observed when performing hardware-in-the-loop attacks, for which the attacker is assumed to have full access to the hardware. A careful study of the various noise sources indicate that a combination of stochastic noise sources (both recurrent and non-recurrent) are responsible for the adversarial robustness and that their type and magnitude disproportionately effects this property. Finally, it is demonstrated, via simulations, that when a much larger transformer network is used to implement a natural language processing task, additional robustness is still observed. Adversarial attacks threaten deep neural networks. Here, authors show analog in-memory computing chips enhance robustness, attributed to stochastic noise properties. This is validated experimentally and in simulations with larger transformer models.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2025_Lammie_InherentAdversarialRobustnessAIMC_NatCommun.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2025_Lammie_InherentAdversarialRobustnessAIMC_NatCommun.pdf", "priority": 6.21}, {"id": "W4414758157", "short": "CIMNAS", "title": "CIMNAS: A Joint Framework for Compute-In-Memory-Aware Neural Architecture Search", "authors": ["Olga Krestinskaya", "Mohammed E. Fouda", "Ahmed M. Eltawil", "Khaled N. Salama"], "year": 2025, "venue": "IEEE transactions on circuits and systems for artificial intelligence.", "venue_short": "TCASAI", "venue_full": "IEEE Transactions on Circuits and Systems for Artificial Intelligence", "venue_ok": true, "doi": "https://doi.org/10.1109/tcasai.2025.3617422", "cites_global": 1, "cat": "07", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["CNN", "ResNet", "MLP"], "evidence": "algorithm+simulation", "tldr": "CIMNAS is an evolutionary-algorithm-based hardware-aware NAS that jointly searches neural-architecture, quantization and CIM hardware (device/circuit/architecture) parameters over a 9.9x10^85-combination space, cutting MobileNet-on-RRAM EDAP by 90-104.5x at 73.81% ImageNet accuracy, and ResNet50-on-SRAM EDAP by up to 819.5x with only a 0.6 percentage-point accuracy drop.", "summary": "The paper targets the combinatorial design problem of co-optimizing neural-network architecture, quantization policy, and CIM accelerator hardware (device bits-per-cell, operating voltage, cycle time, crossbar size, macros-per-tile, tiles-per-router, tile-groups-per-chip, global buffer size) jointly rather than sequentially, since prior HW-NAS work either fixes the hardware, fixes the model, or jointly optimizes only a limited parameter subset. CIMNAS builds a joint search space (5.9x10^38 model configurations x quantization choices x a 1.4x10^7-combination hardware space, totalling 9.9x10^85) on top of a pretrained full-precision MobileNetV2 supernetwork, uses an accuracy predictor (to avoid retraining each sampled design) plus the CiMLoop simulator for hardware metrics, and searches with an evolutionary algorithm (chosen over differentiable search and RL/Bayesian optimization for scalability to discrete, huge joint spaces) to minimize an EDAP-focused objective while constraining against accuracy loss via supernetwork-derived sampling. On an RRAM-based MobileNet/ImageNet setup, CIMNAS finds designs with 90.1x-104.5x lower energy-delay-area product (EDAP), 4.68x-4.82x higher TOPS/W, and 11.3x-12.78x higher TOPS/mm^2 than baselines while holding 73.81% accuracy. Applying the same framework to a 7nm SRAM-based ResNet50 design shows its generality: the best found design reaches 77.6% Top-1 / 91.2% Top-5 accuracy (a 0.6pp drop from the 78.2%/91.8% 8-bit baseline) while cutting EDAP by 251.1x (vs. a median baseline) and 819.5x (vs. a random-1000-sample baseline).", "contributions": ["Formulates a single joint search space spanning neural-architecture (5.9x10^38), quantization-policy, and device/circuit/architecture-level CIM hardware parameters (1.4x10^7), totalling 9.9x10^85 combinations", "Uses an evolutionary algorithm over a pretrained supernetwork plus accuracy predictor and the CiMLoop hardware simulator to make this scale of joint search tractable, avoiding per-candidate retraining or full hardware simulation", "Sets EDAP (energy-delay-area product) as the primary optimization objective while implicitly preserving accuracy via supernetwork-constrained sampling, rather than requiring an explicit accuracy-loss penalty", "Demonstrates large EDAP, TOPS/W and TOPS/mm^2 gains for an RRAM-based MobileNet/ImageNet design at competitive accuracy, outperforming prior CIM HW-NAS frameworks (e.g. Gibbon, AnalogNAS, CoMN, XPert) compared via a common baseline-EDAP-ratio/accuracy-drop metric", "Shows framework generality by porting CIMNAS to a different backbone (ResNet50), different device technology (SRAM-based CIM) and a different technology node (7nm), with large EDAP gains and negligible (0.6pp) accuracy loss", "Releases CIMNAS source code publicly on GitHub"], "claims": [{"claim": "CIMNAS reduces EDAP by 90.1x-104.5x for an RRAM-based MobileNet/ImageNet design relative to baselines, while maintaining 73.81% accuracy", "support": "Reported 90.1x-104.5x EDAP reduction, 4.68x-4.82x TOPS/W improvement, 11.3x-12.78x TOPS/mm^2 improvement, 73.81% accuracy", "loc": "Abstract; Sec. IV results"}, {"claim": "Unlike other state-of-the-art CIM HW-NAS methods, CIMNAS achieves EDAP-focused optimization without accuracy loss", "support": "Comparison table (Table I) shows other methods (ResNet32/ResNet20/DenseNets/VGG11-based approaches) incur accuracy drops of up to 11.0% or more, while CIMNAS designs show accuracy changes of only +/-0.6-0.8 percentage points at far larger EDAP reductions", "loc": "Table I"}, {"claim": "The framework generalizes across backbone, device technology, and process node", "support": "Ported to 7nm SRAM-based ResNet50: best found design reaches 77.6% Top-1 / 91.2% Top-5 accuracy (vs. 78.2%/91.8% 8-bit baseline, a 0.6pp drop) while cutting EDAP by 251.1x vs. a median-configuration baseline and 819.5x vs. a random-1000-sample baseline", "loc": "Sec. IV-B, Fig. 5(c)"}, {"claim": "An evolutionary algorithm scales better than differentiable search or RL/Bayesian optimization for this joint, discrete, huge-dimensional search space", "support": "Differentiable search (DARTS-style) requires training a supernetwork over days and cannot scale to joint discrete hardware search; RL/Bayesian methods like BANANAS need hundreds of surrogate samples (283.2 GPU-hours) and degrade in high-dimensional spaces", "loc": "Sec. III-C discussion of search algorithms, Table II"}], "results": ["RRAM-based MobileNet/ImageNet: 90.1x-104.5x EDAP reduction, 4.68x-4.82x TOPS/W improvement, 11.3x-12.78x TOPS/mm^2 improvement vs. various baselines, at 73.81% accuracy", "SRAM-based 7nm ResNet50: 77.6% Top-1 / 91.2% Top-5 accuracy (0.6pp drop from 78.2%/91.8% 8-bit baseline); EDAP reduced 251.1x vs. median-configuration baseline and 819.5x vs. random-1000-sample baseline", "Most compact full-precision supernetwork variant (smallest per-layer configuration across all layers) achieves 64.9% accuracy on ImageNet as a reference point for the model search space", "CiMLoop hardware simulator (used for hardware-metric evaluation) reports ~3% average error vs. ground truth, per the cited CiMLoop paper", "Total joint search space size: 9.9x10^85 combinations (5.9x10^38 model x quantization space combined with a 1.4x10^7 hardware space)"], "limitations": ["Accuracy during search is estimated via a trained accuracy predictor rather than full retraining/fine-tuning of every candidate; only the top-selected networks are fine-tuned for final reported accuracy", "Hardware metrics come from the CiMLoop simulator (itself reporting ~3% average error vs. hardware), not from fabricated chips or circuit-level SPICE simulation of the searched designs", "Evaluated on two specific architecture families (MobileNetV2/RRAM and ResNet50/SRAM); generalization to Transformer/LLM workloads or other device types (PCM, FeFET, MRAM) is not demonstrated", "EDAP reduction magnitude is reported relative to specific chosen baselines (median-parameter and random-1000-sample configurations), which affects the absolute multiplier and complicates cross-paper comparison, as the authors themselves note for comparing against other frameworks"], "remarks": "This is a well-benchmarked simulation/algorithm paper (not measured silicon) that directly engages with the HW-NAS-for-CIM literature via an explicit baseline-EDAP-ratio/accuracy-drop comparison table, which is a useful meta-contribution for navigating that literature. For model-to-crossbar mapping research, the key insight is architectural: jointly searching model, quantization and hardware parameters (rather than two-stage or hardware-fixed search) lets EDAP optimization draw most of its gains from the hardware-parameter dimensions (crossbar size, tiling, voltage/cycle time) when that subspace dominates sensitivity, as shown by the ResNet50/SRAM experiment achieving an even larger EDAP win with negligible accuracy cost. The reliance on simulated hardware metrics (CiMLoop) and a learned accuracy predictor means the absolute multipliers should be read as design-space exploration results rather than verified hardware outcomes.", "basis": "full-text", "pdf_source_url": "", "abstract": "To maximize hardware efficiency and performance accuracy in Compute-In-Memory (CIM)-based neural network accelerators for Artificial Intelligence (AI) applications, co-optimizing both software and hardware design parameters is essential. Manual tuning is impractical due to the vast number of parameters and their complex interdependencies. To effectively automate the design and optimization of CIM-based neural network accelerators, hardware-aware neural architecture search (HW-NAS) techniques can be applied. This work introduces CIMNAS, a joint model-quantization-hardware optimization framework for CIM architectures. CIMNAS simultaneously searches across software parameters, quantization policies, and a broad range of hardware parameters, incorporating device-,circuit-, and architecture-level co-optimizations. CIMNAS experiments were conducted over a search space of 9.9×1085potential parameter combinations with the MobileNet model as a baseline and RRAM-based CIM architecture. Evaluated on the ImageNet dataset, CIMNAS achieved a reduction in energy-delay-area product (EDAP) ranging from 90.1× to 104.5×, an improvement in TOPS/W between 4.68× and 4.82×, and an enhancement in TOPS/mm2from 11.3× to 12.78× relative to various baselines, all while maintaining an accuracy of 73.81%. The adaptability and robustness of CIMNAS are demonstrated by extending the framework to support the SRAM-based ResNet50 architecture, achieving up to an 819.5× reduction in EDAP. Unlike other state-of-the-art methods, CIMNAS achieves EDAP-focused optimization without any accuracy loss, generating diverse software-hardware parameter combinations for high-performance CIM-based neural network designs. The source code of CIMNAS is available athttps://github.com/OlgaKrestinskaya/CIMNAS.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2025_Krestinskaya_CIMNAS_TCASAI.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2025_Krestinskaya_CIMNAS_TCASAI.pdf", "priority": 4.21}, {"id": "W4414499786", "short": "Drift-Aware PCM Regularization", "title": "Drift-Aware Regularization for Long-Term Stability in Phase-Change Memory Based Neural Network Implementations", "authors": ["Adnan Haidar", "Vasileios G. Ntinas", "Ronald Tetzlaff"], "year": 2025, "venue": "", "venue_short": "AICAS", "venue_full": "IEEE International Conference on Artificial Intelligence Circuits and Systems (AICAS 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/aicas64808.2025.11173140", "cites_global": 1, "cat": "07", "seed": false, "devices": ["PCM"], "models": ["MLP"], "evidence": "simulation", "tldr": "A drift-aware regularization framework with attention-based feature prioritization, layered on top of hardware-aware training, cuts a simulated 5-year PCM conductance-drift classification error on MNIST from 9.14% (standard HWA training) to 3.75%, and to 2.12% when combined with global drift compensation.", "summary": "PCM crossbars suffer conductance drift that degrades inference accuracy over months to years, a key obstacle to long-term deployment of PCM-based analog in-memory computing (AIMC). The paper proposes a drift-aware regularization framework that stabilizes weight drift during training, complemented by an attention-based mechanism that prioritizes critical features, going beyond standard hardware-aware (HWA) training. Evaluated with a 5-year drift simulation on a benchmark two-layer perceptron trained on MNIST, the method reduces classification error from 9.14% (standard HWA training) to 3.75%; combining it with global drift compensation further reduces error to 2.12%.", "contributions": ["Proposes a drift-aware regularization framework that stabilizes PCM weight drift during training, beyond standard hardware-aware (HWA) training", "Adds an attention-based mechanism that prioritizes critical features to further improve drift resilience", "Shows the method can be combined with global drift compensation for additional improvement", "Quantifies long-term (5-year simulated) robustness on a benchmark MNIST two-layer-perceptron task"], "claims": [{"claim": "Drift-aware regularization substantially reduces long-term classification error versus standard hardware-aware training", "support": "5-year drift simulation: 3.75% classification error with drift-aware regularization vs. 9.14% with standard HWA training on a two-layer perceptron for MNIST", "loc": "Abstract"}, {"claim": "Combining drift-aware regularization with global drift compensation further improves long-term accuracy", "support": "Error further reduced to 2.12% when combined with global drift compensation", "loc": "Abstract"}], "results": ["5-year simulated PCM drift: 9.14% classification error with standard HWA training vs. 3.75% with drift-aware regularization (two-layer perceptron, MNIST)", "2.12% classification error when drift-aware regularization is combined with global drift compensation"], "limitations": ["Evaluated on a single small benchmark (two-layer perceptron on MNIST); generalization to deeper/larger networks or other tasks is not demonstrated in the abstract", "Drift evaluation is a simulation over 5 (simulated) years rather than a measured long-term PCM hardware study", "Abstract does not specify the PCM drift model or hyperparameters used for the regularization, limiting independent assessment of mechanism novelty versus existing drift-compensation literature"], "remarks": "This is a companion piece to the same group's ISCAS paper (Attention-driven PCM-based In-Memory Computing for Smart Vision Systems) and builds directly on the existing PCM drift-compensation and HWA-training literature (Ambrogio's global drift compensation, Rasch's HWA training/AIHWKit, Kariyappa's noise-aware training). The reported error reduction (9.14%->3.75%, and to 2.12% with global drift compensation) is a meaningful relative improvement if confirmed by the full paper, and the idea of an attention-style feature-prioritizing regularizer as an add-on to standard HWA training is a lightweight, architecture-agnostic way to target drift specifically rather than noise in general -- useful context for comparing drift-mitigation strategies in a mapping-focused thesis.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Phase-Change Memory (PCM) based resistive crossbars are a promising technology for energy-efficient neural network inference in analog in-memory computing (AIMC) systems. However, a conductance drift in PCM devices degrades performance over time, posing a challenge for applications requiring long-term stability. In order to overcome such problems, we propose a drift-aware regularization framework that stabilizes weight drift during training, complemented by an attention-based mechanism to prioritize critical features. Our approach significantly improves upon traditional hardware-aware (HWA) training and achieves more robust inference performance in the presence of conductance drift. In a five-year drift simulation, our method reduces classification error to 3.75%, compared to 9.14% with standard HWA training on a benchmark two-layer perceptron for the MNIST dataset. When combined with global drift compensation, the error is further reduced to 2.12%. These results demonstrate the effectiveness of our drift-aware regularization in enhancing the stability and accuracy of neural networks on AIMC hardware, offering a scalable, energy-efficient solution for inference in resource-constrained environments.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2025_Haidar_DriftAwarePCMRegularization_AICAS.pdf", "analysed": true, "pdf": null, "priority": 4.21}, {"id": "W4405718102", "short": "Non-Ideal PIM Fine-Tuning", "title": "Improving DNN Accuracy on MLC PIM via Non-Ideal PIM Device Fine-Tuning", "authors": ["Hao Lv", "Lei Zhang", "Ying Wang"], "year": 2024, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2024.3521195", "cites_global": 38, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "The paper recasts model-accuracy recovery on multilevel RRAM (one-to-one weight-cell mapping, no precise programming) as a non-ideal PIM device optimization problem and proposes a knowledge-distillation-guided fine-tuning scheme that uses the on-chip model's own input/output to recover nearly all accuracy lost to device variation, beating variation-aware training by over 3%.", "summary": "Multilevel RRAM cells are attractive for one-to-one weight-cell mapping (better memory utilization than multi-cell encoding of a weight), but RRAM variation (device variation, read disturbance, limited on/off ratio) causes the mapped weight to deviate from its intended value, degrading model accuracy, and this problem is exacerbated as DNN model sizes grow. Rather than requiring precise weight programming (the conventional multi-cell-per-weight workaround), the authors frame post-deployment accuracy recovery on multilevel RRAM as a non-ideal PIM device optimization problem, and systematically study how different fine-tuning strategies behave when recovering accuracy under this non-ideal setting. Based on this analysis, they propose a fine-tuning scheme that leverages knowledge distillation together with the input/output behavior of the deployed (non-ideal) model itself to guide the fine-tuning process, restoring accuracy without needing precise weight programming or an accurate per-cell noise profile. Experiments show the scheme achieves nearly complete recovery of model performance on multilevel RRAM, improving accuracy by over 3% compared to variation-aware training baselines.", "contributions": ["Reframing of RRAM-variation-induced accuracy loss under one-to-one weight-cell mapping as a 'non-ideal PIM device optimization' problem rather than a programming-precision problem", "A systematic analysis of how various fine-tuning strategies perform at recovering accuracy under this non-ideal device setting", "A knowledge-distillation-based fine-tuning scheme that uses the deployed model's own input/output information (rather than requiring precise device-noise profiling) to guide recovery", "Demonstrated near-complete accuracy recovery and >3% improvement over variation-aware training approaches"], "claims": [{"claim": "The proposed fine-tuning scheme achieves nearly complete recovery of model accuracy under multilevel RRAM non-ideality", "support": "'achieving nearly complete recovery of model performance' (abstract)", "loc": "Abstract"}, {"claim": "The method outperforms variation-aware training baselines", "support": "'over a 3% improvement in model accuracy compared to variation-aware training approaches' (abstract)", "loc": "Abstract"}], "results": [">3% accuracy improvement over variation-aware training baselines", "Near-complete recovery of model performance under non-ideal multilevel RRAM device settings (exact accuracy figures not available from abstract alone)"], "limitations": ["Abstract-only analysis in this record: full text unavailable, so the exact fine-tuning/distillation algorithm, models/datasets used, and comparison baselines beyond 'variation-aware training' could not be verified", "Approach appears to require post-deployment fine-tuning access to the chip's own input/output behavior, which may have practical constraints (data availability, latency/energy cost of fine-tuning on edge) not assessable from the abstract"], "remarks": "This addresses a practically important variant of the hardware-aware training problem: most non-ideality-robustness work (e.g. this paper's own in-set references on accelerator-friendly training, program/verify schemes) either assumes training-time noise injection or write-verify at programming time, whereas this paper targets post-deployment recovery without precise programming, framed via knowledge distillation against the model's own non-ideal behavior. Because only the abstract was available, it is not possible to assess how this compares quantitatively to write-verify (program/verify) approaches or how much fine-tuning data/compute it requires, which would matter for its practicality on resource-constrained PIM edge devices.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive random access memory (RRAM) emerges as a promising technology for developing energy-efficient deep neural network (DNN) accelerators, owing to its analog computing paradigm for matrix-vector multiplication. However, the inherent nonideal device features of RRAM cells, such as device variation, read disturbances, and limited on/off ratio, present challenges for model deployment. Therefore, to ensure accurate storage and computing precision for RRAM-based accelerators, a widely used practice is encoding a DNN weight by multiple cells, resulting in significant memory overhead and underutilization. This challenge is further exacerbated by the rapid increases in model size witnessed in recent years. While the one-to-one weight-cell mapping strategy can improve memory utilization, it inevitably introduces deviations in the mapped DNN weight from the desired value due to RRAM variation issues, leading to model accuracy degradation. In response to this challenge, we abstract the model optimization on RRAM chips as a non-ideal PIM device optimization problem, aimed at optimizing model accuracy without the requirement of precise weight programming. We systematically analyze the model optimization behavior on multilevel RRAM devices by investigating the accuracy recovery process of various fine-tuning strategies in recovering model performance under the non-ideal PIM device setting. Based on the analysis, we propose a non-ideal PIM device finetune scheme to recover the model performance for multilevel RRAM under the non-ideal PIM device setting. Our proposed scheme leverages knowledge distillation and exploits input/output information of the model on RRAM to guide the fine-tuning process, finally restoring its accuracy. Experimental results demonstrate the efficacy of our non-ideal PIM device fine-tuning scheme, achieving nearly complete recovery of model performance. Our approach yields over a 3% improvement in model accuracy compared to variation-aware training approaches.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2024_Lv_NonIdealPIMFineTuning_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.11}, {"id": "W4400233540", "short": "AIMC Post-Training Opt", "title": "Improving the Accuracy of Analog-Based In-Memory Computing Accelerators Post-Training", "authors": ["Corey Lammie", "Athanasios Vasilopoulos", "Julian Büchel", "Giacomo Camposampiero", "Manuel Le Gallo", "Malte J. Rasch", "Abu Sebastian"], "year": 2024, "venue": "", "venue_short": "ISCAS", "venue_full": "IEEE International Symposium on Circuits and Systems (ISCAS 2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/iscas58744.2024.10558540", "cites_global": 10, "cat": "07", "seed": false, "devices": ["PCM"], "models": ["Transformer", "BERT"], "evidence": "algorithm+simulation", "tldr": "Two post-training (no-retraining) optimization methods for DAC input range and per-column conductance range recover nearly all the accuracy lost when these ranges are not hardware-aware-trained, on a PCM-calibrated RoBERTa/GLUE simulation.", "summary": "Hardware-aware (HWA) training for analog in-memory computing (AIMC) accelerators normally must learn per-crossbar input (DAC) and conductance ranges during training, which adds complexity and requires detailed hardware knowledge. The authors propose two post-training (PT) optimization algorithms, run after ordinary HWA training, that set the DAC input range per crossbar from a percentile of sampled activations and set each bit-line's conductance range to avoid ADC saturation while maximizing SNR. They evaluate on RoBERTa-base fine-tuned on all 8 GLUE tasks, using an AIHWKIT hardware model calibrated against a 1M-device PCM array (512x512 tiles, 8-bit PWM input, 8-bit ADC, differential weight mapping, drift/IR-drop modeled). Without range learning, PT optimization recovers accuracy close to the configuration where both ranges are explicitly learned during training (within 0.1% average GLUE score), and applying PT optimization even on top of learned ranges gives a further ~0.9% average improvement. Average GLUE score rises from 76.3 (weight clipping/IO quantization only) to 81.6 with full PT optimization plus learned ranges.", "contributions": ["Two post-training optimization algorithms (input-range percentile selection; per-bitline conductance-range rescaling to avoid ADC saturation) that remove the need to learn these ranges during HWA training", "Demonstration on RoBERTa-base across all 8 GLUE tasks with a PCM-calibrated AIHWKIT hardware model", "Shows PT optimization reduces training complexity/hyperparameters with negligible accuracy cost (<=0.1%) vs. learning ranges during training", "Shows PT optimization composes with learned ranges for a further accuracy gain (+0.9% avg)", "Establishes baseline PCM-simulated GLUE scores for RoBERTa as a reference point"], "claims": [{"claim": "PT range optimization matches training-time range learning to within 0.1% average GLUE accuracy", "support": "average score decreased by only 0.1% when optimized PT vs. learned, compared to 5.3% drop when neither learned nor PT-optimized", "loc": "Sec. VI Discussion"}, {"claim": "Combining learned ranges with further PT optimization improves accuracy", "support": "average score increased by 0.9% when both input and conductance ranges were learned and then optimized PT", "loc": "Sec. VI Discussion"}, {"claim": "Full PT optimization plus learned ranges gives the best overall GLUE average", "support": "average score increased from 76.3 (baseline weight clipping + I/O quant only) to 81.6 with best configuration", "loc": "Table II / Sec. VII Conclusion"}, {"claim": "MVM error grows over time due to PCM conductance drift", "support": "Fig. 2: at t=0 the L2 error of simulated vs ideal MVM output is ~14%, increasing with log(time)", "loc": "Fig. 2 / Sec. III"}], "results": ["Average GLUE score (RoBERTa-base, PCM-simulated, t=1h): 75.1 (no range learning/PT) -> 81.6 (learned input+conductance range plus PT optimization of both), vs. 85.9 ideal (noiseless FP) baseline", "PT-only optimization (no training-time range learning) reaches 80.7-81.4 average, within ~0.1% of the best training-time-learned configuration", "Baseline FP (noiseless) RoBERTa GLUE average: 85.9/100; mapped network uses 486 tiles at 61.57% average utilization for 124.6M parameters"], "limitations": ["Only evaluated on one model family (RoBERTa-base) and one hardware model (PCM, AIHWKIT-calibrated simulation)", "No physical hardware experiments; relies on an experimentally-calibrated but still simulated device/circuit model", "Sizeable residual accuracy gap vs. ideal FP baseline remains (e.g. 81.6 vs 85.9) even with best configuration", "Conductance range optimization hyperparameter (N=2 samples) was chosen empirically, not derived analytically", "Only short-term (t=1h) drift is evaluated in the main comparison; longer-term calibration behavior only briefly discussed"], "remarks": "A practically useful, incremental contribution from the IBM AIHWKIT/analog-AI group: it shows that much of the benefit of expensive hardware-aware range-learning can be recovered cheaply after standard training, which matters for reducing HWA-training cost on large transformer models. Evidence is simulation-only but uses a well-calibrated PCM device model from the same group's prior silicon work (64-core PCM chip, Joshi et al.), so the quantitative trends are credible even though absolute numbers are simulation-dependent. It is a narrow, single-architecture study rather than a general theory of PT calibration.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog-Based In-Memory Computing (AIMC) inference accelerators can be used to efficiently execute Deep Neural Network (DNN) inference workloads. However, to mitigate accuracy losses, due to circuit and device non-idealities, Hardware-Aware (HWA) training methodologies must be employed. These typically require significant information about the underlying hardware. In this paper, we propose two Post-Training (PT) optimization methods to improve accuracy after training is performed. For each crossbar, the first optimizes the conductance range of each column, and the second optimizes the input, i.e, Digital-to-Analog Converter (DAC), range. It is demonstrated that, when these methods are employed, the complexity during training, and the amount of information about the underlying hardware can be reduced, with no notable change in accuracy (≤0.1%) when finetuning the pretrained RoBERTa transformer model for all General Language Understanding Evaluation (GLUE) benchmark tasks. Additionally, it is demonstrated that further optimizing learned parameters PT improves accuracy.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2024_Lammie_AIMCPostTrainingOpt_ISCAS.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2024_Lammie_AIMCPostTrainingOpt_ISCAS.pdf", "priority": 6.53}, {"id": "W4402742347", "short": "Variation-Tolerant OU Framework", "title": "A Hardware Friendly Variation-Tolerant Framework for RRAM-Based Neuromorphic Computing", "authors": ["Fang-Yi Gu", "Cheng‐Han Yang", "Ing-Chao Lin", "Da-Wei Chang", "Darsen D. Lu", "Ulf Schlichtmann"], "year": 2024, "venue": "IEEE Transactions on Circuits and Systems I Regular Papers", "venue_short": "TCAS-I", "venue_full": "IEEE Transactions on Circuits and Systems I: Regular Papers (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcsi.2024.3443180", "cites_global": 10, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "A hardware-friendly variation-tolerant framework combines unary-based non-uniform weight quantization with a variation-aware Operation-Unit (OU) scheme (plus OU skipping/recombination/compensation) to cut RRAM conductance-variation-induced accuracy loss and ADC power on 2-bit-cell crossbars, outperforming prior methods on four NN models across two datasets.", "summary": "RRAM cells used in compute-in-memory DNN accelerators suffer from conductance variation that shifts stored weight values from their targets, degrading inference accuracy; the problem worsens as more wordlines/bitlines are concurrently activated, which also drives up ADC resolution requirements and power. The paper proposes a two-part methodology: a unary-based non-uniform quantization scheme that equalizes the significance of weights stored across RRAM cells (so that variation on any one cell matters less), and a variation-aware Operation-Unit (OU)-based framework that only activates RRAM cells belonging to the same OU simultaneously, limiting both the scope of variation accumulation and the required ADC resolution/power. Three additional techniques - OU skipping, OU recombination, and OU compensation - are introduced to further mitigate the residual impact of variations within and across OUs. The approach is evaluated with 2-bit cell resolution on four NN models across two datasets, and the authors report it outperforms the state of the art.", "contributions": ["Unary-based non-uniform quantization that equalizes per-cell weight significance to reduce sensitivity to conductance variation", "A variation-aware Operation-Unit (OU) based computation framework limiting concurrently activated wordlines/bitlines to control variation accumulation and ADC overhead", "Three refinement techniques - OU skipping, OU recombination, and OU compensation - to further reduce the impact of variations", "Evaluation across four NN models and two datasets at 2-bit RRAM cell resolution showing improvement over prior state-of-the-art variation-mitigation methods"], "claims": [{"claim": "The proposed unary-based non-uniform quantization plus variation-aware OU framework outperforms state-of-the-art variation-mitigation approaches", "support": "'the proposed approach outperforms the state-of-the-art among four NN models on two datasets with 2-bit cell resolution' (abstract)", "loc": "Abstract"}, {"claim": "Restricting simultaneous activation to RRAM cells within the same OU reduces required ADC resolution/power while mitigating variation impact", "support": "stated motivation and mechanism in abstract/methodology description", "loc": "Abstract"}], "results": ["Outperforms state-of-the-art variation-mitigation baselines across four NN models on two datasets at 2-bit cell resolution (specific accuracy/power numbers not available from abstract alone)"], "limitations": ["Abstract-only analysis in this record: full text unavailable, so exact accuracy deltas, ADC power savings, and comparison baselines could not be verified", "Evaluation limited to 2-bit cell resolution; behavior at other cell resolutions not described in the abstract", "Relies on an OU-based restricted-parallelism scheme, which (as in related work such as BWQ) inherently trades off crossbar throughput for accuracy/robustness"], "remarks": "This fits squarely into the non-ideality/reliability literature alongside works like Unary Coding and Variation-Aware Optimal Mapping (an in-set reference by the same OU/unary-coding lineage) and CASCADE; the combination of unary quantization with OU-level scheduling and three dedicated mitigation sub-techniques (skip/recombine/compensate) suggests an incremental but systematic engineering contribution to variation tolerance. Without full text, it is not possible to assess how the accuracy/ADC-power trade-off compares quantitatively to the cited ISAAC/PRIME baselines or how large the 2-bit-resolution constraint limits generality to higher-bit-cell designs.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Emerging resistive random access memory (RRAM) attracts considerable interest in computing-in-memory by its high efficiency in multiply-accumulate operation, which is the key computation in the neural network (NN). However, due to the imperfect fabrication, RRAM cells suffer from the variations, which make the values in RRAM cells deviate from the target values so that the accuracy of the RRAM-based NN accelerator degrades significantly. Moreover, in a practical hardware design of RRAM-based NN accelerators, if the number of wordlines and bitlines in a crossbar array activated at the same time increases, ADCs with a high resolution are required and the power consumption of ADC increases. This paper proposes a novel methodology to mitigate the impact of variations in RRAM-based neural network accelerators. The methodology includes a unary-based non-uniform quantization method and a variation-aware operation unit (OU) based framework. The unary-based non-uniform quantization method equalizes the significance of weights stored in each RRAM cell to reduce the impact of variations. The variation-aware OU-based framework activates only RRAM cells in the same OU at the same time, which reduces the power consumption of ADCs. Additionally, the framework introduces three methods, including OU skipping, OU recombination, and OU compensation, to further mitigate the impact of variations. The experiments show that the proposed approach outperforms the state-of-the-art among four NN models on two datasets with 2-bit cell resolution.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2024_Gu_VariationTolerantOUFramework_TCASI.pdf", "analysed": true, "pdf": null, "priority": 4.73}, {"id": "W4386293192", "short": "HWA Training for Large-scale AIMC", "title": "Hardware-aware training for large-scale and diverse deep learning inference workloads using in-memory computing-based accelerators", "authors": ["Malte J. Rasch", "Charles Mackin", "Manuel Le Gallo", "An Chen", "Andrea Fasoli", "Frédéric Odermatt", "Ning Li", "S. R. Nandakumar", "Pritish Narayanan", "Hsinyu Tsai", "Geoffrey W. Burr", "Abu Sebastian", "Vijay Narayanan"], "year": 2023, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications 14, 5282 (2023)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-023-40770-4", "cites_global": 176, "cat": "07", "seed": true, "devices": ["PCM", "ReRAM"], "models": ["CNN", "ResNet", "DenseNet", "LSTM/RNN", "RNN-T", "Speech", "BERT", "ALBERT", "Transformer"], "evidence": "simulation", "tldr": "Defines a standard PCM-calibrated AIMC crossbar model (fixed I/O/weight ranges, 8-bit DAC/ADC, per-column digital affine scales, programming noise, drift, read noise, IR-drop, output noise) and a hardware-aware training recipe that brings 11 large DNNs (CNNs, LSTMs, BERT/ALBERT) to >97% normalized accuracy at 1 h, 5 of them iso-accurate, cutting the average accuracy gap from 11.3% to 1.1%.", "summary": "The paper addresses the lack of a standardized, realistic model for judging how much accuracy large DNNs lose on analog in-memory computing and how much hardware-aware (HWA) retraining can recover. It defines a tile-level non-ideal MVM model: a per-tile learned input scale alpha, fixed-range 8-bit DAC/ADC with clipping, weights normalized to [-gmax, gmax] on a differential conductance pair, hardware-calibrated PCM programming noise, drift and 1/f read noise, an input-dependent IR-drop approximation, additive output (system) noise, and per-column digital scales gamma_i/offsets beta_i; its MVM error (~15%) roughly equals 4-bit fixed-point. HWA training injects these non-idealities (with PCM-measured noise structure) into the forward pass during SGD fine-tuning of FP32 models, learns scales, and clips weights, once per model per chip family rather than per chip. On 11 benchmarks from ResNet-32 to BERT-base (108M params) and RNN-T, mapped naively onto 512x512 tiles, direct mapping fails iso-accuracy for nearly all models, while HWA training gives >97% normalized accuracy at 1 h and iso-accuracy (>99%) for BERT, three LSTM workloads and WideResNet-16. A sensitivity analysis shows input/output-side noise (ADC/DAC resolution, additive output noise, S-shaped ADC nonlinearity) hurts far more than weight-side noise at equal MVM error, CNNs are most sensitive and RNNs least, and exempting a few sensitive layers (2-11% of parameters) from PCM noise lets ImageNet CNNs reach iso-accuracy. The model is released in IBM AIHWKit.", "contributions": ["A standardized, mathematically specified AIMC crossbar inference model calibrated to PCM hardware (with ReRAM generalization in supplementary), released in AIHWKit.", "An improved HWA training recipe (PCM-structured weight noise, learned input/output scales, per-column affine periphery, clipping, optional distillation).", "Benchmark of 11 large DNNs across CNN, LSTM/RNN-T and transformer families with drift evaluation from 1 s to 1 year.", "Systematic per-non-ideality sensitivity analysis and tolerance thresholds informing AIMC hardware specs (e.g., DAC 8->6 bit tolerable).", "Analysis of weight-distribution compactness (kurtosis) and layer-selective noise exemption to reach iso-accuracy for ImageNet CNNs."], "claims": [{"claim": "Directly mapping FP32-trained weights onto the standard AIMC model fails iso-accuracy for almost all DNNs.", "support": "e.g. ResNet-50 test error 23.87% FP32 -> 36.51% at 1 h; BERT-base MRPC 14.60% -> 22.87%; normalized accuracy A*1h 83-93% for CNNs/transformers.", "loc": "Table 2"}, {"claim": "HWA training brings all 11 DNNs above 97% normalized accuracy at 1 h and 5/11 to iso-accuracy (>99%).", "support": "BERT-base GLUE8 17.47% FP32 vs 17.55% at 1 h (A*1h 99.8%); ResNet-50 24.83% at 1 h (98.1%); averaged gap reduced from 11.3% to 1.1%.", "loc": "Table 3; Conclusion"}, {"claim": "Non-idealities adding noise to inputs/outputs (ADC/DAC resolution, additive output noise, S-shaped ADC nonlinearity) have far larger accuracy impact than weight-related ones at equal MVM error.", "support": "Sensitivity grid at boosted MVM error ε*M = 20% (from standard 15%).", "loc": "Fig. 4B"}, {"claim": "RNNs are the most robust and CNNs the most sensitive topology to AIMC non-idealities.", "support": "e.g. PCM noise threshold x* = 1.2x for ResNet-18 vs 3.3x for LSTM-PTB at A1h = 99%.", "loc": "Fig. 5"}, {"claim": "Exempting a few sensitive layers from PCM weight noise suffices for ImageNet CNN iso-accuracy.", "support": "Only 6.4%, 2% and 11.3% of parameters for ResNet-18, ResNet-50 and DenseNet-121; WideResNet-50 additionally needs lower system noise.", "loc": "Fig. 7"}, {"claim": "DAC precision can be reduced from 8 to 6 bits without retraining with little accuracy impact.", "support": "Tolerance thresholds across all 11 DNNs.", "loc": "Fig. 5B"}], "results": ["Average normalized accuracy gap reduced from 11.3% (direct mapping) to 1.1% (HWA) at 1 h drift", "BERT-base (GLUE avg.): 17.55% error at 1 h vs 17.47% FP32 (A*1h 99.8%, 98.9% after 1 year)", "ResNet-50 ImageNet: 24.83% error at 1 h vs 23.87% FP32 (98.1%); DenseNet-121 92.9% normalized accuracy after 1 year", "Speech-SWB300 and LSTM-PTB remain iso-accurate out to 1 year of PCM drift", "Standard AIMC model MVM error ≈15% ≈ 4-bit fixed-point quantization", "Tolerates 0.42% stuck-at-reset devices for the least robust model (3-4% for some RNNs), but only ~0.05% stuck-at-set/random devices in some large CNNs"], "limitations": ["Entirely simulation with Gaussian/abstracted noise models; the authors note it cannot replace hardware verification.", "Static crossbar effects (systematic conductance changes) ignored, assuming write-verify compensates them; IR-drop is approximated with average currents.", "Assumes one differential PCM pair per weight, naive tile mapping (each matrix ≥1 tile), and first conv / last FC layers in FP32 for ImageNet CNNs.", "No energy/latency evaluation (deferred to the companion architecture study); LLM-scale generative models not covered.", "Noise injected once per mini-batch; hyperparameters chosen per model, and HWA retraining requires training data and substantial compute."], "remarks": "This is the reference HWA-training/AIMC-evaluation baseline in the field: its standard crossbar model and AIHWKit implementation are reused by later IBM works (AnalogNAS, post-training optimization, adversarial-robustness study) and by external groups as a comparison point. For crossbar mapping, its key lessons are that per-column digital affine scaling, learned input ranges and compact weight distributions matter as much as device noise, and that ADC/output noise rather than weight noise dominates accuracy loss. Evidence is simulation, but noise models are calibrated on real PCM and related chip results (e.g., IBM 64-core HERMES chip) corroborate the approach.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog in-memory computing-a promising approach for energy-efficient acceleration of deep learning workloads-computes matrix-vector multiplications but only approximately, due to nonidealities that often are non-deterministic or nonlinear. This can adversely impact the achievable inference accuracy. Here, we develop an hardware-aware retraining approach to systematically examine the accuracy of analog in-memory computing across multiple network topologies, and investigate sensitivity and robustness to a broad set of nonidealities. By introducing a realistic crossbar model, we improve significantly on earlier retraining approaches. We show that many larger-scale deep neural networks-including convnets, recurrent networks, and transformers-can in fact be successfully retrained to show iso-accuracy with the floating point implementation. Our results further suggest that nonidealities that add noise to the inputs or outputs, not the weights, have the largest impact on accuracy, and that recurrent networks are particularly robust to all nonidealities.", "review": [{"fid": "F14", "text": "The field's framing of its own open problem has shifted: since floating-point-level inference accuracy has been demonstrated via hardware-aware training, the question is no longer whether analog can match digital accuracy but what device specifications are required at what fabrication cost — motivating systematic methodologies for mapping the multidimensional device-specification space, with PCM as the representative platform.", "grade": "Medium confidence", "vote": "3–0 unanimous", "note": "Graded medium: a research-agenda framing statement from a single recent paper, and it understates the residual gap seen at larger model scale (see F3, F10)."}, {"fid": "R3", "text": "“Direct mapping of FP-trained DNN weights onto realistic PCM crossbars causes accuracy losses of roughly 1.3% to 23.9% across 11 benchmark networks.”", "grade": "Refuted 0–3", "vote": "Nature Communications 2023", "note": ""}, {"fid": "R4", "text": "“Hardware-aware training makes analog-deployable not just small CNNs but large-scale, diverse architectures including BERT, RoBERTa, ALBERT, RNN/LSTM and CNN families.”", "grade": "Refuted 1–2", "vote": "Nature Communications 2023", "note": "Consequence: the HWA-training evidence in F4 rests on the ALBERT chip paper, Analog Foundation Models and HERMES instead — not on this breadth claim."}], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2023_Rasch_HWATrainingLargeScaleAIMC_NatCommun.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2023_Rasch_HWATrainingLargeScaleAIMC_NatCommun.pdf", "priority": 11.86}, {"id": "W4383501742", "short": "Mapping-aware Biased Training", "title": "Mapping-aware Biased Training for Accurate Memristor-based Neural Networks", "authors": ["Sumit Diware", "Anteneh Gebregiorgis", "Rajiv Joshi", "Said Hamdioui", "Rajendra Bishnoi"], "year": 2023, "venue": "", "venue_short": "AICAS", "venue_full": "2023 IEEE 5th International Conference on Artificial Intelligence Circuits and Systems (AICAS 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/aicas57966.2023.10168661", "cites_global": 15, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "Constrains the most hardware-important crossbar columns during training so their weight bit-slices map only to low-error RRAM conductance states, giving up to 2.4x higher simulated hardware accuracy (e.g. 35.4% -> 85.2% on FMNIST/LeNet-5) at zero hardware overhead.", "summary": "Memristor conductance variation corrupts stored weights in ISAAC/PUMA-style bit-sliced CIM. The authors rank the four states of a 2-bit RRAM by their absolute error-current contribution (not relative variation), so low-conductance states are favorable and the highest state G10 is unfavorable. A favorability constraint, derived from the bit-slicing/offset mapping scheme (8-bit fixed-point weights split over four 2-bit cells, ISAAC 2^7 shift), restricts the MSB slice of important weights to favorable states. Importance is computed per crossbar column by summing gradient-based weight saliency over crossbar-sized chunks, and the top m% of columns (chosen by design-space exploration) are constrained each epoch of fine-tuning. A Python behavioral CIM simulator with measured RRAM variation data evaluates LeNet-5 on MNIST, FMNIST and EMNIST-letters, showing up to 2.4x hardware accuracy and 2.4x 'correct operations per joule' vs conventional training.", "contributions": ["Favorability analysis ranking multi-level RRAM conductance states by absolute error-current contribution rather than percentage variation.", "Column-level hardware importance metric (sum of gradient saliency per crossbar column) aligned with column-wise MAC in CIM.", "Mapping-aware biased training that constrains only important columns' weights to values whose MSB slice maps to favorable states.", "Behavioral CIM evaluation with ISAAC/PUMA IMA unit and a 'correct operations per unit energy' metric."], "claims": [{"claim": "Conductance-state preference should be based on error current contribution, not relative variation, so low-mean states are preferable despite higher % variation.", "support": "Preference order G00 (best), G01, G11, G10 (worst) from measured variation data [32].", "loc": "Sec. III-A, Fig. 4"}, {"claim": "Constraining only a moderate fraction of important crossbar columns balances software accuracy and hardware robustness.", "support": "Design-space exploration shows peak hardware accuracy at dataset-dependent intermediate column percentages; too many constrained columns lower software and hardware accuracy.", "loc": "Sec. IV-B1, Fig. 8"}, {"claim": "Mapping-aware biased training improves hardware accuracy up to 2.4x over conventional training.", "support": "FMNIST hardware accuracy 35.4% (conventional) vs 85.2% (proposed).", "loc": "Sec. IV-B2, Fig. 9, Table I"}, {"claim": "The method has no hardware overhead and improves correct operations per unit energy.", "support": "Same 3738 pJ and 21765 µm² per IMA; 96.9 vs 233.4 GOP/J correct operations per energy on FMNIST.", "loc": "Table I"}], "results": ["FMNIST/LeNet-5 hardware accuracy: 35.4% (conventional training) -> 85.2% (biased training), ~2.4x", "Correct operations per unit energy (FMNIST): 96.9 -> 233.4 GOP/J with identical 3738 pJ energy and 21765 µm² area per IMA unit", "Accuracy gains larger on FMNIST/EMNIST-L than MNIST; software accuracy slightly lower than conventional training"], "limitations": ["Only LeNet-5 on MNIST-class datasets; no evidence for deep CNNs or transformers.", "Behavioral Python simulation with conductance variation only; ignores IR drop, drift, read noise and ADC non-linearity.", "Very poor conventional-training baseline (35.4% on FMNIST) suggests an extreme variation regime; no comparison to noise-injection training or other state-of-the-art variation-aware methods.", "Favorability constraint is tied to a specific bit-slicing/offset scheme; constrains only MSB slice.", "Minor internal inconsistency: Config-3 favorable set is listed as {G00,G01,G11} but Fig. 7 text says G00, G01 and G10."], "remarks": "The idea of shaping weight distributions so that bit-slices land in device states with low absolute error is a sensible mapping-aware twist on hardware-aware training, and it exploits the column-wise nature of crossbar MAC for importance ranking. However, evidence is weak: a 4-page AICAS paper on LeNet-5 with no comparison against standard noise-injection HWA training (e.g., Joshi 2020, Rasch 2023), which might close most of the gap by itself. Useful as a conceptual reference for state-aware quantization/mapping on multi-level RRAM.", "basis": "full-text", "pdf_source_url": "", "abstract": "Memristor-based computation-in-memory (CIM) can achieve high energy efficiency by processing the data within the memory, which makes it well-suited for applications like neural networks. However, memristors suffer from conductance variation problem where their programmed conductance values deviate from the desired values. Such variations lead to computational errors that result in degraded inference accuracy in CIM-based neural networks. In this paper, we present a mapping-aware biased training methodology to mitigate the impact of conductance variation on CIM-based neural networks. We first determine which conductance states of the memristor are inherently more immune to variation. The neural network is then trained under the constraint that important weights can only take numeric values which directly get mapped to such favorable states. Simulation results show that our proposed mapping-aware biased training achieves up to 2.4× hardware accuracy compared to the conventional training.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2023_Diware_MappingAwareBiasedTraining_AICAS.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2023_Diware_MappingAwareBiasedTraining_AICAS.pdf", "priority": 4.34}, {"id": "W4386352784", "short": "AnalogNAS", "title": "AnalogNAS: A Neural Network Design Framework for Accurate Inference with Analog In-Memory Computing", "authors": ["Hadjer Benmeziane", "Corey Lammie", "Irem Boybat", "Malte J. Rasch", "Manuel Le Gallo", "Hsinyu Tsai", "R. Muralidhar", "Smaïl Niar", "Hamza Ouarnoughi", "Vijay Narayanan", "Abu Sebastian", "Kaoutar El Maghraoui"], "year": 2023, "venue": "", "venue_short": "EDGE", "venue_full": "2023 IEEE International Conference on Edge Computing and Communications (EDGE 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/edge60047.2023.00045", "cites_global": 12, "cat": "07", "seed": false, "devices": ["PCM"], "models": ["CNN", "ResNet", "Wide-ResNet", "ResNeXt"], "evidence": "algorithm+simulation", "tldr": "Hardware-aware NAS for analog IMC that uses an XGBoost ranking surrogate trained on ~1,000 HWA-trained (AIHWKit) ResNet-like networks plus evolutionary search to find wide, shallow, drift-robust TinyML models; the CIFAR-10 T500 model reaches 92.07% on IBM's 64-core PCM chip vs 89.55% for ResNet32.", "summary": "Existing HW-NAS spaces contain analog-unfriendly ops (depthwise convs) and ignore noise/drift. AnalogNAS defines a ~73B-architecture ResNet-like macro search space (main blocks, residual blocks, branches, conv block types, widening factors, first-conv channels/kernel). Sampled networks (LHS plus evolutionary sampling) are HWA-trained in AIHWKit with varied weight-noise levels and 256/512 tile sizes, and an XGBoost surrogate with pairwise hinge ranking loss predicts 1-day accuracy rank, accuracy variation over one month (AVM) and 1-day std. A constrained evolutionary search (population 200, 200 iterations, parameter and AVM thresholds) then finds models for CIFAR-10, Visual Wake Words and Keyword Spotting. Found models beat SOTA tiny models in simulated drift robustness and accuracy; the CIFAR-10 T500 model was validated on IBM's 64-core PCM chip and simulated on a heterogeneous AIMC architecture for latency/energy. The search consistently favors wider, shallower networks that better utilize crossbar tiles.", "contributions": ["ResNet-like analog-friendly NAS search space (~73B architectures) without depthwise convolutions.", "Analog-accuracy surrogate (XGBoost, pairwise ranking) trained on HWA-trained networks predicting 1-day accuracy rank, AVM and variance across trials.", "Constrained evolutionary search with LHS initialization, AVM/parameter constraints and surrogate fine-tuning.", "Results on CIFAR-10, VWW and KWS plus hardware validation on a 64-core PCM IMC chip and system-level latency/energy simulation.", "Insight that wider, shallower networks are more noise/drift-robust and tile-efficient on AIMC."], "claims": [{"claim": "AnalogNAS-found models are more accurate and more drift-robust than SOTA models of similar size on simulated AIMC.", "support": "CIFAR-10 T500 is smaller than ResNet32 with +1.86% accuracy and 1.8% one-month drop vs 5.04%; AnalogNAS 1M beats Wide ResNet by +0.86% with 1.16% vs 6.33% drop (~86x fewer params than 36.5M WRN).", "loc": "Sec. VI-B, Fig. 7"}, {"claim": "The advantage transfers to real PCM hardware.", "support": "64-core PCM chip: T500 92.07% vs ResNet32 89.55% (FP 94.54% vs 94.34%), mean of five repetitions.", "loc": "Sec. VII-A, Table IV"}, {"claim": "Found models are faster and more energy-efficient on a simulated heterogeneous AIMC system.", "support": "Execution time 0.108 ms vs 0.434 ms; 54,502 vs 43,956.7 inferences/s/W; 27 vs 43 tiles.", "loc": "Sec. VII-B, Table IV"}, {"claim": "Depthwise-separable baselines suffer large drift-induced drops on AIMC; AnalogNAS finds more robust VWW/KWS models.", "support": "VWW T200 +2.44% / +5.1% 1-day accuracy vs AnalogNet-VWW / Micronets-VWW, avg AVM 2.63%; KWS 96.8% with 2.3% one-month drop vs 4.72% average drop of baselines.", "loc": "Sec. VI-B"}, {"claim": "Search favors wider and shallower architectures for AIMC robustness.", "support": "Average depth decreases and widening factor increases over search iterations.", "loc": "Sec. VIII, Fig. 9"}], "results": ["CIFAR-10 T500: +1.86% accuracy vs ResNet32 with 1.8% vs 5.04% one-month drift drop (simulated)", "Hardware (64-core PCM chip): 92.07% (T500) vs 89.55% (ResNet32)", "Simulated system: >4x lower execution time (0.108 vs 0.434 ms) and >1.2x energy efficiency (54,502 vs 43,956.7 inf/s/W)", "T100 model: +7.98% accuracy vs ResNet-V1 (MLPerf tiny) with 5.14% vs 10.1% one-month drop", "CIFAR-10 search took 17 min after surrogate training (surrogate datasets of 1,200/600/1,500 HWA-trained networks)"], "limitations": ["Search space restricted to ResNet-like CNNs and TinyML tasks; no transformers or large models.", "Large upfront cost: training 600-1,500 HWA networks per task to build the surrogate is not included in the quoted search time.", "Hardware validation for only two networks on CIFAR-10, with non-MVM operations on host/FPGA; latency/energy are simulated.", "Minor inconsistency: text reports 92.05% / 89.87% hardware accuracy while Table IV lists 92.07% / 89.55%.", "Tile utilization is not optimized and both networks show poor utilization (acknowledged)."], "remarks": "AnalogNAS is a solid demonstration that architecture choice is a lever for AIMC robustness beyond HWA training, with the important hardware-validated finding that wide/shallow ResNets suit crossbars better than depthwise-heavy edge models. It builds directly on IBM's AIHWKit and the Rasch et al. HWA-training methodology, and its 'wider is better' message is consistent with Rasch 2023 on tile utilization. The surrogate approach is task- and hardware-config-specific, so its cost-benefit for larger models remains untested.", "basis": "full-text", "pdf_source_url": "", "abstract": "The advancement of Deep Learning (DL) is driven by efficient Deep Neural Network (DNN) design and new hardware accelerators. Current DNN design is primarily tailored for general-purpose use and deployment on commercially viable platforms. Inference at the edge requires low latency, compact and power-efficient models, and must be cost-effective. Digital processors based on typical von Neumann architectures are not conducive to edge AI given the large amounts of required data movement in and out of memory. Conversely, analog/mixed-signal in-memory computing hardware accelerators can easily transcend the memory wall of von Neuman architectures when accelerating inference workloads. They offer increased area-and power efficiency, which are paramount in edge resource-constrained environments. In this paper, we propose AnalogNAS, a framework for automated DNN design targeting deployment on analog In-Memory Computing (IMC) inference accelerators. We conduct extensive hardware simulations to demonstrate the performance of AnalogNAS on State-Of-The-Art (SOTA) models in terms of accuracy and deployment efficiency on various Tiny Machine Learning (TinyML) tasks. We also present experimental results that show AnalogNAS models achieving higher accuracy than SOTA models when implemented on a 64-core IMC chip based on Phase Change Memory (PCM). The AnalogNAS search code is released1", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2023_Benmeziane_AnalogNAS_EDGE.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2023_Benmeziane_AnalogNAS_EDGE.pdf", "priority": 5.18}, {"id": "W4378800995", "short": "Batchnorm Fine-tuning for IMC Noise", "title": "Examining the Role and Limits of Batchnorm Optimization to Mitigate Diverse Hardware-noise in In-memory Computing", "authors": ["Abhiroop Bhattacharjee", "Abhishek Moitra", "Youngeun Kim", "Yeshwanth Venkatesha", "Priyadarshini Panda"], "year": 2023, "venue": "", "venue_short": "GLSVLSI", "venue_full": "Proceedings of the Great Lakes Symposium on VLSI 2023 (GLSVLSI '23), ACM", "venue_ok": true, "doi": "https://doi.org/10.1145/3583781.3590241", "cites_global": 11, "cat": "07", "seed": false, "devices": ["FeFET", "PCM", "ReRAM"], "models": ["CNN", "ResNet"], "evidence": "simulation", "tldr": "Shows that fine-tuning only the digital batchnorm parameters (gamma, beta) with conv weights frozen on crossbars recovers most accuracy lost to read noise, drift and IR-drop parasitics as long as the non-linear weight distortion (measured as PCA PC2) stays below ~1e-2, cutting on-hardware retraining memory by ~95%/52%.", "summary": "The paper asks whether costly noise-aware retraining/reprogramming of crossbar weights is always needed to keep DNN accuracy under analog non-idealities. Conv layers of VGG16 (CIFAR10) and ResNet-18 (TinyImagenet) are mapped weight-stationary onto 64x64 (and 128x128) crossbars of 4-bit FeFET, PCM or RRAM devices (8-bit weights via bit-slicing), while BN, pooling, activation and the FC classifier remain in full-precision digital CMOS. A Python non-ideality framework injects Gaussian read noise, power-law drift and resistive parasitics (circuit-law model from NEAT/RxNN) into the conv weights. The distortion between ideal and non-ideal weights is quantified by the second principal component (PC2) of their joint distribution; BN statistic adaptation works only for small PC2 (~<3e-3), whereas BN gamma/beta fine-tuning for 5 epochs recovers accuracy up to PC2 ~1e-2. Hardware savings for on-chip training when weights stay frozen are estimated as ~95% (VGG16) and ~52% (ResNet-18) memory and ~8% training energy.", "contributions": ["Proposes crossbar-noise-aware fine-tuning of only batchnorm gamma/beta (weights frozen) as a nearly training-less mitigation for read noise, drift and parasitics.", "Introduces PCA-based PC2 metric of the ideal-vs-non-ideal weight scatter to quantify non-linear distortion and predict when BN adaptation/fine-tuning suffices.", "Ablation across FeFET, two PCM variants and RRAM, crossbar sizes 64x64/128x128, and drift up to 1e10 s.", "Estimates memory and training-energy savings for on-chip training hardware when weight gradients/reprogramming are avoided."], "claims": [{"claim": "Simple BN statistic adaptation fails once read-noise distortion exceeds a threshold, while BN gamma/beta fine-tuning extends the tolerable range.", "support": "VGG16/CIFAR10 on FeFET: BN adaptation keeps 87.78% at sigma=0.05 but only 77.89% at sigma=0.15; BN fine-tuning preserves accuracy until PC2 < 1e-2 (sigma=0.15-0.2).", "loc": "Sec. 4.1, Fig. 6"}, {"claim": "BN fine-tuning almost completely compensates resistive parasitic (IR-drop) non-idealities without weight retraining.", "support": "VGG16 on RRAM 64x64 (128x128): 74.37% (32.9%) raw -> 86.31% (83.03%) BN adaptation -> 87.97% (87.81%) BN fine-tuning vs 88.62% software.", "loc": "Sec. 4.3, Fig. 10"}, {"claim": "BN fine-tuning mitigates long-term conductance drift on FeFET crossbars.", "support": "At T=1e10 s accuracy drop reduced from 76.5%/26.1% (BN adaptation) to 5.0%/8.0% for VGG16/ResNet-18.", "loc": "Sec. 4.2, Fig. 8"}, {"claim": "Higher device ON/OFF ratio reduces noise sensitivity (lower PC2) and improves post-fine-tuning accuracy.", "support": "PCM-i (ON/OFF 40): PC2 9.61e-3, 82.0%; PCM-ii (ON/OFF 80): PC2 3.16e-3, 86.81%; RRAM (ON/OFF 10): PC2 5.59e-3, 84.07%.", "loc": "Sec. 4.1, Fig. 7"}, {"claim": "Freezing crossbar weights during on-chip fine-tuning yields large memory savings.", "support": "~95% (VGG16/CIFAR10) and ~52% (ResNet-18/TinyImagenet) memory savings and ~8% training-energy reduction per epoch (batch size 1).", "loc": "Sec. 5, Fig. 11"}], "results": ["RRAM 64x64 parasitics + sigma=0.1 read noise: 62.28% -> 83.22% after BN fine-tuning (VGG16/CIFAR10; 128x128: 27.86% -> 81.59%)", "FeFET drift at T=1e10 s: accuracy loss cut to 5.0% (VGG16) and 8.0% (ResNet-18) with BN fine-tuning", "BN adaptation alone preserves accuracy only up to ~1e4-1e5 s of drift on FeFET", "~95% / ~52% on-hardware training memory savings and ~8% training energy savings vs full weight fine-tuning"], "limitations": ["Simulation only; non-idealities are injected into weights (weight-perturbation model), not full circuit/ADC simulation of activations.", "Small benchmarks (VGG16/CIFAR10, ResNet-18/TinyImagenet with low 51.8% baseline); no transformers or large models.", "Assumes BN and FC layers run in noise-free full-precision digital CMOS; only conv layers are analog.", "BN fine-tuning still requires labelled training data and backprop through the noisy model (per chip / per drift time).", "Short 4-page workshop-style paper; energy savings estimate (~8%) is coarse and based on external data."], "remarks": "A useful negative/positive boundary study: it gives an intuitive PC2 metric for when cheap affine (BN) correction is enough versus when weight-level hardware-aware training is required. For crossbar mapping, it supports keeping per-channel affine scales/offsets in digital periphery as a calibration knob, consistent with IBM's later post-training affine/BN recalibration work. Evidence is purely simulated with simple noise models and small CNNs, so the PC2 thresholds should not be assumed to transfer to transformers or measured chips.", "basis": "full-text", "pdf_source_url": "", "abstract": "In-Memory Computing (IMC) platforms such as analog crossbars are gaining focus as they facilitate the acceleration of low-precision Deep Neural Networks (DNNs) with high area- & compute-efficiencies. However, the intrinsic non-idealities in crossbars, which are often non-deterministic and non-linear, degrade the performance of the deployed DNNs. In addition to quantization errors, most frequently encountered non-idealities during inference include crossbar circuit-level parasitic resistances and device-level non-idealities such as stochastic read noise and temporal drift. In this work, our goal is to closely examine the distortions caused by these non-idealities on the dot-product operations in analog crossbars and explore the feasibility of a nearly training-less solution via crossbar-aware fine-tuning of batchnorm parameters in real-time to mitigate the impact of the non-idealities. This enables reduction in hardware costs in terms of memory and training energy for IMC noise-aware retraining of the DNN weights on crossbars.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2023_Bhattacharjee_BatchnormFinetuningIMCNoise_GLSVLSI.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2023_Bhattacharjee_BatchnormFinetuningIMCNoise_GLSVLSI.pdf", "priority": 6.35}, {"id": "W4385679805", "short": "RRAM-PoolFormer", "title": "RRAM-PoolFormer: A Resistive Memristor-based PoolFormer Modeling and Training Framework for Edge-AI Applications", "authors": ["Tiancheng Cao", "Weihao Yu", "Yuan Gao", "Chen Liu", "Shuicheng Yan", "Wang Ling Goh"], "year": 2023, "venue": "", "venue_short": "ISCAS", "venue_full": "2023 IEEE International Symposium on Circuits and Systems (ISCAS 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/iscas46773.2023.10181612", "cites_global": 9, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["PoolFormer/MetaFormer", "MLP"], "evidence": "simulation", "tldr": "Adapts a tiny 16-block, 0.26M-parameter PoolFormer (pooling token mixer, LayerNorm replaced by channel scaling) to 4-level TaOx RRAM 64x64 crossbars and trains it with device/array non-idealities in the loop, reaching 85.86% CIFAR-10 accuracy (<4% below FP64).", "summary": "Self-attention is expensive for edge devices; PoolFormer replaces it with parameter-free pooling, leaving only patch embedding and channel-MLP matrix multiplies, which map naturally onto crossbars. The authors build a 2-stage (12+4 blocks, embedding dims 32/64) PoolFormer and replace layer normalization with learned per-channel scaling to simplify peripheral hardware. Patch embedding is implemented as unfold + crossbar VMM, and channel-MLP weights are mapped directly using a differential two-cell-per-weight scheme with a ReLU readout circuit between layers. Non-idealities from measured TaOx 2T1R RRAM (4 levels, 5-30 kOhm, 15% variation), programming failures (stuck at HRS), and line resistance (fast O(mn) scaling-factor IR-drop model from prior work) are included in training. Simulated inference reaches 85.86% on CIFAR-10 with 0.5 Ohm line resistance, and non-ideality-aware training loses <1% as line resistance grows to 2 Ohm, while conventional offline training degrades sharply.", "contributions": ["Hardware-friendly PoolFormer variant: pooling token mixer, LayerNorm replaced by trainable channel scaling, reduced 2-stage 16-block topology with 0.26M weights.", "Crossbar mapping of patch embedding (unfold + VMM) and channel MLP with differential two-cell weights.", "Non-ideality-aware training integrating measured RRAM variation, programming failure masks, and a fast O(mn) line-resistance model.", "Comparison against CNN-based RRAM accelerator models on CIFAR-10 showing comparable accuracy with >10x fewer weights."], "claims": [{"claim": "A hardware-adapted PoolFormer on 4-level RRAM crossbars achieves competitive CIFAR-10 accuracy with very few weights.", "support": "85.86% inference accuracy with 64x64 arrays, 0.5 Ohm line resistance, 15% device variation; 0.26M weights vs 6.6-13M for compared CNNs.", "loc": "Sec. IV, Fig. 5, Table I"}, {"claim": "Non-ideality-aware training keeps accuracy close to software even at very low weight resolution.", "support": "With 2-bit weights only ~3% accuracy loss vs ideal software; conventional offline training degrades much more.", "loc": "Sec. IV, Fig. 6"}, {"claim": "Non-ideality-aware training is robust to interconnect line resistance.", "support": "Line resistance 0 -> 2 Ohm causes <1% accuracy drop with proposed training vs a substantial drop for conventional training.", "loc": "Sec. IV, Fig. 7"}, {"claim": "Replacing LayerNorm by channel scaling maintains satisfactory accuracy on small datasets while relaxing computation.", "support": "Design choice stated; no separate ablation number reported.", "loc": "Sec. II-A"}], "results": ["CIFAR-10: 85.86% inference accuracy with 0.26M weights on simulated 4-level 64x64 TaOx RRAM crossbars (<4% below FP64 model)", "<1% accuracy drop for line resistance up to 2 Ohm with non-ideality-aware training", "~3% loss vs software with 2-bit weights", "Training cost: 2.7 h on a 16-core CPU for 500 epochs"], "limitations": ["Simulation only (device model from measured array data, but no on-chip demonstration).", "Only CIFAR-10; PoolFormer has no attention, so conclusions do not transfer to attention-based transformers/LLMs.", "No energy, latency or area evaluation; ADC/DAC and peripheral costs not quantified.", "No ablation of channel scaling vs LayerNorm, and comparison table mixes different devices/networks (accuracy of some baselines not reported).", "Short 4-page conference paper; relies on authors' prior framework [31] for details."], "remarks": "An interesting angle for mapping transformer-like vision models onto crossbars: choose architectures (MetaFormer/PoolFormer) whose only weighted operations are static-weight MLPs, avoiding the dynamic-operand attention matmuls that are awkward for NVM crossbars. Evidence is limited to a small simulated CIFAR-10 study with mixed baselines, and accuracy (85.86%) is modest. It builds directly on the same authors' non-ideality-aware co-design framework (W4312081519) and was later extended in 'Edge PoolFormer'.", "basis": "full-text", "pdf_source_url": "https://oar.a-star.edu.sg/storage/p/prv2k26jzg/post-print-rram-poolformer-a-resistive-memristor-based-poolformer-modeling-and-training-framework-for-edge-ai-applications.pdf", "abstract": "PoolFormer is a type of neural network architecture that is abstracted from Transformer where the computationally heavy token mixer module is replaced with simple pooling function. This paper presents a memristor-based PoolFormer modeling and training framework for edge-AI applications. To fit for implementation on resistive crossbar array, original PoolFormer structure is further optimized by replacing normalization operation with hardware friendly scaling operation. In addition, the non-idealities of RRAM crossbar from device to array level as well as peripheral readout circuits are also included. By incorporating these elements under a single framework for network training, their impact to the network performance can be effectively mitigated. This framework is implemented in a combination of Python and PyTorch. A 16-block PoolFormer network is designed and optimized for CIFAR-10 image classification tasks using measured$\\mathbf{64}\\times \\mathbf{64}$RRAM crossbar array results. The total network weights are only 0.26M, which is at least one order of magnitude smaller than that of the conventional DNN implementation. When compared to the ideal model with FP64 weight bit-length, 85.86% inference accuracy is reached with only 4-level weight resolutions and less than 4% accuracy loss.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2023_Cao_RRAMPoolFormer_ISCAS.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2023_Cao_RRAMPoolFormer_ISCAS.pdf", "priority": 4.2}, {"id": "W4391213160", "short": "NLP-AIMC", "title": "Resilience and Precision Assessment of Natural Language Processing Algorithms in Analog In-Memory Computing: A Hardware-Aware Study", "authors": ["Amirhossein Parvaresh", "Shima Hosseinzadeh", "Dietmar Fey"], "year": 2023, "venue": "", "venue_short": "NANOARCH", "venue_full": "Proceedings of the 18th ACM International Symposium on Nanoscale Architectures (NANOARCH 2023)", "venue_ok": true, "doi": "https://doi.org/10.1145/3611315.3633266", "cites_global": 1, "cat": "07", "seed": false, "devices": ["generic analog crossbar (PCM-style via AIHWKit, assumed)"], "models": ["RNN", "CNN"], "evidence": "simulation", "tldr": "Evaluates NLP networks (GRU, LSTM, CNN) under analog in-memory computing non-idealities with and without hardware-aware training; GRU is most robust (3.97% avg error), CNN least (13.34%).", "summary": "The paper asks how well NLP algorithms tolerate analog in-memory computing non-idealities such as noise. It runs hardware-aware simulation of several NLP networks, with and without hardware-aware training. GRUs reach 3.97% average test error after HWA training relative to full precision, LSTMs 5.67%, CNNs 13.34% relative error. It also analyses sensitivity to individual non-idealities. Based on the abstract only; mapping details are not available.", "contributions": ["Comparative resilience study of GRU, LSTM, CNN NLP models on simulated AIMC", "Quantifies benefit of hardware-aware training", "Per-non-ideality sensitivity profiles"], "claims": [{"claim": "GRU is more noise-resilient than LSTM and CNN under AIMC", "support": "3.97% vs 5.67% vs 13.34% avg error", "loc": "Abstract"}], "results": ["GRU 3.97% avg test error after HWA training; LSTM 5.67%; CNN 13.34% relative error (baseline: full precision)"], "limitations": ["No transformer/LLM models", "Abstract-only analysis; details of noise model unverified"], "remarks": "Early, small-model NLP robustness study; useful as a baseline for non-ideality sensitivity but predates transformer-based SLM work. Metrics defined loosely (error relative to full precision). Weakly relevant to SLMs.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Natural Language Processing (NLP) serves as a cornerstone technology, facilitating complex human-computer interactions, enabling information retrieval, conducting sentiment analysis, and enhancing language comprehension. With the ever-growing use of NLPs, the conventional ’von Neumann’ computing paradigm is rapidly approaching its inherent limitations. In response, Analog In-Memory Computing (AIMC) emerges as a compelling alternative, albeit accompanied by inherent non-idealities when deploying neural networks on such platforms. In this paper, we have evaluated the precision and resilience of various NLP algorithms when executed within the AIMC framework, both with and without the application of hardware-aware training. Our analysis reveals noteworthy insights: Gated Recurrent Unit (GRU) neural networks exhibit enhanced resilience to noise, yielding an average test error of 3.97% following hardware-aware training, as compared to their full precision counterparts. Conversely, Long Short-Term Memory (LSTM) networks demonstrate a slightly higher average test error of 5.67%, indicating a relatively lower tolerance to non-idealities. In contrast, Convolutional Neural Networks (CNNs) manifest a heightened vulnerability, exhibiting an average relative test error of 13.34%. Furthermore, we systematically investigate the sensitivity profiles of the selected neural networks in the presence of specific non-idealities, providing valuable insights into their robustness and susceptibility within the AIMC environment.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2023_Parvaresh_NlpAimcResilience_NANOARCH.pdf", "analysed": true, "slm": false, "lm_models": ["GRU", "LSTM", "CNN text models"], "param_scale": "small (unspecified)", "slm_note": "Studies GRU, LSTM and CNN-based NLP models (small recurrent/convolutional text models), not transformer language models, under AIMC non-idealities (likely via the IBM AIHWKit, which it cites). Analog compute in memory is simulated. Only loosely 'language model' relevant; no BERT/GPT-style models mentioned in the abstract.", "added": "2026-10 SLM search", "pdf": null, "priority": 3.71}, {"id": "W4312081519", "short": "Non-Idealities Aware Co-Design", "title": "A Non-Idealities Aware Software–Hardware Co-Design Framework for Edge-AI Deep Neural Network Implemented on Memristive Crossbar", "authors": ["Tiancheng Cao", "Chen Liu", "Weijie Wang", "Tan‐Tan Zhang", "Hock Koon Lee", "Ming Hua Li", "Wen‐Dong Song", "Zhixian Chen", "Victor Yi-Qian Zhuo", "Nan Wang", "Yao Hua Zhu", "Yuan Gao", "Wang Ling Goh"], "year": 2022, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems (JETCAS 2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2022.3214334", "cites_global": 31, "cat": "07", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Presents a unified software-hardware co-design/training framework that jointly models device-level (conductance variation, quantization, D2D variation, programming failure) and array-level (line resistance, sneak path) non-idealities, achieving 83% CIFAR-10 accuracy (within 3% of ideal) on a simplified VGG mapped to a measured 128x128 RRAM array with 3-level weights.", "summary": "The paper addresses the gap between ideal DNN training and real memristive-crossbar deployment by building a holistic non-ideality-aware training/evaluation framework implemented in Python/PyTorch. It models device-level non-idealities (conductance variation, nonuniform quantization levels, device-to-device variation, programming failure probability) together with array-level effects (line resistance and sneak-path leakage via a new fast/accurate line-resistance estimation model) and peripheral circuit non-linearity/offset. These factors are incorporated into the DNN training loop so that the network learns to compensate for them, rather than being evaluated only post-hoc on an ideally-trained network. The framework is validated on a simplified 5-layer VGG network mapped to a measured 128x128 RRAM array with only 3-level (not full precision) per-device weight resolution, targeting CIFAR-10 classification, and shown to substantially close the accuracy gap versus the ideal (non-quantized, noise-free) model.", "contributions": ["Unified software-hardware co-design framework combining device-level (conductance variation, quantization levels, D2D variation, programming failure) and array-level (line resistance, sneak path) non-ideality models", "A new fast and accurate line-resistance/IR-drop estimation model for array-level effects", "Incorporation of peripheral circuit non-linearity and offset into the unified model", "Non-ideality-aware training procedure (Python+PyTorch) that mitigates accuracy degradation rather than just measuring it", "Validation against a measured 128x128 RRAM array with 3-level weight resolution on a VGG/CIFAR-10 task"], "claims": [{"claim": "The non-ideality-aware training process can mitigate accuracy degradation caused by device/array/peripheral non-idealities on real hardware", "support": "83% inference accuracy achieved on CIFAR-10 with less than 3% accuracy drop vs. the ideal model", "loc": "Results (per abstract; exact section unknown without full text)"}, {"claim": "A 3-level (very low precision) per-device weight resolution on a measured 128x128 RRAM array is sufficient to reach competitive CIFAR-10 accuracy when the full non-ideality model is used in training", "support": "83% accuracy figure quoted in abstract for simplified VGG at 3-level resolution", "loc": "Evaluation (per abstract)"}], "results": ["83% inference accuracy on CIFAR-10 with a simplified 5-layer VGG mapped to a measured 128x128 RRAM array using 3-level weight resolution", "Less than 3% accuracy drop compared to the ideal (non-hardware-aware) model"], "limitations": ["Abstract-only basis for this entry: the described numbers (83% accuracy, <3% drop) are taken directly from the abstract, but methodological/experimental detail (e.g., exact baseline, dataset split, number of trials) could not be verified from full text", "Evaluated on a simplified VGG (5 layers) and CIFAR-10 only — not validated on deeper networks or other datasets", "Very low per-device weight resolution (3 levels) implies many devices per weight bit, raising array-area/energy overhead questions not addressed in the abstract", "Single measured 128x128 array — scalability of the line-resistance/sneak-path model to much larger crossbars is untested here"], "remarks": "This paper is representative of the hardware-aware-training literature (similar in spirit to IBM's hardware-aware training and TxSim/NeuroSim-style tools) but distinguishes itself by combining device, array (line resistance/sneak path) and peripheral circuit non-idealities into one PyTorch-based training loop validated against a real measured RRAM array rather than a purely simulated device model. The reported 83%/<3%-drop result is a reasonably strong, hardware-grounded data point for the value of non-ideality-aware training at very low (3-level) cell precision, though verification would require the full text; later citations (e.g., RRAM-PoolFormer, error-injected robustness metric papers) suggest the framework or its non-ideality modeling approach has been used as a baseline/building block in subsequent noise-robustness work.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "In this work, a non-idealities aware software-hardware co-design framework for deep neural network (DNN) implemented on memristive crossbar is presented. The device level non-ideal factors such as device conductance variation, nonuniform quantization levels, device-to-device variation and programming failure probability are included in the model. At array level, the impact of line resistance and sneak path are considered using a new fast and accurate line resistance estimation model. The non-linearity and offset of the peripheral circuits are also considered. By incorporating these factors into a unified DNN training process, the neural network performance can be evaluated holistically. Furthermore, the proposed training process can effectively mitigate the impact of these non-idealities and reduce the inference accuracy degradations. Implemented in a hybrid fashion of Python and PyTorch, the proposed framework is evaluated with a simplified 5-layer VGG network implemented on measured$128\\times 128$RRAM array with 3-level weight resolution. For CIFAR-10 tasks, 83% inference accuracy is achieved with less than 3% accuracy drop compared to the ideal model.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2022_Cao_NonIdealitiesAwareCoDesign_JETCAS.pdf", "analysed": true, "pdf": null, "priority": 5.98}, {"id": "W4226247444", "short": "Nonideality-Aware Training", "title": "Nonideality‐Aware Training for Accurate and Robust Low‐Power Memristive Neural Networks", "authors": ["Dovydas Joksas", "Erwei Wang", "Nikolaos Barmpatsalos", "Wing H. Ng", "Anthony Joseph Kenyon", "George Anthony Constantinides", "Adnan Mehonić"], "year": 2022, "venue": "Advanced Science", "venue_short": "AdvSci", "venue_full": "Advanced Science", "venue_ok": true, "doi": "https://doi.org/10.1002/advs.202105784", "cites_global": 38, "cat": "07", "seed": false, "devices": ["ReRAM", "Memristor(generic)"], "models": ["MLP", "CNN"], "evidence": "algorithm+simulation", "tldr": "A nonideality-aware ex-situ training scheme that regularizes weights toward low-conductance states lets highly nonlinear, high-resistance memristors reach error rates close to low-resistance devices while improving estimated vector-matrix-multiplier energy efficiency by almost three orders of magnitude (0.715 to 381 TOPS/W).", "summary": "The paper addresses the trade-off in memristive neural networks (MNNs) between using low-resistance devices (power-hungry but close to linear I-V) and high-resistance devices (energy-efficient but strongly nonlinear, which standard ex-situ training handles poorly). They propose nonideality-aware training that incorporates I-V nonlinearity (and other common nonidealities such as stuck devices and D2D/cycle-to-cycle variability) directly into the forward pass during training, combined with weight regularization that biases individual memristors toward less conductive states, and a modified validation procedure appropriate for stochastic nonidealities. Using experimentally characterized SiOx RRAM I-V data (low- and high-nonlinearity regimes) fed into a simulation framework, they train MLPs on MNIST and CNNs on CIFAR-10. With standard training, high-nonlinearity (high-resistance) devices give median error of 41.6% on MNIST, but nonideality-aware training brings this down to 9.1% (7.1% with regularization), comparable to low-resistance devices (4.3%/4.1%), while estimated energy efficiency of the VMM rises from 0.715 TOPS/W (low-resistance, standard training) to 234-381 TOPS/W (high-resistance, nonideality-aware, with regularization reaching 381 TOPS/W).", "contributions": ["Nonideality-aware ex-situ training that injects I-V nonlinearity (and other nonidealities: stuck devices, D2D/cycle-to-cycle variability) into the training forward pass rather than only at inference", "A weight regularization scheme that biases individual memristor conductances toward lower (less conductive) states, directly trading off nonlinearity/power for reliability", "A modified validation procedure suited to stochastic nonidealities, improving reliability of performance estimates during training", "Experimentally grounded simulation using fabricated SiOx RRAM I-V characteristics across low- and high-nonlinearity regimes", "Demonstration across MLP (MNIST) and CNN (CIFAR-10) architectures, plus robustness tests on nonidealities the network was not explicitly trained for"], "claims": [{"claim": "Nonideality-aware training allows high-resistance, highly nonlinear memristors to match the accuracy of low-resistance devices while being far more energy-efficient.", "support": "High-resistance devices: 41.6% median error with standard training vs 9.1% (unregularized) / 7.1% (regularized) with nonideality-aware training on MNIST, approaching low-resistance devices' 4.3%/4.1%", "loc": "Sec. 3.2, Fig. 5"}, {"claim": "Energy efficiency of memristive VMMs improves by almost three orders of magnitude when switching from low-resistance/standard training to high-resistance/nonideality-aware+regularized training.", "support": "0.715 TOPS/W (low-resistance, standard) vs 381 TOPS/W (high-resistance, nonideality-aware, regularized); 234 TOPS/W without regularization", "loc": "Sec. 3.2, Eq. 11"}, {"claim": "Without accounting for nonidealities during training, the chosen network configuration can be highly suboptimal for nonideal inference.", "support": "Standard-trained networks show validation/test curve divergence and early-then-rising test error under high I-V nonlinearity (Fig. 4d), unlike nonideality-aware training (Fig. 4e-f)", "loc": "Sec. 3.1, Fig. 4"}, {"claim": "Nonideality-aware training generalizes robustly to nonidealities not explicitly trained for.", "support": "Reported lower error versus conventional training when encountering untrained-for nonidealities (qualitative robustness study)", "loc": "Conclusion / Sec. 3.6"}], "results": ["MNIST, high-resistance (high I-V nonlinearity) devices: 41.6% median error (standard training) -> 9.1% (nonideality-aware) -> 7.1% (nonideality-aware + regularization)", "MNIST, low-resistance devices: 4.6% (digital ANN reference) vs 4.3% (standard training) vs 4.1% (regularization), showing low-nonlinearity devices are less sensitive to the nonideality", "Estimated VMM energy efficiency: 0.715 TOPS/W (low-resistance, standard) vs 234 TOPS/W (high-resistance, nonideality-aware) vs 381 TOPS/W (high-resistance, nonideality-aware + regularized) -- ~3 orders of magnitude gain", "CNN (CIFAR-10) results qualitatively mirror MLP/MNIST findings: nonideality-aware training couples validation/test error curves and lowers inference error relative to standard training under high I-V nonlinearity (Fig. 6)"], "limitations": ["Energy-efficiency figures are estimates from an analytical power model (P=IV for crossbar arrays only; Eq. 11 assumes 50 ns read pulses and 2 ops/weight) layered on simulation, not measured end-to-end chip power", "I-V nonlinearity data come from a single device type/size (SiOx RRAM, 400 um x 400 um) extrapolated to low- and high-nonlinearity regimes via lognormal interpolation, not a full fabricated crossbar array", "Networks are relatively small-scale (MNIST MLP, CIFAR-10 CNN); scaling to larger/deeper or Transformer-scale models is not studied", "Regularization and nonideality-aware training add training-time complexity (modified forward pass, custom validation) relative to standard training"], "remarks": "A carefully done simulation study, grounded in real device I-V data, that reframes a common materials/circuits trade-off (linear-but-power-hungry vs nonlinear-but-efficient memristors) as a training-algorithm problem: if nonidealities are faithfully modeled during ex-situ training, much less linear (and thus more energy-efficient) devices become usable. The near-3-orders-of-magnitude efficiency claim is an estimate built on an analytical energy model rather than measured hardware, so it should be read as an upper-bound opportunity rather than a demonstrated system-level number; still, it is a strong, reproducible argument for hardware-aware/noise-aware training as a first-class lever (alongside device engineering) for closing the gap between high-resistance, low-power memristors and usable neural-network accuracy, and it aligns with the broader hardware-aware-training literature (e.g., IBM's HWA training work) that this collection also covers.", "basis": "full-text", "pdf_source_url": "", "abstract": "Abstract Recent years have seen a rapid rise of artificial neural networks being employed in a number of cognitive tasks. The ever‐increasing computing requirements of these structures have contributed to a desire for novel technologies and paradigms, including memristor‐based hardware accelerators. Solutions based on memristive crossbars and analog data processing promise to improve the overall energy efficiency. However, memristor nonidealities can lead to the degradation of neural network accuracy, while the attempts to mitigate these negative effects often introduce design trade‐offs, such as those between power and reliability. In this work, authors design nonideality‐aware training of memristor‐based neural networks capable of dealing with the most common device nonidealities. The feasibility of using high‐resistance devices that exhibit high I‐V nonlinearity is demonstrated—by analyzing experimental data and employing nonideality‐aware training, it is estimated that the energy efficiency of memristive vector‐matrix multipliers is improved by almost three orders of magnitude (0.715 TOPs−1W−1 to 381 TOPs−1W−1) while maintaining similar accuracy. It is shown that associating the parameters of neural networks with individual memristors allows to bias these devices toward less conductive states through regularization of the corresponding optimization problem, while modifying the validation procedure leads to more reliable estimates of performance. The authors demonstrate the universality and robustness of this approach when dealing with a wide range of nonidealities.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2022_Joksas_NonidealityAwareTraining_AdvSci.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2022_Joksas_NonidealityAwareTraining_AdvSci.pdf", "priority": 5.51}, {"id": "W4313138950", "short": "BRoCoM", "title": "BRoCoM: A Bayesian Framework for Robust Computing on Memristor Crossbar", "authors": ["Di Gao", "Zeyu Yang", "Qingrong Huang", "Grace Li Zhang", "Xunzhao Yin", "Bing Li", "Ulf Schlichtmann", "Cheng Zhuo"], "year": 2022, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2022.3215071", "cites_global": 11, "cat": "07", "seed": false, "devices": ["Memristor(generic)"], "models": [], "evidence": "algorithm+simulation", "tldr": "BRoCoM is a unified Bayesian-inference framework that folds memristor process-variation and noise statistics into a prior weight distribution and reformulates robustness optimization as Bayesian neural network training, aiming to keep inference accuracy stable when a trained network's weights deviate from their programmed memristor conductances.", "summary": "Deploying a trained neural network on a memristor crossbar requires programming memristors to target conductance values, but device-based process variation and noise cause the realized weights to deviate from the trained values, degrading inference accuracy. BRoCoM proposes a unified Bayesian inference-based framework that connects device-level nonidealities to algorithmic training: it incorporates different levels of nonideality (variation, noise) into a prior distribution over weights, then casts the robustness-optimization problem as Bayesian neural network (BNN) training, so that the optimized network weights natively accommodate the expected uncertainty and minimize inference degradation. The authors report experimental results confirming that BRoCoM achieves stable inference performance while tolerating nonideal process-variation and noise effects on memristor crossbars.", "contributions": ["A unified Bayesian-inference-based framework (BRoCoM) linking memristor device nonidealities directly to the prior weight distribution used in training", "Reformulation of crossbar robustness optimization as Bayesian neural network (BNN) training rather than ad hoc noise-injection training", "Support for incorporating different levels/types of device nonideality (process variation, noise) into the same framework", "Experimental validation that the resulting networks maintain stable inference accuracy under nonideal memristor effects"], "claims": [{"claim": "Mapping a trained NN onto memristor crossbars without compensation causes inference accuracy degradation due to weight-programming deviations from process variation and noise", "support": "motivating claim stated in the abstract", "loc": "Abstract"}, {"claim": "BRoCoM's Bayesian-training-based approach achieves stable inference performance despite nonideal process variation and noise", "support": "experimental results reported to confirm stable inference performance under nonideal effects", "loc": "Abstract"}], "results": ["Experimental results reported to confirm stable inference performance under process variation and noise (specific accuracy numbers not given in the abstract)"], "limitations": ["This entry is based on the abstract only (no full text or PDF was located); the specific NN models, datasets, nonideality magnitudes, and quantitative accuracy results are not confirmed here", "Framework appears to be evaluated via simulation of device nonideality models rather than on fabricated memristor hardware (not confirmed from abstract alone)"], "remarks": "BRoCoM belongs to the hardware-aware/noise-robust training literature (category 07) and its distinguishing idea -- folding device nonideality statistics directly into a Bayesian prior over weights rather than treating robustness as a separate regularization or noise-injection trick -- is conceptually appealing for connecting device physics to training theory. Because only the abstract was available, the magnitude of the reported robustness gains, the specific device/noise models used, and the benchmarks tested could not be verified here and should be checked in the full paper before citing specific numbers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Memristor crossbar arrays are considered to be a promising platform for neuromorphic computing. To deploy a trained neural network (NN) model on memristor crossbars, memristors need to be programmed to the corresponding weight values. In fact, due to device-based process variation and noise, deviations of the stored weights from the trained weights are inevitable, thereby causing the degradation of the actual inference performance. This article proposes a unified Bayesian inference-based framework, BRoCoM, which connects device nonidealities and algorithmic training together for robust computing on memristor crossbars. BRoCoM is able to incorporate different levels of nonidealities into prior weight distribution, and transform robustness optimization to Bayesian NN (BNN) training, the weights of NNs are optimized to accommodate uncertainties and minimize inference degradation. Experimental results confirm the capability of the proposed BRoCoM to achieve stable inference performance while tolerating the nonideal effects of process variation and noise.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2022_Gao_BRoCoM_TCAD.pdf", "analysed": true, "pdf": null, "priority": 4.26}, {"id": "W4226427756", "short": "D-NAT", "title": "D-NAT: Data-Driven Non-Ideality Aware Training Framework for Fabricated Computing-In-Memory Macros", "authors": ["Ming-Guang Lin", "Chi-Tse Huang", "Yu-Chuan Chuang", "Yi-Ta Chen", "Ying–Tuan Hsu", "Yukai Chen", "Jyun‐Jhe Chou", "Tsung-Te Liu", "Chi‐Sheng Shih", "An-Yeu Andy Wu"], "year": 2022, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems (JETCAS), vol. 12, no. 2, June 2022", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2022.3171268", "cites_global": 10, "cat": "07", "seed": false, "devices": ["SRAM-analog"], "models": ["CNN", "ResNet"], "evidence": "device-experiment", "tldr": "D-NAT trains DNNs against a MAC-error model measured directly from a fabricated SRAM-based CIM macro (plus a statistical gradient estimator and an extended-PACT activation quantizer) and, validated on-chip, recovers VGG8 CIFAR-10 accuracy from 14.17% to 87.17% (vs. an 88.33% ideal-CIM software ceiling) without any extra hardware.", "summary": "The paper targets the accuracy loss caused by MAC errors in SRAM-based compute-in-memory (CIM) macros, arising from crossbar non-idealities and peripheral-circuit (DAC/ADC) imperfections. Instead of an analytical non-ideality model (A-MAC-EM, e.g. Gaussian-based), the authors measure a fabricated SRAM-CIM macro directly to build a data-driven MAC error model (D-MAC-EM) and fold it into training: a statistical training mechanism estimates gradients through the discrete, measured D-MAC-EM, and an extended PACT (E-PACT) activation quantizer learns per-layer upper and lower clipping bounds (including negative activations) to balance quantization range against quantization error. On CIFAR-10/CIFAR-100 with ResNet20, VGG8, ResNet34 and VGG16, D-NAT recovers 78.98%, 71.8%, 72.04% and 57.85% of the accuracy lost to non-idealities relative to an analytically-trained A-NAT baseline, closing to the ideal-quantized-model upper bound. Finally, deploying the D-NAT-trained VGG8 on the actual fabricated SRAM-CIM chip (first conv layer computed on-chip, remaining layers modeled with D-MAC-EM) raises measured accuracy from 14.17% (ideal-CIM-trained model run on the real chip) to 87.17%, versus an 88.33% ideal-CIM software ceiling and 90.1% FP32 baseline, at the cost of about 5x training time and 2x GPU memory versus standard FP32 training.", "contributions": ["A data-driven MAC error model (D-MAC-EM) built from direct measurements of a fabricated SRAM-based CIM macro, replacing analytical (e.g., Gaussian) non-ideality models", "A statistical training mechanism that better estimates gradients through the discrete, measured D-MAC-EM than a plain straight-through estimator (STE)", "Extended PACT (E-PACT): a per-layer learnable upper/lower activation clipping scheme (including negative bounds) that trades off quantization range vs. quantization error", "On-chip validation of the full D-NAT pipeline on a real fabricated SRAM-CIM macro (not just simulation)", "Demonstrated scalability from small (ResNet20/VGG8 on CIFAR-10) to larger (ResNet34/VGG16 on CIFAR-100) models"], "claims": [{"claim": "A data-driven (measured) MAC error model is necessary; an analytical model is insufficient to capture real SRAM-CIM non-idealities.", "support": "A-NAT (analytical model) only slightly improves accuracy and remains low, while D-NAT (measured model) recovers accuracy close to the ideal-quantized upper bound", "loc": "Sec. V-D, Table III"}, {"claim": "D-NAT recovers most of the accuracy degradation caused by CIM non-idealities across model scales.", "support": "Accuracy recovery of 78.98% (ResNet20), 71.8% (VGG8), 72.04% (ResNet34), 57.85% (VGG16) relative to the non-ideal baseline, reaching the ideal-quantized-model bound", "loc": "Sec. V-D, Table III"}, {"claim": "D-NAT works on real fabricated hardware, not just in simulation.", "support": "On-chip VGG8/CIFAR-10 accuracy rises from 14.17% (ideal-CIM-trained model on the real chip) to 87.17% (D-NAT-trained model on the real chip), vs. 88.33% ideal-CIM / 90.1% FP32 software ceilings", "loc": "Sec. VI, Table IV"}, {"claim": "E-PACT's learned, per-layer (including negative) activation bounds outperform other quantization schemes.", "support": "E-PACT improves accuracy of ResNet20 and VGG8 by 1.1-30.1% and 0.51-12.06% respectively over compared quantization schemes", "loc": "Sec. V-C, Table II, Fig. 14"}, {"claim": "The statistical training mechanism converges faster/more stably than STE when training through the discrete D-MAC-EM.", "support": "0.55% and 1.3% accuracy improvement on ResNet20 and VGG8 respectively vs. STE", "loc": "Conclusion"}], "results": ["On-chip VGG8/CIFAR-10: accuracy improves from 14.17% (Ideal-CIM-trained model on real chip) to 87.17% (D-NAT-trained model on real chip); software references: FP32 90.1%, Ideal-CIM 88.33%", "Simulated accuracy recovery vs. non-ideal baseline: 78.98% (ResNet20), 71.8% (VGG8), 72.04% (ResNet34), 57.85% (VGG16), reaching the ideal-quantized-model upper bound", "E-PACT vs. other quantization schemes: +1.1% to +30.1% (ResNet20) and +0.51% to +12.06% (VGG8) accuracy", "Statistical training mechanism vs. STE: +0.55% (ResNet20) and +1.3% (VGG8) accuracy", "Training overhead: ~5x training time and ~2x GPU memory vs. standard FP32 training (one-time offline cost)"], "limitations": ["Validated SRAM-CIM device uses only 7-bit input activation / 1-bit weight hardware settings; generality to other bit-widths or other CIM device types (ReRAM/PCM) is only claimed, not demonstrated", "On-chip validation only computes the first convolutional layer on the real macro; remaining layers are modeled with the measured D-MAC-EM rather than executed on-chip end-to-end", "On-chip evaluation uses a reduced 600-image CIFAR-10 subset (due to limited on-chip buffer) rather than the full test set", "Training overhead (~5x time, ~2x GPU memory) could limit applicability to very large models, though the authors note it is a one-time offline cost", "D-MAC-EM is specific to the measured macro instance; portability of the data-driven model across chip-to-chip process variation is not studied"], "remarks": "A well-grounded hardware-aware-training paper distinguished by using a real, measured error model from a fabricated SRAM-based CIM macro rather than an analytical noise model, and by partially validating the trained network on that same real chip (not just simulation) -- the 14.17% to 87.17% on-chip accuracy recovery is a strong, concrete result. Because it targets digital/analog-hybrid SRAM CIM (not ReRAM/PCM analog crossbars), it is somewhat adjacent to the memristor-crossbar mapping literature in this collection, but the core idea (data-driven, measured non-ideality models feeding training, versus analytical noise injection) is directly relevant and comparable to NEAT and other ReRAM nonlinearity-aware training works it engages with and improves upon.", "basis": "full-text", "pdf_source_url": "", "abstract": "To enable energy-efficient computation for deep neural networks (DNNs) at edge, computing-in-memory (CIM) is proposed to reduce the energy costs during intense off-chip memory access. However, CIM is prone to multiply-accumulate (MAC) errors due to non-idealities of memory crossbars and peripheral circuits, which severely degrade the accuracy of DNNs. In this work, we propose a Data-Driven Non-ideality Aware Training (D-NAT) framework to compensate for the accuracy degradation. The proposed D-NAT framework has the following contributions: 1) We measured a fabricated SRAM-based CIM macro to obtain a data-driven MAC error model (D-MAC-EM). Based on the derived D-MAC-EM, we analyze the impact of the non-idealities on DNN’s accuracy. 2) To make DNNs robust to the non-idealities of CIM macros, we incorporate the measured D-MAC-EM into DNN’s training procedure. Moreover, we propose a statistical training mechanism to better estimate the gradients of the discrete D-MAC-EM. 3) We investigate trade-offs between quantization range and quantization errors. To mitigate the quantization errors in activations, we introduce extended PACT (E-PACT) that adaptively learns the upper and lower bounds of input activations for each layer. Simulation results show that our proposed D-NAT improves the accuracy of ResNet20, VGG8, ResNet34, and VGG16 by 78.98%, 71.8%, 72.04%, and 57.85%, respectively, which reaches the ideal upper bound of the quantized model. Lastly, the D-NAT framework is validated on an FPGA platform with the fabricated SRAM-based CIM macro chip. Based on the measurement results, D-NAT successfully recovers the accuracy under non-idealities of a real SRAM-based CIM macro.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2022_Lin_DNAT_JETCAS.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2022_Lin_DNAT_JETCAS.pdf", "priority": 4.23}, {"id": "W3201198776", "short": "CF-MESMO", "title": "Multi-Objective Optimization of ReRAM Crossbars for Robust DNN Inferencing under Stochastic Noise", "authors": ["Xiaoxuan Yang", "Syrine Belakaria", "Biresh Kumar Joardar", "Huanrui Yang", "Janardhan Rao Doppa", "Partha Pratim Pande", "Krishnendu Chakrabarty", "Hai Helen Li"], "year": 2021, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad51958.2021.9643444", "cites_global": 50, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "Proposes ReSNA, a stochastic-noise-aware training method for ReRAM DNN inference, plus CF-MESMO, a continuous-fidelity Bayesian multi-objective optimizer that searches ReRAM design configurations far more cheaply than NSGA-II.", "summary": "The paper studies stochastic noise (thermal, shot, random telegraph, programming) in ReRAM crossbars, which is distinct from the deterministic defects/drift studied in most prior work, and shows it significantly degrades DNN inference accuracy, especially for high-resolution cells and FC layers. It proposes ReSNA, a hardware-aware training method that injects device-calibrated stochastic noise during training, applies lower noise to FC layers than Conv layers (since FC layers accumulate noise more because Conv kernel duplication averages out noise), and uses majority-vote duplication in the classification layer. Because evaluating each ReRAM design via ReSNA training is expensive (~7 hours per 100-epoch run, ~30 GPU-days for 100 configurations), the paper formulates a multi-objective optimization (MOO) problem over ReRAM design space (cell resolution, frequency, temperature, crossbar size) against accuracy/area/latency/energy, and solves it with CF-MESMO, a continuous-fidelity extension of Max-value Entropy Search for Multi-Objective optimization (MESMO) that varies the number of training epochs as a fidelity knob. Experiments on ResNet20/32/44, VGG11/13 (CIFAR-10) and ResNet18 (CIFAR-100), using PytorX for noise simulation and NeuroSim (32nm) for area/latency/energy, show ReSNA improves accuracy over an untrained-for-noise baseline and CF-MESMO finds comparable-quality Pareto fronts at a fraction of the search cost of NSGA-II, random search, and single-fidelity MESMO.", "contributions": ["Identifies and quantifies the impact of stochastic noise (thermal/shot/RTN/programming) on ReRAM DNN inference accuracy, distinct from deterministic nonidealities studied in prior work", "ReSNA: a stochastic-noise-aware training method with layer-differentiated noise injection (less noise on FC layers) and majority-vote classification-layer duplication", "CF-MESMO: a continuous-fidelity information-theoretic multi-objective Bayesian optimization algorithm that varies ReSNA training epochs as a fidelity dial to cut search cost", "Joint accuracy/area/latency/energy Pareto-front analysis across ReRAM design configurations (cell resolution, crossbar size, frequency, temperature) for multiple CNNs"], "claims": [{"claim": "ReSNA improves DNN inference accuracy under stochastic noise relative to a no-noise-trained baseline", "support": "ReSNA without voting beats baseline by 1.62% on average across test conditions for ResNet20; with voting, by 2.57% on average, and by 5.47% at the extreme 1000 MHz/400 K setting", "loc": "Sec. VII-B"}, {"claim": "CF-MESMO reaches the same quality Pareto front as NSGA-II and random search at far lower computation cost", "support": "90.91% and 91.21% reduction in computation cost vs. NSGA-II and random search respectively", "loc": "Sec. VII-C, Fig. 6(a)"}, {"claim": "Continuous-fidelity evaluation beats single-maximum-fidelity MESMO", "support": "CF-MESMO lowers computation cost by 78.18% to reach the same quality Pareto front as MESMO (fixed 100-epoch fidelity)", "loc": "Sec. VII-C, Fig. 6(b)"}, {"claim": "Evaluating ReRAM designs via noise-aware training is prohibitively expensive, motivating the fidelity approach", "support": "~7 hours for 100 training epochs per configuration; ~30 GPU-days to evaluate 100 configurations with the PytorX simulator", "loc": "Sec. VI, Sec. VII-C"}, {"claim": "Increasing ReRAM cell resolution to save area hurts inference accuracy due to reduced noise margin", "support": "Going from 2-bit to 8-bit cells cuts crossbar count by 75% but drops the noise margin by 64x (margin inversely proportional to 2^Rescell)", "loc": "Sec. IV-C"}], "results": ["ReSNA with voting: +2.57% average inference accuracy over baseline (ResNet20, CIFAR-10, 8-bit cells, 64x64 crossbars) across temperature/frequency sweep; +5.47% at 1000 MHz/400 K", "ResNet18/CIFAR-100: ReSNA 70.80% vs baseline 69.37% at 500 MHz/350K; ReSNA 68.23% vs baseline 64.45% at 1000 MHz/350K", "CF-MESMO vs NSGA-II / random search: 90.91% / 91.21% reduction in computation cost to reach equal-quality Pareto front", "CF-MESMO vs single-fidelity MESMO: 78.18% lower computation cost for equal-quality Pareto front", "Design-space search covers an estimated 1.485x10^7 candidate ReRAM configurations"], "limitations": ["Evaluated only on CIFAR-10/CIFAR-100 with ResNet/VGG family models, not larger datasets (ImageNet) or transformer/LLM workloads", "Relies on PytorX simulator and NeuroSim area/energy models at 32nm rather than silicon measurement", "ReSNA's noise model (Gaussian approximations for thermal/shot noise, extracted programming-noise sigma) is itself a simplification of real device behavior", "Majority-vote duplication for the classification layer adds area overhead not fully quantified against overall chip budget"], "remarks": "This is a software/algorithmic co-design paper rather than a hardware or device paper: its contribution is a Bayesian-optimization search strategy (CF-MESMO) and a differentiated noise-injection training recipe (ReSNA), evaluated purely in simulation (PytorX + NeuroSim). It usefully separates stochastic noise (thermal/shot/RTN/programming) from the deterministic defect/drift nonidealities that dominate most of the ReRAM mapping literature, and the FC-vs-Conv noise sensitivity argument (duplication averages out Conv noise but not FC noise) is a concrete, reusable observation for crossbar mapping. The CF-MESMO search-cost reduction is the paper's most novel angle, relevant to anyone needing to explore large hardware/algorithm co-design spaces cheaply, though its benefit is specific to this MOO formulation and evaluation protocol.", "basis": "full-text", "pdf_source_url": "", "abstract": "Resistive random-access memory (ReRAM) is a promising technology for designing hardware accelerators for deep neural network (DNN) inferencing. However, stochastic noise in ReRAM crossbars can degrade the DNN inferencing accuracy. We propose the design and optimization of a high-performance, area-and energy-efficient ReRAM-based hardware accelerator to achieve robust DNN inferencing in the presence of stochastic noise. We make two key technical contributions. First, we propose a stochastic-noise-aware training method, referred to as ReSNA, to improve the accuracy of DNN inferencing on ReRAM crossbars with stochastic noise. Second, we propose an information-theoretic algorithm, referred to as CF-MESMO, to identify the Pareto set of solutions to trade-off multiple objectives, including inferencing accuracy, area overhead, execution time, and energy consumption. The main challenge in this context is that executing the ReSNA method to evaluate each candidate ReRAM design is prohibitive. To address this challenge, we utilize the continuous-fidelity evaluation of ReRAM designs associated with prohibitive high computation cost by varying the number of training epochs to trade-off accuracy and cost. CF-MESMO iteratively selects the candidate ReRAM design and fidelity pair that maximizes the information gained per unit computation cost about the optimal Pareto front. Our experiments on benchmark DNNs show that the proposed algorithms efficiently uncover high-quality Pareto fronts. On average, ReSNA achieves 2.57% inferencing accuracy improvement for ResNet20 on the CIFAR-10 dataset with respect to the baseline configuration. Moreover, CF-MESMO algorithm achieves 90.91% reduction in computation cost compared to the popular multi-objective optimization algorithm NSGA-II to reach the best solution from NSGA-II.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2021_Yang_CFMESMO_ICCAD.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2021_Yang_CFMESMO_ICCAD.pdf", "priority": 6.79}, {"id": "W3195461290", "short": "Noise-Resilient DNN", "title": "Noise-Resilient DNN: Tolerating Noise in PCM-Based AI Accelerators via Noise-Aware Training", "authors": ["Sanjay Kariyappa", "Hsinyu Tsai", "Katie Spoon", "Stefano Ambrogio", "Pritish Narayanan", "Charles Mackin", "An Chen", "Moinuddin K. Qureshi", "Geoffrey W. Burr"], "year": 2021, "venue": "IEEE Transactions on Electron Devices", "venue_short": "TED", "venue_full": "IEEE Transactions on Electron Devices (2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/ted.2021.3089987", "cites_global": 46, "cat": "07", "seed": false, "devices": ["PCM"], "models": ["CNN", "LSTM/RNN"], "evidence": "algorithm+simulation", "tldr": "Proposes two training-time techniques -- drift regularization (DR) and multiplicative noise training (MNT) -- to make DNNs mapped onto PCM-based Analog-AI accelerators more resilient to PCM read noise and conductance drift, improving model accuracy by up to 12% after one month of drift.", "summary": "PCM-based 'Analog-AI' accelerators offer energy-efficient in-memory inference but suffer from device-inherent noise sources (read noise and long-term conductance drift) that corrupt DNN weight values stored as PCM conductances, degrading inference accuracy over time. This paper (from an IBM-affiliated author group including Ambrogio, Tsai, Narayanan, Burr et al., who are central to IBM's PCM Analog-AI research) proposes two noise-resiliency training techniques: drift regularization (DR), which regularizes training to reduce sensitivity to conductance drift, and multiplicative noise training (MNT), which injects multiplicative (rather than purely additive) noise during training to better match the statistics of PCM programming/read noise. The techniques are evaluated on convolutional networks for image classification and recurrent networks for language modeling, measuring accuracy as a function of elapsed time after programming (to capture drift effects). The combined techniques improve model accuracy by up to 12% after one month of drift compared to a non-noise-aware baseline.", "contributions": ["Proposes drift regularization (DR), a training-time regularizer targeting PCM conductance drift sensitivity", "Proposes multiplicative noise training (MNT), injecting multiplicative noise during training to better match PCM device noise statistics than standard additive noise injection", "Evaluates noise resiliency across both CNNs (image classification) and RNNs (language modeling), rather than CNNs alone", "Demonstrates accuracy improvement specifically as a function of time elapsed since weight programming, directly addressing long-term drift rather than only instantaneous read noise"], "claims": [{"claim": "DR and MNT jointly improve long-term inference accuracy on PCM-based accelerators", "support": "Up to 12% accuracy improvement over one month compared to baseline (non-noise-aware) training", "loc": "Abstract"}], "results": ["Up to 12% accuracy improvement over a one-month drift period on PCM-based inference, combining drift regularization and multiplicative noise training, vs. a non-hardware-aware baseline"], "limitations": ["Full text not available to this analysis (abstract-only basis); exact network architectures, datasets, drift/noise models, and baseline details could not be independently verified", "Evaluation appears simulation-based (noise/drift models applied to trained networks) rather than on physically fabricated PCM hardware, based on the abstract"], "remarks": "This paper sits squarely in the hardware-aware noise-robust training literature alongside IBM's broader PCM Analog-AI line (Ambrogio et al. on drift compensation, Joshi et al. on computational PCM inference), and is cited by several later IBM Analog-AI papers (e.g., combined HW/SW drift mitigation, hardware-aware training for diverse workloads, the IBM AIHWKit paper) as an early reference for drift-aware regularization and multiplicative noise training. Because full text could not be retrieved (not on arXiv; aggregator APIs were rate-limited/blocked during this pass), this entry is abstract-only; a thesis-level treatment would benefit from obtaining the IEEE TED version to extract the specific drift model, noise injection formulation, and per-network/per-dataset accuracy-vs-time curves.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Phase change memory (PCM)-based “Analog-AI” accelerators are gaining importance for inference in edge applications due to the energy efficiency offered by in-memory computing. Nevertheless, noise sources inherent to PCM devices cause inaccuracies in the deep neural network (DNN) weight values. Such inaccuracies can lead to severe degradation in model accuracy. To address this, we propose two techniques to improve noise resiliency of DNNs: 1) drift regularization (DR) and 2) multiplicative noise training (MNT). We evaluate convolutional networks trained on image classification and recurrent neural networks trained on language modeling and show that our techniques improve model accuracy by up to 12% over one month.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2021_Kariyappa_NoiseResilientDNN_TED.pdf", "analysed": true, "pdf": null, "priority": 7.9}, {"id": "W3198405160", "short": "NEAT", "title": "NEAT: Nonlinearity Aware Training for Accurate, Energy-Efficient, and Robust Implementation of Neural Networks on 1T-1R Crossbars", "authors": ["Abhiroop Bhattacharjee", "Lakshya Bhatnagar", "Youngeun Kim", "Priyadarshini Panda"], "year": 2021, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2021.3109857", "cites_global": 31, "cat": "07", "seed": false, "devices": ["ReRAM", "Memristor(generic)"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "NEAT trains DNNs to keep weights within the SPICE-characterized linear-conductance regime of a 1T-1R crossbar synapse, recovering accuracy lost to transistor-induced non-linearity while cutting energy via lower gate-voltage operation.", "summary": "Memristive 1T-1R crossbars add a series transistor to suppress sneak paths, but the transistor's voltage-dependent (data-dependent) non-linearity distorts the effective conductance Geff away from the ideal memristor conductance GM, which degrades DNN accuracy when weights are mapped onto the array. The paper first runs SPICE Monte-Carlo characterization of a PTM 45nm 1T-1R cell to show that for a given gate-voltage Vg there is a conductance cutoff (Geff_cutoff / Wcut) below which Geff tracks GM linearly. It then proposes Non-linearity Aware Training (NEAT): weights are clipped to [-Wcut, Wcut] and the network is iteratively retrained (clip-then-retrain for N=30 iterations) to recover accuracy, under either a homogeneous (single Vg for all layers) or heterogeneous (per-layer Vg search, Algorithm 1) gate-voltage control scheme. Experiments on VGG11/ResNet18 with CIFAR-10/CIFAR-100 in PyTorch show iterative training largely restores accuracy lost from clipping and that heterogeneous, layer-wise Vg selection gives better energy/accuracy trade-offs than a single global Vg. The version analyzed here is the earlier arXiv preprint (2012.00261); the published TCAD journal version additionally reports adversarial robustness experiments (FGSM/PGD) and combines NEAT with other non-idealities on nonideal 64x64 crossbars (per the abstract), which are not present in this preprint text.", "contributions": ["SPICE-based characterization identifying the transistor gate-voltage Vg and NVM conductance GM as the key factors governing 1T-1R non-linearity and per-synapse power", "Definition of a conductance cutoff (Geff_cutoff / Wcut) marking the linear-operation boundary of a 1T-1R synapse for a given Vg", "Non-linearity Aware Training (NEAT): iterative weight-clipping + retraining to keep DNN weights within the linear regime", "Homogeneous vs. heterogeneous (layer-wise) gate-voltage control schemes with an Algorithm 1 search procedure for per-layer optimal Vg", "Empirical energy-accuracy trade-off study on VGG11/ResNet18 with CIFAR-10/CIFAR-100"], "claims": [{"claim": "NEAT achieves roughly 20% energy gain on ResNet18 with CIFAR-10/CIFAR-100 with less than 1% accuracy loss using homogeneous gate control.", "support": "~20% energy gain, <1% accuracy loss claim in abstract/intro", "loc": "Abstract; Sec. I contributions"}, {"claim": "With iterative training, ~23% energy gain is achievable at Vg=0.8 on ResNet18/CIFAR-10 with only ~1.5% accuracy loss, while Vg=0.75 causes severe degradation without it.", "support": "~23% energy gain at Vg=0.8, ~1.5% accuracy loss; Vg=0.75 induces huge degradation", "loc": "Sec. IV-C, Fig. 11; Sec. IV-A, Fig. 8"}, {"claim": "Heterogeneous (layer-wise) Vg selection yields over 10% energy gain in all tested configurations while keeping accuracy drop under 0.3% at the 'Optimal Vg' setting (no iterative training needed).", "support": "<0.3% accuracy drop at Optimal Vg; >10% energy gain for heterogeneous setting", "loc": "Sec. IV-B, Table I; Sec. IV-C"}, {"claim": "Iterative training drives ~96% of weights in the first convolution layer into the linear regime after 30 iterations.", "support": "~96% of weights in linear regime after 30 iterations", "loc": "Sec. IV-A, Fig. 9"}], "results": ["~20% energy gain with <1% accuracy loss on ResNet18 (CIFAR-10/CIFAR-100), homogeneous gate control (abstract)", "~23% energy gain at Vg=0.8 for ResNet18/CIFAR-10 with ~1.5% accuracy loss (Sec. IV-C)", ">50% accuracy improvement from iterative training at Vg=0.75 for ResNet18 (Sec. IV-A)", "Heterogeneous 'Optimal Vg' setting: <0.3% accuracy drop across VGG11/ResNet18 x CIFAR-10/CIFAR-100 without iterative training (Table I)", "Heterogeneous setting achieves >10% energy gain in all tested configurations (Sec. IV-C, Fig. 11)"], "limitations": ["Evaluated only on VGG11 and ResNet18 with CIFAR-10/CIFAR-100, not ImageNet-scale models", "1T-1R non-linearity characterization relies on a single SPICE device model (PTM 45nm CMOS, fixed RON/ROFF), not validated against fabricated silicon", "This analysis is based on the earlier arXiv preprint; the published TCAD version reportedly adds adversarial robustness (FGSM/PGD) results and combination with other non-idealities not present in this text", "Weight clipping approach is complementary to, not a replacement for, other non-ideality mitigation (IR drop, device variation), so it must be combined with other techniques for a full accuracy picture", "Vg search granularity (0.05V steps) is coarse; finer search is noted as possible but untested"], "remarks": "This is a clean, device-physics-grounded contribution to hardware-aware training: it isolates one specific, previously under-addressed 1T-1R non-ideality (transistor-induced non-linearity) and shows a simple, cheap fix (weight clipping + retraining) with a layer-wise control knob (gate voltage) that trades energy for accuracy. The evidence is simulation/SPICE + PyTorch retraining on small-to-mid-size CNNs, not measured hardware, and the dataset used here is an earlier preprint rather than the full published TCAD paper, so the adversarial-robustness claims in the abstract are not verified from this text. For a crossbar-mapping thesis, it is a good example of co-designing circuit-level device modeling with training-time weight regularization rather than purely architectural or ADC-side fixes.", "basis": "full-text", "pdf_source_url": "", "abstract": "In this era of IoT, energy-efficient and adversarially secure implementation of deep neural networks (DNNs) on hardware has become imperative. Memristive crossbars have emerged as an energy-efficient component of deep learning hardware accelerators due to their compact and efficient matrix-vector multiplication (MVM) implementation. However, they suffer from nonidealities (such as, interconnect parasitics, device variations, and sneak paths) introduced by their circuit topology that degrades computational accuracy. A 1T-1R synapse, adding a transistor (1T) in series with the memristive synapse (1R), has been proposed to mitigate sneak paths in a crossbar. However, we observe that the nonlinear characteristics of the transistor affect the overall conductance of the 1T-1R cell which in turn affects the MVM operation. This 1T-1R nonlinearity arising from the input voltage-dependent nonlinearity is not only difficult to model or formulate, but also causes a drastic performance degradation of DNNs when mapped to such crossbars. In this article, we first analyses the nonlinearity in ideal 1T-1R crossbars (excluding nonidealities, such as device variations and interconnect parasitics) and propose a novel nonlinearity aware training (NEAT) method to address the nonlinearities. Specifically, we first identify the range of network weights, which can be mapped into the 1T-1R cell within the linear operating region of the transistor. After that, we regularize the weights of neural networks to exist within the linear operating range by using an iterative training algorithm. Our iterative training significantly recovers the classification accuracy drop caused by the nonlinearity. Moreover, we find that each layer has a different weight distribution and in turn requires different gate voltage of transistor to guarantee linear operation. Based on this observation, we achieve energy efficiency while preserving classification accuracy by applying heterogeneous gate-voltage control to the 1T-1R cells across different layers. Finally, we conduct various experiments on CIFAR10 and CIFAR100 benchmark datasets to demonstrate the effectiveness of our NEAT. Overall, NEAT yields$\\sim 20\\%$energy gain with less than 1% accuracy loss (with homogeneous gate control) when mapping ResNet18 networks on 1T-1R crossbars. Thereafter, we integrate the 1T-1R crossbars with various nonidealities. We show that NEAT leads to more adversarially robust mappings of DNNs onto nonideal 1T-1R crossbars than standard DNNs mapped directly onto 1R crossbars. In case of a VGG11 network on CIFAR100 dataset, we obtain$\\sim 17$% improvement in clean accuracy and$\\sim 2$%–8% &$\\sim 5$%–6% improvements in adversarial accuracies, respectively, for fast gradient sign method (FGSM) and projected gradient descent (PGD)-based adversarial attacks via NEAT on nonideal 64$\\times $64 crossbars, in comparison to standard DNNs.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2021_Bhattacharjee_NEAT_TCAD.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2021_Bhattacharjee_NEAT_TCAD.pdf", "priority": 6.36}, {"id": "W3109300165", "short": "Robust Trainable Quantizer", "title": "A Quantized Training Framework for Robust and Accurate ReRAM-based Neural Network Accelerators", "authors": ["Chenguang Zhang", "Pingqiang Zhou"], "year": 2021, "venue": "", "venue_short": "ASP-DAC", "venue_full": "26th Asia and South Pacific Design Automation Conference (ASP-DAC 2021)", "venue_ok": true, "doi": "https://doi.org/10.1145/3394885.3431528", "cites_global": 4, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "A learnable, non-uniform weight quantizer trained with an EM-style clustering algorithm that trades off quantization error against conductance-variation sensitivity improves ReRAM inference accuracy by 10-30% over uniform quantization under large conductance variation, with no extra hardware overhead.", "summary": "The paper targets accuracy loss from ReRAM conductance variation (device-to-device and pulse-to-pulse), which is lognormally distributed around the target conductance and gets worse at higher conductance values. The authors make two observations: (1) weights mapped to higher-conductance ReRAM states suffer larger absolute variation, so robustness improves if fewer weights use high-conductance states, and (2) quantization itself introduces error that must be jointly minimized with variation sensitivity. They formulate quantization as a 1-D weighted clustering problem, where each quantization level's 'sensitivity' is approximated via a 3-sigma conductance bound, and combine a quantization-error term (L1) with an accumulated-squared-error variation-sensitivity term (L2, weighted by hyperparameter gamma) into one objective. An EM-style algorithm alternately updates quantization levels (M-step, closed form under a constant-relative-variation assumption) and cluster assignments (E-step) during the forward pass, with the straight-through estimator used for backpropagation through the non-differentiable quantizer; no extra hardware is required since this is a software-only training-time technique compatible with any ReRAM accelerator. Evaluated on a 2-layer MLP (LeNet-300-100) on MNIST using the PytorX-based simulator, with conductance variation swept via Monte Carlo (sigma 0-2.0), the learned quantizer degrades much more gracefully than uniform quantization (e.g., 88.7% vs 58.79% at sigma=0.6) and outperforms a prior variation-tolerant quantization-aware regularization method (Song et al.) at the same variation levels while also matching or exceeding uniform-quantization accuracy with no variation.", "contributions": ["A quantitative framework decomposing weight deviation under ReRAM mapping into quantization error and device-variation sensitivity, both to be jointly minimized", "A trainable, non-uniform quantizer formulated as weighted 1-D clustering, with a sensitivity term derived from a 3-sigma conductance-variation model", "An EM-style layer-by-layer optimization algorithm to solve for quantization levels and cluster assignments during training, integrated with a standard STE-based backward pass", "A tunable hyperparameter (gamma) exposing an explicit accuracy-robustness trade-off that can be selected per deployment variation level", "Evaluation showing 10-30% accuracy improvement over uniform quantization under large conductance variation with no extra hardware overhead"], "claims": [{"claim": "The proposed quantized training framework improves inference accuracy by 10-30% under large conductance variation compared to uniform quantization", "support": "Abstract claim; Fig. 4 shows e.g. 88.7% (proposed) vs 58.79% (uniform) at sigma=0.6", "loc": "Abstract, Sec. 4.2, Fig. 4"}, {"claim": "The method matches or exceeds uniform-quantization accuracy even with no device variation", "support": "At sigma=0: 94.69% (proposed, best gamma) vs 93.07% (uniform quantization)", "loc": "Sec. 4.2, Fig. 4"}, {"claim": "The method outperforms a prior variation-tolerant quantization-aware regularization approach (Song et al. [14]) at comparable variation levels", "support": "At sigma=0.6/1.2/2.0: proposed 88.7%/51.65%/24.05% vs Song's 87.02%/48.16%/22%, with proposed also better at sigma=0 (94.69% vs Song's 94.11%)", "loc": "Sec. 4.2"}, {"claim": "The learned quantizer allocates finer quantization resolution to low-magnitude, high-density weight regions (which suffer less variation)", "support": "Fig. 5: weight distribution after quantization shows denser quantization levels near zero", "loc": "Sec. 4.2, Fig. 5"}, {"claim": "The robustness-accuracy trade-off is tunable via the gamma hyperparameter", "support": "Fig. 6: larger gamma improves robustness at the cost of some accuracy degradation under small variation", "loc": "Sec. 4.3, Fig. 6"}], "results": ["Uniform quantization accuracy degrades from 93.07% (sigma=0) to 58.79%/32.67%/25.64% at sigma=0.6/1.2/2.0", "Proposed method achieves 94.69%/88.7%/51.65%/24.05% at sigma=0/0.6/1.2/2.0 (best gamma per point)", "Prior method (Song et al.) achieves 94.11%/87.02%/48.16%/22% at the same sigma values", "Evaluated on LeNet-300-100 (2-hidden-layer MLP) on MNIST with 64x64 crossbars using the PytorX simulator"], "limitations": ["Evaluated only on a small 2-layer MLP (LeNet-300-100) on MNIST; no CNN or larger-scale network results", "Relies on simulation (PytorX-based) with an analytical lognormal conductance-variation model rather than measured device data", "The hyperparameter gamma must be tuned per expected variation level, requiring prior knowledge or search (Fig. 6) rather than being fully adaptive", "The constant-relative-variation assumption (3*sigma_g(k)/g(k) = constant) used to get a closed-form M-step is a simplification of real device statistics", "Only weight quantization is addressed; input/output quantization (ADC/DAC) effects are treated separately/fixed rather than co-optimized"], "remarks": "This is a compact, training-only contribution that nicely isolates how the choice of non-uniform quantization levels can be used as a free robustness lever against ReRAM conductance variation, without touching hardware. The evaluation is limited to a tiny MLP on MNIST, so the magnitude of the reported 10-30% accuracy gains should be read as a proof-of-concept rather than a result generalizable to deep CNNs or transformers; nonetheless it is directly comparable to other noise-injection/regularization papers in this collection (e.g., Noise Injection Adaptation, Song et al.) and extends that line of work by making the quantization levels themselves learnable rather than fixed uniform or power-of-two grids.", "basis": "full-text", "pdf_source_url": "", "abstract": "Neural networks (NN), especially deep neural networks (DNN), have achieved great success in lots of fields. ReRAM crossbar, as a promising candidate, is widely employed to accelerate neural network owing to its nature of processing MVM. However, ReRAM crossbar suffers high conductance variation due to many non-ideal effects, resulting in great inference accuracy degradation. Recent works use uniform quantization to enhance the tolerance of conductance variation, but these methods still suffer high accuracy loss with large variation. In this paper, firstly, we analyze the impact of the quantization and conductance variation on the accuracy. Then, based on two observation, we propose a quantized training framework to enhance the robustness and accuracy of the neural network running on the accelerator, by introducing a smart non-uniform quantizer. This framework consists of a robust trainable quantizer and a corresponding training method, and needs no extra hardware overhead and compatible with a standard neural network training procedure. Experimental results show that our proposed method can improve inference accuracy by 10% ~ 30% under large variation, compared with uniform quantization method.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2021_Zhang_RobustTrainableQuantizer_ASPDAC.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2021_Zhang_RobustTrainableQuantizer_ASPDAC.pdf", "priority": 4.89}, {"id": "W2948661249", "short": "PCM-NoiseInject", "title": "Accurate deep neural network inference using computational phase-change memory", "authors": ["Vinay Joshi", "Manuel Le Gallo", "Simon Haefeli", "Irem Boybat", "S. R. Nandakumar", "Christophe Piveteau", "Martino Dazzi", "Bipin Rajendran", "Abu Sebastian", "Evangelos Eleftheriou"], "year": 2020, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-020-16108-9", "cites_global": 472, "cat": "07", "seed": false, "devices": ["PCM"], "models": ["CNN", "ResNet"], "evidence": "device-experiment", "tldr": "A hardware-calibrated weight-noise-injection training scheme plus periodic batch-norm recalibration lets ResNet-32/34 weights transferred to real PCM devices retain 93.5%+ CIFAR-10 accuracy over a day and 71.6% top-1 on ImageNet.", "summary": "The paper addresses the accuracy loss that occurs when digitally trained DNN weights are transferred to noisy, drifting PCM conductances for analog in-memory inference. It proposes injecting weight noise during software training, with noise statistics estimated once from a hardware characterization of read/write noise, rather than from extra tunable hyperparameters. Each ResNet-32 weight is encoded as a differential pair of PCM conductances (G+ - G-) programmed on a prototype PCM chip, with the rest of the network simulated in software. A global drift-compensation (GDC) scheme recalibrates batch-normalization statistics over time to counteract conductance drift and 1/f-noise-driven activation shifts. The method is validated with real hardware programming of all 361,722 ResNet-32 weights on PCM devices (CIFAR-10) and in simulation for ResNet-34 on ImageNet.", "contributions": ["A noise-injection training method whose noise level is derived from a one-time PCM hardware characterization rather than extra hyperparameters", "Hardware/software co-validation: 361,722 ResNet-32 weights physically programmed on PCM devices in a differential (G+/G-) configuration", "A global drift-compensation (GDC) technique that recalibrates batch-norm parameters over time to offset conductance drift and noise", "Demonstration of accuracy retention over a 1-day period on real hardware, and of scaling the approach to ImageNet-scale ResNet-34 in simulation"], "claims": [{"claim": "Noise-injected training recovers near-software accuracy after mapping to PCM", "support": "93.7% CIFAR-10 and 71.6% top-1 ImageNet accuracy after mapping trained weights to PCM", "loc": "Abstract"}, {"claim": "Real PCM hardware retains high accuracy over time after programming", "support": "experimental accuracy of 93.75% immediately after programming, staying above 92.6% over 1 day on CIFAR-10/ResNet-32", "loc": "Sec. II (Results)"}, {"claim": "Global drift compensation (GDC) substantially improves long-term accuracy retention vs. simple global scaling", "support": "up to 93.5% retained accuracy on hardware with GDC vs. lower accuracy with simple global scaling, at the cost of extra digital calibration", "loc": "Sec. II / Abstract"}, {"claim": "Each synaptic weight needs only two PCM devices for high accuracy", "support": "361,722 synaptic weights each programmed on just two PCM devices (differential pair)", "loc": "Abstract, Methods"}], "results": ["93.7% accuracy on CIFAR-10 (ResNet-32) after mapping trained weights to PCM (software/behavioral model)", "71.6% top-1 accuracy on ImageNet (ResNet-34) after mapping to PCM", "93.75% measured hardware accuracy immediately after programming on CIFAR-10, retained above 92.6% over 1 day without compensation, and up to ~93.5% with global drift compensation"], "limitations": ["Hardware validation is limited to CIFAR-10/ResNet-32; ImageNet/ResNet-34 results are software-simulated with a behavioral PCM model, not measured on-chip", "Noise/drift model is based on a one-time array-level characterization and may not capture all device-to-device or chip-to-chip variability", "Retention is only demonstrated over a 1-day window, not the multi-year horizons relevant for deployed inference accelerators", "Relies on periodic digital recalibration (GDC) of batch-norm parameters, adding runtime/calibration overhead"], "remarks": "This is one of the more rigorous experimental demonstrations that software noise-injection training, calibrated from real device statistics, can make PCM-based inference competitive with digital baselines at a non-trivial scale (ResNet-32 fully programmed on real PCM). It is frequently cited as a baseline/comparison point by later hardware-aware training and drift-mitigation work (e.g., batch-norm-based drift compensation became a recurring technique). The main caveat for a thesis on crossbar mapping is that only the CIFAR-10 network was physically realized on hardware; larger ImageNet-scale claims still rest on simulation with a fitted device model.", "basis": "full-text", "pdf_source_url": "", "abstract": "In-memory computing using resistive memory devices is a promising non-von Neumann approach for making energy-efficient deep learning inference hardware. However, due to device variability and noise, the network needs to be trained in a specific way so that transferring the digitally trained weights to the analog resistive memory devices will not result in significant loss of accuracy. Here, we introduce a methodology to train ResNet-type convolutional neural networks that results in no appreciable accuracy loss when transferring weights to phase-change memory (PCM) devices. We also propose a compensation technique that exploits the batch normalization parameters to improve the accuracy retention over time. We achieve a classification accuracy of 93.7% on CIFAR-10 and a top-1 accuracy of 71.6% on ImageNet benchmarks after mapping the trained weights to PCM. Our hardware results on CIFAR-10 with ResNet-32 demonstrate an accuracy above 93.5% retained over a one-day period, where each of the 361,722 synaptic weights is programmed on just two PCM devices organized in a differential configuration.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2020_Joshi_PCMNoiseInject_NatCommun.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2020_Joshi_PCMNoiseInject_NatCommun.pdf", "priority": 9.85}, {"id": "W3016762888", "short": "KD+RSA Joint Algo-Design", "title": "Accurate Inference With Inaccurate RRAM Devices: A Joint Algorithm-Design Solution", "authors": ["Gouranga Charan", "Abinash Mohanty", "Xiaocong Du", "Gokul Krishnan V", "Rajiv Joshi", "Yu Kevin Cao"], "year": 2020, "venue": "IEEE Journal on Exploratory Solid-State Computational Devices and Circuits", "venue_short": "JXCDC", "venue_full": "IEEE Journal on Exploratory Solid-State Computational Devices and Circuits (JXCDC), vol. 6, no. 1, 2020", "venue_ok": true, "doi": "https://doi.org/10.1109/jxcdc.2020.2987605", "cites_global": 48, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "A joint algorithm-design solution combining knowledge-distillation-based variation-aware training (premapping) with random sparse adaptation using a small on-chip SRAM (postmapping) recovers near-software accuracy on RRAM (99.41% MNIST LeNet-5, 91.86% CIFAR-10 VGG-16) with up to 5% parameter overhead and 15-150x speedup over read-verify-write.", "summary": "The paper addresses accuracy degradation when a pretrained DNN is mapped to an RRAM crossbar for inference, due to device-to-device/cycle-to-cycle write variation, stuck-at-faults (9.04% SF1, 1.75% SF0), and coarse (4-bit) quantization. Prior read-verify-write (R-V-W) cell-by-cell compensation is accurate but slow because RRAM writes (us-ms) are far slower than SRAM (~1ns). The proposed joint algorithm-design solution has two parts: (1) a premapping software step using knowledge distillation (KD), where a full-precision teacher guides training of a 'student' model that has RRAM nonidealities (4-bit quantization, SAFs, lognormal write-variation with sigma=0.1) injected during training, improving accuracy by 2.28% (MNIST) and 4.53% (CIFAR-10) over training the realistic model standalone; and (2) a postmapping hardware step, random sparse adaptation (RSA), which hard-wires a small on-chip SRAM in parallel with a random subset of RRAM cells (masked/non-trainable) and trains only the SRAM to recover accuracy, avoiding slow RRAM rewrites. Evaluated on LeNet-5/MNIST and VGG-16/CIFAR-10 with area/energy analysis via NeuroSim, KD reduces the RSA parameter overhead needed from 10%->5% (CIFAR-10) and 7%->3% (MNIST), and the combined KD+RSA reaches 99.41%/91.86% accuracy with 15-150x speedup over R-V-W and 7.7% area overhead on CIFAR-10 (vs 12% for RSA alone).", "contributions": ["Knowledge-distillation-based variation-aware training (VAT) where a full-precision teacher guides a student model trained with injected RRAM nonidealities (quantization, SAFs, write variation)", "Random sparse adaptation (RSA): a postmapping online adaptation scheme using a small, randomly-wired on-chip SRAM trained in place of RRAM cells (masked from further writes) to recover inference accuracy without slow R-V-W", "Joint algorithm-design integration of KD (premapping) and RSA (postmapping) that cuts the on-chip memory overhead needed for accuracy recovery roughly in half versus RSA alone", "NeuroSim-based area/energy evaluation of the hybrid RRAM+SRAM architecture, quantifying overhead at the array/peripheral level", "Demonstration of 15-150x speedup over conventional read-verify-write accuracy recovery"], "claims": [{"claim": "Knowledge distillation improves robustness of the model under RRAM nonidealities over standalone variation-aware training", "support": "2.28% (MNIST: 95.15%->97.43%) and 4.53% (CIFAR-10: 82.6%->87.13%) inference accuracy improvement from teacher-realistic to student (KD) model", "loc": "Sec. V.A, Fig. 6"}, {"claim": "RSA alone achieves large speedup in accuracy recovery versus R-V-W but with area cost", "support": "RSA achieves a 10x improvement in time to reach baseline accuracy versus R-V-W using 10% of parameters on CIFAR-10/VGG-16", "loc": "Sec. V.B, Fig. 7"}, {"claim": "Combining KD with RSA reduces the fraction of parameters that must be moved to on-chip memory for full accuracy recovery", "support": "Parameter requirement for RSA drops from 10% to 5% (CIFAR-10) and from 7% to 3% (MNIST) when KD-pretrained models are used", "loc": "Sec. V.B, Fig. 8"}, {"claim": "KD+RSA achieves state-of-the-art inference accuracy with low area overhead and large speedup over R-V-W", "support": "99.41% (MNIST)/91.86% (CIFAR-10) accuracy with up to 5% parameter overhead, 10-150x speedup vs RSA-alone/R-V-W (abstract states 15-150x)", "loc": "Abstract, Sec. V.B, Table 4"}, {"claim": "KD reduces the SRAM area overhead needed for RSA", "support": "Area overhead for CIFAR-10 drops from 12% (RSA alone, 10% parameters) to 7.7% (KD+RSA, 5% parameters)", "loc": "Sec. VI (Conclusion), Fig. 10, Table 5"}], "results": ["Final accuracy with KD+RSA: 99.41% MNIST (LeNet-5), 91.86% CIFAR-10 (VGG-16) -- abstract numbers; body text reports 99.13%/91.86% in one instance", "4-bit weight quantization alone drops VGG-16/CIFAR-10 accuracy from 93.3% (FP32) to ~20%", "KD+RSA parameter overhead: 5% (CIFAR-10), 3% (MNIST), down from 10%/7% for RSA alone", "Speedup over R-V-W: 15-150x (abstract); RSA alone achieves ~10x speedup vs R-V-W on CIFAR-10", "Area overhead: 7.7% for KD+RSA (CIFAR-10, 5% SRAM) vs 12% for RSA alone (10% SRAM); 15% SRAM parameters leads to 26% total area increase", "Total energy overhead vs. main RRAM array: 32.27% (KD+RSA) vs 65.04% (RSA alone) on CIFAR-10/VGG-16"], "limitations": ["Evaluated only on relatively small/older networks (LeNet-5 on MNIST, VGG-16 on CIFAR-10); no modern large-scale architectures", "Write variation modeled with a single fixed sigma=0.1 lognormal model; authors note they plan to refine device statistical characterization in future work", "Does not explicitly model sneak-path currents or other peripheral-circuit noise during RSA adaptation, only folds effects into the final loss via the main+SRAM output sum", "Hardware costs (area, energy) are estimated via NeuroSim architectural modeling rather than measured silicon", "RSA requires hard-wired random connections between a chosen percentage of RRAM cells and SRAM, which adds design/routing complexity not fully characterized beyond area/energy"], "remarks": "This is a solid algorithm-architecture co-design contribution for recovering RRAM inference accuracy without the high latency cost of iterative read-verify-write, and it quantifies both accuracy and area/energy tradeoffs via NeuroSim, giving it more hardware credibility than a pure training paper. Because it still requires on-chip SRAM overhead (3-15% of parameters) and the benefit is only demonstrated on two relatively small benchmarks, it functions as a point in the design space between purely offline variation-aware training and expensive per-chip R-V-W; the direct NeuroSim-based comparison against DNN+NeuroSim's framework (a paper later popular for CIM benchmarking) is a useful anchor for readers mapping models onto crossbars with device variation.", "basis": "full-text", "pdf_source_url": "", "abstract": "Resistive random access memory (RRAM) is a promising technology for energy-efficient neuromorphic accelerators. However, when a pretrained deep neural network (DNN) model is programmed to an RRAM array for inference, the model suffers from accuracy degradation due to RRAM nonidealities, such as device variations, quantization error, and stuck-at-faults. Previous solutions involving multiple read-verify-write (R-V-W) to the RRAM cells require cell-by-cell compensation and, thus, an excessive amount of processing time. In this article, we propose a joint algorithm-design solution to mitigate the accuracy degradation. We first leverage knowledge distillation (KD), where the model is trained with the RRAM nonidealities to increase the robustness of the model under device variations. Furthermore, we propose random sparse adaptation (RSA), which integrates a small on-chip memory with the main RRAM array for postmapping adaptation. Only the on-chip memory is updated to recover the inference accuracy. The joint algorithm-design solution achieves the state-of-the-art accuracy of 99.41% for MNIST (LeNet-5) and 91.86% for CIFAR-10 (VGG-16) with up to 5% parameters as overhead while providing a 15-150× speedup compared with R-V-W.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2020_Charan_KDRSA_JXCDC.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2020_Charan_KDRSA_JXCDC.pdf", "priority": 5.99}, {"id": "W3013241373", "short": "Energy-Efficient Quant+Reg Training", "title": "An Energy-Efficient Quantized and Regularized Training Framework For Processing-In-Memory Accelerators", "authors": ["Hanbo Sun", "Zhenhua Zhu", "Yi Cai", "Xiaoming Chen", "Yu Wang", "Huazhong Yang"], "year": 2020, "venue": "", "venue_short": "ASP-DAC", "venue_full": "25th Asia and South Pacific Design Automation Conference (ASP-DAC 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/asp-dac47756.2020.9045192", "cites_global": 41, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "A training framework that non-uniformly quantizes activations and regularizes weights to cut ADC resolution by 2 bits and analog compute energy by 35%, yielding 3.4x energy-efficiency gains on PIM/RRAM accelerators with little accuracy loss.", "summary": "The paper targets the ADC energy bottleneck in RRAM-based processing-in-memory (PIM) CNN accelerators, where ADCs are reported to consume over 60% of system energy, and the fact that analog MVM energy depends on the actual data values computed. It proposes two training-time optimizations: (1) a PIM-aware non-uniform activation quantization scheme, combining a tighter [-|mu|-3sigma, |mu|+3sigma] quantization range, a high-precision (non-power-of-2) scale realized via an adjustable RRAM load resistor, and sigmoid-based non-uniform quantization implemented with non-linear ADCs plus MUXes; and (2) an energy-aware weight regularization term, derived from a TIA-based crossbar energy model, added to the training loss to bias weight/activation value distributions away from the highest-energy state (high voltage level on low-resistance state). Both are trained end-to-end with standard backprop (quantization operators made differentiable via STE). Evaluated on LeNet, VGG-8 and ResNet-18 on CIFAR-10 using a 256x256 RRAM crossbar PIM architecture with ADC/DAC energy numbers drawn from fabricated circuit papers. The combined framework reduces ADC resolution by 2 bits and analog computing energy by 35% while keeping accuracy close to baseline, and reports an overall 3.4x energy-efficiency improvement (9.02 TOPS/W) versus a prior low-bit-width CNN-on-RRAM baseline.", "contributions": ["PIM-based non-uniform (sigmoid-CDF) activation quantization scheme with optimized quantization range and a high-precision, non-power-of-2 scale implemented via adjustable RRAM load resistance", "An energy consumption model for crossbar MVM based on a TIA sensing model relating energy to input voltage level and cell conductance state", "An energy-aware weight regularization loss term that biases trained weight/activation distributions to reduce the fraction of high-energy (HVL-on-LRS) states by ~41%", "End-to-end differentiable training framework combining both optimizations, evaluated on LeNet/VGG-8/ResNet-18 on CIFAR-10"], "claims": [{"claim": "Non-uniform activation quantization reduces required ADC resolution by 1 bit versus uniform quantization without accuracy loss", "support": "Fig. 3: 4-bit non-uniform quantization average error (0.025) is between 4-bit uniform (0.035) and 5-bit uniform (0.017)", "loc": "Sec. IV.D, Fig. 3"}, {"claim": "The combined training framework reduces ADC resolution needs by 2 bits and analog computing energy by 35%", "support": "Abstract / Sec. VI.C", "loc": "Abstract, Sec. VI"}, {"claim": "Weight regularization reduces the proportion of the highest-energy state (HVL on LRS) and cuts crossbar computing energy", "support": "Fig. 4: HVL-on-LRS proportion drops (71.01%->67.68% in one panel; ~41% relative reduction cited), total crossbar energy reduced ~40% (39.2% in Fig. 4b)", "loc": "Sec. V.C, Fig. 4"}, {"claim": "Overall framework achieves 3.4x energy efficiency improvement with little accuracy loss vs. prior low bit-width CNN-on-RRAM work", "support": "9.02 TOPS/W equivalent efficiency, 2.6-4.2x vs. existing work; A4W4 accuracy 0.7467/0.9286/0.8655 on LeNet/VGG-8/ResNet-18 vs. float baselines 0.7448/0.9336/0.8887", "loc": "Sec. VI.B-C, Table I, Fig. 5"}, {"claim": "Under equal parameter precision, the proposed quantization improves classification accuracy by >10% over a baseline at low bit-width", "support": ">10% accuracy improvement at same precision (e.g., VGG-8 A4W4: 0.9286 proposed vs. 0.1887 baseline [7]-style A4W4)", "loc": "Sec. VI.B, Table I"}], "results": ["ADC resolution reduced by 2 bits; analog computing energy reduced by 35% (abstract)", "Overall energy efficiency improved 3.4x; equivalent efficiency 9.02 TOPS/W, 2.6-4.2x versus prior work", "Non-uniform quantization scheme alone reduces ~65% of system energy consumption (Fig. 5), mainly via 70% ADC energy reduction (4-bit ADC power is 54.68% of 8-bit ADC power)", "Weight regularization reduces crossbar computing energy by ~35-40% (accounts for ~3% of total system energy)", "ResNet-18/CIFAR-10 accuracy at A4W4: 0.8655 (proposed) vs. 0.8887 float baseline and 0.7412 for a plain A4W4 baseline"], "limitations": ["Evaluated only on CIFAR-10 with relatively small/older CNNs (LeNet, VGG-8, ResNet-18); no ImageNet-scale or modern architectures", "Energy model is analytical (TIA-based) combined with simulation; no silicon measurement or full non-ideality (IR drop, device variation, stuck-at-fault) modeling", "ADC/DAC energy numbers are stitched together from separate fabricated-circuit papers rather than a single consistent chip design", "Non-linear ADC and MUX circuit overhead is estimated (~3% extra) rather than measured from an actual layout"], "remarks": "This is a software/training-side optimization paper rather than a hardware or full-system contribution: its energy savings hinge on an analytical TIA energy model and ADC power numbers imported from separate papers, so the headline 3.4x figure should be read as a training-framework-level estimate rather than a validated chip result. It is a useful illustration of co-designing quantization-aware training with the specific analog energy characteristics of RRAM crossbars (value-dependent energy, non-power-of-two scales), complementing architecture papers like ISAAC/PRIME that it builds directly on and compares against.", "basis": "full-text", "pdf_source_url": "", "abstract": "Convolutional Neural Networks (CNNs) have made breakthroughs in various fields, while the energy consumption becomes enormous. Processing-In-Memory (PIM) architectures based on emerging non-volatile memory (e.g., Resistive Random Access Memory, RRAM) have demonstrated great potential in improving the energy efficiency of CNN computing. However, there is still much room for improvement in the energy efficiency of existing PIM architectures. On the one hand, current work shows that high resolution Analog-to-Digital Converters (ADCs) are required for maintaining computing accuracy, but they dominate more than 60% energy consumption of the entire system, damaging the energy efficiency benefits of PIM. On the other hand, the characteristic of computing in the analog domain in PIM accelerators leads to the computing energy consumption is influenced by the specific input and weight values. However, as far as we know, there is no energy efficiency optimization method based on this characteristic in existing work. To solve these problems, in this paper, we propose an energy-efficient quantized and regularized training framework for PIM accelerators, which consists of a PIM-based non-uniform activation quantization scheme and an energy-aware weight regularization method. The proposed framework can improve the energy efficiency of PIM architectures by reducing the ADC resolution requirements and training low energy consumption CNN models for PIM, with little accuracy loss. The experimental results show that the proposed training framework can reduce the resolution of ADCs by 2 bits and the computing energy consumption in the analog domain by 35%. The energy efficiency, therefore, can be enhanced by $3.4 \\times$ in our proposed training framework.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2020_Sun_EnergyEfficientQuantReg_ASPDAC.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2020_Sun_EnergyEfficientQuantReg_ASPDAC.pdf", "priority": 5.94}, {"id": "W3020429010", "short": "ITT-RNA", "title": "ITT-RNA: Imperfection Tolerable Training for RRAM-Crossbar-Based Deep Neural-Network Accelerator", "authors": ["Zhuoran Song", "Yanan Sun", "Lerong Chen", "Tianjian Li", "Naifeng Jing", "Xiaoyao Liang", "Li Jiang"], "year": 2020, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (TCAD), 2020", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2020.2989373", "cites_global": 32, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["MLP", "CNN"], "evidence": "algorithm+simulation", "tldr": "ITT-RNA combines an accelerator-friendly off-device training method (exploiting NN self-healing to avoid mapping large weights onto imperfect memristors) with a software-hardware co-design on-device fine-tuning step to keep CNN/MLP accuracy loss under 1.1% despite RRAM-crossbar defects and up to 20% stuck-at-fault rates.", "summary": "The paper targets accuracy loss in RRAM-crossbar DNN accelerators caused by fabrication imperfections -- device defects and process variations, including stuck-at-faults (SAFs) -- which both reduce manufacturing yield and degrade inference accuracy. The authors first propose an 'accelerator-friendly' off-device (pure software) training method that leverages the neural network's inherent self-healing capability to steer large-magnitude weights away from imperfect memristor cells, with a dynamic adjustment mechanism to handle error accumulation/magnification across layers in deeper MLPs. Since this software-only approach is insufficient for CNNs, they add a software-hardware co-design step that permits a small number of on-device retraining iterations directly on the RRAM crossbar to recover accuracy while limiting the number of (endurance-damaging) write operations, as an alternative to fully hardware-based on-device training. Based on the abstract, the reported results show the combined method keeps accuracy loss under 1.1% for resistance variations on both MLPs and CNNs, and under 1% even at a 20% stuck-at-fault rate.", "contributions": ["An accelerator-friendly, off-device (pure software) training method that uses the neural network's self-healing property to avoid mapping large-magnitude weights onto defective/imperfect memristor cells", "A dynamic adjustment mechanism extending this training approach to deeper MLPs where imperfect-memristor-induced errors accumulate and magnify across layers", "A software-hardware co-design methodology enabling CNNs to preserve accuracy with only a few on-device training (retraining) iterations on the RRAM crossbar, reducing the write-endurance cost versus fully hardware-based on-device training"], "claims": [{"claim": "The proposed off-device, self-healing-based training method mitigates accuracy loss from RRAM resistance variation and defects for MLPs and CNNs", "support": "Reported accuracy loss <=1.1% for resistance variations in both MLP and CNN (abstract)", "loc": "Abstract"}, {"claim": "The software-hardware co-design method remains robust even at high stuck-at-fault rates", "support": "Reported accuracy loss <=1% even at SAF rate = 20% (abstract)", "loc": "Abstract"}, {"claim": "A pure off-device/software training solution is insufficient for CNNs, motivating the need for limited on-device retraining", "support": "Stated directly: 'it is unable to provide enough accuracy for convolutional neural networks (CNNs)' (abstract)", "loc": "Abstract"}], "results": ["<=1.1% accuracy loss under resistance variation for both MLP and CNN (per abstract)", "<=1% accuracy loss even with 20% stuck-at-fault rate (per abstract)"], "limitations": ["Only the abstract was available for this analysis (full text not accessible from this machine; IEEE Xplore is not downloadable here), so method details (datasets, network sizes, exact SAF/variation models, number of on-device iterations) could not be verified beyond what the abstract states", "The on-device co-design step still requires some RRAM write operations for retraining, which the paper itself identifies as an endurance concern it only partially mitigates"], "remarks": "Based on the abstract, this is a hardware-aware training / fault-tolerance contribution combining offline self-healing-guided weight placement with limited on-device fine-tuning, addressing both device variation and stuck-at-faults -- a combination that is more complete than the typical variation-only (VAT) or SAF-only compensation. Because the full text could not be obtained from this environment, the specific network sizes, variation models, and the quantitative comparison against prior work could not be independently verified; this assessment should be read as abstract-derived and treated with appropriate caution for a thesis-level literature review.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Deep neural networks (DNNs) have gained a strong momentum among various applications. The enormous matrix-multiplication exhibited in the above DNNs is computation and memory intensive. Resistive random-access memory crossbar (RRAM-crossbar) consisting of memristor cells can naturally carry out the matrix-vector multiplication. RRAM-crossbar-based accelerator, therefore, has two orders of magnitude of higher energy-efficiency than conventional accelerators. The imperfect fabrication process of RRAM-crossbars, however, causes various defects and process variations. These fabrication imperfections not only result in significant yield loss but also degrade the accuracy of DNNs executed on the RRAM-crossbars. In this article, we first propose an accelerator-friendly neural-network training method, by leveraging the inherent self-healing capability of the neural network, to prevent the large-weight synapses from being mapped to the imperfect memristors. Next, we propose a dynamic adjustment mechanism to extend the above method for DNNs, such as multilayer perceptrons (MLPs), wherein the imperfect-memristor induced errors can accumulate and magnify through multiple layers. Such off-device training method is a pure software solution, and it is unable to provide enough accuracy for convolutional neural networks (CNNs). Several works propose error-tolerable hardware design by allowing the retraining of CNNs on the RRAM-crossbar. Although this hardware-based on-device training method is effective, the frequent write operation on RRAM-crossbar hurt the endurance of RRAM-crossbars. Consequently, we propose a software and hardware co-design methodology to effectively preserve the classification accuracy of CNN with few on-device training iterations. The experimental results show that the proposed method can guarantee ≤1.1% loss of accuracy for resistance variations in MLP and CNN. Moreover, the proposed method can guarantee ≤1% loss of accuracy even when stuck-at-faults (SAFs) rate = 20%.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2020_Song_ITTRNA_TCAD.pdf", "analysed": true, "pdf": null, "priority": 6.16}, {"id": "W2946522000", "short": "NIA / PytorX", "title": "Noise Injection Adaption", "authors": ["Zhezhi He", "Jie Lin", "Rickard Ewetz", "Jiann Shiun Yuan", "Deliang Fan"], "year": 2019, "venue": "", "venue_short": "DAC", "venue_full": "56th ACM/IEEE Design Automation Conference (DAC 2019); full title: \"Noise Injection Adaption: End-to-End ReRAM Crossbar Non-ideal Effect Adaption for Neural Network Mapping\"", "venue_ok": true, "doi": "https://doi.org/10.1145/3316781.3317870", "cites_global": 150, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Introduces PytorX, a PyTorch-based end-to-end training/mapping/evaluation framework modeling ReRAM crossbar non-idealities (stuck-at-fault, IR-drop, thermal/shot/random-telegraph noise), a digital stuck-at-fault correction algorithm, and a Noise Injection Adaption (NIA) training method that regularizes DNNs against IR-drop-induced current shift so they map to crossbars without per-chip retraining.", "summary": "The paper studies how multiple ReRAM crossbar non-idealities -- stuck-at-fault (SAF), IR-drop, thermal noise, shot noise, and random telegraph noise -- degrade DNN accuracy when a trained network is mapped onto a crossbar-based dot-product engine. To study this jointly, the authors build PytorX, an end-to-end PyTorch-based framework for training, mapping and evaluating crossbar-based neural network accelerators that models all these non-idealities together; they report that directly mapping large, deep/wide DNNs into crossbars without accounting for these effects can cause complete system failure (accuracy collapsing to random guessing). To counter SAF, they propose a digital, one-time-profiling error-correction algorithm that largely eliminates its accuracy impact. To counter IR-drop, they propose Noise Injection Adaption (NIA): injecting stochastic noise during training that statistically matches the IR-drop-induced current shift in each crossbar, which is a one-time training procedure (no retraining per physical crossbar instance) that regularizes the network to be intrinsically robust. Other effects (thermal/shot/RTN-type noise) are addressed by tuning the system operating frequency. Experiments on multiple DNNs for image recognition show the combined methodology recovers accuracy that would otherwise collapse under these non-idealities.", "contributions": ["PytorX: an end-to-end PyTorch-based framework for training, mapping and evaluating crossbar-based DNN accelerators that jointly models SAF, IR-drop, thermal noise, shot noise and random telegraph noise", "Empirical demonstration that naively mapping deep/wide DNNs to ReRAM crossbars without non-ideality awareness can collapse accuracy to random-guess level", "A digital stuck-at-fault (SAF) error-correction algorithm requiring only one-time profiling with negligible accuracy loss", "Noise Injection Adaption (NIA): a one-time (no per-crossbar retraining) noise-injection training method that statistically models IR-drop-induced current shift as training-time stochastic noise to regularize the network"], "claims": [{"claim": "Non-ideality-unaware mapping of large DNNs onto ReRAM crossbars can cause complete functional failure.", "support": "Directly mapping trained large-scale DNNs without considering SAF/IR-drop/noise effects leads to accuracy equal to random guess as networks get deeper/wider (per abstract).", "loc": "Abstract"}, {"claim": "The proposed SAF correction algorithm removes most of the SAF-induced accuracy loss with a one-time profiling cost.", "support": "Digital SAF error correction compensates crossbar output errors with 'almost no system accuracy degradation' after one-time profiling (per abstract).", "loc": "Abstract"}, {"claim": "NIA makes a single trained model robust to IR-drop across crossbars without per-device retraining.", "support": "NIA is described as a one-time training method without the need for retraining for every specific crossbar (per abstract).", "loc": "Abstract"}], "results": ["Qualitative result: unmitigated non-idealities drive deep/wide DNNs to random-guess accuracy on crossbar mapping (no single numeric figure given in abstract)", "SAF correction: 'almost no system accuracy degradation' after one-time profiling (abstract; no exact percentage given)", "Evaluations across 'various DNNs' for image recognition reported to show efficacy of NIA (abstract; per-model numbers not available without full text)"], "limitations": ["Analysis based on the abstract only -- the only open-access copy found was behind ACM Digital Library, which this task's instructions exclude as a download source, so method details and exact quantitative tables could not be verified", "The abstract itself does not give precise per-model/per-fault-rate accuracy numbers, limiting how falsifiable the claims above can be stated"], "remarks": "This is the DAC 2019 paper behind the well-known open-source PytorX framework (used/cited widely in later ReRAM non-ideality literature), and the in-set cited-by list in this collection (IR-QNN, BRoCoM, MNSIM 2.0, Noise-Resilient DNN, etc.) confirms it had substantial downstream influence on hardware-aware/noise-aware training and non-ideality simulation work. Because full text could not be legitimately obtained (ACM DL only), the specific quantitative accuracy-recovery numbers and the precise SAF/IR-drop noise models could not be checked here; a thesis treatment should pull the published DAC version or the PytorX GitHub repo (github.com/ASU-ESIC-FAN-Lab/pytorx) for implementation and number verification.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "In this work, we investigate various non-ideal effects (Stuck-At-Fault (SAF), IR-drop, thermal noise, shot noise, and random telegraph noise)of ReRAM crossbar when employing it as a dot-product engine for deep neural network (DNN) acceleration. In order to examine the impacts of those non-ideal effects, we first develop a comprehensive framework called PytorX based on main-stream DNN pytorch framework. PytorX could perform end-to-end training, mapping, and evaluation for crossbar-based neural network accelerator, considering all above discussed non-ideal effects of ReRAM crossbar together. Experiments based on PytorX show that directly mapping the trained large scale DNN into crossbar without considering these non-ideal effects could lead to a complete system malfunction (i.e., equal to random guess) when the neural network goes deeper and wider. In particular, to address SAF side effects, we propose a digital SAF error correction algorithm to compensate for crossbar output errors, which only needs one-time profiling to achieve almost no system accuracy degradation. Then, to overcome IR drop effects, we propose a Noise Injection Adaption (NIA) methodology by incorporating statistics of current shift caused by IR drop in each crossbar as stochastic noise to DNN training algorithm, which could efficiently regularize DNN model to make it intrinsically adaptive to non-ideal ReRAM crossbar. It is a one-time training method without the request of retraining for every specific crossbar. Optimizing system operating frequency could easily take care of rest non-ideal effects. Various experiments on different DNNs using image recognition application are conducted to show the efficacy of our proposed methodology.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2019_He_NoiseInjectionAdaption_DAC.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2019_He_NoiseInjectionAdaption_DAC.pdf", "priority": 8.6}, {"id": "W2605257365", "short": "I-V Nonlinearity Aware DNN", "title": "Deep Neural Network Optimized to Resistive Memory with Nonlinear Current-Voltage Characteristics", "authors": ["Hyungjun Kim", "Taesu Kim", "Jin-Seok Kim", "Jae‐Joon Kim"], "year": 2018, "venue": "ACM Journal on Emerging Technologies in Computing Systems", "venue_short": "JETC", "venue_full": "ACM Journal on Emerging Technologies in Computing Systems (JETC), 2018", "venue_ok": true, "doi": "https://doi.org/10.1145/3145478", "cites_global": 38, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "Instead of mapping a conventional neural network onto a nonlinear-I-V RRAM crossbar, the authors replace the perceptron's weighted-sum transfer function with the device's own nonlinear I-V model (e.g. sinh) and train the resulting network directly, nearly eliminating the accuracy loss that nonlinearity otherwise causes.", "summary": "Nonlinear I-V characteristics, often introduced deliberately in RRAM cells to mitigate sneak-path currents, distort the linear vector-matrix multiplication that crossbar-based accelerators rely on, and the paper first shows via simulation that this nonlinearity causes large inference-accuracy loss when weights are naively linearly mapped to conductance (e.g. 9.05% accuracy, versus 97.43% ideal, for a deep 784-2500-2000-1500-1000-500-10 MNIST MLP at k=7.5 nonlinearity). The authors trace the cause to mid-range neuron activation values, which are more exposed to I-V nonlinearity error, and show deeper networks and CIFAR-10-like inputs are more vulnerable because they produce more mid-range activations. Rather than tuning hardware parameters or restricting the read-voltage range (prior approaches), they redefine the perceptron's transfer function to be the device's own empirical nonlinear I-V model (e.g., I=G*sinh(BV), with positive/negative sub-weight decomposition using two crossbar columns), derive the corresponding backpropagation gradients, and train networks end-to-end against this nonlinear transfer function. Evaluated on MNIST (shallow and deep MLP) and CIFAR-10 (shallow MLP) with two different empirical RRAM I-V models, the proposed networks retain accuracy close to the ideal linear baseline across a wide range of nonlinearity k, unlike naively mapped networks whose accuracy collapses as k grows.", "contributions": ["Quantifies and explains why nonlinear RRAM I-V characteristics cause large neural-network inference-accuracy loss under naive linear-to-conductance weight mapping, tying the error to mid-range activation values", "Shows depth and input-data distribution (e.g., CIFAR-10 vs MNIST) increase vulnerability to I-V-nonlinearity-induced error", "Proposes replacing the perceptron's linear weighted-sum transfer function with the device's own nonlinear I-V model so training/inference directly account for nonlinearity, using a positive/negative sub-weight (two-column) decomposition", "Derives the backpropagation gradient equations for training with a nonlinear (sinh-based and a more complex exponential) transfer function", "Demonstrates the method generalizes to a second, more complex empirical I-V model, and evaluates across a range of nonlinearity degrees k"], "claims": [{"claim": "Naive linear weight-to-conductance mapping onto nonlinear-I-V RRAM devices causes severe accuracy loss that grows with both device nonlinearity k and network depth", "support": "Deep MNIST MLP accuracy drops from 97.43% (ideal) to 9.05% (naive mapping) at k=7.5, while shallow MNIST only drops to 87.90%", "loc": "Table 1 / Section 5.1"}, {"claim": "Accuracy degradation is driven by mid-range neuron activation values, which are most exposed to the current gap between nonlinear and linear I-V curves", "support": "Synthetic input-distribution experiment (data A concentrated near 0/1 vs. data B concentrated near 0.5) shows large output error only for data B (Fig. 5)", "loc": "Section 3 / Fig. 5-6"}, {"claim": "Training the network against the device's actual nonlinear I-V transfer function (rather than compensating hardware parameters) restores accuracy close to the ideal baseline across a wide range of nonlinearity k", "support": "Proposed network: 96.74% (shallow MNIST), 96.91% (deep MNIST), 52.09% (shallow CIFAR-10) at k=7.5, versus ideal 94.8%/97.43%/54.97%, and roughly flat accuracy vs. k in Fig. 8 (unlike naive mapping)", "loc": "Table 1 / Fig. 8 / Section 5"}, {"claim": "The proposed transfer-function-substitution method generalizes beyond the simple sinh I-V model to more complex empirical device models", "support": "Repeated evaluation with a second, more complex exponential I-V model (Eq. 23, device from [26]) yields similarly recovered accuracy (Fig. 9b)", "loc": "Section 6 / Fig. 9"}], "results": ["Deep MNIST MLP (784-2500-2000-1500-1000-500-10): ideal 97.43% vs naive-mapped 9.05% vs proposed-network 96.91% at device nonlinearity k=7.5", "Shallow MNIST MLP (784-500-250-10): ideal 94.8% vs naive-mapped 87.90% vs proposed-network 96.74% at k=7.5", "Shallow CIFAR-10 MLP (2352-4000-1000-4000-10): ideal 54.97% vs naive-mapped 41.94% vs proposed-network 52.09% at k=7.5", "Proposed network accuracy stays roughly flat across a wide sweep of nonlinearity k, while naive-mapped network accuracy degrades sharply as k increases (Fig. 8)", "Method validated on a second, more complex empirical nonlinear I-V model with similar accuracy recovery (Fig. 9b)"], "limitations": ["Pure simulation study using empirical/fitted I-V device models, not measured chip-level hardware", "Only MLP architectures evaluated (CNN/RNN explicitly left for future work)", "Other non-idealities (IR drop, device variability/noise, ADC/DAC quantization) are not modeled", "CIFAR-10 accuracy is low overall (~50%) because an MLP (not a CNN) is used, limiting how informative that benchmark is", "Requires re-deriving backpropagation gradients per device I-V model, and the transfer function must be differentiable, limiting generality to arbitrary devices"], "remarks": "This is a clean, early example of the hardware-aware-training idea applied specifically to device I-V nonlinearity rather than conductance noise or drift: instead of trying to force the device to behave linearly (restricting read voltage, selector/linearization tricks), it bakes the device's true nonlinear transfer characteristic into the forward/backward pass. The core idea -- training the model against the real analog hardware's actual input-output relationship -- prefigures much of the later hardware-aware-training literature for PCM/ReRAM crossbars (including IR-drop-aware training, which the paper itself flags as the obvious next non-ideality to address and which one of its citing works, IR-QNN, follows up on). Evidence is simulation/algorithmic only on MLPs and MNIST/CIFAR-10, so the claims about accuracy recovery need confirmation on measured hardware and on networks of practical depth/architecture (CNNs) before being taken as broadly solved.", "basis": "full-text", "pdf_source_url": "", "abstract": "Artificial Neural Network computation relies on intensive vector-matrix multiplications. Recently, the emerging nonvolatile memory (NVM) crossbar array showed a feasibility of implementing such operations with high energy efficiency. Thus, there have been many works on efficiently utilizing emerging NVM crossbar arrays as analog vector-matrix multipliers. However, nonlinear I-V characteristics of NVM restrain critical design parameters, such as the read voltage and weight range, resulting in substantial accuracy loss. In this article, instead of optimizing hardware parameters to a given neural network, we propose a methodology of reconstructing the neural network itself to be optimized to resistive memory crossbar arrays. To verify the validity of the proposed method, we simulated various neural networks with MNIST and CIFAR-10 dataset using two different Resistive Random Access Memory models. Simulation results show that our proposed neural network produces inference accuracies significantly higher than conventional neural network when the network is mapped to synapse devices with nonlinear I-V characteristics.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2018_Kim_NonlinearIVAwareDNN_JETC.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2018_Kim_NonlinearIVAwareDNN_JETC.pdf", "priority": 5.54}, {"id": "W2612375349", "short": "Accelerator-friendly Training", "title": "Accelerator-friendly neural-network training: Learning variations and defects in RRAM crossbar", "authors": ["Lerong Chen", "Jiawen Li", "Yiran Chen", "Qiuping Deng", "Jiyuan Shen", "Xiaoyao Liang", "Li Jiang"], "year": 2017, "venue": "", "venue_short": "DATE", "venue_full": "2017 Design, Automation and Test in Europe (DATE)", "venue_ok": true, "doi": "https://doi.org/10.23919/date.2017.7926952", "cites_global": 246, "cat": "07", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "Proposes an off-device, bipartite-matching-based weight-to-memristor mapping plus a retraining step that exploits neural-network self-healing to tolerate RRAM crossbar resistance variation and stuck-at faults, keeping accuracy loss under 1% versus 10-45% loss in prior work.", "summary": "RRAM crossbars suffer from device-to-device resistance variation and stuck-at-zero/stuck-at-one faults, which can severely degrade the classification accuracy of neural networks mapped onto them. The paper proposes a two-stage, accelerator-friendly training method: first, a weighted bipartite-matching algorithm (\"bi-match\") assigns weights to memristor cells so that large-magnitude weights avoid the most abnormal (high-variation or faulty) devices; second, an iterative retraining step (\"bi-retrain\") progressively shrinks weights mapped to the worst-variation memristors by a fixed exponential factor and lets the network's own self-healing/retraining recover the lost information, reducing multiple independent weights per iteration to keep training time tractable. Evaluated with Monte Carlo simulation of a two-layer MLP (784x10 differential RRAM crossbars) on MNIST, comparing against an ideal baseline, an unmapped baseline, and the prior VAT/Vortex variation-aware training method. The bi-retrain method gets close to the ideal accuracy even under the largest variation levels tested and also benefits from adding redundant crossbar rows.", "contributions": ["A weighted bipartite-matching algorithm to find a variation/fault-aware mapping between neural-network weights and crossbar memristor cells, minimizing a summed-weighted-variation (SWV) metric", "An off-device retraining procedure that exponentially shrinks weights assigned to high-variation/faulty memristors and lets the rest of the network compensate, instead of zeroing weights as in magnitude-pruning-style compression", "A batched weight-reduction strategy that reduces/fixes multiple spatially-independent weights per training iteration to cut the number of retraining iterations needed", "Evaluation of the method jointly under resistance variation and clustered stuck-at faults, plus study of combining it with redundant crossbar rows"], "claims": [{"claim": "The proposed bi-retrain method keeps classification accuracy loss to <=1% versus an ideal (no-variation) baseline, where prior work loses 10-45%", "support": "stated improvement using the comparison figures in the abstract and Sec. V-B results (e.g. <5% loss vs ideal under the largest variation set in [Vortex], vs 45% loss for Vortex)", "loc": "Abstract; Sec. V-B"}, {"claim": "Under only resistance variation (sigma=2), bi-retrain raises the test rate from 61.8% (bi-match alone) to 86.0%", "support": "61.8% -> 86.0%, Fig. 4(a)", "loc": "Sec. V-B, Fig. 4(a)"}, {"claim": "Under combined resistance variation and stuck-at faults, bi-match alone only reaches 55.87% average test rate while bi-retrain reaches 89.27% (sigma=0.5) and 71.02% (sigma=2)", "support": "55.87% vs 89.27%/71.02%, Fig. 4(b)", "loc": "Sec. V-B, Fig. 4(b)"}, {"claim": "Batching the reduction of multiple (N) independent weights per training iteration drastically cuts the number of iterations needed with only a small accuracy drop", "support": "Table I: N=1 needs 2000 iterations for 89.7% test rate, N=20 needs only 205 iterations for 89.3%", "loc": "Sec. V-B, Table I"}, {"claim": "bi-retrain combined with 20 redundant rows keeps the test rate above 85% under large resistance variation, with diminishing returns beyond ~40 redundant rows", "support": "test rate >85% at 20 redundant rows; no further gains beyond 40 rows", "loc": "Sec. V-B, Fig. 4(d)"}], "results": ["Test rate 86.0% (bi-retrain) vs 61.8% (bi-match only) under resistance variation sigma=2 (no SAFs)", "Test rate 89.27% (sigma=0.5) and 71.02% (sigma=2) with bi-retrain under combined variation+SAFs, vs 55.87% average for bi-match alone", "Training iterations reduced from 2000 (N=1 weight/iteration) to 205 (N=20 weights/iteration) with test rate only dropping from 89.7% to 89.3%", "Baseline (ideal, no variation) MNIST accuracy of the 2-layer network is ~90%, used as the upper bound for all comparisons"], "limitations": ["Evaluated only on a small two-layer MLP (784x10 crossbar) on MNIST; no CNNs or deeper networks", "Off-device training approach assumes the fault/variation map of the specific target crossbar is known in advance before training", "Variation and fault models are statistical/synthetic (lognormal resistance variation, fixed SA0/SA1 rates) rather than measured from a fabricated chip", "No evaluation of circuit-level effects such as IR drop or sneak-path currents, which are treated as separate, previously-solved problems", "No comparison against later, more scalable variation-aware training methods (the paper itself notes future work on deeper networks)"], "remarks": "This is an early (2017) and influential example of device-variation-aware, chip-specific offline retraining for crossbar accelerators, directly building on and outperforming the prior VAT/Vortex method; it is widely cited by later hardware-aware training and fault-tolerant-mapping papers (e.g., ITT-RNA, NEAT, BRoCoM) as a baseline for comparison. Its evidence is purely from small-network Monte Carlo simulation, so the headline <1% loss claim should be read as an upper bound achievable on a toy MLP/MNIST setup rather than a guarantee for larger, more realistic DNNs; the approach's practical cost (per-chip retraining given a measured fault map) is a key limitation for scaling to production accelerators.", "basis": "full-text", "pdf_source_url": "", "abstract": "RRAM crossbar consisting of memristor devices can naturally carry out the matrix-vector multiplication; it thereby has gained a great momentum as a highly energy-efficient accelerator for neuromorphic computing. The resistance variations and stuck-at faults in the memristor devices, however, dramatically degrade not only the chip yield, but also the classification accuracy of the neural-networks running on the RRAM crossbar. Existing hardware-based solutions cause enormous overhead and power consumption, while software-based solutions are less efficient in tolerating stuck-at faults and large variations. In this paper, we propose an accelerator-friendly neural-network training method, by leveraging the inherent self-healing capability of the neural-network, to prevent the large-weight synapses from being mapped to the abnormal memristors based on the fault/variation distribution in the RRAM crossbar. Experimental results show the proposed method can pull the classification accuracy (10%-45% loss in previous works) up close to ideal level with ≤ 1% loss.", "review": [], "pdf_expected": "07_Hardware_Aware_Training_and_Robustness/2017_Chen_AcceleratorFriendlyTraining_DATE.pdf", "analysed": true, "pdf": "07_Hardware_Aware_Training_and_Robustness/2017_Chen_AcceleratorFriendlyTraining_DATE.pdf", "priority": 9.18}, {"id": "W4414008085", "short": "ASiM", "title": "ASiM: Modeling and Analyzing Inference Accuracy of SRAM-Based Analog CiM Circuits", "authors": ["Wenlun Zhang", "Shimpei Ando", "Yung-Chin Chen", "Kentaro Yoshioka"], "year": 2025, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2025.3605286", "cites_global": 12, "cat": "08", "seed": false, "devices": ["SRAM-analog"], "models": ["CNN", "ResNet", "Transformer", "ViT"], "evidence": "algorithm+simulation", "tldr": "ASiM is an open-source, PyTorch-integrated simulation framework that models ADC quantization, bit-parallel encoding and analog noise in SRAM-based analog CiM, validated against a prototype chip, and used to show that even 1 LSB of ADC noise severely degrades accuracy on complex tasks like ImageNet/ViT.", "summary": "The paper addresses the lack of a standardized, circuit-aware simulator for SRAM-based analog compute-in-memory (ACiM), noting that existing tools give inconsistent accuracy predictions. ASiM models charge-domain-specific effects (ADC quantization using full dynamic range rather than Min-Max, bit-parallel encoding, and analog noise) and plugs into PyTorch to evaluate CNNs and Transformers (ResNet-18, ViT-B-32) on CIFAR-10 and ImageNet. The authors validate ASiM's accuracy predictions against silicon measurements from their own CR-CIM prototype chip (91.84% predicted vs 91.70% measured for ResNet-18), then use the framework to study how ADC precision, noise level and bit-parallel encoding factor into inference accuracy. Key findings: bit-parallel encoding improves energy efficiency with only modest accuracy loss, but as little as 1 LSB of analog noise (and especially MSB-cycle errors) can collapse accuracy on harder tasks/models (ImageNet, ViT) while being far more tolerable for simpler CNN/CIFAR-10 cases. To recover accuracy without giving up energy savings, the authors propose and evaluate hybrid analog-digital CiM (HCiM) and majority-voting/oversampling of MSB cycles, showing large accuracy recovery (e.g., 72.74%->90.55% on a 6-bit CR-CIM configuration) at a favorable energy-efficiency trade-off.", "contributions": ["Proposes ASiM, an open-source, PyTorch-pluggable simulation framework specifically for SRAM-based ACiM, modeling ADC quantization (full dynamic range, not Min-Max), bit-parallel encoding, and analog noise with charge-domain fidelity", "Validates ASiM's inference-accuracy predictions against measured silicon results from a prototype CR-CIM chip (91.84% predicted vs 91.70% measured ResNet-18 accuracy), including matching the ADC-precision inflection point", "Shows that bit-parallel encoding improves energy efficiency with modest accuracy cost, but even 1 LSB of analog noise (especially in MSB cycles) severely degrades accuracy, more so for ImageNet/ViT than CIFAR-10/CNN", "Proposes and evaluates two mitigation strategies -- hybrid analog-digital CiM (HCiM) and MSB-cycle oversampling with majority voting -- that recover accuracy with limited loss of energy-efficiency gains", "Benchmarks several state-of-the-art ACiM chip designs (BPBS, Sparsity-Adaptive, E2E Analog, Diff.-SC, CR-CIM, Hybrid) on a common accuracy-vs-efficiency-vs-area plane using ASiM"], "claims": [{"claim": "ASiM accurately predicts real-chip inference accuracy from circuit-level parameters", "support": "ASiM predicted 91.84% ResNet-18 accuracy vs 91.70% measured on the CR-CIM prototype chip; predicted ADC-precision inflection point matched silicon measurements", "loc": "Sec. Silicon Validation"}, {"claim": "Analog noise as small as 1 LSB can severely degrade inference accuracy, particularly for complex tasks", "support": "On ResNet-18/ImageNet with bit-serial encoding, accuracy drops from 65.51% to 16.26% at Enc=4, ADC precision 8; ImageNet is far more sensitive than CIFAR-10 to the same noise/precision settings", "loc": "Sec. V, Table/Fig. (ResNet-18 & ViT-B-32 CIFAR-10/ImageNet sweep)"}, {"claim": "Majority voting / oversampling of MSB cycles recovers accuracy lost to reduced ADC precision with a net energy-efficiency gain", "support": "3x oversampling with majority voting (boundary level 3) recovers 6-bit CR-CIM accuracy from 72.74% to 90.55% while still achieving 65% energy-efficiency improvement over the 8-bit configuration", "loc": "Sec. VI / Fig. 14"}, {"claim": "Hybrid analog-digital CiM (HCiM) can substantially improve efficiency with negligible accuracy loss", "support": "The HCiM architecture achieves ~2x energy efficiency improvement and reduced area versus standard digital CiM (DCiM) with negligible accuracy loss", "loc": "Sec. VI / Fig. 15, Table III"}], "results": ["ResNet-18/CIFAR-10 baseline 92.08%, ResNet-18/ImageNet baseline 65.49%, ViT-B-32/CIFAR-10 baseline 95.26%, ViT-B-32/ImageNet baseline 68.17% (floating-point references)", "ResNet-18/ImageNet, bit-serial, ADC precision 8: accuracy falls from 65.51% (Enc=2) to 16.26% (Enc=4) due to 1-LSB-scale analog noise effects", "Silicon validation: ASiM-predicted 91.84% vs CR-CIM measured 91.70% ResNet-18 accuracy (8b/8b)", "6-bit CR-CIM with 3x majority-voting oversampling: accuracy recovers from 72.74% to 90.55%, with 65% energy-efficiency improvement vs the 8-bit configuration", "HCiM: ~2x energy-efficiency improvement and reduced area vs standard DCiM with negligible accuracy loss"], "limitations": ["Simulation-based study for most results; only the ResNet-18/CR-CIM comparison point is cross-checked against actual silicon", "Noise models (random noise, nonlinearity) are simplified decompositions of measured LSBrms and may not capture all real-device non-idealities", "Evaluated primarily on ResNet-18 and ViT-B-32 on CIFAR-10/ImageNet; generalization to larger LLM-scale Transformers is not directly tested", "Benefits of HCiM and majority voting come with added circuit complexity (extra digital arrays, oversampling cycles) that trade off against the latency/area gains"], "remarks": "This is a careful, silicon-validated simulation tool paper rather than a new accelerator, and the silicon cross-check (91.84% vs 91.70%) gives real credibility to its noise-modeling choices (full-dynamic-range ADC quantization vs the optimistic Min-Max assumption used in NeuroSim-style tools). For a thesis on mapping models to analog crossbars, the key takeaway is methodological: existing CiM simulators can disagree substantially because of how they model ADC quantization and noise, and MSB-cycle errors dominate accuracy loss in bit-parallel/bit-serial ACiM -- motivating mitigation like HCiM or majority voting rather than blanket ADC precision reduction. The tool is open-sourced (GitHub) which should let later work reproduce and extend its noise/ADC models.", "basis": "full-text", "pdf_source_url": "", "abstract": "Static random-access memory (SRAM)-based analog compute-in-memory (ACiM) demonstrates promising energy efficiency for deep neural network (DNN) processing. Nevertheless, efforts to optimize efficiency frequently compromise accuracy, and this trade-off remains insufficiently studied due to the difficulty of performing full-system validation. Specifically, existing simulation tools rarely target SRAM-based ACiM and exhibit inconsistent accuracy predictions, highlighting the need for a standardized, SRAM compute-in-memory (CiM) circuit-aware evaluation methodology. This article presents ASiM, a simulation framework for evaluating inference accuracy in SRAM-based ACiM systems. ASiM captures critical effects in SRAM-based analog compute in memory systems, such as analog-to-digital converter (ADC) quantization, bit-parallel encoding, and analog noise, which must be modeled with high fidelity due to their distinct behavior in charge-domain architectures compared to other memory technologies. ASiM supports a wide range of modern DNN workloads, including CNN and Transformer-based models such as ViT, and scales to large-scale tasks like ImageNet classification. Our results indicate that bit-parallel encoding can improve energy efficiency with only modest accuracy degradation; however, even 1 LSB of analog noise can significantly impair inference performance, particularly in complex tasks such as ImageNet. To address this, we explore hybrid analog-digital execution and majority voting schemes, both of which enhance robustness without negating energy savings. ASiM bridges the gap between hardware design and inference performance, offering actionable insights for energy-efficient, high-accuracy ACiM deployment. The code is available athttps://github.com/Keio-CSG/ASiM", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2025_Zhang_ASiM_TVLSI.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2025_Zhang_ASiM_TVLSI.pdf", "priority": 5.18}, {"id": "W4414198111", "short": "IMCsim", "title": "A Full-system, Programmable, and Extensible In-Memory Computing Simulation Framework for Deep Learning", "authors": ["Kaining Zhou", "Jian Huang", "Nam Sung Kim", "Naresh R. Shanbhag"], "year": 2025, "venue": "", "venue_short": "DAC", "venue_full": "ACM/IEEE Design Automation Conference (DAC 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/dac63849.2025.11132463", "cites_global": 0, "cat": "08", "seed": false, "devices": ["MRAM", "SRAM-analog", "Generic-NVM"], "models": ["ResNet", "GPT/LLM", "Transformer"], "evidence": "simulation", "tldr": "IMCsim is a full-system in-memory-computing simulator with software runtime libraries, ISA extensions for tensor operators, and flexible mapping across eNVM/SRAM/digital IMC architectures, validated against measured 22nm MRAM and 28nm SRAM IMC prototype chips and used to explore ResNet-18/Llama/DiT design trade-offs and derive an efficient 28nm DiT chip layout.", "summary": "The paper addresses a gap in IMC tooling: designing programmable IMC platforms for today's large generative models (LLMs, diffusion transformers) requires a simulator that is simultaneously scalable and faithful to device/circuit-level IMC behavior, which existing tools reportedly lack. IMCsim is presented as a versatile full-system IMC simulation framework that integrates software runtime libraries for AI models, introduces a new set of ISA extensions to express common tensor operators, and flexibly maps these operators onto different IMC architectures, letting designers explore performance/energy/area/accuracy trade-offs across IMC design choices. The authors instantiate three IMC types in IMCsim -- embedded non-volatile memory (eNVM)-based, SRAM-based, and digital IMC -- and validate the simulator against measured data from two lab-tested prototype ICs (a 22nm MRAM-based IMC and a 28nm SRAM-based IMC) plus a digital IMC design in 28nm. They then use IMCsim to explore the architectural design space across ResNet-18, Llama, and a diffusion transformer (DiT) workload for the three IMC types, and finally use it as a design tool to derive an efficient chip architecture and layout in 28nm for a lightweight DiT.", "contributions": ["Presents IMCsim, a full-system IMC simulation framework combining scalability with device/circuit-level fidelity, addressing a gap for simulating large generative-AI workloads (LLMs, DiTs) on IMC hardware", "Introduces software runtime libraries for AI models plus new ISA extensions to express common tensor operators on IMC hardware", "Supports flexible mapping of tensor operators across multiple IMC architecture types (eNVM-based, SRAM-based, digital)", "Validates IMCsim against measured data from two lab-tested prototype ICs (22nm MRAM-based IMC, 28nm SRAM-based IMC) and a 28nm digital IMC design", "Uses IMCsim to explore architectural trade-offs for ResNet-18, Llama, and a DiT workload across the three IMC types, and to derive an efficient 28nm chip architecture/layout for a lightweight DiT"], "claims": [{"claim": "IMCsim's simulation results are validated against real silicon across two different IMC device technologies", "support": "Validated using measured data from two lab-tested prototype ICs: a 22nm MRAM-based IMC and a 28nm SRAM-based IMC, plus a digital IMC design in 28nm", "loc": "Abstract"}, {"claim": "IMCsim can be used as a practical design tool to derive an efficient real chip architecture/layout for modern generative workloads", "support": "Used to obtain an efficient chip architecture and layout in 28nm for a lightweight diffusion transformer (DiT)", "loc": "Abstract"}], "results": [], "limitations": ["Abstract does not report specific quantitative validation error margins (e.g. % error vs. measured silicon) for the simulator's predictions", "Only three IMC device/architecture types are modeled (eNVM, SRAM, digital); other analog device classes (PCM, ReRAM crossbars with analog MAC) are not mentioned as validated in the abstract", "Full text not available to this analysis; scope of the ISA extensions and runtime library coverage cannot be independently verified"], "remarks": "A full-system simulator paper with a notably strong validation story (grounded in two measured prototype ICs rather than only literature-reported numbers), which is valuable for anyone needing to trust IMC-level performance/energy/accuracy predictions for LLM/DiT-scale workloads rather than just CNN-scale ones. Without the full text, the degree of validation accuracy and the breadth of the ISA-extension abstraction (how well it generalizes to analog crossbar-style MAC, as opposed to the eNVM/SRAM/digital IMC variants it demonstrates) remain open questions for this thesis's purposes.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "In-memory computing (IMC) has established itself as an attractive alternative to hardware accelerators in addressing the memory wall problem for artificial intelligence (AI) workloads. However, designing programmable IMC-based computing platforms for today’s large generative AI models, such as large language models (LLMs) and diffusion transformers (DiTs), is hindered by the absence of a simulator that is able to address the associated scalability challenges while simultaneously incorporating device and circuit-level behaviors intrinsic to IMCs. To address this challenge, we present IMCsim, a versatile fullsystem IMC simulation framework. IMCsim integrates software runtime libraries for AI models, introduces a new set of ISA extensions to express common tensor operators, and provides flexibility in mapping these operators to various IMC architectures. As such, IMCsim enables designers to explore trade-offs between performance, energy, area, and computational accuracy for various IMC design choices. To demonstrate the functionality, efficiency, and versatility of IMCsim, we model three types of IMCs: (1) embedded non-volatile memory (eNVM)-based, (2) SRAM-based, and (3) digital IMCs. We validate IMCsim using measured data from two laboratory-tested IMC prototype ICs—a 22 nm MRAM-based IMC and a 28 nm SRAM-based IMC—and a digital IMC design in 28 nm. Next, we demonstrate the utility of IMCsim by exploring the architectural design space to obtain insights for maximizing utilization of IMC-based processors for diverse workloads—ResNet-18, Llama, and a DiT—using the three IMC types. Finally, we employ IMCsim as a design tool to obtain an efficient chip architecture and layout in 28 nm for a lightweight DiT.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2025_Zhou_IMCsim_DAC.pdf", "analysed": true, "pdf": null, "priority": 3.5}, {"id": "W7106169063", "short": "NIPA", "title": "How Do Errors Impact NN Accuracy on Non-Ideal Analog PIM? Fast Evaluation via an Error-Injected Robustness Metric", "authors": ["Lidong Guo", "Zhenhua Zhu", "Qiushi Lin", "Yuan Xie", "Huazhong Yang", "Wangyang Fu", "Yu Wang"], "year": 2025, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad66269.2025.11240851", "cites_global": 0, "cat": "08", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN", "GPT/LLM"], "evidence": "simulation", "tldr": "Proposes an error-injected robustness metric and a Non-Ideal PIM Accuracy (NIPA) model that unifies diverse analog-PIM error sources into a single weight-space representation, giving a non-slicing accuracy-evaluation method up to 105.8x faster than bit-and-crossbar slicing simulators like DNN+NeuroSim while matching accuracy within 0.29% average error and 0.91 correlation.", "summary": "The paper tackles the extreme simulation cost of evaluating DNN accuracy under non-ideal analog PIM hardware: standard simulators use a bit-and-crossbar slicing paradigm that evaluates each matrix-vector multiplication bit-by-bit and crossbar-by-crossbar, which becomes prohibitively slow for large models including LLMs. The authors propose an 'error-injected robustness metric' that unifies various software/hardware error sources (device variation, quantization, etc.) into the weight dimension, enabling joint error analysis. Building on this, they design a Non-Ideal PIM Accuracy (NIPA) evaluation model for fast relative accuracy evaluation that explicitly accounts for coupling between different error sources using the network's prior information (e.g., weight/activation statistics), and further propose a non-slicing absolute accuracy evaluation method that removes the need for the slow bit-and-crossbar slicing process entirely. Experiments on CNNs and LLMs show NIPA achieves correlations up to 0.91 with the absolute accuracy computed by DNN+NeuroSim, and the non-slicing method achieves up to 105.8x speedup over existing slicing-based evaluators with average evaluation error as low as 0.29%.", "contributions": ["Error-injected robustness metric that unifies heterogeneous analog-PIM error sources (software and hardware) into a single weight-dimension representation", "NIPA evaluation model for fast relative accuracy evaluation that models coupling effects between error sources using NN prior information", "Non-slicing absolute accuracy evaluation method that avoids the costly bit-by-bit, crossbar-by-crossbar slicing simulation", "Validation on both CNNs and LLMs, including comparison against the DNN+NeuroSim bit-and-crossbar slicing baseline"], "claims": [{"claim": "NIPA's relative accuracy evaluation correlates strongly with ground-truth absolute accuracy from a standard slicing simulator", "support": "Correlation up to 0.91 with absolute accuracy evaluated by DNN+NeuroSim", "loc": "Abstract"}, {"claim": "The non-slicing absolute accuracy method is dramatically faster than bit-and-crossbar slicing evaluation while remaining accurate", "support": "Up to 105.8x speedup with average evaluation error as low as 0.29% compared to existing slicing-based methods", "loc": "Abstract"}], "results": ["Up to 105.8x speedup over bit-and-crossbar slicing-based accuracy evaluation methods", "Average evaluation error as low as 0.29% for the non-slicing absolute accuracy method", "Correlation up to 0.91 between NIPA relative-accuracy metric and DNN+NeuroSim absolute accuracy", "Validated on CNNs and LLMs (specific models/benchmarks not confirmable beyond the abstract since full text was not accessible)"], "limitations": ["Full text not accessible to this reviewer (no open preprint found); exact models, error types, and experimental configurations beyond the abstract could not be verified", "Reported speedup/correlation figures are relative to a specific baseline (DNN+NeuroSim slicing simulation), so generality across other simulators/error models is unconfirmed from the abstract alone"], "remarks": "Abstract-only assessment: ICCAD proceedings are not downloadable here and no arXiv preprint was found. This is squarely a simulation/benchmarking-framework contribution (category 08) that directly addresses a practical bottleneck for anyone trying to evaluate LLM-scale models on non-ideal analog PIM hardware — the combinatorial cost of bit-sliced, crossbar-by-crossbar Monte Carlo simulation. If the claimed 100x+ speedup with sub-1% error holds up, it would be a useful tool for thesis-level design-space exploration, but the fairness of the comparison and generality beyond DNN+NeuroSim-style baselines cannot be verified without the full paper.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The emerging analog Processing-in-Memory (PIM) architectures have shown great potential to overcome the memory wall problem and accelerate neural network (NN) inference. However, different from digital architectures, the computation accuracy of analog PIM architectures is directly impacted by various errors, which are related to both software and hardware parameters. Existing PIM simulators mainly adopt the bit-and-crossbar slicing paradigm to evaluate the accuracy under various errors. Each MVM operation is performed bit by bit and crossbar by crossbar, which is extremely time-consuming, especially for models with a larger number of parameters, such as large language models (LLMs).In this work, we propose an error-injected robustness metric, unifying various errors into the weight dimension and facilitating joint error analysis. Based on the error-injected robustness metric, we propose a Non-Ideal PIM Accuracy (NIPA) evaluation model for relative accuracy evaluation, considering the coupling effect (i.e., various errors can be affected by the same factor) among various errors using NN’s prior information. We further propose a non-slicing absolute accuracy evaluation method, eliminating the need for the time-consuming bit-and-crossbar slicing process. Extensive experiments on CNNs and LLMs validate that the proposed NIPA evaluation model achieves high correlations of up to 0.91 with the absolute accuracy evaluated by DNN+NeuroSim. At the same time, compared to existing bit-and-crossbar slicing evaluation methods, the proposed non-slicing absolute accuracy evaluation method achieves up to 105.8× speedup with average evaluation errors as low as 0.29%.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2025_Guo_NIPA_ICCAD.pdf", "analysed": true, "pdf": null, "priority": 3.5}, {"id": "W4391164199", "short": "CoMN", "title": "CoMN: Algorithm-Hardware Co-Design Platform for Nonvolatile Memory-Based Convolutional Neural Network Accelerators", "authors": ["Lixia Han", "Renjie Pan", "Zheng Zhou", "Hairuo Lu", "Yiyang Chen", "Haozhang Yang", "Peng Cheng Huang", "Guangyu Sun", "Xiaoyan Liu", "Jinfeng Kang"], "year": 2024, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2024.3358220", "cites_global": 15, "cat": "08", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "CoMN is a GUI-based algorithm-hardware co-design platform for NVM-based CIM CNN accelerators, providing an automatic CNN-to-chip mapper, joint accuracy/energy/latency/area evaluators, a nonideality- and energy-aware retraining 'algorithm adapter', and a hardware microarchitecture/circuit design-space optimizer.", "summary": "The paper addresses the complexity of co-designing NVM-based compute-in-memory (CIM) CNN accelerators, where the design space spans algorithm (model/weights), mapping, microarchitecture, and circuit levels, and design decisions at one level interact strongly with others, making ad hoc single-level design methodologies inefficient. CoMN is proposed as an integrated, browser-accessible platform with four main components: (1) a mapper that automatically maps CNN models onto CIM chips by optimizing pipelining, weight transformation, partitioning, and placement; (2) joint accuracy and performance evaluators that estimate accuracy, energy, latency, and area together, capturing cross-level design dependencies; (3) an algorithm adapter that retrains CNN weights to be more hardware-robust and energy-efficient via nonideality-aware training and energy-aware training under an energy budget; and (4) a hardware optimizer that searches the microarchitecture/circuit design space early in the design process. The authors demonstrate the platform through case studies showing it supports algorithm-hardware mapping, hardware-aware algorithm adaptation, hardware configuration exploration, and combined co-design, and make the tool publicly accessible online.", "contributions": ["Integrated, GUI-accessible algorithm-hardware co-design platform (CoMN) spanning model, mapping, microarchitecture, and circuit levels for NVM-based CIM CNN accelerators", "Automatic CNN-to-chip mapper optimizing pipeline scheduling, weight transformation, partitioning, and placement", "Joint accuracy/energy/latency/area evaluation framework that accounts for cross-level design dependencies rather than evaluating each level in isolation", "An 'algorithm adapter' performing nonideality-aware and energy-aware retraining of CNN weights to improve hardware accuracy within an energy budget", "A hardware optimizer for early-stage search of microarchitecture and circuit design choices", "Publicly hosted, browser-accessible deployment of the platform for use by other designers"], "claims": [{"claim": "CoMN enables effective algorithm-hardware mapping, hardware-aware algorithm adaptation, hardware configuration exploration, and combined co-design in case studies.", "support": "case-study demonstrations described in abstract", "loc": "Case studies section (not verified in full text)"}, {"claim": "Jointly modeling accuracy, energy, latency, and area across design levels is necessary because of strong cross-level design dependencies in NVM-based CIM CNN accelerators.", "support": "motivation and evaluator design rationale", "loc": "Introduction / platform design rationale"}], "results": ["No specific quantitative benchmark numbers (e.g., speedup/energy-efficiency figures) are given in the abstract; the contribution is the platform/tooling and its qualitative demonstration via case studies"], "limitations": ["Full text not available for this analysis; the abstract does not provide quantitative results, so the platform's accuracy of accuracy/energy/latency/area prediction versus ground truth (e.g., SPICE or silicon) is unknown from this review", "As a flexible platform paper, it may rely on simplified device/circuit models similar to other CIM DSE frameworks (e.g., NeuroSim-family tools); the fidelity of its nonideality-aware training versus real device characterization is unclear from the abstract alone", "Evaluated only on CNNs per the abstract; no evidence of support for transformers/LLMs"], "remarks": "CoMN sits alongside other co-design/benchmarking frameworks (DNN+NeuroSim, MNSIM) in this collection as infrastructure for exploring the CIM CNN accelerator design space, distinguished by its explicit four-stage pipeline (mapper, joint evaluator, algorithm adapter, hardware optimizer) and public GUI/online access. Because only the abstract was available, the analysis here is necessarily qualitative; a follow-up read of the full text would be needed to assess how its accuracy/energy models are validated and how it compares quantitatively to NeuroSim-style tools already in the collection.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Computing in memory (CIM) convolutional neural network (CNN) accelerators based on nonvolatile memory (NVM) show great potential to improve energy efficiency and throughput, while the multiple design levels and huge design space of CIM-based CNN acceleration system make cross-level co-design methodology and platforms extremely desired. In this work, an algorithm-hardware co-design platform CoMN with the graphic user interface is proposed for designers to fast verify and further optimize the designments. In the platform, 1) a mapper is developed to automatically map CNN models to CIM chips through optimizing pipeline, weight transformation, partition, and placement; 2) accuracy evaluator and performance evaluator are built to jointly estimate accuracy, energy, latency, and area overheads considering the design dependencies across multiple levels; 3) algorithm adapter is exploited to retrain CNN weights for higher hardware accuracy within limited energy budget through nonidealities aware training and energy aware training; 4) hardware optimizer is developed to search hardware microarchitecture and circuit design space in the early design stage. We conduct several case studies to verify the effectiveness of the CoMN platform. Results indicate that CoMN platform can enable algorithm-hardware mapping, hardware-aware algorithm adaption, hardware configuration exploration, and overall algorithm-hardware co-design efficiently. The CoMN platform can be accessed online at http://101.42.97.22:8081/index.html with username “tcad” and password “comnuser”.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2024_Han_CoMN_TCAD.pdf", "analysed": true, "pdf": null, "priority": 6.15}, {"id": "W4400681289", "short": "CiMLoop", "title": "CiMLoop: A Flexible, Accurate, and Fast Compute-In-Memory Modeling Tool", "authors": ["Tanner Andrulis", "Joel Emer", "Vivienne Sze"], "year": 2024, "venue": "", "venue_short": "ISPASS", "venue_full": "IEEE International Symposium on Performance Analysis of Systems and Software (ISPASS 2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/ispass61541.2024.00012", "cites_global": 30, "cat": "08", "seed": false, "devices": ["ReRAM", "SRAM-analog", "Generic-NVM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "CiMLoop is an open-source, full-stack (device/circuit/architecture/workload/mapping) compute-in-memory modeling tool that combines a flexible user-defined hardware specification with a fast, statistically accurate data-value-dependent energy model, matching NeuroSim-level accuracy at orders-of-magnitude higher speed.", "summary": "The paper argues that CiM research is fragmented across devices, circuits, architecture, workload and mapping, and that existing tools (NeuroSim, MNSim, Timeloop) are each either inflexible, circuit-coarse, or use fixed-energy models that ignore data-value dependence, making full-stack co-design hard. CiMLoop addresses this with (1) a flexible specification letting users describe arbitrary circuits/architectures and how workloads map onto them, (2) a statistical energy model that captures how DNN operand value distributions (not just counts) affect analog/digital circuit energy, and (3) amortization of data-value-dependent computation so exploration scales to thousands of mappings. Built as a NeuroSim plug-in for validation, CiMLoop is benchmarked against NeuroSim ground truth on a ResNet-18/ImageNet workload: its data-value-dependent model achieves 3% average (7% max) full-macro energy error versus 28% average (70% max) for a non-data-value-dependent fixed-energy model, while running orders of magnitude faster (e.g., 1076 mappings/sec with 16 cores vs. 0.07/sec for NeuroSim). The authors further validate CiMLoop against four published CiM macros (A-D) for voltage, bit-precision, and energy/area breakdown, and present four design-space case studies (mapping, circuit choice, architecture scaling, and full-system/cross-macro comparison) that would be hard to do with prior single-level tools.", "contributions": ["A flexible, user-defined specification format spanning devices, circuits, architecture, workload and mapping, enabling full-stack CiM modeling without editing simulator source code", "A statistical, data-value-dependent energy model that represents DNN operand tensors as per-layer distributions rather than fixed averages, substantially reducing energy-estimation error", "An amortization scheme that decouples (slow) data-value-dependent calculation from (fast) per-mapping evaluation, giving orders-of-magnitude speedup over NeuroSim for large design-space exploration", "Validation against NeuroSim ground truth and against four published CiM macros (voltage/precision/energy-area breakdown)", "Four cross-stack case studies (mapping reuse, circuit trade-offs, architecture scaling, full-system/cross-macro projection) demonstrating co-design use cases", "Open-source release (github.com/mit-emze/cimloop) integrating NeuroSim as a plug-in"], "claims": [{"claim": "Data-value-dependent modeling is far more accurate than fixed-energy modeling for CiM macro energy", "support": "CiMLoop: 3% avg / 7% max full-macro energy error vs. NeuroSim ground truth; non-data-value-dependent fixed-energy model: 28% avg / 70% max error", "loc": "Sec. IV-A, Fig. 6"}, {"claim": "CiMLoop explores the design space orders of magnitude faster than NeuroSim without losing accuracy", "support": "Table II: NeuroSim 0.07 mapping-layers/s (1 core); CiMLoop 0.28/s (1 core, 1 mapping) rising to 1076/s (16 cores, 5000 mappings)", "loc": "Sec. IV-B, Table II"}, {"claim": "CiMLoop correctly reproduces measured/published macro behavior under varying supply voltage and input bit-precision", "support": "Figs. 7-10 validate energy/throughput vs. voltage and input bits, and energy/area breakdowns, against four published macros (A-D)", "loc": "Sec. V, Figs. 7-10"}, {"claim": "Full-stack, cross-level exploration finds better designs than single-level optimization", "support": "Case study: optimizing for macro energy alone would mislead toward a higher full-system-energy design; considering the full system changes the optimal choice", "loc": "Sec. III-A / Sec. V case studies"}], "results": ["Full-macro energy error vs. NeuroSim: 3% average / 7% max (CiMLoop) vs. 28% average / 70% max (fixed-energy baseline), across 21 ResNet-18 layers", "Modeling throughput: up to 1076 mapping-layer evaluations/sec (16-core, 5000 mappings) vs. 0.07/sec for NeuroSim (single core, single mapping) -- several orders of magnitude speedup", "Validated against 4 published CiM macros (A-D) for energy/throughput vs. supply voltage, input-bit precision, and energy/area breakdown (Figs. 7-10)"], "limitations": ["Accuracy still has residual error (avg 3%, max 7%) from representing per-layer operand tensors as independent statistical distributions rather than exact values", "Validation macros are a small set (4 published designs, mostly SRAM/ReRAM) and one workload family (ResNet-18/ImageNet)", "Focuses on area/energy/throughput modeling, not DNN task accuracy (acknowledges tools like AIHWKit/CrossSim/MemTorch are needed for that)", "Per-mapping (non-data-value-dependent) evaluation still dominates runtime in most explorations, so overall speed depends on that component's efficiency", "Tool quality depends on user-provided circuit/architecture specifications being accurate; flexibility shifts some modeling burden to the user"], "remarks": "A well-engineered, now widely-cited (30+ citations within ~1.5 years) open-source modeling tool that fills a real gap between circuit-only (NeuroSim) and architecture-only (Timeloop) simulators by explicitly modeling how DNN operand value distributions affect analog/digital circuit energy. Because it integrates NeuroSim as a validated back-end, its accuracy claims are only as good as NeuroSim's own device models, and it is restricted to energy/area/throughput rather than inference accuracy. It is already being built upon by several 2025 follow-on frameworks (CIMFlow, CIMNAS, TriCIM) for dataflow and NAS-aware CiM design, suggesting it is becoming a standard tool for full-stack CiM architecture research relevant to crossbar mapping studies.", "basis": "full-text", "pdf_source_url": "", "abstract": "Compute-In-Memory (CiM) is a promising solution to accelerate Deep Neural Networks (DNNs) as it can avoid energy-intensive DNN weight movement and use memory arrays to perform low-energy, high-density computations. These benefits have inspired research across the CiM stack, but CiM research often focuses on only one level of the stack (i.e., devices, circuits, architecture, workload, or mapping) or only one design point (e.g., one fabricated chip). There is a need for a full-stack modeling tool to evaluate design decisions in the context of full systems (e.g., see how a circuit impacts system energy) and to perform rapid early -stage exploration of the CiM co-design space. To address this need, we propose CiMLoop: an open-source tool to model diverse CiM systems and explore decisions across the CiM stack. CiMLoop introduces (1) a flexible specification that lets users describe, model, and map workloads to both circuits and architecture, (2) an accurate energy model that captures the interaction between DNN operand values, hardware data representations, and analog/digital values propagated by circuits, and (3) a fast statistical model that can explore the design space orders-of-magnitude more quickly than other high-accuracy models. Using CiMLoop, researchers can evaluate design choices at different levels of the CiM stack, co-design across all levels, fairly compare different implementations, and rapidly explore the design space.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2024_Andrulis_CiMLoop_ISPASS.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2024_Andrulis_CiMLoop_ISPASS.pdf", "priority": 6.87}, {"id": "W4404915602", "short": "MELISO", "title": "The Lynchpin of In-Memory Computing: A Benchmarking Framework for Vector-Matrix Multiplication in RRAMs", "authors": ["Md Tawsif Rahman Chowdhury", "Huynh Quang Nguyen Vo", "Paritosh Ramanan", "Murat Yildirim", "Gözde Tütüncüoğlu"], "year": 2024, "venue": "", "venue_short": "ICONS", "venue_full": "International Conference on Neuromorphic Systems (ICONS 2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/icons62911.2024.00058", "cites_global": 3, "cat": "08", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "MELISO is a NeuroSim-based end-to-end VMM benchmarking framework that statistically characterizes how RRAM device metrics (memory window, weight bits, non-linearity, cycle-to-cycle variation) shape the magnitude and probability-distribution shape (skewness/kurtosis) of vector-matrix-multiplication error, benchmarked across four real device types.", "summary": "RRAM crossbar VMM promises to overcome the Von Neumann bottleneck, but device and circuit non-idealities corrupt the analog dot product, and prior work rarely characterizes the full error distribution rather than just magnitude. The authors build MELISO (In-Memory Linear Solver), a Python/Cython front-end over the C++ MLP+NeuroSim simulator, that runs large populations of random 32x32 matrix-vector multiplications (1000 matrices x 1000 vectors, aggregated into a 32000x1 error vector) on simulated RRAM crossbars and statistically models the resulting error. Using an Ag:a-Si device model, they independently sweep weight-bit precision (1 to 11 bits / up to 2048 states) and memory window (Gmax/Gmin), then separately sweep weight-update non-linearity and cycle-to-cycle (C-to-C) variation, showing error magnitude/variance decreases with more conductance states and larger memory window, while increasing sharply (with roughly exponential variance growth) with non-linearity and C-to-C variation. Finally, they benchmark four real device types (Ag:a-Si, TaOx/HfOx, AlOx/HfO2, EpiRAM) with and without non-idealities, finding EpiRAM (largest memory window, lowest non-linearity and C-to-C) performs best and AlOx/HfO2 worst, and that VMM errors are non-Gaussian, best fit by Johnson-Su, Normal-2/3-Mixture, or SHASH distributions rather than a normal distribution.", "contributions": ["MELISO: an open, end-to-end VMM benchmarking framework combining a Python/Cython interface (MelisoPy) with the MLP+NeuroSim C++ backend for RRAM crossbar simulation", "A statistically rigorous error-characterization methodology using large populations (1000x1000 matrix-vector pairs, 32000-element error vectors) rather than single-instance error measurements", "Systematic, independently-controlled sweeps of memory window, weight-bit precision, weight-update non-linearity, and cycle-to-cycle (C-to-C) variation on VMM error", "Cross-device benchmarking of 4 literature RRAM device types (Ag:a-Si, TaOx/HfOx, AlOx/HfO2, EpiRAM) with/without non-idealities", "Identification of best-fit parametric error distributions (Johnson Su, Normal-2/3-Mixture, SHASH) rather than assuming Gaussian error, with skewness/kurtosis analysis"], "claims": [{"claim": "VMM error magnitude and variance decrease monotonically with increasing weight-bit precision and memory window", "support": "Fig. 2: error magnitude/variance decreases as weight bits increase from 1-bit (2 states) to 11-bit (2048 states), and as memory window increases beyond the default 12.5", "loc": "Sec. III, Fig. 2"}, {"claim": "Weight-update non-linearity exacerbates VMM error with an exponential-like growth in variance", "support": "Fig. 3: error variance grows with non-linearity magnitude swept from 0 to 5, reflecting NeuroSim+'s exponential non-linear synaptic weight encoding", "loc": "Sec. III, Fig. 3"}, {"claim": "RRAM VMM errors are non-Gaussian, with device-dependent skewness and heavy tails", "support": "Table II: best-fit distributions are Johnson Su, Normal-2-Mixture, Normal-3-Mixture, or SHASH depending on device/non-ideality configuration, not Normal", "loc": "Sec. III, Table II"}, {"claim": "EpiRAM has the best VMM accuracy among four benchmarked devices due to its largest memory window and lowest non-linearity/C-to-C", "support": "EpiRAM: memory window 50.2, non-linearity 0.5/-0.5, C-to-C 2% -> smallest error magnitude in both ideal and non-ideal configurations (Fig. 5)", "loc": "Sec. III, Fig. 5, Table I"}], "results": ["Device metrics compared (Table I): Ag:a-Si (97 states, non-linearity 2.4/-4.88, memory window 12.5, C-to-C 3.5%), TaOx/HfOx (128 states, 0.04/-0.63, MW 10, C-to-C 3.7%), AlOx/HfO2 (40 states, 1.94/-0.61, MW 4.43, C-to-C 5%), EpiRAM (64 states, 0.5/-0.5, MW 50.2, C-to-C 2%)", "Ranking of VMM error magnitude/variance across 4 devices (best to worst): EpiRAM < Ag:a-Si approx. TaOx/HfOx < AlOx/HfO2, consistent with and without non-idealities", "C-to-C variation swept 0%-5%; even the baseline 3.5% C-to-C (Ag:a-Si) introduces substantial VMM error, with error increasing as C-to-C grows"], "limitations": ["Experiments limited to small 32x32 crossbar arrays and random matrix/vector inputs, not real DNN workloads or larger-scale arrays", "No end-task (e.g., classification) accuracy results reported; only raw dot-product error statistics are characterized", "Only 4 RRAM device types from the literature are benchmarked; device models come from NeuroSim+/NeuroSim V3.0 parameter tables rather than the authors' own measurements", "Error-source sweeps (weight bits, memory window, non-linearity, C-to-C) are mostly varied independently/pairwise rather than in full joint combination, so interaction effects beyond the few studied pairs are not explored", "Short conference paper (ICONS, 6 pages); the statistical distribution-fitting methodology is demonstrated but not deeply validated against alternative fitting approaches"], "remarks": "A useful, methodologically careful addition to the growing set of CiM-error-modeling tools: rather than reporting a single error number, it shows RRAM VMM error is non-Gaussian and device-dependent in its higher moments (skewness, kurtosis), which matters for anyone doing noise-aware training or error-correction coding on crossbars, since a Gaussian-noise assumption may be wrong for certain devices/non-idealities. However, because it only studies isolated 32x32 random-matrix VMMs rather than full DNN layers or end-task accuracy, its practical implications for model-mapping decisions are suggestive rather than demonstrated; it would need to be connected to actual network inference/training experiments to show the benchmarking insights translate to real accuracy gains.", "basis": "full-text", "pdf_source_url": "", "abstract": "The Von Neumann bottleneck, a fundamental challenge in conventional computer architecture, arises from the inability to execute fetch and data operations simultaneously due to a shared bus linking processing and memory units. This bottleneck significantly limits system performance, increases energy consumption, and exacerbates computational complexity. Emerging technologies such as Resistive Random Access Memories (RRAMs), leveraging crossbar arrays, offer promising alternatives for addressing the demands of data-intensive computational tasks through in-memory computing of analog vector-matrix multiplication (VMM) operations. However, the propagation of errors due to device and circuit-level imperfections remains a significant challenge. In this study, we introduce MELISO (In-Memory Linear Solver), a comprehensive end-to-end VMM benchmarking framework tailored for RRAM-based systems. MELISO evaluates the error propagation in VMM operations, analyzing the impact of RRAM device metrics on error magnitude and distribution. This paper introduces the MELISO framework and demonstrates its utility in characterizing and mitigating VMM error propagation using state-of-the-art RRAM device metrics.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2024_Chowdhury_MELISO_ICONS.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2024_Chowdhury_MELISO_ICONS.pdf", "priority": 3.92}, {"id": "W4409285506", "short": "SPICE eNVM ACIM Framework", "title": "Accurate, Yet Scalable: A SPICE-based Design and Optimization Framework for eNVM based Analog In-memory Computing", "authors": ["S M Mojahidul Ahsan", "Muhammad Sakib Shahriar", "Mrittika Chowdhury", "Tanvir Hossain", "Md Sakib Hasan", "Tamzidul Hoque"], "year": 2024, "venue": "", "venue_short": "ICCAD", "venue_full": "Proceedings of the 43rd IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2024)", "venue_ok": true, "doi": "https://doi.org/10.1145/3676536.3676827", "cites_global": 2, "cat": "08", "seed": false, "devices": ["Generic-NVM"], "models": ["MLP"], "evidence": "simulation", "tldr": "A scalable SPICE-based simulation framework automates SPICE-level netlist generation for eNVM analog compute-in-memory (ACIM) DNN accelerators, speeding up simulation by up to 35x and enabling convergent SPICE simulation of large crossbars (e.g., an 800,000-parameter MLP on MNIST) that contemporary SPICE simulators cannot handle, with under 3.8% accuracy drop versus software inference.", "summary": "Simulating analog compute-in-memory (ACIM) architectures built from emerging non-volatile resistive memories (eNVM) accurately requires circuit-level (SPICE) simulation because these crossbars are highly sensitive to process, voltage, temperature variation and analog noise, but standard SPICE simulators do not scale to the large netlists needed for realistic DNNs and often fail to converge. The paper introduces a scalable SPICE-based tool infrastructure that automates generation of SPICE-level ACIM circuit descriptions for DNNs, and speeds up simulation runtime by up to 35x for large models while preserving SPICE-level accuracy, also improving convergence for large netlists. The framework is validated by simulating inference of MLPs with over 800,000 parameters trained on MNIST, a scale that the authors state is impractical for contemporary SPICE simulators, and the simulated inference accuracy is shown to be within 3.8% of software-based inference. The framework is also integrated with an architectural simulator to enable combined circuit-to-system-level simulation.", "contributions": ["Proposes a scalable SPICE-based simulation framework specifically for eNVM-based analog compute-in-memory (ACIM) architectures", "Automates generation of SPICE-level ACIM circuit netlists directly from DNN model descriptions", "Achieves up to 35x simulation speedup for large DNN models while retaining SPICE-level circuit accuracy", "Solves convergence failures that prevent contemporary SPICE simulators from handling large eNVM crossbar netlists", "Integrates the circuit-level simulator with an architectural simulator for combined system-level evaluation"], "claims": [{"claim": "The framework substantially accelerates SPICE-accurate simulation of large ACIM designs", "support": "Simulation runtime speedup of up to 35x for large DNN models while maintaining the same SPICE-level accuracy", "loc": "Abstract"}, {"claim": "The framework enables SPICE simulation of eNVM crossbar DNNs at scales infeasible for standard SPICE tools", "support": "Simulates inference using netlists for MLPs with over 800,000 parameters trained on MNIST within acceptable runtime, where contemporary SPICE simulators do not converge", "loc": "Abstract"}, {"claim": "Simulated (circuit-level) inference accuracy closely matches software inference despite analog non-idealities", "support": "Less than 3.8% accuracy drop compared to software-based inference results", "loc": "Abstract"}], "results": ["Up to 35x simulation runtime speedup for large DNN models at SPICE-level accuracy", "Successfully simulates an MLP with >800,000 parameters on MNIST, where contemporary SPICE simulators fail to converge", "Less than 3.8% inference accuracy drop versus software-based inference"], "limitations": ["Analysis is based on the abstract only; full text was not accessible (not found via arXiv or other legitimate open-access sources), so the specific SPICE automation techniques, device models, and benchmark details beyond the MNIST MLP could not be verified", "Demonstrated scale (MLP, MNIST, ~800K parameters) is still modest relative to modern CNN/transformer workloads"], "remarks": "This is a simulation/EDA-tooling contribution addressing a real bottleneck in the field: circuit-accurate (SPICE) evaluation of eNVM crossbars is the gold standard for capturing non-idealities but does not scale, forcing most mapping/architecture papers in this collection to rely on faster but less accurate behavioral models (e.g., NeuroSim-style). A 35x speedup with SPICE-level fidelity and architectural-simulator integration, if it generalizes beyond the MNIST MLP case demonstrated in the abstract, would be a useful bridge between device-accurate and system-level crossbar simulation frameworks elsewhere in this collection.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "This paper introduces a scalable SPICE-based tool infrastructure designed to optimize analog compute-in-memory (ACIM) architectures utilizing emerging non-volatile resistive memory (eNVM) technologies. The inherent efficiency of analog eNVM crossbar arrays in performing matrix-vector multiplications significantly enhances the power, performance, and area efficiency of edge AI devices and other applications. Our framework addresses the challenges of accurately simulating ACIM architectures, which are highly susceptible to variations in process, voltage, temperature, and analog noise. The framework uses SPICE for accurate analog and mixed-signal circuit simulation. It automates the generation of SPICE-level ACIM designs for deep neural networks. Additionally, it speeds up the simulation runtime by up to 35× for large DNN models while maintaining the same SPICE-level accuracy. Moreover, it ensures simulation convergence for large netlists, facilitating SPICE simulation of large-scale eNVM crossbars that were previously impractical. We demonstrated that our framework is capable of simulating inference using netlists for MLPs with over 800,000 parameters trained on the MNIST dataset within acceptable runtime, where contemporary SPICE simulators do not even converge. We validated the simulation results in terms of inference accuracy, which shows less than a 3.8% accuracy drop compared to software-based inference results. Lastly, we demonstrated the integration of our framework with an architectural simulator, facilitating comprehensive system-level simulation.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2024_Ahsan_SPICEenvmACIMFramework_ICCAD.pdf", "analysed": true, "pdf": null, "priority": 3.83}, {"id": "W4389082012", "short": "AIHWKit", "title": "Using the IBM analog in-memory hardware acceleration kit for neural network training and inference", "authors": ["Manuel Le Gallo", "Corey Lammie", "Julian Büchel", "Fabio Carta", "Omobayode I. Fagbohungbe", "Charles Mackin", "Hsinyu Tsai", "Vijay Narayanan", "Abu Sebastian", "Kaoutar El Maghraoui", "Malte J. Rasch"], "year": 2023, "venue": "APL Machine Learning", "venue_short": "APLMachLearn", "venue_full": "APL Machine Learning", "venue_ok": true, "doi": "https://doi.org/10.1063/5.0168089", "cites_global": 69, "cat": "08", "seed": false, "devices": ["PCM", "ReRAM", "Generic-NVM"], "models": ["CNN", "ResNet", "MLP", "LSTM/RNN", "Transformer"], "evidence": "algorithm+simulation", "tldr": "A tutorial-style paper describing the IBM Analog Hardware Acceleration Kit (AIHWKit), an open-source PyTorch-based simulator for training and inference of DNNs on analog in-memory computing hardware, plus its cloud-hosted Analog AI Cloud Composer front end.", "summary": "The paper addresses the lack of standardized, actively maintained tooling for simulating DNN deployment on noisy, non-ideal AIMC hardware. It presents AIHWKit, a Python/PyTorch library that models AIMC device nonidealities (programming noise, conductance drift, read noise), peripheral circuit effects (ADC/DAC quantization, bound management, noise management), and provides analog equivalents of standard DNN layers so that arbitrary pretrained models can be converted to 'analog' models via convert_to_analog(). It walks through hardware-aware (HWA) training for on-chip training and for robust inference deployment, including drift compensation, weight clipping/remapping, and custom noise-model/drift-compensation extension points. It also introduces the Analog AI Cloud Composer, a no-code cloud platform giving access to AIHWKit simulations and to physical PCM-based AIMC chip ('Fusion Chip') inference. The paper is a methods/tooling tutorial rather than a new accelerator or algorithm, illustrated with worked examples (e.g., HWA training of a model to recover near-floating-point accuracy, and demonstrations of accuracy degradation vs. device-to-device variation and conductance drift).", "contributions": ["Open-sources and documents AIHWKit, comparing it feature-by-feature against other AIMC simulation toolkits (NeuroSim, CrossSim, XB-SIM, MemTorch) in a capability table (ML library support, RNN/Transformer support, on-chip inference/training, performance estimation)", "Describes phenomenological device/circuit nonideality models built into the toolkit: programming (write) noise, conductance drift (power-law model), read noise, and drift compensation strategies", "Provides step-by-step guidance for hardware-aware training (both for on-chip training and for inference-only robust deployment) and weight clipping/remapping techniques", "Introduces the Analog AI Cloud Composer, a managed cloud platform exposing AIHWKit simulation plus access to a physical PCM-based in-memory compute chip", "Demonstrates extensibility with worked code examples: adding a custom NVM noise model and a custom drift-compensation class"], "claims": [{"claim": "AIHWKit is the only actively maintained open-source AIMC simulation toolkit that simultaneously supports RNNs, Transformers, on-chip training and on-chip inference evaluation among the compared tools.", "support": "Feature comparison Table I against NeuroSim, CrossSim, XB-SIM, MemTorch", "loc": "Sec. I, Table I"}, {"claim": "About 120% of the device's measured noise (relative to as-measured data) can be tolerated before a significant accuracy drop occurs for a given device/model combination.", "support": "Dashed line at 99% of no-variation accuracy occurs around 120% noise factor", "loc": "Sec. (noise factor sweep figure), p.~2369-2371"}, {"claim": "Reducing noise variation to about 70% of baseline can significantly improve in-memory training performance because accuracy changes little for noise factors between 1-70% but degrades faster beyond that.", "support": "Described rate-of-change behavior in the noise-factor sweep discussion", "loc": "Sec. on training accuracy vs noise factor, p.~2390-2392"}, {"claim": "Hardware-aware (HWA) training can recover a pretrained model's baseline (floating-point) accuracy (~94% in the worked example) when deployed on simulated analog hardware.", "support": "Worked example pre-training baseline ~94% test accuracy, then HWA-trained analog model", "loc": "Sec. V (worked training example), p.~1704-1705"}], "results": ["Worked CIFAR-like example: baseline (floating point) model accuracy ~94%, used as the reference point for evaluating HWA-trained analog models (Sec. V)", "MVM simulation example: for a sparsity of 50% and clipped Gaussian weights, reported L2 error of the MVM at t=1s is 13% (Sec. IV example)", "Accuracy remains roughly stable for device-to-device variation noise factors up to ~70% of the as-measured baseline before degrading more steeply beyond that (noise-factor sweep figure)"], "limitations": ["This is a tooling/tutorial paper, not a new accelerator or algorithm; results shown are illustrative worked examples rather than a systematic benchmark suite", "AIHWKit models devices phenomenologically (statistical/physical approximations), not full circuit/SPICE-level simulation, so some second-order circuit effects are not captured", "No performance (latency/energy/area) estimation capability at the time of writing; the toolkit targets algorithmic/functional accuracy level only", "Physical hardware access (Fusion Chip via Analog AI Cloud Composer) is limited/managed access, not a generally reproducible silicon benchmark"], "remarks": "This is the reference tutorial for the most widely used open-source AIMC simulation framework (AIHWKit), and is heavily cited by later work needing a standard way to inject PCM/ReRAM noise, drift, and HWA training into PyTorch models. Its value is as shared infrastructure rather than as a novel result: the quantitative numbers given (94% baseline, 13% MVM L2 error, 70-120% noise tolerance) are illustrative rather than benchmarked across architectures. For a thesis on mapping models to analog crossbars, AIHWKit (and its RPUConfig abstractions for ADC/DAC, drift compensation, and noise models) is a practical baseline tool to build on or compare against.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog In-Memory Computing (AIMC) is a promising approach to reduce the latency and energy consumption of Deep Neural Network (DNN) inference and training. However, the noisy and non-linear device characteristics and the non-ideal peripheral circuitry in AIMC chips require adapting DNNs to be deployed on such hardware to achieve equivalent accuracy to digital computing. In this Tutorial, we provide a deep dive into how such adaptations can be achieved and evaluated using the recently released IBM Analog Hardware Acceleration Kit (AIHWKit), freely available at https://github.com/IBM/aihwkit. AIHWKit is a Python library that simulates inference and training of DNNs using AIMC. We present an in-depth description of the AIHWKit design, functionality, and best practices to properly perform inference and training. We also present an overview of the Analog AI Cloud Composer, a platform that provides the benefits of using the AIHWKit simulation in a fully managed cloud setting along with physical AIMC hardware access, freely available at https://aihw-composer.draco.res.ibm.com. Finally, we show examples of how users can expand and customize AIHWKit for their own needs. This Tutorial is accompanied by comprehensive Jupyter Notebook code examples that can be run using AIHWKit, which can be downloaded from https://github.com/IBM/aihwkit/tree/master/notebooks/tutorial.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2023_LeGallo_AIHWKit_APLMachLearn.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2023_LeGallo_AIHWKit_APLMachLearn.pdf", "priority": 7.41}, {"id": "W4389166767", "short": "AIMC-vs-DIMC Modeling", "title": "Analog or Digital In-Memory Computing? Benchmarking Through Quantitative Modeling", "authors": ["Jiacong Sun", "Pouya Houshmand", "Marian Verhelst"], "year": 2023, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad57390.2023.10323763", "cites_global": 33, "cat": "08", "seed": true, "devices": ["SRAM-analog"], "models": ["CNN"], "evidence": "analytical", "tldr": "Proposes an analytical, validated cost model for SRAM-based analog (AIMC) and digital (DIMC) in-memory-computing macros, integrated into a system-level design-space-exploration framework (ZigZag-IMC), to fairly compare AIMC vs. DIMC on real workloads rather than peak-only metrics.", "summary": "The paper addresses the lack of a fair, quantitative, workload-level comparison between analog (AIMC) and digital (DIMC) in-memory-computing macros, since prior IMC benchmarking focuses on peak single-macro performance rather than full-system performance on real workloads, and published analytical models mostly target only AIMC. The authors build a parametrized, physics-based cost model of IMC macro energy/area/latency (covering ADC/adder-tree/array costs, based on a CACTI-derived RC model) that is validated against ~10 published 28/22nm AIMC and DIMC macro implementations with a worst-case mismatch of ~11-20%. This macro model is integrated into the open-source ZigZag-IMC system-level DSE framework to evaluate IMC designs at the system level, scaling array sizes and across individual DNN layer types and full MLPerf Tiny networks. Results show DIMC has higher computational density (peak TOP/s/mm2) than AIMC in general, but AIMC with large macro sizes can be more energy-efficient on convolutional/pointwise layers that permit high spatial unrolling, whereas small-macro DIMC wins on depthwise layers with limited unrolling opportunity; averaged over MLPerf Tiny, DIMC has higher TOP/s/mm2 while system-level energy efficiency is similar between the two paradigms.", "contributions": ["Introduces an analytical, physically grounded cost model for both AIMC and DIMC SRAM-based macros (covering array, ADC, and adder-tree energy/area/delay)", "Validates the cost model against ~10 published 28nm/22nm AIMC and DIMC silicon implementations, achieving a maximum mismatch of ~11% (up to ~20% for less commonly reported sparsity conditions)", "Integrates the macro-level cost model into a system-level DSE framework (ZigZag-IMC) enabling workload-level, not just peak, performance comparison", "Benchmarks AIMC vs DIMC across individual DNN layer types (conv, pointwise, depthwise, FC) and across full MLPerf Tiny benchmark networks", "Open-sources the model and framework (zigzag-imc on GitHub)"], "claims": [{"claim": "DIMC generally achieves higher computational density (TOP/s/mm2) than AIMC.", "support": "System-level and workload comparisons in Figs. 7-8, 12", "loc": "Sec. V, Fig. 7-8, 12"}, {"claim": "AIMC with large macro sizes can achieve better energy efficiency than DIMC on convolutional and pointwise layers that allow high spatial unrolling.", "support": "Layer-type energy/throughput comparison", "loc": "Sec. V, Fig. 10-11"}, {"claim": "DIMC with small macro size outperforms AIMC on depthwise layers, which have limited spatial unrolling opportunities.", "support": "Layer-type comparison, Fig. 10-11", "loc": "Sec. V, Fig. 10-11"}, {"claim": "The proposed macro-level cost model matches published silicon implementations to within ~11% in the standard case.", "support": "Validation against 28/22nm published chips, Fig. 6", "loc": "Sec. IV, Fig. 6"}, {"claim": "Averaged over the MLPerf Tiny benchmark suite, DIMC achieves higher workload TOP/s/mm2 than AIMC while system-level energy efficiency between the two is similar.", "support": "Geometric mean over 4 MLPerf Tiny models", "loc": "Sec. V (Conclusion of workload evaluation)"}], "results": ["Macro-level model validated against ~10 published 28nm/22nm AIMC/DIMC chips with maximum mismatch ~11% (up to ~20% under non-reported sparsity assumptions, with 50% input toggle rate / 50% weight sparsity assumed for validation)", "ResNet8 (all-convolutional) achieves TOP/s/W closest to peak among MLPerf Tiny models tested; FC-heavy Autoencoder suffers from frequent weight reloading overhead", "Geometric-mean comparison across 4 MLPerf Tiny models: DIMC has higher average workload TOP/s/mm2 than AIMC, with similar system-level energy efficiency"], "limitations": ["Sparsity impact on energy is explicitly not modeled, despite being a known significant factor for IMC energy", "Only SRAM-based (volatile, charge/digital-domain) IMC is modeled; non-volatile resistive devices (ReRAM/PCM) with their own nonidealities (drift, variation) are out of scope", "Validation against published chips necessarily relies on authors' reported numbers (often not uniformly reported, e.g., sparsity), introducing validation uncertainty", "Evaluation limited to MLPerf Tiny (edge-scale) models; does not address large-scale CNNs, transformers, or LLMs"], "remarks": "A careful, silicon-validated analytical modeling contribution that directly challenges the common practice of comparing IMC designs purely by peak TOP/s/W or TOP/s/mm2, showing that the AIMC-vs-DIMC ranking is workload- and layer-shape-dependent (unrolling potential matters more than raw peak numbers). Useful reference point for a thesis chapter on benchmarking/mapping onto crossbar/IMC hardware, since it quantifies when analog's density/efficiency advantage actually materializes (high-reuse conv/pointwise layers) versus when it does not (depthwise, FC). Because the model targets SRAM-based (charge-domain) IMC specifically, its conclusions should be validated separately for resistive (ReRAM/PCM) crossbar accelerators, which have different ADC/array cost structures and nonidealities.", "basis": "full-text", "pdf_source_url": "", "abstract": "In-Memory Computing (IMC) has emerged as a promising paradigm for energy-efficient, throughput-efficient and area-efficient machine learning at the edge. However, the differences in hardware architectures, array dimensions, and fabrication technologies among published IMC realizations have made it difficult to grasp their relative strengths. Moreover, previous studies have primarily focused on exploring and bench-marking the peak performance of a single IMC macro rather than full system performance on real workloads. This paper aims to address the lack of a quantitative comparison of Analog In-Memory Computing (AIMC) and Digital In-Memory Computing (DIMC) processor architectures. We propose an analytical IMC performance model that is validated against published implementations and integrated into a system-level exploration framework for comprehensive performance assessments on different work-loads with varying IMC configurations. Our experiments show that while DIMC generally has higher computational density than AIMC, AIMC with large macro sizes may have better energy efficiency than DIMC on convolutional-layers and pointwise-layers, which can exploit high spatial unrolling. On the other hand, DIMC with small macro size outperforms AIMC on depthwise-layers, which feature limited spatial unrolling opportunities inside a macro.", "review": [{"fid": "F8", "text": "ADC/DAC conversion is a first-order cost and it creates a scaling trap: up to 58% of energy and 81% of area, energy exponential in precision; AIMC only beats DIMC once that overhead is amortized over a large array, but larger arrays force higher-resolution ADCs that degrade throughput and computational density.", "grade": "High confidence", "vote": "3 claims merged · 3–0 unanimous", "note": "arXiv 2406.08413 · KU Leuven quantitative IMC benchmarking (ICCAD 2023)"}], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2023_Sun_AIMCvsDIMC_ICCAD.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2023_Sun_AIMCvsDIMC_ICCAD.pdf", "priority": 8.37}, {"id": "W4323022446", "short": "MNSIM 2.0", "title": "MNSIM 2.0: A Behavior-Level Modeling Tool for Processing-In-Memory Architectures", "authors": ["Zhenhua Zhu", "Hanbo Sun", "Tongxin Xie", "Yu Zhu", "Guohao Dai", "Lixue Xia", "Dimin Niu", "Xiaoming Chen", "Xiaobo Sharon Hu", "Yu Kevin Cao", "Yuan Xie", "Huazhong Yang", "Yu Wang"], "year": 2023, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2023.3251696", "cites_global": 72, "cat": "08", "seed": false, "devices": ["ReRAM", "Generic-NVM"], "models": ["CNN"], "evidence": "simulation", "tldr": "MNSIM 2.0 is a behavior-level PIM modeling/simulation tool with a unified analog+digital memory-array model, PIM-aware NN training/quantization flow, and flexible scheduling, validated against fabricated PIM macros to within ~3.8-5.5% error.", "summary": "Successor to the widely used MNSIM simulator, built to address the need for efficient, flexible design-space exploration tools for Processing-In-Memory (PIM) accelerators as NN models and PIM hardware design spaces both grow. At the hardware level, MNSIM 2.0 provides a hierarchical, configurable and extensible modeling structure, including (per the abstract) the first unified PIM memory array model able to describe both digital and analog PIM arrays within the same framework. At the algorithm level, it supports accuracy simulation of PIM-based NN inference accounting for architecture and device non-idealities, and integrates a PIM-oriented NN training/quantization flow intended to recover performance lost to those non-idealities. At the scheduling level, it adopts a universal scheduling description meant to be compatible with multiple different mapping/scheduling strategies, rather than hard-coding one dataflow. The tool is validated against measurements from fabricated PIM macros, reporting a relative modeling error of about 3.8-5.5%, and the authors present case studies using MNSIM 2.0 for design-space exploration, device-parameter sensitivity analysis and architecture-design insight discovery.", "contributions": ["A hierarchical, configurable, extensible behavior-level PIM modeling framework (successor to MNSIM)", "A unified memory-array model spanning both digital and analog PIM arrays", "A PIM-oriented NN training and quantization flow integrated into the simulation loop to improve achievable performance", "A universal scheduling description compatible with multiple scheduling strategies", "Validation against fabricated PIM macros with reported ~3.8-5.5% modeling error, plus case studies for design-space exploration"], "claims": [{"claim": "MNSIM 2.0's behavior-level model matches measured silicon PIM macros closely", "support": "relative modeling error rate of 3.8-5.5% against fabricated PIM macros", "loc": "Abstract"}, {"claim": "The tool enables productive design-space exploration and device/architecture insight discovery", "support": "case studies on PIM design-space exploration, device-parameter influence analysis, and architecture insight discovery (per abstract)", "loc": "Abstract / case studies"}], "results": ["Relative modeling error rate of 3.8-5.5% versus fabricated PIM macros (exact figure as stated in abstract)"], "limitations": ["Abstract-only analysis in this record: no full text available, so method details (exact unified array model, training/quantization algorithm, scheduling description) could not be independently verified", "As a behavior-level simulator, it trades some circuit-level fidelity for speed/flexibility compared to SPICE-level tools"], "remarks": "MNSIM 2.0 is a successor to one of the most cited open PIM simulation frameworks (original MNSIM is an in-set reference of this paper) and is itself cited by many later PIM compiler/simulator papers in this collection (CoMN, CiMLoop, PIMCOMP, PIMapping, etc.), indicating it functions as infrastructure the field builds on. Because only the abstract was available for this analysis, specific quantitative claims beyond the headline validation error could not be extracted; a full-text pass would be valuable given the tool's apparent influence.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "In the age of Artificial Intelligence (AI), the huge data movements between memory and computing units become the bottleneck of von Neumann architectures, i.e., the “memory wall” problem. In order to tackle this challenge, Processing-In-Memory (PIM) architectures are proposed, which perform in-situ computations in memory and give alternative solutions to boost the computing energy efficiency and performance. Because of the large-scale Neural Network (NN) algorithm models and the huge hardware design space, various factors affect computing accuracy and performance, bringing the need for efficient PIM modeling and evaluation tools. In this work, we propose a behavior-level modeling tool, MNSIM 2.0, to model the performance of PIM architectures efficiently. At the hardware level, MNSIM 2.0 provides a hierarchical PIM modeling structure with flexible architecture configurability and components extensibility. Moreover, the first unified PIM memory array model is proposed for describing both digital and analog PIM. At the algorithm level, MNSIM 2.0 supports the PIM-based NN computing accuracy simulation considering various architecture and device parameters. A PIM-oriented NN model training and quantization flow is also integrated to improve the performance gain brought by PIM. At the scheduling level, MNSIM 2.0 adopts a universal scheduling description compatible with different scheduling strategies. Validation using fabricated PIM macros shows the relative modeling error rate of MNSIM 2.0 is 3:8 5:5%. Case studies show that MNSIM 2.0 enables PIM design space explorations, influences analysis of device parameters, and architecture design insight discoveries.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2023_Zhu_MNSIM20_TCAD.pdf", "analysed": true, "pdf": null, "priority": 7.3}, {"id": "W4225637124", "short": "PIMulator-NN", "title": "PIMulator-NN: An Event-Driven, Cross-Level Simulation Framework for Processing-In-Memory-Based Neural Network Accelerators", "authors": ["Qilin Zheng", "Xingchen Li", "Yijin Guan", "Zongwei Wang", "Yimao Cai", "Yiran Chen", "Guangyu Sun", "Ru Huang"], "year": 2022, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2022.3160947", "cites_global": 12, "cat": "08", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "simulation", "tldr": "PIMulator-NN is an event-driven, cross-level simulator for PIM-based neural network accelerators that couples architecture-level event simulation with circuit-level modeling of analog compute units, revealing that memory access and interconnect effects (often missed by performance-model-based estimators) substantially impact system-level latency and energy.", "summary": "Existing performance-model-based estimators for processing-in-memory (PIM) neural-network accelerators often cannot capture fine architectural details such as interconnect and memory-access behavior. PIMulator-NN addresses this with an event-driven simulation engine that models architecture-level timing/behavior while integrating a mainstream circuit-level simulation framework to accurately estimate the area, latency, and energy of analog computation units. The authors implement several representative PIM accelerator designs as templates within PIMulator-NN and run detailed simulations, finding that memory access and interconnects have considerable, sometimes counter-intuitive ('anti-common-sense') effects on system-level performance and energy that conventional performance-model estimators fail to capture. The framework's templates let users quickly assemble and explore their own PIM architecture design space (dataflow, interconnect topology, data parallelism, etc.).", "contributions": ["An event-driven, cross-level (architecture + circuit) simulation framework specifically for PIM-based neural-network accelerators", "Integration of a mainstream circuit-level simulator to accurately model area, latency, and energy of analog compute units within the architectural simulation", "Several implemented architecture templates reproducing representative PIM accelerator designs for quick design-space exploration", "Empirical demonstration that memory access and interconnect effects materially (and sometimes counter-intuitively) affect system-level performance/energy, beyond what conventional performance models capture"], "claims": [{"claim": "Conventional performance-model-based estimations fail to capture the system-level impact of memory access and interconnects in PIM accelerators.", "support": "PIMulator-NN simulations reveal 'anti-common-sense' results for memory access/interconnect impact on performance and energy not visible in performance-model estimates", "loc": "Abstract (full text not available)"}, {"claim": "PIMulator-NN enables users to quickly build and explore PIM architecture design choices (dataflow, interconnect, data parallelism).", "support": "Several architecture templates implemented and demonstrated for rapid PIM design-space exploration", "loc": "Abstract (full text not available)"}], "results": ["Demonstrated on several implemented PIM accelerator designs, showing memory access and interconnects considerably affect system-level performance and energy, with some results contradicting intuitive/common-sense expectations (per abstract; no specific quantitative figures given)"], "limitations": ["Analysis is abstract-only (full text not accessible from this machine) -- validation methodology (e.g., comparison against measured chips or other simulators such as NeuroSim/MNSIM), supported device models, and quantitative accuracy of the circuit-level integration are not verifiable here", "As a simulation-framework paper, its own claims are inherently about relative/architectural insights rather than absolute measured-hardware numbers"], "remarks": "Part of the family of cross-level PIM simulation/benchmarking tools (alongside MNSIM, DNN+NeuroSim, RxNN) that this collection's category 08 depends on; its event-driven architecture-plus-circuit coupling is positioned to capture interconnect/memory-access effects that coarser performance-model-based estimators miss, which is an important methodological point for anyone using simulators to make hardware design or mapping decisions for crossbar/PIM accelerators. Without the full text, the specific validation evidence for its circuit-level accuracy claims could not be assessed here; cited later by ALPINE and MNSIM 2.0, suggesting continued relevance to the simulation/benchmarking sub-literature.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Processing-in-memory (PIM) architecture has been proposed to accelerate state-of-the-art neuro-inspired algorithms, such as deep neural networks. In this article, we present PIMulator-NN, an event-driven, cross-level simulation framework for PIM-based neural network accelerators. By employing an event-driven simulation mechanism, PIMulator-NN is able to model architecture details and capture design details of the architecture. Moreover, we integrate the main-stream circuit-level simulation framework with PIMulator-NN to accurately simulate the area, latency, and energy consumption of analog computation units. To demonstrate the usage of PIMulator-NN, we implement several PIM designs with PIMulator-NN and perform detailed simulation. The simulation results show that memory access and interconnects make considerable impacts on system-level performance and energy. Note that such results are hard to be captured by conventional performance model-based estimations. We found some anti common-sense results while modeling the architecture details with PIMulator-NN. With several architecture templates, PIMulator-NN provides the users with a platform to build up their PIM architecture quickly. PIMulator-NN is able to capture the impacts of different design choices (e.g., dataflow, interconnect, data parallelism, etc.), and this could enable users to explore their design space efficiently.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2022_Zheng_PIMulatorNN_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.58}, {"id": "W4311416617", "short": "SACA", "title": "SACA: System-level Analog CIM Accelerators Simulation Framework: Accurate Simulation of Non-Ideal Components", "authors": ["Fernando Garćıa-Redondo", "Ali BanaGozar", "Kanishkan Vadivel", "Corporaal Henk", "Shidhartha Das"], "year": 2022, "venue": "", "venue_short": "DCIS", "venue_full": "Conference on Design of Circuits and Integrated Systems (DCIS 2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/dcis55711.2022.9970112", "cites_global": 3, "cat": "08", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN", "MLP"], "evidence": "simulation", "tldr": "SACA is a system-level simulation framework for host+CIM-accelerator TinyML systems that models device- and periphery-level non-idealities (including IR-drop) and reports accuracy/energy/performance trade-offs for a CIFAR-10 CNN and a Human Activity Recognition MLP.", "summary": "Always-on TinyML edge accelerators based on non-volatile-memory compute-in-memory (CIM) crossbars are constrained by noise and non-idealities that compromise DNN accuracy. The authors present SACA, a system-level framework that simulates a full host+CIM-accelerator system while accounting for device-level non-idealities and periphery (ADC/DAC and interconnect) characteristics, including IR-drop effects that become severe at larger crossbar sizes. The framework sweeps NVM technology choice, crossbar size, and periphery design to produce energy/performance/accuracy trade-off curves. It is demonstrated on two representative TinyML workloads: a CNN for CIFAR-10 image classification and a fully-connected network for Human Activity Recognition (HAR). The paper emphasizes that IR-drop on larger crossbars substantially degrades accuracy and system reliability, informing crossbar-size and technology choices for edge CIM designs.", "contributions": ["A system-level (host + CIM accelerator) simulation framework, SACA, targeting TinyML edge workloads", "Joint modeling of device-level non-idealities and periphery/circuit-level effects (including IR-drop)", "Exploration across NVM technology, crossbar size and periphery configuration to generate energy/performance/accuracy design curves", "Case studies on a CIFAR-10 CNN and a Human Activity Recognition fully-connected network"], "claims": [{"claim": "IR-drop has a dramatic, size-dependent effect on accuracy and reliability of larger CIM crossbars", "support": "stated as headline finding in the abstract; no numeric values available without full text", "loc": "Results/discussion (abstract-only, page unknown)"}, {"claim": "Crossbar characteristics (NVM technology, size, periphery) can be tuned to find optimal energy/performance/accuracy operating points", "support": "framework capability demonstrated via sweep experiments", "loc": "Experiments section (abstract-only, page unknown)"}], "results": ["Abstract-only: energy/performance/accuracy trade-off curves generated by sweeping NVM technology, crossbar size and periphery characteristics for a CIFAR-10 CNN and a HAR MLP (no specific numbers available without full text)"], "limitations": ["Abstract-only basis: no concrete accuracy/energy numbers verifiable here", "Short conference paper (DCIS) — scope limited to two TinyML-scale workloads, not large-scale CNNs/transformers", "System-level host+accelerator framing suggests coarser-grained modeling than detailed circuit-level simulators (e.g., SPICE-based tools)"], "remarks": "SACA sits in the simulation/benchmarking-framework category alongside NeuroSim-family tools, but is distinguished by its system-level (host+accelerator) scope and explicit focus on IR-drop at the periphery/interconnect level for TinyML-scale (not large CNN) workloads. Its later citation by 'Analog or Digital In-Memory Computing? Benchmarking Through Quantitative Modeling' (2023) suggests it is used as a comparison point for quantitative CIM benchmarking methodology. Without the full text, the depth of circuit modeling (e.g., whether IR-drop is modeled analytically or via SPICE-level simulation) and the quantitative severity of the reported accuracy degradation cannot be independently verified.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Always-ON accelerators running TinyML applications are strongly limited by the memory and computation resources available in edge devices. Compute-In-Memory (CIM) architectures based on non-volatile memories (NVM) promise to bring the required compute and memory demands of Deep Neural Networks (DNN) to the edge while consuming extremely low power. However, their system-level design is constrained by the device and periphery noise which strongly impacts and compromises the accuracy of the DNN workload. In this paper SACA, a framework for simulating host & CIM accelerator systems, is presented. The simulator quantifies the system reliability by taking into account device-level non-idealities. The accuracy of two representative TinyML workloads is analyzed based on the crossbar characteristics -NVM technology, crossbar size, periphery characteristics. To demonstrate the capabilities of SACA, extensive experiments are carried out. We have characterized a convolutional network tackling CIFAR10 image classification and a fully connected network performing Human Activity Recognition. The results lead to optimal energy/performance/accuracy profiles, while the overall analysis highlights the dramatic effects of IR-drop on larger crossbars, degrading the system's accuracy and compromising its reliability.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2022_GarciaRedondo_SACA_DCIS.pdf", "analysed": true, "pdf": null, "priority": 4.32}, {"id": "W4312949026", "short": "IMC-Benchmarking", "title": "Benchmarking In-Memory Computing Architectures", "authors": ["Naresh R. Shanbhag", "Saion K. Roy"], "year": 2022, "venue": "IEEE Open Journal of the Solid-State Circuits Society", "venue_short": "OJSSCS", "venue_full": "IEEE Open Journal of the Solid-State Circuits Society (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/ojsscs.2022.3210152", "cites_global": 48, "cat": "08", "seed": false, "devices": ["SRAM-analog", "Generic-NVM"], "models": [], "evidence": "survey", "tldr": "Proposes a compositional benchmarking methodology and metric set for in-memory-computing (IMC) chips, then applies it to a database of more than 70 published IMC ICs since 2018 to show SRAM-based IMCs beat digital accelerators at the bank level but the gap shrinks at the processor level, eNVM-based IMCs lag both SRAM-IMCs and digital accelerators in compute density, and compute accuracy is widely under-reported.", "summary": "The paper observes that reported IMC energy-efficiency gains appear to be plateauing, but the field lacks a rigorous, consistent way to benchmark designs and identify bottlenecks. It proposes: (1) a compositional view that decomposes an IMC design into canonical components; (2) a set of standardized benchmarking metrics covering performance, energy efficiency, and compute accuracy; and (3) a strategy for analyzing reported data against these metrics. Applying this methodology to an extensive database of metrics extracted from over 70 published IMC IC designs since 2018, the authors find that SRAM-based IMCs have a clear energy-efficiency and compute-density advantage over digital accelerators at the bank level, but that advantage shrinks substantially at the full-processor level; that embedded-NVM (eNVM)-based IMCs lag SRAM-based IMCs in both energy efficiency and compute density, and even lag plain digital accelerators in compute density; and that bank-level compute accuracy -- despite being a critical metric -- and the inherent energy-vs-accuracy trade-off of IMC are rarely reported in the literature.", "contributions": ["A compositional framework that decomposes IMC architectures into canonical building-block components for apples-to-apples comparison", "A set of standardized benchmarking metrics for IMC performance, energy efficiency, and compute accuracy", "An analysis strategy applied to a database of metrics extracted from 70+ published IMC chips since 2018", "Identification of a bank-to-processor-level efficiency gap for SRAM-based IMCs, and of eNVM-based IMCs lagging both SRAM-IMCs and digital accelerators in compute density", "A call-out that compute accuracy and the energy-vs-accuracy trade-off are systematically under-reported in IMC publications"], "claims": [{"claim": "SRAM-based IMCs show a clear energy-efficiency and compute-density advantage over digital accelerators at the bank level, but this advantage shrinks dramatically at the processor level", "support": "stated as a benchmarking finding across the >70-design database", "loc": "Abstract"}, {"claim": "eNVM-based IMCs lag SRAM-based IMCs in both energy efficiency and compute density", "support": "stated finding from the benchmarking database", "loc": "Abstract"}, {"claim": "eNVM-based IMCs surprisingly lag digital accelerators in compute density", "support": "stated finding from the benchmarking database", "loc": "Abstract"}, {"claim": "Bank-level compute accuracy, despite being a critical IMC metric, is pervasively neglected in publications, as is the energy-vs-accuracy trade-off", "support": "stated as a benchmarking observation across the surveyed design database", "loc": "Abstract"}], "results": ["Benchmarking database built from more than 70 published IMC IC designs since 2018", "SRAM-IMC vs. digital-accelerator energy-efficiency/compute-density gap found to be large at the bank level but much smaller at the processor level (magnitude not given in abstract)", "eNVM-based IMCs found to lag both SRAM-IMCs and digital accelerators in compute density (magnitude not given in abstract)"], "limitations": ["Analysis is only as good as the self-reported metrics in the surveyed publications, many of which (per the paper's own finding) omit compute accuracy and energy-accuracy trade-off data", "This entry is based on the abstract only (no full text or PDF was located); specific benchmarking metric definitions, the full device/architecture breakdown, and exact quantitative gaps are not confirmed here", "Cross-paper comparison of chips built in different process nodes and measurement conditions carries inherent benchmarking caveats typical of literature meta-analyses"], "remarks": "A methodology/meta-analysis paper rather than a new device or accelerator design; its value for a thesis on analog/IMC hardware is primarily as a critical, cross-cutting reference for what is and is not reported in the IMC chip literature, and its finding that eNVM-based IMCs lag both SRAM-IMCs and digital accelerators in compute density is a useful counterpoint to many individual eNVM/ReRAM/PCM papers that emphasize energy efficiency without equally emphasizing compute density or accuracy. Because only the abstract was available, the magnitude of the reported gaps and the precise definition of the proposed metrics could not be verified here and should be checked against the full text before citing specific numbers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "In-memory computing (IMC) architectures have emerged as a compelling platform to implement energy efficient machine learning (ML) systems. However, today, the energy efficiency gains provided by IMC designs seem to be leveling off and it is not clear what the limiting factors are. The conceptual complexity of IMCs combined with the absence of a rigorous benchmarking methodology makes it difficult to gauge progress and identify bottlenecks in this exciting field. This paper presents a benchmarking methodology for IMCs comprising: 1) a compositional view of IMCs that enables one to parse an IMC design into its canonical components; 2) a set of benchmarking metrics to quantify the performance, efficiency, and accuracy of IMCs; and 3) a strategy for analyzing the reported IMC data and metrics. We apply the proposed benchmarking methodology on an extensive database of IMC metrics extracted from >70 IC designs published since 2018, in order to infer and comprehend trends in this area. Our benchmarking effort indicates: 1) SRAM-based IMCs show a clear win in terms of energy efficiency and compute density over digital accelerators at the bank-level but the energy efficiency gap reduces dramatically when comparing at the processor level; 2) eNVM-based IMCs lag behind SRAM-based IMCs in terms of both energy efficiency and compute density, and surprisingly lag digital accelerators in terms of compute density; 3) the compute (bank-level) accuracy of IMCs, though a critical metric, is pervasively neglected in publications as is the energy vs. accuracy trade-off inherent to IMCs.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2022_Shanbhag_IMCBenchmarking_OJSSCS.pdf", "analysed": true, "pdf": null, "priority": 6.28}, {"id": "W3148526109", "short": "IBM AIHWKIT", "title": "A Flexible and Fast PyTorch Toolkit for Simulating Training and Inference on Analog Crossbar Arrays", "authors": ["Malte J. Rasch", "Diego Moreda", "Tayfun Gokmen", "Manuel Le Gallo", "Fabio Carta", "Cindy Goldberg", "Kaoutar El Maghraoui", "Abu Sebastian", "Vijay Narayanan"], "year": 2021, "venue": "", "venue_short": "AICAS", "venue_full": "2021 IEEE 3rd International Conference on Artificial Intelligence Circuits and Systems (AICAS 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/aicas51828.2021.9458494", "cites_global": 145, "cat": "08", "seed": false, "devices": ["ReRAM", "PCM", "Generic-NVM"], "models": ["CNN", "MLP"], "evidence": "algorithm+simulation", "tldr": "Introduces the IBM Analog Hardware Acceleration Kit (aihwkit), an open-source PyTorch toolkit built around a C++/CUDA 'analog tile' abstraction that simulates training and inference on analog crossbar arrays with configurable device non-idealities (noise, D2D/cycle-to-cycle variation, drift), including PCM-calibrated inference noise models and Tiki-Taka-style analog optimizers, running full analog-pulsed training at only 2-5x the cost of floating-point training.", "summary": "The paper presents a software-engineering and research-infrastructure contribution rather than a new accelerator or device: the lack of a flexible, PyTorch-native, GPU-accelerated simulator for analog in-memory training and inference motivated IBM to open-source its internal analog AI simulation core as the 'IBM Analog Hardware Acceleration Kit' (aihwkit, pip-installable, Apache-2.0). The toolkit centers on an 'analog tile' abstraction representing a 2D weight matrix on a resistive crossbar, with a highly optimized C++/CUDA (RpuCuda) backend bound to Python/PyTorch so users can build AnalogLinear/AnalogConv layers and train them with an AnalogSGD optimizer. Unlike DNN+NeuroSim, which approximates the analog update by accumulating gradients digitally before discretizing, aihwkit performs the rank-1 update directly in analog via stochastic pulse trains for every example (even with batch size >1 or convolutions), giving a more faithful estimate of update noise. It supports configurable device-to-device and cycle-to-cycle variation, non-linear conductance response curves (with presets calibrated on measured ReRAM and PCM data), unit-cell constructs for multi-device-per-crosspoint designs, Tiki-Taka-style coupled-tile optimizers, and a dedicated inference-tile mode with PCM-calibrated programming noise, read noise, conductance drift and global drift compensation for hardware-aware training. The authors emphasize it targets functional/accuracy verification only, not performance (latency/power/area) estimation, and report that full pulsed analog training on GPU takes only about 2-5x longer than standard floating-point training (e.g., ~60s/epoch vs ~15s/epoch for VGG-8/CIFAR-10 on a V100).", "contributions": ["Open-sourced the IBM Analog Hardware Acceleration Kit (aihwkit), a PyTorch-native, GPU-accelerated analog crossbar simulator (pip install aihwkit)", "An 'analog tile' / rpu_config abstraction that cleanly separates digital and analog operations and lets users compose arbitrary ANNs with mixed analog/digital layers", "A C++/CUDA core (RpuCuda) that performs the rank-1 weight update directly in analog via stochastic pulse trains (not via digital gradient accumulation as in DNN+NeuroSim), giving more realistic update-noise estimates for batch size >1 and convolutions", "Statistical programming-noise and conductance-drift models calibrated on measured PCM hardware, plus measured ReRAM pulse-response presets, enabling hardware-aware inference training and long-term drift evaluation", "Support for advanced analog optimizers (e.g., Tiki-Taka via TransferCompound/unit-cell constructs) and modular, extensible device models"], "claims": [{"claim": "aihwkit's in-place analog update avoids the dramatic under-estimation of update noise produced by DNN+NeuroSim's digital-accumulation approach", "support": "qualitative architectural argument: DNN+NeuroSim accumulates p outer products digitally before discretizing, while aihwkit reimplements conv/linear ops to perform the rank-1 update in analog for every example", "loc": "Sec. 3 (page 7)"}, {"claim": "The toolkit's simulated ReRAM pulse-response and PCM drift models match measured device data", "support": "Fig. 3 comparison of AIHWKIT model vs. ReRAM measurement (Gong et al.) and PCM measurement (Joshi et al.)", "loc": "Sec. 3, Fig. 3"}, {"claim": "Full GPU-accelerated pulsed analog training adds only modest runtime overhead versus standard floating-point training", "support": "~60s/epoch for VGG-8/CIFAR10 with parallel pulsed update vs ~15s/epoch floating point on a V100 GPU (2-5x overhead, DNN/setting dependent)", "loc": "Sec. 3, footnote 3"}], "results": ["Analog pulsed training runs at roughly 2-5x the wall-clock time of floating-point training depending on DNN and device setting (example: ~60s vs ~15s per epoch for VGG-8/CIFAR-10 on a V100 GPU)", "Simulated ReRAM pulse-response (with device-to-device, write noise and cycle-to-cycle variation) qualitatively matches 500-pulse measured ReRAM data from Gong et al. (Fig. 3B)", "Simulated PCM conductance drift over ~10^5 s matches measured PCM temporal evolution from Joshi et al., aside from small deviations at short times (<1000 s) due to simultaneous-programming assumption (Fig. 3C)"], "limitations": ["Explicitly a functional/accuracy simulator only; does not estimate runtime, latency, area or power of actual hardware chips", "Inference noise/drift calibration is based on a single PCM device array dataset (Joshi et al., 1M devices); generality to other PCM arrays or other NVM technologies for drift is not separately validated here", "Assumes all weights are programmed simultaneously in the drift simulation, unlike real devices which converge/start drifting at different times, causing minor discrepancies at short timescales", "Currently supports only parallel read-out schemes and linear ADC; iterative read-out and more complex (e.g., shift-and-add) ADC schemes are not yet implemented", "No large-scale DNN or multi-model benchmark results are reported in this short conference paper itself (examples are illustrative, e.g. single-layer and VGG-8)"], "remarks": "This is the original aihwkit paper, now a de-facto standard open-source simulation tool in the analog/PCM in-memory-computing community (145+ citations by 2025, used or extended by many later papers in this set such as AnalogNAS, CiMLoop citations, and IBM's own hardware-aware training studies). Its significance for mapping AI models onto analog crossbars is primarily infrastructural: by performing updates genuinely in-analog (rather than approximating via digital gradient accumulation as DNN+NeuroSim does) it offers more faithful noise/drift estimates for both inference and on-chip training, making it a common baseline/tool citation rather than a hardware or accuracy result in itself.", "basis": "full-text", "pdf_source_url": "", "abstract": "We introduce the IBM ANALOG HARDWARE ACCELERATION KIT, a new and first of a kind open source toolkit to simulate analog crossbar arrays in a convenient fashion from within PYTORCH (freely available at https://github.com/IBM/aihwkit). The toolkit is under active development and is centered around the concept of an “analog tile” which captures the computations performed on a crossbar array. Analog tiles are building blocks that can be used to extend existing network modules with analog components and compose arbitrary artificial neural networks (ANNs) using the flexibility of the PYTORCH framework. Analog tiles can be conveniently configured to emulate a plethora of different analog hardware characteristics and their non-idealities, such as device-to-device and cycle-to-cycle variations, resistive device response curves, and weight and output noise. Additionally, the toolkit makes it possible to design custom unit cell configurations and to use advanced analog optimization algorithms such as Tiki-Taka. Moreover, the backward and update behavior can be set to “ideal\" to enable hardware-aware training features for chips that target inference acceleration only. To evaluate the inference accuracy of such chips over time, we provide statistical programming noise and drift models calibrated on phase-change memory hardware. Our new toolkit is fully GPU accelerated and can be used to conveniently estimate the impact of material properties and non-idealities of future analog technology on the accuracy for arbitrary ANNs.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2021_Rasch_AIHWKIT_AICAS.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2021_Rasch_AIHWKIT_AICAS.pdf", "priority": 8.59}, {"id": "W3006908002", "short": "TxSim", "title": "TxSim: Modeling Training of Deep Neural Networks on Resistive Crossbar Systems", "authors": ["Sourjya Roy", "Shrihari Sridharan", "Shubham Jain", "Anand Raghunathan"], "year": 2021, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems (2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2021.3063543", "cites_global": 54, "cat": "08", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "TxSim is a fast, BLAS-mapped functional simulator for DNN training on resistive crossbars that models non-idealities in forward, backward, and weight-update operations, achieving 6x-108x speedup over prior tools while showing training accuracy can degrade 3%-36.4% due to crossbar non-idealities.", "summary": "The paper addresses the lack of fast, comprehensive tools for modeling how crossbar device/circuit non-idealities affect DNN training (as opposed to inference-only tools, or training tools too slow for large-scale DNNs). TxSim maps crossbar vector-matrix-multiply evaluations onto highly optimized BLAS routines within standard ML frameworks, and models non-idealities (IR-drop-like effects, device non-linearity, stochastic write noise, update non-linearity) across all three training phases: forward propagation, backward propagation, and weight update. To keep simulation tractable for large networks, it introduces two speedup techniques, an approximate analytical model (AAM) and an interpolated fast crossbar model (interpolated-FCM), that trade a small amount of fidelity for large runtime savings. The framework is validated on LeNet-5/AlexNet (MNIST), ResNet-56 (CIFAR-100), and ResNet-18 (Tiny-ImageNet), comparing ideal vs. non-ideal crossbar training and performing sensitivity analysis over device/circuit parameters (resistance range, non-linearity, stochastic noise, Rmax/Rmin ratio).", "contributions": ["A customizable functional-simulation framework (TxSim) that models crossbar non-idealities during all three DNN training phases (forward, backward, weight update), unlike prior inference-only tools", "A BLAS-routine-based simulation approach that is 6x-108x faster than prior crossbar training simulators (e.g., CrossSim), making large-scale DNN training simulation feasible", "Two speedup techniques, approximate analytical model (AAM) and interpolated-FCM, balancing modeling fidelity against runtime", "An application-level accuracy study across network scales (LeNet-5/AlexNet up to ResNet-56/ResNet-18) quantifying the accuracy degradation due to crossbar non-idealities", "A sensitivity analysis of crossbar/device parameters (resistance range, non-linearity factor, stochastic noise factor, Rmax/Rmin) on training accuracy"], "claims": [{"claim": "TxSim is dramatically faster than prior crossbar training simulators", "support": "108x simulation speedup compared to CrossSim, and 6x-108x speedup over prior frameworks overall", "loc": "Sec. VI.A, Conclusion"}, {"claim": "Crossbar-based DNN training simulation is noticeably slower than native GPU training but tractable", "support": "software simulation of DNN training on a crossbar-based system is 14x slower than native training on an Nvidia GTX 1080 Ti GPU (64x64 crossbar, batch size 128)", "loc": "Sec. VI.A, Fig. 7"}, {"claim": "Crossbar non-idealities cause substantial, network-dependent accuracy degradation", "support": "accuracy degradation due to crossbar non-idealities (Cross-NI vs. Cross-Ideal) is 3%-36.4% across benchmarks, more pronounced for complex ResNet-56/VGG-16 than simple LeNet-5/AlexNet", "loc": "Sec. VI.B, Figs. 8-9"}, {"claim": "Stochastic write noise must be kept below a threshold to avoid significant accuracy loss", "support": "for stochastic noise factor gamma=1 and gamma=5 the accuracy drop is almost negligible, but gamma=10 causes a ~10% drop; recommend non-linearity factor within 0.1 and noise factor within 5", "loc": "Sec. VI.C (Sensitivity Analysis)"}], "results": ["108x simulation speedup vs. CrossSim; 6x-108x speedup over prior frameworks overall", "14x slower than native GPU (GTX 1080 Ti) training, using a 64x64 crossbar (Rmin=100kOhm, Rmax=1MOhm, non-linearity v=0.01, noise factor gamma=5)", "3%-36.4% accuracy degradation from crossbar non-idealities across LeNet-5, AlexNet, ResNet-56/CIFAR-100, ResNet-18/Tiny-ImageNet", "Noise factor gamma=10 causes ~10% accuracy drop, vs. negligible drop at gamma=1 or 5"], "limitations": ["Purely a functional/software modeling tool; no physical crossbar hardware or fabricated chip validation", "Speedup techniques (AAM, interpolated-FCM) trade some modeling fidelity for runtime, and the paper acknowledges this impacts accuracy slightly", "Benchmarks limited to CIFAR-100/Tiny-ImageNet scale (ResNet-56/18), not full ImageNet-1k or transformer-scale models", "Device non-ideality model uses fixed analytical parameters (resistance range, non-linearity, Gaussian noise) rather than data fitted from a specific fabricated device"], "remarks": "TxSim fills an important gap identified by several other papers in this collection (e.g., PANTHER, DNN+NeuroSim) by being one of the first fast, full-training-loop (not just inference) non-ideality simulator, enabling practical exploration of crossbar training accuracy trade-offs at ResNet scale. Its headline finding -- that non-idealities can degrade training accuracy by up to 36% and that deeper/more complex networks are more sensitive -- is an important caution for any crossbar-training proposal, though it rests on a generic analytical non-ideality model rather than measured device statistics, so the specific percentages should be read as illustrative rather than device-specific predictions.", "basis": "full-text", "pdf_source_url": "", "abstract": "Deep neural networks (DNNs) have gained tremendous popularity in recent years due to their ability to achieve superhuman accuracy in a wide variety of machine learning tasks. However, the compute and memory requirements of DNNs have grown rapidly, creating a need for energy-efficient hardware. Resistive crossbars have attracted significant interest in the design of the next generation of DNN accelerators due to their ability to natively execute massively parallel vector-matrix multiplications within dense memory arrays. However, crossbar-based computations face a major challenge due to device and circuit-level nonidealities, which manifest as errors in the vector-matrix multiplications and eventually degrade DNN accuracy. To address this challenge, there is a need for tools that can model the functional impact of nonidealities on DNN training and inference. Existing efforts toward this goal are either limited to inference or are too slow to be used for large-scale DNN training. We propose TxSim, a fast and customizable modeling framework to functionally evaluate DNN training on crossbar-based hardware considering the impact of nonidealities. The key features of TxSim that differentiate it from prior efforts are: 1) it comprehensively models nonidealities during all training operations (forward propagation, backward propagation, and weight update) and 2) it achieves computational efficiency by mapping crossbar evaluations to well-optimized Basic Linear Algebra Subprograms (BLAS) routines and incorporates speedup techniques to further reduce simulation time with minimal impact on accuracy. TxSim achieves 6×- 108× improvement in simulation speed over prior works, and thereby makes it feasible to evaluate the training of large-scale DNNs on crossbars. Our experiments using TxSim reveal that the accuracy degradation in DNN training due to nonidealities can be substantial (3%-36.4%) for large-scale DNNs and data sets, underscoring the need for further research in mitigation techniques. We also analyze the impact of various device and circuit-level parameters and the associated nonidealities to provide key insights that can guide the design of crossbar-based DNN training accelerators.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2021_Roy_TxSim_TVLSI.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2021_Roy_TxSim_TVLSI.pdf", "priority": 7.21}, {"id": "W3112740243", "short": "DNN+NeuroSim V2.0", "title": "DNN+NeuroSim V2.0: An End-to-End Benchmarking Framework for Compute-in-Memory Accelerators for On-Chip Training", "authors": ["Xiaochen Peng", "Shanshi Huang", "Hongwu Jiang", "Anni Lu", "Shimeng Yu"], "year": 2020, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2020.3043731", "cites_global": 308, "cat": "08", "seed": false, "devices": ["ReRAM", "FeFET", "ECRAM", "SRAM-analog", "Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "DNN+NeuroSim V2.0 extends the NeuroSim/PyTorch benchmarking framework from inference to on-chip training, modeling nonlinearity, asymmetry, device-to-device and cycle-to-cycle weight-update variations to benchmark CIM accelerators (SRAM, RRAM, FeFET, EpiRAM, ECRAM) for VGG-8/CIFAR-10.", "summary": "The paper addresses the lack of a benchmarking tool for on-chip (in-situ) training on compute-in-memory (CIM) accelerators built from emerging non-volatile memories (eNVMs). It extends the DNN+NeuroSim inference framework with a Python/PyTorch wrapper that injects non-ideal weight-update behavior (nonlinearity/asymmetry, device-to-device variation, cycle-to-cycle variation) into training, and adds NeuroSim-core peripheral circuitry (transposable synaptic arrays, SRAM-based weight-gradient units) to estimate area, latency, energy, throughput and energy efficiency per training epoch. The framework maps a four-step training pipeline (feed-forward, error backpropagation, weight-gradient computation, weight update) onto a chip/tile/PE/synaptic-array hierarchy, using a 'pseudo-traced' estimation method to keep simulation time tractable. It benchmarks SRAM (7nm/32nm, sequential and parallel read-out) against RRAM, FeFET and EpiRAM devices (32nm) training VGG-8 on CIFAR-10, with momentum optimization to counter nonlinearity. Results show cycle-to-cycle variation below 1%, on-state resistance above 100 kOhm, and nonlinearity within +-3 are the key specs for good training accuracy and hardware efficiency.", "contributions": ["First open-source end-to-end framework (DNN+NeuroSim V2.0) benchmarking CIM accelerators specifically for on-chip training, not just inference", "Behavioral models for nonlinearity/asymmetry, device-to-device and cycle-to-cycle weight-update variation integrated into a PyTorch wrapper", "Transposable synaptic array designs (SRAM, two-terminal eNVM, three-terminal eNVM) supporting both feed-forward and backpropagation on the same array", "'Pseudo-traced' estimation method and per-epoch hardware/accuracy reporting to keep training-accuracy co-simulation tractable", "Cross-technology benchmark (SRAM at 7nm/32nm vs. RRAM/FeFET/EpiRAM/ECRAM at 32nm) identifying key device specs for in-situ training"], "claims": [{"claim": "With momentum optimization, in-situ training reaches ~85% accuracy with moderate asymmetric nonlinearity (NL=+3/-3) and ~77% even with large nonlinearity (NL=+6/-6)", "support": "VGG-8/CIFAR-10 training-accuracy sweep with momentum beta=0.9", "loc": "Sec. IV.A, Fig. 10-11"}, {"claim": "Cycle-to-cycle variation is the most critical non-ideal factor for in-situ training accuracy and should be kept below 1%", "support": "accuracy drops significantly as C2C sigma increases from 1% to 5% of conductance range", "loc": "Sec. IV.A, Fig. 12; Sec. IV.D"}, {"claim": "FeFET-based design achieves ~91% accuracy on VGG-8/CIFAR-10 even with only 32 conductance levels (5-bit) under momentum + low cycle-to-cycle variation", "support": "Table I technology benchmark", "loc": "Sec. IV.D, Table I"}, {"claim": "Desired analog synaptic device specs for on-chip training are: C2C variation <1%, on-state resistance >100 kOhm, write pulse width <1 microsecond, nonlinearity within +3/-3", "support": "summary of cross-technology benchmark conclusions", "loc": "Sec. V (Conclusion)"}], "results": ["FeFET-based CIM training on VGG-8/CIFAR-10 reaches ~91% accuracy at 32 conductance levels (5-bit) with momentum and low C2C variation (Table I)", "With momentum, moderate asymmetric nonlinearity (+3/-3) preserves ~85% accuracy vs ~77% at large nonlinearity (+6/-6) (Fig. 10-11)", "Weight-gradient computation (SRAM-based CIM) dominates total latency and energy per epoch versus feed-forward, error computation and weight update (Fig. 13-14)", "Parallel-readout SRAM at 7nm shows superior energy efficiency and throughput versus other technologies/nodes at the same precision (Sec. IV.D)"], "limitations": ["Simulation-only framework; no silicon measurements, relies on SPICE-calibrated circuit models across nodes", "Assumes feed-forward, error, weight-gradient and weight-update phases do not overlap (no pipelining across the four steps), limiting achievable throughput estimates", "Pseudo-traced estimation for weight-gradient computation approximates row/column activity rather than using full per-cycle real traces", "Benchmarked on a single, relatively small network (VGG-8/CIFAR-10); ResNet-18 support mentioned but not benchmarked in this paper", "Each synaptic weight assumed represented by a single device cell (precision tied directly to device level count), which may not reflect all real designs"], "remarks": "This is a widely used community benchmarking tool (300+ citations) that extended the earlier NeuroSim/DNN+NeuroSim inference framework to on-chip training, and its device-spec guidance (low C2C variation, high Ron, low write pulse width) is frequently cited by later device and architecture papers as target specs. Because it is a simulation framework rather than a single accelerator design, its main contribution is methodological: the hierarchical chip/tile/PE/array mapping and non-ideality models it introduces became a reference point for subsequent compute-in-memory training simulators (e.g., TxSim, MINT, CoMN) cited by later papers in this set.", "basis": "full-text", "pdf_source_url": "", "abstract": "DNN+NeuroSim is an integrated framework to benchmark compute-in-memory (CIM) accelerators for deep neural networks, with hierarchical design options from device-level, to circuit level and up to algorithm level. A python wrapper is developed to interface NeuroSim with a popular machine learning platform: Pytorch, to support flexible network structures. The framework provides automatic algorithm-to-hardware mapping, and evaluates chip-level area, energy efficiency and throughput for training or inference, as well as training/inference accuracy with hardware constraints. Our prior inference version of DNN+NeuroSim framework available athttps://github.com/neurosim/DNN_NeuroSim_V1.2was developed to estimate the impact of reliability in synaptic devices, and analog-to-digital converter (ADC) quantization loss on the accuracy and hardware performance of an inference engine. In this work, we further investigated the impact of the “analog” emerging nonvolatile memory (eNVM)’s nonideal device properties for on-chip training. By introducing the nonlinearity, asymmetry, device-to-device and cycle-to-cycle variation of weight update into the python wrapper, and peripheral circuits for error/weight gradient computation in NeuroSim core, we benchmarked CIM accelerators based on state-of-the-art SRAM and eNVM devices for VGG-8 on CIFAR-10 dataset, revealing the crucial specs of synaptic devices for on-chip training. The latest training version of the DNN+NeuroSim framework is available athttps://github.com/neurosim/DNN_NeuroSim_V2.1.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2020_Peng_DNNNeuroSimV2_TCAD.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2020_Peng_DNNNeuroSimV2_TCAD.pdf", "priority": 8.48}, {"id": "W2909715355", "short": "RxNN", "title": "RxNN: A Framework for Evaluating Deep Neural Networks on Resistive Crossbars", "authors": ["Shubham Jain", "Abhronil Sengupta", "Kaushik Roy", "Anand Raghunathan"], "year": 2020, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2020.3000185", "cites_global": 136, "cat": "08", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "RxNN is a fast crossbar-nonideality simulation framework, built on a circuit-calibrated Fast Crossbar Model (FCM), that finds large ImageNet-scale CNNs lose 9.6-32% accuracy on non-ideal resistive crossbars.", "summary": "The paper addresses the gap between slow, accurate SPICE-level crossbar models and the need to evaluate non-idealities (driver/sensing resistance, sneak paths, interconnect parasitics, nonlinear ADC/DAC, stochastic writes, process variation) on large-scale DNNs. It proposes the Fast Crossbar Model (FCM), which pre-solves the crossbar's voltage-current (Kirchhoff/Ohm) equations once per array to obtain an equivalent non-ideal conductance matrix, plus nonlinear peripheral (DAC/ADC) models, so that subsequent VMM evaluation is a single matrix multiply rather than a circuit simulation. RxNN integrates FCM into the Caffe framework, splitting/mapping each DNN layer's computation onto crossbar tiles of a given size (16x16/32x32/64x64) and evaluates six large ImageNet-scale networks (AlexNet, VGG-16, GoogleNet, NiN, OverFeat, ResNet-50) plus two small networks (LeNet, ConvNet). Results show FCM matches HSPICE far more closely than the simplified MNSIM error model, achieves ~5 orders-of-magnitude speedup over HSPICE, and that large-scale DNNs suffer substantial accuracy loss from non-idealities (up to 32% for ResNet-50) versus negligible loss for small networks, which model-in-the-loop re-training can only partially recover.", "contributions": ["Fast Crossbar Model (FCM): a pre-solved equivalent non-ideal conductance matrix plus nonlinear DAC/ADC models that replace per-inference circuit simulation with a single matrix-vector multiply", "RxNN: integration of FCM into Caffe to enable functional, layer-wise crossbar-mapped evaluation of large-scale DNNs including model-in-the-loop re-training", "First (claimed) quantitative study of crossbar non-ideality impact on application-level accuracy for large-scale ImageNet DNNs (vs. prior work limited to small networks/MNIST)", "Systematic comparison of FCM vs. HSPICE and vs. a simplified architectural error model (MNSIM), and an energy/accuracy trade-off study across 16x16/32x32/64x64 crossbar sizes"], "claims": [{"claim": "FCM matches HSPICE-level circuit simulation far more closely than a simplified architectural error model (MNSIM)", "support": "max deviation from HSPICE is 0.28% for FCM vs 3.51% for MNSIM", "loc": "Sec. VIII-A, Fig. 10"}, {"claim": "FCM is dramatically faster than HSPICE while preserving accuracy", "support": "~5 orders of magnitude speedup, increasing with crossbar size", "loc": "Sec. VIII-A, Fig. 11"}, {"claim": "Non-idealities cause large accuracy loss for large-scale DNNs but negligible loss for small networks on a 64x64 crossbar", "support": "LeNet 0.05%, ConvNet 2.2%, vs. VGG-16 25.6%, OverFeat 27.8%, ResNet-50 32% accuracy degradation", "loc": "Sec. VIII-B, Fig. 12(a)"}, {"claim": "Larger crossbar arrays are more energy efficient but suffer greater accuracy degradation from non-idealities", "support": "Cross16 < Cross32 < Cross64 in both energy consumption and accuracy degradation trend", "loc": "Sec. VIII-B, Fig. 12"}, {"claim": "Re-training with RxNN partially but not fully recovers accuracy lost to non-idealities", "support": "~9%, ~8%, ~26% accuracy improvement after 150 re-training iterations for AlexNet, VGG-16, GoogleNet respectively", "loc": "Sec. VIII-D, Fig. 15"}, {"claim": "RxNN's crossbar-aware simulation adds modest runtime overhead relative to plain Caffe", "support": "2.5x slowdown for inference and 2.75x for re-training vs. baseline Caffe", "loc": "Sec. VIII-B"}], "results": ["FCM max deviation from HSPICE: 0.28% (vs 3.51% for MNSIM error model)", "FCM speedup over HSPICE: ~5 orders of magnitude", "Accuracy degradation on Cross64 (64x64 crossbar): LeNet 0.05%, ConvNet 2.2%, VGG-16 25.6%, OverFeat 27.8%, ResNet-50 32%", "Re-training accuracy recovery after 150 iterations: ~9% (AlexNet), ~8% (VGG-16), ~26% (GoogleNet)", "RxNN overhead vs. baseline Caffe: 2.5x (inference), 2.75x (re-training)", "Model generation (one-time) overhead: 0.038s / 1.2s / 61s for 16x16 / 32x32 / 64x64 crossbars"], "limitations": ["FCM is calibrated against a specific in-house spintronic/ReRAM-like synaptic device model at 45nm and specific ADC/DAC circuit designs from prior work; generality to other device technologies is not separately validated", "The conductance-matrix pre-solve approach assumes a static non-ideal crossbar state per weight programming; it is a steady-state approximation, not a full transient circuit solve", "Re-training uses a straight-through-style approach that assumes forward/backward passes are contiguous and differentiable despite the crossbar abstraction not strictly ensuring this (noted by the authors as a caveat)", "Evaluation is simulation-only (no measured silicon)"], "remarks": "RxNN is an influential, carefully validated simulation-level contribution: by replacing circuit simulation with a pre-solved equivalent conductance matrix, it made application-scale (ImageNet) non-ideality studies computationally tractable for the first time, and its 9.6-32% accuracy-degradation numbers for large CNNs are widely cited as evidence that non-ideality-aware training/mitigation is not optional at scale. It is one of several circuit-calibrated simulators from this era (along with MNSIM and later TxSim) and is frequently used as a baseline/tool by later hardware-aware-training and fault-tolerance papers. Its limitation is that it is still a behavioral approximation of circuit effects (not measured hardware), and it targets a specific device/circuit parameterization, so absolute accuracy-degradation numbers should be read as illustrative of trend and order of magnitude rather than device-agnostic truth.", "basis": "full-text", "pdf_source_url": "", "abstract": "Resistive crossbars designed with nonvolatile memory devices have emerged as promising building blocks for deep neural network (DNN) hardware, due to their ability to compactly and efficiently realize vector-matrix multiplication (VMM), the dominant computational kernel in DNNs. However, a key challenge with resistive crossbars is that they suffer from a range of device and circuit level nonidealities, such as driver resistance, sensing resistance, sneak paths, interconnect parasitics, nonlinearities in the peripheral circuits, stochastic write operations, and process variations. These nonidealities can lead to errors in VMMs, eventually degrading the DNN's accuracy. It is therefore critical to study the impact of crossbar nonidealities on the accuracy of large-scale DNNs (with millions of neurons and billions of synaptic connections). However, this is challenging because the existing device and circuit models are too slow to use in application-level evaluations. We present RxNN, a fast and accurate simulation framework to evaluate large-scale DNNs on resistive crossbar systems. RxNN splits and maps the computations involved in each DNN layer into crossbar operations, and evaluates them using a fast crossbar model (FCM) that accurately captures the errors arising due to crossbar nonidealities while being four-to-five orders of magnitude faster than circuit simulation. FCM models a crossbar-based VMM operation using three stages-nonlinear models for the input and output peripheral circuits (digital-to-analog and analog-to-digital converters), and an equivalent nonideal conductance matrix for the core crossbar array. We implement RxNN by extending the Caffe machine learning framework and use it to evaluate a suite of six large-scale DNNs developed for the ImageNet Challenge (ILSVRC). Our experiments reveal that resistive crossbar nonidealities can lead to significant accuracy degradations (9.6%-32%) for these large-scale DNNs. To the best of our knowledge, this article is the first quantitative evaluation of the accuracy of large-scale DNNs on resistive crossbar-based hardware. We also demonstrate that RxNN enables fast model-in-the-loop retraining of DNNs to partially mitigate the accuracy degradation.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2020_Jain_RxNN_TCAD.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2020_Jain_RxNN_TCAD.pdf", "priority": 7.68}, {"id": "W3011221635", "short": "GENIEx", "title": "GENIEx: A Generalized Approach to Emulating Non-Ideality in Memristive Xbars using Neural Networks", "authors": ["Indranil Chakraborty", "Mustafa Ali", "Dong Eun Kim", "Aayush Ankit", "Kaushik Roy"], "year": 2020, "venue": "", "venue_short": "DAC", "venue_full": "ACM/IEEE Design Automation Conference (DAC 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/dac18072.2020.9218688", "cites_global": 109, "cat": "08", "seed": false, "devices": ["Memristor(generic)"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "GENIEx trains a neural network on extensive HSPICE data to emulate data-dependent (nonlinear) memristive crossbar non-idealities, achieving 7x-12.8x lower RMSE than analytical models and showing that analytical non-ideality models overestimate DNN accuracy degradation by up to ~12% (CIFAR-100) and ~4-6.5% (ImageNet).", "summary": "The paper targets the inaccuracy of purely analytical (linear, non-data-dependent) models of crossbar non-idealities such as parasitic wire resistance and the memristor's non-linear I-V characteristic. It generates extensive HSPICE simulation data over voltage/conductance combinations and trains a neural network (GENIEx) to learn the non-ideal transfer function of a crossbar, capturing data-dependent non-linear effects that analytical models cannot. GENIEx is then embedded in a functional simulator that models architectural facets like tiling and bit-slicing, and is used to evaluate classification accuracy of ResNet-20 on CIFAR-100 and ResNet-18 on a subset of ImageNet, comparing GENIEx-predicted accuracy degradation against that predicted by a conventional linear analytical model. The paper also studies the sensitivity of non-ideality impact to crossbar size, ON resistance, ON/OFF ratio, and bit-slicing (stream/slice width) configuration.", "contributions": ["A neural-network-based emulator (GENIEx) trained on HSPICE data that captures data-dependent, non-linear crossbar non-idealities, unlike prior analytical (non-data-dependent) models", "A functional simulator incorporating GENIEx along with tiling and bit-slicing to evaluate large-scale DNN classification accuracy under realistic crossbar non-idealities", "Quantification of how much purely analytical non-ideality models overestimate DNN accuracy degradation relative to GENIEx, across CIFAR-100 and ImageNet", "A design-space sensitivity study of crossbar size, ON resistance, conductance ON/OFF ratio, and bit-slicing (stream/slice width) on non-ideality impact"], "claims": [{"claim": "GENIEx models crossbar transfer characteristics much more accurately than an analytical model", "support": "GENIEx achieves RMSE of 0.25 (at Vsupply=0.25V) and 0.7 (at Vsupply=0.5V) vs. HSPICE, which is 7x and 12.8x lower than an analytical model, respectively", "loc": "Abstract, Conclusion, Sec. on evaluation (around line 438-457)"}, {"claim": "Analytical non-ideality models overestimate DNN accuracy degradation relative to GENIEx", "support": "analytical model overestimates accuracy degradation by >=10% (up to 12.34%) on CIFAR-100 and 3.7%-6.49% on ImageNet compared to GENIEx, depending on bit precision (16-bit vs 8-bit)", "loc": "Sec. 5 (Results), Conclusion"}, {"claim": "Lower bits-per-device and smaller crossbars with higher ON resistance reduce non-ideality impact", "support": "packing lower bits per device as well as using low crossbar sizes with higher ON resistances is necessary to minimize the impact of non-idealities (sensitivity analysis over crossbar-size, Ron, on/off ratio, stream/slice width)", "loc": "Conclusion, Sec. on sensitivity analysis"}, {"claim": "Floating-point baseline accuracies are high, so degradation estimates are measured against a strong reference", "support": "ideal floating point 32-bit accuracies for CIFAR-100 and ImageNet subset are 69.6% and 76.01% respectively", "loc": "Sec. 5 (Evaluation setup)"}], "results": ["GENIEx RMSE vs. HSPICE: 0.25 (Vsupply=0.25V), 0.7 (Vsupply=0.5V) -- 7x and 12.8x better than an analytical model", "Analytical model overestimates accuracy degradation vs. GENIEx by 12.34% and 3.99% (CIFAR-100, 16-bit and 8-bit) and 3.70% and 6.49% (ImageNet, 16-bit and 8-bit)", "Baseline FP32 accuracies: 69.6% (CIFAR-100/ResNet-20), 76.01% (ImageNet subset/ResNet-18)"], "limitations": ["GENIEx's training data and HSPICE calibration are generic/parametric rather than fit to a specific fabricated memristor device, so absolute accuracy predictions are illustrative rather than device-specific", "ImageNet evaluation uses only a 7680-image subset of the test set, not the full validation set", "The neural-network emulator itself adds inference overhead/complexity to the functional simulator compared to a closed-form analytical model", "Focuses on inference-time non-idealities (not training), and on CNN/ResNet workloads only"], "remarks": "GENIEx is an important methodological contribution to the non-ideality-modeling literature: by learning crossbar transfer characteristics directly from SPICE data rather than assuming linear/analytical non-ideality behavior, it exposes that commonly used analytical models can meaningfully overstate accuracy degradation, which matters for anyone using such models to justify (or reject) a mapping/training technique. It has been used as a more faithful non-ideality oracle by later mapping and fault-tolerance papers. The main caveat is that GENIEx itself is only as good as its HSPICE training distribution, and the reported overestimation percentages are specific to the voltage/precision/network configurations tested.", "basis": "full-text", "pdf_source_url": "", "abstract": "Memristive crossbars have been extensively explored for deep learning accelerators due to their high on-chip storage density and efficient Matrix Vector Multiplication (MVM) compared to digital CMOS. However, their analog nature of computing poses significant issues due to various non-idealities such as: parasitic resistances, non-linear I-V characteristics of the memristor device etc. The non-idealities can have a detrimental impact on the functionality i.e. computational accuracy of crossbars. Past works have explored modeling the non-idealities using analytical techniques. However, several non-idealities have data dependent behavior. This can not be captured using analytical (non data-dependent) models thereby, limiting their suitability in predicting application accuracy. To address this, we propose a Generalized Approach to Emulating Non-Ideality in Memristive Crossbars using Neural Networks (GENIEx), which accurately captures the data-dependent nature of non-idealities. First, we perform extensive HSPICE simulations of crossbars with different voltage and conductance combinations. Based on the obtained data, we train a neural network to learn the transfer characteristics of the non-ideal crossbar. Next, we build a functional simulator which includes key architectural facets such as tiling, and bit-slicing to analyze the impact of non-idealities on the classification accuracy of large-scale neural networks. We show that GENIEx achieves low root mean square errors (RMSE) of 0.25 and 0.7 for low and high voltages, respectively, compared to HSPICE. Additionally, the GENIEx errors are 7× and 12.8× better than an analytical model which can only capture the linear non-idealities. Further, using the functional simulator and GENIEx, we demonstrate that an analytical model can overestimate the degradation in classification accuracy by ≥ 10% on CIFAR-100 and 3.7% on ImageNet datasets compared to GENIEx.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2020_Chakraborty_GENIEx_DAC.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2020_Chakraborty_GENIEx_DAC.pdf", "priority": 7.45}, {"id": "W3036663566", "short": "CIM Area-Constraint Benchmark", "title": "Benchmark of the Compute-in-Memory-Based DNN Accelerator With Area Constraint", "authors": ["Anni Lu", "Xiaochen Peng", "Yandong Luo", "Shimeng Yu"], "year": 2020, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems, 2020", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2020.3001526", "cites_global": 22, "cat": "08", "seed": false, "devices": ["SRAM-analog", "FeFET"], "models": ["ResNet"], "evidence": "analytical", "tldr": "This benchmarking study designs and evaluates compute-in-memory DNN accelerators under realistic chip-area constraints (rather than assuming all weights fit on-chip), comparing two weight-reload dataflows and SRAM vs. FeFET device technologies for ResNet-18/ImageNet inference.", "summary": "Most prior compute-in-memory (CIM) DNN accelerator work assumes a full-custom design where all weights are stored on-chip, an assumption that breaks down for lightweight, area-constrained edge devices. This paper designs and benchmarks CIM-based DNN accelerators under different chip area constraints, where only part of the weight set can reside on-chip at a time. It investigates a scheduling strategy and dataflow for DNN inference under this constraint, comparing two weight-reload schemes: (1) reloading partial weights while reusing on-chip input/output feature maps, and (2) loading a batch of inputs and reusing the on-chip partial weights across that batch. A system-level performance benchmark is then run for ResNet-18 inference on ImageNet, comparing design tradeoffs across area constraints, dataflow choice, and device technology (SRAM vs. ferroelectric FET, FeFET).", "contributions": ["A scheduling/dataflow framework for CIM DNN accelerators operating under chip area constraints where not all weights fit on-chip simultaneously", "Two weight-reload schemes evaluated: reload-partial-weights-reuse-activations vs. reload-batch-of-inputs-reuse-partial-weights", "A system-level benchmark of ResNet-18/ImageNet inference performance across different area constraints, dataflows, and device technologies (SRAM vs. FeFET)"], "claims": [{"claim": "CIM accelerator performance under area constraints depends significantly on the choice of weight-reload dataflow", "support": "Two distinct reload schemes are compared and lead to different design tradeoffs (abstract)", "loc": "Abstract"}, {"claim": "Device technology choice (SRAM vs. FeFET) materially affects area-constrained CIM accelerator design tradeoffs", "support": "Abstract explicitly frames device technology (SRAM vs. FeFET) as a benchmarked design axis", "loc": "Abstract"}], "results": ["System-level performance benchmarking was performed specifically for ResNet-18 inference on ImageNet under varying area constraints, dataflows, and device technologies (per abstract); specific throughput/energy numbers are not stated in the abstract and could not be verified without full text"], "limitations": ["Only the abstract was available for this analysis (full text not accessible from this machine; IEEE Xplore is not downloadable here); quantitative results, exact area-constraint values, and specific performance/energy numbers could not be extracted or verified", "Evaluation appears limited to a single network (ResNet-18) and dataset (ImageNet) based on the abstract"], "remarks": "Based on the abstract, this paper fills a practically important gap in the CIM accelerator literature by relaxing the common (and often unrealistic for edge devices) assumption that all weights fit on-chip, and by directly comparing SRAM and FeFET as the on-chip analog storage technology under area constraints. Without full-text access the specific quantitative tradeoffs (e.g., throughput/energy vs. area curves) cannot be reported here; a thesis reader interested in realistic edge-deployment constraints for compute-in-memory accelerators should treat this as a relevant benchmarking reference to follow up on directly.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Compute-in-memory (CIM) is a promising computing paradigm to accelerate the inference of deep neural network (DNN) algorithms due to its high processing parallelism and energy efficiency. Prior CIM-based DNN accelerators mostly consider full custom design, which assumes that all the weights are stored on-chip. For lightweight smart edge devices, this assumption may not hold. In this article, CIM-based DNN accelerators are designed and benchmarked under different chip area constraints. First, a scheduling strategy and dataflow for DNN inference is investigated when only part of the weights can be stored on-chip. Two weight reload schemes are evaluated: 1) reload partial weights and reuse input/output feature maps and 2) load a batch of input and reuse the partial weights on-chip across the batch. Then, system-level performance benchmark is performed for the inference of ResNet-18 on ImageNet data set. The design tradeoffs with different area constraints, dataflow, and device technologies [static random access memory (SRAM) versus ferroelectric field-effect transistor (FeFET)] are discussed.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2020_Lu_CIMAreaConstraintBenchmark_TVLSI.pdf", "analysed": true, "pdf": null, "priority": 4.88}, {"id": "W3107562138", "short": "XB-SIM*", "title": "XB-SIM∗: A simulation framework for modeling and exploration of ReRAM-based CNN acceleration design", "authors": ["Xiang Fei", "Youhui Zhang", "Weimin Zheng"], "year": 2020, "venue": "Tsinghua Science & Technology", "venue_short": "TST", "venue_full": "Tsinghua Science and Technology, 2020", "venue_ok": true, "doi": "https://doi.org/10.26599/tst.2019.9010070", "cites_global": 13, "cat": "08", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "XB-SIM* is a configurable architecture-level simulation framework for ReRAM-crossbar CNN accelerators, bundling a ReRAM-aware training algorithm and a CNN-oriented mapper, validated against circuit-level simulation of a real chip, and sped up 5.02x-34.29x via a batch-processing mode on CPU/GPGPU.", "summary": "Designing ReRAM-crossbar CNN accelerators requires accounting for device imperfections while also running very large amounts of calculation to accurately simulate crossbar behavior, which is itself a major design challenge. XB-SIM* is presented as a flexible, configurable simulation framework that models an accelerator's structure and clock-driven behavior at the architecture level, bundled with a ReRAM-aware neural-network training algorithm and a CNN-oriented mapper so a network can be trained and efficiently mapped onto the simulated design. The simulator's behavior is validated against circuit-level simulation of an actual chip. To address the massive computation needed to mimic ReRAM-crossbar circuit behavior, the authors propose a batch-processing mode that exploits the mapping strategy's computational concurrency, reporting substantial simulation speedups on CPU and GPGPU platforms, and use the framework for architectural exploration and end-to-end evaluation.", "contributions": ["XB-SIM*: a configurable, architecture-level simulation framework for ReRAM-crossbar CNN accelerators modeling structure and clock-driven behavior", "An integrated ReRAM-aware NN training algorithm and CNN-oriented mapper for training and mapping networks onto the simulated design", "Validation of simulator behavior against circuit-level simulation of a real chip", "A batch-processing mode exploiting mapping-strategy concurrency to accelerate the massive calculations required for crossbar-circuit-accurate simulation", "Architectural exploration and end-to-end evaluation enabled by the framework"], "claims": [{"claim": "The simulator's modeled behavior matches circuit-level simulation of a real chip", "support": "Stated: 'Behavior of the simulator has been verified by the corresponding circuit simulation of a real chip' (abstract)", "loc": "Abstract"}, {"claim": "The proposed batch-processing mode substantially speeds up the massive calculations required to simulate ReRAM-crossbar circuit behavior", "support": "Up to 5.02x (CPU) or 34.29x (GPGPU) simulation speedup (abstract)", "loc": "Abstract"}], "results": ["Simulation speedup of up to 5.02x on CPU and 34.29x on GPGPU via batch processing (per abstract)"], "limitations": ["Only the abstract was available for this analysis (full text not accessible from this machine; IEEE Xplore is not downloadable here); specific accuracy of the architecture-level model versus circuit simulation, supported device/non-ideality models, and benchmark networks could not be verified", "As a simulation/framework paper, its contribution is tooling rather than a new accelerator architecture or training algorithm per se, so its value depends on adoption/validation by other works"], "remarks": "Based on the abstract, XB-SIM* belongs to the family of architecture-level ReRAM-crossbar CNN accelerator simulators (alongside tools like MNSIM and DNN+NeuroSim cited elsewhere in this collection), distinguished by its emphasis on simulation throughput (via batch processing) and validation against real-chip circuit simulation. Without full-text access, the fidelity of its device/non-ideality models and the breadth of architectural exploration it enables cannot be assessed beyond the abstract's claims; readers building or selecting a simulation framework for crossbar-based CNN accelerator design should compare it directly against MNSIM and NeuroSim-family tools in the full papers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive Random Access Memory (ReRAM)-based neural network accelerators have potential to surpass their digital counterparts in computational efficiency and performance. However, design of these accelerators faces a number of challenges including imperfections of the ReRAM device and a large amount of calculations required to accurately simulate the former. We present XB-SIM*, a simulation framework for ReRAM-crossbar-based Convolutional Neural Network (CNN) accelerators. XB-SIM* can be flexibly configured to simulate the accelerator's structure and clock-driven behaviors at the architecture level. This framework also includes an ReRAM-aware Neural Network (NN) training algorithm and a CNN-oriented mapper to train an NN and map it onto the simulated design efficiently. Behavior of the simulator has been verified by the corresponding circuit simulation of a real chip. Furthermore, a batch processing mode of the massive calculations that are required to mimic the behavior of ReRAM-crossbar circuits is proposed to fully apply the computational concurrency of the mapping strategy. On CPU/GPGPU, this batch processing mode can improve the simulation speed by up to 5.02× or 34.29×. Within this framework, comprehensive architectural exploration and end-to-end evaluation have been achieved, which provide some insights for systemic optimization.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2020_Fei_XBSIM_TST.pdf", "analysed": true, "pdf": null, "priority": 5.39}, {"id": "W3005619596", "short": "DNN+NeuroSim", "title": "DNN+NeuroSim: An End-to-End Benchmarking Framework for Compute-in-Memory Accelerators with Versatile Device Technologies", "authors": ["Xiaochen Peng", "Shanshi Huang", "Yandong Luo", "Xiaoyu Sun", "Shimeng Yu"], "year": 2019, "venue": "", "venue_short": "IEDM", "venue_full": "IEEE International Electron Devices Meeting (IEDM 2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/iedm19573.2019.8993491", "cites_global": 361, "cat": "08", "seed": false, "devices": ["SRAM-analog", "ReRAM", "PCM", "FeFET", "ECRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "DNN+NeuroSim is a Pytorch/TensorFlow-integrated, SPICE-calibrated end-to-end benchmarking framework that automatically maps DNNs to chip/tile/PE/synaptic-array hierarchies and jointly evaluates inference accuracy and hardware metrics (area, latency, energy, throughput) across SRAM and emerging NVM (RRAM, PCM, FeFET, ECRAM) devices.", "summary": "The paper presents DNN+NeuroSim, which extends the earlier MLP+NeuroSim (limited to a 2-layer MNIST MLP) into a full-stack, hierarchical benchmarking tool for compute-in-memory accelerators. A Python wrapper interfaces NeuroSim's circuit-level macro model with PyTorch/TensorFlow so that an arbitrary DNN topology (e.g., VGG-8 on CIFAR-10, ResNet-18 on ImageNet) can be automatically floor-planned into chip/tile/PE/synaptic-array hardware, incorporating device weight precision and ADC partial-sum quantization during offline software training and a retention/drift model during inference. The framework benchmarks SRAM and two-/three-terminal NVM devices (RRAM, PCM, FeFET, ECRAM) at the same or technology-appropriate nodes, analyzing the impact of conductance drift and ADC precision on inference accuracy, and comparing chip-level area, energy, throughput, and memory-utilization trade-offs, with all circuit modules calibrated against SPICE using PTM models.", "contributions": ["An end-to-end, hierarchical (chip/tile/PE/synaptic-array) benchmarking framework for compute-in-memory DNN accelerators, interfaced with PyTorch/TensorFlow via a Python wrapper", "Support for automatic DNN-to-hardware mapping and automatic chip floor-planning, with weight-duplication to maximize memory utilization for convolutional layers", "Joint evaluation of hardware-constrained inference accuracy (software side) and chip-level area/energy/throughput (NeuroSim core, SPICE-calibrated)", "Device retention/conductance-drift modeling and ADC quantization analysis, benchmarked across SRAM and RRAM/PCM/FeFET/ECRAM technologies from VGG-8/CIFAR-10 up to ResNet-18/ImageNet scale", "Open-sourced tool (released on GitHub) that became a widely used community benchmarking standard"], "claims": [{"claim": "Devices with large on-state resistance give better hardware performance than low-resistance analog RRAM/PCM", "support": "'analog' synaptic devices with large Ron (>100 kOhm), e.g. interface-engineered analog RRAM or three-terminal FeFET/ECRAM at 32nm, achieve superior energy efficiency (TOPS/W) than parallel SRAM at 7nm", "loc": "Sec. III.C, Table 1"}, {"claim": "Random conductance drift degrades inference accuracy less than directional drift", "support": "random drift maintains inference accuracy even over 10 years (at ~2% equivalent conductance drift), while drifting to maximum/minimum states degrades accuracy faster than drifting to intermediate states", "loc": "Sec. III.A, Fig. 3"}, {"claim": "A 128x128 array size with 5-bit ADC offers a balanced accuracy/efficiency/area trade-off", "support": "128x128 array with 5-bit ADC achieves relatively balanced trade-offs among accuracy, energy efficiency, throughput, area, and memory utilization in the radar-plot comparison (Fig. 5)", "loc": "Sec. III.B, Figs. 4-6"}, {"claim": "Real-traced simulation is more accurate than pseudo-traced or average simulation modes, at a runtime cost", "support": "real-traced framework achieves the most accurate results on FeFET-based ResNet-18/ImageNet benchmarking, while pseudo-traced and average methods underestimate performance (Fig. 7)", "loc": "Sec. IV"}], "results": ["4-bit ADC sufficient for ~89% accuracy with 1-bit/cell at 64x64 and 128x128 array sizes; 5-bit ADC needed to avoid significant accuracy loss at multi-bit/cell precision", "128x128 array with 5-bit ADC chosen as balanced design point across accuracy, energy efficiency, throughput, area, and memory utilization (VGG-8/CIFAR-10)", "Benchmarked SRAM (7nm and 32nm) and NVM (RRAM at 22nm, PCM at 40nm, FeFET at 28nm, all evaluated at 32nm) show large-Ron analog devices beat 7nm parallel SRAM in TOPS/W", "FeFET-based ResNet-18/ImageNet benchmarking run-time and accuracy compared across real-traced, pseudo-traced, and average simulation modes (Fig. 7)"], "limitations": ["A short (4-page) IEDM paper; many framework details (exact circuit models, validation against fabricated chips) are left to companion/follow-up papers (e.g., DNN+NeuroSim V2.0)", "Device retention/drift and ADC quantization are modeled analytically/behaviorally rather than validated against long-term measured device data in this paper", "Benchmark devices (RRAM, PCM, FeFET, ECRAM) are evaluated at different, device-appropriate technology nodes (22-40nm) rather than a single common node, complicating direct comparison", "Framework assumes offline-trained weights; on-chip/analog training is explicitly left to 'an improved version... under development for future release'"], "remarks": "This is the foundational IEDM paper for what became the widely used NeuroSim/DNN+NeuroSim benchmarking suite, and it is heavily cited by nearly every subsequent compute-in-memory architecture, mapping, and quantization paper that needs standardized area/energy/latency/accuracy numbers. Its main contribution is methodological (an open, hierarchical, PyTorch/TensorFlow-integrated, SPICE-calibrated benchmarking flow) rather than a new accelerator; the quantitative device comparison here is best read as an early, lower-fidelity version of the analysis later refined in NeuroSim V2.0 and subsequent versions.", "basis": "full-text", "pdf_source_url": "", "abstract": "DNN+NeuroSim is an integrated framework to benchmark compute-in-memory (CIM) accelerators for deep neural networks, with hierarchical design options from device-level, to circuit-level and up to algorithm-level. A python wrapper is developed to interface NeuroSim with popular machine learning platforms such as Pytorch and Tensorflow. The framework supports automatic algorithm to hardware mapping, and evaluates both chip-level performance and inference accuracy with hardware constraints. In this work, we analyze the impact of reliability in \"analog\" synaptic devices, and analog-to-digital converter (ADC) quantization effects on the inference accuracy. Then we benchmark CIM accelerators based on SRAM and versatile emerging devices including RRAM, PCM, FeFET and ECRAM, from VGG to ResNet, and from CIFAR to ImageNet dataset, revealing the benefits of high on-state resistance, e.g. by using three-terminal synapses. The open-source code of DNN+NeuroSim is available at https://github.com/neurosim/DNN_NeuroSim_V1.0.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2019_Peng_DNNNeuroSim_IEDM.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2019_Peng_DNNNeuroSim_IEDM.pdf", "priority": 9.12}, {"id": "W3003151806", "short": "PCM Device Models", "title": "Phase-Change Memory Models for Deep Learning Training and Inference", "authors": ["S. R. Nandakumar", "Irem Boybat", "Vinay Joshi", "Christophe Piveteau", "Manuel Le Gallo", "Bipin Rajendran", "Abu Sebastian", "Evangelos S. Eleftheriou"], "year": 2019, "venue": "", "venue_short": "ICECS", "venue_full": "IEEE International Conference on Electronics, Circuits and Systems (ICECS 2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/icecs46596.2019.8964852", "cites_global": 34, "cat": "08", "seed": false, "devices": ["PCM"], "models": ["CNN"], "evidence": "device-experiment", "tldr": "Statistically accurate PCM device models, built from characterization of over 10,000 devices and capturing state-dependent conductance update, drift, and read noise, are integrated into TensorFlow to let researchers realistically evaluate on-chip training and inference performance of PCM-based in-memory-computing DNN hardware.", "summary": "The paper addresses the need for computationally simple but statistically faithful PCM device models to evaluate deep-learning hardware based on in-memory computing, since PCM conductance states used as DNN synaptic weights exhibit non-ideal, state-dependent programming behavior, conductance drift, and read noise. The authors characterize more than 10,000 PCM devices and derive models that capture these effects (state-dependent conductance update variability, conductance drift over time, and read noise), designed to be computationally simple enough to integrate with deep-learning frameworks. They integrate the resulting models into TensorFlow so that both on-chip/analog training and one-time weight-programming inference scenarios for PCM-array-based DNN hardware can be evaluated realistically within standard ML training pipelines.", "contributions": ["Statistically accurate PCM device models derived from characterization of more than 10,000 devices", "Models capturing state-dependent conductance update variability, conductance drift, and read noise, rather than simplified generic noise assumptions", "Computationally simple model formulations suitable for integration with deep-learning frameworks", "Integration of the models into TensorFlow, enabling realistic evaluation of PCM-array-based training and inference hardware for DNNs"], "claims": [{"claim": "The proposed PCM models are statistically accurate because they are derived from large-scale device characterization", "support": "models are based on the characterization of more than 10,000 devices and capture the state-dependent nature and variability of conductance update, conductance drift, and read noise", "loc": "Abstract"}, {"claim": "The models are computationally simple enough to be used for realistic DNN training/inference evaluation", "support": "integrating the computationally simple device models with deep learning frameworks such as TensorFlow enables realistic evaluation of training and inference performance of PCM array based hardware implementations of DNNs", "loc": "Abstract"}], "results": [], "limitations": ["Analysis based on the abstract only; the precise functional form of the conductance-update, drift, and noise models, and the benchmark networks used to validate them, could not be verified from the full text", "As a device-modeling paper, it does not itself report new accelerator architecture or DNN accuracy results beyond validating the model's statistical fidelity"], "remarks": "This paper is the device-modeling companion to the IBM group's PCM-based DNN work (e.g., the Joshi et al. Nature Communications paper in this collection, which cites it), and such statistically grounded PCM models (state-dependent update, drift, 1/f noise) became a standard ingredient in later PCM/analog-AI training and drift-mitigation papers. Because only the abstract was available here, the exact modeling equations and the scope of validation (device count per state, networks tested) should be checked against the full ICECS paper before relying on specific modeling details.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Non-volatile analog memory devices such as phase-change memory (PCM) enable designing dedicated connectivity matrices for the hardware implementation of deep neural networks (DNN). In this in-memory computing approach, the analog conductance states of the memory device can be gradually updated to train DNNs on-chip or software trained connection strengths may be programmed one-time to the devices to create efficient inference engines. Reliable and computationally simple models that capture the non-ideal programming and temporal evolution of the devices are needed for evaluating the training and inference performance of the deep learning hardware based on in-memory computing. In this paper, we present statistically accurate models for PCM, based on the characterization of more than 10,000 devices, that capture the state-dependent nature and variability of the conductance update, conductance drift, and read noise. Integrating the computationally simple device models with deep learning frameworks such as TensorFlow enables us to realistically evaluate training and inference performance of the PCM array based hardware implementations of DNNs.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2019_Nandakumar_PCMDeviceModels_ICECS.pdf", "analysed": true, "pdf": null, "priority": 6.7}, {"id": "W2974067241", "short": "Analog vs Digital PIM", "title": "Accelerating Deep Neural Networks in Processing-in-Memory Platforms: Analog or Digital Approach?", "authors": ["Shaahin Angizi", "Zhezhi He", "Dayane Alfenas Reis", "Xiaobo Sharon Hu", "Wilman Tsai", "Shy Jay Lin", "Deliang Fan"], "year": 2019, "venue": "", "venue_short": "ISVLSI", "venue_full": "IEEE Computer Society Annual Symposium on VLSI (ISVLSI 2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/isvlsi.2019.00044", "cites_global": 42, "cat": "08", "seed": false, "devices": ["ReRAM", "MRAM", "SRAM-analog", "DRAM"], "models": ["CNN"], "evidence": "analytical", "tldr": "A bottom-up, iso-capacity and iso-computation comparison framework quantifies area, energy, and latency trade-offs between analog ReRAM-crossbar PIM and digital bulk-bitwise PIM (SOT-MRAM, STT-MRAM, ReRAM, SRAM, DRAM) for DNN acceleration.", "summary": "The paper compares two competing PIM paradigms for DNN acceleration: analog resistive crossbars that compute MAC via current-mode weighted summation, versus digital PIM that performs bulk bitwise logic (NAND/NOR, full-adder) on quantized DNN data inside conventional memories (SRAM, DRAM, STT/SOT-MRAM, digital ReRAM). It builds a bottom-up evaluation framework calibrated with device-level models (including NEGF-LLG MTJ modeling for MRAM) and compares the platforms under an iso-memory-capacity (32Mb single bank) setting and an iso-computation setting (LeNet-5 on MNIST with quantized weights/activations). The analysis reports area (split into memory vs. computation/periphery), latency, and energy for each platform, highlighting that the analog ReRAM crossbar incurs large peripheral/ADC overhead (>85% of computational area) despite a fast read latency, while digital platforms avoid ADC/DAC costs but pay a bulk-logic throughput penalty per operation.", "contributions": ["A unified bottom-up framework to evaluate and compare analog crossbar PIM against five digital bulk-bitwise PIM technologies (SOT-MRAM, STT-MRAM, digital ReRAM, SRAM, DRAM)", "An iso-memory-capacity comparison (32Mb single bank) reporting area, latency, and energy across all six platforms", "An iso-computation comparison mapping a quantized LeNet-5 onto each platform to estimate area/energy/latency for actual DNN inference", "Quantification that peripheral circuitry (buffers, ADC/DAC) dominates analog crossbar computational area (>85%), versus the bulk-logic throughput limits of digital PIM"], "claims": [{"claim": "Analog ReRAM crossbar peripheral circuitry dominates its computational area", "support": "DAC/ADC and buffers contribute more than 85% of the computational area for the analog ReRAM crossbar", "loc": "Sec. IV.A"}, {"claim": "Analog crossbar has the fastest read latency but slowest write latency among compared platforms", "support": "1.48 ns read latency (shortest) vs. 20.9 ns write latency (longest) for analog ReRAM crossbar (Table I)", "loc": "Sec. V.A(b)"}, {"claim": "Under iso-computation (LeNet-5/MNIST), SRAM is the fastest platform and analog crossbar the slowest", "support": "SRAM platform achieves 0.7 ms latency vs. 5.8 ms for the analog crossbar processing convolutional layers (Table II)", "loc": "Sec. V.B(c), Table II"}, {"claim": "SRAM-based PIM consumes much more leakage power than ReRAM-based (digital or analog) PIM", "support": "SRAM platform consumes ~14.5x and ~9x more power than digital and analog ReRAM, respectively", "loc": "Sec. V.A(c)"}], "results": ["Iso-capacity (32Mb): analog ReRAM crossbar computational area = 2.5 mm^2 vs. digital ReRAM = 0.4 mm^2; M/C ratio 1.33 (analog) vs. 23.53 (SOT-MRAM)", "Iso-computation (quantized LeNet-5 convolutional layers): latency 0.7 ms (SRAM), 0.9 ms (SOT-MRAM), 1.3 ms (digital ReRAM), 1.8 ms (STT-MRAM), 5.8 ms (analog ReRAM crossbar), 13.5 ms (DRAM)", "Iso-computation energy (write-back+read-based ops): 0.85 uJ (SOT-MRAM), 0.78 uJ (STT-MRAM), 1.9 uJ (digital ReRAM), 1.6 uJ (SRAM), 2.1 uJ (DRAM), 13.5 uJ (analog ReRAM)"], "limitations": ["Evaluation is purely analytical/model-based; no fabricated chips or SPICE-validated end-to-end system for any of the compared platforms", "DNN workload is limited to LeNet-5 on MNIST, a small network/dataset that may not reflect trends for larger CNNs", "Analog crossbar is modeled with an 8-bit ADC assumption and fixed bit-width configuration ([1:8] weight:activation), which may not be representative of all analog accelerator designs", "Comparison excludes throughput/parallelism-at-scale effects (e.g., multi-tile systems), focusing on row/bank-level estimates"], "remarks": "This is a useful, if small-scale, systematic apples-to-apples comparison that quantifies why analog crossbar PIM pays heavily in peripheral (ADC/DAC) area and write energy/latency while gaining raw read-latency and natural MAC parallelism, versus digital bulk-bitwise PIM which avoids mixed-signal circuitry but is throughput-limited by sequential bitwise operations. For a thesis on crossbar mapping, the main value is the explicit device-level area/energy/latency breakdown (Table I/II) rather than new architectural techniques; the LeNet-5/MNIST-only evaluation limits how far the conclusions generalize to larger, modern CNN/Transformer workloads.", "basis": "full-text", "pdf_source_url": "", "abstract": "Nowadays, research topics on AI accelerator designs have attracted great interest, where accelerating Deep Neural Network (DNN) using Processing-in-Memory (PIM) platforms is an actively-explored direction with great potential. PIM platforms, which simultaneously aims to address power- and memory-wall bottlenecks, have shown orders of performance enhancement in comparison to the conventional computing platforms with Von-Neumann architecture. As one direction of accelerating DNN in PIM, resistive memory array (aka. crossbar) has drawn great research interest owing to its analog current-mode weighted summation operation which intrinsically matches the dominant Multiplication-and-Accumulation (MAC) operation in DNN, making it one of the most promising candidates. An alternative direction for PIM-based DNN acceleration is through bulk bit-wise logic operations directly performed on the content in digital memories. Thanks to the high fault-tolerant characteristic of DNN, the latest algorithmic progression successfully quantized DNN parameters to low bit-width representations, while maintaining competitive accuracy levels. Such DNN quantization techniques essentially convert MAC operation to much simpler addition/subtraction or comparison operations, which can be performed by bulk bit-wise logic operations in a highly parallel fashion. In this paper, we build a comprehensive evaluation framework to quantitatively compare and analyze aforementioned PIM based analog and digital approaches for DNN acceleration.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2019_Angizi_AnalogVsDigitalPIM_ISVLSI.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2019_Angizi_AnalogVsDigitalPIM_ISVLSI.pdf", "priority": 4.54}, {"id": "W2899749435", "short": "DL-RSIM", "title": "DL-RSIM", "authors": ["Meng-Yao Lin", "Hsiang-Yun Cheng", "Wei‐Ting Lin", "Tzu-Hsien Yang", "I-Ching Tseng", "Chia-Lin Yang", "Han-Wen Hu", "Hung-Sheng Chang", "Hsiang-Pang Li", "Meng‐Fan Chang"], "year": 2018, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2018)", "venue_ok": true, "doi": "https://doi.org/10.1145/3240765.3240800", "cites_global": 76, "cat": "08", "seed": false, "devices": ["Memristor(generic)"], "models": ["CNN"], "evidence": "simulation", "tldr": "DL-RSIM is a simulation framework that injects crossbar sum-of-products error rates (from non-ideal device/circuit effects) directly into TensorFlow CNN models to study how memristor-based accelerator reliability issues affect inference accuracy.", "summary": "Memristor-crossbar deep-learning accelerators are attractive for energy efficiency but are error-prone because of non-ideal device and circuit properties. The authors argue that evaluating this requires a simulation platform that connects low-level reliability impact factors to application-level accuracy. DL-RSIM computes the error rate of each sum-of-products (dot-product) operation performed in a memristor crossbar and injects the corresponding errors into a target CNN running in TensorFlow, so the accuracy impact of a chosen set of circuit/device non-idealities can be measured end-to-end without full SPICE-level simulation of the whole network. The framework is designed to be reusable across any TensorFlow-defined CNN and explores a 'rich set of reliability impact factors.' Using three representative CNNs as case studies, the authors show DL-RSIM can be used by chip designers to compare design options and to guide the development of reliability-optimization techniques.", "contributions": ["A flexible, TensorFlow-pluggable simulation framework that models memristor-crossbar non-idealities as per-sum-of-products error rates", "Error injection methodology that maps low-level circuit/device reliability factors onto application-level (accuracy) metrics without full-array SPICE simulation", "Exploration of a broad set of reliability impact factors relevant to memristor-based accelerators", "Case studies on three representative CNNs showing the framework can inform reliability-aware design choices"], "claims": [{"claim": "DL-RSIM can guide chip designers toward reliability-friendly design options and reliability-optimization techniques", "support": "Demonstrated via three CNN case studies (abstract only; specific accuracy/error-rate numbers not available without full text)", "loc": "Abstract"}], "results": ["Abstract-only basis: no verified quantitative results extracted (full text not available from this machine; specific per-factor accuracy-degradation numbers in the original paper are not reproduced here)"], "limitations": ["Analysis here is abstract-only -- no verification of specific numerical error-injection results, benchmark CNNs used, or comparison baselines", "As described, the framework trades fidelity for speed (error-rate injection instead of full circuit-level simulation), which is itself a modeling approximation"], "remarks": "DL-RSIM sits alongside MNSIM and RxNN as one of the early TensorFlow/behavioral-level reliability simulators for memristor accelerators, feeding later tools (MNSIM 2.0, CoMN) and reliability studies that build on injected-error methodologies. Because only the abstract was available, confidence in the specific numeric claims is low; the overall framing (map circuit non-idealities to per-dot-product error rates, inject into a standard DL framework) is a credible and influential approach for a graduate student to be aware of, but exact figures should be checked against the primary source before citing.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Memristor-based deep learning accelerators provide a promising solution to improve the energy efficiency of neuromorphic computing systems. However, the electrical properties and crossbar structure of memristors make these accelerators error-prone. To enable reliable memristor-based accelerators, a simulation platform is needed to precisely analyze the impact of non-ideal circuit and device properties on the inference accuracy. In this paper, we propose a flexible simulation framework, DL-RSIM, to tackle this challenge. DL-RSIM simulates the error rates of every sum-of-products computation in the memristor-based accelerator and injects the errors in the targeted TensorFlow-based neural network model. A rich set of reliability impact factors are explored by DL-RSIM, and it can be incorporated with any deep learning neural network implemented by TensorFlow. Using three representative convolutional neural networks as case studies, we show that DL-RSIM can guide chip designers to choose a reliability-friendly design option and develop reliability optimization techniques.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2018_Lin_DLRSIM_ICCAD.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2018_Lin_DLRSIM_ICCAD.pdf", "priority": 7.15}, {"id": "W2736591611", "short": "MNSIM", "title": "MNSIM: Simulation Platform for Memristor-based Neuromorphic Computing System", "authors": ["Lixue Xia", "Boxun Li", "Tianqi Tang", "Peng Gu", "Pai-Yu Chen", "Shimeng Yu", "Yu Kevin Cao", "Yu Wang", "Yuan Xie", "Huazhong Yang"], "year": 2017, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2017/2018)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2017.2729466", "cites_global": 171, "cat": "08", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["MLP", "CNN"], "evidence": "simulation", "tldr": "MNSIM is a behavior-level simulation platform for memristor-based neuromorphic accelerators that models area/power/latency and a non-ideality-aware computing-accuracy model, achieving over 7000x speed-up versus SPICE while staying within ~10% error on power/latency and <1% error on accuracy.", "summary": "The paper addresses the lack of a fast, behavior-level simulator for memristor-crossbar neuromorphic accelerators that can support early design-space exploration, as circuit-level SPICE simulation is far too slow for full-chip/architecture studies. MNSIM proposes a hierarchical reference architecture (crossbar array -> processing engine -> tile -> chip) with configurable interfaces, combined with analytical area/power/latency models and a behavior-level computing-accuracy model that accounts for interconnect-line resistance and non-ideal device factors. The accuracy and performance models are validated against SPICE simulation of small fully-connected networks and against a layout-extracted crossbar decoder design. Experiments show MNSIM is over 7000x faster than SPICE on single-crossbar simulation (up to ~19000x at 256x256 size) with power/latency error under 10% and computing accuracy error under 1%, and the tool is used to explore area/energy/latency/accuracy trade-offs for a large 2048x1024 network layer under different design choices (crossbar size, technology node, parallelism degree).", "contributions": ["First behavior-level simulation platform (MNSIM) specifically targeting memristor-crossbar-based neuromorphic accelerators", "A hierarchical, customizable reference architecture (crossbar, processing element, tile, chip levels) for memristor-based accelerators", "Analytical area, power, and latency models validated against SPICE and layout extraction", "A behavior-level computing-accuracy model that captures the effect of interconnect-line (IR-drop-like) resistance and non-ideal device characteristics on classification/inference accuracy", "Demonstration of design-space exploration (crossbar size, CMOS technology node, parallelism degree) trading off area, energy, latency and accuracy"], "claims": [{"claim": "MNSIM achieves more than 7000x simulation speed-up compared with SPICE for single crossbar simulation, increasing with crossbar size", "support": "Table III: speed-up ranges from 7642x (16x16 crossbar) to 19489x (256x256 crossbar)", "loc": "Sec. VII-B, Table III"}, {"claim": "MNSIM's power and latency estimates match SPICE within acceptable error for a 3-layer, 128x128-layer fully-connected network", "support": "all error rates smaller than 10% compared with SPICE results (Table II)", "loc": "Sec. VII-A, Table II"}, {"claim": "MNSIM's accuracy model (interconnect + device non-idealities) matches real degraded classification accuracy to within 1% for an approximate-computing JPEG-encoding application on a 64x16x64 network", "support": "error rate of accuracy model is less than 1%", "loc": "Sec. VII-A"}, {"claim": "MNSIM's area model for a 32x32 1T1R crossbar with decoders is within the same order of magnitude as a 130nm-CMOS layout-extracted design, though it under-estimates due to layout spacing overhead", "support": "layout area 3420 um^2 (45um x 76um) vs. MNSIM estimate 2251 um^2", "loc": "Sec. VII-A, Fig. 6"}, {"claim": "MNSIM can be used for architecture-level design-space exploration that trades off area, energy, latency, and accuracy for a large (2048x1024) network layer", "support": "Table IV shows area/energy/latency/accuracy-optimized design points with different crossbar sizes, tech nodes (28nm vs 45nm) and parallelism degrees", "loc": "Sec. VII-C/Table IV"}], "results": ["Over 7000x (up to ~19489x at 256x256 crossbar) simulation speed-up vs SPICE (Table III)", "<10% error on power/latency vs SPICE for a 128x128x128 fully-connected network (Table II)", "<1% error on computing accuracy vs ground truth for a 64x16x64 approximate-computing JPEG network", "Area estimate error of ~34% low vs layout-extracted 32x32 1T1R crossbar+decoder design (2251 um^2 vs 3420 um^2), used as a calibration coefficient"], "limitations": ["Validation is limited to small fully-connected networks (128x128, 64x16x64) and a single small crossbar layout; no validation against a full fabricated chip or large CNN", "Area model has a substantial (~34%) discrepancy from layout extraction, requiring a user-supplied correction coefficient", "Power/latency validation uses average-case input/resistance models, which the authors note is the main source of the ~10% simulation error", "Does not natively model on-chip training, dynamic synaptic device behavior, or inter-layer pipelining at the time of publication (listed as future work)", "Being a pure simulator, all reported numbers are estimates rather than measured silicon results"], "remarks": "MNSIM was one of the first widely-adopted behavior-level simulation/benchmarking frameworks for memristor-crossbar neuromorphic accelerators, predating and complementary to later tools like DNN+NeuroSim; it became a standard baseline and was later extended to MNSIM 2.0 and used/cited by many subsequent mapping and architecture papers (e.g., TIME, XB-SIM*, PIMulator-NN). Its main value for the thesis topic is as an early, fast design-space-exploration tool whose accuracy model (interconnect + device non-ideality) foreshadows the non-ideality-aware simulation frameworks that dominate the field; its limitations (small validation networks, approximate area model) mean its absolute numbers should be treated as rough estimates rather than precise predictions.", "basis": "full-text", "pdf_source_url": "", "abstract": "Memristor-based computation provides a promising solution to boost the power efficiency of the neuromorphic computing system. However, a behavior-level memristor-based neuromorphic computing simulator, which can model the performance and realize an early stage design space exploration, is still missing. In this paper, we propose a simulation platform for the memristor-based neuromorphic system, called MNSIM. A hierarchical structure for memristor-based neuromorphic computing accelerator is proposed to provides flexible interfaces for customization. A detailed reference design is provided for large-scale applications. A behavior-level computing accuracy model is incorporated to evaluate the computing error rate affected by interconnect lines and nonideal device factors. Experimental results show that MNSIM achieves over 7000 times speed-up than SPICE simulation. MNSIM can optimize the design and estimate the tradeoff relationships among different performance metrics for users.", "review": [], "pdf_expected": "08_Simulation_and_Benchmarking_Frameworks/2017_Xia_MNSIM_TCAD.pdf", "analysed": true, "pdf": "08_Simulation_and_Benchmarking_Frameworks/2017_Xia_MNSIM_TCAD.pdf", "priority": 7.96}, {"id": "W4416429523", "short": "OptiRange", "title": "OptiRange: An Efficient ReRAM-Based PIM Accelerator with ADC Resolution Optimization", "authors": ["Seong-Won Jeon", "Gisan Ji", "Yeonggeon Kim", "Youngjun Park", "Sangyeon Kim", "Sungju Ryu"], "year": 2025, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad66269.2025.11240769", "cites_global": 0, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "OptiRange is a ReRAM PIM accelerator that lowers ADC resolution/energy without hurting accuracy or throughput by rebalancing crossbar cell values (split-the-burden) and dynamically adapting the ADC's operating range per column at runtime.", "summary": "The paper targets the ADC energy/throughput tradeoff in ReRAM-based processing-in-memory (PIM) DNN accelerators: existing approaches that lower ADC resolution or share ADCs across columns save energy but hurt throughput. OptiRange introduces a 'split-the-burden' (STB) algorithm that manipulates crossbar cell values (without changing the represented weights) to shrink large cell values and recenter the column-sum distribution near zero, which reduces the number of low-resistance-state cells and lets the hardware use a lower fixed ADC resolution while preserving accuracy. On top of this, a dynamic ADC range (DAR) mechanism picks the optimal ADC operating range per column at the software level at runtime, skipping redundant ADC conversion cycles, and an ADC range-based grouping (AG) strategy manages synchronization across columns with different dynamic latencies to keep system throughput high. Together these weight-preserving cell manipulation and adaptive ADC techniques are evaluated against conventional ReRAM-based accelerators in simulation, showing improved overall performance (energy and throughput) while maintaining accuracy and model flexibility.", "contributions": ["Split-the-burden (STB) algorithm that reshapes crossbar cell-value/column-sum distributions without altering represented weights, enabling lower fixed ADC resolution", "Dynamic ADC range (DAR) adaptation that selects per-column ADC operating ranges at runtime and skips redundant conversion cycles", "ADC range-based grouping (AG) strategy to manage the resulting variable per-column latencies and preserve system throughput", "Combines these into OptiRange, an accelerator design claimed to jointly improve ADC energy efficiency and throughput versus prior resolution-reduction/ADC-sharing methods"], "claims": [{"claim": "STB's cell manipulation lowers the hardware-level fixed ADC resolution needed while improving accuracy relative to unmodified mapping", "support": "Abstract states STB 'significantly lowers the hardware-level fixed ADC resolution and improving accuracy'", "loc": "Abstract"}, {"claim": "OptiRange achieves better energy efficiency and throughput jointly, unlike prior methods that trade one for the other", "support": "Abstract: 'enhances both energy efficiency and throughput while maintaining accuracy and model flexibility'", "loc": "Abstract"}], "results": ["No specific quantitative speedup/energy numbers available from the abstract alone; full text was not accessible"], "limitations": ["Full text not accessible to this reviewer (no open preprint found); specific experimental numbers, baselines, and benchmark models could not be verified beyond the abstract", "Evidence basis is simulation; no fabricated silicon reported"], "remarks": "Abstract-only assessment: a legitimate open copy could not be located (ICCAD proceedings are not downloadable from this environment and no arXiv preprint was found). The core idea — reshaping cell/column-sum distributions to cut required ADC resolution, then adaptively narrowing the per-column ADC range at runtime — is a reasonable and fairly novel combination of a weight-preserving mapping trick with dynamic ADC control, addressing a well-known ADC energy/throughput bottleneck in ReRAM crossbar accelerators (as in ISAAC-style designs). Without the full text, the magnitude of the claimed gains and the fairness of the baseline comparisons cannot be independently verified.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Processing-in-memory (PIM) techniques have attracted significant attention in computer architecture research due to their ability to mitigate the memory wall bottleneck for deep neural network (DNN) applications. In-memory computing (IMC) using ReRAM crossbar arrays is promising for energy efficiency but suffers from high-cost peripheral circuits, particularly analog-to-digital converters (ADCs). There are existing methods to reduce ADC energy consumption, such as lowering resolution or sharing an ADC among multiple columns. Unfortunately, these techniques reduce throughput. In this work, we propose OptiRange for PIM accelerators that enhances both energy efficiency and throughput while maintaining accuracy and model flexibility. OptiRange proposes a split-the-burden (STB) algorithm that manipulates crossbar cell values without changing the weights. STB reduces large cell values, shifts the column-sum distribution center closer to zero, and minimizes the number of low-resistance state (LRS) cells, significantly lowering the hardware-level fixed ADC resolution and improving accuracy. Furthermore, OptiRange utilizes dynamic ADC range (DAR) adaptation, determining the optimal ADC operating range per column at the software level and enabling the skipping of redundant ADC conversion cycles at runtime. An associated ADC range-based grouping (AG) strategy leverages the resulting dynamic latencies to manage synchronization and further boost system throughput. By combining weight-preserving cell manipulation with adaptive ADC operation and synchronization, OptiRange dynamically optimizes the ADC workload. Experimental results indicate that our method significantly enhances overall performance compared to conventional ReRAM-based accelerators.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2025_Jeon_OptiRange_ICCAD.pdf", "analysed": true, "pdf": null, "priority": 3.0}, {"id": "W4399310783", "short": "BWQ", "title": "Block-Wise Mixed-Precision Quantization: Enabling High Efficiency for Practical ReRAM-Based DNN Accelerators", "authors": ["Xueying Wu", "Edward Hanson", "Nansu Wang", "Qilin Zheng", "Xiaoxuan Yang", "Huanrui Yang", "Shiyu Li", "Feng Cheng", "Partha Pratim Pande", "Janardhan Rao Doppa", "Krishnendu Chakrabarty", "Hai Helen Li"], "year": 2024, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2024.3409193", "cites_global": 15, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "BWQ is an algorithm-architecture co-design that applies block-wise mixed-precision quantization matched to the Operation-Unit (OU) granularity of practical ReRAM accelerators, giving 6.08x speedup and 17.47x energy savings over ISAAC.", "summary": "The paper targets the gap between idealized ReRAM-crossbar accelerator designs (which assume whole 128x128/256x256 arrays can be activated at once) and practical designs, which must restrict concurrently-activated wordlines/bitlines (an Operation Unit, OU, e.g. 9x8) to keep ADC resolution and IR-drop manageable. BWQ-A trains networks in a bit-level representation with a weight-block (WB)-level group-Lasso regularizer so that each OU-sized weight block can be pruned to its own bit-width, giving finer-grained mixed precision than prior layer-wise schemes (BSQ). BWQ-H is the matching hardware: a precision-aware weight-mapping scheme that packs same-bit-position weights from a WB into one OU (avoiding the control-logic/utilization penalties of naive bit-interleaved or same-OU mappings), plus a memory controller that tracks per-block bit-width via a LUT and generates skip/accumulate signals for the shift-and-add units. Evaluated on CIFAR-10, CIFAR-100 and ImageNet with ResNet-18/34, VGG16/19-BN, MobileNetV2 and DenseNet121 under a cycle-accurate OU-based simulator against ISAAC, SRE and SME baselines. BWQ-A reaches an average 58.27x weight compression within 1% accuracy loss and 15.74x lower average bit-width than BSQ; BWQ-H delivers 6.08x speedup / 17.47x energy savings over ISAAC, 4.44x/11.98x over SRE, 3.66x/7.65x over SME, and 1.45x/2.66x over BSQ, with 17.38x lower indexing overhead than SRE.", "contributions": ["Block-wise (OU-granularity) mixed-precision quantization (BWQ-A) using bit-level WB group-Lasso and periodic re-quantization/precision adjustment", "Precision-aware weight-mapping scheme (BWQ-H) that packs same-bit-position weights of a block into one OU to reach 100% OU memory utilization without extra control logic", "Memory controller design generating row/column, skip, and fetch signals to support per-block mixed-precision computation on a shared crossbar", "System-level evaluation under the realistic OU-based operation scheme (vs. idealized whole-crossbar activation) against ISAAC, SRE and SME", "Scalability study of BWQ across OU sizes from 9x8 up to 128x128 as a roadmap for future ReRAM fabrication"], "claims": [{"claim": "Practical ReRAM accelerators can only activate ~9 WLs x 8 BLs concurrently to keep computation accurate, unlike idealized whole-crossbar designs", "support": "cites measured macro work [11,12] limiting OU to 9x8", "loc": "Sec. I"}, {"claim": "BWQ-A achieves much higher compression than layer-wise BSQ at similar accuracy", "support": "58.27x average compression within 1% accuracy drop; 15.74x lower average bit-width than BSQ on VGG19-BN/CIFAR-10", "loc": "Sec. VI.A, Fig. 7"}, {"claim": "BWQ-H outperforms ISAAC, SRE, SME and BSQ hardware under the OU-based scheme", "support": "6.08x speedup / 17.47x energy saving vs ISAAC; 4.44x/11.98x vs SRE; 3.66x/7.65x vs SME; 1.45x/2.66x vs BSQ", "loc": "Sec. VI.B, Fig. 9"}, {"claim": "BWQ-H has much lower indexing overhead than fine-grained sparsity method SRE", "support": "17.38x lower indexing overhead than SRE (SRE needs up to 704KB index storage for ResNet-34)", "loc": "Sec. VI.C, Fig. 11"}, {"claim": "A medium/large OU size (around 64x64) minimizes runtime but larger OUs cost more ADC energy", "support": "runtime minimal at OU=64x64 in scalability sweep from 9x8 to 128x128", "loc": "Sec. VI.D.2, Fig. 13"}], "results": ["58.27x average weight compression ratio within 1% accuracy degradation (BWQ-A vs FP32 baseline)", "6.08x speedup and 17.47x energy saving vs ISAAC (average over CIFAR-10/100/ImageNet models)", "4.44x speedup / 11.98x energy saving vs SRE; 3.66x / 7.65x vs SME; 1.45x / 2.66x vs BSQ", "15.74x lower average bit-width than BSQ on VGG19-BN/CIFAR-10", "17.38x lower indexing overhead than SRE, 4.46x higher than SME"], "limitations": ["Architecture-level results are from a cycle-accurate simulator, not silicon", "1-bit ReRAM cells assumed for fair OU-based comparison (ISAAC's native 2-bit cells not used), which affects absolute comparability to ISAAC's original design point", "Accuracy budget fixed at 1% degradation threshold; not explored how results change at tighter/looser accuracy budgets", "OU size limited by current ReRAM fabrication (9x8 assumed as realistic); larger-OU results (up to 128x128) are a forward-looking projection, not a validated near-term design"], "remarks": "This is a solid, well-controlled architecture paper precisely because it takes the OU-based (realistic ADC/parallelism-limited) operating regime as a first-class constraint rather than assuming idealized whole-crossbar MVMs, which is exactly the simplification that papers like ISAAC are often criticized for. The precision-aware mapping trick (align same-bit-position weights within an OU rather than bits of one weight) is a clean, reusable idea for any mixed-precision PIM mapping problem. Evidence is simulation-only (no silicon), and the comparisons to ISAAC/SRE/SME are reproduced from re-implementations rather than apples-to-apples ports of each paper's codebase, so absolute multiplier numbers should be read as architectural trends rather than precise ratios.", "basis": "full-text", "pdf_source_url": "", "abstract": "Resistive random access memory (ReRAM)-based processing-in-memory (PIM) architectures have demonstrated great potential to accelerate Deep Neural Network (DNN) training/ inference. However, the computational accuracy of analog PIM is compromised due to the non-idealities, such as the conductance variation of ReRAM cells. The impact of these non-idealities worsens as the number of concurrently activated wordlines and bitlines increases. To guarantee computational accuracy, only a limited number of wordlines and bitlines of the crossbar array can be turned on concurrently, significantly reducing the achievable parallelism of the architecture. While the constraints on parallelism limit the efficiency of the accelerators, they also provide a new opportunity for finegrained mixed-precision quantization. To enable efficient DNN inference on practical ReRAM-based accelerators, we propose an algorithm-architecture co-design framework called Block-Wise mixed-precision Quantization (BWQ). At the algorithm level, BWQ-A introduces a mixed-precision quantization scheme at the block level, which achieves a high weight and activation compression ratio with negligible accuracy degradation. We also present the hardware architecture design BWQ-H, which leverages the low-bit-width models achieved by BWQ-A to perform high-efficiency DNN inference on ReRAM devices. BWQ-H also adopts a novel precision-aware weight mapping method to increase the ReRAM crossbars throughput. Our evaluation demonstrates the effectiveness of BWQ, which achieves a 6.08× speedup and a 17.47× energy saving on average compared to existing ReRAM-based architectures.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2024_Wu_BWQ_TCAD.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2024_Wu_BWQ_TCAD.pdf", "priority": 3.84}, {"id": "W4394891385", "short": "ReHarvest", "title": "ReHarvest: An ADC Resource-Harvesting Crossbar Architecture for ReRAM-Based DNN Accelerators", "authors": ["Jiahong Xu", "Haikun Liu", "Zhuohui Duan", "Xiaofei Liao", "Hai Jin", "Xiaokang Yang", "Huize Li", "Cong Liu", "Fubing Mao", "Yu Zhang"], "year": 2024, "venue": "ACM Transactions on Architecture and Code Optimization", "venue_short": "TACO", "venue_full": "ACM Transactions on Architecture and Code Optimization", "venue_ok": true, "doi": "https://doi.org/10.1145/3659208", "cites_global": 12, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "ReHarvest decouples ADCs from fixed crossbar arrays via a many-to-many crossbar-ADC resource pool plus multi-tile matrix mapping, improving ADC utilization by 3.2x and achieving 3.5x speedup with 3.1x less ReRAM resource usage versus the state-of-the-art PIM architecture FORMS.", "summary": "The paper targets the ADC bottleneck in ReRAM-based PIM accelerators: ADCs are high-latency, area-inefficient, and are conventionally tightly coupled one-to-one (or few-to-one) with each crossbar array, leaving the scarce ADC resource underutilized when a given crossbar's MVM does not need continuous AD conversion. ReHarvest proposes an ADC-crossbar decoupled architecture with a many-to-many mapping structure that pools all ADCs within a tile so that any crossbar array in that tile can 'harvest' additional ADCs to parallelize its AD conversion, rather than being limited to its statically assigned converters. To extend this sharing benefit across tiles, the authors add a multi-tile matrix mapping (MTMM) scheme that increases data parallelism across tiles, supported by a bus-based interconnection network that multicasts input vectors to multiple tiles to avoid data redundancy and network congestion during the resulting fine-grained data dispatch. Evaluated against the state-of-the-art PIM architecture FORMS, ReHarvest substantially improves ADC resource utilization and throughput while also reducing the amount of ReRAM crossbar hardware needed.", "contributions": ["Identifies ADC-crossbar static coupling as a key source of underutilized ADC resources in ReRAM PIM accelerators", "Proposes a many-to-many crossbar-to-ADC mapping that pools all ADCs in a tile as a shared resource for any crossbar needing AD conversion", "Proposes a multi-tile matrix mapping (MTMM) scheme to extend ADC sharing/parallelism benefits across multiple tiles", "Designs a bus-based interconnection network for fine-grained, multicast-based input-vector dispatch across tiles to avoid data redundancy and network congestion under MTMM", "Demonstrates simultaneous gains in ADC utilization, throughput, and reduced ReRAM array resource consumption versus FORMS"], "claims": [{"claim": "ReHarvest improves ADC utilization by 3.2x on average compared to FORMS.", "support": "reported average utilization improvement", "loc": "Abstract / experimental results"}, {"claim": "ReHarvest achieves 3.5x performance speedup on average compared to FORMS.", "support": "reported average speedup", "loc": "Abstract / experimental results"}, {"claim": "ReHarvest reduces ReRAM resource consumption by 3.1x on average compared to FORMS.", "support": "reported average resource reduction", "loc": "Abstract / experimental results"}, {"claim": "Statically coupling a fixed number of ADCs to each crossbar array leaves ADC resources underutilized because MVM demand across crossbars is uneven.", "support": "motivation/architectural rationale for the many-to-many design", "loc": "Introduction/motivation (abstract)"}], "results": ["3.2x average ADC utilization improvement vs. FORMS", "3.5x average performance speedup vs. FORMS", "3.1x average reduction in ReRAM crossbar resource consumption vs. FORMS"], "limitations": ["Full text not available for this analysis; the quantitative claims above are taken from the abstract only and not independently verified against tables/figures", "Evaluation baseline is limited (as reviewed) to a single state-of-the-art comparison point (FORMS); comparison against other ADC-sharing or ADC-reduction approaches (e.g., Quarry, TinyADC) is not confirmed from the abstract", "The approach adds interconnection/bus complexity (multicast network across tiles) whose own area/energy overhead relative to the ADC savings is not quantified in the abstract"], "remarks": "ReHarvest addresses the same ADC-bottleneck problem noted across much of the ReRAM-crossbar accelerator literature in this collection (e.g., Quarry, TinyADC cited as prior ADC-reduction work for this same research group's related papers), but attacks it from a resource-sharing/architecture angle (decoupling ADC-to-crossbar binding) rather than reducing ADC precision or count directly. This is a useful architectural counterpoint for a mapping/peripheral-circuits thesis chapter: rather than reducing analog-to-digital conversion precision, it reorganizes dataflow and interconnect to make better use of existing ADC resources. Because only the abstract was reviewed, the FORMS baseline comparison and the added interconnect overhead should be checked in the full TACO 2024 paper before relying on the specific 3.1x-3.5x figures.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "ReRAM-based Processing-In-Memory (PIM) architectures have been increasingly explored to accelerate various Deep Neural Network (DNN) applications because they can achieve extremely high performance and energy-efficiency for in-situ analog Matrix-Vector Multiplication (MVM) operations. However, since ReRAM crossbar arrays’ peripheral circuits– analog-to-digital converters (ADCs) often feature high latency and low area efficiency, AD conversion has become a performance bottleneck of in-situ analog MVMs. Moreover, since each crossbar array is tightly coupled with very limited ADCs in current ReRAM-based PIM architectures, the scarce ADC resource is often underutilized. In this article, we propose ReHarvest, an ADC-crossbar decoupled architecture to improve the utilization of ADC resource. Particularly, we design a many-to-many mapping structure between crossbars and ADCs to share all ADCs in a tile as a resource pool, and thus one crossbar array can harvest much more ADCs to parallelize the AD conversion for each MVM operation. Moreover, we propose a multi-tile matrix mapping (MTMM) scheme to further improve the ADC utilization across multiple tiles by enhancing data parallelism. To support fine-grained data dispatching for the MTMM, we also design a bus-based interconnection network to multicast input vectors among multiple tiles, and thus eliminate data redundancy and potential network congestion during multicasting. Extensive experimental results show that ReHarvest can improve the ADC utilization by 3.2×, and achieve 3.5× performance speedup while reducing the ReRAM resource consumption by 3.1× on average compared with the state-of-the-art PIM architecture–FORMS.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2024_Xu_ReHarvest_TACO.pdf", "analysed": true, "pdf": null, "priority": 4.68}, {"id": "W4401070574", "short": "Light-CIM", "title": "Light-CIM: A Lightweight ADC/DAC-Fewer RRAM CIM DNN Accelerator With Fully Analog Tiles and Nonideality-Aware Algorithm for Consumer Electronics", "authors": ["Chenyang Zhao", "Jinbei Fang", "Jingwen Jiang", "Xiaoyong Xue", "Xiaoyang Zeng"], "year": 2024, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2024.3435690", "cites_global": 9, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Light-CIM is a lightweight RRAM CIM accelerator built from fully analog tiles (1T1R arrays plus all-analog peripheral circuits) that eliminates most intra-tile ADCs/DACs, cutting ADC power to 2.5% of total, and uses a nonideality-aware training algorithm to recover accuracy, reaching 3.91 TOPS/mm^2 and 3.08 TOPS/W.", "summary": "Most CIM accelerators need numerous ADCs/DACs for mixed-signal data conversion between analog compute and digital control/storage, which costs significant area and energy. Light-CIM instead builds 'fully analog tiles' (FANTs) from 1T1R RRAM arrays plus customized analog peripheral circuits so that intra-tile data computation, transfer, and buffering all stay in the analog domain (voltage, current, or resistance), removing the costly intermediate data conversions used in conventional CIM designs. To recover the accuracy lost to the resulting analog non-idealities (read nonlinearity, device mismatch, variation, noise), the authors use a nonideality-aware training algorithm that models these circuit non-idealities during software training so the deployed network is robust to them. The approach is evaluated on various NN models, reportedly reaching accuracy close to software (floating-point) performance, with ADC power reduced to only 2.5% of total chip power, and a compute density of 3.91 TOPS/mm^2 and energy efficiency of 3.08 TOPS/W, described as highly competitive versus other state-of-the-art CIM designs for consumer-electronics use.", "contributions": ["Fully Analog Tile (FANT) design based on 1T1R RRAM arrays with analog peripheral circuits, eliminating most intra-tile ADC/DAC conversions", "An architecture keeping data computation, transfer and buffering entirely in the analog domain (voltage/current/resistance) within a tile", "A nonideality-aware training algorithm modeling read nonlinearities, mismatches, variations and noise during software training to recover hardware accuracy", "Demonstration that ADC overhead can be cut to a small fraction (2.5%) of total power while retaining near-software accuracy", "A compute-density and energy-efficiency result (3.91 TOPS/mm^2, 3.08 TOPS/W) targeted at consumer-electronics-class CIM accelerators"], "claims": [{"claim": "Eliminating intra-tile ADC/DAC conversions via fully analog tiles drastically reduces ADC-related power overhead", "support": "ADC accounts for only 2.5% of total power consumption (abstract)", "loc": "Abstract"}, {"claim": "Nonideality-aware training recovers accuracy close to ideal software performance despite the fully-analog, non-ideality-prone datapath", "support": "'accuracy close to software performance in various NN models' (abstract)", "loc": "Abstract"}, {"claim": "Light-CIM achieves highly competitive compute density and energy efficiency versus other state-of-the-art designs", "support": "3.91 TOPS/mm^2 compute density and 3.08 TOPS/W energy efficiency (abstract)", "loc": "Abstract"}], "results": ["ADC power is only 2.5% of total power consumption", "Compute density: 3.91 TOPS/mm^2", "Energy efficiency: 3.08 TOPS/W"], "limitations": ["Abstract-only analysis in this record: full text unavailable, so the exact analog peripheral-circuit design, training algorithm details, and benchmark models/datasets could not be verified", "Fully-analog intra-tile dataflow (no intermediate ADC/DAC) likely increases sensitivity to accumulated analog noise/drift across cascaded stages; the abstract does not quantify this beyond the single accuracy claim", "Unclear from abstract whether results are from fabricated silicon or simulation only"], "remarks": "Light-CIM sits in the same design space as ReCAT/CASCADE-style cascaded-analog approaches that avoid ADC conversion between stages, but applied at the tile/peripheral-circuit level for a lightweight consumer-electronics accelerator rather than for Transformer matrix-matrix chaining. The headline ADC-power-fraction (2.5%) and efficiency numbers are compelling, but without the full text it is not possible to confirm whether these are measured-silicon or simulated results, nor to assess the training algorithm's non-ideality model fidelity.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Neuromorphic computing has emerged as a revolutionary technology in consumer electronics, with computing-in-memory (CIM) attracting considerable attention for its potential to minimize data transfer. However, most CIM accelerators necessitate numerous digital-to-analog converters (DACs) and analog-to-digital converters (ADCs) for mixed-signal data processing, resulting in substantial area and energy overheads. This study introduces a lightweight CIM accelerator, Light-CIM, which operates with fully analog tiles (FANTs) and employs a nonideality-aware algorithm. A FANT consists of one-transistor-one-resistor (1T1R) arrays based on resistive random access memory (RRAM) and customized analog peripheral circuits for data processing. The intratile data computation, transfer, and buffering are all in analog voltage, current, or RRAM resistance, thus eliminating costly DACs and ADCs for intermediate data conversions in conventional CIM accelerators. The fully analog approach significantly reduces power consumption attributed to ADCs, accounting for only 2.5% of the total power consumption. Additionally, a nonideality-aware training algorithm is employed to enhance the robustness of the hardware system. It models and incorporates nonidealities of circuits in software training, including read nonlinearities, mismatches, variations, and noises in the hardware analog data flow. Experimental results demonstrate that Light-CIM achieves accuracy close to software performance in various NN models. Light-CIM accomplishes a compute density of 3.91 TOPS/${\\mathrm { mm}}^{2}$and an energy efficiency of 3.08 TOPS/W, both highly competitive compared to state-of-the-art works.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2024_Zhao_LightCIM_TCAD.pdf", "analysed": true, "pdf": null, "priority": 3.7}, {"id": "W4366389026", "short": "RAELLA", "title": "RAELLA: Reforming the Arithmetic for Efficient, Low-Resolution, and Low-Loss Analog PIM: No Retraining Required!", "authors": ["Tanner Andrulis", "Joel Emer", "Vivienne Sze"], "year": 2023, "venue": "", "venue_short": "ISCA", "venue_full": "ACM/IEEE 50th Annual International Symposium on Computer Architecture (ISCA 2023)", "venue_ok": true, "doi": "https://doi.org/10.1145/3579371.3589062", "cites_global": 45, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet", "Transformer", "BERT"], "evidence": "algorithm+simulation", "tldr": "RAELLA reduces ADC cost in ReRAM PIM accelerators by reshaping computed analog-value distributions (Center+Offset signed weight encoding, per-layer adaptive weight slicing, and runtime speculative/recovery input slicing) rather than changing DNN weights, achieving up to 4.9x energy efficiency and 3.3x throughput over ISAAC-class designs with no retraining and near-zero accuracy loss.", "summary": "PIM accelerator efficiency is dominated by ADC energy, and prior approaches to reduce ADC resolution either prune weights (Weight-Count-Limited, e.g. FORMS) or quantize/requantize sums (Sum-Fidelity-Limited, e.g. TIMELY), both of which require costly DNN retraining to recover accuracy. RAELLA's key idea is that the analog-value distribution computed by a crossbar can be reshaped by the architecture itself rather than by modifying the DNN: (1) Center+Offset encoding shifts/splits positive and negative weight slices so that accumulated column sums are small and centered near zero, keeping them within low ADC resolution with high fidelity; (2) adaptive weight slicing chooses, per DNN layer at compile time, how many ReRAM devices and bits-per-device to use for each weight, balancing density/efficiency against resulting analog-value resolution; (3) dynamic input slicing speculatively processes inputs with fewer, wider slices and detects/recovers via a higher-fidelity, narrower-slice path only when needed, cutting ADC conversions by 5-15x. The design is implemented with 2T2R ReRAM cells for signed in-crossbar subtraction and evaluated via Accelergy/Timeloop plus a modified NeuroSim on 32nm (and 65nm for TIMELY comparison), tested on 6 ImageNet CNNs (GoogLeNet, InceptionV3, ResNet18/50, ShuffleNetV2, MobileNetV2) and BERT-Large on SQuAD. Against an 8-bit ISAAC baseline with no retraining, RAELLA improves energy efficiency 2.9-4.9x (geomean 3.9x) and throughput 0.7-3.3x (geomean 2.0x); against retraining-based FORMS and TIMELY it matches or exceeds efficiency/throughput while avoiding retraining, with accuracy drops of only ~0.06-0.16 percentage points on ResNet18/50 (vs. 0.62-0.70 for FORMS, which retrains).", "contributions": ["Center+Offset weight encoding that reshapes column-sum distributions in ReRAM crossbars to be small and zero-centered, enabling low-resolution (7-bit) ADCs without retraining", "Per-layer adaptive weight slicing (choice of devices-per-weight and bits-per-device) at compile time to balance density, efficiency and resulting analog resolution", "Dynamic (runtime) input slicing with speculation and recovery, reducing ADC conversions by 5-15x by using wide, few slices when safe and narrow, many slices only when needed", "2T2R ReRAM cell design for in-crossbar signed arithmetic (analog subtraction) supporting Center+Offset encoding", "A full accelerator design (larger 512x512 crossbars, 7b ADC) evaluated against ISAAC, FORMS-8 and TIMELY on 6 CNNs and BERT-Large without any DNN retraining"], "claims": [{"claim": "RAELLA substantially improves energy efficiency and throughput over a non-retraining ADC-heavy baseline (ISAAC)", "support": "2.9-4.9x energy efficiency (geomean 3.9x) and 0.7-3.3x throughput (geomean 2.0x) improvement vs. an 8-bit ISAAC baseline across 7 DNNs, with no retraining", "loc": "Sec. 6.3, Fig. 12"}, {"claim": "RAELLA matches or exceeds the efficiency of retraining-based accelerators (FORMS, TIMELY) without needing to retrain DNNs", "support": "RAELLA matches FORMS throughput and exceeds the efficiency of both FORMS and TIMELY (Sec. 6.4, Fig. 13) while FORMS/TIMELY require pruned/requantized retraining", "loc": "Sec. 6.4"}, {"claim": "RAELLA preserves DNN accuracy far better than a naive Zero+Offset alternative, validating the necessity of Center+Offset encoding", "support": "Center+Offset accuracy drop of 0.06-0.16pp (ResNet18/50) vs. 10.17%/16.36% drop for MobileNetV2/ShuffleNetV2 under Zero+Offset (Table 4)", "loc": "Sec. 6.4, Table 4"}, {"claim": "Dynamic input speculation reduces ADC conversions substantially versus always running at full input-slice resolution", "support": "Speculation reduces required ADC conversions 5-15x, and crossbars produce psums every 11 cycles (3 speculation + 8 recovery slices) vs. 8 cycles / 800ns without speculation enabled but with higher ADC energy", "loc": "Sec. 1, Sec. 6.1, Sec. 6.3"}, {"claim": "RAELLA's accuracy loss without retraining is competitive with or better than retraining-based designs", "support": "ResNet18/ResNet50 accuracy drop of 0.06%/-0.08% (Center+Offset, no retrain) vs. 0.62%/0.70% for FORMS (retrained) and <=0.1% for TIMELY (retrained)", "loc": "Table 4"}], "results": ["2.9-4.9x energy efficiency improvement (geomean 3.9x) over 8-bit ISAAC baseline across 7 DNNs, no retraining", "0.7-3.3x throughput improvement (geomean 2.0x) over ISAAC baseline", "Up to 14x fewer ADC conversions than comparable low-accuracy-loss PIM accelerators (vs. ISAAC-class)", "Accuracy drop of only 0.06pp (ResNet18) and -0.08pp (ResNet50, i.e. slight gain) with Center+Offset encoding and no retraining, vs. 0.62pp/0.70pp for retrained FORMS", "Without speculation: 2.8x geomean efficiency, 2.7x geomean throughput vs. ISAAC (lower than with speculation enabled)"], "limitations": ["All results from architectural simulation (Accelergy/Timeloop, modified NeuroSim component models) at 32nm/65nm, not fabricated silicon", "ReRAM device parameters (on/off resistance, read voltage) are taken from the TIMELY paper's reported values rather than independently characterized", "2T2R cell area is pessimistically estimated as the sum of two ReRAMs and two transistors, ignoring potential 3D stacking that could change the area tradeoff", "RAELLA's throughput benefit is reduced for signed-input workloads (e.g., BERT, processed in separate positive/negative cycles) and for compact models with small filters (MobileNetV2, ShuffleNetV2) that underutilize its large 512x512 crossbars", "Baseline comparisons (ISAAC, FORMS) are re-implemented/re-modeled by the authors using shared components for fairness, which, while validated to <10% error against original papers, is still author-controlled re-modeling rather than independent third-party replication"], "remarks": "RAELLA is a well-targeted contribution to the ADC-reduction literature (category 09) because it decouples accuracy preservation from DNN retraining -- a real deployment obstacle when training data is private or retraining pipelines are expensive -- by instead reshaping the analog arithmetic and slicing strategy. The accuracy-preservation claims are credible given the explicit architectural mechanism (zero-centering sums before ADC conversion) and are tested on a reasonably broad and current set of workloads including BERT-Large, which is relatively rare for ADC-focused PIM papers in this era. As with most PIM architecture papers, the efficiency/throughput numbers are simulator-derived (Accelergy/Timeloop + modified NeuroSim) rather than measured silicon, and the comparison baselines are the authors' own careful re-implementations of ISAAC/FORMS rather than the original hardware, which is standard practice but still a caveat when comparing absolute numbers across papers.", "basis": "full-text", "pdf_source_url": "", "abstract": "Processing-In-Memory (PIM) accelerators have the potential to efficiently run Deep Neural Network (DNN) inference by reducing costly data movement and by using resistive RAM (ReRAM) for efficient analog compute. Unfortunately, overall PIM accelerator efficiency is limited by energy-intensive analog-to-digital converters (ADCs). Furthermore, existing accelerators that reduce ADC cost do so by changing DNN weights or by using low-resolution ADCs that reduce output fidelity. These strategies harm DNN accuracy and/or require costly DNN retraining to compensate.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2023_Andrulis_RAELLA_ISCA.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2023_Andrulis_RAELLA_ISCA.pdf", "priority": 6.19}, {"id": "W4385255585", "short": "CIMQ", "title": "CIMQ: A Hardware-Efficient Quantization Framework for Computing-In-Memory-Based Neural Network Accelerators", "authors": ["Jinyu Bai", "Sifan Sun", "Weisheng Zhao", "Wang Kang"], "year": 2023, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2023.3298705", "cites_global": 21, "cat": "09", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "CIMQ is a hardware-aware quantization framework for CIM accelerators that jointly quantizes activations (bit-sparsity aware), weights (array-wise granularity), and partial sums (reparametrized clipping to cut ADC resolution), plus a random-dropping PTQ enhancement, reporting up to 222% hardware-efficiency gain with 58.97% accuracy improvement over conventional quantization.", "summary": "Compute-in-memory accelerators need low-precision data because of limited memory-device and data-interface resolution, but conventional NN quantization methods ignore CIM hardware characteristics (e.g., crossbar array structure, ADC cost), hurting both performance and efficiency when ported to CIM. CIMQ addresses the three CIM computing elements holistically: (1) bit-level-sparsity-induced activation quantization to cut dynamic computation energy, (2) an array-wise weight quantization granularity designed around the crossbar's computation paradigm (rather than per-tensor/per-channel granularity used in digital accelerators), and (3) partial-sum quantization via a reparametrized clipping function that reduces the needed ADC resolution. A fourth technique, a random quantization dropping strategy, is added to a post-training quantization (PTQ) pipeline to recover accuracy without retraining. The framework is evaluated on multiple networks and datasets (CIFAR-10, CIFAR-100, ImageNet), reporting up to 222% hardware-efficiency improvement together with a 58.97% accuracy improvement over conventional (non-CIM-aware) quantization methods in typical cases.", "contributions": ["Bit-level sparsity-induced activation quantization to reduce dynamic computation energy in CIM accelerators", "A CIM-specific array-wise weight quantization granularity motivated by the crossbar computation paradigm, as opposed to standard per-tensor/per-channel granularity", "Partial-sum quantization via a reparametrized clipping function that directly targets reducing required ADC resolution", "A random quantization dropping strategy enhancing post-training quantization (PTQ) accuracy for CIM-targeted QNNs", "A holistic framework spanning all three CIM computing elements (inputs/activations, weights, outputs/partial sums), evaluated across CIFAR-10, CIFAR-100, and ImageNet"], "claims": [{"claim": "CIMQ improves hardware efficiency and accuracy versus conventional quantization methods when applied to CIM accelerators", "support": "up to 222% hardware efficiency improvement with 58.97% accuracy improvement in typical cases", "loc": "Abstract"}], "results": ["Up to 222% hardware-efficiency improvement vs. conventional quantization (typical case)", "58.97% accuracy improvement vs. conventional quantization (typical case)", "Evaluated on CIFAR-10, CIFAR-100, and ImageNet across various NNs"], "limitations": ["Analysis based on abstract only (full text not accessible); exact networks, bit-widths, baseline quantization method, and per-dataset breakdowns could not be verified", "\"Typical case\" framing for the headline 222%/58.97% numbers suggests they are not uniform across all tested configurations; range/variance is unclear without full text"], "remarks": "CIMQ is a quantization/mapping-layer contribution rather than a new device or crossbar architecture; its key idea — treating ADC resolution reduction as a quantization-aware design target via partial-sum clipping, and using array-wise (not per-channel) granularity to match crossbar structure — is directly relevant to ADC/peripheral cost reduction, a major bottleneck this literature map tracks. The large reported gains (222% efficiency, 58.97% accuracy) are plausible for a holistic PTQ scheme but could not be cross-checked against baselines without the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The novel computing-in-memory (CIM) technology has demonstrated significant potential in enhancing the performance and efficiency of convolutional neural networks (CNNs). However, due to the low precision of memory devices and data interfaces, an additional quantization step is necessary. Conventional NN quantization methods fail to account for the hardware characteristics of CIM, resulting in inferior system performance and efficiency. This article proposes CIMQ, a hardware-efficient quantization framework designed to improve the efficiency of CIM-based NN accelerators. The holistic framework focuses on the fundamental computing elements in CIM hardware: inputs, weights, and outputs (or activations, weights, and partial sums in NNs) with four innovative techniques. First, bit-level sparsity induced activation quantization is introduced to decrease dynamic computation energy. Second, inspired by the unique computation paradigm of CIM, an innovative arraywise quantization granularity is proposed for weight quantization. Third, partial sums are quantized with a reparametrized clipping function to reduce the required resolution of analog-to-digital converters (ADCs). Finally, to improve the accuracy of quantized neural networks (QNNs), the post-training quantization (PTQ) is enhanced with a random quantization dropping strategy. The effectiveness of the proposed framework has been demonstrated through experimental results on various NNs and datasets (CIFAR10, CIFAR100, and ImageNet). In typical cases, the hardware efficiency can be improved up to 222% with a 58.97% improvement in accuracy compared to conventional quantization methods.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2023_Bai_CIMQ_TCAD.pdf", "analysed": true, "pdf": null, "priority": 3.44}, {"id": "W4383753658", "short": "ERA-BS", "title": "ERA-BS: Boosting the Efficiency of ReRAM-Based PIM Accelerator With Fine-Grained Bit-Level Sparsity", "authors": ["Fangxin Liu", "Wenbo Zhao", "Zongwu Wang", "Yongbiao Chen", "Xiaoyao Liang", "Li Jiang"], "year": 2023, "venue": "IEEE Transactions on Computers", "venue_short": "TC", "venue_full": "IEEE Transactions on Computers", "venue_ok": true, "doi": "https://doi.org/10.1109/tc.2023.3290869", "cites_global": 15, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "ERA-BS exploits fine-grained bit-level sparsity in both static weights (via an adaptive bit-flip + exponent-based quantization scheme) and dynamic activations (via crossbar-aware pruning) to shrink ReRAM crossbar footprint, claiming up to 43x/78x/73x energy/area/throughput gains over ISAAC and 5.3x/7.2x/32x gains over PIM-Prune.", "summary": "ReRAM crossbar accelerators are limited by constrained concurrent MAC throughput (rows/columns usable at once) and costly high-precision ADCs, and conventional DNN sparsity is hard to exploit in a fixed crossbar structure, especially activation sparsity. ERA-BS targets the correlation between bit-level sparsity (in weights and activations) and crossbar performance. It proposes a bit-flip scheme combined with exponent-based quantization that adaptively flips mapped-weight bits to free redundant crossbar space with little accuracy loss or hardware overhead, plus an architecture that shrinks crossbar footprint so more arrays can be used in parallel. For activations, it adds a dynamic sparsity exploitation scheme (crossbar-aware activation pruning plus runtime hardware support) that exploits the tightly coupled crossbar structure. Together, static weight-bit sparsity and dynamic activation sparsity are both exploited at fine (bit-level) granularity to raise performance and cut energy with reportedly negligible overhead. Across a range of networks, ERA-BS is reported to reach up to 43x energy efficiency, 78x area efficiency, and 73x throughput versus ISAAC, and 5.3x/7.2x/32x versus the more recent PIM-Prune baseline, with similar or higher accuracy.", "contributions": ["A bit-flip scheme combined with exponent-based quantization that adaptively frees redundant crossbar cell space from sparse weight bits with minimal accuracy loss", "A crossbar architecture that integrates the bit-level sparsity techniques to physically shrink crossbar footprint for denser array packing", "A dynamic activation sparsity exploitation scheme (crossbar-aware activation pruning + runtime hardware) tailored to the crossbar's tightly coupled structure", "Joint exploitation of fine-grained static (weight) and dynamic (activation) bit-level sparsity in a ReRAM PIM accelerator", "Large reported efficiency gains over both a classic (ISAAC) and a recent sparsity-aware (PIM-Prune) ReRAM baseline"], "claims": [{"claim": "ERA-BS achieves large efficiency gains over ISAAC", "support": "up to 43x energy efficiency, 78x area efficiency, 73x throughput vs. ISAAC", "loc": "Abstract"}, {"claim": "ERA-BS outperforms the more recent PIM-Prune sparsity-aware ReRAM design with comparable or better accuracy", "support": "5.3x energy efficiency, 7.2x area efficiency, 32x performance gain vs. PIM-Prune, with similar or higher accuracy", "loc": "Abstract"}], "results": ["Up to 43x energy efficiency, 78x area efficiency, 73x throughput vs. ISAAC", "5.3x energy efficiency, 7.2x area efficiency, 32x performance vs. PIM-Prune, similar/higher accuracy"], "limitations": ["Analysis based on abstract only (full text not accessible); the mechanics of the bit-flip/exponent quantization scheme, benchmark network list, and exact accuracy deltas could not be verified", "Very large claimed speedups (up to 78x area efficiency) are relative to the authors' own re-implementation/assumptions for ISAAC and PIM-Prune baselines, which cannot be independently checked from the abstract"], "remarks": "This is an algorithm+architecture co-design paper for sparsity exploitation in ReRAM crossbars, positioned against the well-known ISAAC baseline and the more recent PIM-Prune sparsity accelerator; its distinguishing idea is treating sparsity at bit-level granularity (both static weight bits via adaptive bit-flipping/exponent quantization, and dynamic activation bits via crossbar-aware pruning) rather than at the tensor/channel level. The headline multiplicative gains (up to 78x) are large enough to warrant scrutiny of baseline fidelity once the full text is available; this entry should be revisited with full text if accuracy-critical mapping comparisons are needed.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive Random-Access-Memory (ReRAM) crossbar is one of the most promising neural network accelerators, thanks to its in-memory and in-situ analog computing abilities for Matrix Multiplication-and-Accumulations (MACs). The key limitations are: 1) the number of rows and columns of ReRAM cells for concurrent execution of MACs is constrained, resulting in limited in-memory computing throughput; 2) the cost of high-precision analog-to-digital (A/D) conversions that can offset the efficiency and performance benefits of ReRAM-based Process-In-Memory (PIM). Meanwhile, it is challenging to deploy Deep Neural Network (DNN) models with a large model size in the crossbar since the sparsity of DNNs cannot be effectively exploited in the crossbar structure, especially the sparsity in the activation. As a countermeasure, we develop a novel ReRAM-based PIM accelerator, namely ERA-BS, which pays attention to the correlation between the bit-level sparsity (in both weights and activations) and the performance of the ReRAM-based crossbar. We propose a superior bit-flip scheme combined with the exponent-based quantization, which can adaptively flip the bits of the mapped DNNs to release redundant space without sacrificing the accuracy much or incurring much hardware overhead. Meanwhile, we design an architecture that can integrate the techniques to shrink the crossbar footprint to be used massively. We further propose a dynamic activation sparsity exploitation scheme in conjunction with the tightly coupled structure nature of the crossbar, including crossbar-aware activation pruning and ancillary run-time hardware support. In such a way, we exploit fine-grained sparsity weights (static) and activations (dynamic), respectively, to improve performance while reducing the energy consumption of computation with negligible overheads. Our experiments on a wide variety of networks show that compared to the well-known ReRAM-based PIM accelerator like “ISAAC”, ERA-BS can achieve up to$43\\times$,$78\\times$, and$73\\times$in terms of energy efficiency, area-efficiency, and throughput, respectively. Compared to the state-of-the-art ReRAM-based design “PIM-Prune”, ERA-BS can also achieve$5.3\\times$energy efficiency,$7.2\\times$area efficiency, and$32\\times$performance gain with a similar or even higher accuracy.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2023_Liu_ERABS_TC.pdf", "analysed": true, "pdf": null, "priority": 3.34}, {"id": "W4386859314", "short": "ADC-Less CiM Partial-Sum Quant", "title": "Partial-Sum Quantization for Near ADC-Less Compute-In-Memory Accelerators", "authors": ["Utkarsh Saxena", "Kaushik Roy"], "year": 2023, "venue": "", "venue_short": "ISLPED", "venue_full": "ACM/IEEE International Symposium on Low Power Electronics and Design (ISLPED 2023)", "venue_ok": true, "doi": "https://doi.org/10.1109/islped58423.2023.10244291", "cites_global": 15, "cat": "09", "seed": false, "devices": ["Memristor(generic)", "ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "By quantizing crossbar partial sums down to binary (1-bit, sense-amplifier-only, 'ADC-Less') or ternary (1.5-bit, two-comparator, 'near ADC-Less') precision and using a CiM-hardware-aware DNN quantization training method, this paper nearly eliminates ADC overhead, reporting up to 178x latency and 131x TOPS/mm2 improvement over an 8-bit-ADC baseline on ResNet-20/CIFAR-10 with minimal accuracy loss.", "summary": "ADCs are a dominant source of peripheral-circuit overhead in resistive-crossbar compute-in-memory (CiM) DNN accelerators, limiting the efficiency gains promised by analog MVM. This paper proposes eliminating or minimizing that overhead by quantizing the crossbar's partial sums (the per-column analog MVM output before conversion) to extremely low precision: binary (1-bit) partial sums require only a sense amplifier for analog-to-digital conversion, yielding a fully 'ADC-Less' design, while ternary (1.5-bit) partial sums require two comparators, yielding a 'near ADC-Less' design. Because this aggressive partial-sum quantization would otherwise cause large accuracy degradation, the authors develop a CiM-hardware-aware DNN quantization training methodology specifically to mitigate it. The approach is evaluated on CIFAR-10 (ResNet-20) with the fully ADC-Less design and on ImageNet (ResNet-18) with the near-ADC-Less design, reporting high accuracy with minimal degradation alongside large efficiency gains relative to a conventional 8-bit-ADC baseline.", "contributions": ["ADC-Less CiM design: binary (1-bit) partial-sum quantization requiring only a sense amplifier instead of a multi-bit ADC", "Near-ADC-Less CiM design: ternary (1.5-bit) partial-sum quantization requiring only two comparators", "A CiM-hardware-aware DNN quantization training methodology to recover accuracy lost to extreme partial-sum quantization", "Demonstrated large joint energy/latency/area-efficiency gains over an 8-bit-ADC baseline on both CIFAR-10 (ResNet-20) and ImageNet (ResNet-18) with minimal accuracy degradation"], "claims": [{"claim": "The ADC-Less design achieves large efficiency gains over an 8-bit-ADC baseline on ResNet-20/CIFAR-10 with minimal accuracy loss", "support": "14x energy, 178x latency, and 131x TOPS/mm2 improvement over baseline (8-bit ADC)", "loc": "Abstract"}, {"claim": "The near-ADC-Less design achieves large efficiency gains over an 8-bit-ADC baseline on ResNet-18/ImageNet with minimal accuracy loss", "support": "11x energy, 55x latency, and 36x TOPS/mm2 improvement over baseline (8-bit ADC)", "loc": "Abstract"}], "results": ["ResNet-20/CIFAR-10, ADC-Less (binary partial sums): 14x energy, 178x latency, 131x TOPS/mm2 vs. 8-bit-ADC baseline", "ResNet-18/ImageNet, near-ADC-Less (ternary partial sums): 11x energy, 55x latency, 36x TOPS/mm2 vs. 8-bit-ADC baseline"], "limitations": ["Analysis based on abstract only (full text not accessible); the exact CiM-hardware-aware quantization training method, accuracy numbers (not just 'minimal degradation'), and crossbar/array assumptions could not be verified", "Reducing partial-sum resolution to 1-1.5 bits per crossbar read likely requires many more reads/accumulation steps to reconstruct full precision, a tradeoff not quantifiable from the abstract alone"], "remarks": "This is an ADC/peripheral-cost-reduction paper that pushes partial-sum quantization to its logical extreme (binary/ternary), directly extending prior partial-sum quantization work in this same in-set reference list (Kim et al., 'Extreme Partial-Sum Quantization', W4300228436, and the ADC-reduction line including Quarry, W4200001938). The very large reported latency/area gains (up to 178x) for only 1-2 bit ADC precision suggest the technique trades off read-cycle count for ADC simplicity; full-text access would be needed to confirm whether the TOPS/mm2 and latency figures already account for any additional read cycles needed to recover full-precision partial sums.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Resistive Crossbar (Xbar) Array based Compute-in-Memory (CiM) accelerators form an attractive hardware substrate for acceleration of Deep Neural Networks (DNNs) on edge devices. They perform highly efficient Matrix Vector Multiplication (MVM) operation, employing the power of analog compute. However, efficiency gains with CiM accelerators are limited due to the overhead posed by peripheral circuits, primarily the Analog-to-Digital Converters (ADCs). In this work, we improve efficiency of CiM accelerators by developing ADC-Less and near ADC-Less CiM accelerators which either eliminate or minimize the ADC overhead. More specifically, we leverage partial-sum quantization to reduce ADC precision to binary (1-bit) or ternary (1.5-bit) values. Xbars with binary partial sums require a sense amplifier for analog-to-digital conversion leading to ADC-Less design. Xbars with ternary partial-sums require two comparators for the conversion process leading to a near ADC-Less design. We develop a CiM hardware aware DNN quantization methodology to mitigate accuracy degradation with partial-sum quantization. We show the effectiveness of our training methodology by achieving high accuracies and minimal accuracy degradation on CIFAR-10 and Imagenet datasets. Consequently, we achieve 14x, 178x and 131x improvements over baseline (8-bit ADC) in Energy, Latency and Compute Efficiency (TOPS/mm2), respectively on Resnet-20 (CIFAR-10) with ADC-Less design and 11x, 55x and 36x improvements over baseline (8-bit ADC) in Energy, Latency and TOPS/mm2, respectively on Resnet-18 (ImageNet) with Near ADC-Less design.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2023_Saxena_ADCLessCiMPartialSumQuant_ISLPED.pdf", "analysed": true, "pdf": null, "priority": 3.34}, {"id": "W4312993714", "short": "ENNA", "title": "ENNA: An Efficient Neural Network Accelerator Design Based on ADC-Free Compute-In-Memory Subarrays", "authors": ["Hongwu Jiang", "Shanshi Huang", "Wantong Li", "Shimeng Yu"], "year": 2022, "venue": "IEEE Transactions on Circuits and Systems I Regular Papers", "venue_short": "TCAS-I", "venue_full": "IEEE Transactions on Circuits and Systems I: Regular Papers (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcsi.2022.3208755", "cites_global": 35, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "measured-silicon", "tldr": "ENNA is an ADC-free compute-in-memory accelerator with a taped-out TSMC 40nm RRAM subarray prototype that performs inter-array data processing fully in the analog domain using a pulse-width-modulation input encoding, achieving 73.6-86.4 TOPS/W and 2.3-7 TOPS, with projected 3x-37x throughput gains via heterogeneous 3D integration.", "summary": "The paper targets the ADC bottleneck in compute-in-memory (CIM) accelerators, where analog-to-digital converters that digitize crossbar MAC outputs cause accuracy loss, power overhead, latency penalties, and area cost. ENNA proposes an ADC-free sub-array architecture that keeps inter-array data processing in the analog domain, paired with a lightweight pulse-width-modulation (PWM) input encoding scheme designed to raise throughput. The authors fabricated and taped out a prototype RRAM macro in TSMC 40nm process to validate the ADC-free sub-array design, then used the measured silicon data to project system-level performance for a full accelerator that partitions analog and digital processing at a level above the sub-array. They further project a heterogeneous 3D integration (H3D) variant of the design and compare it to a conventional 2D implementation.", "contributions": ["An ADC-free compute-in-memory sub-array architecture that performs inter-array data processing in the analog domain, avoiding per-sub-array ADC conversion", "A lightweight pulse-width-modulation (PWM) input encoding scheme to improve throughput under the ADC-free design", "A taped-out RRAM prototype macro in TSMC 40nm process validating the ADC-free sub-array concept on measured silicon", "System-level performance projections based on measured silicon data, exploring the analog/digital processing partition point above the sub-array level", "A projected heterogeneous 3D integration (H3D) variant showing further throughput and area benefits over a 2D implementation"], "claims": [{"claim": "The ADC-free sub-array design achieves high energy efficiency validated on measured silicon", "support": "73.6-86.4 TOPS/W energy efficiency (normalized to binary operation), based on measured prototype macro data", "loc": "Abstract"}, {"claim": "The design achieves meaningful throughput across various DNN models", "support": "2.3-7 TOPS throughput (normalized to binary operation) tested on various DNN models", "loc": "Abstract"}, {"claim": "Heterogeneous 3D integration (H3D) substantially improves throughput over a 2D implementation with lower area overhead", "support": "3x-37x throughput improvement depending on task, with ~50% reduced area overhead compared to 2D design (projected)", "loc": "Abstract"}], "results": ["73.6-86.4 TOPS/W energy efficiency (normalized to binary operation), from measured TSMC 40nm prototype macro", "2.3-7 TOPS throughput (normalized to binary operation) across various DNN models", "3x-37x projected throughput improvement with heterogeneous 3D (H3D) integration vs. 2D design, depending on task", "~50% projected area overhead reduction with H3D vs. 2D design"], "limitations": ["This entry is based on the abstract only (no full text or PDF was located); the exact sub-array ADC-free mechanism, PWM encoding details, and system-level partitioning methodology are not independently verified here", "System-level and H3D performance figures are projections built on measured sub-array/macro data, not a fully fabricated and measured full accelerator or 3D-integrated chip", "Specific DNN models, datasets, and accuracy impact of the ADC-free design are not stated in the abstract"], "remarks": "ENNA is notable within the ADC/peripheral-reduction literature (category 09) because it backs its ADC-free claim with a real taped-out RRAM macro rather than pure simulation, which strengthens confidence in the reported TOPS/W and TOPS figures for the sub-array itself. However, the headline H3D throughput and area projections (3x-37x, ~50% area reduction) are extrapolations rather than measurements, and because only the abstract was available here, the accuracy/robustness implications of eliminating ADCs entirely between sub-arrays could not be assessed and should be checked in the full paper.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Compute-in-memory (CIM) is an attractive solution for machine learning hardware acceleration since it merges computation directly into memory arrays, performing parallel multiply-and-accumulate (MAC) operations. The primary challenge in the reported CIM designs is the analog-to-digital converters (ADCs) that digitize analog MAC values for further processing, causing accuracy loss, excessive power dissipation, latency penalty, and area overhead. In this work, we propose ENNA, a novel CIM architecture based on an ADC-free sub-array design, implementing inter-array data processing in an analog manner. A lightweight input encoding scheme based on pulse-width modulation (PWM) is proposed to improve the throughput. We taped-out a prototype macro and validated the proposed ADC-free RRAM array design in TSMC 40nm process. Based on the measured silicon data, we explore the system-level performance with a partition between analog and digital processing at a level higher than the sub-array. The evaluation results show that the proposed accelerator can achieve 73.6~86.4 TOPS/W energy efficiency and 2.3~7 TOPS throughput (normalized to binary operation) tested on various DNN models. Furthermore, we project the proposed design using a heterogeneous 3D integration (H3D) scheme, showing a$3\\times \\sim 37\\times $throughput improvement depending on different tasks and ~50% reduced area overhead compared to 2D design.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2022_Jiang_ENNA_TCAS-I.pdf", "analysed": true, "pdf": null, "priority": 4.19}, {"id": "W4300228436", "short": "Extreme Partial-Sum Quant", "title": "Extreme Partial-Sum Quantization for Analog Computing-In-Memory Neural Network Accelerators", "authors": ["Yulhwa Kim", "Hyungjun Kim", "Jae‐Joon Kim"], "year": 2022, "venue": "ACM Journal on Emerging Technologies in Computing Systems", "venue_short": "JETC", "venue_full": "ACM Journal on Emerging Technologies in Computing Systems", "venue_ok": true, "doi": "https://doi.org/10.1145/3528104", "cites_global": 27, "cat": "09", "seed": false, "devices": ["Generic-NVM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "A data-driven, layer-wise partial-sum quantization scheme with retraining pushes ADC resolution for analog CIM accelerators down to 2-3 bits on CIFAR-10, lower than prior reported CIM accelerator ADC resolutions.", "summary": "The paper targets the ADC overhead problem in analog compute-in-memory (CIM) accelerators, where converting analog partial sums to digital values dominates energy cost, and prior ADC-resolution-reduction schemes still required relatively high bit-widths. The authors propose a data-driven partial-sum quantization scheme that exhaustively searches for the optimal per-layer quantization range rather than relying on global (whole-network) partial-sum statistics, combined with retraining to recover accuracy. By analyzing partial-sum distribution characteristics at each layer individually, the method identifies finer-grained quantization ranges than network-wide approaches used in earlier work. Evaluated on CIFAR-10 classification, the scheme reduces the required ADC resolution to 2-3 bits, which the authors state is lower than any previously reported CIM-based neural network accelerator. The approach is positioned as a quantization/mapping-algorithm contribution rather than a circuit or device design.", "contributions": ["Data-driven partial-sum quantization scheme that exhaustively searches for an optimal quantization range with low computational overhead", "Layer-wise (rather than whole-network) analysis of partial-sum distributions to enable finer-grained, more aggressive ADC resolution reduction", "A combined quantization + retraining methodology for extreme partial-sum quantization", "Demonstration of 2-3 bit ADC resolution on CIFAR-10, lower than prior CIM accelerator designs reported at the time"], "claims": [{"claim": "Per-layer, data-driven partial-sum quantization achieves lower ADC bit resolution than prior whole-network approaches", "support": "ADC resolution reduced to 2-3 bits for CIFAR-10, described as smaller than any previous CIM-based NN accelerator", "loc": "Abstract"}], "results": ["ADC resolution reduced to 2-3 bits on CIFAR-10 with the proposed extreme partial-sum quantization + retraining methodology (no baseline accuracy/energy numbers available without full text)"], "limitations": ["Analysis based on abstract only — paper full text not available (ACM-paywalled, not found on arXiv or open-access mirrors); quantitative accuracy-vs-resolution tradeoffs and hardware energy estimates could not be independently verified beyond the abstract's stated claims", "Evaluation reported only for CIFAR-10 (per abstract); generality to larger datasets (ImageNet) or non-CNN workloads is unclear from available information", "Retraining requirement implies an iterative training-in-the-loop step whose cost/complexity is not detailed in the abstract"], "remarks": "Full text could not be retrieved (ACM Digital Library is not downloadable from this environment and no legitimate open copy was found via arXiv search or general web search within the session's search budget); this entry is abstract-only and the summary/claims are necessarily limited to what the abstract states. The core idea — layer-wise, data-driven ADC/partial-sum quantization ranges rather than global statistics — is a plausible and relevant contribution to the ADC-resolution-reduction literature for CIM accelerators (alongside ISAAC, PRIME, and related quantization/mapping frameworks it cites), but strength of evidence, exact accuracy figures, and energy benefits cannot be assessed without the full paper.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "In Analog Computing-in-Memory (CIM) neural network accelerators, analog-to-digital converters (ADCs) are required to convert the analog partial sums generated from a CIM array to digital values. The overhead from ADCs substantially degrades the energy efficiency of CIM accelerators so that previous works attempted to lower the ADC resolution considering the distribution of the partial sums. Despite the efforts, the required ADC resolution still remains relatively high. In this article, we propose the data-driven partial sum quantization scheme, which exhaustively searches for the optimal quantization range with little computational burden. We also report that analyzing the characteristics of the partial sum distributions at each layer gives an additional information to further reduce the ADC resolution compared to previous works that mostly used the characteristics of the partial sum distributions of the entire network. Based on the finer-level data-driven approach combined with retraining, we present a methodology for extreme partial-sum quantization. Experimental results show that the proposed method can reduce the ADC resolution to 2 to 3 bits for CIFAR-10 dataset, which is the smaller ADC bit resolution than any previous CIM-based NN accelerators.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2022_Kim_ExtremePartialSumQuant_JETC.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2022_Kim_ExtremePartialSumQuant_JETC.pdf", "priority": 4.41}, {"id": "W4214834240", "short": "IVQ", "title": "IVQ: In-Memory Acceleration of DNN Inference Exploiting Varied Quantization", "authors": ["Fangxin Liu", "Wenbo Zhao", "Zongwu Wang", "Yilong Zhao", "Tao Yang", "Yiran Chen", "Li Jiang"], "year": 2022, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems, vol. 41, no. 12, pp. 5313-5326 (2022)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2022.3156017", "cites_global": 18, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "IVQ reorganizes crossbar-based processing-in-memory to natively support mixed/varied weight-quantization schemes by bit-aligning weights of the same magnitude along a bitline, using a spatial mapping to exempt resulting idle ('hollow') cells and a temporal scheduling scheme to pack bits of different magnitudes onto shared bitlines, achieving up to 91.7x speedup and 541x energy savings over compared baselines.", "summary": "Crossbar-based PIM accelerators are efficient but the weight-stationary crossbar binds each weight's bits to a fixed add-operation position on the bitline, so nonuniform/diverse per-layer or per-channel quantization schemes normally must be 'rolled back' to a uniform format before mapping -- discarding the benefits of mixed quantization. IVQ instead aligns bits of equal magnitude along the same bitline, turning the quantization-diversity problem into a consistency problem; naive application of this leaves many idle ('hollow') cells, so the authors propose a spatial mapping that exempts hollow crossbars from the inter-crossbar data path, plus a temporal scheduling scheme that decouples the intra-crossbar data path from the physical bitline so bits of different magnitudes can still share a bitline over time. A temporal pipeline avoids the stalls this scheduling would otherwise introduce, and a dataflow with corresponding control logic realizes the new intra/inter-crossbar data paths. Evaluated against two PIM baselines (ISAAC, CASCADE), two customized quantization accelerators (ASIC- and FPGA-based), and an NVIDIA RTX 2080 GPU, IVQ reports 19.7x/10.7x/4.7-63.4x/91.7x speedup and 17.7x/5.1x/5.7-68.1x/541x energy savings respectively.", "contributions": ["Identification of a PIM-specific opportunity to exploit varied/mixed quantization schemes rather than rolling them back to a uniform format before crossbar mapping", "A bit-alignment reframing of the quantization-diversity problem as a bitline-consistency problem", "A spatial mapping scheme that exempts 'hollow' (idle-cell) crossbars created by naive bit-alignment from the inter-crossbar data path", "A temporal scheduling scheme decoupling the intra-crossbar data path from the physical bitline, letting differently-scaled bits share bitlines over time, with a pipelined dataflow to avoid stalls", "A full IVQ architecture/dataflow and comparative evaluation against PIM, ASIC/FPGA, and GPU baselines"], "claims": [{"claim": "IVQ achieves substantial speedup over PIM baselines, customized quantization accelerators, and GPUs by natively supporting varied quantization on crossbar PIM.", "support": "19.7x, 10.7x, 4.7-63.4x, and 91.7x speedup over ISAAC, CASCADE, ASIC/FPGA quantization accelerators, and an RTX 2080 GPU respectively", "loc": "Abstract (full text not available)"}, {"claim": "IVQ achieves substantial energy savings over the same set of baselines.", "support": "17.7x, 5.1x, 5.7-68.1x, and 541x energy savings over the same four baseline categories respectively", "loc": "Abstract (full text not available)"}], "results": ["19.7x speedup / 17.7x energy savings vs. ISAAC", "10.7x speedup / 5.1x energy savings vs. CASCADE", "4.7x-63.4x speedup / 5.7x-68.1x energy savings vs. customized ASIC/FPGA quantization accelerators", "91.7x speedup / 541x energy savings vs. NVIDIA RTX 2080 GPU"], "limitations": ["Analysis is abstract-only (full text not accessible from this machine; only IEEE Xplore hosts a PDF) -- the specific benchmarks, quantization schemes, and crossbar configuration underlying the reported multipliers are not verifiable here", "As with most ReRAM PIM architecture papers of this kind, results are expected to be simulation-based rather than measured silicon, though this could not be confirmed from the abstract alone", "The very large top-end multipliers (e.g., 541x energy savings vs. GPU) likely reflect a favorable workload/precision regime for mixed quantization; abstract does not specify which network(s)/datasets produce the top-end numbers versus the lower end of the ranges"], "remarks": "A natural companion to the same group's Bit-Transformer (bit-level sparsity) and D-NAT-adjacent quantization-aware training work: IVQ tackles the orthogonal problem of making crossbar PIM hardware itself flexible enough to exploit non-uniform quantization schemes without forcing algorithms back to a uniform format. The idea of decoupling the logical (per-magnitude) bit layout from the physical bitline via spatial+temporal scheduling is architecturally interesting and specific to the weight-stationary nature of crossbar PIM; because only the abstract was available, the practical overhead of the added control logic and pipeline, and how the reported speedups vary across real DNN benchmarks, could not be assessed here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Weight quantization is well adapted to cope with the ever-growing complexity of the deep neural network (DNN) model. Diversified quantization schemes lead to diverse quantized bit width and formats of the weights, thereby, subject to different hardware implementations. Such variety prevents a general NPU to leverage different quantization schemes to gain performance and energy efficiency. More importantly, a trend of quantization diversity emerges that applies multiple quantization schemes to different fine-grained structures (e.g., a layer or a channel of weight) of a DNN. Therefore, a general architecture is desired to exploit varied quantization schemes. The crossbar-based processing-in-memory (PIM) architecture, a promising DNN accelerator, is well known for its highly efficient matrix-vector multiplication. However, PIM suffers from the inflexible intracrossbar data path because the weight is stationary on the crossbar and binds to the “add” operation along the bitline. Therefore, many nonuniform quantization methods must rollback the quantization before mapping the weights onto the crossbar. Counterintuitively, this article discovers a unique opportunity of the PIM architecture to exploit varied quantization schemes. We first transform the quantization diversity problem into a consistency problem by aligning the bit with the same magnitude along the same bitline of the crossbar. Consequently, such naive weight mapping causes many square hollows of idle PIM cells. We then propose a novel spatial mapping to exempt these “hollow” crossbar from the intercrossbar data path. To further squeeze the weights on fewer crossbars, we decouple the intracrossbar data path from the hardware bitline by a novel temporal scheduling, so that bits with different magnitudes can be placed on cells along the same bitline. Finally, the proposed IVQ includes a temporal pipeline to avoid the introduced stalling cycles, and a data flow with delicate control mechanisms for the new intra and intercrossbar data paths. Putting all together, IVQ achieves$19.7\\times $,$10.7\\times $,$4.7\\times \\sim 63.4\\times $,$91.7\\times $speedup, and$17.7\\times $,$5.1\\times $,$5.7\\times \\sim 68.1\\times $,$541\\times $energy savings over two PIM accelerators (ISAAC and CASCADE), two customized quantization accelerators (based on ASIC and FPGA), and NVIDIA RTX 2080 GPU, respectively.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2022_Liu_IVQ_TCAD.pdf", "analysed": true, "pdf": null, "priority": 3.4}, {"id": "W3215634441", "short": "nvCIM Accuracy Opt", "title": "Accuracy Optimization With the Framework of Non-Volatile Computing-In-Memory Systems", "authors": ["Yuxuan Huang", "Yifan He", "Jinshan Yue", "Huazhong Yang", "Yongpan Liu"], "year": 2021, "venue": "IEEE Transactions on Circuits and Systems I Regular Papers", "venue_short": "TCAS-I", "venue_full": "IEEE Transactions on Circuits and Systems I: Regular Papers", "venue_ok": true, "doi": "https://doi.org/10.1109/tcsi.2021.3124553", "cites_global": 10, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "Proposes the nvCIM framework for systematically analyzing how RRAM device, array, and ADC parameters affect DNN classification accuracy in computing-in-memory systems, and introduces circuit-level fixes (a program-verify RRAM programming scheme, a margin-enhanced sense amplifier, and an offset-reduction ADC) that reach 112.1 TOPS/W macro-level energy efficiency with under 3.51% accuracy loss versus an ideal baseline.", "summary": "The paper addresses the accuracy-loss problem in non-volatile RRAM-based computing-in-memory (nvCIM) systems, noting that prior work has mostly optimized computing performance while neglecting systematic accuracy analysis. It proposes the nvCIM framework to analyze the relationship between DNN classification accuracy and key analog factors (RRAM device characteristics, crossbar array properties, and ADC parameters). Building on this analysis, it proposes concrete optimizations: an adaptive voltage-controlled SET / pulse-controlled RESET (VSPR) program-verify scheme to achieve higher-resolution RRAM states, a margin-enhancement current-mode sense amplifier (MECSA), and an offset-reduction ADC (ORADC) to improve the fidelity of analog read-out. Experimental (simulation/design) results report macro-level energy efficiency of 112.1 TOPS/W and system-level 9.86 TOPS/W, with less than 3.51% accuracy loss relative to an ideal (non-degraded) baseline, which the authors state is 2.9x-25.9x more energy efficient than existing RRAM-based nvCIM accelerators.", "contributions": ["The nvCIM framework for systematically relating DNN classification accuracy to analog design factors (device, array, ADC) in RRAM-based computing-in-memory systems", "An adaptive voltage-controlled SET / pulse-controlled RESET (VSPR) program-verify scheme for higher-resolution RRAM cell programming", "A margin-enhancement current-mode sense amplifier (MECSA) to improve read-out accuracy", "An offset-reduction ADC (ORADC) design to reduce analog-to-digital conversion error", "System/macro-level energy efficiency and accuracy evaluation showing improvement over existing RRAM nvCIM accelerators"], "claims": [{"claim": "The proposed nvCIM optimizations achieve high energy efficiency with small accuracy loss relative to an ideal baseline", "support": "Macro-level energy efficiency of 112.1 TOPS/W and system-level 9.86 TOPS/W with less than 3.51% accuracy loss vs. ideal", "loc": "Abstract"}, {"claim": "The proposed design is substantially more energy-efficient than existing RRAM-based nvCIM accelerators", "support": "2.9x-25.9x improvement in energy efficiency compared to existing RRAM-based nvCIM accelerators (abstract-level figure)", "loc": "Abstract"}], "results": ["Macro-level energy efficiency: 112.1 TOPS/W", "System-level energy efficiency: 9.86 TOPS/W", "Accuracy loss: less than 3.51% versus the ideal (non-degraded) baseline", "2.9x-25.9x energy-efficiency improvement over existing RRAM-based nvCIM accelerators (abstract-level comparison)"], "limitations": ["Only the abstract was available for this analysis (paper is paywalled, no open-access copy found); circuit implementation details, benchmark networks/datasets, and the precise baseline accuracy could not be verified from the full text", "Reported efficiency numbers appear to be from design/simulation rather than confirmed fabricated-silicon measurement (unclear from abstract alone)", "No information on which DNN models/datasets were used to obtain the 3.51% accuracy-loss figure"], "remarks": "Abstract-only analysis: this paper sits alongside other peripheral-circuit-and-accuracy-co-design work (TinyADC, Neural-PIM, On the Accuracy of Analog NN Inference Accelerators) in treating ADC/sense-amplifier/programming-scheme design as central levers for closing the accuracy gap in RRAM CIM systems, rather than relying purely on noise-aware retraining. Because no full text was accessible, the specific experimental methodology and the generality of the reported TOPS/W and accuracy-loss numbers could not be independently verified.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Computing-in-memory (CIM) is a new architecture which is more energy-efficient than the Von Neumann architecture due to the fact that it performs calculation in the memory units which can reduce a large amount of data movement. Nowadays, CIM with non-volatile memory (nvCIM), such as resistive random access memory (RRAM), has become a research frontier to further improve computing performance. Recent works mainly explored how to improve the computing performance of nvCIM, but seldom paid attention to the problem of accuracy loss. In this paper, we propose the nvCIM framework, which can systematically analyze the relationship between the classification accuracy of network models and main analog factors. Based on the nvCIM framework, we further provide detailed optimization methods, including RRAM features, array properties, and ADC parameters. The adaptive voltage-controlled SET and pulse-controlled RESET (VSPR) program-verify scheme is proposed to achieve high-resolution RRAM. And the margin enhancement based current-mode sense amplifier (MECSA) and offset reduction based analog-to-digital converter (ORADC) are proposed to improve the accuracy of analog part computing. Experimental results show that the macro-level and system-level energy efficiency is 112.1 TOPS/W and 9.86 TOPS/W respectively with less than 3.51% loss in contrast to the ideal accuracy, which is$2.9\\times $-$25.9\\times $compared to the energy efficiency of existing RRAM based nvCIM accelerators.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Huang_NvcimAccuracyOpt_TCAS-I.pdf", "analysed": true, "pdf": null, "priority": 3.23}, {"id": "W3127794782", "short": "Mixed Precision Quant ReRAM", "title": "Mixed Precision Quantization for ReRAM-based DNN Inference Accelerators", "authors": ["Sitao Huang", "Aayush Ankit", "Plínio Silveira", "Rodrigo Antunes", "Sai Rahul Chalamalasetti", "Izzat El Hajj", "Dong Eun Kim", "Glaucimar Aguiar", "Pedro Bruel", "Sergey Serebryakov", "Cong Xu", "Can Li", "Paolo Faraboschi", "John Paul Strachan", "Deming Chen", "Kaushik Roy", "Wen‐mei Hwu", "Dejan S. Milojicic"], "year": 2021, "venue": "", "venue_short": "ASP-DAC", "venue_full": "26th Asia and South Pacific Design Automation Conference (ASP-DAC 2021)", "venue_ok": true, "doi": "https://doi.org/10.1145/3394885.3431554", "cites_global": 40, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "Proposes a mixed-precision quantization scheme for ReRAM-based DNN inference accelerators that jointly quantizes weights, inputs, and partial sums (addressing ADC cost directly, unlike prior flows), searched automatically via deep reinforcement learning, cutting inference latency and energy by up to 3.89x and 4.84x respectively at only 1.18% accuracy loss.", "summary": "The paper targets the ADC overhead in ReRAM-based DNN inference accelerators, which constitutes a significant fraction of matrix-vector-multiplication cost. It observes that prior quantization flows for such accelerators do not account for partial-sum quantization (unlike in purely digital architectures, where it is less relevant), leaving ADC cost unaddressed. The authors propose a mixed-precision quantization scheme that jointly determines weight, input, and partial-sum precision per DNN layer, and an automated quantization flow based on deep reinforcement learning to search the resulting large design space for the best configuration. This is a collaboration involving HPE Labs, Purdue, UIUC and others, consistent with prior ReRAM accelerator work from this group (PUMA, PANTHER).", "contributions": ["A mixed-precision quantization scheme that jointly optimizes weight, input, and partial-sum precision per layer for ReRAM-based DNN inference accelerators", "Explicit treatment of partial-sum quantization as a first-class design variable, directly targeting ADC cost (which dominates MVM energy/latency in crossbar accelerators)", "An automated quantization flow using deep reinforcement learning to search the large joint design space for near-optimal per-layer quantization configurations"], "claims": [{"claim": "The proposed mixed-precision quantization scheme and automated flow reduce inference latency by up to 3.89x", "support": "stated result in the abstract", "loc": "Abstract"}, {"claim": "The proposed scheme reduces energy consumption by up to 4.84x", "support": "stated result in the abstract", "loc": "Abstract"}, {"claim": "These efficiency gains come at only 1.18% loss in DNN inference accuracy", "support": "stated result in the abstract", "loc": "Abstract"}], "results": ["Up to 3.89x reduction in inference latency", "Up to 4.84x reduction in energy consumption", "Only 1.18% loss in DNN inference accuracy"], "limitations": ["Full text not available to this review; specific benchmarked networks, baseline accelerator configuration, and RL search cost/convergence behavior could not be independently verified beyond the abstract", "Analysis based only on the abstract; details of how partial-sum quantization interacts with ADC resolution/area are unknown from the abstract alone"], "remarks": "This paper extends the authors' broader ReRAM PIM accelerator line (PUMA, PANTHER) by specifically targeting ADC-dominated cost through partial-sum-aware mixed-precision quantization, an angle less commonly addressed than weight/activation-only quantization in the quantization literature for analog accelerators. It is a relevant precursor to later partial-sum-focused and near-ADC-less quantization work (e.g., Partial-Sum Quantization for Near ADC-Less Compute-In-Memory Accelerators, which cites it). Full-text verification was not possible (ACM DL, not downloadable from this environment), so this entry is abstract-only.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "ReRAM-based accelerators have shown great potential for accelerating DNN inference because ReRAM crossbars can perform analog matrix-vector multiplication operations with low latency and energy consumption. However, these crossbars require the use of ADCs which constitute a significant fraction of the cost of MVM operations. The overhead of ADCs can be mitigated via partial sum quantization. However, prior quantization flows for DNN inference accelerators do not consider partial sum quantization which is not highly relevant to traditional digital architectures. To address this issue, we propose a mixed precision quantization scheme for ReRAM-based DNN inference accelerators where weight quantization, input quantization, and partial sum quantization are jointly applied for each DNN layer. We also propose an automated quantization flow powered by deep reinforcement learning to search for the best quantization configuration in the large design space. Our evaluation shows that the proposed mixed precision quantization scheme and quantization flow reduce inference latency and energy consumption by up to 3.89x and 4.84x, respectively, while only losing 1.18% in DNN inference accuracy.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Huang_MixedPrecisionQuant_ASP-DAC.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Huang_MixedPrecisionQuant_ASP-DAC.pdf", "priority": 5.06}, {"id": "W3184191382", "short": "TinyADC", "title": "TinyADC: Peripheral Circuit-aware Weight Pruning Framework for Mixed-signal DNN Accelerators", "authors": ["Geng Yuan", "Payman Behnam", "Yuxuan Cai", "Ali Reza Shafiee", "Jingyan Fu", "Zhiheng Liao", "Zhengang Li", "Xiaolong Ma", "Jieren Deng", "Jinhui Wang", "Mahdi Nazm Bojnordi", "Yanzhi Wang", "Caiwen Ding"], "year": 2021, "venue": "", "venue_short": "DATE", "venue_full": "Design, Automation & Test in Europe Conference (DATE 2021)", "venue_ok": true, "doi": "https://doi.org/10.23919/date51398.2021.9474235", "cites_global": 30, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "TinyADC is a weight-pruning framework for ReRAM-based mixed-signal DNN accelerators that is explicitly aware of peripheral ADC circuit cost, reducing required ADC resolution (and thus area/power) without introducing computational inaccuracy, achieving 3.5x power and 2.9x area reduction vs state-of-the-art pruning on ImageNet.", "summary": "Prior ReRAM-crossbar weight-pruning work for mixed-signal DNN accelerators largely ignores peripheral circuitry, even though ADCs dominate the area and power budget of such accelerators. TinyADC proposes a pruning framework that is peripheral-circuit-aware: by constraining how weights are pruned/mapped onto crossbar columns, it reduces the number of ADC resolution bits actually required, cutting ADC area and power without degrading computational accuracy (i.e., without approximating the MVM result). The approach targets the ADC overhead directly rather than treating crossbar/weight-storage reduction as the only optimization goal, situating it as a direct refinement of prior ReRAM pruning frameworks (e.g., TinyButAcc, the ADMM-based structured pruning line of work by the same group). Evaluated against a state-of-the-art pruning baseline on ImageNet, TinyADC achieves 3.5x power and 2.9x area reduction for the ADC/peripheral subsystem, and improves overall architecture throughput by 29% (GOPs/s*mm^2) and 40% (GOPs/W).", "contributions": ["Identifies that existing ReRAM DNN pruning frameworks largely overlook ADC/peripheral circuit cost despite ADCs dominating accelerator area/power", "Proposes a peripheral-circuit-aware weight pruning framework (TinyADC) that reduces required ADC resolution bits as a first-class optimization target", "Achieves ADC resolution/area/power reduction without introducing computational inaccuracy (i.e., no approximation of the dot-product result)", "Demonstrates improved throughput-per-area and throughput-per-power over a state-of-the-art accelerator baseline"], "claims": [{"claim": "TinyADC reduces peripheral circuit (power/area) cost relative to state-of-the-art pruning on ImageNet", "support": "3.5x power reduction and 2.9x area reduction compared to state-of-the-art pruning work on ImageNet", "loc": "Abstract"}, {"claim": "TinyADC improves accelerator throughput efficiency", "support": "29% improvement in GOPs/(s*mm^2) and 40% improvement in GOPs/W over state-of-the-art architecture design", "loc": "Abstract"}], "results": ["3.5x ADC power reduction vs state-of-the-art pruning baseline on ImageNet", "2.9x ADC area reduction vs state-of-the-art pruning baseline on ImageNet", "29% throughput-per-area (GOPs/s*mm^2) improvement over state-of-the-art architecture", "40% throughput-per-power (GOPs/W) improvement over state-of-the-art architecture"], "limitations": ["Full text not available to this analysis (abstract-only basis); specific network architectures, pruning ratios, ADC resolution numbers, and experimental methodology could not be independently verified", "Based on the abstract, evaluation appears limited to ImageNet-scale CNN classification and simulation/estimation rather than fabricated silicon"], "remarks": "TinyADC is a direct, closely-related follow-up/companion to the same group's ADMM-based structured pruning work (e.g., 'Tiny but Accurate') and to TinyADC's successor FORMS, which explicitly cites it as addressing ADC overhead via pruning. Because full text could not be located (not on arXiv, and other open-access aggregators were rate-limited or blocked), this entry is abstract-only and the quantitative claims are taken at face value from the DATE 2021 abstract; a thesis treatment should try to obtain the DATE proceedings version via a library for figure/table-level detail on the pruning method and ADC resolution reduction technique.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "As the number of weight parameters in deep neural networks (DNNs) continues growing, the demand for ultra-efficient DNN accelerators has motivated research on non-traditional architectures with emerging technologies. Resistive Random-Access Memory (ReRAM) crossbar has been utilized to perform insitu matrix-vector multiplication of DNNs. DNN weight pruning techniques have also been applied to ReRAM-based mixed-signal DNN accelerators, focusing on reducing weight storage and accelerating computation. However, the existing works capture very few peripheral circuits features such as Analog to Digital converters (ADCs) during the neural network design. Unfortunately, ADCs have become the main part of power consumption and area cost of current mixed-signal accelerators, and the large overhead of these peripheral circuits is not solved efficiently. To address this problem, we propose a novel weight pruning framework for ReRAM-based mixed-signal DNN accelerators, named TINYADC, which effectively reduces the required bits for ADC resolution and hence the overall area and power consumption of the accelerator without introducing any computational inaccuracy. Compared to state-of-the-art pruning work on the ImageNet dataset, TINYADC achieves 3.5× and 2.9× power and area reduction, respectively. TINYADC framework optimizes the throughput of state-of-the-art architecture design by 29% and 40% in terms of the throughput per unit of millimeter square and watt (GOPs/s×mm2and GOPs/w), respectively.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Yuan_TinyADC_DATE.pdf", "analysed": true, "pdf": null, "priority": 5.35}, {"id": "W4200477077", "short": "Bit-Transformer", "title": "Bit-Transformer: Transforming Bit-level Sparsity into Higher Preformance in ReRAM-based Accelerator", "authors": ["Fangxin Liu", "Wenbo Zhao", "Zhezhi He", "Zongwu Wang", "Yilong Zhao", "Yongbiao Chen", "Li Jiang"], "year": 2021, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad51958.2021.9643569", "cites_global": 25, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "simulation", "tldr": "Bit-Transformer exploits bit-level sparsity in power-of-two-quantized weights via a bit-flip-and-compensation scheme plus inter-crossbar bit mapping, cutting SLC-ReRAM crossbar footprint without retraining and beating prior sparse ReRAM accelerators by up to 13x energy-efficiency, 35x area-efficiency, and 67x throughput.", "summary": "The paper targets the limited row/column parallelism and poor sparsity exploitation of single-level-cell (SLC) ReRAM crossbar DNN accelerators. Weights are first quantized into a sum of a limited number of power-of-two terms (bounding the number of '1' bits per codeword), then mapped bit-wise across multiple crossbars (inter-crossbar mapping) instead of packing all bits of a weight onto one crossbar. A bit-flip-and-compensation scheme then adaptively flips selected '1' cells (compensating the resulting value bias) to cap the maximum number of '1's per column, letting more rows be driven concurrently, and prunes/locks columns with the lowest flip cost -- all without retraining on the original training data. An accompanying ReRAM-bank architecture integrates MUX-based data paths and shift-and-add logic to realize the scheme with modest peripheral overhead. Evaluated on ResNet-18/50, VGG-16, AlexNet and MobileNet-v2 over CIFAR-10/ImageNet with a GEM5+ReRAM-crossbar simulator, Bit-Transformer matches or nearly matches baseline accuracy (e.g., ResNet-18 ImageNet: 70.91% vs 71.18% original) while achieving higher crossbar sparsity (e.g., ~94-98% reported sparsity figures) than SmartExchange, Pattern-Based pruning, PIM-Prune and SRE, translating into up to 13x/35x/67x gains in energy-efficiency/area-efficiency/throughput over prior state-of-the-art sparse ReRAM designs.", "contributions": ["Power-of-two weight quantization that bounds the number of '1' bits per codeword as a preliminary sparsity source", "Inter-crossbar (bit-wise) mapping of quantized codewords across multiple crossbars instead of packing all bits of a weight on one crossbar, simplifying peripheral shift-and-add logic", "A bit-flip-and-compensation scheme that caps the max number of '1's per column (raising achievable row-parallelism) and prunes/locks low-value columns, without any retraining", "A ReRAM-bank microarchitecture (MUX-based datapaths, shift-and-add) implementing the scheme with small hardware overhead", "GEM5-based evaluation across 5 CNNs / 2 datasets showing large gains over prior sparse ReRAM accelerators (SmartExchange, Pattern-Based, PIM-Prune, SRE)"], "claims": [{"claim": "Bit-Transformer improves energy-efficiency, area-efficiency and throughput over prior state-of-the-art ReRAM accelerator designs by up to 13x, 35x and 67x respectively.", "support": "Headline comparative results in Section V (abstract reiterated with experimental figures)", "loc": "Abstract / Sec. V"}, {"claim": "The bit-flip-and-compensation scheme increases crossbar bit-level sparsity without retraining while retaining near-original accuracy.", "support": "Bit-Transformer-W/X accuracy on ImageNet for ResNet-18 is 70.91%/70.87% vs 71.18% original FP accuracy", "loc": "Table I (experiments)"}, {"claim": "Bit-Transformer achieves higher effective sparsity than prior ReRAM sparsity-exploiting accelerators (SmartExchange, PIM-Prune, SRE) at comparable or better accuracy.", "support": "Reported crossbar sparsity rates up to ~98% versus lower rates for SmartExchange/PIM-Prune baselines (Table I)", "loc": "Table I / Sec. V"}, {"claim": "On ResNet-50/ImageNet, Bit-Transformer achieves higher sparsity at lower accuracy loss than SmartExchange and SRE.", "support": "Bit-Transformer: 91.9% sparse rate at 0.6% accuracy loss vs SmartExchange 70.1% sparse/0.8% loss and SRE 83.9% sparse (loss unreported)", "loc": "Sec. V, energy-efficiency comparison"}], "results": ["Up to 13x energy-efficiency, 35x area-efficiency, and 67x throughput improvement over prior state-of-the-art ReRAM-based sparse accelerators (abstract)", "ResNet-18 on ImageNet: Bit-Transformer-W 70.91% / Bit-Transformer-X 70.87% vs 71.18% original accuracy", "On CIFAR-10, Bit-Transformer-W reaches 93.60-93.97% accuracy across the ResNet/VGG benchmarks tested, close to the 93.66-94.58% original (unpruned) accuracies and above SmartExchange/PIM-Prune/P-RM baselines in the same table", "ResNet-50 on ImageNet: Bit-Transformer achieves 91.9% crossbar sparsity at 0.6% accuracy loss vs SmartExchange's 70.1% sparsity at 0.8% loss and SRE's 83.9% sparsity", "Evaluated via Pytorch for algorithm validation plus a modified GEM5 + ReRAM-crossbar simulator (parameters derived from ISAAC/DaDianNao) for architecture-level performance/energy"], "limitations": ["Purely simulation-based (Pytorch for accuracy, modified GEM5 for hardware metrics); no fabricated chip or device-level ReRAM nonideality characterization", "Uses single-level cells (SLC) only, forgoing MLC density/area benefits in exchange for bit-level sparsity controllability", "Despite the paper's name, no Transformer/NLP/LLM workload is evaluated -- benchmarks are exclusively CNNs (ResNet, VGG, AlexNet, MobileNet-v2)", "Gains are reported relative to specific prior sparsity-exploiting baselines (SmartExchange, PIM-Prune, SRE, Pattern-Based); absolute comparison against non-sparse ISAAC-class baselines is less emphasized"], "remarks": "A representative algorithm-hardware co-design paper for exploiting bit-level (rather than weight-level or channel-level) sparsity in SLC ReRAM crossbars, with a mapping and bit-flip scheme that avoids retraining -- a practically attractive property versus many sparsity-pruning accelerators that need fine-tuning. The name is misleading: this is a CNN-sparsity/quantization-mapping paper, not a Transformer-on-ReRAM paper, so it belongs with the quantization/sparsity/mapping literature rather than the LLM-on-analog-hardware thread. Evidence is simulation-only (GEM5 + ReRAM crossbar model), so absolute throughput/energy multipliers should be read as architecture-simulator estimates rather than measured-silicon numbers; the paper is useful chiefly for its bit-flip/compensation mapping idea, later cited by bit-level-sparsity follow-ups (e.g., ERA-BS) and by IVQ (same group) for varied-quantization crossbar mapping.", "basis": "full-text", "pdf_source_url": "https://mxhx7199.github.io/files/%5BICCAD-21%5DBit-Transformer_preprint.pdf", "abstract": "Resistive Random-Access-Memory (ReRAM) crossbar is one of the most promising neural network accelerators, thanks to its in-memory and in-situ analog computing abilities for Matrix Multiplication-and-Accumulations (MACs). Nevertheless, the number of rows and columns of ReRAM cells for concurrent execution of MACs is constrained, resulting in limited in-memory computing throughput. Moreover, it is challenging to deploy Deep Neural Network(DNN) models with large model size in the crossbar, since the sparsity of DNNs cannot be effectively exploited in the crossbar structure. As the countermeasure, we develop a novel ReRAM-based DNN accelerator, named Bit-Transformer, which pays attention to the correlation between the bit-level sparsity and the performance of the ReRAM-based crossbar. We propose a superior bit-flip scheme combined with the exponent-based quantization, which can adaptively flip the bits of the mapped DNNs to release redundant space without sacrificing the accuracy much or incurring much hardware overhead. Meanwhile, we design an architecture that can integrate the techniques to massively shrink the crossbar footprint to be used. In this way, It efficiently leverages the bit-level sparsity for performance gains while reducing the energy consumption of computation. The comprehensive experiments indicate that our Bit-Transformer outperforms prior state-of-the-art designs up to 13 x, 35 x, and 67 x, in terms of energy-efficiency, area-efficiency, and throughput, respectively. Code will be open-source in the camera-ready version.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Liu_BitTransformer_ICCAD.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Liu_BitTransformer_ICCAD.pdf", "priority": 5.58}, {"id": "W3211168157", "short": "Neural-PIM", "title": "Neural-PIM: Efficient Processing-In-Memory with Neural Approximation of Peripherals", "authors": ["Weidong Cao", "Yilong Zhao", "Adith Boloor", "Yinhe Han", "Xuan Zhang", "Li Jiang"], "year": 2021, "venue": "IEEE Transactions on Computers", "venue_short": "TC", "venue_full": "IEEE Transactions on Computers", "venue_ok": true, "doi": "https://doi.org/10.1109/tc.2021.3122905", "cites_global": 22, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet", "LSTM/RNN"], "evidence": "simulation", "tldr": "Neural-PIM replaces ADC quantization and shift-add accumulation peripherals in RRAM crossbar PIM with small RRAM-crossbar-based neural-network approximators (NeuralPeriph), extending accumulation into the analog domain to cut A/D conversions and improve both energy efficiency and throughput over ISAAC and CASCADE.", "summary": "The paper targets the ADC/peripheral overhead problem in RRAM-based PIM accelerators (58% of system energy in ISAAC, up to 98% of area in some designs). It first builds an analytical framework characterizing existing accumulation/quantization dataflow strategies (ISAAC-style digital accumulate-after-quantize, CASCADE-style analog buffering) and identifies that extending shift-and-add (S+A) accumulation fully into the analog domain, before a single final quantization, can minimize required A/D conversions. It then proposes NeuralPeriph: small neural-network-based approximators for both the analog S+A circuit (NNS+A) and the ADC (NNADC), physically synthesized using RRAM crossbar arrays plus CMOS inverters so they are area- and energy-efficient and reuse the same crossbar substrate as the main compute arrays. These NeuralPeriph circuits are assembled into a full accelerator, Neural-PIM, evaluated with a custom full-system simulator against ISAAC- and CASCADE-style baselines on 8 CNNs (AlexNet, ResNet-50/101, VGG-16/19, Inception, MobileNet, etc.) and 1 RNN (LSTM), all trained on ImageNet with 8-bit quantization. Neural-PIM achieves large energy-efficiency and throughput gains without accuracy loss, while keeping crossbar array density comparable to the baselines despite using higher-resolution DACs.", "contributions": ["Analytical framework characterizing the dataflow/accumulation strategies of existing RRAM-based PIM accelerators (ISAAC, CASCADE, etc.) and identifying the opportunity to extend accumulation into the analog domain", "NeuralPeriph: a neural-approximation method to implement both analog shift-add accumulation (NNS+A) and quantization (NNADC) as small neural networks synthesized directly on RRAM crossbar arrays", "Neural-PIM accelerator design built on the extended analog dataflow with NeuralPeriph peripherals, including a full system-level design and accuracy analysis", "Comprehensive system-level evaluation (energy, throughput, area/density) against ISAAC- and CASCADE-style baselines on 9 DNN benchmarks"], "claims": [{"claim": "Neural-PIM substantially improves energy efficiency over both ISAAC-style and CASCADE-style accelerators", "support": "5.36x energy-efficiency improvement vs. ISAAC-style, 1.73x vs. CASCADE-style, averaged across 8 CNN + 1 RNN benchmarks", "loc": "Sec. 7.2, Fig. 12(a)"}, {"claim": "Neural-PIM substantially improves throughput over both baselines", "support": "3.43x throughput vs. ISAAC-style, 1.59x vs. CASCADE-style", "loc": "Sec. 7.2, Fig. 12(b)"}, {"claim": "The analog NNS+A accumulation circuit is far cheaper than the ADCs it effectively replaces", "support": "The NNS+A analog summation in Neural-PIM consumes 33x less energy than the ADCs of ISAAC", "loc": "Sec. 7.2, Fig. 13"}, {"claim": "These gains come without sacrificing crossbar array density / area efficiency, despite using higher-resolution DACs", "support": "Computing-array density: ISAAC 0.68%, CASCADE 0.76%, Neural-PIM 0.71% of PE area (Table 3), with Neural-PIM using 4-bit DAC / 8-bit effective ADC resolution vs. ISAAC's 1-bit DAC / 7-bit ADC and CASCADE's 1-bit DAC / 10-bit interface", "loc": "Sec. 7.3, Table 3"}, {"claim": "The gains are achieved without inference accuracy loss", "support": "Reported as accuracy-neutral across all 9 benchmarks (AlexNet, ResNet-50/101, VGG-16/19, Inception, MobileNet, LSTM) on ImageNet with 8-bit quantization", "loc": "Sec. 7, Conclusion"}], "results": ["5.36x (1.73x) average energy-efficiency improvement over ISAAC-style (CASCADE-style) baselines across 9 DNN benchmarks", "3.43x (1.59x) average throughput improvement over ISAAC-style (CASCADE-style) baselines", "NNS+A analog accumulation circuit: 33x lower energy than ISAAC's ADCs", "PE-level computing-array density: ISAAC 0.68%, CASCADE 0.76%, Neural-PIM 0.71% (Table 3), using 128x128 1-bit-cell RRAM arrays, 8-bit inputs/weights", "Peripheral configuration per 64 arrays: ISAAC 64 ADCs (8-bit, 1-bit DAC), CASCADE 3 ADCs (10-bit-equivalent interface, 1-bit DAC), Neural-PIM 4 NNADCs (8-bit, 4-bit DAC)"], "limitations": ["Purely simulation-based evaluation (full-system simulator); no fabricated chip or silicon measurement of NeuralPeriph circuits", "Relies on training small neural-network approximators offline for S+A and ADC functions, whose robustness to device variation/noise/drift beyond what is modeled is not deeply explored", "Baselines (ISAAC, CASCADE) are reconstructed/simulated rather than measured hardware, so comparisons are simulator-to-simulator", "Benchmarks are standard CNN/LSTM image/sequence workloads; no transformer/LLM evaluation"], "remarks": "This is a creative peripheral-circuit redesign that reframes ADC/accumulation as a learned function approximation problem and implements it on the same RRAM-crossbar substrate as the compute arrays, which is an elegant way to amortize area/energy cost. The gains over ISAAC and CASCADE are large and consistent across both energy and throughput, and the density table (Table 3) gives a rare direct peripheral-area comparison across three design styles. However, all results are simulator-based, and the practical manufacturability and noise/variation robustness of training-time-synthesized NNS+A/NNADC circuits on real RRAM arrays is not validated against fabricated silicon, so these numbers should be read as an upper-bound architectural projection rather than a demonstrated result.", "basis": "full-text", "pdf_source_url": "", "abstract": "Processing-in-memory (PIM) architecture has demonstrated great potentials in accelerating numerous deep learning tasks. In particular, resistive random-access memory (RRAM) technology provides a promising hardware substrate for PIM accelerators, because it can support efficient in-situ vector-matrix multiplications (VMMs) with high-density RRAM crossbar arrays. However, such accelerators suffer from frequent and energy-intensive analog-to-digital (A/D) conversions, severely limiting their performance. This paper proposes a new PIM architecture to efficiently accelerate deep learning tasks by minimizing the required A/D conversions with neural approximated peripheral circuits. By characterizing the existing dataflows of state-of-the-art PIM architectures, we first propose a new dataflow by extending shift and add (S+A) operations into the analog domain before the final A/D conversion, which can remarkably reduce the required A/D conversions for a dot-product. We then elaborate on a neural approximation method to design both accumulation circuits (S+A) and quantization circuits (ADC) using RRAM crossbar arrays. Finally, we apply them to build a RRAM-based PIM accelerator--\\textbf{Neural-PIM} based on the proposed analog dataflow and evaluate its system-level performances. Evaluations on different DNN benchmarks demonstrate that Neural-PIM can improve energy efficiency by 5.36x (1.73x) and speed up throughput by 3.43x (1.59x) without losing accuracy, compared to state-of-the-art RRAM-based PIM accelerators, i.e., ISAAC} (CASCADE)", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Cao_NeuralPIM_TC.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Cao_NeuralPIM_TC.pdf", "priority": 4.35}, {"id": "W3131573445", "short": "RaQu", "title": "An Automated Quantization Framework for High-Utilization RRAM-Based PIM", "authors": ["Bing Li", "Songyun Qu", "Ying Wang"], "year": 2021, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2021.3061521", "cites_global": 20, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "algorithm+simulation", "tldr": "RaQu is an AutoML-based quantization framework for RRAM-based PIM that generates a fine-grained, hardware-structure-aware quantization strategy to maximize crossbar resource utilization, improving utilization by 29.2-37.4% and accuracy by 1.8-3.3% over prior coarse-grained quantization methods.", "summary": "The paper addresses resource under-utilization in RRAM-based processing-in-memory (PIM) DNN accelerators caused by a mismatch between neural-network layer structure and the fixed crossbar array geometry, which leaves many RRAM cells unused when deploying a network. Prior quantization approaches, the authors argue, ignore this hardware-structure information and therefore fail to improve utilization. RaQu is proposed as an automated quantization framework that leverages AutoML to generate a fine-grained quantization strategy jointly informed by the neural network model and the heterogeneous RRAM crossbar structure, aiming to fully utilize PIM hardware resources for any given model.", "contributions": ["Identification of the resource-utilization problem caused by mismatch between DNN layer dimensions and fixed RRAM crossbar array sizes under conventional (coarse-grained) quantization", "RaQu: an AutoML-driven quantization framework that incorporates hardware structure information (heterogeneous crossbar sizes) into the quantization search", "Joint consideration of model parameters and RRAM hardware information to automatically generate fine-grained, per-layer quantization strategies", "Demonstrated improvements in both resource utilization and model accuracy versus prior coarse-grained quantization baselines"], "claims": [{"claim": "RaQu improves RRAM-based PIM resource utilization by 29.2% to 37.4% over prior coarse-grained quantization methods", "support": "stated experimental result in the abstract", "loc": "Abstract"}, {"claim": "RaQu simultaneously improves model accuracy by 1.8% to 3.3% over prior coarse-grained quantization methods", "support": "stated experimental result in the abstract", "loc": "Abstract"}], "results": ["29.2%-37.4% improvement in RRAM-based PIM resource utilization versus coarse-grained quantization baselines", "1.8%-3.3% improvement in model accuracy versus coarse-grained quantization baselines"], "limitations": ["Full text not available to this review; specific networks/datasets evaluated, the AutoML search method details, and search cost were not independently verified beyond the abstract", "Analysis based only on the abstract; the exact definition and measurement methodology for 'resource utilization' is unknown from the abstract alone"], "remarks": "RaQu targets a specific and often-overlooked inefficiency in RRAM PIM deployment: crossbar resource under-utilization due to layer/array size mismatch, complementing more commonly studied accuracy-vs-bitwidth quantization work by jointly optimizing for hardware utilization. The framing is similar in spirit to other hardware-aware quantization/mapping work in this collection (e.g., Mixed Precision Quantization for ReRAM-based DNN Inference Accelerators). Full-text verification was not possible from this environment, so this entry is abstract-only.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "With the advancement of deep neural networks (DNNs), the applications driven by DNNs have been spread from the cloud to the edge. However, the intensive computations and data movements in CNNs impede the adoption of DNNs in resource-constraint edge devices.Quantization, a common model compression method, has attracted a lot of attention as it enables efficient inference by lowering the data bit-width of CNN parameters. Due to the features of massive storage and computing-in-memory array, resistive memory (RRAM) has established the energy efficiency and small area processing-in-memory (PIM) for the acceleration of DNNs at the edge end. However, when deploying the network onto resistive-memory-based PIM (RRAM-based PIM), there will be tremendous unused cells due to the mismatch between the structure of the neural network layer and memory array, resulting in the resource under-utilization and low computation efficiency. In this work, we observed prior quantization approaches fail to improve hardware resource utilization as they ignored the hardware structure information in RRAM. Thus, combining the information of the neural network model and hardware information is essential for a high-utilization RRAM-based PIM design. Considering the vast model parameters and heterogeneous RRAM crossbar structure, we develop a novel quantization framework by leveraging the AutoML technique, i.e., RaQu, which automatically generates a fine-grained quantization strategy for any model that fully utilizes the resource of RRAM-based PIM. The experimental results show that RaQu achieves at most 29.2%–37.4% and 1.8%–3.3% improvement in resource utilization and model accuracy, respectively, compared to prior coarse-grained quantization methods.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Li_RaQu_TCAD.pdf", "analysed": true, "pdf": null, "priority": 3.43}, {"id": "W4200001938", "short": "Quarry", "title": "Quarry: Quantization-based ADC Reduction for ReRAM-based Deep Neural Network Accelerators", "authors": ["Azat Azamat", "Faaiz Asim", "Jongeun Lee"], "year": 2021, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad51958.2021.9643502", "cites_global": 21, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "Quarry uses advanced quantization techniques (no hardware changes) to shrink the ADC resolution/size needed in ReRAM crossbar DNN accelerators, cutting ADC size 32x versus ISAAC at only 0.24 percentage-point accuracy loss on ImageNet.", "summary": "The paper addresses the well-known ADC overhead problem in ReRAM crossbar DNN accelerators, where peripheral analog-to-digital converters dominate area and/or slow down operation. Instead of changing the crossbar hardware, Quarry applies quantization techniques to reduce the required ADC precision/size, and is presented as general-purpose: it does not restrict the DNN type (binarized or multi-bit weights) or the ReRAM crossbar array size. Experimental results with ResNet on ImageNet show a large reduction in ADC size relative to the ISAAC baseline with only a very small accuracy loss. (Full text was not accessible from this machine; this entry is based on the abstract and OpenAlex metadata only, so method details beyond the abstract — e.g., the specific quantization scheme, whether it requires retraining, and comparisons beyond ISAAC — are not captured here.)", "contributions": ["A quantization-based method to reduce ADC resolution/overhead in ReRAM crossbar DNN accelerators without hardware modification", "A general approach claimed to be independent of DNN type (binarized vs. multi-bit) and crossbar array size", "Experimental demonstration on ResNet/ImageNet showing large ADC size reduction versus ISAAC at minimal accuracy cost"], "claims": [{"claim": "Quarry reduces ADC size substantially relative to the ISAAC baseline with negligible accuracy loss", "support": "32x reduction in ADC size compared with ISAAC at an accuracy loss of only 0.24 percentage points, measured with ResNet on ImageNet", "loc": "Abstract"}, {"claim": "The method requires no hardware changes and generalizes across DNN/ReRAM configurations", "support": "Stated in abstract: 'does not require any hardware change' and 'no restriction in terms of DNN type (binarized or multi-bit) or ReRAM crossbar array size'", "loc": "Abstract"}], "results": ["32x reduction in ADC size vs. ISAAC at 0.24 percentage-point accuracy loss (ResNet, ImageNet)"], "limitations": ["Analysis based on abstract and metadata only; full methodology, baselines beyond ISAAC, and robustness/noise considerations could not be verified", "No open-access copy found (OpenAlex reports closed access, no repository full text; IEEE Xplore not reachable from this environment)"], "remarks": "This entry is abstract-only: a legitimate open copy could not be located (OpenAlex flags the work as closed access with no repository full text, and only IEEE Xplore hosts it). The claimed 32x ADC size reduction at 0.24-point accuracy loss is a strong, specific result in the same vein as other ADC-reduction work in this collection (e.g., TinyADC, Neural-PIM), suggesting a growing consensus that ADC overhead is the dominant cost center of ReRAM crossbar accelerators and that software-only quantization changes (no circuit redesign) can meaningfully attack it. This should be revisited with the full text if institutional IEEE Xplore access becomes available.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "ReRAM (Resistive Random-Access Memory) crossbar arrays have the potential to provide extremely fast and low-cost DNN (Deep Neural Network) acceleration. However, peripheral circuits, in particular ADCs (Analog-Digital Converters), can be a large overhead and/or slow down the operation considerably. In this paper we propose to use advanced quantization techniques to reduce the ADC overhead of ReRAM crossbar arrays. Our method does not require any hardware change but can reduce the overhead of ADC greatly. Our methodology is also general, having no restriction in terms of DNN type (binarized or multi-bit) or ReRAM crossbar array size. Our experimental results using ResNet on ImageNet dataset demonstrate that our method can reduce the size of ADC by 32× compared with ISAAC at very little accuracy loss of 0.24%p.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2021_Azamat_Quarry_ICCAD.pdf", "analysed": true, "pdf": null, "priority": 5.24}, {"id": "W3013407975", "short": "Tiny but Accurate (P-RM)", "title": "Tiny but Accurate: A Pruned, Quantized and Optimized Memristor Crossbar Framework for Ultra Efficient DNN Implementation", "authors": ["Xiaolong Ma", "Geng Yuan", "Sheng Lin", "Caiwen Ding", "Fuxun Yu", "Tao Liu", "Wujie Wen", "Xiang Chen", "Yanzhi Wang"], "year": 2020, "venue": "", "venue_short": "ASP-DAC", "venue_full": "25th Asia and South Pacific Design Automation Conference (ASP-DAC 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/asp-dac47756.2020.9045658", "cites_global": 53, "cat": "09", "seed": false, "devices": ["Memristor(generic)"], "models": ["CNN", "ResNet", "MLP"], "evidence": "algorithm+simulation", "tldr": "An ADMM-based structured pruning and quantization framework for memristor crossbar DNNs, extended with a Network Purification / Unused Path Removal post-processing step, achieves up to 231.82x compression on LeNet-5 and 59.84x on ResNet-18 with negligible accuracy loss and large area/power reductions.", "summary": "The paper addresses extreme model compression for memristor crossbar DNN accelerators, where pruning and quantization must jointly respect hardware constraints (fixed crossbar block sizes, limited memristance levels). It formulates structured (filter/channel/shape-wise) weight pruning and discrete weight quantization as two memristor-aware constraint sets solved jointly via ADMM (alternating direction method of multipliers). The authors observe that ADMM's solution is non-optimal and leaves redundant 'unused paths' in a structured-pruned network, so they add a software-hardware co-optimization stage: Network Purification (removing channels/filters below importance and emptiness thresholds) and Unused Path Removal (removing connections made dead by upstream pruning), followed by knowledge-distillation-guided quantization to 8-bit memristor weight representations (two 4-bit memristors per weight). Evaluated on LeNet-5/MNIST, ConvNet/VGG-16/ResNet-18 on CIFAR-10, and AlexNet/ResNet-18/ResNet-50 on ImageNet, using NVSim-derived power/area models for 1R memristor crossbars (Ron=1MOmega, Roff=10MOmega) at 45nm. The method reaches compression ratios up to 231.82x on LeNet-5 (0.4% accuracy drop), 59.84x on ResNet-18/CIFAR-10, and 3.33x/2.70x on ImageNet ResNet-18/50, with 8-bit quantization causing little to no further accuracy loss, and reduces crossbar area/power substantially (e.g., ResNet-18 15.14x model: 0.117mm^2/1.622W down to 0.041mm^2/0.556W).", "contributions": ["Joint memristor-aware ADMM formulation combining structured (filter/channel/shape) weight pruning and discrete weight quantization into a single regularized optimization", "Discovery that ADMM pruning leaves non-optimal, unused data paths in structured-pruned networks", "Network Purification and Unused Path Removal (P-RM) post-processing algorithm using emptiness-ratio and importance-score thresholds to remove redundant channels/filters without retraining", "Knowledge-distillation-guided quantization of pruned weights to 8-bit memristor representation (via two 4-bit devices)", "Evaluation of compression, accuracy, and memristor crossbar area/power (via NVSim) across LeNet-5, ConvNet, VGG-16, ResNet-18/50, AlexNet on MNIST/CIFAR-10/ImageNet"], "claims": [{"claim": "P-RM substantially increases achievable compression ratio over plain ADMM pruning at comparable accuracy", "support": "LeNet-5 compression improves from 45.54x (without P-RM) to 231.82x (with P-RM) with only 0.4% accuracy drop (99.17%->98.05%)", "loc": "Table 1"}, {"claim": "The framework outperforms prior structured pruning (Group Scissor) at equal or higher compression", "support": "CIFAR-10 ConvNet: 84.55% accuracy at 2.35x vs. Group Scissor's 82.09% at 4.16x on LeNet-5-class comparison; VGG-16/ResNet-18 pushed to 50.02x/59.84x", "loc": "Sec. 6, Table 1"}, {"claim": "8-bit memristor weight quantization causes negligible accuracy loss after structured pruning", "support": "No accuracy loss on 40x/88x LeNet-5 models after quantization; ResNet-18/50 ImageNet models show no accuracy loss after quantization, ~1% loss on 5.13x AlexNet", "loc": "Sec. 6 (MNIST/ImageNet results)"}, {"claim": "P-RM reduces memristor crossbar hardware footprint (area and power) substantially with no/minimal accuracy loss", "support": "ResNet-18 5.83x model: area 0.235mm^2->0.042mm^2, power 3.359W->0.585W; VGG-16 20.16x model: area 0.113mm^2->0.056mm^2, power 1.611W->0.824W", "loc": "Table 2"}, {"claim": "On ImageNet, the framework beats prior SSL compression on AlexNet in both ratio and accuracy", "support": "4.69x compression with 81.76% accuracy vs. SSL's 1.40x with 80.40% accuracy", "loc": "Sec. 6 (ImageNet)"}], "results": ["LeNet-5/MNIST: up to 231.82x compression with P-RM, 98.05% accuracy (vs. 99.17% original)", "ResNet-18/CIFAR-10: up to 59.84x compression, 93.22-93.27% accuracy after quantization", "VGG-16/CIFAR-10: up to 50.02x compression, 93.36% accuracy after quantization", "ImageNet ResNet-18/ResNet-50: 3.33x/2.70x compression at 88.36%/92.27% top-5 accuracy with no accuracy loss from 8-bit quantization", "ResNet-18 crossbar area/power reduced from 0.235mm^2/3.359W to 0.042mm^2/0.585W at 5.83x compression (no accuracy loss)"], "limitations": ["Evaluated purely in software simulation (PyTorch models + NVSim for area/power); no fabricated memristor crossbar or device-level non-ideality (variation, drift, IR drop) modeling beyond the nominal Ron/Roff values", "Results reported as 'non-retraining' after P-RM, meaning no fine-tuning after the purification step is used, which may understate potential accuracy recovery or risk", "Posted as an arXiv preprint (arXiv:1908.10017) alongside the ASP-DAC 2020 publication; some claims (e.g., 'first to discover' unused paths) are self-reported", "Assumes a single memristor device/crossbar technology (1R, fixed Ron/Roff, 128x64 crossbars) rather than exploring sensitivity across device types"], "remarks": "This is primarily an algorithmic compression paper (ADMM pruning + quantization + a purification heuristic) with hardware costs estimated via NVSim rather than measured; the 'memristor crossbar' framing mainly constrains the pruning granularity (structured, block-aligned) and the quantization levels rather than modeling realistic analog non-idealities. It is a useful data point for how aggressive compression (two orders of magnitude) can shrink crossbar area/power for mapping CNNs, but readers interested in device variation or IR-drop robustness should look to other papers in this collection (e.g., ITT-RNA, IR-QNN) for more hardware-realistic treatments.", "basis": "full-text", "pdf_source_url": "", "abstract": "The memristor crossbar array has emerged as an intrinsically suitable matrix computation and low-power acceleration framework for DNN applications. Many techniques such as memristor-based weight pruning and memristor-based quantization have been studied. However, the high accuracy solution for the above techniques is still waiting for unraveling. In this paper, we propose a memristor-based DNN framework which combines both structured weight pruning and quantization by incorporating ADMM algorithm for better pruning and quantization performance. We also discover the non-optimality of the ADMM solution in weight pruning and the unused data path in a structured pruned model. We design a software-hardware co-optimization framework which contains the first proposed Network Purification and Unused Path Removal algorithms targeting on post-processing a structured pruned model after ADMM steps. By taking memristor hardware constraints into our whole framework, we achieve extreme high compression rate with minimum accuracy loss. For quantizing structured pruned model, our framework achieves nearly no accuracy loss after quantizing weights to 8-bit memristor weight representation. We share our models at anonymous link https://bit.ly/2VnMUy0.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2020_Ma_TinyButAccurate_ASPDAC.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2020_Ma_TinyButAccurate_ASPDAC.pdf", "priority": 5.54}, {"id": "W2945592020", "short": "LB-CNN", "title": "Low Bit-Width Convolutional Neural Network on RRAM", "authors": ["Yi Cai", "Tianqi Tang", "Lixue Xia", "Boxun Li", "Yu Wang", "Huazhong Yang"], "year": 2019, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (TCAD), 2019/2020", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2019.2917852", "cites_global": 68, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "Proposes a low bit-width RRAM crossbar CNN (LB-CNN) accelerator with a matrix-splitting strategy for oversized weight matrices, a line-buffer pipeline for inference, and a splitting-and-quantizing-while-training method, achieving roughly 6x pipeline speedup on ResNet-18 and ~55% energy / ~48% area savings versus a multi-bit RRAM VGG-8.", "summary": "High-precision RRAM-based computing is limited by resistance-level and ADC/DAC interface constraints, motivating low bit-width CNNs that use low bit-width RRAM devices and interfaces. The paper (per its abstract) addresses three open system-design problems for such low bit-width RRAM-based CNN systems (RCS): how to split a weight matrix across multiple crossbars when it does not fit in one, how to pipeline inference using a line-buffer structure, and how to limit the accuracy drop introduced by splitting and quantization. It proposes an RRAM crossbar-based low-bit-width CNN (LB-CNN) accelerator with matrix-splitting strategies for scalability, a pipelined line-buffer implementation to accelerate inference, and a 'splitting and quantizing while training' method that bakes the hardware constraints into training. Reported results (from the abstract) include low bit-width LeNet-5 on RRAM showing better robustness to device variation than multi-bit models, about 6.0x per-image speedup from the pipeline strategy on ResNet-18, and for low-bit VGG-8 on CIFAR-10, 54.9% energy and 48.3% area savings versus a multi-bit VGG-8 implementation.", "contributions": ["Matrix-splitting strategies for mapping CNN weight matrices too large for a single crossbar onto multiple crossbars with improved scalability", "A pipelined inference architecture based on line-buffer structures to accelerate CNN inference on the low bit-width RRAM system", "A 'splitting and quantizing while training' method that incorporates the actual hardware splitting/quantization constraints directly into network training to reduce accuracy drop", "System-level design and evaluation of an RRAM crossbar-based low bit-width CNN (LB-CNN) accelerator across LeNet-5, ResNet-18 and VGG-8"], "claims": [{"claim": "Low bit-width CNNs mapped to RRAM are more robust to device variation than multi-bit CNN models.", "support": "Low bit-width LeNet-5 on RRAM shows much better robustness than multi-bit models with device variation (per abstract).", "loc": "Abstract"}, {"claim": "The proposed line-buffer pipeline substantially accelerates per-image inference.", "support": "Approximately 6.0x speedup to process each image on ResNet-18.", "loc": "Abstract"}, {"claim": "The LB-CNN accelerator reduces energy and area versus a multi-bit RRAM implementation of the same network.", "support": "For low-bit VGG-8 on CIFAR-10, saves 54.9% of energy consumption and 48.3% of area compared with the multi-bit VGG-8 structure.", "loc": "Abstract"}], "results": ["~6.0x per-image inference speedup on ResNet-18 from the pipelined line-buffer strategy (vs. non-pipelined baseline, per abstract)", "54.9% energy savings and 48.3% area savings for low-bit VGG-8 on CIFAR-10 vs. a multi-bit VGG-8 RRAM structure", "Improved robustness to device variation for low bit-width LeNet-5 vs. multi-bit models (no exact figure given in abstract)"], "limitations": ["Analysis based on the paper's abstract only -- no verified open-access full text was found (IEEE Xplore only; no arXiv/author-page copy located), so method details (exact matrix-splitting algorithm, precise bit-widths, full benchmark table) could not be independently checked", "Reported numbers are quoted from the abstract and should be treated as headline figures rather than fully contextualized results"], "remarks": "This paper sits in the same Tsinghua RRAM-mapping lineage as SemiMap, Crossbar-Aware Pruning and the Mixed-Size-Crossbar paper in this collection, tackling a genuinely practical problem (splitting oversized weight matrices across crossbars plus a hardware-aware training loop) rather than a purely algorithmic quantization trick. Because only the abstract was accessible, the specific matrix-splitting algorithm and the quantitative accuracy-vs-compression trade-off curves could not be verified here; the headline 6x pipeline speedup and ~50% area/energy savings for VGG-8 are self-reported and should be cross-checked against the published TCAD version when available.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The emerging resistive random-access memory (RRAM) has been widely applied in accelerating the computing of deep neural networks. However, it is challenging to achieve highprecision computations based on RRAM due to the limits of the resistance level and the interfaces. Low bit-width convolutional neural networks (CNNs) provide promising solutions to introduce low bit-width RRAM devices and low bit-width interfaces in RRAM-based computing system (RCS). While open questions still remain regarding: 1) how to make matrix splitting when a single crossbar is not large enough to hold all parameters of one weight matrix; 2) how to design a pipeline to accelerate the inference based on line buffer structure; and 3) how to reduce the accuracy drop due to the parameter splitting and data quantization. In this paper, we propose an RRAM crossbar-based low bit-width CNN (LB-CNN) accelerator. We make detailed discussion on the system design, including the matrix splitting strategies to enhance the scalability, and the pipelined implementation based on line buffers to accelerate the inference. In addition, we propose a splitting and quantizing while training method to incorporate the actual hardware constraints with the training. In our experiments, low bit-width LeNet-5 on RRAM show much better robustness than multibit models with device variation. The pipeline strategy achieves approximately 6.0× speedup to process each image on ResNet-18. For low-bit VGG-8 on CIFAR-10, the proposed accelerator saves 54.9% of the energy consumption and 48.3% of the area compared with the multibit VGG-8 structure.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2019_Cai_LBCNN_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.62}, {"id": "W2910506572", "short": "Sparse ReRAM Mapping", "title": "Learning the sparsity for ReRAM", "authors": ["Jilan Lin", "Zhenhua Zhu", "Yu Wang", "Yuan Xie"], "year": 2019, "venue": "", "venue_short": "ASP-DAC", "venue_full": "24th Asia and South Pacific Design Automation Conference (ASP-DAC 2019)", "venue_ok": true, "doi": "https://doi.org/10.1145/3287624.3287715", "cites_global": 79, "cat": "09", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "Proposes an element-clustering sparse-NN mapping scheme plus crossbar-grained pruning for ReRAM crossbars, reporting 3-5x energy efficiency and >2.5-6x speedup over dense-NN accelerators with negligible accuracy loss.", "summary": "The paper targets the inefficiency of mapping sparse neural networks onto ReRAM crossbars: conventional accelerators map the full dense weight matrix onto the crossbar to preserve O(1) computation, wasting crossbar capacity on zero weights. The authors propose a mapping scheme based on clustering nonzero elements to improve crossbar utilization for sparse NNs, combined with a crossbar-grained pruning algorithm that removes entire crossbars with low utilization rather than pruning individual weights. They additionally analyze how limited ReRAM device precision interacts with sparse mapping and propose composing higher precision in the analog domain with supporting peripheral circuit design. Experiments sweep crossbar sizes to find an efficiency-optimized design point and measure energy, speedup, and accuracy against dense-NN ReRAM accelerators.", "contributions": ["Element-clustering-based mapping scheme for sparse NN weights onto ReRAM crossbars to raise crossbar utilization", "Crossbar-grained pruning algorithm that eliminates whole low-utilization crossbars rather than individual weights", "Analysis of quantization precision effects for sparse NN mapping and an analog-domain high-precision composition scheme with periphery circuit design", "Design-space exploration across crossbar sizes to identify an energy/performance-optimized configuration"], "claims": [{"claim": "The proposed sparse mapping + crossbar-grained pruning improves energy efficiency over dense-NN ReRAM accelerators", "support": "3-5x energy efficiency improvement", "loc": "abstract"}, {"claim": "The scheme improves throughput/speedup over dense-NN accelerators", "support": "more than 2.5-6x speedup", "loc": "abstract"}, {"claim": "Pruning for sparsity causes little to no accuracy degradation", "support": "accuracy experiments show almost no accuracy loss", "loc": "abstract"}], "results": ["3-5x energy efficiency vs. dense-NN ReRAM accelerators", "More than 2.5-6x speedup vs. dense-NN ReRAM accelerators", "Near-zero accuracy loss from the proposed pruning method"], "limitations": ["Full methodological details (clustering algorithm specifics, exact benchmark networks, baseline accelerator identity) not verifiable beyond the abstract since full text could not be obtained", "Analysis based on abstract only; quantitative claims not independently checked against figures/tables", "No information from abstract on whether evaluation is architectural simulation only or includes circuit-level/device non-ideality modeling"], "remarks": "This is a short ASP-DAC paper addressing a real practical gap: dense crossbar mapping wastes array capacity on pruned/sparse weights, so crossbar-grained pruning (removing whole low-utilization crossbars) is a sensible unit of sparsity for PIM architectures, as opposed to element-wise pruning which does not reduce dense-matrix mapping costs. Because only the abstract was accessible, the reported energy/speedup numbers should be treated as the authors' own baseline-relative figures without independent verification of baselines or benchmarks; it sits alongside other sparsity-aware ReRAM mapping work (e.g., crossbar pruning, bit-level sparsity accelerators) cited by later papers in this collection.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "With the in-memory processing ability, ReRAM based computing gets more and more attractive for accelerating neural networks (NNs). However, most ReRAM based accelerators cannot support efficient mapping for sparse NN, and we need to map the whole dense matrix onto ReRAM crossbar array to achieve O(1) computation complexity. In this paper, we propose a sparse NN mapping scheme based on elements clustering to achieve better ReRAM crossbar utilization. Further, we propose crossbar-grained pruning algorithm to remove the crossbars with low utilization. Finally, since most current ReRAM devices cannot achieve high precision, we analyze the effect of quantization precision for sparse NN, and propose to complete high-precision composing in the analog field and design related periphery circuits. In our experiments, we discuss how the system performs with different crossbar sizes to choose the optimized design. Our results show that our mapping scheme for sparse NN with proposed pruning algorithm achieves 3 -- 5X energy efficiency and more than 2.5 -- 6X speedup, compared with those accelerators for dense NN. Also, the accuracy experiments show that our pruning method appears to have almost no accuracy loss.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2019_Lin_SparseReRAMMapping_ASP-DAC.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2019_Lin_SparseReRAMMapping_ASP-DAC.pdf", "priority": 5.86}, {"id": "W2971533524", "short": "ADMM Memristor Pruning", "title": "An Ultra-Efficient Memristor-Based DNN Framework with Structured Weight Pruning and Quantization Using ADMM", "authors": ["Geng Yuan", "Xiaolong Ma", "Caiwen Ding", "Sheng Lin", "Tianyun Zhang", "Zeinab S. Jalali", "Yilong Zhao", "Li Jiang", "Sucheta Soundarajan", "Yanzhi Wang"], "year": 2019, "venue": "", "venue_short": "ISLPED", "venue_full": "IEEE/ACM International Symposium on Low Power Electronics and Design (ISLPED 2019)", "venue_ok": true, "doi": "https://doi.org/10.1109/islped.2019.8824944", "cites_global": 58, "cat": "09", "seed": false, "devices": ["Memristor(generic)"], "models": ["CNN", "ResNet"], "evidence": "algorithm+simulation", "tldr": "An ADMM-based joint structured-pruning-and-quantization training framework, combined with memristor-crossbar-aware masked mapping and retraining, compresses VGG-16/ResNet-18 weights by up to 29.81x with under 1% accuracy loss while cutting crossbar power and area by over 97%.", "summary": "The paper targets the area/power cost of mapping large DNNs onto memristor crossbar arrays by jointly exploiting structured weight pruning (crossbar-block-level) and weight quantization, which prior work had studied only separately. It formulates both as constrained optimization and uses the alternating direction method of multipliers (ADMM) to solve them jointly during training, incorporating hardware constraints such as crossbar-block pruning granularity, limited conductance range, and weight-to-conductance mapping mismatch. The framework runs in three steps: ADMM-regularized optimization, masked mapping onto memristor crossbars, and retraining. It is evaluated on LeNet-5, a ConvNet (CIFAR-10), VGG-16 and ResNet-18 using a memristor crossbar simulation model (128x64/32x32 arrays, 4-bit conductance precision, 45nm periphery), comparing against the prior Group Scissor pruning baseline.", "contributions": ["A unified ADMM-based optimization that jointly performs structured (crossbar-block-level) weight pruning and weight quantization during DNN training", "Incorporation of hardware-realistic constraints (crossbar block granularity, conductance range, weight-conductance mismatch) directly into the training-time optimization", "A three-stage framework: ADMM-regularized optimization, masked mapping to crossbars, and retraining", "Demonstrated large weight-compression ratios with correspondingly large crossbar power/area savings on VGG-16 and ResNet-18, outperforming the Group Scissor baseline"], "claims": [{"claim": "Joint ADMM pruning+quantization achieves much larger compression than pruning alone on deep networks", "support": "29.81x weight compression on VGG-16 with 0.5% accuracy loss, 20.88x on ResNet-18 with 0.76% accuracy loss", "loc": "Abstract, Sec. IV"}, {"claim": "The framework yields large crossbar power and area savings", "support": "98.38%/96.96% power reduction and 98.29%/97.47% area reduction on VGG-16/ResNet-18 respectively", "loc": "Abstract, Sec. IV"}, {"claim": "On simpler networks, structured pruning alone gives very high compression with negligible accuracy loss", "support": "17.69x weight reduction without accuracy loss, up to 105.52x within 1% accuracy loss on LeNet-5", "loc": "Sec. IV.A"}, {"claim": "The method saves more crossbar area than the Group Scissor baseline", "support": "96.65% crossbar area reduction for VGG-16 and 95.21% for ResNet-18, compared with Group Scissor [23]", "loc": "Sec. IV"}], "results": ["29.81x weight compression on VGG-16 with 0.5% accuracy loss (20.88x on ResNet-18 with 0.76% loss)", "98.38%/98.29% power/area reduction on VGG-16 (96.96%/97.47% on ResNet-18) vs. uncompressed baseline", "Up to 105.52x weight reduction on LeNet-5 within 1% accuracy loss; >94% memristor crossbar area reduction on LeNet-5", "96.65% (VGG-16) and 95.21% (ResNet-18) crossbar area reduction, exceeding the Group Scissor baseline"], "limitations": ["Evaluated with a MATLAB/behavioral memristor crossbar model (Rmin=1M ohm, Rmax=10M ohm, 4-bit precision), not real hardware or SPICE-level non-idealities beyond conductance range/mismatch", "Only compares against one prior pruning baseline (Group Scissor); no comparison to other quantization-aware or ADC-aware mapping methods", "Does not model ADC/peripheral circuit overhead in detail, focusing mainly on crossbar array power/area", "Compression numbers are reported per-model on standard benchmarks (MNIST/CIFAR-10/ImageNet-scale VGG/ResNet) without system-level throughput or latency results"], "remarks": "This is an algorithm-level, training-time co-design paper rather than an architecture or circuit paper: its contribution is treating crossbar block pruning and cell quantization as a single ADMM-constrained optimization problem instead of tackling them in separate stages, which is a reasonable and now-common pattern in hardware-aware compression for analog crossbars. The reported compression numbers are strong but rest entirely on a simplified crossbar model, so the practical power/area gains would need to be re-validated against a more detailed circuit/ADC-aware simulator (e.g., NeuroSim-class tools) before being taken as hardware-accurate.", "basis": "full-text", "pdf_source_url": "", "abstract": "The high computation and memory storage of large deep neural networks (DNNs) models pose intensive challenges to the conventional Von-Neumann architecture, incurring sub-stantial data movements in the memory hierarchy. The memristor crossbar array has emerged as a promising solution to mitigate the challenges and enable low-power acceleration of DNNs. Memristor-based weight pruning and weight quantization have been seperately investigated and proven effectiveness in reducing area and power consumption compared to the original DNN model. However, there has been no systematic investigation of memristor-based neuromorphic computing (NC) systems considering both weight pruning and weight quantization. In this paper, we propose an unified and systematic memristor-based framework considering both structured weight pruning and weight quantization by incorporating alternating direction method of multipliers (ADMM) into DNNs training. We consider hardware constraints such as crossbar blocks pruning, conductance range, and mismatch between weight value and real devices, to achieve high accuracy and low power and small area footprint. Our framework is mainly integrated by three steps, i.e., memristor-based ADMM regularized optimization, masked mapping and retraining. Experimental results show that our proposed framework achieves 29.81× (20.88×) weight compression ratio, with 98.38% (96.96%) and 98.29% (97.47%) power and area reduction on VGG-16 (ResNet-18) network where only have 0.5% (0.76%) accuracy loss, compared to the original DNN models. We share our models at anonymous link http://bit.ly/2Jp5LHJ.", "review": [], "pdf_expected": "09_ADCs_Peripherals_Quantization_Sparsity/2019_Yuan_ADMMMemristorPruning_ISLPED.pdf", "analysed": true, "pdf": "09_ADCs_Peripherals_Quantization_Sparsity/2019_Yuan_ADMMMemristorPruning_ISLPED.pdf", "priority": 5.57}, {"id": "W4414428210", "short": "FeCAP-Memristor HM", "title": "A ferroelectric–memristor memory for both training and inference", "authors": ["Michele Martemucci", "François Rummens", "Yannick Malot", "Tifenn Hirtzlin", "Olivier Guille", "Simon Martin", "Catherine Carabasse", "Adrien F. Vincent", "Sylvain Saïghi", "L. Grenouillet", "Damien Querlioz", "Elisa Vianello"], "year": 2025, "venue": "Nature Electronics", "venue_short": "NatElectron", "venue_full": "Nature Electronics, Volume 8 (October 2025), pp. 921-933", "venue_ok": true, "doi": "https://doi.org/10.1038/s41928-025-01454-7", "cites_global": 27, "cat": "10", "seed": false, "devices": ["ReRAM", "Charge/Capacitor"], "models": ["MLP", "CNN"], "evidence": "device-experiment", "tldr": "A fabricated 18,432-device hybrid memory stack combining HfO2-based ferroelectric capacitors (for high-endurance, low-energy weight updates) with oxide memristors (for non-destructive, energy-efficient inference) lets a single BEOL-integrated technology support both on-chip training and inference, achieving software-competitive accuracy on MNIST/Fashion-MNIST/ECG and transfer-learning benchmarks.", "summary": "The paper targets a fundamental mismatch for edge AI: memristors have near-infinite read endurance and low-energy in-memory inference but poor write endurance/high programming energy, while ferroelectric capacitors (FeCAPs) have excellent write endurance and low programming energy but a destructive read that unsuits them for inference. The authors co-integrate both device types -- built from the same silicon-doped HfO2/Ti stack -- into the BEOL of a CMOS process, fabricating a hybrid array of 16,384 FeCAPs and 2,048 memristors with on-chip CMOS periphery. Each synaptic weight keeps a high-precision 10-bit hidden value in the FeCAP devices (frequently updated during training) and an analogue conductance value in the memristors (read during inference, updated only every k samples), with weight transfer between the two technologies done via on-chip circuitry rather than a digital-to-analogue converter. Using hardware-aware simulations calibrated to extensive electrical measurements of the fabricated array, they train small MLPs online (stochastic gradient descent, Bernoulli-masked hidden-weight updates) on MNIST (96.7% accuracy at k=100, ~38 nJ/sample, a 38x energy reduction vs k=1 with no accuracy loss), Fashion-MNIST and ECG classification, and demonstrate transfer learning with a MobileNet-V2 feature extractor onto CIFAR-10 and several harder ImageNet-pretrained target datasets, with a 1.2-7.3 percentage-point accuracy drop versus floating-point baselines attributed mainly to the lack of mini-batching rather than device variability. Endurance accounting shows the realized transfer/programming operation counts stay well below both the memristor and FeCAP endurance limits for these workloads.", "contributions": ["Co-fabricates ferroelectric capacitors and memristors from the same silicon-doped HfO2/Ti BEOL stack into a single 18,432-device hybrid array (16,384 FeCAPs + 2,048 memristors) with on-chip CMOS periphery", "Introduces a weight representation that splits precision across devices: 10-bit hidden weights in FeCAPs (frequent, high-endurance training updates) and analogue conductance in memristors (infrequent updates, non-destructive reads for inference)", "Demonstrates on-chip-style weight transfer between FeCAP and memristor domains without a formal DAC, characterized over 15 distinct conductance levels", "Validates on-chip training (SGD with stochastic/masked hidden-weight updates) via hardware-aware simulation calibrated against measured device statistics, on MNIST, Fashion-MNIST, ECG classification and MobileNet-V2 transfer learning", "Shows that tuning the analogue-weight-update period k trades off accuracy, energy and endurance, finding k=100 gives floating-point-competitive accuracy at 38x lower energy than k=1 while keeping both device types well within their endurance limits"], "claims": [{"claim": "The hybrid FeCAP/memristor approach reaches software (floating-point) competitive accuracy on several edge benchmarks without hitting either device's endurance limit", "support": "96.7% MNIST accuracy at k=100 (~38 nJ/sample total programming energy); HM approach loses only ~1-2 percentage points vs FP on MNIST, Fashion-MNIST and ECG; programming operation counts for MNIST, Fashion-MNIST, ECG and transfer-learning tasks remain well below the ~10^5 (memristor) and ~10^7 (FeCAP) endurance limits", "loc": "Results: 'Training at the edge', Fig. 5c-f"}, {"claim": "Updating analogue (memristor) weights only every k=100 inputs instead of every input cuts energy 38x with no accuracy loss, but updating too rarely (k>100) degrades accuracy", "support": "'At k = 100, the method achieves 96.7% accuracy with approximately 38 nJ of total energy consumption, representing a 38-fold reduction with no loss of accuracy with regard to k = 1'; test accuracy stable up to k=100 then drops for larger k", "loc": "Results, Fig. 5c-e"}, {"claim": "A pure memristor-only on-chip training scheme would exceed memristor write endurance even for small datasets", "support": "'the number of write operations for the k = 1 case of the MNIST dataset is around 1.2x10^6', i.e. above typical memristor cycling endurance (~10^5 cycles measured for this stack)", "loc": "Conclusion"}, {"claim": "Transfer-learning accuracy loss from the fully on-chip online training method is dominated by the lack of mini-batching rather than hardware/device transfer variability", "support": "Online HM training loses 1.2 pp (CIFAR-100->CIFAR-10) up to 1.8-7.3 pp (ImageNet-pretrained -> Pet/Flowers/Birds/Cars) vs floating-point baseline; Supplementary analysis attributes most of this drop to lack of mini-batch updates rather than FeCAP-to-memristor transfer variability", "loc": "Results, Fig. 6c"}, {"claim": "The fabricated HfO2-based memristor achieves sub-200 fJ/bit switching energy and ~10^5-cycle write endurance, while the co-integrated FeCAP achieves ~10^7-cycle endurance", "support": "'achieving switching energies below 200 fJ bit^-1'; 'estimating the SET-RESET cycling endurance to be 10^5 cycles' for the memristor; FeCAP endurance tests run to 10^7 cycles", "loc": "Results: 'Electrical characterization of FeCAP and memristor arrays', Fig. 2"}], "results": ["96.7% test accuracy on MNIST at k=100 (analogue-weight update period), with ~38 nJ total programming energy per sample -- a 38x energy reduction vs k=1 with no accuracy loss", "HM approach (quantized hidden weights, induced transfer errors) loses ~1-2 percentage points vs floating-point baseline across MNIST, Fashion-MNIST and ECG detection; mini-batch + batch-norm variant narrows this to 0.8 pp on MNIST", "MobileNet-V2 transfer learning: online HM training loses 1.2 pp vs FP on CIFAR-100->CIFAR-10, and 1.8-7.3 pp on harder ImageNet-pretrained transfers (Oxford-IIIT Pet, Oxford Flowers 102, Caltech Birds, Stanford Cars)", "Memristor switching energy below 200 fJ/bit; measured write endurance ~10^5 SET-RESET cycles (two orders below the FeCAP's ~10^7-cycle endurance)", "For k=1 (per-sample analogue update), MNIST training would require ~1.2x10^6 memristor write operations -- exceeding the measured memristor endurance limit, motivating the k=100 scheme", "Month-long retention stability of memristor conductance states observed (per Supplementary Note 9)"], "limitations": ["Accuracy/energy/endurance results for training come from hardware-aware simulations calibrated to measured device statistics, not a literal end-to-end training run executed entirely on the physical chip in real time", "Benchmarks are small-scale (MLPs on MNIST/Fashion-MNIST/ECG; a frozen MobileNet-V2 feature extractor with only the final classifier trained on-device) -- not demonstrated on larger modern architectures", "Online (per-sample, no mini-batching) training is used to keep hardware costs low, but this is shown to be the dominant source of the accuracy gap vs floating-point, especially on harder transfer-learning tasks", "Array scale (18,432 devices; 128x16 synapse grid) is far below what full-scale DNN deployment would require, so endurance/energy conclusions are extrapolated rather than demonstrated at production scale"], "remarks": "This is a genuine device/circuit co-integration result (measured switching energy, endurance, and transfer characterization on a real fabricated array), which is stronger evidence than pure simulation papers in this space, though the headline training-accuracy numbers rely on hardware-calibrated simulation rather than literal on-chip training loops. The core idea -- splitting the 'hidden' high-precision weight (needs endurance, not read-stability) from the 'analogue' inference weight (needs read-stability, not endurance) across two co-integrated device technologies -- is a notable mapping-level contribution relevant to anyone designing training-capable analog crossbars, complementing software-only hardware-aware-training approaches (e.g. Rasch/Gokmen-style HWA training) by addressing the endurance bottleneck at the device/architecture level rather than purely algorithmically.", "basis": "full-text", "pdf_source_url": "", "abstract": "Developing artificial intelligence systems that are capable of learning at the edge of a network requires both energy-efficient inference and learning. However, current memory technology cannot provide the necessary combination of high endurance, low programming energy and non-destructive read processes. Here we report a unified memory stack that functions as a memristor as well as a ferroelectric capacitor. Memristors are ideal for inference but have limited endurance and high programming energy; ferroelectric capacitors are ideal for learning, but their destructive read process makes them unsuitable for inference. Our memory stack uses a silicon-doped hafnium oxide and titanium scavenging layer that are integrated into the back end of line of a complementary metal-oxide-semiconductor process. With this approach, we fabricate an 18,432-device hybrid array (consisting of 16,384 ferroelectric capacitors and 2,048 memristors) with on-chip complementary metal-oxide-semiconductor periphery circuits. Each weight is associated with an analogue value stored as conductance levels in the memristors and a high-precision hidden value stored as a signed integer in the ferroelectric capacitors. Weight transfers between the different memory technologies occur without a formal digital-to-analogue converter. We use the array to validate an on-chip learning solution that, without batching, performs competitively with floating-point-precision software models across several benchmarks.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2025_Martemucci_FeCapMemristorHM_NatElectron.pdf", "analysed": true, "pdf": "10_On_Chip_and_Analog_Training/2025_Martemucci_FeCapMemristorHM_NatElectron.pdf", "priority": 3.51}, {"id": "W4401729360", "short": "c-TTv2/AGAD Training", "title": "Fast and robust analog in-memory deep neural network training", "authors": ["Malte J. Rasch", "Fabio Carta", "Omobayode I. Fagbohungbe", "Tayfun Gokmen"], "year": 2024, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications, vol. 15, article 7133 (2024)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-024-51221-z", "cites_global": 39, "cat": "10", "seed": false, "devices": ["ReRAM", "ECRAM", "Generic-NVM", "Charge/Capacitor"], "models": ["MLP", "CNN", "LSTM/RNN", "ViT"], "evidence": "algorithm+simulation", "tldr": "Two new fully-in-memory training algorithms, Chopped-TTv2 (c-TTv2) and Analog Gradient Accumulation with Dynamic reference (AGAD), remove Tiki-Taka v2's requirement for a near-perfectly programmed zero-reference conductance while keeping its O(1)/O(N) runtime advantage, with AGAD being robust even to symmetric device materials.", "summary": "Accelerating DNN training (not just inference) in-memory requires computing and accumulating weight gradients on-chip, but the state-of-the-art Tiki-Taka v2 (TTv2) algorithm needs a very precisely programmed reference conductance device to define an algorithmic zero point, which is impractical for most analog non-volatile memory materials. The authors propose c-TTv2, which periodically swaps (chops) the sign convention to cancel a static reference offset, and AGAD, which dynamically estimates and subtracts the reference point from readouts of past conductance changes, removing the precise-programming requirement altogether. Both are implemented in the IBM AIHWKit simulator and tested on weight-programming tasks and on DNN training (3-layer FC and LeNet on MNIST, 2-layer LSTM on War & Peace, and a 4.3M-parameter ViT on CIFAR-10) under device models with injected reference offset, asymmetry, and limited number of states. c-TTv2 greatly improves tolerance to reference offset versus TTv2 at negligible extra digital compute, while AGAD is essentially invariant to reference offset and to device asymmetry (working for both asymmetric materials like ReRAM and more symmetric ones like ECRAM/capacitors) at a small additional digital-compute cost, and the authors estimate a per-update time of 62.1 ns for AGAD vs >3000 ns for a fully digital gradient accumulation on a 512x512 array.", "contributions": ["Chopped-TTv2 (c-TTv2): periodic sign-chopping scheme that removes TTv2's dependence on a precisely programmed zero-reference conductance with negligible extra digital overhead", "AGAD (Analog Gradient Accumulation with Dynamic reference): dynamically computes the reference point from past conductance readouts, making training robust to both reference offset and device asymmetry (works on symmetric devices like ECRAM/capacitors, not just asymmetric ones like ReRAM)", "Systematic characterization of the algorithms' tolerance to conductance noise, device asymmetry, number of states, retention, and endurance to inform device-material requirements", "Validation on weight-programming tasks and full DNN training (FC, LeNet/MNIST, LSTM, and a ViT on CIFAR-10) implemented in the open-source AIHWKit", "Runtime/energy complexity analysis showing in-memory gradient accumulation (O(N)) is orders of magnitude faster than digital gradient accumulation (O(N^2))"], "claims": [{"claim": "TTv2 fails when the reference conductance offset is not programmed to within a few percent, while c-TTv2 and AGAD tolerate much larger offsets", "support": "TTv2 performance collapses as soon as sigma_r >= 0.1; c-TTv2 corrects offsets up to ~25% drift (sigma_r=0.5) within training duration; AGAD is invariant to offset entirely", "loc": "Fig. 4B-D / Results 'Weight programming'"}, {"claim": "AGAD's achieved weight-programming error is independent of device asymmetry, unlike TTv2/c-TTv2 which need some asymmetry to work well", "support": "Fig. 6B: AGAD (green line) retains low error across all asymmetry settings, while TTv2/c-TTv2 (blue/orange) and plain in-memory SGD (red) depend strongly on symmetry", "loc": "Fig. 6 / Device material requirements"}, {"claim": "In-memory gradient accumulation gives orders-of-magnitude faster per-update time than digital accumulation", "support": "estimated average gradient update time for a 512x512 weight matrix: 62.1 ns for AGAD vs. >3000 ns for digital gradient-matrix computation (O(N^2))", "loc": "Discussion, Table 1"}, {"claim": "c-TTv2 and AGAD match or exceed TTv2's converged DNN training accuracy, and remain stable when TTv2 fails", "support": "Fig. 5A-D: c-TTv2/AGAD reach near-FP test error across FC/LeNet/LSTM benchmarks and across nstates settings, while TTv2 degrades sharply with reference offset", "loc": "Results 'DNN training experiments', Fig. 5"}, {"claim": "The qualitative robustness trend holds even for a much larger model (ViT, 4.3M params) on CIFAR-10", "support": "classification error remains stable for c-TTv2/AGAD but not TTv2 when the reference offset is imperfectly corrected, confirmed without hyperparameter tuning", "loc": "Results, Supplementary Methods Sec. C.1.4"}], "results": ["Benchmark DNNs: 3-layer FC (235K params) and LeNet (80K params) on MNIST, 2-layer LSTM (77K params) on War & Peace, plus a 4.3M-parameter ViT on CIFAR-10", "Maximal pulses per input sample for convergence (LeNet/MNIST) found to be 0.5-4 pulses for the relevant device matrices, informing endurance requirements", "Estimated gradient-update time per 512x512 array: 62.1 ns (AGAD, in-memory) vs. >3000 ns (digital O(N^2) accumulation)"], "limitations": ["All results are algorithm-level simulations in AIHWKit with parameterized device noise models, not physical hardware demonstrations", "Benchmark DNNs are relatively small (77K-235K parameters); only one larger ViT (4.3M) experiment, and that without hyperparameter tuning", "AGAD introduces extra digital compute/storage versus c-TTv2, though claimed to remain within overall O(N) complexity", "Runtime/energy estimates are back-of-envelope (Table 1 assumptions: tMVM, single-pulse time, etc.), not measured on silicon", "Does not provide a full end-to-end DNN training time/energy estimate, only the gradient-update step"], "remarks": "This is a methodologically solid, simulation-based algorithmic advance from the IBM Research analog-AI group (same lineage as Gokmen's Tiki-Taka work and the AIHWKit toolkit) that directly targets a long-standing practical blocker -- precise reference-conductance programming -- for fully analog in-memory training. Because it is validated only in simulation with parameterized device models rather than on fabricated arrays, the claimed robustness needs confirmation on real asymmetric/symmetric NVM devices (ReRAM, ECRAM, capacitors), but the explicit mapping from algorithm requirements to device-material properties (asymmetry, states, retention, endurance) is a useful bridge between device and algorithm communities. Already cited by at least one 2025 ADC-resolution-optimization PIM paper as motivation for in-memory training acceleration.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog in-memory computing is a promising future technology for efficiently accelerating deep learning networks. While using in-memory computing to accelerate the inference phase has been studied extensively, accelerating the training phase has received less attention, despite its arguably much larger compute demand to accelerate. While some analog in-memory training algorithms have been suggested, they either invoke significant amount of auxiliary digital compute-accumulating the gradient in digital floating point precision, limiting the potential speed-up-or suffer from the need for near perfectly programming reference conductance values to establish an algorithmic zero point. Here, we propose two improved algorithms for in-memory training, that retain the same fast runtime complexity while resolving the requirement of a precise zero point. We further investigate the limits of the algorithms in terms of conductance noise, symmetry, retention, and endurance which narrow down possible device material choices adequate for fast and robust in-memory deep neural network training.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2024_Rasch_cTTv2AGADTraining_NatCommun.pdf", "analysed": true, "pdf": "10_On_Chip_and_Analog_Training/2024_Rasch_cTTv2AGADTraining_NatCommun.pdf", "priority": 4.52}, {"id": "W4400937214", "short": "Learning-in-Memory Review", "title": "Difficulties and approaches in enabling learning-in-memory using crossbar arrays of memristors", "authors": ["Wei Juan Wang", "Yang Li", "Ming Wang"], "year": 2024, "venue": "Neuromorphic Computing and Engineering", "venue_short": "NeuromorphComputEng", "venue_full": "Neuromorphic Computing and Engineering (2024)", "venue_ok": true, "doi": "https://doi.org/10.1088/2634-4386/ad6732", "cites_global": 4, "cat": "10", "seed": false, "devices": ["Memristor(generic)"], "models": [], "evidence": "survey", "tldr": "A review of the difficulties and proposed approaches for implementing error backpropagation and weight update directly in memristor crossbar arrays (in-situ/in-memory learning), rather than only accelerating the forward inference pass.", "summary": "Memristor crossbar arrays can accelerate deep learning inference in a non-von-Neumann manner, but most prior work only accelerates the forward pass while error backpropagation and weight update are still done on a conventional von Neumann computer. This review surveys in situ learning schemes that attempt to perform backpropagation and/or weight update within the crossbar array itself, discussing the difficulties these schemes face from non-ideal synaptic behavior of memristors (noise, non-linearity, device variation) and from the complexity of the peripheral neural circuits required to support in-memory learning. The authors aim to summarize current approaches and open issues to help guide development of open neuromorphic simulation tools and eventual hardware implementations of full learning-in-memory systems.", "contributions": ["Surveys and categorizes approaches for implementing error backpropagation in memristor crossbar arrays for in situ/on-chip learning", "Surveys approaches for implementing in-memory weight update adapted to noisy, non-ideal memristor devices", "Discusses the circuit-level complexities (peripheral neural circuits) required to support online/in-memory training beyond simple inference acceleration", "Identifies open difficulties and gaps motivating future open-source neuromorphic simulation tools for learning-in-memory systems"], "claims": [{"claim": "Most existing crossbar-based accelerators only speed up DNN inference (forward pass), while backpropagation and weight update remain digitally simulated", "support": "stated as the paper's core motivating observation (abstract)", "loc": "abstract"}, {"claim": "Non-ideal synaptic behavior and neural-circuit complexity are the two central obstacles to practical in-memory learning", "support": "abstract: 'issues of non-ideal synaptic behaviors of the memristors and the complexities of the neural circuits surrounding crossbar arrays'", "loc": "abstract"}], "results": ["No full text available; this is a review paper and does not itself report new quantitative experimental results beyond synthesizing prior literature (per abstract)"], "limitations": ["Full text unavailable; analysis based on abstract only, so the specific taxonomy of schemes, device models, and comparative discussion could not be verified", "As a review, it does not itself provide new experimental validation; its value is in synthesis and gap identification", "No in-set citing papers recorded (in_set_cited_by empty), limiting ability to assess downstream influence within this collection"], "remarks": "A survey specifically focused on online/in-situ learning in memristor crossbars -- a narrower and less mature sub-area than inference acceleration -- that is useful for understanding why on-chip analog training remains largely unsolved (non-ideal device behavior plus peripheral circuit complexity). Without full text, its depth and the comprehensiveness of its coverage relative to other surveys in this collection cannot be assessed, but the abstract suggests it specifically targets the backpropagation/weight-update bottleneck rather than analog training algorithms in general.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Abstract Crossbar arrays of memristors are promising to accelerate the deep learning algorithm as a non-von-Neumann architecture, where the computation happens at the location of the memory. The computations are parallelly conducted employing the basic physical laws. However, current research works mainly focus on the offline training of deep neural networks, i.e. only the information forwarding is accelerated by the crossbar array. Two other essential operations, i.e. error backpropagation and weight update, are mostly simulated and coordinated by a conventional computer in von Neumann architecture, respectively. Several different in situ learning schemes incorporating error backpropagation and/or weight updates have been proposed and investigated through neuromorphic simulation. Nevertheless, they met the issues of non-ideal synaptic behaviors of the memristors and the complexities of the neural circuits surrounding crossbar arrays. Here we review the difficulties and approaches in implementing the error backpropagation and weight update operations for online training or in-memory learning that are adapted to noisy and non-ideal memristors. We hope this work will be beneficial for the development of open neuromorphic simulation tools for learning-in-memory systems, and eventually for the hardware implementation of such as system.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2024_Wang_LearningInMemoryReview_NeuromorphComputEng.pdf", "analysed": true, "pdf": "10_On_Chip_and_Analog_Training/2024_Wang_LearningInMemoryReview_NeuromorphComputEng.pdf", "priority": 2.99}, {"id": "W3211973280", "short": "Passive RRAM LSTM", "title": "Long Short-Term Memory Implementation Exploiting Passive RRAM Crossbar Array", "authors": ["Honey Nikam", "Siddharth Satyam", "Shubham Sahay"], "year": 2021, "venue": "IEEE Transactions on Electron Devices", "venue_short": "TED", "venue_full": "IEEE Transactions on Electron Devices, vol. 69 (2022; published online Dec. 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/ted.2021.3133197", "cites_global": 21, "cat": "10", "seed": false, "devices": ["ReRAM"], "models": ["LSTM/RNN"], "evidence": "simulation", "tldr": "A simulation study of in-situ Manhattan-rule training of a small LSTM on a selector-less (passive) Pt/Al2O3/TiO2-x RRAM crossbar. On the airline-passenger task it reports about 6.5x10^3 smaller area and about 51.7x lower update energy than a 1T1R memristor LSTM.", "summary": "The paper proposes mapping LSTM gate weights onto a passive (0T1R) RRAM crossbar to avoid the large select transistors of 1T1R arrays. A hardware-aware framework uses an experimentally calibrated compact model of Pt/Al2O3/TiO2-x passive crossbars (Nili et al.), validated against more than 2M data points and 324 devices. The model includes conductance-dependent nonlinearity, device-to-device variation and noise. A 64x64 crossbar is partitioned into a 34x60 block for the LSTM layer (15 units, 4 gates, differential pairs) and a 32x1 block for the dense layer. VMMs and weight updates run on the simulated crossbar, while gradients, activations and the loss are computed digitally. Weights are updated in situ with the Manhattan rule (fixed +/-0.8 V, 100 ns pulses). On the 144-sample airline-passenger forecasting task, it converges within 200 epochs and fits the test data closely. The authors compare area and programming energy against the 1T1R LSTM of Li et al. (Nat. Mach. Intell. 2019).", "contributions": ["Mapping of LSTM gates and dense layer onto a passive RRAM crossbar with differential conductance pairs", "Hardware-aware simulation framework using a calibrated passive-crossbar compact model (variation, noise, nonlinearity)", "In-situ Manhattan-rule training with fixed-amplitude pulses", "Area and training-energy comparison against a 1T1R memristor LSTM"], "claims": [{"claim": "A passive crossbar LSTM is much smaller than a 1T1R implementation.", "support": "About 921.6 um2 vs about 6.041 mm2 for a 40x64 array (cell 0.36 um2 vs about 2360 um2), roughly 6.5x10^3", "loc": "Sec. III-C"}, {"claim": "In-situ training energy in the array is far lower than for 1T1R.", "support": "3.0 uJ (with variations, 200 epochs) vs about 145 uJ (1T1R, 800 epochs), a factor of about 51.7", "loc": "Sec. III-B, Figs. 11-12"}, {"claim": "Training converges faster than the 1T1R LSTM.", "support": "Convergence within 200 epochs vs 800 epochs for 1T1R", "loc": "Sec. III-A, Fig. 8"}, {"claim": "The implementation is robust to device-to-device variation and noise.", "support": "Predictions with variations/noise closely match noise-free crossbar predictions (qualitative, Fig. 10). Update energy 3.0 vs 2.8 uJ", "loc": "Sec. III-A, Fig. 10"}], "results": ["Area: about 921.6 um2 (passive) vs about 6.041 mm2 (1T1R) for 40x64 array, about 6.5x10^3 reduction", "Programming energy for in-situ training: 3.0 uJ (with non-idealities) vs 2.8 uJ (ideal), about 51.7x lower than 1T1R (about 145 uJ)", "Convergence within 200 epochs vs 800 for the 1T1R baseline"], "limitations": ["Simulation only, despite the 'implementation' framing. No fabricated passive-crossbar LSTM", "Toy workload: 144-sample airline-passenger regression with 15 LSTM units. No quantitative test error is reported, only plots", "Energy counts only conductance-programming pulses. Digital gradient/activation computation and peripheral circuits (ADC/DAC, drivers) are excluded", "Area compares bare cells and ignores periphery. Sneak paths, line resistance and half-select disturb in passive arrays are not analysed", "The 1T1R comparison mixes epochs (200 vs 800) and different device stacks, so it is not like-for-like"], "remarks": "This is a useful proof-of-concept that passive crossbars can, in principle, host recurrent-network in-situ training. The headline gains, however, come mostly from comparing a dense passive-cell footprint against a large-transistor 1T1R research array, and they leave out periphery and digital costs, so they should not be read as system-level efficiency. For a thesis on mapping, the relevant parts are the gate-weight partitioning on one crossbar with differential pairs and the use of sign-based (Manhattan) updates to tolerate nonlinear conductance updates. Sneak-path and IR-drop effects at scale remain open. The analysed full text is the arXiv preprint (2111.04588), whose bibliography does not include the in-set references listed for the TED version.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2111.04588", "abstract": "The ever-increasing demand to extract temporal correlations across sequential data and perform context-based learning in this era of big data has led to the development of long short-term memory (LSTM) networks. Furthermore, there is an urgent need to perform these time-series data-dependent applications, including speech/video processing and recognition, and language modeling and translation, on compact Internet-of-Things (IoT) edge devices with limited energy. To this end, in this work, for the first time, we propose an extremely area- and energy-efficient LSTM network implementation exploiting the passive resistive random access memory (RRAM) crossbar array. We developed a hardware-aware LSTM network simulation framework and performed an extensive analysis of the proposed LSTM implementation considering the nonideal hardware artifacts such as spatial (device-to-device) and temporal variations, nonlinearity, and noise, utilizing an experimentally calibrated comprehensive phenomenological model for passive RRAM crossbar array. Our results indicate that the proposed passive RRAM crossbar-based LSTM network implementation not only outperforms the prior digital and active 1Transistor-1RRAM (1T-1R) crossbar-based LSTM implementations by more than three orders of magnitude in terms of area and two orders of magnitude in terms of training energy for identical network accuracy but also exhibits robustness against spatial and temporal variations and noise, and a faster convergence rate. Our work may provide the incentive for experimental realization of LSTM networks on passive RRAM crossbar arrays.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2021_Nikam_PassiveRRAMLSTM_TED.pdf", "analysed": true, "pdf": "10_On_Chip_and_Analog_Training/2021_Nikam_PassiveRRAMLSTM_TED.pdf", "priority": 2.94}, {"id": "W2997247951", "short": "PANTHER", "title": "PANTHER: A Programmable Architecture for Neural Network Training Harnessing Energy-Efficient ReRAM", "authors": ["Aayush Ankit", "Izzat El Hajj", "Sai Rahul Chalamalasetti", "Sapan Agarwal", "Matthew J. Marinella", "Martin Foltín", "John Paul Strachan", "Dejan S. Milojicic", "Wen‐mei Hwu", "Kaushik Roy"], "year": 2020, "venue": "IEEE Transactions on Computers", "venue_short": "TC", "venue_full": "IEEE Transactions on Computers (2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/tc.2020.2998456", "cites_global": 88, "cat": "10", "seed": false, "devices": ["ReRAM"], "models": ["CNN", "MLP"], "evidence": "simulation", "tldr": "PANTHER introduces a bit-sliced outer-product-accumulate (OPA) technique for high-precision ReRAM-crossbar weight-gradient/update computation, packaged as an ISA-programmable, compiler-supported training accelerator with up to 103x energy and 16x execution-time reduction over GPUs.", "summary": "The paper targets the weight-gradient and weight-update step of ReRAM-crossbar-based DNN training accelerators, which prior designs implement with slow, energy-costly serial reads/writes, or with low-precision outer-product-accumulate (OPA) operations limited to fully-connected layers. PANTHER proposes a bit-slicing technique tailored to OPA (distinct from bit-slicing for matrix-vector multiplication) that raises precision enough for realistic training. This is built into a crossbar-based matrix-compute-unit (MCU) architecture with three variants supporting SGD, mini-batch SGD, and mini-batch SGD with large batches, covering fully-connected and convolutional layers. The full system, PANTHER, is an ISA-programmable training accelerator with compiler support, allowing it to also be integrated into other crossbar accelerators. It is evaluated in simulation against digital accelerators, prior ReRAM-based accelerators, and GPUs on DNN training workloads (CIFAR, SVHN, CIFAR-100-scale networks).", "contributions": ["A bit-slicing technique for high-precision outer-product-accumulate (OPA) operations in ReRAM crossbars, distinct from conventional MVM bit-slicing", "A crossbar matrix-compute-unit (MCU) architecture with three variants tailored to SGD, mini-batch SGD, and large-batch mini-batch SGD training", "PANTHER: an ISA-programmable, compiler-supported training accelerator built from these MCUs, generalizing to fully-connected and convolutional layers", "A design that can be integrated into other existing crossbar accelerators in the literature to improve their training efficiency"], "claims": [{"claim": "PANTHER substantially reduces training energy versus digital, ReRAM-based, and GPU baselines", "support": "up to 8.02x, 54.21x, and 103x energy reductions compared to digital accelerators, ReRAM-based accelerators, and GPUs, respectively", "loc": "Abstract, Conclusion"}, {"claim": "PANTHER substantially reduces training execution time versus the same baselines", "support": "up to 7.16x, 4.02x, and 16x execution time reductions vs. digital accelerators, ReRAM-based accelerators, and GPUs, respectively", "loc": "Abstract, Conclusion"}, {"claim": "Bit-sliced OPA gives large energy reductions specifically for fully-connected layers", "support": "8.02x reduction in energy (attributed to the OPA technique) and 54.21x energy reductions for FC layers (Layers 1-4)", "loc": "Sec. VII (Evaluation), around line 2052-2056"}, {"claim": "Iterative re-training can recover accuracy loss from ReRAM non-idealities without major added training cost", "support": "re-training is a fine-tuning process (typically 1 epoch) with insignificant cost compared to full training, used to recover accuracy loss from non-idealities, faults, and variations", "loc": "Sec. VIII (Discussion)"}], "results": ["Up to 8.02x / 54.21x / 103x energy reduction vs. digital accelerators / ReRAM-based accelerators / GPUs", "Up to 7.16x / 4.02x / 16x execution-time reduction vs. digital accelerators / ReRAM-based accelerators / GPUs", "54.21x energy reduction specifically reported for fully-connected layers (Layers 1-4) in the evaluated networks"], "limitations": ["Evaluation is simulation-based; no fabricated chip or physical ReRAM OPA measurement is reported", "Floating-point training (bfloat16, float8) is noted as not directly amenable to ReRAM hardware without modification; PANTHER relies on fixed-point/bit-sliced precision instead", "Relies on iterative re-training to compensate for ReRAM write non-idealities, faults, and variations, assumed to cost only ~1 epoch but not exhaustively characterized across devices", "Benchmarks are at CIFAR/SVHN/CIFAR-100 scale, smaller than modern large-scale CNN or Transformer training workloads"], "remarks": "PANTHER is a well-cited training-focused crossbar architecture that specifically addresses the long-standing bottleneck of implementing the weight-gradient/update (outer-product) step precisely in ReRAM, rather than only the forward MVM. Its bit-slicing-for-OPA idea and ISA-programmable/compiler-supported design make it a frequently used baseline for later ReRAM training accelerators and transformer/attention mapping works (e.g., X-Former, Atleus cite it). As with most crossbar training papers, the claimed gains rest on simulation and an assumption that cheap re-training offsets device non-idealities, which would need hardware validation to confirm at scale.", "basis": "full-text", "pdf_source_url": "", "abstract": "The wide adoption of deep neural networks has been accompanied by ever-increasing energy and performance demands due to the expensive nature of training them. Numerous special-purpose architectures have been proposed to accelerate training: both digital and hybrid digital-analog using resistive RAM (ReRAM) crossbars. ReRAM-based accelerators have demonstrated the effectiveness of ReRAM crossbars at performing matrix-vector multiplication operations that are prevalent in training. However, they still suffer from inefficiency due to the use of serial reads and writes for performing the weight gradient and update step. A few works have demonstrated the possibility of performing outer products in crossbars, which can be used to realize the weight gradient and update step without the use of serial reads and writes. However, these works have been limited to low precision operations which are not sufficient for typical training workloads. Moreover, they have been confined to a limited set of training algorithms for fully-connected layers only. To address these limitations, we propose a bit-slicing technique for enhancing the precision of ReRAM-based outer products, which is substantially different from bit-slicing for matrix-vector multiplication only. We incorporate this technique into a crossbar architecture with three variants catered to different training algorithms. To evaluate our design on different types of layers in neural networks (fully-connected, convolutional, etc.) and training algorithms, we develop PANTHER, an ISA-programmable training accelerator with compiler support. Our design can also be integrated into other accelerators in the literature to enhance their efficiency. Our evaluation shows that PANTHER achieves up to 8.02×, 54.21×, and 103× energy reductions as well as 7.16×, 4.02×, and 16× execution time reductions compared to digital accelerators, ReRAM-based accelerators, and GPUs, respectively.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2020_Ankit_PANTHER_TC.pdf", "analysed": true, "pdf": "10_On_Chip_and_Analog_Training/2020_Ankit_PANTHER_TC.pdf", "priority": 6.3}, {"id": "W3090816752", "short": "MINT", "title": "MINT: Mixed-Precision RRAM-Based IN-Memory Training Architecture", "authors": ["Hongwu Jiang", "Shanshi Huang", "Xiaochen Peng", "Shimeng Yu"], "year": 2020, "venue": "", "venue_short": "ISCAS", "venue_full": "IEEE International Symposium on Circuits and Systems (ISCAS 2020)", "venue_ok": true, "doi": "https://doi.org/10.1109/iscas45731.2020.9181020", "cites_global": 27, "cat": "10", "seed": false, "devices": ["ReRAM"], "models": ["CNN"], "evidence": "simulation", "tldr": "MINT splits DNN weights into MSBs (processed by transposable RRAM compute-in-memory arrays for forward/backward propagation) and LSBs (stored and updated in regular memory arrays), enabling on-chip training with ~91% CIFAR-10 accuracy, ~4.46 TOPS/W, 1.35x higher energy efficiency, and only 31.9% of the chip area versus a baseline RRAM CIM architecture.", "summary": "On-chip training of DNNs using compute-in-memory (CIM) is attractive for solving the memory-wall problem but is challenged by the need for higher weight precision and higher ADC resolution than inference-only CIM. MINT (Mixed-precision IN-memory Training) addresses this by splitting each multi-bit weight into most-significant bits (MSBs) and least-significant bits (LSBs): forward and backward propagation use CIM transposable RRAM arrays that store only the MSBs, while the weight update (which needs higher precision) is performed in regular (non-CIM) memory arrays that store the LSBs. The paper analyzes the impact of ADC resolution on training accuracy and evaluates training of a VGG-like CNN on CIFAR-10 under this mixed-precision architecture.", "contributions": ["A mixed-precision RRAM-based CIM training architecture (MINT) that splits weights into MSBs (in CIM transposable arrays) and LSBs (in regular memory arrays) to balance training precision needs against CIM hardware costs", "An analysis of how ADC resolution affects on-chip training accuracy under this split-precision scheme", "Evaluation of a VGG-like CNN trained on CIFAR-10 with the proposed architecture under realistic hardware constraints", "A chip-area and energy-efficiency comparison against baseline full-precision RRAM CIM training architectures"], "claims": [{"claim": "MINT achieves competitive training accuracy on CIFAR-10 under realistic hardware (ADC resolution, mixed precision) constraints", "support": "~91% accuracy reported for a VGG-like network on CIFAR-10 (abstract)", "loc": "Abstract"}, {"claim": "MINT improves energy efficiency over baseline RRAM CIM training architectures", "support": "~4.46 TOPS/W energy efficiency, 1.35x higher than baseline CIM architectures based on RRAM (abstract)", "loc": "Abstract"}, {"claim": "MINT substantially reduces chip area versus a baseline full-precision CIM training architecture", "support": "Only 31.9% of baseline chip size (~98.86 mm^2 at 32nm node) (abstract)", "loc": "Abstract"}], "results": ["~91% accuracy for VGG-like CNN on CIFAR-10 under hardware constraints", "~4.46 TOPS/W energy efficiency", "1.35x higher energy efficiency vs. baseline RRAM CIM architecture", "Chip area reduced to 31.9% of baseline (~98.86 mm^2 at 32nm technology node)"], "limitations": ["Only the abstract was available for this analysis (full text not accessible from this machine; IEEE Xplore is not downloadable here); exact MSB/LSB bit-split, ADC resolution values, and training hyperparameters could not be verified", "Evaluation limited to a single VGG-like network on CIFAR-10 per the abstract; generalization to larger/deeper networks or datasets is not addressed", "As a short ISCAS conference paper, the architectural and experimental detail is likely limited compared to a journal-length treatment"], "remarks": "Based on the abstract, MINT is a concrete architectural proposal for the on-chip (analog) training problem, directly addressing the known tension between CIM's need for compact low-precision arrays and training's need for high weight-update precision, via an MSB/LSB split across CIM and conventional memory. The quantitative results (91% CIFAR-10 accuracy, 4.46 TOPS/W, ~32% baseline chip area) are notable but, lacking full-text access, cannot be independently checked against the exact baseline configuration or verified for consistency with the companion DNN+NeuroSim V2.0 benchmarking framework that is reported to cite it.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "On-chip training of large-scale deep neural networks (DNNs) is challenging. To solve the memory wall problem, compute-in-memory (CIM) is a promising approach that exploits the analog computation inside the memory array to speed up the vector-matrix multiplication (VMM). Challenges for on-chip CIM training include higher weight precision and higher analog-to-digital converter (ADC) resolution. In this work, we propose a mixed-precision RRAM-based CIM architecture that overcomes these challenges and supports on-chip training. In particular, we split the multi-bit weight into the most significant bits (MSBs) and the least significant bits (LSBs). The forward and backward propagations are performed with CIM transposable arrays for MSBs only, while the weight update is performed in regular memory arrays that store LSBs. Impact of ADC resolution on training accuracy is analyzed. We explore the training performance of a convolutional VGG-like network on the CIFAR-10 dataset using this Mixed-precision IN-memory Training architecture, namely MINT, showing that it can achieve ~91% accuracy under hardware constraints and ~4.46TOPS/W energy efficiency. Compared with the baseline CIM architectures based on RRAM, it can achieve 1.35× higher energy efficiency and only 31.9% chip size (~98.86 mm2at 32 nm node).", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2020_Jiang_MINT_ISCAS.pdf", "analysed": true, "pdf": null, "priority": 3.94}, {"id": "W2803163155", "short": "PCM+Capacitor Analog Training", "title": "Equivalent-accuracy accelerated neural-network training using analogue memory", "authors": ["Stefano Ambrogio", "Pritish Narayanan", "Hsinyu Tsai", "Robert M. Shelby", "Irem Boybat", "Carmelo di Nolfo", "Severin Sidler", "Massimo Giordano", "Martina Bodini", "Nathan C. P. Farinha", "Benjamin D. Killeen", "Christina Cheng", "Yassine Jaoudi", "Geoffrey W. Burr"], "year": 2018, "venue": "Nature", "venue_short": "Nature", "venue_full": "Nature, vol. 558, 2018", "venue_ok": true, "doi": "https://doi.org/10.1038/s41586-018-0180-5", "cites_global": 1150, "cat": "10", "seed": false, "devices": ["PCM", "Charge/Capacitor"], "models": ["MLP"], "evidence": "measured-silicon", "tldr": "Mixed hardware-software training with up to 204,900 synapses (PCM for long-term storage, capacitors for near-linear updates, polarity inversion) reaches software-equivalent accuracy on MNIST, MNIST-backrand, CIFAR-10 and CIFAR-100.", "summary": "In-situ training on analog NVM had lagged software accuracy because of limited dynamic range and asymmetric weight updates. Ambrogio et al. pair a non-volatile PCM conductance pair (long-term storage) with a volatile capacitor-based 3T1C cell (near-linear, symmetric updates) in each synapse. Accumulated updates are periodically transferred to the PCM, using \"polarity inversion\" to cancel device-to-device variations. The mixed hardware-software experiments use up to 204,900 synapses and reach generalization accuracy equivalent to software training on MNIST, MNIST-backrand, CIFAR-10 and CIFAR-100. The authors project 28,065 GOPS/W and 3.6 TOPS/mm² for the design, about two orders of magnitude better than contemporary GPUs, mainly for fully connected layers.", "contributions": ["Two-tier synapse: volatile capacitor for linear updates plus PCM pair for non-volatile storage", "Polarity inversion to cancel device-to-device variations on weight transfer", "Software-equivalent in-situ training accuracy on four datasets with up to 204,900 synapses", "Energy and area-throughput projections against GPUs"], "claims": [{"claim": "Analog in-situ training can reach software-equivalent generalization accuracy.", "support": "Equivalent accuracy on MNIST, MNIST-backrand, CIFAR-10 and CIFAR-100 (transfer-learning setting for CIFAR)", "loc": "Abstract"}, {"claim": "Combining volatile linear-update elements with non-volatile PCM storage overcomes update asymmetry and limited dynamic range.", "support": "3T1C capacitor + PCM pair synapse with polarity inversion", "loc": "Abstract"}, {"claim": "The design is two orders of magnitude more efficient than GPUs.", "support": "28,065 GOPS/W and 3.6 TOPS/mm² (calculated, not measured end-to-end)", "loc": "Abstract"}], "results": ["Up to 204,900 synapses in mixed hardware-software experiments", "Software-equivalent accuracy on MNIST, MNIST-backrand, CIFAR-10, CIFAR-100", "Projected 28,065 GOPS/W and 3.6 TOPS/mm²"], "limitations": ["Mixed hardware-software: parts of the network/periphery emulated in software.", "Efficiency figures are calculated projections.", "Fully connected layers; CIFAR results rely on transfer learning with fixed conv features.", "Summary based on the abstract; the full text was not available here."], "remarks": "A landmark for analog training (category 10). It shows a device-level trick (multi-tier synapse) can close the accuracy gap that pure NVM updates cannot. It anchors the IBM line that leads to HERMES and the 14 nm chips. Its projected efficiency should not be compared with measured chip TOPS/W.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2018_Ambrogio_PCUAnalogueMemoryTraining_Nature.pdf", "analysed": true, "pdf": null, "priority": 8.86}, {"id": "W2807750997", "short": "In-Situ Memristor Learning", "title": "Efficient and self-adaptive in-situ learning in multilayer memristor neural networks", "authors": ["Can Li", "Daniel Belkin", "Yunning Li", "Peng Yan", "Miao Hu", "Ning Ge", "Hao Jiang", "Eric Montgomery", "Peng Lin", "Zhongrui Wang", "Wenhao Song", "John Paul Strachan", "Mark D. Barnell", "Qing Wu", "Richard Stanley Williams", "J. Joshua Yang", "Qiangfei Xia"], "year": 2018, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-018-04484-2", "cites_global": 935, "cat": "10", "seed": false, "devices": ["Memristor(generic)"], "models": ["MLP"], "evidence": "device-experiment", "tldr": "A monolithically integrated 128x64 Ta/HfO2/Pt 1T1R memristor array demonstrates fully in-situ (on-chip) online SGD training of a multilayer perceptron, reaching 91.71% MNIST test accuracy despite 11% unresponsive devices.", "summary": "The paper tackles the lack of experimental demonstrations of in-situ (on-device) learning in large, multilayer memristor neural networks, as opposed to ex-situ training with weights programmed after the fact. The authors monolithically integrate HfO2-based memristors with a foundry transistor array (1T1R) into a 128x64 crossbar, and develop a two-pulse conductance programming scheme that gives linear, symmetric conductance updates with low cycle-to-cycle and device-to-device variation. A two-layer perceptron is trained online with stochastic gradient descent directly on hardware (inference done in the crossbar via Ohm's/Kirchhoff's laws; weight updates computed in software from read-out weights and written back to the array) over 80,000 MNIST training samples, reaching 91.71% accuracy on the 10,000-image test set with 11% of devices stuck/unresponsive. Simulations calibrated to the measured device parameters show that in-situ training is far more defect-tolerant than ex-situ (pre-loaded) training, retaining >60% accuracy even at 50% stuck-device rate, and project >97% accuracy on a larger (1024x512) array with similar 11% defect rates. The work demonstrates that online, in-array learning can self-adapt to hardware imperfections without knowledge of the defect map.", "contributions": ["First experimental demonstration of in-situ (fully on-chip) training of a multilayer (two-layer) memristor neural network, as opposed to single-layer or ex-situ-trained prior work", "A reliable two-pulse conductance programming scheme giving linear/symmetric conductance updates on a 128x64 1T1R HfO2 memristor array", "Quantified self-adaptation: in-situ training tolerates device defects (11% stuck) with only 2.4% accuracy loss vs ideal simulation, without the algorithm knowing which devices are defective", "Experimentally calibrated simulation model extended to project accuracy on larger (1024x512) arrays and higher stuck-device rates (up to 50%)", "Direct quantitative comparison of in-situ vs ex-situ training robustness under the same defect model"], "claims": [{"claim": "In-situ trained 128x64 memristor MLP reaches 91.71% MNIST test accuracy with 11% stuck devices", "support": "91.71% of 10,000 test images correctly classified", "loc": "Abstract / main text p.2"}, {"claim": "In-situ training is far more defect-tolerant than ex-situ training", "support": "with 50% of memristors stuck in a low-conductance state, in-situ online training still achieves >60% accuracy while ex-situ accuracy drops quickly with defect rate", "loc": "Fig. 4b"}, {"claim": "A larger crossbar would substantially close the gap to digital CMOS accuracy", "support": "simulation of a 1024x512 array with 11% stuck devices projects 97.3 ± 0.4% accuracy after 20 epochs", "loc": "p.6, Fig. 4d discussion"}, {"claim": "The two-pulse programming scheme achieves linear, symmetric, low-variation conductance updates across a full array", "support": "shown for 20 cycles on a single device and across all responsive devices in an 8k-cell array (Fig. 1f-h)", "loc": "Fig. 1f-h"}], "results": ["91.71% MNIST test accuracy achieved in situ on a 128x64 array with 11% stuck devices (2.4% below idealized defect-free simulation)", ">60% classification accuracy retained under in-situ training even with 50% of devices stuck off, vs. fast degradation for ex-situ training (Fig. 4b)", "Simulated 97.3 ± 0.4% accuracy projected for a 1024x512 array with 11% stuck devices after 20 training epochs", "Memristor devices cited as supporting switching faster than 100 ps and energy per conductance update below 3 fJ (device-level figures from prior characterization, not this experiment's measured throughput/energy)"], "limitations": ["Demonstrated network is small (two-layer perceptron on a 128x64 array), far from practical DNN scale", "Backpropagation (weight-update computation) is done in software from read-out weights, not yet implemented in the crossbar itself", "Peripheral/control electronics are off-chip and explicitly described as not optimized for speed or power, so no end-to-end system energy/latency numbers are reported", "Projection to 97% accuracy on a 1024x512 array is simulation-only (calibrated to measured device stats, not fabricated or tested)", "Single dataset (MNIST) and single architecture (MLP); no convolutional or larger-model demonstration"], "remarks": "This is a genuine measured-silicon (device-experiment) result, not a simulation-only mapping paper: it is one of the earliest demonstrations that in-situ/online training on a real memristor array is inherently more fault-tolerant than programming pre-trained (ex-situ) weights, since the online gradient updates implicitly route around stuck or noisy devices. For the mapping/analog-training literature, it is an important data point establishing that defect/noise tolerance can come from the training procedure itself rather than purely from device engineering or compensation circuitry; later work on hardware-aware training and committee machines builds on this general insight at larger scale. The main caveat is scale: the 128x64 array and two-layer MLP are a proof of concept, and extrapolation to larger, multilayer convolutional networks or full on-chip backprop remains simulation-based.", "basis": "full-text", "pdf_source_url": "", "abstract": "Memristors with tunable resistance states are emerging building blocks of artificial neural networks. However, in situ learning on a large-scale multiple-layer memristor network has yet to be demonstrated because of challenges in device property engineering and circuit integration. Here we monolithically integrate hafnium oxide-based memristors with a foundry-made transistor array into a multiple-layer neural network. We experimentally demonstrate in situ learning capability and achieve competitive classification accuracy on a standard machine learning dataset, which further confirms that the training algorithm allows the network to adapt to hardware imperfections. Our simulation using the experimental parameters suggests that a larger network would further increase the classification accuracy. The memristor neural network is a promising hardware platform for artificial intelligence with high speed-energy efficiency.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2018_Li_InSituMemristorLearning_NatCommun.pdf", "analysed": true, "pdf": "10_On_Chip_and_Analog_Training/2018_Li_InSituMemristorLearning_NatCommun.pdf", "priority": 7.66}, {"id": "W2740220207", "short": "Multiscale Co-Design ReRAM Training", "title": "Multiscale Co-Design Analysis of Energy, Latency, Area, and Accuracy of a ReRAM Analog Neural Training Accelerator", "authors": ["Matthew J. Marinella", "Sapan Agarwal", "Alexander H. Hsia", "Isaac Richter", "Robin Bay Jacobs-Gedrim", "John Niroula", "Steven J. Plimpton", "Engin İpek", "Conrad D. James"], "year": 2018, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems (2018)", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2018.2796379", "cites_global": 184, "cat": "10", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "algorithm+simulation", "tldr": "A device-to-algorithm co-design study of a ReRAM-based analog neural-network training accelerator block, quantifying energy/latency/area gains over digital SRAM and ReRAM designs and showing realistic TaOx ReRAM device non-idealities cap MNIST backpropagation training accuracy at ~77-85% versus ~98% in floating point.", "summary": "The paper studies an analog ReRAM crossbar module performing vector-matrix multiply, matrix-vector multiply, and outer-product weight updates for on-chip neural network training, arguing that separating device/circuit/architecture/algorithm design (as in traditional CMOS flows) is insufficient when analog device non-idealities directly affect algorithm-level accuracy. It develops energy, latency, and area models for the analog block and compares them against digital SRAM-only and digital-ReRAM implementations. Using Sandia's open-source CrossSim simulator and measured TaOx ReRAM conductance-change (G-pulse) statistics (following the Burr et al. methodology), it simulates backpropagation training of a 784x300x10 MNIST MLP with device nonidealities (nonlinearity, asymmetry, stochasticity) injected into each weight update, and decomposes which nonideality mechanisms most degrade accuracy. Results show the analog ReRAM accelerator offers roughly 430x energy, 34x latency, and 11x area advantage over an SRAM-based accelerator, and roughly 270x energy and 540x latency advantage over a digital ReRAM design, but realistic device conductance-update nonlinearity limits MNIST training accuracy to about 77% (up to ~85% with optimized pulsing) versus ~98% for numerically exact training, identifying device nonlinearity as the dominant accuracy-limiting factor and endurance/voltage requirements as key unsolved device challenges.", "contributions": ["A multiscale (device-to-architecture) co-design methodology and set of analytical energy/latency/area models for a ReRAM analog vector-matrix-multiply/outer-product training accelerator block", "Quantitative comparison of the analog ReRAM block against digital SRAM-only and digital ReRAM implementations for the same training operations", "Measured-device-grounded simulation (via CrossSim, using TaOx ReRAM G-pulse statistics) of MNIST backpropagation training accuracy under analog weight-update nonidealities", "Decomposition of accuracy loss into separate contributions from nonlinearity, asymmetry, and stochasticity of the conductance-update characteristic", "Identification of specific unsolved device challenges (endurance, operating voltage, ultra-low programming current) required to realize the projected accelerator gains"], "claims": [{"claim": "An analog ReRAM training accelerator provides large energy/latency/area advantages over SRAM-based and digital-ReRAM designs performing the same training operations", "support": "270x energy, 540x latency, 1.8x area better than digital ReRAM; 430x energy, 34x latency, 11x area better than SRAM-based accelerator", "loc": "Sec. VII Discussion; Sec. VIII Conclusion"}, {"claim": "A single analog multiply-accumulate operation in the proposed ReRAM block can be performed at ~11 fJ, meeting the paper's stated 10 fJ/operation (100 TOPS/W) target", "support": "'an analog multiply-accumulate requires ~11 fJ, meeting the target specified above'", "loc": "Sec. VII"}, {"claim": "Using measured TaOx ReRAM device characteristics in backpropagation training of MNIST caps achievable accuracy well below floating-point training", "support": "max accuracy with device ~77% (up to ~85% with optimized pulsing) vs ~98% for numeric (floating-point) training on a 784x300x10 network", "loc": "Sec. VI-A, Fig. 14"}, {"claim": "The dominant source of training-accuracy degradation is the nonlinear, state-dependent conductance-update characteristic of the ReRAM device, more so than stochastic (cycle-to-cycle) noise", "support": "comparison of 'no-noise', 'linearized', and full TaOx ReRAM curves shows the nonlinear state-dependence is the greatest degrader of accuracy", "loc": "Sec. VI-A"}, {"claim": "Multi-device synaptic schemes (e.g., periodic carry with multiple TaOx devices per synapse) can substantially recover training accuracy lost to single-device nonidealities", "support": "Fig. 15 compares single TaOx synapse vs. 3-device periodic-carry TaOx vs numeric training accuracy over epochs", "loc": "Sec. VI, Fig. 15"}], "results": ["270x energy and 540x latency improvement vs. digital ReRAM; 1.8x area improvement", "430x energy and 34x latency improvement vs. SRAM/CMOS-only accelerator; 11x area improvement", "~11 fJ per analog multiply-accumulate operation", "MNIST (784x300x10 MLP) training accuracy: ~98% numeric (floating point) vs ~77% with as-measured TaOx ReRAM device nonidealities, up to ~85% with optimized pulse voltage/length"], "limitations": ["Accuracy results are from algorithmic simulation (CrossSim) using measured single-device conductance statistics, not a fabricated full training accelerator chip", "Evaluated only on a small 3-layer MLP on MNIST, not larger/deeper networks or convolutional architectures", "Energy/latency/area comparisons are analytical/architectural-level estimates for a training accelerator block, not full end-to-end system benchmarks with ADC/DAC and control overhead", "Authors explicitly note ReRAM device endurance (needs >10^13 cycles vs ~10^12 demonstrated) and operating-voltage requirements are not yet met for analog training accelerators", "The low ~77-85% MNIST accuracy with realistic devices highlights that the projected hardware efficiency gains are not yet achievable with acceptable accuracy using current TaOx ReRAM devices"], "remarks": "This Sandia National Laboratories study is a notable early (2018) device-to-algorithm co-design analysis that is unusually transparent about the gap between projected hardware efficiency and achievable training accuracy with real ReRAM conductance-update nonlinearity -- a caution against purely architectural energy/latency projections that ignore device-level write nonidealities. Its CrossSim-based accuracy results (using the Burr et al. methodology for extracting device statistics) and its explicit identification of conductance nonlinearity as the dominant accuracy limiter are frequently cited by later hardware-aware training and analog accelerator papers; the paper is more a feasibility/requirements study than a competitive accelerator proposal, and later work (e.g., IBM's PCM training results) achieved much higher accuracy by using differential/multi-device synapse schemes akin to the periodic-carry approach it discusses.", "basis": "full-text", "pdf_source_url": "", "abstract": "Neural networks are an increasingly attractive algorithm for natural language processing and pattern recognition. Deep networks with >50 M parameters are made possible by modern graphics processing unit clusters operating at <;50 pJ per op and more recently, production accelerators are capable of <;5 pJ per operation at the board level. However, with the slowing of CMOS scaling, new paradigms will be required to achieve the next several orders of magnitude in performance per watt gains. Using an analog resistive memory (ReRAM) crossbar to perform key matrix operations in an accelerator is an attractive option. This paper presents a detailed design using the state-of-the-art 14/16 nm process development kit for of an analog crossbar circuit block designed to process three key kernels required in training and inference of neural networks. A detailed circuit and device-level analysis of energy, latency, area, and accuracy are given and compared with relevant designs using standard digital ReRAM and static random access memory (SRAM) operations. It is shown that the analog accelerator has 270× energy and 540× latency advantage over a similar block utilizing only digital ReRAM and takes only 11 fJ per multiply and accumulate. Compared with an SRAM-based accelerator, the energy is 430× better and latency is 34× better. Although training accuracy is degraded in the analog accelerator, several options to improve this are presented. The possible gains over a similar digital only version of this accelerator block suggest that continued optimization of analog resistive memories is valuable. This detailed circuit and device analysis of a training accelerator may serve as a foundation for further architecture-level studies.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2018_Marinella_MultiscaleCoDesignReRAMTraining_JETCAS.pdf", "analysed": true, "pdf": "10_On_Chip_and_Analog_Training/2018_Marinella_MultiscaleCoDesignReRAMTraining_JETCAS.pdf", "priority": 6.32}, {"id": "W2796472956", "short": "TIME", "title": "TIME: A Training-in-Memory Architecture for RRAM-Based Deep Neural Networks", "authors": ["Ming Cheng", "Lixue Xia", "Zhenhua Zhu", "Yi Cai", "Yuan Xie", "Yu Wang", "Huazhong Yang"], "year": 2018, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems (2018)", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2018.2824304", "cites_global": 66, "cat": "10", "seed": false, "devices": ["ReRAM"], "models": ["MLP"], "evidence": "simulation", "tldr": "TIME is a Training-in-Memory RRAM architecture and peripheral-circuit design supporting backpropagation and weight update (not just inference), reporting 5.3x higher energy efficiency than DaDianNao for supervised learning and up to 126x higher efficiency than GPU for deep reinforcement learning.", "summary": "Neural-network training is time- and resource-intensive, and while RRAM crossbars can efficiently perform the matrix-vector multiplications used in inference, existing RRAM architectures only support inference and cannot perform the backpropagation and weight-update steps needed for on-chip training; moreover, the iterative RRAM weight updates required for training incur large energy costs due to RRAM's non-ideal device behavior. The authors propose TIME, a Training-in-Memory RRAM architecture and accompanying peripheral circuit design that supports backpropagation and weight update directly on RRAM crossbars while maximizing reuse of the peripheral circuits already used for inference. They also design a set of optimization strategies that target RRAM's non-ideal factors to reduce the cost of tuning (writing) RRAM cells during training. They evaluate TIME on both supervised learning (SL) and deep reinforcement learning (DRL) workloads, including a specific DRL-oriented mapping method to further improve energy efficiency, using simulation. Reported results show TIME achieves 5.3x higher energy efficiency than DaDianNao (a CMOS ASIC) on average for supervised learning, and about 126x higher energy efficiency than GPU on average for deep reinforcement learning, with the authors projecting up to two further orders of magnitude improvement if RRAM tuning costs can be further reduced.", "contributions": ["TIME, an RRAM-based Training-in-Memory architecture that supports backpropagation and weight update in addition to inference, unlike prior RRAM accelerators limited to inference", "A peripheral circuit design that maximizes reuse of inference-time peripheral circuitry (ADCs/DACs, sense amps, etc.) for the training (BP/weight-update) datapath", "A set of optimization strategies specifically targeting RRAM non-ideal factors to reduce the energy/time cost of iterative weight tuning during training", "Evaluation across both supervised learning and deep reinforcement learning workloads, including a DRL-specific mapping method for improved energy efficiency"], "claims": [{"claim": "TIME achieves substantially higher energy efficiency than a CMOS ASIC baseline (DaDianNao) for supervised-learning training workloads", "support": "'TIME can achieve 5.3x higher energy efficiency on average compared with DaDianNao'", "loc": "Abstract"}, {"claim": "TIME achieves much higher energy efficiency than GPU for deep reinforcement learning workloads", "support": "'TIME can perform an average 126x higher than GPU in energy efficiency' in DRL", "loc": "Abstract"}, {"claim": "Further reductions in RRAM tuning (write) cost could allow TIME's energy-efficiency advantage over ASIC to grow by roughly two more orders of magnitude", "support": "'If the cost of tuning RRAM can be further reduced, TIME has the potential to boost the energy efficiency by two orders of magnitudes compared with ASIC'", "loc": "Abstract"}], "results": ["5.3x average energy-efficiency improvement over DaDianNao (ASIC) for supervised learning", "126x average energy-efficiency improvement over GPU for deep reinforcement learning", "Up to ~2 further orders-of-magnitude projected improvement vs. ASIC if RRAM write/tuning cost is reduced"], "limitations": ["Full text not available to this review (abstract-only basis); specific benchmark networks, crossbar sizes, and precision/accuracy assumptions underlying the reported speedups could not be independently verified", "Results are simulation-based rather than measured on fabricated silicon", "The large gains for deep reinforcement learning depend on a specific, workload-tailored mapping method, so the generality of the 126x figure across other DRL algorithms is unclear from the abstract alone", "The stated further two-orders-of-magnitude improvement is an explicitly conditional projection (contingent on reducing RRAM tuning cost), not an achieved result"], "remarks": "TIME is an important and frequently cited RRAM training-in-memory architecture, built on the same Tsinghua group's prior inference-focused work (MNSIM), and is commonly used as a comparison baseline in later on-chip/analog training architecture papers (e.g., PANTHER, TxSim). Because the full text could not be retrieved, the headline efficiency numbers above are taken directly from the paper's own abstract; the practical significance of the DRL-specific 126x figure depends on workload and mapping details not verifiable here.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The training of neural networks (NN) is usually time-consuming and resource intensive. The emerging metaloxide resistive random-access memory (RRAM) device has shown potential for the computation of NN. RRAM crossbar structure and multibit characteristics can perform the matrix-vector product in high energy efficiency, which is the most common operation of NN. Two challenges exist for realizing training NN based on RRAM. First, the current architectures based on RRAM only support the inference in training NN and cannot perform the backpropagation (BP) and the weight update of training NN. Second, training NN requires enormous iterations to constantly update the weights for reaching the convergence. However, this weight update leads to large energy consumption because of the nonideal factors of RRAM. In this paper, we propose a training-in-memory based on RRAM (TIME) architecture and the peripheral circuit design to enable training NN on RRAM. TIME supports the BP and the weight update while maximizing the re-usage of peripheral circuits of the inference operation on RRAM. Meanwhile, a set of optimization strategies focusing on the nonideal factors are designed to reduce the cost of tuning RRAM. We explore the performance of both supervised learning (SL) and deep reinforcement learning (DRL) on TIME. A specific mapping method of DRL is also introduced to further improve energy efficiency. Simulation results show that in SL, TIME can achieve 5.3× higher energy efficiency on average compared with DaDianNao, an application-specific integrated circuits (ASIC) in CMOS technology. In DRL, TIME can perform an average 126× higher than GPU in energy efficiency. If the cost of tuning RRAM can be further reduced, TIME has the potential to boost the energy efficiency by two orders of magnitudes compared with ASIC.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2018_Cheng_TIME_TCAD.pdf", "analysed": true, "pdf": null, "priority": 5.11}, {"id": "W2787453651", "short": "FeFET Analog Synapse", "title": "Ferroelectric FET analog synapse for acceleration of deep neural network training", "authors": ["Matthew Jerry", "Pai-Yu Chen", "Jianchi Zhang", "Pankaj Sharma", "Kai Ni", "Shimeng Yu", "Suman Datta"], "year": 2017, "venue": "", "venue_short": "IEDM", "venue_full": "2017 IEEE International Electron Devices Meeting (IEDM)", "venue_ok": true, "doi": "https://doi.org/10.1109/iedm.2017.8268338", "cites_global": 590, "cat": "10", "seed": false, "devices": ["FeFET"], "models": ["MLP"], "evidence": "device-experiment", "tldr": "Demonstrates a 5-bit ferroelectric-FET (FeFET) analog synapse with symmetric potentiation/depression and a 45x tunable conductance range using 75ns update pulses, and benchmarks it via a circuit macro-model to show 10^3-10^6x faster on-chip learning latency than multi-state RRAM analog synapses.", "summary": "Deep neural network training is normally bottlenecked by off-chip storage and updating of synaptic weights (e.g., in DRAM), which limits energy efficiency and training time; on-chip analog non-volatile memory crossbars could remove this bottleneck if they can store and update weights with enough precision. The authors exploit voltage-controlled partial polarization switching dynamics in ferroelectric-FETs (FeFETs) to build an analog synapse and develop a transient Preisach model that accurately predicts minor-loop trajectories and remnant polarization charge for arbitrary pulse width, voltage and history. They experimentally demonstrate a FeFET-based analog synapse with 5-bit resolution, symmetric potentiation/depression characteristics, and a 45x tunable conductance range achieved with 75 ns update pulses. Using a circuit macro-model built on these device characteristics, they benchmark on-chip learning performance (area, latency, energy, accuracy) of a FeFET synaptic core and report a 10^3-10^6x improvement in online-learning latency compared to multi-state RRAM-based analog synapses.", "contributions": ["A transient Preisach model of FeFET partial polarization switching that predicts minor-loop trajectories and remnant polarization charge for arbitrary pulse width, voltage and programming history", "Experimental demonstration of a 5-bit FeFET analog synapse with symmetric potentiation and depression and a 45x conductance tuning range using fast (75 ns) update pulses", "A circuit macro-model benchmarking the area, latency, energy and accuracy of an on-chip learning core built from FeFET synapses", "Quantitative comparison showing large on-chip training-latency advantages of FeFET synapses over multi-state RRAM analog synapses"], "claims": [{"claim": "FeFET devices can implement a 5-bit analog synapse with symmetric, well-controlled potentiation/depression behavior", "support": "'experimentally demonstrate a 5-bit FeFET synapse with symmetric potentiation and depression characteristics'", "loc": "Abstract"}, {"claim": "The FeFET synapse supports fast weight updates with a wide dynamic range", "support": "45x tunable range in conductance achieved with a 75 ns update pulse", "loc": "Abstract"}, {"claim": "A FeFET-based synaptic core offers dramatically faster on-chip learning than multi-state RRAM-based analog synapse cores", "support": "circuit macro-model shows a 10^3-10^6x acceleration in online-learning latency over multi-state RRAM analog synapses", "loc": "Abstract"}], "results": ["5-bit (32-level) FeFET analog synapse resolution demonstrated experimentally", "45x tunable conductance range with 75 ns update pulses", "10^3 to 10^6x improvement in on-chip online-learning latency vs. multi-state RRAM analog synapses (circuit macro-model projection)"], "limitations": ["Full text not available to this review (abstract-only basis); exact test-vehicle size, network benchmarks, and macro-model assumptions could not be independently verified", "Device-level demonstration appears to be at the single/few-device level, with array-level and full-chip integration performance only estimated via a circuit macro-model rather than measured directly", "The large (10^3-10^6x) latency advantage over RRAM synapses is a modeled/projected comparison rather than a head-to-head silicon measurement", "No neural-network task-level (e.g., classification) accuracy results are reported in the abstract; accuracy benchmarking in the macro-model appears to be at the circuit/synapse level rather than end-to-end"], "remarks": "This is an early and influential device-level demonstration that FeFETs can serve as fast, symmetric, multi-bit analog synapses for on-chip DNN training, positioning FeFET as a competitive alternative to RRAM/PCM for analog training accelerators; it is frequently cited in later on-chip-training and device-comparison surveys (e.g., alongside DNN+NeuroSim benchmarking work). Because only the abstract was available, the strong latency-improvement claim versus RRAM synapses should be read as model-based projection grounded in measured single-device FeFET characteristics, not as a measured full-core or full-chip comparison.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "The memory requirement of at-scale deep neural networks (DNN) dictate that synaptic weight values be stored and updated in off-chip memory such as DRAM, limiting the energy efficiency and training time. Monolithic cross-bar / pseudo cross-bar arrays with analog non-volatile memories capable of storing and updating weights on-chip offer the possibility of accelerating DNN training. Here, we harness the dynamics of voltage controlled partial polarization switching in ferroelectric-FETs (FeFET) to demonstrate such an analog synapse. We develop a transient Presiach model that accurately predicts minor loop trajectories and remnant polarization charge (Pr) for arbitrary pulse width, voltage, and history. We experimentally demonstrate a 5-bit FeFET synapse with symmetric potentiation and depression characteristics, and a 45x tunable range in conductance with 75ns update pulse. A circuit macro-model is used to evaluate and benchmark on-chip learning performance (area, latency, energy, accuracy) of FeFET synaptic core revealing a 103to 106acceleration in online learning latency over multi-state RRAM based analog synapses.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2017_Jerry_FeFETAnalogSynapse_IEDM.pdf", "analysed": true, "pdf": null, "priority": 6.3}, {"id": "W1937359183", "short": "PCM 165k-Synapse Network", "title": "Experimental Demonstration and Tolerancing of a Large-Scale Neural Network (165 000 Synapses) Using Phase-Change Memory as the Synaptic Weight Element", "authors": ["Geoffrey W. Burr", "Robert M. Shelby", "Severin Sidler", "Carmelo di Nolfo", "Junwoo Jang", "Irem Boybat", "Rohit S. Shenoy", "Pritish Narayanan", "Kumar R. Virwani", "Emanuele U. Giacometti", "Bulent N. Kurdi", "Hyunsang Hwang"], "year": 2015, "venue": "IEEE Transactions on Electron Devices", "venue_short": "TED", "venue_full": "IEEE Transactions on Electron Devices, 2015", "venue_ok": true, "doi": "https://doi.org/10.1109/ted.2015.2439635", "cites_global": 941, "cat": "10", "seed": false, "devices": ["PCM"], "models": ["MLP"], "evidence": "device-experiment", "tldr": "IBM demonstrates a three-layer perceptron with 164,885 synapses, each a pair of phase-change memory devices, trained in situ with a backpropagation variant suited to NVM+selector crossbars, reaching 82.2% train / 82.9% test accuracy on a 5000-example MNIST subset, and uses a matched simulator to tolerance how much PCM variability, yield, stochasticity, nonlinearity and asymmetry can be tolerated before accuracy collapses.", "summary": "The paper addresses whether phase-change memory (PCM), as a non-volatile analog synaptic weight element, can support training of a reasonably large neural network despite its non-ideal conductance-update behavior (noise, nonlinearity, asymmetry between potentiation and depression, device-to-device variability, and imperfect yield). Each synaptic weight is represented differentially by two PCM devices, and a large-scale three-layer perceptron (164,885 synapses) is built/operated and trained with a backpropagation-derived weight-update rule adapted for crossbar arrays with an access device (selector) at each cell, on a 5,000-example subset of MNIST. The experimental system achieves 82.2% training accuracy and 82.9% generalization (test) accuracy. To go beyond what the hardware demonstrator alone could probe, the authors build a neural-network simulator calibrated to match the experimental PCM array and use it to perform extensive tolerancing studies, sweeping NVM variability, device yield, and the stochasticity/linearity/asymmetry of the conductance response. The central finding is that a bidirectional NVM device with a symmetric, linear, high-dynamic-range conductance response can in principle match the accuracy of a conventional software-trained network on this task, identifying which device non-idealities are and are not tolerable for on-chip/analog training.", "contributions": ["Large-scale (164,885-synapse) experimental demonstration of an on-chip-trainable neural network using PCM devices as the synaptic weight element, with two PCM devices per differential synapse", "Adapts the backpropagation weight-update rule to a form compatible with NVM+selector crossbar arrays for in-situ training", "Achieves 82.2% training / 82.9% generalization accuracy on a 5,000-example MNIST subset with real PCM hardware", "Builds and calibrates a neural-network simulator matched to the experimental PCM demonstrator to extend analysis beyond the hardware's own scale/conditions", "Performs extensive tolerancing of PCM-array non-idealities (variability, yield, stochasticity, conductance-response linearity and asymmetry) to identify the device requirements for analog on-chip training to match software baseline accuracy"], "claims": [{"claim": "A PCM-based crossbar network can be trained in situ to reach close to the accuracy of a software-trained equivalent network on a reduced MNIST task", "support": "82.2% training accuracy and 82.9% generalization accuracy reported for the experimental 164,885-synapse PCM network (abstract)", "loc": "Abstract"}, {"claim": "A bidirectional NVM device with symmetric, linear, high-dynamic-range conductance response is sufficient to match conventional software-based classification accuracy on this problem", "support": "Simulator-based tolerancing results (as stated in the abstract) show such a device profile achieves accuracy parity with software", "loc": "Abstract / tolerancing simulation results"}], "results": ["164,885-synapse three-layer perceptron implemented with PCM devices (two PCM per synapse)", "82.2% training accuracy and 82.9% generalization (test) accuracy on a 5,000-example MNIST subset", "Simulator-based tolerancing shows accuracy is sensitive to NVM variability, yield, and the stochasticity/linearity/asymmetry of the conductance response, with symmetric+linear+high-dynamic-range response needed to match software accuracy"], "limitations": ["Analysis based on the paper's abstract only; full methodological details, exact figures/tables for the tolerancing sweeps, and specific numeric tolerance thresholds could not be independently verified in this pass", "Evaluated on a reduced 5,000-example subset of MNIST rather than the full dataset, and with a relatively small 3-layer perceptron by later standards", "Reported accuracies (~82%) are notably below the near-99% achievable by software MLPs on MNIST, reflecting the impact of real PCM device non-idealities", "Tolerancing conclusions are drawn from a simulator calibrated to, but not identical to, the physical hardware, so its generality beyond the specific PCM device model used is not established here"], "remarks": "This is one of the earliest and most-cited large-scale hardware demonstrations of on-chip/analog training with PCM, establishing both a scaling milestone (164,885 synapses on real NVM) and a widely used tolerancing methodology (sweeping variability, yield, nonlinearity, and asymmetry against a calibrated simulator) that strongly influenced later PCM/ReRAM hardware-aware training work, including subsequent IBM papers on equivalent-accuracy analog training and PCM device models for deep learning. Because this entry is abstract-only (no verified open-access full text could be retrieved within the allotted attempts -- IBM Research, EPFL Infoscience, and Semantic Scholar mirrors were checked but the Infoscience OA copy was blocked by a bot-verification wall), the specific tolerancing numbers, figures and architecture details beyond what the abstract states should be confirmed against the original IEEE TED paper before being cited with precision.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Using two phase-change memory devices per synapse, a three-layer perceptron network with 164 885 synapses is trained on a subset (5000 examples) of the MNIST database of handwritten digits using a backpropagation variant suitable for nonvolatile memory (NVM) + selector crossbar arrays, obtaining a training (generalization) accuracy of 82.2% (82.9%). Using a neural network simulator matched to the experimental demonstrator, extensive tolerancing is performed with respect to NVM variability, yield, and the stochasticity, linearity, and asymmetry of the NVM-conductance response. We show that a bidirectional NVM with a symmetric, linear conductance response of high dynamic range is capable of delivering the same high classification accuracies on this problem as a conventional, software-based implementation of this same network.", "review": [], "pdf_expected": "10_On_Chip_and_Analog_Training/2015_Burr_PCM165kSynapseNetwork_TED.pdf", "analysed": true, "pdf": null, "priority": 8.24}, {"id": "W7134813260", "short": "HaLoRA", "title": "Hardware-aware Low-Rank Adaptation for Large Language Models Based on Hybrid Compute-in-Memory Architecture", "authors": ["Taiqiang Wu", "Chenchen Ding", "Weitao Zhou", "Yuxin Cheng", "Xincheng Feng", "Shuqi Wang", "Wendong Xu", "Chufan Shi", "Zhengwu Liu", "Ngai Wong"], "year": 2026, "venue": "ACM Transactions on Design Automation of Electronic Systems", "venue_short": "TODAES", "venue_full": "ACM Transactions on Design Automation of Electronic Systems", "venue_ok": true, "doi": "https://doi.org/10.1145/3801559", "cites_global": 4, "cat": "11", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["Transformer", "GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "HaLoRA deploys LoRA-finetuned LLMs on a hybrid RRAM (frozen backbone) + SRAM (LoRA branch) CIM architecture and trains the LoRA branch to be robust to RRAM read noise, recovering up to 22.7 points of average accuracy lost to noise while costing only ~3% of the energy of an A100 GPU.", "summary": "The paper targets efficient on-chip deployment of LoRA-finetuned LLMs: task-agnostic pretrained weights are mapped to energy-dense but noisy RRAM-based CIM macros, while the small, task-specific LoRA branch is mapped to noise-free SRAM-based digital CIM macros, exploiting the fact that LoRA parameters are a tiny fraction of total model size (e.g., 0.15% for LLaMA-3.2 1B). Because RRAM read noise on the frozen backbone degrades generation quality, they propose Hardware-aware LoRA (HaLoRA), which injects block-wise Gaussian noise into the pretrained weights during finetuning and adds a regularization loss that minimizes the theoretical upper bound on the gap between the LoRA optimization trajectory under noisy vs. ideal conditions, producing a LoRA branch that compensates for backbone noise without added inference cost. They evaluate by finetuning Qwen2.5-0.5B and LLaMA-3.2-1B/3B on six commonsense-reasoning benchmarks under injected Gaussian noise (and separately stuck-at faults) at several severities, and perform a hardware/energy/area simulation (via XPEsim plus reported silicon data) comparing GPU-only, RRAM-only, SRAM-only and the proposed RRAM+SRAM hybrid deployment. HaLoRA consistently beats vanilla LoRA in both accuracy and run-to-run variance under noise, with training overhead that is negligible (+0.12h, +0.9GB GPU memory for Qwen2.5-0.5B), and the hybrid hardware strategy achieves energy within ~0.3% of the RRAM-only strategy while matching SRAM-level robustness.", "contributions": ["Proposes a hybrid CIM deployment strategy for LoRA-finetuned LLMs: frozen backbone on RRAM, trainable LoRA branch on SRAM", "Proposes HaLoRA, a noise-aware finetuning method that minimizes a derived upper bound on the gap between noisy and noise-free LoRA optimization trajectories", "Designs a PE-level hybrid CIM architecture (HaLoRA unit) combining 1T1R-RRAM analog macros and 10T-SRAM digital macros with adder-tree fusion for attention and FFN blocks", "Evaluates accuracy/robustness on Qwen2.5-0.5B and LLaMA-3.2-1B/3B across 6 commonsense-reasoning benchmarks under Gaussian noise and stuck-at faults", "Performs hardware simulation (energy, area) comparing GPU, RRAM-only, SRAM-only and hybrid RRAM+SRAM deployment"], "claims": [{"claim": "HaLoRA substantially reduces accuracy degradation from RRAM noise compared to vanilla LoRA", "support": "At noise level 0.02, HaLoRA average score 63.1 vs. LoRA 40.4 for LLaMA-3.2 1B (+22.7 points)", "loc": "Sec. 1 / Table 3"}, {"claim": "HaLoRA achieves much lower run-to-run variance under noise", "support": "LLaMA-3.2 1B: variance on WinoGrande 1.0 vs 12.9 (7%), on PIQA 1.7 vs 17.3 (10%) of vanilla LoRA's variance", "loc": "Sec. 4.2"}, {"claim": "The hybrid RRAM+SRAM deployment is dramatically more energy efficient than GPU inference", "support": "LLaMA-3.2 1B, 512 tokens: HaLoRA 18.1 mJ vs. 550.5 mJ on an Nvidia A100 GPU (3.29%)", "loc": "Sec. 1 / Table 6"}, {"claim": "The hybrid strategy's energy cost is close to the RRAM-only strategy despite adding SRAM for LoRA", "support": "LLaMA-3.2 3B: HaLoRA 51.3 mJ vs. RRAM-only 51.1 mJ (0.3% more); circuit area only 1.1% more than RRAM-only, 10% of SRAM-only", "loc": "Sec. 4.5 / Table 6"}, {"claim": "Larger models are intrinsically more robust to backbone noise", "support": "Accuracy drop at noise 0.02: LLaMA-3.2 1B 21.9 vs 3B 15.8 points for vanilla LoRA; 4.5 vs 2.9 for HaLoRA", "loc": "Sec. 4.2"}, {"claim": "The training-time overhead of HaLoRA's extra regularization loss is negligible", "support": "Qwen2.5-0.5B: +0.12h training time (1.95 vs 1.83h), +0.9GB GPU memory (19.7 vs 18.8GB)", "loc": "Sec. 4.3 / Table 4"}], "results": ["HaLoRA average-score gains over vanilla LoRA at noise level 0.02: +20.5 (Qwen2.5 0.5B, 48.6 vs 28.1), +22.7 (LLaMA-3.2 1B, 63.1 vs 40.4), +13.5 (LLaMA-3.2 3B, 78.4 vs 64.9)", "Energy per 512-token inference, LLaMA-3.2 1B: HaLoRA 18.1 mJ vs A100 GPU 550.5 mJ (3.29%)", "Energy per 512-token inference, LLaMA-3.2 3B: HaLoRA 51.3 mJ vs A100 GPU 1666.8 mJ (3.0%), vs RRAM-only 51.1 mJ (+0.3%)", "RRAM arrays dominate energy consumption of transformer blocks: 72.83% (1B) and 78.66% (3B) of total; SRAM LoRA branch only 0.54%/0.42%", "At noise-free deployment, HaLoRA still outperforms vanilla LoRA (e.g., average score 67.6 vs 62.3 in a qualitative case; up to +9.08 points on ARC-c in ablation)"], "limitations": ["Evaluated only on commonsense-reasoning benchmarks (6 tasks); no mathematical reasoning or code generation, left as future work", "RRAM non-ideality modeled only as block-wise zero-mean Gaussian noise (plus a separate stuck-at-fault study); no conductance drift, cycle-to-cycle variation, or IR-drop modeling", "All hardware numbers (energy, area) are simulation-based using XPEsim and reported taped-out-chip data, not an actual fabricated hybrid chip", "Largest model evaluated is LLaMA-3.2 3B; scaling behavior to larger LLMs (7B+) with full on-chip RRAM capacity is not demonstrated", "Assumes idealized single-cell 8-bit weight storage in RRAM (high-precision programming) rather than realistic multi-bit-per-cell programming variability"], "remarks": "This is an algorithm+simulation paper, not measured silicon, so the energy/area numbers rely on XPEsim projections calibrated against reported chip data rather than an actual fabricated hybrid RRAM/SRAM system; the accuracy robustness claims are better supported since they come from real LLM finetuning runs with injected noise. The RRAM-backbone/SRAM-LoRA split is a clean, practical instance of the broader 'put the noise-sensitive, frequently-updated part on a reliable device and the bulk of static weights on a dense but noisy device' pattern seen elsewhere in hybrid CIM work; it is a useful complement to papers that instead try to make the whole backbone noise-robust via quantization or mapping tricks. For a thesis on mapping LLMs to analog crossbars, this is a good example of noise-aware PEFT co-design, though it should be read alongside device-level or chip-level papers for a realistic sense of RRAM noise beyond Gaussian/stuck-at models.", "basis": "full-text", "pdf_source_url": "", "abstract": "Low-rank adaptation (LoRA) is a predominant parameter-efficient finetuning method for adapting large language models (LLMs) to downstream tasks. Meanwhile, Compute-in-Memory (CIM) architectures demonstrate superior energy efficiency due to their array-level parallel in-memory computing designs. In this article, we propose deploying the LoRA-finetuned LLMs on the hybrid CIM architecture (i.e., pretrained weights onto energy-efficient Resistive Random-Access Memory (RRAM) and LoRA branches onto noise-free Static Random-Access Memory (SRAM)), reducing the energy cost to about 3% compared with the Nvidia A100 GPU. However, the inherent noise of RRAM on the saved weights leads to performance degradation, simultaneously. To address this issue, we design a novel Hardware-aware Low-rank Adaptation (HaLoRA) method. The key insight is to train a LoRA branch that is robust toward such noise and then deploy it on noise-free SRAM, while the extra cost is negligible since the parameters of LoRAs are much fewer than pretrained weights (e.g., 0.15% for LLaMA-3.2 1B model). To improve the robustness towards the noise, we theoretically analyze the gap between the optimization trajectories of the LoRA branch under both ideal and noisy conditions and further design an extra loss to minimize the upper bound of this gap. Therefore, we can enjoy both energy efficiency and accuracy during inference. Experiments finetuning the Qwen and LLaMA series demonstrate the effectiveness of HaLoRA across multiple reasoning tasks, achieving up to 22.7 improvement in average score while maintaining robustness at various noise types and noise levels.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Wu_HaLoRA_TODAES.pdf", "analysed": true, "slm": true, "lm_models": ["Qwen2.5-0.5B", "LLaMA-3.2-1B", "LLaMA-3.2-3B"], "param_scale": "0.5B–3B", "slm_note": "LoRA-finetuned Qwen2.5-0.5B and LLaMA-3.2 1B/3B (SLM scale) evaluated with injected RRAM noise in simulation, with energy modeled for hybrid RRAM (analog CIM) + SRAM digital CIM versus A100 GPU.", "pdf": "11_Small_Language_Models_on_AIMC/2026_Wu_HaLoRA_TODAES.pdf", "priority": 9.92}, {"id": "W7127107108", "short": "AHWA-LoRA", "title": "Efficient transformer adaptation for analog in-memory computing via low-rank adapters", "authors": ["Chen Li", "Elena Ferro", "Corey Lammie", "Manuel Le Gallo", "Irem Boybat", "Bipin Rajendran"], "year": 2026, "venue": "Neuromorphic Computing and Engineering", "venue_short": "NeuromorphComputEng", "venue_full": "Neuromorphic Computing and Engineering (IOP Publishing), 2026", "venue_ok": true, "doi": "https://doi.org/10.1088/2634-4386/ae405e", "cites_global": 1, "cat": "11", "seed": true, "devices": ["PCM"], "models": ["BERT", "Transformer", "GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "AHWA-LoRA keeps the pretrained transformer weights fixed on PCM AIMC tiles and trains only small digital LoRA adapters under simulated hardware noise. This matches full hardware-aware training on MobileBERT/SQuAD (F1 85.36 vs 85.14 after 10-year drift) with 15x fewer trainable parameters, allows multi-task switching and continual adaptation, and adds as little as 4% per-layer latency when the adapters run on RISC-V clusters.", "summary": "Conventional analog hardware-aware (AHWA) training retrains and reprograms the whole model for every task and every hardware change, which is costly for transformers and conflicts with the slow, energy-hungry programming of NVM. AHWA-LoRA programs the pretrained 'meta-weights' of all static linear layers (QKV, FFN, embedding and output projections) onto 512x512 PCM AIMC tiles with 8-bit DAC/ADC. During training, hardware noise (6.7% Gaussian weight noise, 4% ADC noise, clipping) is applied in the forward pass, but only the LoRA A/B matrices are updated; these run in FP on digital units next to each tile. Attention matmuls also run on the digital RISC-V PMCAs (Snitch cluster + RedMulE). Simulations use AIHWKIT with a PCM model calibrated on measured devices, including drift up to 10 years with global drift compensation. The method is tested on MobileBERT (SQuAD, GLUE), BERT-Base/Large, and LLaMA-3.1 8B (Alpaca instruction tuning and GRPO RL on GSM8K). Cycle-accurate RTL simulation of the PMCA is used to balance AIMC and LoRA latency through token batching.", "contributions": ["AHWA-LoRA: hardware- and task-adaptation via LoRA adapters while analog meta-weights stay fixed (no reprogramming)", "Demonstrates single-analog-model multi-task inference (8 GLUE tasks with swappable 1.6M-parameter adapters) and on-chip adaptation to changed ADC/DAC precision", "Scaling study from MobileBERT (25M) to BERT-Large (334M) and LLaMA-3.1 8B, including instruction tuning and GRPO reinforcement learning under analog noise", "Hybrid AIMC-tile + RISC-V PMCA architecture with pipeline/latency balancing analysis from cycle-accurate RTL simulation"], "claims": [{"claim": "Training only LoRA adapters matches or beats full AHWA training under drift", "support": "MobileBERT SQuAD v1.1 at 10-year drift: F1 85.36 vs 85.14 and EM 76.92 vs 76.40; within 1% at all drift times", "loc": "Table I"}, {"claim": "AHWA-LoRA substantially reduces training cost", "support": "~1M trainable parameters (>15x reduction) and 13% (>4 GB) less GPU memory on MobileBERT", "loc": "Table II"}, {"claim": "One analog model with swappable adapters serves many tasks", "support": "8 GLUE tasks with 8x1.6M LoRA params: 38.1M total vs (8x20.4+4.9)M for separate AHWA models, >4x fewer parameters", "loc": "Sec. Multi-Task Inference, Table III"}, {"claim": "LoRA can compensate for post-deployment hardware changes", "support": "8-bit to 6-bit ADC/DAC causes 25% F1 drop at 10-year drift; retrained LoRA lifts F1 from 60.81 to 74.23", "loc": "Fig. 3a"}, {"claim": "The approach transfers to billion-parameter LLMs", "support": "LLaMA-3.1 8B GSM8K (RL): analog 37.98% -> 70.74% after AHWA-LoRA (digital LoRA 85.06%); instruction tuning recovers up to 38.23 points on HellaSwag", "loc": "Tables IV-V"}, {"claim": "LoRA overhead on digital PMCAs can be largely hidden", "support": "latency overhead 2.72x / 1.39x / 1.05x for 128/256/512 ns integration time on 512x128 layers; best case 4% overhead", "loc": "Fig. 4c"}], "results": ["MobileBERT SQuAD v1.1 F1 at 10-year drift: AHWA-LoRA 85.36, full AHWA 85.14", "Trainable parameters ~1M (6.6% of model), >15x fewer than full AHWA training; GPU memory -13%", "LoRA rank 8 gives the best accuracy/cost trade-off; rank 1->2 adds ~2.2 F1 at 10 years, rank 8->16 only ~1.0", "BERT-Base and BERT-Large lose only 0.63 and 0.48 F1 after 10-year drift (vs ~4 points for MobileBERT)", "LLaMA-3.1 8B GSM8K with RL: 70.74% (analog, AHWA-LoRA) vs 37.98% (analog, no adaptation) and 85.06% (digital LoRA)", "Best-case 4% per-layer latency overhead vs pure AIMC when AIMC and PMCA latencies are balanced"], "limitations": ["Simulation only (AIHWKIT PCM model, RTL simulation of PMCA); no measured end-to-end chip run", "LLM experiments use a simplified Gaussian noise model without ADC/DAC modelling, no weight clipping, and reduced 3% noise for RL", "Attention and LoRA execute digitally in FP, so system energy depends on digital overhead that is not quantified in energy terms", "PMCA latency overhead can be large (2.72x) when AIMC integration is fast; memory needs exceed the 128 KiB TCDM for large layers and many tokens", "LLaMA results still show a ~15-point gap to digital on GSM8K at 3% noise"], "remarks": "This is a practical approach for weight-stationary AIMC deployment: program the analog arrays once and absorb hardware error and task drift into small digital adapters, which avoids NVM endurance and programming-time costs. The evidence is solid for BERT-class models with a realistic PCM model, but the LLaMA results use a looser noise abstraction, so they mostly show feasibility. It complements Büchel et al.'s Analog Foundation Models (full distillation HWA training) by making adaptation cheap, and HaLoRA (TODAES 2026) takes a similar RRAM-meta-weight + SRAM-LoRA split with a theory-motivated robustness loss.", "basis": "full-text", "pdf_source_url": "", "abstract": "Abstract Analog in-memory computing (AIMC) offers a promising solution to the von Neumann bottleneck. However, deploying transformer models on AIMC remains challenging due to their inherent need for flexibility and adaptability across diverse tasks. For the benefits of AIMC to be fully realized, weights of static vector-matrix multiplications must be mapped and programmed to analog devices in a weight-stationary manner. This poses two challenges for adapting a base network to hardware and downstream tasks: (i) conventional analog hardware-aware (AHWA) training requires retraining the entire model, and (ii) reprogramming analog devices is both time- and energy-intensive. To address these issues, we propose AHWA low-rank adaptation (AHWA-LoRA) training, a novel approach for efficiently adapting transformers to AIMC hardware. AHWA-LoRA training keeps the analog weights fixed as meta-weights and introduces lightweight external LoRA modules for both hardware and task adaptation. We validate AHWA-LoRA training on SQuAD v1.1 and the GLUE benchmark, demonstrate its scalability to larger models, and show its effectiveness in instruction tuning and reinforcement learning. We further evaluate a practical deployment scenario that balances AIMC tile latency with digital LoRA processing using optimized pipeline strategies, with RISC-V-based programmable multi-core accelerators. This hybrid architecture achieves efficient transformer inference with only a 4% per-layer overhead compared to a fully AIMC implementation.", "review": [{"fid": "F5", "text": "Full-model analog retraining is not necessary. Analog hardware-aware LoRA freezes the analog-programmed weights as fixed meta-weights and trains only small external digital low-rank adapters, matching full HWA retraining within 1% F1/EM on SQuAD v1.1 and beating it after 10 years of simulated PCM drift (F1 85.36 vs 85.14; EM 76.92 vs 76.40). Adapter-swapping also mitigates the reprogramming problem: one analog base model serves many tasks, avoiding the error accumulation of repeated programming, with adapters refreshed off-chip and drift handled by global drift compensation.", "grade": "Medium confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Graded medium: single research group, one model (MobileBERT), one task, and drift modeled rather than measured over 10 years."}], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Li_AHWA-LoRA_NeuromorphComputEng.pdf", "analysed": true, "slm": true, "lm_models": ["MobileBERT", "BERT-Base", "BERT-Large", "LLaMA-3.1 8B"], "param_scale": "MobileBERT to 8B (BERT-Base/Large 110M-340M)", "slm_note": "MobileBERT, BERT-Base/Large and LLaMA-3.1 8B (all <=10B) evaluated with simulated PCM analog in-memory computing (noise and 10-year drift) using low-rank adapters; no hardware chip.", "pdf": "11_Small_Language_Models_on_AIMC/2026_Li_AHWA-LoRA_NeuromorphComputEng.pdf", "priority": 10.71}, {"id": "W7143500069", "short": "JADE", "title": "JADE: Joint Architecture-Dataflow Exploration for LLM Inference on Heterogeneous In- and Near-Memory Computing Systems", "authors": ["Yimin Wang", "Zhen Wu", "Yue Jiet Chong", "Xuanyao Fong"], "year": 2026, "venue": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_short": "JETCAS", "venue_full": "IEEE Journal on Emerging and Selected Topics in Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/jetcas.2026.3679018", "cites_global": 0, "cat": "11", "seed": false, "devices": ["Generic-NVM"], "models": ["Transformer", "GPT/LLM"], "evidence": "analytical", "tldr": "JADE is a joint architecture-dataflow design-space-exploration framework for LLM inference on heterogeneous in-/near-memory computing (IMC/NMC) systems, using a unified matrix-multiplication representation to jointly explore compute/memory organization, interconnect topology, MM unrolling/mapping, and attention-mechanism handling.", "summary": "The paper observes that efficient LLM orchestration on in-memory computing (IMC) and near-memory computing (NMC) hardware, and the architectural design of that hardware itself, are tightly interrelated but usually studied separately, leaving a large, underexplored hardware-software co-design space. JADE (Joint Architecture-Dataflow Exploration) is proposed as a framework covering both architectural factors (computing/memory/communication organization) and algorithmic factors (LLM dataflow), organized into four key configuration categories: computing and memory organization, interconnection topology, matrix-multiplication (MM) unrolling and mapping, and attention-mechanism handling. A unified MM representation lets the framework flexibly unroll and map matrix multiplications onto varied architectural organizations, and dataflow routing is derived from the collective-communication patterns inherent to distributed LLM execution combined with the properties of common network topologies. The paper presents case studies illustrating design tradeoffs among these configuration axes and draws insights for both homogeneous and heterogeneous IMC/NMC architectures targeting LLMs.", "contributions": ["A joint architecture-dataflow design-space-exploration framework (JADE) spanning computing/memory organization, interconnect topology, MM unrolling/mapping, and attention handling", "A unified matrix-multiplication representation enabling flexible unrolling/mapping across different architectural organizations", "Dataflow routing derived from LLM distributed-execution communication patterns matched to common network topologies", "Case studies quantifying design tradeoffs for homogeneous and heterogeneous IMC/NMC architectures for LLM inference"], "claims": [{"claim": "Architectural and dataflow/algorithmic design choices for LLM IMC/NMC systems are interrelated and benefit from joint exploration rather than separate optimization", "support": "Abstract frames efficient orchestration and architecture optimization as 'interrelated, encompassing a hardware-software co-design space'", "loc": "Abstract"}], "results": ["No specific quantitative results available from the abstract alone; full text was not accessible"], "limitations": ["Full text not accessible to this reviewer (no open preprint found); the case-study results, specific architectures compared, and quantitative tradeoffs could not be verified", "Evidence basis appears to be an analytical/design-space-exploration framework rather than a single concrete accelerator with measured or simulated performance numbers"], "remarks": "Abstract-only assessment: JETCAS is not downloadable here and no arXiv preprint was found. The central contribution is a DSE/mapping framework for IMC/NMC systems (arguably also fitting category 05, Mapping/Compilation/Dataflow) rather than a specific LLM accelerator design or algorithmic robustness technique, though LLM inference is clearly the target workload. This kind of unified-representation DSE tool is valuable for systematically comparing mapping choices across the fragmented landscape of IMC/NMC LLM accelerators, but without the full text its concrete conclusions (which configurations actually win, and by how much) are unknown.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Large Language Model (LLM) inference challenges memory/computing organization and dataflow optimization on traditional hardware stacks due to its various attention mechanisms and autoregressive structure. In-memory computing (IMC) and near-memory computing (NMC) architectures have emerged as potential solutions to reduce the memory burden in LLMs. However, efficient LLM orchestration on IMC/NMC, as well as dedicated IMC/NMC architecture optimization, are interrelated, encompassing a hardware-software co-design space of a myriad of parameters, which still remains largely underexplored. This work provides a joint architecture-dataflow exploration (JADE) framework that covers both architectural factors on computing/memory/communication, and algorithmic factors on LLM dataflow. We identify key configurations in four categories: computing and memory organization, interconnection topology, matrix multiplication (MM) unrolling and mapping, and attention mechanism. A unified MM representation enables flexible unrolling and mapping on various architectural organizations. Dataflow is routed based on the collective communication patterns inherent in the distributed LLMs and the features of common topologies. Finally, case studies show the design tradeoffs between key design options and provide insights into both homogeneous and heterogeneous IMC/NMC design for LLMs.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Wang_JADE_JETCAS.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Only the abstract was available; it names no specific LLMs or scales, exploring IMC/NMC architecture-dataflow co-design.", "pdf": null, "priority": 8.0}, {"id": "W7162404347", "short": "AIMC for LLM Inference", "title": "Analog In-Memory Computing for Large Language Model Inference: Opportunities and Challenges", "authors": ["A. Vasilopoulos", "H. Benmeziane", "J. Büchel", "W. Simon", "A. Singh", "I. Boybat", "J. Luquin", "P. Narayanan", "H. Tsai", "G. W. Burr", "A. Rahimi", "M. Le Gallo", "V. Narayanan", "A. Sebastian"], "year": 2026, "venue": "", "venue_short": "IMW", "venue_full": "IEEE International Memory Workshop (IMW 2026)", "venue_ok": true, "doi": "https://doi.org/10.1109/imw68301.2026.11532624", "cites_global": 0, "cat": "11", "seed": false, "devices": ["PCM", "ReRAM", "Generic-NVM"], "models": ["Transformer", "GPT/LLM"], "evidence": "survey", "tldr": "A perspective paper from the IBM Research AIMC group arguing that LLM inference has shifted the AI-hardware bottleneck from compute to memory capacity/data movement, and surveying which LLM operations suit analog in-memory computing plus the open challenges in memory technology, algorithms, system architecture, and heterogeneous composition needed to make AIMC practical for LLM inference infrastructure.", "summary": "The paper's central argument is that the primary bottleneck for AI hardware running modern LLMs has moved from raw compute to memory capacity and data movement, which analog in-memory computing (AIMC) is well positioned to address since it performs matrix-vector multiplication directly within the memory array, cutting the data traffic associated with model weights. Written by IBM's AIMC research group (Vasilopoulos, Benmeziane, Buchel, Simon, Singh, Boybat, Luquin, Narayanan, Tsai, Burr, Rahimi, Le Gallo, Narayanan, Sebastian), it takes a 'holistic systems perspective,' analyzing the architecture of modern transformer-based LLMs to identify which operations (e.g., the large, static weight matrices in FC/projection layers) are well suited to AIMC versus which are not (e.g., dynamic attention/KV-cache operations). It then discusses the key challenges and opportunities across four areas needed to make AIMC a practical LLM-inference accelerator: memory technologies (device characteristics, array capacity), algorithms (quantization, hardware-aware training, noise robustness), system architecture (how AIMC tiles are composed into full accelerators), and heterogeneous system composition (combining AIMC with digital compute for the parts of LLMs that don't map well to analog arrays).", "contributions": ["Articulates the shift in LLM-era AI hardware bottlenecks from compute to memory capacity and data movement, and positions AIMC as a response", "Analyzes modern LLM/transformer architecture to identify which operations are well suited vs. poorly suited to AIMC execution", "Surveys challenges and opportunities across memory technology, algorithms, system architecture, and heterogeneous composition for AIMC-based LLM inference", "Authored by IBM's AIMC research group, drawing on their PCM/ReRAM in-memory compute chip experience (e.g., HERMES core, analog-AI chips referenced elsewhere in this collection)"], "claims": [{"claim": "The dominant AI-hardware bottleneck for LLMs has shifted from compute to memory capacity and data movement", "support": "Abstract: 'Recent advancements in large language models (LLMs) have shifted the primary bottleneck of AI hardware from compute to memory capacity and data movement'", "loc": "Abstract"}, {"claim": "Not all LLM operations are equally suited to AIMC execution; a holistic, heterogeneous systems view is needed", "support": "Abstract: 'identify which operations are well-suited for AIMC' and discussion of 'heterogeneous system composition'", "loc": "Abstract"}], "results": [], "limitations": ["This is a perspective/position paper rather than a paper reporting new experimental results; no new accuracy, throughput, or energy numbers are claimed in the abstract", "Full text not accessible to this reviewer (IMW proceedings not downloadable here, no arXiv preprint found), so the depth of the technical discussion in each of the four challenge areas could not be verified"], "remarks": "Abstract-only assessment: IMW proceedings are not downloadable here and no preprint was found. As a position/perspective piece from one of the most experienced industrial AIMC groups (IBM Research), it is a useful framing reference for a thesis on mapping AI models to analog hardware, since it explicitly names the LLM-specific gap (data movement/memory capacity dominating over compute) that most of the other accelerator papers in this collection (DuoPIM, ASMA, HyPIM, etc.) are implicitly trying to solve; it cites and builds on the same group's tile-design paper (W4417492578) in this set, suggesting it functions as a synthesis/roadmap document rather than a narrow technical contribution.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Recent advancements in large language models (LLMs) have shifted the primary bottleneck of AI hardware from compute to memory capacity and data movement. Analog in-memory computing (AIMC) offers a promising path to address this challenge by enabling matrix-vector multiplication directly within memory arrays, significantly reducing data transfers associated with model weights. In this paper, we discuss the role of AIMC in LLM inference workloads from a holistic systems perspective. We analyze the architecture of modern LLMs and identify which operations are well-suited for AIMC. We further discuss key challenges and opportunities in memory technologies, algorithms, system architecture, and heterogeneous system composition that must be addressed to enable AIMC as a practical accelerator for future AI inference infrastructure.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Vasilopoulos_AIMCforLLMInference_IMW.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Perspective paper on AIMC for LLM inference; names no specific models or scales.", "pdf": null, "priority": 8.0}, {"id": "W7164181555", "short": "HyPIM", "title": "HyPIM: LLM Acceleration with A Hybrid ReRAM/SRAM 3D-PIM Architecture", "authors": ["Xiaolong Hu", "Chubo Liu", "Yan Ding", "Keqin Li", "Kenli Li"], "year": 2026, "venue": "ACM Transactions on Embedded Computing Systems", "venue_short": "TECS", "venue_full": "ACM Transactions on Embedded Computing Systems", "venue_ok": true, "doi": "https://doi.org/10.1145/3820366", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM", "SRAM-analog"], "models": ["Transformer", "GPT/LLM"], "evidence": "simulation", "tldr": "HyPIM is a 3D hybrid SRAM+ReRAM PIM architecture for transformer-based LLMs that assigns different transformer-block operations to whichever memory slice suits their compute/memory-access characteristics, plus a hardware-friendly early-termination approximation and sparse matmul strategy for the attention bottleneck, achieving 1.27x-1.67x latency improvement over Newton, TransPIM, HAIMA, HARDSEA, and H3DAtten.", "summary": "The paper targets the mismatch between transformer-based LLM workloads and PIM designs built around a single memory technology (SRAM, DRAM, or ReRAM alone), since different operations within a transformer block (e.g., static weight-heavy projections vs. dynamic attention) have very different computation and memory-access characteristics that no single technology handles well. HyPIM is a 3D hybrid PIM architecture that integrates SRAM and ReRAM slices so they cooperate, routing each type of operation to the memory technology best suited to it. The authors note that even with this hybrid structure, attention's inference latency still dominates total latency for long sequences, so they further design a hardware-friendly early-termination approximation algorithm and a sparse matrix-multiplication strategy specifically for the HyPIM architecture, reducing attention overhead through combined software/hardware co-design. Evaluated against five prior accelerators/PIM designs (Newton, TransPIM, HAIMA, HARDSEA, and H3DAtten), HyPIM achieves 1.27x to 1.67x latency improvement.", "contributions": ["3D hybrid PIM architecture integrating SRAM and ReRAM slices that cooperate, matching each transformer-block operation to its best-suited memory technology", "Identification that attention latency continues to dominate even after hybridizing SRAM/ReRAM, motivating further optimization", "Hardware-friendly early-termination approximation algorithm for attention, co-designed with the HyPIM architecture", "Sparse matrix-multiplication strategy for HyPIM reducing attention computation/communication overhead", "Comparative evaluation against five prior architectures: Newton, TransPIM, HAIMA, HARDSEA, and H3DAtten"], "claims": [{"claim": "HyPIM improves latency over multiple state-of-the-art PIM/CIM transformer accelerators", "support": "1.27x-1.67x latency improvement compared with Newton, TransPIM, HAIMA, HARDSEA, and H3DAtten", "loc": "Abstract"}, {"claim": "Attention latency remains the dominant cost even in the hybrid SRAM/ReRAM architecture for long sequences", "support": "Abstract: 'HyPIM does not change the scenario where the inference latency of the attention mechanism continues to dominate the overall inference latency ... when dealing with long sequences of data'", "loc": "Abstract"}], "results": ["1.27x-1.67x latency improvement vs. Newton, TransPIM, HAIMA, HARDSEA, and H3DAtten"], "limitations": ["Full text not accessible to this reviewer (TECS is not downloadable here and no arXiv preprint was found); the specific benchmarked LLMs, sequence lengths, and accuracy impact of the early-termination approximation could not be verified", "The approximation/sparsity strategy for attention implies an accuracy-latency tradeoff whose magnitude is not confirmable from the abstract alone", "Evidence basis is simulation, not measured silicon for the 3D hybrid architecture"], "remarks": "Abstract-only assessment: TECS (ACM) is not downloadable here and no preprint was found. The comparison set (Newton, TransPIM, HAIMA, HARDSEA, H3DAtten) places this squarely among the recent wave of hybrid/heterogeneous CIM-for-transformer accelerators in this collection, and the explicit acknowledgment that attention latency still dominates even after hybridizing memory technologies is a useful, honest framing of the field's remaining bottleneck; the 1.27x-1.67x gains are comparatively modest next to some other papers in this batch claiming order-of-magnitude improvements, which may reflect a more realistic/conservative baseline comparison, but this cannot be confirmed without the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformer-based Large Language Models (LLMs) have made significant progress in the fields of computer vision and natural language processing. The use of LLMs in embedded and real-time systems to provide more powerful intelligence capabilities is also an inevitable trend. However, the traditional von Neumann architecture encounters great challenges with transformer-based LLMs due to huge data movement overheads. Processing-in-Memory (PIM) emerges as a great potential solution by significantly closing the gap between computation and storage. Nevertheless, transformer-based LLMs usually consist of multiple transformer blocks, and the operations within each transformer block vary significantly on computation and memory access characteristics. Existing PIM designs that rely solely on SRAM, DRAM, or ReRAM cannot adapt well to transformer-based LLMs. To address these challenges, we introduce HyPIM, a 3D hybrid PIM architecture that integrates SRAM and ReRAM slices to process through their cooperation. However, HyPIM does not change the scenario where the inference latency of the attention mechanism continues to dominate the overall inference latency in the transformer-based LLMs when dealing with long sequences of data. Exploiting these insights, we then design a hardware-friendly early termination approximation algorithm and a sparse matrix multiplication strategy for the HyPIM architecture, reducing the overhead through a software and hardware co-design. Compared with the state-of-the-art Newton, TransPIM, HAIMA, HARDSEA, and H3DAtten architectures, the proposed HyPIM architecture achieves up to a 1.27×–1.67× latency improvement.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Hu_HyPIM_TECS.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Only the abstract was available; it names no specific LLMs or scales, targeting hybrid ReRAM/SRAM 3D-PIM.", "pdf": null, "priority": 8.0}, {"id": "W7127342328", "short": "RoboPIM", "title": "RoboPIM: A ReRAM-Based Accelerator for LLM-Based Robotics Applications via Dynamic Task Slicing", "authors": ["Wenjing Xiao", "Jianyu Wang", "Dan Chen", "Huize Li", "Mohsen Guizani", "Min Chen", "Thomas Wu"], "year": 2026, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems, 2026", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2026.3660201", "cites_global": 1, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["GPT/LLM", "Robotics"], "evidence": "simulation", "tldr": "RoboPIM uses heterogeneous ReRAM crossbar sizes with dynamic task slicing and two-stage scheduling, giving 2.85x and 6.85x speedups across robot platforms and LLMs.", "summary": "LLM-based robotics involves dense and block-sparse matmuls of widely varying size, making large LLM-oriented crossbars inefficient. RoboPIM provides crossbars of various sizes, slices matrices to suitably sized crossbars, and uses a two-stage schedule for utilization. It reports 2.85x and 6.85x speedups over domain-specific solutions across robotic platforms and LLMs. (Abstract only.)", "contributions": ["Multi-size ReRAM crossbar architecture", "Dynamic task slicing", "Two-stage scheduling"], "claims": [{"claim": "2.85x and 6.85x speedup across platforms and LLMs", "support": "abstract", "loc": "Abstract"}], "results": ["2.85x speedup across robot platforms; 6.85x across LLMs"], "limitations": ["Abstract only", "No mention of device non-idealities or accuracy"], "remarks": "Mapping/scheduling work; the language model aspect is mostly workload framing. Nothing known on noise robustness.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "1Large Language Models (LLMs) have demonstrated significant potential in improving robotics applications through natural language processing capabilities. Matrix multiplication dominates the computational workload in these LLM-based robotics systems, and Resistive Random Access Memory (ReRAM) provides notable performance benefits due to its inherent parallelism and energy efficiency. However, matrix multiplications in these applications pose dual heterogeneity challenges, encompassing both structural and scale heterogeneity. Structurally, these applications involve both standard dense matrix operations and block-structured sparse multiplications, where sparsity patterns vary significantly with robot topology. In terms of scale, matrix sizes range from just a few to thousands of dimensions, making large ReRAM crossbars designed for LLM inefficient for small-scale robotics computations. Existing acceleration approaches fail to address this dual heterogeneity, limiting their effectiveness for LLM-based robotics applications. In this work, we propose RoboPIM, the first low-energy ReRAM-based accelerator tailored for LLM-based robotics applications. RoboPIM adapts to the diverse matrix multiplication requirements across robot platforms and LLM configurations. Our design features a ReRAM architecture with various crossbar sizes and implements a dynamic task slicing scheme that allocates matrix slices to appropriately sized crossbars. To maximize ReRAM’s parallel processing capabilities, we develop a two-stage scheduling strategy that efficiently manages matrix multiplications while enhancing hardware utilization. Comprehensive evaluations demonstrate that RoboPIM achieves 2.85× and 6.85× speedup across diverse robotic platforms and LLMs respectively, outperforming state-of-the-art domain-specific solutions.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Xiao_RoboPIM_TCAD.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "", "slm_note": "ReRAM crossbar (analog MVM) accelerator for matrix multiplications in LLM-based robotics pipelines; LLM configurations and scale unspecified in abstract; marginal LM focus (robot dynamics matmuls).", "added": "2026-10 SLM search", "pdf": null, "priority": 8.21}, {"id": "W7133301734", "short": "RSLPU-ISSCC", "title": "31.1 A 14.08-to-135.69Token/s ReRAM-on-Logic Stacked Outlier-Free Large-Language-Model Accelerator with Block-Clustered Weight-Compression and Adaptive Parallel-Speculative-Decoding", "authors": ["Pingcheng Dong", "Yonghao Tan", "Xuejiao Liu", "Peng Luo", "Yu Liu", "Di Pang", "Songchen Ma", "Xijie Huang", "Shih-Yang Liu", "D. Zhang", "Zhichao Lu", "Luhong Liang", "Chi-Ying Tsui", "Fengbin Tu", "Liang Zhao", "Kwang-Ting Cheng"], "year": 2026, "venue": "Digest of technical papers/Digest of technical papers - IEEE International Solid-State Circuits Conference", "venue_short": "ISSCC", "venue_full": "IEEE International Solid-State Circuits Conference (ISSCC), 2026", "venue_ok": true, "doi": "https://doi.org/10.1109/isscc49663.2026.11409211", "cites_global": 1, "cat": "11", "seed": false, "devices": ["ReRAM (face-to-face stacked)"], "models": ["GPT/LLM"], "evidence": "measured-silicon", "tldr": "55nm LLM accelerator with ReRAM-on-logic stacking, local-rotation W4A8 quantization, blockwise VQ and adaptive parallel speculative decoding; 14.08-135.69 token/s and 4.46-7.17x speedup over vanilla SD.", "summary": "Edge LLM decoding is dominated by weight external memory access. The chip stacks 4 ReRAM dies on logic via 2048 bumps (25.6GB/s, 8MB) to hold draft-model weights as block-level codebooks reconstructed on chip (blockwise vector quantization, INT4 QAT). A local rotation unit approximates global Hadamard rotation with two 6-depth FWHTs for outlier-free W4A8 target-LM quantization (92.7% area saving). Adaptive parallel speculative decoding with an out-of-order scheduler (4 instruction queues) raises utilization. Measured: 2.33 TOPS peak, 4.46-7.17x speedup and 3.74-4.85x energy saving over BF16 SD; LLaMA2-7B on MT-Bench 17.82 token/s and 123.41 mJ/token.", "contributions": ["Local rotation unit with decomposed FWHT for W4A8 outlier-free quantization", "ReRAM-stacked PNM with blockwise vector quantization", "Adaptive parallel speculative decoding with workload-decoupled out-of-order scheduler", "55nm chip with face-to-face ReRAM-on-logic stacking"], "claims": [{"claim": "LRU saves area vs global rotation and gives speedup", "support": "92.7% area saving; 3.82-3.93x speedup over BF16 SD", "loc": "Fig. 31.1.3"}, {"claim": "RS-PNM with INT4 BVQ speedup over W4A8 SD", "support": "1.1-1.46x", "loc": "Fig. 31.1.4"}, {"claim": "Overall speedup and energy saving vs BF16 SD", "support": "4.46-7.17x, 3.74-4.85x", "loc": "Fig. 31.1.6"}], "results": ["14.08-135.69 token/s", "2.33 TOPS peak, logic 63.5-285MHz at 0.89-1.40V", "ReRAM die 49.54mW at 100MHz, 1.1V; 25.6GB/s; 4-chip system 32MB, 102.4GB/s", "LLaMA2-7B MT-Bench: 17.82 token/s, 123.41 mJ/token"], "limitations": ["ReRAM used as storage only, no analog in-memory compute", "Only 8MB ReRAM per chip; DLM needs 4-chip system", "Comparison baselines enhanced by authors with LPDDR3 interface", "ReRAM retention/endurance not discussed in text"], "remarks": "Strong measured-silicon evidence and a practical use of NVM for small draft models. For analog IMC research it is a counterpoint: NVM contributes bandwidth/density, not analog MVM, so non-idealities are avoided.", "basis": "full-text", "pdf_source_url": "", "abstract": "This work presents a 55nm speculative decoding-based LLM accelerator with bumpingbased face-to-face ReRAM-on-logic stacking technology. It features a local rotation unit for outlier-free low-bit quantization, a stacking-aware PNM architecture co-designed with blockwise vector quantization to reduce weight EMA overheads, and an adaptive parallel speculative decoding scheme with out-of-order scheduler for high resource and bandwidth utilization. Our chip achieves 14.08-to-135.69token/s and 4.46-to-7.17× speedup over vanilla speculative decoding.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Dong_ReramOnLogicSpecDecodeLlm_ISSCC.pdf", "analysed": true, "slm": true, "lm_models": ["LLaMA2-7B", "LLaMA3-8B (target)", "draft LMs (unspecified small)"], "param_scale": "draft small; target 7-8B", "slm_note": "Speculative-decoding LLM accelerator, 55nm, with 4 stacked ReRAM dies (8MB) storing codebooks of the small draft LM (DLM); target LLMs include LLaMA2-7B and LLaMA3-8B. Compute is digital (tile-fused tensor engine, INT MACs); ReRAM is NOT used for analog MVM, only as high-bandwidth NVM storage (processing-near-memory). Relevant because the draft LM is an SLM held in NVM.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2026_Dong_ReramOnLogicSpecDecodeLlm_ISSCC.pdf", "priority": 8.81}, {"id": "W7118450172", "short": "KVCacheSLCMLC", "title": "Mapping strategy of quantized KV cache of LLMs into mixture of SLC and MLC ReRAM among various quantization methods", "authors": ["Shota Suzuki", "Naoko Misawa", "Chihiro Matsui", "Ken Takeuchi"], "year": 2026, "venue": "Japanese Journal of Applied Physics", "venue_short": "JJAP", "venue_full": "Japanese Journal of Applied Physics, 2026", "venue_ok": true, "doi": "https://doi.org/10.35848/1347-4065/ae33cb", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["GPT/LLM"], "evidence": "simulation", "tldr": "Splitting quantized KV values into upper bits in SLC and lower bits in MLC ReRAM gives 49.1% fewer cells with perplexity kept low across LLMs and quantizers.", "summary": "MLC ReRAM is denser than SLC but random telegraph noise causes false state detection. The authors analyze error robustness of the three components of a quantized KV cache and propose storing upper bits in SLC and lower bits in MLC. They report 49.1% fewer memory cells than the conventional method while keeping perplexity low regardless of LLM and quantization method. Abstract-only; details not checked.", "contributions": ["Error-robustness analysis of KV-cache components", "Hybrid SLC/MLC bit-split mapping", "49.1% cell reduction at maintained perplexity"], "claims": [{"claim": "49.1% fewer memory cells while maintaining perplexity", "support": "stated in abstract", "loc": "Abstract"}], "results": ["49.1% fewer cells vs conventional mapping"], "limitations": ["Abstract-only; models and noise levels unknown", "NVM used as storage, no in-memory compute", "Write endurance/latency for per-token KV writes not discussed in abstract"], "remarks": "Relevant to KV caches on NVM and to reliability-aware bit mapping. Uncertain evidence strength without the paper; the bit-significance split is a sensible, reusable idea.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Abstract Quantized key-value (KV) cache is a remarkable technology to reduce the memory footprint during large language model (LLM) inference. While multi-level cell (MLC) resistive random-access memory (ReRAM) offers higher density than single-level cell (SLC) ReRAM, its current fluctuation, often induced by random telegraph noise, leads to false detection of cell state and degraded reliability. This work explores a strategy to store quantized KV cache in ReRAM to reduce memory area, while maintaining LLM performance. This study analyzes the error robustness of the three constituent components of the quantized KV cache. The proposal splits the value of each component into the upper bits and the lower bits, then stores the upper bits in SLC ReRAM and the lower bits in MLC ReRAM. This work achieves 49.1% fewer memory cells than the conventional method while maintaining the perplexity at a low level, regardless of LLMs and quantization methods.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Suzuki_KVCacheSLCMLC_JJAP.pdf", "analysed": true, "slm": true, "lm_models": ["unspecified LLMs"], "param_scale": "unspecified", "slm_note": "Stores quantized LLM KV cache in a mix of SLC and MLC ReRAM (upper bits SLC, lower bits MLC) to save area under RTN-induced errors; ReRAM is dense storage, not analog compute. Specific LLMs not verified (abstract-only).", "added": "2026-10 SLM search", "pdf": null, "priority": 8.0}, {"id": "W7162655367", "short": "NL-DPE", "title": "NL-DPE: An Analog In-memory Non-Linear Dot Product Engine for Efficient CNN and LLM Inference", "authors": ["Lei Zhao", "Luca Buonanno", "Archit Gajjar", "John Moon", "Aishwarya Natarajan", "Sergey Serebryakov", "Ron M. Roth", "Xia Sheng", "Youtao Zhang", "Paolo Faraboschi", "Jim Ignowski", "Giacomo Pedretti"], "year": 2026, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems, 2026", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2026.3698009", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["Transformer/BERT", "GPT/LLM", "CNN"], "evidence": "simulation", "tldr": "NL-DPE adds RRAM analog CAM to crossbars to run non-linear ops and attention in the analog domain without ADCs, giving 28x energy and 249x speedup over an H100 on BERT and about 100x for Llama-3.2-1B/3B.", "summary": "Conventional IMC handles only static VMMs, relying on ADCs and digital vector units for activations, softmax and QK/AV products. NL-DPE places an ACAM behind each crossbar column, turning functions and multiplications (via log/exp decomposition) into per-bit decision trees; 8-bit with Gray encoding. Noise-aware fine-tuning (NAF) trains crossbar weights and each decision tree independently with RRAM noise measured from a fabricated chip, with no post-deployment calibration. Simulated in CiMLoop at 32nm against H100 (TensorRT INT8), Eyeriss, ISAAC, RAELLA and BRAHMS. Larger LLaMA models are mapped across multiple chips to avoid RRAM rewriting.", "contributions": ["RRAM ACAM decision-tree engine for arbitrary non-linear functions and DMMul in analog", "ADC-free VMM readout", "Per-DT noise-aware fine-tuning using measured RRAM noise", "CiMLoop evaluation across CNNs, BERT and Llama-3.2"], "claims": [{"claim": "28x energy efficiency and 249x speedup over GPU; 22x and 245x over existing IMC accelerators", "support": "BERT multi-batch", "loc": "Abstract, Sec. VI-E, Fig. 11"}, {"claim": "ACAM replaces ADC+activation with ~98% lower power and 86x smaller area", "support": "Table IV", "loc": "Sec. VI-B"}, {"claim": "About 100x speedup/efficiency over GPU for Llama-3.2-1B/3B on 3/8 chips", "support": "Fig. 13(a), C2C 30 pJ/bit", "loc": "Sec. VI-F"}], "results": ["BERT-base GLUE accuracy after NAF near FP32 baseline (e.g. SST-2 92.43 vs ~92.4, MRPC 84.55 vs 84.55)", "BS=1: 112x faster, 28x more efficient than GPU", "Below 7 bits accuracy drops >50%; 8 bits matches full precision", "SAF tolerance: analog slicing up to ~20% in crossbar, only ~5% with ACAM faults", "C2C energy 18% (1B), 35% (3B)"], "limitations": ["Simulation only; ACAM from 16nm SPICE, no silicon", "LLM accuracy for Llama not reported (only BERT accuracy)", "ACAM is sensitive to stuck-at faults", "Multi-chip needed (8 chips for 3B); no KV-cache/autoregressive decode analysis in the text read", "Baselines modified by authors (FlexSFU), GPU comparison INT8"], "remarks": "Among the stronger architecture proposals for fully analog attention, which matters for SLMs since it avoids reprogramming for dynamic matmuls. Speedups are large and depend on simulation assumptions; the Llama results lack accuracy validation, so the SLM claim is mostly efficiency, not quality.", "basis": "full-text", "pdf_source_url": "arXiv:2511.13950", "abstract": "Resistive Random Access Memory (RRAM) based in-memory computing (IMC) accelerators offer significant performance and energy advantages for deep neural networks (DNNs), but face three major limitations: (1) they support onlystaticdot-product operations and cannot accelerate arbitrary non-linear functions or data-dependent multiplications essential to modern LLMs; (2) they demand large, power-hungry analog-to-digital converter (ADC) circuits; and (3) mapping model weights to device conductance introduces errors from cell nonidealities. These challenges hinder scalable and accurate IMC acceleration as models grow. We propose NL-DPE, a Non-Linear Dot Product Engine that overcomes these barriers. NL-DPE augments crosspoint arrays with RRAM-based Analog Content Addressable Memory (ACAM) to execute arbitrary non-linear functions and data-dependent matrix multiplications in the analog domain by transforming them into decision trees, fully eliminating ADCs. To address device noise, NL-DPE uses software-based Noise Aware Fine-tuning (NAF), requiring no in-device calibration. Experiments show that NL-DPE delivers 28× energy efficiency and 249× speedup over a GPU baseline, and 22× energy efficiency and 245× speedup over existing IMC accelerators, while maintaining high accuracy.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Zhao_NLDPE_TCAD.pdf", "analysed": true, "slm": true, "lm_models": ["BERT-tiny", "BERT-base", "Llama-3.2-1B", "Llama-3.2-3B"], "param_scale": "4M-3B", "slm_note": "RRAM crossbars for VMM plus RRAM analog CAM (decision-tree) units for non-linear functions, softmax and data-dependent matmul, removing ADCs; evaluated on BERT-tiny/base (GLUE) and Llama-3.2-1B/3B scalability (3 and 8 chips) via CiMLoop simulation. Genuinely analog in-memory compute including attention.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2026_Zhao_NLDPE_TCAD.pdf", "priority": 8.0}, {"id": "W7163529284", "short": "HINT", "title": "HINT: A Hybrid SRAM–MRAM Compute-In-Memory with INput-aware Skipping SAR-ADC for Energy Efficient Ternary LLMs", "authors": ["Jaebeom Park", "Seung-Eon Hwang", "Jongsun Park"], "year": 2026, "venue": "", "venue_short": "DATE", "venue_full": "2026 Design, Automation & Test in Europe Conference (DATE)", "venue_ok": true, "doi": "https://doi.org/10.23919/date69613.2026.11539338", "cites_global": 0, "cat": "11", "seed": false, "devices": ["MRAM", "SRAM"], "models": ["GPT/LLM"], "evidence": "simulation", "tldr": "Hybrid SRAM-MRAM ternary bitcell and sparsity-skipping SAR-ADC give 1.85x bitcell density and up to 2.67x energy efficiency on BitNet b1.58 700M.", "summary": "Targets ternary LLM CIM, where existing ternary bitcells are low-density and cut-off ADCs hurt accuracy. HINT uses a hybrid ternary bitcell combining SRAM reliability and MRAM density, plus an input-aware SAR-ADC that skips conversion cycles using input sparsity. On BitNet b1.58 700M it improves density 1.85x and energy efficiency up to 2.67x over SRAM/eDRAM CIM, skipping up to 21% of cycles for 1.27x ADC efficiency without accuracy loss. Abstract-only.", "contributions": ["Hybrid SRAM-MRAM ternary bitcell", "Input-aware skipping SAR-ADC"], "claims": [], "results": ["1.85x bitcell density", "up to 2.67x energy efficiency vs SRAM/eDRAM CIM", "up to 21% ADC cycles skipped, 1.27x ADC efficiency"], "limitations": ["Circuit simulation likely; abstract-only", "Baselines are volatile CIMs, not NVM"], "remarks": "Directly on target for ternary SLMs on MRAM-assisted CIM. The ADC skipping idea is generic. Needs full text to verify accuracy and device modeling.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Although large language models (LLMs) show remarkable performance in natural language processing tasks, their deployment on resource-constrained devices remains challenging due to a substantial memory footprint and high-energy consumption. To address these challenges, low-bit and ternary quantization reduce the model size, while hardware approaches such as compute-in-memory (CIM) alleviate the overhead of external memory accesses. However, billions of parameters of LLMs still cause significant data movement, and existing ternary CIM suffers from a low-density bitcell as well as accuracy degradation due to cut-off analog-to-digital converters (ADCs). In this paper, we propose HINT, a CIM architecture incorporating two energy efficient techniques. First, hybrid ternary bitcell leverages the reliability of SRAM and the high-density of MRAM, reducing area and energy overhead. Second, input-aware skipping SAR-ADC exploits input sparsity to skip unnecessary conversion cycles without sacrificing accuracy. On BitNet b1.58 (700M), compared to SRAM-based and eDRAM-based CIM baselines, HINT improves bitcell density by 1.85× and achieves up to 2.67× higher energy efficiency, respectively. By skipping up to 21% of conversion cycles, the proposed ADC improves energy efficiency up to 1.27× while maintaining model accuracy.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Park_HINT_DATE.pdf", "analysed": true, "slm": true, "lm_models": ["BitNet b1.58 700M"], "param_scale": "700M", "slm_note": "Hybrid SRAM-MRAM ternary CIM with input-aware skipping SAR-ADC, evaluated on BitNet b1.58 700M (ternary SLM). Analog MAC with ADC readout; MRAM provides density.", "added": "2026-10 SLM search", "pdf": null, "priority": 8.0}, {"id": "W7165129018", "short": "HATFI", "title": "HAT-FI: Hardware-Aware Training for Fault-Tolerant LLM Inference on RRAM-Based Compute-in-Memory", "authors": ["Pragya Sharma", "Soyed Tuhin Ahmed", "Farshad Firouzi", "Krishnendu Chakrabarty"], "year": 2026, "venue": "Proceedings - IEEE VLSI Test Symposium/Proceedings of the ... IEEE VLSI Test Symposium", "venue_short": "VTS", "venue_full": "IEEE VLSI Test Symposium (VTS), 2026", "venue_ok": true, "doi": "https://doi.org/10.1109/vts69484.2026.11563304", "cites_global": 0, "cat": "11", "seed": false, "devices": ["RRAM"], "models": ["GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "Hardware-aware training to make LLM inference on RRAM compute-in-memory tolerant to faults (title only; no abstract available).", "summary": "No abstract or full text was available. From the title, the work proposes a hardware-aware training method (HAT-FI, likely with fault injection) for fault-tolerant LLM inference on RRAM-based CIM. It cites noise-injection adaptation, accuracy studies of analog inference and HaLoRA for hybrid CIM, suggesting an HWA-training lineage. No numbers can be stated.", "contributions": ["Hardware-aware training for fault tolerance (inferred from title)"], "claims": [], "results": [], "limitations": ["Analysis based on title and reference list only"], "remarks": "Likely relevant to reliability of LLMs on RRAM, but cannot be assessed without the text. Fetch from IEEE Xplore manually.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Sharma_HatFi_VTS.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "unspecified", "slm_note": "Title indicates hardware-aware training for fault-tolerant LLM inference on RRAM CIM; no abstract available, so models, scale and fault models are unknown. Fault-tolerance on RRAM analog CIM (06 reliability theme).", "added": "2026-10 SLM search", "pdf": null, "priority": 8.0}, {"id": "W7165182181", "short": "AnalogLLMCoDesign", "title": "Towards Energy-Efficient LLM Inferencing on Analog Devices via Algorithm-Hardware Co-Design", "authors": ["Guojing Cong", "Ashish Gautam", "Shruti Kulkarni", "Seung–Hwan Lim"], "year": 2026, "venue": "", "venue_short": "IGSC", "venue_full": "Proceedings of the 16th ACM International Green and Sustainable Computing Conference (IGSC 2026)", "venue_ok": true, "doi": "https://doi.org/10.1145/3797248.3816058", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["GPT/LLM"], "evidence": "simulation", "tldr": "Simulation-guided algorithm-hardware co-design exploring Transformer inference on RRAM analog IMC with reduced-complexity attention.", "summary": "Motivates the energy problems of LLM inference (self-attention cost, billion-parameter weight bandwidth). Presents a simulation study of mapping Transformer inference onto RRAM crossbars while lowering algorithmic complexity via novel efficient attention mechanisms. Abstract is truncated and gives no numbers.", "contributions": ["Mapping of Transformer inference to RRAM crossbar IMC", "Efficient attention mechanisms"], "claims": [], "results": [], "limitations": ["Abstract-only, no quantitative results available"], "remarks": "Relevant topic but nothing verifiable beyond intent; check full text for models and device-noise treatment.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Large language model (LLM) inferencing poses severe energy challenges: the compute intensity and memory consumption of standard self-attention, and the bandwidth demands of billion-parameter weight matrices make GPU-only deployment increasingly hard to sustain at scale. We present a simulation-guided algorithm–hardware co-design study that explores how Transformer inference can be mapped onto analog in-memory computing (IMC) devices, specifically resistive RAM (RRAM) crossbar arrays, while reducing algorithmic complexity through novel efficient attention mechanisms.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Cong_AnalogLLMCoDesign_IGSC.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "unspecified", "slm_note": "Simulation-guided study mapping Transformer inference onto RRAM crossbar analog IMC with efficient attention variants; model identities and scale not given in abstract.", "added": "2026-10 SLM search", "pdf": null, "priority": 8.0}, {"id": "W7166819412", "short": "AttentionUnderAttack", "title": "Attention Under Attack: Analog Noise Effects and Mechanistic Vulnerabilities in Transformer Models", "authors": ["Mafizur Rahman", "Lijun Qian"], "year": 2026, "venue": "Annual Meeting of the Association for Computational Linguistics (ACL)", "venue_short": "ACL", "venue_full": "Annual Meeting of the Association for Computational Linguistics (ACL, short papers), 2026", "venue_ok": true, "doi": "https://doi.org/10.18653/v1/2026.acl-short.21", "cites_global": 0, "cat": "11", "seed": false, "devices": ["PCM"], "models": ["BERT", "GPT/LLM"], "evidence": "simulation", "tldr": "AIHWKIT study showing Q/K/V projections are the most noise-sensitive components and that noise scatters attention in higher layers, with 1-3 point drops on classification and larger on SQuAD.", "summary": "The paper evaluates pretrained transformers under AIHWKIT analog noise (tile 256, weight modifier std 0.05, read noise 0.0175, output noise 0.04, PCM drift with compensation), with no retraining and 3 seeds. Encoders lose 1-3 points on MNLI/SST-2 and 3-6 on SQuAD. Submodule isolation shows Q, K, V projections dominate failure while FFNs are robust. Head-level KL divergence and entropy shifts show depth-dependent attention scattering. Decoder LLMs (Phi-3-mini, Llama-3.2-1B) lose ~2-3% on ARC-Easy at medium noise and up to ~7% at high noise.", "contributions": ["First fine-grained analog vulnerability analysis of pretrained NLP transformers", "Submodule-level noise isolation", "Head/layer attention analysis via KL and entropy", "Extension to Phi-3-mini and Llama-3.2-1B"], "claims": [{"claim": "Q/K/V projections are most vulnerable, FFN comparatively robust", "support": "isolated-noise drops", "loc": "RQ2, Fig. 2"}, {"claim": "Decoder LLMs lose ~2-3% under medium noise, up to ~7% under high noise", "support": "Table 2", "loc": "Table 2"}], "results": ["Encoder drops 1-3 points MNLI/SST-2; 3-6 points SQuAD", "ARC-Easy: ~-2.6 (medium), ~-7 (high) for Phi-3 and Llama-3.2-1B"], "limitations": ["Simulation only, single fixed noise config", "Only linear layers analog; attention matmuls (QK^T, AV) stay digital", "Short paper, small LLM experiment, no mitigation proposed"], "remarks": "Useful, cheap diagnostic of where to protect (Q/K/V) when mapping SLMs to PCM-like hardware. Evidence is limited to simulation and ARC-Easy for LLMs; the decoder results are thin. Mitigation (noise-aware training, selective digital fallback) is left open.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog in-memory computing (AIMC) offers substantial efficiency gains for transformer inference but introduces hardware-induced noise that can distort attention behavior.Prior studies primarily focus on AIMC evaluations for vision tasks and CNN-based models.They largely overlook how hardware-induced noise perturbs internal attention dynamics in NLP models.In this work, we present the first fine-grained analysis of analog vulnerability in pretrained transformers, examining projection submodules, attention heads, and layerwise dynamics across multiple NLP tasks.Results show that query (Q), key (K), and value (V) projections are the most sensitive components, while feed-forward layers remain comparatively robust.Also, analog noise yields depth-dependent degradation in higher layers, leading to scattered attention and disrupted token routing.This pre-deployment analysis mitigates potential resource misuse before physical deployment and offers practical guidance for designing noise-resilient analog NLP transformers.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Rahman_AttentionUnderAttack_ACL.pdf", "analysed": true, "slm": true, "lm_models": ["BERT-base", "DistilBERT", "ALBERT", "RoBERTa-base", "DeBERTa-large", "Phi-3-mini", "Llama-3.2-1B"], "param_scale": "66M-1B+", "slm_note": "AIHWKIT (PCM-calibrated) simulation of analog noise on BERT-base, DistilBERT, ALBERT, RoBERTa, DeBERTa-large, plus Phi-3-mini and Llama-3.2-1B (8-bit) on ARC-Easy. Analog MVM in crossbars, linear layers only.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2026_Rahman_AttentionUnderAttack_ACL.pdf", "priority": 8.0}, {"id": "W7203694387", "short": "RSLPU", "title": "RS-LPU: A ReRAM-on-Logic Stacked Large Language Model Accelerator With Software–Hardware Co-Designed Weight Compression and Speculative Decoding", "authors": ["Pingcheng Dong", "Yonghao Tan", "Xuejiao Liu", "Peng Luo", "Yu Liu", "Di Pang", "Fengshi Tian", "Songchen Ma", "Xijie Huang", "Shih-Yang Liu", "Dong liang Zhang", "Zhichao Lu", "Luhong Liang", "Chi-Ying Tsui", "Fengbin Tu", "Liang Zhao", "Kwang-Ting Tim Cheng"], "year": 2026, "venue": "IEEE Journal of Solid-State Circuits", "venue_short": "JSSC", "venue_full": "IEEE Journal of Solid-State Circuits, 2026", "venue_ok": true, "doi": "https://doi.org/10.1109/jssc.2026.3718555", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM (stacked)"], "models": ["GPT/LLM"], "evidence": "measured-silicon", "tldr": "Journal extension of the ReRAM-on-logic stacked LLM accelerator with co-designed weight compression and speculative decoding (title only; details inferred from the ISSCC version).", "summary": "No abstract or full text was available. The title and authorship match the ISSCC 2026 chip (W7133301734), so this is presumably its extended journal version covering software-hardware co-designed weight compression and speculative decoding on ReRAM-on-logic stacking. No new numbers can be asserted.", "contributions": ["Extended description of RS-LPU (inferred from title)"], "claims": [], "results": [], "limitations": ["Analysis based on title only"], "remarks": "Treat together with the ISSCC paper; read the JSSC text for extra ablations and ReRAM details.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Dong_RsLpu_JSSC.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "unspecified (likely draft SLM + 7-8B target as in ISSCC version)", "slm_note": "Journal version of the ISSCC 2026 31.1 work (same authors, ReRAM-on-logic stacked LLM accelerator with weight compression and speculative decoding). No abstract or text available; by analogy the ReRAM stores compressed draft-LM weights while compute is digital. Not analog MVM.", "added": "2026-10 SLM search", "pdf": null, "priority": 8.6}, {"id": "W7212031114", "short": "InterfaceKVQ", "title": "Interface-Aware KV Cache Quantization for Dense On-Chip NVM in Long-Context LLM Decoding", "authors": ["Jiahao Zheng", "Yifan Qin", "Xiaobo Sharon Hu", "Yiyu Shi"], "year": 2026, "venue": "arXiv (Cornell University)", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2026), accepted; arXiv 2609.05764", "venue_ok": true, "doi": "https://doi.org/10.48550/arxiv.2609.05764", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "A rotation plus shared-codebook 4-bit KV quantization matched to NVM converter interfaces gives 3.1-3.6x lower KV read energy and 8x lower metadata than KIVI/KVQuant, at some accuracy cost.", "summary": "KIVI (about 25% group metadata) and KVQuant (sparse fp outliers) suit GPU memory but are costly in dense NVM behind fixed-range converters. The authors apply a fixed randomized rotation (static write-once crossbar) and per-vector normalization so each coordinate has the same range, allowing one fixed codebook for keys and one for values, programmed as read-converter reference levels. Dequantization is a 16-entry lookup and a norm multiply; metadata is one scalar (~3%). Evaluated with injected storage and crossbar noise up to 3-5% of full scale, NeuroSim-based 22nm analytic cost model.", "contributions": ["Interface-aware KV quantization with shared codebooks", "Rotation on a static analog crossbar, codebook thresholds as ADC references", "Noise robustness to ~3% full-scale storage noise", "Energy/area/metadata comparison vs KIVI and KVQuant on the same NVM"], "claims": [{"claim": "3.1-3.6x lower KV read energy than KIVI/KVQuant on the same NVM; 8x lower metadata than KIVI", "support": "Table 3", "loc": "Sec. 4.3"}, {"claim": "4-bit KV accuracy stable up to 3% FS storage noise", "support": "Fig. 3", "loc": "Sec. 4.4"}, {"claim": "Software accuracy below KIVI/KVQuant", "support": "MV retrieval 80.4/98.1/94.9 vs KIVI 89.0/100/98.5", "loc": "Sec. 4.2, Table 2"}], "results": ["At 8k context on 3B: KV 939 MB to 242 MB (3.88x), area 140 to 62 mm2, read energy 0.16 to 0.041 mJ/step", "Rotation crossbar noise 2% conductance, 6-bit DAC, 2% accumulation tracks ideal", "Effective bits 4.1 vs KIVI 5.0"], "limitations": ["Accuracy gap to KIVI/KVQuant", "Analytic mapping-cost model, not full-system", "Write-side normalization hardware abstracted", "Compute still digital attention; NVM write endurance for per-token KV writes not deeply addressed", "Simulation only"], "remarks": "Honest framing (no accuracy claim) and a concrete NVM co-design view of the KV cache. Important for SLM/long-context on NVM, though analog compute is minimal; arXiv ID in metadata looks unusual, so check the venue status.", "basis": "full-text", "pdf_source_url": "", "abstract": "The key-value (KV) cache is the dominant memory bottleneck in long-context large language model (LLM) decoding: every step reads it entirely, so decoding is memory-bandwidth bound. Holding a quantized KV cache in dense on-chip non-volatile memory (NVM) removes the off-chip transfer. Existing KV quantization methods, however, were designed for GPU-style memory systems: KIVI attaches per-group metadata, adding about 25% to the stored KV cache; KVQuant keeps sparse full-precision outliers that a dense array cannot hold in place. This paper examines what these structures cost when the KV cache resides in NVM behind fixed-range converters, and designs a quantization scheme matched to that interface. The architecture stores the quantized KV cache in dense on-chip NVM, uses a small static analog crossbar only for the fixed rotation, and keeps attention in on-chip digital logic. A randomized rotation and per-vector normalization give every coordinate the same range, so one fixed codebook for keys and one for values, each shared across all tokens of the corresponding tensor type, serve the entire KV cache. The codebook thresholds are programmed once as the read converter's reference levels, enabling fixed-range digitization with no per-token converter reconfiguration. Dequantization is a sixteen-entry lookup and one norm multiply; the only per-vector metadata is one scalar, about 3%. Across models from 3B to 14B and contexts to 32k tokens, the four-bit KV cache maintains accuracy under storage and crossbar noise simulated at realistic device levels. KIVI and KVQuant remain more accurate in software; the advantage of our format lies at the memory interface: 3.1-3.6x lower KV read energy than both mapped to the same NVM, and 8x lower metadata overhead than KIVI. The contribution is a KV quantization co-designed with the NVM memory interface rather than a new accuracy record.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2026_Zheng_InterfaceKVQ_ICCAD.pdf", "analysed": true, "slm": true, "lm_models": ["Llama-3.2-3B", "Llama-3.1-8B", "Qwen2.5-14B"], "param_scale": "3B-14B", "slm_note": "4-bit KV cache for Llama-3.2-3B, Llama-3.1-8B, Qwen2.5-14B stored in dense on-chip NVM (RRAM-class); one small static analog crossbar does a fixed random rotation; attention stays digital. NVM is mainly storage with noisy reads; analog compute is only the rotation.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2026_Zheng_InterfaceKVQ_ICCAD.pdf", "priority": 8.0}, {"id": "W4414659772", "short": "ALBERT on 14nm Analog AI Chip", "title": "Demonstration of transformer-based ALBERT model on a 14nm analog AI inference chip", "authors": ["An Chen", "Stefano Ambrogio", "Pritish Narayanan", "Atsuya Okazaki", "Charles Mackin", "Andrea Fasoli", "Malte J. Rasch", "Alexander M. Friz", "Jose Luquin", "Takeo Yasuda", "Masatoshi Ishii", "Takuto Kanamori", "Kohji Hosokawa", "Timothy Philicelli", "Seiji Munetoh", "Vijay Narayanan", "Hsinyu Tsai", "Geoffrey W. Burr"], "year": 2025, "venue": "Nature Communications", "venue_short": "NatCommun", "venue_full": "Nature Communications 16:8661 (2025)", "venue_ok": true, "doi": "https://doi.org/10.1038/s41467-025-63794-4", "cites_global": 6, "cat": "11", "seed": true, "devices": ["PCM"], "models": ["ALBERT", "Transformer"], "evidence": "measured-silicon", "tldr": "Maps all 7.1M unique weights of ALBERT-base (shared across 12 layers) onto IBM's 14nm 34-tile PCM analog inference chip and reaches GLUE accuracy only 1.8% (average over 7 tasks) below floating point, with HWA fine-tuning worth +4.4% and recalibration limiting 30-day drift loss to <1%.", "summary": "The paper tests whether a meaningfully large Transformer can run on fully weight-stationary analog CIM hardware. Because ALBERT shares weights across its 12 encoder layers, the four FC layer-blocks of one layer (inProj/QKV, outProj, FC1, FC2; >99% of weights) are mapped onto the 34 tiles (512x512 weights per tile, 4 PCM devices per weight) of the 14nm PCM chip with a 2D duration-format mesh, and the chip is iterated 12 times with layer outputs fed back as inputs. Attention (QK^T, softmax-V), LayerNorm, GELU, pooler and classifier run in software on a host; each of the 12 uses of a tile has its own column-wise scale/offset calibration. Weights are HWA fine-tuned per GLUE task with a PCM noise model scaled 0-3x, then closed-loop programmed into 28.3M PCM devices (79.4% of chip weight capacity). Measured on seven GLUE tasks, average hardware accuracy is 1.79% below FP (MRPC and QNLI at iso-accuracy, RTE/CoLA worst at 95.5%/96.7% of FP); a 30-day MRPC drift study and an energy model (measured analog + simulated 14nm digital) estimate >3 TOPS/W system efficiency for the non-pipelined dataflow.", "contributions": ["First analog-hardware demonstration of a meaningfully large Transformer (ALBERT-base, 7.1M unique / ~85M effective weights) with fully weight-stationary PCM tiles.", "Multi-tile mapping of inProj/outProj/FC1/FC2 onto fixed 512x512 tiles with shared tiles and crossing-free 2D-mesh routing between 6 input and 6 output landing pads.", "Hardware evidence that HWA fine-tuning with an optimal noise scale (~1.0-2.0x PCM noise) is essential for Transformers (+4.4% average GLUE accuracy).", "30-day PCM drift study showing column-wise recalibration (drift compensation) keeps accuracy loss <1%.", "Analysis of task-dependent robustness (error margin vs MAC error), layer-wise accuracy build-up for early exit, and tile-to-tile summation as a dominant MAC-noise source."], "claims": [{"claim": "ALBERT on the analog PCM chip achieves near iso-accuracy on GLUE.", "support": "Average HW accuracy over 7 GLUE tasks is 1.79% below FP (0.5% SW clipping/HWA loss + 1.29% HW imperfections); MRPC and QNLI exceed 99% of FP.", "loc": "Fig. 3a,b; Results 'Accuracy of the ALBERT model in hardware'"}, {"claim": "Hardware-aware fine-tuning substantially improves on-chip Transformer accuracy, with an optimal noise scale.", "support": "HWA-tuned weights improve average hardware GLUE accuracy by 4.4% vs zero-noise weights; optimum noise scale typically 1.0-2.0.", "loc": "Fig. 4a,b"}, {"claim": "Recalibration compensates PCM conductance drift.", "support": "Without recalibration MRPC accuracy degrades ~5% over 30 days; with recalibration the decrease is <1%.", "loc": "Fig. 4c,d"}, {"claim": "Tile-to-tile partial-sum summation (with 7-bit OLP quantization) is a major source of MAC variation.", "support": "FC2 (3072x768, summed across six tiles) shows the highest normalized read-to-read MAC variation; FC1 (analog summation within tile pairs) the lowest.", "loc": "Fig. 4e; Fig. 2h"}, {"claim": "4-bit effective weight precision suffices for almost all GLUE tasks.", "support": "Quantization sweep 6-bit to 2-bit; 3-bit causes degradation, QNLI robust even at 2 bits, RTE most sensitive.", "loc": "Fig. 1e"}, {"claim": "Most accuracy is reached before the final layer, enabling early exit.", "support": "Average accuracy after layer 11 is only 0.4% below the layer-12 accuracy.", "loc": "Fig. 3f,g"}], "results": ["7.1M unique ALBERT weights programmed into 28.3M PCM devices on a single 34-tile 14nm chip; 79.4% of weight capacity used", "Average GLUE (7 tasks) hardware accuracy 1.8% below FP reference; MRPC and QNLI at iso-accuracy (>99% of FP)", "HWA fine-tuning: +4.4% average hardware accuracy vs zero-noise fine-tuning", "PCM drift: ~5% accuracy loss over 30 days without recalibration vs <1% with recalibration (MRPC)", "Analog ops are >99% (short sequences) / ~98% (longer) of operations and >95% of energy; all 7 GLUE tasks >3 TOPS/W system-level (estimated), vs 6-7 TOPS/W for the earlier RNNT demo on the same chip"], "limitations": ["Not end-to-end: attention matmuls, softmax, LayerNorm, GELU, pooler and classifier run in software on a host computer.", "Relies on ALBERT weight sharing to fit on one chip; a non-shared BERT/LLM would need many chips or reprogramming.", "Non-pipelined dataflow limited by 6 ILP/6 OLP landing pads; throughput/energy figures are estimates combining measurements with simulated 14nm digital compute.", "Per-layer, per-column calibration requires calibration data/ground truth and on-chip digital arithmetic; drift tested only 30 days at room temperature.", "Large GLUE tasks evaluated on 1000-sample subsets chosen to match full-dataset FP accuracy; short sequences (<=128 tokens)."], "remarks": "This is the strongest measured-silicon evidence to date that encoder Transformers can run on fully weight-stationary analog PCM tiles at near-FP accuracy, and it validates in hardware the HWA-training and drift-compensation recipes previously shown only in simulation (Rasch et al. 2023, AIHWKit). However, the 'Transformer on analog' claim covers only the static-weight FC projections; the dynamic attention products, which do not suit NVM crossbars, are entirely off-chip, and the energy result (~3 TOPS/W) is modest because tiles are only ~3-4x more efficient than 14nm digital. For mapping research, the key lessons are that partial-sum splitting across tiles adds measurable noise and that per-reuse calibration is needed when a crossbar is time-multiplexed across layers.", "basis": "full-text", "pdf_source_url": "", "abstract": "A Lite Bidirectional Encoder Representations from Transformers model is demonstrated on an analog inference chip fabricated at 14nm node with phase change memory. The 7.1 million unique analog weights shared across 12 layers are mapped to a single chip, accurately programmed into the conductance of 28.3 million devices, for this first analog hardware demonstration of a meaningfully large Transformer model. The implemented model achieved near iso-accuracy on the General Language Understanding Evaluation benchmark of seven tasks, despite the presence of weight-programming errors, hardware imperfections, readout noise, and error propagation. The average hardware accuracy was only 1.8% below that of the floating-point reference, with several tasks at full iso-accuracy. Careful fine-tuning of model weights using hardware-aware techniques contributes an average hardware accuracy improvement of 4.4%. Accuracy loss due to conductance drift – measured to be roughly 5% over 30 days – was reduced to less than 1% with a recalibration-based “drift compensation” technique. The authors report the implementation of a Transformer-based model on the same architecture used in Large Language Models in a 14nm analog AI accelerator with 35 million Phase Change Memory devices, which achieves near iso-accuracy despite hardware imperfections and noise.", "review": [{"fid": "F1", "text": "Transformers now run on real analog PCM silicon at near-iso-accuracy: ALBERT-base on a single 14 nm PCM chip across 28.3M devices, averaging only 1.8% below the floating-point reference on 7 GLUE tasks, with several tasks at full iso-accuracy.", "grade": "High confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Nature Communications 2025 · corroborated on PubMed 41027896, PMC12485056"}, {"fid": "F3", "text": "Measured on-chip accuracy is close to software but not free, and the penalty grows with model scale — from full software-equivalence on keyword spotting, to <1 pp on ResNet-9, to 1.8 pp on ALBERT/GLUE, to a missed equivalence threshold on a 45M-weight RNN-T.", "grade": "High confidence", "vote": "3–0 on NeuRRAM · 2–1 on HERMES and RNN-T", "note": "Dissents addressed interpretive framing, not the numbers. Caveat: NeuRRAM's “comparable to software” baseline is itself 4-bit quantized."}, {"fid": "F4", "text": "Hardware-aware training — injecting realistic device noise during training or fine-tuning — is the field's dominant and empirically validated mitigation, and it now scales to pre-trained LLMs. On under 1% of pre-training tokens, Phi-3-mini-4k-instruct and Llama-3.2-1B-Instruct retained accuracy comparable to 4-bit-weight / 8-bit-activation quantized baselines under hardware-realistic analog noise — a gap off-the-shelf LLMs cannot close on their own.", "grade": "High confidence", "vote": "3–0 on the LLM result and the 4.4% ALBERT figure", "note": "Analog Foundation Models, NeurIPS 2025 (IBM Zurich / ETH) · ALBERT paper quantifies HWA's own contribution at 4.4% average recovery"}], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Chen_ALBERTOn14nmAnalogAIChip_NatCommun.pdf", "analysed": true, "slm": true, "lm_models": ["ALBERT-base"], "param_scale": "7.1M unique weights (ALBERT-base, shared across 12 layers)", "slm_note": "ALBERT-base (7.1M unique weights) run on a real 14nm PCM analog AI inference chip (34 tiles), with attention/LayerNorm etc. in digital; GLUE tasks.", "pdf": "11_Small_Language_Models_on_AIMC/2025_Chen_ALBERTOn14nmAnalogAIChip_NatCommun.pdf", "priority": 12.59}, {"id": "W4414064893", "short": "Gain-Cell Analog Attention", "title": "Analog in-memory computing attention mechanism for fast and energy-efficient large language models", "authors": ["Nathan Leroux", "Paul-Philipp Manea", "Chirag Sudarshan", "Jan Finkbeiner", "Sebastian Siegel", "John Paul Strachan", "Emre Neftci"], "year": 2025, "venue": "Nature Computational Science", "venue_short": "NatCompSci", "venue_full": "Nature Computational Science, vol. 5, pp. 813-824 (2025)", "venue_ok": true, "doi": "https://doi.org/10.1038/s43588-025-00854-1", "cites_global": 24, "cat": "11", "seed": true, "devices": ["Gain-cell", "Charge/Capacitor"], "models": ["GPT/LLM", "Transformer"], "evidence": "simulation", "tldr": "Stores the KV cache in capacitor-based gain-cell crossbars that also compute QK^T and phi(S)V in the analog domain (PWM inputs, charge-to-pulse HardSigmoid, no ADCs), and adapts pre-trained GPT-2 to these constraints, reaching GPT-2-level accuracy with up to ~100x lower attention latency and ~10^4-10^5x lower attention energy than GPUs.", "summary": "In autoregressive LLM decoding, attention must stream the growing KV cache from memory at every token. Writing the cache into NVM crossbars is too slow, energy-hungry and wear-prone, while SRAM is volatile and not dense. The authors propose gain cells (a capacitor plus read transistors, multi-level, fast and cheap to write, with non-destructive reads) as crossbar elements that both store K and V and compute the two attention dot products. Queries enter as PWM pulses, the first array's bitline currents are integrated by charge-to-pulse circuits that implement a HardSigmoid (replacing softmax) and drive the second array directly, and pulse counters digitise the output, so the datapath has no ADCs. Sliding-window attention (M=1024) bounds the array size, and 16 sub-tiles of 64x64 arrays form one head. Because the hardware (HardSigmoid, sliding window, 4/3/5-bit quantization, 3rd-order nonlinear cell, 5 ms capacitor leakage) diverges from standard attention, the authors fine-tune a linear intermediate model and then use a statistics-matching scaling algorithm to map it to the nonlinear cell model; the result matches GPT-2 on standard benchmarks and also scales to GPT-2-XL.", "contributions": ["Gain-cell crossbar arrays that store the KV cache and perform both attention dot products in analog, written once per token in a sliding-window fashion", "Fully analog attention datapath using PWM inputs and charge-to-pulse HardSigmoid/signed integrators with pulse counters instead of ADCs", "Placed-and-routed multi-tile floorplan with energy/latency/area estimates for a full attention head", "Hardware-aware adaptation pipeline (linear intermediate model, then a scaling-factor adaptation algorithm, then nonlinear fine-tuning) that maps pre-trained GPT-2 to non-ideal gain-cell hardware without training from scratch"], "claims": [{"claim": "The adaptation algorithm makes a non-ideal gain-cell model usable without full retraining.", "support": "perplexity of the nonlinear gain-cell model is \"reduced from 1,757 to 21 during this adaption stage\"; the linear intermediate model matches GPT-2 in <3,000 iterations vs >13,000 from scratch", "loc": "Fig. 4c,d"}, {"claim": "The hardware attention model reaches accuracy comparable to public GPT-2.", "support": "Average acc 41.80% / ppl 41.52 (nonlinear, adapted+fine-tuned) vs 43.02% / 36.26 (public GPT-2) and 41.46% / 43.82 (software trained from scratch)", "loc": "Table 1"}, {"claim": "The approach scales to a 1.5B-parameter model.", "support": "Nonlinear hardware GPT-2-XL averages 51.69% acc / 17.23 ppl vs 50.15% / 19.90 for software GPT-2-XL trained from scratch (public XL: 55.12% / 15.03)", "loc": "Table 1"}, {"claim": "Attention latency and energy fall by orders of magnitude versus GPUs.", "support": "speed-up x7,000 vs Jetson Nano, x300 vs RTX 4090, x100 vs H100; energy reduction x40,000, x90,000 and x70,000 respectively", "loc": "Results, Fig. 5c,d"}, {"claim": "Per-token attention cost per head is a few nJ at tens-of-ns latency.", "support": "65 ns attention latency; 1,120 pJ + 700 pJ for the two dot products, 4 nJ digital control, 330 pJ DACs, about 6.1 nJ per token per head", "loc": "Results, Fig. 5e"}], "results": ["Attention latency ~65 ns per token; ~6.1 nJ per token per head (digital control ~4 nJ dominates)", "Attention speed-up of 100x vs H100, 300x vs RTX 4090 and 7,000x vs Jetson Nano; energy 70,000x, 90,000x and 40,000x lower respectively", "GPT-2 (hardware, nonlinear, adapted + fine-tuned): avg acc 41.80% / ppl 41.52 vs public GPT-2 43.02% / 36.26", "One-head area of 0.5 mm^2 including digital control (16 sub-tiles of 2x64x64 6T gain-cell arrays, ~1 um^2 per cell); KV-cache crossbar area per GPT-2 head estimated at ~15.7e-3 mm^2 with denser cells", "Silicon-CMOS gain-cell retention time constant tau = 5 ms (modelled as exponential decay during training)"], "limitations": ["Only attention is accelerated; linear layers (most of the FLOPs and weights) remain off this hardware, so the end-to-end LLM benefit is not quantified", "Evidence comes from SPICE, layout and neural-network simulation; no fabricated chip or measured arrays", "Changes the model (HardSigmoid instead of softmax, sliding-window attention, d=64 heads) and needs fine-tuning, so off-the-shelf pre-trained models cannot be dropped in", "GPT-2 and GPT-2-XL only, and the XL hardware model trails the public checkpoint (51.69% vs 55.12% average acc)", "Retention/leakage (5 ms for Si gain cells) restricts operation; longer retention relies on OSFET (IGZO/ITO) gain cells that are still emerging", "The GPU comparison covers attention only, and the abstract (four orders of magnitude energy) and contributions list (five orders) disagree"], "remarks": "A high-profile, well-executed co-design that tackles the part of LLM inference crossbar NVMs handle badly: the dynamic, write-heavy KV cache. Charge-domain gain cells with ADC-free pulse chaining are a credible answer, and the adaptation algorithm is a reusable recipe for mapping pre-trained models onto non-ideal analog nonlinearities. The headline 10^4x energy figure compares an attention-only analog block with full GPUs, and the architecture swaps softmax for HardSigmoid and uses sliding windows, so it is a co-designed model, not a drop-in. It complements NVM-weight analog work (IBM PCM, HyFlexPIM), which leaves attention digital.", "basis": "full-text", "pdf_source_url": "", "abstract": "Transformer networks, driven by self-attention, are central to large language models. In generative transformers, self-attention uses cache memory to store token projections, avoiding recomputation at each time step. However, graphics processing unit (GPU)-stored projections must be loaded into static random-access memory for each new generation step, causing latency and energy bottlenecks. Here we present a custom self-attention in-memory computing architecture based on emerging charge-based memories called gain cells, which can be efficiently written to store new tokens during sequence generation and enable parallel analog dot-product computation required for self-attention. However, the analog gain-cell circuits introduce non-idealities and constraints preventing the direct mapping of pre-trained models. To circumvent this problem, we design an initialization algorithm achieving text-processing performance comparable to GPT-2 without training from scratch. Our architecture reduces attention latency and energy consumption by up to two and four orders of magnitude, respectively, compared with GPUs, marking a substantial step toward ultrafast, low-power generative transformers.", "review": [{"fid": "F13", "text": "Charge-based analog gain cells targeting attention's KV-cache dot products project ~100× speedup and ~70,000× energy reduction versus an H100 (~6.1 nJ and ~65 ns per token per attention head). Circuit non-idealities — third-order polynomial nonlinearity, charge leakage, 4-bit queries / 3-bit stored K,V, HardSigmoid replacing softmax — make direct mapping of pre-trained weights impossible, so a hardware-aware adaptation step is mandatory; the authors mapped GPT-2 weights through a nonlinear gain-cell model rather than training from scratch.", "grade": "Medium confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Graded medium: SPICE simulation of the attention mechanism alone, no fabricated chip, explicitly excluding linear projections and end-to-end energy. The paper itself notes that substantial overall energy reductions require optimizing all components."}], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Leroux_GainCellAnalogAttention_NatCompSci.pdf", "analysed": true, "slm": true, "lm_models": ["GPT-2", "GPT-2-XL"], "param_scale": "124M–1.5B (GPT-2 to GPT-2-XL)", "slm_note": "GPT-2 and GPT-2-XL (1.5B) adapted to a gain-cell analog in-memory attention design, evaluated by simulation/hardware modeling with energy/latency compared against digital GPUs; GPT-2 scale is SLM-range.", "pdf": "11_Small_Language_Models_on_AIMC/2025_Leroux_GainCellAnalogAttention_NatCompSci.pdf", "priority": 13.28}, {"id": "W4411486499", "short": "HyFlexPIM", "title": "Hybrid SLC-MLC RRAM Mixed-Signal Processing-in-Memory Architecture for Transformer Acceleration via Gradient Redistribution", "authors": ["Chang Eun Song", "Priyansh Bhatnagar", "Zihan Xia", "Nam Sung Kim", "Tajana Rosing", "Mingu Kang"], "year": 2025, "venue": "", "venue_short": "ISCA", "venue_full": "ACM/IEEE 52nd Annual International Symposium on Computer Architecture (ISCA 2025)", "venue_ok": true, "doi": "https://doi.org/10.1145/3695053.3731109", "cites_global": 4, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["Transformer", "BERT", "GPT/LLM", "ViT"], "evidence": "algorithm+simulation", "tldr": "HyFlexPIM is a mixed-signal RRAM PIM that maps static Transformer weights to reconfigurable SLC/2-bit-MLC analog crossbars (digital PIM for attention), and uses SVD-based 'gradient redistribution' fine-tuning so only 5-20% of weights need the robust SLC mode, giving up to 1.86x speedup and 1.24x linear-layer energy efficiency over ASADI with <1% accuracy loss on encoders.", "summary": "Analog RRAM PIM with multi-level cells is dense and efficient but the MLC non-idealities devastate Transformer accuracy (a 40% drop for BERT-Base on MRPC with all-2b-MLC). HyFlexPIM uses digital (bit-wise NOR) RRAM PIM for the dynamic, high-precision attention operations (QK^T, xV) and analog RRAM PIM for static linear layers, where each 64x128 array can be reconfigured between SLC and 2-bit MLC with a shared 6b/7b reconfigurable SAR ADC (<1% overhead). To make the SLC/MLC split effective, each weight matrix is decomposed with SVD, truncated, and fine-tuned so that a few singular components carry dominant gradients; components with the top-k% absolute gradients go to SLC and the rest to MLC. Accuracy is evaluated with Gaussian weight noise calibrated to a measured ~4.04% MLC RRAM bit error rate plus ADC quantization, and energy/latency via NVSim and 65 nm scaled models, on BERT-Base/Large, GPT-2, Llama-3.2-1B and ViT-Base. Against ASADI, SPRINT, a TransPIM-style NMP baseline and a non-PIM baseline, it reports 1.1-1.86x speedup over INT8 ASADI and 4.69-4.94x end-to-end energy efficiency vs SPRINT/NMP.", "contributions": ["Mixed-signal RRAM PIM: digital PIM for dynamic attention and analog PIM for static weight GEMVs, with each analog array switchable between SLC and 2-bit MLC", "Reconfigurable 6b/7b SAR ADC that bypasses the MSB capacitor for SLC mode, with <1% area/energy overhead", "Gradient redistribution: SVD + truncation + fine-tuning that concentrates loss sensitivity in 5-10% (encoder) / 5-20% (decoder) of weights, which are mapped to SLC", "Accuracy evaluation with noise calibrated to measured MLC RRAM BER, across BERT, GPT-2, Llama-3.2-1B and ViT", "Scalability analysis using tensor parallelism across processing units and pipeline parallelism across chips"], "claims": [{"claim": "Mapping a Transformer entirely onto 2-bit MLC RRAM causes catastrophic accuracy loss.", "support": "\"40% drop for BERT-Base with GLUE MRPC dataset\"", "loc": "Sec. 1"}, {"claim": "After gradient redistribution, protecting a small share of weights in SLC keeps accuracy within 1% of the INT8 baseline.", "support": "5% SLC rate keeps the drop below 1% on MRPC, QNLI and STS-B for BERT-Base; ViT-Base on CIFAR-10 needs only 5% SLC; GPT-2 and Llama3 at 20% SLC see <10% loss increase", "loc": "Sec. 6.1 / Fig. 12"}, {"claim": "Gradient-based selection of SVD components beats magnitude-based and rank-based selection for choosing what goes to SLC.", "support": "On MRPC and CoLA (BERT-Base) the gradient-based approach consistently outperforms both alternatives", "loc": "Sec. 6.2 / Fig. 13"}, {"claim": "2-bit MLC doubles throughput at the same energy compared with an SLC-only analog PIM.", "support": "1.1-1.86x speedup vs ASADI-INT8; ~1.9x area efficiency", "loc": "Sec. 6.3.1 / Fig. 16"}, {"claim": "Higher-level MLC (3-4 bit) is too unreliable for Transformers.", "support": "measured chips show a \"7x higher bit error rate than SLC\" for 3b/4b MLC, so 2b MLC is adopted", "loc": "Sec. 3.2"}], "results": ["Up to 1.24x linear-layer energy efficiency and 1.1-1.86x end-to-end speedup vs ASADI-dagger (INT8 ASADI) at 5% SLC; average 1.23x energy and 1.79x speedup at ~20% SLC", "Up to 1.67x (BERT-Large) and 1.44x (GPT-2) end-to-end energy efficiency vs ASADI at N=1024", "vs SPRINT: up to 5.4x lower linear-layer energy, 4.94x/4.69x end-to-end energy efficiency (GLUE/WikiText-2, N=128), and 10.6x/46x speedup", "vs NMP (TransPIM-style) baseline: up to 3.31x linear-layer energy efficiency; vs non-PIM baseline: up to 6.6x linear and 6.15x/5.82x end-to-end", "ADC accounts for 64.2% of analog-module area and 55% of its power (512 shared 6b/7b SAR ADCs)", "Llama3 on quad/octa chips: 1.96x/3.65x throughput over the dual-chip configuration"], "limitations": ["Simulation only: RRAM noise is a multiplicative Gaussian calibrated to one BER figure (4.04% after one day), with no IR drop, drift over longer horizons, or programming-variability modelling per layer", "Requires SVD truncation plus fine-tuning per model/task (not training-free), which is costly for large LLMs", "Decoder models still lose accuracy (<10% loss increase at 20% SLC), and only small LLMs (GPT-2, Llama-3.2-1B) are evaluated", "Baselines are re-implemented or scaled to 65 nm from reported numbers (ASADI, SPRINT, TransPIM), so comparisons depend on those assumptions", "Attention is done in digital RRAM PIM with frequent writes; the endurance argument (10^8 cycles) is a back-of-envelope estimate", "The abstract's energy number (1.45x) does not match the 1.24x given in the introduction and Sec. 6.3.1"], "remarks": "A solid ISCA-level co-design paper. Its main idea, reshaping the model with SVD so that the fraction of weights sensitive to analog error is small and explicit, is a useful complement to passive hardware-aware training and a clear example of importance-aware mapping onto heterogeneous crossbar precision. The evidence is simulated, with a simple noise model, so the 2b-MLC accuracy claims need validation on real arrays. Like ASADI and many PIM works, it gives up on analog attention and uses digital PIM for QK^T/SV. That contrasts with gain-cell analog attention (Leroux et al.) and VQ-based approaches (VQT-CiM).", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2506.00020", "abstract": "Transformers, while revolutionary, face challenges due to their demanding computational cost and large data movement.To address this, we propose HyFlexPIM, a novel mixed-signal processingin-memory (PIM) accelerator for inference that flexibly utilizes both single-level cell (SLC) and multi-level cell (MLC) RRAM technologies to trade-off accuracy and efficiency.HyFlexPIM achieves efficient dual-mode operation by utilizing digital PIM for highprecision and write-intensive operations while analog PIM for high parallel and low-precision computations.The analog PIM further distributes tasks between SLC and MLC PIM operations, where a single analog PIM module can be reconfigured to switch between two operations (SLC/MLC) with minimal overhead (<1% for area & energy).Critical weights are allocated to SLC RRAM for high accuracy, while less critical weights are assigned to MLC RRAM to maximize capacity, power, and latency efficiency.However, despite employing such a hybrid mechanism, brute-force mapping on hardware fails to deliver significant benefits due to the limited proportion of weights accelerated by the MLC and the noticeable degradation in accuracy.To maximize the potential of our hybrid hardware architecture, we propose an algorithm co-optimization technique, called gradient redistribution, which uses Singular Value Decomposition (SVD) to decompose and truncate matrices based on their importance, then fine-tune them to concentrate significance into a small subset of weights.By doing so, only 5-10% of the weights have dominantly large gradients, making it favorable for HyFlexPIM by minimizing the use of expensive SLC RRAM while maximizing the efficient MLC RRAM.Our evaluation shows that HyFlexPIM significantly enhances computational throughput and energy efficiency, achieving maximum 1.86× and 1.45× higher than state-of-the-art methods.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Song_HyFlexPIM_ISCA.pdf", "analysed": true, "slm": true, "lm_models": ["BERT-Base", "BERT-Large", "GPT-2 (small)", "Llama-3.2-1B", "ViT-Base"], "param_scale": "110M–1B (BERT-Base to Llama-3.2-1B)", "slm_note": "BERT-Base/Large, GPT-2 small, Llama-3.2-1B (and ViT-Base) evaluated with simulated hybrid SLC/MLC RRAM analog+digital PIM noise and 65 nm energy/latency models; all SLM-scale.", "pdf": "11_Small_Language_Models_on_AIMC/2025_Song_HyFlexPIM_ISCA.pdf", "priority": 8.49}, {"id": "W4410584352", "short": "NORA", "title": "NORA: Noise-Optimized Rescaling of LLMs on Analog Compute-in-Memory Accelerators", "authors": ["Y. Thomas Hou", "Hsinyu Tsai", "Kaoutar El Maghraoui", "Tayfun Gokmen", "Geoffrey W. Burr", "Liu Liu"], "year": 2025, "venue": "", "venue_short": "DATE", "venue_full": "Design, Automation and Test in Europe Conference (DATE 2025)", "venue_ok": true, "doi": "https://doi.org/10.23919/date64628.2025.10993217", "cites_global": 4, "cat": "11", "seed": false, "devices": ["PCM"], "models": ["GPT/LLM"], "evidence": "simulation", "tldr": "A sensitivity study finds LLMs are robust to analog weight noise but highly sensitive to quantization and additive Gaussian noise on analog CIM, and proposes NORA, a rescaling method that shifts the non-ideality burden to weights, cutting OPT-6.7B accuracy loss on simulated analog CIM from ~30% to under 1%.", "summary": "The paper studies how analog compute-in-memory (CIM) non-idealities affect Large Language Model (LLM) accuracy, a question the authors say is unexplored relative to the extensive prior work on CNNs/DNNs. Via a sensitivity analysis, they find LLMs tolerate weight-related analog noise reasonably well but are highly sensitive to quantization noise and additive Gaussian noise, which typically arise on the input/output (activation) side of analog MAC operations. Based on this asymmetry, they propose a noise-optimized rescaling method (NORA) that redistributes where the non-ideality burden falls -- shifting it from the noise-sensitive input/output path to the more noise-resilient weights. Implementing OPT-6.7B on simulated analog CIM hardware with NORA keeps accuracy loss under 1% relative to the floating-point baseline, versus about 30% loss without the rescaling.", "contributions": ["First (per the authors) systematic sensitivity analysis of analog CIM non-idealities (weight noise, quantization noise, additive Gaussian noise) specifically for LLMs rather than conventional DNNs", "Identifies an asymmetry: LLMs are robust to weight-related analog noise but highly sensitive to quantization and additive Gaussian noise", "Proposes NORA, a noise-optimized rescaling method that shifts the non-ideality burden from sensitive input/output signals to resilient weights", "Demonstrates OPT-6.7B on simulated analog CIM hardware with less than 1% accuracy loss using NORA, versus ~30% loss without rescaling"], "claims": [{"claim": "LLMs are robust to weight-related analog noise but highly sensitive to quantization noise and additive Gaussian noise", "support": "Stated finding of the sensitivity analysis in the abstract", "loc": "Abstract"}, {"claim": "NORA reduces OPT-6.7B accuracy loss on simulated analog CIM hardware to under 1% from the floating-point baseline, compared to ~30% without rescaling", "support": "Quantitative comparison given in the abstract (<1% vs ~30%)", "loc": "Abstract"}], "results": ["OPT-6.7B on simulated analog CIM: <1% accuracy loss vs. floating-point baseline with NORA rescaling, vs. ~30% accuracy loss without rescaling"], "limitations": ["Abstract-only analysis for this entry; full methodological details (noise models, exact analog CIM configuration, which layers are rescaled) not verified from the abstract alone", "Evaluation is simulation-based, not on fabricated analog hardware", "Demonstrated on a single model (OPT-6.7B); generality across other LLM families/sizes is not stated in the abstract"], "remarks": "Authored by IBM's analog AI team (Tsai, Gokmen, Burr, El Maghraoui), this fits a line of work extending IBM's PCM-based analog-AI hardware-aware training/inference tools (AIHWKit) to LLMs, specifically addressing that LLMs have different noise sensitivity profiles than CNNs. The claimed 30%-to-<1% accuracy-loss reduction is a large effect if it holds up under full-text scrutiny, and the weight-vs-activation noise asymmetry finding is a useful design principle for mapping LLMs onto analog crossbars (favor pushing non-ideality onto weights, which the array stores, rather than onto the signal path).", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Large Language Models (LLMs) have become critical in AI applications, yet current digital AI accelerators suffer from significant energy inefficiencies due to frequent data movement. Analog compute-in-memory (CIM) accelerators offer a potential solution for improving energy efficiency but introduce non-idealities that can degrade LLM accuracy. While analog CIM has been extensively studied for traditional deep neural networks, its impact on LLMs remains unexplored, particularly concerning the large influence of Analog CIM non-idealities. In this paper, we conduct a sensitivity analysis on the effects of analog-induced noise on LLM accuracy. We find that while LLMs demonstrate robustness to weight-related noise, they are highly sensitive to quantization noise and additive Gaussian noise. Based on these insights, we propose a noise-optimized rescaling method to mitigate LLM accuracy loss by shifting the non-ideality burden from the sensitive input/output to the more resilient weight. Through rescaling, we can implement the OPT-6.7b model on simulated analog CIM hardware with less than 1% accuracy loss from the floating-point baseline, compared to a much higher loss of around 30% without rescaling.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Hou_NORA_DATE.pdf", "analysed": true, "slm": true, "lm_models": ["OPT-6.7B"], "param_scale": "6.7B", "slm_note": "OPT-6.7B evaluated on simulated analog CIM hardware with noise-optimized rescaling (below 10B, SLM scale).", "pdf": null, "priority": 10.29}, {"id": "W4417092543", "short": "Analog Foundation Models", "title": "Analog Foundation Models", "authors": ["Julian Büchel", "Iason Chalas", "Giovanni Acampa", "An Chen", "Omobayode I. Fagbohungbe", "Hsinyu Tsai", "Kaoutar El Maghraoui", "Manuel Le Gallo", "Abbas Rahimi", "Abu Sebastian"], "year": 2025, "venue": "", "venue_short": "NeurIPS", "venue_full": "39th Conference on Neural Information Processing Systems (NeurIPS 2025)", "venue_ok": true, "doi": "https://doi.org/10.52202/085713-2044", "cites_global": 2, "cat": "11", "seed": true, "devices": ["PCM", "ReRAM"], "models": ["GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "Hardware-aware distillation training on 20B self-generated tokens makes Phi-3-mini-4k-instruct and Llama-3.2-1B-Instruct robust to PCM-chip programming noise plus static 8-bit input/output quantization, reaching accuracy similar to W4A8 quantized models (gap to FP16 cut to 3.81% / 4.58% from 8.01% / 9.81%).", "summary": "Off-the-shelf LLMs lose a lot of accuracy on analog in-memory computing (AIMC) hardware because of weight programming noise, static input (DAC) ranges and globally fixed output (ADC) ranges, and the original pre-training data is not available for retraining. The authors follow the LLM-QAT recipe: the teacher model generates synthetic data, and the student is distilled with hardware-aware training in AIHWKIT-Lightning. Training uses learnable static 8-bit input ranges, globally static 8-bit output quantization with a straight-through estimator, per-channel additive Gaussian weight noise (gamma 0.02-0.03), and iterative weight clipping to alpha·std. Linear layers with static weights are assumed to run on AIMC tiles, while attention, activations and the KV cache stay in digital FP16. They evaluate on 12 benchmarks with a programming-noise model taken from IBM's 64-core PCM chip, plus Gaussian, ReRAM, drift and read-noise models. The resulting 'analog foundation models' beat LLM-QAT and SpinQuant under noise, also quantize well to 4-bit RTN, and scale better with test-time compute.", "contributions": ["A scalable data-generation + distillation HWA-training pipeline for billion-parameter LLMs without access to pre-training data (20B synthetic tokens, <1% of pre-training)", "Analog versions of Phi-3-mini-4k-instruct (3.8B) and Llama-3.2-1B-Instruct robust to PCM-derived programming noise with static SI8/O8 quantization", "Ablations showing weight clipping matters more than noise injection for LLM robustness (via higher per-weight SNR), and that simple STE handles globally static ADC ranges", "Shows the same models quantize to 4-bit RTN better than LLM-QAT/SpinQuant with static inputs, and benefit from test-time compute scaling", "Broad evaluation including safety (XSTest) and instruction following (IFEval) under noise; open-source code"], "claims": [{"claim": "Off-the-shelf LLMs degrade substantially under hardware-realistic AIMC noise", "support": "average drop 8.01% (Phi-3) and 9.81% (Llama-3.2-1B); GSM8K drops 21.43% and 23.2%", "loc": "Sec. 4.1, Table 1"}, {"claim": "Analog foundation models close most of the gap even with static 8-bit input and global static 8-bit output quantization", "support": "gap to FP16 reduced to 3.81% (Phi-3) and 4.58% (Llama); avg 66.22 vs 70.03 FP16 for Phi-3 under hw noise", "loc": "Sec. 4.1, Table 1"}, {"claim": "QAT/PTQ-quantized models are less robust to analog noise than HWA-trained models", "support": "AFM beats LLM-QAT by up to 12.87% (Phi-3) / 8.16% (Llama) on hard tasks; SpinQuant SI8-W4 under hw noise collapses to 28.71 avg for Phi-3", "loc": "Sec. 4.1, Table 1, Fig. 3"}, {"claim": "Globally static 8-bit ADC output quantization costs little when trained with simple STE", "support": "0.2%-0.5% average accuracy loss, contrasting with >400 perplexity increase reported by Zhang et al. with simple QAT", "loc": "Sec. 3.1, App. C"}, {"claim": "Weight clipping gives more robustness than noise injection for LLMs because it raises average per-weight SNR on PCM", "support": "ablation results; combination performs best", "loc": "Sec. 3.1, App. C/D"}, {"claim": "The robustness generalizes to stronger/other noise", "support": "+7.05% vs LLM-QAT under ReRAM noise model; +15.92% / +20.62% vs LLM-QAT at 1.5x / 2.0x PCM programming noise", "loc": "Sec. 4.1, App. F"}], "results": ["Phi-3-mini-4k-instruct avg accuracy: FP16 70.03, off-the-shelf + hw noise 62.02, AFM + hw noise 66.22, LLM-QAT + hw noise 60.58, SpinQuant SI8-W4 + hw noise 28.71", "Llama-3.2-1B-Instruct avg: FP16 45.49, off-the-shelf + hw noise 35.68, AFM + hw noise 40.91, LLM-QAT + hw noise 37.92", "4-bit RTN of AFM (SI8-W4-O8): 66.64 avg (Phi-3) vs 65.63 LLM-QAT and 63.30 SpinQuant SI8; 41.88 (Llama) vs 40.24 and 27.35", "Per-tile weight rescaling (tiling) improves off-the-shelf/LLM-QAT noisy accuracy by 1.76% / 1.11% but not AFM; AFM still leads LLM-QAT by 4.43%", "Up to 4.74% better MATH-500 accuracy vs W4/SI8 models with test-time compute scaling", "Training cost: ~230 h (Phi-3) and ~90 h (Llama-1B) on 96 V100 GPUs with 20B tokens"], "limitations": ["Simulation only: noise is injected from a statistical PCM programming-noise model, not run on an AIMC chip", "Only static-weight linear layers are analog; attention and KV cache are FP16 digital, so the dynamic matmul problem is not addressed", "Considers mainly programming noise; drift/read noise, IR drop, ADC nonlinearity and real tile-size mapping effects are only partly covered (appendices)", "Costly: ~230 GPU-hours x 96 V100s per model; the HWA linear kernel is ~3x slower", "There is still a clear gap to FP16 on reasoning tasks (GSM8K, MATH-500); models are at most 3.8B parameters"], "remarks": "This is the most convincing evidence so far that HWA training scales from small CNN/BERT models to instruction-tuned LLMs. Its evaluation (12 benchmarks, 10 noise seeds, safety and test-time compute) is stronger than most AIMC-LLM papers. For crossbar mapping, the useful lessons are that globally fixed ADC ranges and static DAC ranges can be handled cheaply with STE, and that clipping the weight distribution (to use high-SNR conductances) matters more than noise injection. The paper explicitly suggests HWA low-rank adaptation to cut training cost, which follow-up work such as AHWA-LoRA and HaLoRA does. The hardware model is idealised (digital attention, per-channel scaling), so system-level energy claims need separate architecture work.", "basis": "full-text", "pdf_source_url": "", "abstract": "Analog in-memory computing (AIMC) is a promising compute paradigm to improve speed and power efficiency of neural network inference beyond the limits of conventional von Neumann-based architectures. However, AIMC introduces fundamental challenges such as noisy computations and strict constraints on input and output quantization. Because of these constraints and imprecisions, off-the-shelf LLMs are not able to achieve 4-bit-level performance when deployed on AIMC-based hardware. While researchers previously investigated recovering this accuracy gap on small, mostly vision-based models, a generic method applicable to LLMs pre-trained on trillions of tokens does not yet exist. In this work, we introduce a general and scalable method to robustly adapt LLMs for execution on noisy, low-precision analog hardware. Our approach enables state-of-the-art models $\\unicode{x2013}$ including Phi-3-mini-4k-instruct and Llama-3.2-1B-Instruct $\\unicode{x2013}$ to retain performance comparable to 4-bit weight, 8-bit activation baselines, despite the presence of analog noise and quantization constraints. Additionally, we show that as a byproduct of our training methodology, analog foundation models can be quantized for inference on low-precision digital hardware. Finally, we show that our models also benefit from test-time compute scaling, showing better scaling behavior than models trained with 4-bit weight and 8-bit static input quantization. Our work bridges the gap between high-capacity LLMs and efficient analog hardware, offering a path toward energy-efficient foundation models. Code is available at https://github.com/IBM/analog-foundation-models.", "review": [{"fid": "F4", "text": "Hardware-aware training — injecting realistic device noise during training or fine-tuning — is the field's dominant and empirically validated mitigation, and it now scales to pre-trained LLMs. On under 1% of pre-training tokens, Phi-3-mini-4k-instruct and Llama-3.2-1B-Instruct retained accuracy comparable to 4-bit-weight / 8-bit-activation quantized baselines under hardware-realistic analog noise — a gap off-the-shelf LLMs cannot close on their own.", "grade": "High confidence", "vote": "3–0 on the LLM result and the 4.4% ALBERT figure", "note": "Analog Foundation Models, NeurIPS 2025 (IBM Zurich / ETH) · ALBERT paper quantifies HWA's own contribution at 4.4% average recovery"}], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Buchel_AnalogFoundationModels_NeurIPS.pdf", "analysed": true, "slm": true, "lm_models": ["Phi-3-mini-4k-instruct", "Llama-3.2-1B-Instruct"], "param_scale": "1B–3.8B", "slm_note": "Phi-3-mini-4k-instruct and Llama-3.2-1B-Instruct (SLM scale) trained hardware-aware and evaluated under simulated AIMC noise (AIHWKIT-Lightning) and digital low-bit baselines; GPUs used for training.", "pdf": "11_Small_Language_Models_on_AIMC/2025_Buchel_AnalogFoundationModels_NeurIPS.pdf", "priority": 11.74}, {"id": "W4410582659", "short": "NVCiM-PT", "title": "NVCiM-PT: An NVCiM-Assisted Prompt Tuning Framework for Edge LLMs", "authors": ["Ruiyang Qin", "Pengyu Ren", "Zheyu Yan", "Liu Liu", "Dancheng Liu", "Amir Nassereldine", "Jinjun Xiong", "Kai Ni", "Xiaobo Sharon Hu", "Yiyu Shi"], "year": 2025, "venue": "", "venue_short": "DATE", "venue_full": "Design, Automation & Test in Europe Conference & Exhibition (DATE 2025)", "venue_ok": true, "doi": "https://doi.org/10.23919/date64628.2025.10993249", "cites_global": 2, "cat": "11", "seed": false, "devices": ["ReRAM", "FeFET"], "models": ["GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "NVCiM-PT stores per-domain optimal prompt-tuning virtual tokens (OVTs) in a non-volatile CiM crossbar and retrieves the right one via an in-memory multi-scale matrix-multiply search, cutting edge-LLM domain-shift degradation while giving up to 120x lower latency and 60x lower energy than a Jetson Orin CPU.", "summary": "Edge LLMs personalized via prompt tuning (PT) degrade when user data drifts across domains, since a single 'one-for-all' set of virtual tokens cannot cover all domains, while storing a separate Optimal Virtual Token (OVT) set per domain explodes memory and retrieval latency on resource-constrained edge devices. NVCiM-PT addresses this with three components: (1) representative selection, which k-means-clusters buffered user embeddings into domains and PT-trains an OVT only on one representative sample per cluster; (2) noise-aware training, which injects magnitude-dependent Gaussian noise into the virtual tokens during PT so they tolerate NVM (RRAM/FeFET) device-variation noise after being written to a crossbar; (3) a store-and-scaled-search algorithm (SSA) that encodes OVTs with a Deep-Compression-style autoencoder, stores them as crossbar conductances, and retrieves the best-matching OVT for a new query via a multi-scale (pooling at scales 1/2/4) weighted dot-product computed as an in-memory matrix-matrix multiplication, which is more robust than directly running MIPS at mismatched embedding granularities. Evaluated on 3 edge LLMs (Gemma-2B, Mistral-7B-GPTQ, Phi-2), 5 LaMP datasets, 5 measured NVM device-variation profiles, and compared against noise-mitigation baselines (SWV, CxDNN, CorrectNet) combined with plain MIPS retrieval, plus NeuroSim-based latency/energy simulation of the crossbar search versus a Jetson Orin CPU.", "contributions": ["First work to use NVCiM (RRAM/FeFET crossbars) to accelerate and store prompt-tuning data for edge LLM personalization", "Representative-selection (k-means-based) method to bound the number of per-domain OVTs needed for prompt tuning under limited edge buffer size", "Noise-aware training that injects magnitude-binned Gaussian noise into virtual tokens during PT so they survive NVM device variation after storage", "A scaled search algorithm (SSA) performing multi-scale pooled dot-product retrieval of OVTs as an in-memory matrix-matrix multiply, addressing granularity mismatch between MIPS and virtual-token representations", "System evaluation across 3 LLMs, 5 datasets and 5 real NVM device-variation profiles, plus NeuroSim-based latency/energy comparison vs CPU"], "claims": [{"claim": "Per-sample OVTs greatly outperform one-for-all prompt tuning across domain-shifted user data", "support": "prefix-tuning with OVTs outperforms Vanilla, DEPT and P-tuning v2 across Gemma-2B and Phi-2 on four datasets", "loc": "Sec. I, Fig. 1"}, {"claim": "NVCiM-PT outperforms noise-mitigation + MIPS baselines (SWV, CxDNN, CorrectNet, No-Miti) across LLMs, datasets, and NVM devices", "support": "NVCiM-PT achieves the highest accuracy/Rouge-1 score in nearly every cell of the 3 LLM x 5 dataset x 5 device comparison table", "loc": "Sec. IV, Table I"}, {"claim": "NVCiM retrieval is much faster and more energy-efficient than CPU-based retrieval", "support": "up to 120x latency improvement and up to 60x energy improvement vs Jetson Orin CPU", "loc": "Abstract; Sec. IV.2, Fig. 5"}, {"claim": "The proposed SSA retrieval scheme is useful independent of which noise-mitigation method is used for storage", "support": "SWV/CxDNN/CorrectNet combined with SSA all outperform No-Miti(MIPS) in Table I", "loc": "Sec. IV"}], "results": ["Up to 36.7% improvement in edge LLM performance across multiple NVCiM devices (Abstract)", "Up to 120x latency improvement and up to 60x energy improvement vs Jetson Orin CPU (Abstract, Fig. 5)", "NVCiM-PT outperforms SWV, CxDNN, CorrectNet, No-Miti(MIPS) and NVP*(MIPS) baselines across 3 LLMs x 5 datasets x 5 NVM devices at device variation sigma=0.1 (Table I)"], "limitations": ["Crossbar retrieval latency/energy are NeuroSim simulation results (22nm node model), not measured silicon", "Device variation modeled as simple magnitude-binned Gaussian noise from prior measured profiles, not a full non-ideality model (IR-drop, drift, etc.)", "OVT storage/retrieval capacity evaluated only at modest scales (subarray 384x128, up to 128 virtual-token sets per array); scaling to many more domains/users not studied", "Comparison baselines (SWV, CxDNN, CorrectNet) are compensation methods repurposed for this retrieval task rather than methods originally designed for it"], "remarks": "This is a short DATE paper (algorithm + architecture-level simulation) that is one of the first to connect analog/NVM CiM specifically to prompt-tuning-based edge LLM personalization rather than full inference or training acceleration — a distinct mapping problem (storing/retrieving many small virtual-token vectors) from the usual weight-crossbar mapping literature. The core idea (treating OVT retrieval as an in-memory matrix-matrix multiply/similarity search, with multi-scale pooling to bridge representation mismatches) is a reusable template for other in-memory associative-retrieval or RAG-on-CiM systems. Evidence is purely simulated (NeuroSim-based circuit numbers, no fabricated macro), and the device-variation model is relatively coarse, so the robustness claims should be read as a proof-of-concept rather than a hardened design.", "basis": "full-text", "pdf_source_url": "", "abstract": "Large Language Models (LLMs) deployed on edge devices, known as edge LLMs, need to continuously fine-tune their model parameters from user-generated data under limited resource constraints. However, most existing learning methods are not applicable for edge LLMs because of their reliance on high resources and low learning capacity. Prompt tuning (PT) has recently emerged as an effective fine-tuning method for edge LLMs by only modifying a small portion of LLM parameters, but it suffers from user domain shifts, resulting in repetitive training and losing resource efficiency. Conventional techniques to address domain shift issues often involve complex neural networks and sophisticated training, which are incompatible for PT for edge LLMs. Therefore, an open research question is how to address domain shift issues for edge LLMs with limited resources. In this paper, we propose a prompt tuning framework for edge LLMs, exploiting the benefits offered by non-volatile computing-in-memory (NVCiM) architectures. We introduce a novel NVCiM-assisted PT framework, where we narrow down the core operations to matrix-matrix multiplication, which can then be accelerated by performing in-situ computation on NVCiM. To the best of our knowledge, this is the first work employing NVCiM to improve the edge LLM PT performance.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Qin_NVCiMPT_DATE.pdf", "analysed": true, "slm": true, "lm_models": ["Gemma-2B", "Mistral-7B-GPTQ", "Phi-2"], "param_scale": "2B–7B", "slm_note": "Gemma-2B, Mistral-7B-GPTQ and Phi-2 (edge SLMs) personalized by prompt tuning with virtual tokens stored/searched on simulated NVM crossbars (RRAM/FeFET) versus Jetson Orin CPU.", "pdf": "11_Small_Language_Models_on_AIMC/2025_Qin_NVCiMPT_DATE.pdf", "priority": 8.33}, {"id": "W4413755433", "short": "CIM-LLM Dataflow", "title": "CIM for Transformer Models: Enhancing Large Language Model Inference Efficiency", "authors": ["Miao Li", "Jung-Fang Ke", "En-Ming Huang", "Zhiwei Liu", "Yuguang Chen", "Chun‐Yi Lee"], "year": 2025, "venue": "", "venue_short": "ISVLSI", "venue_full": "IEEE Computer Society Annual Symposium on VLSI (ISVLSI 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/isvlsi65124.2025.11130222", "cites_global": 0, "cat": "11", "seed": false, "devices": ["Generic-NVM"], "models": ["GPT/LLM", "Transformer"], "evidence": "simulation", "tldr": "Proposes a Compute-in-Memory dataflow and memory hierarchy that performs LLM attention-score and feed-forward computation directly in CIM instead of offloading KV cache to the CPU, reporting 0.026x latency and ~1.2e-3x energy relative to a CPU-based implementation.", "summary": "The paper addresses the memory and compute bottleneck of LLM inference when GPU memory cannot hold the full KV cache and no high-bandwidth inter-GPU link (e.g. NVLink) is available: the usual fallback is to offload the KV cache to the CPU for storage/attention computation and ship results back to the GPU, which the authors note is costly both because attention-score computation is demanding on the CPU and because it requires heavy data movement between KV caches and memory. They propose computing attention scores and even the feed-forward layers directly on Compute-in-Memory (CIM) hardware instead, presenting a tailored CIM-based dataflow and memory hierarchy design for this purpose. The authors position this as an early (first, per the abstract) exploration of integrating CIM specifically into the LLM inference pipeline for attention and FFN computation, reporting large latency and energy reductions relative to a CPU-based baseline.", "contributions": ["Identifies KV-cache CPU-offloading (needed when GPU memory and inter-GPU links are insufficient) as a major latency/energy bottleneck for LLM inference", "Proposes computing both attention-score and feed-forward-layer computation directly on Compute-in-Memory (CIM) hardware rather than offloading to CPU", "Designs a tailored CIM-based dataflow and memory hierarchy for this attention + FFN computation", "Reports large latency and energy reductions versus a CPU-based implementation"], "claims": [{"claim": "The proposed CIM-based dataflow substantially reduces LLM inference latency and energy versus a CPU-based implementation", "support": "0.026x inference latency and 1.199x10^-3x energy compared to a CPU-based implementation", "loc": "Abstract"}], "results": ["0.026x inference latency (~38x speedup) vs. CPU-based implementation", "1.199x10^-3x energy consumption (~834x energy reduction) vs. CPU-based implementation"], "limitations": ["Baseline comparison is only against a CPU-based implementation, not a GPU baseline, which likely inflates the reported speedup/energy-reduction multipliers relative to what a GPU-vs-CIM comparison would show", "Abstract does not specify the memory device technology used for the CIM arrays", "Evidence basis (simulation vs. prototype) and model/benchmark scale are not stated in the abstract"], "remarks": "The framing (CPU-offloaded KV cache as the bottleneck being replaced by CIM) is a reasonable motivation, but the headline 38x/834x figures should be read cautiously since they are measured against a CPU baseline rather than the GPU-based baselines most LLM-serving systems actually use; a fairer comparison for assessing real-world impact would also include GPU-only and GPU+NVLink multi-GPU baselines. Still, the idea of using CIM for both attention-score and FFN computation (rather than attention alone, as in several ReRAM-attention accelerators) is a relevant mapping contribution for full-pipeline LLM-on-CIM designs.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "In the field of large language model (LLM) inference, the high computational demand and extensive memory requirements for weights and key-value (KV) cache storage present significant challenges. This issue becomes especially problematic when relying exclusively on GPUs, as they often lack the capacity to accommodate the entire KV cache, particularly in larger LLMs. In the absence of direct communications like NVlink among multiple GPUs, LLMs typically require offloading the KV cache to the CPU for storage and computation, followed by transferring the multi-head attention results back to the GPU for subsequent transformer computations. Given that attention score computation is computationally demanding on the CPU and requires substantial data movement between KV caches and memory, the direct computation of attention scores and even the feedforward layers on Compute-in-Memory (CIM) systems emerges as a viable alternative. This paper is at the forefront of integrating CIM technology in LLM inference, and proposes an innovative architecture that leverages this emerging technology to enhance inference efficiency. Specifically, we present a tailored CIM-based dataflow and hierarchy design for optimize the computation of attention scores and feed-forward layers using CIMs. The results show improvements in performance, with $0.026 \\times$ inference latency and $1.199 \\times 10^{-3} \\times$ energy as compared to a CPU-based implementation.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Li_CIMLLMDataflow_ISVLSI.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Only the abstract was available; it names no specific LLMs or scales, offloading KV-cache attention to CIM versus CPU.", "pdf": null, "priority": 8.0}, {"id": "W4416429987", "short": "SAGE", "title": "SAGE: Saliency-Aware Grouping for Efficient Mapping of LLMs on Analog Compute-in-Memory", "authors": ["Y. Thomas Hou", "Zhenyu Liu", "Garrett Gagnon", "Hsinyu Tsai", "Kaoutar El Maghraoui", "Geoffrey W. Burr", "Liu Liu"], "year": 2025, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad66269.2025.11240907", "cites_global": 0, "cat": "11", "seed": false, "devices": ["Generic-NVM"], "models": ["Transformer", "GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "SAGE is a training-free channel-reordering strategy for LLM fully-connected layers on analog compute-in-memory hardware that reduces output kurtosis (by grouping salient/long-tailed values together), improving signal-to-noise ratio and inference accuracy under hardware noise without retraining.", "summary": "The paper addresses the problem that analog compute-in-memory (ACIM) hardware struggles with the long-tailed, high-kurtosis activation/weight distributions typical of LLM fully-connected (FC) layers: large-amplitude 'salient values' degrade analog signal quality once quantized and exposed to system noise. SAGE (Saliency-Aware Grouping for Efficient Mapping) is proposed as a training-free strategy that reorders weight and input channels of FC layers based on their statistical characteristics, identifying kurtosis as the key factor harming analog robustness and developing a saliency-aware grouping method that reduces output kurtosis to boost SNR. A reconfigurable tile design is introduced alongside the mapping method to support mixed-precision execution and maximize crossbar array utilization across layers with heterogeneous precision needs. The approach is evaluated via ACIM simulation on multiple LLMs and benchmarks, reportedly improving both inference accuracy and energy efficiency without requiring any retraining of the model.", "contributions": ["Identifies kurtosis of per-channel output distributions as a key driver of analog-hardware noise sensitivity in LLM FC layers", "Proposes SAGE, a training-free channel-reordering/grouping method that reduces output kurtosis to improve SNR under ACIM noise and quantization", "Introduces a reconfigurable tile design supporting mixed-precision execution to maximize crossbar array utilization across layers", "Evaluates across multiple LLMs and benchmarks via ACIM simulation, reporting accuracy and energy-efficiency gains without retraining"], "claims": [{"claim": "Reordering channels by saliency/kurtosis statistics (without any retraining) improves ACIM inference accuracy for LLMs", "support": "Abstract: 'significantly improves inference accuracy and energy efficiency based on ACIM simulation without requiring retraining'", "loc": "Abstract"}, {"claim": "Long-tailed, high-kurtosis activation distributions are a primary cause of degraded analog signal quality in LLM FC layers", "support": "Abstract identifies kurtosis as 'a key factor affecting analog robustness'", "loc": "Abstract"}], "results": ["No specific quantitative accuracy/energy numbers available from the abstract alone; full text was not accessible"], "limitations": ["Full text not accessible to this reviewer (no open preprint found); exact benchmarks, noise models, and magnitude of improvement could not be verified", "Evaluation is simulation-based (ACIM simulator), not measured silicon"], "remarks": "Abstract-only assessment: a legitimate open copy could not be located (ICCAD is not downloadable here and no arXiv preprint was found). The idea of exploiting a training-free statistical reordering of channels to tame outlier/long-tail activations is conceptually related to outlier-aware quantization work for LLMs (e.g., channel reordering/mixed precision seen in digital LLM quantization literature) but applied specifically to the SNR constraints of analog CIM arrays; this is a relevant and timely contribution to the 'mapping LLMs onto analog crossbars under noise' problem, though its quantitative strength cannot be verified without the full paper.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Large Language Models (LLMs) demand high memory bandwidth and computational efficiency, posing significant challenges for deployment on traditional digital accelerators. Analog Compute-in-Memory (ACIM) architectures offer an attractive alternative by co-locating storage and computation to reduce data movement. However, executing LLMs on ACIM systems remains challenging due to hardware non-idealities and the unique statistical properties of LLM inputs and outputs in FC layers. In particular, long-tailed data distributions containing large-amplitude \"salient values\" degrade analog signal quality under quantization and system noise. In this work, we propose SAGE (Saliency-Aware Grouping for Efficient Mapping), a training-free strategy that improves noise resilience by reordering weight and input channels of FC layers based on statistical characteristics of LLMs. We identify kurtosis as a key factor affecting analog robustness and develop a saliency-aware mapping method that reduces output kurtosis to enhance the signal-to-noise ratio. We further introduce a reconfigurable tile design that supports mixed-precision execution and maximizes array utilization across layers. Evaluations on multiple LLMs and benchmarks show that SAGE significantly improves inference accuracy and energy efficiency based on ACIM simulation without requiring retraining.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Hou_SAGE_ICCAD.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Only the abstract was available; LLM names/scales are not stated in the library text, targeting LLM FC-layer mapping onto analog CIM.", "pdf": null, "priority": 8.0}, {"id": "W7117258492", "short": "DuoPIM", "title": "DuoPIM: RRAM–DRAM Hybrid PIM Acceleration for Flexible-Batch LLM Decoding", "authors": ["Xiaotian Sun", "Xinyu Wang", "Wanqian Li", "Xueqi Li", "Chunmeng Dou", "Yinhe Han", "Xiaoming Chen"], "year": 2025, "venue": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_short": "TCAD", "venue_full": "IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems", "venue_ok": true, "doi": "https://doi.org/10.1109/tcad.2025.3648674", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM", "DRAM"], "models": ["Transformer", "GPT/LLM"], "evidence": "simulation", "tldr": "DuoPIM is a hybrid RRAM+DRAM processing-in-memory architecture for LLM decoding that maps weight-heavy FC layers to batch-insensitive RRAM in-situ compute and cache-dependent attention to DRAM-PIM, with architectural and scheduling innovations to keep both resource types well utilized across batch sizes.", "summary": "The paper targets the batch-size dilemma in LLM decoding: batching boosts FC-layer throughput on GPUs but inflates the KV-cache demands of attention layers, and existing DRAM-PIM accelerators for attention are underutilized at small batch sizes while RRAM-based in-situ compute for FC layers is insensitive to batch size because it avoids weight reloading. DuoPIM proposes a hybrid architecture that assigns RRAM to FC layers and DRAM-PIM to attention layers to escape the batch-size-throughput tradeoff, but notes that naively scaling existing RRAM designs misaligns with LLM compute/storage demands and that DRAM-PIM suffers from attention's irregular computational pattern. To address this, DuoPIM decouples RRAM's storage and compute into a hierarchical architecture, makes minimal DRAM-PIM modifications to support online softmax, and introduces scheduling strategies across multiple architectural levels to improve resource utilization in the hybrid system. Evaluations reportedly show DuoPIM can fully exploit computing capacity across a range of batch sizes, addressing the utilization problems of each memory technology used alone.", "contributions": ["Hybrid RRAM (for FC layers) + DRAM-PIM (for attention) architecture that targets batch-size-insensitive LLM decoding throughput", "Hierarchical RRAM architecture that decouples storage and compute capabilities to better match LLM compute/storage demands", "Minimal DRAM-PIM modifications to support online softmax computation for attention", "Multi-level scheduling strategies to coordinate the two PIM subsystems and improve resource utilization across batch sizes"], "claims": [{"claim": "RRAM-based FC-layer acceleration is insensitive to batch size because it avoids weight-loading overhead, unlike GPU-based approaches", "support": "Abstract: 'emerging non-volatile RRAM technology offers batch size-insensitive acceleration for FC layers through highly parallel in-situ computations by eliminating weight loading overhead'", "loc": "Abstract"}, {"claim": "DuoPIM's hybrid design keeps computing capacity well utilized across various batch sizes, unlike pure DRAM-PIM attention accelerators", "support": "Abstract: 'Evaluations demonstrate DuoPIM's ability to fully leverage computing capacity across various batch sizes'", "loc": "Abstract"}], "results": ["No specific quantitative throughput/energy numbers available from the abstract alone; full text was not accessible"], "limitations": ["Full text not accessible to this reviewer (TCAD is not downloadable here and no arXiv preprint was found); baselines and quantitative results could not be verified", "Evidence basis is simulation (architectural/system-level), not measured silicon"], "remarks": "Abstract-only assessment: IEEE Xplore (TCAD) is not downloadable in this environment and no preprint was found. The core architectural insight — splitting the LLM decode workload so that weight-dominated FC layers go to batch-insensitive RRAM in-situ compute while cache-dependent attention goes to DRAM-PIM — is a sensible way to avoid the respective underutilization failure modes of each memory technology alone, and fits within the broader trend of heterogeneous/hybrid PIM designs for LLM inference (c.f. HyPIM, ASMA in this same batch). Without the full text, the magnitude of utilization/throughput gains and the realism of the cross-technology scheduling overhead cannot be assessed.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformer-based large language models (LLMs) primarily consist of weight-intensive fully-connected (FC) layers and cache-dependent attention layers. While batching significantly enhances the throughput of FC layers, it paradoxically increases the cache demands of attention layers. This provides no performance benefit and creates substantial memory pressure. Consequently, existing GPU-based LLM acceleration systems face throughput limitations from batch size constraints. Even when DRAM-based processing-in-memory (PIM) is employed to accelerate attention, the utilization remains extremely low under small batch sizes, which is unsuitable for low batch scenarios. Fortunately, the emerging non-volatile RRAM technology offers batch size-insensitive acceleration for FC layers through highly parallel in-situ computations by eliminating weight loading overhead. This insight leads us to propose a hybrid approach: RRAM for FC layers and DRAM PIM for attention layers to overcome batch size limitations. However, merely scaling existing RRAM architectures misaligned with LLMs’ computation and storage demands will result in prohibitive overheads. Meanwhile, existing DRAM-based PIMs suffer from poor resource utilization due to the computational pattern of attention layers. Implementing an effective scheduling strategy is equally crucial to harness the potential of the hybrid PIM system. To address these challenges, we present DuoPIM, a novel RRAM-DRAM hybrid PIM architecture optimized for LLM decoding. We introduce novel architectural innovations for both the RRAM and DRAM PIM components to address the challenges posed by LLMs. Specifically, we decouple RRAM’s storage and computing capabilities within a hierarchical architecture, implement minimal modifications to DRAM PIM to support online softmax, and devise dedicated strategies across multiple architectural levels to enhance overall resource utilization. Evaluations demonstrate DuoPIM’s ability to fully leverage computing capacity across various batch sizes.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Sun_DuoPIM_TCAD.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Only the abstract was available; it names no specific LLMs or scales, targeting RRAM (FC layers) plus DRAM-PIM (attention) decoding.", "pdf": null, "priority": 8.0}, {"id": "W7117549365", "short": "ASMA", "title": "ASMA: An Anisotropy Scaling Memristor-Based Accelerator for LLM Inference", "authors": ["Zijian Xiong", "Xiangrui Yang", "Yuhang Zhang", "Yue Zhou", "Jianguo Yang", "Yaoyu Tao", "Xiangshui Miao", "Yu He"], "year": 2025, "venue": "", "venue_short": "ICCD", "venue_full": "IEEE International Conference on Computer Design (ICCD 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccd65941.2025.00086", "cites_global": 0, "cat": "11", "seed": false, "devices": ["Memristor(generic)"], "models": ["Transformer", "GPT/LLM"], "evidence": "simulation", "tldr": "ASMA is a memristor-based CIM accelerator for LLM FFN layers that exploits the 'anisotropic' (additive/concatenative/sequential) scaling structure of LLM computations, using a Subtile hierarchy, a hierarchical anisotropic NoC, and a co-designed compiler to cut communication overhead versus isotropic CIM designs, reporting up to 81.7% latency and 91.5% energy improvement in a transaction-level simulator.", "summary": "The paper argues that naively scaling isotropic (uniform) CIM architectures to handle LLM feed-forward network (FFN) layers introduces severe new communication overheads, because LLM FFN computations actually scale anisotropically along different dimensions (categorized as additive, concatenative, and sequential). ASMA is proposed as an Anisotropy Scaling Memristor-based Accelerator that is co-designed around this observation: it introduces a Subtile hierarchy for optimized pipelining, a hierarchical anisotropic Network-on-Chip with distinct channels for broadcast versus localized communication, and a co-designed compiler that maps LLM computations onto the architecture by exploiting these anisotropic scaling characteristics. Evaluation with a transaction-level simulator shows latency improvements up to 81.7% and energy improvements up to 91.5% versus conventional hierarchical CIM designs, which the authors frame as a new design paradigm for LLM-specific CIM accelerators that embrace rather than ignore workload anisotropy.", "contributions": ["Identifies and categorizes LLM FFN layer scaling as anisotropic (additive, concatenative, sequential dimensions), unlike the isotropic assumption in prior CIM designs", "Subtile hierarchy for optimized pipelining matched to this anisotropic structure", "Hierarchical anisotropic Network-on-Chip with distinct broadcast and localized-communication channels", "Co-designed compiler that maps LLM computation onto the anisotropic architecture", "Transaction-level simulator evaluation showing large latency/energy gains over conventional hierarchical CIM"], "claims": [{"claim": "ASMA substantially reduces latency versus conventional hierarchical CIM designs by exploiting workload anisotropy", "support": "Abstract: 'latency improvement up to 81.7% ... compared to conventional hierarchical CIM designs'", "loc": "Abstract"}, {"claim": "ASMA substantially reduces energy versus conventional hierarchical CIM designs", "support": "Abstract: 'energy improvement up to 91.5% compared to conventional hierarchical CIM designs'", "loc": "Abstract"}], "results": ["Up to 81.7% latency improvement vs. conventional hierarchical CIM designs", "Up to 91.5% energy improvement vs. conventional hierarchical CIM designs"], "limitations": ["Full text not accessible to this reviewer (ICCD is not downloadable here and no arXiv preprint was found); exact baselines, benchmarked LLMs, and simulator assumptions could not be verified beyond the abstract", "Evidence basis is a transaction-level simulator, not measured silicon or cycle-accurate hardware emulation"], "remarks": "Abstract-only assessment: ICCD proceedings are not downloadable here and no preprint was found. The anisotropy framing (additive/concatenative/sequential scaling of FFN dimensions) is a genuinely architecture-relevant observation for mapping LLM FFN layers onto tiled memristor CIM systems, distinguishing this from CNN-era CIM accelerators that assumed more uniform/isotropic tiling; the claimed 80-90%+ improvements are large and would need the full paper's baseline definitions to assess credibility.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Large Language Models (LLMs) present substantial computational and memory challenges, particularly within their Feed-Forward Network (FFN) layers. While Computing-in-Memory (CIM) using Memristor offers a path to mitigate data movement bottlenecks, naively scaling existing CIM architectures for LLMs leads to new, severe communication overheads due to their typically isotropic (uniform) design. This paper introduces ASMA, an Anisotropy Scaling Memristor-based Accelerator, specifically co-designed for efficient LLM inference. ASMA identifies and exploits the inherent anisotropic scaling characteristics of LLM FFN layers—categorized into additive, concatenative, and sequential dimensions. Key innovations include a novel Subtile hierarchy for optimized pipelining, a hierarchical anisotropic Network-on-Chip (NoC) featuring distinct channels for broadcast and localized communication, and a co-designed compiler that maps LLM computations by leveraging these architectural specializations. Evaluations using a transaction-level simulator demonstrate that ASMA achieves latency improvement up to 81.7% and energy improvement up to 91.5% compared to conventional hierarchical CIM designs. ASMA offers a new paradigm for designing LLM-specific CIM accelerators by embracing workload anisotropy.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Xiong_ASMA_ICCD.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Only the abstract was available; it names no specific LLMs or scales, targeting memristor CIM accelerator for LLM FFN layers.", "pdf": null, "priority": 8.0}, {"id": "W4406178148", "short": "MoE 3D Analog In-Memory Computing", "title": "Efficient scaling of large language models with mixture of experts and 3D analog in-memory computing", "authors": ["Julian Büchel", "Athanasios Vasilopoulos", "William Simon", "Irem Boybat", "Hsinyu Tsai", "Geoffrey W. Burr", "Hernan Castro", "B. Filipiak", "Manuel Le Gallo", "Abbas Rahimi", "Vijay Narayanan", "Abu Sebastian"], "year": 2025, "venue": "Nature Computational Science", "venue_short": "NatCompSci", "venue_full": "Nature Computational Science", "venue_ok": true, "doi": "https://doi.org/10.1038/s43588-024-00753-x", "cites_global": 40, "cat": "11", "seed": false, "devices": ["PCM"], "models": ["GPT/LLM", "Transformer"], "evidence": "analytical", "tldr": "An IBM Research team argues that mixture-of-experts (MoE) transformer architectures are a natural match for analog in-memory computing, and proposes using 3D-stacked PCM crossbar arrays to store the large number of expert weight matrices at high density so that large-capacity LLMs can be scaled efficiently while only a small subset of experts (and hence tiles) are read per token.", "summary": "Large language models increasingly use mixture-of-experts (MoE) architectures, which decouple total parameter count from per-token compute by activating only a small subset of expert sub-networks for each token. This paper (from the IBM Research analog-AI group behind prior PCM-based AIMC chips such as HERMES and the 64-core mixed-signal chip) argues that this sparsity property is a natural fit for analog in-memory computing: because AIMC weights are stored in dense, non-volatile crossbar tiles that are read rather than streamed, an MoE model's experts can be mapped one-per-tile (or group of tiles) so that only the tiles corresponding to the token's selected experts need to be activated, avoiding the energy and area cost of duplicating or reprogramming weights that dense, non-MoE AIMC-LLM mappings would require. To push model capacity further, the authors propose 3D integration/stacking of PCM crossbar layers to increase on-chip expert storage density beyond what 2D AIMC tiling can offer. The paper evaluates this MoE-plus-3D-AIMC approach for scaling LLMs, projecting efficiency benefits relative to conventional (GPU/digital or dense-AIMC) implementations, though specific quantitative figures could not be confirmed from the abstract/metadata available for this analysis.", "contributions": ["Proposes combining mixture-of-experts (MoE) LLM architectures with analog in-memory computing, arguing the two are naturally complementary due to MoE's sparse per-token expert activation", "Proposes 3D stacking/integration of PCM-based AIMC crossbar arrays to increase on-chip weight storage density for very large (many-expert) MoE models", "Builds on the IBM analog-AI hardware and software stack (e.g., AIHWKIT, HERMES-class PCM chips) used in the group's prior work", "Analyzes/projects efficiency and scaling benefits of this approach for large language model inference"], "claims": [], "results": [], "limitations": ["No abstract or full text was retrievable for this paper (empty abstract field; a PDF initially found at the source URL was not a valid PDF, and no legitimate open copy was found via the arXiv API), so this summary relies on the title, authorship, venue, and general knowledge of the IBM analog-AI research program rather than verified paper content", "No specific quantitative results (energy, throughput, model scale, accuracy) can be responsibly reported without access to the paper text"], "remarks": "This is a prominent, highly-cited (40+ citations per metadata) IBM Research Nature Computational Science paper connecting two major trends in this collection — LLM mixture-of-experts architectures and analog in-memory computing with PCM — and is cited by several later analog-LLM mapping papers in this set (e.g., SAGE, COMET-3D). However, since neither an abstract nor the full text could be retrieved in this session, the entry above is necessarily high-level and should be revisited and filled in with concrete claims/results if the paper becomes accessible.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Buchel_MoE3DAnalogInMemoryComputing_NatCompSci.pdf", "analysed": true, "slm": true, "lm_models": ["GPT-2 (300M)", "GPT-2 (700M)", "GPT-2 (1B)", "Megatron (1B)", "Mixtral 8x7B (comparison)", "MoE models up to ~51B"], "param_scale": "300M–~51B (MoE up to ~51B total parameters)", "slm_note": "Dense GPT-2 (300M-1B) and Megatron-1B compared with MoE models scaling up to ~51B total parameters, mapped to 3D analog (PCM) in-memory computing in simulation/projection; the largest MoE models exceed the SLM range, although per-token active compute is smaller.", "pdf": "11_Small_Language_Models_on_AIMC/2025_Buchel_MoE3DAnalogInMemoryComputing_NatCompSci.pdf", "priority": 11.83}, {"id": "W4411233250", "short": "Analog AI LLM Accelerators", "title": "Analog AI Accelerators for Transformer-based Language Models: Hardware, Workload, and Power Performance", "authors": ["Hsinyu Tsai", "Hadjer Benmeziane", "Irem Boybat", "Julian Büchel", "Pritish Narayanan", "Manuel Le Gallo", "Sameer H. Jain", "A. Vasilopoulos", "William Simon", "Kohji Hosokawa", "Masatoshi Ishii", "Yasuteru Kohda", "A. Chen", "Charles Mackin", "Kaoutar El Maghraoui", "Atsuya Okazaki", "Alexander M. Friz", "Jose Luquin", "Abu Sebastian", "Vijay Narayanan", "Geoffrey W. Burr"], "year": 2025, "venue": "", "venue_short": "IMW", "venue_full": "IEEE International Memory Workshop (IMW 2025)", "venue_ok": true, "doi": "https://doi.org/10.1109/imw61990.2025.11026974", "cites_global": 2, "cat": "11", "seed": false, "devices": ["PCM"], "models": ["Transformer", "GPT/LLM"], "evidence": "survey", "tldr": "An IBM-authored overview of recent progress on Phase-Change-Memory-based analog AI hardware and architectures aimed at the capacity, compute, and dynamic-memory-throughput demands of Transformer-based LLM inference.", "summary": "This is a progress/overview paper from the large IBM Research analog-AI team (Tsai, Boybat, Buchel, Narayanan, Le Gallo, Sebastian, Burr and others) describing why Transformer-based LLMs stress conventional hardware: they need large weight capacity, efficient compute, and high-throughput access to large dynamic memory (e.g. KV caches). The paper surveys recent PCM-based hardware and architectural designs developed by the group to address these LLM-inference challenges, covering hardware, workload characteristics, and power-performance considerations for analog AI accelerators applied to LLMs.", "contributions": ["Articulates the specific hardware demands LLM inference places on analog AI accelerators: weight capacity, compute efficiency, and dynamic-memory throughput", "Reviews recent progress on PCM-based analog AI hardware and chip/architecture designs relevant to LLM inference", "Discusses workload and power-performance characteristics of analog AI accelerators applied to Transformer-based LLMs"], "claims": [], "results": [], "limitations": ["Abstract gives no specific quantitative results; this is primarily a review/progress-report style paper summarizing the group's own prior hardware work rather than presenting new experiments", "Full text not available to this analysis; scope and depth of coverage inferred only from the abstract and author affiliations"], "remarks": "Written by essentially the same IBM Research team behind PCM-based analog-AI chips (HERMES-Core, the 64-core PCM chip, NorthPole-adjacent 2D-mesh accelerators) and the AIHWKit training/inference toolchain, this paper appears to be a conference overview tying that hardware lineage specifically to LLM inference workloads (e.g. complementing the same group's NORA paper on noise-aware LLM rescaling). As a survey-style piece from IMW, it is useful for citation/context purposes but likely does not contain new quantitative benchmarks beyond what is reported in the underlying hardware papers it reviews.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Transformer-based Large Language Models (LLMs) demand large weight capacity, efficient computing, and high throughput access to large amount of dynamic memory. These challenges present great opportunities for algorithmic and hardware innovations, including Analog AI accelerators. In this paper, we describe recent progress on Phase Change Memory-based hardware and architectural designs to address the challenges for LLM inference.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Tsai_AnalogAILLMAccelerators_IMW.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "not specified", "slm_note": "Overview of IBM PCM-based analog AI accelerators for Transformer LLMs; the available text names no specific models or scales.", "pdf": null, "priority": 9.24}, {"id": "W4411233189", "short": "eDRAMRRAMZO", "title": "Analog Multilevel eDRAM-RRAM CIM for Zeroth-Order Fine-tuning of LLMs", "authors": ["Mufeng Chen", "Luqi Zheng", "Jian-Yu Lin", "Peide D. Ye", "Haitong Li"], "year": 2025, "venue": "IEEE International Memory Workshop (IMW)", "venue_short": "IMW", "venue_full": "IEEE International Memory Workshop (IMW), 2025", "venue_ok": true, "doi": "https://doi.org/10.1109/imw61990.2025.11026966", "cites_global": 3, "cat": "11", "seed": false, "devices": ["RRAM", "eDRAM (MOM, In2O3 FET gain cell)"], "models": ["GPT/LLM"], "evidence": "simulation", "tldr": "Reliability-aware analog MLC eDRAM-RRAM CIM for zeroth-order LM fine-tuning, with 12x bit density over prior MLC eDRAM and further 5x density, 2x retention from In2O3 FETs.", "summary": "Zeroth-order fine-tuning avoids backpropagation and lowers memory overhead, suiting on-device LLM fine-tuning, but existing memory-centric accelerators trade off density, CIM capability and endurance/retention. The paper presents an RRAM-assisted MLC eDRAM programming scheme and a PVT-robust large-window time-to-digital converter. Two-finger MOM MLC-eDRAM gives 12x bit density over state of the art; BEOL In2O3 FETs add 5x density and 2x retention. Evidence type (measured vs simulated) is not clear from the truncated abstract.", "contributions": ["RRAM-assisted MLC eDRAM programming", "PVT-robust large-window TDC", "Co-design with zeroth-order optimisation for LM fine-tuning", "In2O3 BEOL FET gain cell for density/retention"], "claims": [{"claim": "MLC-eDRAM with two-finger MOM gives 12x bit density over SOTA MLC", "support": "12x", "loc": "Abstract"}], "results": ["12x bit density vs state-of-the-art MLC eDRAM", "additional 5x density and 2x retention with BEOL In2O3 FETs"], "limitations": ["Abstract-only; LM sizes and accuracy not seen", "Unclear if silicon or simulation"], "remarks": "Interesting because it targets training/fine-tuning, which is rare in analog IMC literature. Without the full text the LM-level evidence is unverified.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Zeroth-order fine-tuning eliminates explicit back-propagation and reduces memory overhead for large language models (LLMs), making it a promising approach for on-device fine-tuning tasks. However, existing memory-centric accelerators fail to fully leverage these benefits due to inefficiencies in balancing bit density, compute-in-memory capability, and endurance-retention trade-off. We present a reliability-aware, analog multi-level-cell (MLC) eDRAM-RRAM compute-in-memory (CIM) solution co-designed with zeroth-order optimization for language model fine-tuning. An RRAM-assisted eDRAM MLC programming scheme is developed, along with a process-voltage-temperature (PVT)-robust, large-sensing-window time-to-digital converter (TDC). The MLC-eDRAM integrating two-finger MOM provides 12× improvement in bit density over state-of-the-art MLC design. Another 5× density and 2× retention benefits are gained by adopting BEOL In2O3FETs.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Chen_EdramRramZoFinetune_IMW.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "unspecified (language-model fine-tuning)", "slm_note": "Analog multi-level eDRAM-RRAM CIM co-designed with zeroth-order optimisation for on-device LM fine-tuning; analog in-memory compute with RRAM-assisted MLC eDRAM and BEOL In2O3 FETs. Specific LMs and parameter sizes not stated in the abstract.", "added": "2026-10 SLM search", "pdf": null, "priority": 8.42}, {"id": "W4414198682", "short": "UniCAIM", "title": "UniCAIM: A Unified CAM/CIM Architecture with Static-Dynamic KV Cache Pruning for Efficient Long-Context LLM Inference", "authors": ["Weikai Xu", "Wenxuan Zeng", "Qianqian Huang", "Meng Li", "Ru Huang"], "year": 2025, "venue": "Proceedings - ACM IEEE Design Automation Conference", "venue_short": "DAC", "venue_full": "ACM/IEEE Design Automation Conference (DAC), 2025", "venue_ok": true, "doi": "https://doi.org/10.1109/dac63849.2025.11133273", "cites_global": 3, "cat": "11", "seed": false, "devices": ["FeFET"], "models": ["GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "FeFET CAM/CIM cell supports O(1) dynamic top-k KV pruning plus static pruning and exact attention, cutting AEDP 8.2-831x vs Sprint/TranCIM/CIMFormer with accuracy near full cache.", "summary": "KV cache growth limits long-context LLM inference. UniCAIM proposes a FeFET-based unified CAM and CIM array with three modes: CAM mode for approximate similarity and O(1) top-k dynamic pruning, charge-domain CIM mode for accumulating attention scores for static eviction, and current-domain mode for exact attention on selected tokens. Multi-level FeFETs store signed multibit KV. Algorithm combines prefill-stage static pruning with decode-time top-k and eviction. Evaluated at circuit level and on LongBench tasks with LongChat-7B.", "contributions": ["Static-dynamic KV cache pruning algorithm", "Unified CAM/CIM FeFET cell and array with three modes", "AEDP and accuracy evaluation vs SOTA CIM LLM accelerators"], "claims": [{"claim": "AEDP reduction vs prior CIM accelerators", "support": "8.2x/13.9x/124x (50% prune, 1-bit) vs Sprint/TranCIM/CIMFormer; up to 831x with 3-bit cell, 80% pruning", "loc": "Sec. IV-A4, Table II"}, {"claim": "Accuracy comparable to full cache", "support": "HotpotQA/NarrativeQA F1 near full cache, above SnapKV and StreamingLLM", "loc": "Fig. 13"}], "results": ["AEDP 8.2-831x lower than Sprint, TranCIM, CIMFormer", "Speedup 4.2x to 16.7x growing with sequence length", "Accuracy comparable to dense attention on LongBench subsets"], "limitations": ["Simulation only, no silicon", "Only KV cache/attention in memory, weights digital", "Analog non-idealities of FeFET not shown to affect accuracy results", "Two QA datasets only"], "remarks": "A cogent KV-cache-in-NVM design, relevant for long-context SLMs, with big AEDP gains partly from baseline choice. Accuracy evaluation is algorithmic and does not inject device noise, so analog robustness is unproven.", "basis": "full-text", "pdf_source_url": "", "abstract": "Transformer-based large language models (LLMs) have achieved impressive performance in various natural language processing (NLP) applications. However, the high memory and computation cost induced by the KV cache limits the inference efficiency, especially for long input sequences. Compute-in-memory (CIM)-based accelerators have been proposed for LLM acceleration with KV cache pruning. However, as existing accelerators only support static pruning with a fixed pattern or dynamic pruning with primitive implementations, they suffer from either high accuracy degradation or low efficiency. In this paper, we propose a ferroelectric FET (FeFET)-based unified content addressable memory (CAM) and CIM architecture, dubbed as UniCAIM. UniCAIM features simultaneous support for static and dynamic pruning with 3 computation modes: 1) in the CAM mode, UniCAIM enables approximate similarity measurement in $\\mathcal{O}(1)$ time for dynamic KV cache pruning with high energy efficiency; 2) in the charge-domain CIM mode, static pruning can be supported based on accumulative similarity score, which is much more flexible compared to fixed patterns; 3) in the current-domain mode, exact attention computation can be conducted with a subset of selected KV cache. We further propose a novel CAM/CIM cell design that leverages the multi-level characteristics of FeFETs for signed multibit storage of the KV cache and in-place attention computation. With extensive experimental results, we demonstrate UniCAIM can reduce the area-energy-delay product (AEDP) by $8.2 \\sim 831 \\times$ over the state-of-the-art CIM-based LLM accelerators at the circuit level, along with high accuracy comparable with dense attention at the application level, showing its great potential for efficient long-context LLM inference.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Xu_UniCAIM_DAC.pdf", "analysed": true, "slm": true, "lm_models": ["LongChat-v1.5-7B-32k", "Llama-2-7B (motivation)"], "param_scale": "7B", "slm_note": "FeFET unified CAM/CIM macro for KV-cache pruning and attention in long-context LLMs; accuracy evaluated on LongChat-v1.5-7B-32k (7B). Weights not in CIM; only the KV cache attention is in-memory (CAM approximate similarity, charge-domain accumulation, current-domain exact attention). Circuit-level simulation.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2025_Xu_UniCAIM_DAC.pdf", "priority": 8.42}, {"id": "W7126184620", "short": "FeRAMKVCache", "title": "First Experimental Demonstration of Disturb-Free 3D Vertical 1T-nC-1T Ferroelectric-based KV Cache with Co-Optimization of Hybrid Analog-Digital CIM and Token-Wise Dynamic Pruning for Efficient Long-Context LLM Inference", "authors": ["Weikai Xu", "Danyun Luo", "Minyue Deng", "Shuzhang Zhong", "Shengjie Cao", "Meng Li", "Qianqian Huang", "Ru Huang"], "year": 2025, "venue": "Technical digest - International Electron Devices Meeting/Technical digest", "venue_short": "IEDM", "venue_full": "IEEE International Electron Devices Meeting (IEDM), 2025", "venue_ok": true, "doi": "https://doi.org/10.1109/iedm50572.2025.11353834", "cites_global": 2, "cat": "11", "seed": false, "devices": ["FeRAM"], "models": ["GPT/LLM"], "evidence": "measured-silicon", "tldr": "First experimental FE-based KV cache: fabricated 3D 3x32x32 FeCap array with analog CIM token selection and digital CIM attention, claiming 6x/315x performance/energy gains over SOTA.", "summary": "Proposes a 3D vertical 1T-nC-1T FeRAM with shared FeCap strings. Analog 1T-nC CIM evaluates similarity in O(1) for token selection via small-signal non-destructive read; nC-1T digital CIM does exact attention over selected KV with destructive read. Data mapping enables parallel nC-string computation and avoids write disturb. Device shows ~10 ns switching, 10-year retention, 1e16 endurance. Abstract-only.", "contributions": ["3D vertical 1T-nC-1T FeRAM structure", "Hybrid analog-digital CIM with token-wise dynamic pruning", "Experimental array demonstration"], "claims": [], "results": ["~10 ns switching, 10-year retention, 1e16 endurance", "6x performance and 315x energy efficiency vs SOTA"], "limitations": ["Tiny 3x32x32 array; LLM-level results presumably simulated", "Abstract-only"], "remarks": "Rare measured hardware for KV cache in NVM. Gap between small array and LLM-scale claims remains.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "For the first time, a ferroelectric (FE)-based key-value (KV) cache for large language models (LLMs) is proposed and experimentally demonstrated. Through device-architecture-algorithm co-optimization, a novel 3D vertical 1T-nC-1T FeRAM structure, featuring orthogonally aligned word-lines/bit-lines and shared FE capacitor (FeCap) strings, as well as a hybrid analog-digital compute-in-memory (CIM) architecture with token-wise dynamic pruning algorithm, are presented. The designed 1T-nC-based analog CIM with small-signal non-destructive read can evaluate similarity in O(1) time for efficient token selection, and the nC-1T-based digital CIM with robust destructive read supports accurate attention computation with a subset of selected KV cache, enabling efficient and accurate processing of dynamically sparse KV cache workloads. Besides, by optimizing data mapping scheme, parallel computation across nC strings is enabled, leading to enhanced throughput and avoided write disturbance. Based on the above design, a 3D 3×32×32 FeCap array is experimentally fabricated with ~10ns switching, 10-year retention, 1016endurance and good consistency, and the KV cache-based attention is demonstrated with 6×/315× improved performance and energy efficiency over the state-of-the-art designs, along with high accuracy comparable with full attention, showing its great potential for efficient long-context LLM inference.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Xu_FeRAMKVCache3D_IEDM.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "unspecified", "slm_note": "3D vertical 1T-nC-1T FeRAM KV cache with hybrid analog (similarity, O(1)) and digital CIM attention for long-context LLMs; 3x32x32 FeCap array fabricated. LM scale not stated in abstract.", "added": "2026-10 SLM search", "pdf": null, "priority": 8.93}, {"id": "W4410492466", "short": "AnalogAILLM", "title": "Analog-AI Hardware Accelerators for Low-Latency Transformer-Based Language Models (Invited)", "authors": ["Geoffrey W. Burr", "Hsinyu Tsai", "Irem Boybat", "William Simon", "Julian Büchel", "A. Vasilopoulos", "Pritish Narayanan", "Andrea Fasoli", "Kohji Hosokawa", "Manuel Le Gallo", "Masatoshi Ishii", "Yasuteru Kohda", "Atsuya Okazaki", "A. Chen", "Charles Mackin", "Elena Ferro", "Kaoutar El Maghraoui", "Hadjer Benmeziane", "Timothy Philicelli", "Corey Lammie", "Alexander M. Friz", "Jose Luquin", "S. Jain", "Abu Sebastian", "Vijay Narayanan"], "year": 2025, "venue": "IEEE Custom Integrated Circuits Conference (CICC)", "venue_short": "CICC", "venue_full": "IEEE Custom Integrated Circuits Conference (CICC), 2025", "venue_ok": true, "doi": "https://doi.org/10.1109/cicc63670.2025.10983594", "cites_global": 1, "cat": "11", "seed": false, "devices": ["PCM"], "models": ["BERT/Transformer", "GPT/LLM"], "evidence": "survey", "tldr": "Invited paper reviewing IBM chip-demo and architecture work on analog NVM accelerators for LLM fully-connected layers, quantifying benefits of fully weight-stationary systems and latency factors.", "summary": "Notes that large FC layers dominate Transformer LLMs and analog NVM accelerators do these MACs with high throughput and efficiency. Describes recent chip demos and architectural efforts, quantifies benefits of fully- rather than partially-weight-stationary systems, and discusses what affects token-processing and generation latency. Abstract-only.", "contributions": ["Overview of analog-AI chip and architecture efforts for LLMs", "Quantification of fully weight-stationary advantage", "Latency discussion for prefill and generation"], "claims": [], "results": [], "limitations": ["Invited overview; abstract-only analysis"], "remarks": "Authoritative viewpoint from the main analog-AI group, directly on point for LM inference on PCM. Exact numbers need the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Analog Non-Volatile Memory-based accelerators offer highthroughput and energy-efficient Multiply-Accumulate operations for the large Fully-Connected layers that dominate Transformer-based Large Language Models (LLMs). We describe recent chip-demo and architectural efforts, quantify the unique benefits of Fully- (rather than Partially-) Weight-Stationary systems, and discuss factors affecting latency of token-processing and generation.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Burr_AnalogAILowLatencyLM_CICC.pdf", "analysed": true, "slm": true, "lm_models": [], "param_scale": "unspecified", "slm_note": "Invited overview of analog NVM (PCM) accelerators for Transformer language models; discusses fully vs partially weight-stationary systems and token-processing/generation latency. Specific models and scales not known from abstract.", "added": "2026-10 SLM search", "pdf": null, "priority": 9.11}, {"id": "W4411204550", "short": "HybridReRAMNMC", "title": "Hybrid ReRAM-NMC & SRAM-CiM Matrix Multiplication for Large Language Model", "authors": ["Tao Wang", "Daqi Lin", "Kenshin Yamauchi", "Naoko Misawa", "Chihiro Matsui", "Ken Takeuchi"], "year": 2025, "venue": "", "venue_short": "COOLCHIPS", "venue_full": "2025 IEEE Symposium on Low-Power and High-Speed Chips and Systems (COOL CHIPS)", "venue_ok": true, "doi": "https://doi.org/10.1109/coolchips65488.2025.11018598", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM", "SRAM"], "models": ["GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "Splits activations so <1% go to SRAM-CiM and the rest to ReRAM-NMC, keeping Llama2-7B perplexity increase under 2 for Gaussian and shift ReRAM errors at 6-bit precision.", "summary": "ReRAM nonidealities (conductance shift) hinder LLM deployment on ReRAM CiM. The proposed hybrid places a small fraction of sensitive activations on error-free SRAM-CiM and the remaining on ReRAM-NMC, improving robustness. A hardware architecture with MAC circuit and hybrid-core pipeline is outlined. With 6-bit quantization, Llama2-7B perplexity increases by less than 2 for both error models with SRAM share below 1%. (Abstract only.)", "contributions": ["Hybrid ReRAM-NMC and SRAM-CiM matrix multiplication", "Activation separation to improve robustness", "Hybrid-core pipeline and MAC circuit design"], "claims": [{"claim": "Perplexity rise <2 for Llama2-7B with SRAM share <1%", "support": "abstract", "loc": "Abstract"}], "results": ["Llama2-7B, W6A6: perplexity increase <2 under Gaussian and shift errors, SRAM <1%"], "limitations": ["Abstract only", "Error models simplified; no silicon", "Absolute perplexity and energy numbers unknown"], "remarks": "Directly on target: a 7B LLM under ReRAM error with a cheap mitigation. Perplexity increase of up to 2 is not negligible. Needs real device validation.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "This paper proposes a novel design called hybrid ReRAM-Near-Memory Computing (NMC) & SRAM-Computation-in-Memory (CiM) Matrix Multiplication (MM) for Large Language Model (LLM). Non-volatile memory ReRAM introduces device error (i.e. conductance shift) due to its nonidealities. To enable the deployment of LLM on ReRAM-based CiM, the proposed design enhances model's robustness by separating a small percentage of activations to SRAM-CiM and placing the remaining activations on ReRAM-NMC. Furthermore, a corresponding hardware architecture design is proposed to demonstrate the possible MAC circuit and hybrid-core pipeline. This paper demonstrates that the perplexity increases of Llama27B utilizing 6-bit precision quantization for both activations and weights are smaller than 2 for both gaussian error and shift error with the capacity percentage of SRAM less than 1%.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Wang_HybridReRamNmcSramCim_COOLCHIPS.pdf", "analysed": true, "slm": true, "lm_models": ["Llama2-7B"], "param_scale": "7B", "slm_note": "Llama2-7B with 6-bit weights/activations under ReRAM conductance error (Gaussian and shift); outlier activations routed to SRAM-CiM, rest on ReRAM near-memory computing (ReRAM-NMC). ReRAM used with NMC, so analog-compute status unclear; robustness to device error is the focus.", "added": "2026-10 SLM search", "pdf": null, "priority": 8.0}, {"id": "W4412375723", "short": "ReTern", "title": "ReTern: Exploiting Natural Redundancy and Sign Transformations for Enhanced Fault Tolerance in Compute-in-Memory-Based Ternary LLMs", "authors": ["Akul Malhotra", "Sumeet Kumar Gupta"], "year": 2025, "venue": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems", "venue_short": "TVLSI", "venue_full": "IEEE Transactions on Very Large Scale Integration (VLSI) Systems, 2025", "venue_ok": true, "doi": "https://doi.org/10.1109/tvlsi.2025.3585043", "cites_global": 0, "cat": "11", "seed": false, "devices": ["ReRAM", "FeFET", "SRAM"], "models": ["GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "ReTern combines fault-aware column sign flipping and zero-weight bitcell reprogramming to cut perplexity degradation from stuck-at faults by about 35% on BitNet 700M at 10% SAF, with under 7% overhead.", "summary": "Ternary LLMs have low sparsity, so the earlier TFix scheme (which only fixes SAFs in zero weights using the unused 11 bitcell state) is weak for them. ReTern adds fault-aware sign transformations (FAST): each column is stored as W or -W based on SAF-induced error, with a col_flip bit and two 2:1 muxes negating the subtractor output. Zero-fix handles zero weights; FAST handles +/-1 weights. Evaluated with 20 Monte Carlo SAF injections at 5% and 10% rates on Wikitext, PIQA and ARC-easy; hardware overheads from SPICE/NeuroSim at 7nm.", "contributions": ["Analysis of SAF effects on BitNet b1.58 700M/3B in TCiM", "Identifies TFix limitation for low-sparsity ternary LLMs", "ReTern: FAST plus zero-fix, training-free and offline", "Overhead evaluation for SRAM, ReRAM and FeFET TCiM"], "claims": [{"claim": "~35% (700M) and ~25% (3B) Wikitext perplexity reduction at 10% SAF", "support": "Fig. 6/7 averages", "loc": "Sec. IV-B"}, {"claim": "Overheads <3% energy, <7% latency, <1% area", "support": "macro-level SPICE+NeuroSim", "loc": "Sec. IV-C"}], "results": ["Baseline 700M perplexity ~12 to ~26 at 10% SAF; 3B ~10 to ~15", "ReTern PIQA +4% (700M), +2% (3B); ARC-easy +6% (700M), +5% (3B) at 10% SAF", "TFix and FAST alone each give ~23% (700M) / 15% (3B) perplexity gain at 10% SAF"], "limitations": ["Only stuck-at faults; no analog noise/drift", "Binary-cell TCiM with ADCs; not multi-level analog NVM", "Attention assumed fault-free and digital", "Array size trade-off (col_flip overhead, FAST effectiveness) left to future work", "Simulation only"], "remarks": "One of the few papers on ternary/1-bit LLMs under CiM faults; evidence is credible but simulation-only and the fault model is narrow. Relevant to SLM deployment since ternary models map well to NVM, but residual perplexity after mitigation (still well above ideal) shows faults remain costly.", "basis": "full-text", "pdf_source_url": "arXiv:2506.01140", "abstract": "Ternary large language models (LLMs), which use ternary precision weights and 8-bit activations, have demonstrated competitive performance while significantly reducing the high computational and memory requirements of full-precision LLMs. The energy efficiency and performance of ternary LLMs can be further improved by deploying them on ternary computing-in-memory (TCiM) accelerators, thereby alleviating the von-Neumann bottleneck. However, TCiM accelerators are prone to memory stuck-at faults (SAFs) leading to degradation in model accuracy. This is particularly severe for LLMs due to their low weight sparsity. To boost SAF tolerance of TCiM accelerators, we propose ReTern that is based on 1) fault-aware sign transformations (FASTs) and 2) TCiM bitcell reprogramming exploiting their natural redundancy. The key idea is to use FAST to minimize computation errors due to SAFs in +1/−1 weights, while the natural bitcell redundancy is exploited to target SAFs in 0 weights (zero-fix). Our experiments on BitNet b1.58 700M and 3B ternary LLMs show that our technique furnishes significant fault tolerance, notably ~35% reduction in perplexity on the Wikitext dataset in the presence of faults. These benefits come at the cost of <3%, <7%, and <1% energy, latency, and area overheads, respectively.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Malhotra_ReTern_TVLSI.pdf", "analysed": true, "slm": true, "lm_models": ["BitNet b1.58 700M", "BitNet b1.58 3B"], "param_scale": "0.7B-3B", "slm_note": "Ternary BitNet b1.58 700M and 3B on ternary CiM arrays (64x64, SRAM/ReRAM/FeFET bitcells, two binary cells per ternary weight, ADC readout); fault tolerance to stuck-at faults. Feed-forward layers in CiM, attention digital. Binary cells with analog bitline accumulation.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2025_Malhotra_ReTern_TVLSI.pdf", "priority": 8.0}, {"id": "W4416728625", "short": "PIM-LLM", "title": "Accelerating 1-Bit Llms Via in-Memory Computing Architectures", "authors": ["Jinendra Malekar", "Ramtin Zand"], "year": 2025, "venue": "Conference proceedings", "venue_short": "MWSCAS", "venue_full": "2025 IEEE 68th International Midwest Symposium on Circuits and Systems (MWSCAS)", "venue_ok": true, "doi": "https://doi.org/10.1109/mwscas53549.2025.11244527", "cites_global": 0, "cat": "11", "seed": false, "devices": ["RRAM"], "models": ["GPT/LLM"], "evidence": "simulation", "tldr": "Hybrid analog-PIM plus digital-systolic architecture for 1-bit LLMs, up to ~80x tokens/s and 70% better tokens/J than conventional digital accelerators.", "summary": "In 1-bit LLMs the projection-layer MatMuls are binary/ternary and dominate compute, while attention MatMuls need higher precision (INT8). PIM-LLM maps projection weights to RRAM crossbars (256x256, 8-bit ADCs, differential pairs) for analog MVM, and sends attention head activation-activation MatMuls to a digital TPU-like systolic array. Latency and energy are simulated with MNSIM 2.0 for the PIM part, using GPT-2 350M through OPT-6.7B at several context lengths. It reports up to ~80x tokens/s and 70% tokens/J gains over digital baselines and at least 2x GOPS and 5x GOPS/W over prior PIM LLM accelerators.", "contributions": ["Hybrid analog PIM + digital systolic partitioning by precision need for 1-bit LLMs", "Latency/energy evaluation across GPT-2 and OPT sizes and context lengths", "Comparison with TransPIM and HARDSEA"], "claims": [{"claim": "Up to ~80x tokens/s and 70% tokens/J vs conventional accelerators", "support": "OPT-6.7B 79.2x speedup at l=128", "loc": "Abstract, results"}, {"claim": "At least 2x GOPS and 5x GOPS/W over prior PIM LLM accelerators", "support": "abstract", "loc": "Table comparison"}], "results": ["GPT-2 350M 11.6x and OPT-6.7B 79.2x speedup at context 128", "Speedup shrinks at long context (attention digital array dominates latency)", "ADC energy share <1% in reported breakdown"], "limitations": ["Analytical/simulated (MNSIM 2.0), no silicon", "Ignores analog non-idealities and accuracy impact", "Attention stays digital and dominates at long context", "Authors note applicability beyond tested models is untested"], "remarks": "Reasonable architectural partitioning argument, but accuracy under RRAM noise is not evaluated, so throughput gains are optimistic. The 1-bit weight assumption eases analog precision demands. Used the arXiv version (PIM-LLM, 2504.01994) as it matches the abstract.", "basis": "full-text", "pdf_source_url": "https://arxiv.org/pdf/2504.01994", "abstract": "In this paper, we present a novel hybrid computing architecture designed to accelerate inference in 1-bit large language models (LLMs). Our approach combines the strengths of analog in-memory computing (IMC) and digital systolic arrays to address the diverse precision requirements across different layers of 1-bit LLMs. Specifically, we utilize analog IMC to accelerate low-precision matrix multiplication (MatMul) operations within the projection layers, which are naturally amenable to extreme quantization. Meanwhile, digital systolic arrays are employed to efficiently handle high-precision MatMul operations in the attention heads, preserving accuracy where precision is most critical. By partitioning the computational workload based on precision needs, our hybrid architecture increases throughput and energy efficiency. Experimental evaluations demonstrate that our design delivers up to an$80 \\times$improvement in tokens processed per second and achieves a 70 % increase in energy efficiency (tokens per joule) when compared to conventional digital hardware accelerators.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2025_Malekar_PimLlm_MWSCAS.pdf", "analysed": true, "slm": true, "lm_models": ["GPT-2 350M", "OPT-125M..6.7B (1-bit)"], "param_scale": "350M-6.7B", "slm_note": "Hybrid analog RRAM-crossbar PIM plus digital systolic array for 1-bit (BitNet-style binary/ternary) decoder-only LLMs; evaluated on GPT-2 350M up to OPT-6.7B. Projection-layer MatMuls run as analog MVM on 256x256 RRAM crossbars; attention MatMuls on digital systolic arrays.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2025_Malekar_PimLlm_MWSCAS.pdf", "priority": 8.0}, {"id": "W4403534421", "short": "LLM on Memristor Crossbar", "title": "Enabling Energy-Efficient Deployment of Large Language Models on Memristor Crossbar: A Synergy of Large and Small", "authors": ["Zhehui Wang", "Tao Luo", "Cheng Liu", "Weichen Liu", "Rick Siow Mong Goh", "Weng‐Fai Wong"], "year": 2024, "venue": "IEEE Transactions on Pattern Analysis and Machine Intelligence", "venue_short": "TPAMI", "venue_full": "IEEE Transactions on Pattern Analysis and Machine Intelligence (2024)", "venue_ok": true, "doi": "https://doi.org/10.1109/tpami.2024.3483654", "cites_global": 11, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["BERT", "GPT/LLM", "Transformer", "ResNet"], "evidence": "simulation", "tldr": "Proposes a two-crossbar architecture (small reconfigurable resistor-based 'computation crossbars' plus large memory-bank-style 'dense' RRAM crossbars) that decomposes all LLM operations into a standard sub-operation, claiming up to 39x area and 18x energy savings over conventional memristor crossbars and 68x lower area-delay product than TPU/GPU on BERT-Large.", "summary": "The paper targets three obstacles to running LLMs on memristor crossbars: model size exceeding crossbar capacity (ADC/DAC-dominated area), non-weight-stationary attention MatMuls, and nonlinear ops (softmax, LayerNorm). It decomposes every LLM operation into a standardized sub-operation F(X·col(Y)) and executes it on a 'computation crossbar' (128x128) in which the cells are fixed resistors whose on/off state is set by transistor switches driven by activations encoded in a balanced base-(2^(S+1)-1) numeral system (base-7 by default), while weights are applied as DAC inputs; a digital unit at the column output computes the nonlinear function F. All model weights live in 'dense crossbars' (1k x 64k, organised like a DRAM bank, 2 bits/cell, 1-bit DAC/2-bit ADC) and are streamed into the computation crossbar, so the same small compute array handles both weight-stationary and non-weight-stationary products. Evaluation uses ISAAC-style component models at 32 nm and a PyTorch noise/quantization simulation on BERT-Base/Large (GLUE), Phi-1.5 and GPT-2, with area scaling projections up to GPT-3.", "contributions": ["Decomposition of all LLM operations (QKV, attention MatMuls, softmax, FFN, LayerNorm) into one standardized sub-operation executable on a crossbar plus an output function unit.", "A reconfigurable computation crossbar using fixed resistors switched by balanced-base-encoded activations, avoiding per-input memristor programming for non-weight-stationary products.", "Separation of weight storage (dense, memory-bank-like RRAM arrays with heavily shared peripherals) from computation, so a whole LLM can sit on one chip/package.", "Design-space study of the encoding base (S=1..7) and scalability analysis to GPT-2, T5, LLaMA and GPT-3."], "claims": [{"claim": "Conventional memristor crossbars are peripheral-dominated, limiting effective density for LLMs.", "support": "Approximately 95% of conventional crossbar area occupied by DACs and ADCs; GPT-3 would need 2777 ISAAC chips.", "loc": "Sec. 1, Sec. 6.3"}, {"claim": "The proposed architecture greatly reduces area versus multi-bit and single-bit crossbar designs at equal delay.", "support": "~6x (multi-bit) and ~39x (single-bit) area savings on average.", "loc": "Sec. 6.3, Fig. 12(a)"}, {"claim": "The proposed architecture reduces energy versus conventional crossbars.", "support": "~18x (multi-bit) and ~3x (single-bit) energy reductions on average.", "loc": "Sec. 6.4, Fig. 12(b)"}, {"claim": "It outperforms TPUv4 and A100 on BERT-Large.", "support": "At least 68x lower area-delay product and 69% energy savings (Table 10: ADP 0.03 vs 2.24/2.04 mm^2·s; energy 20.44 vs 71.71/65.84 mJ).", "loc": "Sec. 6.5, Table 10"}, {"claim": "Accuracy loss is negligible under simulated device noise.", "support": "BERT-Base/Large GLUE scores within ~±1 point of GPU baseline; Phi-1.5 and GPT-2 benchmark scores similar to baseline; robust to 5x (2-bit) or 18x (1-bit) noise amplitude.", "loc": "Sec. 6.2, Tables 8-9"}, {"claim": "Area scales far more gently with model size than prior crossbar designs.", "support": "For GPT-3, area overhead is ~1/51 of the previous architecture.", "loc": "Sec. 6.7, Fig. 14"}], "results": ["Up to 39x area and 18x energy reduction vs conventional (single-bit / multi-bit) memristor crossbars.", "BERT-Large: >=68x lower area-delay product and 69% lower energy than TPUv4/A100 (32 nm vs 7 nm comparison).", "51x lower area overhead than ISAAC-style architecture for GPT-3 (175B).", "Base-3 (S=1) and base-7 (S=2) encodings minimize the scale-cycle product for INT8 activations.", "Reported energy efficiency of 0.27 pJ/OP at 32 nm vs ~0.62 pJ/OP estimated for TPUv4 at 7 nm."], "limitations": ["Purely simulated (ISAAC/NeuroSim-style component models at 32 nm); no silicon or device experiments for the proposed computation crossbar.", "Dense crossbar is effectively a digital NVM memory bank; weights must be streamed into compute arrays each use, so the 'in-memory' benefit for weights is reduced and bandwidth assumptions (HBM3-like 819 Gbps, 1000 GBps cache) are optimistic and only bounded.", "Comparisons with PRIME/ISAAC/PipeLayer include only weight-stationary modules for the baselines; TPU/GPU comparisons cross technology nodes.", "Noise model is RTN-style fluctuation with <5% signal level; write endurance and dense-array programming costs are not deeply analysed.", "Some reported figures are hard to interpret (e.g. energy per operation computed from '20.7 mJ for 77.3 operations')."], "remarks": "An ambitious system-level proposal that sidesteps the non-weight-stationary problem by making the analog array hold constants and letting activations act as switch controls, which is closer to a digit-serial mixed-signal MAC engine than to classic weight-stationary analog IMC. The large headline factors depend heavily on separating storage from compute and on favourable modelling choices; claims of single-chip GPT-3 are projections. For crossbar mapping research it is an interesting alternative to writing K/V into NVM (cf. ClipFormer's write-noise concerns), but evidence strength is modest.", "basis": "full-text", "pdf_source_url": "", "abstract": "Large language models (LLMs) have garnered substantial attention due to their promising applications in diverse domains. Nevertheless, the increasing size of LLMs comes with a significant surge in the computational requirements for training and deployment. Memristor crossbars have emerged as a promising solution, which demonstrated a small footprint and remarkably high energy efficiency in computer vision (CV) models. Memristors possess higher density compared to conventional memory technologies, making them highly suitable for effectively managing the extreme model size associated with LLMs. However, deploying LLMs on memristor crossbars faces three major challenges. First, the size of LLMs increases rapidly, already surpassing the capabilities of state-of-the-art memristor chips. Second, LLMs often incorporate multi-head attention blocks, which involve non-weight stationary multiplications that traditional memristor crossbars cannot support. Third, while memristor crossbars excel at performing linear operations, they are not capable of executing complex nonlinear operations in LLM such as softmax and layer normalization. To address these challenges, we present a novel architecture for the memristor crossbar that enables the deployment of state-of-the-art LLM on a single chip or package, eliminating the energy and time inefficiencies associated with off-chip communication. Our testing on BERT showed negligible accuracy loss. Compared to traditional memristor crossbars, our architecture achieves enhancements of up to in area overhead and in energy consumption. Compared to modern TPU/GPU systems, our architecture demonstrates at least a reduction in the area-delay product and a significant 69% energy consumption reduction.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2024_Wang_LLMOnMemristorCrossbar_TPAMI.pdf", "analysed": true, "slm": true, "lm_models": ["BERT-Base", "BERT-Large", "Phi-1.5", "GPT-2", "GPT-3 (area projection only)"], "param_scale": "110M–340M (BERT), 1.3B (Phi-1.5), up to 175B (GPT-3, projection)", "slm_note": "BERT-Base/Large, Phi-1.5 and GPT-2 evaluated with simulated memristor crossbar noise and 32 nm area/energy models, with GPT-3 (175B) only as an area-scaling projection.", "pdf": "11_Small_Language_Models_on_AIMC/2024_Wang_LLMOnMemristorCrossbar_TPAMI.pdf", "priority": 8.76}, {"id": "W4392240059", "short": "H3DTransformer", "title": "H3D-Transformer: A Heterogeneous 3D (H3D) Computing Platform for Transformer Model Acceleration on Edge Devices", "authors": ["Yandong Luo", "Shimeng Yu"], "year": 2024, "venue": "ACM Transactions on Design Automation of Electronic Systems", "venue_short": "TODAES", "venue_full": "ACM Transactions on Design Automation of Electronic Systems, 2024", "venue_ok": true, "doi": "https://doi.org/10.1145/3649219", "cites_global": 27, "cat": "11", "seed": false, "devices": ["FeFET"], "models": ["BERT/Transformer", "GPT/LLM"], "evidence": "simulation", "tldr": "Heterogeneous 3D interposer design pairing mixed-signal CIM cubes and digital TPUs for transformer MatMuls reaches 10 TOPS/W on BERT/GPT-2, 2.6-3.1x above a 7nm TPU + stacked FeFET baseline.", "summary": "Argues GB-class NLP transformers exceed single-chip CIM accelerators. Proposes an interposer with several 3D memory/logic hybrid cubes optimized for different MatMul workloads, and an approximate computing scheme splitting work between mixed-signal CIM and digital TPUs. System-level evaluation on BERT and GPT-2 gives about 10 TOPS/W. Abstract-only.", "contributions": ["Heterogeneous 3D interposer accelerator for transformers", "Approximate scheme mixing mixed-signal CIM and digital TPU", "System evaluation on BERT and GPT-2"], "claims": [], "results": ["~10 TOPS/W on BERT and GPT-2", "2.6x-3.1x over 7nm TPU with stacked FeFET memory"], "limitations": ["System-level simulation only", "Accuracy impact of approximation not known from abstract"], "remarks": "Relevant as an architectural study placing LM weights in stacked NVM with partial analog CIM; results are simulated and baseline-dependent.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Prior hardware accelerator designs primarily focused on single-chip solutions for 10 MB-class computer vision models. The GB-class transformer models for natural language processing (NLP) impose challenges on existing accelerator design due to the massive number of parameters and the diverse matrix multiplication (MatMul) workloads involved. This work proposes a heterogeneous 3D-based accelerator design for transformer models, which adopts an interposer substrate with multiple 3D memory/logic hybrid cubes optimized for accelerating different MatMul workloads. An approximate computing scheme is proposed to take advantage of heterogeneous computing paradigms of mixed-signal compute-in-memory (CIM) and digital tensor processing units (TPU). From the system-level evaluation results, 10 TOPS/W energy efficiency is achieved for the BERT and GPT2 model, which is about 2.6× ∼ 3.1× higher than the baseline with 7 nm TPU and stacked FeFET memory.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2024_Luo_H3DTransformer_TODAES.pdf", "analysed": true, "slm": true, "lm_models": ["BERT", "GPT-2"], "param_scale": "~100M-1.5B", "slm_note": "Evaluates BERT and GPT-2 on a heterogeneous 3D system combining mixed-signal CIM (FeFET-based per abstract) with digital TPUs; some MatMuls are in-memory approximate compute, others digital. Model scale up to GPT-2 (hundreds of millions of params).", "added": "2026-10 SLM search", "pdf": null, "priority": 11.11}, {"id": "W4409282487", "short": "RoCR", "title": "Robust Implementation of Retrieval-Augmented Generation on Edge-based Computing-in-Memory Architectures", "authors": ["Ruiyang Qin", "Zheyu Yan", "Dewen Zeng", "Zhenge Jia", "Dancheng Liu", "Jianbo Liu", "Ahmed Abbasi", "Zhi Zheng", "Ningyuan Cao", "Kai Ni", "Jinjun Xiong", "Yiyu Shi"], "year": 2024, "venue": "", "venue_short": "ICCAD", "venue_full": "43rd IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2024)", "venue_ok": true, "doi": "https://doi.org/10.1145/3676536.3676674", "cites_global": 10, "cat": "11", "seed": false, "devices": ["ReRAM", "FeFET"], "models": ["Transformer/BERT", "GPT/LLM"], "evidence": "algorithm+simulation", "tldr": "RoCR trains the sentence-embedding model with contrastive learning and noise-aware training so that CiM-based retrieval stays accurate under RRAM/FeFET variation, improving RAG performance by up to 35%.", "summary": "Edge LLMs personalize via RAG, but retrieval over growing profile data is slow. The authors propose storing document embeddings in NVM CiM arrays and doing MIPS in-situ. Device variation (Gaussian, per-level sigma from 2 RRAM and 3 FeFET device models) breaks retrieval, so RoCR combines triplet contrastive learning, data construction with explicit (CDE) or implicit (CDI) labels using dropout-based positives/negatives, and flexible noise-aware training that reshapes embeddings to 64-d int8 and injects device noise. On five LaMP-style datasets with four LLM generators, RoCR beats SWV, CxDNN and CorrectNet baselines on most metrics. No hardware overhead since only the embedding model changes.", "contributions": ["First use of CiM to accelerate RAG for edge LLMs", "Contrastive-learning data construction for explicit and implicit user data (CDE/CDI)", "Flexible noise-aware training reshaping embeddings to CiM dimension/precision", "Evaluation on five NVM device models and five datasets with four LLMs"], "claims": [{"claim": "RoCR improves RAG performance on multiple CiM devices by up to 35%", "support": "Abstract/Intro; Table 1", "loc": "Sec. 1, Table 1"}, {"claim": "Unprotected MIPS accuracy collapses toward random guessing as device noise rises", "support": "Fig. 2 preliminary study", "loc": "Fig. 2"}, {"claim": "No inference-time hardware overhead", "support": "Only the embedding model weights change", "loc": "Sec. 4"}], "results": ["sigma=0.1 default, embeddings 64-d int8, 2000 anchors, k=5, 5 runs averaged", "Table 1 e.g. Device-1 Citation acc 0.4401 (vanilla RAG) vs 0.5536 (RoCR-CDE)", "Gains persist for sigma from 0 to 0.15 on Device-1 (DBLP)"], "limitations": ["Only temporal programming variation modeled (Gaussian), no ADC/IR-drop/drift", "LLM generator not on CiM", "No measured silicon or energy/latency evaluation (50 ms retrieval is cited)", "Some metrics (MAE/RMSE) show baselines better; gains are mixed"], "remarks": "Relevant to the SLM-on-NVM theme only at the edges: it shows a robustness recipe for an embedding retriever, not for LM weights. The noise model is simple and results are task-dependent. Useful as a RAG-on-CiM precedent and as a source of RRAM/FeFET variation parameters.", "basis": "full-text", "pdf_source_url": "arXiv:2405.04700 (already in txt)", "abstract": "Large Language Models (LLMs) deployed on edge devices learn through fine-tuning and updating a certain portion of their parameters. Although such learning methods can be optimized to reduce resource utilization, the overall required resources remain a heavy burden on edge devices. Instead, Retrieval-Augmented Generation (RAG), a resource-efficient LLM learning method, can improve the quality of the LLM-generated content without updating model parameters. However, the RAG-based LLM may involve repetitive searches on the profile data in every user-LLM interaction. This search can lead to significant latency along with the accumulation of user data. Conventional efforts to decrease latency result in restricting the size of saved user data, thus reducing the scalability of RAG as user data continuously grows. It remains an open question: how to free RAG from the constraints of latency and scalability on edge devices? In this paper, we propose a novel framework to accelerate RAG via Computing-in-Memory (CiM) architectures. It accelerates matrix multiplications by performing in-situ computation inside the memory while avoiding the expensive data transfer between the computing unit and memory. Our framework, Robust CiM-backed RAG (RoCR), utilizing a novel contrastive learning-based training method and noise-aware training, can enable RAG to efficiently search profile data with CiM. To the best of our knowledge, this is the first work utilizing CiM to accelerate RAG.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2024_Qin_RoCR_ICCAD.pdf", "analysed": true, "slm": true, "lm_models": ["all-MiniLM-L6-v2 (retriever)", "Gemma-2B", "Phi-2", "Mistral-7B", "Llama-2-3B"], "param_scale": "22M embedding model; 2B-7B generators (digital)", "slm_note": "RAG for edge LLMs: the all-MiniLM-L6-v2 sentence-embedding matrix is stored in NVM CiM (RRAM/FeFET models) and max-inner-product search runs in-memory with device noise. Generator LLMs (Gemma-2B, Phi-2, Mistral-7B, Llama-2-3B) run digitally and are only the downstream consumer; the analog part is the retriever, not the LM.", "added": "2026-10 SLM search", "pdf": "11_Small_Language_Models_on_AIMC/2024_Qin_RoCR_ICCAD.pdf", "priority": 9.63}, {"id": "W4381733878", "short": "MGen", "title": "MGen: A Framework for Energy-Efficient In-ReRAM Acceleration of Multi-Task BERT", "authors": ["Myeonggu Kang", "Hyein Shin", "Junkyum Kim", "Lee‐Sup Kim"], "year": 2023, "venue": "IEEE Transactions on Computers", "venue_short": "TC", "venue_full": "IEEE Transactions on Computers", "venue_ok": true, "doi": "https://doi.org/10.1109/tc.2023.3288749", "cites_global": 3, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["BERT", "Transformer"], "evidence": "algorithm+simulation", "tldr": "MGen is a framework that generates reduced-redundancy multi-task BERT models and schedules their execution order to cut the energy (not just area) cost of running multi-task BERT on ReRAM-based accelerators, reporting up to 4.4x energy-efficiency gains.", "summary": "The paper addresses multi-task BERT deployment on ReRAM-based DNN accelerators: prior work reduced the area overhead of storing multiple task-specific BERT models in ReRAM crossbars, but computation volume (and hence energy) stays the same regardless of parameter-sharing, so energy consumption remains high. The authors analyze redundancies inherent to multi-task BERT together with the computational characteristics of ReRAM-based accelerators, then propose a 'model generator' that produces optimized BERT variants supporting multiple tasks while reducing the number of computations and preserving task accuracy. A companion 'task scheduler' reorders execution of multiple tasks' inference to better exploit the generated models' structure on the ReRAM accelerator. The framework is shown to be composable with prior area-reduction multi-task BERT techniques, jointly achieving smaller area and higher energy efficiency, with a reported maximum 4.4x energy-efficiency improvement over baseline.", "contributions": ["Identifies that prior multi-task BERT work on ReRAM accelerators reduces area/parameter count but not computation volume or energy", "Model generator: produces optimized multi-task BERT models that reduce computation while preserving algorithmic (task) performance", "Task scheduler: reorders multi-task execution to better exploit the generated models' structure for energy efficiency on ReRAM hardware", "Shows the framework composes with prior area-efficient multi-task BERT accelerator work for combined area and energy gains"], "claims": [{"claim": "The proposed framework achieves up to 4.4x higher energy efficiency than the baseline ReRAM multi-task BERT accelerator", "support": "maximally 4.4x higher energy efficiency over baseline", "loc": "Abstract"}], "results": ["Up to 4.4x energy-efficiency improvement over baseline multi-task BERT ReRAM acceleration"], "limitations": ["Analysis based on abstract only (full text not accessible); specific benchmark tasks, accuracy deltas, and ReRAM simulator/architecture assumptions could not be verified", "Energy-efficiency gains are relative to the authors' own baseline multi-task BERT ReRAM setup, so absolute comparison to other accelerator families is unclear from the abstract alone"], "remarks": "This is a software/mapping-level contribution (model generation + task scheduling) layered on top of ReRAM-based transformer accelerators, directly building on the same group's earlier area-efficient multi-task BERT framework (Kang et al., W4200149283) and the ReRAM transformer accelerator literature (ReTransformer, Kang's prior ReRAM transformer framework). Its significance for analog/PIM mapping is in treating energy, not just crossbar area, as the optimization target for multi-task LLM-style deployment — but with abstract-only access the specific mechanisms behind the 4.4x figure (e.g., which redundancies are exploited, what accuracy is preserved) could not be confirmed.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Recently, multiple transformer models, such as BERT, have been utilized together to support multiple natural language processing (NLP) tasks in a system, also known as multi-task BERT. Multi-task BERT with very high weight parameters increases the area requirement of a processing in resistive memory (ReRAM) architecture, and several works have attempted to address this model size issue. Despite the reduced parameters, the number of multi-task BERT computations remains the same, leading to massive energy consumption in ReRAM-based deep neural network (DNN) accelerators. Therefore, we suggest a framework for better energy efficiency during the ReRAM acceleration of multi-task BERT. First, we analyze the inherent redundancies of multi-task BERT and the computational properties of the ReRAM-based DNN accelerator, after which we propose what is termed the model generator, which produces optimal BERT models supporting multiple tasks. The model generator reduces multi-task BERT computations while maintaining the algorithmic performance. Furthermore, we present task scheduler, which adjusts the execution order of multiple tasks, to run the produced models efficiently. As a result, the proposed framework achieves maximally 4.4× higher energy efficiency over the baseline, and it can also be combined with the previous multi-task BERT works to achieve both a smaller area and higher energy efficiency.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2023_Kang_MGen_TC.pdf", "analysed": true, "slm": true, "lm_models": ["BERT (multi-task)"], "param_scale": "BERT-scale (size not specified)", "slm_note": "Multi-task BERT models on a ReRAM-based digital/analog accelerator model; specific BERT size not stated in the available text.", "pdf": null, "priority": 7.92}, {"id": "W4391594670", "short": "AnalogAI-Transformers", "title": "Design of Analog-AI Hardware Accelerators for Transformer-based Language Models (Invited)", "authors": ["Geoffrey W. Burr", "Hsinyu Tsai", "William Simon", "Irem Boybat", "Stefano Ambrogio", "C.-E. Ho", "Z.-W. Liou", "Malte J. Rasch", "Julian Büchel", "Pritish Narayanan", "T. Gordon", "Shilpa Jain", "T. M. Levin", "Kohji Hosokawa", "Manuel Le Gallo", "H. Smith", "Masatoshi Ishii", "Yasuteru Kohda", "A. Chen", "Charles Mackin", "Andrea Fasoli", "K. ElMaghraoui", "R. Muralidhar", "Atsuya Okazaki", "C. -T. Chen", "Martin M. Frank", "Corey Lammie", "A. Vasilopoulos", "Alexander M. Friz", "Jose Luquin", "S. Teehan", "Ishtiaq Ahsan", "Abu Sebastian", "Vijay Narayanan"], "year": 2023, "venue": "Technical digest - International Electron Devices Meeting/Technical digest", "venue_short": "IEDM", "venue_full": "IEEE International Electron Devices Meeting (IEDM), 2023 (invited)", "venue_ok": true, "doi": "https://doi.org/10.1109/iedm45741.2023.10413767", "cites_global": 10, "cat": "11", "seed": false, "devices": ["PCM"], "models": ["Transformer/BERT", "GPT/LLM"], "evidence": "survey", "tldr": "IBM invited review of architecture, wafer-scale test, chip demos and hardware-aware training for analog-NVM Transformer accelerators, arguing fully weight-stationary systems give unique throughput and latency benefits.", "summary": "The paper argues that analog NVM crossbars suit the large fully-connected layers that dominate Transformer LLMs. It surveys the authors' efforts across architecture design, wafer-scale device testing, fabricated chip demos (e.g. 14nm PCM chips) and hardware-aware training. A central message is quantifying the raw-throughput and latency benefits of fully weight-stationary systems (all weights resident on-chip) versus partially weight-stationary ones that must reload weights. Details beyond the abstract were not available (abstract-only).", "contributions": ["Overview of IBM analog-AI work toward Transformer LLM acceleration", "Quantifies throughput/latency benefit of fully vs partially weight-stationary designs", "Links wafer-scale PCM testing, chip demos and hardware-aware training into one design argument"], "claims": [{"claim": "Fully weight-stationary analog-NVM systems offer unique raw-throughput and latency benefits over partially weight-stationary ones", "support": "stated in abstract", "loc": "Abstract"}], "results": ["No numbers verifiable from abstract"], "limitations": ["Invited overview; largely synthesises prior IBM work", "Full-weight-stationary requires enough on-chip NVM for the entire model, which scales poorly for large LLMs", "Attention and non-linear ops remain digital (not covered in abstract)"], "remarks": "Useful framing paper from the leading analog-AI group, and a good pointer to the weight-stationary argument that favors SLMs (fit entirely on chip). Evidence is a synthesis and could not be checked in detail here; read the full paper for model sizes and projected numbers.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "Analog Non-Volatile Memory-based accelerators offer high-throughput and energy-efficient Multiply-Accumulate operations for the large Fully-Connected layers that dominate Transformer-based Large Language Models. We describe architectural, wafer-scale testing, chip-demo, and hardware-aware training efforts towards such accelerators, and quantify the unique raw-throughput and latency benefits of Fully-(rather than Partially-) Weight-Stationary systems.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2023_Burr_AnalogAITransformers_IEDM.pdf", "analysed": true, "slm": true, "lm_models": ["Transformer LLMs (unspecified)"], "param_scale": "unspecified (BERT to LLM scale)", "slm_note": "Invited overview from IBM on analog-NVM (PCM) accelerators targeting the large fully-connected layers of Transformer-based LLMs; compute is analog in-memory MAC. Abstract-only: specific model sizes not verified; scope is BERT/LLM-class Transformers, with chip-demo evidence from IBM's PCM chips.", "added": "2026-10 SLM search", "pdf": null, "priority": 9.13}, {"id": "W4200149283", "short": "Area-Efficient Multi-Task BERT", "title": "A Framework for Area-efficient Multi-task BERT Execution on ReRAM-based Accelerators", "authors": ["Myeonggu Kang", "Hyein Shin", "Jaekang Shin", "Lee‐Sup Kim"], "year": 2021, "venue": "", "venue_short": "ICCAD", "venue_full": "IEEE/ACM International Conference on Computer-Aided Design (ICCAD 2021)", "venue_ok": true, "doi": "https://doi.org/10.1109/iccad51958.2021.9643471", "cites_global": 4, "cat": "11", "seed": false, "devices": ["ReRAM"], "models": ["BERT", "Transformer"], "evidence": "simulation", "tldr": "A framework that decomposes each fine-tuned multi-task BERT model relative to a shared base model and compresses the decomposed weights with a two-stage, ReRAM-property-aware compressor, cutting the ReRAM-based accelerator area to 0.26x of baseline without retraining.", "summary": "Running several fine-tuned BERT models ('multi-task BERT') on a ReRAM-based accelerator multiplies crossbar area because each task needs its own fine-tuned weight set. The authors decompose each task's fine-tuned model relative to a shared base model, then apply a two-stage weight compressor designed around ReRAM-crossbar properties to shrink the decomposed (task-specific) weight deltas, with a profiler that automatically generates the compressor's hyperparameters per task/layer. Because the base model is shared across tasks and only the (now compressed) decomposed deltas need to be stored per task, total accelerator area drops sharply. The method requires no additional training/fine-tuning procedure, and the paper reports 0.26x area relative to a non-compressed multi-task baseline while preserving algorithmic (task) accuracy.", "contributions": ["A decomposition scheme that expresses each task's fine-tuned BERT weights relative to a shared base model, exposing low-redundancy task-specific deltas", "A two-stage weight compressor tailored to the properties of ReRAM-based crossbar accelerators", "An automatic profiler that generates the compressor's hyperparameters per model/layer", "A full framework that reduces multi-task BERT accelerator area without any additional training or fine-tuning step"], "claims": [{"claim": "The proposed framework reduces ReRAM accelerator area for multi-task BERT execution to 0.26x of the baseline while maintaining algorithmic (task) performance.", "support": "0.26x area reduction reported with no additional training procedure", "loc": "Abstract (full text not available)"}], "results": ["0.26x area versus baseline ReRAM-based multi-task BERT accelerator, with algorithmic performance maintained (per abstract)"], "limitations": ["Analysis is abstract-only (full text not accessible from this machine; IEEE Xplore paywalled, no legitimate open copy found) -- per-task accuracy deltas, number of tasks/benchmarks evaluated, and detailed compressor/profiler mechanics are not verifiable here", "As an ICCAD architecture paper, results are expected to be simulation-based rather than measured silicon, but this cannot be confirmed from the abstract alone"], "remarks": "Addresses a real deployment problem -- multi-task BERT serving multiplies per-task fine-tuned weight storage, which is especially costly on area-constrained ReRAM crossbars -- with a retraining-free, base-model-relative compression approach. Later work from the same group (MGen, 2023) explicitly builds on this area-efficiency framework for energy-efficient in-ReRAM multi-task BERT acceleration, suggesting this paper established a useful decomposition/compression baseline for multi-task Transformer-on-ReRAM deployment, though its own evaluation depth could not be verified without the full text.", "basis": "abstract-only", "pdf_source_url": "", "abstract": "With the superior algorithmic performances, BERT has become the de-facto standard model for various NLP tasks. Accordingly, multiple BERT models have been adopted on a single system, which is also called multi-task BERT. Although the ReRAM-based accelerator shows the sufficient potential to execute a single BERT model by adopting in-memory computation, processing multi-task BERT on the ReRAM-based accelerator extremely increases the overall area due to multiple fine-tuned models. In this paper, we propose a framework for area-efficient multi-task BERT execution on the ReRAM-based accelerator. Firstly, we decompose the fine-tuned model of each task by utilizing the base-model. After that, we propose a two-stage weight compressor, which shrinks the decomposed models by analyzing the properties of the ReRAM-based accelerator. We also present a profiler to generate hyper-parameters for the proposed compressor. By sharing the base-model and compressing the decomposed models, the proposed framework successfully reduces the total area of the ReRAM-based accelerator without an additional training procedure. It achieves a 0.26 x area than baseline while maintaining the algorithmic performances.", "review": [], "pdf_expected": "11_Small_Language_Models_on_AIMC/2021_Kang_AreaEfficientMultiTaskBERT_ICCAD.pdf", "analysed": true, "slm": true, "lm_models": ["BERT (multi-task)"], "param_scale": "BERT-scale (size not specified)", "slm_note": "Multi-task BERT models on a ReRAM-based accelerator model; specific BERT size not stated in the available text.", "pdf": null, "priority": 9.42}], "edges": [{"s": "W2605257365", "t": "W1542981317", "ctx": "Since this approach can be several orders of magnitude more efficient than CMOS ASIC approaches in terms of both speed and power [3-6], many studies proposed neural network accelerators based on emerging NVM crossbar array [9-12].", "purpose": "background"}, {"s": "W2605257365", "t": "W1937359183", "ctx": "Since this approach can be several orders of magnitude more efficient than CMOS ASIC approaches in terms of both speed and power [3-6], many studies proposed neural network accelerators based on emerging NVM crossbar array [9-12].", "purpose": "background"}, {"s": "W2605257365", "t": "W4243519499", "ctx": "To address the issue, many dedicated accelerators for vector-matrix multiplications have been proposed [3-6].", "purpose": "background"}, {"s": "W2605257365", "t": "W4254672563", "ctx": "To address the issue, many dedicated accelerators for vector-matrix multiplications have been proposed [3-6].", "purpose": "background"}, {"s": "W2613989746", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2613989746", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2625840880", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2736591611", "t": "W1542981317", "ctx": "In the future, we will further support the simulation for other structures like dynamic synaptic properties [22], on-chip Training method [51], and inner-layer pipeline structure [7].", "purpose": "background"}, {"s": "W2736591611", "t": "W4243519499", "ctx": "Therefore, several memristor-crossbar-based neuromorphic systems and accelerators have been developed to improve energy efficiency significantly [6], [7].", "purpose": "background"}, {"s": "W2736591611", "t": "W4254672563", "ctx": "Therefore, the matrix-vector multiplications can be efficiently processed by memristor crossbars [6].", "purpose": "background"}, {"s": "W2740220207", "t": "W1937359183", "ctx": "In order to model these effects on the training of the algorithm, statistical data is extracted from the repeated pulsing between GMIN and GMAX following the methodology first presented in Burr et al [27, 36].", "purpose": "uses-method-or-tool"}, {"s": "W2740220207", "t": "W4243519499", "ctx": "The ISAAC architecture is a full neural execution unit similar to DaDianNao but using ReRAM crossbars to store and process weights for CNN inference [9].", "purpose": "background"}, {"s": "W2740220207", "t": "W4254672563", "ctx": "PRIME is a new pipelined architecture and a method of efficiently processing neural network inference with analog weights. PRIME provides an energy advantage of three orders of magnitude [10].", "purpose": "background"}, {"s": "W2765081478", "t": "W2795127895", "ctx": "Possible avenues are improving the memristive device characteristics with respect to variability and conductance noise33 , mapping a single column of the matrix to multiple physical columns of an array encoding different bits (Supplementary Note III), and using error-correction techniques within the computational memory unit41 .", "purpose": "background"}, {"s": "W2765081478", "t": "W4243519499", "ctx": "Research on these devices has already led to the development of massively parallel, memory-centric hardware accelerators with applications ranging from image processing to healthcare19–22 .", "purpose": "background"}, {"s": "W2782791387", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2782791387", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2785141883", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2785141883", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2785141883", "t": "W2787453651", "ctx": "", "purpose": ""}, {"s": "W2785141883", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2785141883", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2794288888", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2795127895", "t": "W2613989746", "ctx": "While analog neural network accelerators such as the memristive Boltzmann machine [1], ISAAC [9], PRIME [10], and PipeLayer [11] exhibit significant potential to improve the energy efficiency, error correction for these accelerators remains unaddressed.", "purpose": "motivation"}, {"s": "W2795127895", "t": "W4243519499", "ctx": "We evaluate a memristive accelerator similar to ISAAC [9], wherein each layer of the neural network is placed in one or more tiles.", "purpose": "uses-method-or-tool"}, {"s": "W2795127895", "t": "W4254672563", "ctx": "While analog neural network accelerators such as the memristive Boltzmann machine [1], ISAAC [9], PRIME [10], and PipeLayer [11] exhibit significant potential to improve the energy efficiency, error correction for these accelerators remains unaddressed.", "purpose": "motivation"}, {"s": "W2796472956", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2796472956", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W2796472956", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2796472956", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2803163155", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2803163155", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2805362231", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2805362231", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2807750997", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2807750997", "t": "W1937359183", "ctx": "Our finding is consistent with previous theoretical and simulation studies on more sophisticated problems20,24,47-51.", "purpose": "data/numbers"}, {"s": "W2807750997", "t": "W2740220207", "ctx": "While the external control electronics we use in this work is not optimized for fast speed and low power consumption yet, previous literature on circuit design45,51 and architecture21,53 suggest an on-chip integrated system would yield significant advantages in speed-energy efficiency.", "purpose": "motivation"}, {"s": "W2807750997", "t": "W2782791387", "ctx": "During inference, all transistors operate in the deep triode region, and the memristor array becomes a pseudo-crossbar capable of performing matrix multiplication following Ohm's law and Kirchhoff's current law37,38.", "purpose": "background"}, {"s": "W2811080765", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2811080765", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2811080765", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2811080765", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2811080765", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2883149906", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2883149906", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2883149906", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W2883149906", "t": "W2902501132", "ctx": "For one-to-one comparison, we adopt the same semi-folded mapping compiler for the neural network chip in [29].", "purpose": "uses-method-or-tool"}, {"s": "W2883149906", "t": "W4236788275", "ctx": "With this guidance, previous work attempted to obtain crossbar-oriented pruning using iterative clustering method [39], but the fully-connected (FC) layer was the focus.", "purpose": "contrasts/critiques"}, {"s": "W2883149906", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2883149906", "t": "W4254672563", "ctx": "It can achieve extremely throughput compared to the fully-folded mapping that reuses all the neurons and weights [1] cycle by cycle, however, this scheme consumes significantly huge crossbar resources.", "purpose": "background"}, {"s": "W2896122000", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W2896122000", "t": "W2787453651", "ctx": "", "purpose": ""}, {"s": "W2896122000", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W2899641901", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2899749435", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W2899749435", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W2899749435", "t": "W2795127895", "ctx": "", "purpose": ""}, {"s": "W2899749435", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2899749435", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2899868573", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2899868573", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W2899868573", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2899868573", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2902501132", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2902501132", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2902501132", "t": "W2613989746", "ctx": "Our implementation using off-the-shelf SRAM array and extra PEs to mimic the crossbar behavior is just for cost saving, and in fact, the proposed SemiMap can be easily extended to other crossbar architectures, such as the emerging devices with in-memory computing (including PipeLayer).", "purpose": "background"}, {"s": "W2902501132", "t": "W2883149906", "ctx": "One promising direction is to study the crossbar-aware sparsification like that in [Crossbar-Aware Neural Network Pruning].", "purpose": "extends/builds-on"}, {"s": "W2902501132", "t": "W4243519499", "ctx": "Besides conventional technologies, plenty of researches leverage modified SRAM/Flash or various emerging non-volatile memory devices with in-memory computing capability to design this many-crossbar architecture, such as the most widely used RRAM... Our implementation using off-the-shelf SRAM array and extra PEs to mimic the crossbar behavior is just for cost saving, and in fact, the proposed SemiMap can be easily extended to other crossbar architectures, such as the emerging devices with in-memory computing.", "purpose": "contrasts/critiques"}, {"s": "W2902501132", "t": "W4254672563", "ctx": "Specifically, it fully reuses the crossbar cycle by cycle for completing the Conv operations across many sliding windows [PRIME]. For other synchronous ones, the limited scalability makes it difficult to unfold the whole computational graph.", "purpose": "baseline/comparison"}, {"s": "W2909715355", "t": "W2612375349", "ctx": "Prior efforts towards realizing DNNs on resistive crossbar systems can be broadly classified into specialized hardware accelerator designs [7-9, 11-13], nonideality mitigation schemes [14-18, 22-26], and design tools for resistive crossbar systems [27-30].", "purpose": "background"}, {"s": "W2909715355", "t": "W2625840880", "ctx": "These include (i) (re-)training [16-21], ... (iv) schemes to alleviate the effect of hard failures [26], and (vi) hardware solutions to address low-voltage induced drift [15], programming errors [23], and IR drop [24].", "purpose": "background"}, {"s": "W2909715355", "t": "W4243519499", "ctx": "Resistive crossbar based specialized hardware systems have been proposed for accelerating DNN inference [7-11] and training [12, 13].", "purpose": "background"}, {"s": "W2909715355", "t": "W4254672563", "ctx": "Resistive crossbar based specialized hardware systems have been proposed for accelerating DNN inference [7-11] and training [12, 13].", "purpose": "background"}, {"s": "W2910506572", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2910506572", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W2910506572", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2910506572", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2913104037", "t": "W1542981317", "ctx": "To overcome this limitation, memristor crossbars can store a matrix with high storage density and perform MVM operations with very low energy and latency [5, 13, 52, 87, 98, 116].", "purpose": "background"}, {"s": "W2913104037", "t": "W1937359183", "ctx": "To overcome this limitation, memristor crossbars can store a matrix with high storage density and perform MVM operations with very low energy and latency [5, 13, 52, 87, 98, 116].", "purpose": "background"}, {"s": "W2913104037", "t": "W2613989746", "ctx": "Some accelerators support inference only [9, 23, 53, 73, 88, 95] while others also support training [12, 22, 66, 100].", "purpose": "background"}, {"s": "W2913104037", "t": "W2782791387", "ctx": "Practically realizable crossbars provide 2-6 bits of precision per device [52]. We conservatively use 2 bits per device, and realize 16-bit MVM operations by combining 8 crossbars via bit-slicing [95]", "purpose": "data/numbers"}, {"s": "W2913104037", "t": "W2795127895", "ctx": "Further, recent research have explored coding schemes for reliable memristor computation at high precision [38, 92].", "purpose": "background"}, {"s": "W2913104037", "t": "W4243519499", "ctx": "Table 6 compares the peak area and power efficiency of PUMA with ISAAC [95], a memristor-based accelerator customized for CNNs. PUMA has 20.7% lower power efficiency and 29.2% lower area efficiency than ISAAC due to the overhead of programmability.", "purpose": "baseline/comparison"}, {"s": "W2913104037", "t": "W4254672563", "ctx": "3.1 Instruction Execution Pipeline Existing memristor-based accelerators [23, 73, 95] are limited to one or two ML workloads.", "purpose": "contrasts/critiques"}, {"s": "W2921329602", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W2923010225", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2923010225", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W2923010225", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W2923010225", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W2923010225", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W2923010225", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2925767305", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2925767305", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2925767305", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W2925767305", "t": "W2811080765", "ctx": "", "purpose": ""}, {"s": "W2925767305", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2925767305", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2945592020", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W2945592020", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2945592020", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W2945592020", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2945592020", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2946522000", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W2946522000", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2946522000", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2946659370", "t": "W2613989746", "ctx": "In addition, some RRAM-based accelerators utilize the multi-bit RRAM devices which have more than two stable resistance states, to achieve higher storage and computation density, such as PRIME [3] and PipeLayer [16] with 4-bit RRAM.", "purpose": "background"}, {"s": "W2946659370", "t": "W2794288888", "ctx": "In order to achieve high reliable and accurate CNN computing, researchers and chip designers also proposed several CNN accelerators based on single bit RRAM [2, 17, 18, 21].", "purpose": "background"}, {"s": "W2946659370", "t": "W2899868573", "ctx": "Besides, since the crossbar size determines the number of crossbars we need for storing the weights, it will also affect the hardware area and energy overhead [24].", "purpose": "uses-method-or-tool"}, {"s": "W2946659370", "t": "W4243519499", "ctx": "With above hardware configurations and accuracy loss threshold setting, the equivalent energy efficiency of the computing units (i.e., RRAM Banks) is 3.44TOps/W, nearly 8.6x and 1.6x compared with existing RRAM-based accelerators, ISAAC [15] and PRIME [3], respectively.", "purpose": "baseline/comparison"}, {"s": "W2946659370", "t": "W4254672563", "ctx": "Previous work demonstrated that emerging resistive random access memories (RRAMs) provide alternative solution to boost the energy efficiency of CNN computing [3] due to its capability of performing matrix-vector-multiplications (MVMs) in memory, referred as one of the Processing-In-Memory (PIM) architectures.", "purpose": "background"}, {"s": "W2948661249", "t": "W2612375349", "ctx": "Off-line variation-aware training schemes have also been proposed, where hardware non-idealities such as device-to-device variations13,14, defective devices14, or IR drop13 are first characterized and then fed into the training algorithm running in software.", "purpose": "contrasts/critiques"}, {"s": "W2948661249", "t": "W2765081478", "ctx": "...and phase-change memory (PCM)7-9 are being investigated for this.", "purpose": "background"}, {"s": "W2948661249", "t": "W2782791387", "ctx": "Both charge-based storage devices, such as Flash memory4, and resistance-based (memristive) storage devices, such as metal-oxide resistive random-access memory (ReRAM)5,6 ... are being investigated for this.", "purpose": "background"}, {"s": "W2948661249", "t": "W2803163155", "ctx": "One potential solution to this problem is to train the network fully on hardware9,10, such that all hardware non-idealities would be de facto included as constraints during training.", "purpose": "motivation"}, {"s": "W2948661249", "t": "W3003151806", "ctx": "", "purpose": ""}, {"s": "W2948661249", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W2948661249", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W2948661249", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W2948661249", "t": "W4243519499", "ctx": "In order to reduce the data transfers to a minimum in inference accelerators, a promising avenue is to employ in-memory computing using non-volatile memory devices3.", "purpose": "background"}, {"s": "W2949989598", "t": "W2613989746", "ctx": "FloatPIM training is on average 303.2x and 48.6x (4.3x and 15.8x) faster and more energy efficient as compared to GTX 1080 GPU (PipeLayer [1] PIM accelerator).", "purpose": "baseline/comparison"}, {"s": "W2949989598", "t": "W4243519499", "ctx": "ISAAC [2] and PRIME [11] exploit analog characteristics of non-volatile memory to support matrix multiplication in memory. These architectures transfer the digital input data into an analog domain and pass the analog signal through a crossbar ReRAM to compute matrix multiplication.", "purpose": "baseline/comparison"}, {"s": "W2949989598", "t": "W4254672563", "ctx": "ISAAC [2] and PRIME [11] exploit analog characteristics of non-volatile memory to support matrix multiplication in memory.", "purpose": "baseline/comparison"}, {"s": "W2971533524", "t": "W2782791387", "ctx": "Row Decoder design is no larger than 128x64 [36] and is identical for all DNN layers.", "purpose": "background"}, {"s": "W2971533524", "t": "W4236788275", "ctx": "Ankit et al. [22] implemented weight pruning techniques to NC systems using memristor crossbar arrays, which reduces the area (energy) consumption compared to the original network.", "purpose": "baseline/comparison"}, {"s": "W2971533524", "t": "W4254672563", "ctx": "To ensure a relatively high accuracy, usually two (or more) memristors are bundled to represent weights with high resolution (more bits) [39].", "purpose": "background"}, {"s": "W2972862238", "t": "W1542981317", "ctx": "Although here we focus on ex-situ training, such systems have been successfully utilised for in-situ training too [10, 11].", "purpose": "background"}, {"s": "W2972862238", "t": "W1937359183", "ctx": "fortunately, this type of behaviour is more relevant for in-situ training where it is necessary to ensure linear adjustment of ANN’s weights [27].", "purpose": "background"}, {"s": "W2972862238", "t": "W2765081478", "ctx": "To mitigate the effects of these device non-idealities, it is often necessary to modify device structure [9], to use more advanced programming schemes [14] or to use additional circuitry [15] or highprecision processing units [16] in conjunction with memristive elements.", "purpose": "background"}, {"s": "W2972862238", "t": "W2803163155", "ctx": "Memristive devices, such as phase-change memories (PCMs) [6, 7] or resistive random-access memories (RRAMs) [8, 9], have been considered as candidates for such tasks.", "purpose": "background"}, {"s": "W2972862238", "t": "W2807750997", "ctx": "The detailed fabrication process parameters can be found in references [11, 28, 29] for Ta/HfO2 , Ta2 O5 and aVMCO RRAMs respectively.", "purpose": "data/numbers"}, {"s": "W2972862238", "t": "W2923010225", "ctx": "These line resistance effects can be partially compensated for algorithmically [17] or partially mitigated by using multiple smaller crossbar arrays [18].", "purpose": "background"}, {"s": "W2974067241", "t": "W2613989746", "ctx": "PipeLayer [15] achieves the speedup and energy saving of 42.45x and 7.17x, respectively, compared with a GPU platform on average.", "purpose": "baseline/comparison"}, {"s": "W2974067241", "t": "W2946522000", "ctx": "However, many non-ideal effects, such as IR-drop (i.e., wire resistance), Stuck-At-Fault (SAF), thermal noise, shot and random telegraph noise [16], are hampering the progress of real hardware implementation of large-scale DNNs on ReRAM crossbar-based accelerators.", "purpose": "background"}, {"s": "W2974067241", "t": "W4243519499", "ctx": "For example, ISAAC [14] architecture improves throughput and energy by 14.8x and 5.5x, respectively, relative to a well-known ASIC architecture.", "purpose": "baseline/comparison"}, {"s": "W2974067241", "t": "W4254672563", "ctx": "More importantly, its current-mode weighted summation operation intrinsically matches the dominant Multiplication-and-Accumulation (MAC) in the artificial neural network, making it one of the most promising candidates as the basic computing unit for neural network accelerator design [6].", "purpose": "background"}, {"s": "W2978384356", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W2978384356", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2978384356", "t": "W2625840880", "ctx": "", "purpose": ""}, {"s": "W2978384356", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W2978384356", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2978384356", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2979663695", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W2979663695", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2979663695", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W2979663695", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W2979663695", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W2979663695", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2979663695", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2996781237", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2996781237", "t": "W2811080765", "ctx": "", "purpose": ""}, {"s": "W2996781237", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W2996781237", "t": "W2925767305", "ctx": "", "purpose": ""}, {"s": "W2996781237", "t": "W4236788275", "ctx": "", "purpose": ""}, {"s": "W2996781237", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2996781237", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2997247951", "t": "W2612375349", "ctx": "(bib #45, Chen et al. accelerator-friendly neural-network training referenced in discussion of non-idealities/faults/variations recovery via re-training)", "purpose": "background"}, {"s": "W2997247951", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2997247951", "t": "W2625840880", "ctx": "We make the following contributions: a bit-slicing technique for implementing high-precision OPA operations using ReRAM crossbars (Section 3), a crossbar-based architecture... an ISA-programmable accelerator with compiler support...", "purpose": "background"}, {"s": "W2997247951", "t": "W2740220207", "ctx": "To overcome this issue, recent demonstrations [10, 11] have shown that Outer Product Accumulate (OPA) operations can be performed in crossbars to realize the weight gradient and update operations without the use of serial reads and writes.", "purpose": "motivation"}, {"s": "W2997247951", "t": "W2782791387", "ctx": "The weights of the matrix (W) are stored in the crossbar cells as the conductance state [15]. To strike a balance, we choose p = 4, since p > 4 requires a device precision that exceeds ReRAM technology limits [15].", "purpose": "background"}, {"s": "W2997247951", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W2997247951", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2997247951", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W2997869757", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W2997869757", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W2997869757", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W2997869757", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3003151806", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3003821665", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W3003821665", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3003821665", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3003821665", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3003821665", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W3003821665", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W3003821665", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W3005874416", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3006908002", "t": "W2613989746", "ctx": "We specifically focus on crossbar-based architectures for DNN training [11-13], which have attracted increasing interest in recent years. Various efforts that propose crossbar-based training architectures [11-13] also develop performance and energy models to evaluate them.", "purpose": "background"}, {"s": "W3006908002", "t": "W2736591611", "ctx": "MNSIM [21] is a tool for early design space exploration of such architectures.", "purpose": "baseline/comparison"}, {"s": "W3006908002", "t": "W2909715355", "ctx": "Crossbar-based systems face a major challenge due to numerous device and circuit-level non-idealities, viz., driver and sensing resistances, analog-to-digital converter (ADC) and digital-to-analog converter (DAC) non-linearity, interconnect resistances, process variations, imperfect write operations, and sneak paths [12, 14-16].", "purpose": "background"}, {"s": "W3006908002", "t": "W2946522000", "ctx": "Inference modeling. [15, 16, 17, 18] are modeling tools that consider the impact of non-idealities in crossbar-based inference.", "purpose": "baseline/comparison"}, {"s": "W3006908002", "t": "W2997247951", "ctx": "We conservatively assume 32-bit precision for all data structures (viz.) weights, activations and errors in DNN training based on the scheme proposed in [30], since it provides classification accuracy close to floating-point training [31].", "purpose": "uses-method-or-tool"}, {"s": "W3006908002", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W3011221635", "t": "W2625840880", "ctx": "An alternative way of capturing effects such as stuck-at-faults [14] or device variations [15] is to map the distribution of the variations or defects. While the above modelling approaches [9, 13-15] consider linear (non-data dependent) non-idealities, GENIEx also captures the non-linear (data dependent) non-idealities.", "purpose": "contrasts/critiques"}, {"s": "W3011221635", "t": "W2782791387", "ctx": "To this effect, researchers have explored Non Volatile Memory (NVM) [4, 5] based crossbar architectures to achieve higher on-chip storage density and efficient MVMs in the analog domain [6, 7].", "purpose": "background"}, {"s": "W3011221635", "t": "W2803163155", "ctx": "To this effect, researchers have explored Non Volatile Memory (NVM) [4, 5] based crossbar architectures to achieve higher on-chip storage density and efficient MVMs in the analog domain [6, 7].", "purpose": "background"}, {"s": "W3011221635", "t": "W2913104037", "ctx": "Crossbar-based accelerators commonly use bit-slicing to perform high precision MVM operations [6, 7].", "purpose": "background"}, {"s": "W3011221635", "t": "W4243519499", "ctx": "For CMOS, matrix operations (ops) in a ML model are expressed as General Matrix-Matrix Multiplications (GEMMs) that use floating/fixed point compute units, whereas Crossbar requires matrix ops expressed as Matrix-Vector Multiplications (MVM) that use bit-serial compute units [6, 7].", "purpose": "background"}, {"s": "W3013080934", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2765081478", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2795127895", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3013080934", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3013241373", "t": "W2945592020", "ctx": "Table I shows the accuracy and energy consumption of PIM architectures compared with existing work [7]. ... the proposed training framework can achieve a comparable accuracy compared with the floating baseline, but brings >70% energy reduction (equivalent to 3.4x energy efficiency improvement).", "purpose": "baseline/comparison"}, {"s": "W3013241373", "t": "W2946659370", "ctx": "Researchers have pointed out that the ADCs occupy more than 60% energy consumption of the overall PIM architectures, which damage the energy efficiency gains of PIM architectures [2].", "purpose": "motivation"}, {"s": "W3013241373", "t": "W4243519499", "ctx": "From Figure 3, non-uniform quantization can reduce 1 bit ADC resolution compared with uniform quantization without accuracy loss, and ADC overheads grow exponentially with resolution [11].", "purpose": "background"}, {"s": "W3013241373", "t": "W4254672563", "ctx": "Besides, in order to minimize the calculation error caused by resistance deviations, R ratio (i.e., HRS/LRS) needs to be large enough (e.g., 10~100 [1]).", "purpose": "background"}, {"s": "W3013407975", "t": "W2782791387", "ctx": "Due to the increasing reading/writing errors caused by expanding the memristor crossbar size, we limited our design by using multiple 128x64 [25] crossbars for all DNN layers.", "purpose": "uses-method-or-tool"}, {"s": "W3013407975", "t": "W4236788275", "ctx": "[16] implemented weight pruning techniques on a neuromorphic computing system using irregular pruning caused unbalanced workload, greater circuits overheads and extra memory requirement on indices. To overcome the limitations, [17] proposed group connection deletion, which structually prunes connections to reduce routing congestion between memristor crossbar arrays.", "purpose": "background"}, {"s": "W3013407975", "t": "W4243519499", "ctx": "Due to its outstanding performance on computing matrix-vector multiplications (MVM), memristor crossbars are widely used as dot-product accelerator in recent neuromorphic computing designs [19].", "purpose": "background"}, {"s": "W3013896150", "t": "W2613989746", "ctx": "Moreover, the use of MCAs allow matrices to be stored in-place, which reduces data fetching and communication costs that fundamentally bounds the performance of any computing system that processes large amounts of data [8], [2], [9].", "purpose": "background"}, {"s": "W3013896150", "t": "W4243519499", "ctx": "Moreover, the use of MCAs allow matrices to be stored in-place, which reduces data fetching and communication costs that fundamentally bounds the performance of any computing system that processes large amounts of data [8], [2], [9].", "purpose": "background"}, {"s": "W3013896150", "t": "W4254672563", "ctx": "Moreover, the use of MCAs allow matrices to be stored in-place, which reduces data fetching and communication costs that fundamentally bounds the performance of any computing system that processes large amounts of data [8], [2], [9].", "purpose": "background"}, {"s": "W3015980402", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W3015980402", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3015982917", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W3015982917", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3016048022", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W3016048022", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3016762888", "t": "W2612375349", "ctx": "In VAT [20], [21], [23], RRAM array is read to characterize device variations, and these statistical variations are then embedded to train the neural network. However, these approaches require computationally expensive retraining for each RRAM device.", "purpose": "contrasts/critiques"}, {"s": "W3016762888", "t": "W2899749435", "ctx": "Recently, Lin et al. [18] proposed a simulation framework to compute and model the error rates of the memristor computation in the DNN model to partially recover the inference accuracy.", "purpose": "background"}, {"s": "W3016762888", "t": "W3005619596", "ctx": "To evaluate the hardware efficiency of the proposed method, we use NeuroSim [27], an architectural analysis tool for evaluating the area cost of the main model and the additional on-chip memory.", "purpose": "uses-method-or-tool"}, {"s": "W3016762888", "t": "W4243519499", "ctx": "Nonvolatile memory (NVM)-based processing-in-memory (PIM) architectures, such as the crossbar, have demonstrated the potential to speed up the multiply-and-accumulate (MAC) operations in DNNs, achieving high energy efficiency with low latency [8], [9], [11].", "purpose": "background"}, {"s": "W3020429010", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W3020429010", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3020429010", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3020429010", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3020429010", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3020710655", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3020710655", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3020710655", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3030670306", "t": "W2782791387", "ctx": "To guarantee the actual output close to the ideal output, we adopt an experiment verified method[14].", "purpose": "uses-method-or-tool"}, {"s": "W3030670306", "t": "W2785141883", "ctx": "To overcome the memory bottleneck, many researchers show interest in resistive crossbar arrays for the computing-in-memory feature [1, 8, 14, 21, 25, 41].", "purpose": "background"}, {"s": "W3030670306", "t": "W2910506572", "ctx": "Although we could partition huge matrix into multiple small matrices[23], sparse mapping still needs 100x numbers of DACs&ADCs than dense mapping.", "purpose": "contrasts/critiques"}, {"s": "W3030670306", "t": "W2946522000", "ctx": "PytorX[12] and FTNNA[24] are designed for neural network applications with the consideration of non-ideal effects. They also have the ability to alleviate the impact of those non-ideal effects and have been demonstrated on large datasets. However, such rescue ability is given by the error tolerance of NN models rather than the optimization of simulators, since both need to re-training the model", "purpose": "contrasts/critiques"}, {"s": "W3030670306", "t": "W4243519499", "ctx": "In Table 2, crossbar, ADC/DAC parameters are adopted from ISAAC[29].", "purpose": "data/numbers"}, {"s": "W3036663566", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3036663566", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3036663566", "t": "W2787453651", "ctx": "", "purpose": ""}, {"s": "W3036663566", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W3036663566", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3036663566", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W3036663566", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3036663566", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2740220207", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2787453651", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2795127895", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2896122000", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2910506572", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3041897167", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2625840880", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2740220207", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2883149906", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W3006908002", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W3011221635", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W4236788275", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3042468132", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3042493405", "t": "W2612375349", "ctx": "To address this challenge, TIMELY not only leverages algorithm resilience of CNNs/DNNs to counter hardware vulnerability [9], [48], [81], but also minimize potential errors introduced by hardware, thereby achieving the optimal trade-off between energy efficiency and accuracy.", "purpose": "background"}, {"s": "W3042493405", "t": "W2613989746", "ctx": "To the best of our knowledge, TIMELY is the first to implement and maximize analog data locality via ALBs, which have at least one order of magnitude lower access energy cost compared to the two level memories in PRIME [14]/ISAAC [58]/Pipelayer [62].", "purpose": "baseline/comparison"}, {"s": "W3042493405", "t": "W2625840880", "ctx": "To address this challenge, TIMELY not only leverages algorithm resilience of CNNs/DNNs to counter hardware vulnerability [9], [48], [81], but also minimize potential errors introduced by hardware, thereby achieving the optimal trade-off between energy efficiency and accuracy.", "purpose": "background"}, {"s": "W3042493405", "t": "W2785141883", "ctx": "Specifically, the average energy of one high-cost memory access in PRIME is about 9× and 33× higher than that of P-subBufs and X-subBufs [79] in TIMELY, respectively.", "purpose": "data/numbers"}, {"s": "W3042493405", "t": "W2979663695", "ctx": "Although a recent R2 PIM accelerator, CASCADE [15], has adopted analog buffers, it only uses analog ReRAM buffer to reduce the number of A/D conversions, thereby minimizing computational energy. TIMELY uses ALBs to minimize both the computational energy and data movement energy.", "purpose": "contrasts/critiques"}, {"s": "W3042493405", "t": "W3003821665", "ctx": "Among PIM accelerators on various memory technologies [14], [42], [43], [56], [58], [62], [66], [78], resistive-random-access-memory-(ReRAM)-based-PIM (R2PIM) accelerators have gained extensive research interest due to ReRAM's high density", "purpose": "background"}, {"s": "W3042493405", "t": "W4243519499", "ctx": "(2) the energy of the interfacing circuits (such as analog-to-digital converters (ADCs)/digital-to-analog converters (DACs)) is another limiting factor (as high as 61% in ISAAC [58]).", "purpose": "motivation"}, {"s": "W3042493405", "t": "W4254672563", "ctx": "However, the energy efficiency of R2 PIM accelerators (such as PRIME [14], ISAAC [58], and PipeLayer [62]) is still limited due to two bottlenecks (see Fig. 1 (b)): (1) although the weights are kept stationary in memory, the energy cost of data movements due to inputs and Psums is still large (as high as 83% in PRIME [14]);", "purpose": "motivation"}, {"s": "W3090816752", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W3090816752", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3090816752", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3090816752", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3091895175", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W3091895175", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3091895175", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3107562138", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W3107562138", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3107562138", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W3107562138", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3109300165", "t": "W2612375349", "ctx": "Weight compensation: Some works [5, 7] cooperate mask retraining and re-mapping methods to compensate the conductance deviation measured on a specific ReRAM crossbar. However, these methods require careful learning rate tuning, complex mask design and device-by-device conductance reading, which are either computing-intensive or time-consuming.", "purpose": "contrasts/critiques"}, {"s": "W3109300165", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3109300165", "t": "W2945592020", "ctx": "And [13, 14] try to incorporate quantization with training to eliminate the quantization error. Their results show improvement in conductance variation tolerance. Nevertheless, there is still a significant accuracy drop with large variation compared with the baseline model.", "purpose": "baseline/comparison"}, {"s": "W3109300165", "t": "W2946522000", "ctx": "Figure 1: Computing unit of ReRAM NN accelerator [15].", "purpose": "uses-method-or-tool"}, {"s": "W3109300165", "t": "W2946659370", "ctx": "Digital crossbar: In [10-12], a high-precision value is represented by several single-bit crossbars, which is also called 'ReRAM crossbar in digital mode'.", "purpose": "background"}, {"s": "W3109300165", "t": "W4243519499", "ctx": "With these merits, the ReRAM-based neural network accelerator has been widely studied and is proved to be a promising alternative to Von-Neumann architecture [2] [3] for this type of application.", "purpose": "background"}, {"s": "W3109300165", "t": "W4254672563", "ctx": "With these merits, the ReRAM-based neural network accelerator has been widely studied and is proved to be a promising alternative to Von-Neumann architecture [2] [3] for this type of application.", "purpose": "background"}, {"s": "W3111367661", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W2605257365", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3111367661", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3111375540", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3111375540", "t": "W2811080765", "ctx": "", "purpose": ""}, {"s": "W3111375540", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W3111375540", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3111375540", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3111989171", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3111989171", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W3111989171", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3111989171", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3111989171", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3112740243", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3112740243", "t": "W2785141883", "ctx": "Emerging eNVM devices such as RRAM, PCM, EpiRAM, ECRAM and FeFET have been proposed by the device community as candidates of \"analog\" synaptic devices, to represent the weights of deep CNNs in CIM accelerators.", "purpose": "background"}, {"s": "W3112740243", "t": "W2787453651", "ctx": "", "purpose": ""}, {"s": "W3112740243", "t": "W2997869757", "ctx": "To realize the input data reuse practically, we have proposed a novel mapping method and data flow for CIM inference in prior work, where the weights at different spatial location of each kernel are mapped into different sub-matrices.", "purpose": "uses-method-or-tool"}, {"s": "W3112740243", "t": "W3005619596", "ctx": "As what has been proposed in prior framework V1.0 [7], the NeuroSim core is wrapped by python library, to support flexible network topologies, the default model is VGG-8 for CIFAR-10 based on low precision training method WAGE.", "purpose": "extends/builds-on"}, {"s": "W3112740243", "t": "W3090816752", "ctx": "In DNN+NeuroSim V2.0, we do not consider pipeline among the four key steps in training... however the users can potentially optimize the design as done in other works [14][15] (including MINT: Mixed-Precision RRAM-Based IN-Memory Training Architecture).", "purpose": "contrasts/critiques"}, {"s": "W3116577775", "t": "W2978384356", "ctx": "A crossbar with the incomplete matrix will definitely lead to accuracy degradation because the inference accuracy is sensitive to the number of defective memristors [13]... Meanwhile, Zhang et al. [13] also use similar methods to handle this issue.", "purpose": "contrasts/critiques"}, {"s": "W3116577775", "t": "W4243519499", "ctx": "The area and power for memristor-based crossbars are adapted from ISAAC.", "purpose": "uses-method-or-tool"}, {"s": "W3116577775", "t": "W4254672563", "ctx": "Processing-in-Memory (PIM) platforms are more and more popular in accelerating neural network applications due to fewer data movements compared to FPGA and ASIC implementations [1]-[3]... Among these works, Processing-In-Memory architectures [1]-[3] achieve better performance than FPGA and ASIC.", "purpose": "background"}, {"s": "W3119537022", "t": "W2612375349", "ctx": "At the algorithmic level, the weights are trained to enhance the tolerance of NNs to the resistance variations of ReRAMs [15]-[18]... However, the methods in [15] and [16] can only address the variation problems in Single-Layer Perceptron (SLP), which has limited application.", "purpose": "background"}, {"s": "W3119537022", "t": "W2613989746", "ctx": "Recent works present several NN accelerators based on ReRAM crossbars, such as PRIME [4], ISAAC [5], and PipeLayer [6].", "purpose": "background"}, {"s": "W3119537022", "t": "W2811080765", "ctx": "", "purpose": ""}, {"s": "W3119537022", "t": "W2946522000", "ctx": "However, due to the immaturity of fabrication process combined with stochastic filament-based switching, ReRAM suffers from the resistance variations problem [10][11], manifested as the deviation of actual resistance from its target value.", "purpose": "background"}, {"s": "W3119537022", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W3119537022", "t": "W3003821665", "ctx": "Moreover, several ReRAM-based chips have been fabricated to accelerate NN computing using Multi-Level Cells (MLCs) [7][8].", "purpose": "motivation"}, {"s": "W3119537022", "t": "W3020429010", "ctx": "To achieve higher accuracy in CNN with acceptable hardware cost, a combination of off-device and on-device training methods is proposed in [18]. The on-device training however still needs to rewrite the ReRAMs to update the weights, which hurts the device endurance.", "purpose": "contrasts/critiques"}, {"s": "W3119537022", "t": "W4243519499", "ctx": "Recent works present several NN accelerators based on ReRAM crossbars, such as PRIME [4], ISAAC [5], and PipeLayer [6]. Usually, the DAC resolution is not very high [5].", "purpose": "background"}, {"s": "W3119537022", "t": "W4254672563", "ctx": "Recent works present several NN accelerators based on ReRAM crossbars, such as PRIME [4], ISAAC [5], and PipeLayer [6].", "purpose": "background"}, {"s": "W3127794782", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3127794782", "t": "W2740220207", "ctx": "", "purpose": ""}, {"s": "W3127794782", "t": "W2795127895", "ctx": "", "purpose": ""}, {"s": "W3127794782", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W3127794782", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W3127794782", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W3127794782", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3127794782", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3131573445", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3131573445", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W3131573445", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W3131573445", "t": "W2971533524", "ctx": "", "purpose": ""}, {"s": "W3131573445", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3131573445", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3138725418", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W3138725418", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W3138725418", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W3148526109", "t": "W2896122000", "ctx": "One promising future technology is the use of memristive crossbar arrays for accelerating the ubiquitous matrix-vector multiply and rank-update operations in ANNs by employing in-memory computation of matrices stored as analog quantities in tunable resistive elements [1,7,8,13].", "purpose": "background"}, {"s": "W3148526109", "t": "W2909715355", "ctx": "While there exists a number of current software packages that are dedicated to simulating AI workloads on non-volatile memory elements, notably MLP-NeuroSim [2] and RxNN [9], they are usually not tied to modern AI frameworks, such as PyTorch. RxNN is based on the rather outdated Caffe framework and only caters to analog chips dedicated to inference, lacking more advanced algorithms and pulse update schemes that are needed for training-enabled chip designs.", "purpose": "contrasts/critiques"}, {"s": "W3148526109", "t": "W2948661249", "ctx": "The noise strength and temporal profile is calibrated on a 1M phase-change memory (PCM) device array [10] (see Fig. 3).", "purpose": "uses-method-or-tool"}, {"s": "W3148526109", "t": "W3013080934", "ctx": "One promising future technology is the use of memristive crossbar arrays for accelerating the ubiquitous matrix-vector multiply and rank-update operations in ANNs by employing in-memory computation of matrices stored as analog quantities in tunable resistive elements [1,7,8,13].", "purpose": "background"}, {"s": "W3148526109", "t": "W3112740243", "ctx": "A recent PyTorch re-implementation of a subset of the MLP-NeuroSim package using PyTorch, called DNN+NeuroSim, is closest to our framework. However, it does not support fast custom CUDA kernels for in-situ parallel analog update... Note that our framework differs significantly from the update approach implemented by DNN+NeuroSim. For instance, DNN+NeuroSim uses native PyTorch operators to compute the accumulated gradient... This will result in a dramatic under-estimation of the update noise properties.", "purpose": "contrasts/critiques"}, {"s": "W3155456425", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2796472956", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W3155456425", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W3157191380", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W3157191380", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3157191380", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3157191380", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W3157191380", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W3157191380", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3162727751", "t": "W2612375349", "ctx": "Several methods are proposed to address the stuck-at-fault defects, such as permuting the order of the crossbar rows and columns [4], retraining the network by considering the defect locations [5], [6].", "purpose": "contrasts/critiques"}, {"s": "W3162727751", "t": "W2625840880", "ctx": "In [5], redundant columns of ReRAM crossbars are utilized as a substitution for the defect ReRAM columns. But this method not only introduces nontrivial area overhead, but also increases design complexity of peripheral circuit.", "purpose": "contrasts/critiques"}, {"s": "W3162727751", "t": "W2971533524", "ctx": "DNN Weight pruning [8], [28]–[31], as one of the DNN model compression techniques, has also been investigated to reduce the weight storage and improve performance for ReRAM-based acceleration designs [32], [33].", "purpose": "background"}, {"s": "W3162727751", "t": "W2978384356", "ctx": "Although these methods are effective in mitigating the accuracy drop caused by the stuck-at-fault defects, even [7] can restore 99% of the accuracy drop, but for mass-produced IoT products, applying optimization for each individual product (IoT device) will bring a huge time cost, and is not realistic.", "purpose": "motivation"}, {"s": "W3162727751", "t": "W3013407975", "ctx": "DNN Weight pruning [8], [28]–[31], as one of the DNN model compression techniques, has also been investigated to reduce the weight storage and improve performance for ReRAM-based acceleration designs [32], [33].", "purpose": "background"}, {"s": "W3162727751", "t": "W3042493405", "ctx": "Recent work, TIMELY [23] saves the energy cost of data movements and D/A and A/D domain conversion by enhancing analog data locality to keep computations in analog domain.", "purpose": "background"}, {"s": "W3162727751", "t": "W4243519499", "ctx": "Previous work, such as PRIME [21] and ISAAC [22], leverages in-situ computation to avoid the tremendous cost of data movement and efficiently compute multiply-accumulate operations, the most intensive computation in DNNs.", "purpose": "background"}, {"s": "W3162727751", "t": "W4254672563", "ctx": "Previous work, such as PRIME [21] and ISAAC [22], leverages in-situ computation to avoid the tremendous cost of data movement and efficiently compute multiply-accumulate operations, the most intensive computation in DNNs.", "purpose": "background"}, {"s": "W3164913974", "t": "W2613989746", "ctx": "It is worth mentioning that fully parallelism of all MAC operations is possible with inter-layer pipelining [27], [28], and the imbalanced speed/throughput of each pipeline stage can be solved by mapping techniques, such as replication. However, such architectures also come with high overall power and pipelining overhead and also requires the pipelines to be filled by streaming inputs", "purpose": "contrasts/critiques"}, {"s": "W3164913974", "t": "W2899641901", "ctx": "The compute density is higher than state-of-the-art programmable charge-domain IMC [26, 34] despite CAP-RAM has 1-to-8 row parallelism and multi-bit analog computing circuits.", "purpose": "baseline/comparison"}, {"s": "W3164913974", "t": "W4243519499", "ctx": "It is worth mentioning that fully parallelism of all MAC operations is possible with inter-layer pipelining [27], [28], and the imbalanced speed/throughput of each pipeline stage can be solved by mapping techniques, such as replication.", "purpose": "contrasts/critiques"}, {"s": "W3174812964", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W3174812964", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3174812964", "t": "W2625840880", "ctx": "", "purpose": ""}, {"s": "W3174812964", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W3174812964", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W3174812964", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3174812964", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3180792321", "t": "W1937359183", "ctx": "To maximize the inference accuracy of the neural network in the 4-kbit array, here we implemented the FC-NN synaptic weights using the 9 IGVVA-10 CDFs in Fig. 6 combined with the differential scheme illustrated in Fig. 7(a), namely by encoding the weight as the difference of two 1T1R conductances G+ and G- [3].", "purpose": "uses-method-or-tool"}, {"s": "W3180792321", "t": "W2782791387", "ctx": "A major advantage of IMC is the capability to execute matrix-vector multiplication (MVM) in parallel on multiple rows and columns of a memory array, which allows for a strong acceleration of neural networks [3]-[7].", "purpose": "background"}, {"s": "W3180792321", "t": "W2785141883", "ctx": "A major advantage of IMC is the capability to execute matrix-vector multiplication (MVM) in parallel on multiple rows and columns of a memory array, which allows for a strong acceleration of neural networks [3]-[7].", "purpose": "background"}, {"s": "W3180792321", "t": "W2794288888", "ctx": "The recent demonstration of embedded RRAM devices at Mbit capacity [8] enables the design and integration of IMC circuits [9]-[11], thus paving the way for energy efficient RRAM-based accelerators of artificial intelligence (AI).", "purpose": "background"}, {"s": "W3180792321", "t": "W2805362231", "ctx": "Resistive switching memory (RRAM) has recently gained increased interest for its application in novel computing concepts called in-memory computing (IMC) [1], [2].", "purpose": "background"}, {"s": "W3180792321", "t": "W2921329602", "ctx": "The recent demonstration of embedded RRAM devices at Mbit capacity [8] enables the design and integration of IMC circuits [9]-[11], thus paving the way for energy efficient RRAM-based accelerators of artificial intelligence (AI).", "purpose": "background"}, {"s": "W3180792321", "t": "W3157191380", "ctx": "An approach to achieve low conductance levels to minimize the IR drop issues could be the application of an algorithm based on incremental reset. However, partial reset was shown to lead to higher conductance variation compared to gradual set [30], suggesting that combined algorithms based on partial set/reset pulses need further studies.", "purpose": "extends/builds-on"}, {"s": "W3184191382", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3184191382", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W3184191382", "t": "W2949989598", "ctx": "", "purpose": ""}, {"s": "W3184191382", "t": "W2971533524", "ctx": "", "purpose": ""}, {"s": "W3184191382", "t": "W3013407975", "ctx": "", "purpose": ""}, {"s": "W3184191382", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3188508394", "t": "W2613989746", "ctx": "A similar approach is used in other works [10], [35]–[37] where the in-memory accelerator exposes an API. During compilation, the API is lowered to data-path configurations and control-flow commands. Again, it is up to the programmer to rewrite the application using the provided API, thus reducing application readiness.", "purpose": "contrasts/critiques"}, {"s": "W3188508394", "t": "W2913104037", "ctx": "Building on their effort, Ankit et al. [24] developed a runtime compiler implemented as a C++ library, which requires the users to rewrite the application with the proposed API. On the contrary, our work enables transparent acceleration as computational idioms amendable for CIM acceleration are lowered to API calls directly without user intervention.", "purpose": "contrasts/critiques"}, {"s": "W3188508394", "t": "W2948661249", "ctx": "Memristor crossbars, in particular, have attracted significant interest due to their ability to efficiently perform matrix–matrix and matrix– vector multiplications—the dominant computational kernels in deep neural networks [6].", "purpose": "motivation"}, {"s": "W3188508394", "t": "W4243519499", "ctx": "The physical properties of each PCM device, such as write and read latency, are taken from [9] and [22], and reported in Table II.", "purpose": "data/numbers"}, {"s": "W3188508394", "t": "W4254672563", "ctx": "A similar approach is used in other works [10], [35]–[37] where the in-memory accelerator exposes an API. During compilation, the API is lowered to data-path configurations and control-flow commands. Again, it is up to the programmer to rewrite the application using the provided API, thus reducing application readiness.", "purpose": "contrasts/critiques"}, {"s": "W3191560475", "t": "W2613989746", "ctx": "Several ReRAM-based in-situ mixed-signal DNN accelerators such as ISAAC [18], Newton [19], PipeLayer [20], PRIME [17], PUMA [21], MultiScale [22], XNORRRAM [37], RapidDNN [38], have been proposed in recent years.", "purpose": "background"}, {"s": "W3191560475", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W3191560475", "t": "W2740220207", "ctx": "Several ReRAM-based in-situ mixed-signal DNN accelerators such as ISAAC [18], Newton [19], PipeLayer [20], PRIME [17], PUMA [21], MultiScale [22], XNORRRAM [37], RapidDNN [38], have been proposed in recent years.", "purpose": "background"}, {"s": "W3191560475", "t": "W2807750997", "ctx": "The general way is to decompose each weight into a positive magnitude portion and a negative magnitude portion, then use two crossbars to represent each of the portions [17, 26-28, 41].", "purpose": "background"}, {"s": "W3191560475", "t": "W2913104037", "ctx": "Mapping Scheme and Dataflow In FORMS, instead of mapping both the sign and magnitude bits of arbitrary/mixed signs of weight values as in prior works such as memristive Boltzman machine [55], ISAAC [18], Newton [19], PipleLayer [20], PRIME [17], PUMA [21], we only need to store the magnitude bits to the ReRAM, and the sign bit of each fragment in the 1R ReRAM-based array [56].", "purpose": "contrasts/critiques"}, {"s": "W3191560475", "t": "W2949989598", "ctx": "The recent study [40, 42] reports the ADC/DAC blocks may become the major contributor to the total chip area and power.", "purpose": "motivation"}, {"s": "W3191560475", "t": "W2971533524", "ctx": "The previous ReRAM-based accelerator designs [47, 48] apply structured pruning and aim to make the pruning ratio as high as possible while maintaining an acceptable accuracy loss.", "purpose": "baseline/comparison"}, {"s": "W3191560475", "t": "W3013407975", "ctx": "TinyButAcc [47] is a state-of-the-art ReRAM-based pruning work using ADMM. By taking the crossbar size into account, we achieve a similar crossbar reduction ratio from the pruning part as TinyButAcc, with a lower pruning ratio.", "purpose": "baseline/comparison"}, {"s": "W3191560475", "t": "W3015980402", "ctx": "variation [18, 61].", "purpose": "background"}, {"s": "W3191560475", "t": "W3042493405", "ctx": "Besides, the recent work TIMELY [23] is proposed to enhance the analog data C...", "purpose": "background"}, {"s": "W3191560475", "t": "W3162727751", "ctx": "While keeping the number of crossbars the same, the latter approach introduces additional hardware costs for the peripheral circuits by adding extra offset circuits and may also decrease the network robustness to hardware failures [29]. Moreover, this mapping method decreases the network robustness to hardware failures [29].", "purpose": "contrasts/critiques"}, {"s": "W3191560475", "t": "W3184191382", "ctx": "TinyADC [40] proposes a pruning solution that fixes the number of non-zero weights in each column of the ReRAM crossbar while their positions can vary.", "purpose": "baseline/comparison"}, {"s": "W3191560475", "t": "W4243519499", "ctx": "In contrast, ISAAC [18] adds an offset to weights so that all values become positive... Instead, ISAAC [18] addresses this problem by shifting or adding an offset to the original negative weight value, so that all the weights become positive.", "purpose": "baseline/comparison"}, {"s": "W3191560475", "t": "W4254672563", "ctx": "The general way is to use two ReRAM crossbars to hold the positive and negative magnitudes weights separately, doubling the ReRAM portion of hardware cost [17, 25-28].", "purpose": "baseline/comparison"}, {"s": "W3194056411", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2796472956", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3036663566", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W3090816752", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3194056411", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3195245399", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3195245399", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W3195245399", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3195245399", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W3195245399", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W3195461290", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W3195461290", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W3195461290", "t": "W2896122000", "ctx": "", "purpose": ""}, {"s": "W3195461290", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W3195461290", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W3195461290", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W3195461290", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3197197128", "t": "W2605257365", "ctx": "This exponential nonlinearity makes the VMM operation inaccurate, which deteriorates the training performance [119].", "purpose": "background"}, {"s": "W3197197128", "t": "W2612375349", "ctx": "The first one is retraining [100–103]. ... Matrix permutation [100, 103, 107, 108] can be based on row permutation [100, 107] and neuron permutation [100, 107].", "purpose": "background"}, {"s": "W3197197128", "t": "W2613989746", "ctx": "Unlike PRIME and ISAAC, PipeLayer supports both the training and inference of neural networks [36].", "purpose": "background"}, {"s": "W3197197128", "t": "W2625840880", "ctx": "The first one is retraining [100–103].", "purpose": "background"}, {"s": "W3197197128", "t": "W2785141883", "ctx": "Nonlinear and asymmetric update dynamics in some RRAM devices hinder large-scale deployment in neural networks [122].", "purpose": "background"}, {"s": "W3197197128", "t": "W2794288888", "ctx": "A 65 nm ReRAm macro was designed to accelerate a binary convolution neural network (CNN) [39].", "purpose": "data/numbers"}, {"s": "W3197197128", "t": "W2913104037", "ctx": "PUMA is a spatial processor and provides more flexibility and scalability to accelerate a wide range of workloads and different types of data [41].", "purpose": "background"}, {"s": "W3197197128", "t": "W2946522000", "ctx": "In [106], the authors estimated the error contributed by SAF cells and recovered accuracy by additional CMOS circuits.", "purpose": "background"}, {"s": "W3197197128", "t": "W2979663695", "ctx": "The CASCADE architecture implemented an analog partial sum accumulation and achieved a peak performance of 101 GOPS/mm2 [38].", "purpose": "data/numbers"}, {"s": "W3197197128", "t": "W2997247951", "ctx": "PANTHER proposed the use of bit-slicing Outer Product Accumulate (OPA) operations to achieve higher precision and to implement different training algorithms [40].", "purpose": "background"}, {"s": "W3197197128", "t": "W3015980402", "ctx": "In a fabricated 22 nm 2 Mb ReRAM-CIM macro [65], the precision of input data was increased from binary to 4-bit.", "purpose": "data/numbers"}, {"s": "W3197197128", "t": "W3015982917", "ctx": "A Fully Integrated Analog ReRAM-based 130 nm macro used a 2T2R cell, which decreased the effect of the IR drop by decreasing the accumulative SL current [66].", "purpose": "background"}, {"s": "W3197197128", "t": "W3016762888", "ctx": "In a knowledge distillation (KD)-based retraining, the teacher network transfers 'knowledge' to a student network [102].", "purpose": "background"}, {"s": "W3197197128", "t": "W3107562138", "ctx": "There are other available crossbar simulation frameworks such as MNSIM, NeuroSim, and XB-sim. They also provide a simplified estimation of power, area, and latency [141], [142].", "purpose": "background"}, {"s": "W3197197128", "t": "W3111367661", "ctx": "However, even the small value of the wire resistance has a significant effect on the weights stored in RCA [112–114].", "purpose": "background"}, {"s": "W3197197128", "t": "W3111989171", "ctx": "", "purpose": ""}, {"s": "W3197197128", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W3197197128", "t": "W4243519499", "ctx": "It outperformed the fully digital DaDianNao with improvements of 14.8x, 5.5x, and 7.5x in throughput, energy, and computational density, respectively [34].", "purpose": "data/numbers"}, {"s": "W3197197128", "t": "W4254672563", "ctx": "Around the same time, the architecture of PRIME was introduced [35].", "purpose": "background"}, {"s": "W3198405160", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W3198405160", "t": "W2909715355", "ctx": "Most of the previous works [3, 7-10] have proposed strategies and frameworks to model and mitigate data-independent non-idealities (primarily resistive non-idealities and NVM device variations) pertaining to 1R crossbar arrays to improve on the accuracy of the mapped DNNs.", "purpose": "background"}, {"s": "W3198405160", "t": "W2913104037", "ctx": "a 1 x m input vector of voltages (Vi) interacts with a matrix of NVM conductances (Gij) to produce the output current... for performing the Matrix-Vector-Multiplication (MVM) operations of DNNs in the analog domain [2, 3]", "purpose": "background"}, {"s": "W3198405160", "t": "W3011221635", "ctx": "These results support the observations in prior work GenieX [6]. The authors found higher supply voltage (Vsupply) of 0.5V (or higher Vin) yields higher non-ideality than lower supply voltage Vsupply = 0.25V.", "purpose": "data/numbers"}, {"s": "W3198405160", "t": "W3020429010", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W2740220207", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W2795127895", "ctx": "Error-correcting codes can correct a fraction of the dot product errors [19], but...", "purpose": "background"}, {"s": "W3198899759", "t": "W2899749435", "ctx": "This can be achieved by using smaller arrays [43, 66], but this is inefficient as it amortizes the ADC energy cost over fewer MACs.", "purpose": "background"}, {"s": "W3198899759", "t": "W2913104037", "ctx": "To avoid this overhead and to provide a baseline that is similar to prior work [6, 49, 56], offset subtraction is evaluated with digital S&A accumulation of input bits (Bin = 1 bit).", "purpose": "baseline/comparison"}, {"s": "W3198899759", "t": "W2946522000", "ctx": "A common approach is to add noise to weights and activations during forward propagation [28, 32, 34, 36, 44].", "purpose": "background"}, {"s": "W3198899759", "t": "W2948661249", "ctx": "To avoid the energy and area overheads of reading, digitizing and aggregating multiple bit-sliced arrays, the magnitude of a weight can also be fully encoded in one device [30, 34].", "purpose": "background"}, {"s": "W3198899759", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W3013080934", "ctx": "In situ MVM has been demonstrated using a wide variety of memory cell technologies [55, 61, 68].", "purpose": "background"}, {"s": "W3198899759", "t": "W3030670306", "ctx": "With less precise cells, some prior work has relied on ADC quantization to cut off the propagation of cell errors from layer to layer in a DNN [30, 66, 71]. It is well known that parasitic resistance degrades MVM accuracy and some compensation methods have been proposed [30,32,33,71].", "purpose": "background"}, {"s": "W3198899759", "t": "W3041897167", "ctx": "Pruning is more difficult to exploit in analog accelerators, due to the rigid structure of a memory crossbar [62].", "purpose": "background"}, {"s": "W3198899759", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W3191560475", "ctx": "Comparison of data representation in selected prior work on analog in situ inference accelerators (Table 1), listing FORMS alongside ISAAC, PUMA, PRIME and others by bit-slicing, sign handling, array size and ADC/DAC bits.", "purpose": "baseline/comparison"}, {"s": "W3198899759", "t": "W3194056411", "ctx": "", "purpose": ""}, {"s": "W3198899759", "t": "W4243519499", "ctx": "To provide precision on par with digital systems, many prior analog inference accelerators adopt a hybrid approach known as bit slicing, where weight values are spread bitwise across multiple memory devices, and the analog intermediate results are digitized and aggregated [9, 11, 56].", "purpose": "baseline/comparison"}, {"s": "W3198899759", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3201198776", "t": "W2612375349", "ctx": "The first category includes device defects (e.g., stuck-at-high or stuck-at-low resistance [12]) and device reliability issues (e.g., retention failure [13] and resistance drift [14]) that are mostly deterministic in nature and have been addressed in prior work [15]-[20].", "purpose": "background"}, {"s": "W3201198776", "t": "W2613989746", "ctx": "ReRAM-based accelerators for fast and efficient DNN training and inferencing have been extensively studied [3]-[8].", "purpose": "background"}, {"s": "W3201198776", "t": "W2625840880", "ctx": "The first category includes device defects ... and device reliability issues ... that are mostly deterministic in nature and have been addressed in prior work [15]-[20].", "purpose": "background"}, {"s": "W3201198776", "t": "W2795127895", "ctx": "The second category includes stochastic noise in ReRAM devices that includes thermal noise [21], shot noise [22], random telegraph noise (RTN) [23], and programming noise [24].", "purpose": "background"}, {"s": "W3201198776", "t": "W2811080765", "ctx": "ReRAM-based accelerators for fast and efficient DNN training and inferencing have been extensively studied [3]-[8].", "purpose": "background"}, {"s": "W3201198776", "t": "W2946522000", "ctx": "He et al. [27] investigated the integration of stochastic noise during the training process, but their method failed to reach the desired DNN inferencing accuracy. Consequently, they suggested lowering the operational frequency such that the noise amplitude is low.", "purpose": "contrasts/critiques"}, {"s": "W3201198776", "t": "W2948661249", "ctx": "Long et al. [25] injected Gaussian noise during training to mimic programming noise, and Joshi et al. [26] incorporated device programming variation extracted from experiments during training. However, these methods only considered programming noise while neglecting the other types of noise.", "purpose": "contrasts/critiques"}, {"s": "W3201198776", "t": "W2997869757", "ctx": "The ReRAM crossbar and peripheral configurations are adopted from [52].", "purpose": "uses-method-or-tool"}, {"s": "W3201198776", "t": "W3005619596", "ctx": "We use NeruoSim [51] along with the 32 nm technology node parameters to evaluate the hardware area, execution time, and energy consumption.", "purpose": "uses-method-or-tool"}, {"s": "W3201198776", "t": "W3011221635", "ctx": "The first category includes device defects ... and device reliability issues ... that are mostly deterministic in nature and have been addressed in prior work [15]-[20].", "purpose": "background"}, {"s": "W3201198776", "t": "W3111375540", "ctx": "ReRAM-based accelerators for fast and efficient DNN training and inferencing have been extensively studied [3]-[8].", "purpose": "background"}, {"s": "W3201198776", "t": "W4243519499", "ctx": "ReRAM-based accelerators for fast and efficient DNN training and inferencing have been extensively studied [3]-[8].", "purpose": "background"}, {"s": "W3201198776", "t": "W4254672563", "ctx": "ReRAM-based accelerators for fast and efficient DNN training and inferencing have been extensively studied [3]-[8].", "purpose": "background"}, {"s": "W3204737618", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W2899868573", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W2902501132", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W2925767305", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W2949989598", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W2996781237", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3204737618", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3209892756", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3209892756", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W3209892756", "t": "W2811080765", "ctx": "", "purpose": ""}, {"s": "W3209892756", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3209892756", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3211168157", "t": "W2613989746", "ctx": "PRIME [16] and PipeLayer [17] adopt single-bit sense amplifiers and integrate-and-fire (IF) neurons to replace traditional high-resolution ADCs. However, these 1-bit quantizers take up to 2^n clock cycles to produce an n-bit BL output, leading to significant processing latency.", "purpose": "contrasts/critiques"}, {"s": "W3211168157", "t": "W2979663695", "ctx": "CASCADE [2] leverages RRAM buffer arrays to temporally store the analog partial sums and accumulate them before quantization. This method can effectively reduce the required A/D conversions. However, buffering high-precision ... trivial programming energy and suffers from severe device variations, degenerating the inference accuracy.", "purpose": "baseline/comparison"}, {"s": "W3211168157", "t": "W2996781237", "ctx": "We adopt a similar NoC implementation proposed in a prior work [31].", "purpose": "uses-method-or-tool"}, {"s": "W3211168157", "t": "W4243519499", "ctx": "ISAAC [1] uses 8-bit ADCs for quantization. However, high-resolution ADCs ...", "purpose": "baseline/comparison"}, {"s": "W3211168157", "t": "W4254672563", "ctx": "PRIME [16] and PipeLayer [17] adopt single-bit sense amplifiers and integrate-and-fire (IF) neurons to replace traditional high-resolution ADCs.", "purpose": "contrasts/critiques"}, {"s": "W3211973280", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W3211973280", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W3211973280", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W3211973280", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3211973280", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W3211973280", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W2811080765", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W2899868573", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W2902501132", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3212662098", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W3215634441", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W2795127895", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W2899868573", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W3011221635", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W3111367661", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4200001938", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4200149283", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W4200149283", "t": "W3111375540", "ctx": "", "purpose": ""}, {"s": "W4200149283", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4200149283", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4200477077", "t": "W2613989746", "ctx": "A certain number of ReRAM crossbar-based DNN accelerator designs are built in prior works, such as ISAAC [9], PRIME [4], PipeLayer [10], and CASCADE [6].", "purpose": "background"}, {"s": "W4200477077", "t": "W2794288888", "ctx": "Therefore, there are only 9 rows, and 8 columns of ReRAM cells on a 512 x 256 crossbar for concurrent execution of MACs in the macro of a state-of-the-art ReRAM-crossbar acceleration [25] in 65nm process.", "purpose": "motivation"}, {"s": "W4200477077", "t": "W2883149906", "ctx": "Existing works [12, 13, 17, 18] mainly focus on the structured compression (i.e., quantization and sparsification) for practical acceleration and the compression object is the numbers (i.e., weights).", "purpose": "contrasts/critiques"}, {"s": "W4200477077", "t": "W2946522000", "ctx": "For example, the IR drop caused by wire resistance lead to a huge voltage drop at the target cell and limits the number of columns that can be executed at the same time [8, 11, 24].", "purpose": "background"}, {"s": "W4200477077", "t": "W2979663695", "ctx": "A certain number of ReRAM crossbar-based DNN accelerator designs are built in prior works, such as ISAAC [9], PRIME [4], PipeLayer [10], and CASCADE [6].", "purpose": "background"}, {"s": "W4200477077", "t": "W3003821665", "ctx": "ReRAM-Based DNN Acceleration ReRAM crossbar is emerging as a promising solution to mitigate problems such as memory wall, owing to its high memory accessing bandwidth and high density [4, 6, 9, 10, 19-23].", "purpose": "background"}, {"s": "W4200477077", "t": "W3042493405", "ctx": "ReRAM-Based DNN Acceleration ReRAM crossbar is emerging as a promising solution to mitigate problems such as memory wall, owing to its high memory accessing bandwidth and high density [4, 6, 9, 10, 19-23].", "purpose": "background"}, {"s": "W4200477077", "t": "W4243519499", "ctx": "A certain number of ReRAM crossbar-based DNN accelerator designs are built in prior works, such as ISAAC [9], PRIME [4], PipeLayer [10], and CASCADE [6]. ... Simulation Setup We adapt the parameters similar to the analysis ISAAC with modified GEM5 to build a simulator for ReRAM-based crossbar architecture.", "purpose": "uses-method-or-tool"}, {"s": "W4200477077", "t": "W4254672563", "ctx": "A certain number of ReRAM crossbar-based DNN accelerator designs are built in prior works, such as ISAAC [9], PRIME [4], PipeLayer [10], and CASCADE [6].", "purpose": "background"}, {"s": "W4205363571", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4205363571", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4205363571", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4205363571", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4210530509", "t": "W1937359183", "ctx": "Prior to this, most of the demonstrations have been based on either simulation studies based on the measured characteristics of individual devices or on experiments based on PCM memory chips that were re-purposed for IMC operations [28]–[30].", "purpose": "background"}, {"s": "W4210530509", "t": "W2899641901", "ctx": "This allows the execution of shift-and-add operations within the ADC at a minimal overhead, avoiding dedicated multi-bit adders [42]–[44].", "purpose": "contrasts/critiques"}, {"s": "W4210530509", "t": "W2948661249", "ctx": "Prior to mapping the networks onto analog IMC cores, it is essential to perform a hardware-aware custom training in software as described in [30].", "purpose": "uses-method-or-tool"}, {"s": "W4210530509", "t": "W3003821665", "ctx": "In addition, voltage-based A/D converters (ADCs) are mostly used [31] that require a voltage to current conversion, usually employing a large capacitor for integration [23], [32].", "purpose": "contrasts/critiques"}, {"s": "W4210530509", "t": "W3013080934", "ctx": "In-memory computing (IMC) is an emerging non-von Neumann paradigm where computation is performed in the memory array itself [1], [2].", "purpose": "background"}, {"s": "W4210530509", "t": "W3015982917", "ctx": "In addition, voltage-based A/D converters (ADCs) are mostly used [31] that require a voltage to current conversion, usually employing a large capacitor for integration [23], [32].", "purpose": "contrasts/critiques"}, {"s": "W4210530509", "t": "W3138725418", "ctx": "The analog nature of the device, however, allows the encoding of more levels, the only limit being ADC precision and allowable programming time [35], [36].", "purpose": "background"}, {"s": "W4210530509", "t": "W3195245399", "ctx": "Although experimental results on ReRAM-based IMC systems have already been demonstrated [23]–[25], complete IMC systems based on PCM crossbar arrays had been lacking till recently [26], [27].", "purpose": "background"}, {"s": "W4210530509", "t": "W4243519499", "ctx": "This allows the execution of shift-and-add operations within the ADC at a minimal overhead, avoiding dedicated multi-bit adders [42]–[44].", "purpose": "contrasts/critiques"}, {"s": "W4214834240", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W4200477077", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4214834240", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4223592331", "t": "W2782791387", "ctx": "Multiplication of the intensity values of the input pixels by the kernel weights can be achieved using Ohm's law, and the accumulation can be achieved using Kirchhoff's law (20, 46).", "purpose": "uses-method-or-tool"}, {"s": "W4223592331", "t": "W2785141883", "ctx": "The linearity of weight updates represents the linearity of the curve between the conductance of the FeTFTs and the number of pulses (11). ... For the simulation of the VGG-8 network based on ideal synaptic devices, ideal synaptic characteristics (including a perfectly linear conductance modulation of Gmax/Gmin = 100 and 100 conductance states) were used (11).", "purpose": "baseline/comparison"}, {"s": "W4223592331", "t": "W2787453651", "ctx": "Among the available three-terminal synaptic devices, ferroelectric transistors based on zirconium-doped hafnium oxide (HfZrOx) are advantageous because they have CMOS compatibility, fast operation speed, low operation voltages, and high scalability (33-36).", "purpose": "motivation"}, {"s": "W4223592331", "t": "W2807750997", "ctx": "The analog conductance modulation characteristics of two-terminal devices are usually achieved by controlling the current of devices during the programming process (22-24).", "purpose": "background"}, {"s": "W4223592331", "t": "W2948661249", "ctx": "In previous studies, several CIM devices with a crossbar structure have been demonstrated using two-terminal devices, such as phase-change and resistive-switching memories, as synaptic devices (13-18).", "purpose": "contrasts/critiques"}, {"s": "W4223592331", "t": "W3003821665", "ctx": "To overcome these limitations, compute-in-memory (CIM) has been suggested as alternative hardware for CNNs because it enables parallel data processing (5-9).", "purpose": "background"}, {"s": "W4223592331", "t": "W3005619596", "ctx": "The average change in the conductance of the FeTFTs was about 4.1%, and no overlap between the states was observed for 10,000 s (fig. S10). The stable retention characteristics of the FeTFTs can be advantageous for maintaining accuracy (56).", "purpose": "background"}, {"s": "W4223592331", "t": "W3013080934", "ctx": "To overcome these limitations, compute-in-memory (CIM) has been suggested as alternative hardware for CNNs because it enables parallel data processing (5-9).", "purpose": "background"}, {"s": "W4223592331", "t": "W3112740243", "ctx": "An eight-layer visual geometry group (VGG-8) network for the Canadian Institute for Advanced Research (CIFAR-10) dataset was simulated to investigate the potential of using ferroelectric synaptic transistor arrays as the hardware for CNNs (12, 53).", "purpose": "uses-method-or-tool"}, {"s": "W4225637124", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4225637124", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W4225637124", "t": "W2796472956", "ctx": "", "purpose": ""}, {"s": "W4225637124", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W4225637124", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W4225637124", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4225637124", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4225637124", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4225739994", "t": "W2997869757", "ctx": "Reference [53] proposes an optimized weight mapping and dataflow in computing convolutional neural networks on ReRAM-based PIM. Unlike the traditional mapping scheme, which unrolls all of the 3D kernels into a large matrix, the proposed mapping scheme divides the 3D kernel of K × K × D into multiple 1 × 1 × D matrices", "purpose": "background"}, {"s": "W4225739994", "t": "W3015982917", "ctx": "In addition, analog ReRAM has also been utilized in PIM for neural networks with good error tolerance [34], [35], [40].", "purpose": "background"}, {"s": "W4225739994", "t": "W3016048022", "ctx": "Although the analog nature of ReRAM allows it to store a multi-bit weight for improved memory capacity [34], [35], [40], most ReRAM PIM works employ digital ReRAM with two distinct states: HRS and LRS [41]–[45].", "purpose": "background"}, {"s": "W4225739994", "t": "W3194056411", "ctx": "ReRAM-based PIM has become increasingly attractive in energy-efficient accelerators for edge computing where batteries or energy harvesting devices are the primary power sources [29]–[36].", "purpose": "background"}, {"s": "W4226111665", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W4226111665", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W4226111665", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4226111665", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4226111665", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4226111665", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W4226111665", "t": "W3155456425", "ctx": "", "purpose": ""}, {"s": "W4226247444", "t": "W2612375349", "ctx": "The need to transfer data between memory and computing units in the von Neumann architecture is the main bottleneck in modern computers [7]; this is especially evident in machine learning where large amounts of data are utilized.", "purpose": "background"}, {"s": "W4226247444", "t": "W2625840880", "ctx": "Find published open-access version in Advanced Science, doi:10.1002/advs.202105784 1 Introduction ities [15-19], including in convolutional neural networks (CNNs) [14, 20], recurrent structures [20], Artificial neural networks (ANNs) are now routinely used and in neural networks used for reinforcement learning [21] to autonomous driving [2].", "purpose": "background"}, {"s": "W4226247444", "t": "W2803163155", "ctx": "In this specific case, an alternative of faulty-devices [27] or line resistance [28].", "purpose": "background"}, {"s": "W4226247444", "t": "W2807750997", "ctx": "Fabrication process is described in more detail in [48]. Characterization: Device conductance was being increased using SET pulses (500 us @ 2.5 V and gate voltage linearly increasing from 0.6 V to 1.6 V).", "purpose": "uses-method-or-tool"}, {"s": "W4226247444", "t": "W2948661249", "ctx": "Alternatively, modifying ex-situ training has been proposed: altering the cost function [30] or injecting noise into the synaptic weights [31] can make MNNs more robust to the effects of nonidealities.", "purpose": "background"}, {"s": "W4226247444", "t": "W2972862238", "ctx": "In the specific context of MNNs, multiple smaller nonideal networks may replace a large one and increase the accuracy in this way [29].", "purpose": "background"}, {"s": "W4226247444", "t": "W3003821665", "ctx": "Memristor-oriented ex-situ training is indeed a very promising method of making MNNs feasible. However, it has been applied by considering only a limited number of nonidealities, while the robustness of this technique is not well understood.", "purpose": "contrasts/critiques"}, {"s": "W4226427756", "t": "W3013080934", "ctx": "Recently, computing-in-memory (CIM) [5, 6] mechanism has been proposed as a promising solution to the von-Neumann bottleneck through the integration of computational units and memories.", "purpose": "background"}, {"s": "W4226427756", "t": "W3194056411", "ctx": "On the other hand, to develop the A-MAC-EM for the target SRAM-based CIM macro, we assume the variation mainly occurs in ADC and DAC [28].", "purpose": "uses-method-or-tool"}, {"s": "W4226427756", "t": "W3198405160", "ctx": "In [20], an iterative training algorithm was proposed to regularize model parameters to fit into a linear operating range of 1T1R cells in a layer-by-layer manner to compensate for the accuracy degradation.", "purpose": "contrasts/critiques"}, {"s": "W4236788275", "t": "W1542981317", "ctx": "Thus, MCA is an analog computation unit and performs highly area and energy efficient inner-product operations [19].", "purpose": "background"}, {"s": "W4236788275", "t": "W4243519499", "ctx": "Consequently, MCAs have been aggressively harnessed for energy-efficient DNN acceleration [2], [4], [22].", "purpose": "background"}, {"s": "W4236788275", "t": "W4254672563", "ctx": "Consequently, MCAs have been aggressively harnessed for energy-efficient DNN acceleration [2], [4], [22].", "purpose": "background"}, {"s": "W4243519499", "t": "W1542981317", "ctx": "Prior work has already observed that crossbar arrays using resistive memory are effective at performing many dot-product operations in parallel [33], [43], [53], [71], [78]. ... This is therefore an example of in-situ computing [2], [30], [53].", "purpose": "background"}, {"s": "W4243519499", "t": "W1937359183", "ctx": "Other emerging memory technologies (e.g., PCM) have also been used as synaptic weight elements [6], [68]. None of the above works are targeted at CNNs or DNNs.", "purpose": "background"}, {"s": "W4243519499", "t": "W4254672563", "ctx": "Chi et al. [10] propose PRIME, a morphable PIM structure for ReRAM based main memory with carefully designed peripheral circuits that allow arrays to be used as memory, scratchpads, and dot product engines for CNN workloads. The data encoding and pipelining in ISAAC and PRIME are both very different.", "purpose": "contrasts/critiques"}, {"s": "W4254672563", "t": "W1542981317", "ctx": "Recently, Presioso et al. fabricated a 12 × 12 ReRAM crossbar prototype with a fully operational neural network, successfully classifying 3 × 3-pixel black/white images into 3 categories [12].", "purpose": "background"}, {"s": "W4254672563", "t": "W4243519499", "ctx": "Recently, a full-fledged NN accelerator design based on ReRAM crossbars have been proposed, named ISAAC [39]. Most prior work exploits ReRAM either as DRAM/flash replacement [20], [28], [40] or as synapses for NN computation [10], [11], [12], [13], [38].", "purpose": "background"}, {"s": "W4280496502", "t": "W2949989598", "ctx": "FloatPIM [17] supports reduction by organizing reduction data in a bit-serial way to avoid extra data movement. But this scheme sacrifices parallelism in Transformer which usually has long vectors for reduction.", "purpose": "contrasts/critiques"}, {"s": "W4280592620", "t": "W2625840880", "ctx": "", "purpose": ""}, {"s": "W4280592620", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4280592620", "t": "W3111989171", "ctx": "", "purpose": ""}, {"s": "W4280592620", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4280592620", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4283733417", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4283733417", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4283733417", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W4283733417", "t": "W2948661249", "ctx": "To date, each type of analogue memory exhibits some form of non-ideal behaviour such as limited resistance contrast, significant non-linearity and stochasticity in conductance-vs-pulse characteristics, strong asymmetry during bidirectional programming, read noise, and conductance drift after programming to name a few15-19.", "purpose": "background"}, {"s": "W4283733417", "t": "W3003151806", "ctx": "To date, each type of analogue memory exhibits some form of non-ideal behaviour such as limited resistance contrast, significant non-linearity and stochasticity in conductance-vs-pulse characteristics, strong asymmetry during bidirectional programming, read noise, and conductance drift after programming to name a few15-19.", "purpose": "background"}, {"s": "W4283733417", "t": "W3005874416", "ctx": "As mentioned earlier, this can be mitigated using a drift compensation technique32, where activations are amplified close to their original levels using drift compensation factor alpha, which may or may not be uniform along the column-wise dimension of the crossbar array.", "purpose": "uses-method-or-tool"}, {"s": "W4283733417", "t": "W3013080934", "ctx": "Introducing such redundancy has been shown to offer accuracy benefits by effectively countering some of the variability present in analogue memory26,37,38.", "purpose": "background"}, {"s": "W4283733417", "t": "W3138725418", "ctx": "We have previously employed this weight programming time-scale as an effective compromise between conductance stability and programming speed for the programming of millions of weights40.", "purpose": "background"}, {"s": "W4283733417", "t": "W3148526109", "ctx": "By subjecting the DNN to memory and circuit non-idealities during training22-25, HWA training clearly makes the DNN more resilient to the various hardware non-idealities, and significantly enhances network accuracy relative to floating-point training across the board.", "purpose": "uses-method-or-tool"}, {"s": "W4283733417", "t": "W3195245399", "ctx": "The significance factor can be implemented in a number of ways, but is limited to discrete values in this case, which can be readily implemented by multiplying the pulse durations of the input activations applied to the MSP relative to the LSP30,31.", "purpose": "uses-method-or-tool"}, {"s": "W4283733417", "t": "W3195461290", "ctx": "Incorporating hardware non-idealities within DNN training (i.e., 'hardware-aware' algorithmic training) has been shown effective in making analogue memory-based DNNs more resilient to hardware imperfections22-25.", "purpose": "background"}, {"s": "W4285122104", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W3006908002", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W3011221635", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W3016762888", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W3111367661", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W3174812964", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4285122104", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4285263226", "t": "W2913104037", "ctx": "Second, multi-layer parallel architectures (e.g., ISAAC [5] and PUMA [7]) are capable of processing multiple CNN layers simultaneously, allowing multi-layer pipelines to maximize the throughput of a full CNN workload.", "purpose": "background"}, {"s": "W4285263226", "t": "W3194056411", "ctx": "In recent years, analog in memory compute (AIMC) arrays have attracted much attention in the accelerator design [3].", "purpose": "background"}, {"s": "W4285263226", "t": "W4243519499", "ctx": "Second, multi-layer parallel architectures (e.g., ISAAC [5] and PUMA [7]) are capable of processing multiple CNN layers simultaneously, allowing multi-layer pipelines to maximize the throughput of a full CNN workload.", "purpose": "baseline/comparison"}, {"s": "W4287736153", "t": "W2765081478", "ctx": "This approach has been demonstrated to solve linear equations [26] and in DNN inference and even training tasks [23], showing limited error in the computation and much higher efficiency compared to traditional approaches [2].", "purpose": "background"}, {"s": "W4287736153", "t": "W2794288888", "ctx": "Considering ReRAM-based IMC, Chen et al. [12] demonstrate significant computing parallelism, performing 8k MAC operations simultaneously.", "purpose": "background"}, {"s": "W4287736153", "t": "W2805362231", "ctx": "Charge-based memory technologies (e.g. SRAM [10], DRAM, Flash) and non-volatile (NV) resistive memory technologies [11] (e.g. ReRAM [12] PCM [2] and MRAM [13]) both serve as computing substrates for analog in-memory computing.", "purpose": "background"}, {"s": "W4287736153", "t": "W2899641901", "ctx": "Complex real-world neural networks mix MVMs with other workloads such as residuals, activation functions, or depth-wise convolutions; coupling the IMA with a single core, as has recently been proposed [6], will likely hit Amdahl's effect caused by the single-core bottleneck, hindering the whole computation performance.", "purpose": "contrasts/critiques"}, {"s": "W4287736153", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4287736153", "t": "W2948661249", "ctx": "Also, noise-robust networks are an active research field for IMC deployment [15].", "purpose": "background"}, {"s": "W4287736153", "t": "W3013080934", "ctx": "Both charge-based memory technologies (e.g. SRAM, DRAM, and flash) and resistance-based memory technologies (e.g. RRAM, PCM, and STT-MRAM) can serve as elements for such computational units [2].", "purpose": "background"}, {"s": "W4287736153", "t": "W3015980402", "ctx": "Other works show ReRAM-based IMC arrays as dense as 2Mb [24] or 4Mb [25], with peak energy efficiencies in the range of 120-200 TOPS/W within a power envelope of few milliwatts, suitable for tiny edge AI devices.", "purpose": "background"}, {"s": "W4287736153", "t": "W3138725418", "ctx": "", "purpose": ""}, {"s": "W4287736153", "t": "W3195245399", "ctx": "The programming of the IMA is done in a diagonal [27] or row-wise [39] fashion, therefore takes considerably larger time (20x to 30x higher) than merely performing a parallel MVM.", "purpose": "data/numbers"}, {"s": "W4287736153", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W4287736153", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4287736153", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W1542981317", "ctx": "Compute-in-memory (CIM) based on resistive random-access memory (RRAM) promises to meet such demand... thus eliminating power-hungry data movement between separate compute and memory [refs 2-5].", "purpose": "background"}, {"s": "W4292121737", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W2787453651", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W2803163155", "ctx": "...thus eliminating power-hungry data movement between separate compute and memory2-5.", "purpose": "background"}, {"s": "W4292121737", "t": "W2805362231", "ctx": "...thus eliminating power-hungry data movement between separate compute and memory2-5.", "purpose": "background"}, {"s": "W4292121737", "t": "W2913104037", "ctx": "Multi-core architecture design with network-on-chip that realizes efficient and versatile data transfers and inter-array pipelining is likely to be the next major challenge for RRAM-CIM [ISAAC, PUMA].", "purpose": "background"}, {"s": "W4292121737", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W3003821665", "ctx": "...thus eliminating power-hungry data movement between separate compute and memory2-5.", "purpose": "background"}, {"s": "W4292121737", "t": "W3006908002", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4292121737", "t": "W4243519499", "ctx": "Network-on-chip and program scheduling need to be carefully designed to achieve good end-to-end application-level energy efficiency [ISAAC, PUMA].", "purpose": "background"}, {"s": "W4293243554", "t": "W2612375349", "ctx": "[7, 24] utilize VAT based on known device variation (sigma) characterized from RRAM devices, while [5] combines VAT with dynamic precision quantization to mitigate the post-mapping accuracy loss.", "purpose": "background"}, {"s": "W4293243554", "t": "W2613989746", "ctx": "L. Song, X. Qian, H. Li, and Y. Chen, \"Pipelayer: A Pipelined Reram-Based Accelerator for Deep Learning,\" in HPCA. IEEE, 2017. [cited among background works on RRAM-based IMC architectures, ref. 20]", "purpose": "background"}, {"s": "W4293243554", "t": "W2946522000", "ctx": "Finally, we perform a hardware-aware training for the DNN by splitting the conv and FC layers into partial operations based on the IMC crossbar size (we use 64x64 [13]).", "purpose": "uses-method-or-tool"}, {"s": "W4293243554", "t": "W2948661249", "ctx": "However, RRAM device suffers from several non-idealities such as limited resistance levels, device-to-device write variations, stuck-at-faults, and limited Roff/Ron ratio, posing a significant challenge to designing reliable RRAM-based IMC architectures [5-12].", "purpose": "motivation"}, {"s": "W4293243554", "t": "W2949989598", "ctx": "", "purpose": ""}, {"s": "W4293243554", "t": "W3011221635", "ctx": "To mitigate the post-mapping accuracy loss in DNNs, variation-aware training (VAT) and special encoding schemes are employed [5-9, 13]. VAT exploits the inherent DNN redundancy by embedding the device variations (sigma) ... into the training process to achieve a variation-tolerant model.", "purpose": "background"}, {"s": "W4293243554", "t": "W3119537022", "ctx": "At the same time, [6, 9] propose to use a custom unary mapping scheme by mapping the MSB and LSB of the weights to RRAM devices based on the individual cell variations and bit significance. These approaches partially recover the accuracy but fail to consider the effect of activation quantization and the hardware implementation.", "purpose": "contrasts/critiques"}, {"s": "W4293243554", "t": "W3201198776", "ctx": "Compared against Multi-Objective Optimization of ReRAM Crossbars (Unary Opt [9]) as a state-of-the-art baseline in Table V: Unary Opt achieves 92.77% on VGG-16/CIFAR-10 and 62.69% on ResNet-18/ImageNet Top-1, improved by this work by 0.20% and 6.52% respectively.", "purpose": "baseline/comparison"}, {"s": "W4293243554", "t": "W4243519499", "ctx": "Prior works with RRAM-based crossbar architectures have shown up to 1,000x improvement in energy efficiency as compared to CPUs/GPUs [2-4]. ... RRAM-based IMC architectures provide a promising alternative to conventional von-Neumann architectures [2-4, 8, 19-21].", "purpose": "background"}, {"s": "W4300228436", "t": "W2945592020", "ctx": "", "purpose": ""}, {"s": "W4300228436", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W4300228436", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4300228436", "t": "W3013241373", "ctx": "", "purpose": ""}, {"s": "W4300228436", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4300228436", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W2787453651", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W2796472956", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W2899868573", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W3013241373", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W3091895175", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4307927141", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4310449176", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4310449176", "t": "W3041897167", "ctx": "", "purpose": ""}, {"s": "W4310449176", "t": "W3194056411", "ctx": "", "purpose": ""}, {"s": "W4310449176", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4310449176", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4311416617", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4311416617", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4311416617", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4311978413", "t": "W2765081478", "ctx": "", "purpose": ""}, {"s": "W4311978413", "t": "W2899641901", "ctx": "A dedicated line from an AIMC control pipeline can send signals and data directly to and from the AIMC tile's control unit, akin to a co-processor; this loosely-coupled style can be seen in [PUMA, Programmable Heterogeneous Microprocessor].", "purpose": "contrasts/critiques"}, {"s": "W4311978413", "t": "W2913104037", "ctx": "One way to address the limitations of standalone AIMC-based accelerators is to add local CPUs [PUMA et al.].", "purpose": "background"}, {"s": "W4311978413", "t": "W2948661249", "ctx": "Prior work includes iso-accuracy studies for convolutional neural networks (CNNs), recurrent neural networks (RNNs) and transformers, showing AIMC implementations address inference with high accuracies despite reduced precision weights.", "purpose": "background"}, {"s": "W4311978413", "t": "W3013080934", "ctx": "With analog in-memory computing (AIMC) certain computations directly take place where the data is located, exploiting device physics and circuit laws.", "purpose": "background"}, {"s": "W4311978413", "t": "W3015980402", "ctx": "The CPU-AIMC interplay nonetheless often is the run-time bottleneck in these systems, as AIMC tiles at competitive technology nodes typically operate on the order of hundreds of nanoseconds [citing 22nm ReRAM CIM macro and PCM tile work].", "purpose": "motivation"}, {"s": "W4311978413", "t": "W3138725418", "ctx": "The programming and reading of analog weight value are prone to various non-idealities, including noise, temporal conductance fluctuations and temperature-induced variations [citing PCM synaptic weight precision study].", "purpose": "background"}, {"s": "W4311978413", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W4311978413", "t": "W4225637124", "ctx": "Zheng et al. also use the ONNX framework as the front end for their event-driven cross-level simulation of processing-in-memory accelerators, while also incorporating elements for simulating memory access and interconnects.", "purpose": "baseline/comparison"}, {"s": "W4311978413", "t": "W4243519499", "ctx": "One approach to exploit in-memory computing for DNNs is to design stand-alone accelerators where multiple AIMC tiles and associated digital logic blocks are interconnected by a suitable communication fabric [ISAAC, Dazzi].", "purpose": "background"}, {"s": "W4312081519", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W4312081519", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W4312081519", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W4312081519", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4312081519", "t": "W3006908002", "ctx": "", "purpose": ""}, {"s": "W4312081519", "t": "W3107562138", "ctx": "", "purpose": ""}, {"s": "W4312081519", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4312141825", "t": "W4313170690", "ctx": "", "purpose": ""}, {"s": "W4312457094", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4312457094", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4312457094", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4312457094", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4312457094", "t": "W3111989171", "ctx": "", "purpose": ""}, {"s": "W4312457094", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4312457094", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W2910506572", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W3013407975", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W3091895175", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4312542636", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4312949026", "t": "W2899641901", "ctx": "", "purpose": ""}, {"s": "W4312949026", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4312949026", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4312993714", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4312993714", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4312993714", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4312993714", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4312993714", "t": "W3194056411", "ctx": "", "purpose": ""}, {"s": "W4312993714", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W3006908002", "ctx": "", "purpose": ""}, {"s": "W4313138950", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4313170690", "t": "W2805362231", "ctx": "With the increased computational demands of machine learning (ML) workloads, in-memory computing (IMC) [1] architectures have attracted considerable attention to address the processor-memory bottleneck in conventional von Neumann architectures through executing the logic functions directly on memory via changing the internal memory circuitry.", "purpose": "background"}, {"s": "W4313170690", "t": "W2913104037", "ctx": "Despite the potential benefits of the analog IMC architectures, one of the major factors limiting their wide use in practical ML applications is the large and energy-hungry signal conversion units required to change the computation domain from analog-to-digital (and vice versa) to compute the nonlinear vector operations, e.g. activation functions in DNNs [9].", "purpose": "background"}, {"s": "W4313251083", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W2740220207", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4313251083", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W4313254474", "t": "W1542981317", "ctx": "Compared to MRAM, RRAM and PCM offer the advantages of compact cell size, large ON/OFF ratio and multi-bit capability [78] [171] [178] [179].", "purpose": "background"}, {"s": "W4313254474", "t": "W2782791387", "ctx": "In [169] a RRAM based cross-bar array with off-chip peripheral circuits was built with a Ta/HFO2/Pd stack as a switching element accessible through a select transistor... The demonstration vehicle was a one-layer (96 x 40) network for hand written digit classification (MNIST)... Classification error was 89.9% which was 2.5% shy of theoretical expectation for the same configuration.", "purpose": "data/numbers"}, {"s": "W4313254474", "t": "W2785141883", "ctx": "It has been shown that On-resistance in the range of 100-200 kΩ leads to minimal IR drop for moderate crossbar array sizes (such as 64 x 64 or 128 x 128) [36].", "purpose": "data/numbers"}, {"s": "W4313254474", "t": "W2803163155", "ctx": "There have been an increasing number of experimental studies of all analog CIM that involve inference as well as training [58] [25] [53].", "purpose": "background"}, {"s": "W4313254474", "t": "W2805362231", "ctx": "the most competitive candidates at present among emerging memories are resistive random-access memory (RRAM) [76] [77] [78] [79] [80] [81] [82] [83] [84] [37], phase-change memory (PCM) [85] [34] [86], and magnetic random-access memory (MRAM) [87] [88] [89] [90] [91].", "purpose": "background"}, {"s": "W4313254474", "t": "W2807750997", "ctx": "the most competitive candidates at present among emerging memories are resistive random-access memory (RRAM) [76] [77] [78] [79] [80] [81] [82] [83] [84] [37]...", "purpose": "background"}, {"s": "W4313254474", "t": "W2896122000", "ctx": "The mechanism and operation of all analog MAC has also been described in detail elsewhere [59] [52] [57].", "purpose": "background"}, {"s": "W4313254474", "t": "W2909715355", "ctx": "Due to the analog nature of the MVM operations with crossbar memory arrays, the illustrated in-situ computation of MVM is prone to errors caused by various sources of device and circuit non-idealities [43, 45].", "purpose": "background"}, {"s": "W4313254474", "t": "W2923010225", "ctx": "Excellent recent reviews on these five types of memories, mentioned above, have been published earlier [94] [77] [95] [96] [97] [98] [99] [100] [101] [102] [103] [104].", "purpose": "background"}, {"s": "W4313254474", "t": "W2948661249", "ctx": "the most competitive candidates at present among emerging memories are resistive random-access memory (RRAM) ... phase-change memory (PCM) [85] [34] [86]...", "purpose": "background"}, {"s": "W4313254474", "t": "W3003821665", "ctx": "the most competitive candidates at present among emerging memories are resistive random-access memory (RRAM) [76] [77] [78] [79] [80] [81] [82] [83] [84] [37]...", "purpose": "background"}, {"s": "W4313254474", "t": "W3042468132", "ctx": "As is illustrated in Figure 5, ADC consumes about 60% of the total energy, and over 80% of the chip area in CIM hardware [27].", "purpose": "data/numbers"}, {"s": "W4313254474", "t": "W3195245399", "ctx": "It has been shown, however, that individual direct write introduces errors that cannot easily be compensated [65].", "purpose": "background"}, {"s": "W4313254474", "t": "W4283733417", "ctx": "As discussed earlier, the weight transfer into an analog storage mode requires special considerations [182] [183].", "purpose": "background"}, {"s": "W4313254474", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W2765081478", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W2896122000", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4319990485", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W4321488325", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W4321488325", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4321488325", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4321488325", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4321488325", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W4321488325", "t": "W3194056411", "ctx": "", "purpose": ""}, {"s": "W4321488325", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4322007931", "t": "W2612375349", "ctx": "Some researchers propose to first measure variation distribution and then map the weight according to the measured distribution [4, 8, 14]. This process needs a large amount of computation which is intolerable for edge devices.", "purpose": "contrasts/critiques"}, {"s": "W4322007931", "t": "W2625840880", "ctx": "Although [15] can also reach 95% recovery accuracy, our proposed method doesn't need the retraining process which is a very costly process for platforms [27].", "purpose": "baseline/comparison"}, {"s": "W4322007931", "t": "W2978384356", "ctx": "One is the retraining method [4, 15] and the other is the permutation of rows and columns of the weight matrix [23, 28]. ... both methods need SAF maps of crossbars and then perform complex algorithms to find the best permutation, which is not efficient for edge devices", "purpose": "contrasts/critiques"}, {"s": "W4322007931", "t": "W3011221635", "ctx": "Large weight matrices are always separated into pieces and then mapped to several MCAs [3].", "purpose": "background"}, {"s": "W4322007931", "t": "W3109300165", "ctx": "On MNIST dataset and with a 3-layer fully-connected network, the state-of-the-art method [29] can only increase the accuracy from 50% (without the method) to 80% (with the method).", "purpose": "baseline/comparison"}, {"s": "W4322007931", "t": "W4243519499", "ctx": "If all columns are computed together, each layer can be computed in 103 ns [18], which is overpowered for edge devices.", "purpose": "data/numbers"}, {"s": "W4323022446", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W2946659370", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W3013241373", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W4225637124", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4323022446", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4360831836", "t": "W2613989746", "ctx": "Specifically, PIM hardware with resistive random-access memory (RRAM, ReRAM, a.k.a. memristor) has been explored to build accelerators for deep learning models in numerous works [6, 10, 20, 42, 48]... Prior PIM-based designs [9, 10, 42, 48] have been built upon the WS dataflow, especially by unrolling the weight values... As a result, few RRAM-based PIMs can support the in situ training process [20, 48].", "purpose": "baseline/comparison"}, {"s": "W4360831836", "t": "W2785141883", "ctx": "We chose the zero-centered normal distribution to model the noise caused by nonideal properties like variation, nonlinearity, and asymmetry, following [65].", "purpose": "uses-method-or-tool"}, {"s": "W4360831836", "t": "W2899868573", "ctx": "It is well-known that ADCs exponentially undermine performance and energy efficiency [67, 71]. Fine-grained WS accelerators demand extra processing but do not resolve light models' utilization [67, 71].", "purpose": "motivation"}, {"s": "W4360831836", "t": "W2949989598", "ctx": "Because of the different disposition of elements, previous crossbar designs should separately hold transposed weight matrices in addition to the original weight [20, 48].", "purpose": "baseline/comparison"}, {"s": "W4360831836", "t": "W3005619596", "ctx": "For the evaluation, a customized simulator was implemented based on our circuit simulation results and NeuroSim+ [38, 39].", "purpose": "uses-method-or-tool"}, {"s": "W4360831836", "t": "W3111375540", "ctx": "", "purpose": ""}, {"s": "W4360831836", "t": "W3112740243", "ctx": "For the evaluation, a customized simulator was implemented based on our circuit simulation results and NeuroSim+ [38, 39].", "purpose": "uses-method-or-tool"}, {"s": "W4360831836", "t": "W3155456425", "ctx": "According to [66], a WS system with TaOx/HfOx RRAM shows an 11% accuracy drop in VGG8 on CIFAR10 when compared to GPU with floating-point arithmetic.", "purpose": "data/numbers"}, {"s": "W4360831836", "t": "W3191560475", "ctx": "As mentioned early, one 8-bit ADCs consumes energy as much as four 4-bit ADCs, not two [67]. Therefore, ADCs of INCA spend 5x less energy in total than ADCs of the baseline.", "purpose": "data/numbers"}, {"s": "W4360831836", "t": "W4243519499", "ctx": "For the baseline, we referred to a representative 2D accelerator design, ISAAC [42]. However, ISAAC only can support the feedforward phase for inference. Thus, we reflected the PipeLayer [48] in the baseline design for training.", "purpose": "baseline/comparison"}, {"s": "W4360831836", "t": "W4254672563", "ctx": "Specifically, PIM hardware with resistive random-access memory (RRAM, ReRAM, a.k.a. memristor) has been explored to build accelerators for deep learning models in numerous works [6, 10, 20, 42, 48].", "purpose": "background"}, {"s": "W4361857408", "t": "W2613989746", "ctx": "Existing studies have proposed various memristor-based PIM architecture and realize 2~3 orders of magnitude energy efficiency improvement compared with GPU and CMOS-based ASIC solutions [3] [4] [6] [5] [23].", "purpose": "background"}, {"s": "W4361857408", "t": "W2736591611", "ctx": "Furthermore, they utilize PIM simulators, e.g., MNSIM [16] and NeuroSim [17], to evaluate the PIM-based NN accuracy and other hardware performance.", "purpose": "uses-method-or-tool"}, {"s": "W4361857408", "t": "W2796472956", "ctx": "Therefore, PIM-based NN accelerators can improve the energy efficiency of NN computing by two to three orders of magnitude over GPU and CMOS ASIC solutions [3-7].", "purpose": "background"}, {"s": "W4361857408", "t": "W2899868573", "ctx": "On the one hand, the numbers of rows and columns of the crossbars (the basic computing units in PIM) are always the power of two, e.g., 64, 128, and 256 [36].", "purpose": "background"}, {"s": "W4361857408", "t": "W2945592020", "ctx": "", "purpose": ""}, {"s": "W4361857408", "t": "W3112740243", "ctx": "However, NACIM utilizes a time-consuming PIM simulator (i.e., NeuroSim [17]) as the performance evaluator, resulting in a tremendous search time cost (~59 GPU hours).", "purpose": "baseline/comparison"}, {"s": "W4361857408", "t": "W4243519499", "ctx": "Existing studies have proposed various memristor-based PIM architecture and realize 2~3 orders of magnitude energy efficiency improvement compared with GPU and CMOS-based ASIC solutions [3] [4] [6] [5] [23].", "purpose": "background"}, {"s": "W4361857408", "t": "W4254672563", "ctx": "Therefore, PIM-based NN accelerators can improve the energy efficiency of NN computing by two to three orders of magnitude over GPU and CMOS ASIC solutions [3-7].", "purpose": "background"}, {"s": "W4366389026", "t": "W2613989746", "ctx": "Furthermore, PIM accelerators often utilize Resistive-RAM (ReRAM) devices and ReRAM crossbars [5, 54, 56] for dense and efficient analog compute [34]... RAELLA replicates weights to increase throughput following previous work [24, 54, 56].", "purpose": "background"}, {"s": "W4366389026", "t": "W2740220207", "ctx": "Crossbars can compute with high parallelism, scaling to 1024 rows [32], but the area and energy of ADCs scale exponentially with resolution [65]... To process inputs, we use 4b pulse-train DACs for their simple hardware [32] and superior linearity [55].", "purpose": "uses-method-or-tool"}, {"s": "W4366389026", "t": "W2902501132", "ctx": "If there is space, weights are replicated in-crossbar to compute multiple convolution steps using a partial Toeplitz expansion [11, 24]. For a fair comparison, we modify ISAAC to support the partial-Toeplitz mappings [11, 24] that RAELLA supports, which increased the throughput of ISAAC by an additional 1-1.9x.", "purpose": "uses-method-or-tool"}, {"s": "W4366389026", "t": "W2910506572", "ctx": "Some designs prune DNNs [8, 26, 48, 75, 80] to reduce DNN weight count, so we call these designs Weight-Count-Limited.", "purpose": "background"}, {"s": "W4366389026", "t": "W2979663695", "ctx": "Alternatively, other designs use efficient lower-resolution ADCs to process high-resolution analog values from crossbars [5, 7, 24]... While dropping LSBs permits a lower saturation chance, it also necessarily loses fidelity in every psum.", "purpose": "contrasts/critiques"}, {"s": "W4366389026", "t": "W3015982917", "ctx": "RAELLA uses 2T2R devices, shown in Fig. 6, to realize analog subtraction in-crossbar. 2T2R, with two ReRAMs (2R) per weight accessed via two access transistors (2T), have been explored as a method to represent signed weights [3, 27, 28, 67, 74].", "purpose": "uses-method-or-tool"}, {"s": "W4366389026", "t": "W3042493405", "ctx": "Crossbars are dense, but architectures can spend 5 [24] to 50 [54] times more area on ADC than crossbars... TIMELY [24], a Sum-Fidelity-Limited architecture, achieves up to a 512x Converts/MAC reduction over [54] by using large crossbars and many bits per input/weight slice.", "purpose": "baseline/comparison"}, {"s": "W4366389026", "t": "W3112740243", "ctx": "DAC, input driver, and crossbar area/energy are generated using a modified NeuroSim [2, 44]... which captures the data-dependent energy consumption of analog components.", "purpose": "uses-method-or-tool"}, {"s": "W4366389026", "t": "W3184191382", "ctx": "TinyADC [79] retrains while pruning DNN weight bits, achieving impressive reductions in column sum resolution.", "purpose": "contrasts/critiques"}, {"s": "W4366389026", "t": "W3191560475", "ctx": "FORMS [80], a Weight-Count-Limited architecture, achieves a 2.0x MACs/DNN ... Like other PIM accelerators [24, 47, 54, 80], RAELLA is programmed once for many inferences to mitigate high ReRAM write energy [45].", "purpose": "baseline/comparison"}, {"s": "W4366389026", "t": "W3198899759", "ctx": "While DNN weight distributions are commonly cited as zero-mean [14, 73], a zero mean for all weight values over a DNN does not necessarily mean any given weight filter is zero-mean, nor that column sums are zero-mean... Offset encoding provides noise resistance [73], and Center+Offset increases bit sparsity and decreases noise.", "purpose": "extends/builds-on"}, {"s": "W4366389026", "t": "W3212662098", "ctx": "BRAHMS [57] tailors ADC quantization steps for each layer to maximize DNN accuracy under fidelity loss.", "purpose": "contrasts/critiques"}, {"s": "W4366389026", "t": "W4243519499", "ctx": "Compared to other low-accuracy-loss PIM accelerators [54], RAELLA can both lower ADC resolution and run DNNs with up to 14x fewer ADC conversions without sacrificing fidelity.", "purpose": "baseline/comparison"}, {"s": "W4366389026", "t": "W4254672563", "ctx": "PIM can operate directly in weight memory to reduce data movement [5] and use Resistive-RAM (ReRAM) for dense and efficient analog compute.", "purpose": "background"}, {"s": "W4376606760", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W3138725418", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4376606760", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4378800995", "t": "W2740220207", "ctx": "We achieve ∼ 8% reduction in training-energy for both models, calculated based on the data in [14].", "purpose": "data/numbers"}, {"s": "W4378800995", "t": "W2909715355", "ctx": "In recent years, several noise models [2, 19, 26] and crossbar-realistic DNN accuracy evaluation frameworks (Neurosim [17], RxNN [10], GenieX [6], Memtorch [13]) have been proposed that are integrated with hardware-aware re-training or fine-tuning of GPU-trained DNN weights", "purpose": "background"}, {"s": "W4378800995", "t": "W2948661249", "ctx": "Drift noiseaware BN adaptation can maintain the accuracy of crossbar-mapped DNNs till a retention time T beyond which the accuracy dramatically decreases [12].", "purpose": "background"}, {"s": "W4378800995", "t": "W3006908002", "ctx": "However, this hardware-integrated re-training can lead to a huge increase in the overall training cost in terms of GPUhours [16, 17, 20].", "purpose": "motivation"}, {"s": "W4378800995", "t": "W3011221635", "ctx": "In recent years, several noise models [2, 19, 26] and crossbar-realistic DNN accuracy evaluation frameworks (Neurosim [17], RxNN [10], GenieX [6], Memtorch [13]) have been proposed", "purpose": "background"}, {"s": "W4378800995", "t": "W3013080934", "ctx": "In the context of hardware implementation of DNNs for resource-constrained edge platforms, In-Memory Computing (IMC) systems, such as analog crossbar-arrays that alleviate the ‘memory-wall’ bottleneck of von-Neumann architectures are gaining popularity [21].", "purpose": "background"}, {"s": "W4378800995", "t": "W3030670306", "ctx": "In recent years, several noise models [2, 19, 26] and crossbar-realistic DNN accuracy evaluation frameworks ... have been proposed that are integrated with hardware-aware re-training or fine-tuning of GPU-trained DNN weights", "purpose": "background"}, {"s": "W4378800995", "t": "W3112740243", "ctx": "Note, we realize 8-bit weights using the 4-bit memristive devices via bit-slicing [17] and the input activations to the crossbars are assumed to be 8-bits.", "purpose": "uses-method-or-tool"}, {"s": "W4378800995", "t": "W3148526109", "ctx": "For works that support on-chip training and inference using realistic IMC crossbar platforms for forward and backward propagation stages, fine-tuning (or re-programming) the weights (or memristive conductances) of a pre-trained DNN on hardware to mitigate accuracy losses due to noise and quantization effects becomes highly compute- & memory-intensive [11, 17, 18].", "purpose": "motivation"}, {"s": "W4378800995", "t": "W3198405160", "ctx": "Also, the resistive non-idealities in the crossbars (see Fig. 1) are as follows: Rdriver = 1kΩ, Rwire_row = 5Ω, Rwire_col = 10Ω and Rsense = 1kΩ [3, 4].", "purpose": "data/numbers"}, {"s": "W4378800995", "t": "W4319990485", "ctx": "Analog IMC platforms are susceptible to various non-idealities arising from the device-to-device variations and temporal conductance drift of the memristive devices as well as from the parasitic resistances of the metallic interconnects in the crossbar-arrays [2, 6, 10, 22].", "purpose": "background"}, {"s": "W4378800995", "t": "W4386293192", "ctx": "This shows that resistive non-idealities, although can disrupt a DNN’s performance on crossbars, can be totally mitigated with the help of BN fine-tuning, without the need for parasitic noise-aware re-training of weights as proposed in [16, 19, 20].", "purpose": "contrasts/critiques"}, {"s": "W4379116135", "t": "W2899641901", "ctx": "For this reason, few recent works [8]-[10] proposed the integration of nvAIMC cores into digital System-on-Chips (SoC), exploiting a mix of nvAIMC cores and more flexible specialized and programmable digital processors.", "purpose": "background"}, {"s": "W4379116135", "t": "W2913104037", "ctx": "Shafiee et al. [12] and Ankit et al. [13] target VGG-like networks featuring no residual layers, nicely fitting mapping on pipelined data-flow architectures. However, DNNs generally feature data flow graph loops (e.g., residual layers) that make a straightforward pipelining implementation much more challenging.", "purpose": "contrasts/critiques"}, {"s": "W4379116135", "t": "W3013080934", "ctx": "In recent years, Analog In-Memory Computing (AIMC) has been a widely studied computing paradigm since it promises outstanding performance and energy efficiency on MVM operations [1].", "purpose": "background"}, {"s": "W4379116135", "t": "W3194056411", "ctx": "Moreover, a further challenge is the fabricable size of nvIMC devices, which de-facto is limited to 1024x1024 with up to 8-bit equivalent memory cells [4].", "purpose": "background"}, {"s": "W4379116135", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4379116135", "t": "W4210530509", "ctx": "In this work, we assume an MVM to be executed in 130 ns as reported in Khaddam et al. [7].", "purpose": "data/numbers"}, {"s": "W4379116135", "t": "W4243519499", "ctx": "Shafiee et al. [12] and Ankit et al. [13] target VGG-like networks featuring no residual layers, nicely fitting mapping on pipelined data-flow architectures.", "purpose": "contrasts/critiques"}, {"s": "W4379116135", "t": "W4287736153", "ctx": "Each cluster also includes a nvAIMC Accelerator (IMA) sharing the same multi-banked memory as the CORES for efficient communication, similarly to the architecture presented in Garofalo et al. [9].", "purpose": "uses-method-or-tool"}, {"s": "W4379527483", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W4379527483", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4379527483", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4379527483", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4379527483", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4379527483", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4379527483", "t": "W4226111665", "ctx": "", "purpose": ""}, {"s": "W4379527483", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4381233128", "t": "W2613989746", "ctx": "Recently, various hardware accelerators have been proposed to improve the efficiency and performance of traditional deep learning networks [4], [12]-[16]. However, they are not optimized to process the unique computational kernels of Transformers described in section II.", "purpose": "background"}, {"s": "W4381233128", "t": "W2913104037", "ctx": "Finally, we integrated both the Projection Engine and Attention Engine into PUMAsim [14] to obtain the execution traces and estimate the overall latency and energy.", "purpose": "uses-method-or-tool"}, {"s": "W4381233128", "t": "W2997247951", "ctx": "NVM devices also have very limited endurance, only about 10^6-10^9 conservative writes [8]-[10] which degrades the lifetime of these devices swiftly and limits their applicability to Transformers.", "purpose": "motivation"}, {"s": "W4381233128", "t": "W3006908002", "ctx": "Due to the analog nature of computations in X-Former, functional errors are introduced in the inference pass that impacts the overall application level accuracy [33], [34].", "purpose": "background"}, {"s": "W4381233128", "t": "W3042468132", "ctx": "This is a challenge due to NVMs requiring atleast one to two orders of magnitude higher latency and energy/bit depending on the NVM device compared to SRAM for the same technology node [8]-[10].", "purpose": "motivation"}, {"s": "W4381233128", "t": "W3111375540", "ctx": "The existing processing in-memory architectures on accelerating Transformers are [25] and [26]. Both the works use NVM crossbars to accelerate both MVM_Static and MVM_Dynamic operations. While they propose techniques to reduce latency of reprogramming the NVM crossbars, these devices offer very low endurance which can degrade their lifetime quickly.", "purpose": "contrasts/critiques"}, {"s": "W4381233128", "t": "W4243519499", "ctx": "Recently, various hardware accelerators have been proposed to improve the efficiency and performance of traditional deep learning networks [4], [12]-[16]. However, they are not optimized to process the unique computational kernels of Transformers described in section II.", "purpose": "background"}, {"s": "W4381733878", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4381733878", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W4381733878", "t": "W3111375540", "ctx": "", "purpose": ""}, {"s": "W4381733878", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W4381733878", "t": "W4200149283", "ctx": "", "purpose": ""}, {"s": "W4381733878", "t": "W4205363571", "ctx": "", "purpose": ""}, {"s": "W4381733878", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4381733878", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4383501742", "t": "W2612375349", "ctx": "Moreover, some works [17, 18] prevent large weights from mapping to high variation memristors.", "purpose": "contrasts/critiques"}, {"s": "W4383501742", "t": "W2807750997", "ctx": "First, on-chip training inherently adapts the weights to conductance variation as the network is trained on the CIM chip [13, 14]. However, it is not scalable due to individual training necessity for each chip, high energy consumption, and endurance issues.", "purpose": "contrasts/critiques"}, {"s": "W4383501742", "t": "W2913104037", "ctx": "It is based on in-situ multiply-accumulate (IMA) unit in stateof-the-art CIM architectures [29, 33].", "purpose": "uses-method-or-tool"}, {"s": "W4383501742", "t": "W2948661249", "ctx": "Alternatively, noise estimated from a non-extensive chip characterization can be injected in off-chip training [19–24] to enhance the network’s tolerance towards errors due to conductance variation. However, this approach fails to address the issue of reducing such errors, as memristors can still get mapped to high variation conductance states", "purpose": "contrasts/critiques"}, {"s": "W4383501742", "t": "W3013080934", "ctx": "It uses emerging non-volatile memory technologies such as memristors, also called resistive random access memories (RRAMs), which are highly scalable and compatible with CMOS technology [11].", "purpose": "background"}, {"s": "W4383501742", "t": "W3016762888", "ctx": "Second, off-chip training using a hardware-calibrated software model of conductance variation [15, 16] is also not scalable, as each chip requires individual characterization and training.", "purpose": "contrasts/critiques"}, {"s": "W4383501742", "t": "W3020429010", "ctx": "Moreover, some works [17, 18] prevent large weights from mapping to high variation memristors. This requires extensive chip characterization and does not address errors due to the accumulation of variations in small weights.", "purpose": "contrasts/critiques"}, {"s": "W4383501742", "t": "W3157191380", "ctx": "(a) Concept illustration. (b) Measurements in [31]. Fig. 3. Conductance variation in memristors.", "purpose": "data/numbers"}, {"s": "W4383501742", "t": "W4243519499", "ctx": "For example, consider 2-bit memristors (slices), 8-bit fixed-point weights (6-bit fraction), and CIM architecture in [29]. ... It then shifts the 2’s complement weight range by 27 to overcome the difficulty in isolating the sign contribution from a multi-bit slice [29].", "purpose": "uses-method-or-tool"}, {"s": "W4383501742", "t": "W4319990485", "ctx": "Alternatively, noise estimated from a non-extensive chip characterization can be injected in off-chip training [19–24] to enhance the network’s tolerance towards errors due to conductance variation.", "purpose": "contrasts/critiques"}, {"s": "W4383753658", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W2883149906", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W4200477077", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4383753658", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4385255585", "t": "W2945592020", "ctx": "", "purpose": ""}, {"s": "W4385255585", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4385255585", "t": "W3127794782", "ctx": "", "purpose": ""}, {"s": "W4385255585", "t": "W4200001938", "ctx": "", "purpose": ""}, {"s": "W4385255585", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4385656513", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4385656513", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W4385656513", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4385656513", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4385656513", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W4385656513", "t": "W3111375540", "ctx": "", "purpose": ""}, {"s": "W4385656513", "t": "W4226111665", "ctx": "", "purpose": ""}, {"s": "W4385679805", "t": "W2785141883", "ctx": "Due to the fluctuation of devices, it is currently not feasible for large-scale arrays. The two-cell-one-weight method depicted is thus used [16].", "purpose": "uses-method-or-tool"}, {"s": "W4385679805", "t": "W3107562138", "ctx": "...the network size is at least one order smaller and yet the inference results is comparable to the conventional CNN based memristor accelerator models [26-28].", "purpose": "baseline/comparison"}, {"s": "W4385679805", "t": "W3111375540", "ctx": "For example, the self-attention operation is decomposed to reduce the frequency of intermediate results reloading and transfers the Softmax function to logical inference with lookup table [24]. However, these reported solutions still require considerable computation resources.", "purpose": "motivation"}, {"s": "W4385679805", "t": "W3112740243", "ctx": "...the network size is at least one order smaller and yet the inference results is comparable to the conventional CNN based memristor accelerator models [26-28].", "purpose": "baseline/comparison"}, {"s": "W4385679805", "t": "W3209892756", "ctx": "The implementations of Transformer structure on memristor crossbar array have been reported in literature [23].", "purpose": "background"}, {"s": "W4385679805", "t": "W4312081519", "ctx": "After the weight mapping to crossbar array, the non-idealities-aware training is carried out [31].", "purpose": "extends/builds-on"}, {"s": "W4385768723", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W3036663566", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W4200477077", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W4226111665", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4385768723", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4385896568", "t": "W2782791387", "ctx": "Early works on performing neural network inference with AIMC showed promising accuracy results in mixed hardware/software implementations, where functionalities such as digital-to-analog and analog-to-digital conversions, activation functions, and other necessary digital operations were implemented with off-chip software or hardware8-12.", "purpose": "background"}, {"s": "W4385896568", "t": "W2948661249", "ctx": "Prior to being deployed on the chip, the networks are trained in a hardware-aware manner by injecting noise on the synaptic weights to improve their resilience to hardware nonidealities12, using the publicly available IBM Analog Hardware Acceleration Kit38.", "purpose": "uses-method-or-tool"}, {"s": "W4385896568", "t": "W3003151806", "ctx": "In order to make the model more robust to noise, we perturb the weights of each tile according to a model simulating two times the PCM programming noise derived experimentally in Ref. 46.", "purpose": "uses-method-or-tool"}, {"s": "W4385896568", "t": "W3003821665", "ctx": "Early works on performing neural network inference with AIMC showed promising accuracy results in mixed hardware/software implementations ... off-chip software or hardware8-12.", "purpose": "background"}, {"s": "W4385896568", "t": "W3013080934", "ctx": "Analog in-memory computing (AIMC) with spatially instantiated synaptic weights holds high promise to overcome this challenge, by performing matrix-vector multiplications (MVMs) directly within the network weights stored on a chip to execute an inference workload2-7.", "purpose": "background"}, {"s": "W4385896568", "t": "W3041897167", "ctx": "Analog in-memory computing (AIMC) with spatially instantiated synaptic weights holds high promise to overcome this challenge, by performing matrix-vector multiplications (MVMs) directly within the network weights stored on a chip to execute an inference workload2-7.", "purpose": "background"}, {"s": "W4385896568", "t": "W3148526109", "ctx": "Prior to being deployed on the chip, the networks are trained in a hardware-aware manner by injecting noise on the synaptic weights to improve their resilience to hardware nonidealities12, using the publicly available IBM Analog Hardware Acceleration Kit38 (see Methods for details about the training procedure).", "purpose": "uses-method-or-tool"}, {"s": "W4385896568", "t": "W3194056411", "ctx": "Analog in-memory computing (AIMC) with spatially instantiated synaptic weights holds high promise to overcome this challenge, by performing matrix-vector multiplications (MVMs) directly within the network weights stored on a chip to execute an inference workload2-7.", "purpose": "background"}, {"s": "W4385896568", "t": "W3195245399", "ctx": "Both digital20,22 (1 device corresponds to 1 weight bit) and analog (1 device encodes an entire weight)21,25 storage of weights in those devices have been explored in the recent AIMC chips.", "purpose": "contrasts/critiques"}, {"s": "W4385896568", "t": "W4210530509", "ctx": "The design is based on the fully-integrated standalone PCM-based single-core chip presented in Ref. 18, with the addition of the link controller for transmitting and receiving data across different cores.", "purpose": "extends/builds-on"}, {"s": "W4385896568", "t": "W4243519499", "ctx": "Analog in-memory computing (AIMC) with spatially instantiated synaptic weights holds high promise to overcome this challenge, by performing matrix-vector multiplications (MVMs) directly within the network weights stored on a chip to execute an inference workload2-7.", "purpose": "background"}, {"s": "W4385896568", "t": "W4292121737", "ctx": "Both digital20,22 (1 device corresponds to 1 weight bit) and analog (1 device encodes an entire weight)21,25 storage of weights in those devices have been explored in the recent AIMC chips.", "purpose": "contrasts/critiques"}, {"s": "W4385896568", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4386100686", "t": "W2740220207", "ctx": "However, several NVM compute-in-memory studies have focused on the macro-level32,34,39,40,41, without accounting for data transport, control or chip infrastructure (such as clocking) costs. They are also usually at a much smaller scale ... than the work here.", "purpose": "contrasts/critiques"}, {"s": "W4386100686", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4386100686", "t": "W2948661249", "ctx": "Analog in-memory computing (analog-AI)3-7 can provide better energy efficiency by performing matrix-vector multiplications in parallel on 'memory tiles'.", "purpose": "background"}, {"s": "W4386100686", "t": "W3003821665", "ctx": "Analog in-memory computing (analog-AI)3-7 can provide better energy efficiency by performing matrix-vector multiplications in parallel on 'memory tiles'.", "purpose": "background"}, {"s": "W4386100686", "t": "W3195245399", "ctx": "Analog in-memory computing (analog-AI)3-7 can provide better energy efficiency by performing matrix-vector multiplications in parallel on 'memory tiles'.", "purpose": "background"}, {"s": "W4386100686", "t": "W3195461290", "ctx": "To make the network more resilient to analog noise23-26, we retrained it while including weight and [output] noise during training.", "purpose": "uses-method-or-tool"}, {"s": "W4386100686", "t": "W4210530509", "ctx": "Analog in-memory computing (analog-AI)3-7 can provide better energy efficiency by performing matrix-vector multiplications in parallel on 'memory tiles'.", "purpose": "background"}, {"s": "W4386100686", "t": "W4292121737", "ctx": "Analog in-memory computing (analog-AI)3-7 can provide better energy efficiency by performing matrix-vector multiplications in parallel on 'memory tiles'.", "purpose": "background"}, {"s": "W4386100686", "t": "W4313251083", "ctx": "A highly heterogeneous and programmable accelerator architecture for analog AI has been introduced20 for which system-level performance assessments have predicted energy efficiencies 40-140 times higher than those of cutting-edge graphics processing units. However, this simulation study required several design assumptions that have yet to be demonstrated in HW.", "purpose": "extends/builds-on"}, {"s": "W4386293192", "t": "W2612375349", "ctx": "Emerging memory devices such as PCM exhibit imperfect yield, and some fraction of the devices in a given crossbar array will simply not switch properly30,75.", "purpose": "background"}, {"s": "W4386293192", "t": "W2803163155", "ctx": "Although some promising, small-sized DNN prototype demonstrations exist43–49, it remains unclear how robust the AIMC deployment of realistically sized AI workloads will be.", "purpose": "motivation"}, {"s": "W4386293192", "t": "W2899641901", "ctx": "This enables approximate MVM computation directly in-memory, by applying activation vectors (as voltages or pulse durations) to the crossbar array, and then reading out analog physical quantities (instantaneous current or accumulated charge)16–18.", "purpose": "background"}, {"s": "W4386293192", "t": "W2909715355", "ctx": "Some aspects of our AIMC crossbar model have been investigated individually in earlier studies, such as the effect of ADC/DAC quantization, IR-drop, and general read noise55–57, as well as data-dependent long-term noise38.", "purpose": "background"}, {"s": "W4386293192", "t": "W2948661249", "ctx": "A few previous studies have attempted to improve the robustness of DNNs to nonidealities by noise-aware training, where multiplicative or additive Gaussian noise38,41 is added to weights or activations during training.", "purpose": "extends/builds-on"}, {"s": "W4386293192", "t": "W3003151806", "ctx": "We mainly investigate the situation where all weight-related parameters have been carefully calibrated to existing PCM hardware31, however, the model can be adapted to other memory technologies as well (see Supplementary Notes B.2).", "purpose": "uses-method-or-tool"}, {"s": "W4386293192", "t": "W3003821665", "ctx": "Although some promising, small-sized DNN prototype demonstrations exist43–49, it remains unclear how robust the AIMC deployment of realistically sized AI workloads will be.", "purpose": "motivation"}, {"s": "W4386293192", "t": "W3005619596", "ctx": "Some aspects of our AIMC crossbar model have been investigated individually in earlier studies, such as the effect of ADC/DAC quantization, IR-drop, and general read noise55–57", "purpose": "background"}, {"s": "W4386293192", "t": "W3005874416", "ctx": "For evaluation times teval long after NVM programming, the conductance drift Eq. (8) can be compensated in the digital domain without any expensive re-programming36,73.", "purpose": "uses-method-or-tool"}, {"s": "W4386293192", "t": "W3006908002", "ctx": "We chose to intentionally ignore static crossbar effects that would change the conductance value systematically55,60, since read–write-verify conductance programming can readily adapt to such effects.", "purpose": "contrasts/critiques"}, {"s": "W4386293192", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4386293192", "t": "W3138725418", "ctx": "", "purpose": ""}, {"s": "W4386293192", "t": "W3148526109", "ctx": "Functions for our standard evaluation process are provided in an open-source IBM Analog Hardware Acceleration Toolkit (AIHWKit)50, enabling future studies on noise robustness for AIMC to build seamlessly upon our work.", "purpose": "uses-method-or-tool"}, {"s": "W4386293192", "t": "W3195245399", "ctx": "However, our analysis only assumes one pair of conductances per weight —since many existing AIMC designs provide multiple pairs of PCM devices per weight44,47, such additional redundancy can potentially counteract such stringent device yield requirements.", "purpose": "contrasts/critiques"}, {"s": "W4386293192", "t": "W3195461290", "ctx": "Injecting noise to improve robustness to nonidealities was suggested by a number of studies38,40,41, and has been one of the hallmarks of HWA training for AIMC.", "purpose": "extends/builds-on"}, {"s": "W4386293192", "t": "W4283733417", "ctx": "That said, our HWA training approach could readily be combined with more sophisticated online compensation methods, with on-chip or chip-in-the-loop training, or with more than one device pair used per weight, including optimization of how weights are assigned across these conductances62.", "purpose": "background"}, {"s": "W4386293192", "t": "W4292121737", "ctx": "Some prior works propose using on-chip or chip-in-the-loop training methods38,43,49,55,61, which can greatly increase the attainable accuracy by addressing the speciﬁc fabrication variations found on that particular chip. However, we strongly believe that the time and cost of such individualized preparation is likely to be untenable for widespread deployment.", "purpose": "contrasts/critiques"}, {"s": "W4386293192", "t": "W4313251083", "ctx": "In terms of AIMC workload execution latency and system mapping51, CNNs are already less well-suited for resistive crossbar arrays due to the uneven temporal reuse between layers and spatial underutilization of the large analog tiles by the small kernel matrices (see Table 1), although some optimization and mapping tricks52 are available.", "purpose": "background"}, {"s": "W4386293192", "t": "W4385896568", "ctx": "For instance in a recent study54, a ResNet9 CNN was trained with a similar general HWA training approach yielding vastly improved AIMC accuracy in hardware.", "purpose": "background"}, {"s": "W4386352784", "t": "W2948661249", "ctx": "Many types of memory devices, including Flash memory, PCM, and Resistive Random Access Memory (RRAM), can be used for IMC [2].", "purpose": "background"}, {"s": "W4386352784", "t": "W3013080934", "ctx": "Analog IMC [1] can provide radical improvements in performance and power efficiency, by leveraging the physical properties of memory devices to perform computation and storage at the same physical location.", "purpose": "background"}, {"s": "W4386352784", "t": "W3148526109", "ctx": "Each sampled architecture is trained using different levels of weight noise and HWA training hyper-parameters using the AIHWKIT [21].", "purpose": "uses-method-or-tool"}, {"s": "W4386352784", "t": "W4313251083", "ctx": "We conducted power performance simulations for AnalogNAS T500 and ResNet32 models using a 2D-mesh based heterogeneous analog IMC system with the simulation tool presented in [46].", "purpose": "uses-method-or-tool"}, {"s": "W4386352784", "t": "W4385896568", "ctx": "An experimental hardware accuracy validation study was performed using a 64-core IMC chip based on PCM [44].", "purpose": "uses-method-or-tool"}, {"s": "W4386352784", "t": "W4386293192", "ctx": "The AIHWKIT is an open-source Python toolkit for exploring and using the capabilities of in-memory computing devices in the context of artificial intelligence and has been used for HWA training of standard DNNs with hardware-calibrated device noise and drift models [22].", "purpose": "uses-method-or-tool"}, {"s": "W4386763580", "t": "W2899868573", "ctx": "Nonetheless, related optimizations such as mixed size crossbars [13] and low-bit ADCs [14] are compatible with this abstract architecture.", "purpose": "background"}, {"s": "W4386763580", "t": "W2913104037", "ctx": "As a comparison, we faithfully implement the PUMA dataflow under our framework and it is called a PUMA-like dataflow.", "purpose": "baseline/comparison"}, {"s": "W4386763580", "t": "W3042468132", "ctx": "The 2D crossbar structure formed by NVM devices has attracted growing interest due to its high memory density and parallel in-situ computing properties [4].", "purpose": "background"}, {"s": "W4386763580", "t": "W3212662098", "ctx": "There are previous works (e.g., [5]-[9]) proposing NVM crossbar-based PIM DNN accelerators. However, they mainly focus on the design of specific architectures and lack consideration of the execution details of DNNs.", "purpose": "motivation"}, {"s": "W4386763580", "t": "W4243519499", "ctx": "Our proposed abstract architecture is compatible with the Crossbar/IMA/Tile/Chip structure widely adopted in previous work [5].", "purpose": "extends/builds-on"}, {"s": "W4386764227", "t": "W3111375540", "ctx": "For the baseline NVPIM accelerators, we quantitatively compare our design with ReTransformer [3], as implemented with our cycle-accurate simulator. ReTransformer is designed for dense attention computation, so we apply the method proposed in SRE [6] to support the sparse attention.", "purpose": "baseline/comparison"}, {"s": "W4386764227", "t": "W4243519499", "ctx": "For the NVPIM bank, we use the memory array model from [9].", "purpose": "uses-method-or-tool"}, {"s": "W4386764227", "t": "W4254672563", "ctx": "We select ReRAM as our target device because of its high density and energy efficiency, as shown in previous designs for other neural networks [8], [9].", "purpose": "background"}, {"s": "W4386859314", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4386859314", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4386859314", "t": "W3127794782", "ctx": "", "purpose": ""}, {"s": "W4386859314", "t": "W4200001938", "ctx": "", "purpose": ""}, {"s": "W4386859314", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4386859314", "t": "W4300228436", "ctx": "", "purpose": ""}, {"s": "W4388052862", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4388052862", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W4388052862", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4388052862", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W4388052862", "t": "W4285263226", "ctx": "", "purpose": ""}, {"s": "W4388052862", "t": "W4293243554", "ctx": "", "purpose": ""}, {"s": "W4388052862", "t": "W4312141825", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W2899868573", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W3212662098", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4388210331", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4388893898", "t": "W2613989746", "ctx": "Several RRAM-based CIM architectures have been presented [6]-[8], [18].", "purpose": "background"}, {"s": "W4388893898", "t": "W2913104037", "ctx": "To achieve maximum flexibility and scalability, the MVM units are often embedded in CIM cores, which can communicate with each other over a bus system [6], [7].", "purpose": "background"}, {"s": "W4388893898", "t": "W3211168157", "ctx": "Multiple RRAM devices can be arranged in crossbar structures to enable in-memory computing [16].", "purpose": "background"}, {"s": "W4388893898", "t": "W4243519499", "ctx": "Previous works presented accelerator architectures that use RRAM crossbars as matrix-vector multiplication (MVM) units [5]-[8]. These architectures are designed hierarchically to scale from single MVM units to complex multi-core systems.", "purpose": "background"}, {"s": "W4388893898", "t": "W4254672563", "ctx": "Several RRAM-based CIM architectures have been presented [6]-[8], [18]. They aim at efficient and parallel execution of MVMs.", "purpose": "background"}, {"s": "W4388893898", "t": "W4292121737", "ctx": "Performing MVMs is significantly faster than programming the crossbar cells [5]. If the accelerator provides a sufficient number of crossbars, the weights should therefore be programmed only once to ensure an efficient inference phase.", "purpose": "motivation"}, {"s": "W4389082012", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W2736591611", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W2925767305", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3003151806", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3005619596", "ctx": "Framework comparison table lists NeuroSim, IBM Analog Hardware Acceleration Kit, CrossSim, XB-SIM, and MemTorch as the actively maintained/compared AIMC simulation toolkits, evaluated on ML library, network types supported (incl. Recurrent/Transformer), accuracy estimation, HW-calibration, and on-chip training/inference support.", "purpose": "baseline/comparison"}, {"s": "W4389082012", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3041897167", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3112740243", "ctx": "Framework comparison table lists NeuroSim, IBM Analog Hardware Acceleration Kit, CrossSim, XB-SIM, and MemTorch as the actively maintained/compared AIMC simulation toolkits, evaluated on ML library, network types supported (incl. Recurrent/Transformer), accuracy estimation, HW-calibration, and on-chip training/inference support.", "purpose": "baseline/comparison"}, {"s": "W4389082012", "t": "W3138725418", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3148526109", "ctx": "The AIHWKit toolkit itself is referenced to its earlier introductory conference paper describing a flexible and fast PyTorch toolkit for simulating training and inference on analog crossbar arrays.", "purpose": "extends/builds-on"}, {"s": "W4389082012", "t": "W3194056411", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4389082012", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4389166698", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4389166698", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4389166698", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4389166698", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4389166767", "t": "W4285263226", "ctx": "\"Similarly, for mapping space explorations, most of the focus has been dedicated to AIMC designs, while lacking DIMC assessment [18], [19], [22], [23].\" (ref [22] = AERO)", "purpose": "background"}, {"s": "W4389166767", "t": "W4311416617", "ctx": "\"Published models however primarily focus on AIMC designs [1], [15]-[21], while there is a lack of DIMC modeling efforts.\" (ref [17] = SACA, one of the cited AIMC-only analytical/simulation frameworks)", "purpose": "contrasts/critiques"}, {"s": "W4389166806", "t": "W2612375349", "ctx": "Notably, softwarebased techniques [4, 6, 7] have aimed to lessen the impact of ReRAM's variation by retraining or fine-tuning the DNNs to adapt to the non-ideal distribution of ReRAM resistance. However, these methods can be cost-prohibitive due to the required re-training processes", "purpose": "contrasts/critiques"}, {"s": "W4389166806", "t": "W2794288888", "ctx": "Several works have been proposed to ensure reliable operations with a low Rratio ReRAM device [5, 9–12].", "purpose": "background"}, {"s": "W4389166806", "t": "W2795127895", "ctx": "[15]–[17] have used ECC such as AN code, Low Density Parity Check (LDPC) or successive error correction to lessen variation in the ReRAMbased PIM. Although proven effective, such techniques require a large power and latency overhead to encode and decode data", "purpose": "contrasts/critiques"}, {"s": "W4389166806", "t": "W2948661249", "ctx": "Processing-In Memory (PIM) architecture, utilizing Resistive Random Access Memory (ReRAM), offers a promising solution to address the limitations of conventional von Neumann architecture [1]–[3].", "purpose": "background"}, {"s": "W4389166806", "t": "W4243519499", "ctx": "The simulations focus on a ReRAM-based DNN accelerator with a hardware configuration based on ISAAC architecture [1].", "purpose": "uses-method-or-tool"}, {"s": "W4389166806", "t": "W4254672563", "ctx": "Processing-In Memory (PIM) architecture, utilizing Resistive Random Access Memory (ReRAM), offers a promising solution to address the limitations of conventional von Neumann architecture [1]–[3].", "purpose": "background"}, {"s": "W4390017976", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4390017976", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4390017976", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W4390017976", "t": "W4280496502", "ctx": "", "purpose": ""}, {"s": "W4390017976", "t": "W4381233128", "ctx": "", "purpose": ""}, {"s": "W4390241252", "t": "W2910506572", "ctx": "\"Direct application of current ReRAM-based sparse methods [17, 28] to ReRAM-based SDDMM and SpMM operations will achieve inferior performance (for details to see IV-C and IV-D).\" / \"Many ReRAM-based SpMM solutions [17, 28] have been proposed.\"", "purpose": "contrasts/critiques"}, {"s": "W4390241252", "t": "W3209892756", "ctx": "\"Utilizing the in-situ processing ability of ReRAM arrays, there emerge ReRAM-based PIM-featured solutions to accelerate traditional neural network [27] and the dense attention mechanism [11, 36].\" ... \"Even worse, the write operation works serial with the VMM operation and greatly increases the latency, just as the calculation mode of ReBERT [11] shown in Figure 4 (a).\"", "purpose": "baseline/comparison"}, {"s": "W4390241252", "t": "W4243519499", "ctx": "\"Second, the Z matrix will be sent to the FC layer to generate the result of this encoder, which is processed following the ReRAM-based dot-product method proposed in ISAAC [27].\" / \"As configured in ISAAC [27], the 'cycle' in CPSAA means the time of ADC processing 32 column signals, i.e., 25ns.\"", "purpose": "uses-method-or-tool"}, {"s": "W4390576773", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4390576773", "t": "W2899868573", "ctx": "", "purpose": ""}, {"s": "W4390576773", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4390576773", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4390576773", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4390576773", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4390576773", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W3194056411", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4391164199", "t": "W4323022446", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W1937359183", "ctx": "\"Multi-layer Perceptron (MLP)54,196,267, Convolutional Neural Networks (CNNs)268, Spiking Neural Networks (SNNs)269, among others (see Table 5).\" -- Burr et al. (ref 267) listed among MLP-based memristor hardware demonstrations compared in the accuracy table.", "purpose": "data/numbers"}, {"s": "W4392367648", "t": "W2613989746", "ctx": "\"Alternatives to overcome this limitation have been proposed, as for instance the simulator developed by Song et al. [PipeLayer] to evaluate their PipeLayer architecture, which considers highly parallel designs based on the notion of parallelism granularity and weight replication.\"", "purpose": "background"}, {"s": "W4392367648", "t": "W2625840880", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W2765081478", "ctx": "\"Mixed-precision training, which accumulates the weight update in software and only updates the memristor devices when the accumulated value surpasses the programming granularity, can greatly relax requirement for conductance update resolution and endurance and allow software-comparable accuracy to be achieved.\"", "purpose": "background"}, {"s": "W4392367648", "t": "W2782791387", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W2899749435", "ctx": "\"Whitin this group, we found for instance the DL-RSIM simulator, proposed by Lin et al., which simulates the error rates of every sum-of-products computation in memristor-based accelerators externally, and injects the errors in targeted TensorFlow-based neural network models.\"", "purpose": "uses-method-or-tool"}, {"s": "W4392367648", "t": "W2913104037", "ctx": "\"Moreover, ADC can consume up to 70-90% of the on-chip area of the crossbar-based computation unit, including memristive crossbar and peripheral circuits, and up to 80-88% of energy.\" ... \"Then, moving forward with the path toward the most accurate memristive neural network simulators, the PUMAsim proposed by Ankit et al. uses Verilog HDL to model the tiles and cores at the Register Transfer Level, which allows them to be mapped into a 45 nm Silicon-on-Insulator CMOS process for area estimation.\"", "purpose": "uses-method-or-tool"}, {"s": "W4392367648", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W2948661249", "ctx": "\"To avoid this loss of accuracy, hardware-aware training methods, in which device non-idealities are incorporated during training have been proposed in the literature.\"", "purpose": "background"}, {"s": "W4392367648", "t": "W2971533524", "ctx": "\"However, the negative side is that these are rather closed pieces of software, which has been partially solved by Ma et al. and Yuan et al., by using PyTorch instead of TensorFlow, focusing in this case on the weight pruning and quantization effects.\"", "purpose": "uses-method-or-tool"}, {"s": "W4392367648", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3013080934", "ctx": "\"To avoid this loss of accuracy, hardware-aware training methods, in which device non-idealities are incorporated during training have been proposed in the literature.\" (co-cited with Joshi et al. computational PCM paper)", "purpose": "background"}, {"s": "W4392367648", "t": "W3013407975", "ctx": "\"However, the negative side is that these are rather closed pieces of software, which has been partially solved by Ma et al. and Yuan et al., by using PyTorch instead of TensorFlow, focusing in this case on the weight pruning and quantization effects.\"", "purpose": "uses-method-or-tool"}, {"s": "W4392367648", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3041897167", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3042468132", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3107562138", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W3198899759", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W4210530509", "ctx": "\"Finally, the most advanced prototypes exploit the time-encoding scheme, which simplifies the DAC design and allows one DAC per channel, without losing resolution of the input vector.\" (HERMES-Core cited among advanced time-encoding ADC prototypes)", "purpose": "data/numbers"}, {"s": "W4392367648", "t": "W4226111665", "ctx": "\"For this reason, these approaches have been demonstrated mostly for the weight update of isolated devices, with just a few examples of on-chip integrated approaches.\"", "purpose": "background"}, {"s": "W4392367648", "t": "W4243519499", "ctx": "\"The other method is sharing a single ADC across several columns or using a single ADC per crossbar tile.\" (ISAAC cited as an example of ADC-sharing architecture)", "purpose": "uses-method-or-tool"}, {"s": "W4392367648", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4392367648", "t": "W4313251083", "ctx": "Figure/table adaptation note: performance comparison chart adapted with permission, citing the 'Analog-AI Using Dense 2-D Mesh' architecture alongside DaDianNao and 3D-aCortex in the throughput/process-node comparison.", "purpose": "data/numbers"}, {"s": "W4392367648", "t": "W4385896568", "ctx": "\"For benchmarking a device or a chip, it is essential to evaluate the accuracy of standard deep neural network models like VGG and ResNet on CIFAR and ImageNet dataset by utilizing architecture-level simulation and realistic hardware statistics.\" / \"the impact of ADC resolution on VMM accuracy needs to be carefully evaluated to identify the lowest ADC resolution ... while preserving the neural network accuracy.\"", "purpose": "data/numbers"}, {"s": "W4392367648", "t": "W4386293192", "ctx": "\"To avoid this loss of accuracy, hardware-aware training methods, in which device non-idealities are incorporated during training have been proposed in the literature.\"", "purpose": "background"}, {"s": "W4393168980", "t": "W2949989598", "ctx": "This work focuses on DRAM-based (HBM) PIM technologies which can support larger capacity than SRAM [23] with high bandwidth, lower latency, and higher numerical stability than nonvolatile memory designs [6], [24].", "purpose": "contrasts/critiques"}, {"s": "W4393168980", "t": "W4280496502", "ctx": "We identify TransPIM [27] as our baseline due to its recentness and superior performance than other accelerators including GPU, TPU, other PIM accelerators [5], [13], and ASIC Transformer accelerators [4], [22].", "purpose": "baseline/comparison"}, {"s": "W4393168980", "t": "W4381233128", "ctx": "Previous works [19], [27] have shown a software-hardware co-designed PIM architecture can provide better throughput and power consumption than GPU and TPU for Transformers. However, they lack the support for algorithmic optimizations like dynamic token pruning.", "purpose": "motivation"}, {"s": "W4394891385", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4394891385", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4394891385", "t": "W3184191382", "ctx": "", "purpose": ""}, {"s": "W4394891385", "t": "W4200001938", "ctx": "", "purpose": ""}, {"s": "W4394891385", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4394891385", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W2765081478", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W4394909859", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4394998365", "t": "W2613989746", "ctx": "\"A variety of CIM-based architectures emerge, achieving significantly improved computing efficiency for DNN applications over traditional architectures [PipeLayer et al.].\" / \"To accommodate different CIM designs for executing MVM on crossbars, we introduce the concept of VXB (Virtual Crossbar) as the computational unit rather than physical crossbars to facilitate the computing scheduling in the compiler.\"", "purpose": "background"}, {"s": "W4394998365", "t": "W2811080765", "ctx": "\"We sort out the designs of recent CIM accelerators from three dimensions: memory device, architecture hierarchy, and programming interface, and summarize them in Figure 1\" (ReRAM-RNN listed among surveyed CIM designs).", "purpose": "background"}, {"s": "W4394998365", "t": "W2913104037", "ctx": "\"However, we observe these works are inadequate as a general compilation tool for CIM\" ... \"Additionally, even though ISAAC and PUMA have a similar hierarchical structure, they still use different crossbar sizes and the number of crossbars.\" PUMA is also used as a validation target architecture for CIM-MLC.", "purpose": "baseline/comparison"}, {"s": "W4394998365", "t": "W2946659370", "ctx": "Listed among surveyed CIM accelerator designs compared across memory device, architecture hierarchy, and programming interface dimensions (Figure 1/2); also cited for crossbar-based MVM execution diversity motivating the VXB abstraction.", "purpose": "background"}, {"s": "W4394998365", "t": "W2974067241", "ctx": "\"For example, when comparing SRAM and ReRAM, although both have similar latency for read operations, the cost of writing data is considerably higher in ReRAM.\" Also compared in the related-compiler-work table (Figure/Table of input CIM architecture, hardware abstraction, supported device/interface).", "purpose": "baseline/comparison"}, {"s": "W4394998365", "t": "W3188508394", "ctx": "\"Relatively, OCC is a comprehensive compilation that encompasses abundant device types as well as numerous programming interfaces.\" -- compared directly against CIM-MLC in the related-work capability table.", "purpose": "baseline/comparison"}, {"s": "W4394998365", "t": "W3191560475", "ctx": "\"However, we observe these works are inadequate as a general compilation tool for CIM when summarizing them from the dimensions of FORMS, SRE, PUMA...\" FORMS listed among surveyed CIM accelerator hierarchies compared against CIM-MLC's abstraction.", "purpose": "baseline/comparison"}, {"s": "W4394998365", "t": "W3204737618", "ctx": "\"For example, Han et al. design a compilation tool to deploy DNNs on the ISAAC architecture via an MVM-grained programming interface, but its optimization strategy stays at the computing graph level neglecting the opportunity to fine-control the crossbar resource allocation and MVM operation sequencing for better results.\" ... \"Compared with existing compilation work [Han et al.], the proposed CIM-MLC can improve the inference speed by up to 3.2x.\"", "purpose": "baseline/comparison"}, {"s": "W4394998365", "t": "W4243519499", "ctx": "\"Thus, SRAM-based CIM supports flexible data read and write updates on CIM memory, while ReRAM-based CIM usually assumes that weights are frozen in the crossbar, avoiding the penalty of frequent writes.\" ISAAC is also used as the deployment target architecture for the Han et al. baseline compiler.", "purpose": "baseline/comparison"}, {"s": "W4394998365", "t": "W4254672563", "ctx": "\"Thus, SRAM-based CIM supports flexible data read and write updates on CIM memory, while ReRAM-based CIM usually assumes that weights are frozen in the crossbar, avoiding the penalty of frequent writes.\" PRIME listed among surveyed CIM hierarchies.", "purpose": "background"}, {"s": "W4394998365", "t": "W4312542636", "ctx": "\"Other works propose to decompose DNN operators and schedule MVM-grained operation in CIM crossbars.\" (the authors' own prior pruning+mapping framework, cited as related work on MVM-grained scheduling).", "purpose": "extends/builds-on"}, {"s": "W4399310783", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4399310783", "t": "W2794288888", "ctx": "It is demonstrated by several recent studies that for a practical ReRAM-based DNN accelerator to attain an acceptable level of inference accuracy, only nine WLs and eight BLs can be turned on concurrently [3, 11, 12].", "purpose": "motivation"}, {"s": "W4399310783", "t": "W2899749435", "ctx": "For a practical ReRAM-based DNN accelerator, the VMM on the crossbar arrays should operate at a much finer granularity, termed as an Operation Unit (OU), rather than at the subarray granularity. [3, 9, 10].", "purpose": "background"}, {"s": "W4399310783", "t": "W3015980402", "ctx": "It is demonstrated by several recent studies that for a practical ReRAM-based DNN accelerator to attain an acceptable level of inference accuracy, only nine WLs and eight BLs can be turned on concurrently [3, 11, 12].", "purpose": "motivation"}, {"s": "W4399310783", "t": "W4243519499", "ctx": "HW-based optimization solutions only improve the accelerators' performance from an HW perspective, featuring intra-layer pipeline (ISAAC [5]) or leveraging the natural sparsity of the neural networks with index reordering (SRE [3]).", "purpose": "baseline/comparison"}, {"s": "W4399310783", "t": "W4254672563", "ctx": "ReRAM is a type of non-volatile memory that stores information by changing the resistance of the metal oxide material [4].", "purpose": "background"}, {"s": "W4400230160", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4400233540", "t": "W2948661249", "ctx": "To perform realistic hardware simulations, we used an experimentally verified model, calibrated based on extensive measurements performed on an array containing 1 million Phase-Change Memory (PCM) devices [24].", "purpose": "uses-method-or-tool"}, {"s": "W4400233540", "t": "W3013080934", "ctx": "Analog-Based In-Memory Computing (AIMC) accelerators are one such type of accelerator, which have gained significant interest, due to their ability to execute Vector-Matrix Multiplications (VMMs) in O(1) time-complexity [6]-[8].", "purpose": "background"}, {"s": "W4400233540", "t": "W3148526109", "ctx": "To perform HWA training, the IBM Analog Hardware Acceleration Kit (AIHWKIT) [19], [20] is used.", "purpose": "uses-method-or-tool"}, {"s": "W4400233540", "t": "W4385896568", "ctx": "dedicated accelerators are required to accelerate the inference workloads of these models in resource-contained environments [2]-[5].", "purpose": "background"}, {"s": "W4400233540", "t": "W4386293192", "ctx": "Mathematically, the generally simulated AIMC forward passes can be expressed as y_i = alpha_i_out f_adc(sum ...) ... where f_adc and f_dac model the non-linear analog-to-digital and digital-to-analog processes, with dynamic scaling and range clipping, and xi denotes Gaussian noise [16].", "purpose": "uses-method-or-tool"}, {"s": "W4400233540", "t": "W4389082012", "ctx": "To perform HWA training, the IBM Analog Hardware Acceleration Kit (AIHWKIT) [19], [20] is used.", "purpose": "uses-method-or-tool"}, {"s": "W4400681289", "t": "W2613989746", "ctx": "To store large DNNs, this may require a multi-chip pipeline [2, 67] or dense storage technologies [1].", "purpose": "background"}, {"s": "W4400681289", "t": "W2899641901", "ctx": "To further reduce ADC energy, different macros use a variety of strategies: Macro A [16] reuses analog outputs across different columns by summing them on wires.", "purpose": "data/numbers"}, {"s": "W4400681289", "t": "W2910506572", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W2913104037", "ctx": "PUMA [74] provides a detailed model of a particular DNN system but does not explore the design space.", "purpose": "contrasts/critiques"}, {"s": "W4400681289", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W3005619596", "ctx": "Modeling Work Architecture Flexibility / Circuit Flexibility / Energy Accuracy / Model Speed: NeuroSim [3-6] Low/Low/High/Low; MNSim [7,8] Low/Low/Low/Med; Timeloop [9-14] High/Low/High/High; This Work High/High/High/High.", "purpose": "baseline/comparison"}, {"s": "W4400681289", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W3112740243", "ctx": "Unfortunately, prior CiM modeling tools are either inflexible [6, 8], or lack circuit-level modeling [9, 13]... prior CiM modeling works have not addressed this problem; accurate prior models are slow [6] and fast prior models are inaccurate [8-14].", "purpose": "contrasts/critiques"}, {"s": "W4400681289", "t": "W3148526109", "ctx": "While CiMLoop models area/energy/throughput, IBM AI Hardware Kit [68], CrossSim [69], and MemTorch [70], model DNN accuracy.", "purpose": "contrasts/critiques"}, {"s": "W4400681289", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W3198899759", "ctx": "We can break data-value-dependence into three components: 1) DNN Workload ... 2) Representation: How data values appear is determined by how the hardware represents operands [47].", "purpose": "background"}, {"s": "W4400681289", "t": "W3212662098", "ctx": "", "purpose": ""}, {"s": "W4400681289", "t": "W4243519499", "ctx": "Data movement consumes a significant portion of DNN energy [27, 28], and CiM can reduce energy costs by computing directly within the memory arrays [29]... One commonly-explored macro topology [2, 29, 30] is shown in Fig. 1.", "purpose": "background"}, {"s": "W4400681289", "t": "W4254672563", "ctx": "Most commonly, CiM systems keep DNN weights in memory because they do not change during DNN inference [2, 18, 20, 29].", "purpose": "background"}, {"s": "W4400681289", "t": "W4292121737", "ctx": "ADC ADC ADC ADC ... Base Macro [15] / A [16] / B [17] / C [18,19] / D [20,21] ... comparison of ADC-energy-reducing strategies used as validation macros.", "purpose": "data/numbers"}, {"s": "W4400681289", "t": "W4323022446", "ctx": "Unfortunately, prior CiM modeling tools are either inflexible [6, 8], or lack circuit-level modeling [9, 13]. ... Unfortunately, some prior models may use inaccurate fixed-energy or fixed-power models [8, 9, 13] that do not model data-value-dependence.", "purpose": "contrasts/critiques"}, {"s": "W4400681289", "t": "W4366389026", "ctx": "For more information, see the Titanium Law [38], which breaks down the factors that contribute to ADC energy and shows how ADC energy can be reduced.", "purpose": "uses-method-or-tool"}, {"s": "W4400937214", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W4226247444", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W4307927141", "ctx": "", "purpose": ""}, {"s": "W4400937214", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W3212662098", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4401070574", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4401070622", "t": "W2909715355", "ctx": "In step-2, we partition these matrices into multiple NVM crossbars of size 64×64 [13], [22].", "purpose": "uses-method-or-tool"}, {"s": "W4401070622", "t": "W3006908002", "ctx": "The noisy conductance G′ under write noise [12], [25] is given as G′ = G + ñW ... Also for the RRAM device, we have RMIN = 100kΩ with a high ON/OFF ratio of 100 [23], whereby the impact of parasitic non-idealities due to crossbar interconnects is negligible [25].", "purpose": "uses-method-or-tool"}, {"s": "W4401070622", "t": "W3011221635", "ctx": "Previous works have demonstrated the effectiveness of using NVM devices with higher ON/OFF ratios to reduce read variations during inference of deep neural networks [14], [29]–[31].", "purpose": "background"}, {"s": "W4401070622", "t": "W3112740243", "ctx": "Fig. 1(a) presents a radar chart that compares a ViT model inferred on analog RRAM crossbars against digital SRAM-based IMC arrays [14] (devoid of read and write non-idealities).", "purpose": "uses-method-or-tool"}, {"s": "W4401070622", "t": "W3198405160", "ctx": "These non-idealities primarily arise from the NVM devices (such as stochastic read and write noise), resulting in inaccurate MVMs in the crossbars and thereby, reduced inference accuracy for AI workloads [11], [13], [15].", "purpose": "background"}, {"s": "W4401070622", "t": "W4200477077", "ctx": "Recent works [7]–[10] have proposed compact, energy-efficient and low-latency implementations of transformers on IMC architectures using efficiency-driven hardware optimizations and architectural modifications.", "purpose": "background"}, {"s": "W4401070622", "t": "W4378800995", "ctx": "Previous works have demonstrated the effectiveness of using NVM devices with higher ON/OFF ratios to reduce read variations during inference of deep neural networks [14], [29]–[31].", "purpose": "background"}, {"s": "W4401070622", "t": "W4381233128", "ctx": "Recent works [7]–[10] have proposed compact, energy-efficient and low-latency implementations of transformers on IMC architectures using efficiency-driven hardware optimizations and architectural modifications.", "purpose": "background"}, {"s": "W4401070622", "t": "W4386293192", "ctx": "Recent works on crossbar variation-aware-training (VAT) [16] of transformers, aimed at enhancing their non-ideal accuracies during inference, have not accounted for write noise in the K & V matrices [15], [17].", "purpose": "contrasts/critiques"}, {"s": "W4401729360", "t": "W2896122000", "ctx": "Great energy efficiency is achieved by representing weight matrices in resistive elements of crossbar arrays and using basic physical laws of electrostatics ... to compute ubiquitous matrix-vector multiplications directly in memory in essentially constant time O(1) [refs 1-5].", "purpose": "background"}, {"s": "W4401729360", "t": "W3003821665", "ctx": "Many recent AIMC prototype chip-building efforts to date have been focused on accelerating the inference phase of deep neural networks (DNNs) trained in digital [refs 6-12].", "purpose": "background"}, {"s": "W4401729360", "t": "W3013080934", "ctx": "Great energy efficiency is achieved by representing weight matrices in resistive elements of crossbar arrays and using basic physical laws of electrostatics ... to compute ubiquitous matrix-vector multiplications directly in memory in essentially constant time O(1) [refs 1-5].", "purpose": "background"}, {"s": "W4401729360", "t": "W3148526109", "ctx": "For simulations, we use the PyTorch-based open source toolkit (AIHWKit), where we have implemented the proposed algorithms (see also Supplementary Fig. 4).", "purpose": "uses-method-or-tool"}, {"s": "W4401729360", "t": "W3195245399", "ctx": "Many recent AIMC prototype chip-building efforts to date have been focused on accelerating the inference phase of deep neural networks (DNNs) trained in digital [refs 6-12].", "purpose": "background"}, {"s": "W4401729360", "t": "W4292121737", "ctx": "Many recent AIMC prototype chip-building efforts to date have been focused on accelerating the inference phase of deep neural networks (DNNs) trained in digital [refs 6-12].", "purpose": "background"}, {"s": "W4401729360", "t": "W4313251083", "ctx": "For the analog compute time, we assume l_avg = 5, t_MVM = 40 ns and t_single-pulse = 5 ns... the memory operations (Table 1, rows in first section) can be hidden behind the compute.", "purpose": "data/numbers"}, {"s": "W4401729360", "t": "W4378800995", "ctx": "Note that this in-memory training approach is radically different from hardware-aware training typically employed when using analog crossbar arrays for DNN inference only (e.g., refs. 32, 41, 42).", "purpose": "contrasts/critiques"}, {"s": "W4401729360", "t": "W4385896568", "ctx": "Many recent AIMC prototype chip-building efforts to date have been focused on accelerating the inference phase of deep neural networks (DNNs) trained in digital [refs 6-12].", "purpose": "background"}, {"s": "W4401729360", "t": "W4386100686", "ctx": "Many recent AIMC prototype chip-building efforts to date have been focused on accelerating the inference phase of deep neural networks (DNNs) trained in digital [refs 6-12].", "purpose": "background"}, {"s": "W4401729360", "t": "W4386293192", "ctx": "Note that this in-memory training approach is radically different from hardware-aware training typically employed when using analog crossbar arrays for DNN inference only... it has recently been shown in simulation that with realistic MVM assumptions many large-scale DNNs can be deployed without significant accuracy drop on AIMC inference hardware when retrained properly.", "purpose": "contrasts/critiques"}, {"s": "W4402742347", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W4402742347", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4402742347", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4402742347", "t": "W3020429010", "ctx": "", "purpose": ""}, {"s": "W4402742347", "t": "W3119537022", "ctx": "", "purpose": ""}, {"s": "W4402742347", "t": "W3157191380", "ctx": "", "purpose": ""}, {"s": "W4402742347", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4402742347", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4402811198", "t": "W2899641901", "ctx": "Charge-based CIMs [4, 5] have the potential to satisfy the linearity due to its high-matching property of capacitors but are impractical to scale up to the necessary 10-bit ADC resolution for Transformers, owing to the significant overheads in area and power consumption.", "purpose": "contrasts/critiques"}, {"s": "W4403534421", "t": "W2613989746", "ctx": "We follow the evaluation methodology employed in three highly cited works: PRIME [22], ISAAC [9], and PipeLayer [23].", "purpose": "baseline/comparison"}, {"s": "W4403534421", "t": "W2795127895", "ctx": "Simulation results show that the environmental noise contributes less than 5% to the signal level, which is typical for real devices [44].", "purpose": "data/numbers"}, {"s": "W4403534421", "t": "W2805362231", "ctx": "Another design is the single-bit memristor, where we need multiple memristors to store a single weight. Examples are [20, 21].", "purpose": "background"}, {"s": "W4403534421", "t": "W3011221635", "ctx": "However, this is challenging due to the accumulation of noise from the non-ideal behavior of memristors [45][46][47].", "purpose": "background"}, {"s": "W4403534421", "t": "W3013080934", "ctx": "Memristor crossbars are widely considered strong competitors for traditional machine learning accelerators [3].", "purpose": "background"}, {"s": "W4403534421", "t": "W4243519499", "ctx": "For instance, the GPT-3 model has over 175 billion parameters, and it would require 2777 ISAAC chips [9] to store all of its parameters.", "purpose": "motivation"}, {"s": "W4403534421", "t": "W4254672563", "ctx": "While the PRIME [22] and PipeLayer [23] approaches eliminate the need for ADCs, their input or output circuits still contain numerous capacitors, which consume a significant amount of chip area.", "purpose": "contrasts/critiques"}, {"s": "W4403534421", "t": "W4378800995", "ctx": "However, this is challenging due to the accumulation of noise from the non-ideal behavior of memristors [45][46][47].", "purpose": "background"}, {"s": "W4403546214", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W2979663695", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W3111375540", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W4205363571", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W4381233128", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W4390241252", "ctx": "", "purpose": ""}, {"s": "W4403546214", "t": "W4394891385", "ctx": "", "purpose": ""}, {"s": "W4403600569", "t": "W2909715355", "ctx": "In practice, due to the analog nature of computation, various hardware noise and non-idealities arise, such as interconnect parasitic resistances, synaptic device-level variations during read and write operations [27]–[29] among others.", "purpose": "background"}, {"s": "W4403600569", "t": "W3011221635", "ctx": "While there exists other IMC-specific non-idealities such as IR-drop [26] and transistor nonlinearities [29], we use read/write variations (only for FeFET implementation) and ADC quantization noise (for both FeFET and SRAM implementations) to evaluate TReX.", "purpose": "background"}, {"s": "W4403600569", "t": "W3042493405", "ctx": "Additionally, to reduce the ADC precision, we follow input and weight splitting paradigms similar to prior works [7], [34].", "purpose": "uses-method-or-tool"}, {"s": "W4403600569", "t": "W3112740243", "ctx": "We adopt the standard tiled architecture in prior works [7], [33]. ... The crossbar energy, delay and area values are obtained based on IMC implementations of SRAM and FeFET crossbars of size 64×64 [33], [40].", "purpose": "uses-method-or-tool"}, {"s": "W4403600569", "t": "W4205363571", "ctx": "Interestingly, IMC-based implementation of QK^T and S(QK^T)V layers, require crossbar write operations [10], [11]. The write operations inside the attention block makes it a significant contributor (∼80%) to the overall delay.", "purpose": "motivation"}, {"s": "W4403600569", "t": "W4378800995", "ctx": "The IR-drop and transistor non-linearity noise follow a structured profile and can be mitigated using simple approaches such as batchnorm adaptation and weight retraining [28], [30].", "purpose": "background"}, {"s": "W4403600569", "t": "W4381233128", "ctx": "Recent IMC-centric transformer co-optimization works [10], [11], [18] have proposed IMC architecture implementations to efficiently compute the Matmul layers.", "purpose": "background"}, {"s": "W4403600569", "t": "W4386293192", "ctx": "Extensive research has shown that device variations and ADC quantization contribute significantly towards accuracy degradation and cannot be easily mitigated [28], [39].", "purpose": "background"}, {"s": "W4404294109", "t": "W2613989746", "ctx": "For accelerating DNNs on PIM, there is a crucial strategy called weight replication [5, 7, 24]. ... The most common unfolding method is (IK^2, O, 1) [7, 27], which unfolds the weight into a single matrix.", "purpose": "background"}, {"s": "W4404294109", "t": "W2899868573", "ctx": "", "purpose": ""}, {"s": "W4404294109", "t": "W2913104037", "ctx": "Among them, Polyhedral [16], Co-Design [17], SongC [18], and PIMCOMP focus on DNNs, while TC-CIM [19], TDO-CIM [20], OCC [21], and PUMA [22] target a broader range of machine learning algorithms. ... PUMA [22] do not consider the interaction between weight replication and weight layout, and simply map computational tasks to PIM arrays.", "purpose": "baseline/comparison"}, {"s": "W4404294109", "t": "W3013080934", "ctx": "Therefore, a compiler that can adapt to various PIM architectures and automatically complete DNN model deployment is indispensable to improve the usability of PIM accelerators, which also helps build a PIM ecosystem [11].", "purpose": "motivation"}, {"s": "W4404294109", "t": "W3188508394", "ctx": "Consequently, specialized compilation tools for PIM have been developed [16]-[23]. ... OCC [21] ... do not consider the interaction between weight replication and weight layout, and simply map computational tasks to PIM arrays.", "purpose": "baseline/comparison"}, {"s": "W4404294109", "t": "W3204737618", "ctx": "Among them, Polyhedral [16], Co-Design [17], SongC [18], and PIMCOMP focus on DNNs ... Polyhedral [16] ... do not consider the interaction between weight replication and weight layout, and simply map computational tasks to PIM arrays.", "purpose": "baseline/comparison"}, {"s": "W4404294109", "t": "W4243519499", "ctx": "Based on this principle, previous works (e.g., [5]-[10]) have designed a series of crossbar array-based DNN accelerators. ... Architecture Template: The architecture template is a representative multi-level configurable and scalable architecture derived from previous PIM accelerators [5, 22, 26].", "purpose": "background"}, {"s": "W4404294109", "t": "W4254672563", "ctx": "Similarly, a signed weight may need two crossbar arrays to store the positive and negative parts separately [6].", "purpose": "background"}, {"s": "W4404294109", "t": "W4323022446", "ctx": "Users can customize the VFU to perform different vector operations ... with integrated multi-function vector units [22]. Due to the limited precision of crossbar array cells, high-precision weights usually need multiple crossbar arrays to store collaboratively [27].", "purpose": "background"}, {"s": "W4404294109", "t": "W4386763580", "ctx": "A previous version of this work was published in [12], which provides an optimization scheme for resource allocation, task mapping, and pipeline dataflow through four stages ... PIMCOMP is a practical compiler that builds on Ref. [12] and enhances hardware compatibility, software support, and holistic performance.", "purpose": "extends/builds-on"}, {"s": "W4404294109", "t": "W4388052862", "ctx": "Furthermore, a reconfigurable architecture is introduced in [32] to support different unfolding strategies.", "purpose": "background"}, {"s": "W4404294109", "t": "W4388210331", "ctx": "For accelerating DNNs on PIM, there is a crucial strategy called weight replication [5, 7, 24].", "purpose": "background"}, {"s": "W4404915602", "t": "W2612375349", "ctx": "As RRAMs critically suffer from device nonidealities, most prominently non-linear conductance tuning, C-to-C, and device-to-device variations, benchmarking frameworks need to incorporate these key issues [23, 24].", "purpose": "motivation"}, {"s": "W4404915602", "t": "W3091895175", "ctx": "TABLE I: State-of-the-Art Device Metrics ... Extensive literature exists on benchmarking frameworks designed to evaluate RRAM device performance and integration with CMOS peripheral circuitry for a variety of applications.", "purpose": "background"}, {"s": "W4404915602", "t": "W3155456425", "ctx": "This mechanism underscores the computational efficiency inherent in the RRAM crossbar design for implementing VMM operations, with improved energy efficiency and reduced latency metrics [8-16].", "purpose": "background"}, {"s": "W4404915602", "t": "W4243519499", "ctx": "Emerging non-volatile memory technologies, such as resistive random access memories (RRAMs) based crossbar arrays, provide a versatile solution to the challenges of data-intensive, large-scale computational tasks [6, 7].", "purpose": "background"}, {"s": "W4404915602", "t": "W4321488325", "ctx": "This mechanism underscores the computational efficiency inherent in the RRAM crossbar design for implementing VMM operations, with improved energy efficiency and reduced latency metrics [8-16].", "purpose": "background"}, {"s": "W4404915602", "t": "W4392367648", "ctx": "Emerging non-volatile memory technologies, such as resistive random access memories (RRAMs) based crossbar arrays, provide a versatile solution to the challenges of data-intensive, large-scale computational tasks [6, 7].", "purpose": "background"}, {"s": "W4405718102", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W3180792321", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4405718102", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W4389082012", "ctx": "", "purpose": ""}, {"s": "W4406178148", "t": "W4394909859", "ctx": "", "purpose": ""}, {"s": "W4406521098", "t": "W2613989746", "ctx": "ReRAMs perform in situ MAC operations and necessitate the MHA and FF pre-trained weights on separate cores for pipelining [38].", "purpose": "uses-method-or-tool"}, {"s": "W4406521098", "t": "W2997247951", "ctx": "Processing-in-Memory (PIM) has emerged as a promising approach to accelerate the training/inference of machine learning (ML) workloads [9].", "purpose": "background"}, {"s": "W4406521098", "t": "W3111375540", "ctx": "We do not compare with homogenous ReRAM-based PIM architecture, ReTransformer or Acceltran in this comparative performance evaluation due to the endurance concern [21] [22].", "purpose": "contrasts/critiques"}, {"s": "W4406521098", "t": "W3112740243", "ctx": "SCALE-Sim is utilized for the systolic array cores and a modified NeuroSim is employed to obtain the latency of all on-chip buffers, and peripheral circuits in ReRAM cores [47] [32].", "purpose": "uses-method-or-tool"}, {"s": "W4406521098", "t": "W3201198776", "ctx": "For this purpose, we follow existing work and utilize a noise injection approach to improve the robustness of the finetuned model to ReRAM non-idealities [54] [55].", "purpose": "uses-method-or-tool"}, {"s": "W4406521098", "t": "W3209892756", "ctx": "Similarly, another work introduces a hardware-software co-design framework for transformer acceleration on ReRAM-based architecture [23].", "purpose": "background"}, {"s": "W4406521098", "t": "W4243519499", "ctx": "We facilitate dequantization by integrating additional shift-and-add (S&A) units into the previously proposed ReRAM tile architecture [20].", "purpose": "extends/builds-on"}, {"s": "W4406521098", "t": "W4280496502", "ctx": "TransPIM is a DRAM-based PIM accelerator with compute units integrated within High Bandwidth Memory (HBM) banks to accelerate transformer inference [25].", "purpose": "background"}, {"s": "W4406521098", "t": "W4312457094", "ctx": "Existing approaches aimed at reducing the number of rewrites during training or fine-tuning incur significant performance overhead or necessitate redundant hardware [15] [16].", "purpose": "contrasts/critiques"}, {"s": "W4406521098", "t": "W4381233128", "ctx": "Hence, standalone NVM-based PIM architectures are not suitable for transformer fine-tuning and inference [12].", "purpose": "motivation"}, {"s": "W4407065774", "t": "W1937359183", "ctx": "Diverse technologies including resistive random-access memory (ReRAM) and phase change memory are being considered as promising crossbar candidates to implement the multiply and accumulate operations representing the standard synaptic weights model used in most neural networks.", "purpose": "background"}, {"s": "W4407065774", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W4407065774", "t": "W2782791387", "ctx": "Since memristor crossbars are programmable and non-volatile, they can be utilized to build dedicated hardware accelerators for deep neural networks.", "purpose": "background"}, {"s": "W4407065774", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W4407065774", "t": "W2972862238", "ctx": "We offer comparisons with two existing state-of-the-art hardware-oriented fault tolerance schemes Mapping Algorithm with inner fault tolerant ability (MAO) and the Committee Machines (CM) algorithm.", "purpose": "baseline/comparison"}, {"s": "W4407065774", "t": "W3015980402", "ctx": "A purely experimental approach is unfeasible since commercial tape-outs have long timelines and significant design and fabrication costs.", "purpose": "motivation"}, {"s": "W4407065774", "t": "W4292121737", "ctx": "Diverse technologies including resistive random-access memory (ReRAM) and phase change memory are being considered as promising crossbar candidates to implement the multiply and accumulate operations representing the standard synaptic weights model used in most neural networks.", "purpose": "background"}, {"s": "W4407720907", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4407720907", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4407720907", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4407720907", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4407751056", "t": "W2805362231", "ctx": "One such compute substrate which shows significant promise for adversarial robustness is that based on analog in-memory computing (AIMC).", "purpose": "background"}, {"s": "W4407751056", "t": "W2948661249", "ctx": "However, Hardware-Aware (HWA) training, where the DNN is made robust via the injection of weight noise during the training process, has been found to recover much of the accuracy loss.", "purpose": "background"}, {"s": "W4407751056", "t": "W3011221635", "ctx": "While automated ML-based in-the-loop modeling approaches can be utilized, they require a significant amount of data, which is instance-specific.", "purpose": "contrasts/critiques"}, {"s": "W4407751056", "t": "W3013080934", "ctx": "One such compute substrate which shows significant promise for adversarial robustness is that based on analog in-memory computing (AIMC).", "purpose": "background"}, {"s": "W4407751056", "t": "W4385896568", "ctx": "To experimentally study the adversarial robustness, we employed a PCM-based AIMC chip with tiles comprising 256x256 synaptic unit cells; for some experiments, the IBM HERMES Project Chip, a 64-core AIMC chip based on back-end integrated PCM in a 14-nm CMOS process with a total capacity of 4,194,304 programmable weights, was used.", "purpose": "uses-method-or-tool"}, {"s": "W4407751056", "t": "W4386293192", "ctx": "However, Hardware-Aware (HWA) training, where the DNN is made robust via the injection of weight noise during the training process, has been found to recover much of the accuracy loss.", "purpose": "uses-method-or-tool"}, {"s": "W4407751056", "t": "W4389082012", "ctx": "We refer the reader to Le Gallo et al. for a comprehensive tutorial on HWA training using IBM AIHWKIT.", "purpose": "uses-method-or-tool"}, {"s": "W4407751056", "t": "W4400233540", "ctx": "Post-training optimizations are then performed to tune the (i) input range of each AIMC tile and the (ii) maximum conductance range of each column.", "purpose": "uses-method-or-tool"}, {"s": "W4408245641", "t": "W2765081478", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W3016048022", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4408245641", "t": "W4394909859", "ctx": "", "purpose": ""}, {"s": "W4408563999", "t": "W3112740243", "ctx": "These methods can implement vector-matrix multiplies very efficiently, but they suffer from ADC overheads. The overall system simulation, conducted using the NeuroSim framework, comprises chip, tile, processing element (PE) and array hierarchies.", "purpose": "uses-method-or-tool"}, {"s": "W4408563999", "t": "W4381233128", "ctx": "X-former proposes a hybrid IMC architecture built up with RRAM and SRAM together to efficiently execute different workloads of transformer.", "purpose": "baseline/comparison"}, {"s": "W4408563999", "t": "W4390017976", "ctx": "Compared to ELSA, ReTransformer, X-Former and HARDSEA, Topkima-Former can achieve 1.8x-84x higher speed, and 1.3x-35x energy reduction, respectively.", "purpose": "baseline/comparison"}, {"s": "W4408893285", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W2913104037", "ctx": "These tools formulate an optimized policy for weight mapping and devise a computation scheduling scheme across various operational granularities to maximize memory resource utilization and enhance computational performance.", "purpose": "baseline/comparison"}, {"s": "W4408893285", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W3091895175", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W3188508394", "ctx": "For example, OCC, built upon MLIR, utilizes a specific ISA to support scheduling optimization for multiple operators.", "purpose": "baseline/comparison"}, {"s": "W4408893285", "t": "W3204737618", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W4243519499", "ctx": "Compared to conventional architectures, CIM significantly mitigates persistent memory wall problem and demonstrates strong competitiveness in data-intensive applications especially deep neural network (DNN) inference.", "purpose": "background"}, {"s": "W4408893285", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W4381233128", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4408893285", "t": "W4386763580", "ctx": "To enhance efficiency and fully realize the potential of the CIM accelerators, researchers have explored various compilation optimization techniques, aimed at various CIM architectures such as resistant RAM and SRAM-based solutions.", "purpose": "background"}, {"s": "W4408893285", "t": "W4394998365", "ctx": "Compared with state-of-the-art compilation works [CIM-MLC], CMSwitch achieves average inference speed improvement by 1.31x. To address these challenges, our approach at first provides the hardware abstraction of dual-mode CIM accelerators based on CIM-MLC so that the dimension of CIM reconfiguration can be fused into the original mapping/scheduling space of CIM as a formalized optimization space.", "purpose": "extends/builds-on"}, {"s": "W4409285506", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4409285506", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4409285506", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4409285506", "t": "W3155456425", "ctx": "", "purpose": ""}, {"s": "W4409285506", "t": "W3194056411", "ctx": "", "purpose": ""}, {"s": "W4409285506", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4409285593", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4409285593", "t": "W3116577775", "ctx": "", "purpose": ""}, {"s": "W4409285593", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W4409285593", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4409285593", "t": "W4280496502", "ctx": "", "purpose": ""}, {"s": "W4409285593", "t": "W4385656513", "ctx": "", "purpose": ""}, {"s": "W4409285593", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W4410582659", "t": "W3112740243", "ctx": "We also evaluate the latency and energy of retrieval of the appropriate data by our scaled search algorithm on NVCiM via NeuroSim [36]. In our simulation, we obtain the latency and energy of crossbar array and peripheral circuits for the 22nm technology node.", "purpose": "uses-method-or-tool"}, {"s": "W4410582659", "t": "W4292121737", "ctx": "RRAM stores data by changing the resistance across a dielectric material [18], while FeFET utilizes ferroelectric materials to maintain data through polarization states [19].", "purpose": "background"}, {"s": "W4410583474", "t": "W2613989746", "ctx": "Similar to previous works [1, 2, 13], the architecture defines a Macro-Core-Chip hierarchy as shown in Fig. 1.", "purpose": "uses-method-or-tool"}, {"s": "W4410583474", "t": "W2913104037", "ctx": "PIM-aware compilers like PUMA [13] and PIMCOMP [3] have their primary focus on mapping all the weights on chip, but it is not possible to map large networks on chip when PIM memory footprint is constrained to tens of MBs at most.", "purpose": "contrasts/critiques"}, {"s": "W4410583474", "t": "W4243519499", "ctx": "Recognizing these challenges, attention to Processing-In-Memory (PIM) architectures has been rapidly increasing as an alternative to traditional architecture [1-4].", "purpose": "background"}, {"s": "W4410583474", "t": "W4386763580", "ctx": "We adopt the hardware architecture of PIMCOMP [3] and PUMA [13] but with tighter resource constraints... All partitioning schemes, including ours, are implemented by extending the open-source PIMCOMP framework [3].", "purpose": "uses-method-or-tool"}, {"s": "W4410584352", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W2949989598", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W3138725418", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4366389026", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4389082012", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W4410584352", "t": "W4390241252", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4389082012", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4406178148", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4407720907", "ctx": "", "purpose": ""}, {"s": "W4411233250", "t": "W4410584352", "ctx": "", "purpose": ""}, {"s": "W4411486499", "t": "W1542981317", "ctx": "Out of these efforts, RRAM is one of the most widely explored devices for PIM acceleration due to its non-volatile memory (NVM) nature, high storage density, fast read operation, low energy consumption, and excellent analog programmability for the multi-level cell (MLC) [23, 42, 46, 58, 60, 74, 78, 80].", "purpose": "background"}, {"s": "W4411486499", "t": "W2949989598", "ctx": "Each NOR operation takes three columns for two input operand bits and one output bit [22].", "purpose": "uses-method-or-tool"}, {"s": "W4411486499", "t": "W3003821665", "ctx": "As an alternative solution, memory-centric processing architectures have been emerging, specifically processing-in-memory (PIM) [48, 74, 80].", "purpose": "background"}, {"s": "W4411486499", "t": "W3016048022", "ctx": "The noise level was derived from the studies by Wan et al. [61] and Fan et al. [15], utilizing the non-idealities measured from the fabricated real MLC RRAM chips.", "purpose": "data/numbers"}, {"s": "W4411486499", "t": "W3111375540", "ctx": "For the digital PIM module, where realtime generated Q, K, V, and intermediate data are supposed to be written, could potentially compromise RRAM endurance [72].", "purpose": "background"}, {"s": "W4411486499", "t": "W3155456425", "ctx": "Specifically, the RRAM features an on-state resistance (R_ON) of 6 kΩ with an on/off ratio of 150 [77].", "purpose": "data/numbers"}, {"s": "W4411486499", "t": "W4243519499", "ctx": "The pioneering works, ISAAC [50] and [20] demonstrate a pipelined RRAM crossbar and hybrid RRAM capable of efficiently executing CNNs.", "purpose": "background"}, {"s": "W4411486499", "t": "W4254672563", "ctx": "PRIME [11] introduces a reconfigurable RRAM PIM architecture, where the same PIM hardware can be configured as both regular memory and computing elements.", "purpose": "background"}, {"s": "W4411486499", "t": "W4280496502", "ctx": "We benchmark our HyFlexPIM against ... 4) a near-memory processing (NMP) baseline, TransPIM [79], which is based on the functionin-memory DRAM (FIMDRAM) processor [30] with HBM", "purpose": "baseline/comparison"}, {"s": "W4411486499", "t": "W4366389026", "ctx": "analog PIM demonstrates dramatic efficiency improvement, achieving more than two orders of magnitude benefit [5, 9, 17, 24] through low-voltage swing operations.", "purpose": "background"}, {"s": "W4411725113", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4411725113", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4411725113", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4411725113", "t": "W3003151806", "ctx": "", "purpose": ""}, {"s": "W4411725113", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4411725113", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4411725113", "t": "W4389082012", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W3188508394", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4311978413", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4392367648", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4394998365", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4400233540", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4400681289", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4404294109", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4407720907", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4407751056", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4408145534", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4280496502", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4280592620", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4381233128", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4385656513", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4406178148", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4406521098", "ctx": "", "purpose": ""}, {"s": "W4413553738", "t": "W2613989746", "ctx": "The initial works on analog CIM based accelerators focused on convolutional and fully connected networks [30, 51–53].", "purpose": "background"}, {"s": "W4413553738", "t": "W2913104037", "ctx": "We used a cycle-level simulator based on PUMASim [52], having a hierarchy of chip, tile, core, and MVMUs in 32nm technology.", "purpose": "uses-method-or-tool"}, {"s": "W4413553738", "t": "W2948661249", "ctx": "Further, analog CIM also introduces quantization and functional errors due to various circuit non-idealities. We assume that such errors can be reduced during transformer inference using hardware-aware training [60].", "purpose": "uses-method-or-tool"}, {"s": "W4413553738", "t": "W3042468132", "ctx": "While emerging memories offer a high-density memory solution, they typically suffer from issues such as resistance drift, write endurance and/or low on-off distinguishability [50].", "purpose": "motivation"}, {"s": "W4413553738", "t": "W4243519499", "ctx": "In the past, compute-in-memory (CIM) has shown great promise in accelerating convolutional and fully-connected layers by leveraging their weight stationary nature, as their feature maps are known before runtime [29–31].", "purpose": "background"}, {"s": "W4413553738", "t": "W4254672563", "ctx": "The initial works on analog CIM based accelerators focused on convolutional and fully connected networks [30, 51–53].", "purpose": "background"}, {"s": "W4413553738", "t": "W4280496502", "ctx": "Other CIM works focused on content addressable memories for softmax, ReRAMSRAM hybrid architecture, and processing in off-chip memory to facilitate efficient data communication during transformer inference [26, 32, 33].", "purpose": "background"}, {"s": "W4413553738", "t": "W4381233128", "ctx": "Other CIM works focused on content addressable memories for softmax, ReRAMSRAM hybrid architecture, and processing in off-chip memory to facilitate efficient data communication during transformer inference [26, 32, 33].", "purpose": "background"}, {"s": "W4413633179", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4413633179", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4413633179", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4413633179", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4413633179", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4413633179", "t": "W4366389026", "ctx": "", "purpose": ""}, {"s": "W4413633179", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4413633179", "t": "W4400681289", "ctx": "", "purpose": ""}, {"s": "W4413755433", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4413755433", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W4413755433", "t": "W3111375540", "ctx": "", "purpose": ""}, {"s": "W4413755433", "t": "W3201198776", "ctx": "", "purpose": ""}, {"s": "W4413755433", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4413755433", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4414008085", "t": "W2899641901", "ctx": "Conventional estimates, assuming uniform distribution of weights and inputs [24, 25], predict a signal variance of DR^2_ADC/12, which is significantly higher than the actual variance, resulting in optimistic CSNR estimates.", "purpose": "contrasts/critiques"}, {"s": "W4414008085", "t": "W3005619596", "ctx": "NeuroSim [14, 31] assumes that the ADC dynamic range is defined by the Min-Max range of each MAC output, leading to overly optimistic inference results.", "purpose": "contrasts/critiques"}, {"s": "W4414008085", "t": "W3148526109", "ctx": "Fundamental architecture and MAC operation of ACiM: (a) Bit-serial ACiM. (b) Bit-parallel ACiM. [cited among works establishing ACiM inference-accuracy evaluation methods, refs 17-20]", "purpose": "background"}, {"s": "W4414008085", "t": "W4389166767", "ctx": "Among CiM architectures, Analog Compute-in-Memory (ACiM) offers high computational density and energy efficiency by leveraging the analog properties of memory cells to perform Multiply-and-ACcumulate (MAC) operations directly in the analog domain [4].", "purpose": "background"}, {"s": "W4414008085", "t": "W4402811198", "ctx": "Yoshioka [25] extended this approach by introducing analog Gaussian noise into each binary MAC cycle to estimate the actual CSNR of ACiM chips.", "purpose": "uses-method-or-tool"}, {"s": "W4414064893", "t": "W3013080934", "ctx": "IMC is particularly beneficial when using non-volatile memories to store stationary weights in linear layers22.", "purpose": "background"}, {"s": "W4414064893", "t": "W3111375540", "ctx": "Non-volatile memories can be used for linear layers of transformers17, but are too slow, energy expensive and are not endurant enough for dynamical KV-cache writing18,22.", "purpose": "contrasts/critiques"}, {"s": "W4414064893", "t": "W4280496502", "ctx": "KV cache has been implemented either by dynamic random-access memories (DRAMs)21,23, which have limited parallelism requiring many digital sequential adders, or by SRAMs19,24, which are limited by their volatility and relatively low density25.", "purpose": "contrasts/critiques"}, {"s": "W4414064893", "t": "W4292121737", "ctx": "The analog-to-digital conversion required for analog IMC often hinders the advantages this approach offers, as analog-t-digital converters (ADCs) are power and area intensive34. To mitigate this issue, charge-based integration is an energy-efficient alternative35,36.", "purpose": "uses-method-or-tool"}, {"s": "W4414064893", "t": "W4381233128", "ctx": "KV cache has been implemented either by dynamic random-access memories (DRAMs)21,23, which have limited parallelism requiring many digital sequential adders, or by SRAMs19,24, which are limited by their volatility and relatively low density25.", "purpose": "contrasts/critiques"}, {"s": "W4414064893", "t": "W4386100686", "ctx": "To mitigate this issue, charge-based integration is an energy-efficient alternative35,36.", "purpose": "uses-method-or-tool"}, {"s": "W4414064893", "t": "W4390017976", "ctx": "KV cache has been implemented either by dynamic random-access memories (DRAMs)21,23, which have limited parallelism requiring many digital sequential adders, or by SRAMs19,24, which are limited by their volatility and relatively low density25.", "purpose": "contrasts/critiques"}, {"s": "W4414064893", "t": "W4401070622", "ctx": "In particular, to mitigate data-transfer overhead of weights loading, several approaches leverage either near-memory or in-memory computing (IMC)17–21.", "purpose": "background"}, {"s": "W4414197154", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4414197154", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W4414197154", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W4414197154", "t": "W4390241252", "ctx": "", "purpose": ""}, {"s": "W4414198111", "t": "W2899641901", "ctx": "", "purpose": ""}, {"s": "W4414198111", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W4414198111", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4414198111", "t": "W4225637124", "ctx": "", "purpose": ""}, {"s": "W4414198111", "t": "W4312949026", "ctx": "", "purpose": ""}, {"s": "W4414198111", "t": "W4323022446", "ctx": "", "purpose": ""}, {"s": "W4414198111", "t": "W4400681289", "ctx": "", "purpose": ""}, {"s": "W4414428210", "t": "W1542981317", "ctx": "In addition, memristor-based architectures can leverage in-memory computing to minimize data movement to greatly reduce energy consumption.", "purpose": "background"}, {"s": "W4414428210", "t": "W2803163155", "ctx": "For example, a fully analogue solution based on a synaptic unit cell combining non-volatile phase change memory (PCM) with conventional CMOS-based capacitors (the PCM array was fabricated and the CMOS capacitors were simulated) has been explored16. However, such solutions lack scalability because of the large footprint of the capacitors required to store high-resolution weights.", "purpose": "contrasts/critiques"}, {"s": "W4414428210", "t": "W2805362231", "ctx": "In addition, memristor-based architectures can leverage in-memory computing to minimize data movement to greatly reduce energy consumption.", "purpose": "background"}, {"s": "W4414428210", "t": "W3003821665", "ctx": "Among the memory types suitable for integration into advanced commercial processes, filamentary memristors have been extensively studied for analogue in-memory neural network inference.", "purpose": "background"}, {"s": "W4414428210", "t": "W4292121737", "ctx": "Among the memory types suitable for integration into advanced commercial processes, filamentary memristors have been extensively studied for analogue in-memory neural network inference.", "purpose": "background"}, {"s": "W4414428210", "t": "W4385896568", "ctx": "In addition, memristor-based architectures can leverage in-memory computing to minimize data movement to greatly reduce energy consumption.", "purpose": "background"}, {"s": "W4414428210", "t": "W4386100686", "ctx": "In addition, memristor-based architectures can leverage in-memory computing to minimize data movement to greatly reduce energy consumption.", "purpose": "background"}, {"s": "W4414428210", "t": "W4386293192", "ctx": "However, the limited write endurance and high programming energy make them poorly suited for on-chip training, necessitating off-chip training and pre-programming for specific tasks.", "purpose": "motivation"}, {"s": "W4414428210", "t": "W4394909859", "ctx": "One approach to the challenge of training at the edge is to combine memristors with accurate digital static random-access memory, which can be made using standard transistors.", "purpose": "contrasts/critiques"}, {"s": "W4414499786", "t": "W1937359183", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W3003151806", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W4389082012", "ctx": "", "purpose": ""}, {"s": "W4414499786", "t": "W4400233540", "ctx": "", "purpose": ""}, {"s": "W4414659772", "t": "W3005874416", "ctx": "As the amorphous phase within programmed PCM devices relaxes, device-conductances decrease logarithmically over time38.", "purpose": "background"}, {"s": "W4414659772", "t": "W3148526109", "ctx": "The HWA ﬁne-tuning of the ALBERT model was conducted with an internal tool and the same capability is available in the IBM Analog Hardware Acceleration Kit at https://github.com/IBM/aihwkit43,44.", "purpose": "uses-method-or-tool"}, {"s": "W4414659772", "t": "W3195245399", "ctx": "In this work, we map the weights of one ALBERT layer onto a single PCM-based analog inference chip that we have demonstrated recently34.", "purpose": "uses-method-or-tool"}, {"s": "W4414659772", "t": "W4292121737", "ctx": "Analog accelerators based on CIM have been demonstrated using various NVM technologies, e.g., Flash3–5, PCM6–9, RRAM10–13, MRAM14–16, ECRAM17–19, or ferroelectric devices20–22.", "purpose": "background"}, {"s": "W4414659772", "t": "W4313251083", "ctx": "In a more advanced design where digital compute units are distributed on-chip amongst the tiles, ﬁne-grained pipelining within each layer can be expected to keep all resources continuously busy, leading to signiﬁcant improvements in both energy-efﬁciency and throughput36.", "purpose": "extends/builds-on"}, {"s": "W4414659772", "t": "W4385896568", "ctx": "Analog accelerators based on CIM have been demonstrated using various NVM technologies, e.g., Flash3–5, PCM6–9, RRAM10–13, MRAM14–16, ECRAM17–19, or ferroelectric devices20–22.", "purpose": "background"}, {"s": "W4414659772", "t": "W4386100686", "ctx": "The prior work on the demonstration of the Recurrent Neural Network Transducer (RNNT) model in this analog accelerator achieved the efﬁciency of 6-7 TOPS/W, a 14 × improvement over conventional digital accelerators8.", "purpose": "baseline/comparison"}, {"s": "W4414659772", "t": "W4386293192", "ctx": "Hardware-aware (HWA) ﬁne-tuning HWA techniques are employed in the ﬁne-tuning of the ALBERT model to improve the resilience of the ALBERT model31.", "purpose": "uses-method-or-tool"}, {"s": "W4414659772", "t": "W4389082012", "ctx": "The HWA ﬁne-tuning of the ALBERT model was conducted with an internal tool and the same capability is available in the IBM Analog Hardware Acceleration Kit at https://github.com/IBM/aihwkit43,44.", "purpose": "uses-method-or-tool"}, {"s": "W4414758157", "t": "W3013080934", "ctx": "Compute-In-Memory (CIM) neural network accelerators have emerged as promising architectures for achieving energy-efficient AI processing [2-6].", "purpose": "background"}, {"s": "W4414758157", "t": "W3112740243", "ctx": "CiMLoop was selected for its relatively high simulation speed and accuracy close to that of NeuroSim [49], while offering enhanced flexibility.", "purpose": "baseline/comparison"}, {"s": "W4414758157", "t": "W3197197128", "ctx": "Compute-In-Memory (CIM) neural network accelerators have emerged as promising architectures for achieving energy-efficient AI processing [2-6].", "purpose": "background"}, {"s": "W4414758157", "t": "W3201198776", "ctx": "In contrast, CIM-based design space exploration focuses on identifying the optimal CIM hardware parameters for deploying a fixed neural network model [18, 19, 23].", "purpose": "background"}, {"s": "W4414758157", "t": "W4361857408", "ctx": "Gibbon co-optimizes a large search space ... crossbar and converter precision, leading to a notable accuracy drop due to modifications in ResNet for better CIM compatibility. To reduce the search space from 4.3x10^84 to 1.3x10^22, Gibbon's algorithm prunes lower-priority parameters.", "purpose": "baseline/comparison"}, {"s": "W4414758157", "t": "W4386352784", "ctx": "AnalogNAS [15], NAS4RRAM [16], Flash [22], and NACIM [17] frameworks focus on HW-NAS for optimizing neural network models with hardware feedback.", "purpose": "baseline/comparison"}, {"s": "W4414758157", "t": "W4391164199", "ctx": "Current state-of-the-art HW-NAS frameworks for CIM primarily focus on optimizing neural network models for hardware implementation, performing hardware design space exploration separately, or jointly optimizing model parameters with a limited set of hardware parameters [including CoMN, 18].", "purpose": "baseline/comparison"}, {"s": "W4414758157", "t": "W4392367648", "ctx": "To maximize the hardware efficiency of CIM accelerators and maintain high performance for neural network workloads, it is essential to co-optimize both neural network model parameters and CIM hardware parameters [7].", "purpose": "motivation"}, {"s": "W4414758157", "t": "W4400681289", "ctx": "Hardware metrics evaluation is performed using the CiMLoop simulator, a highly flexible, cycle-accurate simulation framework designed for architecture-level evaluation of CIM-based hardware accelerators. CiMLoop was selected for its relatively high simulation speed and accuracy close to that of NeuroSim, while offering enhanced flexibility. Specifically, CiMLoop achieves an average error of approximately 3% in hardware estimations.", "purpose": "uses-method-or-tool"}, {"s": "W4415179271", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W2899641901", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W3091895175", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4225739994", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4285263226", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4323022446", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4386763580", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4388052862", "ctx": "", "purpose": ""}, {"s": "W4415179271", "t": "W4394998365", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W4366389026", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4416429523", "t": "W4401729360", "ctx": "", "purpose": ""}, {"s": "W4416429527", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4416429527", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W4416429527", "t": "W3204737618", "ctx": "", "purpose": ""}, {"s": "W4416429527", "t": "W3212662098", "ctx": "", "purpose": ""}, {"s": "W4416429527", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4416429527", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4416429527", "t": "W4394998365", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W3003151806", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W3042493405", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4366389026", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4376606760", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4385656513", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4390241252", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4392367648", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4402811198", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4406178148", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4406521098", "ctx": "", "purpose": ""}, {"s": "W4416429987", "t": "W4410584352", "ctx": "", "purpose": ""}, {"s": "W4416963215", "t": "W3005619596", "ctx": "Digital CIM data is from [21] and scaled to 22nm via [25] while analog CIM data is extracted from NeuroSim v1.3 [26].", "purpose": "uses-method-or-tool"}, {"s": "W4416963215", "t": "W3005874416", "ctx": "Device engineering [36] and circuit-device co-design [37] can further alleviate effects, which is out of the scope of this work.", "purpose": "background"}, {"s": "W4416963215", "t": "W3112740243", "ctx": "We modify NeuroSim v2.1 [30] to evaluate the non-ideal effects.", "purpose": "uses-method-or-tool"}, {"s": "W4416963215", "t": "W4307927141", "ctx": "The finite on/off ratio impact is not incorporated, as prior work has demonstrated that it can be effectively mitigated via the dummy column scheme [35].", "purpose": "uses-method-or-tool"}, {"s": "W4416963215", "t": "W4313251083", "ctx": "Due to the non-ideal effects of RRAM ACIM and the low-density of SRAM DCIM, a heterogeneous architecture has been adopted in prior research on CIM-based Transformer accelerators [5]–[16].", "purpose": "background"}, {"s": "W4416963215", "t": "W4381233128", "ctx": "X-Former [7] proposed a Sequence Blocking Dataflow to improve PE utilization by overlapping computations between SRAM-based and RRAM-based PEs. However, its benefits are limited due to the operator ordering in Transformers.", "purpose": "baseline/comparison"}, {"s": "W4416963215", "t": "W4385656513", "ctx": "Previous studies have proposed using SRAM-based Analog CIM [7], [10], [13], [16] or Digital CIM [8], [9] to perform DMM operations.", "purpose": "background"}, {"s": "W4416963215", "t": "W4390017976", "ctx": "Prior research on heterogeneous-CIM-based Transformer accelerators aims to reduce computation amounts of DMM through algorithm co-design [8], [14], [15].", "purpose": "background"}, {"s": "W4416963215", "t": "W4400230160", "ctx": "Prior research on heterogeneous-CIM-based Transformer accelerators aims to reduce computation amounts of DMM through algorithm co-design [8], [14], [15].", "purpose": "background"}, {"s": "W4417052206", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W3188508394", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W3191560475", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W3204737618", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W4226111665", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W4386763580", "ctx": "", "purpose": ""}, {"s": "W4417052206", "t": "W4404294109", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W2794288888", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W2899641901", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W3015980402", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W3041897167", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W3164913974", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4312949026", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4389166767", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4394909859", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4406178148", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4407720907", "ctx": "", "purpose": ""}, {"s": "W4417492578", "t": "W4408245641", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W2899749435", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W2909715355", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W3011221635", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W3198899759", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W4312081519", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W4323022446", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W4361857408", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W4389166767", "ctx": "", "purpose": ""}, {"s": "W7106169063", "t": "W4391164199", "ctx": "", "purpose": ""}, {"s": "W7117258492", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W7117258492", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W7117549365", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W7117549365", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W7117549365", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W7117549365", "t": "W4386763580", "ctx": "", "purpose": ""}, {"s": "W7117549365", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W7117549365", "t": "W4392367648", "ctx": "", "purpose": ""}, {"s": "W7117584415", "t": "W2913104037", "ctx": "The second approach, adopted by architectures such as PUMA [13], introduces programmable digital Vector Functional Units (VFUs) to support a wide range of operations. However, this programmability comes at the cost of performance, particularly for DMMuls in Transformer models.", "purpose": "contrasts/critiques"}, {"s": "W7117584415", "t": "W3111375540", "ctx": "The third approach, as demonstrated in ReTransformer [6], directly computes DMMuls and Softmax within RRAM crossbars by programming the inputs into the array. While promising, it suffers from the inherent drawbacks of RRAM’s slow writes and limited endurance [19].", "purpose": "contrasts/critiques"}, {"s": "W7117584415", "t": "W4200149283", "ctx": "In-memory Computing (IMC) stands out as a promising solution to alleviate the computational and memory challenges posed by Transformer models [6]–[8].", "purpose": "background"}, {"s": "W7117584415", "t": "W4243519499", "ctx": "The design largely follows ISAAC [9], adopting a hierarchical structure of tiles and cores (Figure 10(a) and (b)), with the key difference that each tile integrates a RACE unit, adders, and registers to support intermediate data storage for RACE and adder operations.", "purpose": "extends/builds-on"}, {"s": "W7117584415", "t": "W4292121737", "ctx": "High-performance silicon demonstrations of multi-core IMC accelerators using RRAM [16] and PCM [17] have been recently presented, finally grounding years of research in experimental measurements.", "purpose": "background"}, {"s": "W7117584415", "t": "W4385896568", "ctx": "High-performance silicon demonstrations of multi-core IMC accelerators using RRAM [16] and PCM [17] have been recently presented, finally grounding years of research in experimental measurements.", "purpose": "background"}, {"s": "W7117584415", "t": "W4386764227", "ctx": "In-memory Computing (IMC) stands out as a promising solution to alleviate the computational and memory challenges posed by Transformer models [6]–[8].", "purpose": "background"}, {"s": "W7127107108", "t": "W2765081478", "ctx": "Analog In-Memory Computing (AIMC) has emerged as a promising computing paradigm to tackle these challenges, offering improved performance and energy-efficiency through computation directly within the memory array4,5.", "purpose": "background"}, {"s": "W7127107108", "t": "W2948661249", "ctx": "We used global drift compensation22 to mitigate temporal variations.", "purpose": "uses-method-or-tool"}, {"s": "W7127107108", "t": "W3003151806", "ctx": "Industry-fabricated Phase Change Memory (PCM) devices, for example, display state-dependent programming and read noise, as well as drift in conductance states over time7–10.", "purpose": "background"}, {"s": "W7127107108", "t": "W3013080934", "ctx": "Industry-fabricated Phase Change Memory (PCM) devices, for example, display state-dependent programming and read noise, as well as drift in conductance states over time7–10.", "purpose": "background"}, {"s": "W7127107108", "t": "W3148526109", "ctx": "To accurately model the behavior and constraints of AIMC hardware, we used AIHWKIT, an opensource simulator for AIMC devices21.", "purpose": "uses-method-or-tool"}, {"s": "W7127107108", "t": "W4385896568", "ctx": "Simulation results confirm that our method is effective on a 25.3M-parameter transformer model, a practical size suitable for deployment on currently available AIMC chips18,19.", "purpose": "motivation"}, {"s": "W7127107108", "t": "W4386293192", "ctx": "conventional AHWA training methodologies typically optimize performance for only one task at a time12.", "purpose": "contrasts/critiques"}, {"s": "W7127107108", "t": "W4389082012", "ctx": "Analog Hardware-Aware (AHWA) training techniques have been demonstrated to enhance model robustness under these constraints for various NN architectures, effectively mitigating accuracy losses by injecting Gaussian noise during forward-propagation and simulating circuit-non-idealities11–13.", "purpose": "background"}, {"s": "W7127107108", "t": "W4394909859", "ctx": "Simulation results confirm that our method is effective on a 25.3M-parameter transformer model, a practical size suitable for deployment on currently available AIMC chips18,19.", "purpose": "motivation"}, {"s": "W7127107108", "t": "W4407720907", "ctx": "Analog In-Memory Computing (AIMC) has emerged as a promising computing paradigm to tackle these challenges, offering improved performance and energy-efficiency through computation directly within the memory array4,5.", "purpose": "background"}, {"s": "W7127107108", "t": "W4407751056", "ctx": "Analog Hardware-Aware (AHWA) training techniques have been demonstrated to enhance model robustness under these constraints for various NN architectures, effectively mitigating accuracy losses by injecting Gaussian noise during forward-propagation and simulating circuit-non-idealities11–13.", "purpose": "background"}, {"s": "W7127107108", "t": "W4408145534", "ctx": "Optimizing the allocation of LoRA parameters is crucial for balancing model performance and resource efficiency. This challenge represents a typical resource allocation problem34.", "purpose": "background"}, {"s": "W7127107108", "t": "W4411926812", "ctx": "However, distinct properties of AIMC, namely device noise and circuit non-idealities, introduce additional complexity to NN training and deployment6.", "purpose": "background"}, {"s": "W7129625181", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W3011221635", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W4226111665", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W4381233128", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W4385656513", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W4413553738", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W4414064893", "ctx": "", "purpose": ""}, {"s": "W7129625181", "t": "W7134813260", "ctx": "", "purpose": ""}, {"s": "W7130560115", "t": "W2613989746", "ctx": "", "purpose": ""}, {"s": "W7130560115", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W7130560115", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W7130560115", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W7130560115", "t": "W4390241252", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W2612375349", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W3003151806", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W3138725418", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W4283733417", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W4389082012", "ctx": "", "purpose": ""}, {"s": "W7134259416", "t": "W4407720907", "ctx": "", "purpose": ""}, {"s": "W7134813260", "t": "W3005619596", "ctx": "Additionally, following the block-wise linear mapping characteristics of weights on physical RRAM crossbars [50], we partitioned the corresponding weights into 64×64 blocks to align with conventional memory tile dimensions.", "purpose": "uses-method-or-tool"}, {"s": "W7134813260", "t": "W4205363571", "ctx": "For attention blocks, dynamic matrix-matrix multiplication (MatMul) necessitates extensive write-verify operations in RRAM [47, 48].", "purpose": "background"}, {"s": "W7134813260", "t": "W4293243554", "ctx": "Existing work related to CIM has investigated the implementation of small-scale neural networks [1, 7, 8].", "purpose": "background"}, {"s": "W7134813260", "t": "W4381233128", "ctx": "In this paper, we propose deploying finetuned LLMs on hybrid CIM, leveraging both the energy efficiency and computational density of RRAM and the noise-free computation of SRAM [64, 65].", "purpose": "motivation"}, {"s": "W7134813260", "t": "W4394909859", "ctx": "Existing work related to CIM has investigated the implementation of small-scale neural networks [1, 7, 8].", "purpose": "background"}, {"s": "W7143500069", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W7143500069", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W7143500069", "t": "W4280496502", "ctx": "", "purpose": ""}, {"s": "W7143500069", "t": "W4285263226", "ctx": "", "purpose": ""}, {"s": "W7143500069", "t": "W4388052862", "ctx": "", "purpose": ""}, {"s": "W7143500069", "t": "W4390241252", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W2913104037", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W3112740243", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4323022446", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4389166698", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4394998365", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4400681289", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4404294109", "ctx": "", "purpose": ""}, {"s": "W7160523127", "t": "W4414008085", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W1542981317", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W2807750997", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W2921329602", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W3015982917", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W3164913974", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W3180792321", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4379527483", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4392367648", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4394909859", "ctx": "", "purpose": ""}, {"s": "W7160842405", "t": "W4408245641", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4292121737", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4406178148", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4410584352", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4411233250", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4414064893", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4414659772", "ctx": "", "purpose": ""}, {"s": "W7162404347", "t": "W4417492578", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W2997247951", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W2997869757", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W3005619596", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W3042468132", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4254672563", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4293243554", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4323022446", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4385656513", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4391164199", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4409285593", "ctx": "", "purpose": ""}, {"s": "W7162657777", "t": "W4416963215", "ctx": "", "purpose": ""}, {"s": "W7164181555", "t": "W4243519499", "ctx": "", "purpose": ""}, {"s": "W7164181555", "t": "W4385656513", "ctx": "", "purpose": ""}, {"s": "W4210530509", "t": "W3015980402", "ctx": "Compared to the state-of-the-art (shown in Table I), the measured throughput density of 1.59 TOPS/mm2 is significantly higher than recent non-volatile ReRAM-based designs [24], [45] and also slightly higher than recent SRAM + capacitor-based designs [44], when 8-bit input quantization is used.", "purpose": "baseline/comparison"}, {"s": "W7127107108", "t": "W4417092543", "ctx": "Notably, recent work by Büchel et al.28 demonstrates that knowledge distillation can be used to overcome the precision limitations of ADC, highlighting a promising direction for future research.", "purpose": "background"}, {"s": "W4312799098", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W4312799098", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W4312799098", "t": "W3003821665", "ctx": "", "purpose": ""}, {"s": "W4312799098", "t": "W3005874416", "ctx": "", "purpose": ""}, {"s": "W4312799098", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4312799098", "t": "W3195461290", "ctx": "", "purpose": ""}, {"s": "W4366389026", "t": "W4312799098", "ctx": "", "purpose": ""}, {"s": "W4391213160", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W4391213160", "t": "W3148526109", "ctx": "", "purpose": ""}, {"s": "W4391594670", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4391594670", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4391594670", "t": "W4312949026", "ctx": "", "purpose": ""}, {"s": "W4391594670", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4391594670", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4391594670", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4391594670", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4392240059", "t": "W3111375540", "ctx": "", "purpose": ""}, {"s": "W4392240059", "t": "W4280496502", "ctx": "", "purpose": ""}, {"s": "W4405521014", "t": "W2923010225", "ctx": "", "purpose": ""}, {"s": "W4405521014", "t": "W4385656513", "ctx": "", "purpose": ""}, {"s": "W4406521098", "t": "W4392240059", "ctx": "", "purpose": ""}, {"s": "W4409282487", "t": "W2795127895", "ctx": "Temporal variations are typically independent from device to device and are irrelevant to the value to be programmed [20].", "purpose": "background"}, {"s": "W4409282487", "t": "W3003821665", "ctx": "For the hardware techniques, the write-verify procedure [26, 27] is one of the most commonly used approach during programming.", "purpose": "background"}, {"s": "W4410492466", "t": "W3195245399", "ctx": "", "purpose": ""}, {"s": "W4410492466", "t": "W4210530509", "ctx": "", "purpose": ""}, {"s": "W4410492466", "t": "W4312949026", "ctx": "", "purpose": ""}, {"s": "W4410492466", "t": "W4313251083", "ctx": "", "purpose": ""}, {"s": "W4410492466", "t": "W4385896568", "ctx": "", "purpose": ""}, {"s": "W4410492466", "t": "W4386100686", "ctx": "", "purpose": ""}, {"s": "W4410492466", "t": "W4386293192", "ctx": "", "purpose": ""}, {"s": "W4410492466", "t": "W4406178148", "ctx": "", "purpose": ""}, {"s": "W4410582659", "t": "W4409282487", "ctx": "", "purpose": ""}, {"s": "W4411926812", "t": "W4391594670", "ctx": "", "purpose": ""}, {"s": "W4412375723", "t": "W3005619596", "ctx": "To estimate the energy, latency, and area of the TCiM array peripherals—including the row decoder,flash ADC, and subtractor—as well as the additional multiplexers (MUXes) and register required for ReTern, we use NeuroSim [42].", "purpose": "uses-method-or-tool"}, {"s": "W4412375723", "t": "W4280496502", "ctx": "Various CiM-based LLM accelerators have been proposed, showcasing sizeable benefits over conventional von-Neumann based platforms such as GPUs [2–5].", "purpose": "background"}, {"s": "W4412375723", "t": "W4312457094", "ctx": "The works in [17–19] show improved accuracies for inference with SAFs; however, these mapping strategies are not applicable to ternary weights.", "purpose": "contrasts/critiques"}, {"s": "W4412375723", "t": "W4313251083", "ctx": "Thus, works like [33] utilize digital compute cores for the self-attention layers, while using CiM-based memory arrays for the feedforward layers.", "purpose": "uses-method-or-tool"}, {"s": "W4412375723", "t": "W4390017976", "ctx": "", "purpose": ""}, {"s": "W4412375723", "t": "W4406178148", "ctx": "", "purpose": ""}, {"s": "W4413394346", "t": "W4392240059", "ctx": "", "purpose": ""}, {"s": "W4414198682", "t": "W3013080934", "ctx": "FeFET for CIM and CAM In recent years, various emerging NVMs, such as resistive randomaccess memory (RRAM), magnetic tunnel junction (MTJ) and FeFET, have triggered lots of attention for CIM, due to the high storage density and efficient GEMV operation via analog computing within the memory array [26–28].", "purpose": "background"}, {"s": "W4414198682", "t": "W4376606760", "ctx": "", "purpose": ""}, {"s": "W4414198682", "t": "W4386764227", "ctx": "Besides, there are emerging non-volatile memories (NVMs)-based CIM designs for dynamic pruning by utilizing approximate attention scores [17, 18], but suffering the trade-off between energy efficiency and accuracy.", "purpose": "contrasts/critiques"}, {"s": "W4414198682", "t": "W4390285480", "ctx": "Meanwhile, from the hardware perspective, the computing-in-memory (CIM) architecture which can perform the general matrix-vector multiplication (GEMV) operations within the memory array, has been proven to compute attention efficiently by reducing the data movement [9–12].", "purpose": "background"}, {"s": "W4414659772", "t": "W4410492466", "ctx": "", "purpose": ""}, {"s": "W4416728625", "t": "W3116577775", "ctx": "Interest in using PIM technologies to accelerate language models has grown significantly in recent years [17–27].", "purpose": "background"}, {"s": "W4416728625", "t": "W3209892756", "ctx": "Interest in using PIM technologies to accelerate language models has grown significantly in recent years [17–27].", "purpose": "background"}, {"s": "W4416728625", "t": "W4280496502", "ctx": "", "purpose": ""}, {"s": "W4416728625", "t": "W4323022446", "ctx": "To simulate the PIM component and assess its latency and energy consumption, we used MNSIM 2.0 [39] with 256 × 256 RRAM crossbars and 45nm 8-bit ADCs [40].", "purpose": "uses-method-or-tool"}, {"s": "W4416728625", "t": "W4381233128", "ctx": "Interest in using PIM technologies to accelerate language models has grown significantly in recent years [17–27].", "purpose": "background"}, {"s": "W4416728625", "t": "W4390017976", "ctx": "Similarly, PIM-based architectures, which are not tailored for decoder-only LLMs, face notable performance challenges when running these models [18, 26].", "purpose": "contrasts/critiques"}, {"s": "W4416728625", "t": "W4390285480", "ctx": "", "purpose": ""}, {"s": "W4416963215", "t": "W4392240059", "ctx": "", "purpose": ""}, {"s": "W7118450172", "t": "W3013080934", "ctx": "", "purpose": ""}, {"s": "W7127342328", "t": "W2785141883", "ctx": "", "purpose": ""}, {"s": "W7127342328", "t": "W3209892756", "ctx": "", "purpose": ""}, {"s": "W7143500069", "t": "W4392240059", "ctx": "", "purpose": ""}, {"s": "W7165129018", "t": "W2803163155", "ctx": "", "purpose": ""}, {"s": "W7165129018", "t": "W2805362231", "ctx": "", "purpose": ""}, {"s": "W7165129018", "t": "W2946522000", "ctx": "", "purpose": ""}, {"s": "W7165129018", "t": "W2948661249", "ctx": "", "purpose": ""}, {"s": "W7165129018", "t": "W3198899759", "ctx": "", "purpose": ""}, {"s": "W7165129018", "t": "W7134813260", "ctx": "", "purpose": ""}, {"s": "W4409282487", "t": "W3005619596", "ctx": "Given the same amount of documents, CiM can finish computation within 50ms [15], which is negligible compared to the computation latency on normal edge devices.", "purpose": "data/numbers"}, {"s": "W4416728625", "t": "W3013080934", "ctx": "The crossbars carry out MVM operations in parallel, applying Kirchhoff’s and Ohm’s Laws for analog computation [14, 16].", "purpose": "background"}, {"s": "W7162655367", "t": "W4292121737", "ctx": "The development of in-memory computing (IMC) accelerators, particularly those based on resistive memories, such as RRAM [1], Phase Change Memories (PCM) [2], and FeFET [3], stand out as one of the most promising solutions due to their potential for high energy efficiency and scalability.", "purpose": "background"}, {"s": "W7162655367", "t": "W4385896568", "ctx": "The development of in-memory computing (IMC) accelerators, particularly those based on resistive memories, such as RRAM [1], Phase Change Memories (PCM) [2], and FeFET [3], stand out as one of the most promising solutions due to their potential for high energy efficiency and scalability.", "purpose": "background"}, {"s": "W7162655367", "t": "W4243519499", "ctx": "Most IMC accelerators [4–6] perform activations and DMMul using on-chip digital circuits or the host processor, which demand the conversion of the analog outputs from DPEs into digital signals via analog-to-digital converters (ADCs) before computation.", "purpose": "baseline/comparison"}, {"s": "W7212031114", "t": "W4414064893", "ctx": "Leroux et al. [11] hold keys and values in volatile gain-cell arrays rewritten at every step over a fixed 1,024-token window, with 3-bit storage that requires retraining; X-Former [26] targets encoder-only models and has no decoding KV cache; HARDSEA [12] prescreens token relevance in analog ReRAM and computes the exact sparse attention in digital SRAMCiM, with 8-bit keys and values in volatile SRAM.", "purpose": "contrasts/critiques"}, {"s": "W7212031114", "t": "W4390017976", "ctx": "HARDSEA [12] prescreens token relevance in analog ReRAM and computes the exact sparse attention in digital SRAMCiM, with 8-bit keys and values in volatile SRAM.", "purpose": "contrasts/critiques"}, {"s": "W7212031114", "t": "W3005619596", "ctx": "Hardware energy and area are computed with a NeuroSim-based model [17] at 22nm; per-component constants appear in Section 4.3, with only the DAC constants as negligible literature placeholders.", "purpose": "uses-method-or-tool"}, {"s": "W7212031114", "t": "W4243519499", "ctx": "The entries of H are ±1/ 𝑑, while a memory cell holds only a positive conductance; the sign is realized in the standard differential scheme: each output column is a pair of bit lines accumulating the positive and the negative entries, subtracted at the periphery [24].", "purpose": "uses-method-or-tool"}], "findings": [{"fid": "F1", "text": "Transformers now run on real analog PCM silicon at near-iso-accuracy: ALBERT-base on a single 14 nm PCM chip across 28.3M devices, averaging only 1.8% below the floating-point reference on 7 GLUE tasks, with several tasks at full iso-accuracy.", "grade": "High confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Nature Communications 2025 · corroborated on PubMed 41027896, PMC12485056"}, {"fid": "F2", "text": "Analog CIM has moved past simulation to fabricated, measured multi-core silicon in both PCM and RRAM: IBM's 14 nm chip, IBM's 64-core HERMES chip, and NeuRRAM. HERMES's 400 GOPS/mm² in 4-phase mode is more than 15× higher than previous multi-core resistive-memory AIMC chips.", "grade": "High confidence", "vote": "3–0 on HERMES and NeuRRAM · 2–1 on the 14 nm chip", "note": "The single dissent concerned the scope of “software-equivalent”, not the hardware specifications."}, {"fid": "F3", "text": "Measured on-chip accuracy is close to software but not free, and the penalty grows with model scale — from full software-equivalence on keyword spotting, to <1 pp on ResNet-9, to 1.8 pp on ALBERT/GLUE, to a missed equivalence threshold on a 45M-weight RNN-T.", "grade": "High confidence", "vote": "3–0 on NeuRRAM · 2–1 on HERMES and RNN-T", "note": "Dissents addressed interpretive framing, not the numbers. Caveat: NeuRRAM's “comparable to software” baseline is itself 4-bit quantized."}, {"fid": "F4", "text": "Hardware-aware training — injecting realistic device noise during training or fine-tuning — is the field's dominant and empirically validated mitigation, and it now scales to pre-trained LLMs. On under 1% of pre-training tokens, Phi-3-mini-4k-instruct and Llama-3.2-1B-Instruct retained accuracy comparable to 4-bit-weight / 8-bit-activation quantized baselines under hardware-realistic analog noise — a gap off-the-shelf LLMs cannot close on their own.", "grade": "High confidence", "vote": "3–0 on the LLM result and the 4.4% ALBERT figure", "note": "Analog Foundation Models, NeurIPS 2025 (IBM Zurich / ETH) · ALBERT paper quantifies HWA's own contribution at 4.4% average recovery"}, {"fid": "F5", "text": "Full-model analog retraining is not necessary. Analog hardware-aware LoRA freezes the analog-programmed weights as fixed meta-weights and trains only small external digital low-rank adapters, matching full HWA retraining within 1% F1/EM on SQuAD v1.1 and beating it after 10 years of simulated PCM drift (F1 85.36 vs 85.14; EM 76.92 vs 76.40). Adapter-swapping also mitigates the reprogramming problem: one analog base model serves many tasks, avoiding the error accumulation of repeated programming, with adapters refreshed off-chip and drift handled by global drift compensation.", "grade": "Medium confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Graded medium: single research group, one model (MobileBERT), one task, and drift modeled rather than measured over 10 years."}, {"fid": "F6", "text": "The central architectural gap between CNN-era analog IMC accelerators and transformer workloads is self-attention's dynamic matrix-matrix multiplication: both operands are input-dependent, so crossbars must be reprogrammed per self-attention layer. At sequence length 256 these dynamic MVMs consume 80% of total runtime, and the compute-write-compute dependency stalls MatMul until KT is written column by column.", "grade": "High confidence", "vote": "4 claims merged · 3–0 unanimous", "note": "X-Former (IEEE TVLSI) · ReTransformer (ICCAD 2020) · arXiv 2601.14260 — three independent groups; repeated by ClipFormer, CPSAA, RED-PIM, RAELLA, TransPIM"}, {"fid": "F7", "text": "The write bottleneck is being attacked algorithmically rather than only with better devices, via reformulations that keep the static weight matrix in the crossbar; dedicated ReRAM PIM transformer accelerators report large gains (ReTransformer: 23.21× efficiency and 1086× power versus GPU).", "grade": "Medium confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Graded medium: self-reported simulator and architecture-level speedups against differing baselines, not measured silicon. The 1086× power figure compares an accelerator model against a general-purpose GPU."}, {"fid": "F8", "text": "ADC/DAC conversion is a first-order cost and it creates a scaling trap: up to 58% of energy and 81% of area, energy exponential in precision; AIMC only beats DIMC once that overhead is amortized over a large array, but larger arrays force higher-resolution ADCs that degrade throughput and computational density.", "grade": "High confidence", "vote": "3 claims merged · 3–0 unanimous", "note": "arXiv 2406.08413 · KU Leuven quantitative IMC benchmarking (ICCAD 2023)"}, {"fid": "F9", "text": "Device non-idealities are the physical limit and span a hierarchy, not just the material: memory window, read noise, program noise and conductance drift act on different time scales while constraining manufacturability; errors originate at device, array, architecture and algorithm levels. NVM writes cost 1–2 orders of magnitude more latency and energy per bit than SRAM, with ~106–109 write endurance.", "grade": "High confidence", "vote": "3–0 unanimous", "note": "Wiley Adv. Intelligent Systems 2026 · Nature Materials 2026 · X-Former"}, {"fid": "F10", "text": "Non-idealities translate into quantified, model-scale-dependent accuracy loss. Simulated device variation costs under 1% in low-variation regimes (0–0.2) but up to 4.2% for BERT-base and 9.87% for BERT-large, because errors accumulate across layers. Separately, measured RRAM read-disturb resistance shifts from a 40 nm foundry test chip (1300 mV bitline, 10 cycles of 50k stresses) dropped VGG-8 CIFAR-10 accuracy from 87% to 66%.", "grade": "High confidence", "vote": "2–1 on BERT variation · 3–0 on read-disturb", "note": "The dissent objected to inferring “scales with depth” from a single task. Caveat: the depth-scaling numbers come from one simulator (NeuroSim) on one task (WNLI, 56.34% baseline). An IRPS 2020 study reports a harsher 87.35% → 11.58% after 144 hours of read disturb."}, {"fid": "F11", "text": "Heterogeneous architecture is the consensus design point: AIMC tiles combined with digital processing units, because analog tiles alone cannot execute an end-to-end deep neural network.", "grade": "Medium confidence", "vote": "3–0 unanimous", "note": "Graded medium because “dominant” is a review-level characterization resting largely on one review plus the same lab's own chips — and a companion claim from that same review was refuted 0–3 (see §09)."}, {"fid": "F12", "text": "LLM KV-cache state is a newly identified analog-noise vulnerability and it is highly non-uniform across token positions. Under measured CIM-chip noise, average perplexity across nine models rose from a clean 11.06 to 33.91 unprotected (Llama3.2-1B collapsing 15.42 → 100.78; Qwen3-8B 10.64 → 21.54), but attention-sink and recent-window tokens carry disproportionate sensitivity while middle-bulk tokens are near noise-tolerant — so protecting roughly 5% of tokens in high-precision digital storage recovers most of the loss (33.91 → ~11.95).", "grade": "Medium confidence", "vote": "2–1 on degradation · 3–0 on non-uniformity", "note": "Graded medium: a single un-peer-reviewed 2026 preprint, no independent replication, and the noise model is injected into digital simulation rather than run on the chip."}, {"fid": "F13", "text": "Charge-based analog gain cells targeting attention's KV-cache dot products project ~100× speedup and ~70,000× energy reduction versus an H100 (~6.1 nJ and ~65 ns per token per attention head). Circuit non-idealities — third-order polynomial nonlinearity, charge leakage, 4-bit queries / 3-bit stored K,V, HardSigmoid replacing softmax — make direct mapping of pre-trained weights impossible, so a hardware-aware adaptation step is mandatory; the authors mapped GPT-2 weights through a nonlinear gain-cell model rather than training from scratch.", "grade": "Medium confidence", "vote": "2 claims merged · 3–0 unanimous", "note": "Graded medium: SPICE simulation of the attention mechanism alone, no fabricated chip, explicitly excluding linear projections and end-to-end energy. The paper itself notes that substantial overall energy reductions require optimizing all components."}, {"fid": "F14", "text": "The field's framing of its own open problem has shifted: since floating-point-level inference accuracy has been demonstrated via hardware-aware training, the question is no longer whether analog can match digital accuracy but what device specifications are required at what fabrication cost — motivating systematic methodologies for mapping the multidimensional device-specification space, with PCM as the representative platform.", "grade": "Medium confidence", "vote": "3–0 unanimous", "note": "Graded medium: a research-agenda framing statement from a single recent paper, and it understates the residual gap seen at larger model scale (see F3, F10)."}, {"fid": "F15", "text": "The shared motivation across this literature is the memory wall: data movement between separate processing and memory units is the dominant time and energy cost in von Neumann systems, aggravated by data-centric AI workloads. In-memory computing computes in place inside the array by exploiting device physics; two-terminal resistive switching devices are the favoured substrate.", "grade": "High confidence", "vote": "4 claims merged · 3–0 unanimous", "note": "Nature Electronics 2018 · Nature Nanotechnology 2020"}, {"fid": "R1", "text": "“Accuracy, not energy efficiency, is the binding constraint on memristor-based analogue CIM — high efficiency and high accuracy cannot be achieved simultaneously.”", "grade": "Refuted 0–3", "vote": "Nature Materials 2026", "note": "Consequence: do not present analog accuracy as fundamentally unachievable. The review this came from catalogues mitigation strategies; the claim overstated its own source."}, {"fid": "R2", "text": "“Conventional deep-learning compiler stacks (TVM, Glow, nGraph) cannot be reused for AIMC, making software a first-order bottleneck.”", "grade": "Refuted 0–3", "vote": "Nature Rev. Electrical Engineering 2025", "note": "Consequence: the software-stack story in this review is thin and should not be asserted. This is a genuine coverage gap, not a settled negative."}, {"fid": "R3", "text": "“Direct mapping of FP-trained DNN weights onto realistic PCM crossbars causes accuracy losses of roughly 1.3% to 23.9% across 11 benchmark networks.”", "grade": "Refuted 0–3", "vote": "Nature Communications 2023", "note": ""}, {"fid": "R4", "text": "“Hardware-aware training makes analog-deployable not just small CNNs but large-scale, diverse architectures including BERT, RoBERTa, ALBERT, RNN/LSTM and CNN families.”", "grade": "Refuted 1–2", "vote": "Nature Communications 2023", "note": "Consequence: the HWA-training evidence in F4 rests on the ALBERT chip paper, Analog Foundation Models and HERMES instead — not on this breadth claim."}, {"fid": "R5", "text": "“Per-ADC reference-tuning granularity is required because coarse per-module tuning fails on larger networks — ResNeXt50-32x4d on ImageNet failed entirely under per-module tuning.”", "grade": "Refuted 1–2", "vote": "arXiv 2502.05948", "note": ""}, {"fid": "N1", "text": "The December 2025 IBM Research perspective (Nature Electronics) frames the AIMC tile as the building block, buildable from volatile charge-based or non-volatile memristive memory; no single memory technology has been settled on, and signed multi-bit weight encoding and output conversion remain open design axes.", "grade": "Not adjudicated", "vote": "", "note": "Reported in §10 of the review as a lead; never sampled into verification."}]};
